--
-- Name: active_tenant_id(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.active_tenant_id(p_user_id uuid DEFAULT auth.uid()) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN EXISTS (
      SELECT 1
      FROM public.profiles AS profile
      WHERE profile.id = p_user_id
        AND lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
    ) THEN coalesce(
      (
        SELECT context.tenant_id
        FROM public.tenant_user_contexts AS context
        JOIN public.tenant_memberships AS membership
          ON membership.user_id = context.user_id
         AND membership.tenant_id = context.tenant_id
         AND membership.status = 'ACTIVE'
        WHERE context.user_id = p_user_id
        LIMIT 1
      ),
      (
        SELECT membership.tenant_id
        FROM public.tenant_memberships AS membership
        WHERE membership.user_id = p_user_id
          AND membership.status = 'ACTIVE'
        ORDER BY
          membership.is_primary DESC,
          membership.created_at,
          membership.id
        LIMIT 1
      )
    )
    ELSE NULL
  END;
$$;


--
-- Name: active_tenant_role(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.active_tenant_role(p_user_id uuid DEFAULT auth.uid()) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN profile.role = 'SUPER_ADMIN' THEN 'SUPER_ADMIN'
    ELSE coalesce(
      (
        SELECT membership.role
        FROM public.tenant_memberships AS membership
        WHERE membership.user_id = p_user_id
          AND membership.tenant_id = private.active_tenant_id(p_user_id)
          AND membership.status = 'ACTIVE'
        LIMIT 1
      ),
      CASE
        WHEN profile.role = 'NON_STUDENT' AND profile.tenant_id IS NULL
        THEN 'NON_STUDENT'
        ELSE NULL
      END
    )
  END
  FROM public.profiles AS profile
  WHERE profile.id = p_user_id
    AND lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active';
$$;


--
-- Name: advance_student_learning_enrollment(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.advance_student_learning_enrollment(p_enrollment_id uuid, p_student_id uuid, p_path_id uuid, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_enrollment public.student_path_enrollments%rowtype;
  v_next record;
begin
  select *
    into v_enrollment
    from public.student_path_enrollments as enrollment
   where enrollment.id = p_enrollment_id
     and enrollment.student_id = p_student_id
     and enrollment.path_id = p_path_id
     and enrollment.status = 'ACTIVE'
     and enrollment.completed_at is null
   for update;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'active_learning_enrollment_required';
  end if;

  select next_activity.activity_id, next_activity.unit_id
    into v_next
    from private.next_incomplete_learning_activity(
      p_student_id,
      p_path_id
    ) as next_activity;

  if found then
    update public.student_path_enrollments
       set current_unit_id = v_next.unit_id,
           updated_at = p_now
     where id = p_enrollment_id;

    return pg_catalog.jsonb_build_object(
      'nextActivityId', v_next.activity_id,
      'currentUnitId', v_next.unit_id,
      'pathCompleted', false
    );
  end if;

  update public.student_path_enrollments
     set status = 'COMPLETED',
         status_reason = 'ALL_ACTIVITIES_COMPLETED',
         current_unit_id = null,
         completed_at = p_now,
         ended_at = p_now,
         updated_at = p_now
   where id = p_enrollment_id;

  insert into public.student_path_enrollment_history (
    enrollment_id,
    tenant_id,
    student_id,
    path_id,
    event_type,
    from_status,
    to_status,
    reason,
    actor_id,
    occurred_at
  ) values (
    p_enrollment_id,
    v_enrollment.tenant_id,
    p_student_id,
    p_path_id,
    'COMPLETED',
    'ACTIVE',
    'COMPLETED',
    'ALL_ACTIVITIES_COMPLETED',
    p_student_id,
    p_now
  );

  return pg_catalog.jsonb_build_object(
    'nextActivityId', null,
    'currentUnitId', null,
    'pathCompleted', true
  );
end;
$$;


--
-- Name: apply_attendance_response(uuid, text, text, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.apply_attendance_response(p_confirmation_id uuid, p_token text, p_response text, p_actor_id uuid, p_actor_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_requested public.attendance_confirmations%rowtype;
  c public.attendance_confirmations%rowtype;
  v_canonical_id uuid;
  v_previous text;
  v_now timestamptz := pg_catalog.now();
  v_corrected boolean := false;
  v_status text;
begin
  if p_response not in (
    'STUDENT_PRESENT',
    'TEACHER_NO_SHOW',
    'STUDENT_SELF_ABSENT',
    'CANCELLED_RESCHEDULED'
  ) then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'resposta_invalida');
  end if;

  if p_actor_kind = 'PUBLIC_TOKEN' then
    if nullif(pg_catalog.btrim(coalesce(p_token, '')), '') is null then
      return pg_catalog.jsonb_build_object('ok', false, 'error', 'token_invalido');
    end if;

    select ac.*
      into v_requested
      from public.attendance_confirmations ac
     where ac.token = p_token
     for update;

    if not found then
      return pg_catalog.jsonb_build_object('ok', false, 'error', 'token_invalido');
    end if;
  elsif p_actor_kind = 'AUTHENTICATED_STUDENT' then
    if p_actor_id is null or p_confirmation_id is null then
      return pg_catalog.jsonb_build_object('ok', false, 'error', 'sem_permissao');
    end if;

    select ac.*
      into v_requested
      from public.attendance_confirmations ac
     where ac.id = p_confirmation_id
       and ac.student_id = p_actor_id
     for update;

    if not found then
      return pg_catalog.jsonb_build_object('ok', false, 'error', 'sem_permissao');
    end if;
  else
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'ator_invalido');
  end if;

  v_canonical_id := coalesce(v_requested.canonical_confirmation_id, v_requested.id);

  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = v_canonical_id
   for update;

  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'confirmacao_invalida');
  end if;

  -- Lock session members in a deterministic order so simultaneous answers via
  -- WhatsApp and the authenticated panel cannot overwrite one another.
  perform 1
    from public.attendance_confirmations ac
   where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
   order by ac.id
   for update;

  if p_actor_kind = 'AUTHENTICATED_STUDENT'
     and c.student_id is distinct from p_actor_id then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  if v_requested.token_expires_at is null
     or v_requested.token_expires_at <= v_now then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'token_expirado');
  end if;

  if c.status = 'CANCELLED' or c.delivery_status = 'CANCELLED' then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'confirmacao_cancelada');
  end if;

  if c.status in ('RESOLVED_PAID', 'RESOLVED_UNPAID') then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'decisao_finalizada');
  end if;

  v_previous := c.student_response;

  if v_previous is not null and v_previous = p_response then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'already', true,
      'teacher_name', c.teacher_name,
      'status', c.status,
      'student_response', c.student_response,
      'corrected', false,
      'editable_until', c.response_editable_until
    );
  end if;

  if v_previous is not null then
    if c.response_editable_until is null
       or c.response_editable_until <= v_now then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'error', 'janela_correcao_encerrada'
      );
    end if;
    v_corrected := true;
  end if;

  insert into private.attendance_response_audit (
    confirmation_id,
    session_key,
    previous_response,
    new_response,
    actor_id,
    actor_kind,
    changed_at
  ) values (
    c.id,
    c.session_key,
    v_previous,
    p_response,
    p_actor_id,
    p_actor_kind,
    v_now
  );

  update public.attendance_confirmations ac
     set student_response = p_response,
         responded_at = coalesce(ac.responded_at, v_now),
         response_updated_at = v_now,
         response_editable_until = coalesce(
           ac.response_editable_until,
           v_now + interval '30 minutes'
         ),
         student_rating = case
           when v_previous = 'STUDENT_PRESENT'
                and p_response <> 'STUDENT_PRESENT'
           then null
           else ac.student_rating
         end
   where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id;

  -- The reconciliation is session-aware and reverses a former hard conflict
  -- (hold, Turbo suspension and delayed alert) when a valid correction changes
  -- the answer during the edit window.
  perform public.reconcile_attendance_confirmation(v_canonical_id);

  select ac.status
    into v_status
    from public.attendance_confirmations ac
   where ac.id = v_canonical_id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'teacher_name', c.teacher_name,
    'status', v_status,
    'student_response', p_response,
    'corrected', v_corrected,
    'editable_until', coalesce(c.response_editable_until, v_now + interval '30 minutes')
  );
end;
$$;


--
-- Name: apply_final_attendance_resolution(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.apply_final_attendance_resolution(p_canonical_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  c public.attendance_confirmations%rowtype;
  v_session_key text;
  v_original_booking_id uuid;
  v_reschedule_id uuid;
begin
  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = p_canonical_id
   for update;

  if not found
     or c.status not in ('RESOLVED_PAID', 'RESOLVED_UNPAID')
     or c.resolution_verdict is null then
    return;
  end if;

  perform 1
    from public.attendance_confirmations ac
   where coalesce(ac.canonical_confirmation_id, ac.id) = c.id
   order by ac.id
   for update;

  with members as (
    select ac.*
      from public.attendance_confirmations ac
     where coalesce(ac.canonical_confirmation_id, ac.id) = c.id
  )
  update public.class_logs cl
     set presence = case
           when c.resolution_verdict = 'TEACHER_ABSENT'
             then 'TEACHER_ABSENCE'
           when c.resolution_verdict = 'TEACHER_PRESENT'
                and cl.presence in ('TEACHER_ABSENCE', 'Falta do Professor')
             then 'STUDENT_ABSENCE'
           else cl.presence
         end,
         verification_status = c.status,
         payment_hold = false,
         teacher_verdict = case
           when c.resolution_verdict in ('TEACHER_PRESENT', 'TEACHER_ABSENT')
             then c.resolution_verdict
           else cl.teacher_verdict
         end
   where cl.tenant_id = c.tenant_id
     and cl.teacher_id = c.teacher_id
     and cl.student_id is not distinct from c.student_id
     and cl.class_date = c.class_date
     and exists (
       select 1
         from members m
        where m.class_log_id = cl.id
           or (m.source_type = 'booking' and m.source_id = cl.booking_id)
           or (m.source_type = 'reschedule' and m.source_id = cl.reschedule_id)
           or (m.source_type = 'appointment' and m.source_id = cl.appointment_id)
     );

  -- Attach every member to its exact late/existing financial row and reflect
  -- the final, normalized report back into the audit row.
  update public.attendance_confirmations ac
     set class_log_id = coalesce((
           select cl.id
             from public.class_logs cl
            where cl.tenant_id = ac.tenant_id
              and cl.teacher_id = ac.teacher_id
              and cl.student_id is not distinct from ac.student_id
              and cl.class_date = ac.class_date
              and (
                cl.id = ac.class_log_id
                or (ac.source_type = 'booking' and ac.source_id = cl.booking_id)
                or (ac.source_type = 'reschedule' and ac.source_id = cl.reschedule_id)
                or (ac.source_type = 'appointment' and ac.source_id = cl.appointment_id)
              )
            order by (cl.id = ac.class_log_id) desc, cl.created_at desc, cl.id
            limit 1
         ), ac.class_log_id),
         teacher_reported = coalesce((
           select cl.presence
             from public.class_logs cl
            where cl.tenant_id = ac.tenant_id
              and cl.teacher_id = ac.teacher_id
              and cl.student_id is not distinct from ac.student_id
              and cl.class_date = ac.class_date
              and (
                cl.id = ac.class_log_id
                or (ac.source_type = 'booking' and ac.source_id = cl.booking_id)
                or (ac.source_type = 'reschedule' and ac.source_id = cl.reschedule_id)
                or (ac.source_type = 'appointment' and ac.source_id = cl.appointment_id)
              )
            order by (cl.id = ac.class_log_id) desc, cl.created_at desc, cl.id
            limit 1
         ), ac.teacher_reported)
   where coalesce(ac.canonical_confirmation_id, ac.id) = c.id;

  v_session_key := coalesce(c.session_key, 'attendance:legacy:' || c.id::text);

  select coalesce(
           case
             when ac.source_type = 'booking'
                  and ac.source_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
             then ac.source_id::uuid
           end,
           case when ac.source_type = 'reschedule' then (
             select r.original_booking_id
               from public.reschedules r
              where r.id::text = ac.source_id
                and r.tenant_id = ac.tenant_id
                and r.teacher_id = ac.teacher_id
                and r.student_id is not distinct from ac.student_id
              limit 1
           ) end
         )
    into v_original_booking_id
    from public.attendance_confirmations ac
   where coalesce(ac.canonical_confirmation_id, ac.id) = c.id
   order by (ac.source_type = 'booking') desc, ac.class_time, ac.id
   limit 1;

  -- Prefer the reschedule emitted by the teacher logging RPC in the same
  -- transaction as a matching class_log. Otherwise create one session-level
  -- make-up. The unique attendance_session_key makes this idempotent.
  select r.id
    into v_reschedule_id
    from public.reschedules r
   where r.fault_type = 'TEACHER'
     and r.tenant_id = c.tenant_id
     and r.teacher_id = c.teacher_id
     and r.student_id is not distinct from c.student_id
     and (
       r.attendance_session_key = v_session_key
       or (
         r.attendance_session_key is null
         and exists (
           select 1
             from public.class_logs cl
             join public.attendance_confirmations ac
               on coalesce(ac.canonical_confirmation_id, ac.id) = c.id
              and ac.tenant_id = cl.tenant_id
              and ac.teacher_id = cl.teacher_id
              and ac.student_id is not distinct from cl.student_id
              and ac.class_date = cl.class_date
              and (
                ac.class_log_id = cl.id
                or (ac.source_type = 'booking' and ac.source_id = cl.booking_id)
                or (ac.source_type = 'reschedule' and ac.source_id = cl.reschedule_id)
              )
            where cl.created_at between r.created_at - interval '5 minutes'
                                    and r.created_at + interval '5 minutes'
              and r.original_booking_id is not distinct from v_original_booking_id
         )
       )
     )
   order by (r.attendance_session_key = v_session_key) desc,
            r.created_at desc,
            r.id
   limit 1
   for update;

  if c.resolution_verdict = 'TEACHER_ABSENT' and c.student_id is not null then
    if v_reschedule_id is not null then
      update public.reschedules r
         set attendance_session_key = v_session_key,
             used_at = null
       where r.id = v_reschedule_id;
    else
      insert into public.reschedules (
        tenant_id,
        original_booking_id,
        teacher_id,
        student_id,
        date,
        time,
        fault_type,
        attendance_session_key,
        created_at
      ) values (
        c.tenant_id,
        v_original_booking_id,
        c.teacher_id,
        c.student_id,
        'Pendente',
        'Pendente',
        'TEACHER',
        v_session_key,
        pg_catalog.now()
      )
      on conflict (attendance_session_key)
        where attendance_session_key is not null and fault_type = 'TEACHER'
      do update set used_at = null;
    end if;
  elsif c.resolution_verdict = 'TEACHER_PRESENT' and v_reschedule_id is not null then
    update public.reschedules r
       set attendance_session_key = coalesce(r.attendance_session_key, v_session_key),
           used_at = coalesce(r.used_at, pg_catalog.now())
     where r.id = v_reschedule_id;
  end if;
end;
$_$;


--
-- Name: apply_management_payment_notification_receipt(text, text, text, text, timestamp with time zone, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.apply_management_payment_notification_receipt(p_tenant_id text, p_provider_instance_name text, p_provider_message_id text, p_delivery_status text, p_accepted_at timestamp with time zone, p_delivered_at timestamp with time zone, p_read_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_status text := lower(pg_catalog.btrim(coalesce(p_delivery_status, '')));
  v_outbox public.management_payment_notification_outbox%rowtype;
begin
  if v_status not in (
       'accepted', 'sent', 'delivered', 'read', 'failed', 'uncertain'
     ) then
    return;
  end if;

  update public.management_payment_notification_outbox as outbox
  set provider_delivery_status = v_status,
      status = case
        when v_status in ('delivered', 'read') then 'SENT'
        when v_status = 'failed' then 'FAILED'
        when v_status = 'uncertain' then 'UNKNOWN'
        else outbox.status
      end,
      accepted_at = case
        when p_accepted_at is null then outbox.accepted_at
        else least(coalesce(outbox.accepted_at, p_accepted_at), p_accepted_at)
      end,
      delivered_at = case
        when p_delivered_at is null then outbox.delivered_at
        else least(
          coalesce(outbox.delivered_at, p_delivered_at),
          p_delivered_at
        )
      end,
      read_at = case
        when p_read_at is null then outbox.read_at
        else least(coalesce(outbox.read_at, p_read_at), p_read_at)
      end,
      lease_expires_at = pg_catalog.now(),
      last_error = case
        when v_status in ('sent', 'delivered', 'read') then null
        when v_status = 'failed' then 'provider_reported_failed'
        when v_status = 'uncertain' then 'provider_delivery_uncertain'
        else outbox.last_error
      end,
      updated_at = pg_catalog.now()
  where outbox.tenant_id = p_tenant_id
    and lower(outbox.provider_instance_name) = lower(
      pg_catalog.btrim(coalesce(p_provider_instance_name, ''))
    )
    and outbox.provider_message_id = pg_catalog.btrim(
      coalesce(p_provider_message_id, '')
    )
    and outbox.submit_attempt_count = 1
    and outbox.status in ('SUBMITTING', 'SENT', 'FAILED', 'UNKNOWN')
  returning outbox.* into v_outbox;

  if v_outbox.id is not null
     and v_outbox.status = 'SENT'
     and v_outbox.notification_kind = 'PAYMENT_SPLIT' then
    insert into public.automation_sent (kind, subject_id, ref_date)
    select
      'PAYMENT_SPLIT',
      payment.id::text,
      coalesce(payment.created_at, pg_catalog.now())::date
    from public.student_payments as payment
    where payment.id = v_outbox.payment_id
      and payment.tenant_id = v_outbox.tenant_id
    on conflict (kind, subject_id, ref_date) do nothing;
  end if;
end;
$$;


--
-- Name: apply_saas_checkout_billing_event_unordered_impl(uuid, text, text, numeric, text, text, text, text, timestamp with time zone, date, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.apply_saas_checkout_billing_event_unordered_impl(p_checkout_id uuid, p_event_name text, p_payment_id text DEFAULT NULL::text, p_payment_value numeric DEFAULT NULL::numeric, p_billing_type text DEFAULT NULL::text, p_customer_id text DEFAULT NULL::text, p_subscription_id text DEFAULT NULL::text, p_billing_cycle text DEFAULT NULL::text, p_paid_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_due_date date DEFAULT NULL::date, p_invoice_url text DEFAULT NULL::text, p_bank_slip_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_event text := upper(trim(coalesce(p_event_name, '')));
  effective_event text;
  result jsonb;
begin
  effective_event := case
    when normalized_event = 'PAYMENT_CONFIRMED' then 'PAYMENT_UPDATED'
    when normalized_event = 'PAYMENT_RECEIVED_IN_CASH' then 'PAYMENT_RECEIVED'
    else normalized_event
  end;

  result := public.apply_saas_checkout_billing_event_pre_settlement_impl(
    p_checkout_id,
    effective_event,
    p_payment_id,
    p_payment_value,
    p_billing_type,
    p_customer_id,
    p_subscription_id,
    p_billing_cycle,
    p_paid_at,
    p_due_date,
    p_invoice_url,
    p_bank_slip_url
  );

  if normalized_event = 'PAYMENT_CONFIRMED' then
    return coalesce(result, '{}'::jsonb) || jsonb_build_object(
      'action', 'AWAITING_SETTLEMENT',
      'provider_event', normalized_event
    );
  end if;
  return result;
end;
$$;


--
-- Name: apply_tenant_plan_limits(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.apply_tenant_plan_limits() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  selected_plan public.saas_plans%ROWTYPE;
BEGIN
  IF NEW.plan_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND NEW.plan_id IS NOT DISTINCT FROM OLD.plan_id THEN
    RETURN NEW;
  END IF;

  SELECT *
  INTO selected_plan
  FROM public.saas_plans AS plan
  WHERE plan.id = NEW.plan_id
    AND plan.active IS TRUE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'active_saas_plan_required' USING ERRCODE = '23503';
  END IF;

  NEW.student_limit := selected_plan.max_students;
  NEW.teacher_limit := COALESCE(selected_plan.max_teachers, selected_plan.max_users);
  RETURN NEW;
END;
$$;


--
-- Name: apply_whatsapp_contact_handoff(text, text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.apply_whatsapp_contact_handoff(p_tenant_id text, p_phone text, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_phone text := pg_catalog.regexp_replace(
    coalesce(p_phone, ''),
    '\D',
    '',
    'g'
  );
  v_suffix text;
  v_at timestamptz := pg_catalog.now();
  v_lead_count integer := 0;
  v_application_count integer := 0;
begin
  if p_active is null then
    raise exception 'invalid_whatsapp_contact_handoff' using errcode = '22023';
  end if;
  if pg_catalog.char_length(v_phone) not between 10 and 15 then
    return jsonb_build_object('leads', 0, 'applications', 0);
  end if;
  v_suffix := pg_catalog.right(v_phone, 8);

  -- Todos os registros inequívocos daquele telefone no MESMO tenant recebem o
  -- mesmo estado. Assim nenhum dos agentes comerciais continua respondendo.
  update public.crm_leads as lead
  set ai_handoff = p_active,
      ai_handoff_at = case when p_active then v_at else null end
  where lead.tenant_id = p_tenant_id
    and pg_catalog.right(
      pg_catalog.regexp_replace(coalesce(lead.phone, ''), '\D', '', 'g'),
      8
    ) = v_suffix
    and private.commercial_phones_match(lead.phone, v_phone);
  get diagnostics v_lead_count = row_count;

  update public.job_applications as application
  set ai_handoff = p_active,
      ai_handoff_at = case when p_active then v_at else null end
  where application.tenant_id = p_tenant_id
    and pg_catalog.right(
      pg_catalog.regexp_replace(
        coalesce(application.whatsapp, ''),
        '\D',
        '',
        'g'
      ),
      8
    ) = v_suffix
    and private.commercial_phones_match(application.whatsapp, v_phone);
  get diagnostics v_application_count = row_count;

  return jsonb_build_object(
    'leads', v_lead_count,
    'applications', v_application_count
  );
end;
$$;


--
-- Name: asaas_http_response_outcome(integer, boolean, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.asaas_http_response_outcome(p_status_code integer, p_timed_out boolean, p_error_msg text, p_content text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_payload jsonb;
begin
  if coalesce(p_timed_out, false) then
    return 'TRANSPORT_TIMEOUT';
  end if;
  if p_error_msg is not null then
    return 'TRANSPORT_ERROR';
  end if;
  if p_status_code is null or p_status_code not between 200 and 299 then
    return 'HTTP_STATUS_FAILURE';
  end if;

  begin
    v_payload := p_content::jsonb;
  exception when others then
    return 'INVALID_JSON_RESPONSE';
  end;
  if pg_catalog.jsonb_typeof(v_payload) <> 'object' then
    return 'INVALID_JSON_RESPONSE';
  end if;

  if pg_catalog.lower(coalesce(v_payload ->> 'success', 'true')) = 'false'
     or pg_catalog.lower(coalesce(v_payload ->> 'ok', 'true')) = 'false'
     or (
       v_payload ? 'error'
       and v_payload -> 'error' <> 'null'::jsonb
       and nullif(pg_catalog.btrim(v_payload ->> 'error'), '') is not null
     )
     or (
       coalesce(v_payload ->> 'failed', '') ~ '^[0-9]+$'
       and (v_payload ->> 'failed')::integer > 0
     )
     or (
       coalesce(v_payload ->> 'falhas', '') ~ '^[0-9]+$'
       and (v_payload ->> 'falhas')::integer > 0
     )
     or (
       coalesce(v_payload ->> 'blocked', '') ~ '^[0-9]+$'
       and (v_payload ->> 'blocked')::integer > 0
     )
     or (
       coalesce(v_payload ->> 'bloqueados', '') ~ '^[0-9]+$'
       and (v_payload ->> 'bloqueados')::integer > 0
     )
     or (
       pg_catalog.jsonb_typeof(v_payload -> 'failures') = 'array'
       and pg_catalog.jsonb_array_length(v_payload -> 'failures') > 0
     ) then
    return 'APPLICATION_FAILURE';
  end if;
  return 'SUCCEEDED';
end;
$_$;


