--
-- Name: assert_materialized_enrollment_schedule(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assert_materialized_enrollment_schedule(p_offer_id uuid, p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_offer record;
  v_expected_count integer;
  v_actual_count integer;
begin
  perform private.lock_and_validate_enrollment_schedule(
    p_offer_id,
    p_user_id
  );

  -- DELETE/CANCEL de booking nao passa pelo trigger BEFORE de INSERT/UPDATE.
  -- Bloquear as linhas vinculadas fecha a janela MVCC entre a revalidacao da
  -- grade e a conclusao: um cancelamento em curso termina primeiro e e visto
  -- pela contagem abaixo; depois deste lock, ele espera o complete finalizar.
  perform booking.id
  from public.bookings as booking
  join private.enrollment_offer_schedule_slots as slot
    on slot.id = booking.enrollment_offer_slot_id
   and slot.offer_id = booking.enrollment_offer_id
  where slot.offer_id = p_offer_id
    and booking.student_id = p_user_id
    and pg_catalog.upper(coalesce(booking.status, 'SCHEDULED')) = 'SCHEDULED'
  order by booking.id
  for update of booking;

  select offer.tenant_id, offer.payload, offer.processing_by
  into v_offer
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.kind = 'ENROLLMENT'
  for update;
  if not found or v_offer.processing_by is distinct from p_user_id then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end if;
  begin
    v_expected_count := (v_offer.payload ->> 'classesPerWeek')::integer;
  exception when others then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end;

  select pg_catalog.count(*)::integer
  into v_actual_count
  from private.enrollment_offer_schedule_slots as slot
  join public.bookings as booking
    on booking.id = slot.materialized_booking_id
   and booking.enrollment_offer_slot_id = slot.id
   and booking.enrollment_offer_id = slot.offer_id
   and booking.tenant_id = slot.tenant_id
   and booking.teacher_id = slot.teacher_id
   and booking.student_id = p_user_id
   and public.dow_name_to_int(booking.day_of_week) = slot.day_of_week
   and pg_catalog.left(pg_catalog.btrim(booking.time_slot), 5)
       = pg_catalog.to_char(slot.class_time, 'HH24:MI')
   and booking.start_date is not distinct from slot.start_date
   and pg_catalog.upper(coalesce(booking.status, 'SCHEDULED')) = 'SCHEDULED'
  where slot.offer_id = p_offer_id
    and slot.tenant_id = v_offer.tenant_id
    and slot.status = 'MATERIALIZED'
    and slot.reserved_by = p_user_id;
  if v_actual_count <> v_expected_count then
    raise exception 'enrollment_schedule_materialization_incomplete'
      using errcode = '23P01';
  end if;
end;
$$;


--
-- Name: attendance_session_is_consistent(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.attendance_session_is_consistent(p_canonical_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  c public.attendance_confirmations%rowtype;
  member public.attendance_confirmations%rowtype;
  v_member_count integer := 0;
  v_member_time time;
  v_member_phone text;
  v_original_booking_id uuid;
  v_coverage_count integer;
  v_cover_teacher_id uuid;
  v_first_time time;
  v_previous_time time;
  v_participant_key text;
  v_expected_session_key text;
  v_source_matches_snapshot boolean;
begin
  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = p_canonical_id;

  if not found
     or coalesce(c.canonical_confirmation_id, c.id) <> c.id
     or c.tenant_id is null
     or c.teacher_id is null
     or c.class_date is null then
    return false;
  end if;

  perform 1
    from public.profiles teacher
   where teacher.id = c.teacher_id
     and teacher.tenant_id = c.tenant_id
     and teacher.role = 'TEACHER'
   for key share;
  if not found then
    return false;
  end if;

  for member in
    select ac.*
      from public.attendance_confirmations ac
     where coalesce(ac.canonical_confirmation_id, ac.id) = c.id
     order by (
       case
         when pg_catalog.btrim(coalesce(ac.class_time, ''))
              ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
         then pg_catalog.left(pg_catalog.btrim(ac.class_time), 5)::time
       end
     ) nulls last, ac.id
  loop
    v_member_count := v_member_count + 1;

    if member.tenant_id is distinct from c.tenant_id
       or member.teacher_id is distinct from c.teacher_id
       or member.student_id is distinct from c.student_id
       or member.class_date is distinct from c.class_date then
      return false;
    end if;

    -- Current grouped sessions have an immutable shared key and every member
    -- points directly to the canonical row. A legacy NULL key is safe only for
    -- a true singleton, never as an umbrella for additional rows.
    if c.session_key is null then
      if member.id <> c.id
         or member.session_key is not null then
        return false;
      end if;
    elsif member.session_key is distinct from c.session_key
          or member.canonical_confirmation_id is distinct from c.id then
      return false;
    end if;

    v_member_time := case
      when pg_catalog.btrim(coalesce(member.class_time, ''))
           ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
      then pg_catalog.left(pg_catalog.btrim(member.class_time), 5)::time
      else null
    end;
    if v_member_time is null then
      return false;
    end if;

    v_first_time := coalesce(v_first_time, v_member_time);
    if v_previous_time is not null
       and v_member_time - v_previous_time > interval '30 minutes' then
      return false;
    end if;
    v_previous_time := v_member_time;

    if member.student_id is not null then
      perform 1
        from public.profiles student
       where student.id = member.student_id
         and student.tenant_id = member.tenant_id
         and student.role = 'STUDENT'
       for key share;
      if not found then
        return false;
      end if;
    end if;

    -- Prove that the snapshot still identifies a real source owned by the same
    -- school and participant. Date/time/teacher remain the immutable audit
    -- snapshot: booking and reschedule rows are mutable after the lesson.
    if member.source_type = 'booking' then
      if member.student_id is null then
        return false;
      end if;

      select (
        b.teacher_id = member.teacher_id
        and (b.start_date is null or member.class_date >= b.start_date)
        and public.dow_name_to_int(b.day_of_week) =
            extract(dow from member.class_date)::integer
        and case
              when pg_catalog.btrim(coalesce(b.time_slot, ''))
                   ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
              then pg_catalog.left(pg_catalog.btrim(b.time_slot), 5)::time
            end = v_member_time
      )
        into v_source_matches_snapshot
        from public.bookings b
       where b.id::text = member.source_id
         and b.tenant_id = member.tenant_id
         and b.student_id = member.student_id
       for key share;
      if not found then
        return false;
      end if;

      select
        count(*)::integer,
        (array_agg(coverage.cover_teacher_id order by coverage.id))[1]
        into v_coverage_count, v_cover_teacher_id
        from public.class_coverages coverage
       where coverage.booking_id::text = member.source_id
         and coverage.tenant_id = member.tenant_id
         and coverage.student_id = member.student_id
         and coverage.class_date = member.class_date
         and pg_catalog.lower(coalesce(coverage.status, '')) = 'confirmed';

      if v_coverage_count > 1 then
        return false;
      elsif v_coverage_count = 1 then
        if v_cover_teacher_id is distinct from member.teacher_id then
          return false;
        end if;
        perform 1
          from public.class_coverages coverage
         where coverage.booking_id::text = member.source_id
           and coverage.tenant_id = member.tenant_id
           and coverage.cover_teacher_id = v_cover_teacher_id
           and coverage.student_id = member.student_id
           and coverage.class_date = member.class_date
           and pg_catalog.lower(coalesce(coverage.status, '')) = 'confirmed'
           and case
                 when pg_catalog.btrim(coalesce(coverage.class_time, ''))
                      ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
                 then pg_catalog.left(
                   pg_catalog.btrim(coverage.class_time),
                   5
                 )::time
               end = v_member_time
         for key share;
        if not found then
          return false;
        end if;
      elsif not coalesce(v_source_matches_snapshot, false)
            and not exists (
              select 1
                from public.class_logs historical_log
               where historical_log.id = member.class_log_id
                 and historical_log.tenant_id = member.tenant_id
                 and historical_log.teacher_id = member.teacher_id
                 and historical_log.student_id = member.student_id
                 and historical_log.class_date = member.class_date
                 and historical_log.start_time = v_member_time
                 and historical_log.booking_id = member.source_id
            ) then
        -- The live booking may legitimately change after class, but a mismatch
        -- then needs an exact immutable class-log proof. Otherwise this could
        -- simply be another booking of the same student.
        return false;
      end if;
    elsif member.source_type = 'reschedule' then
      if member.student_id is null then
        return false;
      end if;

      v_original_booking_id := null;
      select
        reschedule.original_booking_id,
        (
          reschedule.teacher_id = member.teacher_id
          and pg_catalog.btrim(coalesce(reschedule.date, '')) =
              pg_catalog.to_char(member.class_date, 'YYYY-MM-DD')
          and case
                when pg_catalog.btrim(coalesce(reschedule.time, ''))
                     ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
                then pg_catalog.left(
                  pg_catalog.btrim(reschedule.time),
                  5
                )::time
              end = v_member_time
        )
        into v_original_booking_id, v_source_matches_snapshot
        from public.reschedules reschedule
       where reschedule.id::text = member.source_id
         and reschedule.tenant_id = member.tenant_id
         and reschedule.student_id = member.student_id
         and (
           reschedule.original_booking_id is null
           or exists (
             select 1
               from public.bookings original_booking
              where original_booking.id = reschedule.original_booking_id
                and original_booking.tenant_id = reschedule.tenant_id
                and original_booking.student_id = reschedule.student_id
           )
         )
       for key share;
      if not found then
        return false;
      end if;
      if v_original_booking_id is not null then
        perform 1
          from public.bookings original_booking
         where original_booking.id = v_original_booking_id
           and original_booking.tenant_id = member.tenant_id
           and original_booking.student_id = member.student_id
         for key share;
        if not found then
          return false;
        end if;
      end if;
      if not coalesce(v_source_matches_snapshot, false)
         and not exists (
           select 1
             from public.class_logs historical_log
            where historical_log.id = member.class_log_id
              and historical_log.tenant_id = member.tenant_id
              and historical_log.teacher_id = member.teacher_id
              and historical_log.student_id = member.student_id
              and historical_log.class_date = member.class_date
              and historical_log.start_time = v_member_time
              and historical_log.reschedule_id = member.source_id
         ) then
        return false;
      end if;
    elsif member.source_type = 'appointment' then
      v_member_phone := pg_catalog.regexp_replace(
        coalesce(member.student_phone, ''),
        '\\D',
        '',
        'g'
      );
      if v_member_phone = '' then
        return false;
      end if;

      select (
        member.teacher_id in (
          appointment.teacher_id,
          appointment.professor_id
        )
        and pg_catalog.regexp_replace(
              coalesce(appointment.student_phone, ''),
              '\\D',
              '',
              'g'
            ) = v_member_phone
        and (
          (
            (appointment.start_time at time zone 'America/Sao_Paulo')::date =
              member.class_date
            and pg_catalog.date_trunc(
                  'minute',
                  appointment.start_time at time zone 'America/Sao_Paulo'
                )::time = v_member_time
          )
          or (
            (appointment.start_time at time zone 'UTC')::date = member.class_date
            and pg_catalog.date_trunc(
                  'minute',
                  appointment.start_time at time zone 'UTC'
                )::time = v_member_time
          )
        )
      )
        into v_source_matches_snapshot
        from public.appointments appointment
       where appointment.id::text = member.source_id
         and appointment.tenant_id = member.tenant_id
       for key share;
      if not found then
        return false;
      end if;
      if not coalesce(v_source_matches_snapshot, false)
         and not exists (
           select 1
             from public.class_logs historical_log
            where historical_log.id = member.class_log_id
              and historical_log.tenant_id = member.tenant_id
              and historical_log.teacher_id = member.teacher_id
              and historical_log.student_id is not distinct from member.student_id
              and historical_log.class_date = member.class_date
              and historical_log.start_time = v_member_time
              and historical_log.appointment_id = member.source_id
         ) then
        return false;
      end if;
    else
      return false;
    end if;

    if member.class_log_id is not null then
      perform 1
        from public.class_logs cl
       where cl.id = member.class_log_id
         and cl.tenant_id = member.tenant_id
         and cl.teacher_id = member.teacher_id
         and cl.student_id is not distinct from member.student_id
         and cl.class_date is not distinct from member.class_date
         and cl.start_time = v_member_time
         and (
           (member.source_type = 'booking' and cl.booking_id = member.source_id)
           or (
             member.source_type = 'reschedule'
             and cl.reschedule_id = member.source_id
           )
           or (
             member.source_type = 'appointment'
             and cl.appointment_id = member.source_id
           )
           or (
             cl.booking_id is null
             and cl.reschedule_id is null
             and cl.appointment_id is null
             and member.student_id is not null
             and cl.start_time = v_member_time
           )
         )
       for update;
      if not found then
        return false;
      end if;
    end if;
  end loop;

  if c.session_key is not null then
    v_participant_key := coalesce(
      c.student_id::text,
      nullif(
        pg_catalog.regexp_replace(
          coalesce(c.student_phone, ''),
          '\\D',
          '',
          'g'
        ),
        ''
      ),
      c.id::text
    );
    v_expected_session_key := 'attendance:' || pg_catalog.md5(
      coalesce(c.tenant_id, '-') || '|' ||
      coalesce(c.teacher_id::text, '-') || '|' ||
      v_participant_key || '|' ||
      c.class_date::text || '|' ||
      coalesce(v_first_time::text, c.id::text)
    );
    if c.session_key is distinct from v_expected_session_key then
      return false;
    end if;
  end if;

  return v_member_count > 0;
end;
$_$;


--
-- Name: bridge_management_payment_notification_receipt(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.bridge_management_payment_notification_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.apply_management_payment_notification_receipt(
    new.tenant_id,
    new.provider_instance_name,
    new.provider_message_id,
    new.delivery_status,
    new.accepted_at,
    new.delivered_at,
    new.read_at
  );
  return new;
end;
$$;


--
-- Name: bump_reschedule_notification_revision(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.bump_reschedule_notification_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    new.notification_revision := 1;
    return new;
  end if;

  if row(new.date, new.time, new.teacher_id, new.student_id)
       is distinct from
     row(old.date, old.time, old.teacher_id, old.student_id) then
    new.notification_revision := old.notification_revision + 1;
  else
    -- Also neutralizes an explicit UPDATE of notification_revision by a caller.
    new.notification_revision := old.notification_revision;
  end if;

  return new;
end;
$$;


--
-- Name: can_access_invoice_object(text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_access_invoice_object(p_object_name text, p_write boolean DEFAULT false) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text;
  actor_tenant_id text;
  canonical_path boolean;
BEGIN
  IF actor_id IS NULL
    OR coalesce(auth.role(), '') <> 'authenticated'
    OR p_object_name IS NULL
    OR pg_catalog.length(p_object_name) > 512
  THEN
    RETURN false;
  END IF;

  actor_tenant_id := private.active_tenant_id(actor_id);
  actor_role := private.active_tenant_role(actor_id);

  IF actor_tenant_id IS NULL
    OR actor_role NOT IN ('TEACHER', 'SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN')
    OR NOT private.tenant_is_operational(actor_tenant_id)
  THEN
    RETURN false;
  END IF;

  canonical_path := p_object_name ~* (
    '^closings/'
    || '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/'
    || '[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.]pdf$'
  );

  -- O namespace novo nunca cai na compatibilidade legada. Assim um nome
  -- malformado em closings/ não ganha acesso só porque apareceu em nf_link.
  IF p_object_name ~* '^closings/' AND NOT canonical_path THEN
    RETURN false;
  END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.teacher_closings AS closing
    WHERE closing.tenant_id = actor_tenant_id
      AND (
        (
          canonical_path
          AND pg_catalog.lower(closing.id::text) = pg_catalog.lower(
            pg_catalog.split_part(p_object_name, '/', 2)
          )
          AND (
            p_write
            OR nullif(pg_catalog.btrim(closing.nf_link), '') = p_object_name
          )
        )
        OR (
          NOT canonical_path
          AND p_object_name !~* '^closings/'
          AND nullif(pg_catalog.btrim(closing.nf_link), '') = p_object_name
        )
      )
      AND (
        (actor_role = 'TEACHER' AND closing.teacher_id = actor_id)
        OR actor_role IN ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN')
      )
      AND (
        NOT p_write
        OR actor_role IN ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN')
        OR (
          actor_role = 'TEACHER'
          AND coalesce(closing.total_amount, 0) > 0
          AND upper(coalesce(closing.status, '')) IN (
            'PAID_WAITING_NF',
            'PAGO',
            'PAID',
            'REJECTED',
            'REJEITADO',
            'UNDER_REVIEW'
          )
        )
      )
  );
END;
$_$;


--
-- Name: can_access_teacher_closing(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_access_teacher_closing(p_teacher_id uuid, p_month text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text;
  actor_tenant_id text;
BEGIN
  IF p_month !~ '^\d{4}-\d{2}$'
    OR actor_id IS NULL
    OR coalesce(auth.role(), '') <> 'authenticated'
  THEN
    RETURN false;
  END IF;

  actor_role := private.active_tenant_role(actor_id);
  actor_tenant_id := private.active_tenant_id(actor_id);

  IF actor_tenant_id IS NULL
    OR NOT private.tenant_is_operational(actor_tenant_id)
    OR NOT EXISTS (
      SELECT 1
      FROM public.profiles AS profile
      WHERE profile.id = p_teacher_id
        AND profile.role = 'TEACHER'
    )
  THEN
    RETURN false;
  END IF;

  IF actor_id = p_teacher_id THEN
    IF actor_role <> 'TEACHER'
      OR NOT EXISTS (
        SELECT 1
        FROM public.tenant_memberships AS membership
        WHERE membership.user_id = actor_id
          AND membership.tenant_id = actor_tenant_id
          AND membership.role = 'TEACHER'
          AND membership.status = 'ACTIVE'
      )
    THEN
      RETURN false;
    END IF;
  ELSIF actor_role NOT IN ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN')
    OR NOT EXISTS (
      SELECT 1
      FROM public.tenant_memberships AS membership
      WHERE membership.user_id = p_teacher_id
        AND membership.tenant_id = actor_tenant_id
        AND membership.role = 'TEACHER'
    )
  THEN
    RETURN false;
  END IF;

  -- The legacy report has no tenant argument. Month-scoped ambiguity is denied
  -- before its implementation is allowed to run.
  IF EXISTS (
    SELECT 1 FROM public.class_logs AS class_log
    WHERE class_log.teacher_id = p_teacher_id
      AND to_char(class_log.class_date, 'YYYY-MM') = p_month
      AND class_log.tenant_id IS DISTINCT FROM actor_tenant_id
  ) OR EXISTS (
    SELECT 1 FROM public.teacher_closings AS closing
    WHERE closing.teacher_id = p_teacher_id
      AND closing.month_year = p_month
      AND closing.tenant_id IS DISTINCT FROM actor_tenant_id
  ) OR EXISTS (
    SELECT 1 FROM public.closing_adjustments AS adjustment
    WHERE adjustment.teacher_id = p_teacher_id
      AND adjustment.month_year = p_month
      AND adjustment.tenant_id IS DISTINCT FROM actor_tenant_id
  ) OR EXISTS (
    SELECT 1
    FROM public.class_logs AS class_log
    JOIN public.profiles AS student ON student.id = class_log.student_id
    WHERE class_log.teacher_id = p_teacher_id
      AND to_char(class_log.class_date, 'YYYY-MM') = p_month
      AND student.tenant_id IS DISTINCT FROM actor_tenant_id
  ) OR EXISTS (
    SELECT 1
    FROM public.class_logs AS class_log
    JOIN public.appointments AS appointment
      ON appointment.id::text = class_log.appointment_id
    WHERE class_log.teacher_id = p_teacher_id
      AND to_char(class_log.class_date, 'YYYY-MM') = p_month
      AND appointment.tenant_id IS DISTINCT FROM actor_tenant_id
  ) THEN
    RETURN false;
  END IF;

  RETURN true;
END;
$_$;


--
-- Name: can_access_teacher_projection(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_access_teacher_projection(p_teacher_id uuid, p_month text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text;
  actor_tenant_id text;
  target_tenant_id text;
  target_membership_count integer;
  normalized_month text := coalesce(p_month, to_char(current_date, 'YYYY-MM'));
BEGIN
  IF normalized_month !~ '^\d{4}-\d{2}$' THEN
    RETURN false;
  END IF;

  SELECT count(*), min(membership.tenant_id)
  INTO target_membership_count, target_tenant_id
  FROM public.tenant_memberships AS membership
  WHERE membership.user_id = p_teacher_id
    AND membership.role = 'TEACHER'
    AND membership.status = 'ACTIVE';

  IF target_membership_count <> 1
    OR target_tenant_id IS NULL
    OR NOT private.tenant_is_operational(target_tenant_id)
    OR NOT EXISTS (
      SELECT 1
      FROM public.profiles AS profile
      WHERE profile.id = p_teacher_id
        AND profile.role = 'TEACHER'
        AND profile.tenant_id = target_tenant_id
        AND lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
    )
  THEN
    RETURN false;
  END IF;

  -- The legacy calculation aggregates by teacher_id. Until the finance domain
  -- receives tenant_id as a first-class argument, fail closed whenever this
  -- identity has operational history in more than one tenant.
  IF EXISTS (
    SELECT 1 FROM public.bookings AS booking
    WHERE booking.teacher_id = p_teacher_id
      AND booking.tenant_id IS DISTINCT FROM target_tenant_id
  ) OR EXISTS (
    SELECT 1 FROM public.class_logs AS class_log
    WHERE class_log.teacher_id = p_teacher_id
      AND class_log.tenant_id IS DISTINCT FROM target_tenant_id
  ) OR EXISTS (
    SELECT 1 FROM public.attendance_confirmations AS confirmation
    WHERE confirmation.teacher_id = p_teacher_id
      AND confirmation.tenant_id IS DISTINCT FROM target_tenant_id
  ) OR EXISTS (
    SELECT 1 FROM public.teacher_closings AS closing
    WHERE closing.teacher_id = p_teacher_id
      AND closing.tenant_id IS DISTINCT FROM target_tenant_id
  ) OR EXISTS (
    SELECT 1 FROM public.closing_adjustments AS adjustment
    WHERE adjustment.teacher_id = p_teacher_id
      AND adjustment.tenant_id IS DISTINCT FROM target_tenant_id
  ) OR EXISTS (
    SELECT 1
    FROM public.bookings AS booking
    JOIN public.profiles AS student ON student.id = booking.student_id
    WHERE booking.teacher_id = p_teacher_id
      AND student.tenant_id IS DISTINCT FROM target_tenant_id
  ) OR EXISTS (
    SELECT 1
    FROM public.class_logs AS class_log
    JOIN public.profiles AS student ON student.id = class_log.student_id
    WHERE class_log.teacher_id = p_teacher_id
      AND student.tenant_id IS DISTINCT FROM target_tenant_id
  ) THEN
    RETURN false;
  END IF;

  IF coalesce(auth.role(), '') = 'service_role' THEN
    RETURN true;
  END IF;

  IF actor_id IS NULL OR coalesce(auth.role(), '') <> 'authenticated' THEN
    RETURN false;
  END IF;

  actor_role := private.active_tenant_role(actor_id);
  actor_tenant_id := private.active_tenant_id(actor_id);

  IF actor_tenant_id IS DISTINCT FROM target_tenant_id THEN
    RETURN false;
  END IF;

  RETURN (actor_id = p_teacher_id AND actor_role = 'TEACHER')
    OR actor_role IN ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN');
END;
$_$;


--
-- Name: can_admin_tenant(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_admin_tenant(target_tenant_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = (select auth.uid())
      and (
        p.role = 'SUPER_ADMIN'
        or (p.tenant_id = target_tenant_id and p.role = 'SCHOOL_ADMIN')
      )
  );
$$;


--
-- Name: FUNCTION can_admin_tenant(target_tenant_id text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.can_admin_tenant(target_tenant_id text) IS 'Checks authenticated tenant-admin authorization against the trusted profile row.';


--
-- Name: can_create_teacher_transfer(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_create_teacher_transfer(p_student_id uuid, p_to_teacher_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text;
  actor_tenant_id text;
  student_tenant_id text;
  teacher_tenant_id text;
BEGIN
  SELECT profile.tenant_id
  INTO student_tenant_id
  FROM public.profiles AS profile
  JOIN public.tenant_memberships AS membership
    ON membership.user_id = profile.id
   AND membership.tenant_id = profile.tenant_id
   AND membership.role = 'STUDENT'
   AND membership.status = 'ACTIVE'
  WHERE profile.id = p_student_id
    AND profile.role = 'STUDENT'
    AND lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
  LIMIT 1;

  SELECT profile.tenant_id
  INTO teacher_tenant_id
  FROM public.profiles AS profile
  JOIN public.tenant_memberships AS membership
    ON membership.user_id = profile.id
   AND membership.tenant_id = profile.tenant_id
   AND membership.role = 'TEACHER'
   AND membership.status = 'ACTIVE'
  WHERE profile.id = p_to_teacher_id
    AND profile.role = 'TEACHER'
    AND lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
  LIMIT 1;

  IF student_tenant_id IS NULL
    OR teacher_tenant_id IS NULL
    OR student_tenant_id IS DISTINCT FROM teacher_tenant_id
    OR NOT private.tenant_is_operational(student_tenant_id)
  THEN
    RETURN false;
  END IF;

  IF actor_id IS NULL OR coalesce(auth.role(), '') <> 'authenticated' THEN
    RETURN false;
  END IF;

  actor_role := private.active_tenant_role(actor_id);
  actor_tenant_id := private.active_tenant_id(actor_id);

  RETURN actor_tenant_id = student_tenant_id
    AND actor_role IN ('SCHOOL_ADMIN', 'SUPER_ADMIN');
END;
$$;


--
-- Name: can_execute_legacy_role_rpc(text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_execute_legacy_role_rpc(p_allowed_roles text[]) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text;
  actor_tenant_id text;
  jwt_role text := coalesce(auth.jwt() ->> 'role', '');
BEGIN
  -- Service workers and direct database maintenance remain explicit trusted
  -- callers. A JWT claim always wins, so SET ROLE authenticated in SQL tests
  -- cannot inherit the postgres session user's authority.
  IF jwt_role = 'service_role'
    OR (
      jwt_role = ''
      AND session_user IN ('postgres', 'supabase_admin')
    )
  THEN
    RETURN true;
  END IF;

  IF jwt_role <> 'authenticated'
    OR actor_id IS NULL
    OR p_allowed_roles IS NULL
    OR pg_catalog.cardinality(p_allowed_roles) = 0
  THEN
    RETURN false;
  END IF;

  actor_tenant_id := private.active_tenant_id(actor_id);
  actor_role := private.active_tenant_role(actor_id);

  IF actor_tenant_id IS NULL
    OR actor_role IS NULL
    OR NOT (actor_role = ANY (p_allowed_roles))
    OR NOT private.tenant_is_operational(actor_tenant_id)
  THEN
    RETURN false;
  END IF;

  -- Legacy bodies still read role/tenant from profiles. Refuse ambiguous
  -- multi-tenant context instead of letting the body write to the primary
  -- profile tenant while the UI is operating in another tenant.
  RETURN EXISTS (
    SELECT 1
    FROM public.profiles AS profile
    WHERE profile.id = actor_id
      AND pg_catalog.lower(
        pg_catalog.btrim(coalesce(profile.lifecycle_status, 'active'))
      ) = 'active'
      AND (
        (
          actor_role = 'SUPER_ADMIN'
          AND profile.role = 'SUPER_ADMIN'
        )
        OR (
          profile.role = actor_role
          AND profile.tenant_id = actor_tenant_id
          AND EXISTS (
            SELECT 1
            FROM public.tenant_memberships AS membership
            WHERE membership.user_id = actor_id
              AND membership.tenant_id = actor_tenant_id
              AND membership.role = actor_role
              AND membership.status = 'ACTIVE'
          )
        )
      )
  );
END;
$$;


--
-- Name: can_manage_crm_tenant(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_manage_crm_tenant(target_tenant_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = (select auth.uid())
      and (
        p.role = 'SUPER_ADMIN'
        or (
          p.tenant_id = target_tenant_id
          and p.role in ('SCHOOL_ADMIN', 'SALESPERSON', 'COMMERCIAL')
        )
      )
  );
$$;


--
-- Name: FUNCTION can_manage_crm_tenant(target_tenant_id text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.can_manage_crm_tenant(target_tenant_id text) IS 'Checks authenticated CRM staff authorization against the trusted profile row.';


--
-- Name: can_manage_sdr(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_manage_sdr(p_tenant_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1 from public.profiles p where p.id=auth.uid()
    and p.lifecycle_status='active' and (
      p.role='SUPER_ADMIN' or exists (
        select 1 from public.tenant_memberships m where m.user_id=p.id
        and m.tenant_id=p_tenant_id and m.status='ACTIVE'
        and m.role in ('SCHOOL_ADMIN','COORDINATOR','SALESPERSON','COMMERCIAL')
      )
    )
  );
$$;


--
-- Name: canonical_payment_notification_kind(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.canonical_payment_notification_kind(p_notification_kind text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case upper(pg_catalog.btrim(coalesce(p_notification_kind, '')))
    when 'PAYMENT_CONFIRMED' then 'PAYMENT_CONFIRMED_WHATSAPP'
    else upper(pg_catalog.btrim(coalesce(p_notification_kind, '')))
  end
$$;


--
-- Name: canonicalize_notification_queue_kind(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.canonicalize_notification_queue_kind() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.notification_kind := nullif(
    upper(pg_catalog.btrim(coalesce(new.notification_kind, ''))),
    ''
  );
  return new;
end;
$$;


--
-- Name: capture_student_payment_provider_customer(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.capture_student_payment_provider_customer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  candidate text;
  raw_candidate text;
  raw_payment_id text;
begin
  raw_payment_id := nullif(
    pg_catalog.btrim(new.raw_payload #>> '{payment,id}'),
    ''
  );
  raw_candidate := nullif(
    pg_catalog.btrim(new.raw_payload #>> '{payment,customer}'),
    ''
  );
  if raw_candidate is not null
    and raw_payment_id is distinct from pg_catalog.btrim(new.asaas_payment_id)
  then
    raise exception using
      errcode = '23514',
      message = 'student_payment_raw_provider_id_mismatch';
  end if;

  if tg_op = 'UPDATE' and old.provider_customer_id is not null then
    if new.provider_customer_id is distinct from old.provider_customer_id then
      raise exception using
        errcode = '23514',
        message = 'student_payment_provider_customer_immutable';
    end if;
    if new.raw_payload is distinct from old.raw_payload
      and raw_candidate is not null
      and raw_candidate is distinct from old.provider_customer_id
    then
      raise exception using
        errcode = '23514',
        message = 'student_payment_raw_customer_mismatch';
    end if;
    return new;
  end if;

  candidate := nullif(pg_catalog.btrim(new.provider_customer_id), '');
  if candidate is not null
    and raw_candidate is not null
    and candidate is distinct from raw_candidate
  then
    raise exception using
      errcode = '23514',
      message = 'student_payment_raw_customer_mismatch';
  elsif candidate is null then
    candidate := raw_candidate;
  end if;

  -- A new provider payment may be created before its first webhook. Capture
  -- the exact profile binding at insert time only; never derive it later on an
  -- UPDATE, when the profile customer might already have rotated.
  if candidate is null
     and tg_op = 'INSERT'
     and new.asaas_payment_id is not null
     and new.student_id is not null
     and new.tenant_id is not null
  then
    select nullif(pg_catalog.btrim(profile.asaas_customer_id), '')
      into candidate
      from public.profiles as profile
     where profile.id = new.student_id
       and profile.tenant_id = new.tenant_id
       and profile.role = 'STUDENT';
  end if;

  if candidate is not null and pg_catalog.length(candidate) > 240 then
    raise exception using
      errcode = '22001',
      message = 'student_payment_provider_customer_too_long';
  end if;

  new.provider_customer_id := candidate;
  return new;
end;
$$;


--
-- Name: capture_wolfie_meeting_attempt_memories(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.capture_wolfie_meeting_attempt_memories() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  begin
    perform private.persist_wolfie_meeting_attempt_memories(new.id);
  exception when sqlstate '22023' then
    -- A rolled-back Edge Function may still persist the former assessment
    -- shape. Keep that authoritative attempt, but fail closed by creating no
    -- memory. Permission, lineage, constraint and storage failures still abort
    -- the transaction.
    null;
  end;
  return new;
end;
$$;


--
-- Name: collect_asaas_http_failures(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.collect_asaas_http_failures() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_recorded integer := 0;
begin
  -- Persista o resultado antes que a tabela UNLOGGED do pg_net expire.
  update private.asaas_automation_http_requests as request
     set status = case
           when outcome.value = 'SUCCEEDED' then 'SUCCEEDED'
           else 'FAILED'
         end,
         http_status = response.status_code,
         outcome_summary = outcome.value,
         response_checked_at = pg_catalog.now()
    from net._http_response as response
    cross join lateral (
      select private.asaas_http_response_outcome(
        response.status_code,
        response.timed_out,
        response.error_msg,
        response.content
      ) as value
   ) as outcome
   where request.request_id = response.id
     and request.status in ('QUEUED', 'TIMED_OUT');

  update private.asaas_automation_http_requests as request
     set status = 'TIMED_OUT',
         outcome_summary = 'HTTP_RESPONSE_MISSING',
         response_checked_at = pg_catalog.now()
   where request.status = 'QUEUED'
     and request.deadline_at < pg_catalog.now()
     and not exists (
       select 1
         from net._http_response as response
        where response.id = request.request_id
     );

  -- Uma resposta 2xx valida encerra somente a issue "sem resposta". Uma
  -- resposta HTTP/aplicativa de erro e imutavel e requer revisao.
  update public.asaas_reconciliation_issues as issue
     set resolved_at = pg_catalog.now(),
         resolution_note = 'http_response_2xx_observed'
    from private.asaas_automation_http_requests as request
   where issue.source = 'AUTOMATION_HTTP'
     and issue.kind = 'HTTP_RESPONSE_MISSING'
     and issue.resolved_at is null
     and issue.provider_entity_id = request.request_id::text
     and request.status = 'SUCCEEDED';

  insert into public.asaas_reconciliation_issues (
    tenant_id,
    source,
    kind,
    severity,
    provider_entity_id,
    fingerprint,
    details,
    observed_at
  )
  select
    null,
    'AUTOMATION_HTTP',
    case when request.status = 'TIMED_OUT'
      then 'HTTP_RESPONSE_MISSING'
      else 'HTTP_RESPONSE_FAILED'
    end,
    case
      when request.automation_name in ('WEBHOOK_WORKER', 'RECONCILIATION')
        then 'CRITICAL'
      else 'HIGH'
    end,
    request.request_id::text,
    'automation-http:' || request.request_id::text,
    pg_catalog.jsonb_build_object(
      'automation', request.automation_name,
      'request_id', request.request_id,
      'queued_at', request.queued_at,
      'deadline_at', request.deadline_at,
      'response_observed', request.status = 'FAILED',
      'status_code', request.http_status,
      'outcome', request.outcome_summary
    ),
    coalesce(request.response_checked_at, pg_catalog.now())
  from private.asaas_automation_http_requests as request
  where request.queued_at > pg_catalog.now() - interval '24 hours'
    and request.status in ('FAILED', 'TIMED_OUT')
  on conflict (source, fingerprint)
    where run_id is null and resolved_at is null
  do update set
    kind = excluded.kind,
    severity = excluded.severity,
    details = excluded.details,
    observed_at = excluded.observed_at;

  get diagnostics v_recorded = row_count;
  return v_recorded;
end;
$$;


--
-- Name: commercial_phones_match(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commercial_phones_match(left_phone text, right_phone text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  left_digits text := regexp_replace(coalesce(left_phone, ''), '\D', '', 'g');
  right_digits text := regexp_replace(coalesce(right_phone, ''), '\D', '', 'g');
  left_prefix text;
  right_prefix text;
  left_ddd text;
  right_ddd text;
begin
  if length(left_digits) < 10 or length(right_digits) < 10 then
    return false;
  end if;
  if right(left_digits, 8) <> right(right_digits, 8) then
    return false;
  end if;

  left_prefix := left(left_digits, length(left_digits) - 8);
  right_prefix := left(right_digits, length(right_digits) - 8);
  left_prefix := regexp_replace(left_prefix, '^55', '');
  right_prefix := regexp_replace(right_prefix, '^55', '');
  left_prefix := regexp_replace(left_prefix, '9$', '');
  right_prefix := regexp_replace(right_prefix, '9$', '');
  left_ddd := right(left_prefix, 2);
  right_ddd := right(right_prefix, 2);

  return length(left_ddd) = 2
    and length(right_ddd) = 2
    and left_ddd = right_ddd;
end;
$_$;


