  )
  on conflict (tenant_id, provider) do nothing;

  insert into private.tenant_integration_connections (
    tenant_id,
    provider,
    mode,
    status,
    connection_config
  )
  values (
    new.id,
    'asaas',
    'DISABLED',
    'disabled',
    '{}'::jsonb
  )
  on conflict (tenant_id, provider) do nothing;

  return new;
end;
$$;


