-- Name: enforce_ai_conversation_scope_immutable(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_ai_conversation_scope_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
begin
  if new.student_id is distinct from old.student_id
     or new.product_family is distinct from old.product_family
     or new.hub_account_id is distinct from old.hub_account_id then
    raise exception 'ai conversation ownership and product scope are immutable'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_final_attendance_resolution_on_log(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_final_attendance_resolution_on_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_verdict text;
  v_final text;
begin
  select ac.resolution_verdict, ac.status
    into v_verdict, v_final
    from public.attendance_confirmations ac
   where ac.tenant_id = new.tenant_id
     and ac.teacher_id = new.teacher_id
     and ac.student_id is not distinct from new.student_id
     and ac.class_date = new.class_date
     and ac.status in ('RESOLVED_PAID', 'RESOLVED_UNPAID')
     and ac.student_response = 'TEACHER_NO_SHOW'
     and (
       ac.class_log_id = new.id
       or (ac.source_type = 'booking' and ac.source_id = new.booking_id)
       or (ac.source_type = 'reschedule' and ac.source_id = new.reschedule_id)
       or (ac.source_type = 'appointment' and ac.source_id = new.appointment_id)
     )
   order by ac.resolved_at desc nulls last, ac.id
   limit 1;

  if not found then
    return new;
  end if;

  if v_verdict = 'TEACHER_ABSENT' then
    new.presence := 'TEACHER_ABSENCE';
    new.teacher_verdict := 'TEACHER_ABSENT';
  elsif v_verdict = 'TEACHER_PRESENT' then
    if new.presence in ('TEACHER_ABSENCE', 'Falta do Professor') then
      new.presence := 'STUDENT_ABSENCE';
    end if;
    new.teacher_verdict := 'TEACHER_PRESENT';
  end if;

  new.verification_status := v_final;
  new.payment_hold := false;
  return new;
end;
$$;


--
-- Name: enforce_student_activity_progress_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_student_activity_progress_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_expected_unit_id uuid;
begin
  if not exists (
    select 1
      from public.profiles as profile
     where profile.id = new.student_id
       and profile.role = 'STUDENT'
       and profile.tenant_id is not null
  ) then
    raise exception using
      errcode = '23514',
      message = 'learning_progress_requires_student_profile';
  end if;

  select activity.unit_id
    into v_expected_unit_id
    from public.unit_activities as activity
   where activity.id = new.activity_id;

  if not found or new.unit_id is distinct from v_expected_unit_id then
    raise exception using
      errcode = '23514',
      message = 'learning_progress_activity_unit_mismatch';
  end if;

  return new;
end;
$$;


--
-- Name: enforce_student_complementary_activity_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_student_complementary_activity_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_tenant text;
begin
  select profile.tenant_id
    into v_student_tenant
    from public.profiles as profile
   where profile.id = new.student_id
     and profile.role = 'STUDENT';

  if not found or v_student_tenant is null then
    raise exception using
      errcode = '23514',
      message = 'complementary_activity_requires_student_profile';
  end if;

  if new.tenant_id is not null and new.tenant_id <> v_student_tenant then
    raise exception using
      errcode = '23514',
      message = 'complementary_activity_tenant_mismatch';
  end if;

  new.tenant_id := v_student_tenant;
  new.updated_at := pg_catalog.now();
  return new;
end;
$$;


--
-- Name: enforce_student_path_enrollment_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_student_path_enrollment_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_tenant text;
  v_student_role text;
  v_path_tenant text;
begin
  select profile.tenant_id, profile.role
    into v_student_tenant, v_student_role
    from public.profiles as profile
   where profile.id = new.student_id;

  if not found
     or v_student_role <> 'STUDENT'
     or v_student_tenant is null then
    raise exception using
      errcode = '23514',
      message = 'learning_enrollment_requires_student_profile';
  end if;

  select path.tenant_id
    into v_path_tenant
    from public.learning_paths as path
   where path.id = new.path_id;

  if not found
     or (v_path_tenant is not null and v_path_tenant <> v_student_tenant) then
    raise exception using
      errcode = '23514',
      message = 'learning_enrollment_tenant_mismatch';
  end if;

  if new.current_unit_id is not null
     and not exists (
       select 1
         from public.learning_units as unit
        where unit.id = new.current_unit_id
          and unit.path_id = new.path_id
     ) then
    raise exception using
      errcode = '23514',
      message = 'learning_enrollment_current_unit_mismatch';
  end if;

  new.tenant_id := v_student_tenant;
  new.updated_at := pg_catalog.now();

  if new.status = 'ACTIVE' then
    new.completed_at := null;
    new.ended_at := null;
  elsif new.completed_at is null then
    new.completed_at := pg_catalog.now();
    new.ended_at := coalesce(new.ended_at, new.completed_at);
  end if;

  return new;
end;
$$;


--
-- Name: enforce_tenant_membership_limit(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_tenant_membership_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  seat_limit integer;
  seats_in_use integer;
  limit_code text;
BEGIN
  IF NEW.status <> 'ACTIVE' OR NEW.role NOT IN ('STUDENT', 'TEACHER') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE'
     AND NEW.tenant_id IS NOT DISTINCT FROM OLD.tenant_id
     AND NEW.role IS NOT DISTINCT FROM OLD.role
     AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  PERFORM pg_advisory_xact_lock(
    hashtextextended('tenant-seat:' || NEW.tenant_id || ':' || NEW.role, 0)
  );

  SELECT CASE
    WHEN NEW.role = 'STUDENT' THEN tenant.student_limit
    ELSE tenant.teacher_limit
  END
  INTO seat_limit
  FROM public.tenants AS tenant
  WHERE tenant.id = NEW.tenant_id;

  -- NULL and non-positive values keep compatibility with legacy "unlimited".
  IF seat_limit IS NULL OR seat_limit <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT count(*)::integer
  INTO seats_in_use
  FROM public.tenant_memberships AS membership
  WHERE membership.tenant_id = NEW.tenant_id
    AND membership.role = NEW.role
    AND membership.status = 'ACTIVE'
    AND membership.id <> NEW.id;

  IF seats_in_use >= seat_limit THEN
    limit_code := CASE
      WHEN NEW.role = 'STUDENT' THEN 'tenant_student_limit_reached'
      ELSE 'tenant_teacher_limit_reached'
    END;
    RAISE EXCEPTION '%', limit_code
      USING
        ERRCODE = 'P0001',
        DETAIL = format(
          'tenant_id=%s role=%s limit=%s',
          NEW.tenant_id,
          NEW.role,
          seat_limit
        );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_vendor_trial_teacher_acceptance(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_vendor_trial_teacher_acceptance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request private.vendor_trial_teacher_requests%rowtype;
begin
  if upper(coalesce(old.status, '')) = 'OPEN'
     and upper(coalesce(new.status, '')) = 'CLAIMED' then
    select request.*
      into v_request
      from private.vendor_trial_teacher_requests as request
     where request.opportunity_id = old.id
     for update;

    if found then
      if v_request.status <> 'AWAITING_TEACHER'
         or new.winner_teacher_id is distinct from
              v_request.target_teacher_id
         or new.professor_id is distinct from v_request.target_teacher_id
         or new.trial_appointment_id is null
         or not exists (
           select 1
             from public.appointments as appointment
            where appointment.id = new.trial_appointment_id
              and appointment.tenant_id = v_request.tenant_id
              and appointment.teacher_id = v_request.target_teacher_id
              and appointment.professor_id = v_request.target_teacher_id
              and appointment.start_time = v_request.slot_start
              and lower(coalesce(appointment.status, '')) in (
                'scheduled', 'confirmed'
              )
         ) then
        raise exception 'vendor_trial_teacher_acceptance_required'
          using errcode = '42501';
      end if;

      update private.vendor_trial_teacher_requests
         set status = 'ACCEPTED',
             accepted_at = now(),
             accepted_appointment_id = new.trial_appointment_id,
             updated_at = now()
       where id = v_request.id;
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: enqueue_cron_health_alert(text, text, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enqueue_cron_health_alert(p_kind text, p_subject text, p_message text, p_ref_date date) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_admin record;
  v_queue_id uuid;
  v_kind text := upper(pg_catalog.btrim(coalesce(p_kind, '')));
  v_subject text := pg_catalog.btrim(coalesce(p_subject, ''));
begin
  if v_kind = '' or v_subject = '' or p_ref_date is null
     or nullif(pg_catalog.btrim(coalesce(p_message, '')), '') is null
  then
    raise exception using errcode = '22023', message = 'invalid_cron_health_alert';
  end if;

  select
    profile.id,
    membership.tenant_id,
    coalesce(
      nullif(pg_catalog.btrim(profile.attendance_phone), ''),
      nullif(pg_catalog.btrim(profile.phone), '')
    ) as phone
  into v_admin
  from public.tenant_memberships as membership
  join public.profiles as profile on profile.id = membership.user_id
  where membership.tenant_id = 'school-wise-wolf'
    and membership.role = 'SCHOOL_ADMIN'
    and membership.status = 'ACTIVE'
    and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) = 'active'
    and coalesce(profile.is_test_account, false) is false
    and coalesce(
      nullif(pg_catalog.btrim(profile.attendance_phone), ''),
      nullif(pg_catalog.btrim(profile.phone), '')
    ) is not null
  order by
    membership.is_primary desc nulls last,
    membership.created_at,
    profile.id
  limit 1;

  if v_admin.id is null then
    raise exception using
      errcode = '55000',
      message = 'cron_health_recipient_unavailable';
  end if;

  insert into public.notification_queue (
    tenant_id,
    teacher_id,
    student_phone,
    message_body,
    scheduled_for,
    next_attempt_at,
    status,
    attempts,
    max_attempts,
    delivery_status,
    source_type,
    class_date,
    notification_kind,
    idempotency_key
  ) values (
    v_admin.tenant_id,
    v_admin.id,
    v_admin.phone,
    p_message,
    now(),
    now(),
    'pending',
    0,
    5,
    'queued',
    'CRON_HEALTH',
    p_ref_date,
    'CRON_ALERT',
    'cron-health:' || v_kind || ':' || v_subject || ':' || p_ref_date::text
  )
  on conflict (tenant_id, idempotency_key)
    where idempotency_key is not null
  do nothing
  returning id into v_queue_id;

  return v_queue_id is not null;
end;
$$;


--
-- Name: enqueue_interview_notification_internal(uuid, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enqueue_interview_notification_internal(p_application_id uuid, p_expected_slot timestamp with time zone, p_event text, p_audience text, p_destination text, p_message_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_application public.job_applications%rowtype;
  v_event text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_event, '')));
  v_audience text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_audience, '')));
  v_destination text := pg_catalog.regexp_replace(
    coalesce(p_destination, ''),
    '[^0-9]',
    '',
    'g'
  );
  v_message text := pg_catalog.btrim(coalesce(p_message_body, ''));
  v_kind text;
  v_ref_date date;
  v_idempotency_key text;
  v_queue_id uuid;
begin
  if p_application_id is null or p_expected_slot is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'queued', false,
      'duplicate', false,
      'reason', 'notification_binding_missing'
    );
  end if;
  if v_event not in ('BOOKED', 'REMINDER') then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'queued', false,
      'duplicate', false,
      'reason', 'invalid_event'
    );
  end if;
  if v_audience not in ('CANDIDATE', 'MANAGEMENT') then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'queued', false,
      'duplicate', false,
      'reason', 'invalid_audience'
    );
  end if;
  -- Public candidate intake historically accepted BR numbers with DDD only.
  -- Normalize that persisted format at the durable database boundary so an
  -- otherwise valid booking cannot be rolled back merely for lacking +55.
  if pg_catalog.char_length(v_destination) in (10, 11) then
    v_destination := '55' || v_destination;
  end if;
  if v_destination !~ '^[0-9]{12,15}$' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'queued', false,
      'duplicate', false,
      'reason', 'invalid_destination'
    );
  end if;
  if pg_catalog.char_length(v_message) not between 1 and 4096 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'queued', false,
      'duplicate', false,
      'reason', 'invalid_message'
    );
  end if;

  select application.*
    into v_application
    from public.job_applications as application
   where application.id = p_application_id
   for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'queued', false,
      'duplicate', false,
      'reason', 'application_not_found'
    );
  end if;
  if v_application.interview_slot is null
     or v_application.interview_slot is distinct from p_expected_slot then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'queued', false,
      'duplicate', false,
      'reason', 'interview_slot_changed'
    );
  end if;

  v_kind := 'INTERVIEW_' || v_event || '_' || v_audience;
  v_ref_date := (p_expected_slot at time zone 'America/Sao_Paulo')::date;
  v_idempotency_key := pg_catalog.lower(
    'interview:' || v_event || ':' || v_audience || ':' ||
    v_application.id::text || ':' ||
    pg_catalog.floor(extract(epoch from p_expected_slot))::bigint::text
  );

  insert into public.notification_queue (
    tenant_id,
    teacher_id,
    student_id,
    student_name,
    student_phone,
    message_body,
    scheduled_for,
    status,
    attempts,
    next_attempt_at,
    delivery_status,
    notification_kind,
    source_id,
    source_type,
    class_date,
    idempotency_key
  ) values (
    v_application.tenant_id,
    null,
    null,
    case
      when v_audience = 'MANAGEMENT'
        then 'Direção — ' || v_application.name
      else v_application.name
    end,
    v_destination,
    v_message,
    pg_catalog.now(),
    'pending',
    0,
    pg_catalog.now(),
    'queued',
    v_kind,
    v_application.id,
    'job_application',
    v_ref_date,
    v_idempotency_key
  )
  on conflict (tenant_id, idempotency_key)
    where idempotency_key is not null
  do nothing
  returning id into v_queue_id;

  if v_queue_id is null then
    select queue.id
      into v_queue_id
      from public.notification_queue as queue
     where queue.tenant_id = v_application.tenant_id
       and queue.idempotency_key = v_idempotency_key
     limit 1;
    return pg_catalog.jsonb_build_object(
      'ok', v_queue_id is not null,
      'queued', false,
      'duplicate', v_queue_id is not null,
      'reason', case when v_queue_id is null then 'queue_conflict' else 'already_queued' end,
      'queue_id', v_queue_id,
      'notification_kind', v_kind
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'queued', true,
    'duplicate', false,
    'queue_id', v_queue_id,
    'notification_kind', v_kind
  );
end;
$_$;


--
-- Name: enrollment_offer_payload_fingerprint(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enrollment_offer_payload_fingerprint(p_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(coalesce(p_payload, 'null'::jsonb)::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: ensure_saas_owner_access_locked(uuid, text, text, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_saas_owner_access_locked(p_checkout_id uuid, p_tenant_id text, p_owner_email text, p_owner_user_id uuid, p_require_checkout_marker boolean) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  auth_email text;
  checkout_marker text;
  expected_checkout_marker text;
  profile_row public.profiles%rowtype;
  profile_inserted boolean := false;
  quarantine_owned boolean := false;
  canonical_tenant boolean := false;
  target_already_primary boolean := false;
  other_primary_exists boolean := false;
  make_primary boolean := false;
begin
  if p_checkout_id is null or p_tenant_id is null
     or p_owner_email is null or p_owner_user_id is null
  then
    return false;
  end if;

  perform 1
    from public.saas_checkout_intents as checkout
    join public.tenants as tenant on tenant.id = checkout.tenant_id
   where checkout.id = p_checkout_id
     and checkout.tenant_id = p_tenant_id
     and lower(pg_catalog.btrim(checkout.owner_email)) = p_owner_email
     and checkout.status in (
       'PAID', 'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED'
     )
     and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) = 'active'
   for update of checkout, tenant;
  if not found then
    return false;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-access-user:' || p_owner_user_id::text,
      0
    )
  );
  if p_require_checkout_marker then
    select coalesce(
      attempt.owner_identity_marker_checkout_id,
      attempt.checkout_id
    )::text
      into expected_checkout_marker
      from public.saas_owner_activation_attempts as attempt
     where attempt.checkout_id = p_checkout_id
       and (
         attempt.owner_user_id = p_owner_user_id
         or attempt.owner_user_id is null
       )
     for update;
    if not found then
      return false;
    end if;
  end if;
  select
    lower(pg_catalog.btrim(coalesce(auth_user.email, ''))),
    pg_catalog.btrim(coalesce(
      auth_user.raw_app_meta_data
        ->> 'saas_owner_activation_checkout_id',
      ''
    ))
    into auth_email, checkout_marker
    from auth.users as auth_user
   where auth_user.id = p_owner_user_id
     and auth_user.deleted_at is null
     and auth_user.email_confirmed_at is not null
     and (
       auth_user.banned_until is null
       or auth_user.banned_until <= pg_catalog.now()
     )
   for update;
  if not found
     or auth_email is distinct from p_owner_email
     or (
       p_require_checkout_marker
       and checkout_marker is distinct from expected_checkout_marker
     )
  then
    return false;
  end if;

  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_owner_user_id
   for update;
  if found and lower(pg_catalog.btrim(coalesce(
       profile_row.lifecycle_status,
       ''
     ))) <> 'active'
  then
    return false;
  end if;
  if not found then
    insert into public.profiles (
      id,
      full_name,
      email,
      role,
      tenant_id,
      status_financial,
      created_at
    ) values (
      p_owner_user_id,
      coalesce(nullif(auth_email, ''), 'Administrador da escola'),
      auth_email,
      'SCHOOL_ADMIN',
      p_tenant_id,
      'ACTIVE',
      pg_catalog.now()
    )
    returning * into profile_row;
    profile_inserted := true;
  end if;

  quarantine_owned := p_require_checkout_marker
    and checkout_marker = expected_checkout_marker
    and profile_row.tenant_id is null
    and profile_row.role = 'STUDENT'
    and profile_row.status_financial = 'PENDING';
  if quarantine_owned then
    update public.profiles
       set tenant_id = p_tenant_id,
           role = 'SCHOOL_ADMIN',
           status_financial = 'ACTIVE'
     where id = p_owner_user_id
       and tenant_id is null
       and role = 'STUDENT'
       and status_financial = 'PENDING'
     returning * into profile_row;
    if not found then
      return false;
    end if;
  elsif profile_row.tenant_id = p_tenant_id
        and profile_row.role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN')
  then
    -- Becoming the checkout owner grants the role but never clears an
    -- existing student's/teacher's financial state.
    update public.profiles
       set role = 'SCHOOL_ADMIN'
     where id = p_owner_user_id
       and tenant_id = p_tenant_id
       and role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN')
     returning * into profile_row;
    if not found then
      return false;
    end if;
  end if;

  canonical_tenant := profile_inserted
    or quarantine_owned
    or profile_row.tenant_id = p_tenant_id;
  perform 1
    from public.tenant_memberships as membership
   where membership.user_id = p_owner_user_id
   order by membership.tenant_id
   for update;
  select coalesce(pg_catalog.bool_or(
      membership.tenant_id = p_tenant_id
      and membership.is_primary
      and membership.status = 'ACTIVE'
    ), false),
    coalesce(pg_catalog.bool_or(
      membership.tenant_id <> p_tenant_id
      and membership.is_primary
      and membership.status = 'ACTIVE'
    ), false)
    into target_already_primary, other_primary_exists
    from public.tenant_memberships as membership
   where membership.user_id = p_owner_user_id;
  make_primary := canonical_tenant
    and (target_already_primary or not other_primary_exists);

  insert into public.tenant_memberships (
    user_id,
    tenant_id,
    role,
    status,
    is_primary,
    updated_at
  ) values (
    p_owner_user_id,
    p_tenant_id,
    'SCHOOL_ADMIN',
    'ACTIVE',
    make_primary,
    pg_catalog.now()
  )
  on conflict (user_id, tenant_id) do update
    set role = excluded.role,
        status = excluded.status,
        is_primary = excluded.is_primary,
        updated_at = excluded.updated_at;

  return exists (
    select 1
      from public.tenant_memberships as membership
     where membership.user_id = p_owner_user_id
       and membership.tenant_id = p_tenant_id
       and membership.role = 'SCHOOL_ADMIN'
       and membership.status = 'ACTIVE'
  );
end;
$$;


--
-- Name: expire_hub_core_cancellations_internal(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.expire_hub_core_cancellations_internal() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_expired integer := 0;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  update public.hub_subscriptions as subscription
  set status = 'EXPIRED',
      metadata = coalesce(subscription.metadata, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'cancelAtPeriodEnd', true,
          'accessEndedAt', subscription.current_period_ends_at,
          'expiredAt', v_now,
          'expiredBy', 'hub_core_period_expiration'
        ),
      updated_at = v_now
  where subscription.product_family = 'HUB_CORE'
    and subscription.status in ('ACTIVE', 'PAST_DUE')
    and subscription.current_period_ends_at is not null
    and subscription.current_period_ends_at <= pg_catalog.now()
    and pg_catalog.jsonb_typeof(
      subscription.metadata -> 'cancelAtPeriodEnd'
    ) = 'boolean'
    and (subscription.metadata ->> 'cancelAtPeriodEnd')::boolean;

  get diagnostics v_expired = row_count;
  return v_expired;
end;
$$;


--
-- Name: FUNCTION expire_hub_core_cancellations_internal(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.expire_hub_core_cancellations_internal() IS 'Idempotently expires Hub Core access after a confirmed cancel-at-period-end request reaches its paid boundary.';


--
-- Name: expire_hub_trials_internal(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.expire_hub_trials_internal() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_expired integer := 0;
begin
  update public.hub_subscriptions as subscription
  set status = 'EXPIRED',
      current_period_ends_at = least(
        coalesce(
          subscription.current_period_ends_at,
          subscription.trial_ends_at,
          pg_catalog.now()
        ),
        pg_catalog.now()
      ),
      metadata = coalesce(subscription.metadata, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'expiredBy', 'hub_trial_expiration',
          'expiredAt', pg_catalog.now()
        ),
      updated_at = pg_catalog.now()
  where subscription.status = 'TRIALING'
    and subscription.trial_ends_at is not null
    and subscription.trial_ends_at <= pg_catalog.now();

  get diagnostics v_expired = row_count;
  return v_expired;
end;
$$;


--
-- Name: FUNCTION expire_hub_trials_internal(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.expire_hub_trials_internal() IS 'Idempotently expires elapsed Hub trials. Owner/pg_cron only.';


--
-- Name: financial_report_message_exact_scope_active(text, text, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.financial_report_message_exact_scope_active(p_tenant_id text, p_notification_kind text, p_subject_id text, p_ref_date date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select private.financial_report_message_scope_active(
    p_tenant_id,
    p_notification_kind
  ) and (
    p_notification_kind <> 'MONTHLY_CLOSING'
    or exists (
      select 1
        from public.teacher_closings as closing
        join public.profiles as teacher
          on teacher.id = closing.teacher_id
         and teacher.tenant_id = closing.tenant_id
         and teacher.role = 'TEACHER'
         and lower(pg_catalog.btrim(coalesce(teacher.lifecycle_status, ''))) = 'active'
         and coalesce(teacher.is_test_account, false) is false
       where closing.tenant_id = p_tenant_id
         and upper(pg_catalog.btrim(coalesce(closing.status, ''))) = 'PENDENTE'
         and coalesce(closing.total_lessons, 0) > 0
         and closing.month_year ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'
         and p_ref_date::text = closing.month_year || '-01'
         and p_subject_id = closing.teacher_id::text || ':'
           || closing.month_year || ':' || closing.id::text || ':'
           || coalesce(closing.total_lessons, 0)::bigint::text || ':'
           || pg_catalog.round(
             coalesce(closing.total_amount, 0)::numeric * 100
           )::bigint::text
         and exists (
           select 1
             from public.tenant_memberships as membership
            where membership.user_id = closing.teacher_id
              and membership.tenant_id = closing.tenant_id
              and membership.role = 'TEACHER'
              and membership.status = 'ACTIVE'
         )
    )
  );
$_$;


--
-- Name: financial_report_message_scope_active(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.financial_report_message_scope_active(p_tenant_id text, p_notification_kind text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.tenants as tenant
     where tenant.id = p_tenant_id
       and tenant.whatsapp_enabled is true
       and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) in (
         'active', 'trial', 'trialing'
       )
  ) and (
    p_notification_kind = 'WEEKLY_DIGEST'
    or (
      p_notification_kind = 'DRE_REPORT'
      and exists (
        select 1
          from public.dre_report_settings as setting
        where setting.tenant_id = p_tenant_id
           and setting.is_active
      )
    )
    or (
      p_notification_kind = 'MONTHLY_CLOSING'
      and exists (
        select 1
          from public.tenant_admin_settings as setting
         where setting.tenant_id = p_tenant_id
           and setting.teacher_notifications_enabled is true
      )
    )
  );
$$;


--
-- Name: generated_activity_content_is_valid(text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.generated_activity_content_is_valid(p_type text, p_content jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_items jsonb;
  v_item jsonb;
  v_options jsonb;
  v_prompt text;
  v_correct_text text;
  v_correct_index integer;
  v_option_count integer;
  v_distinct_options integer;
begin
  if coalesce(pg_catalog.jsonb_typeof(p_content), 'null') <> 'object'
     or p_content = '{}'::jsonb then
    return false;
  end if;

  if p_type = 'reading' then
    return coalesce(
      pg_catalog.length(
             pg_catalog.btrim(coalesce(p_content ->> 'instructions_pt', ''))
           ) between 3 and 2000
       and pg_catalog.length(
             pg_catalog.btrim(coalesce(
               p_content ->> 'text',
               p_content ->> 'passage',
               p_content ->> 'reading_text',
               ''
             ))
           ) between 20 and 12000
       and private.learning_text_array_is_valid(
             p_content -> 'checklist',
             1,
             12,
             500
           )
       and pg_catalog.length(
             pg_catalog.btrim(coalesce(
               p_content ->> 'reflection_prompt',
               p_content ->> 'reflectionPrompt',
               ''
             ))
           ) between 3 and 1200,
      false
    );
  elsif p_type in ('grammar', 'quiz') then
    if p_type = 'grammar' then
      if pg_catalog.length(
           pg_catalog.btrim(coalesce(p_content ->> 'rule_pt', ''))
         ) not between 3 and 4000 then
        return false;
      end if;
      v_items := p_content -> 'exercises';
    else
      if pg_catalog.length(
           pg_catalog.btrim(coalesce(p_content ->> 'instructions_pt', ''))
         ) not between 3 and 2000 then
        return false;
      end if;
      v_items := p_content -> 'questions';
    end if;

    if coalesce(pg_catalog.jsonb_typeof(v_items), 'null') <> 'array'
       or pg_catalog.jsonb_array_length(v_items) not between 1 and 20 then
      return false;
    end if;

    for v_item in
      select item.value
        from pg_catalog.jsonb_array_elements(v_items) as item(value)
    loop
      if pg_catalog.jsonb_typeof(v_item) is distinct from 'object' then
        return false;
      end if;

      v_prompt := pg_catalog.btrim(coalesce(
        v_item ->> 'q',
        v_item ->> 'question',
        v_item ->> 'question_text',
        v_item ->> 'sentence',
        v_item ->> 'prompt',
        ''
      ));
      v_options := v_item -> 'options';
      v_correct_text := coalesce(
        v_item ->> 'correct',
        v_item ->> 'correctIndex',
        v_item ->> 'correct_option_index'
      );

      if pg_catalog.length(v_prompt) not between 1 and 2000
         or pg_catalog.jsonb_typeof(v_options) is distinct from 'array'
         or pg_catalog.jsonb_array_length(v_options) not between 2 and 8
         or coalesce(v_correct_text ~ '^[0-9]+$', false) is not true
         or pg_catalog.length(v_correct_text) not between 1 and 2
         or (
           v_item ? 'id'
           and pg_catalog.length(
             pg_catalog.btrim(coalesce(v_item ->> 'id', ''))
           ) not between 1 and 160
         )
         or (
           v_item ? 'exp'
           and (
             pg_catalog.jsonb_typeof(v_item -> 'exp') is distinct from 'string'
             or pg_catalog.length(v_item ->> 'exp') > 2000
           )
         ) then
        return false;
      end if;

      select
        pg_catalog.count(*)::integer,
        pg_catalog.count(
          distinct pg_catalog.btrim(option.value #>> '{}')
        )::integer
        into v_option_count, v_distinct_options
        from pg_catalog.jsonb_array_elements(v_options) as option(value)
       where pg_catalog.jsonb_typeof(option.value) = 'string'
         and pg_catalog.length(
               pg_catalog.btrim(option.value #>> '{}')
             ) between 1 and 500;

      v_correct_index := v_correct_text::integer;
      if v_option_count <> pg_catalog.jsonb_array_length(v_options)
         or v_distinct_options <> v_option_count
         or v_correct_index < 0
         or v_correct_index >= v_option_count then
        return false;
      end if;
    end loop;

    return true;
  elsif p_type = 'conversation' then
    return coalesce(
      pg_catalog.length(
             pg_catalog.btrim(coalesce(p_content ->> 'scenario', ''))
           ) between 2 and 1000
       and pg_catalog.length(
             pg_catalog.btrim(coalesce(p_content ->> 'instructions_pt', ''))
           ) between 3 and 4000
       and private.learning_text_array_is_valid(
             p_content -> 'preparation',
             1,
             12,
             500
           )
       and private.learning_text_array_is_valid(
             p_content -> 'target_phrases',
             1,
             20,
             500
           )
       and pg_catalog.length(
             pg_catalog.btrim(coalesce(
               p_content ->> 'reflection_prompt',
               p_content ->> 'reflectionPrompt',
               ''
             ))
           ) between 3 and 1200,
      false
    );
  end if;

  return false;
end;
$_$;


--
-- Name: guard_active_student_learning_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_active_student_learning_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_id uuid := new.student_id;
begin
  if tg_table_name = 'student_complementary_generation_reservations'
     and tg_op = 'UPDATE'
     and coalesce(pg_catalog.to_jsonb(new) ->> 'status', '') in (
       'RELEASED',
       'EXPIRED',
       'DENIED'
     ) then
    return new;
  end if;

  if tg_table_name = 'student_path_enrollments'
     and tg_op = 'UPDATE'
     and coalesce(pg_catalog.to_jsonb(new) ->> 'status', '') <> 'ACTIVE' then
    return new;
  end if;

  if not private.student_learning_access_is_active(v_student_id) then
    raise exception using
      errcode = '42501',
      message = 'inactive_student_learning_mutation_forbidden';
  end if;

  return new;
end;
$$;


--
-- Name: guard_active_student_scheduled_booking(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_active_student_scheduled_booking() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.student_id is null
     or pg_catalog.upper(pg_catalog.btrim(coalesce(
          new.status,
          ''
        ))) <> 'SCHEDULED'
  then
    return new;
  end if;

  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || coalesce(new.tenant_id, '') || ':' ||
        new.student_id::text,
      0
    )
  ) then
    raise exception using
      errcode = '55000',
      message = 'student_lifecycle_operation_in_flight';
  end if;

  perform 1
    from public.profiles as student
   where student.id = new.student_id
     and student.tenant_id = new.tenant_id
     and student.role = 'STUDENT'
     and pg_catalog.lower(pg_catalog.btrim(coalesce(
           student.lifecycle_status,
           ''
         ))) = 'active'
     and pg_catalog.lower(pg_catalog.btrim(coalesce(
           student.status,
           'Ativo'
         ))) not in (
           'inativo', 'inactive', 'arquivado', 'cancelado', 'trancado'
         )
   for key share;
  if not found then
    raise exception using
      errcode = '23514',
      message = 'inactive_student_scheduled_booking_forbidden';
  end if;

  return new;
end;
$$;


--
-- Name: guard_against_student_card_schedule_move(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_against_student_card_schedule_move() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id text;
  v_student_id uuid;
  v_subscription_id text;
  v_active boolean := false;
begin
  if tg_table_name = 'asaas_provider_creation_attempts' then
    v_tenant_id := new.tenant_id;
    v_student_id := new.lifecycle_student_id;
    v_active := v_student_id is not null
      and new.lifecycle_released_at is null
      and new.status in (
        'CLAIMED', 'SUBMITTING', 'UNKNOWN', 'SUCCEEDED', 'BLOCKED'
      );
  elsif tg_table_name = 'student_overdue_card_charge_claims' then
    v_tenant_id := new.tenant_id;
    v_student_id := new.student_id;
    v_active := new.status in (
      'PROCESSING', 'SUBMITTING', 'UNKNOWN', 'BLOCKED'
    ) or (
      new.status = 'SUCCEEDED'
      and not exists (
        select 1
          from public.student_payments as payment
         where payment.tenant_id = new.tenant_id
           and payment.student_id = new.student_id
           and nullif(pg_catalog.btrim(coalesce(
                 payment.asaas_payment_id, ''
               )), '') = new.asaas_payment_id
           and pg_catalog.upper(pg_catalog.btrim(coalesce(
                 payment.status, ''
               ))) in ('RECEIVED', 'RECEIVED_IN_CASH')
      )
    );
  else
    v_tenant_id := new.tenant_id;
    v_student_id := new.student_id;
    v_active := case tg_table_name
      when 'student_offboarding_operations' then new.status in (
        'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
        'UNKNOWN', 'BLOCKED'
      )
      when 'student_account_deletion_claims' then new.status in (
        'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
        'UNKNOWN', 'BLOCKED'
      )
      when 'student_billing_method_operations' then new.status in (
        'CLAIMED', 'MUTATING', 'UNKNOWN', 'BLOCKED'
      )
      when 'asaas_student_billing_period_claims' then new.status in (
        'CLAIMED', 'SUBMITTING', 'UNKNOWN', 'BLOCKED'
      )
      when 'asaas_outbound_message_attempts' then new.status in (
        'CLAIMED', 'SUBMITTING', 'UNKNOWN'
      )
      when 'asaas_subscription_mutation_operations' then new.status in (
        'CLAIMED', 'SUBMITTING', 'UNKNOWN', 'BLOCKED'
      )
      else false
    end;
    if tg_table_name = 'asaas_subscription_mutation_operations' then
      v_subscription_id := new.subscription_id;
    end if;
  end if;

  if not v_active or v_student_id is null then return new; end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || v_tenant_id || ':' ||
        v_student_id::text,
      0
    )
  );
  if private.student_card_schedule_move_active(
       v_tenant_id,
       v_student_id,
       v_subscription_id
     )
  then
    raise exception 'student_card_schedule_move_in_flight'
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: guard_anonymous_resume_path(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_anonymous_resume_path() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
begin
  if (select auth.uid()) is null
    and coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role'
    and (
      new.resume_url is null
      or new.resume_url !~* '^https://api[.]wisewolflanguage[.]com[.]br/storage/v1/object/public/resumes/school-wise-wolf/[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](pdf|doc|docx)$'
    )
  then
    raise exception 'invalid public resume path' using errcode = '22023';
  end if;

  return new;
end;
$_$;


