--
-- Name: guard_claim_against_student_card_schedule_move(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_claim_against_student_card_schedule_move() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation record;
  v_old_claim_id uuid := case when tg_op = 'INSERT' then null else old.id end;
  v_new_claim_id uuid := case when tg_op = 'DELETE' then null else new.id end;
  v_old_tenant_id text := case when tg_op = 'INSERT' then null else old.tenant_id end;
  v_new_tenant_id text := case when tg_op = 'DELETE' then null else new.tenant_id end;
  v_old_student_id uuid := case when tg_op = 'INSERT' then null else old.student_id end;
  v_new_student_id uuid := case when tg_op = 'DELETE' then null else new.student_id end;
  v_old_due_date date := case when tg_op = 'INSERT' then null else old.due_date end;
  v_new_due_date date := case when tg_op = 'DELETE' then null else new.due_date end;
  v_lock_key text;
begin
  for v_lock_key in
    select candidate.lock_key
      from (values
        (case when v_old_tenant_id is null or v_old_student_id is null
                    or v_old_due_date is null then null else
          'student-billing-period-month:' || v_old_tenant_id || ':' ||
            v_old_student_id::text || ':' ||
            pg_catalog.date_trunc('month', v_old_due_date)::date::text end),
        (case when v_new_tenant_id is null or v_new_student_id is null
                    or v_new_due_date is null then null else
          'student-billing-period-month:' || v_new_tenant_id || ':' ||
            v_new_student_id::text || ':' ||
            pg_catalog.date_trunc('month', v_new_due_date)::date::text end)
      ) as candidate(lock_key)
     where candidate.lock_key is not null
     group by candidate.lock_key
     order by candidate.lock_key
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_lock_key, 0)
    );
  end loop;
  for v_operation in
    select operation.tenant_id, operation.student_id,
           operation.subscription_id
      from public.asaas_student_card_schedule_moves as operation
     where operation.status in (
       'READY', 'MOVING_PAYMENT', 'PAYMENT_MOVED',
       'UPDATING_TARGET_SCHEDULE', 'TARGET_SCHEDULED',
       'AWAITING_LOCAL_RECONCILIATION', 'COMPENSATING',
       'RESTORING_ORIGINAL_SCHEDULE',
       'ORIGINAL_SCHEDULE_RESTORED', 'RESTORING_ORIGINAL_PAYMENT',
       'UNKNOWN', 'BLOCKED'
     )
       and (
         operation.target_billing_claim_id in (
           v_old_claim_id, v_new_claim_id
         )
         or (
           v_old_tenant_id = operation.tenant_id
           and v_old_student_id = operation.student_id
           and pg_catalog.date_trunc('month', v_old_due_date) in (
             pg_catalog.date_trunc('month', operation.old_due_date),
             pg_catalog.date_trunc('month', operation.target_due_date)
           )
         )
         or (
           v_new_tenant_id = operation.tenant_id
           and v_new_student_id = operation.student_id
           and pg_catalog.date_trunc('month', v_new_due_date) in (
             pg_catalog.date_trunc('month', operation.old_due_date),
             pg_catalog.date_trunc('month', operation.target_due_date)
           )
         )
       )
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'student-billing-lifecycle:' || v_operation.tenant_id || ':' ||
          v_operation.student_id::text,
        0
      )
    );
    if private.student_card_schedule_move_active(
         v_operation.tenant_id,
         v_operation.student_id,
         v_operation.subscription_id
       )
    then
      raise exception 'student_card_schedule_move_in_flight'
        using errcode = '55000';
    end if;
  end loop;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: guard_crm_lead_trial_delete(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_crm_lead_trial_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.opportunity_id is not null then
    raise exception 'linked crm trial leads cannot be deleted'
      using errcode = '23503';
  end if;
  return old;
end;
$$;


--
-- Name: guard_crm_lead_trial_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_crm_lead_trial_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_binding_lead text := nullif(
    pg_catalog.current_setting('app.crm_trial_binding_lead', true),
    ''
  );
  v_binding_opportunity text := nullif(
    pg_catalog.current_setting('app.crm_trial_binding_opportunity', true),
    ''
  );
  v_binding_changed boolean := false;
begin
  if tg_op = 'INSERT' then
    v_binding_changed := new.opportunity_id is not null;
  else
    v_binding_changed := new.opportunity_id is distinct from
      old.opportunity_id;
  end if;

  if v_binding_changed
     and (
       v_binding_lead is distinct from new.id::text
       or v_binding_opportunity is distinct from new.opportunity_id::text
     ) then
    raise exception 'crm lead trial binding requires the secure command'
      using errcode = '42501';
  end if;
  if new.opportunity_id is not null
     and not exists (
       select 1
         from public.opportunities as opportunity
        where opportunity.id = new.opportunity_id
          and opportunity.tenant_id = new.tenant_id
          and opportunity.kind = 'TRIAL'
     ) then
    raise exception 'crm lead trial opportunity tenant mismatch'
      using errcode = '23503';
  end if;
  return new;
end;
$$;


--
-- Name: guard_crm_trial_status_authority(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_crm_trial_status_authority() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_authoritative_opportunity text := nullif(
    pg_catalog.current_setting('app.crm_trial_outcome_opportunity', true),
    ''
  );
  v_binding_lead text := nullif(
    pg_catalog.current_setting('app.crm_trial_binding_lead', true),
    ''
  );
  v_binding_opportunity text := nullif(
    pg_catalog.current_setting('app.crm_trial_binding_opportunity', true),
    ''
  );
  v_linked_opportunity uuid := coalesce(
    new.opportunity_id,
    old.opportunity_id
  );
  v_authoritative_change boolean := false;
begin
  if new.status is distinct from old.status then
    v_authoritative_change := (
      v_linked_opportunity is not null
      and v_authoritative_opportunity is not distinct from
        v_linked_opportunity::text
    ) or (
      new.opportunity_id is not null
      and v_binding_lead is not distinct from new.id::text
      and v_binding_opportunity is not distinct from
        new.opportunity_id::text
    );

    if (
      pg_catalog.upper(pg_catalog.btrim(coalesce(old.status, ''))) = 'WON'
      and pg_catalog.upper(pg_catalog.btrim(coalesce(new.status, ''))) <>
        'WON'
    ) or (
      pg_catalog.upper(pg_catalog.btrim(coalesce(new.status, ''))) in (
        'SCHEDULED', 'TRIAL_DONE'
      )
      and not v_authoritative_change
    ) or (
      old.opportunity_id is not null
      and not v_authoritative_change
    ) then
      new.status := old.status;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: guard_enrolled_learning_curriculum(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_enrolled_learning_curriculum() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_new jsonb := case when tg_op = 'DELETE' then null else pg_catalog.to_jsonb(new) end;
  v_old jsonb := case when tg_op = 'INSERT' then null else pg_catalog.to_jsonb(old) end;
  v_path_id uuid;
  v_unit_id uuid;
  v_archive_path text := nullif(
    pg_catalog.current_setting('app.learning_path_archive_id', true),
    ''
  );
  v_archive_nonce text := nullif(
    pg_catalog.current_setting('app.learning_path_archive_nonce', true),
    ''
  );
begin
  if tg_table_name = 'learning_paths' then
    v_path_id := coalesce(
      nullif(v_new ->> 'id', '')::uuid,
      nullif(v_old ->> 'id', '')::uuid
    );
  elsif tg_table_name = 'learning_units' then
    if tg_op = 'UPDATE'
       and v_new ->> 'path_id' is distinct from v_old ->> 'path_id' then
      raise exception using
        errcode = '55000',
        message = 'learning_unit_cannot_change_path';
    end if;
    v_path_id := coalesce(
      nullif(v_new ->> 'path_id', '')::uuid,
      nullif(v_old ->> 'path_id', '')::uuid
    );
  elsif tg_table_name = 'unit_activities' then
    if tg_op = 'UPDATE'
       and v_new ->> 'unit_id' is distinct from v_old ->> 'unit_id' then
      raise exception using
        errcode = '55000',
        message = 'learning_activity_cannot_change_unit';
    end if;
    v_unit_id := coalesce(
      nullif(v_new ->> 'unit_id', '')::uuid,
      nullif(v_old ->> 'unit_id', '')::uuid
    );
    select unit.path_id
      into v_path_id
      from public.learning_units as unit
     where unit.id = v_unit_id;

    -- A parent learning_unit DELETE fires its FK cascade after that parent is
    -- no longer visible. The parent's own BEFORE DELETE guard has already
    -- locked and validated the path, so the child cascade is safe to finish.
    -- A direct activity DELETE still resolves its existing parent normally.
    if v_path_id is null and tg_op = 'DELETE' then
      return old;
    end if;
  else
    raise exception using
      errcode = '55000',
      message = 'unsupported_learning_curriculum_table';
  end if;

  if v_path_id is null then
    raise exception using
      errcode = '23503',
      message = 'learning_curriculum_path_required';
  end if;

  perform 1
    from public.learning_paths as path
   where path.id = v_path_id
   for update;
  if not found then
    -- A parent learning_path DELETE validates and locks itself in its own
    -- BEFORE trigger. Its subsequent unit/activity FK cascades run after the
    -- parent is no longer visible, so only those child DELETEs may finish.
    if tg_op = 'DELETE'
       and tg_table_name in ('learning_units', 'unit_activities') then
      return old;
    end if;

    raise exception using
      errcode = '23503',
      message = 'learning_curriculum_path_not_found';
  end if;

  if exists (
    select 1
      from public.student_path_enrollments as enrollment
     where enrollment.path_id = v_path_id
  ) then
    if tg_table_name = 'learning_paths' and tg_op = 'UPDATE' then
      if v_archive_path = v_path_id::text
         and new.active is false
         and old.active is true
         and (v_new - 'active') = (v_old - 'active')
         and exists (
           select 1
             from private.learning_path_archive_capabilities as capability
            where capability.nonce::text = v_archive_nonce
              and capability.path_id = v_path_id
              and capability.actor_id = auth.uid()
              and capability.backend_pid = pg_catalog.pg_backend_pid()
              and capability.transaction_id = pg_catalog.txid_current()
         ) then
        return new;
      end if;
    end if;

    raise exception using
      errcode = '55000',
      message = 'learning_path_curriculum_frozen_after_enrollment';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: guard_membership_against_student_card_schedule_move(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_membership_against_student_card_schedule_move() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_old_student_id uuid := case when tg_op = 'INSERT' then null else old.user_id end;
  v_new_student_id uuid := case when tg_op = 'DELETE' then null else new.user_id end;
  v_lock_student_id uuid;
  v_operation record;
begin
  for v_lock_student_id in
    select candidate.student_id
      from (values (v_old_student_id), (v_new_student_id))
        as candidate(student_id)
     where candidate.student_id is not null
     group by candidate.student_id
     order by candidate.student_id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'student-membership-user:' || v_lock_student_id::text,
        0
      )
    );
  end loop;
  for v_operation in
    select operation.tenant_id, operation.student_id,
           operation.subscription_id
      from public.asaas_student_card_schedule_moves as operation
     where operation.student_id in (
       v_old_student_id, v_new_student_id
     )
       and operation.status in (
         'READY', 'MOVING_PAYMENT', 'PAYMENT_MOVED',
         'UPDATING_TARGET_SCHEDULE', 'TARGET_SCHEDULED',
         'AWAITING_LOCAL_RECONCILIATION', 'COMPENSATING',
         'RESTORING_ORIGINAL_SCHEDULE',
         'ORIGINAL_SCHEDULE_RESTORED', 'RESTORING_ORIGINAL_PAYMENT',
         'UNKNOWN', 'BLOCKED'
       )
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'student-billing-lifecycle:' || v_operation.tenant_id || ':' ||
          v_operation.student_id::text,
        0
      )
    );
    if private.student_card_schedule_move_active(
         v_operation.tenant_id,
         v_operation.student_id,
         v_operation.subscription_id
       )
    then
      raise exception 'student_card_schedule_move_in_flight'
        using errcode = '55000';
    end if;
  end loop;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


