--
-- Name: guard_profile_against_student_card_schedule_move(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_profile_against_student_card_schedule_move() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_protected_change boolean;
begin
  v_protected_change := tg_op = 'DELETE' or (
    old.tenant_id is distinct from new.tenant_id
    or old.role is distinct from new.role
    or old.status is distinct from new.status
    or old.lifecycle_status is distinct from new.lifecycle_status
    or old.is_test_account is distinct from new.is_test_account
    or old.asaas_customer_id is distinct from new.asaas_customer_id
    or old.subscription_id is distinct from new.subscription_id
    or old.monthly_fee is distinct from new.monthly_fee
    or old.due_day is distinct from new.due_day
    or old.start_date is distinct from new.start_date
    or old.asaas_subscription_status is distinct from
      new.asaas_subscription_status
    or old.asaas_subscription_end_date is distinct from
      new.asaas_subscription_end_date
    or old.asaas_subscription_synced_at is distinct from
      new.asaas_subscription_synced_at
  );
  if not v_protected_change then return new; end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || old.tenant_id || ':' || old.id::text,
      0
    )
  );
  if tg_op = 'DELETE' then
    if private.student_card_schedule_move_active(
         old.tenant_id,
         old.id,
         old.subscription_id
       )
    then
      raise exception 'student_card_schedule_move_in_flight'
        using errcode = '55000';
    end if;
    return old;
  end if;
  if private.student_card_schedule_move_active(
       old.tenant_id,
       old.id,
       old.subscription_id
     )
  then
    raise exception 'student_card_schedule_move_in_flight'
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: guard_public_intake(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_public_intake() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  request_headers pg_catalog.jsonb := coalesce(
    nullif(
      pg_catalog.current_setting('request.headers', true),
      ''
    )::pg_catalog.jsonb,
    '{}'::pg_catalog.jsonb
  );
  caller_role text := coalesce(auth.jwt() ->> 'role', '');
  client_ip text;
  v_client_hash text;
  v_current_window timestamptz := pg_catalog.date_trunc(
    'hour',
    pg_catalog.clock_timestamp()
  );
  updated_count integer;
  normalized_phone text;
  staff_authorized boolean := false;
begin
  -- service_role is the only JWT role allowed to bypass tenant checks. A
  -- regular authenticated identity must still be authorized by its trusted
  -- profile row for the tenant being written.
  if caller_role = 'service_role' then
    return new;
  end if;

  if (select auth.uid()) is not null then
    if tg_table_schema = 'public' and tg_table_name = 'crm_leads' then
      staff_authorized := private.can_manage_crm_tenant(new.tenant_id);
    elsif tg_table_schema = 'public' and tg_table_name = 'job_applications' then
      staff_authorized := private.can_admin_tenant(new.tenant_id);
    end if;

    if staff_authorized then
      return new;
    end if;
  end if;

  client_ip := pg_catalog.split_part(
    coalesce(
      nullif(request_headers ->> 'x-real-ip', ''),
      nullif(request_headers ->> 'cf-connecting-ip', ''),
      nullif(request_headers ->> 'x-forwarded-for', ''),
      'unknown'
    ),
    ',',
    1
  );
  v_client_hash := pg_catalog.encode(
    extensions.digest(client_ip, 'sha256'),
    'hex'
  );

  if tg_table_schema = 'public' and tg_table_name = 'crm_leads' then
    if new.tenant_id is distinct from 'school-wise-wolf'
      or pg_catalog.char_length(pg_catalog.btrim(coalesce(new.name, '')))
        not between 2 and 120
      or pg_catalog.char_length(coalesce(new.email, '')) > 254
      or pg_catalog.char_length(coalesce(new.phone, '')) > 32
      or pg_catalog.char_length(coalesce(new.goal, '')) > 500
      or pg_catalog.char_length(coalesce(new.source, '')) > 120
      or pg_catalog.char_length(coalesce(new.notes, '')) > 3000
      or (
        new.source = 'wolfie_quiz'
        and new.public_intake_idempotency_key is null
      )
    then
      raise exception 'invalid public lead payload' using errcode = '22023';
    end if;

    normalized_phone := pg_catalog.regexp_replace(
      coalesce(new.phone, ''),
      '\D',
      '',
      'g'
    );
    if normalized_phone <> ''
      and pg_catalog.char_length(normalized_phone) not between 10 and 13
    then
      raise exception 'invalid public lead phone' using errcode = '22023';
    end if;
  elsif tg_table_schema = 'public' and tg_table_name = 'job_applications' then
    if new.tenant_id is distinct from 'school-wise-wolf'
      or pg_catalog.char_length(pg_catalog.btrim(coalesce(new.name, '')))
        not between 2 and 120
      or pg_catalog.char_length(
        pg_catalog.regexp_replace(
          coalesce(new.whatsapp, ''),
          '\D',
          '',
          'g'
        )
      ) not between 10 and 13
      or pg_catalog.char_length(coalesce(new.email, '')) > 254
      or pg_catalog.char_length(coalesce(new.source, '')) > 120
      or pg_catalog.char_length(coalesce(new.answers::text, '')) > 20000
      or coalesce(pg_catalog.lower(new.role), 'professor')
        not in ('professor', 'vendedor')
      or new.resume_url is null
      or new.resume_url not like
        'https://api.wisewolflanguage.com.br/storage/v1/object/public/resumes/school-wise-wolf/%'
    then
      raise exception 'invalid public job application payload'
        using errcode = '22023';
    end if;

    if exists (
      select 1
      from public.job_applications as application
      where application.tenant_id = new.tenant_id
        and pg_catalog.regexp_replace(
          application.whatsapp,
          '\D',
          '',
          'g'
        ) = pg_catalog.regexp_replace(new.whatsapp, '\D', '', 'g')
        and application.created_at >=
          pg_catalog.clock_timestamp() - interval '24 hours'
    ) then
      raise exception 'application already received recently'
        using errcode = '23505';
    end if;
  else
    raise exception 'unsupported public intake table' using errcode = '22023';
  end if;

  insert into private.public_intake_rate_limits (
    intake_kind,
    client_hash,
    window_started_at,
    request_count
  )
  values (tg_table_name, v_client_hash, v_current_window, 1)
  on conflict (intake_kind, client_hash, window_started_at)
  do update
    set request_count =
      private.public_intake_rate_limits.request_count + 1
  returning request_count into updated_count;

  if updated_count > (case when tg_table_name = 'crm_leads' then 5 else 3 end) then
    raise exception 'public intake rate limit exceeded' using errcode = 'P0001';
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION guard_public_intake(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.guard_public_intake() IS 'Validates/rate-limits public or unauthorized intake; bypasses only service_role and tenant-authorized staff.';


--
-- Name: guard_public_saas_lead_intake(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_public_saas_lead_intake() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
declare
  client_identity text;
  rate_limit_client_hash text;
  current_window timestamptz := date_trunc('hour', clock_timestamp());
  updated_count integer;
  normalized_phone text := regexp_replace(coalesce(new.phone, ''), '\D', '', 'g');
  normalized_owner_phone text := regexp_replace(coalesce(new.owner_phone, ''), '\D', '', 'g');
begin
  if coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
    or exists (
      select 1
      from public.profiles as profile
      where profile.id = (select auth.uid())
        and profile.role = 'SUPER_ADMIN'
        and lower(btrim(profile.lifecycle_status)) = 'active'
    )
  then
    return new;
  end if;

  if char_length(btrim(coalesce(new.name, ''))) not between 2 and 120
    or char_length(btrim(coalesce(new.school_name, ''))) not between 2 and 160
    or char_length(btrim(coalesce(new.email, ''))) not between 5 and 254
    or position('@' in coalesce(new.email, '')) <= 1
    or char_length(normalized_phone) not between 10 and 13
    or char_length(coalesce(new.notes, '')) > 3000
    or char_length(coalesce(new.source, '')) > 120
    or char_length(coalesce(new.plan_interest, '')) > 120
    or new.lead_type not in ('school', 'teacher')
    or new.converted_tenant_id is not null
    or (new.estimated_students is not null and new.estimated_students not between 0 and 1000000)
    or (new.estimated_teachers is not null and new.estimated_teachers not between 0 and 100000)
    or (normalized_owner_phone <> '' and char_length(normalized_owner_phone) not between 10 and 13)
    or new.owner_cpf_cnpj is not null
  then
    raise exception 'invalid public SaaS lead payload' using errcode = '22023';
  end if;

  if new.lead_type = 'teacher' then
    if lower(coalesce(new.status, '')) <> 'new'
      or new.plan_interest <> 'Professor Negócio'
      or coalesce(new.estimated_teachers, 1) <> 1
      or new.source <> (case
        when new.referrer_teacher_id is not null then 'teacher_to_teacher_referral'
        when new.parent_tenant_id is not null then 'teacher_referral'
        else 'teacher_signup'
      end)
      or btrim(coalesce(new.owner_name, '')) <> btrim(new.name)
      or lower(btrim(coalesce(new.owner_email, ''))) <> lower(btrim(new.email))
      or (normalized_owner_phone <> '' and normalized_owner_phone <> normalized_phone)
      or (
        new.parent_tenant_id is not null
        and (
          new.parent_tenant_id = 'master'
          or not exists (
            select 1
            from public.tenants as tenant
            where tenant.id = new.parent_tenant_id
          )
        )
      )
      or (
        new.referrer_teacher_id is not null
        and not exists (
          select 1
          from public.profiles as teacher
          join public.tenant_memberships as membership
            on membership.user_id = teacher.id
           and membership.status = 'ACTIVE'
           and membership.role = 'TEACHER'
          where teacher.id = new.referrer_teacher_id
            and teacher.role = 'TEACHER'
            and lower(btrim(teacher.lifecycle_status)) = 'active'
            and (
              new.parent_tenant_id is null
              or membership.tenant_id = new.parent_tenant_id
            )
        )
      )
    then
      raise exception 'invalid public teacher lead payload' using errcode = '22023';
    end if;
  elsif upper(coalesce(new.status, '')) <> 'LEAD'
    or new.source <> 'public_school_diagnosis'
    or new.plan_interest <> 'Wise Wolf para Escolas — diagnóstico assistido'
    or btrim(coalesce(new.owner_name, '')) <> btrim(new.name)
    or lower(btrim(coalesce(new.owner_email, ''))) <> lower(btrim(new.email))
    or normalized_owner_phone <> normalized_phone
    or new.parent_tenant_id is not null
    or new.referrer_teacher_id is not null
  then
    raise exception 'invalid public school lead payload' using errcode = '22023';
  end if;

  client_identity := coalesce(
    (select auth.uid())::text,
    lower(btrim(new.email)) || ':' || normalized_phone
  );
  rate_limit_client_hash := encode(digest(client_identity, 'sha256'), 'hex');

  insert into private.public_intake_rate_limits (
    intake_kind,
    client_hash,
    window_started_at,
    request_count
  )
  values ('saas_leads', rate_limit_client_hash, current_window, 1)
  on conflict (intake_kind, client_hash, window_started_at)
  do update
  set request_count = private.public_intake_rate_limits.request_count + 1
  returning request_count into updated_count;

  if updated_count > 5 then
    raise exception 'public SaaS lead rate limit exceeded' using errcode = 'P0001';
  end if;

  delete from private.public_intake_rate_limits
  where window_started_at < clock_timestamp() - interval '48 hours';

  return new;
end;
$$;


--
-- Name: FUNCTION guard_public_saas_lead_intake(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.guard_public_saas_lead_intake() IS 'Validates and rate-limits public SaaS diagnosis requests before they enter the privileged sales workflow.';


--
-- Name: guard_student_card_schedule_move(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_student_card_schedule_move() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.operation_key is distinct from new.operation_key
     or (
       old.tenant_id is distinct from new.tenant_id
       and not (
         old.tenant_id is not null and new.tenant_id is null
         and old.status in ('COMPLETED', 'COMPENSATED', 'FAILED')
         and new.status = old.status
       )
     )
     or (
       old.student_id is distinct from new.student_id
       and not (
         old.student_id is not null and new.student_id is null
         and old.status in ('COMPLETED', 'COMPENSATED', 'FAILED')
         and new.status = old.status
       )
     )
     or (
       old.offer_id is distinct from new.offer_id
       and not (
         old.offer_id is not null and new.offer_id is null
         and old.status in ('COMPLETED', 'COMPENSATED', 'FAILED')
         and new.status = old.status
       )
     )
     or (
       old.student_payment_id is distinct from new.student_payment_id
       and not (
         old.student_payment_id is not null
         and new.student_payment_id is null
         and old.status in ('COMPLETED', 'COMPENSATED', 'FAILED')
         and new.status = old.status
       )
     )
     or (
       old.target_billing_claim_id is distinct from new.target_billing_claim_id
       and not (
         old.target_billing_claim_id is not null
         and new.target_billing_claim_id is null
         and new.status in ('COMPLETED', 'FAILED', 'COMPENSATED')
       )
     )
     or old.target_claim_fingerprint is distinct from
          new.target_claim_fingerprint
     or old.customer_id is distinct from new.customer_id
     or old.subscription_id is distinct from new.subscription_id
     or old.payment_id is distinct from new.payment_id
     or old.old_due_date is distinct from new.old_due_date
     or old.target_due_date is distinct from new.target_due_date
     or old.target_next_due_date is distinct from new.target_next_due_date
     or old.original_next_due_date is distinct from new.original_next_due_date
     or old.target_end_date is distinct from new.target_end_date
     or old.original_end_date is distinct from new.original_end_date
     or old.expected_value is distinct from new.expected_value
     or old.expected_max_payments is distinct from new.expected_max_payments
     or old.original_subscription_snapshot is distinct from
          new.original_subscription_snapshot
     or old.target_subscription_snapshot is distinct from
          new.target_subscription_snapshot
     or old.original_payment_snapshot is distinct from
          new.original_payment_snapshot
     or old.target_payment_snapshot is distinct from new.target_payment_snapshot
     or old.original_payments_snapshot is distinct from
          new.original_payments_snapshot
     or old.integration_snapshot is distinct from new.integration_snapshot
     or old.accept_events_until is distinct from new.accept_events_until
     or old.started_at is distinct from new.started_at
     or old.created_at is distinct from new.created_at
  then
    raise exception 'student_card_schedule_move_snapshot_immutable'
      using errcode = '55000';
  end if;

  if old.status in ('COMPLETED', 'COMPENSATED', 'FAILED')
     and (
       new.status is distinct from old.status
       or new.last_error is distinct from old.last_error
     )
  then
    raise exception 'student_card_schedule_move_terminal'
      using errcode = '55000';
  end if;
  if old.completed_at is not null
     and new.completed_at is distinct from old.completed_at
  then
    raise exception 'student_card_schedule_move_completion_immutable'
      using errcode = '55000';
  end if;

  new.updated_at := pg_catalog.clock_timestamp();
  return new;
end;
$$;


--
-- Name: guard_student_card_schedule_move_step(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_student_card_schedule_move_step() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.operation_id is distinct from new.operation_id
     or old.step_kind is distinct from new.step_kind
     or old.route_kind is distinct from new.route_kind
     or old.ordinal is distinct from new.ordinal
     or old.request_fingerprint is distinct from new.request_fingerprint
     or old.expected_before is distinct from new.expected_before
     or old.desired_after is distinct from new.desired_after
     or old.provider_request is distinct from new.provider_request
     or old.created_at is distinct from new.created_at
  then
    raise exception 'student_card_schedule_move_step_snapshot_immutable'
      using errcode = '55000';
  end if;
  if new.submit_attempt_count < old.submit_attempt_count
     or new.submit_attempt_count > old.submit_attempt_count + 1
     or (old.submit_attempt_count = 1 and new.submit_attempt_count <> 1)
     or (old.submitted_at is not null
       and new.submitted_at is distinct from old.submitted_at)
     or (old.completed_at is not null
       and new.completed_at is distinct from old.completed_at)
  then
    raise exception 'student_card_schedule_move_step_submit_immutable'
      using errcode = '55000';
  end if;
  if new.status = 'SUBMITTING' and old.status <> 'SUBMITTING'
     and (old.status <> 'READY' or old.submit_attempt_count <> 0
       or new.submit_attempt_count <> 1 or new.submitted_at is null)
  then
    raise exception 'student_card_schedule_move_step_resubmit_forbidden'
      using errcode = '55000';
  end if;
  if old.status in ('SUCCEEDED', 'FAILED', 'BLOCKED')
     and (
       new.status is distinct from old.status
       or new.provider_response is distinct from old.provider_response
       or new.observed_state is distinct from old.observed_state
       or new.provider_http_status is distinct from old.provider_http_status
       or new.submit_attempt_count is distinct from old.submit_attempt_count
       or new.submitted_at is distinct from old.submitted_at
       or new.completed_at is distinct from old.completed_at
       or new.last_error is distinct from old.last_error
     )
  then
    raise exception 'student_card_schedule_move_step_terminal'
      using errcode = '55000';
  end if;
  new.updated_at := pg_catalog.clock_timestamp();
  return new;
end;
$$;


--
-- Name: guard_student_creation_against_subscription_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_student_creation_against_subscription_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.lifecycle_student_id is null
     or new.lifecycle_released_at is not null
     or new.status not in (
       'CLAIMED', 'SUBMITTING', 'UNKNOWN', 'SUCCEEDED', 'BLOCKED'
     )
  then
    return new;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || new.tenant_id || ':' ||
        new.lifecycle_student_id::text,
      0
    )
  );
  if exists (
    select 1
      from public.asaas_subscription_mutation_operations as operation
     where operation.tenant_id = new.tenant_id
       and operation.student_id = new.lifecycle_student_id
       and operation.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN', 'BLOCKED')
  ) then
    raise exception 'student_subscription_mutation_in_flight'
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: guard_student_financial_operation_against_subscription_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_student_financial_operation_against_subscription_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_active boolean := false;
begin
  if tg_table_name = 'asaas_student_billing_period_claims' then
    v_active := new.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN', 'BLOCKED');
  elsif tg_table_name = 'asaas_outbound_message_attempts' then
    v_active := new.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN');
  elsif tg_table_name = 'student_overdue_card_charge_claims' then
    v_active := new.status in (
      'PROCESSING', 'SUBMITTING', 'UNKNOWN', 'BLOCKED'
    ) or (
      new.status = 'SUCCEEDED'
      and not exists (
        select 1
          from public.student_payments as payment
         where payment.tenant_id = new.tenant_id
           and payment.student_id = new.student_id
           and nullif(pg_catalog.btrim(coalesce(
                 payment.asaas_payment_id, ''
               )), '') = new.asaas_payment_id
           and pg_catalog.upper(pg_catalog.btrim(coalesce(
                 payment.status, ''
               ))) in ('RECEIVED', 'RECEIVED_IN_CASH')
      )
    );
  end if;
  if not v_active then
    return new;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || new.tenant_id || ':' ||
        new.student_id::text,
      0
    )
  );
  if exists (
    select 1
      from public.asaas_subscription_mutation_operations as operation
     where operation.tenant_id = new.tenant_id
       and operation.student_id = new.student_id
       and operation.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN', 'BLOCKED')
  ) then
    raise exception 'student_subscription_mutation_in_flight'
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: guard_student_lifecycle_against_subscription_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_student_lifecycle_against_subscription_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status not in (
    'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
    'MUTATING', 'UNKNOWN', 'BLOCKED'
  ) then
    return new;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || new.tenant_id || ':' ||
        new.student_id::text,
      0
    )
  );
  if exists (
    select 1
      from public.asaas_subscription_mutation_operations as operation
     where operation.tenant_id = new.tenant_id
       and operation.student_id = new.student_id
       and operation.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN', 'BLOCKED')
  ) then
    raise exception 'student_subscription_mutation_in_flight'
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: guard_student_membership_lifecycle_operation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_student_membership_lifecycle_operation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  subject_id uuid;
  profile_tenant text;
begin
  if tg_op = 'UPDATE' and new.user_id is distinct from old.user_id then
    raise exception 'tenant_membership_user_id_immutable'
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    subject_id := old.user_id;
  else
    subject_id := new.user_id;
  end if;

  select profile.tenant_id
    into profile_tenant
    from public.profiles as profile
   where profile.id = subject_id;

  -- A non-blocking advisory lock closes the BEFORE-trigger visibility gap.
  -- If a begin/finalize RPC already owns the student lifecycle key, fail
  -- immediately instead of waiting while holding a row lock (which could
  -- invert the RPC's advisory -> row lock order). The owning finalizer
  -- transaction can reacquire its own key and continue.
  if profile_tenant is not null and not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || profile_tenant || ':' ||
        subject_id::text,
      0
    )
  ) then
    raise exception 'student_lifecycle_operation_in_flight'
      using errcode = '55000';
  end if;

  if exists (
    select 1
      from public.student_offboarding_operations as operation
     where operation.student_id = subject_id
       and operation.status in (
         'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN'
       )
  ) then
    raise exception 'student_lifecycle_operation_in_flight'
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: guard_student_profile_lifecycle_operation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_student_profile_lifecycle_operation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.student_offboarding_operations%rowtype;
  finalizer_id text := coalesce(
    pg_catalog.current_setting('app.student_lifecycle_finalizer', true),
    ''
  );
begin
  if tg_op = 'UPDATE' and new.id is distinct from old.id then
    raise exception 'student_profile_id_immutable'
      using errcode = '55000';
  end if;

  if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || old.tenant_id || ':' || old.id::text,
      0
    )
  ) then
    raise exception 'student_lifecycle_operation_in_flight'
      using errcode = '55000';
  end if;
  if tg_op = 'UPDATE'
     and new.tenant_id is distinct from old.tenant_id
     and not pg_catalog.pg_try_advisory_xact_lock(
       pg_catalog.hashtextextended(
         'student-billing-lifecycle:' || new.tenant_id || ':' || new.id::text,
         0
       )
     )
  then
    raise exception 'student_lifecycle_operation_in_flight'
      using errcode = '55000';
  end if;

  select operation.*
    into operation_row
    from public.student_offboarding_operations as operation
   where operation.student_id = old.id
     and (
       operation.tenant_id = old.tenant_id
       or (tg_op = 'UPDATE' and operation.tenant_id = new.tenant_id)
     )
     and operation.status in (
       'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN'
     )
   order by operation.created_at desc, operation.id
   limit 1;

  -- Check OLD as well as NEW authority so role/tenant rewrites cannot move the
  -- student out of an already-frozen operation. Only the exact finalizer
  -- transaction may apply its compare-and-swap profile update.
  if found and finalizer_id is distinct from operation_row.id::text then
    raise exception 'student_lifecycle_operation_in_flight'
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: guard_wolfie_topup_provider_snapshot(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_wolfie_topup_provider_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.provider_customer_id is not null
     and new.provider_customer_id is distinct from old.provider_customer_id
  then
    raise exception 'wolfie_topup_customer_snapshot_immutable'
      using errcode = '55000';
  end if;
  if old.provider_payment_id is null
     and new.provider_payment_id is not null
     and new.provider_customer_id is null
  then
    raise exception 'wolfie_topup_customer_snapshot_required'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: has_tenant_membership(text, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_tenant_membership(p_tenant_id text, p_roles text[] DEFAULT NULL::text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.tenant_memberships AS membership
    WHERE membership.user_id = (SELECT auth.uid())
      AND membership.tenant_id = p_tenant_id
      AND membership.status = 'ACTIVE'
      AND (p_roles IS NULL OR membership.role = ANY (p_roles))
  );
$$;


--
-- Name: hub_activate_paid_checkout_apply(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_activate_paid_checkout_apply(p_checkout_id uuid, p_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_checkout public.hub_checkout_sessions%rowtype;
  v_subscription public.hub_subscriptions%rowtype;
  v_plan public.hub_plans%rowtype;
  v_payment public.hub_subscription_payments%rowtype;
  v_payment_id text := nullif(pg_catalog.btrim(p_payment_id), '');
  v_period_interval interval;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_student_plan_id uuid;
  v_student_plan_name text;
  v_is_renewal boolean := false;
begin
  if p_checkout_id is null
     or v_payment_id is null
     or pg_catalog.char_length(v_payment_id) > 200 then
    raise exception 'invalid_hub_payment' using errcode = '22023';
  end if;

  -- The provider can emit distinct event names for one payment. Serialize by
  -- payment id before consulting the ledger so only one transaction can buy a
  -- period.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('hub-payment:ASAAS:' || v_payment_id, 0)
  );

  select * into v_checkout
  from public.hub_checkout_sessions
  where id = p_checkout_id
  for update;
  if not found then
    raise exception 'hub_checkout_not_found' using errcode = 'P0002';
  end if;
  if v_checkout.status in ('CANCELLED', 'REVERSED') then
    raise exception 'hub_checkout_cancelled' using errcode = 'P0001';
  end if;

  select * into v_payment
  from public.hub_subscription_payments
  where provider = 'ASAAS'
    and provider_payment_id = v_payment_id
  for update;
  if found and v_payment.checkout_id <> v_checkout.id then
    raise exception 'hub_checkout_payment_mismatch' using errcode = '42501';
  end if;
  if found and v_payment.status = 'REVERSED' then
    return pg_catalog.jsonb_build_object(
      'accountId', v_checkout.account_id,
      'subscriptionId', v_payment.subscription_id,
      'status', 'REVERSED',
      'idempotent', true,
      'applied', false
    );
  end if;
  if found and v_payment.status = 'APPLIED' then
    if v_payment.subscription_id is not null then
      select * into v_subscription
      from public.hub_subscriptions
      where id = v_payment.subscription_id;
    end if;
    return pg_catalog.jsonb_build_object(
      'accountId', v_checkout.account_id,
      'subscriptionId', v_payment.subscription_id,
      'status', coalesce(v_subscription.status, 'ACTIVE'),
      'idempotent', true,
      'applied', true
    );
  end if;

  select * into v_plan
  from public.hub_plans
  where id = v_checkout.plan_id;
  if not found then
    raise exception 'hub_plan_required' using errcode = '55000';
  end if;
  if v_plan.product_family is distinct from v_checkout.product_family then
    raise exception 'hub_checkout_product_mismatch' using errcode = '23514';
  end if;
  if not v_plan.is_active
     and v_checkout.status in ('CREATED', 'PENDING') then
    raise exception 'active_hub_plan_required' using errcode = '55000';
  end if;
  if v_checkout.product_family = 'WOLFIE_STANDALONE'
     and v_checkout.billing_cycle <> 'MONTHLY' then
    raise exception 'wolfie_monthly_billing_required' using errcode = '23514';
  end if;

  -- Resolve the subscription before deciding whether this is an initial
  -- settlement or a recurring payment. The provider subscription id is the
  -- stable link; checkout payment id intentionally remains the first payment.
  if v_payment.subscription_id is not null then
    select * into v_subscription
    from public.hub_subscriptions
    where id = v_payment.subscription_id
      and account_id = v_checkout.account_id
      and product_family = v_checkout.product_family
    for update;
  else
    select * into v_subscription
    from public.hub_subscriptions as subscription
    where subscription.account_id = v_checkout.account_id
      and subscription.product_family = v_checkout.product_family
      and subscription.provider = 'ASAAS'
      and (
        (
          v_checkout.asaas_subscription_id is not null
          and subscription.provider_subscription_id =
            v_checkout.asaas_subscription_id
        )
        or subscription.metadata ->> 'checkoutId' = v_checkout.id::text
      )
    order by
      (subscription.provider_subscription_id =
        v_checkout.asaas_subscription_id) desc,
      subscription.created_at desc,
      subscription.id desc
    limit 1
    for update;
  end if;

  if v_subscription.id is null
     and v_checkout.asaas_payment_id is not null
     and v_checkout.asaas_payment_id is distinct from v_payment_id then
    raise exception 'hub_checkout_payment_mismatch' using errcode = '42501';
  end if;

  -- Compatibility for a payment applied before the ledger migration. The
  -- original checkout payment is recorded, never charged as a renewal.
  if v_checkout.status = 'PAID'
     and v_checkout.asaas_payment_id = v_payment_id
     and v_payment.id is null
     and v_subscription.id is not null then
    insert into public.hub_subscription_payments (
      provider, provider_payment_id, checkout_id, subscription_id,
      account_id, product_family, status, period_starts_at, period_ends_at,
      applied_at, metadata
    ) values (
      'ASAAS', v_payment_id, v_checkout.id, v_subscription.id,
      v_checkout.account_id, v_checkout.product_family, 'APPLIED',
      v_subscription.current_period_starts_at,
      v_subscription.current_period_ends_at,
      pg_catalog.now(),
      '{"source":"legacy_paid_checkout"}'::jsonb
    );
    return pg_catalog.jsonb_build_object(
      'accountId', v_checkout.account_id,
      'subscriptionId', v_subscription.id,
      'status', v_subscription.status,
      'idempotent', true,
      'applied', true
    );
  end if;

  v_period_interval := case
    when v_checkout.billing_cycle = 'YEARLY' then interval '1 year'
    else interval '1 month'
  end;
  v_is_renewal := v_subscription.id is not null
    and v_checkout.status in ('PAID', 'OVERDUE');
  v_period_start := case
    when v_is_renewal then greatest(
      coalesce(v_subscription.current_period_ends_at, pg_catalog.now()),
      pg_catalog.now()
    )
    else pg_catalog.now()
  end;
  v_period_end := v_period_start + v_period_interval;

  if v_subscription.id is not null then
    update public.hub_subscriptions
    set status = 'EXPIRED',
        current_period_ends_at = least(
          coalesce(current_period_ends_at, pg_catalog.now()),
          pg_catalog.now()
        ),
        updated_at = pg_catalog.now()
    where account_id = v_checkout.account_id
      and product_family = v_checkout.product_family
      and id <> v_subscription.id
      and status in ('TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE');

    update public.hub_subscriptions
    set status = 'ACTIVE',
        plan_id = v_checkout.plan_id,
        billing_cycle = v_checkout.billing_cycle,
        product_family = v_checkout.product_family,
        provider_payment_id = v_payment_id,
        current_period_starts_at = v_period_start,
        current_period_ends_at = v_period_end,
        cancelled_at = null,
        updated_at = pg_catalog.now()
    where id = v_subscription.id
    returning * into v_subscription;
  else
    update public.hub_subscriptions
    set status = 'EXPIRED',
        current_period_ends_at = least(
          coalesce(current_period_ends_at, pg_catalog.now()),
          pg_catalog.now()
        ),
        updated_at = pg_catalog.now()
    where account_id = v_checkout.account_id
      and product_family = v_checkout.product_family
      and status in ('TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE');

    insert into public.hub_subscriptions (
      account_id, plan_id, status, billing_cycle,
      current_period_starts_at, current_period_ends_at,
      provider, provider_subscription_id, provider_payment_id,
      product_family, metadata
    ) values (
      v_checkout.account_id, v_checkout.plan_id, 'ACTIVE', v_checkout.billing_cycle,
      v_period_start, v_period_end,
      'ASAAS', v_checkout.asaas_subscription_id, v_payment_id,
      v_checkout.product_family,
      pg_catalog.jsonb_build_object('checkoutId', v_checkout.id)
    ) returning * into v_subscription;
  end if;

  if v_payment.id is null then
    insert into public.hub_subscription_payments (
      provider, provider_payment_id, checkout_id, subscription_id,
      account_id, product_family, status, period_starts_at, period_ends_at,
      applied_at, metadata
    ) values (
      'ASAAS', v_payment_id, v_checkout.id, v_subscription.id,
      v_checkout.account_id, v_checkout.product_family, 'APPLIED',
      v_period_start, v_period_end, pg_catalog.now(),
      pg_catalog.jsonb_build_object(
        'billingCycle', v_checkout.billing_cycle,
        'renewal', v_is_renewal
      )
    );
  else
    update public.hub_subscription_payments
    set subscription_id = v_subscription.id,
        status = 'APPLIED',
        period_starts_at = v_period_start,
        period_ends_at = v_period_end,
        applied_at = coalesce(applied_at, pg_catalog.now()),
        reversed_at = null,
        metadata = metadata || pg_catalog.jsonb_build_object(
          'billingCycle', v_checkout.billing_cycle,
          'renewal', v_is_renewal
        ),
        updated_at = pg_catalog.now()
    where id = v_payment.id
      and status = 'OVERDUE';
  end if;

  update public.hub_checkout_sessions
  set status = 'PAID',
      -- Keep the first payment on the checkout. The latest recurring payment
      -- lives on hub_subscriptions and every payment lives in the ledger.
      asaas_payment_id = coalesce(asaas_payment_id, v_payment_id),
      updated_at = pg_catalog.now()
  where id = v_checkout.id;

  if v_checkout.product_family = 'WOLFIE_STANDALONE' then
    v_student_plan_name := nullif(v_plan.metadata ->> 'student_plan_name', '');
    select id into v_student_plan_id
    from public.student_pricing_plans
    where tenant_id = 'wolfie-direct'
      and name = v_student_plan_name
      and active = true
    order by id
    limit 1;
    if v_student_plan_id is null then
      raise exception 'wolfie_student_plan_missing' using errcode = '55000';
    end if;
    if not exists (
      select 1
      from public.tenant_memberships
      where user_id = v_checkout.requested_by
        and tenant_id = 'wolfie-direct'
        and role = 'STUDENT'
        and status = 'ACTIVE'
    ) then
      raise exception 'wolfie_account_not_prepared' using errcode = '55000';
    end if;

    update public.tenant_memberships
    set student_plan_id = v_student_plan_id,
        updated_at = pg_catalog.now()
    where user_id = v_checkout.requested_by
      and tenant_id = 'wolfie-direct'
      and role = 'STUDENT'
      and status = 'ACTIVE';

    perform pg_catalog.set_config('app.enrollment_claim', '1', true);
    update public.profiles
    set fidelity_plan = v_student_plan_name,
        status_financial = 'ACTIVE'
    where id = v_checkout.requested_by
      and tenant_id = 'wolfie-direct'
      and role = 'STUDENT';
  end if;

  insert into public.hub_conversion_events(
    account_id, user_id, event_name, source, metadata
  ) values (
    v_checkout.account_id,
    v_checkout.requested_by,
    case
      when v_checkout.product_family = 'WOLFIE_STANDALONE'
           and v_is_renewal then 'wolfie_subscription_renewed'
      when v_checkout.product_family = 'WOLFIE_STANDALONE'
        then 'wolfie_subscription_paid'
      when v_is_renewal then 'hub_subscription_renewed'
      else 'hub_subscription_paid'
    end,
    'asaas_webhook',
    pg_catalog.jsonb_build_object(
      'checkoutId', v_checkout.id,
      'planId', v_checkout.plan_id,
      'providerPaymentId', v_payment_id,
      'renewal', v_is_renewal
    )
  );

  return pg_catalog.jsonb_build_object(
    'accountId', v_checkout.account_id,
    'subscriptionId', v_subscription.id,
    'status', v_subscription.status,
    'idempotent', false,
    'renewal', v_is_renewal,
    'periodStartsAt', v_period_start,
    'periodEndsAt', v_period_end
  );
end;
$$;


--
-- Name: hub_activate_paid_checkout_provider_apply(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_activate_paid_checkout_provider_apply(p_checkout_id uuid, p_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_checkout public.hub_checkout_sessions%rowtype;
  v_subscription public.hub_subscriptions%rowtype;
  v_payment_id text := nullif(pg_catalog.btrim(p_payment_id), '');
begin
  if p_checkout_id is null
     or v_payment_id is null
     or pg_catalog.char_length(v_payment_id) > 200 then
    raise exception 'invalid_hub_payment' using errcode = '22023';
  end if;

  select checkout.* into v_checkout
  from public.hub_checkout_sessions as checkout
  where checkout.id = p_checkout_id
  for update;
  if not found then
    return private.hub_activate_paid_checkout_apply(
      p_checkout_id,
      v_payment_id
    );
  end if;

  if v_checkout.product_family = 'HUB_CORE' then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'hub-provider-subscription:' || coalesce(
          nullif(v_checkout.asaas_subscription_id, ''),
          v_checkout.id::text
        ),
        0
      )
    );

    select subscription.* into v_subscription
    from public.hub_subscriptions as subscription
    where subscription.account_id = v_checkout.account_id
      and subscription.product_family = 'HUB_CORE'
      and (
        (
          pg_catalog.jsonb_typeof(
            subscription.metadata -> 'cancelAtPeriodEnd'
          ) = 'boolean'
          and (subscription.metadata ->> 'cancelAtPeriodEnd')::boolean
        )
        or (
          pg_catalog.jsonb_typeof(
            subscription.metadata -> 'cancellationInProgress'
          ) = 'boolean'
          and (subscription.metadata ->> 'cancellationInProgress')::boolean
        )
      )
      and (
        (
          nullif(v_checkout.asaas_subscription_id, '') is not null
          and subscription.provider = 'ASAAS'
          and subscription.provider_subscription_id =
            v_checkout.asaas_subscription_id
        )
        or subscription.metadata ->> 'checkoutId' = v_checkout.id::text
      )
    order by subscription.created_at desc, subscription.id desc
    limit 1
    for update;

    if (
         pg_catalog.jsonb_typeof(
           v_checkout.metadata -> 'cancelAtPeriodEnd'
         ) = 'boolean'
         and (v_checkout.metadata ->> 'cancelAtPeriodEnd')::boolean
       ) or v_subscription.id is not null then
      update public.hub_checkout_sessions as checkout
      set metadata = coalesce(checkout.metadata, '{}'::jsonb)
            || pg_catalog.jsonb_build_object(
              'postCancellationPaymentObservedAt', pg_catalog.now(),
              'postCancellationPaymentId', v_payment_id,
              'requiresManualReconciliation', true
            ),
          updated_at = pg_catalog.now()
      where checkout.id = v_checkout.id;

      return pg_catalog.jsonb_build_object(
        'accountId', v_checkout.account_id,
        'subscriptionId', v_subscription.id,
        'status', coalesce(v_subscription.status, 'CANCELLED'),
        'idempotent', true,
        'applied', false,
        'cancelAtPeriodEnd', true,
        'periodEndsAt', v_subscription.current_period_ends_at
      );
    end if;
  end if;

  return private.hub_activate_paid_checkout_apply(
    p_checkout_id,
    v_payment_id
  );
end;
$$;


--
-- Name: FUNCTION hub_activate_paid_checkout_provider_apply(p_checkout_id uuid, p_payment_id text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.hub_activate_paid_checkout_provider_apply(p_checkout_id uuid, p_payment_id text) IS 'Service-only billing activation wrapper that refuses to extend a provider schedule already cancelled at period end.';


--
-- Name: hub_actor_owns_namespaced_material_object(text, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_actor_owns_namespaced_material_object(object_name text, actor_id uuid, actor_tenant_id text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  select actor_id is not null
    and actor_tenant_id is not null
    and cardinality(storage.foldername(object_name)) = 2
    and (storage.foldername(object_name))[1] = actor_tenant_id
    and (storage.foldername(object_name))[2] = actor_id::text
    and storage.filename(object_name) ~
      '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](pdf|jpe?g|png|webp|mp4|mp3|wav)$'
    and exists (
      select 1
      from storage.objects as object
      where object.bucket_id = 'materials'
        and object.name = object_name
        and object.owner_id = actor_id::text
    );
$_$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: hub_provider_operations; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.hub_provider_operations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    logical_key text NOT NULL,
    operation_kind text NOT NULL,
    account_id uuid NOT NULL,
    actor_user_id uuid,
    target_status text,
    reason text,
    snapshot jsonb NOT NULL,
    snapshot_hash text NOT NULL,
    status text DEFAULT 'READY'::text NOT NULL,
    lease_token uuid DEFAULT gen_random_uuid() NOT NULL,
    integration_id uuid,
    integration_version bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT hub_provider_operations_check CHECK ((((integration_id IS NULL) AND (integration_version IS NULL)) OR ((integration_id IS NOT NULL) AND (integration_version IS NOT NULL) AND (integration_version > 0)))),
    CONSTRAINT hub_provider_operations_operation_kind_check CHECK ((operation_kind = ANY (ARRAY['ACCOUNT_STATUS'::text, 'CORE_CANCELLATION'::text, 'WEBHOOK_CANCELLATION'::text]))),
    CONSTRAINT hub_provider_operations_snapshot_check CHECK ((jsonb_typeof(snapshot) = 'object'::text)),
    CONSTRAINT hub_provider_operations_snapshot_hash_check CHECK ((snapshot_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT hub_provider_operations_status_check CHECK ((status = ANY (ARRAY['READY'::text, 'IN_PROGRESS'::text, 'SUCCEEDED'::text, 'BLOCKED'::text])))
);


--
-- Name: TABLE hub_provider_operations; Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON TABLE private.hub_provider_operations IS 'Immutable Hub provider-mutation snapshots; retries after SUBMITTING are GET-only.';


--
-- Name: hub_assert_provider_operation_complete(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_assert_provider_operation_complete(p_operation_id uuid, p_lease_token uuid) RETURNS private.hub_provider_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation private.hub_provider_operations%rowtype;
  v_account public.hub_accounts%rowtype;
  v_checkout public.hub_checkout_sessions%rowtype;
  v_subscription public.hub_subscriptions%rowtype;
  v_account_id uuid;
  v_account_row_version text;
  v_item jsonb;
begin
  perform private.hub_service_role_required();
  select operation.account_id into v_account_id
  from private.hub_provider_operations operation
  where operation.id = p_operation_id;
  if not found then
    raise exception 'hub_provider_operation_claim_lost'
      using errcode = '55000';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-provider-operation:' || v_account_id::text,
      0
    )
  );
  select operation.* into v_operation from private.hub_provider_operations operation
  where operation.id = p_operation_id for update;
  if not found or v_operation.account_id is distinct from v_account_id
     or v_operation.lease_token is distinct from p_lease_token then
    raise exception 'hub_provider_operation_claim_lost' using errcode = '55000';
  end if;
  if exists (select 1 from private.hub_provider_operation_targets target
    where target.operation_id = p_operation_id
      and target.state not in ('CONFIRMED', 'ABSENT')) then
    raise exception 'hub_provider_cancellation_not_confirmed' using errcode = '55000';
  end if;
  if v_operation.snapshot_hash is distinct from pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(v_operation.snapshot::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  ) then
    raise exception 'hub_provider_operation_snapshot_corrupt'
      using errcode = '55000';
  end if;
  if pg_catalog.jsonb_typeof(v_operation.snapshot -> 'targets')
       is distinct from 'array' then
    raise exception 'hub_provider_operation_snapshot_corrupt'
      using errcode = '55000';
  end if;
  if v_operation.status = 'SUCCEEDED' then
    return v_operation;
  end if;

  select account.* into v_account
  from public.hub_accounts as account
  where account.id = v_operation.account_id
  for update;
  if not found
     or pg_catalog.btrim(v_account.asaas_customer_id) is distinct from
       (v_operation.snapshot ->> 'providerCustomerId') then
    raise exception 'hub_provider_operation_scope_changed'
      using errcode = '55000';
  end if;
  select account.xmin::text || ':' || account.cmin::text
    into v_account_row_version
  from public.hub_accounts as account
  where account.id = v_operation.account_id;

  if v_operation.operation_kind in ('ACCOUNT_STATUS', 'CORE_CANCELLATION') then
    perform subscription.id
    from public.hub_subscriptions subscription
    where subscription.account_id = v_operation.account_id
      and (v_operation.operation_kind <> 'CORE_CANCELLATION'
        or subscription.product_family = 'HUB_CORE')
    order by subscription.id
    for update;
    perform checkout.id
    from public.hub_checkout_sessions checkout
    where checkout.account_id = v_operation.account_id
      and (v_operation.operation_kind <> 'CORE_CANCELLATION'
        or checkout.product_family = 'HUB_CORE')
    order by checkout.id
    for update;

    if v_account.status is distinct from
         (v_operation.snapshot ->> 'accountStatus')
       or v_account.updated_at is distinct from
         (v_operation.snapshot ->> 'accountUpdatedAt')::timestamptz
       or v_account_row_version is distinct from
         (v_operation.snapshot ->> 'accountRowVersion')
       or pg_catalog.jsonb_typeof(
         v_operation.snapshot -> 'localSubscriptions'
       ) is distinct from 'array' then
      raise exception 'hub_provider_operation_scope_changed'
        using errcode = '55000';
    end if;

    for v_item in
      select element.value
      from pg_catalog.jsonb_array_elements(
        v_operation.snapshot -> 'localSubscriptions'
      ) as element(value)
    loop
      select subscription.* into v_subscription
      from public.hub_subscriptions as subscription
      where subscription.id = (v_item ->> 'id')::uuid
        and subscription.account_id = v_operation.account_id
      for update;
      if not found
         or v_subscription.product_family is distinct from
           (v_item ->> 'productFamily')
         or v_subscription.status is distinct from (v_item ->> 'status')
         or v_subscription.provider is distinct from (v_item ->> 'provider')
         or v_subscription.provider_subscription_id is distinct from
           (v_item ->> 'providerSubscriptionId') then
        raise exception 'hub_provider_operation_scope_changed'
          using errcode = '55000';
      end if;
    end loop;

    if exists (
      select 1
      from public.hub_subscriptions as subscription
      join public.hub_plans as plan on plan.id = subscription.plan_id
      where subscription.account_id = v_operation.account_id
        and (v_operation.operation_kind <> 'CORE_CANCELLATION'
          or subscription.product_family = 'HUB_CORE')
        and subscription.status in (
          'TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE'
        )
        and not (subscription.provider is null
          and subscription.provider_subscription_id is null
          and plan.code = 'DISCOVERY')
        and not exists (
          select 1
          from pg_catalog.jsonb_array_elements(
            v_operation.snapshot -> 'localSubscriptions'
          ) as item(value)
          where item.value ->> 'id' = subscription.id::text
        )
    ) then
      raise exception 'hub_provider_operation_scope_changed'
        using errcode = '55000';
    end if;

    -- No provider-linked checkout may appear after the immutable snapshot,
    -- even if its subscription row has not been materialized yet. Creation
    -- RPCs are fenced earlier; this is the final compare-and-set defense.
    if exists (
      select 1
      from public.hub_checkout_sessions as checkout
      where checkout.account_id = v_operation.account_id
        and (v_operation.operation_kind <> 'CORE_CANCELLATION'
          or checkout.product_family = 'HUB_CORE')
        and checkout.status in ('CREATED', 'PENDING', 'OVERDUE', 'PAID')
        and nullif(
          pg_catalog.btrim(checkout.asaas_subscription_id),
          ''
        ) is not null
        and not exists (
          select 1
          from pg_catalog.jsonb_array_elements(
            v_operation.snapshot -> 'targets'
          ) as item(value)
          where item.value ->> 'checkoutId' = checkout.id::text
            and item.value ->> 'providerSubscriptionId' =
              checkout.asaas_subscription_id
        )
    ) or exists (
      select 1
      from public.hub_checkout_sessions as checkout
      where checkout.account_id = v_operation.account_id
        and (v_operation.operation_kind <> 'CORE_CANCELLATION'
          or checkout.product_family = 'HUB_CORE')
        and checkout.status in ('PENDING', 'OVERDUE', 'PAID')
        and nullif(
          pg_catalog.btrim(checkout.asaas_subscription_id),
          ''
        ) is null
    ) then
      raise exception 'hub_provider_operation_scope_changed'
        using errcode = '55000';
    end if;
  end if;

  for v_item in
    select element.value
    from pg_catalog.jsonb_array_elements(
      v_operation.snapshot -> 'targets'
    ) as element(value)
  loop
    if not exists (
      select 1
      from private.hub_provider_operation_targets as target
      where target.operation_id = v_operation.id
        and target.provider_subscription_id =
          (v_item ->> 'providerSubscriptionId')
        and target.provider_customer_id =
          (v_item ->> 'providerCustomerId')
        and target.checkout_id = (v_item ->> 'checkoutId')::uuid
        and target.state in ('CONFIRMED', 'ABSENT')
    ) then
      raise exception 'hub_provider_operation_scope_changed'
        using errcode = '55000';
    end if;

    select checkout.* into v_checkout
    from public.hub_checkout_sessions as checkout
    where checkout.id = (v_item ->> 'checkoutId')::uuid
      and checkout.account_id = v_operation.account_id
      and checkout.asaas_subscription_id =
        (v_item ->> 'providerSubscriptionId')
    for update;
    if not found
       or (
         v_operation.operation_kind in (
           'ACCOUNT_STATUS', 'CORE_CANCELLATION'
         ) and (
           v_checkout.product_family is distinct from
             (v_item ->> 'productFamily')
           or v_checkout.status is distinct from
             (v_item ->> 'checkoutStatus')
         )
       ) then
      raise exception 'hub_provider_operation_scope_changed'
        using errcode = '55000';
    end if;
  end loop;
  return v_operation;
end;
$$;


--
-- Name: hub_begin_core_cancellation_internal(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_begin_core_cancellation_internal(p_account_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_subscription public.hub_subscriptions%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if p_account_id is null or p_actor_user_id is null then
    raise exception 'invalid_hub_cancellation_request'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-core-cancellation:' || p_account_id::text,
      0
    )
  );

  if not exists (
    select 1
    from public.hub_accounts as account
    where account.id = p_account_id
      and account.status = 'ACTIVE'
  ) then
    raise exception 'hub_account_inactive_or_missing' using errcode = '42501';
  end if;
  if not exists (
    select 1
    from public.hub_memberships as membership
    where membership.account_id = p_account_id
      and membership.user_id = p_actor_user_id
      and membership.status = 'ACTIVE'
      and membership.membership_role in ('OWNER', 'ADMIN')
  ) then
    raise exception 'hub_manager_required' using errcode = '42501';
  end if;

  select subscription.* into v_subscription
  from public.hub_subscriptions as subscription
  where subscription.account_id = p_account_id
    and subscription.product_family = 'HUB_CORE'
    and subscription.status = 'ACTIVE'
    and subscription.current_period_ends_at > pg_catalog.now()
  order by subscription.created_at desc, subscription.id desc
  limit 1
  for update;
  if not found then
    raise exception 'hub_active_paid_subscription_required'
      using errcode = '55000';
  end if;
  if v_subscription.provider is distinct from 'ASAAS'
     or nullif(pg_catalog.btrim(v_subscription.provider_subscription_id), '')
        is null then
    raise exception 'hub_subscription_reconciliation_required'
      using errcode = '55000';
  end if;

  if pg_catalog.jsonb_typeof(
       v_subscription.metadata -> 'cancelAtPeriodEnd'
     ) = 'boolean'
     and (v_subscription.metadata ->> 'cancelAtPeriodEnd')::boolean then
    return pg_catalog.jsonb_build_object(
      'success', true,
      'idempotent', true,
      'subscriptionId', v_subscription.id,
      'cancelAtPeriodEnd', true
    );
  end if;

  update public.hub_subscriptions as subscription
  set metadata = coalesce(subscription.metadata, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'cancellationInProgress', true,
          'cancellationInProgressAt', v_now,
          'cancellationInProgressBy', p_actor_user_id
        ),
      updated_at = v_now
  where subscription.id = v_subscription.id;

  return pg_catalog.jsonb_build_object(
    'success', true,
    'idempotent', false,
    'subscriptionId', v_subscription.id,
    'cancellationInProgress', true
  );
end;
$$;


--
-- Name: hub_bootstrap_internal(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_bootstrap_internal(p_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_account_id uuid;
  v_active_account_count integer := 0;
  v_is_manager boolean := false;
  v_blocked record;
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception 'authentication_required' using errcode = 'P0001';
  end if;
  if not private.hub_profile_is_active(v_user_id) then
    raise exception 'profile_inactive' using errcode = '42501';
  end if;
  if not private.hub_is_enabled() then
    raise exception 'hub_disabled' using errcode = 'P0001';
  end if;
  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_user_id
      and profile.tenant_id = 'wolfie-direct'
  ) then
    return null;
  end if;

  if p_account_id is null then
    select pg_catalog.count(*)::integer into v_active_account_count
    from public.hub_memberships as membership
    join public.hub_accounts as account
      on account.id = membership.account_id
     and account.status = 'ACTIVE'
    where membership.user_id = v_user_id
      and membership.status = 'ACTIVE';

    if v_active_account_count > 1 then
      return pg_catalog.jsonb_build_object(
        'account', null,
        'membership', null,
        'isManager', false,
        'subscription', null,
        'plan', null,
        'entitlements', '{}'::jsonb,
        'settings', private.hub_public_settings_internal(),
        'access', pg_catalog.jsonb_build_object(
          'allowed', false,
          'code', 'HUB_ACCOUNT_AMBIGUOUS'
        )
      );
    end if;
  end if;

  select
    membership.account_id,
    membership.membership_role in ('OWNER', 'ADMIN')
  into v_account_id, v_is_manager
  from public.hub_memberships as membership
  join public.hub_accounts as account
    on account.id = membership.account_id
   and account.status = 'ACTIVE'
  where membership.user_id = v_user_id
    and membership.status = 'ACTIVE'
    and (p_account_id is null or membership.account_id = p_account_id)
  order by
    (membership.membership_role = 'OWNER') desc,
    (membership.membership_role = 'ADMIN') desc,
    membership.created_at,
    membership.id
  limit 1;

  if v_account_id is null then
    select
      account.id as account_id,
      account.name as account_name,
      account.account_type,
      account.audience,
      account.status as account_status,
      membership.membership_role,
      membership.status as membership_status
    into v_blocked
    from public.hub_memberships as membership
    join public.hub_accounts as account
      on account.id = membership.account_id
    where membership.user_id = v_user_id
      and membership.status <> 'REMOVED'
      and (p_account_id is null or membership.account_id = p_account_id)
      and (
        membership.status <> 'ACTIVE'
        or account.status <> 'ACTIVE'
      )
    order by
      (membership.membership_role = 'OWNER') desc,
      (membership.membership_role = 'ADMIN') desc,
      membership.created_at,
      membership.id
    limit 1;
    if found then
      return pg_catalog.jsonb_build_object(
        'account', pg_catalog.jsonb_build_object(
          'id', v_blocked.account_id,
          'name', v_blocked.account_name,
          'account_type', v_blocked.account_type,
          'audience', v_blocked.audience,
          'status', case
            when v_blocked.account_status = 'ACTIVE'
              then 'SUSPENDED'
            else v_blocked.account_status
          end,
          'metadata', '{}'::jsonb
        ),
        'membership', pg_catalog.jsonb_build_object(
          'membership_role', v_blocked.membership_role,
          'status', v_blocked.membership_status
        ),
        'isManager', false,
        'subscription', null,
        'plan', null,
        'entitlements', '{}'::jsonb,
        'settings', private.hub_public_settings_internal(),
        'access', pg_catalog.jsonb_build_object(
          'allowed', false,
          'code', 'HUB_ACCOUNT_INACTIVE'
        )
      );
    end if;
    return null;
  end if;

  select pg_catalog.jsonb_build_object(
    'account', pg_catalog.jsonb_build_object(
      'id', account.id,
      'name', account.name,
          'account_type', account.account_type,
          'audience', account.audience,
          'status', account.status,
          'trial_claimed_at', account.trial_claimed_at,
          'metadata', pg_catalog.jsonb_strip_nulls(
            pg_catalog.jsonb_build_object(
              'onboarding_completed', account.metadata -> 'onboarding_completed',
              'level', account.metadata -> 'level',
              'role', account.metadata -> 'role',
              'goal', account.metadata -> 'goal',
              'interests', account.metadata -> 'interests',
              'preferred_modality', account.metadata -> 'preferred_modality',
              'personalized_at', account.metadata -> 'personalized_at'
            )
          )
    ),
    'membership', pg_catalog.jsonb_build_object(
      'membership_role', membership.membership_role,
      'status', membership.status
    ),
    'isManager', v_is_manager,
    'subscription', case
      when subscription.id is null then null
      else pg_catalog.jsonb_build_object(
        'id', subscription.id,
        'plan_id', subscription.plan_id,
        'status', subscription.status,
        'billing_cycle', subscription.billing_cycle,
        'trial_starts_at', subscription.trial_starts_at,
        'trial_ends_at', subscription.trial_ends_at,
        'current_period_starts_at', subscription.current_period_starts_at,
        'current_period_ends_at', subscription.current_period_ends_at,
        'product_family', subscription.product_family
      )
    end,
    'plan', case
      when plan.id is null then null
      else pg_catalog.jsonb_build_object(
        'id', plan.id,
        'code', plan.code,
        'name', plan.name,
        'description', plan.description,
        'audience', plan.audience,
        'price_monthly', plan.price_monthly,
        'price_yearly', plan.price_yearly,
        'trial_days', plan.trial_days,
        'features', plan.features,
        'metadata', plan.metadata,
        'product_family', plan.product_family
      )
    end,
    'entitlements', coalesce((
      select pg_catalog.jsonb_object_agg(
        entitlement.feature_key,
        pg_catalog.jsonb_build_object(
          'limit', entitlement.limit_value,
          'resetPeriod', entitlement.reset_period,
          'used', coalesce(usage.used_units, 0)
        )
      )
      from public.hub_plan_entitlements as entitlement
      left join lateral (
        select counter.used_units
        from public.hub_usage_counters as counter
        where counter.subscription_id = subscription.id
          and counter.feature_key = entitlement.feature_key
          and pg_catalog.now() >= counter.period_start
          and pg_catalog.now() < counter.period_end
        order by counter.period_start desc
        limit 1
      ) as usage on true
      where entitlement.plan_id = plan.id
    ), '{}'::jsonb),
    'settings', private.hub_public_settings_internal()
  ) into v_result
  from public.hub_accounts as account
  join public.hub_memberships as membership
    on membership.account_id = account.id
   and membership.user_id = v_user_id
   and membership.status = 'ACTIVE'
  left join lateral (
    select candidate.*
    from public.hub_subscriptions as candidate
    where candidate.account_id = account.id
      and candidate.product_family = 'HUB_CORE'
      and (
        (
          candidate.status = 'TRIALING'
          and candidate.trial_ends_at > pg_catalog.now()
        )
        or (
          candidate.status = 'ACTIVE'
          and coalesce(
            candidate.current_period_ends_at,
            '-infinity'::timestamptz
          ) > pg_catalog.now()
        )
      )
    order by
      (candidate.status = 'ACTIVE') desc,
      candidate.created_at desc,
      candidate.id desc
    limit 1
  ) as subscription on true
  left join public.hub_plans as plan
    on plan.id = subscription.plan_id
   and plan.product_family = 'HUB_CORE'
  where account.id = v_account_id
    and account.status = 'ACTIVE';

  return v_result;
end;
$$;


--
-- Name: hub_catalog_is_ready(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_catalog_is_ready() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    coalesce((
      select case
        when pg_catalog.jsonb_typeof(settings.metadata -> 'catalogReady') =
             'boolean'
          then (settings.metadata ->> 'catalogReady')::boolean
        else true
      end
      from public.hub_settings as settings
      where settings.settings_key = 'default'
    ), true)
    and exists (
      select 1
      from public.hub_content_items as item
      where item.is_active = true
        and item.catalog_scope = 'COMMERCIAL_GLOBAL'
        and item.rights_basis in ('OWNED', 'LICENSED', 'PUBLIC_DOMAIN')
        and item.published_at is not null
        and item.published_at <= pg_catalog.now()
        and item.preview_enabled = true
        and item.rights_verified_at is not null
        and nullif(pg_catalog.btrim(item.license_summary), '') is not null
        and exists (
          select 1
          from public.hub_content_assets as full_asset
          join storage.objects as full_object
            on full_object.bucket_id = full_asset.bucket_id
           and full_object.name = full_asset.object_path
          where full_asset.content_id = item.id
            and full_asset.asset_kind = 'FULL'
            and pg_catalog.btrim(full_asset.object_path) <> ''
        )
        and exists (
          select 1
          from public.hub_content_assets as preview_asset
          join storage.objects as preview_object
            on preview_object.bucket_id = preview_asset.bucket_id
           and preview_object.name = preview_asset.object_path
          where preview_asset.content_id = item.id
            and preview_asset.asset_kind = 'PREVIEW'
            and pg_catalog.btrim(preview_asset.object_path) <> ''
        )
    );
$$;


--
-- Name: FUNCTION hub_catalog_is_ready(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.hub_catalog_is_ready() IS 'Fail-closed commercial readiness check: at least one active, published and rights-verified Hub item must exist.';


--
-- Name: hub_checkout_fulfillment_snapshot_immutable(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_checkout_fulfillment_snapshot_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (old.metadata ? 'fulfillment_snapshot')
     and (
       not (new.metadata ? 'fulfillment_snapshot')
       or old.metadata -> 'fulfillment_snapshot'
         is distinct from new.metadata -> 'fulfillment_snapshot'
     ) then
    raise exception 'hub_checkout_fulfillment_snapshot_immutable'
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: hub_claim_trial_internal(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_claim_trial_internal(p_audience text DEFAULT 'EDUCATOR'::text, p_account_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_account public.hub_accounts%rowtype;
  v_membership public.hub_memberships%rowtype;
  v_account_id uuid;
  v_plan public.hub_plans%rowtype;
  v_subscription public.hub_subscriptions%rowtype;
  v_audience text := pg_catalog.upper(
    coalesce(nullif(pg_catalog.btrim(p_audience), ''), 'EDUCATOR')
  );
  v_name text;
  v_had_subscription boolean := false;
begin
  if v_user_id is null then
    raise exception 'authentication_required' using errcode = 'P0001';
  end if;
  if not private.hub_is_enabled() then
    raise exception 'hub_disabled' using errcode = 'P0001';
  end if;
  if v_audience not in ('LEARNER', 'EDUCATOR', 'INSTITUTION') then
    raise exception 'invalid_audience' using errcode = '22023';
  end if;
  if v_audience = 'INSTITUTION' then
    raise exception 'institutional_sales_assisted' using errcode = 'P0001';
  end if;
  if v_audience = 'LEARNER' then
    raise exception 'learner_product_routing_required' using errcode = 'P0001';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('hub-claim-trial:' || v_user_id::text, 0)
  );

  select * into v_profile
  from public.profiles as profile
  where profile.id = v_user_id;
  if not found then
    raise exception 'profile_required' using errcode = 'P0001';
  end if;
  if pg_catalog.lower(pg_catalog.btrim(v_profile.lifecycle_status)) <> 'active' then
    raise exception 'profile_inactive' using errcode = '42501';
  end if;
  if v_profile.tenant_id = 'wolfie-direct' then
    raise exception 'wolfie_direct_hub_restricted' using errcode = 'P0001';
  end if;

  select account.id into v_account_id
  from public.hub_accounts as account
  where account.owner_user_id = v_user_id
    and account.account_type = 'PERSONAL'
  order by account.created_at, account.id
  limit 1;

  if v_account_id is not null then
    select account.* into v_account
    from public.hub_accounts as account
    where account.id = v_account_id
    for update;
    if v_account.status <> 'ACTIVE' then
      raise exception 'hub_account_inactive' using errcode = '42501';
    end if;

    select membership.* into v_membership
    from public.hub_memberships as membership
    where membership.account_id = v_account.id
      and membership.user_id = v_user_id
    for update;
    if not found
      or v_membership.membership_role <> 'OWNER'
      or v_membership.status <> 'ACTIVE'
    then
      raise exception 'hub_membership_inactive' using errcode = '42501';
    end if;
  else
    v_name := coalesce(
      nullif(pg_catalog.btrim(p_account_name), ''),
      nullif(pg_catalog.btrim(v_profile.full_name), ''),
      pg_catalog.split_part(
        coalesce(v_profile.email, 'Conta Wise Wolf'),
        '@',
        1
      )
    );

    insert into public.hub_accounts (
      account_type,
      audience,
      name,
      owner_user_id,
      status
    ) values (
      'PERSONAL',
      v_audience,
      pg_catalog.left(v_name, 160),
      v_user_id,
      'ACTIVE'
    ) returning * into v_account;

    insert into public.hub_memberships (
      account_id,
      user_id,
      membership_role,
      status
    ) values (
      v_account.id,
      v_user_id,
      'OWNER',
      'ACTIVE'
    );

    perform pg_catalog.set_config('app.enrollment_claim', '1', true);
    update public.profiles as profile
    set role = 'NON_STUDENT'
    where profile.id = v_user_id
      and profile.role = 'STUDENT'
      and profile.tenant_id is null;
  end if;

  update public.hub_subscriptions as expired_trial
  set status = 'EXPIRED',
      current_period_ends_at = least(
        coalesce(
          expired_trial.current_period_ends_at,
          expired_trial.trial_ends_at,
          pg_catalog.now()
        ),
        pg_catalog.now()
      ),
      updated_at = pg_catalog.now()
  where expired_trial.account_id = v_account.id
    and expired_trial.product_family = 'HUB_CORE'
    and expired_trial.status = 'TRIALING'
    and expired_trial.trial_ends_at <= pg_catalog.now();

  select subscription.* into v_subscription
  from public.hub_subscriptions as subscription
  where subscription.account_id = v_account.id
    and subscription.product_family = 'HUB_CORE'
    and subscription.status in ('TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE')
  order by subscription.created_at desc, subscription.id desc
  limit 1;
  if found then
    return pg_catalog.jsonb_build_object(
      'accountId', v_account.id,
      'subscriptionId', v_subscription.id,
      'status', v_subscription.status,
      'trialEndsAt', v_subscription.trial_ends_at,
      'alreadyActive', true,
      'productFamily', 'HUB_CORE'
    );
  end if;

  select exists (
    select 1
    from public.hub_subscriptions as history
    where history.account_id = v_account.id
      and history.product_family = 'HUB_CORE'
  ) into v_had_subscription;
  if v_had_subscription then
    raise exception 'trial_already_claimed' using errcode = 'P0001';
  end if;

  select plan.* into v_plan
  from public.hub_plans as plan
  where plan.code = 'DISCOVERY'
    and plan.product_family = 'HUB_CORE'
    and plan.is_active = true;
  if not found then
    raise exception 'discovery_plan_unavailable' using errcode = 'P0001';
  end if;

  insert into public.hub_subscriptions (
    account_id,
    plan_id,
    status,
    trial_starts_at,
    trial_ends_at,
    current_period_starts_at,
    current_period_ends_at,
    product_family,
    metadata
  ) values (
    v_account.id,
    v_plan.id,
    'TRIALING',
    pg_catalog.now(),
    pg_catalog.now() + pg_catalog.make_interval(
      days => greatest(v_plan.trial_days, 1)
    ),
    pg_catalog.now(),
    pg_catalog.now() + pg_catalog.make_interval(
      days => greatest(v_plan.trial_days, 1)
    ),
    'HUB_CORE',
    '{"source":"hub_onboarding","product_family":"HUB_CORE"}'::jsonb
  ) returning * into v_subscription;

  update public.hub_accounts as account
  set trial_claimed_at = coalesce(account.trial_claimed_at, pg_catalog.now()),
      audience = v_audience,
      updated_at = pg_catalog.now()
  where account.id = v_account.id
  returning * into v_account;

  return pg_catalog.jsonb_build_object(
    'accountId', v_account.id,
    'subscriptionId', v_subscription.id,
    'status', v_subscription.status,
    'trialEndsAt', v_subscription.trial_ends_at,
    'alreadyActive', false,
    'productFamily', 'HUB_CORE'
  );
end;
$$;


--
-- Name: hub_close_unpaid_fulfillment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_close_unpaid_fulfillment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status in ('FAILED', 'CANCELLED', 'REVERSED')
     and old.status is distinct from new.status then
    update public.hub_fulfillment_outbox as delivery
    set status = 'SKIPPED',
        lease_token = null,
        lease_expires_at = null,
        provider_dispatch_started_at = null,
        last_error = 'checkout_closed_before_payment',
        completed_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
    where delivery.checkout_id = new.id
      and delivery.status = 'WAITING_PAYMENT';
  end if;
  return new;
end;
$$;


--
-- Name: hub_commit_feature_internal(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_commit_feature_internal(p_user_id uuid, p_reservation_id uuid, p_lease_token uuid, p_request_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := p_user_id;
  v_subscription_id uuid;
  v_subscription public.hub_subscriptions%rowtype;
  v_reservation private.hub_usage_reservations%rowtype;
  v_limit integer;
  v_used integer := 0;
  v_reserved integer := 0;
  v_event_id bigint;
  v_denial_code text;
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if v_user_id is null then
    raise exception 'user_required' using errcode = '22023';
  end if;
  if p_reservation_id is null
     or p_lease_token is null
     or p_request_key is null then
    raise exception 'invalid_usage_commit' using errcode = '22023';
  end if;
  if not private.hub_profile_is_active(v_user_id) then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'PROFILE_INACTIVE',
      'productFamily', 'HUB_CORE'
    );
  end if;

  select reservation.subscription_id into v_subscription_id
  from private.hub_usage_reservations as reservation
  where reservation.id = p_reservation_id;
  if v_subscription_id is null then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'RESERVATION_NOT_FOUND',
      'productFamily', 'HUB_CORE'
    );
  end if;

  select subscription.* into v_subscription
  from public.hub_subscriptions as subscription
  where subscription.id = v_subscription_id
  for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'RESERVATION_NOT_FOUND',
      'productFamily', 'HUB_CORE'
    );
  end if;

  select reservation.* into v_reservation
  from private.hub_usage_reservations as reservation
  where reservation.id = p_reservation_id
    and reservation.subscription_id = v_subscription.id
    and reservation.user_id = v_user_id
    and reservation.request_key = p_request_key
    and reservation.lease_token = p_lease_token
  for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'RESERVATION_NOT_FOUND',
      'productFamily', 'HUB_CORE'
    );
  end if;

  if v_reservation.status = 'COMMITTED' then
    return pg_catalog.jsonb_build_object(
      'allowed', true,
      'idempotent', true,
      'accountId', v_reservation.account_id,
      'subscriptionId', v_reservation.subscription_id,
      'reservationId', v_reservation.id,
      'productFamily', 'HUB_CORE'
    );
  end if;
  if v_reservation.status = 'RELEASED' then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'idempotent', true,
      'code', 'RESERVATION_RELEASED',
      'productFamily', 'HUB_CORE'
    );
  end if;

  if not private.hub_is_enabled() then
    v_denial_code := 'HUB_DISABLED';
  elsif not exists (
    select 1
    from public.hub_accounts as account
    join public.hub_memberships as membership
      on membership.account_id = account.id
     and membership.user_id = v_user_id
     and membership.status = 'ACTIVE'
    where account.id = v_reservation.account_id
      and account.status = 'ACTIVE'
  ) then
    v_denial_code := 'HUB_ACCOUNT_INACTIVE';
  elsif v_subscription.account_id <> v_reservation.account_id
     or v_subscription.product_family <> 'HUB_CORE'
     or not (
       (
         v_subscription.status = 'TRIALING'
         and v_subscription.trial_ends_at > pg_catalog.now()
       )
       or (
         v_subscription.status = 'ACTIVE'
         and coalesce(
           v_subscription.current_period_ends_at,
           '-infinity'::timestamptz
         ) > pg_catalog.now()
       )
     ) then
    v_denial_code := 'SUBSCRIPTION_REQUIRED';
  elsif v_reservation.lease_expires_at <= pg_catalog.now() then
    v_denial_code := 'RESERVATION_EXPIRED';
  end if;

  if v_denial_code is not null then
    update private.hub_usage_reservations as reservation
    set status = 'RELEASED',
        release_reason = v_denial_code,
        released_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
    where reservation.id = v_reservation.id;
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', v_denial_code,
      'productFamily', 'HUB_CORE'
    );
  end if;

  select entitlement.limit_value into v_limit
  from public.hub_plan_entitlements as entitlement
  where entitlement.plan_id = v_subscription.plan_id
    and entitlement.feature_key = v_reservation.feature_key;
  if not found or v_limit = 0 then
    update private.hub_usage_reservations as reservation
    set status = 'RELEASED',
        release_reason = 'FEATURE_NOT_INCLUDED',
        released_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
    where reservation.id = v_reservation.id;
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'FEATURE_NOT_INCLUDED',
      'productFamily', 'HUB_CORE'
    );
  end if;

  insert into public.hub_usage_counters (
    account_id,
    subscription_id,
    feature_key,
    period_start,
    period_end,
    used_units
  ) values (
    v_reservation.account_id,
    v_reservation.subscription_id,
    v_reservation.feature_key,
    v_reservation.period_start,
    v_reservation.period_end,
    0
  ) on conflict (subscription_id, feature_key, period_start) do nothing;

  select counter.used_units into v_used
  from public.hub_usage_counters as counter
  where counter.subscription_id = v_reservation.subscription_id
    and counter.feature_key = v_reservation.feature_key
    and counter.period_start = v_reservation.period_start
  for update;
  v_used := coalesce(v_used, 0);

  if v_limit is not null and v_used + v_reservation.units > v_limit then
    update private.hub_usage_reservations as reservation
    set status = 'RELEASED',
        release_reason = 'USAGE_LIMIT_REACHED',
        released_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
    where reservation.id = v_reservation.id;
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'USAGE_LIMIT_REACHED',
      'used', v_used,
      'limit', v_limit,
      'remaining', greatest(v_limit - v_used, 0),
      'periodEndsAt', v_reservation.period_end,
      'productFamily', 'HUB_CORE'
    );
  end if;

  insert into public.hub_usage_events (
    account_id,
    subscription_id,
    user_id,
    feature_key,
    units,
    request_key,
    metadata
  ) values (
    v_reservation.account_id,
    v_reservation.subscription_id,
    v_user_id,
    v_reservation.feature_key,
    v_reservation.units,
    v_reservation.request_key,
    v_reservation.metadata
      || pg_catalog.jsonb_build_object('reservationId', v_reservation.id)
  ) returning id into v_event_id;

  update public.hub_usage_counters as counter
  set used_units = counter.used_units + v_reservation.units,
      updated_at = pg_catalog.now()
  where counter.subscription_id = v_reservation.subscription_id
    and counter.feature_key = v_reservation.feature_key
    and counter.period_start = v_reservation.period_start
  returning counter.used_units into v_used;

  update private.hub_usage_reservations as reservation
  set status = 'COMMITTED',
      committed_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where reservation.id = v_reservation.id;

  select coalesce(pg_catalog.sum(reservation.units), 0)::integer
  into v_reserved
  from private.hub_usage_reservations as reservation
  where reservation.subscription_id = v_reservation.subscription_id
    and reservation.feature_key = v_reservation.feature_key
    and reservation.period_start = v_reservation.period_start
    and reservation.period_end = v_reservation.period_end
    and reservation.status = 'RESERVED';

  return pg_catalog.jsonb_build_object(
    'allowed', true,
    'idempotent', false,
    'accountId', v_reservation.account_id,
    'subscriptionId', v_reservation.subscription_id,
    'reservationId', v_reservation.id,
    'usageEventId', v_event_id,
    'productFamily', 'HUB_CORE',
    'used', v_used,
    'reserved', v_reserved,
    'limit', v_limit,
    'remaining', case when v_limit is null then null
      else greatest(v_limit - v_used - v_reserved, 0)
    end,
    'periodEndsAt', v_reservation.period_end
  );
end;
$$;


--
-- Name: hub_consume_feature_internal(text, integer, uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_consume_feature_internal(p_feature_key text, p_units integer DEFAULT 1, p_request_key uuid DEFAULT NULL::uuid, p_account_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_account_id uuid;
  v_subscription public.hub_subscriptions%rowtype;
  v_feature_key text := nullif(pg_catalog.btrim(p_feature_key), '');
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_limit integer;
  v_reset text;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_used integer := 0;
  v_reserved integer := 0;
  v_existing_event bigint;
begin
  if v_user_id is null then
    raise exception 'authentication_required' using errcode = 'P0001';
  end if;
  if v_feature_key is null
     or pg_catalog.char_length(v_feature_key) < 3
     or p_units is null
     or p_units < 0
     or p_units > 1000 then
    raise exception 'invalid_usage_request' using errcode = '22023';
  end if;
  if v_feature_key in (
    'educator_ai.generate',
    'wolfie.turn',
    'library.preview',
    'library.full_access'
  ) and p_units <> 1 then
    raise exception 'invalid_usage_request' using errcode = '22023';
  end if;
  if pg_catalog.jsonb_typeof(v_metadata) <> 'object'
     or pg_catalog.pg_column_size(v_metadata) > 4096 then
    raise exception 'invalid_usage_metadata' using errcode = '22023';
  end if;
  if not private.hub_is_enabled() then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'HUB_DISABLED',
      'productFamily', 'HUB_CORE'
    );
  end if;
  if not private.hub_profile_is_active(v_user_id) then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'PROFILE_INACTIVE',
      'productFamily', 'HUB_CORE'
    );
  end if;
  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_user_id
      and profile.tenant_id = 'wolfie-direct'
  ) then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'PRODUCT_SCOPE_FORBIDDEN',
      'productFamily', 'HUB_CORE'
    );
  end if;

  select membership.account_id into v_account_id
  from public.hub_memberships as membership
  join public.hub_accounts as account
    on account.id = membership.account_id
   and account.status = 'ACTIVE'
  where membership.user_id = v_user_id
    and membership.status = 'ACTIVE'
    and (p_account_id is null or membership.account_id = p_account_id)
  order by
    (membership.membership_role = 'OWNER') desc,
    (membership.membership_role = 'ADMIN') desc,
    membership.created_at,
    membership.id
  limit 1;
  if v_account_id is null then
    if exists (
      select 1
      from public.hub_memberships as membership
      join public.hub_accounts as account
        on account.id = membership.account_id
      where membership.user_id = v_user_id
        and membership.status <> 'REMOVED'
        and (p_account_id is null or membership.account_id = p_account_id)
        and (
          membership.status <> 'ACTIVE'
          or account.status <> 'ACTIVE'
        )
    ) then
      return pg_catalog.jsonb_build_object(
        'allowed', false,
        'code', 'HUB_ACCOUNT_INACTIVE',
        'productFamily', 'HUB_CORE'
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'HUB_ACCOUNT_REQUIRED',
      'productFamily', 'HUB_CORE'
    );
  end if;

  select subscription.* into v_subscription
  from public.hub_subscriptions as subscription
  join public.hub_plans as plan
    on plan.id = subscription.plan_id
   and plan.product_family = 'HUB_CORE'
  where subscription.account_id = v_account_id
    and subscription.product_family = 'HUB_CORE'
    and (
      (
        subscription.status = 'TRIALING'
        and subscription.trial_ends_at > pg_catalog.now()
      )
      or (
        subscription.status = 'ACTIVE'
        and coalesce(
          subscription.current_period_ends_at,
          '-infinity'::timestamptz
        ) > pg_catalog.now()
      )
    )
  order by
    (subscription.status = 'ACTIVE') desc,
    subscription.created_at desc,
    subscription.id desc
  limit 1
  for update of subscription;
  if not found then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'SUBSCRIPTION_REQUIRED',
      'productFamily', 'HUB_CORE'
    );
  end if;

  select entitlement.limit_value, entitlement.reset_period
  into v_limit, v_reset
  from public.hub_plan_entitlements as entitlement
  where entitlement.plan_id = v_subscription.plan_id
    and entitlement.feature_key = v_feature_key;
  if not found or v_limit = 0 then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'FEATURE_NOT_INCLUDED',
      'productFamily', 'HUB_CORE'
    );
  end if;

  if p_request_key is not null then
    select usage_event.id into v_existing_event
    from public.hub_usage_events as usage_event
    where usage_event.subscription_id = v_subscription.id
      and usage_event.feature_key = v_feature_key
      and usage_event.request_key = p_request_key;
    if found then
      select coalesce(counter.used_units, 0) into v_used
      from public.hub_usage_counters as counter
      where counter.subscription_id = v_subscription.id
        and counter.feature_key = v_feature_key
        and pg_catalog.now() >= counter.period_start
        and pg_catalog.now() < counter.period_end
      order by counter.period_start desc
      limit 1;
      return pg_catalog.jsonb_build_object(
        'allowed', true,
        'idempotent', true,
        'subscriptionId', v_subscription.id,
        'productFamily', 'HUB_CORE',
        'used', coalesce(v_used, 0),
        'limit', v_limit,
        'remaining', case when v_limit is null then null
          else greatest(v_limit - coalesce(v_used, 0), 0)
        end
      );
    end if;
    if exists (
      select 1
      from private.hub_usage_reservations as reservation
      where reservation.subscription_id = v_subscription.id
        and reservation.feature_key = v_feature_key
        and reservation.request_key = p_request_key
    ) then
      return pg_catalog.jsonb_build_object(
        'allowed', false,
        'idempotent', true,
        'code', 'IDEMPOTENCY_KEY_REUSED',
        'subscriptionId', v_subscription.id,
        'productFamily', 'HUB_CORE'
      );
    end if;
  end if;

  if v_reset = 'DAY' then
    v_period_start := pg_catalog.date_trunc('day', pg_catalog.now());
    v_period_end := v_period_start + interval '1 day';
  elsif v_reset = 'SUBSCRIPTION' then
    v_period_start := coalesce(
      v_subscription.trial_starts_at,
      v_subscription.current_period_starts_at,
      v_subscription.created_at
    );
    v_period_end := coalesce(
      v_subscription.trial_ends_at,
      v_subscription.current_period_ends_at,
      'infinity'::timestamptz
    );
  else
    v_period_start := pg_catalog.date_trunc('month', pg_catalog.now());
    v_period_end := v_period_start + interval '1 month';
  end if;

  update private.hub_usage_reservations as expired_reservation
  set status = 'RELEASED',
      release_reason = 'LEASE_EXPIRED',
      released_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where expired_reservation.subscription_id = v_subscription.id
    and expired_reservation.feature_key = v_feature_key
    and expired_reservation.status = 'RESERVED'
    and expired_reservation.lease_expires_at <= pg_catalog.now();

  if p_units > 0 then
    insert into public.hub_usage_counters (
      account_id,
      subscription_id,
      feature_key,
      period_start,
      period_end,
      used_units
    ) values (
      v_account_id,
      v_subscription.id,
      v_feature_key,
      v_period_start,
      v_period_end,
      0
    ) on conflict (subscription_id, feature_key, period_start) do nothing;

    select counter.used_units into v_used
    from public.hub_usage_counters as counter
    where counter.subscription_id = v_subscription.id
      and counter.feature_key = v_feature_key
      and counter.period_start = v_period_start
    for update;
  else
    select counter.used_units into v_used
    from public.hub_usage_counters as counter
    where counter.subscription_id = v_subscription.id
      and counter.feature_key = v_feature_key
      and counter.period_start = v_period_start;
  end if;
  v_used := coalesce(v_used, 0);

  select coalesce(pg_catalog.sum(reservation.units), 0)::integer
  into v_reserved
  from private.hub_usage_reservations as reservation
  where reservation.subscription_id = v_subscription.id
    and reservation.feature_key = v_feature_key
    and reservation.period_start = v_period_start
    and reservation.period_end = v_period_end
    and reservation.status = 'RESERVED';

  if v_limit is not null and v_used + v_reserved + p_units > v_limit then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'USAGE_LIMIT_REACHED',
      'subscriptionId', v_subscription.id,
      'productFamily', 'HUB_CORE',
      'used', v_used,
      'reserved', v_reserved,
      'limit', v_limit,
      'remaining', greatest(v_limit - v_used - v_reserved, 0),
      'periodEndsAt', v_period_end
    );
  end if;

  if p_units > 0 then
    insert into public.hub_usage_events (
      account_id,
      subscription_id,
      user_id,
      feature_key,
      units,
      request_key,
      metadata
    ) values (
      v_account_id,
      v_subscription.id,
      v_user_id,
      v_feature_key,
      p_units,
      p_request_key,
      v_metadata
    );

    update public.hub_usage_counters as counter
    set used_units = counter.used_units + p_units,
        updated_at = pg_catalog.now()
    where counter.subscription_id = v_subscription.id
      and counter.feature_key = v_feature_key
      and counter.period_start = v_period_start
    returning counter.used_units into v_used;
  end if;

  return pg_catalog.jsonb_build_object(
    'allowed', true,
    'idempotent', false,
    'accountId', v_account_id,
    'subscriptionId', v_subscription.id,
    'productFamily', 'HUB_CORE',
    'used', v_used,
    'reserved', v_reserved,
    'limit', v_limit,
    'remaining', case when v_limit is null then null
      else greatest(v_limit - v_used - v_reserved, 0)
    end,
    'periodEndsAt', v_period_end
  );
end;
$$;


--
-- Name: hub_content_has_isolated_asset_pair(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_content_has_isolated_asset_pair(item_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.hub_content_assets as full_asset
    join public.hub_content_assets as preview
      on preview.content_id = full_asset.content_id
     and preview.asset_kind = 'PREVIEW'
    where full_asset.content_id = item_id
      and full_asset.asset_kind = 'FULL'
      and (
        preview.bucket_id <> full_asset.bucket_id
        or preview.object_path <> full_asset.object_path
      )
      and (
        preview.external_url is null
        or full_asset.external_url is null
        or preview.external_url <> full_asset.external_url
      )
  );
$$;


--
-- Name: hub_educator_interests_valid(text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_educator_interests_valid(p_interests text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select p_interests is not null
    and pg_catalog.cardinality(p_interests) <= 12
    and pg_catalog.pg_column_size(p_interests) <= 2048
    and not exists (
      select 1
      from pg_catalog.unnest(p_interests) as interest(value)
      where interest.value is null
        or pg_catalog.char_length(pg_catalog.btrim(interest.value)) < 1
        or pg_catalog.char_length(pg_catalog.btrim(interest.value)) > 80
    );
$$;


--
-- Name: hub_enforce_account_billing_transition_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_enforce_account_billing_transition_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid := case
    when tg_op = 'DELETE' then old.id
    else new.id
  end;
begin
  if tg_op = 'UPDATE' then
    if new.status = old.status then
      return new;
    end if;
  end if;

  if exists (
    select 1
    from public.hub_subscriptions as subscription
    join public.hub_plans as plan
      on plan.id = subscription.plan_id
    where subscription.account_id = v_account_id
      and subscription.status in (
        'TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE'
      )
      and (
        plan.code <> 'DISCOVERY'
        or subscription.provider is not null
        or subscription.provider_subscription_id is not null
        or subscription.provider_payment_id is not null
      )
  ) or exists (
    select 1
    from public.hub_checkout_sessions as checkout
    where checkout.account_id = v_account_id
      and checkout.status in ('CREATED', 'PENDING', 'OVERDUE', 'PAID')
  ) then
    raise exception 'hub_live_billing_cancellation_required'
      using errcode = '55000';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: hub_enforce_active_subscription_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_enforce_active_subscription_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_status text;
begin
  if new.status <> 'ACTIVE' then
    return new;
  end if;

  select account.status into v_account_status
  from public.hub_accounts as account
  where account.id = new.account_id;

  if v_account_status is distinct from 'ACTIVE' then
    raise exception 'hub_account_inactive' using errcode = '42501';
  end if;
  if new.product_family = 'HUB_CORE'
     and not private.hub_is_enabled() then
    raise exception 'hub_disabled' using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: hub_enforce_catalog_asset_pair(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_enforce_catalog_asset_pair() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  item_id uuid;
begin
  if tg_table_name = 'hub_content_items' then
    item_id := new.id;
  else
    item_id := coalesce(new.content_id, old.content_id);
  end if;

  if exists (
    select 1
    from public.hub_content_items as item
    where item.id = item_id
      and item.is_active is true
      and item.preview_enabled is true
      and item.published_at is not null
  ) and not private.hub_content_has_isolated_asset_pair(item_id) then
    raise exception 'active_hub_content_requires_isolated_full_and_preview_assets'
      using errcode = '23514';
  end if;

  return null;
end;
$$;


--
-- Name: hub_enforce_distinct_content_assets(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_enforce_distinct_content_assets() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.asset_kind not in ('PREVIEW', 'FULL') then
    return new;
  end if;

  if exists (
    select 1
    from public.hub_content_assets as sibling
    where sibling.content_id = new.content_id
      and sibling.asset_kind in ('PREVIEW', 'FULL')
      and sibling.asset_kind <> new.asset_kind
      and sibling.id <> new.id
      and (
        (
          sibling.bucket_id = new.bucket_id
          and sibling.object_path = new.object_path
        )
        or (
          sibling.external_url is not null
          and sibling.external_url = new.external_url
        )
      )
  ) then
    raise exception 'hub_preview_must_be_distinct_from_full_asset'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


--
-- Name: hub_enforce_membership_subject_role(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_enforce_membership_subject_role() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_account_audience text;
begin
  if new.membership_role in ('OWNER', 'ADMIN') then
    select account.audience
    into v_account_audience
    from public.hub_accounts as account
    where account.id = new.account_id;

    new.subject_role := case
      when v_account_audience = 'LEARNER' then 'LEARNER'
      else 'EDUCATOR'
    end;
  elsif new.membership_role = 'MEMBER' then
    new.subject_role := coalesce(new.subject_role, 'LEARNER');
    if new.subject_role not in ('LEARNER', 'EDUCATOR') then
      raise exception 'invalid_hub_subject_role' using errcode = '22023';
    end if;
  else
    raise exception 'invalid_hub_membership_role' using errcode = '22023';
  end if;

  return new;
end;
$$;


--
-- Name: hub_finalize_account_status_internal(uuid, text, text[], uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_finalize_account_status_internal(p_account_id uuid, p_target_status text, p_cancelled_provider_subscription_ids text[] DEFAULT '{}'::text[], p_actor_user_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'ADMIN_REQUEST'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account public.hub_accounts%rowtype;
  v_target_status text := pg_catalog.upper(
    coalesce(nullif(pg_catalog.btrim(p_target_status), ''), '')
  );
  v_reason text := pg_catalog.left(
    coalesce(nullif(pg_catalog.btrim(p_reason), ''), 'ADMIN_REQUEST'),
    200
  );
  v_subscription record;
  v_checkout record;
  v_idempotent boolean := false;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if p_account_id is null
     or v_target_status not in ('SUSPENDED', 'CLOSED') then
    raise exception 'invalid_hub_account_status_change' using errcode = '22023';
  end if;
  if p_actor_user_id is not null and not exists (
    select 1
    from public.profiles as profile
    where profile.id = p_actor_user_id
      and profile.role = 'SUPER_ADMIN'
  ) then
    raise exception 'hub_status_actor_forbidden' using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-account-status:' || p_account_id::text,
      0
    )
  );

  select account.* into v_account
  from public.hub_accounts as account
  where account.id = p_account_id
  for update;
  if not found then
    raise exception 'hub_account_not_found' using errcode = 'P0002';
  end if;
  v_idempotent := v_account.status = v_target_status;

  for v_subscription in
    select
      subscription.id,
      subscription.provider,
      subscription.provider_subscription_id,
      plan.code as plan_code
    from public.hub_subscriptions as subscription
    join public.hub_plans as plan
      on plan.id = subscription.plan_id
    where subscription.account_id = v_account.id
      and subscription.status in (
        'TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE'
      )
    order by subscription.created_at, subscription.id
    for update of subscription
  loop
    if v_subscription.provider is null
       and v_subscription.provider_subscription_id is null
       and v_subscription.plan_code = 'DISCOVERY' then
      continue;
    end if;
    if v_subscription.provider is distinct from 'ASAAS'
       or nullif(v_subscription.provider_subscription_id, '') is null then
      raise exception 'hub_subscription_reconciliation_required'
        using errcode = '55000';
    end if;
    if not (
      v_subscription.provider_subscription_id = any(
        coalesce(p_cancelled_provider_subscription_ids, '{}'::text[])
      )
    ) then
      raise exception 'hub_provider_cancellation_not_confirmed'
        using errcode = '55000';
    end if;
  end loop;

  for v_checkout in
    select
      checkout.id,
      checkout.status,
      checkout.asaas_subscription_id,
      checkout.asaas_payment_id
    from public.hub_checkout_sessions as checkout
    where checkout.account_id = v_account.id
      and checkout.status in ('CREATED', 'PENDING', 'OVERDUE', 'PAID')
    order by checkout.created_at, checkout.id
    for update of checkout
  loop
    if nullif(v_checkout.asaas_subscription_id, '') is null then
      if v_checkout.status <> 'CREATED'
         or nullif(v_checkout.asaas_payment_id, '') is not null then
        raise exception 'hub_checkout_reconciliation_required'
          using errcode = '55000';
      end if;
      continue;
    end if;
    if not (
      v_checkout.asaas_subscription_id = any(
        coalesce(p_cancelled_provider_subscription_ids, '{}'::text[])
      )
    ) then
      raise exception 'hub_provider_cancellation_not_confirmed'
        using errcode = '55000';
    end if;
  end loop;

  update public.hub_subscriptions as subscription
  set status = 'CANCELLED',
      cancelled_at = coalesce(subscription.cancelled_at, pg_catalog.now()),
      current_period_ends_at = least(
        coalesce(subscription.current_period_ends_at, pg_catalog.now()),
        pg_catalog.now()
      ),
      metadata = coalesce(subscription.metadata, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'accountStatusChange', v_target_status,
          'accountStatusReason', v_reason,
          'accountStatusChangedAt', pg_catalog.now()
        ),
      updated_at = pg_catalog.now()
  where subscription.account_id = v_account.id
    and subscription.status in (
      'TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE'
    );

  update public.hub_checkout_sessions as checkout
  set status = 'CANCELLED',
      metadata = coalesce(checkout.metadata, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'accountStatusChange', v_target_status,
          'accountStatusReason', v_reason,
          'providerCancellationConfirmedAt', pg_catalog.now()
        ),
      updated_at = pg_catalog.now()
  where checkout.account_id = v_account.id
    and checkout.status in ('CREATED', 'PENDING', 'OVERDUE', 'PAID');

  update public.hub_accounts as account
  set status = v_target_status,
      updated_at = pg_catalog.now()
  where account.id = v_account.id
  returning account.* into v_account;

  insert into public.hub_conversion_events (
    account_id,
    user_id,
    event_name,
    source,
    metadata
  ) values (
    v_account.id,
    p_actor_user_id,
    'hub_account_status_changed',
    'hub_billing_admin',
    pg_catalog.jsonb_build_object(
      'status', v_target_status,
      'reason', v_reason,
      'providerSubscriptionsCancelled',
        coalesce(p_cancelled_provider_subscription_ids, '{}'::text[])
    )
  );

  return pg_catalog.jsonb_build_object(
    'accountId', v_account.id,
    'status', v_account.status,
    'idempotent', v_idempotent
  );
end;
$$;


--
-- Name: hub_guard_core_checkout_creation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_guard_core_checkout_creation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.product_family <> 'HUB_CORE'
     or new.status not in ('CREATED', 'PENDING') then
    return new;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-core-cancellation:' || new.account_id::text,
      0
    )
  );

  if not private.hub_catalog_is_ready() then
    raise exception 'hub_catalog_not_ready' using errcode = '55000';
  end if;

  if exists (
    select 1
    from public.hub_subscriptions as subscription
    where subscription.account_id = new.account_id
      and subscription.product_family = 'HUB_CORE'
      and subscription.status = 'ACTIVE'
      and subscription.current_period_ends_at > pg_catalog.now()
      and (
        (
          pg_catalog.jsonb_typeof(
            subscription.metadata -> 'cancelAtPeriodEnd'
          ) = 'boolean'
          and (subscription.metadata ->> 'cancelAtPeriodEnd')::boolean
        )
        or (
          pg_catalog.jsonb_typeof(
            subscription.metadata -> 'cancellationInProgress'
          ) = 'boolean'
          and (subscription.metadata ->> 'cancellationInProgress')::boolean
        )
      )
  ) then
    raise exception 'hub_subscription_cancellation_pending'
      using errcode = '55000';
  end if;

  return new;
end;
$$;


--
-- Name: hub_guard_core_subscription_activation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_guard_core_subscription_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_is_new_live_period boolean := false;
begin
  if new.product_family <> 'HUB_CORE'
     or new.status not in ('TRIALING', 'ACTIVE') then
    return new;
  end if;

  v_is_new_live_period := tg_op = 'INSERT';
  if tg_op = 'UPDATE' then
    v_is_new_live_period := old.status not in ('TRIALING', 'ACTIVE')
      or old.product_family is distinct from new.product_family;
  end if;

  if v_is_new_live_period and not private.hub_catalog_is_ready() then
    raise exception 'hub_catalog_not_ready' using errcode = '55000';
  end if;

  return new;
end;
$$;


--
-- Name: hub_guard_discovery_catalog_ready(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_guard_discovery_catalog_ready() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_plan_code text;
begin
  if new.product_family is distinct from 'HUB_CORE' then
    return new;
  end if;

  select plan.code into v_plan_code
  from public.hub_plans as plan
  where plan.id = new.plan_id;

  if v_plan_code = 'DISCOVERY'
     and not private.hub_catalog_is_ready() then
    raise exception 'hub_catalog_not_ready' using errcode = '55000';
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION hub_guard_discovery_catalog_ready(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.hub_guard_discovery_catalog_ready() IS 'Prevents a free Hub trial from opening into an empty or unlicensed catalog.';


--
-- Name: hub_guard_educator_learner_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_guard_educator_learner_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.account_id is distinct from old.account_id
     or new.created_by is distinct from old.created_by then
    raise exception 'hub_educator_learner_scope_is_immutable'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: hub_guard_material_publication_consent(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_guard_material_publication_consent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  actor_id uuid := (select auth.uid());
  actor_role text;
  actor_tenant_id text;
  consent_changed boolean;
  authorization_changed boolean;
  source_changed boolean;
  storage_object_changed boolean;
  preview_source_changed boolean;
begin
  consent_changed := tg_op = 'INSERT'
    or new.hub_catalog_opt_in is distinct from old.hub_catalog_opt_in
    or new.hub_rights_basis is distinct from old.hub_rights_basis
    or new.hub_rights_declaration is distinct from old.hub_rights_declaration
    or new.hub_preview_source_path is distinct from old.hub_preview_source_path;

  authorization_changed := consent_changed
    or new.hub_commercial_approved
       is distinct from old.hub_commercial_approved
    or new.hub_rights_verified_by is distinct from old.hub_rights_verified_by
    or new.hub_rights_verified_at is distinct from old.hub_rights_verified_at;

  source_changed := tg_op = 'UPDATE' and (
    new.storage_object_path is distinct from old.storage_object_path
    or new.file_url is distinct from old.file_url
    or new.type is distinct from old.type
    or (
      old.approval_status = 'APPROVED'
      and new.approval_status <> 'APPROVED'
    )
  );

  storage_object_changed := new.storage_object_path is not null and (
    tg_op = 'INSERT'
    or new.storage_object_path is distinct from old.storage_object_path
  );
  preview_source_changed := new.hub_preview_source_path is not null and (
    tg_op = 'INSERT'
    or new.hub_preview_source_path is distinct from old.hub_preview_source_path
  );

  -- SQL migrations and service-role jobs may curate directly, but still have to
  -- satisfy the table integrity constraint. Browser callers always have uid().
  if actor_id is null then
    return new;
  end if;

  actor_role := public._my_role();
  actor_tenant_id := public._my_tenant_id();

  if storage_object_changed and not private.hub_actor_owns_namespaced_material_object(
    new.storage_object_path,
    actor_id,
    actor_tenant_id
  ) then
    raise exception 'material_storage_object_must_be_owned_and_namespaced'
      using errcode = '42501';
  end if;

  if preview_source_changed and not private.hub_actor_owns_namespaced_material_object(
    new.hub_preview_source_path,
    actor_id,
    actor_tenant_id
  ) then
    raise exception 'material_preview_object_must_be_owned_and_namespaced'
      using errcode = '42501';
  end if;

  if source_changed and old.hub_catalog_opt_in is true
     and not authorization_changed then
    new.hub_catalog_opt_in := false;
    new.hub_commercial_approved := false;
    new.hub_rights_verified_by := null;
    new.hub_rights_verified_at := null;
    new.hub_publication_revoked_by := actor_id;
    new.hub_publication_revoked_at := now();
    return new;
  end if;

  if not authorization_changed then
    return new;
  end if;

  if actor_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    if new.hub_catalog_opt_in is true
       or new.hub_commercial_approved is true
       or new.hub_rights_basis is not null
       or new.hub_rights_declaration is not null
       or new.hub_preview_source_path is not null then
      raise exception 'hub_publication_requires_school_admin'
        using errcode = '42501';
    end if;
    return new;
  end if;

  if actor_role <> 'SUPER_ADMIN'
     and new.tenant_id is distinct from actor_tenant_id then
    raise exception 'hub_publication_cross_tenant_denied'
      using errcode = '42501';
  end if;

  if new.hub_catalog_opt_in is true then
    if new.approval_status <> 'APPROVED'
       or upper(coalesce(new.type, '')) = 'LINK'
       or new.storage_object_path is null
       or new.hub_preview_source_path is null
       or new.storage_object_path = new.hub_preview_source_path
       or not private.hub_material_object_has_provenance(
         new.storage_object_path,
         new.tenant_id,
         new.uploaded_by
       )
       or not private.hub_material_object_has_provenance(
         new.hub_preview_source_path,
         new.tenant_id,
         null
       )
       or new.hub_rights_basis not in (
         'OWNED', 'LICENSED', 'PUBLIC_DOMAIN'
       )
       or char_length(btrim(coalesce(new.hub_rights_declaration, '')))
          not between 20 and 2000 then
      raise exception 'hub_publication_requirements_incomplete'
        using errcode = '23514';
    end if;

    if consent_changed then
      new.hub_publication_requested_by := actor_id;
      new.hub_publication_requested_at := now();
      new.hub_commercial_approved := false;
      new.hub_rights_verified_by := null;
      new.hub_rights_verified_at := null;
    end if;
    new.hub_publication_revoked_by := null;
    new.hub_publication_revoked_at := null;

    if new.hub_commercial_approved is true then
      if actor_role <> 'SUPER_ADMIN' then
        raise exception 'hub_commercial_approval_requires_super_admin'
          using errcode = '42501';
      end if;
      if new.hub_publication_requested_by = actor_id then
        raise exception 'hub_commercial_approval_requires_second_actor'
          using errcode = '42501';
      end if;
      new.hub_rights_verified_by := actor_id;
      new.hub_rights_verified_at := now();
    elsif actor_role <> 'SUPER_ADMIN'
       and (
         new.hub_rights_verified_by is not null
         or new.hub_rights_verified_at is not null
       ) then
      raise exception 'hub_rights_verification_requires_super_admin'
        using errcode = '42501';
    else
      new.hub_rights_verified_by := null;
      new.hub_rights_verified_at := null;
    end if;
  elsif tg_op = 'UPDATE' and old.hub_catalog_opt_in is true then
    new.hub_commercial_approved := false;
    new.hub_rights_verified_by := null;
    new.hub_rights_verified_at := null;
    new.hub_publication_revoked_by := actor_id;
    new.hub_publication_revoked_at := now();
  end if;

  return new;
end;
$$;


--
-- Name: hub_guard_material_sync_fields(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_guard_material_sync_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if (select auth.uid()) is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    new.hub_object_path := null;
    new.hub_preview_object_path := null;
    new.hub_sync_error := null;
    new.hub_synced_at := null;
    return new;
  end if;

  if new.hub_object_path is distinct from old.hub_object_path
     or new.hub_preview_object_path is distinct from old.hub_preview_object_path
     or new.hub_sync_status is distinct from old.hub_sync_status
     or new.hub_sync_error is distinct from old.hub_sync_error
     or new.hub_synced_at is distinct from old.hub_synced_at then
    raise exception 'hub_sync_fields_are_service_managed'
      using errcode = '42501';
  end if;

  return new;
end;
$$;


--
-- Name: hub_guard_member_profile_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_guard_member_profile_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.account_id is distinct from old.account_id
     or new.user_id is distinct from old.user_id then
    raise exception 'hub_member_profile_scope_is_immutable'
      using errcode = '42501';
  end if;
  return new;
end;
$$;


--
-- Name: hub_has_account_access(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_has_account_access(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.hub_is_enabled()
    and private.hub_profile_is_active((select auth.uid()))
    and exists (
      select 1
      from public.hub_memberships as membership
      join public.hub_accounts as account
        on account.id = membership.account_id
       and account.status = 'ACTIVE'
      where membership.account_id = p_account_id
        and membership.user_id = (select auth.uid())
        and membership.status = 'ACTIVE'
    );
$$;


--
-- Name: hub_has_educator_planner_access(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_has_educator_planner_access(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.hub_user_has_educator_planner_access(
    p_account_id,
    (select auth.uid())
  );
$$;


--
-- Name: hub_is_account_manager(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_is_account_manager(p_account_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.hub_is_enabled()
    and private.hub_profile_is_active((select auth.uid()))
    and exists (
      select 1
      from public.hub_memberships as membership
      join public.hub_accounts as account
        on account.id = membership.account_id
       and account.status = 'ACTIVE'
      where membership.account_id = p_account_id
        and membership.user_id = (select auth.uid())
        and membership.status = 'ACTIVE'
        and membership.membership_role in ('OWNER', 'ADMIN')
    );
$$;


--
-- Name: hub_is_enabled(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_is_enabled() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when pg_catalog.jsonb_typeof(settings.metadata -> 'hubEnabled') = 'boolean'
      then (settings.metadata ->> 'hubEnabled')::boolean
    else true
  end
  from public.hub_settings as settings
  where settings.settings_key = 'default'
  union all
  select true
  where not exists (
    select 1
    from public.hub_settings as settings
    where settings.settings_key = 'default'
  )
  limit 1;
$$;


--
-- Name: hub_is_internal_manager(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_is_internal_manager() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
    or (
      private.hub_profile_is_active((select auth.uid()))
      and exists (
      select 1
      from public.profiles as profile
      where profile.id = (select auth.uid())
        and profile.role = 'SUPER_ADMIN'
      )
    );
$$;


--
-- Name: hub_list_accounts_internal(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_list_accounts_internal() RETURNS TABLE(id uuid, name text, audience text, account_type text, status text, membership_role text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    account.id,
    account.name,
    account.audience,
    account.account_type,
    case
      when membership.status = 'ACTIVE' then account.status
      else 'SUSPENDED'
    end as status,
    membership.membership_role
  from public.hub_memberships as membership
  join public.hub_accounts as account
    on account.id = membership.account_id
  where membership.user_id = auth.uid()
    and membership.status <> 'REMOVED'
    and private.hub_is_enabled()
    and private.hub_profile_is_active(auth.uid())
    and not exists (
      select 1
      from public.profiles as profile
      where profile.id = auth.uid()
        and profile.tenant_id = 'wolfie-direct'
    )
  order by
    (account.status = 'ACTIVE' and membership.status = 'ACTIVE') desc,
    (membership.membership_role = 'OWNER') desc,
    (membership.membership_role = 'ADMIN') desc,
    account.created_at,
    account.id;
$$;


--
-- Name: hub_lock_provider_event_writer(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_lock_provider_event_writer(p_checkout_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
  v_locked_account_id uuid;
begin
  -- Production callers must carry the service-role JWT. The postgres session
  -- exception is limited to migration owners/rollback-only SQL verification;
  -- the public wrappers are additionally EXECUTE-revoked from clients.
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role'
     and session_user not in ('postgres', 'supabase_admin') then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if p_checkout_id is null then
    raise exception 'invalid_hub_checkout' using errcode = '22023';
  end if;
  select checkout.account_id into v_account_id
  from public.hub_checkout_sessions checkout
  where checkout.id = p_checkout_id;
  if not found then
    raise exception 'hub_checkout_not_found' using errcode = 'P0002';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-provider-operation:' || v_account_id::text,
      0
    )
  );
  -- Lock only after the account advisory, in the same account->checkout order
  -- used by begin, mark and finalization.
  perform account.id
  from public.hub_accounts account
  where account.id = v_account_id
  for update;
  if not found then
    raise exception 'hub_provider_operation_scope_changed'
      using errcode = '55000';
  end if;
  select checkout.account_id into v_locked_account_id
  from public.hub_checkout_sessions checkout
  where checkout.id = p_checkout_id
  for update;
  if not found or v_locked_account_id is distinct from v_account_id then
    raise exception 'hub_provider_operation_scope_changed'
      using errcode = '55000';
  end if;
  if exists (
    select 1
    from private.hub_provider_operations operation
    where operation.account_id = v_account_id
      and operation.status in ('READY', 'IN_PROGRESS', 'BLOCKED')
  ) then
    raise exception 'hub_provider_operation_in_progress'
      using errcode = '55000';
  end if;
  return v_account_id;
end;
$$;


--
-- Name: hub_mark_checkout_overdue_provider_apply(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_mark_checkout_overdue_provider_apply(p_checkout_id uuid, p_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_checkout public.hub_checkout_sessions%rowtype;
  v_subscription public.hub_subscriptions%rowtype;
  v_payment public.hub_subscription_payments%rowtype;
  v_payment_id text := nullif(pg_catalog.btrim(p_payment_id), '');
  v_new_event boolean := false;
begin
  if p_checkout_id is null
     or v_payment_id is null
     or pg_catalog.char_length(v_payment_id) > 200 then
    raise exception 'invalid_hub_overdue_payment' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('hub-payment:ASAAS:' || v_payment_id, 0)
  );

  select * into v_checkout
  from public.hub_checkout_sessions
  where id = p_checkout_id
  for update;
  if not found then
    raise exception 'hub_checkout_not_found' using errcode = 'P0002';
  end if;
  if v_checkout.status in ('CANCELLED', 'REVERSED') then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'ignored', true,
      'status', v_checkout.status
    );
  end if;

  select * into v_payment
  from public.hub_subscription_payments
  where provider = 'ASAAS'
    and provider_payment_id = v_payment_id
  for update;
  if found and v_payment.checkout_id <> v_checkout.id then
    raise exception 'hub_checkout_payment_mismatch' using errcode = '42501';
  end if;
  if found and v_payment.status in ('APPLIED', 'REVERSED') then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'ignored', true,
      'paymentStatus', v_payment.status,
      'subscriptionId', v_payment.subscription_id
    );
  end if;

  if v_payment.subscription_id is not null then
    select * into v_subscription
    from public.hub_subscriptions
    where id = v_payment.subscription_id
      and account_id = v_checkout.account_id
      and product_family = v_checkout.product_family
    for update;
  else
    select * into v_subscription
    from public.hub_subscriptions as subscription
    where subscription.account_id = v_checkout.account_id
      and subscription.product_family = v_checkout.product_family
      and subscription.provider = 'ASAAS'
      and (
        (
          v_checkout.asaas_subscription_id is not null
          and subscription.provider_subscription_id =
            v_checkout.asaas_subscription_id
        )
        or subscription.metadata ->> 'checkoutId' = v_checkout.id::text
      )
    order by
      (subscription.provider_subscription_id =
        v_checkout.asaas_subscription_id) desc,
      subscription.created_at desc,
      subscription.id desc
    limit 1
    for update;
  end if;

  -- Before the first settlement, the provider payment must be the checkout's
  -- own payment. Once a provider subscription exists, a different payment id
  -- is a normal recurring installment and is linked through that subscription.
  if v_subscription.id is null
     and v_checkout.asaas_payment_id is distinct from v_payment_id then
    raise exception 'hub_checkout_payment_mismatch' using errcode = '42501';
  end if;

  if v_payment.id is null then
    insert into public.hub_subscription_payments (
      provider, provider_payment_id, checkout_id, subscription_id,
      account_id, product_family, status, metadata
    ) values (
      'ASAAS', v_payment_id, v_checkout.id, v_subscription.id,
      v_checkout.account_id, v_checkout.product_family, 'OVERDUE',
      '{"source":"asaas_webhook"}'::jsonb
    )
    returning * into v_payment;
    v_new_event := true;
  end if;

  update public.hub_checkout_sessions
  set status = 'OVERDUE',
      asaas_payment_id = coalesce(asaas_payment_id, v_payment_id),
      metadata = metadata || pg_catalog.jsonb_build_object(
        'overduePaymentId', v_payment_id,
        'overdueAt', pg_catalog.now()
      ),
      updated_at = pg_catalog.now()
  where id = v_checkout.id;

  if v_subscription.id is not null
     and v_subscription.status in (
       'TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE'
     ) then
    update public.hub_subscriptions
    set status = 'PAST_DUE',
        metadata = metadata || pg_catalog.jsonb_build_object(
          'overduePaymentId', v_payment_id,
          'overdueAt', pg_catalog.now()
        ),
        updated_at = pg_catalog.now()
    where id = v_subscription.id
    returning * into v_subscription;
  end if;

  if v_checkout.product_family = 'WOLFIE_STANDALONE'
     and v_subscription.id is not null then
    perform pg_catalog.set_config('app.enrollment_claim', '1', true);
    update public.profiles
    set status_financial = 'SUSPENDED'
    where id = v_checkout.requested_by
      and tenant_id = 'wolfie-direct'
      and role = 'STUDENT';
  end if;

  if v_new_event then
    insert into public.hub_conversion_events(
      account_id, user_id, event_name, source, metadata
    ) values (
      v_checkout.account_id,
      v_checkout.requested_by,
      case when v_checkout.product_family = 'WOLFIE_STANDALONE'
        then 'wolfie_subscription_overdue'
        else 'hub_subscription_overdue'
      end,
      'asaas_webhook',
      pg_catalog.jsonb_build_object(
        'checkoutId', v_checkout.id,
        'paymentId', v_payment_id,
        'subscriptionId', v_subscription.id
      )
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'idempotent', not v_new_event,
    'checkoutId', v_checkout.id,
    'subscriptionId', v_subscription.id,
    'status', case when v_subscription.id is null
      then 'OVERDUE'
      else v_subscription.status
    end
  );
end;
$$;


--
-- Name: FUNCTION hub_mark_checkout_overdue_provider_apply(p_checkout_id uuid, p_payment_id text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.hub_mark_checkout_overdue_provider_apply(p_checkout_id uuid, p_payment_id text) IS 'Marks one provider payment and its subscription past due without revoking membership.';


--
-- Name: hub_mark_pedagogical_material_for_sync(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_mark_pedagogical_material_for_sync() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.hub_catalog_opt_in is false
     or new.approval_status <> 'APPROVED' then
    new.hub_sync_status := 'CONSENT_REQUIRED';
    new.hub_sync_error := null;
    new.hub_synced_at := null;
    return new;
  end if;

  if new.hub_commercial_approved is false
     or new.hub_rights_verified_by is null
     or new.hub_rights_verified_at is null then
    new.hub_sync_status := 'RIGHTS_REVIEW_REQUIRED';
    new.hub_sync_error := null;
    new.hub_synced_at := null;
    return new;
  end if;

  if upper(coalesce(new.type, '')) = 'LINK'
     or new.storage_object_path is null
     or new.hub_preview_source_path is null
     or new.storage_object_path = new.hub_preview_source_path then
    new.hub_sync_status := 'NOT_APPLICABLE';
    new.hub_sync_error := 'HUB_PUBLICATION_SOURCE_INVALID';
    new.hub_synced_at := null;
    return new;
  end if;

  if tg_op = 'INSERT'
     or new.file_url is distinct from old.file_url
     or new.storage_object_path is distinct from old.storage_object_path
     or new.hub_preview_source_path is distinct from old.hub_preview_source_path
     or new.approval_status is distinct from old.approval_status
     or new.type is distinct from old.type
     or new.hub_catalog_opt_in is distinct from old.hub_catalog_opt_in
     or new.hub_commercial_approved
        is distinct from old.hub_commercial_approved
     or new.hub_rights_basis is distinct from old.hub_rights_basis
     or new.hub_rights_declaration is distinct from old.hub_rights_declaration
     or new.hub_rights_verified_at is distinct from old.hub_rights_verified_at
     or new.title is distinct from old.title
     or new.level_tag is distinct from old.level_tag
     or new.category is distinct from old.category
     or new.niche is distinct from old.niche
     or new.collection_id is distinct from old.collection_id
     or new.part_number is distinct from old.part_number then
    if tg_op = 'INSERT'
       or new.storage_object_path is distinct from old.storage_object_path
       or new.file_url is distinct from old.file_url
       or new.type is distinct from old.type then
      new.hub_object_path := null;
    end if;
    if tg_op = 'INSERT'
       or new.hub_preview_source_path
          is distinct from old.hub_preview_source_path then
      new.hub_preview_object_path := null;
    end if;
    new.hub_sync_status := 'PENDING';
    new.hub_sync_error := null;
    new.hub_synced_at := null;
  end if;

  return new;
end;
$$;


--
-- Name: hub_material_object_has_provenance(text, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_material_object_has_provenance(object_name text, material_tenant_id text, legacy_owner_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select object_name is not null
    and material_tenant_id is not null
    and exists (
      select 1
      from storage.objects as object
      join public.profiles as owner_profile
        on owner_profile.id::text = object.owner_id
       and owner_profile.tenant_id = material_tenant_id
      where object.bucket_id = 'materials'
        and object.name = object_name
        and (
          (
            coalesce(cardinality(storage.foldername(object_name)), 0) = 0
            and legacy_owner_id is not null
            and object.owner_id = legacy_owner_id::text
            and storage.filename(object_name) ~
              '^[0-9]{10,20}[.](pdf|jpe?g|png|webp|mp4|mp3|wav)$'
          )
          or (
            cardinality(storage.foldername(object_name)) = 1
            and (storage.foldername(object_name))[1] = 'materials'
            and legacy_owner_id is not null
            and object.owner_id = legacy_owner_id::text
            and storage.filename(object_name) ~
              '^([0-9]{10,20}|[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12})[.](pdf|jpe?g|png|webp|mp4|mp3|wav)$'
          )
          or (
            cardinality(storage.foldername(object_name)) = 2
            and (storage.foldername(object_name))[1] = material_tenant_id
            and (storage.foldername(object_name))[2] = object.owner_id
            and storage.filename(object_name) ~
              '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.](pdf|jpe?g|png|webp|mp4|mp3|wav)$'
          )
        )
    );
$_$;


--
-- Name: hub_material_object_is_manageable(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_material_object_is_manageable(object_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (select auth.uid()) is not null
    and public._my_tenant_is_operational()
    and public._my_role() in (
      'TEACHER', 'SCHOOL_ADMIN', 'COORDINATOR', 'MANAGER', 'SUPER_ADMIN'
    )
    and exists (
      select 1
      from public.pedagogical_materials as material
      where material.tenant_id = public._my_tenant_id()
        and (
          (
            material.storage_object_path = object_name
            and private.hub_material_object_has_provenance(
              object_name,
              material.tenant_id,
              material.uploaded_by
            )
          )
          or (
            material.hub_preview_source_path = object_name
            and private.hub_material_object_has_provenance(
              object_name,
              material.tenant_id,
              null
            )
          )
        )
        and (
          material.uploaded_by = (select auth.uid())
          or public._my_role() in (
            'SCHOOL_ADMIN', 'COORDINATOR', 'MANAGER', 'SUPER_ADMIN'
          )
        )
    );
$$;


--
-- Name: hub_material_object_is_readable(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_material_object_is_readable(object_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (select auth.uid()) is not null
    and exists (
      select 1
      from public.pedagogical_materials as material
      where material.storage_object_path = object_name
      and private.hub_material_object_has_provenance(
        object_name,
        material.tenant_id,
        material.uploaded_by
      )
      and (
        (
          (
            material.scope = 'GLOBAL'
            or material.is_global is true
          )
          and material.approval_status = 'APPROVED'
        )
        or (
          material.tenant_id = public._my_tenant_id()
          and public._my_tenant_is_operational()
          and (
            (
              public._my_role() = 'STUDENT'
              and material.approval_status = 'APPROVED'
              and exists (
                select 1
                from public.student_assignments as assignment
                where assignment.material_id = material.id
                  and assignment.student_id = (select auth.uid())
              )
            )
            or (
              public._my_role() <> 'STUDENT'
              and (
                material.uploaded_by = (select auth.uid())
                or public._my_role() in (
                  'SCHOOL_ADMIN',
                  'COORDINATOR',
                  'MANAGER',
                  'SUPER_ADMIN'
                )
                or (
                  public._my_role() = 'TEACHER'
                  and material.scope = 'TENANT'
                  and material.approval_status = 'APPROVED'
                )
              )
            )
          )
        )
      )
    );
$$;


--
-- Name: hub_material_url_object_name(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_material_url_object_name(source_url text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select nullif(
    case
      when position(
        '/storage/v1/object/public/materials/' in source_url
      ) > 0 then split_part(
        split_part(
          source_url,
          '/storage/v1/object/public/materials/',
          2
        ),
        '?',
        1
      )
      when position(
        '/storage/v1/object/authenticated/materials/' in source_url
      ) > 0 then split_part(
        split_part(
          source_url,
          '/storage/v1/object/authenticated/materials/',
          2
        ),
        '?',
        1
      )
      else null
    end,
    ''
  );
$$;


--
-- Name: hub_profile_is_active(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_profile_is_active(p_user_id uuid DEFAULT auth.uid()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null
    and exists (
      select 1
      from public.profiles as profile
      where profile.id = p_user_id
        and pg_catalog.lower(pg_catalog.btrim(profile.lifecycle_status)) = 'active'
    );
$$;


--
-- Name: hub_provider_operation_scope_is_current(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_provider_operation_scope_is_current(p_operation_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation private.hub_provider_operations%rowtype;
  v_account public.hub_accounts%rowtype;
  v_subscription public.hub_subscriptions%rowtype;
  v_checkout public.hub_checkout_sessions%rowtype;
  v_account_id uuid;
  v_account_row_version text;
  v_item jsonb;
begin
  perform private.hub_service_role_required();
  select operation.account_id into v_account_id
  from private.hub_provider_operations operation
  where operation.id = p_operation_id;
  if not found then
    return false;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-provider-operation:' || v_account_id::text,
      0
    )
  );
  select operation.* into v_operation
  from private.hub_provider_operations operation
  where operation.id = p_operation_id
  for update;
  if not found
     or v_operation.account_id is distinct from v_account_id
     or v_operation.lease_token is distinct from p_lease_token
     or v_operation.snapshot_hash is distinct from pg_catalog.encode(
       extensions.digest(
         pg_catalog.convert_to(v_operation.snapshot::text, 'UTF8'),
         'sha256'
       ),
       'hex'
     )
     or pg_catalog.jsonb_typeof(v_operation.snapshot -> 'targets')
       is distinct from 'array' then
    return false;
  end if;

  select account.* into v_account
  from public.hub_accounts account
  where account.id = v_operation.account_id
  for update;
  if not found
     or pg_catalog.btrim(v_account.asaas_customer_id) is distinct from
       (v_operation.snapshot ->> 'providerCustomerId') then
    return false;
  end if;

  if v_operation.operation_kind in (
    'ACCOUNT_STATUS', 'CORE_CANCELLATION'
  ) then
    -- Lock the complete account/product row sets, not only rows present in the
    -- old snapshot. This serializes an inactive->active transition or checkout
    -- rebinding that began without the advisory before the comparison below.
    perform subscription.id
    from public.hub_subscriptions subscription
    where subscription.account_id = v_operation.account_id
      and (v_operation.operation_kind <> 'CORE_CANCELLATION'
        or subscription.product_family = 'HUB_CORE')
    order by subscription.id
    for update;
    perform checkout.id
    from public.hub_checkout_sessions checkout
    where checkout.account_id = v_operation.account_id
      and (v_operation.operation_kind <> 'CORE_CANCELLATION'
        or checkout.product_family = 'HUB_CORE')
    order by checkout.id
    for update;

    select account.xmin::text || ':' || account.cmin::text
      into v_account_row_version
    from public.hub_accounts account
    where account.id = v_operation.account_id;
    if v_account.status is distinct from
         (v_operation.snapshot ->> 'accountStatus')
       or v_account.updated_at is distinct from
         (v_operation.snapshot ->> 'accountUpdatedAt')::timestamptz
       or v_account_row_version is distinct from
         (v_operation.snapshot ->> 'accountRowVersion')
       or pg_catalog.jsonb_typeof(
         v_operation.snapshot -> 'localSubscriptions'
       ) is distinct from 'array' then
      return false;
    end if;

    for v_item in
      select element.value
      from pg_catalog.jsonb_array_elements(
        v_operation.snapshot -> 'localSubscriptions'
      ) as element(value)
    loop
      select subscription.* into v_subscription
      from public.hub_subscriptions subscription
      where subscription.id = (v_item ->> 'id')::uuid
        and subscription.account_id = v_operation.account_id
      for update;
      if not found
         or v_subscription.product_family is distinct from
           (v_item ->> 'productFamily')
         or v_subscription.status is distinct from (v_item ->> 'status')
         or v_subscription.provider is distinct from (v_item ->> 'provider')
         or v_subscription.provider_subscription_id is distinct from
           (v_item ->> 'providerSubscriptionId') then
        return false;
      end if;
    end loop;

    if exists (
      select 1
      from public.hub_subscriptions subscription
      join public.hub_plans plan on plan.id = subscription.plan_id
      where subscription.account_id = v_operation.account_id
        and (v_operation.operation_kind <> 'CORE_CANCELLATION'
          or subscription.product_family = 'HUB_CORE')
        and subscription.status in (
          'TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE'
        )
        and not (
          subscription.provider is null
          and subscription.provider_subscription_id is null
          and plan.code = 'DISCOVERY'
        )
        and not exists (
          select 1
          from pg_catalog.jsonb_array_elements(
            v_operation.snapshot -> 'localSubscriptions'
          ) as item(value)
          where item.value ->> 'id' = subscription.id::text
        )
    ) or exists (
      select 1
      from public.hub_checkout_sessions checkout
      where checkout.account_id = v_operation.account_id
        and (v_operation.operation_kind <> 'CORE_CANCELLATION'
          or checkout.product_family = 'HUB_CORE')
        and checkout.status in ('CREATED', 'PENDING', 'OVERDUE', 'PAID')
        and nullif(
          pg_catalog.btrim(checkout.asaas_subscription_id),
          ''
        ) is not null
        and not exists (
          select 1
          from pg_catalog.jsonb_array_elements(
            v_operation.snapshot -> 'targets'
          ) as item(value)
          where item.value ->> 'checkoutId' = checkout.id::text
            and item.value ->> 'providerSubscriptionId' =
              checkout.asaas_subscription_id
        )
    ) or exists (
      select 1
      from public.hub_checkout_sessions checkout
      where checkout.account_id = v_operation.account_id
        and (v_operation.operation_kind <> 'CORE_CANCELLATION'
          or checkout.product_family = 'HUB_CORE')
        and checkout.status in ('PENDING', 'OVERDUE', 'PAID')
        and nullif(
          pg_catalog.btrim(checkout.asaas_subscription_id),
          ''
        ) is null
    ) then
      return false;
    end if;
  end if;

  for v_item in
    select element.value
    from pg_catalog.jsonb_array_elements(
      v_operation.snapshot -> 'targets'
    ) as element(value)
  loop
    select checkout.* into v_checkout
    from public.hub_checkout_sessions checkout
    where checkout.id = (v_item ->> 'checkoutId')::uuid
      and checkout.account_id = v_operation.account_id
      and checkout.asaas_subscription_id =
        (v_item ->> 'providerSubscriptionId')
    for update;
    if not found
       or pg_catalog.btrim(v_account.asaas_customer_id) is distinct from
         (v_item ->> 'providerCustomerId')
       or (
         v_operation.operation_kind in (
           'ACCOUNT_STATUS', 'CORE_CANCELLATION'
         ) and (
           v_checkout.product_family is distinct from
             (v_item ->> 'productFamily')
           or v_checkout.status is distinct from
             (v_item ->> 'checkoutStatus')
         )
       ) then
      return false;
    end if;
  end loop;

  return true;
end;
$$;


--
-- Name: hub_provider_operation_snapshot_immutable(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_provider_operation_snapshot_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.logical_key is distinct from old.logical_key
     or new.operation_kind is distinct from old.operation_kind
     or new.account_id is distinct from old.account_id
     or new.actor_user_id is distinct from old.actor_user_id
     or new.target_status is distinct from old.target_status
     or new.reason is distinct from old.reason
     or new.snapshot is distinct from old.snapshot
     or new.snapshot_hash is distinct from old.snapshot_hash then
    raise exception 'hub_provider_operation_snapshot_immutable'
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: hub_provider_target_identity_immutable(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_provider_target_identity_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.operation_id is distinct from old.operation_id
     or new.provider_subscription_id is distinct from
       old.provider_subscription_id
     or new.provider_customer_id is distinct from old.provider_customer_id
     or new.checkout_id is distinct from old.checkout_id then
    raise exception 'hub_provider_target_identity_immutable'
      using errcode = '55000';
  end if;
  return new;
end;
$$;


--
-- Name: hub_public_settings_internal(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_public_settings_internal() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select pg_catalog.jsonb_build_object(
      'settings_key', settings.settings_key,
      'brand_name', settings.brand_name,
      'headline', settings.headline,
      'subheadline', settings.subheadline,
      'saas_video_url', settings.saas_video_url,
      'saas_cta_url', settings.saas_cta_url,
      'support_url', settings.support_url,
      'metadata', pg_catalog.jsonb_build_object(
        'hubEnabled', case
          when pg_catalog.jsonb_typeof(settings.metadata -> 'hubEnabled') =
               'boolean'
            then (settings.metadata ->> 'hubEnabled')::boolean
          else true
        end,
        'catalogReady', private.hub_catalog_is_ready()
      )
    )
    from public.hub_settings as settings
    where settings.settings_key = 'default'
  ), pg_catalog.jsonb_build_object(
    'metadata', pg_catalog.jsonb_build_object(
      'hubEnabled', true,
      'catalogReady', false
    )
  ));
$$;


--
-- Name: hub_refresh_collection_catalog(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_refresh_collection_catalog() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
begin
  if new.title is distinct from old.title then
    update public.pedagogical_materials
       set title = title
     where collection_id = new.id
       and approval_status = 'APPROVED';
  end if;
  return new;
end;
$$;


--
-- Name: hub_release_feature_internal(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_release_feature_internal(p_user_id uuid, p_reservation_id uuid, p_lease_token uuid, p_request_key uuid, p_reason text DEFAULT 'REQUEST_FAILED'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := p_user_id;
  v_subscription_id uuid;
  v_reservation private.hub_usage_reservations%rowtype;
  v_reason text := pg_catalog.upper(
    coalesce(nullif(pg_catalog.btrim(p_reason), ''), 'REQUEST_FAILED')
  );
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if v_user_id is null then
    raise exception 'user_required' using errcode = '22023';
  end if;
  if p_reservation_id is null
     or p_lease_token is null
     or p_request_key is null then
    raise exception 'invalid_usage_release' using errcode = '22023';
  end if;
  if v_reason not in (
    'REQUEST_FAILED',
    'PROVIDER_FAILED',
    'PERSISTENCE_FAILED',
    'DELIVERY_FAILED',
    'CLIENT_ABORTED'
  ) then
    v_reason := 'REQUEST_FAILED';
  end if;

  select reservation.subscription_id into v_subscription_id
  from private.hub_usage_reservations as reservation
  where reservation.id = p_reservation_id;
  if v_subscription_id is null then
    return pg_catalog.jsonb_build_object(
      'released', false,
      'code', 'RESERVATION_NOT_FOUND'
    );
  end if;

  perform 1
  from public.hub_subscriptions as subscription
  where subscription.id = v_subscription_id
  for update;

  select reservation.* into v_reservation
  from private.hub_usage_reservations as reservation
  where reservation.id = p_reservation_id
    and reservation.subscription_id = v_subscription_id
    and reservation.user_id = v_user_id
    and reservation.request_key = p_request_key
    and reservation.lease_token = p_lease_token
  for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'released', false,
      'code', 'RESERVATION_NOT_FOUND'
    );
  end if;

  if v_reservation.status = 'COMMITTED' then
    return pg_catalog.jsonb_build_object(
      'released', false,
      'idempotent', true,
      'code', 'REQUEST_ALREADY_COMPLETED'
    );
  end if;
  if v_reservation.status = 'RELEASED' then
    return pg_catalog.jsonb_build_object(
      'released', true,
      'idempotent', true,
      'reservationId', v_reservation.id
    );
  end if;

  update private.hub_usage_reservations as reservation
  set status = 'RELEASED',
      release_reason = v_reason,
      released_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where reservation.id = v_reservation.id;

  return pg_catalog.jsonb_build_object(
    'released', true,
    'idempotent', false,
    'reservationId', v_reservation.id
  );
end;
$$;


--
-- Name: hub_release_fulfillment_on_payment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_release_fulfillment_on_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_is_renewal boolean := coalesce(new.metadata ->> 'renewal', 'false') =
    'true';
begin
  if new.status <> 'APPLIED'
     or (tg_op = 'UPDATE' and old.status = 'APPLIED')
     or v_is_renewal then
    return new;
  end if;

  update public.hub_fulfillment_outbox as delivery
  set subscription_id = new.subscription_id,
      status = case
        when coalesce(delivery.metadata ->> 'test_fixture', 'false') = 'true'
          then 'SKIPPED'
        else 'PENDING'
      end,
      next_attempt_at = pg_catalog.now(),
      lease_token = null,
      lease_expires_at = null,
      provider_dispatch_started_at = null,
      last_error = case
        when coalesce(delivery.metadata ->> 'test_fixture', 'false') = 'true'
          then 'test_fixture_suppressed'
        else null
      end,
      completed_at = case
        when coalesce(delivery.metadata ->> 'test_fixture', 'false') = 'true'
          then pg_catalog.now()
        else null
      end,
      updated_at = pg_catalog.now()
  where delivery.checkout_id = new.checkout_id
    and delivery.account_id = new.account_id
    and delivery.product_family = new.product_family
    and delivery.status = 'WAITING_PAYMENT';

  return new;
end;
$$;


--
-- Name: hub_reserve_feature_internal(uuid, text, integer, uuid, text, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_reserve_feature_internal(p_user_id uuid, p_feature_key text, p_units integer, p_request_key uuid, p_request_fingerprint text, p_account_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_user_id uuid := p_user_id;
  v_account_id uuid;
  v_active_account_count integer := 0;
  v_subscription public.hub_subscriptions%rowtype;
  v_reservation private.hub_usage_reservations%rowtype;
  v_feature_key text := nullif(pg_catalog.btrim(p_feature_key), '');
  v_fingerprint text := pg_catalog.lower(
    coalesce(pg_catalog.btrim(p_request_fingerprint), '')
  );
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_limit integer;
  v_reset text;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_used integer := 0;
  v_reserved integer := 0;
  v_lease_token uuid := pg_catalog.gen_random_uuid();
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if v_user_id is null then
    raise exception 'user_required' using errcode = '22023';
  end if;
  if v_feature_key is null
     or pg_catalog.char_length(v_feature_key) < 3
     or p_units is null
     or p_units <> 1
     or p_request_key is null
     or v_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_usage_reservation' using errcode = '22023';
  end if;
  if pg_catalog.jsonb_typeof(v_metadata) <> 'object'
     or pg_catalog.pg_column_size(v_metadata) > 4096 then
    raise exception 'invalid_usage_metadata' using errcode = '22023';
  end if;
  if not private.hub_is_enabled() then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'HUB_DISABLED',
      'productFamily', 'HUB_CORE'
    );
  end if;
  if not private.hub_profile_is_active(v_user_id) then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'PROFILE_INACTIVE',
      'productFamily', 'HUB_CORE'
    );
  end if;
  if exists (
    select 1
    from public.profiles as profile
    where profile.id = v_user_id
      and profile.tenant_id = 'wolfie-direct'
  ) then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'PRODUCT_SCOPE_FORBIDDEN',
      'productFamily', 'HUB_CORE'
    );
  end if;

  if v_feature_key = 'educator_ai.generate' then
    if v_metadata ->> 'source' <> 'pedagogical-content'
       or exists (
         select 1
         from pg_catalog.jsonb_object_keys(v_metadata) as key(name)
         where key.name not in ('source')
       ) then
      raise exception 'invalid_usage_metadata' using errcode = '22023';
    end if;
    v_metadata := '{"source":"pedagogical-content"}'::jsonb;
  elsif v_feature_key = 'wolfie.turn' then
    if v_metadata ->> 'source' <> 'wolf-tutor-api'
       or coalesce(v_metadata ->> 'conversationId', '')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or pg_catalog.char_length(coalesce(v_metadata ->> 'experienceId', '')) > 80
       or exists (
         select 1
         from pg_catalog.jsonb_object_keys(v_metadata) as key(name)
         where key.name not in ('source', 'conversationId', 'experienceId')
       ) then
      raise exception 'invalid_usage_metadata' using errcode = '22023';
    end if;
    v_metadata := pg_catalog.jsonb_strip_nulls(
      pg_catalog.jsonb_build_object(
        'source', 'wolf-tutor-api',
        'conversationId', v_metadata ->> 'conversationId',
        'experienceId', nullif(pg_catalog.btrim(v_metadata ->> 'experienceId'), '')
      )
    );
  elsif v_feature_key in ('library.preview', 'library.full_access') then
    if v_metadata ->> 'source' <> 'hub-library-access'
       or coalesce(v_metadata ->> 'contentId', '')
         !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or v_metadata ->> 'assetKind' not in ('PREVIEW', 'FULL')
       or (
         v_feature_key = 'library.preview'
         and v_metadata ->> 'assetKind' <> 'PREVIEW'
       )
       or (
         v_feature_key = 'library.full_access'
         and v_metadata ->> 'assetKind' <> 'FULL'
       )
       or exists (
         select 1
         from pg_catalog.jsonb_object_keys(v_metadata) as key(name)
         where key.name not in ('source', 'contentId', 'assetKind')
       ) then
      raise exception 'invalid_usage_metadata' using errcode = '22023';
    end if;
    v_metadata := pg_catalog.jsonb_build_object(
      'source', 'hub-library-access',
      'contentId', v_metadata ->> 'contentId',
      'assetKind', v_metadata ->> 'assetKind'
    );
  else
    raise exception 'unsupported_usage_reservation_feature'
      using errcode = '22023';
  end if;

  if p_account_id is null then
    select pg_catalog.count(*)::integer into v_active_account_count
    from public.hub_memberships as membership
    join public.hub_accounts as account
      on account.id = membership.account_id
     and account.status = 'ACTIVE'
    where membership.user_id = v_user_id
      and membership.status = 'ACTIVE';

    if v_active_account_count > 1 then
      return pg_catalog.jsonb_build_object(
        'allowed', false,
        'code', 'HUB_ACCOUNT_AMBIGUOUS',
        'productFamily', 'HUB_CORE'
      );
    end if;
  end if;

  select membership.account_id into v_account_id
  from public.hub_memberships as membership
  join public.hub_accounts as account
    on account.id = membership.account_id
   and account.status = 'ACTIVE'
  where membership.user_id = v_user_id
    and membership.status = 'ACTIVE'
    and (p_account_id is null or membership.account_id = p_account_id)
  order by membership.created_at, membership.id
  limit 1;
  if v_account_id is null then
    if exists (
      select 1
      from public.hub_memberships as membership
      join public.hub_accounts as account
        on account.id = membership.account_id
      where membership.user_id = v_user_id
        and membership.status <> 'REMOVED'
        and (p_account_id is null or membership.account_id = p_account_id)
        and (
          membership.status <> 'ACTIVE'
          or account.status <> 'ACTIVE'
        )
    ) then
      return pg_catalog.jsonb_build_object(
        'allowed', false,
        'code', 'HUB_ACCOUNT_INACTIVE',
        'productFamily', 'HUB_CORE'
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'HUB_ACCOUNT_REQUIRED',
      'productFamily', 'HUB_CORE'
    );
  end if;

  select subscription.* into v_subscription
  from public.hub_subscriptions as subscription
  join public.hub_plans as plan
    on plan.id = subscription.plan_id
   and plan.product_family = 'HUB_CORE'
  where subscription.account_id = v_account_id
    and subscription.product_family = 'HUB_CORE'
    and (
      (
        subscription.status = 'TRIALING'
        and subscription.trial_ends_at > pg_catalog.now()
      )
      or (
        subscription.status = 'ACTIVE'
        and coalesce(
          subscription.current_period_ends_at,
          '-infinity'::timestamptz
        ) > pg_catalog.now()
      )
    )
  order by
    (subscription.status = 'ACTIVE') desc,
    subscription.created_at desc,
    subscription.id desc
  limit 1
  for update of subscription;
  if not found then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'SUBSCRIPTION_REQUIRED',
      'productFamily', 'HUB_CORE'
    );
  end if;

  select entitlement.limit_value, entitlement.reset_period
  into v_limit, v_reset
  from public.hub_plan_entitlements as entitlement
  where entitlement.plan_id = v_subscription.plan_id
    and entitlement.feature_key = v_feature_key;
  if not found or v_limit = 0 then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'FEATURE_NOT_INCLUDED',
      'productFamily', 'HUB_CORE'
    );
  end if;

  if v_reset = 'DAY' then
    v_period_start := pg_catalog.date_trunc('day', pg_catalog.now());
    v_period_end := v_period_start + interval '1 day';
  elsif v_reset = 'SUBSCRIPTION' then
    v_period_start := coalesce(
      v_subscription.trial_starts_at,
      v_subscription.current_period_starts_at,
      v_subscription.created_at
    );
    v_period_end := coalesce(
      v_subscription.trial_ends_at,
      v_subscription.current_period_ends_at,
      'infinity'::timestamptz
    );
  else
    v_period_start := pg_catalog.date_trunc('month', pg_catalog.now());
    v_period_end := v_period_start + interval '1 month';
  end if;

  update private.hub_usage_reservations as expired_reservation
  set status = 'RELEASED',
      release_reason = 'LEASE_EXPIRED',
      released_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where expired_reservation.subscription_id = v_subscription.id
    and expired_reservation.feature_key = v_feature_key
    and expired_reservation.status = 'RESERVED'
    and expired_reservation.lease_expires_at <= pg_catalog.now();

  if exists (
    select 1
    from public.hub_usage_events as usage_event
    where usage_event.subscription_id = v_subscription.id
      and usage_event.feature_key = v_feature_key
      and usage_event.request_key = p_request_key
  ) then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'idempotent', true,
      'code', 'REQUEST_ALREADY_COMPLETED',
      'subscriptionId', v_subscription.id,
      'productFamily', 'HUB_CORE'
    );
  end if;

  select reservation.* into v_reservation
  from private.hub_usage_reservations as reservation
  where reservation.subscription_id = v_subscription.id
    and reservation.feature_key = v_feature_key
    and reservation.request_key = p_request_key
  for update;
  if found then
    if v_reservation.user_id <> v_user_id
       or v_reservation.units <> p_units
       or v_reservation.request_fingerprint <> v_fingerprint then
      return pg_catalog.jsonb_build_object(
        'allowed', false,
        'idempotent', true,
        'code', 'IDEMPOTENCY_KEY_REUSED',
        'productFamily', 'HUB_CORE'
      );
    end if;
    if v_reservation.status = 'COMMITTED' then
      return pg_catalog.jsonb_build_object(
        'allowed', false,
        'idempotent', true,
        'code', 'REQUEST_ALREADY_COMPLETED',
        'subscriptionId', v_subscription.id,
        'productFamily', 'HUB_CORE'
      );
    end if;
    if v_reservation.status = 'RESERVED' then
      return pg_catalog.jsonb_build_object(
        'allowed', false,
        'idempotent', true,
        'code', 'REQUEST_IN_PROGRESS',
        'retryAfterSeconds', greatest(
          pg_catalog.ceil(
            extract(
              epoch from (
                v_reservation.lease_expires_at - pg_catalog.now()
              )
            )
          )::integer,
          1
        ),
        'subscriptionId', v_subscription.id,
        'productFamily', 'HUB_CORE'
      );
    end if;
  end if;

  select coalesce(counter.used_units, 0) into v_used
  from public.hub_usage_counters as counter
  where counter.subscription_id = v_subscription.id
    and counter.feature_key = v_feature_key
    and counter.period_start = v_period_start;
  v_used := coalesce(v_used, 0);

  select coalesce(pg_catalog.sum(reservation.units), 0)::integer
  into v_reserved
  from private.hub_usage_reservations as reservation
  where reservation.subscription_id = v_subscription.id
    and reservation.feature_key = v_feature_key
    and reservation.period_start = v_period_start
    and reservation.period_end = v_period_end
    and reservation.status = 'RESERVED';

  if v_limit is not null and v_used + v_reserved + p_units > v_limit then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'USAGE_LIMIT_REACHED',
      'subscriptionId', v_subscription.id,
      'productFamily', 'HUB_CORE',
      'used', v_used,
      'reserved', v_reserved,
      'limit', v_limit,
      'remaining', greatest(v_limit - v_used - v_reserved, 0),
      'periodEndsAt', v_period_end
    );
  end if;

  if v_reservation.id is null then
    insert into private.hub_usage_reservations (
      account_id,
      subscription_id,
      user_id,
      feature_key,
      units,
      request_key,
      request_fingerprint,
      period_start,
      period_end,
      status,
      lease_token,
      lease_expires_at,
      metadata
    ) values (
      v_account_id,
      v_subscription.id,
      v_user_id,
      v_feature_key,
      p_units,
      p_request_key,
      v_fingerprint,
      v_period_start,
      v_period_end,
      'RESERVED',
      v_lease_token,
      pg_catalog.now() + interval '10 minutes',
      v_metadata
    ) returning * into v_reservation;
  else
    update private.hub_usage_reservations as reservation
    set status = 'RESERVED',
        account_id = v_account_id,
        user_id = v_user_id,
        period_start = v_period_start,
        period_end = v_period_end,
        lease_token = v_lease_token,
        lease_expires_at = pg_catalog.now() + interval '10 minutes',
        release_reason = null,
        released_at = null,
        reserved_at = pg_catalog.now(),
        updated_at = pg_catalog.now(),
        metadata = v_metadata
    where reservation.id = v_reservation.id
    returning * into v_reservation;
  end if;

  return pg_catalog.jsonb_build_object(
    'allowed', true,
    'idempotent', false,
    'accountId', v_account_id,
    'subscriptionId', v_subscription.id,
    'reservationId', v_reservation.id,
    'leaseToken', v_reservation.lease_token,
    'requestKey', p_request_key,
    'productFamily', 'HUB_CORE',
    'used', v_used,
    'reserved', v_reserved + p_units,
    'limit', v_limit,
    'remaining', case when v_limit is null then null
      else greatest(v_limit - v_used - v_reserved - p_units, 0)
    end,
    'periodEndsAt', v_period_end,
    'leaseExpiresAt', v_reservation.lease_expires_at
  );
end;
$_$;


--
-- Name: hub_reverse_paid_checkout_provider_apply(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_reverse_paid_checkout_provider_apply(p_checkout_id uuid, p_payment_id text, p_event_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_checkout public.hub_checkout_sessions%rowtype;
  v_subscription public.hub_subscriptions%rowtype;
  v_payment public.hub_subscription_payments%rowtype;
  v_pending_plan_id uuid;
  v_payment_id text := nullif(pg_catalog.btrim(p_payment_id), '');
  v_event_name text := pg_catalog.left(
    coalesce(nullif(pg_catalog.btrim(p_event_name), ''), 'UNKNOWN'),
    100
  );
begin
  if p_checkout_id is null
     or v_payment_id is null
     or pg_catalog.char_length(v_payment_id) > 200 then
    raise exception 'invalid_hub_payment_reversal' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('hub-payment:ASAAS:' || v_payment_id, 0)
  );

  select * into v_checkout
  from public.hub_checkout_sessions
  where id = p_checkout_id
  for update;
  if not found then
    raise exception 'hub_checkout_not_found' using errcode = 'P0002';
  end if;

  select * into v_payment
  from public.hub_subscription_payments
  where provider = 'ASAAS'
    and provider_payment_id = v_payment_id
  for update;
  if found and v_payment.checkout_id <> v_checkout.id then
    raise exception 'hub_checkout_payment_mismatch' using errcode = '42501';
  end if;
  if v_checkout.status = 'REVERSED' then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'subscriptionId', v_payment.subscription_id
    );
  end if;
  if v_payment.id is not null and v_payment.status = 'REVERSED' then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'subscriptionId', v_payment.subscription_id
    );
  end if;

  if v_payment.subscription_id is not null then
    select * into v_subscription
    from public.hub_subscriptions
    where id = v_payment.subscription_id
      and account_id = v_checkout.account_id
      and product_family = v_checkout.product_family
    for update;
  else
    select * into v_subscription
    from public.hub_subscriptions as subscription
    where subscription.account_id = v_checkout.account_id
      and subscription.product_family = v_checkout.product_family
      and subscription.provider = 'ASAAS'
      and (
        subscription.provider_payment_id = v_payment_id
        or (
          v_checkout.asaas_subscription_id is not null
          and subscription.provider_subscription_id =
            v_checkout.asaas_subscription_id
        )
        or subscription.metadata ->> 'checkoutId' = v_checkout.id::text
      )
    order by
      (subscription.provider_payment_id = v_payment_id) desc,
      subscription.created_at desc,
      subscription.id desc
    limit 1
    for update;
  end if;

  -- Reversals may reference the original checkout payment or the latest
  -- recurring payment. A ledger row is also authoritative for older applied
  -- payments. Anything else is rejected instead of revoking a random account.
  if v_payment.id is null
     and v_checkout.asaas_payment_id is distinct from v_payment_id
     and v_subscription.provider_payment_id is distinct from v_payment_id then
    raise exception 'hub_checkout_payment_mismatch' using errcode = '42501';
  end if;

  update public.hub_checkout_sessions
  set status = 'REVERSED',
      asaas_payment_id = coalesce(asaas_payment_id, v_payment_id),
      metadata = metadata || pg_catalog.jsonb_build_object(
        'reversalEvent', v_event_name,
        'reversedAt', pg_catalog.now(),
        'reversedPaymentId', v_payment_id
      ),
      updated_at = pg_catalog.now()
  where id = v_checkout.id;

  if v_subscription.id is not null then
    update public.hub_subscriptions
    set status = 'CANCELLED',
        cancelled_at = coalesce(cancelled_at, pg_catalog.now()),
        current_period_ends_at = least(
          coalesce(current_period_ends_at, pg_catalog.now()),
          pg_catalog.now()
        ),
        metadata = metadata || pg_catalog.jsonb_build_object(
          'reversalEvent', v_event_name,
          'checkoutId', v_checkout.id,
          'reversedPaymentId', v_payment_id
        ),
        updated_at = pg_catalog.now()
    where id = v_subscription.id
    returning * into v_subscription;
  end if;

  if v_payment.id is null then
    insert into public.hub_subscription_payments (
      provider, provider_payment_id, checkout_id, subscription_id,
      account_id, product_family, status, period_starts_at, period_ends_at,
      reversed_at, metadata
    ) values (
      'ASAAS', v_payment_id, v_checkout.id, v_subscription.id,
      v_checkout.account_id, v_checkout.product_family, 'REVERSED',
      v_subscription.current_period_starts_at,
      v_subscription.current_period_ends_at,
      pg_catalog.now(),
      pg_catalog.jsonb_build_object('event', v_event_name)
    );
  else
    update public.hub_subscription_payments
    set subscription_id = coalesce(subscription_id, v_subscription.id),
        status = 'REVERSED',
        reversed_at = coalesce(reversed_at, pg_catalog.now()),
        metadata = metadata || pg_catalog.jsonb_build_object(
          'event', v_event_name
        ),
        updated_at = pg_catalog.now()
    where id = v_payment.id;
  end if;

  if v_checkout.product_family = 'WOLFIE_STANDALONE' then
    select id into v_pending_plan_id
    from public.student_pricing_plans
    where tenant_id = 'wolfie-direct' and name = 'Wolfie Pendente'
    order by id
    limit 1;

    update public.tenant_memberships
    set student_plan_id = v_pending_plan_id,
        updated_at = pg_catalog.now()
    where user_id = v_checkout.requested_by
      and tenant_id = 'wolfie-direct'
      and role = 'STUDENT';

    perform pg_catalog.set_config('app.enrollment_claim', '1', true);
    update public.profiles
    set fidelity_plan = 'Wolfie Pendente',
        status_financial = 'SUSPENDED'
    where id = v_checkout.requested_by
      and tenant_id = 'wolfie-direct';
  end if;

  insert into public.hub_conversion_events(
    account_id, user_id, event_name, source, metadata
  ) values (
    v_checkout.account_id,
    v_checkout.requested_by,
    case when v_checkout.product_family = 'WOLFIE_STANDALONE'
      then 'wolfie_subscription_reversed'
      else 'hub_subscription_reversed'
    end,
    'asaas_webhook',
    pg_catalog.jsonb_build_object(
      'checkoutId', v_checkout.id,
      'paymentId', v_payment_id,
      'event', v_event_name
    )
  );

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'subscriptionId', v_subscription.id
  );
end;
$$;


--
-- Name: hub_schedule_core_cancellation_internal(uuid, uuid, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_schedule_core_cancellation_internal(p_account_id uuid, p_actor_user_id uuid, p_cancelled_provider_subscription_ids text[] DEFAULT '{}'::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account public.hub_accounts%rowtype;
  v_subscription public.hub_subscriptions%rowtype;
  v_checkout record;
  v_cancelled_ids text[] := coalesce(
    p_cancelled_provider_subscription_ids,
    '{}'::text[]
  );
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_existing_cancel_at_period_end boolean := false;
begin
  if p_account_id is null or p_actor_user_id is null then
    raise exception 'invalid_hub_cancellation_request'
      using errcode = '22023';
  end if;
  if exists (
    select 1
    from pg_catalog.unnest(v_cancelled_ids) as supplied(provider_id)
    where supplied.provider_id is null
      or pg_catalog.char_length(pg_catalog.btrim(supplied.provider_id)) < 1
      or pg_catalog.char_length(pg_catalog.btrim(supplied.provider_id)) > 200
  ) then
    raise exception 'invalid_provider_subscription_id'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-core-cancellation:' || p_account_id::text,
      0
    )
  );

  select account.* into v_account
  from public.hub_accounts as account
  where account.id = p_account_id
  for update;
  if not found then
    raise exception 'hub_account_not_found' using errcode = 'P0002';
  end if;
  if v_account.status <> 'ACTIVE' then
    raise exception 'hub_account_inactive' using errcode = '42501';
  end if;
  if not exists (
    select 1
    from public.hub_memberships as membership
    where membership.account_id = p_account_id
      and membership.user_id = p_actor_user_id
      and membership.status = 'ACTIVE'
      and membership.membership_role in ('OWNER', 'ADMIN')
  ) then
    raise exception 'hub_manager_required' using errcode = '42501';
  end if;

  select subscription.* into v_subscription
  from public.hub_subscriptions as subscription
  where subscription.account_id = p_account_id
    and subscription.product_family = 'HUB_CORE'
    and subscription.status = 'ACTIVE'
    and subscription.current_period_ends_at > pg_catalog.now()
  order by subscription.created_at desc, subscription.id desc
  limit 1
  for update;

  if not found then
    select subscription.* into v_subscription
    from public.hub_subscriptions as subscription
    where subscription.account_id = p_account_id
      and subscription.product_family = 'HUB_CORE'
      and pg_catalog.jsonb_typeof(
        subscription.metadata -> 'cancelAtPeriodEnd'
      ) = 'boolean'
      and (subscription.metadata ->> 'cancelAtPeriodEnd')::boolean
    order by subscription.created_at desc, subscription.id desc
    limit 1
    for update;
    if found then
      return pg_catalog.jsonb_build_object(
        'success', true,
        'idempotent', true,
        'accountId', p_account_id,
        'subscriptionId', v_subscription.id,
        'status', v_subscription.status,
        'cancelAtPeriodEnd', true,
        'accessEndsAt', v_subscription.current_period_ends_at,
        'cancellationRequestedAt',
          v_subscription.metadata ->> 'cancellationRequestedAt'
      );
    end if;
    raise exception 'hub_active_paid_subscription_required'
      using errcode = '55000';
  end if;

  v_existing_cancel_at_period_end :=
    pg_catalog.jsonb_typeof(
      v_subscription.metadata -> 'cancelAtPeriodEnd'
    ) = 'boolean'
    and (v_subscription.metadata ->> 'cancelAtPeriodEnd')::boolean;
  if v_existing_cancel_at_period_end then
    return pg_catalog.jsonb_build_object(
      'success', true,
      'idempotent', true,
      'accountId', p_account_id,
      'subscriptionId', v_subscription.id,
      'status', v_subscription.status,
      'cancelAtPeriodEnd', true,
      'accessEndsAt', v_subscription.current_period_ends_at,
      'cancellationRequestedAt',
        v_subscription.metadata ->> 'cancellationRequestedAt'
    );
  end if;

  if v_subscription.provider is distinct from 'ASAAS'
     or nullif(pg_catalog.btrim(v_subscription.provider_subscription_id), '')
        is null then
    raise exception 'hub_subscription_reconciliation_required'
      using errcode = '55000';
  end if;
  if not (
    v_subscription.provider_subscription_id = any(v_cancelled_ids)
  ) then
    raise exception 'hub_provider_cancellation_not_confirmed'
      using errcode = '55000';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-provider-subscription:' ||
        v_subscription.provider_subscription_id,
      0
    )
  );

  for v_checkout in
    select
      checkout.id,
      checkout.status,
      checkout.asaas_subscription_id,
      checkout.asaas_payment_id
    from public.hub_checkout_sessions as checkout
    where checkout.account_id = p_account_id
      and checkout.product_family = 'HUB_CORE'
      and checkout.status in ('CREATED', 'PENDING', 'OVERDUE', 'PAID')
    order by checkout.created_at, checkout.id
    for update of checkout
  loop
    if nullif(pg_catalog.btrim(v_checkout.asaas_subscription_id), '')
       is null then
      if v_checkout.status <> 'CREATED'
         or nullif(pg_catalog.btrim(v_checkout.asaas_payment_id), '')
            is not null then
        raise exception 'hub_checkout_reconciliation_required'
          using errcode = '55000';
      end if;
      continue;
    end if;
    if not (v_checkout.asaas_subscription_id = any(v_cancelled_ids)) then
      raise exception 'hub_provider_cancellation_not_confirmed'
        using errcode = '55000';
    end if;
  end loop;

  update public.hub_subscriptions as subscription
  set cancelled_at = coalesce(subscription.cancelled_at, v_now),
      metadata = (
        coalesce(subscription.metadata, '{}'::jsonb)
          - 'cancellationInProgress'
          - 'cancellationInProgressAt'
          - 'cancellationInProgressBy'
      )
        || pg_catalog.jsonb_build_object(
          'cancelAtPeriodEnd', true,
          'cancellationRequestedAt', v_now,
          'providerCancellationConfirmedAt', v_now,
          'accessEndsAt', subscription.current_period_ends_at,
          'cancellationRequestedBy', p_actor_user_id
        ),
      updated_at = v_now
  where subscription.id = v_subscription.id
  returning subscription.* into v_subscription;

  update public.hub_checkout_sessions as checkout
  set status = 'CANCELLED',
      metadata = coalesce(checkout.metadata, '{}'::jsonb)
        || pg_catalog.jsonb_build_object(
          'cancelAtPeriodEnd', true,
          'cancellationRequestedAt', v_now,
          'providerCancellationConfirmedAt', v_now,
          'accessEndsAt', v_subscription.current_period_ends_at
        ),
      updated_at = v_now
  where checkout.account_id = p_account_id
    and checkout.product_family = 'HUB_CORE'
    and checkout.status in ('CREATED', 'PENDING', 'OVERDUE', 'PAID');

  insert into public.hub_conversion_events (
    account_id,
    user_id,
    event_name,
    source,
    metadata
  ) values (
    p_account_id,
    p_actor_user_id,
    'hub_subscription_cancellation_scheduled',
    'hub_self_service',
    pg_catalog.jsonb_build_object(
      'subscriptionId', v_subscription.id,
      'cancelAtPeriodEnd', true,
      'accessEndsAt', v_subscription.current_period_ends_at,
      'providerSubscriptionsCancelled', v_cancelled_ids
    )
  );

  return pg_catalog.jsonb_build_object(
    'success', true,
    'idempotent', false,
    'accountId', p_account_id,
    'subscriptionId', v_subscription.id,
    'status', v_subscription.status,
    'cancelAtPeriodEnd', true,
    'accessEndsAt', v_subscription.current_period_ends_at,
    'cancellationRequestedAt', v_now
  );
end;
$$;


--
-- Name: hub_seed_member_profile(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_seed_member_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_display_name text;
begin
  select pg_catalog.left(
    coalesce(
      nullif(
        pg_catalog.btrim(
          pg_catalog.regexp_replace(
            coalesce(profile.full_name, ''),
            '[[:space:]]+',
            ' ',
            'g'
          )
        ),
        ''
      ),
      nullif(
        pg_catalog.btrim(
          pg_catalog.regexp_replace(
            coalesce(account.name, ''),
            '[[:space:]]+',
            ' ',
            'g'
          )
        ),
        ''
      ),
      'Membro do Hub'
    ),
    120
  )
  into v_display_name
  from public.hub_accounts as account
  left join public.profiles as profile
    on profile.id = new.user_id
  where account.id = new.account_id;

  if v_display_name is null then
    raise exception 'hub_account_missing' using errcode = '23503';
  end if;

  insert into public.hub_member_profiles (
    account_id,
    user_id,
    display_name
  ) values (
    new.account_id,
    new.user_id,
    v_display_name
  )
  on conflict (account_id, user_id) do nothing;

  return new;
end;
$$;


--
-- Name: hub_service_role_required(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_service_role_required() RETURNS void
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
end;
$$;


--
-- Name: hub_set_enabled_internal(boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_set_enabled_internal(p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_settings public.hub_settings%rowtype;
begin
  if p_enabled is null then
    raise exception 'hub_enabled_required' using errcode = '22023';
  end if;
  if not private.hub_is_internal_manager() then
    raise exception 'hub_internal_manager_required' using errcode = '42501';
  end if;

  update public.hub_settings as settings
  set metadata = pg_catalog.jsonb_set(
        coalesce(settings.metadata, '{}'::jsonb),
        '{hubEnabled}',
        pg_catalog.to_jsonb(p_enabled),
        true
      ),
      updated_at = pg_catalog.now()
  where settings.settings_key = 'default'
  returning settings.* into v_settings;

  if not found then
    raise exception 'hub_settings_missing' using errcode = 'P0002';
  end if;

  insert into public.hub_conversion_events (
    account_id,
    user_id,
    event_name,
    source,
    metadata
  ) values (
    null,
    v_actor_user_id,
    'hub_operational_status_changed',
    'internal_admin',
    pg_catalog.jsonb_build_object('hubEnabled', p_enabled)
  );

  return pg_catalog.jsonb_build_object(
    'hubEnabled', p_enabled,
    'updatedAt', v_settings.updated_at
  );
end;
$$;


--
-- Name: hub_set_updated_at(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: hub_sync_manager_subject_roles(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_sync_manager_subject_roles() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  update public.hub_memberships as membership
  set subject_role = case
    when new.audience = 'LEARNER' then 'LEARNER'
    else 'EDUCATOR'
  end,
      updated_at = pg_catalog.now()
  where membership.account_id = new.id
    and membership.membership_role in ('OWNER', 'ADMIN');

  return new;
end;
$$;


--
-- Name: hub_sync_pedagogical_material_catalog(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_sync_pedagogical_material_catalog() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  item_id uuid;
  collection_title text;
  material_author text;
  commercial_type text;
  commercial_description text;
  public_license_summary text;
begin
  if tg_op = 'DELETE' then
    update public.hub_content_items
       set is_active = false,
           preview_enabled = false,
           published_at = null,
           updated_at = now()
     where source_material_id = old.id;
    return old;
  end if;

  if new.approval_status <> 'APPROVED'
     or new.hub_catalog_opt_in is false
     or new.hub_commercial_approved is false
     or new.hub_rights_basis not in (
       'OWNED', 'LICENSED', 'PUBLIC_DOMAIN'
     )
     or new.hub_rights_verified_at is null
     or nullif(btrim(new.hub_rights_declaration), '') is null
     or new.hub_sync_status <> 'SYNCED'
     or new.hub_object_path is null
     or new.hub_preview_object_path is null
     or new.hub_object_path = new.hub_preview_object_path then
    update public.hub_content_items
       set is_active = false,
           preview_enabled = false,
           published_at = null,
           updated_at = now()
     where source_material_id = new.id;
    return new;
  end if;

  select collection.title
    into collection_title
  from public.pedagogical_collections as collection
  where collection.id = new.collection_id
    and collection.tenant_id = new.tenant_id;

  select profile.full_name
    into material_author
  from public.profiles as profile
  where profile.id = new.uploaded_by;

  commercial_type := case upper(coalesce(new.type, 'PDF'))
    when 'PDF' then 'PDF'
    when 'VIDEO' then 'VIDEO'
    when 'AUDIO' then 'AUDIO'
    else 'ACTIVITY'
  end;
  commercial_description := concat_ws(
    ' · ',
    nullif(btrim(coalesce(new.category, '')), ''),
    case
      when new.part_number is not null
        then 'Parte ' || new.part_number::text
      else null
    end
  );
  public_license_summary := case new.hub_rights_basis
    when 'OWNED' then
      'Conteúdo próprio com distribuição autorizada no Wise Wolf Hub.'
    when 'PUBLIC_DOMAIN' then
      'Conteúdo de domínio público verificado para distribuição.'
    else
      'Conteúdo licenciado com distribuição autorizada no Wise Wolf Hub.'
  end;

  insert into public.hub_content_items (
    slug,
    title,
    description,
    content_type,
    level_tag,
    niche,
    collection_name,
    preview_enabled,
    license_summary,
    author_name,
    rights_verified_at,
    rights_basis,
    catalog_scope,
    published_at,
    is_active,
    source_material_id,
    metadata
  ) values (
    'material-' || new.id::text,
    new.title,
    nullif(commercial_description, ''),
    commercial_type,
    case
      when new.level_tag in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')
        then new.level_tag
      else null
    end,
    coalesce(nullif(new.niche, ''), 'GENERAL'),
    collection_title,
    true,
    public_license_summary,
    material_author,
    new.hub_rights_verified_at,
    new.hub_rights_basis,
    'COMMERCIAL_GLOBAL',
    now(),
    true,
    new.id,
    jsonb_strip_nulls(
      jsonb_build_object(
        'source', 'curated_pedagogical_material',
        'partNumber', new.part_number
      )
    )
  )
  on conflict (source_material_id) where source_material_id is not null
  do update set
    title = excluded.title,
    description = excluded.description,
    content_type = excluded.content_type,
    level_tag = excluded.level_tag,
    niche = excluded.niche,
    collection_name = excluded.collection_name,
    preview_enabled = true,
    license_summary = excluded.license_summary,
    author_name = excluded.author_name,
    rights_verified_at = excluded.rights_verified_at,
    rights_basis = excluded.rights_basis,
    catalog_scope = excluded.catalog_scope,
    published_at = now(),
    is_active = true,
    metadata = excluded.metadata,
    updated_at = now()
  returning id into item_id;

  insert into public.hub_content_assets (
    content_id,
    asset_kind,
    bucket_id,
    object_path,
    external_url
  ) values
    (
      item_id,
      'FULL',
      'hub-library',
      new.hub_object_path,
      null
    ),
    (
      item_id,
      'PREVIEW',
      'hub-library',
      new.hub_preview_object_path,
      null
    )
  on conflict (content_id, asset_kind) do update set
    bucket_id = excluded.bucket_id,
    object_path = excluded.object_path,
    external_url = null;

  return new;
end;
$$;


--
-- Name: hub_track_event_internal(text, text, jsonb, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_track_event_internal(p_event_name text, p_source text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_account_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_account_id uuid;
  v_active_account_count integer := 0;
  v_is_manager boolean := false;
  v_event_name text := pg_catalog.lower(
    coalesce(pg_catalog.btrim(p_event_name), '')
  );
  v_source text := pg_catalog.lower(
    coalesce(pg_catalog.btrim(p_source), '')
  );
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
  v_plan_code text;
begin
  if v_user_id is null then
    raise exception 'authentication_required' using errcode = 'P0001';
  end if;
  if not private.hub_profile_is_active(v_user_id) then
    raise exception 'profile_inactive' using errcode = '42501';
  end if;
  if not private.hub_is_enabled() then
    raise exception 'hub_disabled' using errcode = 'P0001';
  end if;
  if pg_catalog.jsonb_typeof(v_metadata) <> 'object'
     or pg_catalog.octet_length(v_metadata::text) > 1024 then
    raise exception 'invalid_hub_event_metadata' using errcode = '22023';
  end if;

  if p_account_id is null then
    select pg_catalog.count(*)::integer into v_active_account_count
    from public.hub_memberships as membership
    join public.hub_accounts as account
      on account.id = membership.account_id
     and account.status = 'ACTIVE'
    where membership.user_id = v_user_id
      and membership.status = 'ACTIVE';
    if v_active_account_count > 1 then
      raise exception 'hub_account_ambiguous' using errcode = 'P0001';
    end if;
  end if;

  select
    membership.account_id,
    membership.membership_role in ('OWNER', 'ADMIN')
  into v_account_id, v_is_manager
  from public.hub_memberships as membership
  join public.hub_accounts as account
    on account.id = membership.account_id
   and account.status = 'ACTIVE'
  where membership.user_id = v_user_id
    and membership.status = 'ACTIVE'
    and (p_account_id is null or membership.account_id = p_account_id)
  order by
    (membership.membership_role = 'OWNER') desc,
    (membership.membership_role = 'ADMIN') desc,
    membership.created_at,
    membership.id
  limit 1;
  if v_account_id is null then
    raise exception 'hub_account_required' using errcode = '42501';
  end if;

  if v_event_name = 'hub_trial_activated' then
    if not v_is_manager
       or v_source <> 'hub_onboarding'
       or v_metadata ->> 'audience' is distinct from 'EDUCATOR'
       or exists (
         select 1
         from pg_catalog.jsonb_object_keys(v_metadata) as key(name)
         where key.name <> 'audience'
       ) then
      raise exception 'invalid_hub_event' using errcode = '22023';
    end if;
    v_metadata := pg_catalog.jsonb_build_object(
      'audience', v_metadata ->> 'audience'
    );
  elsif v_event_name = 'plan_interest' then
    v_plan_code := pg_catalog.upper(
      coalesce(pg_catalog.btrim(v_metadata ->> 'planCode'), '')
    );
    if v_source <> 'hub_plans'
       or v_plan_code !~ '^[A-Z0-9][A-Z0-9_-]{0,63}$'
       or not exists (
         select 1
         from public.hub_plans as plan
         where plan.code = v_plan_code
           and plan.product_family = 'HUB_CORE'
           and plan.is_active = true
           and plan.is_public = true
       )
       or exists (
         select 1
         from pg_catalog.jsonb_object_keys(v_metadata) as key(name)
         where key.name <> 'planCode'
       ) then
      raise exception 'invalid_hub_event' using errcode = '22023';
    end if;
    v_metadata := pg_catalog.jsonb_build_object('planCode', v_plan_code);
  elsif v_event_name = 'saas_cta_click' then
    if v_source <> 'hub_portal'
       or v_metadata <> '{}'::jsonb then
      raise exception 'invalid_hub_event' using errcode = '22023';
    end if;
  else
    raise exception 'invalid_hub_event' using errcode = '22023';
  end if;

  insert into public.hub_conversion_events (
    account_id,
    user_id,
    event_name,
    source,
    metadata
  ) values (
    v_account_id,
    v_user_id,
    v_event_name,
    v_source,
    v_metadata
  );
end;
$_$;


--
-- Name: hub_update_preferences_internal(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_update_preferences_internal(p_account_id uuid, p_preferences jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_preferences jsonb := coalesce(p_preferences, '{}'::jsonb);
  v_level text;
  v_role text;
  v_goal text;
  v_interests text;
  v_preferred_modality text;
  v_metadata_patch jsonb := '{}'::jsonb;
  v_updated_at timestamptz := pg_catalog.clock_timestamp();
begin
  if v_user_id is null then
    raise exception 'authentication_required' using errcode = 'P0001';
  end if;
  if p_account_id is null then
    raise exception 'invalid_account_id' using errcode = '22023';
  end if;
  if not private.hub_is_account_manager(p_account_id) then
    raise exception 'hub_manager_required' using errcode = '42501';
  end if;
  if pg_catalog.jsonb_typeof(v_preferences) <> 'object' then
    raise exception 'invalid_preferences' using errcode = '22023';
  end if;
  if pg_catalog.octet_length(v_preferences::text) > 2048 then
    raise exception 'preferences_too_large' using errcode = '22023';
  end if;
  if exists (
    select 1
    from pg_catalog.jsonb_object_keys(v_preferences) as supplied(key)
    where not (
      supplied.key = any (
        array[
          'level',
          'role',
          'goal',
          'interests',
          'preferred_modality'
        ]::text[]
      )
    )
  ) then
    raise exception 'unsupported_preference_key' using errcode = '22023';
  end if;
  if exists (
    select 1
    from pg_catalog.jsonb_each(v_preferences) as supplied(key, value)
    where pg_catalog.jsonb_typeof(supplied.value) <> 'string'
  ) then
    raise exception 'invalid_preference_value' using errcode = '22023';
  end if;

  v_level := pg_catalog.upper(
    pg_catalog.btrim(coalesce(v_preferences->>'level', ''))
  );
  v_role := nullif(
    pg_catalog.btrim(coalesce(v_preferences->>'role', '')),
    ''
  );
  v_goal := nullif(
    pg_catalog.btrim(coalesce(v_preferences->>'goal', '')),
    ''
  );
  v_interests := nullif(
    pg_catalog.btrim(coalesce(v_preferences->>'interests', '')),
    ''
  );
  v_preferred_modality := pg_catalog.lower(
    pg_catalog.btrim(
      coalesce(v_preferences->>'preferred_modality', '')
    )
  );

  if v_preferences ? 'level'
     and v_level <> ''
     and v_level not in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2') then
    raise exception 'invalid_cefr_level' using errcode = '22023';
  end if;
  if pg_catalog.char_length(
       coalesce(v_preferences->>'role', '')
     ) > 120
     or pg_catalog.char_length(
       coalesce(v_preferences->>'goal', '')
     ) > 320
     or pg_catalog.char_length(
       coalesce(v_preferences->>'interests', '')
     ) > 320 then
    raise exception 'preferences_too_long' using errcode = '22023';
  end if;
  if v_preferences ? 'preferred_modality' then
    if v_preferred_modality = '' then
      v_preferred_modality := 'mixed';
    elsif v_preferred_modality not in ('text', 'voice', 'mixed') then
      raise exception 'invalid_preferred_modality' using errcode = '22023';
    end if;
  end if;

  v_metadata_patch := pg_catalog.jsonb_build_object(
    'onboarding_completed', true,
    'personalized_at', v_updated_at
  );
  if v_preferences ? 'level' then
    v_metadata_patch := v_metadata_patch || pg_catalog.jsonb_build_object(
      'level', nullif(v_level, '')
    );
  end if;
  if v_preferences ? 'role' then
    v_metadata_patch := v_metadata_patch || pg_catalog.jsonb_build_object(
      'role', v_role
    );
  end if;
  if v_preferences ? 'goal' then
    v_metadata_patch := v_metadata_patch || pg_catalog.jsonb_build_object(
      'goal', v_goal
    );
  end if;
  if v_preferences ? 'interests' then
    v_metadata_patch := v_metadata_patch || pg_catalog.jsonb_build_object(
      'interests', v_interests
    );
  end if;
  if v_preferences ? 'preferred_modality' then
    v_metadata_patch := v_metadata_patch || pg_catalog.jsonb_build_object(
      'preferred_modality', v_preferred_modality
    );
  end if;

  update public.hub_accounts as account
  set metadata = coalesce(account.metadata, '{}'::jsonb)
        || v_metadata_patch,
      updated_at = v_updated_at
  where account.id = p_account_id
    and account.status = 'ACTIVE'
  returning account.updated_at into v_updated_at;

  if not found then
    raise exception 'hub_account_inactive_or_missing' using errcode = 'P0001';
  end if;

  return pg_catalog.jsonb_build_object(
    'accountId', p_account_id,
    'updatedAt', v_updated_at
  );
end;
$$;


--
-- Name: hub_user_has_educator_planner_access(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.hub_user_has_educator_planner_access(p_account_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_account_id is not null
    and p_user_id is not null
    and private.hub_is_enabled()
    and private.hub_profile_is_active(p_user_id)
    and not exists (
      select 1
      from public.profiles as profile
      where profile.id = p_user_id
        and profile.tenant_id = 'wolfie-direct'
    )
    and exists (
      select 1
      from public.hub_accounts as account
      join public.hub_memberships as membership
        on membership.account_id = account.id
       and membership.user_id = p_user_id
       and membership.status = 'ACTIVE'
       and membership.subject_role = 'EDUCATOR'
      join public.hub_subscriptions as subscription
        on subscription.account_id = account.id
       and subscription.product_family = 'HUB_CORE'
      join public.hub_plans as plan
        on plan.id = subscription.plan_id
       and plan.product_family = 'HUB_CORE'
       and plan.is_active = true
      join public.hub_plan_entitlements as entitlement
        on entitlement.plan_id = plan.id
       and entitlement.feature_key = 'educator_ai.generate'
       and (entitlement.limit_value is null or entitlement.limit_value > 0)
      where account.id = p_account_id
        and account.status = 'ACTIVE'
        and (
          (
            subscription.status = 'TRIALING'
            and subscription.trial_ends_at > pg_catalog.now()
          )
          or (
            subscription.status = 'ACTIVE'
            and coalesce(
              subscription.current_period_ends_at,
              '-infinity'::timestamptz
            ) > pg_catalog.now()
          )
        )
    );
$$;


--
-- Name: learning_actor_role(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.learning_actor_role() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_role text;
begin
  if pg_catalog.to_regprocedure('private.active_tenant_role(uuid)') is not null then
    execute 'select private.active_tenant_role($1)'
      into v_role
      using (select auth.uid());
    return v_role;
  end if;

  select profile.role::text
    into v_role
    from public.profiles as profile
   where profile.id = (select auth.uid());

  return v_role;
end;
$_$;


--
-- Name: learning_actor_tenant_id(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.learning_actor_tenant_id() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_tenant_id text;
begin
  if pg_catalog.to_regprocedure('private.active_tenant_id(uuid)') is not null then
    execute 'select private.active_tenant_id($1)'
      into v_tenant_id
      using (select auth.uid());
    return v_tenant_id;
  end if;

  select profile.tenant_id
    into v_tenant_id
    from public.profiles as profile
   where profile.id = (select auth.uid());

  return v_tenant_id;
end;
$_$;


--
-- Name: learning_text_array_is_valid(jsonb, integer, integer, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.learning_text_array_is_valid(p_value jsonb, p_min_items integer, p_max_items integer, p_max_item_length integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when coalesce(pg_catalog.jsonb_typeof(p_value), 'null') <> 'array' then false
    when pg_catalog.jsonb_array_length(p_value)
           not between p_min_items and p_max_items then false
    else not exists (
      select 1
        from pg_catalog.jsonb_array_elements(p_value) as item(value)
       where pg_catalog.jsonb_typeof(item.value) <> 'string'
          or pg_catalog.length(
               pg_catalog.btrim(item.value #>> '{}')
             ) not between 1 and p_max_item_length
    )
  end;
$$;


--
-- Name: legacy_role_rpc_target_allowed(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.legacy_role_rpc_target_allowed(p_target_tenant_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text;
  actor_tenant_id text;
  jwt_role text := coalesce(auth.jwt() ->> 'role', '');
BEGIN
  IF jwt_role = 'service_role'
    OR (
      jwt_role = ''
      AND session_user IN ('postgres', 'supabase_admin')
    )
  THEN
    RETURN true;
  END IF;

  IF jwt_role <> 'authenticated'
    OR actor_id IS NULL
    OR p_target_tenant_id IS NULL
    OR NOT private.tenant_is_operational(p_target_tenant_id)
  THEN
    RETURN false;
  END IF;

  actor_tenant_id := private.active_tenant_id(actor_id);
  actor_role := private.active_tenant_role(actor_id);

  RETURN actor_role = 'SUPER_ADMIN'
    OR (
      actor_tenant_id IS NOT NULL
      AND actor_tenant_id = p_target_tenant_id
    );
END;
$$;


--
-- Name: legal_snapshot_is_private(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.legal_snapshot_is_private(p_snapshot jsonb, p_tenant_id text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
  signature_path text;
  private_prefix text := p_tenant_id || '/legal-representative-signature/';
BEGIN
  IF p_snapshot IS NULL THEN
    RETURN true;
  END IF;
  IF jsonb_typeof(p_snapshot) IS DISTINCT FROM 'object'
    OR p_snapshot ?| ARRAY[
      'legalRepresentativeSignatureUrl',
      'directorSignatureUrl',
      'signatureUrl'
    ]
  THEN
    RETURN false;
  END IF;
  signature_path := nullif(trim(p_snapshot ->> 'legalRepresentativeSignaturePath'), '');
  IF signature_path IS NULL THEN
    RETURN true;
  END IF;
  RETURN
    left(signature_path, length(private_prefix)) = private_prefix
    AND substring(signature_path FROM length(private_prefix) + 1)
      ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89ab][0-9a-fA-F]{3}-[0-9a-fA-F]{12}\.(png|jpg|jpeg|webp)$';
END;
$_$;


--
-- Name: lock_and_validate_enrollment_schedule(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lock_and_validate_enrollment_schedule(p_offer_id uuid, p_student_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_initial_opportunity_id uuid;
  v_offer record;
  v_expected_count integer;
  v_actual_count integer;
  v_relational_schedule jsonb;
  v_teacher_ids uuid[];
  v_primary_teacher_id uuid;
  v_secondary_teacher_id uuid;
  v_teacher record;
  v_teacher_profile record;
  v_membership record;
  v_slot record;
begin
  select offer.opportunity_id
  into v_initial_opportunity_id
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.kind = 'ENROLLMENT';
  if not found then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end if;

  if v_initial_opportunity_id is not null then
    perform 1
    from public.opportunities as opportunity
    where opportunity.id = v_initial_opportunity_id
    for update;
  end if;

  select
    offer.id,
    offer.tenant_id,
    offer.payload,
    offer.opportunity_id,
    offer.processing_by,
    offer.processing_state,
    offer.revoked_at,
    offer.consumed_at,
    offer.expires_at,
    offer.invite_security_version
  into v_offer
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.kind = 'ENROLLMENT'
  for update;
  if not found
    or v_offer.opportunity_id is distinct from v_initial_opportunity_id
    or v_offer.invite_security_version < 1
    or v_offer.revoked_at is not null
  then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end if;

  begin
    v_expected_count := (v_offer.payload ->> 'classesPerWeek')::integer;
  exception when others then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end;
  select pg_catalog.count(*)::integer
  into v_actual_count
  from private.enrollment_offer_schedule_slots as slot
  where slot.offer_id = p_offer_id;
  if v_expected_count not between 1 and 7
    or v_actual_count <> v_expected_count
  then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end if;

  select pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'day', case slot.day_of_week
        when 0 then 'Sunday'
        when 1 then 'Monday'
        when 2 then 'Tuesday'
        when 3 then 'Wednesday'
        when 4 then 'Thursday'
        when 5 then 'Friday'
        when 6 then 'Saturday'
      end,
      'weekday', case slot.day_of_week
        when 0 then 'Sunday'
        when 1 then 'Monday'
        when 2 then 'Tuesday'
        when 3 then 'Wednesday'
        when 4 then 'Thursday'
        when 5 then 'Friday'
        when 6 then 'Saturday'
      end,
      'time', pg_catalog.to_char(slot.class_time, 'HH24:MI'),
      'teacherId', slot.teacher_id,
      'professorId', slot.teacher_id
    ) order by slot.slot_index
  )
  into v_relational_schedule
  from private.enrollment_offer_schedule_slots as slot
  where slot.offer_id = p_offer_id;

  select pg_catalog.array_agg(
    requested.teacher_id order by requested.first_slot_index
  )
  into v_teacher_ids
  from (
    select slot.teacher_id, pg_catalog.min(slot.slot_index) as first_slot_index
    from private.enrollment_offer_schedule_slots as slot
    where slot.offer_id = p_offer_id
    group by slot.teacher_id
  ) as requested;

  begin
    v_primary_teacher_id := nullif(
      v_offer.payload ->> 'professorId',
      ''
    )::uuid;
    v_secondary_teacher_id := nullif(
      v_offer.payload ->> 'professorId2',
      ''
    )::uuid;
  exception when others then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end;

  if v_offer.payload -> 'schedule' is distinct from v_relational_schedule
    or exists (
      select 1
      from private.enrollment_offer_schedule_slots as slot
      where slot.offer_id = p_offer_id
        and pg_catalog.to_char(slot.start_date, 'YYYY-MM-DD')
            is distinct from v_offer.payload ->> 'startDate'
    )
    or v_primary_teacher_id is null
    or pg_catalog.array_position(v_teacher_ids, v_primary_teacher_id) is null
    or (
      pg_catalog.array_length(v_teacher_ids, 1) = 1
      and v_secondary_teacher_id is not null
    )
    or (
      pg_catalog.array_length(v_teacher_ids, 1) = 2
      and (
        v_secondary_teacher_id is null
        or v_secondary_teacher_id = v_primary_teacher_id
        or pg_catalog.array_position(v_teacher_ids, v_secondary_teacher_id)
           is null
      )
    )
  then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end if;

  -- Professores sempre são bloqueados na mesma ordem lexicográfica.
  for v_slot in
    select distinct
      slot.teacher_id,
      slot.day_of_week,
      slot.day_name,
      slot.class_time
    from private.enrollment_offer_schedule_slots as slot
    where slot.offer_id = p_offer_id
    order by slot.teacher_id, slot.day_of_week, slot.class_time
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'schedule:teacher:' || v_slot.teacher_id::text || ':' ||
        public.fold_accents(v_slot.day_name) || ':' ||
        pg_catalog.to_char(v_slot.class_time, 'HH24:MI'),
        0
      )
    );
  end loop;

  if p_student_id is not null then
    for v_slot in
      select distinct slot.day_of_week, slot.day_name, slot.class_time
      from private.enrollment_offer_schedule_slots as slot
      where slot.offer_id = p_offer_id
      order by slot.day_of_week, slot.class_time
    loop
      perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'schedule:student:' || p_student_id::text || ':' ||
          public.fold_accents(v_slot.day_name) || ':' ||
          pg_catalog.to_char(v_slot.class_time, 'HH24:MI'),
          0
        )
      );
    end loop;
  end if;

  -- Status/lifecycle e membership nao podem mudar depois da validacao e antes
  -- do commit. FOR UPDATE tambem espera writers anteriores e reavalia a linha.
  for v_teacher in
    select distinct slot.teacher_id
    from private.enrollment_offer_schedule_slots as slot
    where slot.offer_id = p_offer_id
    order by slot.teacher_id
  loop
    select
      teacher.id,
      teacher.tenant_id,
      teacher.role,
      teacher.lifecycle_status
    into v_teacher_profile
    from public.profiles as teacher
    where teacher.id = v_teacher.teacher_id
    for update;
    if not found
      or v_teacher_profile.tenant_id is distinct from v_offer.tenant_id
      or v_teacher_profile.role is distinct from 'TEACHER'
      or pg_catalog.lower(
           pg_catalog.btrim(
             coalesce(v_teacher_profile.lifecycle_status, '')
           )
         ) <> 'active'
    then
      raise exception 'inactive_enrollment_teacher' using errcode = '42501';
    end if;

    select membership.user_id, membership.role, membership.status
    into v_membership
    from public.tenant_memberships as membership
    where membership.user_id = v_teacher.teacher_id
      and membership.tenant_id = v_offer.tenant_id
    for update;
    if not found
      or v_membership.role is distinct from 'TEACHER'
      or v_membership.status is distinct from 'ACTIVE'
    then
      raise exception 'inactive_enrollment_teacher' using errcode = '42501';
    end if;
  end loop;

  -- Libera leases vencidos/revogados somente para as chaves já protegidas.
  update private.enrollment_offer_schedule_slots as reserved
  set status = 'RELEASED',
      reserved_by = null,
      reserved_at = null,
      reservation_expires_at = null,
      materialized_booking_id = null,
      updated_at = now()
  where reserved.status = 'RESERVED'
    and exists (
      select 1
      from private.enrollment_offer_schedule_slots as requested
      where requested.offer_id = p_offer_id
        and requested.tenant_id = reserved.tenant_id
        and requested.teacher_id = reserved.teacher_id
        and requested.day_of_week = reserved.day_of_week
        and requested.class_time = reserved.class_time
    )
    and (
      reserved.reservation_expires_at is null
      or reserved.reservation_expires_at <= now()
      or exists (
        select 1
        from public.offers as owner_offer
        where owner_offer.id = reserved.offer_id
          and (
            owner_offer.revoked_at is not null
            or (
              owner_offer.consumed_at is null
              and owner_offer.expires_at <= now()
            )
          )
      )
    );

  -- Compatibilidade defensiva para bookings removidos antes do trigger abaixo.
  update private.enrollment_offer_schedule_slots as materialized
  set status = 'RELEASED',
      reserved_by = null,
      reserved_at = null,
      reservation_expires_at = null,
      materialized_booking_id = null,
      updated_at = now()
  where materialized.status = 'MATERIALIZED'
    and exists (
      select 1
      from private.enrollment_offer_schedule_slots as requested
      where requested.offer_id = p_offer_id
        and requested.tenant_id = materialized.tenant_id
        and requested.teacher_id = materialized.teacher_id
        and requested.day_of_week = materialized.day_of_week
        and requested.class_time = materialized.class_time
    )
    and not exists (
      select 1
      from public.bookings as booking
      where booking.id = materialized.materialized_booking_id
        and booking.enrollment_offer_slot_id = materialized.id
        and pg_catalog.upper(coalesce(booking.status, 'SCHEDULED')) = 'SCHEDULED'
    );

  for v_slot in
    select slot.*
    from private.enrollment_offer_schedule_slots as slot
    where slot.offer_id = p_offer_id
    order by slot.teacher_id, slot.day_of_week, slot.class_time, slot.slot_index
  loop
    if v_slot.tenant_id is distinct from v_offer.tenant_id
      or v_slot.day_name is distinct from public.canonical_weekday_name(v_slot.day_name)
      or public.dow_name_to_int(v_slot.day_name) <> v_slot.day_of_week
    then
      raise exception 'enrollment_schedule_changed' using errcode = '23P01';
    end if;

    perform availability.id
      from public.teacher_availability as availability
      where availability.tenant_id = v_offer.tenant_id
        and availability.teacher_id = v_slot.teacher_id
        and availability.day_of_week = v_slot.day_of_week
        and (
          availability.start_time = v_slot.class_time
          or (
            availability.end_time is not null
            and availability.start_time <= v_slot.class_time
            and availability.end_time > v_slot.class_time
          )
        )
      order by availability.id
      for update;
    if not found then
      raise exception 'teacher_slot_unavailable' using errcode = '23P01';
    end if;

    if exists (
      select 1
      from public.bookings as booking
      where booking.tenant_id = v_offer.tenant_id
        and pg_catalog.upper(coalesce(booking.status, 'SCHEDULED')) = 'SCHEDULED'
        and booking.time_slot ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
        and pg_catalog.left(pg_catalog.btrim(booking.time_slot), 5)
            = pg_catalog.to_char(v_slot.class_time, 'HH24:MI')
        and public.dow_name_to_int(booking.day_of_week) = v_slot.day_of_week
        and booking.enrollment_offer_slot_id is distinct from v_slot.id
        and (
          booking.teacher_id = v_slot.teacher_id
          or (p_student_id is not null and booking.student_id = p_student_id)
        )
    ) then
      raise exception 'teacher_slot_occupied' using errcode = '23P01';
    end if;

    if exists (
      select 1
      from private.enrollment_offer_schedule_slots as occupied
      where occupied.offer_id <> p_offer_id
        and occupied.tenant_id = v_offer.tenant_id
        and (
          occupied.teacher_id = v_slot.teacher_id
          or (
            p_student_id is not null
            and occupied.reserved_by = p_student_id
          )
        )
        and occupied.day_of_week = v_slot.day_of_week
        and occupied.class_time = v_slot.class_time
        and (
          occupied.status = 'RESERVED'
          and occupied.reservation_expires_at > now()
          or occupied.status = 'MATERIALIZED'
          and exists (
            select 1
            from public.bookings as occupied_booking
            where occupied_booking.id = occupied.materialized_booking_id
              and occupied_booking.enrollment_offer_slot_id = occupied.id
              and pg_catalog.upper(
                coalesce(occupied_booking.status, 'SCHEDULED')
              ) = 'SCHEDULED'
          )
        )
    ) then
      raise exception 'enrollment_schedule_reserved' using errcode = '23P01';
    end if;
  end loop;
end;
$_$;


--
-- Name: lock_coverage_absence_pair(uuid, uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lock_coverage_absence_pair(p_original_teacher uuid, p_cover_teacher uuid, p_class_date date) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_first text;
  v_second text;
BEGIN
  IF p_original_teacher IS NULL OR p_cover_teacher IS NULL
     OR p_class_date IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22004', MESSAGE = 'coverage_absence_lock_invalid';
  END IF;

  v_first := least(p_original_teacher::text, p_cover_teacher::text);
  v_second := greatest(p_original_teacher::text, p_cover_teacher::text);
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'coverage-absence:' || v_first || ':' || p_class_date::text,
      0
    )
  );
  IF v_second <> v_first THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'coverage-absence:' || v_second || ':' || p_class_date::text,
        0
      )
    );
  END IF;
END;
$$;


--
-- Name: lock_mutable_learning_path(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lock_mutable_learning_path(p_path_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_role text;
  v_actor_tenant_id text;
  v_is_service_role boolean := coalesce(auth.role(), '') = 'service_role';
  v_path_tenant_id text;
begin
  if not v_is_service_role then
    if v_actor_id is null then
      raise exception using
        errcode = '42501',
        message = 'authentication_required';
    end if;

    v_actor_role := private.learning_actor_role();
    v_actor_tenant_id := private.learning_actor_tenant_id();
    if v_actor_role is null
       or v_actor_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
      raise exception using
        errcode = '42501',
        message = 'learning_curriculum_mutation_not_authorized';
    end if;
  end if;

  select path.tenant_id
    into v_path_tenant_id
    from public.learning_paths as path
   where path.id = p_path_id
   for update;

  if not found
     or (
       not v_is_service_role
       and v_actor_role <> 'SUPER_ADMIN'
       and (
         v_path_tenant_id is null
         or v_actor_tenant_id is distinct from v_path_tenant_id
       )
     ) then
    raise exception using
      errcode = '42501',
      message = 'learning_curriculum_mutation_not_authorized';
  end if;

  if exists (
    select 1
      from public.student_path_enrollments as enrollment
     where enrollment.path_id = p_path_id
  ) then
    raise exception using
      errcode = '55000',
      message = 'learning_path_curriculum_frozen_after_enrollment';
  end if;
end;
$$;


--
-- Name: lock_teacher_closing_pair(text, text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lock_teacher_closing_pair(p_tenant text, p_month text, p_teacher_a uuid, p_teacher_b uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_first text;
  v_second text;
BEGIN
  IF p_tenant IS NULL OR p_month IS NULL OR p_teacher_a IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = '22004', MESSAGE = 'teacher_closing_lock_invalid';
  END IF;

  v_first := least(p_teacher_a::text, coalesce(p_teacher_b, p_teacher_a)::text);
  v_second := greatest(p_teacher_a::text, coalesce(p_teacher_b, p_teacher_a)::text);
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'teacher-closing:' || p_tenant || ':' || v_first || ':' || p_month,
      0
    )
  );
  IF v_second <> v_first THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'teacher-closing:' || p_tenant || ':' || v_second || ':' || p_month,
        0
      )
    );
  END IF;
END;
$$;


--
-- Name: lock_trial_conversion_graph(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lock_trial_conversion_graph(p_opportunity_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform opportunity.id
  from public.opportunities as opportunity
  where opportunity.id = p_opportunity_id
  for update;

  if not found then
    raise exception 'trial_opportunity_not_found' using errcode = 'P0002';
  end if;

  perform offer.id
  from public.offers as offer
  where offer.opportunity_id = p_opportunity_id
  order by offer.id
  for update;

  perform link.id
  from public.enrollment_links as link
  where link.opportunity_id = p_opportunity_id
  order by link.id
  for update;

  perform request.id
  from private.vendor_trial_teacher_requests as request
  where request.opportunity_id = p_opportunity_id
  order by request.id
  for update;
end;
$$;


--
-- Name: management_group_execution_authorized(text, uuid, text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.management_group_execution_authorized(p_tenant text, p_actor_id uuid, p_request_id text, p_expected jsonb, p_group_jid text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select coalesce(auth.role(), '') = 'service_role' and exists (
    select 1 from public.gestao_acao_pendente p
    join public.dre_report_settings c on c.tenant_id = p.tenant_id and c.destino = p.group_jid
    where c.is_active and c.allow_group_member_actions
      and p.tenant_id = p_tenant and p.request_id = p_request_id
      and (p_group_jid is null or p.group_jid = p_group_jid)
      and p.status = 'executing' and p.schema_version = 1
      and p.requested_by_user_id is not distinct from p_actor_id
      and p.confirmed_by_user_id is not distinct from p_actor_id
      and p.requested_by_jid ~ '^[0-9]{6,20}@(lid|s\.whatsapp\.net)$'
      and p.confirmed_by_jid = p.requested_by_jid
      and p.confirmed_at <= p.expires_at
      and p.updated_at > now() - interval '2 minutes'
      and p.acao @> p_expected
  );
$_$;


--
-- Name: management_group_message_exact_scope_active(text, text, text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.management_group_message_exact_scope_active(p_tenant_id text, p_notification_kind text, p_subject_id text, p_ref_date date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.tenants as tenant
      join public.dre_report_settings as setting
        on setting.tenant_id = tenant.id
       and setting.is_active
       and nullif(pg_catalog.btrim(setting.destino), '') is not null
     where tenant.id = p_tenant_id
       and tenant.whatsapp_enabled is true
       and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) in (
         'active', 'trial', 'trialing'
       )
  ) and (
    (
      p_notification_kind = 'PAYMENT_CONFIRMED'
      and exists (
        select 1
          from public.student_payments as payment
          join public.profiles as student
            on student.id = payment.student_id
           and student.tenant_id = payment.tenant_id
           and student.role = 'STUDENT'
           and coalesce(student.is_test_account, false) is false
           and student.test_fixture_key is null
         where payment.id::text = p_subject_id
           and payment.tenant_id = p_tenant_id
           and payment.status = 'CONFIRMED'
           and coalesce(payment.value, 0) > 0
           and p_ref_date = coalesce(payment.due_date, payment.created_at::date)
      )
    )
    or (
      p_notification_kind = 'MONTHLY_PAYMENT_CLOSE'
      and p_subject_id = p_tenant_id
      and exists (
        select 1
          from public.monthly_payment_closures as closure
          join public.payment_split_settings as split
            on split.tenant_id = closure.tenant_id
           and split.is_active
         where closure.tenant_id = p_tenant_id
           and closure.period_start = p_ref_date
           and closure.status = 'READY'
           and closure.sent_at is null
           and closure.snapshot_hash is not null
           and closure.group_destination_snapshot = (
             select setting.destino
               from public.dre_report_settings as setting
              where setting.tenant_id = p_tenant_id
                and setting.is_active
           )
      )
    )
  );
$$;


--
-- Name: management_payment_is_test_fixture(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.management_payment_is_test_fixture(p_tenant_id text, p_payment_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select lower(coalesce(payment.raw_payload ->> 'testMode', '')) in (
             'true', '1'
           )
        or lower(coalesce(payment.raw_payload ->> 'test_mode', '')) in (
             'true', '1'
           )
        or lower(coalesce(payment.raw_payload ->> 'testFixture', '')) in (
             'true', '1'
           )
        or lower(coalesce(payment.raw_payload ->> 'test_fixture', '')) in (
             'true', '1'
           )
        or exists (
          select 1
          from public.profiles as student
          where student.id = payment.student_id
            and student.tenant_id = payment.tenant_id
            and (
              coalesce(student.is_test_account, false)
              or student.test_fixture_key is not null
            )
        )
    from public.student_payments as payment
    where payment.id = p_payment_id
      and payment.tenant_id = p_tenant_id
  ), false)
$$;


--
-- Name: management_payment_notification_kind(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.management_payment_notification_kind(p_tenant_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when not exists (
      select 1
      from public.dre_report_settings as management
      where management.tenant_id = p_tenant_id
        and management.is_active
        and private.normalize_management_group_destination(
          management.destino
        ) is not null
    ) then null
    when exists (
      select 1
      from public.payment_split_settings as split
      where split.tenant_id = p_tenant_id
        and split.is_active
    ) then 'PAYMENT_SPLIT'
    else 'PAYMENT_RECEIVED'
  end
$$;


--
-- Name: management_payment_notification_replacement_kind(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.management_payment_notification_replacement_kind(p_tenant_id text, p_payment_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.management_payment_notification_kind(payment.tenant_id)
  from public.student_payments as payment
  join public.tenants as tenant
    on tenant.id = payment.tenant_id
    and tenant.whatsapp_enabled is true
    and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) in (
      'active', 'trial', 'trialing'
    )
  where payment.id = p_payment_id
    and payment.tenant_id = p_tenant_id
    and upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
      'RECEIVED', 'RECEIVED_IN_CASH'
    )
    and coalesce(payment.value, 0) > 0
    and not private.management_payment_is_test_fixture(
      payment.tenant_id,
      payment.id
    )
$$;


--
-- Name: management_payment_notification_scope_active(text, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.management_payment_notification_scope_active(p_tenant_id text, p_payment_id uuid, p_notification_kind text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.student_payments as payment
    join public.tenants as tenant
      on tenant.id = payment.tenant_id
      and tenant.whatsapp_enabled is true
      and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) in (
        'active', 'trial', 'trialing'
      )
    where payment.id = p_payment_id
      and payment.tenant_id = p_tenant_id
      and upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
        'RECEIVED', 'RECEIVED_IN_CASH'
      )
      and coalesce(payment.value, 0) > 0
      and not private.management_payment_is_test_fixture(
        payment.tenant_id,
        payment.id
      )
      and private.management_payment_notification_kind(payment.tenant_id)
        = p_notification_kind
      and not (
        p_notification_kind = 'PAYMENT_SPLIT'
        and (
          exists (
            select 1
            from public.automation_sent as sent
            where sent.kind = 'PAYMENT_SPLIT'
              and sent.subject_id = payment.id::text
          )
          or exists (
            select 1
            from public.asaas_payment_split_message_attempts as legacy
            where legacy.tenant_id = payment.tenant_id
              and legacy.payment_id = payment.id
              and (
                legacy.submit_attempt_count > 0
                or legacy.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUBMITTING')
              )
          )
        )
      )
      and not (
        p_notification_kind = 'PAYMENT_RECEIVED'
        and exists (
          select 1
          from public.management_group_message_attempts as legacy
          where legacy.tenant_id = payment.tenant_id
            and legacy.notification_kind = 'PAYMENT_CONFIRMED'
            and legacy.subject_id = payment.id::text
            and (
              legacy.submit_attempt_count > 0
              or legacy.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUBMITTING')
            )
        )
      )
  )
$$;


--
-- Name: merge_notification_delivery_status(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.merge_notification_delivery_status(p_current text, p_incoming text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_current text := lower(pg_catalog.btrim(coalesce(p_current, 'queued')));
  v_incoming text := lower(pg_catalog.btrim(coalesce(p_incoming, '')));
  v_current_rank integer;
  v_incoming_rank integer;
begin
  if v_incoming not in (
    'queued', 'preparing', 'submitting', 'accepted', 'sent',
    'delivered', 'read', 'failed', 'uncertain', 'skipped'
  ) then
    raise exception 'invalid_notification_delivery_status'
      using errcode = '22023';
  end if;
  if v_current not in (
    'queued', 'preparing', 'submitting', 'accepted', 'sent',
    'delivered', 'read', 'failed', 'uncertain', 'skipped'
  ) then
    v_current := 'queued';
  end if;

  v_current_rank := case v_current
    when 'accepted' then 40
    when 'sent' then 50
    when 'delivered' then 60
    when 'read' then 70
    else 0
  end;
  v_incoming_rank := case v_incoming
    when 'accepted' then 40
    when 'sent' then 50
    when 'delivered' then 60
    when 'read' then 70
    else 0
  end;

  -- HTTP/provider acceptance is not proof of send or delivery. A definitive
  -- provider failure therefore closes ACCEPTED (and every earlier local state)
  -- as FAILED. SENT/DELIVERED/READ are stronger provider evidence and cannot
  -- be erased by a late, out-of-order failure receipt.
  if v_incoming = 'failed'
     and v_current not in ('sent', 'delivered', 'read') then
    return 'failed';
  end if;
  if v_current = 'failed'
     and v_incoming not in ('sent', 'delivered', 'read') then
    return 'failed';
  end if;

  if v_current_rank > 0 or v_incoming_rank > 0 then
    if v_incoming_rank > v_current_rank then
      return v_incoming;
    end if;
    return v_current;
  end if;

  if v_current = 'failed' then return 'failed'; end if;
  if v_current = 'skipped' then return 'skipped'; end if;
  if v_current = 'uncertain' then
    if v_incoming = 'failed' then return 'failed'; end if;
    return 'uncertain';
  end if;
  if v_incoming in ('failed', 'uncertain', 'skipped') then
    return v_incoming;
  end if;

  return case
    when v_current = 'submitting' or v_incoming = 'submitting'
      then 'submitting'
    when v_current = 'preparing' or v_incoming = 'preparing'
      then 'preparing'
    else 'queued'
  end;
end;
$$;


--
-- Name: merge_whatsapp_message_status(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.merge_whatsapp_message_status(p_current text, p_incoming text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p_incoming is null or p_incoming = p_current then
    return p_current;
  end if;

  -- Confirmações do provedor são monotônicas. Um retry tardio de "sent" não
  -- pode rebaixar "delivered/read", e uma falha tardia não apaga uma entrega.
  if p_current = 'read' or p_incoming = 'read' then
    return 'read';
  end if;
  if p_current = 'delivered' or p_incoming = 'delivered' then
    return 'delivered';
  end if;
  if p_current = 'sent' or p_incoming = 'sent' then
    return 'sent';
  end if;
  if p_current = 'received' then
    return 'received';
  end if;
  if p_incoming = 'received' then
    return 'received';
  end if;
  -- Resultado ambiguo nunca volta para uma fila despachavel. Da mesma forma,
  -- um evento PENDING atrasado nao desfaz um dispatch que ja comecou.
  if p_current = 'uncertain'
     and p_incoming in ('queued', 'dispatching', 'uncertain') then
    return 'uncertain';
  end if;
  if p_current = 'dispatching' and p_incoming = 'queued' then
    return 'dispatching';
  end if;
  if p_current = 'failed'
     and p_incoming in ('queued', 'dispatching', 'uncertain', 'failed') then
    return 'failed';
  end if;
  if p_incoming = 'failed' then
    return 'failed';
  end if;
  if p_incoming = 'uncertain' then
    return 'uncertain';
  end if;
  return p_incoming;
end;
$$;


--
-- Name: next_incomplete_learning_activity(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.next_incomplete_learning_activity(p_student_id uuid, p_path_id uuid) RETURNS TABLE(activity_id uuid, unit_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select activity.id, activity.unit_id
    from public.learning_units as unit
    join public.unit_activities as activity
      on activity.unit_id = unit.id
    left join public.student_activity_progress as progress
      on progress.student_id = p_student_id
     and progress.activity_id = activity.id
   where unit.path_id = p_path_id
     and coalesce(progress.status, 'NOT_STARTED') <> 'COMPLETED'
   order by unit.order_index, activity.order_index, activity.id
   limit 1;
$$;


--
-- Name: normalize_management_group_destination(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_management_group_destination(p_destination text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_destination text := pg_catalog.btrim(coalesce(p_destination, ''));
  v_phone text;
begin
  if v_destination ~ '^[0-9]{10,25}@g[.]us$' then
    return v_destination;
  end if;

  v_phone := pg_catalog.regexp_replace(v_destination, '\D', '', 'g');
  if pg_catalog.char_length(v_phone) in (10, 11) then
    v_phone := '55' || v_phone;
  end if;
  if pg_catalog.char_length(v_phone) not between 12 and 15 then
    return null;
  end if;
  return v_phone;
end;
$_$;


--
-- Name: normalize_notification_destination(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_notification_destination(p_destination text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_destination text := pg_catalog.btrim(coalesce(p_destination, ''));
begin
  if v_destination ~ '^[0-9]{10,25}@g[.]us$' then
    return v_destination;
  end if;
  return private.normalize_notification_phone(v_destination);
end;
$_$;


--
-- Name: normalize_notification_phone(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_notification_phone(p_destination text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_phone text := pg_catalog.regexp_replace(
    coalesce(p_destination, ''),
    '\D',
    '',
    'g'
  );
begin
  if char_length(v_phone) in (10, 11) then
    v_phone := '55' || v_phone;
  end if;

  if char_length(v_phone) not between 12 and 15 then
    return null;
  end if;

  return v_phone;
end;
$$;


--
-- Name: normalize_offboarded_student_financial_state(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_offboarded_student_financial_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  canonical_lifecycle text := pg_catalog.lower(
    pg_catalog.btrim(coalesce(new.lifecycle_status, ''))
  );
begin
  if new.role = 'STUDENT' then
    if canonical_lifecycle in ('suspended', 'offboarded') then
      new.status := 'Inativo';
      if pg_catalog.upper(pg_catalog.btrim(coalesce(
           new.status_financial,
           ''
         ))) <> 'ARCHIVED'
      then
        new.status_financial := 'SUSPENDED';
      end if;
    elsif canonical_lifecycle = 'active'
          and pg_catalog.lower(pg_catalog.btrim(coalesce(
                new.status,
                ''
              ))) in ('active', 'ativo')
    then
      new.status := 'Ativo';
      -- Suspension is a forecast fence, not a permanent financial verdict.
      -- Reset only the SUSPENDED marker introduced by the pause so the
      -- reactivation finalizer's following aggregate recompute can retain
      -- ACTIVE when there is no decisive competence or derive OVERDUE/PENDING
      -- from payment truth. ARCHIVED remains terminal and is never reopened.
      if tg_op = 'UPDATE'
         and pg_catalog.lower(pg_catalog.btrim(coalesce(
               old.lifecycle_status,
               ''
             ))) = 'suspended'
         and pg_catalog.upper(pg_catalog.btrim(coalesce(
               old.status_financial,
               ''
             ))) <> 'ARCHIVED'
         and pg_catalog.upper(pg_catalog.btrim(coalesce(
               new.status_financial,
               ''
             ))) = 'SUSPENDED'
      then
        new.status_financial := 'ACTIVE';
      end if;
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: notification_phones_same_recipient(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.notification_phones_same_recipient(p_left text, p_right text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when private.normalize_notification_phone(p_left) is null
      or private.normalize_notification_phone(p_right) is null then false
    when private.normalize_notification_phone(p_left) =
      private.normalize_notification_phone(p_right) then true
    else
      pg_catalog.left(
        pg_catalog.right(private.normalize_notification_phone(p_left), 10),
        2
      ) = pg_catalog.left(
        pg_catalog.right(private.normalize_notification_phone(p_right), 10),
        2
      )
      and pg_catalog.right(private.normalize_notification_phone(p_left), 8) =
        pg_catalog.right(private.normalize_notification_phone(p_right), 8)
  end
$$;


--
-- Name: notify_asaas_automation_health(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.notify_asaas_automation_health() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  admin_row record;
  dedupe_id uuid;
  triage_count integer := 0;
  dead_letter_count integer := 0;
  stale_inbox_count integer := 0;
  failed_run_count integer := 0;
  stale_run_count integer := 0;
  open_severe_issue_count integer := 0;
  http_failure_count integer := 0;
  inactive_job_count integer := 0;
  failed_job_run_count integer := 0;
  alert_message text;
begin
  if not pg_try_advisory_xact_lock(
    hashtextextended('asaas-automation-health-notifier', 0)
  ) then
    return 0;
  end if;

  -- pg_cron considera sucesso quando o pg_net apenas enfileira a requisicao.
  -- O coletor posterior confronta cada request_id com a resposta HTTP real.
  if to_regprocedure('private.collect_asaas_http_failures()') is not null then
    perform private.collect_asaas_http_failures();
  end if;

  select
    count(*) filter (where inbox.status = 'TRIAGE'),
    count(*) filter (where inbox.status = 'DEAD_LETTER'),
    count(*) filter (
      where (
        inbox.status = 'PROCESSING'
        and inbox.lease_expires_at < now()
      ) or (
        inbox.status in ('RECEIVED', 'RETRY')
        and inbox.updated_at < now() - interval '2 hours'
      )
    )
    into triage_count, dead_letter_count, stale_inbox_count
    from public.asaas_webhook_inbox as inbox;

  select
    count(*) filter (
      where run.status = 'FAILED'
        and run.updated_at > now() - interval '7 days'
    ),
    count(*) filter (
      where run.status = 'RUNNING'
        and run.updated_at < now() - interval '30 minutes'
    )
    into failed_run_count, stale_run_count
    from public.asaas_reconciliation_runs as run;

  select count(*)
    into open_severe_issue_count
    from public.asaas_reconciliation_issues as issue
   where issue.resolved_at is null
     and issue.severity in ('HIGH', 'CRITICAL')
     and issue.observed_at > now() - interval '24 hours';

  select count(*)
    into http_failure_count
    from public.asaas_reconciliation_issues as issue
   where issue.resolved_at is null
     and issue.source = 'AUTOMATION_HTTP'
     and issue.observed_at > now() - interval '24 hours';

  select count(*)
    into inactive_job_count
    from (
      values
        ('wisewolf-asaas-webhook-worker'),
        ('wisewolf-asaas-reconciliation'),
        ('wisewolf-asaas-health'),
        ('wisewolf-sync-plan-change-billing'),
        ('wisewolf-reconcile-ledger'),
        ('wisewolf-sync-subscriptions'),
        ('wisewolf-payment-split-sweep')
    ) as expected(jobname)
    left join cron.job as job
      on job.jobname = expected.jobname
     and job.active is true
   where job.jobid is null;

  select count(*)
    into failed_job_run_count
    from cron.job_run_details as detail
    join cron.job as job on job.jobid = detail.jobid
     where job.jobname in (
       'wisewolf-asaas-webhook-worker',
       'wisewolf-asaas-reconciliation',
       'wisewolf-sync-plan-change-billing',
       'wisewolf-reconcile-ledger',
       'wisewolf-sync-subscriptions',
       'wisewolf-payment-split-sweep'
     )
     and detail.status = 'failed'
     and detail.start_time > now() - interval '24 hours';

  if triage_count = 0
     and dead_letter_count = 0
     and stale_inbox_count = 0
     and failed_run_count = 0
     and stale_run_count = 0
     and open_severe_issue_count = 0
     and http_failure_count = 0
     and inactive_job_count = 0
     and failed_job_run_count = 0
  then
    return 0;
  end if;

  select
    profile.id,
    membership.tenant_id,
    profile.phone
    into admin_row
    from public.tenant_memberships as membership
    join public.profiles as profile on profile.id = membership.user_id
   where membership.tenant_id = 'school-wise-wolf'
     and membership.role = 'SCHOOL_ADMIN'
     and membership.status = 'ACTIVE'
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
     and nullif(trim(profile.phone), '') is not null
     and coalesce(profile.is_test_account, false) is false
   order by membership.is_primary desc nulls last, membership.created_at, profile.id
   limit 1;

  if admin_row.id is null then
    raise exception using
      errcode = '55000',
      message = 'asaas_health_notification_recipient_unavailable';
  end if;

  insert into public.automation_sent (kind, subject_id, ref_date)
  values ('ASAAS_HEALTH', 'school-wise-wolf', current_date)
  on conflict (kind, subject_id, ref_date) do nothing
  returning id into dedupe_id;
  if dedupe_id is null then
    return 0;
  end if;

  alert_message :=
    '🔴 *Asaas requer atenção*' || E'\n\n' ||
    'Triagem: ' || triage_count ||
    ' | fila morta: ' || dead_letter_count ||
    ' | fila parada: ' || stale_inbox_count || E'\n' ||
    'Auditorias falhas: ' || failed_run_count ||
    ' | auditorias travadas: ' || stale_run_count ||
    ' | divergências graves recentes: ' || open_severe_issue_count || E'\n' ||
    'Chamadas HTTP falhas/sem resposta: ' || http_failure_count || E'\n' ||
    'Crons ausentes/desligados: ' || inactive_job_count ||
    ' | execuções de cron falhas: ' || failed_job_run_count || E'\n\n' ||
    'Consulte o painel técnico antes de reenviar ou corrigir qualquer valor.';

  insert into public.notification_queue (
    tenant_id,
    teacher_id,
    student_phone,
    message_body,
    scheduled_for,
    status,
    attempts,
    source_id,
    source_type,
    class_date,
    notification_kind
  ) values (
    admin_row.tenant_id,
    admin_row.id,
    admin_row.phone,
    alert_message,
    now(),
    'pending',
    0,
    dedupe_id,
    'ASAAS_HEALTH',
    current_date,
    'ASAAS_HEALTH'
  );

  return 1;
end;
$$;


--
-- Name: persist_wolfie_meeting_attempt_memories(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.persist_wolfie_meeting_attempt_memories(p_attempt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_candidate record;
  v_existing public.wolfie_memory_items%rowtype;
  v_combined_evidence jsonb;
  v_receipt_attempt_id uuid;
  v_memory_item_id uuid;
  v_candidate_count integer := 0;
  v_recorded integer := 0;
  v_replayed integer := 0;
begin
  for v_candidate in
    select *
      from private.wolfie_meeting_memory_candidates(p_attempt_id)
  loop
    v_candidate_count := v_candidate_count + 1;
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        v_candidate.candidate_tenant_id
          || ':'
          || v_candidate.candidate_student_id::text
          || ':'
          || v_candidate.candidate_memory_key,
        0
      )
    );

    v_receipt_attempt_id := null;
    insert into public.wolfie_meeting_memory_receipts (
      attempt_id,
      source_session_id,
      tenant_id,
      student_id,
      memory_key,
      dimension,
      kind
    ) values (
      v_candidate.candidate_attempt_id,
      v_candidate.candidate_source_session_id,
      v_candidate.candidate_tenant_id,
      v_candidate.candidate_student_id,
      v_candidate.candidate_memory_key,
      v_candidate.candidate_dimension,
      v_candidate.candidate_kind
    )
    on conflict (attempt_id, memory_key) do nothing
    returning attempt_id into v_receipt_attempt_id;

    if v_receipt_attempt_id is null then
      v_replayed := v_replayed + 1;
      continue;
    end if;

    select memory.*
      into v_existing
      from public.wolfie_memory_items as memory
     where memory.tenant_id = v_candidate.candidate_tenant_id
       and memory.student_id = v_candidate.candidate_student_id
       and memory.kind = v_candidate.candidate_kind
       and memory.memory_key = v_candidate.candidate_memory_key
     for update;

    if found then
      if pg_catalog.jsonb_typeof(v_existing.evidence) = 'array' then
        v_combined_evidence := v_existing.evidence
          || pg_catalog.jsonb_build_array(v_candidate.candidate_evidence);
      else
        v_combined_evidence :=
          pg_catalog.jsonb_build_array(v_candidate.candidate_evidence);
      end if;

      if pg_catalog.jsonb_array_length(v_combined_evidence) > 20 then
        select coalesce(
                 pg_catalog.jsonb_agg(entry.value order by entry.ordinality),
                 '[]'::jsonb
               )
          into v_combined_evidence
          from pg_catalog.jsonb_array_elements(v_combined_evidence)
            with ordinality as entry(value, ordinality)
         where entry.ordinality >
           pg_catalog.jsonb_array_length(v_combined_evidence) - 20;
      end if;

      update public.wolfie_memory_items
         set content = v_candidate.candidate_content,
             status = 'active',
             confidence = v_candidate.candidate_confidence,
             occurrence_count = case
               when v_existing.status = 'dismissed'
                and v_existing.occurrence_count = 1
                and v_existing.evidence = '[]'::jsonb
                and v_existing.source_conversation_session_id is null
                and v_existing.source_activity_session_id is null
                and v_existing.next_review_at is null
                and v_existing.expires_at is null
                 then 1
               else least(
                 coalesce(occurrence_count, 1) + 1,
                 1000000
               )
             end,
             evidence = v_combined_evidence,
             sensitive = false,
             consented_at = null,
             source_conversation_session_id = null,
             source_activity_session_id =
               v_candidate.candidate_source_session_id,
             last_seen_at = pg_catalog.now(),
             next_review_at = pg_catalog.now() + interval '30 days',
             mastered_at = null,
             expires_at = pg_catalog.now() + interval '180 days',
             updated_at = pg_catalog.now()
       where id = v_existing.id
       returning id into v_memory_item_id;
    else
      insert into public.wolfie_memory_items (
        tenant_id,
        student_id,
        kind,
        memory_key,
        content,
        status,
        confidence,
        occurrence_count,
        evidence,
        sensitive,
        consented_at,
        source_conversation_session_id,
        source_activity_session_id,
        next_review_at,
        expires_at
      ) values (
        v_candidate.candidate_tenant_id,
        v_candidate.candidate_student_id,
        v_candidate.candidate_kind,
        v_candidate.candidate_memory_key,
        v_candidate.candidate_content,
        'active',
        v_candidate.candidate_confidence,
        1,
        pg_catalog.jsonb_build_array(v_candidate.candidate_evidence),
        false,
        null,
        null,
        v_candidate.candidate_source_session_id,
        pg_catalog.now() + interval '30 days',
        pg_catalog.now() + interval '180 days'
      )
      returning id into v_memory_item_id;
    end if;

    update public.wolfie_meeting_memory_receipts
       set memory_item_id = v_memory_item_id
     where attempt_id = v_candidate.candidate_attempt_id
       and memory_key = v_candidate.candidate_memory_key;
    v_recorded := v_recorded + 1;
  end loop;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'eligible', v_candidate_count > 0,
    'recorded', v_recorded,
    'replayed', v_replayed
  );
end;
$$;


--
-- Name: prepare_enrollment_finance_scope(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prepare_enrollment_finance_scope(p_offer_id uuid, p_student_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_offer record;
  v_profile record;
  v_profile_exists boolean := false;
  v_is_same_offer boolean;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'enrollment:finance:student:' || p_student_id::text,
      0
    )
  );

  select
    offer.tenant_id,
    offer.metadata,
    offer.enrollment_fee,
    offer.processing_by
  into v_offer
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.kind = 'ENROLLMENT'
  for update;
  if not found then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end if;

  select
    profile.tenant_id,
    profile.asaas_customer_id,
    profile.subscription_id,
    profile.enrollment_payment_id
  into v_profile
  from public.profiles as profile
  where profile.id = p_student_id
  for update;
  v_profile_exists := found;

  v_is_same_offer := coalesce(
    v_offer.metadata ->> 'financial_profile_offer_id',
    ''
  ) = p_offer_id::text
    and v_profile.tenant_id is not distinct from v_offer.tenant_id
    and (
      nullif(v_profile.asaas_customer_id, '') is null
      or v_profile.asaas_customer_id
         = nullif(v_offer.metadata ->> 'asaas_customer_id', '')
    )
    and (
      nullif(v_profile.subscription_id, '') is null
      or v_profile.subscription_id
         = nullif(v_offer.metadata ->> 'subscription_id', '')
    )
    and (
      nullif(v_profile.enrollment_payment_id, '') is null
      or v_profile.enrollment_payment_id
         = nullif(v_offer.metadata ->> 'enrollment_payment_id', '')
    );

  if v_profile_exists and not v_is_same_offer then
    if nullif(v_profile.asaas_customer_id, '') is not null
      or nullif(v_profile.subscription_id, '') is not null
      or nullif(v_profile.enrollment_payment_id, '') is not null
    then
      raise exception 'enrollment_financial_scope_conflict'
        using errcode = '23P01';
    end if;
  end if;

  if exists (
    select 1
    from public.offers as competing_offer
    where competing_offer.id <> p_offer_id
      and competing_offer.kind = 'ENROLLMENT'
      and competing_offer.processing_by = p_student_id
      and competing_offer.processing_state not in ('NOT_STARTED', 'COMPLETED')
      and competing_offer.revoked_at is null
      and competing_offer.metadata ->> 'financial_profile_offer_id'
          = competing_offer.id::text
  ) then
    raise exception 'enrollment_financial_scope_conflict'
      using errcode = '23P01';
  end if;

  update public.offers as offer
  set metadata = coalesce(offer.metadata, '{}'::jsonb)
      || pg_catalog.jsonb_build_object(
        'financial_profile_offer_id', p_offer_id,
        'financial_profile_scoped_at', now()
      )
  where offer.id = p_offer_id;
end;
$$;


--
-- Name: prepare_enrollment_offer_payload(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prepare_enrollment_offer_payload(p_payload jsonb, p_tenant_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_schedule jsonb;
  v_normalized_schedule jsonb := '[]'::jsonb;
  v_slot jsonb;
  v_slot_index integer;
  v_raw_teacher text;
  v_teacher_id uuid;
  v_teacher_ids uuid[] := array[]::uuid[];
  v_raw_primary_teacher text;
  v_raw_secondary_teacher text;
  v_primary_teacher_id uuid;
  v_secondary_teacher_id uuid;
  v_other_teacher_id uuid;
  v_raw_day text;
  v_day smallint;
  v_raw_time text;
  v_time time without time zone;
  v_time_text text;
  v_day_en text;
  v_frequency_numeric numeric;
  v_frequency integer;
  v_due_numeric numeric;
  v_due_day integer;
  v_duration_numeric numeric;
  v_duration integer := 1;
  v_value numeric;
  v_start_text text;
  v_start_date date;
  v_billing_month text;
  v_billing_year integer;
  v_billing_month_number integer;
  v_month_first date;
  v_first_billing_date date;
  v_today date := (pg_catalog.clock_timestamp()
    at time zone 'America/Sao_Paulo')::date;
  v_enable_pro_rata boolean := false;
  v_is_dependent boolean := false;
  v_student_phone text;
  v_local_student_phone text;
  v_guardian_id uuid;
  v_guardian record;
  v_guardian_found boolean := false;
  v_guardian_cpf text;
  v_guardian_phone text;
  v_local_guardian_phone text;
  v_class_count integer := 0;
  v_price_per_class numeric;
  v_pro_rata_value numeric;
  v_result jsonb;
begin
  if p_payload is null
    or pg_catalog.jsonb_typeof(p_payload) is distinct from 'object'
    or p_tenant_id is null
  then
    raise exception 'invalid_enrollment_offer' using errcode = '22023';
  end if;

  if pg_catalog.jsonb_typeof(v_payload -> 'classesPerWeek')
       is distinct from 'number'
    or pg_catalog.jsonb_typeof(v_payload -> 'dueDay')
       is distinct from 'number'
    or pg_catalog.jsonb_typeof(v_payload -> 'value')
       is distinct from 'number'
  then
    raise exception 'invalid_enrollment_commercial_terms'
      using errcode = '22023';
  end if;

  begin
    v_frequency_numeric := (v_payload ->> 'classesPerWeek')::numeric;
    v_due_numeric := (v_payload ->> 'dueDay')::numeric;
    v_value := (v_payload ->> 'value')::numeric;
  exception when others then
    raise exception 'invalid_enrollment_commercial_terms'
      using errcode = '22023';
  end;

  if v_frequency_numeric <> pg_catalog.trunc(v_frequency_numeric)
    or v_frequency_numeric not between 1 and 7
    or v_due_numeric <> pg_catalog.trunc(v_due_numeric)
    or v_due_numeric not between 1 and 31
    or v_value <= 0
  then
    raise exception 'invalid_enrollment_commercial_terms'
      using errcode = '22023';
  end if;
  v_frequency := v_frequency_numeric::integer;
  v_due_day := v_due_numeric::integer;

  if v_payload ? 'planDuration' then
    if pg_catalog.jsonb_typeof(v_payload -> 'planDuration')
         is distinct from 'number'
    then
      raise exception 'invalid_enrollment_commercial_terms'
        using errcode = '22023';
    end if;
    begin
      v_duration_numeric := (v_payload ->> 'planDuration')::numeric;
    exception when others then
      raise exception 'invalid_enrollment_commercial_terms'
        using errcode = '22023';
    end;
    if v_duration_numeric <> pg_catalog.trunc(v_duration_numeric)
      or v_duration_numeric not in (0, 1, 6, 12)
    then
      raise exception 'invalid_enrollment_commercial_terms'
        using errcode = '22023';
    end if;
    v_duration := v_duration_numeric::integer;
  end if;

  v_schedule := v_payload -> 'schedule';
  if pg_catalog.jsonb_typeof(v_schedule) is distinct from 'array'
    or pg_catalog.jsonb_array_length(v_schedule) = 0
  then
    raise exception 'enrollment_schedule_required' using errcode = '22023';
  end if;
  if pg_catalog.jsonb_array_length(v_schedule) <> v_frequency then
    raise exception 'enrollment_schedule_cardinality_mismatch'
      using errcode = '22023';
  end if;

  v_start_text := pg_catalog.btrim(coalesce(v_payload ->> 'startDate', ''));
  if v_start_text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    raise exception 'invalid_enrollment_billing_period' using errcode = '22023';
  end if;
  begin
    v_start_date := v_start_text::date;
  exception when others then
    raise exception 'invalid_enrollment_billing_period' using errcode = '22023';
  end;
  if pg_catalog.to_char(v_start_date, 'YYYY-MM-DD') <> v_start_text then
    raise exception 'invalid_enrollment_billing_period' using errcode = '22023';
  end if;
  if v_start_date < v_today then
    raise exception 'invalid_enrollment_billing_period' using errcode = '22023';
  end if;

  v_billing_month := pg_catalog.btrim(
    coalesce(v_payload ->> 'billingStartMonth', '')
  );
  if v_billing_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' then
    raise exception 'invalid_enrollment_billing_period' using errcode = '22023';
  end if;
  begin
    v_billing_year := pg_catalog.substr(v_billing_month, 1, 4)::integer;
    v_billing_month_number := pg_catalog.substr(v_billing_month, 6, 2)::integer;
    v_month_first := pg_catalog.make_date(
      v_billing_year,
      v_billing_month_number,
      1
    );
    v_first_billing_date := pg_catalog.make_date(
      v_billing_year,
      v_billing_month_number,
      least(
        v_due_day,
        extract(
          day from (v_month_first + interval '1 month - 1 day')
        )::integer
      )
    );
  exception when others then
    raise exception 'invalid_enrollment_billing_period' using errcode = '22023';
  end;
  while v_first_billing_date < v_today loop
    v_month_first := (v_month_first + interval '1 month')::date;
    v_first_billing_date := v_month_first + least(
      v_due_day,
      extract(
        day from (v_month_first + interval '1 month - 1 day')
      )::integer
    ) - 1;
  end loop;
  if v_first_billing_date < v_start_date then
    raise exception 'invalid_enrollment_billing_period' using errcode = '22023';
  end if;

  if v_payload ? 'enableProRata' then
    if pg_catalog.jsonb_typeof(v_payload -> 'enableProRata')
         is distinct from 'boolean'
    then
      raise exception 'invalid_enrollment_billing_period' using errcode = '22023';
    end if;
    v_enable_pro_rata := (v_payload ->> 'enableProRata')::boolean;
  end if;
  if v_payload ? 'isDependent' then
    if pg_catalog.jsonb_typeof(v_payload -> 'isDependent')
         is distinct from 'boolean'
    then
      raise exception 'invalid_enrollment_offer' using errcode = '22023';
    end if;
    v_is_dependent := (v_payload ->> 'isDependent')::boolean;
  end if;
  if v_duration = 0 and v_enable_pro_rata then
    raise exception 'pro_rata_not_applicable' using errcode = '22023';
  end if;

  for v_slot, v_slot_index in
    select item.value, item.ordinality::integer
    from pg_catalog.jsonb_array_elements(v_schedule)
      with ordinality as item(value, ordinality)
    order by item.ordinality
  loop
    if pg_catalog.jsonb_typeof(v_slot) is distinct from 'object' then
      raise exception 'invalid_enrollment_schedule' using errcode = '22023';
    end if;

    v_raw_teacher := coalesce(
      nullif(pg_catalog.btrim(v_slot ->> 'teacherId'), ''),
      nullif(pg_catalog.btrim(v_slot ->> 'professorId'), ''),
      nullif(pg_catalog.btrim(v_payload ->> 'professorId'), '')
    );
    if v_raw_teacher is null
      or v_raw_teacher !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    then
      raise exception 'invalid_enrollment_schedule' using errcode = '22023';
    end if;
    v_teacher_id := v_raw_teacher::uuid;

    v_raw_day := pg_catalog.btrim(
      coalesce(v_slot ->> 'day', v_slot ->> 'weekday', '')
    );
    if v_raw_day ~ '^[0-6]$' then
      v_day := v_raw_day::smallint;
    else
      v_day := public.dow_name_to_int(v_raw_day)::smallint;
    end if;
    if v_day is null or v_day not between 0 and 6 then
      raise exception 'invalid_enrollment_schedule' using errcode = '22023';
    end if;

    v_raw_time := pg_catalog.btrim(coalesce(v_slot ->> 'time', ''));
    if v_raw_time !~ '^(?:[0-9]|[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$' then
      raise exception 'invalid_enrollment_schedule' using errcode = '22023';
    end if;
    v_time := v_raw_time::time;
    v_time_text := pg_catalog.to_char(v_time, 'HH24:MI');

    if exists (
      select 1
      from pg_catalog.jsonb_array_elements(v_normalized_schedule) as prior(slot)
      where public.dow_name_to_int(prior.slot ->> 'day') = v_day
        and prior.slot ->> 'time' = v_time_text
    ) then
      raise exception 'duplicate_enrollment_schedule_slot'
        using errcode = '22023';
    end if;

    if pg_catalog.array_position(v_teacher_ids, v_teacher_id) is null then
      v_teacher_ids := pg_catalog.array_append(v_teacher_ids, v_teacher_id);
    end if;
    if pg_catalog.array_length(v_teacher_ids, 1) > 2 then
      raise exception 'invalid_enrollment_schedule' using errcode = '22023';
    end if;

    v_day_en := case v_day
      when 0 then 'Sunday'
      when 1 then 'Monday'
      when 2 then 'Tuesday'
      when 3 then 'Wednesday'
      when 4 then 'Thursday'
      when 5 then 'Friday'
      when 6 then 'Saturday'
    end;
    v_normalized_schedule := v_normalized_schedule || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'day', v_day_en,
        'weekday', v_day_en,
        'time', v_time_text,
        'teacherId', v_teacher_id,
        'professorId', v_teacher_id
      )
    );
  end loop;

  if coalesce(pg_catalog.array_length(v_teacher_ids, 1), 0) not between 1 and 2 then
    raise exception 'invalid_enrollment_schedule' using errcode = '22023';
  end if;

  v_raw_primary_teacher := nullif(
    pg_catalog.btrim(v_payload ->> 'professorId'),
    ''
  );
  v_raw_secondary_teacher := nullif(
    pg_catalog.btrim(v_payload ->> 'professorId2'),
    ''
  );
  if v_raw_primary_teacher is not null then
    if v_raw_primary_teacher !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    then
      raise exception 'invalid_enrollment_schedule' using errcode = '22023';
    end if;
    v_primary_teacher_id := v_raw_primary_teacher::uuid;
    if pg_catalog.array_position(v_teacher_ids, v_primary_teacher_id) is null then
      raise exception 'invalid_enrollment_schedule' using errcode = '22023';
    end if;

    if pg_catalog.array_length(v_teacher_ids, 1) = 2 then
      v_other_teacher_id := case
        when v_teacher_ids[1] = v_primary_teacher_id then v_teacher_ids[2]
        else v_teacher_ids[1]
      end;
      v_teacher_ids := array[v_primary_teacher_id, v_other_teacher_id];
    else
      v_teacher_ids := array[v_primary_teacher_id];
    end if;
  else
    v_primary_teacher_id := v_teacher_ids[1];
  end if;

  if v_raw_secondary_teacher is not null then
    if v_raw_primary_teacher is null
      or v_raw_secondary_teacher !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    then
      raise exception 'invalid_enrollment_schedule' using errcode = '22023';
    end if;
    v_secondary_teacher_id := v_raw_secondary_teacher::uuid;
    if pg_catalog.array_length(v_teacher_ids, 1) <> 2
      or v_secondary_teacher_id is distinct from v_teacher_ids[2]
    then
      raise exception 'invalid_enrollment_schedule' using errcode = '22023';
    end if;
  elsif pg_catalog.array_length(v_teacher_ids, 1) = 2 then
    v_secondary_teacher_id := v_teacher_ids[2];
  end if;

  if exists (
    select 1
    from pg_catalog.unnest(v_teacher_ids) as requested(teacher_id)
    where not exists (
      select 1
      from public.profiles as teacher
      join public.tenant_memberships as membership
        on membership.user_id = teacher.id
       and membership.tenant_id = teacher.tenant_id
       and membership.role = 'TEACHER'
       and membership.status = 'ACTIVE'
      where teacher.id = requested.teacher_id
        and teacher.tenant_id = p_tenant_id
        and teacher.role = 'TEACHER'
        and pg_catalog.lower(pg_catalog.btrim(teacher.lifecycle_status)) = 'active'
    )
  ) then
    raise exception 'inactive_enrollment_teacher' using errcode = '42501';
  end if;

  v_student_phone := pg_catalog.regexp_replace(
    coalesce(v_payload ->> 'studentPhone', ''),
    '[^0-9]',
    '',
    'g'
  );
  v_local_student_phone := case
    when pg_catalog.length(v_student_phone) = 13
      and pg_catalog.left(v_student_phone, 2) = '55'
    then pg_catalog.substr(v_student_phone, 3)
    else v_student_phone
  end;
  if v_is_dependent and (
    v_local_student_phone !~ '^[1-9]{2}9[0-9]{8}$'
    or pg_catalog.substr(v_local_student_phone, 3)
       = pg_catalog.repeat(pg_catalog.substr(v_local_student_phone, 3, 1), 9)
  ) then
    raise exception 'dependent_student_phone_invalid' using errcode = '22023';
  end if;

  if v_is_dependent then
    begin
      v_guardian_id := nullif(
        pg_catalog.btrim(v_payload ->> 'guardianId'),
        ''
      )::uuid;
    exception when others then
      raise exception 'dependent_guardian_contact_invalid'
        using errcode = '22023';
    end;

    select
      guardian.full_name,
      guardian.email,
      guardian.cpf,
      guardian.phone,
      guardian.postal_code,
      guardian.address,
      guardian.address_number,
      guardian.lifecycle_status
    into v_guardian
    from public.profiles as guardian
    join public.tenant_memberships as membership
      on membership.user_id = guardian.id
     and membership.tenant_id = guardian.tenant_id
     and membership.status = 'ACTIVE'
    where guardian.id = v_guardian_id
      and guardian.tenant_id = p_tenant_id
    for update of guardian, membership;
    v_guardian_found := found;

    v_guardian_cpf := pg_catalog.regexp_replace(
      coalesce(v_guardian.cpf, ''),
      '[^0-9]',
      '',
      'g'
    );
    v_guardian_phone := pg_catalog.regexp_replace(
      coalesce(v_guardian.phone, ''),
      '[^0-9]',
      '',
      'g'
    );
    v_local_guardian_phone := case
      when pg_catalog.length(v_guardian_phone) = 13
        and pg_catalog.left(v_guardian_phone, 2) = '55'
      then pg_catalog.substr(v_guardian_phone, 3)
      else v_guardian_phone
    end;
    if not v_guardian_found
      or pg_catalog.lower(
           pg_catalog.btrim(coalesce(v_guardian.lifecycle_status, ''))
         ) <> 'active'
      or pg_catalog.length(pg_catalog.btrim(coalesce(v_guardian.full_name, ''))) < 3
      or pg_catalog.btrim(coalesce(v_guardian.email, ''))
         !~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'
      or not public.is_valid_cpf(v_guardian_cpf)
      or v_local_guardian_phone !~ '^[1-9]{2}9[0-9]{8}$'
      or pg_catalog.substr(v_local_guardian_phone, 3)
         = pg_catalog.repeat(
           pg_catalog.substr(v_local_guardian_phone, 3, 1),
           9
         )
      or pg_catalog.regexp_replace(
           coalesce(v_guardian.postal_code, ''),
           '[^0-9]',
           '',
           'g'
         ) !~ '^[0-9]{8}$'
      or pg_catalog.length(
           pg_catalog.btrim(coalesce(v_guardian.address, ''))
         ) < 5
      or pg_catalog.length(
           pg_catalog.btrim(coalesce(v_guardian.address_number, ''))
         ) < 1
    then
      raise exception 'dependent_guardian_contact_invalid'
        using errcode = '22023';
    end if;
  end if;

  select pg_catalog.count(*)::integer
  into v_class_count
  from pg_catalog.generate_series(
    v_start_date,
    v_first_billing_date - 1,
    interval '1 day'
  ) as occurrence(class_date)
  join lateral pg_catalog.jsonb_array_elements(v_normalized_schedule) as scheduled(slot)
    on public.dow_name_to_int(scheduled.slot ->> 'day')
       = extract(dow from occurrence.class_date)::integer;

  -- Em planos recorrentes, toda aula anterior a primeira mensalidade deve ser
  -- cobrada. O navegador pode pedir o preview, mas nao pode desligar o pro-rata
  -- e criar um intervalo academico sem cobertura financeira.
  v_enable_pro_rata := v_enable_pro_rata and v_duration <> 0 and v_class_count > 0;

  v_price_per_class := pg_catalog.round(
    v_value / (v_frequency * 4)::numeric,
    2
  );
  v_pro_rata_value := case
    when v_enable_pro_rata then pg_catalog.round(
      v_price_per_class * v_class_count,
      2
    )
    else 0::numeric
  end;

  -- Nenhum snapshot de responsavel vindo do navegador atravessa a barreira.
  -- Remove inclusive chaves guardian* futuras/desconhecidas antes de regravar
  -- apenas o conjunto validado no perfil do tenant.
  select coalesce(
    pg_catalog.jsonb_object_agg(entry.key, entry.value),
    '{}'::jsonb
  )
  into v_payload
  from pg_catalog.jsonb_each(v_payload) as entry(key, value)
  where entry.key !~* '^guardian';

  v_result := (
    v_payload
      - 'schedule'
      - 'professorId'
      - 'professorId2'
      - 'classesPerWeek'
      - 'dueDay'
      - 'value'
      - 'planDuration'
      - 'startDate'
      - 'billingStartMonth'
      - 'firstBillingDate'
      - 'proRataClassCount'
      - 'pricePerClass'
      - 'proRataValue'
      - 'proRataFormulaVersion'
      - 'proRataIntervalStartInclusive'
      - 'proRataIntervalEndExclusive'
      - 'enableProRata'
      - 'isDependent'
      - 'studentPhone'
  ) || pg_catalog.jsonb_build_object(
    'schedule', v_normalized_schedule,
    'professorId', v_teacher_ids[1],
    'professorId2', case
      when pg_catalog.array_length(v_teacher_ids, 1) = 2 then v_teacher_ids[2]
      else null
    end,
    'classesPerWeek', v_frequency,
    'dueDay', v_due_day,
    'value', v_value,
    'planDuration', v_duration,
    'startDate', pg_catalog.to_char(v_start_date, 'YYYY-MM-DD'),
    'billingStartMonth', pg_catalog.to_char(v_first_billing_date, 'YYYY-MM'),
    'firstBillingDate', pg_catalog.to_char(v_first_billing_date, 'YYYY-MM-DD'),
    'proRataClassCount', v_class_count,
    'pricePerClass', v_price_per_class,
    'proRataValue', v_pro_rata_value,
    'proRataFormulaVersion', 'weekly-frequency-times-4-v1',
    'proRataIntervalStartInclusive',
      pg_catalog.to_char(v_start_date, 'YYYY-MM-DD'),
    'proRataIntervalEndExclusive',
      pg_catalog.to_char(v_first_billing_date, 'YYYY-MM-DD'),
    'enableProRata', v_enable_pro_rata,
    'isDependent', v_is_dependent
  );
  if v_is_dependent then
    v_result := v_result || pg_catalog.jsonb_build_object(
      'studentPhone', v_local_student_phone,
      'guardianId', v_guardian_id,
      'guardianCpf', v_guardian.cpf,
      'guardianName', v_guardian.full_name,
      'guardianEmail', v_guardian.email,
      'guardianPhone', v_guardian.phone,
      'guardianPostalCode', v_guardian.postal_code,
      'guardianAddress', v_guardian.address,
      'guardianAddressNumber', v_guardian.address_number
    );
  end if;

  return v_result;
end;
$_$;


--
-- Name: FUNCTION prepare_enrollment_offer_payload(p_payload jsonb, p_tenant_id text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.prepare_enrollment_offer_payload(p_payload jsonb, p_tenant_id text) IS 'Normaliza ofertas de matrícula, respeita enableProRata=false e recalcula autoritativamente o valor quando habilitado.';


--
-- Name: prevent_duplicate_final_attendance_reschedule(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_duplicate_final_attendance_reschedule() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session_key text;
begin
  if new.fault_type <> 'TEACHER'
     or new.attendance_session_key is not null
     or new.original_booking_id is null then
    return new;
  end if;

  select ac.session_key
    into v_session_key
    from public.attendance_confirmations ac
    join public.class_logs cl
      on cl.tenant_id = ac.tenant_id
     and cl.teacher_id = ac.teacher_id
     and cl.student_id is not distinct from ac.student_id
     and cl.class_date = ac.class_date
     and (
       ac.class_log_id = cl.id
       or (ac.source_type = 'booking' and ac.source_id = cl.booking_id)
       or (ac.source_type = 'reschedule' and ac.source_id = cl.reschedule_id)
     )
   where ac.status = 'RESOLVED_UNPAID'
     and ac.resolution_verdict = 'TEACHER_ABSENT'
     and ac.tenant_id = new.tenant_id
     and ac.teacher_id = new.teacher_id
     and ac.student_id is not distinct from new.student_id
     and (
       (ac.source_type = 'booking' and ac.source_id = new.original_booking_id::text)
       or (
         ac.source_type = 'reschedule'
         and exists (
           select 1
             from public.reschedules source_reschedule
            where source_reschedule.id::text = ac.source_id
              and source_reschedule.original_booking_id = new.original_booking_id
         )
       )
     )
     and cl.created_at >= now() - interval '10 minutes'
   order by cl.created_at desc, ac.id
   limit 1;

  if v_session_key is not null and exists (
    select 1
      from public.reschedules r
     where r.fault_type = 'TEACHER'
       and r.attendance_session_key = v_session_key
  ) then
    return null;
  end if;

  return new;
end;
$$;


--
-- Name: prevent_hub_core_legal_acceptance_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_hub_core_legal_acceptance_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception 'hub_core_legal_acceptance_immutable' using errcode = '55000';
end;
$$;


--
-- Name: FUNCTION prevent_hub_core_legal_acceptance_mutation(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.prevent_hub_core_legal_acceptance_mutation() IS 'Makes legal acceptance evidence append-only outside an explicit audited retention migration.';


--
-- Name: protect_confirmed_training_slot(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_confirmed_training_slot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_teacher uuid; v_teachers uuid[]; v_day text; v_time text; v_date date; v_start timestamptz; v_start_date date;
begin
 if tg_table_name='appointments' then
  if lower(coalesce(new.status,'')) not in ('scheduled','confirmed') then return new; end if;
  v_start:=new.start_time; v_date:=(v_start at time zone 'America/Sao_Paulo')::date;
  v_time:=to_char(v_start at time zone 'America/Sao_Paulo','HH24:MI');
  v_teachers:=array[new.teacher_id,new.professor_id];
 elsif tg_table_name='bookings' then
  if upper(coalesce(new.status,''))='CANCELLED' then return new; end if;
  v_date:=new.date; v_day:=new.day_of_week; v_time:=left(new.time_slot,5); v_start_date:=new.start_date; v_teachers:=array[new.teacher_id];
 else
  if new.used_at is not null then return new; end if;
  v_date:=public.parse_lesson_date(new.date); v_time:=left(new.time,5); v_teachers:=array[new.teacher_id];
 end if;
 if v_date is not null then v_day:=(array['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'])[extract(dow from v_date)::int+1]; end if;
 for v_teacher in select distinct unnest(v_teachers) order by 1 loop
  if v_teacher is null then continue; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('schedule:teacher:'||v_teacher::text||':'||public.fold_accents(v_day)||':'||v_time,0));
  if exists(select 1 from public.teacher_training_sessions t where t.tenant_id=new.tenant_id and v_teacher in (t.trainer_id,t.trainee_id) and t.status='CONFIRMED' and t.ends_at>now()
    and (tg_table_name<>'appointments' or t.appointment_id is distinct from new.id)
    and ((v_start is not null and t.starts_at<v_start+interval '30 minutes' and t.ends_at>v_start)
      or (v_start is null and to_char(t.starts_at at time zone 'America/Sao_Paulo','HH24:MI')=v_time
        and ((v_date is not null and (t.starts_at at time zone 'America/Sao_Paulo')::date=v_date)
          or (v_date is null and public.fold_accents(v_day)=public.fold_accents((array['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'])[extract(dow from t.starts_at at time zone 'America/Sao_Paulo')::int+1]) and (v_start_date is null or (t.starts_at at time zone 'America/Sao_Paulo')::date>=v_start_date))))))
  then raise exception 'Este teacher já tem um treinamento confirmado nesse horário.'; end if;
 end loop;
 return new;
end;
$$;


--
-- Name: protect_enrollment_schedule_reservation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_enrollment_schedule_reservation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_day text;
  v_day_number integer;
  v_time text;
  v_slot record;
begin
  if (new.enrollment_offer_id is null)
     <> (new.enrollment_offer_slot_id is null)
  then
    raise exception 'invalid_enrollment_booking_link' using errcode = '23514';
  end if;

  if pg_catalog.upper(coalesce(new.status, 'SCHEDULED')) <> 'SCHEDULED' then
    return new;
  end if;

  v_day := public.canonical_weekday_name(new.day_of_week);
  v_day_number := public.dow_name_to_int(v_day);
  v_time := pg_catalog.btrim(new.time_slot);
  if v_day is null
    or v_day_number not between 0 and 6
    or v_time !~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
  then
    raise exception 'invalid_enrollment_booking_slot' using errcode = '23514';
  end if;
  v_time := pg_catalog.to_char(v_time::time, 'HH24:MI');

  if new.teacher_id is not null then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'schedule:teacher:' || new.teacher_id::text || ':' ||
        public.fold_accents(v_day) || ':' || v_time,
        0
      )
    );
  end if;
  if new.student_id is not null then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'schedule:student:' || new.student_id::text || ':' ||
        public.fold_accents(v_day) || ':' || v_time,
        0
      )
    );
  end if;

  if new.enrollment_offer_slot_id is not null then
    select slot.*
    into v_slot
    from private.enrollment_offer_schedule_slots as slot
    where slot.id = new.enrollment_offer_slot_id
      and slot.offer_id = new.enrollment_offer_id
    for update;
    if not found
      or v_slot.tenant_id is distinct from new.tenant_id
      or v_slot.teacher_id is distinct from new.teacher_id
      or v_slot.day_of_week is distinct from v_day_number
      or pg_catalog.to_char(v_slot.class_time, 'HH24:MI') is distinct from v_time
      or v_slot.start_date is distinct from new.start_date
      or v_slot.reserved_by is distinct from new.student_id
      or v_slot.status not in ('RESERVED', 'MATERIALIZED')
    then
      raise exception 'invalid_enrollment_booking_link' using errcode = '42501';
    end if;
    return new;
  end if;

  if (new.teacher_id is not null or new.student_id is not null) and exists (
    select 1
    from private.enrollment_offer_schedule_slots as reserved
    where reserved.tenant_id = new.tenant_id
      and (
        reserved.teacher_id = new.teacher_id
        or reserved.reserved_by = new.student_id
      )
      and reserved.day_of_week = v_day_number
      and pg_catalog.to_char(reserved.class_time, 'HH24:MI') = v_time
      and (
        reserved.status = 'RESERVED'
        and reserved.reservation_expires_at > now()
        or reserved.status = 'MATERIALIZED'
        and exists (
          select 1
          from public.bookings as linked_booking
          where linked_booking.id = reserved.materialized_booking_id
            and linked_booking.enrollment_offer_slot_id = reserved.id
            and pg_catalog.upper(
              coalesce(linked_booking.status, 'SCHEDULED')
            ) = 'SCHEDULED'
        )
      )
  ) then
    raise exception 'booking_conflicts_with_enrollment_reservation'
      using errcode = '23P01';
  end if;

  return new;
end;
$_$;


--
-- Name: protect_training_class_log(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_training_class_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.teacher_training_sessions%rowtype;
begin
 select * into s from public.teacher_training_sessions where appointment_id::text=new.appointment_id for update;
 if not found then return new; end if;
 if s.status not in ('CONFIRMED','COMPLETED') or s.trainer_id is distinct from new.teacher_id or s.tenant_id is distinct from new.tenant_id or s.ends_at>now() or new.class_date is distinct from (s.starts_at at time zone 'America/Sao_Paulo')::date or new.presence is distinct from 'COMPLETED' then
   raise exception 'O treinamento precisa ter aceite e estar concluído para entrar no fechamento.';
 end if;
 if s.class_log_id is not null and s.class_log_id<>new.id then raise exception using errcode='23505',message='Treinamento já lançado.',constraint='uq_class_logs_appointment'; end if;
 new.rate_override:=s.agreed_rate;
 new.subtype:='TREINAMENTO';
 return new;
end;
$$;


--
-- Name: reconcile_student_commercial_state(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reconcile_student_commercial_state() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
begin
  if upper(coalesce(new.role, '')) <> 'STUDENT'
     or new.contract_accepted is not true
     or new.tenant_id is null then
    return new;
  end if;

  update public.crm_leads as lead
     set status = 'WON',
         student_id = new.id,
         ai_handoff = true,
         last_status_change = clock_timestamp()
   where lead.tenant_id = new.tenant_id
     and (
       lead.student_id = new.id
       or (
         nullif(lower(btrim(lead.email)), '') is not null
         and lower(btrim(lead.email)) = lower(btrim(new.email))
       )
       or private.commercial_phones_match(lead.phone, new.phone)
     )
     and upper(coalesce(lead.status, '')) not in ('CONVERTED', 'WON');

  return new;
end;
$$;


--
-- Name: record_asaas_automation_http_request(text, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_asaas_automation_http_request(p_automation_name text, p_request_id bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_existing_name text;
begin
  if p_request_id is null
     or p_request_id <= 0
     or p_automation_name not in (
       'WEBHOOK_WORKER',
       'RECONCILIATION',
       'PLAN_CHANGE_BILLING',
       'LEDGER_RECONCILIATION',
       'SUBSCRIPTION_SYNC',
       'PAYMENT_SPLIT_SWEEP'
     ) then
    raise exception 'invalid_asaas_automation_http_request';
  end if;

  insert into private.asaas_automation_http_requests (
    request_id,
    automation_name
  ) values (
    p_request_id,
    p_automation_name
  )
  on conflict (request_id) do nothing;

  select request.automation_name
    into v_existing_name
    from private.asaas_automation_http_requests as request
   where request.request_id = p_request_id;

  if v_existing_name is distinct from p_automation_name then
    raise exception 'asaas_automation_http_request_identity_conflict';
  end if;
  return p_request_id;
end;
$$;


--
-- Name: record_student_learning_practice(uuid, integer, text, text[], timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_student_learning_practice(p_student_id uuid, p_score integer, p_activity_type text, p_skill_focus text[], p_now timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile record;
  v_today date := (p_now at time zone 'America/Sao_Paulo')::date;
  v_streak integer;
  v_skills text[] := coalesce(p_skill_focus, array[]::text[]);
  v_skill text;
  v_score numeric := least(100, greatest(0, coalesce(p_score, 0)));
begin
  select
    profile.role,
    profile.tenant_id,
    coalesce(profile.streak_count, 0) as streak_count,
    profile.last_streak_date
    into v_profile
    from public.profiles as profile
   where profile.id = p_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  v_streak := case
    when v_profile.last_streak_date = v_today then
      greatest(1, v_profile.streak_count)
    when v_profile.last_streak_date = v_today - 1 then
      greatest(0, v_profile.streak_count) + 1
    else 1
  end;

  update public.profiles
     set streak_count = v_streak,
         last_streak_date = v_today,
         last_activity = p_now
   where id = p_student_id;

  v_skills := v_skills || case p_activity_type
    when 'vocab_cards' then array['vocabulary']::text[]
    when 'quiz' then array['grammar', 'vocabulary']::text[]
    when 'grammar_drill' then array['grammar']::text[]
    when 'reading' then array['reading']::text[]
    when 'speaking_wolfie' then array['speaking', 'pronunciation']::text[]
    when 'listening' then array['listening']::text[]
    when 'writing' then array['writing']::text[]
    else array[]::text[]
  end;

  for v_skill in
    select distinct pg_catalog.lower(pg_catalog.btrim(skill_value))
      from pg_catalog.unnest(v_skills) as skill_value
     where pg_catalog.lower(pg_catalog.btrim(skill_value)) in (
       'grammar',
       'vocabulary',
       'listening',
       'speaking',
       'reading',
       'writing',
       'pronunciation'
     )
  loop
    insert into public.student_skill_scores (
      student_id,
      skill,
      current_score,
      total_activities,
      last_updated
    ) values (
      p_student_id,
      v_skill,
      v_score,
      1,
      p_now
    )
    on conflict (student_id, skill) do update
      set current_score = pg_catalog.round(
            (
              0.4 * excluded.current_score
              + 0.6 * coalesce(public.student_skill_scores.current_score, 0)
            )::numeric,
            1
          ),
          total_activities =
            coalesce(public.student_skill_scores.total_activities, 0) + 1,
          last_updated = p_now;
  end loop;

  return v_streak;
end;
$$;


--
-- Name: refresh_attendance_confirmation_sessions(date, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_attendance_confirmation_sessions(p_min_date date, p_max_date date) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_count integer := 0;
begin
  if p_min_date is null or p_max_date is null or p_min_date > p_max_date then
    return 0;
  end if;

  -- Clear first so that a canonical row can change without a transient unique
  -- collision on delivery_key in the second UPDATE.
  update public.attendance_confirmations
     set delivery_key = null
   where class_date between p_min_date and p_max_date
     and delivery_key is not null;

  with base as (
    select
      ac.id,
      ac.tenant_id,
      ac.teacher_id,
      ac.student_id,
      ac.class_date,
      ac.sent_at,
      ac.responded_at,
      ac.created_at,
      ac.delivery_status,
      ac.last_delivery_error,
      case
        when pg_catalog.btrim(coalesce(ac.class_time, ''))
             ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
        then pg_catalog.left(pg_catalog.btrim(ac.class_time), 5)::time
      end as slot_time,
      coalesce(
        ac.student_id::text,
        nullif(pg_catalog.regexp_replace(coalesce(ac.student_phone, ''), '\\D', '', 'g'), ''),
        ac.id::text
      ) as participant_key
    from public.attendance_confirmations ac
    where ac.class_date between p_min_date and p_max_date
  ), lagged as (
    select
      b.*,
      pg_catalog.lag(b.slot_time) over (
        partition by b.tenant_id, b.teacher_id, b.participant_key, b.class_date
        order by b.slot_time nulls last, b.created_at, b.id
      ) as previous_slot_time
    from base b
  ), marked as (
    select
      l.*,
      case
        when l.slot_time is null then 1
        when l.previous_slot_time is null then 1
        when l.slot_time - l.previous_slot_time > interval '30 minutes' then 1
        else 0
      end as starts_group
    from lagged l
  ), grouped as (
    select
      m.*,
      sum(m.starts_group) over (
        partition by m.tenant_id, m.teacher_id, m.participant_key, m.class_date
        order by m.slot_time nulls last, m.created_at, m.id
        rows between unbounded preceding and current row
      ) as group_number
    from marked m
  ), labeled as (
    select
      g.*,
      pg_catalog.min(g.slot_time) over (
        partition by g.tenant_id, g.teacher_id, g.participant_key,
                     g.class_date, g.group_number
      ) as first_slot_time,
      pg_catalog.max(g.slot_time) over (
        partition by g.tenant_id, g.teacher_id, g.participant_key,
                     g.class_date, g.group_number
      ) as last_slot_time,
      pg_catalog.bool_or(g.delivery_status = 'AMBIGUOUS') over (
        partition by g.tenant_id, g.teacher_id, g.participant_key,
                     g.class_date, g.group_number
      ) as session_has_ambiguous_delivery,
      pg_catalog.first_value(g.id) over (
        partition by g.tenant_id, g.teacher_id, g.participant_key,
                     g.class_date, g.group_number
        order by
          (g.sent_at is not null) desc,
          (g.responded_at is not null) desc,
          (g.delivery_status = 'PROCESSING') desc,
          g.slot_time nulls last,
          g.created_at,
          g.id
      ) as canonical_id
    from grouped g
  ), resolved as (
    select
      l.id,
      l.canonical_id,
      l.session_has_ambiguous_delivery,
      case when l.last_slot_time is not null then
        (
          (l.class_date::text || ' ' || l.last_slot_time::text)::timestamp
          at time zone 'America/Sao_Paulo'
        ) + interval '30 minutes'
      end as resolved_session_end_at,
      'attendance:' || pg_catalog.md5(
        coalesce(l.tenant_id, '-') || '|' ||
        coalesce(l.teacher_id::text, '-') || '|' ||
        l.participant_key || '|' ||
        l.class_date::text || '|' ||
        coalesce(l.first_slot_time::text, l.canonical_id::text)
      ) as resolved_session_key
    from labeled l
  )
  update public.attendance_confirmations ac
     set session_key = r.resolved_session_key,
         canonical_confirmation_id = r.canonical_id,
         session_end_at = r.resolved_session_end_at,
         delivery_key = case
           when ac.id = r.canonical_id
           then 'attendance-delivery:' || r.resolved_session_key
         end,
         delivery_status = case
           when ac.sent_at is not null then 'SENT'
           -- One uncertain legacy member makes the whole logical session
           -- terminal: selecting a different canonical slot must not resend it.
           when r.session_has_ambiguous_delivery then 'AMBIGUOUS'
           when ac.id <> r.canonical_id then 'GROUPED'
           when ac.delivery_status in ('PROCESSING', 'AMBIGUOUS', 'FAILED', 'CANCELLED')
             then ac.delivery_status
           when ac.send_attempts >= 8 then 'FAILED'
           else 'PENDING'
         end,
         last_delivery_error = case
           when ac.sent_at is null
                and r.session_has_ambiguous_delivery
             then coalesce(
               ac.last_delivery_error,
               'session_delivery_attempt_outcome_unknown'
             )
           else ac.last_delivery_error
         end
    from resolved r
   where ac.id = r.id;

  get diagnostics v_count = row_count;
  return v_count;
end;
$_$;


--
-- Name: refresh_student_hearts(uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_student_hearts(p_student_id uuid, p_now timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile record;
  v_hearts integer;
  v_anchor timestamptz;
  v_regenerated integer := 0;
  v_next_heart_at timestamptz;
begin
  if p_student_id is null or p_now is null then
    raise exception using
      errcode = '22023',
      message = 'invalid_heart_refresh_request';
  end if;

  select
    profile.tenant_id,
    profile.role,
    least(5, greatest(0, coalesce(profile.hearts, 5))) as hearts,
    coalesce(profile.hearts_updated_at, p_now) as hearts_updated_at
    into v_profile
    from public.profiles as profile
   where profile.id = p_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  v_hearts := v_profile.hearts;
  v_anchor := v_profile.hearts_updated_at;

  if v_hearts < 5 and p_now > v_anchor then
    v_regenerated := greatest(
      0,
      pg_catalog.floor(
        extract(epoch from (p_now - v_anchor)) / 1800
      )::integer
    );

    if v_regenerated > 0 then
      v_regenerated := least(v_regenerated, 5 - v_hearts);
      v_hearts := v_hearts + v_regenerated;
      v_anchor := case
        when v_hearts >= 5 then p_now
        else v_anchor + (v_regenerated * interval '30 minutes')
      end;
    end if;
  end if;

  if v_hearts is distinct from v_profile.hearts
     or v_anchor is distinct from v_profile.hearts_updated_at then
    update public.profiles
       set hearts = v_hearts,
           hearts_updated_at = v_anchor
     where id = p_student_id;
  end if;

  v_next_heart_at := case
    when v_hearts < 5 then v_anchor + interval '30 minutes'
    else null
  end;

  return pg_catalog.jsonb_build_object(
    'tenantId', v_profile.tenant_id,
    'hearts', v_hearts,
    'maxHearts', 5,
    'heartsUpdatedAt', v_anchor,
    'nextHeartAt', v_next_heart_at,
    'regenerated', v_regenerated
  );
end;
$$;


--
-- Name: refresh_teacher_closing_snapshot(text, uuid, text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_teacher_closing_snapshot(p_tenant text, p_teacher uuid, p_month text, p_allow_create boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_existing public.teacher_closings%ROWTYPE;
  v_paid_count integer := 0;
  v_paid_amount numeric := 0;
  v_carry_count integer := 0;
  v_carry_amount numeric := 0;
  v_adjustment_count integer := 0;
  v_adjustment_amount numeric := 0;
  v_lessons integer;
  v_total numeric;
  v_closing_id uuid;
BEGIN
  IF p_tenant IS NULL OR p_teacher IS NULL
     OR p_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023', MESSAGE = 'teacher_closing_refresh_invalid';
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles AS teacher
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = teacher.id
       AND membership.tenant_id = p_tenant
       AND membership.role = 'TEACHER'
       AND membership.status = 'ACTIVE'
     WHERE teacher.id = p_teacher
       AND teacher.role = 'TEACHER'
       AND teacher.tenant_id = p_tenant
       AND lower(coalesce(teacher.lifecycle_status, 'active'))
             NOT IN ('suspended', 'offboarded')
  ) THEN
    RETURN jsonb_build_object(
      'ok', false, 'state', 'invalid_scope', 'synced', false
    );
  END IF;

  PERFORM private.lock_teacher_closing_pair(
    p_tenant,
    p_month,
    p_teacher,
    NULL
  );

  SELECT count(*), round(coalesce(sum(payable.rate_efetivo), 0), 2)
    INTO v_paid_count, v_paid_amount
    FROM public.v_payable_class_logs AS payable
   WHERE payable.tenant_id = p_tenant
     AND payable.teacher_id = p_teacher
     AND to_char(payable.class_date, 'YYYY-MM') = p_month;

  SELECT count(*), round(coalesce(sum(carryover.amount), 0), 2)
    INTO v_carry_count, v_carry_amount
    FROM public.closing_carryovers AS carryover
    JOIN public.class_logs AS source_log
      ON source_log.id = carryover.class_log_id
     AND source_log.tenant_id = p_tenant
   WHERE carryover.teacher_id = p_teacher
     AND carryover.absorbed_month = p_month;

  SELECT count(*), round(coalesce(sum(adjustment.amount), 0), 2)
    INTO v_adjustment_count, v_adjustment_amount
    FROM public.closing_adjustments AS adjustment
   WHERE adjustment.tenant_id = p_tenant
     AND adjustment.teacher_id = p_teacher
     AND adjustment.month_year = p_month;

  v_lessons := v_paid_count + v_carry_count;
  v_total := round(
    v_paid_amount + v_carry_amount + v_adjustment_amount,
    2
  );

  SELECT closing.*
    INTO v_existing
    FROM public.teacher_closings AS closing
   WHERE closing.tenant_id = p_tenant
     AND closing.teacher_id = p_teacher
     AND closing.month_year = p_month
   ORDER BY closing.created_at
   LIMIT 1
   FOR UPDATE;

  IF NOT FOUND THEN
    IF NOT p_allow_create OR (
      v_paid_count = 0 AND v_carry_count = 0 AND v_adjustment_count = 0
    ) THEN
      RETURN jsonb_build_object(
        'ok', true, 'state', 'absent', 'synced', false,
        'total_lessons', v_lessons, 'total_amount', v_total
      );
    END IF;

    INSERT INTO public.teacher_closings (
      teacher_id, tenant_id, month_year, total_lessons, total_amount,
      status, period_start, period_end, created_at
    ) VALUES (
      p_teacher, p_tenant, p_month, v_lessons, v_total,
      'PENDENTE', (p_month || '-01')::date,
      (
        date_trunc('month', (p_month || '-01')::date) +
        interval '1 month - 1 day'
      )::date,
      now()
    )
    RETURNING id INTO v_closing_id;

    UPDATE public.closing_adjustments
       SET closing_synced = true
     WHERE tenant_id = p_tenant
       AND teacher_id = p_teacher
       AND month_year = p_month;
    RETURN jsonb_build_object(
      'ok', true, 'state', 'created', 'synced', true,
      'closing_id', v_closing_id,
      'total_lessons', v_lessons, 'total_amount', v_total
    );
  END IF;

  IF v_existing.status <> 'PENDENTE' THEN
    RETURN jsonb_build_object(
      'ok', true, 'state', 'frozen', 'synced', false,
      'closing_id', v_existing.id,
      'total_lessons', v_existing.total_lessons,
      'total_amount', v_existing.total_amount
    );
  END IF;

  IF v_existing.total_lessons IS NOT DISTINCT FROM v_lessons
     AND v_existing.total_amount IS NOT DISTINCT FROM v_total THEN
    UPDATE public.closing_adjustments
       SET closing_synced = true
     WHERE tenant_id = p_tenant
       AND teacher_id = p_teacher
       AND month_year = p_month
       AND closing_synced IS DISTINCT FROM true;
    RETURN jsonb_build_object(
      'ok', true, 'state', 'unchanged', 'synced', true,
      'closing_id', v_existing.id,
      'total_lessons', v_lessons, 'total_amount', v_total
    );
  END IF;

  UPDATE public.teacher_closings
     SET total_lessons = v_lessons,
         total_amount = v_total,
         updated_at = now(),
         teacher_confirmation_status = CASE
           WHEN teacher_confirmation_status = 'OK' THEN 'PENDENTE'
           ELSE teacher_confirmation_status
         END,
         teacher_confirmation_date = CASE
           WHEN teacher_confirmation_status = 'OK' THEN NULL
           ELSE teacher_confirmation_date
         END
   WHERE id = v_existing.id
     AND tenant_id = p_tenant
     AND teacher_id = p_teacher
     AND status = 'PENDENTE';

  UPDATE public.closing_adjustments
     SET closing_synced = true
   WHERE tenant_id = p_tenant
     AND teacher_id = p_teacher
     AND month_year = p_month;
  DELETE FROM public.automation_sent
   WHERE kind = 'MONTHLY_CLOSING'
     AND subject_id = p_teacher::text || ':' || p_month;

  RETURN jsonb_build_object(
    'ok', true, 'state', 'updated', 'synced', true,
    'closing_id', v_existing.id,
    'total_lessons', v_lessons, 'total_amount', v_total
  );
END;
$_$;


--
-- Name: reject_student_renewal_event_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reject_student_renewal_event_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  -- The only permitted rewrite is PostgreSQL's nested ON DELETE SET NULL
  -- action for the erasable live student reference.  Every ledger/snapshot
  -- field must remain byte-for-byte equivalent, and a direct UPDATE still
  -- enters at trigger depth 1 and is rejected.
  if tg_op = 'UPDATE'
     and pg_catalog.pg_trigger_depth() > 1
     and old.student_id is not null
     and new.student_id is null
     and (pg_catalog.to_jsonb(new) - 'student_id')
           is not distinct from
         (pg_catalog.to_jsonb(old) - 'student_id')
  then
    return new;
  end if;

  raise exception using
    errcode = '55000',
    message = 'student_renewal_events_are_immutable';
end;
$$;


--
-- Name: release_enrollment_slot_after_booking_end(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.release_enrollment_slot_after_booking_end() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.enrollment_offer_slot_id is null
    or pg_catalog.upper(coalesce(old.status, 'SCHEDULED')) <> 'SCHEDULED'
  then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'DELETE' then
    update private.enrollment_offer_schedule_slots as slot
    set status = 'RELEASED',
        reserved_by = null,
        reserved_at = null,
        reservation_expires_at = null,
        materialized_booking_id = null,
        updated_at = now()
    where slot.id = old.enrollment_offer_slot_id
      and slot.offer_id = old.enrollment_offer_id
      and slot.materialized_booking_id = old.id;
    return old;
  end if;

  if pg_catalog.upper(coalesce(new.status, 'SCHEDULED')) <> 'SCHEDULED'
    or new.enrollment_offer_slot_id is distinct from old.enrollment_offer_slot_id
    or new.enrollment_offer_id is distinct from old.enrollment_offer_id
  then
    update private.enrollment_offer_schedule_slots as slot
    set status = 'RELEASED',
        reserved_by = null,
        reserved_at = null,
        reservation_expires_at = null,
        materialized_booking_id = null,
        updated_at = now()
    where slot.id = old.enrollment_offer_slot_id
      and slot.offer_id = old.enrollment_offer_id
      and slot.materialized_booking_id = old.id;
  end if;
  return new;
end;
$$;


--
-- Name: render_conflict_teacher_alert_message(text, text, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.render_conflict_teacher_alert_message(p_teacher_name text, p_student_name text, p_class_date date, p_class_time text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_teacher_name text := pg_catalog.regexp_replace(
    coalesce(p_teacher_name, ''),
    '^[[:space:]]+|[[:space:]]+$',
    '',
    'g'
  );
  v_teacher_first_name text;
  v_student_name text := pg_catalog.regexp_replace(
    coalesce(p_student_name, ''),
    '^[[:space:]]+|[[:space:]]+$',
    '',
    'g'
  );
  v_class_date text := case
    when p_class_date is null then 'data informada'
    else pg_catalog.to_char(p_class_date, 'DD/MM')
  end;
  v_class_time text := pg_catalog.left(
    pg_catalog.regexp_replace(
      coalesce(p_class_time, ''),
      '^[[:space:]]+|[[:space:]]+$',
      '',
      'g'
    ),
    5
  );
begin
  v_teacher_first_name := nullif(pg_catalog.split_part(
    pg_catalog.regexp_replace(
      v_teacher_name,
      '[[:space:]]+',
      ' ',
      'g'
    ),
    ' ',
    1
  ), '');

  return
    'Oi, ' || coalesce(v_teacher_first_name, 'professor') ||
    '! Aqui é da coordenação da escola.' || E'\n\n' ||
    'Recebemos uma divergência sobre a aula de ' || v_class_date ||
    case
      when v_class_time = '' then ''
      else ' às ' || v_class_time
    end ||
    ' com ' || coalesce(nullif(v_student_name, ''), 'o(a) aluno(a)') ||
    '.' || E'\n' ||
    'Pode nos contar como foi essa aula? Enquanto analisamos, somente esta aula fica em revisão.';
end;
$_$;


--
-- Name: render_lesson_notification_message(text, text, text, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.render_lesson_notification_message(p_template text, p_student_name text, p_class_time text, p_teacher_name text, p_tenant_name text, p_class_link text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_template text := private.safe_notification_text(p_template, 4096);
  v_message text;
begin
  if v_template = '' then
    v_template := $default_template$Oi {student_name}, tudo bem? 👋

Lembrando que nossa aula começa em 30 minutos, às *{class_time}*.

{class_link}

Te espero! 🐺$default_template$;
  end if;

  v_message := pg_catalog.replace(
    v_template,
    '{student_name}',
    coalesce(p_student_name, '')
  );
  v_message := pg_catalog.replace(
    v_message,
    '{class_time}',
    coalesce(p_class_time, '')
  );
  v_message := pg_catalog.replace(
    v_message,
    '{teacher_name}',
    coalesce(p_teacher_name, '')
  );
  v_message := pg_catalog.replace(
    v_message,
    '{tenant_name}',
    coalesce(p_tenant_name, '')
  );
  v_message := pg_catalog.replace(
    v_message,
    '{class_link}',
    coalesce(p_class_link, '')
  );
  v_message := pg_catalog.regexp_replace(
    v_message,
    '\{[A-Za-z0-9_]+\}',
    '',
    'g'
  );
  return pg_catalog.left(pg_catalog.btrim(v_message), 4096);
end;
$_$;


--
-- Name: requeue_prepared_management_payment_notification(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.requeue_prepared_management_payment_notification(p_attempt_id uuid, p_reason text, p_notification_kind text DEFAULT NULL::text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.management_payment_notification_outbox as outbox
  set notification_kind = coalesce(p_notification_kind, outbox.notification_kind),
      status = 'PENDING',
      claim_token = null,
      lease_expires_at = null,
      configured_destination_snapshot = null,
      provider_destination = null,
      provider_instance_name = null,
      provider_integration_id = null,
      provider_integration_version = null,
      provider_endpoint_hash = null,
      provider_credential_hash = null,
      message_body = null,
      source_snapshot = null,
      source_snapshot_hash = null,
      snapshot_hash = null,
      last_error = pg_catalog.left(coalesce(p_reason, 'prepared_retry'), 500),
      updated_at = pg_catalog.now()
  where outbox.id = p_attempt_id
    and outbox.status in ('CLAIMED', 'PREPARED')
    and outbox.submit_attempt_count = 0
$$;


--
-- Name: reschedule_participants_are_active(uuid, text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reschedule_participants_are_active(p_reschedule_id uuid, p_tenant_id text, p_teacher_id uuid, p_student_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.reschedules as reschedule
      join public.profiles as teacher
        on teacher.id = reschedule.teacher_id
      join public.tenant_memberships as teacher_membership
        on teacher_membership.user_id = teacher.id
       and teacher_membership.tenant_id = reschedule.tenant_id
       and teacher_membership.role = 'TEACHER'
       and teacher_membership.status = 'ACTIVE'
      join public.profiles as student
        on student.id = reschedule.student_id
      join public.tenant_memberships as student_membership
        on student_membership.user_id = student.id
       and student_membership.tenant_id = reschedule.tenant_id
       and student_membership.role = 'STUDENT'
       and student_membership.status = 'ACTIVE'
     where reschedule.id = p_reschedule_id
       and reschedule.tenant_id = p_tenant_id
       and reschedule.teacher_id = p_teacher_id
       and reschedule.student_id = p_student_id
       and reschedule.used_at is null
       and pg_catalog.lower(pg_catalog.btrim(coalesce(
             teacher.lifecycle_status,
             ''
           ))) = 'active'
       and pg_catalog.lower(pg_catalog.btrim(coalesce(
             student.lifecycle_status,
             ''
           ))) = 'active'
  );
$$;


--
-- Name: reserve_enrollment_offer_schedule(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reserve_enrollment_offer_schedule(p_offer_id uuid, p_student_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_offer record;
  v_count integer;
  v_first_billing_date date;
  v_today date := (pg_catalog.clock_timestamp()
    at time zone 'America/Sao_Paulo')::date;
begin
  if p_student_id is null then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end if;

  perform private.lock_and_validate_enrollment_schedule(
    p_offer_id,
    p_student_id
  );

  select
    offer.processing_by,
    offer.processing_state,
    offer.consumed_at,
    offer.consumed_by,
    offer.revoked_at,
    offer.expires_at,
    offer.payload
  into v_offer
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.kind = 'ENROLLMENT'
  for update;

  if v_offer.revoked_at is not null
    or (v_offer.consumed_at is null and v_offer.expires_at <= now())
  then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end if;
  begin
    v_first_billing_date := (v_offer.payload ->> 'firstBillingDate')::date;
  exception when others then
    raise exception 'invalid_enrollment_billing_period' using errcode = '22023';
  end;
  if v_first_billing_date < v_today then
    raise exception 'enrollment_first_billing_date_passed'
      using errcode = '22023';
  end if;
  if v_offer.processing_by is not null
    and v_offer.processing_by is distinct from p_student_id
    and v_offer.processing_state <> 'COMPLETED'
  then
    raise exception 'enrollment_schedule_reserved' using errcode = '23P01';
  end if;

  if exists (
    select 1
    from private.enrollment_offer_schedule_slots as slot
    where slot.offer_id = p_offer_id
      and (
        slot.status = 'MATERIALIZED'
        and slot.reserved_by is distinct from p_student_id
        or slot.status = 'RESERVED'
        and slot.reserved_by is distinct from p_student_id
      )
  ) then
    raise exception 'enrollment_schedule_reserved' using errcode = '23P01';
  end if;

  update private.enrollment_offer_schedule_slots as slot
  set status = 'RESERVED',
      reserved_by = p_student_id,
      reserved_at = case
        when slot.status = 'RESERVED' and slot.reserved_by = p_student_id
          then coalesce(slot.reserved_at, now())
        else now()
      end,
      reservation_expires_at = least(
        v_offer.expires_at,
        now() + interval '30 minutes'
      ),
      materialized_booking_id = null,
      updated_at = now()
  where slot.offer_id = p_offer_id
    and slot.status in ('OFFERED', 'RELEASED', 'RESERVED');

  select pg_catalog.count(*)::integer
  into v_count
  from private.enrollment_offer_schedule_slots as slot
  where slot.offer_id = p_offer_id
    and slot.reserved_by = p_student_id
    and slot.status in ('RESERVED', 'MATERIALIZED');
  if v_count <> (
    select (offer.payload ->> 'classesPerWeek')::integer
    from public.offers as offer
    where offer.id = p_offer_id
  ) then
    raise exception 'enrollment_schedule_changed' using errcode = '23P01';
  end if;
end;
$$;


--
-- Name: resolve_whatsapp_contact(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.resolve_whatsapp_contact(p_tenant_id text, p_phone text) RETURNS TABLE(contact_kind text, display_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_phone text := pg_catalog.regexp_replace(
    coalesce(p_phone, ''),
    '\D',
    '',
    'g'
  );
  v_suffix text;
  v_count bigint;
  v_kind text;
  v_name text;
begin
  if pg_catalog.char_length(v_phone) not between 10 and 15 then
    return query select 'unknown'::text, null::text;
    return;
  end if;
  v_suffix := pg_catalog.right(v_phone, 8);

  -- Um perfil ativo é a identidade mais forte: aluno/professor já pertence à
  -- escola. Mais de um perfil no mesmo telefone é ambíguo e não é adivinhado.
  select count(*), min(lower(profile.role)), min(
    nullif(pg_catalog.btrim(profile.full_name), '')
  )
  into v_count, v_kind, v_name
  from public.profiles as profile
  where profile.tenant_id = p_tenant_id
    and profile.role in ('STUDENT', 'TEACHER')
    and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) = 'active'
    and pg_catalog.right(
      pg_catalog.regexp_replace(coalesce(profile.phone, ''), '\D', '', 'g'),
      8
    ) = v_suffix
    and private.commercial_phones_match(profile.phone, v_phone);

  if v_count = 1 then
    return query select v_kind, v_name;
    return;
  elsif v_count > 1 then
    return query select 'unknown'::text, null::text;
    return;
  end if;

  select count(*), min(nullif(pg_catalog.btrim(lead.name), ''))
  into v_count, v_name
  from public.crm_leads as lead
  where lead.tenant_id = p_tenant_id
    and pg_catalog.right(
      pg_catalog.regexp_replace(coalesce(lead.phone, ''), '\D', '', 'g'),
      8
    ) = v_suffix
    and private.commercial_phones_match(lead.phone, v_phone);

  if v_count = 1 then
    return query select 'lead'::text, v_name;
    return;
  elsif v_count > 1 then
    return query select 'unknown'::text, null::text;
    return;
  end if;

  select count(*), min(nullif(pg_catalog.btrim(application.name), ''))
  into v_count, v_name
  from public.job_applications as application
  where application.tenant_id = p_tenant_id
    and pg_catalog.right(
      pg_catalog.regexp_replace(
        coalesce(application.whatsapp, ''),
        '\D',
        '',
        'g'
      ),
      8
    ) = v_suffix
    and private.commercial_phones_match(application.whatsapp, v_phone);

  if v_count = 1 then
    return query select 'candidate'::text, v_name;
  else
    return query select 'unknown'::text, null::text;
  end if;
end;
$$;


--
-- Name: saas_owner_identity_is_dormant_for_activation(uuid, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.saas_owner_identity_is_dormant_for_activation(p_current_checkout_id uuid, p_owner_user_id uuid, p_marker_checkout_id uuid, p_owner_email text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select p_current_checkout_id is not null
    and p_owner_user_id is not null
    and p_marker_checkout_id is not null
    and p_marker_checkout_id <> p_current_checkout_id
    and p_owner_email is not null
    and exists (
      select 1
        from public.saas_owner_activation_attempts as origin_attempt
        join public.saas_checkout_intents as origin_checkout
          on origin_checkout.id = origin_attempt.checkout_id
       where origin_attempt.checkout_id = p_marker_checkout_id
         and origin_attempt.owner_email = p_owner_email
         and lower(pg_catalog.btrim(origin_checkout.owner_email)) = p_owner_email
         and origin_checkout.tenant_id = origin_attempt.tenant_id
         and origin_attempt.status in ('FAILED', 'SUPPRESSED')
         and origin_attempt.submit_attempt_count = 0
         and origin_attempt.provider_payload is null
         and origin_attempt.provider_payload_sha256 is null
         and origin_attempt.provider_payload_staged_at is null
         and origin_attempt.submitted_at is null
         and origin_attempt.provider_message_id is null
         and (
           origin_attempt.owner_user_id is null
           or origin_attempt.owner_user_id = p_owner_user_id
         )
         and (
           origin_attempt.initial_owner_user_id is null
           or origin_attempt.initial_owner_user_id = p_owner_user_id
         )
         and (
           origin_checkout.status not in (
             'PAID', 'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED'
           )
           or not private.tenant_is_operational(origin_attempt.tenant_id)
         )
    )
    and not exists (
      select 1
        from public.saas_owner_activation_attempts as delivered_attempt
       where delivered_attempt.checkout_id <> p_current_checkout_id
         and (
           delivered_attempt.owner_user_id = p_owner_user_id
           or delivered_attempt.initial_owner_user_id = p_owner_user_id
         )
         and (
           delivered_attempt.submit_attempt_count > 0
           or delivered_attempt.status in ('SUBMITTING', 'SENT', 'UNKNOWN')
         )
    )
    and not exists (
      select 1
        from public.tenant_memberships as membership
       where membership.user_id = p_owner_user_id
         and membership.status = 'ACTIVE'
    )
    and not exists (
      select 1
        from public.profiles as profile
       where profile.id = p_owner_user_id
         and not (
           profile.tenant_id is null
           and profile.role = 'STUDENT'
           and profile.status_financial = 'PENDING'
           and lower(pg_catalog.btrim(coalesce(
             profile.lifecycle_status,
             ''
           ))) = 'active'
         )
    )
    and not exists (
      select 1 from public.hub_accounts as account
       where account.owner_user_id = p_owner_user_id
    )
    and not exists (
      select 1 from public.hub_memberships as membership
       where membership.user_id = p_owner_user_id
    )
    and not exists (
      select 1 from auth.sessions as session
       where session.user_id = p_owner_user_id
    )
    and not exists (
      select 1 from auth.mfa_factors as factor
       where factor.user_id = p_owner_user_id
    )
    and exists (
      select 1 from auth.users as auth_user
       where auth_user.id = p_owner_user_id
         and auth_user.deleted_at is null
         and auth_user.last_sign_in_at is null
    );
$$;


--
-- Name: saas_provider_event_is_terminal(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.saas_provider_event_is_terminal(p_event_name text) RETURNS boolean
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select upper(pg_catalog.btrim(coalesce(p_event_name, ''))) in (
    'PAYMENT_DELETED',
    'PAYMENT_REFUNDED',
    'PAYMENT_PARTIALLY_REFUNDED',
    'PAYMENT_RECEIVED_IN_CASH_UNDONE',
    'PAYMENT_CHARGEBACK_REQUESTED',
    'PAYMENT_BANK_SLIP_CANCELLED',
    'PAYMENT_CREDIT_CARD_CAPTURE_REFUSED',
    'PAYMENT_REPROVED_BY_RISK_ANALYSIS',
    'SUBSCRIPTION_INACTIVATED',
    'SUBSCRIPTION_DELETED'
  );
$$;


--
-- Name: saas_provider_event_rank(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.saas_provider_event_rank(p_event_name text) RETURNS integer
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case upper(pg_catalog.btrim(coalesce(p_event_name, '')))
    when 'PAYMENT_DELETED' then 100
    when 'PAYMENT_REFUNDED' then 100
    when 'PAYMENT_RECEIVED_IN_CASH_UNDONE' then 100
    when 'PAYMENT_CHARGEBACK_REQUESTED' then 100
    when 'SUBSCRIPTION_INACTIVATED' then 100
    when 'SUBSCRIPTION_DELETED' then 100
    when 'PAYMENT_PARTIALLY_REFUNDED' then 95
    when 'PAYMENT_REFUND_IN_PROGRESS' then 90
    when 'PAYMENT_BANK_SLIP_CANCELLED' then 85
    when 'PAYMENT_CREDIT_CARD_CAPTURE_REFUSED' then 85
    when 'PAYMENT_REPROVED_BY_RISK_ANALYSIS' then 85
    when 'PAYMENT_RECEIVED_IN_CASH' then 80
    when 'PAYMENT_RECEIVED' then 80
    when 'PAYMENT_CONFIRMED' then 60
    when 'PAYMENT_OVERDUE' then 40
    else 10
  end;
$$;


--
-- Name: saas_provider_event_terminates_checkout(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.saas_provider_event_terminates_checkout(p_event_name text) RETURNS boolean
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select upper(pg_catalog.btrim(coalesce(p_event_name, ''))) in (
    'PAYMENT_DELETED',
    'PAYMENT_REFUNDED',
    'PAYMENT_PARTIALLY_REFUNDED',
    'PAYMENT_RECEIVED_IN_CASH_UNDONE',
    'PAYMENT_CHARGEBACK_REQUESTED',
    'SUBSCRIPTION_INACTIVATED',
    'SUBSCRIPTION_DELETED'
  );
$$;


--
-- Name: safe_notification_text(text, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.safe_notification_text(p_value text, p_maximum_length integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.left(
    pg_catalog.btrim(
      pg_catalog.regexp_replace(
        pg_catalog.regexp_replace(
          coalesce(p_value, ''),
          '[[:cntrl:]<>*_`~]',
          ' ',
          'g'
        ),
        '[[:space:]]+',
        ' ',
        'g'
      )
    ),
    greatest(0, least(
      coalesce(p_maximum_length, 0),
      4096
    ))
  )
$$;


--
-- Name: safe_student_complementary_content(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.safe_student_complementary_content(p_type text, p_content text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_content jsonb;
begin
  begin
    v_content := p_content::jsonb;
  exception
    when others then
      return pg_catalog.to_jsonb(p_content);
  end;

  if pg_catalog.jsonb_typeof(v_content) is distinct from 'object' then
    return pg_catalog.to_jsonb(p_content);
  end if;

  if p_type in ('quiz', 'grammar') then
    return private.strip_student_answer_keys(v_content);
  end if;

  return v_content;
end;
$$;


--
-- Name: schedule_teacher_training(text, uuid, text, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schedule_teacher_training(p_tenant text, p_actor uuid, p_request text, p_trainer uuid, p_trainee uuid, p_start timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare t public.profiles%rowtype; n public.profiles%rowtype; s public.teacher_training_sessions%rowtype; v_token text; v_phone text; v_link text;
begin
  if length(coalesce(p_request,'')) not between 8 and 200 or p_trainer=p_trainee then raise exception 'Pedido inválido: selecione dois teachers diferentes.'; end if;
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('training-request:'||p_tenant||':'||p_request,0));
  select * into s from public.teacher_training_sessions where tenant_id=p_tenant and request_id=p_request;
  if found then
    if s.trainer_id<>p_trainer or s.trainee_id<>p_trainee or s.starts_at<>p_start then raise exception 'Este pedido já foi utilizado para outro treinamento.'; end if;
    return jsonb_build_object('ok',true,'id',s.id,'status',s.status,'idempotent',true);
  end if;
  perform private.validate_training_slot(p_tenant,p_trainer,p_trainee,p_start);
  select * into t from public.profiles where id=p_trainer;
  select * into n from public.profiles where id=p_trainee;
  v_phone := regexp_replace(coalesce(nullif(n.attendance_phone,''),n.phone,''),'[^0-9]','','g');
  if length(v_phone) in (10,11) then v_phone:='55'||v_phone; end if;
  if length(v_phone) not between 12 and 15 then raise exception 'O teacher que receberá o treinamento precisa cadastrar seu WhatsApp.'; end if;
  if nullif(btrim(t.meeting_link),'') is not null and btrim(t.meeting_link) !~ '^https://[^[:space:]]+$' then raise exception 'O link da sala cadastrado precisa começar com https://.'; end if;
  insert into public.teacher_training_sessions(tenant_id,trainer_id,trainee_id,trainer_name,trainee_name,trainee_phone,meeting_link,starts_at,ends_at,request_id,created_by,test_fixture)
  values(p_tenant,p_trainer,p_trainee,t.full_name,n.full_name,v_phone,coalesce(btrim(t.meeting_link),''),p_start,p_start+interval '30 minutes',p_request,p_actor,coalesce(t.is_test_account,false) or coalesce(n.is_test_account,false)) returning * into s;
  v_token:=encode(extensions.gen_random_bytes(32),'hex');
  insert into private.teacher_training_invite_tokens values(encode(extensions.digest(v_token,'sha256'),'hex'),s.id,p_start);
  v_link:='https://api.wisewolflanguage.com.br/functions/v1/teacher-training-invite?token='||v_token;
  if not s.test_fixture then
    insert into public.notification_queue(tenant_id,student_name,student_phone,message_body,scheduled_for,source_type,source_id,notification_kind,idempotency_key)
    values(p_tenant,n.full_name,v_phone,'Olá, '||n.full_name||'! Você recebeu um convite para treinamento com '||t.full_name||' em '||to_char(p_start at time zone 'America/Sao_Paulo','DD/MM/YYYY "às" HH24:MI')||' (Brasília), duração de 30 minutos. Confira e aceite pelo link: '||v_link,now(),'teacher_training',s.id,'TEACHER_TRAINING_INVITE','teacher-training-invite:'||s.id);
  end if;
  return jsonb_build_object('ok',true,'id',s.id,'status',s.status,'invitation_queued',not s.test_fixture);
end;
$_$;


--
-- Name: scope_whatsapp_instance_to_tenant(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.scope_whatsapp_instance_to_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  active_tenant text;
BEGIN
  active_tenant := private.active_tenant_id(NEW.user_id);
  IF active_tenant IS NULL THEN
    RAISE EXCEPTION 'active_tenant_membership_required' USING ERRCODE = '42501';
  END IF;
  IF NEW.tenant_id IS NULL THEN
    NEW.tenant_id := active_tenant;
  ELSIF NEW.tenant_id IS DISTINCT FROM active_tenant THEN
    RAISE EXCEPTION 'cross_tenant_whatsapp_instance' USING ERRCODE = '42501';
  END IF;
  NEW.api_key := NULL;
  RETURN NEW;
END;
$$;


--
-- Name: secure_trial_actor_context(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.secure_trial_actor_context() RETURNS TABLE(actor_id uuid, tenant_id text, actor_role text)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select
    profile.id,
    membership.tenant_id,
    case
      when profile.role = 'SUPER_ADMIN' then 'SUPER_ADMIN'
      else membership.role
    end
  from public.profiles as profile
  join public.tenant_memberships as membership
    on membership.user_id = profile.id
   and membership.tenant_id = private.active_tenant_id(profile.id)
   and membership.status = 'ACTIVE'
  where profile.id = (select auth.uid())
    and lower(trim(coalesce(profile.lifecycle_status, 'active'))) = 'active'
  limit 1;
$$;


--
-- Name: secure_trial_payload_fingerprint(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.secure_trial_payload_fingerprint(p_payload jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(coalesce(p_payload, 'null'::jsonb)::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: secure_trial_portal_origin(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.secure_trial_portal_origin(p_tenant_id text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  SELECT coalesce(
    CASE
      WHEN tenant.custom_domain_verified IS true
       AND lower(trim(coalesce(tenant.custom_domain, ''))) ~
         '^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$'
      THEN 'https://' || lower(trim(tenant.custom_domain))
    END,
    CASE
      WHEN lower(trim(coalesce(tenant.domain, ''))) ~
         '^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$'
      THEN 'https://' || lower(trim(tenant.domain))
    END,
    CASE
      WHEN lower(trim(coalesce(tenant.slug, ''))) IN ('wisewolf', 'system')
        OR tenant.id = 'school-wise-wolf'
      THEN 'https://system.wisewolflanguage.com.br'
      WHEN lower(trim(coalesce(tenant.slug, ''))) ~
         '^[a-z0-9](?:[a-z0-9-]*[a-z0-9])$'
      THEN 'https://' || lower(trim(tenant.slug)) ||
           '.wisewolflanguage.com.br'
    END,
    'https://system.wisewolflanguage.com.br'
  )
  FROM public.tenants AS tenant
  WHERE tenant.id = p_tenant_id;
$_$;


--
-- Name: secure_trial_schedule_conflict(text, uuid, timestamp with time zone, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.secure_trial_schedule_conflict(p_tenant_id text, p_teacher_id uuid, p_start_time timestamp with time zone, p_exclude_appointment_id uuid DEFAULT NULL::uuid, p_exclude_enrollment_link_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $_$
  select
    p_tenant_id is null
    or p_teacher_id is null
    or p_start_time is null
    or exists (
      select 1
        from public.appointments as appointment
       where appointment.tenant_id = p_tenant_id
         and appointment.id is distinct from p_exclude_appointment_id
         and (
           appointment.teacher_id = p_teacher_id
           or appointment.professor_id = p_teacher_id
         )
         and lower(coalesce(appointment.status, '')) in (
           'scheduled', 'confirmed'
         )
         and appointment.start_time > p_start_time - interval '30 minutes'
         and appointment.start_time < p_start_time + interval '30 minutes'
    )
    or exists (
      select 1
        from public.bookings as booking
       where booking.tenant_id = p_tenant_id
         and booking.teacher_id = p_teacher_id
         and lower(coalesce(booking.status, 'scheduled')) not in (
           'cancelled', 'canceled', 'inactive'
         )
         and public.dow_name_to_int(booking.day_of_week) = extract(
           dow from (p_start_time at time zone 'America/Sao_Paulo')::date
         )::integer
         and (
           booking.date is null
           or booking.date =
             (p_start_time at time zone 'America/Sao_Paulo')::date
         )
         and case
           when trim(coalesce(booking.time_slot, '')) ~
                '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
           then abs(extract(epoch from (
             left(trim(booking.time_slot), 5)::time -
             (p_start_time at time zone 'America/Sao_Paulo')::time
           ))) < 1800
           else false
         end
    )
    or exists (
      select 1
        from private.vendor_trial_teacher_requests as request
       where request.tenant_id = p_tenant_id
         and request.target_teacher_id = p_teacher_id
         and (
           p_exclude_enrollment_link_id is null
           or request.enrollment_link_id is distinct from
                p_exclude_enrollment_link_id
         )
         and request.status in ('AWAITING_STUDENT', 'AWAITING_TEACHER')
         and request.slot_start > p_start_time - interval '30 minutes'
         and request.slot_start < p_start_time + interval '30 minutes'
    );
$_$;


--
-- Name: set_single_primary_tenant_membership(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.set_single_primary_tenant_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  NEW.updated_at := now();

  IF NEW.is_primary IS TRUE AND NEW.status = 'ACTIVE' THEN
    UPDATE public.tenant_memberships
    SET is_primary = false,
        updated_at = now()
    WHERE user_id = NEW.user_id
      AND id <> NEW.id
      AND tenant_id IS DISTINCT FROM NEW.tenant_id
      AND is_primary IS TRUE;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: strip_student_answer_keys(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.strip_student_answer_keys(p_value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
  v_key text;
  v_child jsonb;
begin
  if p_value is null then
    return null;
  end if;

  if pg_catalog.jsonb_typeof(p_value) = 'object' then
    v_result := '{}'::jsonb;
    for v_key, v_child in
      select entry.key, entry.value
        from pg_catalog.jsonb_each(p_value) as entry(key, value)
    loop
      if v_key not in (
        'correct',
        'correctIndex',
        'correct_option_index',
        'exp',
        'explanation',
        'explanation_pt',
        'feedback'
      ) then
        v_result := v_result || pg_catalog.jsonb_build_object(
          v_key,
          private.strip_student_answer_keys(v_child)
        );
      end if;
    end loop;
    return v_result;
  elsif pg_catalog.jsonb_typeof(p_value) = 'array' then
    select coalesce(
             pg_catalog.jsonb_agg(
               private.strip_student_answer_keys(item.value)
               order by item.ordinality
             ),
             '[]'::jsonb
           )
      into v_result
      from pg_catalog.jsonb_array_elements(p_value)
           with ordinality as item(value, ordinality);
    return v_result;
  end if;

  return p_value;
end;
$$;


--
-- Name: student_card_schedule_claims_exact(text, uuid, uuid, text, date, date, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_claims_exact(p_tenant_id text, p_student_id uuid, p_offer_id uuid, p_subscription_id text, p_old_due_date date, p_target_due_date date, p_target_claim_id uuid, p_target_claim_fingerprint text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (
    select pg_catalog.count(*) = 1
      from public.asaas_student_billing_period_claims as claim
     where claim.tenant_id = p_tenant_id
       and claim.student_id = p_student_id
       and claim.due_date = p_old_due_date
       and claim.source = 'SUBSCRIPTION'
       and claim.source_key = 'subscription:' || p_offer_id::text
       and claim.status = 'BOUND'
       and claim.provider_entity_id = p_subscription_id
  )
  and exists (
    select 1
      from public.asaas_student_billing_period_claims as claim
     where claim.id = p_target_claim_id
       and claim.tenant_id = p_tenant_id
       and claim.student_id = p_student_id
       and claim.due_date = p_target_due_date
       and claim.source = 'SUBSCRIPTION'
       and claim.source_key = 'subscription:' || p_offer_id::text
       and claim.request_fingerprint = p_target_claim_fingerprint
       and claim.status = 'BOUND'
       and claim.provider_entity_id = p_subscription_id
  );
$$;


--
-- Name: student_card_schedule_local_guard_baseline(text, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_local_guard_baseline(p_tenant_id text, p_student_id uuid, p_local_payment_id uuid, p_payment_id text, p_subscription_id text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_build_object(
    'subscriptionCreatedTriageEventIds', coalesce((
      select pg_catalog.jsonb_agg(
               inbox.provider_event_id order by inbox.provider_event_id
             )
        from public.asaas_webhook_inbox as inbox
       where inbox.status = 'TRIAGE'
         and inbox.event_name = 'SUBSCRIPTION_CREATED'
         and (
           inbox.provider_entity_id = p_subscription_id
           or inbox.payload #>> '{subscription,id}' = p_subscription_id
         )
    ), '[]'::jsonb),
    'subscriptionCreatedOpenIssueIds', coalesce((
      select pg_catalog.jsonb_agg(issue.id::text order by issue.id::text)
        from public.asaas_reconciliation_issues as issue
       where issue.resolved_at is null
         and issue.source = 'WEBHOOK'
         and issue.kind = 'WEBHOOK_TRIAGE'
         and issue.details ->> 'eventName' = 'SUBSCRIPTION_CREATED'
         and (
           issue.tenant_id = p_tenant_id
           or issue.tenant_id is null
         )
         and (
           issue.provider_entity_id = p_subscription_id
           or issue.details ->> 'entityId' = p_subscription_id
         )
    ), '[]'::jsonb)
  );
$$;


--
-- Name: student_card_schedule_local_guard_clear(text, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_local_guard_clear(p_tenant_id text, p_student_id uuid, p_local_payment_id uuid, p_payment_id text, p_subscription_id text, p_baseline jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_typeof(p_baseline) = 'object'
  and pg_catalog.jsonb_typeof(
        p_baseline -> 'subscriptionCreatedTriageEventIds'
      ) = 'array'
  and pg_catalog.jsonb_typeof(
        p_baseline -> 'subscriptionCreatedOpenIssueIds'
      ) = 'array'
  and not exists (
    select 1
      from public.asaas_webhook_inbox as inbox
     where (
       inbox.provider_entity_id in (p_payment_id, p_subscription_id)
       or inbox.payload #>> '{payment,id}' = p_payment_id
       or inbox.payload #>> '{payment,subscription}' = p_subscription_id
       or inbox.payload #>> '{subscription,id}' = p_subscription_id
     )
       and (
         inbox.status in ('RECEIVED', 'PROCESSING', 'RETRY', 'DEAD_LETTER')
         or (
           inbox.status = 'TRIAGE'
           and not (
             inbox.event_name = 'SUBSCRIPTION_CREATED'
             and (
               inbox.provider_entity_id = p_subscription_id
               or inbox.payload #>> '{subscription,id}' = p_subscription_id
             )
             and exists (
               select 1
                 from pg_catalog.jsonb_array_elements_text(
                   p_baseline -> 'subscriptionCreatedTriageEventIds'
                 ) as allowed(event_id)
                where allowed.event_id = inbox.provider_event_id
             )
           )
         )
       )
  )
  and not exists (
    select 1
      from public.asaas_reconciliation_issues as issue
     where issue.resolved_at is null
       and (
         issue.tenant_id = p_tenant_id
         or issue.tenant_id is null
       )
       and (
         issue.provider_entity_id in (p_payment_id, p_subscription_id)
         or issue.local_entity_id in (
           p_student_id::text, p_local_payment_id::text
         )
         or issue.details ->> 'entityId' in (p_payment_id, p_subscription_id)
         or issue.details ->> 'paymentId' = p_payment_id
         or issue.details ->> 'subscriptionId' = p_subscription_id
       )
       and not exists (
         select 1
           from pg_catalog.jsonb_array_elements_text(
             p_baseline -> 'subscriptionCreatedOpenIssueIds'
           ) as allowed(issue_id)
          where allowed.issue_id = issue.id::text
       )
  )
  and not exists (
    select 1
      from public.reconciliation_issues as issue
     where issue.tenant_id = p_tenant_id
       and issue.student_payment_id = p_local_payment_id
       and coalesce(issue.resolved, false) is false
       and issue.resolved_at is null
  );
$$;


--
-- Name: student_card_schedule_local_payment_exact(uuid, text, uuid, text, text, date, numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_local_payment_exact(p_local_payment_id uuid, p_tenant_id text, p_student_id uuid, p_payment_id text, p_customer_id text, p_due_date date, p_value numeric) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (
    select pg_catalog.count(*) = 1
      from public.student_payments as provider_binding
     where nullif(pg_catalog.btrim(coalesce(
             provider_binding.asaas_payment_id, ''
           )), '') = p_payment_id
        or nullif(pg_catalog.btrim(coalesce(
             provider_binding.asaas_id, ''
           )), '') = p_payment_id
  )
  and exists (
    select 1
      from public.student_payments as payment
     where payment.id = p_local_payment_id
       and payment.tenant_id = p_tenant_id
       and payment.student_id = p_student_id
       and nullif(pg_catalog.btrim(coalesce(
             payment.asaas_payment_id, ''
           )), '') = p_payment_id
       and (
         nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') is null
         or nullif(pg_catalog.btrim(payment.asaas_id), '') = p_payment_id
       )
       and nullif(pg_catalog.btrim(coalesce(
             payment.provider_customer_id, ''
           )), '') = p_customer_id
       and payment.due_date = p_due_date
       and payment.value = p_value
       and payment.amount_cents = pg_catalog.round(p_value * 100)::bigint
       and pg_catalog.upper(pg_catalog.btrim(coalesce(
             payment.billing_type, ''
           ))) = 'CREDIT_CARD'
       and (
         nullif(pg_catalog.btrim(coalesce(payment.payment_method, '')), '')
           is null
         or pg_catalog.upper(pg_catalog.btrim(payment.payment_method)) =
           'CREDIT_CARD'
       )
       and pg_catalog.upper(pg_catalog.btrim(coalesce(
             payment.payment_type, ''
           ))) = 'SUBSCRIPTION'
       and pg_catalog.upper(pg_catalog.btrim(coalesce(
             payment.status, ''
           ))) = 'PENDING'
       and pg_catalog.upper(pg_catalog.btrim(coalesce(
             payment.provider_status, ''
           ))) = 'PENDING'
       and payment.payment_date is null
       and payment.paid_at is null
       and payment.credited_at is null
       and coalesce(payment.refunded_amount, 0) = 0
       and coalesce(payment.ledger_entry_created, false) is false
       and not exists (
         select 1
           from public.financial_transactions as ledger_row
          where ledger_row.student_payment_id = payment.id
             or ledger_row.refund_student_payment_id = payment.id
       )
  );
$$;


--
-- Name: student_card_schedule_membership_exact(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_membership_exact(p_tenant_id text, p_student_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (
    select pg_catalog.count(*) = 1
      from public.tenant_memberships as membership
     where membership.user_id = p_student_id
  )
  and exists (
    select 1
      from public.tenant_memberships as membership
     where membership.user_id = p_student_id
       and membership.tenant_id = p_tenant_id
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  );
$$;


--
-- Name: student_card_schedule_move_active(text, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_move_active(p_tenant_id text, p_student_id uuid, p_subscription_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.asaas_student_card_schedule_moves as operation
     where operation.tenant_id = p_tenant_id
       and operation.student_id = p_student_id
       and (p_subscription_id is null
         or operation.subscription_id = p_subscription_id)
       and operation.status in (
         'READY', 'MOVING_PAYMENT', 'PAYMENT_MOVED',
         'UPDATING_TARGET_SCHEDULE', 'TARGET_SCHEDULED',
         'AWAITING_LOCAL_RECONCILIATION', 'COMPENSATING',
         'RESTORING_ORIGINAL_SCHEDULE',
         'ORIGINAL_SCHEDULE_RESTORED', 'RESTORING_ORIGINAL_PAYMENT',
         'UNKNOWN', 'BLOCKED'
       )
  );
$$;


--
-- Name: student_card_schedule_move_fingerprint(text, text, uuid, uuid, text, text, text, date, date, date, date, date, date, numeric, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_move_fingerprint(p_operation_key text, p_tenant_id text, p_student_id uuid, p_offer_id uuid, p_customer_id text, p_subscription_id text, p_payment_id text, p_old_due_date date, p_target_due_date date, p_target_next_due_date date, p_original_next_due_date date, p_target_end_date date, p_original_end_date date, p_value numeric, p_max_payments integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(
        pg_catalog.jsonb_build_object(
          'version', 2,
          'strategy', 'MOVE_PENDING_PAYMENT',
          'operationKey', pg_catalog.btrim(p_operation_key),
          'tenantId', pg_catalog.btrim(p_tenant_id),
          'studentId', p_student_id,
          'offerId', p_offer_id,
          'customerId', pg_catalog.btrim(p_customer_id),
          'subscriptionId', pg_catalog.btrim(p_subscription_id),
          'paymentId', pg_catalog.btrim(p_payment_id),
          'oldDueDate', p_old_due_date,
          'targetDueDate', p_target_due_date,
          'targetNextDueDate', p_target_next_due_date,
          'originalNextDueDate', p_original_next_due_date,
          'targetEndDate', p_target_end_date,
          'originalEndDate', p_original_end_date,
          'value', pg_catalog.round(p_value, 2),
          'maxPayments', p_max_payments
        )::text,
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;


--
-- Name: student_card_schedule_offer_exact(text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_offer_exact(p_tenant_id text, p_student_id uuid, p_offer_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.offers as offer
     where offer.id = p_offer_id
       and offer.tenant_id = p_tenant_id
       and offer.kind = 'ENROLLMENT'
       and p_student_id in (offer.processing_by, offer.consumed_by)
       and (offer.processing_by is null or offer.processing_by = p_student_id)
       and (offer.consumed_by is null or offer.consumed_by = p_student_id)
  );
$$;


--
-- Name: student_card_schedule_profile_exact(text, uuid, text, text, numeric, date, date, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_profile_exact(p_tenant_id text, p_student_id uuid, p_customer_id text, p_subscription_id text, p_expected_value numeric, p_target_due_date date, p_expected_end_date date, p_expected_snapshot jsonb) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_typeof(p_expected_snapshot) = 'object'
  and private.student_card_schedule_profile_snapshot(
        p_tenant_id, p_student_id
      ) is not distinct from p_expected_snapshot
  and exists (
    select 1
      from public.profiles as profile
     where profile.id = p_student_id
       and profile.tenant_id = p_tenant_id
       and profile.role = 'STUDENT'
       and pg_catalog.lower(pg_catalog.btrim(coalesce(
             profile.lifecycle_status, ''
           ))) = 'active'
       and pg_catalog.lower(pg_catalog.btrim(coalesce(
             profile.status, ''
           ))) in ('active', 'ativo')
       and coalesce(profile.is_test_account, false) is false
       and nullif(pg_catalog.btrim(profile.asaas_customer_id), '') =
         p_customer_id
       and nullif(pg_catalog.btrim(profile.subscription_id), '') =
         p_subscription_id
       and profile.monthly_fee = p_expected_value
       and profile.due_day =
         pg_catalog.date_part('day', p_target_due_date)::int
       and profile.start_date is not null
       and pg_catalog.date_trunc('month', profile.start_date) =
         pg_catalog.date_trunc('month', p_target_due_date)
       and profile.start_date <= p_target_due_date
       and pg_catalog.upper(pg_catalog.btrim(coalesce(
             profile.asaas_subscription_status, ''
           ))) = 'ACTIVE'
       and profile.asaas_subscription_end_date = p_expected_end_date
  );
$$;


--
-- Name: student_card_schedule_profile_snapshot(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_profile_snapshot(p_tenant_id text, p_student_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select pg_catalog.jsonb_build_object(
    'status', profile.status,
    'lifecycleStatus', profile.lifecycle_status,
    'isTestAccount', coalesce(profile.is_test_account, false),
    'monthlyFee', profile.monthly_fee,
    'dueDay', profile.due_day,
    'startDate', profile.start_date,
    'asaasSubscriptionStatus', profile.asaas_subscription_status,
    'asaasSubscriptionEndDate', profile.asaas_subscription_end_date
  )
    from public.profiles as profile
   where profile.id = p_student_id
     and profile.tenant_id = p_tenant_id;
$$;


--
-- Name: student_card_schedule_snapshot_has_secret(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_card_schedule_snapshot_has_secret(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_key text;
  v_child jsonb;
begin
  if p_value is null then return false; end if;
  if pg_catalog.jsonb_typeof(p_value) = 'object' then
    for v_key, v_child in
      select item.key, item.value
        from pg_catalog.jsonb_each(p_value) as item(key, value)
    loop
      if pg_catalog.lower(v_key) ~
           '(secret|token|password|credential|authorization|cookie|api[_-]?key|access[_-]?key|private[_-]?key)'
         or private.student_card_schedule_snapshot_has_secret(v_child)
      then
        return true;
      end if;
    end loop;
  elsif pg_catalog.jsonb_typeof(p_value) = 'array' then
    for v_child in
      select item.value
        from pg_catalog.jsonb_array_elements(p_value) as item(value)
    loop
      if private.student_card_schedule_snapshot_has_secret(v_child) then
        return true;
      end if;
    end loop;
  end if;
  return false;
end;
$$;


--
-- Name: student_learning_access_is_active(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_learning_access_is_active(p_student_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.profiles as profile
     where profile.id = p_student_id
       and profile.role = 'STUDENT'
       and profile.tenant_id is not null
       and pg_catalog.lower(pg_catalog.btrim(coalesce(
             profile.lifecycle_status,
             'active'
           ))) = 'active'
       and pg_catalog.lower(pg_catalog.btrim(coalesce(
             profile.status,
             'Ativo'
           ))) not in (
             'inativo', 'inactive', 'arquivado', 'cancelado', 'trancado'
           )
       and pg_catalog.upper(pg_catalog.btrim(coalesce(
             profile.offboarding_status,
             ''
           ))) not in ('REQUESTED', 'PROCESSING', 'COMPLETED')
  );
$$;


--
-- Name: student_subscription_mutation_scope_before_card_move(text, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_subscription_mutation_scope_before_card_move(p_tenant_id text, p_student_id uuid, p_customer_id text, p_subscription_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.profiles as profile
     where profile.id = p_student_id
       and profile.tenant_id = p_tenant_id
       and profile.role = 'STUDENT'
       and pg_catalog.lower(pg_catalog.btrim(
             coalesce(profile.lifecycle_status, '')
           )) = 'active'
       and nullif(pg_catalog.btrim(profile.asaas_customer_id), '')
         is not distinct from p_customer_id
       and nullif(pg_catalog.btrim(profile.subscription_id), '')
         is not distinct from p_subscription_id
  )
  and (
    select pg_catalog.count(*)
      from public.tenant_memberships as membership
     where membership.user_id = p_student_id
  ) = 1
  and exists (
    select 1
      from public.tenant_memberships as membership
     where membership.user_id = p_student_id
       and membership.tenant_id = p_tenant_id
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  )
  and not exists (
    select 1
      from public.student_offboarding_operations as operation
     where operation.tenant_id = p_tenant_id
       and operation.student_id = p_student_id
       and operation.status in (
         'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
         'UNKNOWN', 'BLOCKED'
       )
  )
  and not exists (
    select 1
      from public.student_account_deletion_claims as operation
     where operation.tenant_id = p_tenant_id
       and operation.student_id = p_student_id
       and operation.status in (
         'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
         'UNKNOWN', 'BLOCKED'
       )
  )
  and not exists (
    select 1
      from public.student_billing_method_operations as operation
     where operation.tenant_id = p_tenant_id
       and operation.student_id = p_student_id
       and operation.status in ('CLAIMED', 'MUTATING', 'UNKNOWN', 'BLOCKED')
  )
  and not exists (
    select 1
      from public.asaas_student_billing_period_claims as operation
     where operation.tenant_id = p_tenant_id
       and operation.student_id = p_student_id
       and operation.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN', 'BLOCKED')
  )
  and not exists (
    select 1
      from public.asaas_provider_creation_attempts as operation
     where operation.tenant_id = p_tenant_id
       and operation.lifecycle_student_id = p_student_id
       and operation.lifecycle_released_at is null
       and operation.status in (
         'CLAIMED', 'SUBMITTING', 'UNKNOWN', 'SUCCEEDED', 'BLOCKED'
       )
  )
  and not exists (
    select 1
      from public.student_overdue_card_charge_claims as operation
     where operation.tenant_id = p_tenant_id
       and operation.student_id = p_student_id
       and (
         operation.status in ('PROCESSING', 'SUBMITTING', 'UNKNOWN', 'BLOCKED')
         or (
           operation.status = 'SUCCEEDED'
           and not exists (
             select 1
               from public.student_payments as payment
              where payment.tenant_id = p_tenant_id
                and payment.student_id = p_student_id
                and nullif(pg_catalog.btrim(coalesce(
                      payment.asaas_payment_id, ''
                    )), '') = operation.asaas_payment_id
                and pg_catalog.upper(pg_catalog.btrim(coalesce(
                      payment.status, ''
                    ))) in ('RECEIVED', 'RECEIVED_IN_CASH')
           )
         )
       )
  )
  and not exists (
    select 1
      from public.asaas_outbound_message_attempts as operation
     where operation.tenant_id = p_tenant_id
       and operation.student_id = p_student_id
       and operation.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN')
  );
$$;


--
-- Name: student_subscription_mutation_scope_valid(text, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.student_subscription_mutation_scope_valid(p_tenant_id text, p_student_id uuid, p_customer_id text, p_subscription_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.student_subscription_mutation_scope_before_card_move(
    p_tenant_id,
    p_student_id,
    p_customer_id,
    p_subscription_id
  )
  and not private.student_card_schedule_move_active(
    p_tenant_id,
    p_student_id,
    p_subscription_id
  );
$$;


--
-- Name: sync_lesson_notification_receipt(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_lesson_notification_receipt() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_changed integer := 0;
begin
  if upper(pg_catalog.btrim(coalesce(old.notification_kind, ''))) <>
      'LESSON_REMINDER'
     or old.delivery_status <> 'submitting'
     or old.claim_token is null
     or new.claim_token is not null then
    return new;
  end if;

  if new.delivery_status in (
    'accepted', 'sent', 'delivered', 'read', 'uncertain'
  ) then
    update public.automation_sent as receipt
    set receipt_state = 'COMMITTED',
        notification_claim_token = null
    where receipt.notification_id = old.id
      and receipt.notification_claim_token = old.claim_token
      and receipt.receipt_state = 'SEALED';
    get diagnostics v_changed = row_count;
  elsif new.delivery_status = 'failed' then
    delete from public.automation_sent as receipt
    where receipt.notification_id = old.id
      and receipt.notification_claim_token = old.claim_token
      and receipt.receipt_state = 'SEALED';
    get diagnostics v_changed = row_count;
  else
    raise exception 'invalid_lesson_receipt_terminal_transition'
      using errcode = '23514';
  end if;

  if v_changed <> 1 then
    raise exception 'lesson_receipt_fence_missing'
      using errcode = '23514';
  end if;
  return new;
end;
$$;


--
-- Name: sync_primary_membership_student_plan(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_primary_membership_student_plan() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_tenant text;
  v_plan_name text;
begin
  if tg_table_name = 'profiles' then
    update public.tenant_memberships as membership
       set student_plan_id = (
             select pricing_plan.id
               from public.student_pricing_plans as pricing_plan
              where pricing_plan.tenant_id = new.tenant_id
                and pricing_plan.name = new.fidelity_plan
              order by pricing_plan.id
              limit 1
           ),
           updated_at = pg_catalog.now()
     where membership.user_id = new.id
       and membership.tenant_id = new.tenant_id
       and membership.role = 'STUDENT';
    return new;
  end if;

  if new.role <> 'STUDENT' or new.student_plan_id is not null then
    return new;
  end if;
  select profile.tenant_id, profile.fidelity_plan
    into v_profile_tenant, v_plan_name
    from public.profiles as profile
   where profile.id = new.user_id;
  if v_profile_tenant = new.tenant_id then
    select pricing_plan.id
      into new.student_plan_id
      from public.student_pricing_plans as pricing_plan
     where pricing_plan.tenant_id = new.tenant_id
       and pricing_plan.name = v_plan_name
     order by pricing_plan.id
     limit 1;
  end if;
  return new;
end;
$$;


--
-- Name: sync_primary_tenant_membership(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_primary_tenant_membership() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  membership_role text;
BEGIN
  IF NEW.tenant_id IS NULL THEN
    RETURN NEW;
  END IF;

  membership_role := CASE
    WHEN NEW.role = 'SUPER_ADMIN' THEN 'SCHOOL_ADMIN'
    ELSE NEW.role
  END;

  INSERT INTO public.tenant_memberships (
    user_id,
    tenant_id,
    role,
    status,
    is_primary
  )
  VALUES (
    NEW.id,
    NEW.tenant_id,
    membership_role,
    'ACTIVE',
    true
  )
  ON CONFLICT (user_id, tenant_id) DO UPDATE
  SET role = EXCLUDED.role,
      status = 'ACTIVE',
      is_primary = true,
      updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: teacher_pending_carryover_in_tenant(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.teacher_pending_carryover_in_tenant(p_tenant text, p_teacher uuid) RETURNS TABLE(class_log_id uuid, origin_month text, class_date date, amount numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT payable.id,
         to_char(payable.class_date, 'YYYY-MM'),
         payable.class_date,
         payable.rate_efetivo
    FROM public.v_payable_class_logs AS payable
    JOIN public.teacher_closings AS closing
      ON closing.tenant_id = p_tenant
     AND closing.teacher_id = payable.teacher_id
     AND closing.month_year = to_char(payable.class_date, 'YYYY-MM')
   WHERE payable.tenant_id = p_tenant
     AND payable.teacher_id = p_teacher
     AND closing.status <> 'PENDENTE'
     AND payable.created_at > closing.updated_at
     AND payable.created_at >= date '2026-08-02'
     AND EXISTS (
       SELECT 1
         FROM public.profiles AS teacher
         JOIN public.tenant_memberships AS membership
           ON membership.user_id = teacher.id
          AND membership.tenant_id = p_tenant
          AND membership.role = 'TEACHER'
          AND membership.status = 'ACTIVE'
        WHERE teacher.id = p_teacher
          AND teacher.role = 'TEACHER'
          AND teacher.tenant_id = p_tenant
          AND lower(coalesce(teacher.lifecycle_status, 'active'))
                NOT IN ('suspended', 'offboarded')
     )
     AND NOT EXISTS (
       SELECT 1
         FROM public.closing_carryovers AS absorbed
        WHERE absorbed.class_log_id = payable.id
     );
$$;


--
-- Name: teacher_reschedule_financial_origin_is_proven(uuid, text, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.teacher_reschedule_financial_origin_is_proven(p_reschedule_id uuid, p_tenant_id text, p_teacher_id uuid, p_student_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.reschedules as reschedule
     where reschedule.id = p_reschedule_id
       and reschedule.tenant_id = p_tenant_id
       and reschedule.teacher_id = p_teacher_id
       and reschedule.student_id = p_student_id
       and reschedule.fault_type = 'TEACHER'
       and (
         (
           reschedule.original_booking_id is not null
           and exists (
             select 1
               from public.class_logs as origin_log
              where origin_log.tenant_id = reschedule.tenant_id
                and origin_log.teacher_id = reschedule.teacher_id
                and origin_log.student_id = reschedule.student_id
                and origin_log.booking_id = reschedule.original_booking_id::text
                and origin_log.presence in (
                  'TEACHER_ABSENCE',
                  'Falta do Professor'
                )
           )
         )
         or (
           reschedule.attendance_session_key is not null
           and exists (
             select 1
               from public.attendance_confirmations as confirmation
              where confirmation.session_key = reschedule.attendance_session_key
                and confirmation.tenant_id = reschedule.tenant_id
                and confirmation.teacher_id = reschedule.teacher_id
                and confirmation.student_id is not distinct from reschedule.student_id
                and confirmation.status = 'RESOLVED_UNPAID'
                and confirmation.resolution_verdict = 'TEACHER_ABSENT'
           )
         )
       )
  );
$$;


--
-- Name: tenant_integration_config_is_valid(text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tenant_integration_config_is_valid(p_provider text, p_mode text, p_config jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_config is null
      or jsonb_typeof(p_config) <> 'object'
      or pg_catalog.pg_column_size(p_config) > 4096
    then false
    when p_provider = 'evolution' and p_mode = 'TENANT_BYOK'
    then
      p_config ? 'baseUrl'
      and p_config - 'baseUrl' = '{}'::jsonb
      and jsonb_typeof(p_config -> 'baseUrl') = 'string'
      and length(trim(p_config ->> 'baseUrl')) between 12 and 2048
      and trim(p_config ->> 'baseUrl') ~ '^https://'
    else p_config = '{}'::jsonb
  end;
$$;


--
-- Name: tenant_is_operational(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tenant_is_operational(p_tenant_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.tenants AS tenant
    WHERE tenant.id = p_tenant_id
      AND lower(trim(coalesce(tenant.saas_status, ''))) IN (
        'active', 'trial', 'trialing'
      )
      AND (
        NOT EXISTS (
          SELECT 1
          FROM public.saas_checkout_intents AS paid_checkout
          WHERE paid_checkout.tenant_id = tenant.id
        )
        OR (
          tenant.current_period_end IS NOT NULL
          AND tenant.current_period_end > pg_catalog.now()
          AND EXISTS (
            SELECT 1
            FROM public.saas_checkout_intents AS live_checkout
            WHERE live_checkout.tenant_id = tenant.id
              AND live_checkout.provisioned_at IS NOT NULL
              AND live_checkout.status = 'PROVISIONED'
          )
        )
      )
  );
$$;


--
-- Name: tenant_rls_p0_has_active_booking(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tenant_rls_p0_has_active_booking(p_teacher_id uuid, p_student_id uuid, p_tenant_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_tenant_id = private.active_tenant_id((select auth.uid()))
  and (
    p_teacher_id = (select auth.uid())
    or private.active_tenant_role((select auth.uid())) in (
      'SCHOOL_ADMIN', 'COORDINATOR', 'DIRECTOR', 'SUPER_ADMIN'
    )
  )
  and exists (
    select 1
    from public.bookings as booking
    where booking.teacher_id = p_teacher_id
      and booking.student_id = p_student_id
      and booking.tenant_id = p_tenant_id
      and booking.status = 'SCHEDULED'
  );
$$;


--
-- Name: tenant_rls_p0_has_active_membership(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tenant_rls_p0_has_active_membership(p_tenant_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_tenant_id = private.active_tenant_id((select auth.uid()))
  and exists (
    select 1
    from public.tenant_memberships as membership
    join public.profiles as profile
      on profile.id = membership.user_id
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
    where membership.user_id = (select auth.uid())
      and membership.tenant_id = p_tenant_id
      and membership.status = 'ACTIVE'
  );
$$;


--
-- Name: tenant_rls_p0_has_active_role(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.tenant_rls_p0_has_active_role(p_user_id uuid, p_tenant_id text, p_role text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_tenant_id = private.active_tenant_id((select auth.uid()))
  and exists (
    select 1
    from public.tenant_memberships as membership
    join public.profiles as profile
      on profile.id = membership.user_id
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
    where membership.user_id = p_user_id
