--
-- Name: trial_feedback_is_complete(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.trial_feedback_is_complete(p_opportunity_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.opportunities as opportunity
    join public.trial_feedback as feedback
      on feedback.opportunity_id = opportunity.id
     and feedback.tenant_id = opportunity.tenant_id
     and feedback.booking_id = opportunity.trial_appointment_id
     and feedback.teacher_id = coalesce(
       opportunity.winner_teacher_id,
       opportunity.professor_id
     )
    where opportunity.id = p_opportunity_id
      and opportunity.trial_appointment_id is not null
  );
$$;


--
-- Name: trial_management_destination(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.trial_management_destination(p_tenant_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select coalesce(
    (
      select pg_catalog.btrim(profile.directors_group_id)
      from public.tenant_memberships as membership
      join public.profiles as profile
        on profile.id = membership.user_id
       and profile.tenant_id = membership.tenant_id
      where membership.tenant_id = p_tenant_id
        and membership.role = 'SCHOOL_ADMIN'
        and membership.status = 'ACTIVE'
        and lower(pg_catalog.btrim(coalesce(
          profile.lifecycle_status,
          ''
        ))) = 'active'
        and pg_catalog.btrim(coalesce(profile.directors_group_id, ''))
          ~ '^[0-9]{10,25}@g[.]us$'
      order by membership.is_primary desc nulls last,
        membership.created_at,
        membership.user_id
      limit 1
    ),
    (
      select private.normalize_notification_phone(profile.phone)
      from public.tenant_memberships as membership
      join public.profiles as profile
        on profile.id = membership.user_id
       and profile.tenant_id = membership.tenant_id
      where membership.tenant_id = p_tenant_id
        and membership.role = 'SCHOOL_ADMIN'
        and membership.status = 'ACTIVE'
        and lower(pg_catalog.btrim(coalesce(
          profile.lifecycle_status,
          ''
        ))) = 'active'
        and private.normalize_notification_phone(profile.phone) is not null
      order by membership.is_primary desc nulls last,
        membership.created_at,
        membership.user_id
      limit 1
    )
  );
$_$;


--
-- Name: trigger_asaas_automation_worker(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.trigger_asaas_automation_worker() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_service_key text;
  v_request_id bigint;
begin
  select secret.decrypted_secret into v_service_key
    from vault.decrypted_secrets as secret
   where secret.name = 'wisewolf_service_role_key'
   limit 1;
  if nullif(pg_catalog.btrim(v_service_key), '') is null then
    raise exception 'wisewolf_service_role_key_is_not_configured';
  end if;

  select net.http_post(
    url := 'http://kong:8000/functions/v1/asaas-webhook',
    headers := pg_catalog.jsonb_build_object(
      'Authorization', 'Bearer ' || v_service_key,
      'apikey', v_service_key,
      'Content-Type', 'application/json'
    ),
    body := '{"operation":"drain"}'::jsonb,
    timeout_milliseconds := 30000
  ) into v_request_id;

  perform private.record_asaas_automation_http_request(
    'WEBHOOK_WORKER', v_request_id
  );
end;
$$;


--
-- Name: trigger_asaas_reconciliation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.trigger_asaas_reconciliation() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_service_key text;
  v_request_id bigint;
begin
  select secret.decrypted_secret into v_service_key
    from vault.decrypted_secrets as secret
   where secret.name = 'wisewolf_service_role_key'
   limit 1;
  if nullif(pg_catalog.btrim(v_service_key), '') is null then
    raise exception 'wisewolf_service_role_key_is_not_configured';
  end if;

  select net.http_post(
    url := 'http://kong:8000/functions/v1/asaas-reconcile',
    headers := pg_catalog.jsonb_build_object(
      'Authorization', 'Bearer ' || v_service_key,
      'apikey', v_service_key,
      'Content-Type', 'application/json'
    ),
    body := pg_catalog.jsonb_build_object('lookbackDays', 45),
    timeout_milliseconds := 120000
  ) into v_request_id;

  perform private.record_asaas_automation_http_request(
    'RECONCILIATION', v_request_id
  );
end;
$$;


