--
-- Name: trigger_reconcile_whatsapp_webhooks(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.trigger_reconcile_whatsapp_webhooks() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_service_key text;
  v_secret_count bigint;
  v_request_id bigint;
begin
  select count(*), max(secret.decrypted_secret)
  into v_secret_count, v_service_key
  from vault.decrypted_secrets as secret
  where secret.name = 'wisewolf_service_role_key';

  if v_secret_count <> 1
     or nullif(pg_catalog.btrim(v_service_key), '') is null then
    raise exception 'wisewolf_service_role_key_is_not_configured';
  end if;

  select net.http_post(
    url := 'http://kong:8000/functions/v1/reconcile-whatsapp-webhooks',
    headers := pg_catalog.jsonb_build_object(
      'Authorization', 'Bearer ' || v_service_key,
      'apikey', v_service_key,
      'Content-Type', 'application/json'
    ),
    body := pg_catalog.jsonb_build_object('limit', 100),
    timeout_milliseconds := 120000
  ) into v_request_id;

  if v_request_id is null then
    raise exception 'reconcile_whatsapp_webhooks_http_request_was_not_queued';
  end if;

  return v_request_id;
end;
$$;


--
-- Name: valid_cnpj(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.valid_cnpj(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
  digits text := regexp_replace(coalesce(p_value, ''), '\D', '', 'g');
  first_weights integer[] := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2];
  second_weights integer[] := ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
  total integer := 0;
  remainder integer;
  expected_digit integer;
  position_index integer;
BEGIN
  IF length(digits) <> 14
    OR digits = repeat(substring(digits FROM 1 FOR 1), 14)
  THEN
    RETURN false;
  END IF;

  FOR position_index IN 1..12 LOOP
    total := total
      + substring(digits FROM position_index FOR 1)::integer
        * first_weights[position_index];
  END LOOP;
  remainder := total % 11;
  expected_digit := CASE WHEN remainder < 2 THEN 0 ELSE 11 - remainder END;
  IF expected_digit <> substring(digits FROM 13 FOR 1)::integer THEN
    RETURN false;
  END IF;

  total := 0;
  FOR position_index IN 1..13 LOOP
    total := total
      + substring(digits FROM position_index FOR 1)::integer
        * second_weights[position_index];
  END LOOP;
  remainder := total % 11;
  expected_digit := CASE WHEN remainder < 2 THEN 0 ELSE 11 - remainder END;
  RETURN expected_digit = substring(digits FROM 14 FOR 1)::integer;
END;
$$;


--
-- Name: validate_subscription_mutation_state(text, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_subscription_mutation_state(p_kind text, p_expected jsonb, p_desired jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_kind
    when 'PLAN_VALUE' then
      pg_catalog.jsonb_typeof(p_expected -> 'valueCents') = 'number'
      and pg_catalog.jsonb_typeof(p_desired -> 'valueCents') = 'number'
      and (p_expected ->> 'valueCents')::bigint > 0
      and (p_desired ->> 'valueCents')::bigint > 0
      and p_expected = pg_catalog.jsonb_build_object(
        'valueCents', (p_expected ->> 'valueCents')::bigint
      )
      and p_desired = pg_catalog.jsonb_build_object(
        'valueCents', (p_desired ->> 'valueCents')::bigint
      )
    when 'MAX_PAYMENTS' then
      pg_catalog.jsonb_typeof(p_expected -> 'maxPayments') = 'number'
      and pg_catalog.jsonb_typeof(p_desired -> 'maxPayments') = 'number'
      and (p_expected ->> 'maxPayments')::integer between 1 and 120
      and (p_desired ->> 'maxPayments')::integer between 1 and 120
      and p_expected = pg_catalog.jsonb_build_object(
        'maxPayments', (p_expected ->> 'maxPayments')::integer
      )
      and p_desired = pg_catalog.jsonb_build_object(
        'maxPayments', (p_desired ->> 'maxPayments')::integer
      )
    else false
  end;
$$;


--
-- Name: validate_training_slot(text, uuid, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_training_slot(p_tenant text, p_trainer uuid, p_trainee uuid, p_start timestamp with time zone, p_exclude uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_date date := (p_start at time zone 'America/Sao_Paulo')::date; v_time text := to_char(p_start at time zone 'America/Sao_Paulo','HH24:MI'); v_day text; v_teacher uuid;
begin
  if p_start is null or p_start <= now() or p_start > now()+interval '90 days' or to_char(p_start at time zone 'America/Sao_Paulo','MI:SS') not in ('00:00','30:00') then
    raise exception 'Escolha um horário futuro, em intervalos de 30 minutos, nos próximos 90 dias.';
  end if;
  v_day := (array['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'])[extract(dow from v_date)::int+1];
  for v_teacher in select distinct unnest(array[p_trainer,p_trainee]) order by 1 loop
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('schedule:teacher:'||v_teacher::text||':'||public.fold_accents(v_day)||':'||v_time,0));
    if not exists(select 1 from public.profiles p join public.tenant_memberships m on m.user_id=p.id and m.tenant_id=p_tenant and m.status='ACTIVE' and m.role='TEACHER' where p.id=v_teacher and p.tenant_id=p_tenant and p.role='TEACHER' and lower(coalesce(p.lifecycle_status,'active'))='active' and (p.id<>p_trainer or p.is_trainer=true)) then
      raise exception 'O treinador precisa estar habilitado e os dois teachers precisam estar ativos nesta escola.';
    end if;
    if exists(select 1 from public.bookings b where b.tenant_id=p_tenant and b.teacher_id=v_teacher and upper(coalesce(b.status,''))<>'CANCELLED' and left(b.time_slot,5)=v_time and (b.date=v_date or (b.date is null and public.fold_accents(b.day_of_week)=public.fold_accents(v_day) and (b.start_date is null or b.start_date<=v_date))))
      or exists(select 1 from public.reschedules r where r.tenant_id=p_tenant and r.teacher_id=v_teacher and public.parse_lesson_date(r.date)=v_date and left(r.time,5)=v_time and r.used_at is null)
      or exists(select 1 from public.appointments a where a.tenant_id=p_tenant and v_teacher in (a.teacher_id,a.professor_id) and lower(a.status) in ('scheduled','confirmed') and abs(extract(epoch from a.start_time-p_start))<1800)
      or exists(select 1 from public.class_coverages c where c.tenant_id=p_tenant and c.cover_teacher_id=v_teacher and c.class_date=v_date and left(c.class_time,5)=v_time and (c.status='confirmed' or (c.status='pending' and coalesce(c.invite_expires_at,p_start)>now())))
      or exists(select 1 from public.teacher_absences a where a.tenant_id=p_tenant and a.teacher_id=v_teacher and a.status='active' and a.starts_at::date<=v_date and a.ends_at::date>=v_date)
      or exists(select 1 from public.teacher_training_sessions t where t.tenant_id=p_tenant and v_teacher in (t.trainer_id,t.trainee_id) and t.status in ('PENDING','CONFIRMED') and t.starts_at < p_start+interval '30 minutes' and t.ends_at>p_start and t.id is distinct from p_exclude)
    then raise exception 'Um dos teachers já possui compromisso ou ausência nesse horário.'; end if;
  end loop;
end;
$$;


--
-- Name: validate_whatsapp_instance_integration_binding(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_whatsapp_instance_integration_binding() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- Compatibility for older instance producers: a missing pair is filled from
  -- the tenant's current broker receipt inside the same INSERT transaction.
  if new.integration_id is null and new.integration_version is null then
    select connection.id, connection.version
    into new.integration_id, new.integration_version
    from private.tenant_integration_connections as connection
    where connection.tenant_id = new.tenant_id
      and connection.provider = 'evolution';
  end if;

  if new.integration_id is null
     or coalesce(new.integration_version, 0) <= 0
     or not exists (
       select 1
       from private.tenant_integration_connections as connection
       where connection.id = new.integration_id
         and connection.tenant_id = new.tenant_id
         and connection.provider = 'evolution'
         and connection.version = new.integration_version
     ) then
    raise exception 'invalid_whatsapp_instance_integration_binding'
      using errcode = '23514';
  end if;

  return new;
end;
$$;


--
-- Name: whatsapp_inbox_actor_has_role(uuid, text, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.whatsapp_inbox_actor_has_role(p_actor_id uuid, p_tenant_id text, p_roles text[]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_actor_id is not null
    and p_tenant_id is not null
    and p_roles is not null
    and private.tenant_is_operational(p_tenant_id)
    and private.active_tenant_id(p_actor_id) = p_tenant_id
    and private.active_tenant_role(p_actor_id) = any(p_roles)
    and exists (
      select 1
      from public.tenant_memberships as membership
      join public.profiles as profile
        on profile.id = membership.user_id
       and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, '')))
         = 'active'
      where membership.user_id = p_actor_id
        and membership.tenant_id = p_tenant_id
        and membership.status = 'ACTIVE'
    );
$$;


--
-- Name: whatsapp_inbox_instance_is_eligible(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.whatsapp_inbox_instance_is_eligible(p_tenant_id text, p_instance_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_tenant_id is not null
    and p_instance_id is not null
    and private.tenant_is_operational(p_tenant_id)
    and exists (
      select 1
      from public.whatsapp_instances as instance
      join public.tenant_memberships as membership
        on membership.user_id = instance.user_id
       and membership.tenant_id = instance.tenant_id
       and membership.role = 'SCHOOL_ADMIN'
       and membership.status = 'ACTIVE'
      join public.profiles as owner
        on owner.id = instance.user_id
       and lower(pg_catalog.btrim(coalesce(owner.lifecycle_status, '')))
         = 'active'
      where instance.id = p_instance_id
        and instance.tenant_id = p_tenant_id
        and instance.inbox_enabled is true
    );
$$;


--
-- Name: whatsapp_inbox_remote_jid_is_allowed(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.whatsapp_inbox_remote_jid_is_allowed(p_tenant_id text, p_remote_jid text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  select case
    when nullif(pg_catalog.btrim(p_tenant_id), '') is null
      or nullif(pg_catalog.btrim(p_remote_jid), '') is null then false
    when lower(pg_catalog.btrim(p_remote_jid))
      ~ '^[0-9]{10,15}@s[.]whatsapp[.]net$'
      then true
    when lower(pg_catalog.btrim(p_remote_jid)) like '%@g.us' then exists (
      select 1
      from public.dre_report_settings as settings
      where settings.tenant_id = p_tenant_id
        and settings.is_active is true
        and lower(pg_catalog.btrim(settings.destino))
          = lower(pg_catalog.btrim(p_remote_jid))
    )
    else false
  end;
$_$;


--
-- Name: wolfie_access_snapshot(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.wolfie_access_snapshot(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile public.profiles%rowtype;
  v_school_membership public.tenant_memberships%rowtype;
  v_subscription public.hub_subscriptions%rowtype;
  v_plan public.hub_plans%rowtype;
  v_account_id uuid;
begin
  if p_user_id is null then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'AUTHENTICATION_REQUIRED'
    );
  end if;

  select * into v_profile
  from public.profiles
  where id = p_user_id;
  if not found then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'PROFILE_REQUIRED'
    );
  end if;

  select membership.* into v_school_membership
  from public.tenant_memberships as membership
  where membership.user_id = p_user_id
    and membership.status = 'ACTIVE'
    and membership.role = 'STUDENT'
    and membership.tenant_id <> 'wolfie-direct'
  order by membership.is_primary desc, membership.created_at
  limit 1;
  if found then
    return pg_catalog.jsonb_build_object(
      'allowed', true,
      'accessKind', 'SCHOOL',
      'tenantId', v_school_membership.tenant_id,
      'planCode', null,
      'planName', 'Acesso pela escola'
    );
  end if;

  if not exists (
    select 1
    from public.tenant_memberships as membership
    where membership.user_id = p_user_id
      and membership.tenant_id = 'wolfie-direct'
      and membership.status = 'ACTIVE'
      and membership.role = 'STUDENT'
  ) then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'WOLFIE_ACCOUNT_REQUIRED'
    );
  end if;

  select account.id into v_account_id
  from public.hub_accounts as account
  join public.hub_memberships as membership
    on membership.account_id = account.id
  where account.owner_user_id = p_user_id
    and account.account_type = 'PERSONAL'
    and account.status = 'ACTIVE'
    and membership.user_id = p_user_id
    and membership.status = 'ACTIVE'
    and membership.membership_role = 'OWNER'
  order by account.created_at, account.id
  limit 1;
  if v_account_id is null then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'WOLFIE_ACCOUNT_REQUIRED'
    );
  end if;

  select subscription.*
  into v_subscription
  from public.hub_subscriptions as subscription
  join public.hub_plans as plan on plan.id = subscription.plan_id
  where subscription.account_id = v_account_id
    and subscription.product_family = 'WOLFIE_STANDALONE'
    and plan.product_family = 'WOLFIE_STANDALONE'
    and subscription.status = 'ACTIVE'
    and coalesce(
      subscription.current_period_ends_at,
      '-infinity'::timestamptz
    ) > pg_catalog.now()
  order by subscription.created_at desc
  limit 1;

  if not found then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'WOLFIE_SUBSCRIPTION_REQUIRED',
      'accessKind', 'STANDALONE',
      'tenantId', 'wolfie-direct'
    );
  end if;

  select * into v_plan
  from public.hub_plans
  where id = v_subscription.plan_id;
  if not found then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'WOLFIE_PLAN_REQUIRED',
      'accessKind', 'STANDALONE',
      'tenantId', 'wolfie-direct'
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'allowed', true,
    'accessKind', 'STANDALONE',
    'tenantId', 'wolfie-direct',
    'accountId', v_account_id,
    'subscriptionId', v_subscription.id,
    'subscriptionStatus', v_subscription.status,
    'periodEndsAt', v_subscription.current_period_ends_at,
    'planCode', v_plan.code,
    'planName', v_plan.name,
    'liveMinutes', coalesce(
      (v_plan.metadata ->> 'live_minutes')::integer,
      0
    )
  );
end;
$$;


--
-- Name: wolfie_live_balance_snapshot(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.wolfie_live_balance_snapshot(p_tenant_id text, p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit_minutes integer;
  v_plan uuid;
  v_access_mode text;
  v_entitlement_state text;
  v_start timestamptz := date_trunc('month', pg_catalog.now());
  v_plan_used_seconds bigint := 0;
  v_credit_used_seconds bigint := 0;
  v_credit_used_this_month bigint := 0;
  v_credit_total_seconds bigint := 0;
  v_reserved_plan_seconds bigint := 0;
  v_reserved_credit_seconds bigint := 0;
  v_plan_remaining_seconds bigint;
  v_credit_remaining_seconds bigint;
  v_remaining_seconds bigint;
  v_display_used_seconds bigint;
begin
  select membership.student_plan_id
    into v_plan
    from public.tenant_memberships as membership
   where membership.user_id = p_student_id
     and membership.tenant_id = p_tenant_id
     and membership.status = 'ACTIVE'
     and membership.role = 'STUDENT';
  if not found then
    return pg_catalog.jsonb_build_object(
      'enforced', true,
      'allowed', false,
      'entitlementState', 'MEMBERSHIP_MISSING',
      'remainingSeconds', 0,
      'planRemainingSeconds', 0,
      'creditRemainingSeconds', 0
    );
  end if;

  select entitlement.limit_value, entitlement.access_mode
    into v_limit_minutes, v_access_mode
    from public.student_plan_entitlements as entitlement
   where entitlement.tenant_id = p_tenant_id
     and entitlement.feature_key = 'wolfie.live_minutes'
     and (entitlement.plan_id = v_plan or entitlement.plan_id is null)
   order by entitlement.plan_id nulls last,
     entitlement.created_at desc,
     entitlement.id
   limit 1;

  if found and v_access_mode = 'UNLIMITED' then
    return pg_catalog.jsonb_build_object(
      'enforced', false,
      'allowed', true,
      'entitlementState', 'UNLIMITED',
      'remainingSeconds', null,
      'planRemainingSeconds', null,
      'creditRemainingSeconds', null
    );
  end if;
  if not found then
    v_limit_minutes := 0;
    v_entitlement_state := 'MISSING';
  elsif coalesce(v_limit_minutes, 0) <= 0 then
    v_limit_minutes := 0;
    v_entitlement_state := 'ZERO';
  else
    v_entitlement_state := 'LIMITED';
  end if;

  select
    coalesce(pg_catalog.sum(minutes.plan_seconds), 0),
    coalesce(
      pg_catalog.sum(minutes.credit_seconds)
        filter (where minutes.created_at >= v_start),
      0
    )
    into v_plan_used_seconds, v_credit_used_this_month
    from public.student_live_minutes as minutes
   where minutes.tenant_id = p_tenant_id
     and minutes.student_id = p_student_id
     and minutes.created_at >= v_start
     and minutes.created_at < v_start + interval '1 month';

  select coalesce(pg_catalog.sum(minutes.credit_seconds), 0)
    into v_credit_used_seconds
    from public.student_live_minutes as minutes
   where minutes.tenant_id = p_tenant_id
     and minutes.student_id = p_student_id;

  select coalesce(pg_catalog.sum(credit.minutes), 0) * 60
    into v_credit_total_seconds
    from public.student_minute_credits as credit
   where credit.tenant_id = p_tenant_id
     and credit.student_id = p_student_id
     and credit.status = 'PAID';

  select
    coalesce(pg_catalog.sum(grant_row.reserved_plan_seconds), 0),
    coalesce(pg_catalog.sum(grant_row.reserved_credit_seconds), 0)
    into v_reserved_plan_seconds, v_reserved_credit_seconds
    from public.wolfie_live_grants as grant_row
   where grant_row.tenant_id = p_tenant_id
     and grant_row.student_id = p_student_id
     and (
       grant_row.status in ('ACTIVE', 'CLOSING')
       or (
         grant_row.status = 'RESERVED'
         and grant_row.reservation_expires_at > pg_catalog.now()
       )
     );

  v_plan_remaining_seconds := greatest(
    0,
    v_limit_minutes::bigint * 60
      - v_plan_used_seconds
      - v_reserved_plan_seconds
  );
  v_credit_remaining_seconds := greatest(
    0,
    v_credit_total_seconds
      - v_credit_used_seconds
      - v_reserved_credit_seconds
  );
  v_remaining_seconds := v_plan_remaining_seconds
    + v_credit_remaining_seconds;
  v_display_used_seconds := v_plan_used_seconds
    + v_credit_used_this_month
    + v_reserved_plan_seconds
    + v_reserved_credit_seconds;

  return pg_catalog.jsonb_build_object(
    'enforced', true,
    'allowed', v_remaining_seconds > 0,
    'entitlementState', v_entitlement_state,
    'used', pg_catalog.ceil(v_display_used_seconds / 60.0)::integer,
    'limit', pg_catalog.ceil(
      (v_display_used_seconds + v_remaining_seconds) / 60.0
    )::integer,
    'remaining', pg_catalog.ceil(v_remaining_seconds / 60.0)::integer,
    'remainingSeconds', v_remaining_seconds,
    'planLimit', v_limit_minutes,
    'planRemainingSeconds', v_plan_remaining_seconds,
    'credits', pg_catalog.floor(
      v_credit_remaining_seconds / 60.0
    )::integer,
    'creditRemainingSeconds', v_credit_remaining_seconds,
    'reservedSeconds', v_reserved_plan_seconds + v_reserved_credit_seconds
  );
end;
$$;


--
-- Name: wolfie_meeting_memory_candidates(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.wolfie_meeting_memory_candidates(p_attempt_id uuid) RETURNS TABLE(candidate_tenant_id text, candidate_student_id uuid, candidate_source_session_id uuid, candidate_attempt_id uuid, candidate_kind text, candidate_dimension text, candidate_memory_key text, candidate_content text, candidate_confidence numeric, candidate_evidence jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_attempt public.wolfie_activity_attempts%rowtype;
  v_subject text;
  v_rubric jsonb;
  v_canonical_rubric jsonb := '{}'::jsonb;
  v_rubric_dimension text;
  v_dimension_score numeric;
  v_feedback_score numeric;
  v_feedback_requires_retry boolean;
begin
  if p_attempt_id is null then
    raise exception using
      errcode = '22023',
      message = 'invalid_wolfie_meeting_attempt';
  end if;

  select attempt.*
    into v_attempt
    from public.wolfie_activity_attempts as attempt
   where attempt.id = p_attempt_id;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'wolfie_meeting_attempt_not_found';
  end if;

  select session.subject
    into v_subject
    from public.wolfie_activity_sessions as session
   where session.id = v_attempt.session_id
     and session.tenant_id = v_attempt.tenant_id
     and session.student_id = v_attempt.student_id;
  if not found then
    raise exception using
      errcode = '23503',
      message = 'invalid_wolfie_meeting_memory_lineage';
  end if;

  if v_subject <> 'global_meetings'
     or v_attempt.step_key is null
     or v_attempt.step_key not in (
       'final',
       'final_speech',
       'memorization_complete',
       'readaptation',
       'readaptation_speech'
     ) then
    return;
  end if;

  if not exists (
    select 1
      from public.tenant_memberships as membership
     where membership.tenant_id = v_attempt.tenant_id
       and membership.user_id = v_attempt.student_id
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    raise exception using
      errcode = '42501',
      message = 'inactive_wolfie_meeting_memory_membership';
  end if;

  if pg_catalog.jsonb_typeof(v_attempt.feedback_payload) <> 'object'
     or pg_catalog.jsonb_typeof(v_attempt.feedback_payload -> 'score')
       is distinct from 'number'
     or pg_catalog.jsonb_typeof(
       v_attempt.feedback_payload -> 'requiresRetry'
     ) is distinct from 'boolean'
     or pg_catalog.jsonb_typeof(v_attempt.feedback_payload -> 'rubric')
       is distinct from 'object' then
    raise exception using
      errcode = '22023',
      message = 'invalid_persisted_wolfie_meeting_assessment';
  end if;

  begin
    v_feedback_score := (v_attempt.feedback_payload ->> 'score')::numeric;
    v_feedback_requires_retry :=
      (v_attempt.feedback_payload ->> 'requiresRetry')::boolean;
  exception when others then
    raise exception using
      errcode = '22023',
      message = 'invalid_persisted_wolfie_meeting_assessment';
  end;

  if v_feedback_score not between 0 and 100
     or v_feedback_score <> v_attempt.score
     or v_feedback_requires_retry is distinct from v_attempt.requires_retry then
    raise exception using
      errcode = '22023',
      message = 'inconsistent_persisted_wolfie_meeting_assessment';
  end if;

  v_rubric := v_attempt.feedback_payload -> 'rubric';
  foreach v_rubric_dimension in array array[
    'taskCompletion',
    'structureAndFacilitation',
    'interactionAndTurnTaking',
    'clarificationAndQuestionHandling',
    'diplomacyAndNegotiation',
    'clarityAndConcision',
    'accuracyAndNaturalness',
    'decisionAndActionableClose'
  ]
  loop
    if pg_catalog.jsonb_typeof(v_rubric -> v_rubric_dimension)
         is distinct from 'number' then
      raise exception using
        errcode = '22023',
        message = 'invalid_persisted_wolfie_meeting_rubric';
    end if;
    begin
      v_dimension_score := (v_rubric ->> v_rubric_dimension)::numeric;
    exception when others then
      raise exception using
        errcode = '22023',
        message = 'invalid_persisted_wolfie_meeting_rubric';
    end;
    if v_dimension_score not between 0 and 100 then
      raise exception using
        errcode = '22023',
        message = 'invalid_persisted_wolfie_meeting_rubric';
    end if;
    v_canonical_rubric := v_canonical_rubric
      || pg_catalog.jsonb_build_object(
        v_rubric_dimension,
        v_dimension_score
      );
  end loop;

  return query
  with rubric_dimensions as (
    select
      ordered.dimension_name,
      ordered.dimension_order::integer as dimension_order,
      (v_canonical_rubric ->> ordered.dimension_name)::numeric
        as dimension_score
    from pg_catalog.unnest(array[
      'taskCompletion',
      'structureAndFacilitation',
      'interactionAndTurnTaking',
      'clarificationAndQuestionHandling',
      'diplomacyAndNegotiation',
      'clarityAndConcision',
      'accuracyAndNaturalness',
      'decisionAndActionableClose'
    ]::text[]) with ordinality
      as ordered(dimension_name, dimension_order)
  ), priorities as (
    select
      dimension_name,
      dimension_order,
      dimension_score,
      0 as group_order,
      pg_catalog.row_number() over (
        order by dimension_score, dimension_order
      )::integer as candidate_order
    from rubric_dimensions
    where dimension_score < 75
    order by candidate_order
    limit 3
  ), strengths as (
    select
      dimension_name,
      dimension_order,
      dimension_score,
      1 as group_order,
      pg_catalog.row_number() over (
        order by dimension_score desc, dimension_order
      )::integer as candidate_order
    from rubric_dimensions
    where dimension_score >= 75
    order by candidate_order
    limit 2
  ), selected_dimensions as (
    select * from priorities
    union all
    select * from strengths
  )
  select
    v_attempt.tenant_id,
    v_attempt.student_id,
    v_attempt.session_id,
    v_attempt.id,
    case
      when selected.dimension_score >= 75 then 'strength'
      when v_attempt.requires_retry then 'structure_in_progress'
      else 'recommended_strategy'
    end,
    selected.dimension_name,
    pg_catalog.concat(
      'meeting:',
      v_attempt.student_id::text,
      ':',
      selected.dimension_name,
      ':',
      case
        when selected.dimension_score >= 75 then 'strength'
        when v_attempt.requires_retry then 'structure_in_progress'
        else 'recommended_strategy'
      end
    ),
    case selected.dimension_name
      when 'taskCompletion' then
        case when selected.dimension_score >= 75
          then 'Keep the meeting objective, expected outcome, and main request explicit.'
          else 'State the meeting objective, expected outcome, and main request explicitly.' end
      when 'structureAndFacilitation' then
        case when selected.dimension_score >= 75
          then 'Keep facilitating the meeting through a clear, signposted sequence.'
          else 'Use a clear sequence: opening, context, evidence, proposal, next steps, and close.' end
      when 'interactionAndTurnTaking' then
        case when selected.dimension_score >= 75
          then 'Keep inviting contributions and managing turn-taking explicitly.'
          else 'Invite contributions, manage turn-taking, and acknowledge other participants.' end
      when 'clarificationAndQuestionHandling' then
        case when selected.dimension_score >= 75
          then 'Keep clarifying questions and confirming shared understanding.'
          else 'Clarify questions before answering and confirm shared understanding.' end
      when 'diplomacyAndNegotiation' then
        case when selected.dimension_score >= 75
          then 'Keep using diplomatic language when negotiating or disagreeing.'
          else 'Use diplomatic language to disagree, negotiate, and propose alternatives.' end
      when 'clarityAndConcision' then
        case when selected.dimension_score >= 75
          then 'Keep contributions concise, specific, and easy to act on.'
          else 'Make each contribution concise, specific, and easy to act on.' end
      when 'accuracyAndNaturalness' then
        case when selected.dimension_score >= 75
          then 'Keep using accurate, natural English without sacrificing fluency.'
          else 'Use accurate, natural English while preserving fluency.' end
      when 'decisionAndActionableClose' then
        case when selected.dimension_score >= 75
          then 'Keep closing with a decision, owner, deadline, and next step.'
          else 'Close with the decision, owner, deadline, and verifiable next step.' end
    end,
    case when selected.dimension_score >= 75 then 0.8 else 0.85 end::numeric,
    pg_catalog.jsonb_build_object(
      'basis', 'session_assessment',
      'policyVersion', 1,
      'attemptId', v_attempt.id,
      'stepKey', v_attempt.step_key,
      'score', v_attempt.score,
      'dimension', selected.dimension_name,
      'dimensionScore', selected.dimension_score,
      'rubric', v_canonical_rubric
    )
  from selected_dimensions as selected
  order by selected.group_order, selected.candidate_order;
end;
$$;


--
-- Name: wolfie_prepare_checkout_account_internal(text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.wolfie_prepare_checkout_account_internal(p_full_name text, p_terms_version text, p_quiz jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_profile public.profiles%rowtype;
  v_account public.hub_accounts%rowtype;
  v_pending_plan_id uuid;
  v_existing_school_tenant text;
  v_full_name text := pg_catalog.left(
    nullif(pg_catalog.btrim(p_full_name), ''),
    160
  );
  v_terms_version text := pg_catalog.left(
    nullif(pg_catalog.btrim(p_terms_version), ''),
    80
  );
  v_quiz jsonb := coalesce(p_quiz, '{}'::jsonb);
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if v_full_name is null or pg_catalog.char_length(v_full_name) < 3 then
    raise exception using errcode = '22023', message = 'full_name_required';
  end if;
  if v_terms_version is null
     or pg_catalog.char_length(v_terms_version) < 3 then
    raise exception using errcode = '22023', message = 'terms_acceptance_required';
  end if;
  if pg_catalog.jsonb_typeof(v_quiz) <> 'object'
     or pg_catalog.pg_column_size(v_quiz) > 16000 then
    raise exception using errcode = '22023', message = 'invalid_quiz_snapshot';
  end if;

  select * into v_profile
  from public.profiles
  where id = v_user_id
  for update;
  if not found then
    raise exception using errcode = '42501', message = 'profile_required';
  end if;

  select membership.tenant_id into v_existing_school_tenant
  from public.tenant_memberships as membership
  where membership.user_id = v_user_id
    and membership.tenant_id <> 'wolfie-direct'
    and membership.status = 'ACTIVE'
    and membership.role = 'STUDENT'
  order by membership.is_primary desc, membership.created_at, membership.id
  limit 1;
  if found then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'alreadyIncluded', true,
      'accessKind', 'SCHOOL',
      'tenantId', v_existing_school_tenant
    );
  end if;

  if v_profile.tenant_id is null
     and v_profile.role not in ('STUDENT', 'NON_STUDENT') then
    raise exception using errcode = '42501',
      message = 'profile_not_eligible_for_standalone';
  elsif v_profile.tenant_id = 'wolfie-direct'
        and v_profile.role <> 'STUDENT' then
    raise exception using errcode = '42501',
      message = 'invalid_wolfie_profile_role';
  elsif v_profile.tenant_id is not null
        and v_profile.tenant_id <> 'wolfie-direct' then
    raise exception using errcode = '42501',
      message = 'existing_school_profile_not_eligible_for_standalone';
  end if;

  select account.* into v_account
  from public.hub_accounts as account
  where account.owner_user_id = v_user_id
    and account.account_type = 'PERSONAL'
  order by account.created_at
  limit 1
  for update;

  if not found then
    insert into public.hub_accounts (
      account_type, audience, name, owner_user_id, status, metadata
    ) values (
      'PERSONAL', 'LEARNER', v_full_name, v_user_id, 'ACTIVE',
      pg_catalog.jsonb_build_object(
        'product_family', 'WOLFIE_STANDALONE',
        'wolfie_onboarding_started_at', pg_catalog.now()
      )
    ) returning * into v_account;
  else
    update public.hub_accounts
    set audience = 'LEARNER',
        name = v_full_name,
        status = 'ACTIVE',
        metadata = metadata || pg_catalog.jsonb_build_object(
          'wolfie_onboarding_started_at', pg_catalog.now()
        )
    where id = v_account.id
    returning * into v_account;
  end if;

  insert into public.hub_memberships (
    account_id, user_id, membership_role, status
  ) values (
    v_account.id, v_user_id, 'OWNER', 'ACTIVE'
  )
  on conflict (account_id, user_id) do update
  set membership_role = 'OWNER',
      status = 'ACTIVE',
      updated_at = pg_catalog.now();

  select id into v_pending_plan_id
  from public.student_pricing_plans
  where tenant_id = 'wolfie-direct' and name = 'Wolfie Pendente'
  order by id
  limit 1;
  if v_pending_plan_id is null then
    raise exception using errcode = '55000', message = 'wolfie_pending_plan_missing';
  end if;

  perform pg_catalog.set_config('app.enrollment_claim', '1', true);
  update public.profiles
  set full_name = v_full_name,
      role = 'STUDENT',
      tenant_id = 'wolfie-direct',
      status_financial = 'PENDING',
      fidelity_plan = 'Wolfie Pendente'
  where id = v_user_id;

  insert into public.tenant_memberships (
    user_id, tenant_id, role, status, is_primary, student_plan_id
  ) values (
    v_user_id, 'wolfie-direct', 'STUDENT', 'ACTIVE', true, v_pending_plan_id
  )
  on conflict (user_id, tenant_id) do update
  set role = 'STUDENT',
      status = 'ACTIVE',
      is_primary = true,
      student_plan_id = v_pending_plan_id,
      updated_at = pg_catalog.now();

  insert into public.tenant_user_contexts(user_id, tenant_id)
  values (v_user_id, 'wolfie-direct')
  on conflict (user_id) do update
  set tenant_id = excluded.tenant_id,
      updated_at = pg_catalog.now();

  insert into public.wolfie_standalone_acceptances (
    account_id, user_id, terms_version, quiz_snapshot
  ) values (
    v_account.id, v_user_id, v_terms_version, v_quiz
  )
  on conflict (account_id, user_id, terms_version) do update
  set quiz_snapshot = excluded.quiz_snapshot,
      accepted_at = pg_catalog.now();

  insert into public.hub_conversion_events (
    account_id, user_id, event_name, source, metadata
  ) values (
    v_account.id,
    v_user_id,
    'wolfie_checkout_account_prepared',
    'wolfie_funnel',
    pg_catalog.jsonb_build_object('termsVersion', v_terms_version)
  );

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'alreadyIncluded', false,
    'accountId', v_account.id,
    'tenantId', 'wolfie-direct',
    'accessKind', 'STANDALONE'
  );
end;
$$;


--
-- Name: wolfie_tier_snapshot(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.wolfie_tier_snapshot(p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_tenant     text;
  v_access     jsonb;
  v_balance    jsonb;
  v_enforced   boolean;
  v_remaining  integer;
  v_credits    integer;
  v_plan_limit integer;
  v_premium    boolean;
  v_live       boolean;
  v_reason     text;
BEGIN
  IF p_student_id IS NULL THEN
    RETURN jsonb_build_object(
      'tier', 'FREE', 'voice_replies', false, 'live_allowed', false,
      'live_enforced', false, 'remaining_minutes', 0, 'reason', 'sem_aluno');
  END IF;

  SELECT p.tenant_id INTO v_tenant
  FROM public.profiles p
  WHERE p.id = p_student_id;

  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object(
      'tier', 'FREE', 'voice_replies', false, 'live_allowed', false,
      'live_enforced', false, 'remaining_minutes', 0, 'reason', 'perfil_ausente');
  END IF;

  -- Assinante direto: a assinatura viva é a única fonte, e ela já é fail-closed.
  IF v_tenant = 'wolfie-direct' THEN
    v_access := private.wolfie_access_snapshot(p_student_id);
    v_premium := COALESCE((v_access ->> 'allowed')::boolean, false);
    RETURN jsonb_build_object(
      'tier',              CASE WHEN v_premium THEN 'PREMIUM' ELSE 'FREE' END,
      'source',            'SUBSCRIPTION',
      'voice_replies',     v_premium,
      'live_allowed',      v_premium,
      'live_enforced',     true,
      'remaining_minutes', 0,
      'plan_code',         v_access ->> 'planCode',
      'reason',            CASE WHEN v_premium THEN 'assinatura_ativa'
                                ELSE COALESCE(v_access ->> 'code', 'sem_assinatura') END);
  END IF;

  -- Aluno de escola: premium é a franquia de minutos que a escola vendeu —
  -- por plano (`student_plan_entitlements`) ou por crédito comprado.
  v_balance    := public.wolfie_live_balance(v_tenant, p_student_id);
  v_enforced   := COALESCE((v_balance ->> 'enforced')::boolean, false);
  v_remaining  := COALESCE((v_balance ->> 'remaining')::integer, 0);
  v_credits    := COALESCE((v_balance ->> 'credits')::integer, 0);
  v_plan_limit := COALESCE((v_balance ->> 'plan_limit')::integer, 0);
  v_live       := COALESCE((v_balance ->> 'allowed')::boolean, true);

  -- Franquia não configurada NÃO é premium: é ausência de decisão comercial.
  -- Tratar como premium daria voz paga a toda a escola de graça, que é
  -- exatamente o custo invisível que esta mudança veio fechar.
  v_premium := v_enforced AND v_remaining > 0;

  v_reason := CASE
    WHEN NOT v_enforced THEN 'franquia_nao_configurada'
    WHEN v_remaining > 0 THEN 'franquia_disponivel'
    ELSE 'franquia_esgotada'
  END;

  RETURN jsonb_build_object(
    'tier',              CASE WHEN v_premium THEN 'PREMIUM' ELSE 'FREE' END,
    'source',            CASE WHEN v_credits > 0 AND v_plan_limit = 0
                              THEN 'CREDITS' ELSE 'SCHOOL_PLAN' END,
    'voice_replies',     v_premium,
    'live_allowed',      v_live,
    'live_enforced',     v_enforced,
    'remaining_minutes', v_remaining,
    'credit_minutes',    v_credits,
    'reason',            v_reason);
EXCEPTION WHEN others THEN
  -- Falhar para GRATUITO: sem certeza de que é premium, não se gasta voz paga.
  RETURN jsonb_build_object(
    'tier', 'FREE', 'voice_replies', false, 'live_allowed', true,
    'live_enforced', false, 'remaining_minutes', 0, 'reason', 'tier_indisponivel');
END;
$$;


--
-- Name: FUNCTION wolfie_tier_snapshot(p_student_id uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.wolfie_tier_snapshot(p_student_id uuid) IS 'Decide gratuito x premium do Wolfie. voice_replies=false significa que o Wolfie responde por escrito: a voz paga é do tier premium.';


--
-- Name: _can_manage_training(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._can_manage_training(p_tenant_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.profiles as caller
     where caller.id = (select auth.uid())
       and (
         caller.role = 'SUPER_ADMIN'
         or (
           caller.tenant_id = p_tenant_id
           and (
             caller.role = 'SCHOOL_ADMIN'
             or (
               caller.role = 'TEACHER'
               and caller.is_trainer is true
             )
           )
         )
       )
  );
$$;


--
-- Name: _enqueue_school_whatsapp(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._enqueue_school_whatsapp(p_tenant text, p_to_phone text, p_name text, p_msg text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_admin uuid;
BEGIN
    IF p_to_phone IS NULL OR btrim(p_to_phone) = '' THEN RETURN; END IF;
    SELECT id INTO v_admin FROM public.profiles
      WHERE tenant_id = p_tenant AND role IN ('SCHOOL_ADMIN','SUPER_ADMIN')
      ORDER BY role DESC LIMIT 1;
    INSERT INTO public.notification_queue
        (tenant_id, teacher_id, student_name, student_phone, message_body, notification_kind, source_type, status, scheduled_for)
    VALUES (p_tenant, v_admin, p_name, p_to_phone, p_msg, 'TEACHER_TRANSFER', 'teacher_transfer', 'pending', now());
END;
$$;


