--
-- Name: _teacher_can_access_student(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._teacher_can_access_student(p_student_id uuid, p_tenant_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.profiles as caller
      join public.profiles as student
        on student.id = p_student_id
     where caller.id = (select auth.uid())
       and caller.role = 'TEACHER'
       and caller.tenant_id = p_tenant_id
       and student.role = 'STUDENT'
       and student.tenant_id = p_tenant_id
       and (
         student.professor_id = caller.id
         or student.professor_id2 = caller.id
         or exists (
           select 1
             from public.bookings as booking
            where booking.student_id = student.id
              and booking.teacher_id = caller.id
              and booking.tenant_id = p_tenant_id
              and booking.status = 'SCHEDULED'
         )
       )
  );
$$;


--
-- Name: abort_student_lifecycle_operation(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.abort_student_lifecycle_operation(p_operation_id uuid, p_claim_token uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_tenant_id text;
  operation_student_id uuid;
  normalized_reason text := nullif(
    pg_catalog.left(pg_catalog.btrim(coalesce(p_reason, '')), 500),
    ''
  );
  changed_id uuid;
begin
  if p_operation_id is null or p_claim_token is null
     or normalized_reason is null
  then
    raise exception using
      errcode = '22023', message = 'student_lifecycle_abort_invalid';
  end if;

  select operation.tenant_id, operation.student_id
    into operation_tenant_id, operation_student_id
    from public.student_offboarding_operations as operation
   where operation.id = p_operation_id;
  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || operation_tenant_id || ':' ||
        operation_student_id::text,
      0
    )
  );

  update public.student_offboarding_operations
     set status = 'ABORTED',
         last_error = normalized_reason,
         lease_expires_at = pg_catalog.now(),
         completed_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where id = p_operation_id
     and tenant_id = operation_tenant_id
     and student_id = operation_student_id
     and claim_token = p_claim_token
     and (
       (
         status = 'CLAIMED'
         and provider_started_at is null
       )
       or (
         status = 'BLOCKED'
         and provider_started_at is null
         and normalized_reason = 'blocked_pre_provider_released'
       )
       or (
         status in ('PROVIDER_MUTATING', 'UNKNOWN')
         and target_lifecycle_status in ('suspended', 'active')
         and normalized_reason = 'subscription_absent_new_enrollment_required'
       )
     )
   returning id into changed_id;

  return pg_catalog.jsonb_build_object(
    'ok', changed_id is not null,
    'action', case when changed_id is null then null else 'ABORTED' end,
    'reason', case when changed_id is null then 'claim_lost' else null end
  );
end;
$$;


--
-- Name: accept_teacher_contract(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_teacher_contract(p_typed_signature text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_role text;
  v_accepted boolean;
  v_ip text;
  v_sig text := btrim(coalesce(p_typed_signature, ''));
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nao_autenticado');
  END IF;

  SELECT role, contract_accepted INTO v_role, v_accepted
  FROM profiles WHERE id = v_uid;

  IF v_role IS DISTINCT FROM 'TEACHER' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'apenas_professor');
  END IF;

  IF coalesce(v_accepted, false) = true THEN
    RETURN jsonb_build_object('ok', true, 'already', true);
  END IF;

  IF length(v_sig) < 3 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'assinatura_invalida');
  END IF;

  -- IP real do cliente via headers propagados pelo PostgREST (x-forwarded-for cai no primeiro IP).
  BEGIN
    v_ip := split_part(coalesce(
      current_setting('request.headers', true)::json->>'x-forwarded-for',
      current_setting('request.headers', true)::json->>'x-real-ip',
      ''), ',', 1);
  EXCEPTION WHEN others THEN
    v_ip := NULL;
  END;

  UPDATE profiles SET
    contract_accepted = true,
    accepted_at = now(),
    typed_signature = v_sig,
    signature_ip = nullif(v_ip, ''),
    signature_hash = encode(digest(v_uid::text || '|' || v_sig || '|' || now()::text, 'sha256'), 'hex')
  WHERE id = v_uid;

  RETURN jsonb_build_object('ok', true, 'accepted_at', now());
END;
$$;


--
-- Name: ack_nf_tour(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ack_nf_tour(p_closing_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_owner uuid;
  v_ack timestamptz;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'Não autenticado');
  end if;

  select teacher_id, nf_tour_ack_at into v_owner, v_ack
    from public.teacher_closings
   where id = p_closing_id;

  if v_owner is null then
    return jsonb_build_object('ok', false, 'error', 'Fechamento não encontrado');
  end if;

  if v_owner <> v_uid then
    return jsonb_build_object('ok', false, 'error', 'Sem permissão');
  end if;

  -- Idempotente: reconfirmar não reescreve a data do primeiro aceite.
  if v_ack is not null then
    return jsonb_build_object('ok', true, 'already', true, 'acked_at', v_ack);
  end if;

  update public.teacher_closings
     set nf_tour_ack_at = now()
   where id = p_closing_id;

  return jsonb_build_object('ok', true, 'already', false);
end;
$$;


--
-- Name: activate_wolfie_live_grant(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_wolfie_live_grant(p_grant_id uuid, p_provider_call_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_grant public.wolfie_live_grants%rowtype;
begin
  if p_grant_id is null
     or p_provider_call_id is null
     or p_provider_call_id !~ '^[A-Za-z0-9_-]{1,200}$' then
    raise exception 'invalid_live_provider_call';
  end if;

  select *
    into v_grant
    from public.wolfie_live_grants
   where id = p_grant_id
   for update;
  if not found or v_grant.status <> 'RESERVED' then
    return pg_catalog.jsonb_build_object('activated', false);
  end if;
  if v_grant.reservation_expires_at <= pg_catalog.now() then
    update public.wolfie_live_grants
       set status = 'RELEASED',
           settled_at = pg_catalog.now(),
           updated_at = pg_catalog.now()
     where id = p_grant_id;
    return pg_catalog.jsonb_build_object(
      'activated', false,
      'reason', 'reservation_expired'
    );
  end if;

  update public.wolfie_live_grants
     set status = 'ACTIVE',
         started_at = pg_catalog.now(),
         provider_call_id = p_provider_call_id,
         lease_expires_at = pg_catalog.now()
           + pg_catalog.make_interval(secs => client_max_seconds),
         updated_at = pg_catalog.now()
   where id = p_grant_id
   returning * into v_grant;

  return pg_catalog.jsonb_build_object(
    'activated', true,
    'grantId', v_grant.id,
    'maxSeconds', v_grant.client_max_seconds,
    'leaseExpiresAt', v_grant.lease_expires_at
  );
end;
$_$;


--
-- Name: advance_wolfie_assignment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_wolfie_assignment(p_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_next text := upper(btrim(COALESCE(p_status, '')));
BEGIN
  IF v_next NOT IN ('STARTED', 'DONE') THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'status_invalido');
  END IF;

  UPDATE public.wolfie_assignments
  SET status = v_next,
      started_at = COALESCE(started_at,
        CASE WHEN v_next IN ('STARTED', 'DONE') THEN now() END),
      completed_at = CASE WHEN v_next = 'DONE' THEN now() ELSE completed_at END
  WHERE id = p_id AND student_id = auth.uid() AND status <> 'DONE';

  RETURN jsonb_build_object('ok', FOUND);
END;
$$;


--
-- Name: ai_cost_por_aluno(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_cost_por_aluno(p_month text DEFAULT NULL::text, p_usd_brl numeric DEFAULT 5.50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_jwt text; v_role text; v_tenant text; v_mes text;
  v_pin numeric; v_pout numeric; v_pcache numeric;
BEGIN
  v_jwt := COALESCE(current_setting('request.jwt.claims', true)::json->>'role', '');
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_jwt IN ('anon','authenticated') THEN
    IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
      RETURN jsonb_build_object('error','sem_permissao');
    END IF;
  END IF;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('error','escola_nao_identificada'); END IF;

  v_mes := COALESCE(p_month, to_char((now() AT TIME ZONE 'America/Sao_Paulo')::date,'YYYY-MM'));
  IF v_mes !~ '^\d{4}-\d{2}$' THEN RETURN jsonb_build_object('error','mes_invalido'); END IF;
  IF p_usd_brl IS NULL OR p_usd_brl <= 0 THEN RETURN jsonb_build_object('error','cambio_invalido'); END IF;

  SELECT input_usd_per_1m, output_usd_per_1m, cached_usd_per_1m
    INTO v_pin, v_pout, v_pcache
    FROM ai_model_pricing WHERE model = 'gpt-realtime-2.1';
  IF v_pin IS NULL THEN RETURN jsonb_build_object('error','preco_da_voz_nao_cadastrado'); END IF;

  RETURN (
  WITH voz AS (
    SELECT r.student_id, r.student_name, r.sessions, r.turns,
           -- cached é subconjunto do input: tira antes de multiplicar
           GREATEST(r.input_audio_tokens + r.input_text_tokens - r.cached_tokens, 0) AS in_pago,
           r.cached_tokens,
           r.output_audio_tokens + r.output_text_tokens AS out_total
      FROM wolfie_realtime_usage_report(v_mes) r
  ), voz_custo AS (
    SELECT v.*,
           (v.in_pago * v_pin + v.cached_tokens * v_pcache + v.out_total * v_pout) / 1000000.0 AS usd
      FROM voz v
  ), minutos AS (
    SELECT g.student_id, ROUND(SUM(g.consumed_seconds)/60.0, 1) AS min
      FROM wolfie_live_grants g
     WHERE g.tenant_id = v_tenant
       AND to_char(g.created_at AT TIME ZONE 'America/Sao_Paulo','YYYY-MM') = v_mes
     GROUP BY 1
  ), texto AS (
    -- Texto atribuível a aluno. Evento sem user_id (cron, tarefa da escola) não
    -- pertence a ninguém e entra só no total geral.
    SELECT e.user_id AS student_id,
           SUM((GREATEST(e.input_tokens - COALESCE(e.cached_tokens,0),0) * COALESCE(pr.input_usd_per_1m,0)
              + COALESCE(e.cached_tokens,0) * COALESCE(pr.cached_usd_per_1m,0)
              + e.output_tokens * COALESCE(pr.output_usd_per_1m,0)) / 1000000.0) AS usd
      FROM ai_usage_events e
      LEFT JOIN ai_model_pricing pr ON pr.model = e.model
     WHERE e.tenant_id = v_tenant AND e.user_id IS NOT NULL
       AND to_char(e.created_at AT TIME ZONE 'America/Sao_Paulo','YYYY-MM') = v_mes
     GROUP BY 1
  ), juntos AS (
    SELECT COALESCE(vc.student_id, t.student_id) AS student_id,
           COALESCE(vc.student_name, trim(p.full_name), 'Sem nome') AS nome,
           COALESCE(vc.sessions,0)::int AS sessoes,
           COALESCE(m.min,0) AS minutos,
           ROUND(COALESCE(vc.usd,0) * p_usd_brl, 2) AS voz_brl,
           ROUND(COALESCE(t.usd,0) * p_usd_brl, 2) AS texto_brl,
           ROUND((COALESCE(vc.usd,0) + COALESCE(t.usd,0)) * p_usd_brl, 2) AS total_brl,
           COALESCE(p.monthly_fee,0) AS mensalidade
      FROM voz_custo vc
      FULL JOIN texto t ON t.student_id = vc.student_id
      LEFT JOIN profiles p ON p.id = COALESCE(vc.student_id, t.student_id)
      LEFT JOIN minutos m ON m.student_id = COALESCE(vc.student_id, t.student_id)
  )
  SELECT jsonb_build_object(
    'mes', v_mes,
    'usd_brl', p_usd_brl,
    'aviso', 'Custo de voz é TETO: ai_model_pricing guarda um preço por modelo, e a OpenAI cobra áudio e texto do Realtime a preços diferentes — o texto da conversa entra aqui a preço de áudio.',
    'total_brl', (SELECT ROUND(COALESCE(SUM(total_brl),0),2) FROM juntos),
    'minutos_totais', (SELECT COALESCE(SUM(minutos),0) FROM juntos),
    'custo_por_minuto_brl', (SELECT CASE WHEN COALESCE(SUM(minutos),0) > 0
        THEN ROUND(SUM(voz_brl)/SUM(minutos),2) END FROM juntos),
    'alunos', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'student_id', j.student_id, 'aluno', j.nome,
        'sessoes', j.sessoes, 'minutos', j.minutos,
        'voz_brl', j.voz_brl, 'texto_brl', j.texto_brl, 'total_brl', j.total_brl,
        'mensalidade', j.mensalidade,
        'pct_da_mensalidade', CASE WHEN j.mensalidade > 0
            THEN ROUND(100 * j.total_brl / j.mensalidade, 1) END)
        ORDER BY j.total_brl DESC) FROM juntos j WHERE j.total_brl > 0), '[]'::jsonb),
    -- Custo que a escola tem e não pertence a aluno nenhum (crons, IA de gestão).
    'sem_aluno_brl', (SELECT ROUND(COALESCE(SUM(
        (GREATEST(e.input_tokens - COALESCE(e.cached_tokens,0),0) * COALESCE(pr.input_usd_per_1m,0)
       + COALESCE(e.cached_tokens,0) * COALESCE(pr.cached_usd_per_1m,0)
       + e.output_tokens * COALESCE(pr.output_usd_per_1m,0)) / 1000000.0),0) * p_usd_brl, 2)
      FROM ai_usage_events e LEFT JOIN ai_model_pricing pr ON pr.model = e.model
     WHERE e.tenant_id = v_tenant AND e.user_id IS NULL
       AND to_char(e.created_at AT TIME ZONE 'America/Sao_Paulo','YYYY-MM') = v_mes),
    -- Modelo sem preço: custo real que este relatório NÃO está contando.
    'sem_preco', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'model', x.model, 'chamadas', x.n, 'tokens', x.tok))
      FROM (SELECT e.model, count(*)::int AS n,
                   SUM(e.input_tokens + e.output_tokens)::bigint AS tok
              FROM ai_usage_events e
             WHERE e.tenant_id = v_tenant
               AND to_char(e.created_at AT TIME ZONE 'America/Sao_Paulo','YYYY-MM') = v_mes
               AND NOT EXISTS (SELECT 1 FROM ai_model_pricing pr WHERE pr.model = e.model)
             GROUP BY 1) x), '[]'::jsonb)
  ));
END;
$_$;


--
-- Name: FUNCTION ai_cost_por_aluno(p_month text, p_usd_brl numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ai_cost_por_aluno(p_month text, p_usd_brl numeric) IS 'Custo de IA em reais por aluno (voz + texto). Cached sai do input antes do cálculo; modelo sem preço aparece em sem_preco em vez de virar zero.';


--
-- Name: ai_cost_report(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_cost_report(p_month text DEFAULT NULL::text) RETURNS TABLE(feature text, model text, chamadas bigint, input_tokens bigint, output_tokens bigint, cached_tokens bigint, custo_usd numeric, tem_preco boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_column
declare
  v_caller uuid := (select auth.uid());
  v_tenant text;
  v_role text;
  v_start date;
begin
  v_tenant := private.active_tenant_id(v_caller);
  v_role := private.active_tenant_role(v_caller);
  if v_tenant is null
     or v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') then
    raise exception using errcode = '42501', message = 'sem_permissao';
  end if;

  v_start := date_trunc(
    'month',
    coalesce(
      to_date(nullif(p_month, ''), 'YYYY-MM'),
      current_date
    )
  )::date;

  return query
  select
    event_row.feature,
    event_row.model,
    pg_catalog.count(*)::bigint,
    pg_catalog.sum(event_row.input_tokens)::bigint,
    pg_catalog.sum(event_row.output_tokens)::bigint,
    pg_catalog.sum(event_row.cached_tokens)::bigint,
    pg_catalog.round(pg_catalog.sum(
      (event_row.input_tokens - event_row.cached_tokens)
        * coalesce(pricing.input_usd_per_1m, 0)
      + event_row.cached_tokens * coalesce(pricing.cached_usd_per_1m, 0)
      + event_row.output_tokens * coalesce(pricing.output_usd_per_1m, 0)
    ) / 1000000.0, 4),
    pg_catalog.bool_or(pricing.model is not null)
  from public.ai_usage_events as event_row
  left join public.ai_model_pricing as pricing
    on pricing.model = event_row.model
  where event_row.tenant_id = v_tenant
    and event_row.created_at >= v_start
    and event_row.created_at < v_start + interval '1 month'
  group by event_row.feature, event_row.model
  order by 7 desc nulls last;
end;
$$;


--
-- Name: alunos_sem_assinatura(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.alunos_sem_assinatura(p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_jwt text; v_role text; v_tenant text;
BEGIN
  v_jwt := COALESCE(current_setting('request.jwt.claims', true)::json->>'role', '');
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_jwt IN ('anon','authenticated') THEN
    IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
      RETURN jsonb_build_object('error','sem_permissao');
    END IF;
    IF v_role = 'SUPER_ADMIN' THEN v_tenant := COALESCE(p_tenant, v_tenant); END IF;
  ELSE
    v_tenant := COALESCE(p_tenant, v_tenant);
  END IF;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('error','escola_nao_identificada'); END IF;

  RETURN (
    WITH candidatos AS (
      SELECT p.id, trim(p.full_name) AS nome, p.monthly_fee AS mensalidade,
             p.created_at::date AS matriculado,
             -- Só conta quem REALMENTE estuda: a base tem conta de teste, e
             -- alarmar por elas ensina o diretor a ignorar o alerta.
             (SELECT count(*) FROM v_payable_class_logs v
               WHERE v.student_id = p.id
                 AND v.class_date >= (current_date - 60))::int AS aulas_60d,
             (SELECT max(v.class_date) FROM v_payable_class_logs v WHERE v.student_id = p.id) AS ultima_aula,
             (SELECT count(*) FROM student_payments sp WHERE sp.student_id = p.id)::int AS cobrancas_na_vida
        FROM profiles p
       WHERE p.tenant_id = v_tenant AND p.role = 'STUDENT'
         AND COALESCE(p.monthly_fee,0) > 0
         AND COALESCE(p.subscription_id,'') = ''
         AND is_student_notifiable(p.id)
    ), reais AS (
      SELECT * FROM candidatos WHERE aulas_60d > 0
    )
    SELECT jsonb_build_object(
      'alunos', (SELECT count(*)::int FROM reais),
      'mensalidade_mensal_em_risco', (SELECT round(COALESCE(sum(mensalidade),0),2) FROM reais),
      'nunca_cobrados', (SELECT count(*)::int FROM reais WHERE cobrancas_na_vida = 0),
      'detalhe', COALESCE((SELECT jsonb_agg(jsonb_build_object(
          'aluno', nome, 'mensalidade', mensalidade, 'matriculado', matriculado,
          'aulas_ultimos_60d', aulas_60d, 'ultima_aula', ultima_aula,
          'cobrancas_na_vida', cobrancas_na_vida)
          ORDER BY cobrancas_na_vida, mensalidade DESC) FROM reais), '[]'::jsonb)
    )
  );
END;
$$;


--
-- Name: FUNCTION alunos_sem_assinatura(p_tenant text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.alunos_sem_assinatura(p_tenant text) IS 'Aluno ATIVO, com mensalidade cadastrada, tendo aula, e sem subscription_id — ninguém gera a cobrança dele. Não aparece em inadimplência porque a cobrança nunca chega a vencer.';


--
-- Name: apply_active_student_payment_event(text, uuid, uuid, text, text, text, text, text, text, timestamp with time zone, integer, text, numeric, date, date, text, text, text, text, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_active_student_payment_event(p_provider_payment_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_expected_provider_subscription_id text, p_canonical_reference text, p_event_id text, p_event_name text, p_event_created_at timestamp with time zone, p_event_rank integer, p_provider_status text, p_provider_value numeric, p_due_date date, p_payment_date date, p_billing_type text, p_invoice_url text, p_description text, p_payment_type text, p_credited_at timestamp with time zone, p_estimated_credit_at timestamp with time zone, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  profile_row public.profiles%rowtype;
  payment_row public.student_payments%rowtype;
  normalized_payment_id text := nullif(pg_catalog.btrim(coalesce(p_provider_payment_id, '')), '');
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_expected_tenant_id, '')), '');
  normalized_customer text := nullif(pg_catalog.btrim(coalesce(p_expected_provider_customer_id, '')), '');
  normalized_subscription text := nullif(pg_catalog.btrim(coalesce(p_expected_provider_subscription_id, '')), '');
  normalized_reference text := nullif(pg_catalog.btrim(coalesce(p_canonical_reference, '')), '');
  normalized_event_id text := nullif(pg_catalog.btrim(coalesce(p_event_id, '')), '');
  normalized_event text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_event_name, '')));
  normalized_provider_status text := nullif(pg_catalog.btrim(coalesce(p_provider_status, '')), '');
  normalized_billing_type text := nullif(pg_catalog.btrim(coalesce(p_billing_type, '')), '');
  normalized_invoice_url text := nullif(pg_catalog.btrim(coalesce(p_invoice_url, '')), '');
  normalized_description text := coalesce(nullif(pg_catalog.btrim(coalesce(p_description, '')), ''), 'Mensalidade');
  normalized_payment_type text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_payment_type, '')));
  payload_event_created_text text;
  payload_event_created_at timestamptz;
  payload_value numeric;
  expected_rank integer;
  membership_count integer := 0;
  active_membership_count integer := 0;
  reference_parts text[];
  reference_is_canonical boolean := false;
  reference_offer_id uuid;
  inserted_payment_id uuid;
  next_status text;
  previous_status text;
  was_already_paid boolean := false;
  local_payment_count integer := 0;
  lifecycle_is_active boolean := false;
  lifecycle_operation_active boolean := false;
  inactive_result jsonb;
begin
  expected_rank := case
    when normalized_event in (
      'PAYMENT_REFUNDED', 'PAYMENT_DELETED',
      'PAYMENT_CHARGEBACK_REQUESTED', 'PAYMENT_RECEIVED_IN_CASH_UNDONE'
    ) then 100
    when normalized_event = 'PAYMENT_REFUND_IN_PROGRESS' then 95
    when normalized_event = 'PAYMENT_PARTIALLY_REFUNDED' then 90
    when normalized_event in ('PAYMENT_RECEIVED', 'PAYMENT_RECEIVED_IN_CASH') then 80
    when normalized_event = 'PAYMENT_CONFIRMED' then 60
    when normalized_event = 'PAYMENT_OVERDUE' then 40
    when normalized_event = 'PAYMENT_UPDATED' then 30
    when normalized_event = 'PAYMENT_CREATED' then 20
    else 10
  end;

  if normalized_payment_id is null or pg_catalog.length(normalized_payment_id) > 240
     or p_expected_student_id is null
     or normalized_tenant is null or pg_catalog.length(normalized_tenant) > 240
     or normalized_customer is null or pg_catalog.length(normalized_customer) > 240
     or normalized_reference is null or pg_catalog.length(normalized_reference) > 500
     or normalized_event_id is null or pg_catalog.length(normalized_event_id) > 240
     or normalized_event = '' or pg_catalog.length(normalized_event) > 240
     or p_event_created_at is null or p_event_rank is distinct from expected_rank
     or normalized_provider_status is null or pg_catalog.length(normalized_provider_status) > 120
     or p_provider_value is null
     or p_provider_value::text in ('NaN', 'Infinity', '-Infinity')
     or p_provider_value <= 0 or p_due_date is null
     or normalized_payment_type not in ('ENROLLMENT', 'PRO_RATA', 'REFUND', 'SUBSCRIPTION')
     or jsonb_typeof(p_payload) <> 'object'
     or normalized_event in (
       'PAYMENT_REFUNDED', 'PAYMENT_PARTIALLY_REFUNDED',
       'PAYMENT_RECEIVED_IN_CASH_UNDONE'
     )
  then
    raise exception using errcode = '22023', message = 'active_payment_event_input_invalid';
  end if;

  if nullif(pg_catalog.btrim(p_payload #>> '{payment,id}'), '')
       is distinct from normalized_payment_id
     or nullif(pg_catalog.btrim(p_payload #>> '{payment,customer}'), '')
       is distinct from normalized_customer
     or nullif(pg_catalog.btrim(p_payload ->> 'id'), '')
       is distinct from normalized_event_id
     or pg_catalog.upper(pg_catalog.btrim(coalesce(p_payload ->> 'event', '')))
       is distinct from normalized_event
     or nullif(pg_catalog.btrim(p_payload #>> '{payment,subscription}'), '')
       is distinct from normalized_subscription
     or nullif(pg_catalog.btrim(p_payload #>> '{payment,dueDate}'), '')
       is distinct from p_due_date::text
     or nullif(pg_catalog.btrim(p_payload #>> '{payment,paymentDate}'), '')
       is distinct from (
         case when p_payment_date is null then null else p_payment_date::text end
       )
     or (
       nullif(pg_catalog.btrim(p_payload #>> '{payment,status}'), '') is not null
       and nullif(pg_catalog.btrim(p_payload #>> '{payment,status}'), '')
         is distinct from normalized_provider_status
     )
     or (
       normalized_billing_type is not null
       and nullif(pg_catalog.btrim(p_payload #>> '{payment,billingType}'), '')
         is distinct from normalized_billing_type
     )
     or (
       normalized_invoice_url is not null
       and coalesce(
         nullif(pg_catalog.btrim(p_payload #>> '{payment,bankSlipUrl}'), ''),
         nullif(pg_catalog.btrim(p_payload #>> '{payment,invoiceUrl}'), '')
       ) is distinct from normalized_invoice_url
     )
  then
    raise exception using errcode = '23514', message = 'active_payment_event_payload_identity_mismatch';
  end if;
  begin
    payload_value := (p_payload #>> '{payment,value}')::numeric;
  exception
    when invalid_text_representation or numeric_value_out_of_range then
      raise exception using errcode = '23514', message = 'active_payment_event_payload_value_invalid';
  end;
  if payload_value is null or payload_value::text in ('NaN', 'Infinity', '-Infinity')
     or pg_catalog.round(payload_value, 2) <> pg_catalog.round(p_provider_value, 2)
  then
    raise exception using errcode = '23514', message = 'active_payment_event_payload_value_mismatch';
  end if;
  payload_event_created_text := nullif(
    pg_catalog.btrim(coalesce(p_payload ->> 'dateCreated', '')),
    ''
  );
  begin
    payload_event_created_at := case
      when payload_event_created_text ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
        then (payload_event_created_text || ' 12:00:00+00')::timestamptz
      when payload_event_created_text ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$'
        then (payload_event_created_text || '+00')::timestamptz
      else payload_event_created_text::timestamptz
    end;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      raise exception using errcode = '23514', message = 'active_payment_event_payload_timestamp_invalid';
  end;
  if payload_event_created_at is null
     or payload_event_created_at is distinct from p_event_created_at
  then
    raise exception using errcode = '23514', message = 'active_payment_event_payload_timestamp_mismatch';
  end if;

  -- A subscription-created charge may omit its own reference, but the caller
  -- supplies the canonical reference obtained from the authoritative parent
  -- subscription GET. Direct one-time/manual charges must carry it themselves.
  if normalized_reference = p_expected_student_id::text then
    reference_is_canonical := true;
  elsif pg_catalog.lower(normalized_reference) ~ (
    '^student:' || p_expected_student_id::text || ':(one-time|pro-rata)$'
  ) then
    reference_is_canonical := normalized_subscription is null;
  elsif pg_catalog.lower(normalized_reference) ~ (
    '^manual-pix:[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:student:'
    || p_expected_student_id::text || '$'
  ) then
    reference_is_canonical := normalized_subscription is null;
  else
    reference_parts := pg_catalog.regexp_match(
      pg_catalog.lower(normalized_reference),
      '^enrollment:([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}):(subscription|one-time|pro-rata|fee)$'
    );
    if reference_parts is not null
       and (
         (normalized_subscription is not null and reference_parts[2] = 'subscription')
         or (normalized_subscription is null and reference_parts[2] <> 'subscription')
       )
    then
      reference_offer_id := reference_parts[1]::uuid;
    end if;
  end if;
  if (not reference_is_canonical and reference_offer_id is null)
     or (
       normalized_subscription is null
       and nullif(pg_catalog.btrim(p_payload #>> '{payment,externalReference}'), '')
         is distinct from normalized_reference
     )
     or (
       normalized_subscription is not null
       and nullif(pg_catalog.btrim(p_payload #>> '{payment,externalReference}'), '') is not null
       and nullif(pg_catalog.btrim(p_payload #>> '{payment,externalReference}'), '')
         is distinct from normalized_reference
     )
  then
    raise exception using errcode = '23514', message = 'active_payment_event_reference_mismatch';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' || p_expected_student_id::text,
      0
    )
  );

  if exists (
    select 1
      from public.student_payments as payment
     where (
       nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') = normalized_payment_id
       or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') = normalized_payment_id
     )
       and nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') is not null
       and nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') is not null
       and nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') <>
           nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '')
  ) then
    return jsonb_build_object('ok', false, 'reason', 'local_payment_provider_alias_divergence');
  end if;
  select count(*) into local_payment_count
    from public.student_payments as payment
   where nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') = normalized_payment_id
      or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') = normalized_payment_id;
  if local_payment_count > 1 then
    return jsonb_build_object('ok', false, 'reason', 'local_payment_binding_ambiguous');
  end if;
  if local_payment_count = 1 then
    select payment.* into payment_row
      from public.student_payments as payment
     where nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') = normalized_payment_id
        or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') = normalized_payment_id
     for update;
  end if;
  if payment_row.id is null and p_expected_local_payment_id is not null then
    return jsonb_build_object('ok', false, 'reason', 'expected_local_payment_missing');
  end if;
  if payment_row.id is not null and (
    (p_expected_local_payment_id is not null and payment_row.id is distinct from p_expected_local_payment_id)
    or payment_row.student_id is distinct from p_expected_student_id
    or payment_row.tenant_id is distinct from normalized_tenant
    or nullif(pg_catalog.btrim(coalesce(payment_row.provider_customer_id, '')), '')
      is distinct from normalized_customer
    or payment_row.value is null
    or payment_row.value::text in ('NaN', 'Infinity', '-Infinity')
    or pg_catalog.round(payment_row.value, 2) <> pg_catalog.round(p_provider_value, 2)
  ) then
    return jsonb_build_object('ok', false, 'reason', 'local_payment_binding_mismatch');
  end if;

  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_expected_student_id
   for share;
  if not found
     or profile_row.tenant_id is distinct from normalized_tenant
     or profile_row.role is distinct from 'STUDENT'
     or nullif(pg_catalog.btrim(coalesce(profile_row.asaas_customer_id, '')), '')
       is distinct from normalized_customer
  then
    if normalized_event in ('PAYMENT_RECEIVED', 'PAYMENT_RECEIVED_IN_CASH')
       and payment_row.id is not null
       and p_expected_local_payment_id is not null
    then
      inactive_result := public.apply_inactive_student_payment_settlement(
        normalized_payment_id,
        p_expected_local_payment_id,
        p_expected_student_id,
        normalized_tenant,
        normalized_customer,
        normalized_event_id,
        normalized_event,
        p_event_created_at,
        p_event_rank,
        normalized_provider_status,
        p_provider_value,
        p_payment_date,
        p_credited_at,
        p_estimated_credit_at,
        p_payload
      );
      return inactive_result || jsonb_build_object('inactive_update_only', true);
    end if;
    return jsonb_build_object('ok', false, 'reason', 'student_binding_changed');
  end if;

  select count(*), count(*) filter (
    where membership.tenant_id = normalized_tenant
      and membership.role = 'STUDENT'
      and membership.status = 'ACTIVE'
  )
    into membership_count, active_membership_count
    from (
      select current_membership.tenant_id,
             current_membership.role,
             current_membership.status
        from public.tenant_memberships as current_membership
       where current_membership.user_id = p_expected_student_id
       for share
    ) as membership;
  lifecycle_operation_active := exists (
    select 1 from public.student_offboarding_operations as operation
     where operation.tenant_id = normalized_tenant
       and operation.student_id = p_expected_student_id
       and operation.status in (
         'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED'
       )
  ) or exists (
    select 1 from public.student_account_deletion_claims as deletion
     where deletion.tenant_id = normalized_tenant
       and deletion.student_id = p_expected_student_id
       and deletion.status in (
         'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED'
       )
  );
  lifecycle_is_active :=
    pg_catalog.lower(pg_catalog.btrim(coalesce(profile_row.lifecycle_status, ''))) = 'active'
    and membership_count = 1
    and active_membership_count = 1
    and not lifecycle_operation_active;

  if not lifecycle_is_active then
    if normalized_event in ('PAYMENT_RECEIVED', 'PAYMENT_RECEIVED_IN_CASH')
       and payment_row.id is not null
       and p_expected_local_payment_id is not null
    then
      inactive_result := public.apply_inactive_student_payment_settlement(
        normalized_payment_id,
        p_expected_local_payment_id,
        p_expected_student_id,
        normalized_tenant,
        normalized_customer,
        normalized_event_id,
        normalized_event,
        p_event_created_at,
        p_event_rank,
        normalized_provider_status,
        p_provider_value,
        p_payment_date,
        p_credited_at,
        p_estimated_credit_at,
        p_payload
      );
      return inactive_result || jsonb_build_object('inactive_update_only', true);
    end if;
    return jsonb_build_object('ok', false, 'reason', 'student_lifecycle_or_binding_changed');
  end if;

  if normalized_subscription is not null
     and nullif(pg_catalog.btrim(coalesce(profile_row.subscription_id, '')), '')
       is distinct from normalized_subscription
  then
    return jsonb_build_object('ok', false, 'reason', 'student_subscription_binding_changed');
  end if;

  if reference_offer_id is not null then
    perform 1
      from public.offers as offer
     where offer.id = reference_offer_id
       and offer.tenant_id = normalized_tenant
       and offer.kind = 'ENROLLMENT'
       and p_expected_student_id in (offer.processing_by, offer.consumed_by)
     for share;
    if not found then
      raise exception using errcode = '23514', message = 'active_payment_event_reference_mismatch';
    end if;
  end if;
  -- An exact inbox retry repairs idempotent downstream effects without
  -- rewriting the financial row (or firing its ledger triggers again). A
  -- different event with the same provider timestamp/rank is not equivalent:
  -- keep the already persisted identity as the deterministic winner.
  if payment_row.id is not null
     and nullif(pg_catalog.btrim(coalesce(payment_row.last_provider_event_id, '')), '')
       is not distinct from normalized_event_id
  then
    return jsonb_build_object(
      'ok', true,
      'action', 'REPLAY',
      'id', payment_row.id,
      'due_date', payment_row.due_date,
      'status', payment_row.status,
      'previous_status', payment_row.status,
      'was_already_paid', payment_row.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'PAGO')
        or payment_row.provider_status in ('RECEIVED', 'RECEIVED_IN_CASH', 'PAGO')
    );
  end if;
  if payment_row.id is not null and payment_row.last_provider_event_at is not null and (
    p_event_created_at < payment_row.last_provider_event_at
    or (
      p_event_created_at = payment_row.last_provider_event_at
      and p_event_rank <= coalesce(payment_row.last_provider_event_rank, 0)
    )
  ) then
    return jsonb_build_object(
      'ok', true,
      'action', 'IGNORED',
      'id', payment_row.id,
      'due_date', payment_row.due_date,
      'status', payment_row.status,
      'previous_status', payment_row.status,
      'was_already_paid', payment_row.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'PAGO')
        or payment_row.provider_status in ('RECEIVED', 'RECEIVED_IN_CASH', 'PAGO')
    );
  end if;

  if payment_row.id is null then
    insert into public.student_payments (
      asaas_payment_id, student_id, tenant_id, provider_customer_id,
      value, status, provider_status, due_date, payment_date, billing_type,
      invoice_url, description, payment_type, credited_at, paid_at,
      estimated_credit_at, raw_payload, last_provider_event_id,
      last_provider_event_at, last_provider_event_rank, updated_at
    ) values (
      normalized_payment_id, p_expected_student_id, normalized_tenant,
      normalized_customer, p_provider_value, normalized_provider_status,
      normalized_provider_status, p_due_date, p_payment_date,
      normalized_billing_type, normalized_invoice_url, normalized_description,
      normalized_payment_type, p_credited_at, p_credited_at,
      p_estimated_credit_at, p_payload, normalized_event_id,
      p_event_created_at, p_event_rank, pg_catalog.clock_timestamp()
    )
    on conflict (asaas_payment_id) where asaas_payment_id is not null do nothing
    returning id into inserted_payment_id;

    select payment.* into payment_row
      from public.student_payments as payment
     where nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') = normalized_payment_id
     for update;
    if not found
       or (inserted_payment_id is null and (
         payment_row.student_id is distinct from p_expected_student_id
         or payment_row.tenant_id is distinct from normalized_tenant
         or nullif(pg_catalog.btrim(coalesce(payment_row.provider_customer_id, '')), '')
           is distinct from normalized_customer
         or payment_row.value is null
         or pg_catalog.round(payment_row.value, 2) <> pg_catalog.round(p_provider_value, 2)
       ))
    then
      return jsonb_build_object('ok', false, 'reason', 'provider_payment_identity_collision');
    end if;
    if inserted_payment_id is not null then
      return jsonb_build_object(
        'ok', true,
        'action', 'INSERTED',
        'id', payment_row.id,
        'due_date', payment_row.due_date,
        'status', payment_row.status,
        'previous_status', null,
        'was_already_paid', false
      );
    end if;
  end if;

  previous_status := payment_row.status;
  was_already_paid := (
    payment_row.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'PAGO')
    or payment_row.provider_status in ('RECEIVED', 'RECEIVED_IN_CASH', 'PAGO')
  );
  next_status := case
    when payment_row.status = 'NAO_RECEITA' then 'NAO_RECEITA'
    when payment_row.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'PAGO')
      and normalized_event in (
        'PAYMENT_REFUND_IN_PROGRESS', 'PAYMENT_CHARGEBACK_REQUESTED',
        'PAYMENT_CHARGEBACK_DISPUTE', 'PAYMENT_AWAITING_CHARGEBACK_REVERSAL',
        'PAYMENT_DELETED'
      ) then payment_row.status
    else normalized_provider_status
  end;

  update public.student_payments as payment
     set status = next_status,
         provider_status = normalized_provider_status,
         due_date = p_due_date,
         payment_date = coalesce(p_payment_date, payment.payment_date),
         billing_type = coalesce(normalized_billing_type, payment.billing_type),
         invoice_url = coalesce(normalized_invoice_url, payment.invoice_url),
         description = normalized_description,
         payment_type = normalized_payment_type,
         credited_at = coalesce(p_credited_at, payment.credited_at),
         paid_at = coalesce(p_credited_at, payment.paid_at),
         estimated_credit_at = coalesce(p_estimated_credit_at, payment.estimated_credit_at),
         raw_payload = p_payload,
         last_provider_event_id = normalized_event_id,
         last_provider_event_at = p_event_created_at,
         last_provider_event_rank = p_event_rank,
         updated_at = pg_catalog.clock_timestamp()
   where payment.id = payment_row.id
   returning payment.* into payment_row;

  return jsonb_build_object(
    'ok', true,
    'action', 'UPDATED',
    'id', payment_row.id,
    'due_date', payment_row.due_date,
    'status', payment_row.status,
    'previous_status', previous_status,
    'was_already_paid', was_already_paid
  );
end;
$_$;


--
-- Name: FUNCTION apply_active_student_payment_event(p_provider_payment_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_expected_provider_subscription_id text, p_canonical_reference text, p_event_id text, p_event_name text, p_event_created_at timestamp with time zone, p_event_rank integer, p_provider_status text, p_provider_value numeric, p_due_date date, p_payment_date date, p_billing_type text, p_invoice_url text, p_description text, p_payment_type text, p_credited_at timestamp with time zone, p_estimated_credit_at timestamp with time zone, p_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_active_student_payment_event(p_provider_payment_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_expected_provider_subscription_id text, p_canonical_reference text, p_event_id text, p_event_name text, p_event_created_at timestamp with time zone, p_event_rank integer, p_provider_status text, p_provider_value numeric, p_due_date date, p_payment_date date, p_billing_type text, p_invoice_url text, p_description text, p_payment_type text, p_credited_at timestamp with time zone, p_estimated_credit_at timestamp with time zone, p_payload jsonb) IS 'Atomically revalidates active student lifecycle and exact Asaas payment identity before applying an ordered normal webhook event.';


--
-- Name: apply_coverage_acceptance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_coverage_acceptance(p_coverage_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_cov public.class_coverages%ROWTYPE;
  v_log public.class_logs%ROWTYPE;
  v_log_id uuid;
  v_match_kind text;
  v_match_count integer := 0;
  v_updated integer := 0;
  v_month text;
  v_time time;
  v_target_time time;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'service_role_required';
  END IF;

  SELECT coverage.*
    INTO v_cov
    FROM public.class_coverages AS coverage
   WHERE coverage.id = p_coverage_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'coverage_not_found';
  END IF;
  IF lower(coalesce(v_cov.status, '')) <> 'confirmed'
     OR v_cov.cover_teacher_id IS NULL
     OR v_cov.original_teacher_id IS NULL
     OR v_cov.booking_id IS NULL
     OR v_cov.class_date IS NULL
     OR coalesce(v_cov.class_time, '') !~
          '^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'coverage_invalid';
  END IF;
  IF NOT private.can_access_teacher_projection(
       v_cov.original_teacher_id,
       to_char(v_cov.class_date, 'YYYY-MM')
     )
     OR NOT private.can_access_teacher_projection(
       v_cov.cover_teacher_id,
       to_char(v_cov.class_date, 'YYYY-MM')
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501', MESSAGE = 'coverage_finance_scope_ambiguous';
  END IF;
  v_time := left(v_cov.class_time, 5)::time;
  v_month := to_char(v_cov.class_date, 'YYYY-MM');
  PERFORM private.lock_teacher_closing_pair(
    v_cov.tenant_id,
    v_month,
    v_cov.original_teacher_id,
    v_cov.cover_teacher_id
  );

  IF v_cov.class_log_id IS NOT NULL THEN
    SELECT class_log.*
      INTO v_log
      FROM public.class_logs AS class_log
     WHERE class_log.id = v_cov.class_log_id
     FOR UPDATE;
    IF FOUND
       AND v_log.tenant_id = v_cov.tenant_id
       AND v_log.teacher_id = v_cov.cover_teacher_id
       AND v_log.student_id IS NOT DISTINCT FROM v_cov.student_id
       AND v_log.class_date = v_cov.class_date
       AND (
         (
           coalesce(v_cov.class_log_match_kind, 'booking_time') =
             'booking_time'
           AND v_log.booking_id = v_cov.booking_id::text
           AND v_log.start_time = v_time
         ) OR (
           v_cov.class_log_match_kind = 'booking_no_time'
           AND v_log.booking_id = v_cov.booking_id::text
           AND v_log.start_time IS NULL
         ) OR (
           v_cov.class_log_match_kind = 'student_time'
           AND num_nonnulls(
             v_log.booking_id,
             v_log.reschedule_id,
             v_log.appointment_id
           ) = 0
           AND v_log.start_time = v_time
         ) OR (
           v_cov.class_log_match_kind = 'student_no_time'
           AND num_nonnulls(
             v_log.booking_id,
             v_log.reschedule_id,
             v_log.appointment_id
           ) = 0
           AND v_log.start_time IS NULL
         )
       ) THEN
      RETURN jsonb_build_object(
        'ok', true, 'already', true, 'modo', 'aula_movida',
        'class_log_id', v_cov.class_log_id
      );
    END IF;
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'coverage_log_inconsistent';
  END IF;

  -- 1. Origem e horario exatos.
  SELECT count(*), (array_agg(class_log.id ORDER BY class_log.id))[1]
    INTO v_match_count, v_log_id
    FROM public.class_logs AS class_log
   WHERE class_log.tenant_id = v_cov.tenant_id
     AND class_log.teacher_id = v_cov.original_teacher_id
     AND class_log.class_date = v_cov.class_date
     AND class_log.booking_id = v_cov.booking_id::text
     AND class_log.student_id IS NOT DISTINCT FROM v_cov.student_id
     AND class_log.start_time = v_time;
  IF v_match_count > 0 THEN
    v_match_kind := 'booking_time';
  END IF;

  -- 2. Mesmo booking legado, ainda sem snapshot de horario.
  IF v_match_count = 0 THEN
    SELECT count(*), (array_agg(class_log.id ORDER BY class_log.id))[1]
      INTO v_match_count, v_log_id
      FROM public.class_logs AS class_log
     WHERE class_log.tenant_id = v_cov.tenant_id
       AND class_log.teacher_id = v_cov.original_teacher_id
       AND class_log.class_date = v_cov.class_date
       AND class_log.booking_id = v_cov.booking_id::text
       AND class_log.student_id IS NOT DISTINCT FROM v_cov.student_id
       AND class_log.start_time IS NULL;
    IF v_match_count > 0 THEN
      v_match_kind := 'booking_no_time';
    END IF;
  END IF;

  IF v_match_count = 0 AND EXISTS (
    SELECT 1
      FROM public.class_logs AS class_log
     WHERE class_log.tenant_id = v_cov.tenant_id
       AND class_log.teacher_id = v_cov.original_teacher_id
       AND class_log.class_date = v_cov.class_date
       AND class_log.booking_id = v_cov.booking_id::text
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'coverage_class_log_time_mismatch';
  END IF;

  -- 3. Booking recriado: aluno/data/horario somente se a ocorrencia for unica.
  IF v_match_count = 0 AND v_cov.student_id IS NOT NULL THEN
    SELECT count(*), (array_agg(class_log.id ORDER BY class_log.id))[1]
      INTO v_match_count, v_log_id
      FROM public.class_logs AS class_log
     WHERE class_log.tenant_id = v_cov.tenant_id
       AND class_log.teacher_id = v_cov.original_teacher_id
       AND class_log.student_id = v_cov.student_id
       AND class_log.class_date = v_cov.class_date
       AND num_nonnulls(
         class_log.booking_id,
         class_log.reschedule_id,
         class_log.appointment_id
       ) = 0
       AND class_log.start_time = v_time;
    IF v_match_count > 0 THEN
      v_match_kind := 'student_time';
    END IF;
  END IF;

  -- 4. Ultimo fallback para historico sem horario, ainda assim univoco.
  IF v_match_count = 0 AND v_cov.student_id IS NOT NULL THEN
    SELECT count(*), (array_agg(class_log.id ORDER BY class_log.id))[1]
      INTO v_match_count, v_log_id
      FROM public.class_logs AS class_log
     WHERE class_log.tenant_id = v_cov.tenant_id
       AND class_log.teacher_id = v_cov.original_teacher_id
       AND class_log.student_id = v_cov.student_id
       AND class_log.class_date = v_cov.class_date
       AND num_nonnulls(
         class_log.booking_id,
         class_log.reschedule_id,
         class_log.appointment_id
       ) = 0
       AND class_log.start_time IS NULL;
    IF v_match_count > 0 THEN
      v_match_kind := 'student_no_time';
    END IF;
  END IF;

  IF v_match_count > 1 THEN
    RAISE EXCEPTION USING
      ERRCODE = '21000', MESSAGE = 'coverage_class_log_ambiguous';
  END IF;

  IF v_match_count = 1 AND v_log_id IS NOT NULL THEN
    SELECT class_log.*
      INTO v_log
      FROM public.class_logs AS class_log
     WHERE class_log.id = v_log_id
     FOR UPDATE;
    IF NOT FOUND
       OR v_log.tenant_id IS DISTINCT FROM v_cov.tenant_id
       OR v_log.teacher_id IS DISTINCT FROM v_cov.original_teacher_id
       OR v_log.class_date IS DISTINCT FROM v_cov.class_date
       OR NOT (
         (
           v_match_kind = 'booking_time'
           AND v_log.booking_id = v_cov.booking_id::text
           AND v_log.student_id IS NOT DISTINCT FROM v_cov.student_id
           AND v_log.start_time = v_time
         ) OR (
           v_match_kind = 'booking_no_time'
           AND v_log.booking_id = v_cov.booking_id::text
           AND v_log.student_id IS NOT DISTINCT FROM v_cov.student_id
           AND v_log.start_time IS NULL
         ) OR (
           v_match_kind = 'student_time'
           AND v_log.student_id IS NOT DISTINCT FROM v_cov.student_id
           AND num_nonnulls(
             v_log.booking_id,
             v_log.reschedule_id,
             v_log.appointment_id
           ) = 0
           AND v_log.start_time = v_time
         ) OR (
           v_match_kind = 'student_no_time'
           AND v_log.student_id IS NOT DISTINCT FROM v_cov.student_id
           AND num_nonnulls(
             v_log.booking_id,
             v_log.reschedule_id,
             v_log.appointment_id
           ) = 0
           AND v_log.start_time IS NULL
         )
       ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '40001', MESSAGE = 'coverage_class_log_changed';
    END IF;

    v_target_time := CASE
      WHEN v_match_kind IN ('booking_no_time', 'student_no_time') THEN NULL
      ELSE v_time
    END;
    IF EXISTS (
      SELECT 1
        FROM public.class_logs AS class_log
       WHERE class_log.id <> v_log_id
         AND class_log.tenant_id = v_cov.tenant_id
         AND class_log.teacher_id = v_cov.cover_teacher_id
         AND class_log.student_id IS NOT DISTINCT FROM v_cov.student_id
         AND class_log.class_date = v_cov.class_date
         AND class_log.start_time IS NOT DISTINCT FROM v_target_time
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23505', MESSAGE = 'coverage_target_log_conflict';
    END IF;

    UPDATE public.class_logs
       SET teacher_id = v_cov.cover_teacher_id
     WHERE id = v_log_id
       AND tenant_id = v_cov.tenant_id
       AND teacher_id = v_cov.original_teacher_id
       AND class_date = v_cov.class_date
       AND (
         (
           v_match_kind = 'booking_time'
           AND booking_id = v_cov.booking_id::text
           AND student_id IS NOT DISTINCT FROM v_cov.student_id
           AND start_time = v_time
         ) OR (
           v_match_kind = 'booking_no_time'
           AND booking_id = v_cov.booking_id::text
           AND student_id IS NOT DISTINCT FROM v_cov.student_id
           AND start_time IS NULL
         ) OR (
           v_match_kind = 'student_time'
           AND student_id IS NOT DISTINCT FROM v_cov.student_id
           AND num_nonnulls(booking_id, reschedule_id, appointment_id) = 0
           AND start_time = v_time
         ) OR (
           v_match_kind = 'student_no_time'
           AND student_id IS NOT DISTINCT FROM v_cov.student_id
           AND num_nonnulls(booking_id, reschedule_id, appointment_id) = 0
           AND start_time IS NULL
         )
       );
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    IF v_updated <> 1 THEN
      RAISE EXCEPTION USING
        ERRCODE = '40001', MESSAGE = 'coverage_class_log_changed';
    END IF;

    UPDATE public.class_coverages
       SET class_log_id = v_log_id,
           class_log_match_kind = v_match_kind,
           moved_at = now()
     WHERE id = v_cov.id
       AND tenant_id = v_cov.tenant_id
       AND lower(status) = 'confirmed';

    -- A mesma rotina canônica é usada por ajuste, cobertura e fechamento
    -- mensal; ela preserva ajustes/sobras e reseta a confirmação se o total muda.
    PERFORM private.refresh_teacher_closing_snapshot(
      v_cov.tenant_id,
      v_cov.original_teacher_id,
      v_month,
      false
    );
    PERFORM private.refresh_teacher_closing_snapshot(
      v_cov.tenant_id,
      v_cov.cover_teacher_id,
      v_month,
      false
    );

    RETURN jsonb_build_object(
      'ok', true, 'modo', 'aula_movida', 'class_log_id', v_log_id
    );
  END IF;

  -- Aula futura: a cobertura confirmada passa a ser a fonte do lancamento.
  RETURN jsonb_build_object(
    'ok', true,
    'modo', 'lancamento_redirecionado',
    'booking_id', v_cov.booking_id,
    'data', v_cov.class_date,
    'horario', left(v_cov.class_time, 5)
  );
END;
$_$;


--
-- Name: apply_credit_next_pending(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_credit_next_pending(p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; s_tenant text; v_pid uuid;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id=auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;
  SELECT tenant_id INTO s_tenant FROM profiles WHERE id=p_student_id;
  IF v_role='SCHOOL_ADMIN' AND s_tenant<>v_tenant THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;

  -- cobrança pendente mais antiga (prioriza vencidas)
  SELECT id INTO v_pid FROM student_payments
   WHERE student_id=p_student_id AND status IN ('OVERDUE','DUNNING_REQUESTED','PENDING')
   ORDER BY (status IN ('OVERDUE','DUNNING_REQUESTED')) DESC, due_date ASC NULLS LAST LIMIT 1;
  IF v_pid IS NULL THEN RETURN jsonb_build_object('ok',false,'error','sem_cobranca_pendente'); END IF;

  RETURN apply_credit_to_payment(v_pid);
END;
$$;


--
-- Name: apply_credit_to_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_credit_to_payment(p_payment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text; v_tenant text; p student_payments%ROWTYPE; c record; v_applied numeric := 0;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id=auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;
  SELECT * INTO p FROM student_payments WHERE id=p_payment_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','nao_encontrado'); END IF;
  IF v_role='SCHOOL_ADMIN' AND p.tenant_id<>v_tenant THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;
  IF p.status NOT IN ('PENDING','OVERDUE','DUNNING_REQUESTED') THEN RETURN jsonb_build_object('ok',false,'error','cobranca_nao_pendente'); END IF;

  FOR c IN SELECT * FROM student_credits
            WHERE student_id=p.student_id AND applied_at IS NULL AND (expires_at IS NULL OR expires_at>now())
            ORDER BY created_at LOOP
    IF v_applied + c.amount <= p.value THEN
      UPDATE student_credits SET applied_to_invoice_id=p_payment_id, applied_at=now() WHERE id=c.id;
      v_applied := v_applied + c.amount;
    END IF;
  END LOOP;

  IF v_applied > 0 THEN
    UPDATE student_payments SET value = value - v_applied, updated_at = now() WHERE id=p_payment_id;
  END IF;
  RETURN jsonb_build_object('ok', true, 'applied', v_applied, 'new_value', p.value - v_applied);
END;
$$;


--
-- Name: apply_credits_to_invoice(uuid, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_credits_to_invoice(p_student_id uuid, p_invoice_id text, p_invoice_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_credit RECORD;
    v_remaining NUMERIC(10,2) := p_invoice_amount;
    v_total_applied NUMERIC(10,2) := 0;
    v_credits_applied INTEGER := 0;
BEGIN
    -- Idempotency: check if already applied
    IF EXISTS (
        SELECT 1 FROM public.student_credits
        WHERE applied_to_invoice_id = p_invoice_id
    ) THEN
        SELECT COALESCE(SUM(amount), 0) INTO v_total_applied
        FROM public.student_credits
        WHERE applied_to_invoice_id = p_invoice_id;

        RETURN jsonb_build_object(
            'success', true,
            'already_applied', true,
            'discount', v_total_applied
        );
    END IF;

    -- Consume credits oldest-first, up to invoice amount
    FOR v_credit IN
        SELECT id, amount FROM public.student_credits
        WHERE student_id = p_student_id
          AND applied_at IS NULL
          AND (expires_at IS NULL OR expires_at > now())
        ORDER BY created_at ASC
        FOR UPDATE
    LOOP
        EXIT WHEN v_remaining <= 0;

        IF v_credit.amount <= v_remaining THEN
            -- Fully consume this credit
            UPDATE public.student_credits SET
                applied_to_invoice_id = p_invoice_id,
                applied_at = now()
            WHERE id = v_credit.id;

            v_remaining := v_remaining - v_credit.amount;
            v_total_applied := v_total_applied + v_credit.amount;
        ELSE
            -- Partially consume: split the credit
            -- Mark original as applied with partial amount
            UPDATE public.student_credits SET
                amount = v_remaining,
                applied_to_invoice_id = p_invoice_id,
                applied_at = now()
            WHERE id = v_credit.id;

            -- Create remainder credit
            INSERT INTO public.student_credits (
                student_id, tenant_id, amount, source, source_ref, expires_at
            )
            SELECT student_id, tenant_id, v_credit.amount - v_remaining,
                   source, source_ref || ':remainder:' || gen_random_uuid(),
                   expires_at
            FROM public.student_credits WHERE id = v_credit.id;

            v_total_applied := v_total_applied + v_remaining;
            v_remaining := 0;
        END IF;

        v_credits_applied := v_credits_applied + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'discount', v_total_applied,
        'credits_consumed', v_credits_applied,
        'remaining_invoice', v_remaining
    );
END;
$$;


--
-- Name: apply_due_teacher_transfers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_due_teacher_transfers() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r record; n int := 0;
BEGIN
    FOR r IN SELECT id FROM public.teacher_transfers
             WHERE status = 'ACCEPTED' AND cutover_date <= current_date
    LOOP
        PERFORM public.apply_teacher_transfer(r.id);
        n := n + 1;
    END LOOP;
    RETURN n;
END;
$$;


--
-- Name: apply_enrollment_payment_observation(text, uuid, uuid, text, text, text, text, text, numeric, text, text, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_enrollment_payment_observation(p_tenant_id text, p_student_id uuid, p_offer_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_payment_kind text, p_outcome text, p_provider_value numeric, p_external_reference text, p_provider_status text, p_due_date date, p_billing_type text, p_description text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  normalized_payment_id text := nullif(
    trim(coalesce(p_provider_payment_id, '')),
    ''
  );
  normalized_customer_id text := nullif(
    trim(coalesce(p_provider_customer_id, '')),
    ''
  );
  normalized_subscription_id text := nullif(
    trim(coalesce(p_provider_subscription_id, '')),
    ''
  );
  normalized_kind text := upper(trim(coalesce(p_payment_kind, '')));
  normalized_outcome text := upper(trim(coalesce(p_outcome, '')));
  normalized_reference text := nullif(
    trim(coalesce(p_external_reference, '')),
    ''
  );
  normalized_provider_status text := upper(trim(coalesce(
    p_provider_status,
    ''
  )));
  normalized_billing_type text := upper(trim(coalesce(p_billing_type, '')));
  normalized_description text := nullif(trim(coalesce(p_description, '')), '');
  profiles_have_updated_at boolean := false;
  offer_row public.offers%rowtype;
  profile_row public.profiles%rowtype;
  payment_row public.student_payments%rowtype;
  local_payment_count integer := 0;
  local_outcome text;
  expected_reference text;
  completion jsonb;
  reopening jsonb;
  affected_rows integer := 0;
  offer_fee_id text;
  profile_fee_id text;
  fee_uses_profile_fallback boolean := false;
  fee_competing_offer_count integer := 0;
begin
  select exists(
    select 1
    from pg_catalog.pg_attribute a
    join pg_catalog.pg_class c on c.oid = a.attrelid
    join pg_catalog.pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = 'profiles'
      and a.attname = 'updated_at'
      and not a.attisdropped
      and a.attnum > 0
  ) into profiles_have_updated_at;

  if normalized_tenant is null
     or p_student_id is null
     or normalized_payment_id is null
     or normalized_customer_id is null
     or normalized_kind not in (
       'ENROLLMENT_FEE', 'ONE_TIME', 'PRO_RATA', 'SUBSCRIPTION_ACTIVATION'
     )
     or (
       normalized_kind = 'SUBSCRIPTION_ACTIVATION'
       and normalized_subscription_id is null
     )
     or (
       normalized_kind <> 'SUBSCRIPTION_ACTIVATION'
       and normalized_subscription_id is not null
     )
     or length(coalesce(normalized_subscription_id, '')) > 240
     or normalized_outcome not in ('SETTLED', 'PENDING', 'UNSETTLED')
     or p_provider_value is null
     or p_provider_value <= 0
     or normalized_reference is null
     or normalized_provider_status = ''
     or length(normalized_provider_status) > 120
     or p_due_date is null
     or normalized_billing_type not in ('PIX', 'BOLETO', 'CREDIT_CARD')
     or normalized_description is null
     or length(normalized_description) > 500
     or (p_offer_id is null and normalized_kind <> 'ENROLLMENT_FEE')
  then
    raise exception using
      errcode = '22023',
      message = 'invalid_enrollment_payment_observation';
  end if;

  if normalized_outcome is distinct from (
    case
      when normalized_provider_status in ('RECEIVED', 'RECEIVED_IN_CASH', 'PAGO')
        then 'SETTLED'
      when normalized_provider_status in (
        'REFUNDED', 'CANCELLED', 'DELETED', 'CHARGEBACK',
        'CHARGEBACK_REQUESTED', 'RECEIVED_IN_CASH_UNDONE'
      ) then 'UNSETTLED'
      else 'PENDING'
    end
  )
  then
    raise exception using
      errcode = '22023',
      message = 'provider_status_outcome_mismatch';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' ||
        p_student_id::text,
      0
    )
  );

  if p_offer_id is not null then
    select offer.* into offer_row
      from public.offers as offer
     where offer.id = p_offer_id
       and offer.tenant_id = normalized_tenant
       and offer.kind = 'ENROLLMENT'
     for update;
    if not found
       or (
         offer_row.processing_by is distinct from p_student_id
         and offer_row.consumed_by is distinct from p_student_id
       )
    then
      return jsonb_build_object('ok', false, 'reason', 'offer_not_owned');
    end if;
  end if;

  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_student_id
     and profile.tenant_id = normalized_tenant
     and profile.role = 'STUDENT'
     and nullif(trim(coalesce(profile.asaas_customer_id, '')), '') =
       normalized_customer_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'profile_binding_changed');
  end if;

  expected_reference := case
    when p_offer_id is null then p_student_id::text
    when normalized_kind = 'ENROLLMENT_FEE'
      then 'enrollment:' || p_offer_id::text || ':fee'
    when normalized_kind = 'ONE_TIME'
      then 'enrollment:' || p_offer_id::text || ':one-time'
    when normalized_kind = 'PRO_RATA'
      then 'enrollment:' || p_offer_id::text || ':pro-rata'
    else 'enrollment:' || p_offer_id::text || ':subscription'
  end;
  if normalized_reference <> expected_reference then
    return jsonb_build_object(
      'ok', false,
      'reason', 'provider_reference_mismatch'
    );
  end if;

  if normalized_kind = 'ENROLLMENT_FEE' then
    profile_fee_id := nullif(trim(coalesce(
      profile_row.enrollment_payment_id,
      ''
    )), '');
    offer_fee_id := case when p_offer_id is null then null else nullif(
      trim(coalesce(offer_row.metadata ->> 'enrollment_payment_id', '')),
      ''
    ) end;
    if p_offer_id is null and profile_fee_id is distinct from normalized_payment_id
    then
      return jsonb_build_object(
        'ok', false,
        'reason', 'enrollment_payment_binding_mismatch'
      );
    elsif p_offer_id is not null and offer_fee_id is not null
          and offer_fee_id <> normalized_payment_id
    then
      return jsonb_build_object(
        'ok', false,
        'reason', 'enrollment_payment_binding_mismatch'
      );
    elsif p_offer_id is not null and offer_fee_id is null then
      if profile_fee_id is distinct from normalized_payment_id then
        return jsonb_build_object(
          'ok', false,
          'reason', 'enrollment_payment_binding_mismatch'
        );
      end if;
      select count(*) into fee_competing_offer_count
        from public.offers as competing_offer
       where competing_offer.id <> p_offer_id
         and competing_offer.tenant_id = normalized_tenant
         and competing_offer.kind = 'ENROLLMENT'
         and (
           competing_offer.processing_by = p_student_id
           or competing_offer.consumed_by = p_student_id
         )
         and nullif(trim(coalesce(
           competing_offer.metadata ->> 'enrollment_payment_id',
           ''
         )), '') = normalized_payment_id;
      if fee_competing_offer_count <> 0 then
        return jsonb_build_object(
          'ok', false,
          'reason', 'enrollment_payment_binding_mismatch'
        );
      end if;
      fee_uses_profile_fallback := true;
    end if;
  elsif p_offer_id is null then
    return jsonb_build_object('ok', false, 'reason', 'offer_required');
  elsif normalized_kind = 'ONE_TIME' then
    if (
         nullif(trim(coalesce(
           offer_row.metadata ->> 'one_time_payment_id',
           ''
         )), '') is not null
         and nullif(trim(coalesce(
           offer_row.metadata ->> 'one_time_payment_id',
           ''
         )), '') <> normalized_payment_id
       ) or (
         normalized_outcome <> 'SETTLED'
         and nullif(trim(coalesce(
           offer_row.metadata ->> 'one_time_payment_id',
           ''
         )), '') is distinct from normalized_payment_id
       )
    then
      return jsonb_build_object(
        'ok', false,
        'reason', 'one_time_payment_binding_mismatch'
      );
    end if;
  elsif normalized_kind = 'PRO_RATA' then
    begin
      if offer_row.payload ->> 'enableProRata' is distinct from 'true'
         or coalesce(
           nullif(offer_row.payload ->> 'proRataValue', '')::numeric,
           0
         ) <= 0
         or round(
              coalesce(
                nullif(offer_row.payload ->> 'proRataValue', '')::numeric,
                0
              ),
              2
            ) is distinct from round(p_provider_value, 2)
         or offer_row.payload ->> 'proRataFormulaVersion'
              is distinct from 'weekly-frequency-times-4-v1'
      then
        return jsonb_build_object(
          'ok', false,
          'reason', 'pro_rata_scope_invalid'
        );
      end if;
    exception when others then
      return jsonb_build_object(
        'ok', false,
        'reason', 'pro_rata_scope_invalid'
      );
    end;
    if (
         nullif(trim(coalesce(
           offer_row.metadata ->> 'pro_rata_charge_id',
           ''
         )), '') is not null
         and nullif(trim(coalesce(
           offer_row.metadata ->> 'pro_rata_charge_id',
           ''
         )), '') <> normalized_payment_id
       ) or (
         normalized_outcome <> 'SETTLED'
         and nullif(trim(coalesce(
           offer_row.metadata ->> 'pro_rata_charge_id',
           ''
         )), '') is distinct from normalized_payment_id
       )
    then
      return jsonb_build_object(
        'ok', false,
        'reason', 'pro_rata_payment_binding_mismatch'
      );
    end if;
  else
    if nullif(trim(coalesce(profile_row.subscription_id, '')), '')
         is distinct from normalized_subscription_id
       or nullif(trim(coalesce(
            offer_row.metadata ->> 'subscription_id',
            ''
          )), '') is distinct from normalized_subscription_id
       or (
         coalesce(
           nullif(trim(coalesce(
             offer_row.metadata ->> 'subscription_activation_payment_id',
             ''
           )), ''),
           nullif(trim(coalesce(
             offer_row.metadata ->> 'activation_payment_id',
             ''
           )), '')
         ) is not null
         and coalesce(
           nullif(trim(coalesce(
             offer_row.metadata ->> 'subscription_activation_payment_id',
             ''
           )), ''),
           nullif(trim(coalesce(
             offer_row.metadata ->> 'activation_payment_id',
             ''
           )), '')
         ) <> normalized_payment_id
       )
       or (
         normalized_outcome <> 'SETTLED'
         and coalesce(
           nullif(trim(coalesce(
             offer_row.metadata ->> 'subscription_activation_payment_id',
             ''
           )), ''),
           nullif(trim(coalesce(
             offer_row.metadata ->> 'activation_payment_id',
             ''
           )), '')
         ) is distinct from normalized_payment_id
       )
    then
      return jsonb_build_object(
        'ok', false,
        'reason', 'subscription_activation_payment_binding_mismatch'
      );
    end if;
  end if;

  if exists (
    select 1
      from public.student_payments as payment
     where (
       nullif(trim(coalesce(payment.asaas_payment_id, '')), '') =
         normalized_payment_id
       or nullif(trim(coalesce(payment.asaas_id, '')), '') =
         normalized_payment_id
     )
       and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') is not null
       and nullif(trim(coalesce(payment.asaas_id, '')), '') is not null
       and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') <>
           nullif(trim(coalesce(payment.asaas_id, '')), '')
  ) then
    return jsonb_build_object(
      'ok', false,
      'reason', 'local_payment_provider_alias_divergence'
    );
  end if;

  select count(*) into local_payment_count
    from public.student_payments as payment
   where nullif(trim(coalesce(payment.asaas_payment_id, '')), '') =
           normalized_payment_id
      or nullif(trim(coalesce(payment.asaas_id, '')), '') =
           normalized_payment_id;
  if local_payment_count > 1 then
    return jsonb_build_object(
      'ok', false,
      'reason', 'local_payment_binding_ambiguous'
    );
  end if;

  if local_payment_count = 0 and normalized_outcome = 'PENDING' then
    insert into public.student_payments (
      asaas_payment_id,
      student_id,
      tenant_id,
      provider_customer_id,
      value,
      amount_cents,
      status,
      provider_status,
      due_date,
      billing_type,
      payment_method,
      description,
      payment_type,
      updated_at
    ) values (
      normalized_payment_id,
      p_student_id,
      normalized_tenant,
      normalized_customer_id,
      p_provider_value,
      round(p_provider_value * 100)::integer,
      normalized_provider_status,
      normalized_provider_status,
      p_due_date,
      normalized_billing_type,
      normalized_billing_type,
      normalized_description,
      case
        when normalized_kind = 'ENROLLMENT_FEE' then 'ENROLLMENT'
        when normalized_kind = 'PRO_RATA' then 'PRO_RATA'
        else 'SUBSCRIPTION'
      end,
      now()
    )
    on conflict (asaas_payment_id) where asaas_payment_id is not null
      do nothing;

    select count(*) into local_payment_count
      from public.student_payments as payment
     where nullif(trim(coalesce(payment.asaas_payment_id, '')), '') =
             normalized_payment_id
        or nullif(trim(coalesce(payment.asaas_id, '')), '') =
             normalized_payment_id;
  end if;

  if local_payment_count = 0 then
    return jsonb_build_object(
      'ok', false,
      'reason', 'payment_event_not_observed'
    );
  end if;
  if local_payment_count > 1 then
    return jsonb_build_object(
      'ok', false,
      'reason', 'local_payment_binding_ambiguous'
    );
  end if;

  if local_payment_count = 1 then
    select payment.* into payment_row
      from public.student_payments as payment
     where nullif(trim(coalesce(payment.asaas_payment_id, '')), '') =
             normalized_payment_id
        or nullif(trim(coalesce(payment.asaas_id, '')), '') =
             normalized_payment_id
     for update;

    if payment_row.tenant_id is distinct from normalized_tenant
       or payment_row.student_id is distinct from p_student_id
       or nullif(trim(coalesce(payment_row.provider_customer_id, '')), '')
         is distinct from normalized_customer_id
       or round(coalesce(payment_row.value, 0), 2)
         is distinct from round(p_provider_value, 2)
       or payment_row.due_date is distinct from p_due_date
       or upper(trim(coalesce(payment_row.billing_type, '')))
         is distinct from normalized_billing_type
       or (
         normalized_kind = 'PRO_RATA'
         and upper(trim(coalesce(payment_row.payment_type, '')))
           is distinct from 'PRO_RATA'
       )
    then
      return jsonb_build_object(
        'ok', false,
        'reason', 'local_payment_identity_mismatch'
      );
    end if;

    if fee_uses_profile_fallback
       and lower(trim(coalesce(
         payment_row.raw_payload #>> '{payment,externalReference}',
         ''
       ))) is distinct from lower(expected_reference)
    then
      return jsonb_build_object(
        'ok', false,
        'reason', 'enrollment_payment_binding_mismatch'
      );
    end if;

    local_outcome := case
      when upper(trim(coalesce(payment_row.status, ''))) in (
        'REFUNDED', 'CANCELLED', 'DELETED', 'CHARGEBACK',
        'CHARGEBACK_REQUESTED', 'RECEIVED_IN_CASH_UNDONE'
      ) or upper(trim(coalesce(payment_row.provider_status, ''))) in (
        'REFUNDED', 'CANCELLED', 'DELETED', 'CHARGEBACK',
        'CHARGEBACK_REQUESTED', 'RECEIVED_IN_CASH_UNDONE'
      ) then 'UNSETTLED'
      when upper(trim(coalesce(payment_row.status, ''))) in (
        'RECEIVED', 'RECEIVED_IN_CASH', 'PAGO'
      ) or upper(trim(coalesce(payment_row.provider_status, ''))) in (
        'RECEIVED', 'RECEIVED_IN_CASH', 'PAGO'
      ) then 'SETTLED'
      else 'PENDING'
    end;
    if local_outcome is distinct from normalized_outcome then
      return jsonb_build_object(
        'ok', false,
        'reason', 'provider_observation_stale',
        'local_outcome', local_outcome
      );
    end if;
  end if;

  if normalized_outcome in ('SETTLED', 'PENDING') then
    if lower(trim(coalesce(profile_row.lifecycle_status, ''))) <> 'active'
       or (
         select count(*) from public.tenant_memberships as membership
          where membership.user_id = p_student_id
       ) <> 1
       or not exists (
         select 1 from public.tenant_memberships as membership
          where membership.user_id = p_student_id
            and membership.tenant_id = normalized_tenant
            and membership.role = 'STUDENT'
            and membership.status = 'ACTIVE'
       )
       or exists (
         select 1 from public.student_offboarding_operations as operation
          where operation.tenant_id = normalized_tenant
            and operation.student_id = p_student_id
            and operation.status in (
              'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
              'UNKNOWN', 'BLOCKED'
            )
       )
       or exists (
         select 1 from public.student_account_deletion_claims as deletion
          where deletion.tenant_id = normalized_tenant
            and deletion.student_id = p_student_id
            and deletion.status in (
              'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
              'UNKNOWN', 'BLOCKED'
            )
       )
    then
      return jsonb_build_object(
        'ok', false,
        'reason', 'student_lifecycle_inactive'
      );
    end if;
  end if;

  if normalized_outcome = 'UNSETTLED' then
    if p_offer_id is null then
      if profiles_have_updated_at then
        update public.profiles
           set enrollment_fee_paid = false,
               status_financial = 'PENDING',
               updated_at = now()
         where id = p_student_id
           and tenant_id = normalized_tenant
           and role = 'STUDENT'
           and asaas_customer_id = normalized_customer_id
           and enrollment_payment_id = normalized_payment_id;
      else
        update public.profiles
           set enrollment_fee_paid = false,
               status_financial = 'PENDING'
         where id = p_student_id
           and tenant_id = normalized_tenant
           and role = 'STUDENT'
           and asaas_customer_id = normalized_customer_id
           and enrollment_payment_id = normalized_payment_id;
      end if;
      get diagnostics affected_rows = row_count;
      if affected_rows <> 1 then
        return jsonb_build_object(
          'ok', false,
          'reason', 'profile_binding_changed'
        );
      end if;
      return jsonb_build_object(
        'ok', true,
        'action', 'PAYMENT_REVOKED',
        'processing_state', null
      );
    end if;
    if normalized_kind in ('ONE_TIME', 'PRO_RATA') then
      update public.offers
         set metadata = coalesce(metadata, '{}'::jsonb) ||
               case normalized_kind
                 when 'ONE_TIME' then jsonb_build_object(
                   'one_time_payment_id', normalized_payment_id
                 )
                 else jsonb_build_object(
                   'pro_rata_charge_id', normalized_payment_id
                 )
               end
       where id = p_offer_id;
    end if;
    reopening := public.reopen_enrollment_offer_for_unsettled_payment(
      p_offer_id,
      p_student_id,
      normalized_payment_id,
      'payment_refunded'
    );
    if reopening ->> 'ok' <> 'true' then
      return jsonb_build_object(
        'ok', false,
        'reason', coalesce(reopening ->> 'reason', 'reopen_failed')
      );
    end if;
    return jsonb_build_object(
      'ok', true,
      'action', 'REOPENED',
      'processing_state', 'AWAITING_PAYMENT'
    );
  end if;

  if normalized_kind = 'ENROLLMENT_FEE' then
    if profiles_have_updated_at then
      update public.profiles
         set enrollment_fee_paid = case
               when normalized_outcome = 'SETTLED' then true
               else enrollment_fee_paid
             end,
             updated_at = now()
       where id = p_student_id
         and tenant_id = normalized_tenant
         and role = 'STUDENT'
         and lifecycle_status = 'active'
         and asaas_customer_id = normalized_customer_id
         and enrollment_payment_id = normalized_payment_id;
    else
      update public.profiles
         set enrollment_fee_paid = case
               when normalized_outcome = 'SETTLED' then true
               else enrollment_fee_paid
             end
       where id = p_student_id
         and tenant_id = normalized_tenant
         and role = 'STUDENT'
         and lifecycle_status = 'active'
         and asaas_customer_id = normalized_customer_id
         and enrollment_payment_id = normalized_payment_id;
    end if;
    get diagnostics affected_rows = row_count;
    if affected_rows <> 1 then
      return jsonb_build_object(
        'ok', false,
        'reason', 'profile_binding_changed'
      );
    end if;
  end if;

  if p_offer_id is null then
    return jsonb_build_object(
      'ok', true,
      'action', case
        when normalized_outcome = 'SETTLED' then 'BILLING_RECORDED'
        else 'AWAITING_PAYMENT'
      end,
      'processing_state', null
    );
  end if;

  update public.offers
     set metadata = case normalized_kind
           when 'ENROLLMENT_FEE' then
             coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
               'enrollment_payment_id', normalized_payment_id
             ) || case when normalized_outcome = 'SETTLED'
               then jsonb_build_object('enrollment_fee_paid_at', now())
               else '{}'::jsonb end
           when 'ONE_TIME' then
             coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
               'one_time_payment_id', normalized_payment_id
             ) || case when normalized_outcome = 'SETTLED'
               then jsonb_build_object('one_time_paid_at', now())
               else '{}'::jsonb end
           when 'PRO_RATA' then
             coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
               'pro_rata_charge_id', normalized_payment_id
             ) || case when normalized_outcome = 'SETTLED'
               then jsonb_build_object('pro_rata_paid_at', now())
               else '{}'::jsonb end
           else coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
             'subscription_activation_payment_id', normalized_payment_id,
             'activation_payment_id', normalized_payment_id
           ) || case when normalized_outcome = 'SETTLED'
             then jsonb_build_object(
               'subscription_activation_received_at', now()
             )
             else '{}'::jsonb end
         end,
         processing_state = case
           when processing_state = 'COMPLETED' then processing_state
           when normalized_outcome = 'SETTLED' then 'BILLING_READY'
           else 'AWAITING_PAYMENT'
         end,
         processing_updated_at = now(),
         processing_error_code = null,
         processing_error_message = null
   where id = p_offer_id;

  if normalized_outcome = 'PENDING' then
    if offer_row.processing_state = 'COMPLETED' then
      reopening := public.reopen_enrollment_offer_for_unsettled_payment(
        p_offer_id,
        p_student_id,
        normalized_payment_id,
        'payment_not_settled'
      );
      if reopening ->> 'ok' <> 'true' then
        return jsonb_build_object(
          'ok', false,
          'reason', coalesce(reopening ->> 'reason', 'reopen_failed')
        );
      end if;
    end if;
    return jsonb_build_object(
      'ok', true,
      'action', 'AWAITING_PAYMENT',
      'processing_state', 'AWAITING_PAYMENT'
    );
  end if;

  completion := public.complete_enrollment_offer(p_offer_id, p_student_id);
  if completion ->> 'success' <> 'true' then
    return jsonb_build_object(
      'ok', true,
      'action', 'BILLING_RECORDED',
      'processing_state', 'BILLING_READY',
      'completion_error', completion ->> 'error'
    );
  end if;
  return jsonb_build_object(
    'ok', true,
    'action', case
      when completion ->> 'already_completed' = 'true'
        then 'ALREADY_COMPLETED'
      else 'COMPLETED'
    end,
    'processing_state', 'COMPLETED',
    'correlation_id', completion ->> 'correlation_id'
  );
end;
$$;


--
-- Name: FUNCTION apply_enrollment_payment_observation(p_tenant_id text, p_student_id uuid, p_offer_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_payment_kind text, p_outcome text, p_provider_value numeric, p_external_reference text, p_provider_status text, p_due_date date, p_billing_type text, p_description text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_enrollment_payment_observation(p_tenant_id text, p_student_id uuid, p_offer_id uuid, p_provider_payment_id text, p_provider_customer_id text, p_provider_subscription_id text, p_payment_kind text, p_outcome text, p_provider_value numeric, p_external_reference text, p_provider_status text, p_due_date date, p_billing_type text, p_description text) IS 'Serializa taxa, avulso, pro-rata e primeira parcela sem confundir mensalidades futuras com ativacao.';


--
-- Name: apply_historical_asaas_payment_reversal(text, uuid, uuid, text, text, text, text, timestamp with time zone, integer, text, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_historical_asaas_payment_reversal(p_provider_payment_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_event_id text, p_event_name text, p_event_created_at timestamp with time zone, p_event_rank integer, p_provider_status text, p_refunded_amount numeric, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || trim(coalesce(p_expected_tenant_id, '')) ||
        ':' || p_expected_student_id::text,
      0
    )
  );
  if exists (
    select 1
      from public.asaas_outbound_message_attempts as attempt
     where attempt.tenant_id = trim(coalesce(p_expected_tenant_id, ''))
       and attempt.student_id = p_expected_student_id
       and attempt.provider_entity_id = p_expected_local_payment_id::text
       and attempt.notification_kind in (
         'PAYMENT_CONFIRMED_CAPI', 'PAYMENT_CONFIRMED_WHATSAPP'
       )
       and attempt.status in ('SUBMITTING', 'UNKNOWN')
  ) then
    return jsonb_build_object(
      'ok', false,
      'reason', 'payment_confirmation_delivery_in_flight'
    );
  end if;
  return public.apply_historical_asaas_payment_reversal_pre_message_fence_impl(
    p_provider_payment_id,
    p_expected_local_payment_id,
    p_expected_student_id,
    p_expected_tenant_id,
    p_expected_provider_customer_id,
    p_event_id,
    p_event_name,
    p_event_created_at,
    p_event_rank,
    p_provider_status,
    p_refunded_amount,
    p_payload
  );
end;
$$;


--
-- Name: apply_historical_asaas_payment_reversal_pre_message_fence_impl(text, uuid, uuid, text, text, text, text, timestamp with time zone, integer, text, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_historical_asaas_payment_reversal_pre_message_fence_impl(p_provider_payment_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_event_id text, p_event_name text, p_event_created_at timestamp with time zone, p_event_rank integer, p_provider_status text, p_refunded_amount numeric, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_record public.student_payments%rowtype;
  expected_rank integer;
  incoming_customer text;
  incoming_payment_id text;
  incoming_event_id text;
  incoming_event_name text;
  payload_value_text text;
  payload_value numeric;
  provider_refunded_value numeric := 0;
  completed_refunds_value numeric := 0;
  refund_item jsonb;
  refund_item_value numeric;
  next_status text;
begin
  if nullif(pg_catalog.btrim(p_provider_payment_id), '') is null
    or pg_catalog.length(pg_catalog.btrim(p_provider_payment_id)) > 240
    or p_expected_local_payment_id is null
    or p_expected_student_id is null
    or nullif(pg_catalog.btrim(p_expected_tenant_id), '') is null
    or p_expected_tenant_id <> 'school-wise-wolf'
    or nullif(pg_catalog.btrim(p_expected_provider_customer_id), '') is null
    or pg_catalog.length(
         pg_catalog.btrim(p_expected_provider_customer_id)
       ) > 240
    or nullif(pg_catalog.btrim(p_event_id), '') is null
    or pg_catalog.length(pg_catalog.btrim(p_event_id)) > 240
    or p_event_created_at is null
    or nullif(pg_catalog.btrim(p_provider_status), '') is null
    or pg_catalog.length(pg_catalog.btrim(p_provider_status)) > 120
    or p_payload is null
    or pg_catalog.jsonb_typeof(p_payload) <> 'object'
  then
    raise exception using
      errcode = '22023',
      message = 'historical_reversal_arguments_invalid';
  end if;

  expected_rank := case p_event_name
    when 'PAYMENT_REFUNDED' then 100
    when 'PAYMENT_RECEIVED_IN_CASH_UNDONE' then 100
    when 'PAYMENT_PARTIALLY_REFUNDED' then 90
    when 'PAYMENT_UPDATED' then 30
    else null
  end;
  if expected_rank is null or p_event_rank is distinct from expected_rank then
    raise exception using
      errcode = '22023',
      message = 'historical_reversal_event_invalid';
  end if;

  if p_refunded_amount is null
    or p_refunded_amount::text in ('NaN', 'Infinity', '-Infinity')
    or p_refunded_amount <= 0
  then
    raise exception using
      errcode = '22023',
      message = 'historical_reversal_amount_invalid';
  end if;

  incoming_payment_id := nullif(
    pg_catalog.btrim(p_payload #>> '{payment,id}'),
    ''
  );
  incoming_customer := nullif(
    pg_catalog.btrim(p_payload #>> '{payment,customer}'),
    ''
  );
  incoming_event_id := nullif(pg_catalog.btrim(p_payload ->> 'id'), '');
  incoming_event_name := nullif(pg_catalog.btrim(p_payload ->> 'event'), '');
  if incoming_payment_id is distinct from pg_catalog.btrim(p_provider_payment_id)
    or incoming_customer is distinct from
         pg_catalog.btrim(p_expected_provider_customer_id)
    or incoming_event_id is distinct from pg_catalog.btrim(p_event_id)
    or incoming_event_name is distinct from p_event_name
  then
    raise exception using
      errcode = '23514',
      message = 'historical_reversal_payload_identity_mismatch';
  end if;

  select payment.*
   into payment_record
    from public.student_payments as payment
   where payment.id = p_expected_local_payment_id
     and payment.asaas_payment_id = pg_catalog.btrim(p_provider_payment_id)
   for update;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'payment_not_found'
    );
  end if;

  if payment_record.student_id is distinct from p_expected_student_id
    or payment_record.tenant_id is distinct from
         pg_catalog.btrim(p_expected_tenant_id)
    or payment_record.provider_customer_id is null
    or payment_record.provider_customer_id is distinct from
         pg_catalog.btrim(p_expected_provider_customer_id)
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'local_binding_mismatch'
    );
  end if;

  if payment_record.value is null
    or payment_record.value::text in ('NaN', 'Infinity', '-Infinity')
    or payment_record.value <= 0
    or p_refunded_amount > payment_record.value
    or p_refunded_amount < coalesce(payment_record.refunded_amount, 0)
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'refund_amount_mismatch'
    );
  end if;

  if p_event_name in (
       'PAYMENT_REFUNDED',
       'PAYMENT_RECEIVED_IN_CASH_UNDONE'
     )
     and round(p_refunded_amount, 2) <> round(payment_record.value, 2)
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'full_refund_amount_mismatch'
    );
  end if;

  -- PAYMENT_UPDATED has no reversal semantics by name. It is accepted only
  -- when its own snapshot proves a completed cumulative refund. Explicit
  -- reversal events are checked too so callers cannot inflate a partial
  -- refund beyond the provider evidence present in the signed payload.
  if p_payload #>> '{payment,refundedValue}' is not null then
    begin
      provider_refunded_value :=
        (p_payload #>> '{payment,refundedValue}')::numeric;
    exception
      when invalid_text_representation or numeric_value_out_of_range then
        raise exception using
          errcode = '23514',
          message = 'historical_reversal_refunded_value_invalid';
    end;
    if provider_refunded_value::text in ('NaN', 'Infinity', '-Infinity')
      or provider_refunded_value < 0
    then
      raise exception using
        errcode = '23514',
        message = 'historical_reversal_refunded_value_invalid';
    end if;
  end if;

  if coalesce(
       pg_catalog.jsonb_typeof(p_payload #> '{payment,refunds}'),
       'null'
     ) not in ('null', 'array')
  then
    raise exception using
      errcode = '23514',
      message = 'historical_reversal_refunds_invalid';
  elsif pg_catalog.jsonb_typeof(p_payload #> '{payment,refunds}') = 'array'
  then
    for refund_item in
      select item.value
        from pg_catalog.jsonb_array_elements(
          p_payload #> '{payment,refunds}'
        ) as item(value)
    loop
      if pg_catalog.upper(coalesce(refund_item ->> 'status', '')) = 'DONE' then
        begin
          refund_item_value := (refund_item ->> 'value')::numeric;
        exception
          when invalid_text_representation or numeric_value_out_of_range then
            raise exception using
              errcode = '23514',
              message = 'historical_reversal_refund_item_invalid';
        end;
        if refund_item_value is null
          or refund_item_value::text in ('NaN', 'Infinity', '-Infinity')
          or refund_item_value <= 0
        then
          raise exception using
            errcode = '23514',
            message = 'historical_reversal_refund_item_invalid';
        end if;
        completed_refunds_value := completed_refunds_value + refund_item_value;
      end if;
    end loop;
  end if;

  if p_event_name not in (
       'PAYMENT_REFUNDED',
       'PAYMENT_RECEIVED_IN_CASH_UNDONE'
     )
     and round(
       greatest(provider_refunded_value, completed_refunds_value),
       2
     ) < round(p_refunded_amount, 2)
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'refund_evidence_mismatch'
    );
  end if;

  -- A reversal payload may repeat value, but it may never alter the locally
  -- bound gross amount. If present, validate it to cents and discard it.
  payload_value_text := p_payload #>> '{payment,value}';
  if payload_value_text is not null then
    begin
      payload_value := payload_value_text::numeric;
    exception
      when invalid_text_representation or numeric_value_out_of_range then
        raise exception using
          errcode = '23514',
          message = 'historical_reversal_payload_value_invalid';
    end;
    if payload_value::text in ('NaN', 'Infinity', '-Infinity')
      or round(payload_value, 2) <> round(payment_record.value, 2)
    then
      raise exception using
        errcode = '23514',
        message = 'historical_reversal_payload_value_mismatch';
    end if;
  end if;

  if payment_record.last_provider_event_at is not null
    and (
      p_event_created_at < payment_record.last_provider_event_at
      or (
        p_event_created_at = payment_record.last_provider_event_at
        and p_event_rank < coalesce(payment_record.last_provider_event_rank, 0)
      )
    )
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'IGNORED',
      'id', payment_record.id,
      'due_date', payment_record.due_date,
      'status', payment_record.status
    );
  end if;

  next_status := case
    when payment_record.status = 'NAO_RECEITA' then 'NAO_RECEITA'
    when p_event_name in (
      'PAYMENT_REFUNDED',
      'PAYMENT_RECEIVED_IN_CASH_UNDONE'
    ) or round(p_refunded_amount, 2) >= round(payment_record.value, 2)
      then 'REFUNDED'
    when payment_record.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'PAGO')
      then payment_record.status
    else pg_catalog.btrim(p_provider_status)
  end;

  update public.student_payments as payment
     set status = next_status,
         provider_status = pg_catalog.btrim(p_provider_status),
         refunded_amount = round(p_refunded_amount, 2),
         last_provider_event_id = pg_catalog.btrim(p_event_id),
         last_provider_event_at = p_event_created_at,
         last_provider_event_rank = p_event_rank,
         updated_at = pg_catalog.clock_timestamp()
   where payment.id = payment_record.id
  returning payment.* into payment_record;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'UPDATED',
    'id', payment_record.id,
    'due_date', payment_record.due_date,
    'status', payment_record.status
  );
end;
$$;


--
-- Name: FUNCTION apply_historical_asaas_payment_reversal_pre_message_fence_impl(p_provider_payment_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_event_id text, p_event_name text, p_event_created_at timestamp with time zone, p_event_rank integer, p_provider_status text, p_refunded_amount numeric, p_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_historical_asaas_payment_reversal_pre_message_fence_impl(p_provider_payment_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_event_id text, p_event_name text, p_event_created_at timestamp with time zone, p_event_rank integer, p_provider_status text, p_refunded_amount numeric, p_payload jsonb) IS 'Atomic update-only application of a proven historical Asaas reversal. It preserves gross value, tenant/student/provider identity, provider customer, original raw snapshot, and all financial dates.';


--
-- Name: apply_inactive_student_payment_settlement(text, uuid, uuid, text, text, text, text, timestamp with time zone, integer, text, numeric, date, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_inactive_student_payment_settlement(p_provider_payment_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_event_id text, p_event_name text, p_event_created_at timestamp with time zone, p_event_rank integer, p_provider_status text, p_provider_value numeric, p_payment_date date, p_credited_at timestamp with time zone, p_estimated_credit_at timestamp with time zone, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_row public.student_payments%rowtype;
  normalized_payment_id text := nullif(trim(coalesce(p_provider_payment_id, '')), '');
  normalized_tenant text := nullif(trim(coalesce(p_expected_tenant_id, '')), '');
  normalized_customer text := nullif(trim(coalesce(p_expected_provider_customer_id, '')), '');
  normalized_event_id text := nullif(trim(coalesce(p_event_id, '')), '');
  normalized_event text := upper(trim(coalesce(p_event_name, '')));
  normalized_provider_status text := nullif(trim(coalesce(p_provider_status, '')), '');
  next_status text;
  payload_value numeric;
  local_payment_count integer := 0;
begin
  if normalized_payment_id is null or p_expected_local_payment_id is null
     or p_expected_student_id is null or normalized_tenant is null
     or normalized_customer is null or normalized_event_id is null
     or normalized_event not in ('PAYMENT_RECEIVED', 'PAYMENT_RECEIVED_IN_CASH')
     or p_event_created_at is null or coalesce(p_event_rank, 0) <= 0
     or normalized_provider_status is null or p_provider_value is null
     or p_provider_value::text in ('NaN', 'Infinity', '-Infinity')
     or p_provider_value <= 0 or jsonb_typeof(p_payload) <> 'object'
     or (
       normalized_event = 'PAYMENT_RECEIVED_IN_CASH'
       and p_payment_date is null
     )
  then
    raise exception using errcode = '22023', message = 'inactive_settlement_input_invalid';
  end if;
  if nullif(trim(p_payload #>> '{payment,id}'), '') is distinct from normalized_payment_id
     or nullif(trim(p_payload #>> '{payment,customer}'), '') is distinct from normalized_customer
     or nullif(trim(p_payload ->> 'id'), '') is distinct from normalized_event_id
     or upper(trim(coalesce(p_payload ->> 'event', ''))) is distinct from normalized_event
     or nullif(trim(p_payload #>> '{payment,paymentDate}'), '')
          is distinct from (
            case when p_payment_date is null then null else p_payment_date::text end
          )
  then
    raise exception using errcode = '23514', message = 'inactive_settlement_payload_identity_mismatch';
  end if;
  begin
    payload_value := (p_payload #>> '{payment,value}')::numeric;
  exception
    when invalid_text_representation or numeric_value_out_of_range then
      raise exception using errcode = '23514', message = 'inactive_settlement_payload_value_invalid';
  end;
  if payload_value is null or payload_value::text in ('NaN', 'Infinity', '-Infinity')
     or round(payload_value, 2) <> round(p_provider_value, 2)
  then
    raise exception using errcode = '23514', message = 'inactive_settlement_payload_value_mismatch';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' ||
        p_expected_student_id::text,
      0
    )
  );

  if exists (
    select 1
      from public.student_payments as payment
     where (
       nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = normalized_payment_id
       or nullif(trim(coalesce(payment.asaas_id, '')), '') = normalized_payment_id
     )
       and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') is not null
       and nullif(trim(coalesce(payment.asaas_id, '')), '') is not null
       and trim(payment.asaas_payment_id) <> trim(payment.asaas_id)
  ) then
    return jsonb_build_object('ok', false, 'reason', 'local_payment_provider_alias_divergence');
  end if;
  select count(*) into local_payment_count
    from public.student_payments as payment
   where nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = normalized_payment_id
      or nullif(trim(coalesce(payment.asaas_id, '')), '') = normalized_payment_id;
  if local_payment_count > 1 then
    return jsonb_build_object('ok', false, 'reason', 'local_payment_binding_ambiguous');
  end if;

  select payment.* into payment_row
    from public.student_payments as payment
   where payment.id = p_expected_local_payment_id
     and (
       nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = normalized_payment_id
       or nullif(trim(coalesce(payment.asaas_id, '')), '') = normalized_payment_id
     )
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'payment_not_found');
  end if;
  if payment_row.student_id is distinct from p_expected_student_id
     or payment_row.tenant_id is distinct from normalized_tenant
     or nullif(trim(coalesce(payment_row.provider_customer_id, '')), '') is distinct from normalized_customer
     or payment_row.value is null
     or payment_row.value::text in ('NaN', 'Infinity', '-Infinity')
     or round(payment_row.value, 2) <> round(p_provider_value, 2)
  then
    return jsonb_build_object('ok', false, 'reason', 'local_binding_mismatch');
  end if;
  if payment_row.last_provider_event_at is not null and (
    p_event_created_at < payment_row.last_provider_event_at
    or (
      p_event_created_at = payment_row.last_provider_event_at
      and p_event_rank < coalesce(payment_row.last_provider_event_rank, 0)
    )
  ) then
    return jsonb_build_object(
      'ok', true,
      'action', 'IGNORED',
      'id', payment_row.id,
      'due_date', payment_row.due_date,
      'status', payment_row.status
    );
  end if;

  next_status := case
    when payment_row.status = 'NAO_RECEITA' then 'NAO_RECEITA'
    when normalized_event = 'PAYMENT_RECEIVED_IN_CASH' then 'RECEIVED_IN_CASH'
    else 'RECEIVED'
  end;
  update public.student_payments as payment
     set status = next_status,
         provider_status = normalized_provider_status,
         payment_date = coalesce(p_payment_date, payment.payment_date),
         credited_at = coalesce(p_credited_at, payment.credited_at),
         paid_at = coalesce(
           p_credited_at,
           p_payment_date + interval '12 hours',
           payment.paid_at
         ),
         estimated_credit_at = coalesce(p_estimated_credit_at, payment.estimated_credit_at),
         raw_payload = p_payload,
         last_provider_event_id = normalized_event_id,
         last_provider_event_at = p_event_created_at,
         last_provider_event_rank = p_event_rank,
         updated_at = clock_timestamp()
   where payment.id = payment_row.id
   returning payment.* into payment_row;
  return jsonb_build_object(
    'ok', true,
    'action', 'UPDATED',
    'id', payment_row.id,
    'due_date', payment_row.due_date,
    'status', payment_row.status
  );
end;
$$;


--
-- Name: apply_monthly_payment_closure_delivery_result(text, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_monthly_payment_closure_delivery_result(p_tenant_id text, p_period_start date, p_attempt_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  normalized_period date := pg_catalog.date_trunc('month', p_period_start)::date;
  delivery_status text;
begin
  if normalized_tenant is null or p_period_start is null or p_attempt_id is null then
    return false;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'monthly-payment-closure:' || normalized_tenant || ':' || normalized_period::text,
      0
    )
  );

  select attempt.status
    into delivery_status
    from public.management_group_message_attempts as attempt
   where attempt.id = p_attempt_id
     and attempt.tenant_id = normalized_tenant
     and attempt.notification_kind = 'MONTHLY_PAYMENT_CLOSE'
     and attempt.subject_id = normalized_tenant
     and attempt.ref_date = normalized_period
     and attempt.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED')
   for update;
  if not found then
    return false;
  end if;

  if delivery_status = 'SENT' then
    update public.monthly_payment_closures as closure
       set status = 'SENT',
           sent_at = coalesce(closure.sent_at, pg_catalog.now()),
           sent_attempt_id = p_attempt_id,
           review_reason = null,
           updated_at = pg_catalog.now()
     where closure.tenant_id = normalized_tenant
       and closure.period_start = normalized_period
       and closure.snapshot_hash is not null
       and (
         closure.sent_at is null
         or closure.sent_attempt_id = p_attempt_id
       );
  else
    update public.monthly_payment_closures as closure
       set status = 'REVIEW',
           review_reason = case delivery_status
             when 'FAILED' then 'monthly_message_failed'
             when 'UNKNOWN' then 'monthly_message_unknown'
             else 'monthly_message_suppressed'
           end,
           updated_at = pg_catalog.now()
     where closure.tenant_id = normalized_tenant
       and closure.period_start = normalized_period
       and closure.sent_at is null
       and closure.snapshot_hash is not null;
  end if;

  return found;
end;
$$;


--
-- Name: apply_my_attendance_response(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_my_attendance_response(p_confirmation_id uuid, p_response text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  return private.apply_attendance_response(
    p_confirmation_id,
    null,
    p_response,
    v_uid,
    'AUTHENTICATED_STUDENT'
  );
end;
$$;


--
-- Name: apply_saas_checkout_billing_event(uuid, text, text, timestamp with time zone, text, numeric, text, text, text, text, timestamp with time zone, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_saas_checkout_billing_event(p_checkout_id uuid, p_event_name text, p_provider_event_id text, p_event_created_at timestamp with time zone, p_payment_id text DEFAULT NULL::text, p_payment_value numeric DEFAULT NULL::numeric, p_billing_type text DEFAULT NULL::text, p_customer_id text DEFAULT NULL::text, p_subscription_id text DEFAULT NULL::text, p_billing_cycle text DEFAULT NULL::text, p_paid_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_due_date date DEFAULT NULL::date, p_invoice_url text DEFAULT NULL::text, p_bank_slip_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  checkout_row public.saas_checkout_intents%rowtype;
  checkout_watermark public.saas_checkout_event_watermarks%rowtype;
  entity_watermark public.saas_provider_entity_watermarks%rowtype;
  normalized_event text := upper(pg_catalog.btrim(coalesce(p_event_name, '')));
  normalized_event_id text := nullif(
    pg_catalog.btrim(coalesce(p_provider_event_id, '')),
    ''
  );
  normalized_payment_id text := nullif(
    pg_catalog.btrim(coalesce(p_payment_id, '')),
    ''
  );
  normalized_subscription_id text := nullif(
    pg_catalog.btrim(coalesce(p_subscription_id, '')),
    ''
  );
  normalized_customer_id text := nullif(
    pg_catalog.btrim(coalesce(p_customer_id, '')),
    ''
  );
  normalized_billing_type text := upper(
    pg_catalog.btrim(coalesce(p_billing_type, ''))
  );
  normalized_billing_cycle text := upper(
    pg_catalog.btrim(coalesce(p_billing_cycle, ''))
  );
  entity_kind text;
  entity_id text;
  event_rank integer;
  event_is_terminal boolean;
  event_terminates_checkout boolean;
  event_grants_access boolean;
  event_restricts_access boolean;
  replay_requires_provision boolean;
  checkout_event_is_stale boolean := false;
  terminal_checkout_blocks_global boolean := false;
  checkout_stale_reason text;
  entity_event_advances boolean;
  entity_event_ambiguous boolean;
  legacy_paid_anchor timestamptz;
  existing_invoice public.saas_invoices%rowtype;
  result jsonb;
begin
  if p_checkout_id is null
     or normalized_event_id is null
     or length(normalized_event_id) > 240
     or p_event_created_at is null
     or p_event_created_at < timestamptz '2000-01-01 00:00:00+00'
     or p_event_created_at > pg_catalog.now() + interval '1 day'
     or normalized_event not in (
       'PAYMENT_CONFIRMED',
       'PAYMENT_RECEIVED',
       'PAYMENT_RECEIVED_IN_CASH',
       'PAYMENT_OVERDUE',
       'PAYMENT_REFUND_IN_PROGRESS',
       'PAYMENT_BANK_SLIP_CANCELLED',
       'PAYMENT_CREDIT_CARD_CAPTURE_REFUSED',
       'PAYMENT_REPROVED_BY_RISK_ANALYSIS',
       'PAYMENT_DELETED',
       'PAYMENT_REFUNDED',
       'PAYMENT_PARTIALLY_REFUNDED',
       'PAYMENT_RECEIVED_IN_CASH_UNDONE',
       'PAYMENT_CHARGEBACK_REQUESTED',
       'SUBSCRIPTION_INACTIVATED',
       'SUBSCRIPTION_DELETED'
     )
  then
    raise exception using
      errcode = '22023', message = 'invalid_ordered_saas_provider_event';
  end if;

  if normalized_event like 'SUBSCRIPTION_%' then
    entity_kind := 'SUBSCRIPTION';
    entity_id := normalized_subscription_id;
  else
    entity_kind := 'PAYMENT';
    entity_id := normalized_payment_id;
  end if;
  if entity_id is null or length(entity_id) > 240 then
    raise exception using
      errcode = '22023', message = 'saas_provider_entity_id_required';
  end if;

  event_rank := private.saas_provider_event_rank(normalized_event);
  event_is_terminal := private.saas_provider_event_is_terminal(normalized_event);
  event_terminates_checkout :=
    private.saas_provider_event_terminates_checkout(normalized_event);
  event_grants_access := normalized_event in (
    'PAYMENT_RECEIVED', 'PAYMENT_RECEIVED_IN_CASH'
  );
  event_restricts_access := event_terminates_checkout or normalized_event in (
    'PAYMENT_OVERDUE',
    'PAYMENT_REFUND_IN_PROGRESS',
    'PAYMENT_BANK_SLIP_CANCELLED',
    'PAYMENT_CREDIT_CARD_CAPTURE_REFUSED',
    'PAYMENT_REPROVED_BY_RISK_ANALYSIS'
  );

  select checkout.* into checkout_row
    from public.saas_checkout_intents as checkout
   where checkout.id = p_checkout_id
   for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'saas_checkout_not_found';
  end if;
  if normalized_subscription_id is null
     or checkout_row.asaas_subscription_id is null
     or checkout_row.asaas_subscription_id <> normalized_subscription_id
  then
    raise exception using errcode = '42501', message = 'saas_subscription_mismatch';
  end if;
  if normalized_customer_id is null
     or checkout_row.asaas_customer_id is null
     or checkout_row.asaas_customer_id <> normalized_customer_id
  then
    raise exception using errcode = '42501', message = 'saas_customer_mismatch';
  end if;
  if p_payment_value is null
     or pg_catalog.abs(p_payment_value - checkout_row.amount) >= 0.005
  then
    raise exception using errcode = '42501', message = 'saas_amount_mismatch';
  end if;
  if normalized_billing_type = ''
     or normalized_billing_type <> upper(checkout_row.billing_type)
  then
    raise exception using errcode = '42501', message = 'saas_billing_type_mismatch';
  end if;
  if normalized_billing_cycle <> ''
     and normalized_billing_cycle <> upper(checkout_row.billing_cycle)
  then
    raise exception using errcode = '42501', message = 'saas_billing_cycle_mismatch';
  end if;

  replay_requires_provision := event_grants_access
    and upper(pg_catalog.btrim(coalesce(checkout_row.status, ''))) = 'PAID'
    and normalized_payment_id is not null
    and nullif(
      pg_catalog.btrim(coalesce(checkout_row.asaas_payment_id, '')),
      ''
    ) = normalized_payment_id
    and (
      checkout_row.tenant_id is null
      or checkout_row.provisioned_at is null
    );

  select watermark.* into checkout_watermark
    from public.saas_checkout_event_watermarks as watermark
   where watermark.checkout_id = p_checkout_id
   for update;

  select watermark.* into entity_watermark
    from public.saas_provider_entity_watermarks as watermark
   where watermark.checkout_id = p_checkout_id
     and watermark.provider_entity_kind = entity_kind
     and watermark.provider_entity_id = entity_id
   for update;

  if checkout_watermark.last_provider_event_id is not null
     and checkout_watermark.last_provider_event_id = normalized_event_id
  then
    if checkout_watermark.last_provider_event_at is distinct from p_event_created_at
       or checkout_watermark.last_provider_event_name is distinct from normalized_event
       or checkout_watermark.last_provider_entity_kind is distinct from entity_kind
       or checkout_watermark.last_provider_entity_id is distinct from entity_id
    then
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'REVIEW_REQUIRED',
        'reason', 'saas_checkout_provider_event_id_collision',
        'checkout_id', p_checkout_id,
        'provider_event_id', normalized_event_id
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', case
        when event_terminates_checkout then 'TERMINAL_REPLAY_IGNORED'
        when replay_requires_provision then 'PROVISION_REQUIRED'
        else 'ORDER_REPLAY'
      end,
      'reason', case
        when replay_requires_provision then 'saas_provision_resume_required'
        else 'saas_provider_event_replayed'
      end,
      'checkout_id', p_checkout_id,
      'provider_event_id', normalized_event_id
    );
  end if;
  if entity_watermark.last_provider_event_id is not null
     and entity_watermark.last_provider_event_id = normalized_event_id
     and (
       entity_watermark.last_provider_event_at is distinct from p_event_created_at
       or entity_watermark.last_provider_event_name is distinct from normalized_event
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_provider_entity_event_id_collision',
      'checkout_id', p_checkout_id,
      'provider_event_id', normalized_event_id
    );
  end if;

  entity_event_advances := entity_watermark.last_provider_event_id is null
    or p_event_created_at > entity_watermark.last_provider_event_at
    or (
      p_event_created_at = entity_watermark.last_provider_event_at
      and event_rank > entity_watermark.last_provider_event_rank
    );
  entity_event_ambiguous :=
    entity_watermark.last_provider_event_id is not null
    and entity_watermark.last_provider_event_id <> normalized_event_id
    and p_event_created_at = entity_watermark.last_provider_event_at
    and event_rank = entity_watermark.last_provider_event_rank;

  if entity_kind = 'PAYMENT' then
    select invoice.*
      into existing_invoice
      from public.saas_invoices as invoice
     where invoice.asaas_payment_id = entity_id
     for update;
  end if;

  -- A provider payment id is global. If a historical local invoice already
  -- owns it, that exact tenant and amount must agree before either the normal
  -- billing implementation or the entity-only reconciliation may touch it.
  if existing_invoice.id is not null
     and (
       existing_invoice.tenant_id is distinct from checkout_row.tenant_id
       or existing_invoice.amount is null
       or pg_catalog.abs(existing_invoice.amount - checkout_row.amount) >= 0.005
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_payment_invoice_binding_mismatch',
      'checkout_id', p_checkout_id,
      'provider_event_id', normalized_event_id
    );
  end if;

  -- Existing terminal invoices are authoritative even before this migration's
  -- watermark exists. Never turn the same refunded/reversed payment paid.
  if event_grants_access
     and upper(pg_catalog.btrim(coalesce(existing_invoice.status, ''))) in (
    'REFUNDED', 'PARTIALLY_REFUNDED', 'CHARGEBACK', 'CANCELLED'
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'TERMINAL_IGNORED',
      'reason', 'saas_payment_invoice_is_terminal',
      'checkout_id', p_checkout_id,
      'provider_event_id', normalized_event_id
    );
  end if;

  if entity_watermark.terminal_event and not event_is_terminal then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'TERMINAL_IGNORED',
      'reason', 'saas_provider_entity_is_terminal',
      'checkout_id', p_checkout_id,
      'provider_event_id', normalized_event_id
    );
  end if;

  -- The checkout payment binding identifies the payment backing current
  -- access. An event for another already-existing invoice is historical and
  -- belongs to that entity only. A genuinely new recurring installment has no
  -- invoice yet: only settlement or OVERDUE may inaugurate it after the exact
  -- tuple above and an advancing checkout watermark below. An unbound refund,
  -- chargeback or cancellation remains ambiguous and is triaged entity-local.
  if entity_kind = 'PAYMENT'
     and checkout_row.asaas_payment_id is not null
     and pg_catalog.btrim(checkout_row.asaas_payment_id) <> entity_id
     and (event_restricts_access or event_grants_access)
     and (
       existing_invoice.id is not null
       or (
         event_restricts_access
         and normalized_event <> 'PAYMENT_OVERDUE'
       )
     )
  then
    checkout_event_is_stale := true;
    if checkout_watermark.terminal_event
       and (
         p_event_created_at > checkout_watermark.last_provider_event_at
         or (
           p_event_created_at = checkout_watermark.last_provider_event_at
           and event_rank >= checkout_watermark.last_provider_event_rank
         )
       )
    then
      terminal_checkout_blocks_global := true;
      checkout_stale_reason := 'saas_checkout_provider_lifecycle_is_terminal';
    else
      checkout_stale_reason := 'saas_payment_is_not_current_access_payment';
    end if;
  end if;

  -- A legacy cancelled checkout has no trustworthy event-time watermark. No
  -- non-terminal event may first rewrite it to OVERDUE and later open a paid
  -- restoration path. A new subscription needs a new checkout binding.
  if checkout_row.status = 'CANCELLED'
     and checkout_watermark.last_provider_event_id is null
     and not checkout_event_is_stale
     and not event_terminates_checkout
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'REVIEW_REQUIRED',
      'reason', 'cancelled_saas_checkout_cannot_auto_restore',
      'checkout_id', p_checkout_id,
      'provider_event_id', normalized_event_id
    );
  end if;

  -- Legacy OVERDUE rows have no trustworthy provider-time watermark. A paid
  -- event cannot be ordered against the event that suspended access, so it is
  -- deliberately triaged rather than guessed.
  if checkout_row.status = 'OVERDUE'
     and checkout_watermark.last_provider_event_id is null
     and not event_restricts_access
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'REVIEW_REQUIRED',
      'reason', 'legacy_saas_overdue_order_unknown',
      'checkout_id', p_checkout_id,
      'provider_event_id', normalized_event_id
    );
  end if;

  -- Legacy paid/provisioned checkouts have no trustworthy provider watermark.
  -- Restrictive events therefore cannot be trusted for deterministic global
  -- ordering. They must go to manual review, except for older historical
  -- overdue rows that are clearly stale for the same provisioned payment.
  -- provisioned_at is deliberately not an ordering anchor: local provisioning
  -- occurs after settlement, so a real reversal may fall between the two.
  if checkout_watermark.last_provider_event_id is null
     and not checkout_event_is_stale
     and checkout_row.status in (
       'PAID', 'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED'
     )
     and event_restricts_access
     and checkout_row.asaas_payment_id = normalized_payment_id
  then
    legacy_paid_anchor := checkout_row.paid_at;
    if legacy_paid_anchor is null then
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'REVIEW_REQUIRED',
        'reason', 'legacy_saas_access_order_unknown',
        'checkout_id', p_checkout_id,
        'provider_event_id', normalized_event_id
      );
    end if;
    if normalized_event = 'PAYMENT_OVERDUE'
       and checkout_row.asaas_payment_id = normalized_payment_id
       and p_event_created_at < legacy_paid_anchor
    then
      checkout_event_is_stale := true;
      checkout_stale_reason := 'saas_event_predates_legacy_access';
    else
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'REVIEW_REQUIRED',
        'reason', 'legacy_saas_restrictive_order_unknown',
        'checkout_id', p_checkout_id,
        'provider_event_id', normalized_event_id
      );
    end if;
  end if;

  -- Every event is monotonic at checkout scope. A late refund for payment A
  -- must not revoke access already extended by a newer payment B. At the same
  -- provider timestamp the higher rank wins, so a terminal event still
  -- dominates a non-terminal event without relying on delivery order.
  if checkout_watermark.last_provider_event_id is not null then
    if p_event_created_at < checkout_watermark.last_provider_event_at
       or (
         p_event_created_at = checkout_watermark.last_provider_event_at
         and event_rank < checkout_watermark.last_provider_event_rank
       )
    then
      checkout_event_is_stale := true;
      checkout_stale_reason := 'saas_checkout_event_is_stale';
    end if;
    if not checkout_event_is_stale
       and p_event_created_at = checkout_watermark.last_provider_event_at
       and event_rank = checkout_watermark.last_provider_event_rank
    then
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'REVIEW_REQUIRED',
        'reason', 'saas_checkout_event_order_ambiguous',
        'checkout_id', p_checkout_id,
        'provider_event_id', normalized_event_id
      );
    end if;
  end if;

  -- A terminal checkout still accepts an older, independently monotonic
  -- payment observation into the entity-only ledger path below. A same/newer
  -- non-terminal event can never mutate or reactivate the global lifecycle.
  if checkout_watermark.terminal_event
     and not event_terminates_checkout
     and not checkout_event_is_stale
  then
    if entity_kind = 'PAYMENT'
       and (event_grants_access or event_restricts_access)
    then
      checkout_event_is_stale := true;
      terminal_checkout_blocks_global := true;
      checkout_stale_reason := 'saas_checkout_provider_lifecycle_is_terminal';
    else
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'TERMINAL_IGNORED',
        'reason', 'saas_checkout_provider_lifecycle_is_terminal',
        'checkout_id', p_checkout_id,
        'provider_event_id', normalized_event_id
      );
    end if;
  end if;

  -- A stale event, or one blocked by a terminal checkout, must never rewrite
  -- current access. Its own payment observation is nevertheless durable
  -- accounting data: when it is strictly newer for that payment, record only
  -- invoice/entity state and leave the checkout watermark and tenant untouched.
  if checkout_event_is_stale then
    if (
      not event_restricts_access
      and not event_grants_access
    ) or entity_kind <> 'PAYMENT' then
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'STALE_IGNORED',
        'reason', checkout_stale_reason,
        'checkout_id', p_checkout_id,
        'provider_event_id', normalized_event_id
      );
    end if;

    if entity_event_ambiguous then
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'REVIEW_REQUIRED',
        'reason', 'saas_provider_entity_event_order_ambiguous',
        'checkout_id', p_checkout_id,
        'provider_event_id', normalized_event_id
      );
    end if;
    -- The first pass may have committed the exact entity observation and then
    -- crashed before the outer durable inbox persisted TRIAGE. Preserve that
    -- decision on exact replay: treating it as merely stale would strand real
    -- settled money behind a terminal checkout with no review issue.
    if terminal_checkout_blocks_global
       and entity_watermark.last_provider_event_id = normalized_event_id
    then
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'REVIEW_REQUIRED',
        'reason', 'terminal_saas_checkout_payment_reconciled_for_review',
        'entity_observation_applied', true,
        'checkout_id', p_checkout_id,
        'provider_event_id', normalized_event_id,
        'provider_entity_kind', entity_kind,
        'provider_entity_id', entity_id
      );
    end if;
    if not entity_event_advances
       or (
         event_restricts_access
         and
         existing_invoice.paid_at is not null
         and p_event_created_at < existing_invoice.paid_at
       )
    then
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', case
          when event_is_terminal and entity_watermark.terminal_event
            then 'TERMINAL_REPLAY_IGNORED'
          else 'STALE_IGNORED'
        end,
        'reason', 'saas_payment_observation_is_stale',
        'checkout_id', p_checkout_id,
        'provider_event_id', normalized_event_id
      );
    end if;

    if existing_invoice.id is null
       or existing_invoice.tenant_id is distinct from checkout_row.tenant_id
       or existing_invoice.amount is null
       or pg_catalog.abs(existing_invoice.amount - checkout_row.amount) >= 0.005
    then
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'REVIEW_REQUIRED',
        'reason', 'stale_saas_payment_invoice_binding_missing',
        'checkout_id', p_checkout_id,
        'provider_event_id', normalized_event_id
      );
    end if;

    update public.saas_invoices
       set status = case
         when event_grants_access then 'PAID'
         when normalized_event = 'PAYMENT_REFUNDED' then 'REFUNDED'
         when normalized_event = 'PAYMENT_PARTIALLY_REFUNDED'
           then 'PARTIALLY_REFUNDED'
         when normalized_event = 'PAYMENT_CHARGEBACK_REQUESTED'
           then 'CHARGEBACK'
         when normalized_event in (
           'PAYMENT_OVERDUE',
           'PAYMENT_REFUND_IN_PROGRESS',
           'PAYMENT_BANK_SLIP_CANCELLED',
           'PAYMENT_CREDIT_CARD_CAPTURE_REFUSED',
           'PAYMENT_REPROVED_BY_RISK_ANALYSIS'
         ) then 'OVERDUE'
         else 'CANCELLED'
       end,
       paid_at = case
         when event_grants_access then coalesce(
           paid_at,
           p_paid_at,
           p_event_created_at
         )
         else paid_at
       end
     where id = existing_invoice.id;

    insert into public.saas_provider_entity_watermarks (
      checkout_id,
      provider_entity_kind,
      provider_entity_id,
      last_provider_event_id,
      last_provider_event_at,
      last_provider_event_rank,
      last_provider_event_name,
      terminal_event
    ) values (
      p_checkout_id,
      entity_kind,
      entity_id,
      normalized_event_id,
      p_event_created_at,
      event_rank,
      normalized_event,
      event_is_terminal
    ) on conflict (checkout_id, provider_entity_kind, provider_entity_id)
    do update set
      last_provider_event_id = excluded.last_provider_event_id,
      last_provider_event_at = excluded.last_provider_event_at,
      last_provider_event_rank = excluded.last_provider_event_rank,
      last_provider_event_name = excluded.last_provider_event_name,
      terminal_event = public.saas_provider_entity_watermarks.terminal_event
        or excluded.terminal_event,
      updated_at = pg_catalog.now();

    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', case
        when terminal_checkout_blocks_global then 'REVIEW_REQUIRED'
        else 'STALE_ENTITY_APPLIED'
      end,
      'reason', case
        when terminal_checkout_blocks_global
          then 'terminal_saas_checkout_payment_reconciled_for_review'
        else checkout_stale_reason
      end,
      'entity_observation_applied', true,
      'checkout_id', p_checkout_id,
      'provider_event_id', normalized_event_id,
      'provider_entity_kind', entity_kind,
      'provider_entity_id', entity_id
    );
  end if;

  if entity_event_ambiguous then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_provider_entity_event_order_ambiguous',
      'checkout_id', p_checkout_id,
      'provider_event_id', normalized_event_id
    );
  end if;
  if not entity_event_advances then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', case
        when event_is_terminal and entity_watermark.terminal_event
          then 'TERMINAL_REPLAY_IGNORED'
        else 'STALE_IGNORED'
      end,
      'reason', 'saas_provider_entity_event_is_not_newer',
      'checkout_id', p_checkout_id,
      'provider_event_id', normalized_event_id
    );
  end if;

  result := private.apply_saas_checkout_billing_event_unordered_impl(
    p_checkout_id,
    normalized_event,
    normalized_payment_id,
    p_payment_value,
    p_billing_type,
    p_customer_id,
    normalized_subscription_id,
    p_billing_cycle,
    p_paid_at,
    p_due_date,
    p_invoice_url,
    p_bank_slip_url
  );

  insert into public.saas_provider_entity_watermarks (
    checkout_id,
    provider_entity_kind,
    provider_entity_id,
    last_provider_event_id,
    last_provider_event_at,
    last_provider_event_rank,
    last_provider_event_name,
    terminal_event
  ) values (
    p_checkout_id,
    entity_kind,
    entity_id,
    normalized_event_id,
    p_event_created_at,
    event_rank,
    normalized_event,
    event_is_terminal
  ) on conflict (checkout_id, provider_entity_kind, provider_entity_id)
  do update set
    last_provider_event_id = excluded.last_provider_event_id,
    last_provider_event_at = excluded.last_provider_event_at,
    last_provider_event_rank = excluded.last_provider_event_rank,
    last_provider_event_name = excluded.last_provider_event_name,
    terminal_event = public.saas_provider_entity_watermarks.terminal_event
      or excluded.terminal_event,
    updated_at = pg_catalog.now();

  insert into public.saas_checkout_event_watermarks (
    checkout_id,
    last_provider_event_id,
    last_provider_event_at,
    last_provider_event_rank,
    last_provider_event_name,
    last_provider_entity_kind,
    last_provider_entity_id,
    terminal_event
  ) values (
    p_checkout_id,
    normalized_event_id,
    p_event_created_at,
    event_rank,
    normalized_event,
    entity_kind,
    entity_id,
    event_terminates_checkout
  ) on conflict (checkout_id) do update set
    last_provider_event_id = case when (
      excluded.last_provider_event_at,
      excluded.last_provider_event_rank
    ) > (
      public.saas_checkout_event_watermarks.last_provider_event_at,
      public.saas_checkout_event_watermarks.last_provider_event_rank
    ) then excluded.last_provider_event_id
      else public.saas_checkout_event_watermarks.last_provider_event_id end,
    last_provider_event_at = greatest(
      excluded.last_provider_event_at,
      public.saas_checkout_event_watermarks.last_provider_event_at
    ),
    last_provider_event_rank = case when
      excluded.last_provider_event_at
        > public.saas_checkout_event_watermarks.last_provider_event_at
      then excluded.last_provider_event_rank
      when excluded.last_provider_event_at
        = public.saas_checkout_event_watermarks.last_provider_event_at
      then greatest(
        excluded.last_provider_event_rank,
        public.saas_checkout_event_watermarks.last_provider_event_rank
      ) else public.saas_checkout_event_watermarks.last_provider_event_rank end,
    last_provider_event_name = case when (
      excluded.last_provider_event_at,
      excluded.last_provider_event_rank
    ) > (
      public.saas_checkout_event_watermarks.last_provider_event_at,
      public.saas_checkout_event_watermarks.last_provider_event_rank
    ) then excluded.last_provider_event_name
      else public.saas_checkout_event_watermarks.last_provider_event_name end,
    last_provider_entity_kind = case when (
      excluded.last_provider_event_at,
      excluded.last_provider_event_rank
    ) > (
      public.saas_checkout_event_watermarks.last_provider_event_at,
      public.saas_checkout_event_watermarks.last_provider_event_rank
    ) then excluded.last_provider_entity_kind
      else public.saas_checkout_event_watermarks.last_provider_entity_kind end,
    last_provider_entity_id = case when (
      excluded.last_provider_event_at,
      excluded.last_provider_event_rank
    ) > (
      public.saas_checkout_event_watermarks.last_provider_event_at,
      public.saas_checkout_event_watermarks.last_provider_event_rank
    ) then excluded.last_provider_entity_id
      else public.saas_checkout_event_watermarks.last_provider_entity_id end,
    terminal_event = public.saas_checkout_event_watermarks.terminal_event
      or excluded.terminal_event,
    updated_at = pg_catalog.now();

  return coalesce(result, '{}'::jsonb) || pg_catalog.jsonb_build_object(
    'provider_event_id', normalized_event_id,
    'provider_event_at', p_event_created_at,
    'provider_event_rank', event_rank,
    'provider_entity_kind', entity_kind,
    'provider_entity_id', entity_id
  );
end;
$$;


--
-- Name: apply_saas_checkout_billing_event_pre_settlement_impl(uuid, text, text, numeric, text, text, text, text, timestamp with time zone, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_saas_checkout_billing_event_pre_settlement_impl(p_checkout_id uuid, p_event_name text, p_payment_id text DEFAULT NULL::text, p_payment_value numeric DEFAULT NULL::numeric, p_billing_type text DEFAULT NULL::text, p_customer_id text DEFAULT NULL::text, p_subscription_id text DEFAULT NULL::text, p_billing_cycle text DEFAULT NULL::text, p_paid_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_due_date date DEFAULT NULL::date, p_invoice_url text DEFAULT NULL::text, p_bank_slip_url text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  checkout public.saas_checkout_intents%ROWTYPE;
  selected_plan public.saas_plans%ROWTYPE;
  tenant public.tenants%ROWTYPE;
  existing_invoice public.saas_invoices%ROWTYPE;
  event_name text := upper(trim(coalesce(p_event_name, '')));
  payment_id text := nullif(trim(coalesce(p_payment_id, '')), '');
  customer_id text := nullif(trim(coalesce(p_customer_id, '')), '');
  subscription_id text := nullif(trim(coalesce(p_subscription_id, '')), '');
  billing_type text := upper(trim(coalesce(p_billing_type, '')));
  billing_cycle text := upper(trim(coalesce(p_billing_cycle, '')));
  period_anchor timestamptz;
  period_end timestamptz;
  invoice_was_paid boolean := false;
  is_paid_event boolean := event_name IN (
    'PAYMENT_CONFIRMED',
    'PAYMENT_RECEIVED'
  );
  is_overdue_event boolean := event_name IN (
    'PAYMENT_OVERDUE',
    'PAYMENT_REFUND_IN_PROGRESS',
    'PAYMENT_BANK_SLIP_CANCELLED',
    'PAYMENT_CREDIT_CARD_CAPTURE_REFUSED',
    'PAYMENT_REPROVED_BY_RISK_ANALYSIS'
  );
  is_terminal_event boolean := event_name IN (
    'PAYMENT_DELETED',
    'PAYMENT_REFUNDED',
    'PAYMENT_PARTIALLY_REFUNDED',
    'PAYMENT_RECEIVED_IN_CASH_UNDONE',
    'PAYMENT_CHARGEBACK_REQUESTED',
    'SUBSCRIPTION_INACTIVATED',
    'SUBSCRIPTION_DELETED'
  );
BEGIN
  IF p_checkout_id IS NULL OR event_name = '' THEN
    RAISE EXCEPTION 'saas_billing_event_invalid'
      USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO checkout
  FROM public.saas_checkout_intents AS candidate
  WHERE candidate.id = p_checkout_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'saas_checkout_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF subscription_id IS NULL
     OR checkout.asaas_subscription_id IS NULL
     OR subscription_id <> checkout.asaas_subscription_id THEN
    RAISE EXCEPTION 'saas_subscription_mismatch' USING ERRCODE = '42501';
  END IF;
  IF customer_id IS NULL
     OR checkout.asaas_customer_id IS NULL
     OR customer_id <> checkout.asaas_customer_id THEN
    RAISE EXCEPTION 'saas_customer_mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_payment_value IS NULL
     OR abs(p_payment_value - checkout.amount) >= 0.005 THEN
    RAISE EXCEPTION 'saas_amount_mismatch' USING ERRCODE = '42501';
  END IF;
  IF billing_type = '' OR billing_type <> upper(checkout.billing_type) THEN
    RAISE EXCEPTION 'saas_billing_type_mismatch' USING ERRCODE = '42501';
  END IF;
  IF billing_cycle <> ''
     AND billing_cycle <> upper(checkout.billing_cycle) THEN
    RAISE EXCEPTION 'saas_billing_cycle_mismatch' USING ERRCODE = '42501';
  END IF;
  IF event_name LIKE 'PAYMENT_%' AND payment_id IS NULL THEN
    RAISE EXCEPTION 'saas_payment_id_required' USING ERRCODE = '22023';
  END IF;

  IF NOT is_paid_event AND NOT is_overdue_event AND NOT is_terminal_event THEN
    UPDATE public.saas_checkout_intents
    SET invoice_url = coalesce(p_invoice_url, invoice_url),
        bank_slip_url = coalesce(p_bank_slip_url, bank_slip_url),
        due_date = coalesce(p_due_date, due_date),
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'lastBillingEvent', event_name,
          'lastBillingEventAt', pg_catalog.now()
        ),
        updated_at = pg_catalog.now()
    WHERE id = checkout.id;

    RETURN jsonb_build_object(
      'ok', true,
      'action', 'IGNORED',
      'checkout_id', checkout.id
    );
  END IF;

  IF is_paid_event
     AND (checkout.tenant_id IS NULL OR checkout.provisioned_at IS NULL) THEN
    UPDATE public.saas_checkout_intents
    SET status = 'PAID',
        asaas_payment_id = payment_id,
        invoice_url = coalesce(p_invoice_url, invoice_url),
        bank_slip_url = coalesce(p_bank_slip_url, bank_slip_url),
        due_date = coalesce(p_due_date, due_date),
        paid_at = coalesce(p_paid_at, paid_at, pg_catalog.now()),
        last_error = NULL,
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'lastBillingEvent', event_name,
          'lastBillingEventAt', pg_catalog.now()
        ),
        updated_at = pg_catalog.now()
    WHERE id = checkout.id;

    RETURN jsonb_build_object(
      'ok', true,
      'action', 'PROVISION_REQUIRED',
      'checkout_id', checkout.id
    );
  END IF;

  IF checkout.tenant_id IS NOT NULL THEN
    SELECT *
    INTO tenant
    FROM public.tenants AS candidate
    WHERE candidate.id = checkout.tenant_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'saas_tenant_not_found' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  IF is_overdue_event OR is_terminal_event THEN
    IF payment_id IS NOT NULL THEN
      UPDATE public.saas_invoices
      SET status = CASE
            WHEN is_overdue_event THEN 'OVERDUE'
            WHEN event_name = 'PAYMENT_REFUNDED' THEN 'REFUNDED'
            WHEN event_name = 'PAYMENT_PARTIALLY_REFUNDED' THEN 'PARTIALLY_REFUNDED'
            WHEN event_name = 'PAYMENT_CHARGEBACK_REQUESTED' THEN 'CHARGEBACK'
            ELSE 'CANCELLED'
          END
      WHERE asaas_payment_id = payment_id
        AND tenant_id IS NOT DISTINCT FROM checkout.tenant_id;
    END IF;

    IF checkout.tenant_id IS NOT NULL THEN
      UPDATE public.tenants
      SET saas_status = CASE
            WHEN is_overdue_event THEN 'past_due'
            ELSE 'blocked'
          END,
          current_period_end = least(
            coalesce(current_period_end, pg_catalog.now()),
            pg_catalog.now()
          )
      WHERE id = checkout.tenant_id;
    END IF;

    UPDATE public.saas_checkout_intents
    SET status = CASE
          WHEN is_overdue_event THEN 'OVERDUE'
          ELSE 'CANCELLED'
        END,
        asaas_payment_id = coalesce(payment_id, asaas_payment_id),
        invoice_url = coalesce(p_invoice_url, invoice_url),
        bank_slip_url = coalesce(p_bank_slip_url, bank_slip_url),
        due_date = coalesce(p_due_date, due_date),
        metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
          'lastBillingEvent', event_name,
          'lastBillingEventAt', pg_catalog.now(),
          'accessRevokedAt', pg_catalog.now()
        ),
        updated_at = pg_catalog.now()
    WHERE id = checkout.id;

    RETURN jsonb_build_object(
      'ok', true,
      'action', CASE WHEN is_overdue_event THEN 'SUSPENDED' ELSE 'REVOKED' END,
      'checkout_id', checkout.id,
      'tenant_id', checkout.tenant_id
    );
  END IF;

  IF checkout.tenant_id IS NULL THEN
    RAISE EXCEPTION 'saas_tenant_required_for_renewal'
      USING ERRCODE = '55000';
  END IF;

  SELECT *
  INTO selected_plan
  FROM public.saas_plans AS plan
  WHERE plan.id = checkout.plan_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'saas_plan_not_found' USING ERRCODE = 'P0002';
  END IF;

  SELECT *
  INTO existing_invoice
  FROM public.saas_invoices AS invoice
  WHERE invoice.asaas_payment_id = payment_id
  FOR UPDATE;
  invoice_was_paid := FOUND AND upper(coalesce(existing_invoice.status, '')) = 'PAID';

  IF checkout.status = 'CANCELLED'
     AND (NOT FOUND OR invoice_was_paid) THEN
    RAISE EXCEPTION 'saas_checkout_terminal'
      USING ERRCODE = '55000';
  END IF;

  IF FOUND THEN
    UPDATE public.saas_invoices
    SET status = 'PAID',
        paid_at = coalesce(paid_at, p_paid_at, pg_catalog.now())
    WHERE id = existing_invoice.id;

    IF invoice_was_paid THEN
      UPDATE public.saas_checkout_intents
      SET metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
            'lastBillingEvent', event_name,
            'lastBillingEventAt', pg_catalog.now(),
            'lastBillingReplayPaymentId', payment_id
          ),
          updated_at = pg_catalog.now()
      WHERE id = checkout.id;

      RETURN jsonb_build_object(
        'ok', true,
        'action', 'REPLAY',
        'checkout_id', checkout.id,
        'tenant_id', checkout.tenant_id
      );
    END IF;

    period_end := existing_invoice.billing_period_end::timestamptz;
  ELSE
    period_anchor := greatest(
      coalesce(
        tenant.current_period_end,
        p_due_date::timestamptz,
        p_paid_at,
        pg_catalog.now()
      ),
      coalesce(p_due_date::timestamptz, p_paid_at, pg_catalog.now())
    );
    period_end := CASE
      WHEN checkout.billing_cycle = 'YEARLY'
        THEN period_anchor + interval '1 year'
      ELSE period_anchor + interval '1 month'
    END;

    INSERT INTO public.saas_invoices (
      tenant_id,
      amount,
      status,
      due_date,
      paid_at,
      asaas_payment_id,
      invoice_number,
      plan_snapshot,
      billing_period_start,
      billing_period_end,
      period_month
    ) VALUES (
      checkout.tenant_id,
      checkout.amount,
      'PAID',
      coalesce(p_due_date::timestamptz, p_paid_at, pg_catalog.now()),
      coalesce(p_paid_at, pg_catalog.now()),
      payment_id,
      'WW-' || to_char(pg_catalog.now(), 'YYYYMM') || '-' || left(md5(payment_id), 8),
      to_jsonb(selected_plan),
      period_anchor::date,
      period_end::date,
      to_char(period_anchor, 'YYYY-MM')
    );
  END IF;

  UPDATE public.tenants
  SET saas_status = 'active',
      current_period_end = greatest(
        coalesce(current_period_end, period_end),
        period_end
      )
  WHERE id = checkout.tenant_id;

  UPDATE public.saas_checkout_intents
  SET status = 'PROVISIONED',
      asaas_payment_id = payment_id,
      invoice_url = coalesce(p_invoice_url, invoice_url),
      bank_slip_url = coalesce(p_bank_slip_url, bank_slip_url),
      due_date = coalesce(p_due_date, due_date),
      paid_at = coalesce(p_paid_at, paid_at, pg_catalog.now()),
      last_error = NULL,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'lastBillingEvent', event_name,
        'lastBillingEventAt', pg_catalog.now(),
        'lastPaidPaymentId', payment_id
      ),
      updated_at = pg_catalog.now()
  WHERE id = checkout.id;

  RETURN jsonb_build_object(
    'ok', true,
    'action', CASE
      WHEN existing_invoice.id IS NULL THEN 'RENEWED'
      ELSE 'RESTORED'
    END,
    'checkout_id', checkout.id,
    'tenant_id', checkout.tenant_id,
    'current_period_end', period_end
  );
END;
$$;


--
-- Name: apply_student_response(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_student_response(p_token text, p_response text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return private.apply_attendance_response(
    null,
    p_token,
    p_response,
    null,
    'PUBLIC_TOKEN'
  );
end;
$$;


--
-- Name: apply_teacher_candidate(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_teacher_candidate(p_name text, p_whatsapp text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_link text; v_clean text;
BEGIN
  IF COALESCE(trim(p_name),'') = '' OR length(regexp_replace(COALESCE(p_whatsapp,''),'\D','','g')) < 10 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nome_ou_whatsapp_invalido');
  END IF;
  v_clean := regexp_replace(p_whatsapp, '\D', '', 'g');
  IF NOT EXISTS (SELECT 1 FROM job_applications
                 WHERE regexp_replace(COALESCE(whatsapp,''),'\D','','g') = v_clean
                   AND created_at > now() - interval '30 days') THEN
    INSERT INTO job_applications (tenant_id, name, whatsapp, status, source, notes)
    VALUES ('school-wise-wolf', left(trim(p_name), 120), v_clean, 'Novo', 'ADS', left(p_notes, 600));
  END IF;
  SELECT talent_group_link INTO v_link FROM tenants WHERE id = 'school-wise-wolf';
  RETURN jsonb_build_object('ok', true, 'group_link', v_link);
END; $$;


--
-- Name: apply_teacher_transfer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_teacher_transfer(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  transfer_row public.teacher_transfers%ROWTYPE;
  conflict_count integer;
  student_name text;
  student_phone text;
  target_teacher_name text;
  director_name text;
  director_phone text;
BEGIN
  SELECT transfer.*
  INTO transfer_row
  FROM public.teacher_transfers AS transfer
  WHERE transfer.id = p_id
  FOR UPDATE;

  IF transfer_row.id IS NULL
    OR transfer_row.status <> 'ACCEPTED'
    OR transfer_row.cutover_date > current_date
    OR NOT private.tenant_is_operational(transfer_row.tenant_id)
  THEN
    RETURN;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      transfer_row.tenant_id || ':teacher-transfer:' || transfer_row.to_teacher_id::text,
      0
    )
  );

  IF jsonb_typeof(transfer_row.proposed_slots) IS DISTINCT FROM 'array'
    OR jsonb_array_length(transfer_row.proposed_slots) < 1
    OR jsonb_array_length(transfer_row.proposed_slots) > 14
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(transfer_row.proposed_slots) AS slot
      WHERE jsonb_typeof(slot) IS DISTINCT FROM 'object'
        OR slot->>'day_of_week' NOT IN (
          'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'
        )
        OR coalesce(slot->>'time_slot', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    )
    OR EXISTS (
      SELECT 1
      FROM jsonb_array_elements(transfer_row.proposed_slots) AS slot
      GROUP BY slot->>'day_of_week', slot->>'time_slot'
      HAVING count(*) > 1
    )
  THEN
    RAISE EXCEPTION 'invalid_teacher_transfer_slots' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles AS student
    JOIN public.tenant_memberships AS membership
      ON membership.user_id = student.id
     AND membership.tenant_id = student.tenant_id
     AND membership.role = 'STUDENT'
     AND membership.status = 'ACTIVE'
    WHERE student.id = transfer_row.student_id
      AND student.tenant_id = transfer_row.tenant_id
      AND student.role = 'STUDENT'
      AND lower(trim(coalesce(student.lifecycle_status, ''))) = 'active'
  ) OR NOT EXISTS (
    SELECT 1
    FROM public.profiles AS teacher
    JOIN public.tenant_memberships AS membership
      ON membership.user_id = teacher.id
     AND membership.tenant_id = teacher.tenant_id
     AND membership.role = 'TEACHER'
     AND membership.status = 'ACTIVE'
    WHERE teacher.id = transfer_row.to_teacher_id
      AND teacher.tenant_id = transfer_row.tenant_id
      AND teacher.role = 'TEACHER'
      AND lower(trim(coalesce(teacher.lifecycle_status, ''))) = 'active'
  ) OR (
    transfer_row.from_teacher_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1
      FROM public.profiles AS teacher
      WHERE teacher.id = transfer_row.from_teacher_id
        AND teacher.tenant_id = transfer_row.tenant_id
        AND teacher.role = 'TEACHER'
    )
  ) THEN
    RAISE EXCEPTION 'teacher_transfer_tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  SELECT count(*)
  INTO conflict_count
  FROM jsonb_array_elements(transfer_row.proposed_slots) AS slot
  JOIN public.bookings AS booking
    ON booking.tenant_id = transfer_row.tenant_id
   AND booking.teacher_id = transfer_row.to_teacher_id
   AND booking.day_of_week = slot->>'day_of_week'
   AND booking.time_slot = slot->>'time_slot'
   AND coalesce(booking.status, 'SCHEDULED') = 'SCHEDULED';

  IF conflict_count > 0 THEN
    RAISE EXCEPTION 'teacher_transfer_schedule_conflict' USING ERRCODE = '23505';
  END IF;

  DELETE FROM public.bookings AS booking
  WHERE booking.tenant_id = transfer_row.tenant_id
    AND booking.student_id = transfer_row.student_id
    AND booking.teacher_id = transfer_row.from_teacher_id
    AND booking.day_of_week IS NOT NULL;

  INSERT INTO public.bookings (
    tenant_id,
    teacher_id,
    student_id,
    day_of_week,
    time_slot,
    start_date
  )
  SELECT
    transfer_row.tenant_id,
    transfer_row.to_teacher_id,
    transfer_row.student_id,
    slot->>'day_of_week',
    slot->>'time_slot',
    transfer_row.cutover_date
  FROM jsonb_array_elements(transfer_row.proposed_slots) AS slot;

  UPDATE public.profiles AS student
  SET professor_id = transfer_row.to_teacher_id
  WHERE student.id = transfer_row.student_id
    AND student.tenant_id = transfer_row.tenant_id
    AND student.professor_id IS NOT DISTINCT FROM transfer_row.from_teacher_id;

  UPDATE public.profiles AS student
  SET professor_id2 = transfer_row.to_teacher_id
  WHERE student.id = transfer_row.student_id
    AND student.tenant_id = transfer_row.tenant_id
    AND transfer_row.from_teacher_id IS NOT NULL
    AND student.professor_id2 = transfer_row.from_teacher_id;

  UPDATE public.teacher_transfers
  SET status = 'APPLIED', applied_at = now()
  WHERE id = transfer_row.id
    AND tenant_id = transfer_row.tenant_id
    AND status = 'ACCEPTED';

  SELECT student.full_name, student.phone
  INTO student_name, student_phone
  FROM public.profiles AS student
  WHERE student.id = transfer_row.student_id
    AND student.tenant_id = transfer_row.tenant_id;

  SELECT teacher.full_name
  INTO target_teacher_name
  FROM public.profiles AS teacher
  WHERE teacher.id = transfer_row.to_teacher_id
    AND teacher.tenant_id = transfer_row.tenant_id;

  PERFORM public._enqueue_school_whatsapp(
    transfer_row.tenant_id,
    student_phone,
    student_name,
    'Olá ' || coalesce(student_name, '') || '! Sua aula foi transferida para o(a) professor(a) '
      || coalesce(target_teacher_name, '') || ' a partir de '
      || to_char(transfer_row.cutover_date, 'DD/MM/YYYY')
      || '. Seus valores e acesso continuam os mesmos. 🐺'
  );

  SELECT profile.phone, profile.full_name
  INTO director_phone, director_name
  FROM public.profiles AS profile
  WHERE profile.tenant_id = transfer_row.tenant_id
    AND profile.role IN ('SCHOOL_ADMIN', 'SUPER_ADMIN')
    AND lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
  ORDER BY profile.role DESC
  LIMIT 1;

  PERFORM public._enqueue_school_whatsapp(
    transfer_row.tenant_id,
    director_phone,
    director_name,
    'Transferência aplicada: ' || coalesce(student_name, '') || ' agora é aluno(a) de '
      || coalesce(target_teacher_name, '') || ' (início '
      || to_char(transfer_row.cutover_date, 'DD/MM/YYYY') || ').'
  );
END;
$_$;


--
-- Name: FUNCTION apply_teacher_transfer(p_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_teacher_transfer(p_id uuid) IS 'Internal transfer application with tenant, lifecycle, schedule and cutover revalidation under lock.';


--
-- Name: apply_tenant_admin_settings(text, uuid, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_tenant_admin_settings(p_tenant_id text, p_actor_id uuid, p_expected_version bigint, p_settings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  current_version bigint;
  next_version bigint;
  current_slug text;
  current_domain text;
  current_name text;
  normalized_name text;
  normalized_slug text;
  normalized_branding jsonb;
  normalized_school_info jsonb;
  actor_role text;
BEGIN
  actor_role := private.active_tenant_role(p_actor_id);
  IF p_actor_id IS NULL
    OR actor_role NOT IN ('SCHOOL_ADMIN', 'SUPER_ADMIN')
    OR private.active_tenant_id(p_actor_id) IS DISTINCT FROM p_tenant_id
  THEN
    RAISE EXCEPTION 'cross_tenant_access_denied' USING ERRCODE = '42501';
  END IF;

  IF NOT private.tenant_is_operational(p_tenant_id) THEN
    RAISE EXCEPTION 'tenant_not_operational' USING ERRCODE = '55000';
  END IF;

  IF jsonb_typeof(p_settings) <> 'object'
    OR NOT p_settings ?& ARRAY[
      'name',
      'slug',
      'branding',
      'schoolInfo',
      'whatsappEnabled',
      'financialCutoffDay',
      'locale',
      'timezone',
      'currency',
      'weekStartsOn',
      'defaultLessonDurationMinutes',
      'studentNotificationsEnabled',
      'teacherNotificationsEnabled'
    ]
    OR EXISTS (
      SELECT 1
      FROM jsonb_object_keys(p_settings) AS supplied(key)
      WHERE supplied.key NOT IN (
        'name',
        'slug',
        'branding',
        'schoolInfo',
        'whatsappEnabled',
        'financialCutoffDay',
        'locale',
        'timezone',
        'currency',
        'weekStartsOn',
        'defaultLessonDurationMinutes',
        'studentNotificationsEnabled',
        'teacherNotificationsEnabled'
      )
    )
  THEN
    RAISE EXCEPTION 'invalid_settings_payload' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.tenant_admin_settings (tenant_id)
  VALUES (p_tenant_id)
  ON CONFLICT (tenant_id) DO NOTHING;

  SELECT settings.version
  INTO current_version
  FROM public.tenant_admin_settings AS settings
  WHERE settings.tenant_id = p_tenant_id
  FOR UPDATE;

  IF current_version IS NULL THEN
    RAISE EXCEPTION 'tenant_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF p_expected_version IS DISTINCT FROM current_version THEN
    RAISE EXCEPTION 'settings_version_conflict' USING ERRCODE = '40001';
  END IF;

  normalized_name := trim(p_settings ->> 'name');
  normalized_slug := lower(trim(coalesce(p_settings ->> 'slug', '')));

  -- Look up existing tenant attributes for safe fallback
  SELECT tenant.slug, tenant.domain, tenant.name
  INTO current_slug, current_domain, current_name
  FROM public.tenants AS tenant
  WHERE tenant.id = p_tenant_id;

  -- Safe fallback to current tenant slug if not provided or empty
  IF normalized_slug = '' THEN
    normalized_slug := lower(trim(coalesce(current_slug, '')));
  END IF;
  -- If still empty, derive a clean valid slug from domain, name, or tenant_id
  IF normalized_slug = '' THEN
    normalized_slug := lower(regexp_replace(regexp_replace(coalesce(current_domain, current_name, p_tenant_id, 'escola'), '[^a-z0-9]+', '-', 'g'), '^-+|-+$', '', 'g'));
    IF length(normalized_slug) < 3 THEN
      normalized_slug := substring(normalized_slug || '-escola' from 1 for 40);
    ELSE
      normalized_slug := substring(normalized_slug from 1 for 40);
    END IF;
  END IF;

  normalized_branding := p_settings -> 'branding';
  normalized_school_info := p_settings -> 'schoolInfo';

  IF coalesce(length(normalized_name), 0) NOT BETWEEN 2 AND 120
    OR coalesce(length(normalized_slug), 0) NOT BETWEEN 3 AND 40
    OR coalesce(normalized_slug !~ '^[a-z0-9](?:[a-z0-9-]*[a-z0-9])$', true)
    OR jsonb_typeof(normalized_branding) <> 'object'
    OR NOT normalized_branding ?& ARRAY[
      'primaryColor',
      'secondaryColor',
      'logoPath',
      'faviconPath',
      'logoUrl',
      'faviconUrl'
    ]
    OR coalesce(
      normalized_branding ->> 'primaryColor' !~ '^#[0-9A-Fa-f]{6}$',
      true
    )
    OR coalesce(
      normalized_branding ->> 'secondaryColor' !~ '^#[0-9A-Fa-f]{6}$',
      true
    )
    OR pg_column_size(normalized_branding) > 16384
    OR (
      normalized_school_info IS DISTINCT FROM 'null'::jsonb
      AND (
        jsonb_typeof(normalized_school_info) <> 'object'
        OR pg_column_size(normalized_school_info) > 16384
      )
    )
    OR (p_settings ->> 'financialCutoffDay')::integer NOT BETWEEN 1 AND 28
    OR p_settings ->> 'locale' !~ '^[a-z]{2}(?:-[A-Z]{2})?$'
    OR length(p_settings ->> 'timezone') NOT BETWEEN 3 AND 64
    OR p_settings ->> 'currency' !~ '^[A-Z]{3}$'
    OR (p_settings ->> 'weekStartsOn')::integer NOT BETWEEN 0 AND 6
    OR (p_settings ->> 'defaultLessonDurationMinutes')::integer NOT BETWEEN 15 AND 240
  THEN
    RAISE EXCEPTION 'invalid_settings_values' USING ERRCODE = '22023';
  END IF;

  UPDATE public.tenants AS tenant
  SET name = normalized_name,
      slug = normalized_slug,
      domain = normalized_slug || '.wisewolflanguage.com.br',
      branding = normalized_branding,
      school_info = CASE
        WHEN normalized_school_info = 'null'::jsonb THEN NULL
        ELSE normalized_school_info
      END,
      whatsapp_enabled = (p_settings ->> 'whatsappEnabled')::boolean,
      financial_cutoff_day = (p_settings ->> 'financialCutoffDay')::integer
  WHERE tenant.id = p_tenant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant_not_found' USING ERRCODE = 'P0002';
  END IF;

  next_version := current_version + 1;
  UPDATE public.tenant_admin_settings AS settings
  SET version = next_version,
      locale = p_settings ->> 'locale',
      timezone = p_settings ->> 'timezone',
      currency = p_settings ->> 'currency',
      week_starts_on = (p_settings ->> 'weekStartsOn')::smallint,
      default_lesson_duration_minutes =
        (p_settings ->> 'defaultLessonDurationMinutes')::smallint,
      student_notifications_enabled =
        (p_settings ->> 'studentNotificationsEnabled')::boolean,
      teacher_notifications_enabled =
        (p_settings ->> 'teacherNotificationsEnabled')::boolean,
      updated_at = now(),
      updated_by = p_actor_id
  WHERE settings.tenant_id = p_tenant_id;

  INSERT INTO public.tenant_configuration_audit (
    tenant_id,
    actor_id,
    actor_role,
    action,
    section,
    changes
  )
  VALUES (
    p_tenant_id,
    p_actor_id,
    actor_role,
    'settings_published',
    'school',
    jsonb_build_object(
      'version', next_version,
      'sections', jsonb_build_array(
        'identity', 'branding', 'operations', 'communications'
      )
    )
  );

  RETURN jsonb_build_object('ok', true, 'version', next_version);
END;
$_$;


--
-- Name: apply_verified_unsettled_asaas_payment_deletion(text, uuid, uuid, text, text, text, timestamp with time zone, integer, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_verified_unsettled_asaas_payment_deletion(p_provider_event_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_expected_provider_subscription_id text, p_event_created_at timestamp with time zone, p_event_rank integer, p_payload jsonb, p_authoritative_payment jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_event_id text := nullif(pg_catalog.btrim(coalesce(p_provider_event_id, '')), '');
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_expected_tenant_id, '')), '');
  normalized_customer text := nullif(pg_catalog.btrim(coalesce(p_expected_provider_customer_id, '')), '');
  normalized_subscription text := nullif(pg_catalog.btrim(coalesce(p_expected_provider_subscription_id, '')), '');
  inbox_row public.asaas_webhook_inbox%rowtype;
  payment_row public.student_payments%rowtype;
  profile_row public.profiles%rowtype;
  event_payment_id text;
  event_customer_id text;
  event_subscription_id text;
  event_reference text;
  event_status text;
  event_value numeric;
  event_due_date date;
  authoritative_payment_id text;
  authoritative_customer_id text;
  authoritative_subscription_id text;
  authoritative_reference text;
  authoritative_status text;
  authoritative_value numeric;
  authoritative_due_date date;
  payment_binding_count integer;
  provider_profile_count integer;
  previous_status text;
begin
  if normalized_event_id is null
     or pg_catalog.length(normalized_event_id) > 240
     or p_expected_local_payment_id is null
     or p_expected_student_id is null
     or normalized_tenant is null
     or normalized_customer is null
     or normalized_subscription is null
     or pg_catalog.length(normalized_customer) > 240
     or pg_catalog.length(normalized_subscription) > 240
     or p_event_created_at is null
     or p_event_rank is distinct from 100
     or p_payload is null
     or pg_catalog.jsonb_typeof(p_payload) <> 'object'
     or p_authoritative_payment is null
     or pg_catalog.jsonb_typeof(p_authoritative_payment) <> 'object'
  then
    raise exception using
      errcode = '22023',
      message = 'deleted_payment_arguments_invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' ||
        p_expected_student_id::text,
      0
    )
  );

  select inbox.*
    into inbox_row
    from public.asaas_webhook_inbox as inbox
   where inbox.provider_event_id = normalized_event_id
   for update;

  if not found
     or inbox_row.status <> 'PROCESSING'
     or inbox_row.lease_owner is null
     or inbox_row.lease_expires_at is null
     or inbox_row.lease_expires_at <= pg_catalog.now()
     or inbox_row.event_name <> 'PAYMENT_DELETED'
     or inbox_row.event_created_at is distinct from p_event_created_at
     or inbox_row.payload is distinct from p_payload
     or nullif(pg_catalog.btrim(inbox_row.payload_hash), '') is null
     or nullif(pg_catalog.btrim(p_payload ->> 'id'), '')
          is distinct from normalized_event_id
     or upper(pg_catalog.btrim(coalesce(p_payload ->> 'event', ''))) <>
       'PAYMENT_DELETED'
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'deleted_payment_trusted_webhook_evidence_missing'
    );
  end if;

  event_payment_id := nullif(pg_catalog.btrim(p_payload #>> '{payment,id}'), '');
  event_customer_id := nullif(pg_catalog.btrim(p_payload #>> '{payment,customer}'), '');
  event_subscription_id := nullif(pg_catalog.btrim(p_payload #>> '{payment,subscription}'), '');
  event_reference := nullif(pg_catalog.btrim(p_payload #>> '{payment,externalReference}'), '');
  event_status := upper(nullif(pg_catalog.btrim(p_payload #>> '{payment,status}'), ''));
  authoritative_payment_id := nullif(pg_catalog.btrim(p_authoritative_payment ->> 'id'), '');
  authoritative_customer_id := nullif(pg_catalog.btrim(p_authoritative_payment ->> 'customer'), '');
  authoritative_subscription_id := nullif(pg_catalog.btrim(p_authoritative_payment ->> 'subscription'), '');
  authoritative_reference := nullif(pg_catalog.btrim(p_authoritative_payment ->> 'externalReference'), '');
  authoritative_status := upper(nullif(pg_catalog.btrim(p_authoritative_payment ->> 'status'), ''));

  begin
    event_value := (p_payload #>> '{payment,value}')::numeric;
    event_due_date := (p_payload #>> '{payment,dueDate}')::date;
    authoritative_value := (p_authoritative_payment ->> 'value')::numeric;
    authoritative_due_date := (p_authoritative_payment ->> 'dueDate')::date;
  exception
    when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'deleted_payment_provider_evidence_invalid'
      );
  end;

  if event_payment_id is distinct from inbox_row.provider_entity_id
     or event_customer_id is distinct from normalized_customer
     or event_subscription_id is distinct from normalized_subscription
     or event_status is null
     or authoritative_payment_id is distinct from event_payment_id
     or authoritative_customer_id is distinct from event_customer_id
     or authoritative_subscription_id is distinct from event_subscription_id
     or authoritative_reference is distinct from event_reference
     or authoritative_status is distinct from event_status
     or not (p_authoritative_payment @> '{"deleted":true}'::jsonb)
     or nullif(pg_catalog.btrim(p_authoritative_payment ->> 'creditDate'), '') is not null
     or event_value is null
     or event_value::text in ('NaN', 'Infinity', '-Infinity')
     or event_value <= 0
     or authoritative_value is null
     or authoritative_value::text in ('NaN', 'Infinity', '-Infinity')
     or authoritative_value <= 0
     or pg_catalog.round(authoritative_value, 2)
          is distinct from pg_catalog.round(event_value, 2)
     or event_due_date is null
     or authoritative_due_date is distinct from event_due_date
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'deleted_payment_provider_evidence_mismatch'
    );
  end if;

  select pg_catalog.count(*)::integer
    into payment_binding_count
    from public.student_payments as payment
   where nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') = event_payment_id
      or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') = event_payment_id;
  if payment_binding_count <> 1 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'deleted_payment_local_binding_not_unique'
    );
  end if;

  select payment.*
    into payment_row
    from public.student_payments as payment
   where payment.id = p_expected_local_payment_id
     and (
       nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') = event_payment_id
       or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') = event_payment_id
     )
   for update;
  if not found
     or payment_row.student_id is distinct from p_expected_student_id
     or payment_row.tenant_id is distinct from normalized_tenant
     or (
       nullif(pg_catalog.btrim(coalesce(payment_row.provider_customer_id, '')), '') is not null
       and nullif(pg_catalog.btrim(payment_row.provider_customer_id), '')
         is distinct from normalized_customer
     )
     or pg_catalog.round(coalesce(payment_row.value, 0), 2)
          is distinct from pg_catalog.round(event_value, 2)
     or (
       payment_row.amount_cents is not null
       and payment_row.amount_cents is distinct from
         pg_catalog.round(event_value * 100)::integer
     )
     or payment_row.due_date is distinct from event_due_date
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'deleted_payment_local_binding_mismatch'
    );
  end if;

  select profile.*
    into profile_row
    from public.profiles as profile
   where profile.id = p_expected_student_id
     and profile.tenant_id = normalized_tenant
     and profile.role = 'STUDENT'
     and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) in (
       'active', 'suspended', 'offboarded'
     )
     and coalesce(profile.is_test_account, false) is false
     and nullif(pg_catalog.btrim(coalesce(profile.asaas_customer_id, '')), '') =
       normalized_customer
     and nullif(pg_catalog.btrim(coalesce(profile.subscription_id, '')), '') =
       normalized_subscription
   for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'deleted_payment_student_scope_not_corroborated'
    );
  end if;

  select pg_catalog.count(*)::integer
    into provider_profile_count
    from public.profiles as profile
   where profile.role = 'STUDENT'
     and (
       nullif(pg_catalog.btrim(coalesce(profile.asaas_customer_id, '')), '') =
         normalized_customer
       or nullif(pg_catalog.btrim(coalesce(profile.subscription_id, '')), '') =
         normalized_subscription
     );
  if provider_profile_count <> 1 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'deleted_payment_provider_profile_not_unique'
    );
  end if;
  if (
    select pg_catalog.count(*)
      from public.tenant_memberships as membership
     where membership.user_id = p_expected_student_id
  ) <> 1
     or not exists (
       select 1
         from public.tenant_memberships as membership
        where membership.user_id = p_expected_student_id
          and membership.tenant_id = normalized_tenant
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'deleted_payment_membership_not_corroborated'
    );
  end if;

  if nullif(pg_catalog.btrim(coalesce(payment_row.last_provider_event_id, '')), '')
       is not distinct from normalized_event_id
     and upper(pg_catalog.btrim(coalesce(payment_row.status, ''))) = 'CANCELLED'
     and upper(pg_catalog.btrim(coalesce(payment_row.provider_status, ''))) = 'DELETED'
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'REPLAY',
      'id', payment_row.id,
      'due_date', payment_row.due_date,
      'previous_status', payment_row.status
    );
  end if;
  if payment_row.last_provider_event_at is not null and (
    p_event_created_at < payment_row.last_provider_event_at
    or (
      p_event_created_at = payment_row.last_provider_event_at
      and p_event_rank <= coalesce(payment_row.last_provider_event_rank, 0)
    )
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'IGNORED',
      'id', payment_row.id,
      'due_date', payment_row.due_date,
      'previous_status', payment_row.status
    );
  end if;

  previous_status := upper(pg_catalog.btrim(coalesce(payment_row.status, '')));
  if previous_status not in ('PENDING', 'OVERDUE', 'CONFIRMED')
     or upper(pg_catalog.btrim(coalesce(payment_row.provider_status, ''))) in (
       'RECEIVED', 'RECEIVED_IN_CASH', 'PAGO', 'REFUNDED'
     )
     or payment_row.credited_at is not null
     or payment_row.paid_at is not null
     or coalesce(payment_row.refunded_amount, 0) <> 0
     or coalesce(payment_row.ledger_entry_created, false)
     or exists (
       select 1
         from public.financial_transactions as financial_transaction
        where financial_transaction.student_payment_id = payment_row.id
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'deleted_payment_not_proven_unsettled'
    );
  end if;

  update public.student_payments as payment
     set status = 'CANCELLED',
         provider_status = 'DELETED',
         raw_payload = p_payload,
         last_provider_event_id = normalized_event_id,
         last_provider_event_at = p_event_created_at,
         last_provider_event_rank = p_event_rank,
         updated_at = pg_catalog.clock_timestamp()
   where payment.id = payment_row.id
   returning payment.* into payment_row;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'CANCELLED',
    'id', payment_row.id,
    'due_date', payment_row.due_date,
    'previous_status', previous_status,
    'provider_reason', 'provider_deleted'
  );
end;
$$;


--
-- Name: apply_verified_wolfie_topup_payment(uuid, text, text, numeric, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_verified_wolfie_topup_payment(p_order_id uuid, p_payment_id text, p_event text, p_amount_brl numeric, p_refunded_amount_brl numeric, p_provider_customer_id text, p_external_reference text, p_billing_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_order public.wolfie_topup_orders%rowtype;
  v_payment_id text := nullif(pg_catalog.btrim(p_payment_id), '');
  v_customer_id text := nullif(
    pg_catalog.btrim(p_provider_customer_id),
    ''
  );
  v_reference text := nullif(pg_catalog.btrim(p_external_reference), '');
  v_expected_reference text;
begin
  if p_order_id is null
     or v_payment_id is null
     or pg_catalog.char_length(v_payment_id) > 200
     or v_customer_id is null
     or pg_catalog.char_length(v_customer_id) > 200
     or v_reference is null
     or pg_catalog.upper(pg_catalog.btrim(coalesce(p_billing_type, '')))
       <> 'PIX'
  then
    raise exception 'invalid_verified_wolfie_topup_identity';
  end if;

  select orders.*
    into v_order
    from public.wolfie_topup_orders as orders
   where orders.id = p_order_id
   for update;
  if not found then
    raise exception 'wolfie_topup_order_not_found';
  end if;

  v_expected_reference := 'wolfie-topup-order:' || v_order.id::text;
  if v_order.provider_customer_id is null
     or pg_catalog.btrim(v_order.provider_customer_id) <> v_customer_id
     or v_reference <> v_expected_reference
     or pg_catalog.round(v_order.amount_brl, 2)
       is distinct from pg_catalog.round(p_amount_brl, 2)
  then
    raise exception 'wolfie_topup_provider_identity_mismatch';
  end if;

  if v_order.provider_payment_id is not null then
    if pg_catalog.btrim(v_order.provider_payment_id) <> v_payment_id then
      raise exception 'wolfie_topup_payment_mismatch';
    end if;
  elsif not exists (
    select 1
      from public.asaas_provider_creation_attempts as attempt
     where attempt.tenant_id = v_order.tenant_id
       and attempt.operation = 'PAYMENT_CREATE'
       and attempt.logical_key = v_order.id::text
       and attempt.external_reference = v_expected_reference
       and attempt.status = 'SUCCEEDED'
       and pg_catalog.btrim(attempt.provider_entity_id) = v_payment_id
  ) then
    raise exception 'wolfie_topup_provider_creation_unproven';
  end if;

  return public.apply_wolfie_topup_payment(
    p_order_id,
    v_payment_id,
    p_event,
    p_amount_brl,
    p_refunded_amount_brl
  );
end;
$$;


--
-- Name: FUNCTION apply_verified_wolfie_topup_payment(p_order_id uuid, p_payment_id text, p_event text, p_amount_brl numeric, p_refunded_amount_brl numeric, p_provider_customer_id text, p_external_reference text, p_billing_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_verified_wolfie_topup_payment(p_order_id uuid, p_payment_id text, p_event text, p_amount_brl numeric, p_refunded_amount_brl numeric, p_provider_customer_id text, p_external_reference text, p_billing_type text) IS 'Credits or reverses a top-up only after exact customer/reference/type/value proof and an existing local payment link or durable successful creation claim.';


--
-- Name: apply_wolfie_repertoire_event(uuid, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_wolfie_repertoire_event(p_session_id uuid, p_term_key text, p_term text, p_translation text, p_definition_pt text, p_example_sentence text, p_event_type text, p_event_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session public.wolfie_activity_sessions%rowtype;
  v_event_id uuid;
  v_repertoire_id uuid;
  v_term_key text;
  v_delta integer;
  v_mastery integer;
  v_review_days integer;
begin
  v_term_key := pg_catalog.left(
    pg_catalog.btrim(pg_catalog.lower(coalesce(p_term_key, ''))),
    160
  );
  if v_term_key = ''
     or pg_catalog.btrim(coalesce(p_term, '')) = ''
     or pg_catalog.char_length(coalesce(p_event_key, '')) not between 1 and 300
     or p_event_type not in (
       'EXPOSED',
       'ANSWERED_CORRECTLY',
       'ANSWERED_INCORRECTLY',
       'USED_WITH_GUIDANCE',
       'USED_INDEPENDENTLY',
       'PRONOUNCED_SUCCESSFULLY'
     ) then
    raise exception 'invalid_repertoire_event';
  end if;

  select session.*
    into v_session
    from public.wolfie_activity_sessions as session
   where session.id = p_session_id;
  if not found then
    raise exception 'wolfie_session_not_found';
  end if;

  insert into public.wolfie_learning_events (
    tenant_id,
    student_id,
    session_id,
    event_type,
    subject,
    cefr_level,
    event_key,
    metadata,
    test_fixture
  ) values (
    v_session.tenant_id,
    v_session.student_id,
    v_session.id,
    p_event_type,
    v_session.subject,
    v_session.cefr_level,
    p_event_key,
    pg_catalog.jsonb_build_object(
      'term', pg_catalog.left(pg_catalog.btrim(p_term), 120),
      'phase', v_session.phase
    ),
    v_session.test_fixture
  )
  on conflict (tenant_id, student_id, event_key)
    where event_key is not null
    do nothing
  returning id into v_event_id;

  if v_event_id is null then
    return pg_catalog.jsonb_build_object(
      'applied', false,
      'eventKey', p_event_key
    );
  end if;

  v_delta := case p_event_type
    when 'ANSWERED_CORRECTLY' then 12
    when 'ANSWERED_INCORRECTLY' then -8
    when 'USED_INDEPENDENTLY' then 18
    when 'PRONOUNCED_SUCCESSFULLY' then 15
    when 'USED_WITH_GUIDANCE' then 7
    else 2
  end;

  insert into public.wolfie_repertoire (
    tenant_id,
    student_id,
    term_key,
    term,
    translation,
    definition_pt,
    example_sentence,
    cefr_level,
    source_subject,
    source_session_id,
    sector,
    mastery_score,
    exposure_count,
    correct_count,
    incorrect_count,
    independent_use_count,
    pronunciation_success_count,
    last_seen_at,
    next_review_at
  ) values (
    v_session.tenant_id,
    v_session.student_id,
    v_term_key,
    pg_catalog.left(pg_catalog.btrim(p_term), 120),
    nullif(pg_catalog.left(pg_catalog.btrim(p_translation), 240), ''),
    nullif(pg_catalog.left(pg_catalog.btrim(p_definition_pt), 500), ''),
    nullif(pg_catalog.left(pg_catalog.btrim(p_example_sentence), 500), ''),
    v_session.cefr_level,
    v_session.subject,
    v_session.id,
    v_session.sector,
    greatest(0, least(100, v_delta)),
    1,
    case when p_event_type = 'ANSWERED_CORRECTLY' then 1 else 0 end,
    case when p_event_type = 'ANSWERED_INCORRECTLY' then 1 else 0 end,
    case when p_event_type = 'USED_INDEPENDENTLY' then 1 else 0 end,
    case when p_event_type = 'PRONOUNCED_SUCCESSFULLY' then 1 else 0 end,
    pg_catalog.now(),
    pg_catalog.now()
  )
  on conflict (tenant_id, student_id, term_key) do update
    set term = excluded.term,
        translation = coalesce(
          excluded.translation,
          public.wolfie_repertoire.translation
        ),
        definition_pt = coalesce(
          excluded.definition_pt,
          public.wolfie_repertoire.definition_pt
        ),
        example_sentence = coalesce(
          excluded.example_sentence,
          public.wolfie_repertoire.example_sentence
        ),
        cefr_level = excluded.cefr_level,
        source_subject = excluded.source_subject,
        source_session_id = excluded.source_session_id,
        sector = excluded.sector,
        mastery_score = greatest(
          0,
          least(100, public.wolfie_repertoire.mastery_score + v_delta)
        ),
        exposure_count = public.wolfie_repertoire.exposure_count + 1,
        correct_count = public.wolfie_repertoire.correct_count
          + case when p_event_type = 'ANSWERED_CORRECTLY' then 1 else 0 end,
        incorrect_count = public.wolfie_repertoire.incorrect_count
          + case when p_event_type = 'ANSWERED_INCORRECTLY' then 1 else 0 end,
        independent_use_count =
          public.wolfie_repertoire.independent_use_count
          + case when p_event_type = 'USED_INDEPENDENTLY' then 1 else 0 end,
        pronunciation_success_count =
          public.wolfie_repertoire.pronunciation_success_count
          + case
              when p_event_type = 'PRONOUNCED_SUCCESSFULLY' then 1
              else 0
            end,
        last_seen_at = pg_catalog.now(),
        updated_at = pg_catalog.now()
  returning id, mastery_score into v_repertoire_id, v_mastery;

  v_review_days := case
    when v_mastery >= 85 then 21
    when v_mastery >= 65 then 10
    when v_mastery >= 40 then 5
    else 2
  end;

  update public.wolfie_repertoire
     set next_review_at = pg_catalog.now()
       + pg_catalog.make_interval(days => v_review_days)
   where id = v_repertoire_id;

  update public.wolfie_learning_events
     set repertoire_id = v_repertoire_id
   where id = v_event_id;

  return pg_catalog.jsonb_build_object(
    'applied', true,
    'eventKey', p_event_key,
    'repertoireId', v_repertoire_id,
    'masteryScore', v_mastery
  );
end;
$$;


--
-- Name: apply_wolfie_topup_payment(uuid, text, text, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_wolfie_topup_payment(p_order_id uuid, p_payment_id text, p_event text, p_amount_brl numeric, p_refunded_amount_brl numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_order public.wolfie_topup_orders%rowtype;
  v_event_name text := pg_catalog.upper(
    pg_catalog.btrim(coalesce(p_event, ''))
  );
  v_payment_id text := nullif(pg_catalog.btrim(p_payment_id), '');
  v_is_paid boolean := v_event_name in (
    'PAYMENT_RECEIVED',
    'PAYMENT_RECEIVED_IN_CASH'
  );
  v_is_reversal boolean := v_event_name in (
    'PAYMENT_DELETED',
    'PAYMENT_REFUNDED',
    'PAYMENT_CHARGEBACK_REQUESTED',
    'PAYMENT_RECEIVED_IN_CASH_UNDONE'
  );
  v_is_freeze boolean := v_event_name in (
    'PAYMENT_PARTIALLY_REFUNDED',
    'PAYMENT_REFUND_IN_PROGRESS'
  );
begin
  if p_order_id is null
     or v_payment_id is null
     or pg_catalog.char_length(v_payment_id) > 200
     or v_event_name = ''
     or (not v_is_paid and not v_is_reversal and not v_is_freeze)
     or p_amount_brl is null
     or (
       p_refunded_amount_brl is not null
       and p_refunded_amount_brl < 0
     ) then
    raise exception 'invalid_wolfie_topup_event';
  end if;

  select *
    into v_order
    from public.wolfie_topup_orders
   where id = p_order_id
   for update;
  if not found then
    raise exception 'wolfie_topup_order_not_found';
  end if;
  if pg_catalog.round(v_order.amount_brl, 2)
       is distinct from pg_catalog.round(p_amount_brl, 2) then
    raise exception 'wolfie_topup_amount_mismatch';
  end if;
  if v_order.provider_payment_id is not null
     and v_order.provider_payment_id <> v_payment_id then
    raise exception 'wolfie_topup_payment_mismatch';
  end if;
  if p_refunded_amount_brl is not null
     and pg_catalog.round(p_refunded_amount_brl, 2)
       > pg_catalog.round(v_order.amount_brl, 2) then
    raise exception 'wolfie_topup_refund_amount_mismatch';
  end if;

  if v_is_freeze then
    update public.student_minute_credits
       set status = 'SUSPENDED',
           reversal_event = v_event_name
     where order_id = v_order.id
       and status = 'PAID';
    update public.wolfie_topup_orders
       set status = 'SUSPENDED',
           provider_payment_id = coalesce(provider_payment_id, v_payment_id),
           reversal_event = v_event_name,
           refunded_amount_brl = coalesce(
             p_refunded_amount_brl,
             refunded_amount_brl
           ),
           reconciliation_required = true,
           updated_at = pg_catalog.now()
     where id = v_order.id
       and status <> 'REVERSED';
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'suspended', true,
      'reconciliationRequired', true,
      'tenantId', v_order.tenant_id,
      'studentId', v_order.student_id
    );
  end if;

  if v_is_reversal then
    update public.student_minute_credits
       set status = 'REVERSED',
           reversed_at = coalesce(reversed_at, pg_catalog.now()),
           reversal_event = v_event_name
     where order_id = v_order.id
       and status <> 'REVERSED';
    update public.wolfie_topup_orders
       set status = 'REVERSED',
           provider_payment_id = coalesce(provider_payment_id, v_payment_id),
           reversed_at = coalesce(reversed_at, pg_catalog.now()),
           reversal_event = v_event_name,
           refunded_amount_brl = coalesce(
             p_refunded_amount_brl,
             refunded_amount_brl,
             amount_brl
           ),
           reconciliation_required = false,
           updated_at = pg_catalog.now()
     where id = v_order.id;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'reversed', true,
      'tenantId', v_order.tenant_id,
      'studentId', v_order.student_id
    );
  end if;

  if v_order.status in (
    'SUSPENDED',
    'REVERSED',
    'RECONCILIATION_REQUIRED'
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'suspended', v_order.status <> 'REVERSED',
      'reversed', v_order.status = 'REVERSED',
      'idempotent', true
    );
  end if;

  insert into public.student_minute_credits (
    tenant_id,
    student_id,
    minutes,
    payment_id,
    order_id,
    status
  ) values (
    v_order.tenant_id,
    v_order.student_id,
    v_order.minutes,
    v_payment_id,
    v_order.id,
    'PAID'
  )
  on conflict (order_id) where order_id is not null do nothing;

  update public.wolfie_topup_orders
     set status = 'PAID',
         provider_payment_id = coalesce(provider_payment_id, v_payment_id),
         paid_at = coalesce(paid_at, pg_catalog.now()),
         creation_lease_expires_at = null,
         updated_at = pg_catalog.now()
   where id = v_order.id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'paid', true,
    'tenantId', v_order.tenant_id,
    'studentId', v_order.student_id,
    'minutes', v_order.minutes
  );
end;
$$;


--
-- Name: FUNCTION apply_wolfie_topup_payment(p_order_id uuid, p_payment_id text, p_event text, p_amount_brl numeric, p_refunded_amount_brl numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.apply_wolfie_topup_payment(p_order_id uuid, p_payment_id text, p_event text, p_amount_brl numeric, p_refunded_amount_brl numeric) IS 'Owner-only implementation for verified top-up events; normalizes formatting and credits only settled receipts.';


--
-- Name: archive_learning_path(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_learning_path(p_path_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_role text;
  v_actor_tenant_id text;
  v_path public.learning_paths%rowtype;
  v_reason text := nullif(pg_catalog.btrim(coalesce(p_reason, '')), '');
  v_archive_nonce uuid := pg_catalog.gen_random_uuid();
  v_previous_archive_path text := pg_catalog.current_setting(
    'app.learning_path_archive_id',
    true
  );
  v_previous_archive_nonce text := pg_catalog.current_setting(
    'app.learning_path_archive_nonce',
    true
  );
begin
  if v_actor_id is null or p_path_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if v_reason is null or pg_catalog.length(v_reason) not between 5 and 500 then
    raise exception using
      errcode = '22023',
      message = 'learning_path_archive_reason_required';
  end if;

  v_actor_role := private.active_tenant_role(v_actor_id);
  v_actor_tenant_id := private.active_tenant_id(v_actor_id);
  if v_actor_role is null
     or v_actor_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    raise exception using
      errcode = '42501',
      message = 'learning_path_archive_not_authorized';
  end if;

  select *
    into v_path
    from public.learning_paths as path
   where path.id = p_path_id
   for update;
  if not found
     or (
       v_actor_role <> 'SUPER_ADMIN'
       and (
         v_path.tenant_id is null
         or v_actor_tenant_id is distinct from v_path.tenant_id
       )
     ) then
    raise exception using
      errcode = '42501',
      message = 'learning_path_archive_not_authorized';
  end if;

  if v_path.active is false then
    return pg_catalog.jsonb_build_object(
      'pathId', p_path_id,
      'active', false,
      'alreadyApplied', true
    );
  end if;

  if exists (
    select 1
      from public.student_path_enrollments as enrollment
     where enrollment.path_id = p_path_id
       and enrollment.status = 'ACTIVE'
       and enrollment.completed_at is null
  ) then
    raise exception using
      errcode = '55000',
      message = 'learning_path_has_active_students';
  end if;

  begin
    insert into private.learning_path_archive_capabilities (
      nonce,
      path_id,
      actor_id,
      backend_pid,
      transaction_id
    ) values (
      v_archive_nonce,
      p_path_id,
      v_actor_id,
      pg_catalog.pg_backend_pid(),
      pg_catalog.txid_current()
    );

    perform pg_catalog.set_config(
      'app.learning_path_archive_id',
      p_path_id::text,
      true
    );
    perform pg_catalog.set_config(
      'app.learning_path_archive_nonce',
      v_archive_nonce::text,
      true
    );

    update public.learning_paths
       set active = false
     where id = p_path_id;

    insert into public.learning_path_archive_audit (
      tenant_id,
      path_id,
      actor_id,
      reason
    ) values (
      v_path.tenant_id,
      p_path_id,
      v_actor_id,
      v_reason
    );

    delete from private.learning_path_archive_capabilities as capability
     where capability.nonce = v_archive_nonce;

    perform pg_catalog.set_config(
      'app.learning_path_archive_id',
      coalesce(v_previous_archive_path, ''),
      true
    );
    perform pg_catalog.set_config(
      'app.learning_path_archive_nonce',
      coalesce(v_previous_archive_nonce, ''),
      true
    );
  exception
    when others then
      delete from private.learning_path_archive_capabilities as capability
       where capability.nonce = v_archive_nonce;
      perform pg_catalog.set_config(
        'app.learning_path_archive_id',
        coalesce(v_previous_archive_path, ''),
        true
      );
      perform pg_catalog.set_config(
        'app.learning_path_archive_nonce',
        coalesce(v_previous_archive_nonce, ''),
        true
      );
      raise;
  end;

  return pg_catalog.jsonb_build_object(
    'pathId', p_path_id,
    'active', false,
    'alreadyApplied', false
  );
end;
$$;


--
-- Name: archive_student(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_student(p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; s_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id=auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;
  SELECT tenant_id INTO s_tenant FROM profiles WHERE id=p_student_id AND role='STUDENT';
  IF s_tenant IS NULL THEN RETURN jsonb_build_object('ok',false,'error','nao_encontrado'); END IF;
  IF v_role='SCHOOL_ADMIN' AND s_tenant<>v_tenant THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;
  UPDATE profiles SET status_financial='ARCHIVED' WHERE id=p_student_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: asaas_reconciliation_attention(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.asaas_reconciliation_attention() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_tenant_id text;
  v_today date := pg_catalog.timezone(
    'America/Sao_Paulo', pg_catalog.now()
  )::date;
  v_latest_run_id uuid;
  v_observed_at timestamptz;
  v_window_start date;
  v_window_end date;
  v_payload jsonb;
begin
  if not private.can_execute_legacy_role_rpc(
    array['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) then
    return '{}'::jsonb;
  end if;
  v_tenant_id := private.active_tenant_id((select auth.uid()));
  if v_tenant_id is null then
    return '{}'::jsonb;
  end if;

  select run.id, run.finished_at, run.window_start, run.window_end
    into v_latest_run_id, v_observed_at, v_window_start, v_window_end
    from public.asaas_reconciliation_runs as run
   where run.status = 'COMPLETED'
     and run.metrics ->> 'tenantId' = v_tenant_id
     and run.window_end - run.window_start >= 44
     and run.window_start <= v_today - 45
     and run.window_end >= v_today - 1
     and run.finished_at >= pg_catalog.now() - interval '36 hours'
   order by run.finished_at desc nulls last, run.started_at desc
   limit 1;

  with unlinked_current as (
    select
      coalesce(
        nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), ''),
        nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '')
      ) as provider_entity_id,
      payment.id::text as local_entity_id,
      'PAYMENT_TENANT_OR_STUDENT_UNRESOLVED'::text as kind,
      case
        when upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
          'RECEIVED', 'RECEIVED_IN_CASH'
        ) then 'HIGH'::text
        else 'CRITICAL'::text
      end as severity,
      payment.value,
      payment.due_date,
      payment.status,
      'Sem aluno vinculado'::text as student_name,
      payment.updated_at as observed_at
    from public.student_payments as payment
    where payment.tenant_id = v_tenant_id
      and payment.student_id is null
      and upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
        'PENDING', 'OVERDUE', 'CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH'
      )
  ),
  run_attention as (
    select
      issue.provider_entity_id,
      issue.local_entity_id,
      issue.kind,
      issue.severity,
      coalesce(
        payment.value,
        case
          when coalesce(issue.details ->> 'value', '') ~ '^-?[0-9]+(\.[0-9]+)?$'
            then (issue.details ->> 'value')::numeric
          else null
        end
      ) as value,
      coalesce(
        payment.due_date,
        case
          when coalesce(issue.details ->> 'dueDate', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
            then (issue.details ->> 'dueDate')::date
          else null
        end
      ) as due_date,
      coalesce(payment.status, issue.details ->> 'providerStatus') as status,
      coalesce(
        nullif(pg_catalog.btrim(coalesce(student.full_name, '')), ''),
        'Sem aluno vinculado'
      ) as student_name,
      issue.observed_at
    from public.asaas_reconciliation_issues as issue
    left join public.student_payments as payment
      on payment.id::text = issue.local_entity_id
     and payment.tenant_id = v_tenant_id
    left join public.profiles as student
      on student.id = payment.student_id
     and student.tenant_id = payment.tenant_id
    where issue.run_id = v_latest_run_id
      and issue.tenant_id = v_tenant_id
      and issue.resolved_at is null
      and issue.severity in ('HIGH', 'CRITICAL')
      and issue.kind <> 'PAYMENT_TENANT_OR_STUDENT_UNRESOLVED'
  ),
  combined_attention as (
    select * from unlinked_current
    union all
    select * from run_attention
  ),
  current_attention as (
    select distinct on (
      coalesce(provider_entity_id, local_entity_id, kind)
    )
      provider_entity_id, local_entity_id, kind, severity, value, due_date,
      status, student_name, observed_at
    from combined_attention
    order by
      coalesce(provider_entity_id, local_entity_id, kind),
      case severity when 'CRITICAL' then 0 else 1 end,
      observed_at desc
  )
  select pg_catalog.jsonb_build_object(
    'run_id', v_latest_run_id,
    'observed_at', v_observed_at,
    'window_start', v_window_start,
    'window_end', v_window_end,
    'audit_available', v_latest_run_id is not null,
    'qtd', pg_catalog.count(*)::integer,
    'total', pg_catalog.round(coalesce(pg_catalog.sum(value), 0), 2),
    'itens', coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'referencia', case
          when provider_entity_id is null then '—'
          else '…' || pg_catalog.right(provider_entity_id, 8)
        end,
        'aluno', student_name,
        'valor', value,
        'vencimento', due_date,
        'status', status,
        'severidade', severity,
        'problema', case kind
          when 'PAYMENT_TENANT_OR_STUDENT_UNRESOLVED'
            then 'Pagamento sem aluno identificado'
          when 'PROVIDER_PAYMENT_DELETED_LOCAL_OPEN'
            then 'Cobrança excluída no Asaas ainda aberta aqui'
          when 'LOCAL_CREDIT_DATE_MISSING'
            then 'Data de crédito ainda não conciliada'
          when 'PAYMENT_STATUS_MISMATCH'
            then 'Situação do pagamento divergente'
          else pg_catalog.replace(kind, '_', ' ')
        end
      ) order by
        case severity when 'CRITICAL' then 0 else 1 end,
        case upper(coalesce(status, ''))
          when 'OVERDUE' then 0
          when 'PENDING' then 1
          when 'CONFIRMED' then 2
          else 3
        end,
        due_date nulls last,
        provider_entity_id
    ), '[]'::jsonb)
  )
  into v_payload
  from current_attention;

  return coalesce(
    v_payload,
    pg_catalog.jsonb_build_object(
      'audit_available', false,
      'qtd', 0, 'total', 0, 'itens', '[]'::jsonb
    )
  );
end;
$_$;


--
-- Name: assign_class_coverage(uuid, uuid, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_class_coverage(p_absence_id uuid, p_booking_id uuid, p_class_date date, p_cover_teacher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_role TEXT;
    v_tenant TEXT;
    v_booking RECORD;
    v_cov_id UUID;
BEGIN
    SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
    IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','TEACHER') THEN RAISE EXCEPTION 'Sem permissão'; END IF;

    SELECT * INTO v_booking FROM bookings WHERE id = p_booking_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Booking não encontrado'; END IF;

    INSERT INTO class_coverages (
        original_teacher_id, cover_teacher_id, student_id, booking_id, absence_id,
        tenant_id, class_date, class_time
    )
    VALUES (
        v_booking.teacher_id, p_cover_teacher_id, v_booking.student_id, p_booking_id, p_absence_id,
        v_booking.tenant_id, p_class_date, v_booking.time_slot
    )
    ON CONFLICT (booking_id, class_date) DO UPDATE SET
        cover_teacher_id = EXCLUDED.cover_teacher_id,
        absence_id = EXCLUDED.absence_id,
        status = 'SCHEDULED'
    RETURNING id INTO v_cov_id;

    RETURN jsonb_build_object('coverage_id', v_cov_id, 'status','SCHEDULED');
END;
$$;


--
-- Name: assign_tenant_plan(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_tenant_plan(p_tenant_id text, p_plan_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT is_super_admin() THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;
  UPDATE tenants SET plan_id = p_plan_id,
    current_period_end = COALESCE(current_period_end, (current_date + interval '1 month'))
  WHERE id = p_tenant_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: assign_wolfie_task(uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_wolfie_task(p_student_id uuid, p_topic text, p_note text DEFAULT NULL::text, p_class_log_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role     text;
  v_tenant   text;
  v_student  record;
  v_id       uuid;
  v_topic    text := left(btrim(COALESCE(p_topic, '')), 120);
BEGIN
  SELECT p.role, p.tenant_id INTO v_role, v_tenant
  FROM public.profiles p WHERE p.id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN
     ('TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') THEN
    RAISE EXCEPTION 'sem_permissao';
  END IF;
  IF v_topic = '' THEN
    RAISE EXCEPTION 'tema_obrigatorio';
  END IF;

  SELECT p.id, p.full_name, p.phone, p.tenant_id, p.status, p.status_financial
    INTO v_student
  FROM public.profiles p
  WHERE p.id = p_student_id AND p.role = 'STUDENT';
  IF v_student.id IS NULL OR v_student.tenant_id <> v_tenant THEN
    RAISE EXCEPTION 'aluno_invalido';
  END IF;

  -- Aluno inativo não recebe automação; a mesma regra do resto do sistema.
  IF NOT public.is_student_notifiable(p_student_id) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'aluno_inativo');
  END IF;

  INSERT INTO public.wolfie_assignments
    (tenant_id, student_id, teacher_id, class_log_id, topic, note)
  VALUES (v_tenant, p_student_id, auth.uid(), p_class_log_id, v_topic,
          left(btrim(COALESCE(p_note, '')), 300))
  ON CONFLICT (student_id, assigned_on)
    WHERE status = 'PENDING' DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'duplicada', true,
                              'reason', 'ja_tem_tarefa_hoje');
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'id', v_id, 'topic', v_topic,
    'student_name', v_student.full_name, 'student_phone', v_student.phone
  );
END;
$$;


--
-- Name: audit_table_trigger(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_table_trigger() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_user_role TEXT;
    v_tenant_id TEXT;
    v_resource_id TEXT;
    v_old JSONB;
    v_new JSONB;
    v_diff JSONB := '{}'::JSONB;
    v_key TEXT;
BEGIN
    SELECT role, tenant_id INTO v_user_role, v_tenant_id FROM profiles WHERE id = v_user_id;

    IF TG_OP = 'DELETE' THEN
        v_old := to_jsonb(OLD);
        v_resource_id := (OLD.id)::TEXT;
        v_tenant_id := COALESCE(v_tenant_id, (v_old->>'tenant_id'));
    ELSIF TG_OP = 'UPDATE' THEN
        v_old := to_jsonb(OLD);
        v_new := to_jsonb(NEW);
        v_resource_id := (NEW.id)::TEXT;
        v_tenant_id := COALESCE(v_tenant_id, (v_new->>'tenant_id'));
        -- compute diff
        FOR v_key IN SELECT jsonb_object_keys(v_new) LOOP
            IF v_new->v_key IS DISTINCT FROM v_old->v_key THEN
                v_diff := v_diff || jsonb_build_object(v_key, jsonb_build_object('old', v_old->v_key, 'new', v_new->v_key));
            END IF;
        END LOOP;
        -- skip se mudou só timestamps automáticos
        IF v_diff = '{}'::JSONB OR (ARRAY(SELECT jsonb_object_keys(v_diff)) <@ ARRAY['updated_at','last_updated_at']::TEXT[]) THEN
            RETURN NEW;
        END IF;
    ELSE -- INSERT
        v_new := to_jsonb(NEW);
        v_resource_id := (NEW.id)::TEXT;
        v_tenant_id := COALESCE(v_tenant_id, (v_new->>'tenant_id'));
    END IF;

    INSERT INTO audit_logs (tenant_id, user_id, user_role, action, resource_type, resource_id, old_values, new_values, diff)
    VALUES (v_tenant_id, v_user_id, v_user_role, TG_OP, TG_TABLE_NAME, v_resource_id, v_old, v_new, v_diff);

    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: authorize_management_payment_notification_submission(uuid, uuid, uuid, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_management_payment_notification_submission(p_attempt_id uuid, p_claim_token uuid, p_integration_id uuid, p_integration_version bigint, p_provider_endpoint_hash text, p_provider_credential_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_outbox public.management_payment_notification_outbox%rowtype;
  v_payment public.student_payments%rowtype;
  v_instance public.whatsapp_instances%rowtype;
  v_connection private.tenant_integration_connections%rowtype;
  v_current_destination text;
  v_current_source_snapshot jsonb;
  v_replacement_kind text;
  v_decrypted_api_key text;
  v_expected_endpoint_hash text;
  v_expected_credential_hash text;
  v_snapshot jsonb;
  v_snapshot_hash text;
  v_endpoint_hash text := lower(pg_catalog.btrim(
    coalesce(p_provider_endpoint_hash, '')
  ));
  v_credential_hash text := lower(pg_catalog.btrim(
    coalesce(p_provider_credential_hash, '')
  ));
begin
  if p_attempt_id is null
     or p_claim_token is null
     or p_integration_id is null
     or coalesce(p_integration_version, 0) <= 0
     or v_endpoint_hash !~ '^[0-9a-f]{64}$'
     or v_credential_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_management_payment_provider_snapshot'
      using errcode = '22023';
  end if;

  select outbox.* into v_outbox
  from public.management_payment_notification_outbox as outbox
  where outbox.id = p_attempt_id;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'prepared_claim_lost'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'management-payment-notification:' || v_outbox.tenant_id || ':' ||
        v_outbox.payment_id::text,
      0
    )
  );

  select payment.* into v_payment
  from public.student_payments as payment
  where payment.id = v_outbox.payment_id
    and payment.tenant_id = v_outbox.tenant_id
  for update;

  select outbox.* into v_outbox
  from public.management_payment_notification_outbox as outbox
  where outbox.id = p_attempt_id
  for update;

  if not found
     or v_outbox.status <> 'PREPARED'
     or v_outbox.claim_token is distinct from p_claim_token
     or v_outbox.lease_expires_at <= pg_catalog.now()
     or v_outbox.submit_attempt_count <> 0 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'prepared_claim_lost'
    );
  end if;

  v_replacement_kind :=
    private.management_payment_notification_replacement_kind(
      v_outbox.tenant_id,
      v_outbox.payment_id
    );
  if v_replacement_kind is not null
     and v_replacement_kind is distinct from v_outbox.notification_kind then
    perform private.requeue_prepared_management_payment_notification(
      v_outbox.id,
      'management_payment_notification_kind_regenerated',
      v_replacement_kind
    );
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'RETRY',
      'status', 'PENDING',
      'notification_kind', v_replacement_kind,
      'reason', 'management_payment_notification_kind_regenerated'
    );
  end if;

  if v_payment.id is null
     or not private.management_payment_notification_scope_active(
       v_outbox.tenant_id,
       v_outbox.payment_id,
       v_outbox.notification_kind
     ) then
    update public.management_payment_notification_outbox
    set status = 'SUPPRESSED',
        lease_expires_at = pg_catalog.now(),
        last_error = 'management_payment_scope_changed_at_provider_fence',
        updated_at = pg_catalog.now()
    where id = v_outbox.id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'status', 'SUPPRESSED',
      'reason', 'management_payment_scope_changed_at_provider_fence'
    );
  end if;

  select private.normalize_management_group_destination(management.destino)
  into v_current_destination
  from public.dre_report_settings as management
  where management.tenant_id = v_outbox.tenant_id
    and management.is_active
  for share;
  if v_current_destination is null
     or v_current_destination is distinct from
       v_outbox.configured_destination_snapshot then
    perform private.requeue_prepared_management_payment_notification(
      v_outbox.id,
      'management_destination_changed_at_provider_fence',
      null
    );
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'management_destination_changed_at_provider_fence'
    );
  end if;

  v_current_source_snapshot :=
    public.management_payment_notification_source_snapshot(
      v_outbox.tenant_id,
      v_outbox.payment_id,
      v_outbox.notification_kind
    );
  if v_current_source_snapshot is null
     or v_current_source_snapshot is distinct from v_outbox.source_snapshot then
    perform private.requeue_prepared_management_payment_notification(
      v_outbox.id,
      'management_payment_source_changed_at_provider_fence',
      null
    );
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'management_payment_source_changed_at_provider_fence'
    );
  end if;

  select instance.* into v_instance
  from public.whatsapp_instances as instance
  where instance.tenant_id = v_outbox.tenant_id
    and lower(instance.instance_name) = lower(v_outbox.provider_instance_name)
    and lower(pg_catalog.btrim(coalesce(instance.status, ''))) in (
      'connected', 'open'
    )
    and instance.inbox_enabled is true
    and instance.webhook_auth_version = 3
    and instance.integration_id = p_integration_id
    and instance.integration_version = p_integration_version
    and exists (
      select 1
      from public.tenant_memberships as membership
      where membership.tenant_id = instance.tenant_id
        and membership.user_id = instance.user_id
        and membership.role = 'SCHOOL_ADMIN'
        and membership.status = 'ACTIVE'
    )
  for share;

  select connection.* into v_connection
  from private.tenant_integration_connections as connection
  where connection.id = p_integration_id
    and connection.id = v_outbox.provider_integration_id
    and connection.tenant_id = v_outbox.tenant_id
    and connection.provider = 'evolution'
    and connection.version = p_integration_version
    and connection.version = v_outbox.provider_integration_version
    and connection.mode <> 'DISABLED'
    and connection.status = 'healthy'
  for share;

  if v_instance.id is null or v_connection.id is null then
    perform private.requeue_prepared_management_payment_notification(
      v_outbox.id,
      'management_provider_binding_changed_at_final_fence',
      null
    );
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'management_provider_binding_changed_at_final_fence'
    );
  end if;

  perform 1
  from public.tenant_memberships as membership
  where membership.tenant_id = v_instance.tenant_id
    and membership.user_id = v_instance.user_id
    and membership.role = 'SCHOOL_ADMIN'
    and membership.status = 'ACTIVE'
  for share;
  if not found then
    perform private.requeue_prepared_management_payment_notification(
      v_outbox.id,
      'management_provider_authority_changed_at_final_fence',
      null
    );
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'management_provider_authority_changed_at_final_fence'
    );
  end if;

  if v_connection.mode = 'TENANT_BYOK' then
    v_expected_endpoint_hash := pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(
          pg_catalog.regexp_replace(
            pg_catalog.btrim(v_connection.connection_config ->> 'baseUrl'),
            '/+$',
            '',
            'g'
          ),
          'UTF8'
        ),
        'sha256'
      ),
      'hex'
    );

    select secret.decrypted_secret
    into v_decrypted_api_key
    from private.tenant_secret_registry as registry
    join vault.decrypted_secrets as secret
      on secret.id = registry.vault_secret_id
    where registry.tenant_id = v_outbox.tenant_id
      and registry.provider = 'evolution'
      and registry.status = 'healthy'
      and registry.last_validated_at is not null
    for share of registry;

    if nullif(pg_catalog.btrim(coalesce(v_decrypted_api_key, '')), '') is null then
      perform private.requeue_prepared_management_payment_notification(
        v_outbox.id,
        'management_provider_credential_unavailable_at_final_fence',
        null
      );
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'RETRY',
        'reason', 'management_provider_credential_unavailable_at_final_fence'
      );
    end if;

    v_expected_credential_hash := pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(pg_catalog.btrim(v_decrypted_api_key), 'UTF8'),
        'sha256'
      ),
      'hex'
    );

    if v_endpoint_hash is distinct from v_expected_endpoint_hash
       or v_credential_hash is distinct from v_expected_credential_hash then
      perform private.requeue_prepared_management_payment_notification(
        v_outbox.id,
        'management_provider_secret_changed_at_final_fence',
        null
      );
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'RETRY',
        'reason', 'management_provider_secret_changed_at_final_fence'
      );
    end if;
  elsif v_connection.mode <> 'PLATFORM_MANAGED' then
    perform private.requeue_prepared_management_payment_notification(
      v_outbox.id,
      'management_provider_mode_invalid_at_final_fence',
      null
    );
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'management_provider_mode_invalid_at_final_fence'
    );
  end if;

  -- One last fresh scope/source check occurs after every provider and
  -- credential lock. No mutable read is permitted between this RPC response
  -- and the single provider POST.
  if not private.management_payment_notification_scope_active(
       v_outbox.tenant_id,
       v_outbox.payment_id,
       v_outbox.notification_kind
     )
     or public.management_payment_notification_source_snapshot(
       v_outbox.tenant_id,
       v_outbox.payment_id,
       v_outbox.notification_kind
     ) is distinct from v_outbox.source_snapshot then
    perform private.requeue_prepared_management_payment_notification(
      v_outbox.id,
      'management_payment_changed_at_last_provider_fence',
      null
    );
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'management_payment_changed_at_last_provider_fence'
    );
  end if;

  v_snapshot := pg_catalog.jsonb_build_object(
    'tenantId', v_outbox.tenant_id,
    'paymentId', v_outbox.payment_id,
    'notificationKind', v_outbox.notification_kind,
    'paymentStatus', upper(pg_catalog.btrim(coalesce(v_payment.status, ''))),
    'paymentValue', v_payment.value,
    'studentId', v_payment.student_id,
    'configuredDestination', v_outbox.configured_destination_snapshot,
    'providerDestination', v_outbox.provider_destination,
    'providerInstanceName', v_outbox.provider_instance_name,
    'integrationId', p_integration_id,
    'integrationVersion', p_integration_version,
    'providerEndpointHash', v_endpoint_hash,
    'providerCredentialHash', v_credential_hash,
    'sourceSnapshotHash', v_outbox.source_snapshot_hash,
    'sourceSnapshot', v_outbox.source_snapshot,
    'messageBody', v_outbox.message_body
  );
  v_snapshot_hash := pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(v_snapshot::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  update public.management_payment_notification_outbox
  set status = 'SUBMITTING',
      submit_attempt_count = 1,
      provider_endpoint_hash = v_endpoint_hash,
      provider_credential_hash = v_credential_hash,
      snapshot_hash = v_snapshot_hash,
      lease_expires_at = pg_catalog.now() + interval '10 minutes',
      last_error = null,
      updated_at = pg_catalog.now()
  where id = v_outbox.id
    and status = 'PREPARED'
    and claim_token = p_claim_token
    and lease_expires_at > pg_catalog.now()
    and submit_attempt_count = 0
  returning * into v_outbox;

  if not found then
    raise exception 'management_payment_provider_submission_transition_failed';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SUBMITTING',
    'status', v_outbox.status,
    'attempt_id', v_outbox.id,
    'notification_kind', v_outbox.notification_kind,
    'provider_destination', v_outbox.provider_destination,
    'provider_instance_name', v_outbox.provider_instance_name,
    'provider_integration_id', v_outbox.provider_integration_id,
    'provider_integration_version', v_outbox.provider_integration_version,
    'provider_endpoint_hash', v_outbox.provider_endpoint_hash,
    'provider_credential_hash', v_outbox.provider_credential_hash,
    'message_body', v_outbox.message_body,
    'source_snapshot_hash', v_outbox.source_snapshot_hash,
    'snapshot_hash', v_outbox.snapshot_hash
  );
end;
$_$;


--
-- Name: award_verified_student_xp(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.award_verified_student_xp(p_source_type text, p_source_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.assert_active_student_learning_mutation();
  return public.award_verified_student_xp_core(
    p_source_type,
    p_source_id
  );
end;
$$;


--
-- Name: award_verified_student_xp_core(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.award_verified_student_xp_core(p_source_type text, p_source_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_student_id uuid := auth.uid();
  v_source_type text := upper(trim(coalesce(p_source_type, '')));
  v_source_id text := trim(coalesce(p_source_id, ''));
  v_source_uuid uuid;
  v_profile record;
  v_existing public.student_verified_xp_awards%rowtype;
  v_base_xp integer;
  v_score smallint;
  v_daily_xp integer;
  v_today date := (now() at time zone 'America/Sao_Paulo')::date;
  v_xp_awarded integer;
  v_new_xp integer;
  v_old_level integer;
  v_new_level integer;
begin
  if v_student_id is null or auth.role() <> 'authenticated' then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if v_source_type not in (
    'CLASS_LOG_CONFIRM'
  ) then
    raise exception using errcode = '22023', message = 'invalid_xp_source_type';
  end if;
  if length(v_source_id) < 1 or length(v_source_id) > 180 then
    raise exception using errcode = '22023', message = 'invalid_xp_source_id';
  end if;

  select
    id,
    tenant_id,
    role,
    current_book_part,
    coalesce(xp, 0) as xp,
    coalesce(level, 1) as level,
    coalesce(daily_xp, 0) as daily_xp,
    daily_xp_date,
    coalesce(is_test_account, false) as is_test_account
    into v_profile
    from public.profiles
   where id = v_student_id
   for update;

  if not found or v_profile.role <> 'STUDENT' or v_profile.tenant_id is null then
    raise exception using errcode = '42501', message = 'student_profile_required';
  end if;

  select *
    into v_existing
    from public.student_verified_xp_awards
   where student_id = v_student_id
     and source_type = v_source_type
     and source_id = v_source_id;

  if found then
    return jsonb_build_object(
      'alreadyAwarded', true,
      'xpEarned', 0,
      'originalXpAwarded', v_existing.xp_awarded,
      'newXP', v_profile.xp,
      'newLevel', v_profile.level,
      'leveledUp', false
    );
  end if;

  if v_source_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    raise exception using errcode = '22023', message = 'invalid_xp_source_id';
  end if;
  v_source_uuid := v_source_id::uuid;

  if not exists (
    select 1
      from public.class_logs
     where id = v_source_uuid
       and student_id = v_student_id
       and tenant_id = v_profile.tenant_id
       and student_confirmed is true
  ) then
    raise exception using errcode = '42501', message = 'xp_source_not_verified';
  end if;
  v_base_xp := 100;
  v_score := 100;

  if v_profile.daily_xp_date is distinct from v_today then
    v_daily_xp := 0;
  else
    v_daily_xp := v_profile.daily_xp;
  end if;

  v_xp_awarded := least(v_base_xp, greatest(0, 250 - v_daily_xp));
  if v_profile.is_test_account then
    v_xp_awarded := 0;
  end if;
  v_old_level := v_profile.level;
  v_new_xp := v_profile.xp + v_xp_awarded;
  v_new_level := floor(v_new_xp / 1000) + 1;

  insert into public.student_verified_xp_awards (
    tenant_id,
    student_id,
    source_type,
    source_id,
    base_xp,
    xp_awarded,
    score_used,
    test_fixture
  ) values (
    v_profile.tenant_id,
    v_student_id,
    v_source_type,
    v_source_id,
    v_base_xp,
    v_xp_awarded,
    v_score,
    v_profile.is_test_account
  );

  update public.profiles
     set xp = v_new_xp,
         level = v_new_level,
         daily_xp = v_daily_xp + v_xp_awarded,
         daily_xp_date = v_today,
         last_activity = now()
   where id = v_student_id;

  return jsonb_build_object(
    'alreadyAwarded', false,
    'xpEarned', v_xp_awarded,
    'newXP', v_new_xp,
    'newLevel', v_new_level,
    'leveledUp', v_new_level > v_old_level
  );
end;
$_$;


--
-- Name: balancete_professores(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.balancete_professores(p_month text DEFAULT NULL::text, p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_jwt_role text; v_caller_role text; v_tenant text; v_month text; v_base numeric;
BEGIN
  v_jwt_role := COALESCE(current_setting('request.jwt.claims', true)::json->>'role', '');
  SELECT role, tenant_id INTO v_caller_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_jwt_role IN ('anon','authenticated') THEN
    IF v_caller_role IS NULL OR v_caller_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
      RAISE EXCEPTION 'Apenas a direção pode ver o balancete';
    END IF;
    IF v_caller_role = 'SUPER_ADMIN' THEN v_tenant := COALESCE(p_tenant, v_tenant); END IF;
  ELSE
    v_tenant := COALESCE(p_tenant, v_tenant);
  END IF;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'Escola não identificada'; END IF;

  v_month := COALESCE(p_month, to_char(current_date,'YYYY-MM'));
  IF v_month !~ '^\d{4}-\d{2}$' THEN RAISE EXCEPTION 'Mês inválido (use YYYY-MM)'; END IF;

  SELECT rate INTO v_base FROM teacher_pay_tiers
   WHERE tenant_id = v_tenant AND min_students = 1;
  v_base := COALESCE(v_base, 0);

  RETURN (
  WITH aulas AS (
    SELECT v.id, v.teacher_id, v.student_id, v.rate_efetivo, v.rate_override, v.subtype
      FROM v_payable_class_logs v
      JOIN profiles t ON t.id = v.teacher_id
     WHERE to_char(v.class_date,'YYYY-MM') = v_month AND t.tenant_id = v_tenant
  ), classificado AS (
    SELECT a.*,
           CASE
             WHEN a.rate_override IS NOT NULL                           THEN 'ajuste'
             WHEN a.subtype = 'TREINAMENTO' AND a.rate_efetivo > v_base THEN 'treinamento'
             WHEN a.rate_efetivo > v_base                               THEN 'turbo'
             ELSE 'base'
           END AS motivo
      FROM aulas a
  ), aulas_aluno_prof AS (
    SELECT c.student_id, c.teacher_id, count(*)::int AS n
      FROM classificado c WHERE c.student_id IS NOT NULL
     GROUP BY 1,2
  ), aulas_aluno AS (
    SELECT ap.student_id, sum(ap.n) AS total FROM aulas_aluno_prof ap GROUP BY 1
  ), receita_aluno AS (
    SELECT sp.student_id, sum(greatest(round(coalesce(sp.value, 0) - coalesce(sp.refunded_amount, 0), 2), 0)) AS receita
      FROM student_payments sp
     WHERE sp.tenant_id = v_tenant
       AND sp.status IN ('RECEIVED','RECEIVED_IN_CASH')
       AND to_char(COALESCE(sp.credited_at, sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM') = v_month
       AND sp.student_id IS NOT NULL
     GROUP BY 1
  ), rateio AS (
    SELECT ap.teacher_id, ap.student_id,
           ra.receita * ap.n / NULLIF(aa.total,0) AS receita
      FROM aulas_aluno_prof ap
      JOIN aulas_aluno   aa ON aa.student_id = ap.student_id
      JOIN receita_aluno ra ON ra.student_id = ap.student_id
  ), rateio_contratado AS (
    -- Mesmo rateio da faturada, para os dois números serem comparáveis.
    SELECT ap.teacher_id, ap.student_id,
           COALESCE(pf.monthly_fee,0) * ap.n / NULLIF(aa.total,0) AS receita
      FROM aulas_aluno_prof ap
      JOIN aulas_aluno aa ON aa.student_id = ap.student_id
      JOIN profiles    pf ON pf.id = ap.student_id
  ), por_aluno AS (
    SELECT c.teacher_id, c.student_id,
           max(COALESCE(sp.full_name,'Aluno não cadastrado')) AS student_name,
           count(*)::int                          AS aulas,
           sum(c.rate_efetivo)                    AS custo,
           count(*) FILTER (WHERE c.motivo = 'turbo')::int AS aulas_turbo,
           COALESCE(max(r.receita), 0)            AS receita,
           COALESCE(max(rc.receita), 0)           AS receita_contratada
      FROM classificado c
      LEFT JOIN profiles sp ON sp.id = c.student_id
      LEFT JOIN rateio   r  ON r.teacher_id = c.teacher_id AND r.student_id = c.student_id
      LEFT JOIN rateio_contratado rc ON rc.teacher_id = c.teacher_id AND rc.student_id = c.student_id
     WHERE c.student_id IS NOT NULL
     GROUP BY c.teacher_id, c.student_id
  ), ajustes AS (
    SELECT ca.teacher_id, sum(ca.amount) AS valor
      FROM closing_adjustments ca
     WHERE ca.tenant_id = v_tenant AND ca.month_year = v_month
     GROUP BY 1
  ), por_prof AS (
    SELECT c.teacher_id,
           count(*)::int                                              AS aulas,
           count(DISTINCT c.student_id) FILTER (WHERE c.student_id IS NOT NULL)::int AS alunos,
           (count(*) * v_base)                                        AS custo_base,
           sum(CASE WHEN c.motivo='turbo'       THEN c.rate_efetivo - v_base ELSE 0 END) AS comissao_turbo,
           sum(CASE WHEN c.motivo='treinamento' THEN c.rate_efetivo - v_base ELSE 0 END) AS bonus_treinamento,
           sum(CASE WHEN c.motivo='ajuste'      THEN c.rate_efetivo - v_base ELSE 0 END) AS ajuste_valor_base,
           count(*) FILTER (WHERE c.motivo='turbo')::int              AS aulas_turbo,
           count(*) FILTER (WHERE c.motivo='treinamento')::int        AS aulas_treinamento,
           count(*) FILTER (WHERE c.motivo='ajuste')::int             AS aulas_ajustadas,
           sum(c.rate_efetivo)                                        AS custo_aulas
      FROM classificado c
     GROUP BY c.teacher_id
  ), consolidado AS (
    SELECT p.*,
           COALESCE(aj.valor, 0)                          AS ajustes_fechamento,
           p.custo_aulas + COALESCE(aj.valor, 0)          AS custo_total,
           COALESCE((SELECT sum(r.receita) FROM rateio r WHERE r.teacher_id = p.teacher_id), 0) AS receita,
           COALESCE((SELECT sum(rc.receita) FROM rateio_contratado rc WHERE rc.teacher_id = p.teacher_id), 0) AS receita_contratada,
           trim(t.full_name)                              AS teacher_name
      FROM por_prof p
      JOIN profiles t   ON t.id = p.teacher_id
      LEFT JOIN ajustes aj ON aj.teacher_id = p.teacher_id
  )
  SELECT jsonb_build_object(
    'month', v_month,
    'base_rate', v_base,
    'como_ler',
      'Para COMPARAR PROFESSORES use lucro_contratado: ele mede o que o professor entregou, sem a interferência de a escola ter conseguido cobrar ou não. Para saber quanto SOBROU no mês use lucro (faturado) — é ele que fecha com o DRE e com o caixa. nao_faturado positivo = mensalidade que não foi cobrada (responsabilidade da secretaria, não do professor); nao_faturado NEGATIVO = o aluno pagou mais que a mensalidade no mês, quase sempre atrasado de mês anterior caindo agora.',
    'professores', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'teacher_id', k.teacher_id, 'teacher_name', k.teacher_name,
        'aulas', k.aulas, 'alunos', k.alunos,
        'custo_base',         round(k.custo_base,2),
        'comissao_turbo',     round(k.comissao_turbo,2),
        'bonus_treinamento',  round(k.bonus_treinamento,2),
        'ajuste_valor_base',  round(k.ajuste_valor_base,2),
        'ajustes_fechamento', round(k.ajustes_fechamento,2),
        'custo_total',        round(k.custo_total,2),
        'aulas_turbo', k.aulas_turbo, 'aulas_treinamento', k.aulas_treinamento,
        'aulas_ajustadas', k.aulas_ajustadas,
        'receita',            round(k.receita,2),
        'receita_contratada', round(k.receita_contratada,2),
        'nao_faturado',       round(k.receita_contratada - k.receita,2),
        'lucro',              round(k.receita - k.custo_total,2),
        'lucro_contratado',   round(k.receita_contratada - k.custo_total,2),
        'margem_pct',         round(100 * (k.receita - k.custo_total) / NULLIF(k.receita,0),1),
        'margem_contratada_pct', round(100 * (k.receita_contratada - k.custo_total) / NULLIF(k.receita_contratada,0),1),
        'custo_por_aula', round(k.custo_total / NULLIF(k.aulas,0),2),
        'alunos_detalhe', COALESCE((
           SELECT jsonb_agg(jsonb_build_object(
                    'student_id', pa.student_id, 'student_name', pa.student_name,
                    'aulas', pa.aulas, 'aulas_turbo', pa.aulas_turbo,
                    'custo', round(pa.custo,2), 'receita', round(pa.receita,2),
                    'receita_contratada', round(pa.receita_contratada,2),
                    'nao_faturado', round(pa.receita_contratada - pa.receita,2),
                    'lucro', round(pa.receita - pa.custo,2))
                  ORDER BY pa.receita_contratada - pa.custo DESC)
             FROM por_aluno pa WHERE pa.teacher_id = k.teacher_id), '[]'::jsonb)
      ) ORDER BY k.receita_contratada - k.custo_total DESC)   -- ← ordena pelo justo
      FROM consolidado k), '[]'::jsonb),
    'totais', (SELECT jsonb_build_object(
        'aulas',              COALESCE(sum(k.aulas),0),
        'custo_base',         round(COALESCE(sum(k.custo_base),0),2),
        'comissao_turbo',     round(COALESCE(sum(k.comissao_turbo),0),2),
        'bonus_treinamento',  round(COALESCE(sum(k.bonus_treinamento),0),2),
        'ajuste_valor_base',  round(COALESCE(sum(k.ajuste_valor_base),0),2),
        'ajustes_fechamento', round(COALESCE(sum(k.ajustes_fechamento),0),2),
        'custo_total',        round(COALESCE(sum(k.custo_total),0),2),
        'receita_alocada',    round(COALESCE(sum(k.receita),0),2),
        'receita_contratada', round(COALESCE(sum(k.receita_contratada),0),2),
        'nao_faturado',       round(COALESCE(sum(k.receita_contratada),0) - COALESCE(sum(k.receita),0),2),
        'lucro',              round(COALESCE(sum(k.receita),0) - COALESCE(sum(k.custo_total),0),2),
        'lucro_contratado',   round(COALESCE(sum(k.receita_contratada),0) - COALESCE(sum(k.custo_total),0),2)
      ) FROM consolidado k),
    'receita_total', round((SELECT COALESCE(sum(greatest(round(coalesce(sp.value, 0) - coalesce(sp.refunded_amount, 0), 2), 0)),0) FROM student_payments sp
        WHERE sp.tenant_id = v_tenant AND sp.status IN ('RECEIVED','RECEIVED_IN_CASH')
          AND to_char(COALESCE(sp.credited_at, sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM') = v_month),2),
    'receita_sem_aluno', round((SELECT COALESCE(sum(greatest(round(coalesce(sp.value, 0) - coalesce(sp.refunded_amount, 0), 2), 0)),0) FROM student_payments sp
        WHERE sp.tenant_id = v_tenant AND sp.status IN ('RECEIVED','RECEIVED_IN_CASH')
          AND to_char(COALESCE(sp.credited_at, sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM') = v_month
          AND sp.student_id IS NULL),2),
    'receita_aluno_sem_aula', round(
        (SELECT COALESCE(sum(greatest(round(coalesce(sp.value, 0) - coalesce(sp.refunded_amount, 0), 2), 0)),0) FROM student_payments sp
          WHERE sp.tenant_id = v_tenant AND sp.status IN ('RECEIVED','RECEIVED_IN_CASH')
            AND to_char(COALESCE(sp.credited_at, sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM') = v_month
            AND sp.student_id IS NOT NULL
            AND NOT EXISTS (SELECT 1 FROM aulas_aluno aa WHERE aa.student_id = sp.student_id)),2),
    'alunos_multi_professor', (SELECT count(*)::int FROM (
        SELECT ap.student_id FROM aulas_aluno_prof ap
         GROUP BY ap.student_id HAVING count(DISTINCT ap.teacher_id) > 1) z)
  ));
END;
$_$;


--
-- Name: FUNCTION balancete_professores(p_month text, p_tenant text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.balancete_professores(p_month text, p_tenant text) IS 'Balancete por professor: receita realizada liquida de refunded_amount; receita contratada permanece bruta.';


--
-- Name: balancete_receita_sem_aula(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.balancete_receita_sem_aula(p_month text DEFAULT NULL::text, p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_jwt_role text; v_role text; v_tenant text; v_month text;
BEGIN
  v_jwt_role := COALESCE(current_setting('request.jwt.claims', true)::json->>'role', '');
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_jwt_role IN ('anon','authenticated') THEN
    IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
      RETURN jsonb_build_object('error','sem_permissao');
    END IF;
    IF v_role = 'SUPER_ADMIN' THEN v_tenant := COALESCE(p_tenant, v_tenant); END IF;
  ELSE
    v_tenant := COALESCE(p_tenant, v_tenant);
  END IF;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('error','escola_nao_identificada'); END IF;

  v_month := COALESCE(p_month, to_char(current_date,'YYYY-MM'));
  IF v_month !~ '^\d{4}-\d{2}$' THEN RETURN jsonb_build_object('error','mes_invalido'); END IF;

  RETURN COALESCE((
    WITH pagou AS (
      SELECT sp.student_id, sum(greatest(round(coalesce(sp.value, 0) - coalesce(sp.refunded_amount, 0), 2), 0)) AS receita
        FROM student_payments sp
       WHERE sp.tenant_id = v_tenant
         AND sp.status IN ('RECEIVED','RECEIVED_IN_CASH')
         AND to_char(COALESCE(sp.credited_at, sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM') = v_month
         AND sp.student_id IS NOT NULL
       GROUP BY 1
    ), com_aula AS (
      SELECT DISTINCT v.student_id FROM v_payable_class_logs v
       WHERE to_char(v.class_date,'YYYY-MM') = v_month AND v.student_id IS NOT NULL
    ), sem_aula AS (
      SELECT pg.student_id, pg.receita, p.full_name AS student_name,
             -- Professor da AGENDA. Aluno em dois professores na agenda vira
             -- lista: não dá para escolher um sem inventar critério.
             (SELECT string_agg(DISTINCT trim(t.full_name), ', ')
                FROM bookings b JOIN profiles t ON t.id = b.teacher_id
               WHERE b.student_id = pg.student_id AND b.status = 'SCHEDULED') AS professor,
             (SELECT count(*) FROM bookings b
               WHERE b.student_id = pg.student_id AND b.status = 'SCHEDULED')::int AS slots
        FROM pagou pg JOIN profiles p ON p.id = pg.student_id
       WHERE NOT EXISTS (SELECT 1 FROM com_aula ca WHERE ca.student_id = pg.student_id)
    )
    SELECT jsonb_build_object(
      'total', round(COALESCE(sum(s.receita),0),2),
      'alunos', COALESCE(jsonb_agg(jsonb_build_object(
                  'student_id', s.student_id, 'student_name', s.student_name,
                  'receita', round(s.receita,2),
                  'professor', COALESCE(s.professor,'(sem agenda)'),
                  'slots', s.slots) ORDER BY s.receita DESC), '[]'::jsonb),
      'por_professor', COALESCE((
         SELECT jsonb_agg(x ORDER BY (x->>'receita')::numeric DESC) FROM (
           SELECT jsonb_build_object(
                    'professor', COALESCE(s2.professor,'(sem agenda)'),
                    'receita', round(sum(s2.receita),2),
                    'alunos', count(*)::int) AS x
             FROM sem_aula s2 GROUP BY COALESCE(s2.professor,'(sem agenda)')) y), '[]'::jsonb)
    ) FROM sem_aula s), jsonb_build_object('total',0,'alunos','[]'::jsonb,'por_professor','[]'::jsonb));
END;
$_$;


--
-- Name: FUNCTION balancete_receita_sem_aula(p_month text, p_tenant text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.balancete_receita_sem_aula(p_month text, p_tenant text) IS 'Receita recebida sem aula, liquida de refunded_amount, sem criar margem artificial para professor.';


--
-- Name: begin_asaas_reconciliation_run(date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_asaas_reconciliation_run(p_window_start date, p_window_end date, p_started_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  run_row public.asaas_reconciliation_runs%rowtype;
begin
  if p_window_start is null or p_window_end is null
     or p_window_end < p_window_start
     or p_window_end - p_window_start > 366
  then
    raise exception using errcode = '22023', message = 'invalid_reconciliation_window';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('asaas-reconciliation-run', 0));

  update public.asaas_reconciliation_runs
     set status = 'FAILED',
         finished_at = now(),
         last_error = 'stale_run_reclaimed',
         updated_at = now()
   where status = 'RUNNING'
     and updated_at < now() - interval '30 minutes';

  select run.* into run_row
    from public.asaas_reconciliation_runs as run
   where run.status = 'RUNNING'
   order by run.started_at
   limit 1;
  if found then
    return jsonb_build_object('ok', false, 'reason', 'already_running', 'run_id', run_row.id);
  end if;

  insert into public.asaas_reconciliation_runs (
    window_start, window_end, started_by
  ) values (
    p_window_start, p_window_end, p_started_by
  ) returning * into run_row;

  return jsonb_build_object('ok', true, 'run_id', run_row.id);
end;
$$;


--
-- Name: begin_enrollment_offer(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_enrollment_offer(p_offer_id uuid, p_profile jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_user_id uuid := (select auth.uid());
  v_offer record;
  v_safe_profile jsonb;
  v_student_phone text;
  v_result jsonb;
  v_error_state text;
  v_error_message text;
  v_error_detail text;
begin
  select
    offer.tenant_id,
    offer.payload,
    offer.invite_security_version,
    offer.processing_by,
    offer.processing_state,
    offer.consumed_at,
    offer.consumed_by,
    offer.revoked_at,
    offer.expires_at
  into v_offer
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.kind = 'ENROLLMENT';
  if not found then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'OFFER_NOT_FOUND'
    );
  end if;
  if v_offer.invite_security_version < 1 or v_offer.revoked_at is not null then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'OFFER_REVOKED'
    );
  end if;
  if not private.tenant_is_operational(v_offer.tenant_id) then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'TENANT_UNAVAILABLE'
    );
  end if;
  if v_user_id is null then
    return public.begin_enrollment_offer_pre_schedule_impl(
      p_offer_id,
      p_profile
    );
  end if;
  if v_offer.processing_state = 'COMPLETED'
    or (
      v_offer.consumed_at is not null
      and v_offer.consumed_by = v_user_id
    )
    or (
      v_offer.processing_by is not null
      and v_offer.processing_by is distinct from v_user_id
    )
  then
    return public.begin_enrollment_offer_pre_schedule_impl(
      p_offer_id,
      p_profile
    );
  end if;
  if pg_catalog.jsonb_typeof(coalesce(p_profile, '{}'::jsonb))
       is distinct from 'object'
  then
    return public.begin_enrollment_offer_pre_schedule_impl(
      p_offer_id,
      p_profile
    );
  end if;

  v_safe_profile := coalesce(p_profile, '{}'::jsonb);

  begin
    perform private.reserve_enrollment_offer_schedule(
      p_offer_id,
      v_user_id
    );

    -- reserve ja detem o lock da oferta. Rele o snapshot sob esse lock para
    -- nao usar telefone/endereco antigo enquanto outro writer altera a oferta.
    select offer.payload
    into v_offer
    from public.offers as offer
    where offer.id = p_offer_id
      and offer.kind = 'ENROLLMENT'
    for update;
    if not found then
      raise exception 'enrollment_schedule_changed' using errcode = '23P01';
    end if;

    if coalesce((v_offer.payload ->> 'isDependent')::boolean, false) then
      v_student_phone := pg_catalog.regexp_replace(
        coalesce(v_offer.payload ->> 'studentPhone', ''),
        '[^0-9]',
        '',
        'g'
      );
      if v_student_phone !~ '^[1-9]{2}9[0-9]{8}$' then
        raise exception 'dependent_student_phone_invalid'
          using errcode = '22023';
      end if;
      v_safe_profile := v_safe_profile || pg_catalog.jsonb_build_object(
        'phone', v_student_phone,
        'postal_code', pg_catalog.regexp_replace(
          coalesce(v_offer.payload ->> 'guardianPostalCode', ''),
          '[^0-9]',
          '',
          'g'
        ),
        'address', pg_catalog.btrim(
          coalesce(v_offer.payload ->> 'guardianAddress', '')
        ),
        'address_number', pg_catalog.btrim(
          coalesce(v_offer.payload ->> 'guardianAddressNumber', '')
        )
      );
    end if;

    perform private.prepare_enrollment_finance_scope(
      p_offer_id,
      v_user_id
    );

    v_result := public.begin_enrollment_offer_pre_schedule_impl(
      p_offer_id,
      v_safe_profile
    );
    if coalesce((v_result ->> 'success')::boolean, false) is false then
      raise exception using
        errcode = 'PZ001',
        message = 'enrollment_begin_rejected',
        detail = v_result::text;
    end if;
    return v_result;
  exception
    when sqlstate 'PZ001' then
      get stacked diagnostics v_error_detail = pg_exception_detail;
      return v_error_detail::jsonb;
    when exclusion_violation or check_violation
      or insufficient_privilege or unique_violation
      or invalid_parameter_value or deadlock_detected
    then
      get stacked diagnostics
        v_error_state = returned_sqlstate,
        v_error_message = message_text;
      if v_error_message = 'enrollment_financial_scope_conflict' then
        return pg_catalog.jsonb_build_object(
          'success', false,
          'error', 'FINANCIAL_SCOPE_CONFLICT'
        );
      end if;
      if v_error_message = 'enrollment_first_billing_date_passed' then
        return pg_catalog.jsonb_build_object(
          'success', false,
          'error', 'BILLING_PERIOD_EXPIRED'
        );
      end if;
      if v_error_message = 'dependent_student_phone_invalid' then
        return pg_catalog.jsonb_build_object(
          'success', false,
          'error', 'INVALID_STUDENT_PHONE'
        );
      end if;
      if v_error_state = '40P01' or v_error_message in (
        'enrollment_schedule_changed',
        'enrollment_schedule_reserved',
        'inactive_enrollment_teacher',
        'teacher_slot_unavailable',
        'teacher_slot_occupied'
      ) then
        return pg_catalog.jsonb_build_object(
          'success', false,
          'error', 'SCHEDULE_UNAVAILABLE'
        );
      end if;
      raise;
  end;
end;
$_$;


--
-- Name: begin_enrollment_offer_authoritative_impl(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_enrollment_offer_authoritative_impl(p_offer_id uuid, p_profile jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  v_email text;
  v_existing_role text;
  v_payload jsonb;
  v_dependent boolean;
  v_fee numeric;
  v_phone text;
  v_cpf text;
  v_signature text;
  v_expected_signer text;
  v_signature_normalized text;
  v_expected_normalized text;
  v_billing_type text;
  v_invite_id uuid;
  v_referrer_id uuid;
  v_referrer_role text;
  v_referrer_teacher_id uuid;
  v_referrer_student_id uuid;
  v_opportunity_id uuid;
  v_enrollment_link_id uuid;
  v_request_headers jsonb := coalesce(
    nullif(current_setting('request.headers', true), '')::jsonb,
    '{}'::jsonb
  );
  v_ip text;
  v_user_agent text;
  v_accepted_at timestamptz := clock_timestamp();
  o public.offers%rowtype;
  v_opp public.opportunities%rowtype;
begin
  if v_user is null then
    return jsonb_build_object('success', false, 'error', 'UNAUTHORIZED');
  end if;
  if jsonb_typeof(coalesce(p_profile, '{}'::jsonb)) is distinct from 'object' then
    return jsonb_build_object('success', false, 'error', 'INVALID_PROFILE');
  end if;

  select opportunity_id
    into v_opportunity_id
    from public.offers
   where id = p_offer_id
     and kind = 'ENROLLMENT';
  if not found then
    return jsonb_build_object('success', false, 'error', 'OFFER_NOT_FOUND');
  end if;

  -- Mesma ordem de locks usada na emissão/finalização: opportunity -> offer.
  if v_opportunity_id is not null then
    select *
      into v_opp
      from public.opportunities
     where id = v_opportunity_id
     for update;
  end if;

  select *
    into o
    from public.offers
   where id = p_offer_id
     and kind = 'ENROLLMENT'
   for update;

  if not found then return jsonb_build_object('success', false, 'error', 'OFFER_NOT_FOUND'); end if;
  if o.revoked_at is not null then return jsonb_build_object('success', false, 'error', 'OFFER_REVOKED'); end if;
  if o.consumed_at is not null and o.consumed_by is distinct from v_user then
    return jsonb_build_object('success', false, 'error', 'OFFER_CONSUMED');
  end if;
  if o.consumed_at is null and o.expires_at <= now() then
    return jsonb_build_object('success', false, 'error', 'OFFER_EXPIRED');
  end if;
  if o.processing_by is not null and o.processing_by is distinct from v_user
     and o.processing_state <> 'COMPLETED' then
    return jsonb_build_object('success', false, 'error', 'OFFER_IN_PROGRESS');
  end if;
  if o.processing_state = 'COMPLETED' or (
    o.consumed_at is not null and o.consumed_by = v_user
  ) then
    return jsonb_build_object(
      'success', true,
      'already_completed', true,
      'offer_id', o.id,
      'correlation_id', o.processing_correlation_id,
      'processing_state', 'COMPLETED',
      'payload', coalesce(o.payload, '{}'::jsonb) || jsonb_build_object('_offerId', o.id)
    );
  end if;

  if v_opportunity_id is not null then
    if v_opp.id is null or v_opp.tenant_id is distinct from o.tenant_id then
      return jsonb_build_object('success', false, 'error', 'OPPORTUNITY_INVALID');
    end if;
    if v_opp.conversion_status = 'LOST' then
      return jsonb_build_object('success', false, 'error', 'OPPORTUNITY_CLOSED');
    end if;
    if v_opp.conversion_status = 'WON'
       and (v_opp.student_id is null or v_opp.student_id is distinct from v_user) then
      return jsonb_build_object('success', false, 'error', 'OPPORTUNITY_CONVERTED');
    end if;
  end if;

  select p.role
    into v_existing_role
    from public.profiles p
   where p.id = v_user
   for update;
  if found and v_existing_role is distinct from 'STUDENT' then
    return jsonb_build_object('success', false, 'error', 'PROFILE_ROLE_NOT_ALLOWED');
  end if;

  select lower(trim(u.email))
    into v_email
    from auth.users u
   where u.id = v_user;
  if v_email is null then
    return jsonb_build_object('success', false, 'error', 'USER_NOT_FOUND');
  end if;

  v_payload := coalesce(o.payload, '{}'::jsonb) || jsonb_build_object(
    'unitId', o.tenant_id,
    'requiresEnrollment', o.requires_enrollment,
    'enrollmentFee', o.enrollment_fee,
    'opportunityId', o.opportunity_id,
    'vendorId', o.vendor_id
  );
  v_dependent := coalesce((v_payload ->> 'isDependent')::boolean, false);
  v_fee := greatest(coalesce(o.enrollment_fee, 0), 0);
  v_phone := regexp_replace(coalesce(p_profile ->> 'phone', ''), '[^0-9]', '', 'g');
  v_cpf := regexp_replace(coalesce(p_profile ->> 'cpf', ''), '[^0-9]', '', 'g');
  v_signature := btrim(coalesce(p_profile ->> 'typed_signature', ''));
  v_billing_type := upper(btrim(coalesce(p_profile ->> 'billing_type', '')));
  v_expected_signer := case
    when v_dependent then coalesce(v_payload ->> 'guardianName', '')
    else coalesce(p_profile ->> 'full_name', '')
  end;
  v_signature_normalized := lower(regexp_replace(v_signature, '\s+', ' ', 'g'));
  v_expected_normalized := lower(regexp_replace(btrim(v_expected_signer), '\s+', ' ', 'g'));

  if length(trim(coalesce(p_profile ->> 'full_name', ''))) < 3 then
    return jsonb_build_object('success', false, 'error', 'INVALID_NAME');
  end if;
  if length(v_phone) < 10 or length(v_phone) > 13 then
    return jsonb_build_object('success', false, 'error', 'INVALID_PHONE');
  end if;
  if not v_dependent and not public.is_valid_cpf(v_cpf) then
    return jsonb_build_object('success', false, 'error', 'INVALID_CPF');
  end if;
  if v_billing_type not in ('PIX', 'BOLETO', 'CREDIT_CARD') then
    return jsonb_build_object('success', false, 'error', 'INVALID_BILLING_TYPE');
  end if;
  if length(v_signature) < 3 or v_signature_normalized is distinct from v_expected_normalized then
    return jsonb_build_object('success', false, 'error', 'INVALID_SIGNATURE');
  end if;
  if not v_dependent and exists (
    select 1
      from public.profiles p
     where regexp_replace(coalesce(p.cpf, ''), '[^0-9]', '', 'g') = v_cpf
       and p.tenant_id = o.tenant_id
       and p.id <> v_user
  ) then
    return jsonb_build_object('success', false, 'error', 'CPF_ALREADY_REGISTERED');
  end if;

  v_ip := split_part(
    coalesce(
      nullif(v_request_headers ->> 'x-real-ip', ''),
      nullif(v_request_headers ->> 'cf-connecting-ip', ''),
      nullif(v_request_headers ->> 'x-forwarded-for', ''),
      ''
    ),
    ',',
    1
  );
  v_user_agent := left(coalesce(v_request_headers ->> 'user-agent', ''), 500);

  -- A indicação é derivada de e-mail/tenant e só será convertida na finalização.
  select ri.id, ri.referrer_id, rp.role
    into v_invite_id, v_referrer_id, v_referrer_role
    from public.referral_invites ri
    join public.profiles rp on rp.id = ri.referrer_id
   where lower(trim(ri.invitee_email)) = v_email
     and ri.status = 'PENDING'
     and ri.expires_at > now()
     and (ri.tenant_id is null or ri.tenant_id = o.tenant_id)
     and rp.tenant_id = o.tenant_id
     and ri.referrer_id <> v_user
   order by ri.created_at desc
   limit 1
   for update of ri;

  if v_invite_id is not null then
    if v_referrer_role in ('TEACHER', 'SCHOOL_ADMIN', 'COORDINATOR') then
      v_referrer_teacher_id := v_referrer_id;
    elsif v_referrer_role = 'STUDENT' then
      v_referrer_student_id := v_referrer_id;
    end if;
  end if;

  perform set_config('app.enrollment_claim', '1', true);

  insert into public.profiles (
    id, email, full_name, role, tenant_id, phone, cpf, postal_code,
    address, address_number, status_financial, monthly_fee, due_day,
    module, contract_accepted, documentation_status, accepted_at,
    class_frequency, signature_ip, user_ip, typed_signature, signature_hash,
    student_signature_url, signed_document_url, wise_wolf_signature_token,
    enrollment_fee, enrollment_fee_paid, professor_id, professor_id2,
    start_date, guardian_id, guardian_name, guardian_cpf, guardian_email,
    guardian_phone, attendance_phone, referrer_teacher_id, referrer_student_id
  )
  values (
    v_user,
    v_email,
    trim(p_profile ->> 'full_name'),
    'STUDENT',
    o.tenant_id,
    v_phone,
    case when v_dependent then null else v_cpf end,
    nullif(p_profile ->> 'postal_code', ''),
    nullif(p_profile ->> 'address', ''),
    nullif(p_profile ->> 'address_number', ''),
    'PENDING',
    (v_payload ->> 'value')::numeric,
    (v_payload ->> 'dueDay')::integer,
    'General',
    true,
    'APPROVED',
    v_accepted_at,
    coalesce(v_payload ->> 'classesPerWeek', '1') || 'x',
    nullif(v_ip, ''),
    nullif(v_ip, ''),
    v_signature,
    encode(digest(
      v_user::text || '|' || o.id::text || '|' || v_signature || '|' ||
      v_accepted_at::text || '|' || v_user_agent,
      'sha256'
    ), 'hex'),
    nullif(p_profile ->> 'student_signature_url', ''),
    nullif(p_profile ->> 'signed_document_url', ''),
    gen_random_uuid()::text,
    v_fee,
    v_fee <= 0,
    nullif(v_payload ->> 'professorId', '')::uuid,
    nullif(v_payload ->> 'professorId2', '')::uuid,
    nullif(v_payload ->> 'startDate', '')::date,
    case when v_dependent then nullif(v_payload ->> 'guardianId', '')::uuid else null end,
    case when v_dependent then nullif(v_payload ->> 'guardianName', '') else null end,
    case when v_dependent then regexp_replace(coalesce(v_payload ->> 'guardianCpf', ''), '[^0-9]', '', 'g') else null end,
    case when v_dependent then nullif(v_payload ->> 'guardianEmail', '') else null end,
    case when v_dependent then regexp_replace(coalesce(v_payload ->> 'guardianPhone', ''), '[^0-9]', '', 'g') else null end,
    case when v_dependent then regexp_replace(coalesce(v_payload ->> 'studentPhone', ''), '[^0-9]', '', 'g') else null end,
    v_referrer_teacher_id,
    v_referrer_student_id
  )
  on conflict (id) do update set
    email = excluded.email,
    full_name = excluded.full_name,
    role = 'STUDENT',
    tenant_id = excluded.tenant_id,
    phone = excluded.phone,
    cpf = excluded.cpf,
    postal_code = excluded.postal_code,
    address = excluded.address,
    address_number = excluded.address_number,
    -- Nunca rebaixa um perfil já sincronizado/ativo durante uma retomada.
    status_financial = coalesce(public.profiles.status_financial, excluded.status_financial),
    monthly_fee = excluded.monthly_fee,
    due_day = excluded.due_day,
    module = excluded.module,
    contract_accepted = true,
    documentation_status = excluded.documentation_status,
    accepted_at = coalesce(public.profiles.accepted_at, excluded.accepted_at),
    class_frequency = excluded.class_frequency,
    signature_ip = coalesce(public.profiles.signature_ip, excluded.signature_ip),
    user_ip = coalesce(public.profiles.user_ip, excluded.user_ip),
    typed_signature = coalesce(public.profiles.typed_signature, excluded.typed_signature),
    signature_hash = coalesce(public.profiles.signature_hash, excluded.signature_hash),
    student_signature_url = coalesce(excluded.student_signature_url, public.profiles.student_signature_url),
    signed_document_url = coalesce(excluded.signed_document_url, public.profiles.signed_document_url),
    wise_wolf_signature_token = coalesce(public.profiles.wise_wolf_signature_token, excluded.wise_wolf_signature_token),
    enrollment_fee = excluded.enrollment_fee,
    enrollment_fee_paid = case
      when excluded.enrollment_fee <= 0 then true
      else coalesce(public.profiles.enrollment_fee_paid, false)
    end,
    professor_id = excluded.professor_id,
    professor_id2 = excluded.professor_id2,
    start_date = excluded.start_date,
    guardian_id = excluded.guardian_id,
    guardian_name = excluded.guardian_name,
    guardian_cpf = excluded.guardian_cpf,
    guardian_email = excluded.guardian_email,
    guardian_phone = excluded.guardian_phone,
    attendance_phone = excluded.attendance_phone,
    referrer_teacher_id = coalesce(public.profiles.referrer_teacher_id, excluded.referrer_teacher_id),
    referrer_student_id = coalesce(public.profiles.referrer_student_id, excluded.referrer_student_id);

  select el.id
    into v_enrollment_link_id
    from public.enrollment_links el
   where el.offer_id = o.id
   limit 1
   for update;

  update public.enrollment_links
     set status = 'PROCESSING'
   where offer_id = o.id
     and status = 'PENDING';

  update public.offers
     set processing_by = v_user,
         processing_state = case
           when processing_state in ('CUSTOMER_READY', 'BILLING_READY', 'AWAITING_PAYMENT')
             then processing_state
           else 'PROFILE_READY'
         end,
         processing_started_at = coalesce(processing_started_at, now()),
         processing_updated_at = now(),
         processing_attempts = processing_attempts + 1,
         processing_error_code = null,
         processing_error_message = null,
         metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
           'billing_type', v_billing_type,
           'referral_invite_id', v_invite_id,
           'signature_user_agent', v_user_agent,
           'enrollment_link_id', v_enrollment_link_id
         )
   where id = o.id;

  select * into o from public.offers where id = o.id;

  return jsonb_build_object(
    'success', true,
    'offer_id', o.id,
    'correlation_id', o.processing_correlation_id,
    'processing_state', o.processing_state,
    'payload', v_payload || jsonb_build_object('_offerId', o.id)
  );
end;
$$;


--
-- Name: begin_enrollment_offer_pre_schedule_impl(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_enrollment_offer_pre_schedule_impl(p_offer_id uuid, p_profile jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  offer_tenant_id text;
  offer_security_version smallint;
BEGIN
  SELECT offer.tenant_id, offer.invite_security_version
  INTO offer_tenant_id, offer_security_version
  FROM public.offers AS offer
  WHERE offer.id = p_offer_id
    AND offer.kind = 'ENROLLMENT';
  IF offer_tenant_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'OFFER_NOT_FOUND');
  END IF;
  IF offer_security_version < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'OFFER_REVOKED');
  END IF;
  IF NOT private.tenant_is_operational(offer_tenant_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_UNAVAILABLE');
  END IF;
  RETURN public.begin_enrollment_offer_authoritative_impl(p_offer_id, p_profile);
END;
$$;


--
-- Name: begin_management_payment_notification_submission(uuid, uuid, text, text, text, uuid, bigint, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_management_payment_notification_submission(p_attempt_id uuid, p_claim_token uuid, p_expected_destination text, p_provider_destination text, p_provider_instance_name text, p_integration_id uuid, p_integration_version bigint, p_source_snapshot jsonb, p_message_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_outbox public.management_payment_notification_outbox%rowtype;
  v_payment public.student_payments%rowtype;
  v_instance public.whatsapp_instances%rowtype;
  v_connection private.tenant_integration_connections%rowtype;
  v_expected_destination text :=
    private.normalize_management_group_destination(p_expected_destination);
  v_provider_destination text :=
    private.normalize_management_group_destination(p_provider_destination);
  v_current_destination text;
  v_instance_name text := pg_catalog.btrim(
    coalesce(p_provider_instance_name, '')
  );
  v_source_snapshot jsonb := p_source_snapshot;
  v_current_source_snapshot jsonb;
  v_source_snapshot_hash text;
  v_replacement_kind text;
  v_message_body text := coalesce(p_message_body, '');
  v_destination_matches boolean := false;
begin
  if p_attempt_id is null
     or p_claim_token is null
     or v_expected_destination is null
     or v_provider_destination is null
     or pg_catalog.char_length(v_instance_name) not between 3 and 120
     or p_integration_id is null
     or coalesce(p_integration_version, 0) <= 0
     or pg_catalog.jsonb_typeof(v_source_snapshot) <> 'object'
     or pg_catalog.char_length(v_message_body) not between 1 and 8000 then
    raise exception 'invalid_management_payment_notification_submission'
      using errcode = '22023';
  end if;

  select outbox.*
  into v_outbox
  from public.management_payment_notification_outbox as outbox
  where outbox.id = p_attempt_id;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'claim_lost'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'management-payment-notification:' || v_outbox.tenant_id || ':' ||
        v_outbox.payment_id::text,
      0
    )
  );

  -- Canonical order matches the settlement trigger: financial source first,
  -- then its outbox row. A repeated provider transition cannot deadlock the
  -- final submission fence by holding these rows in the inverse order.
  select payment.*
  into v_payment
  from public.student_payments as payment
  where payment.id = v_outbox.payment_id
    and payment.tenant_id = v_outbox.tenant_id
  for update;

  select outbox.*
  into v_outbox
  from public.management_payment_notification_outbox as outbox
  where outbox.id = p_attempt_id
  for update;

  if not found
     or v_outbox.status <> 'CLAIMED'
     or v_outbox.claim_token is distinct from p_claim_token
     or v_outbox.lease_expires_at <= pg_catalog.now()
     or v_outbox.submit_attempt_count <> 0 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'claim_lost'
    );
  end if;

  v_replacement_kind :=
    private.management_payment_notification_replacement_kind(
      v_outbox.tenant_id,
      v_outbox.payment_id
    );
  if v_replacement_kind is not null
     and v_replacement_kind is distinct from v_outbox.notification_kind then
    update public.management_payment_notification_outbox
    set notification_kind = v_replacement_kind,
        status = 'PENDING',
        claim_token = null,
        lease_expires_at = null,
        configured_destination_snapshot = null,
        provider_destination = null,
        provider_instance_name = null,
        provider_integration_id = null,
        provider_integration_version = null,
        provider_endpoint_hash = null,
        provider_credential_hash = null,
        message_body = null,
        source_snapshot = null,
        source_snapshot_hash = null,
        snapshot_hash = null,
        last_error = 'management_payment_notification_kind_regenerated',
        updated_at = pg_catalog.now()
    where id = v_outbox.id
      and submit_attempt_count = 0;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'RETRY',
      'status', 'PENDING',
      'notification_kind', v_replacement_kind,
      'reason', 'management_payment_notification_kind_regenerated'
    );
  end if;

  if v_payment.id is null
     or not private.management_payment_notification_scope_active(
       v_outbox.tenant_id,
       v_outbox.payment_id,
       v_outbox.notification_kind
     ) then
    update public.management_payment_notification_outbox
    set status = 'SUPPRESSED',
        lease_expires_at = pg_catalog.now(),
        last_error = 'management_payment_scope_changed_before_send',
        updated_at = pg_catalog.now()
    where id = v_outbox.id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'status', 'SUPPRESSED',
      'reason', 'management_payment_scope_changed_before_send'
    );
  end if;

  select private.normalize_management_group_destination(management.destino)
  into v_current_destination
  from public.dre_report_settings as management
  where management.tenant_id = v_outbox.tenant_id
    and management.is_active
  for share;

  if v_current_destination is null
     or v_current_destination is distinct from v_expected_destination then
    update public.management_payment_notification_outbox
    set status = 'SUPPRESSED',
        lease_expires_at = pg_catalog.now(),
        last_error = 'management_destination_changed_before_send',
        updated_at = pg_catalog.now()
    where id = v_outbox.id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'status', 'SUPPRESSED',
      'reason', 'management_destination_changed_before_send'
    );
  end if;

  v_destination_matches := case
    when v_expected_destination like '%@g.us'
      then v_provider_destination = v_expected_destination
    else private.notification_phones_same_recipient(
      v_expected_destination,
      v_provider_destination
    )
  end;
  if not coalesce(v_destination_matches, false) then
    update public.management_payment_notification_outbox
    set status = 'SUPPRESSED',
        lease_expires_at = pg_catalog.now(),
        last_error = 'management_provider_destination_mismatch',
        updated_at = pg_catalog.now()
    where id = v_outbox.id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'status', 'SUPPRESSED',
      'reason', 'management_provider_destination_mismatch'
    );
  end if;

  select instance.*
  into v_instance
  from public.whatsapp_instances as instance
  where instance.tenant_id = v_outbox.tenant_id
    and lower(instance.instance_name) = lower(v_instance_name)
    and lower(pg_catalog.btrim(coalesce(instance.status, ''))) in (
      'connected', 'open'
    )
    and instance.inbox_enabled is true
    and instance.webhook_auth_version = 3
    and instance.integration_id = p_integration_id
    and instance.integration_version = p_integration_version
    and exists (
      select 1
      from public.tenant_memberships as membership
      where membership.tenant_id = instance.tenant_id
        and membership.user_id = instance.user_id
        and membership.role = 'SCHOOL_ADMIN'
        and membership.status = 'ACTIVE'
    )
  for share;

  select connection.*
  into v_connection
  from private.tenant_integration_connections as connection
  where connection.id = p_integration_id
    and connection.tenant_id = v_outbox.tenant_id
    and connection.provider = 'evolution'
    and connection.version = p_integration_version
    and connection.mode <> 'DISABLED'
    and connection.status = 'healthy'
  for share;

  if v_instance.id is null or v_connection.id is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'management_provider_binding_changed'
    );
  end if;

  -- Hold the exact active admin authority through the commit that seals the
  -- submission. The instance lookup above validates membership, while this
  -- lock prevents a concurrent revocation from slipping between that lookup
  -- and the immutable snapshot transition.
  perform 1
  from public.tenant_memberships as membership
  where membership.tenant_id = v_instance.tenant_id
    and membership.user_id = v_instance.user_id
    and membership.role = 'SCHOOL_ADMIN'
    and membership.status = 'ACTIVE'
  for share;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'management_provider_authority_changed'
    );
  end if;

  -- This is deliberately the last mutable business-scope read before the
  -- PREPARED snapshot. It catches a settlement reversal,
  -- fixture flag, tenant switch, split toggle or legacy attempt that changed
  -- while the destination/provider binding was being resolved.
  if not private.management_payment_notification_scope_active(
    v_outbox.tenant_id,
    v_outbox.payment_id,
    v_outbox.notification_kind
  ) then
    v_replacement_kind :=
      private.management_payment_notification_replacement_kind(
        v_outbox.tenant_id,
        v_outbox.payment_id
      );
    if v_replacement_kind is not null
       and v_replacement_kind is distinct from v_outbox.notification_kind then
      update public.management_payment_notification_outbox
      set notification_kind = v_replacement_kind,
          status = 'PENDING',
          claim_token = null,
          lease_expires_at = null,
          configured_destination_snapshot = null,
          provider_destination = null,
          provider_instance_name = null,
          provider_integration_id = null,
          provider_integration_version = null,
          provider_endpoint_hash = null,
          provider_credential_hash = null,
          message_body = null,
          source_snapshot = null,
          source_snapshot_hash = null,
          snapshot_hash = null,
          last_error = 'management_payment_notification_kind_regenerated',
          updated_at = pg_catalog.now()
      where id = v_outbox.id
        and submit_attempt_count = 0;
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'RETRY',
        'status', 'PENDING',
        'notification_kind', v_replacement_kind,
        'reason', 'management_payment_notification_kind_regenerated'
      );
    end if;

    update public.management_payment_notification_outbox
    set status = 'SUPPRESSED',
        lease_expires_at = pg_catalog.now(),
        last_error = 'management_payment_scope_changed_at_final_fence',
        updated_at = pg_catalog.now()
    where id = v_outbox.id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'status', 'SUPPRESSED',
      'reason', 'management_payment_scope_changed_at_final_fence'
    );
  end if;

  v_current_source_snapshot :=
    public.management_payment_notification_source_snapshot(
      v_outbox.tenant_id,
      v_outbox.payment_id,
      v_outbox.notification_kind
    );
  if v_current_source_snapshot is null
     or v_current_source_snapshot is distinct from v_source_snapshot then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'management_payment_source_changed_before_send'
    );
  end if;

  v_source_snapshot_hash := pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(v_source_snapshot::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  update public.management_payment_notification_outbox
  set status = 'PREPARED',
      submit_attempt_count = 0,
      configured_destination_snapshot = v_expected_destination,
      provider_destination = v_provider_destination,
      provider_instance_name = v_instance.instance_name,
      provider_integration_id = p_integration_id,
      provider_integration_version = p_integration_version,
      message_body = v_message_body,
      source_snapshot = v_source_snapshot,
      source_snapshot_hash = v_source_snapshot_hash,
      provider_endpoint_hash = null,
      provider_credential_hash = null,
      snapshot_hash = null,
      lease_expires_at = pg_catalog.now() + interval '5 minutes',
      last_error = null,
      updated_at = pg_catalog.now()
  where id = v_outbox.id
    and status = 'CLAIMED'
    and claim_token = p_claim_token
    and lease_expires_at > pg_catalog.now()
    and submit_attempt_count = 0
  returning * into v_outbox;

  if not found then
    raise exception 'management_payment_submission_transition_failed';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'PREPARED',
    'status', v_outbox.status,
    'attempt_id', v_outbox.id,
    'notification_kind', v_outbox.notification_kind,
    'provider_destination', v_outbox.provider_destination,
    'provider_instance_name', v_outbox.provider_instance_name,
    'provider_integration_id', v_outbox.provider_integration_id,
    'provider_integration_version', v_outbox.provider_integration_version,
    'message_body', v_outbox.message_body,
    'source_snapshot_hash', v_outbox.source_snapshot_hash
  );
end;
$$;


--
-- Name: begin_notification_delivery_submission(uuid, uuid, text, text, text, text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_notification_delivery_submission(p_notification_id uuid, p_claim_token uuid, p_provider_instance_name text, p_expected_destination text, p_provider_destination text, p_expected_message_body text, p_integration_id uuid, p_integration_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_runtime_role text := coalesce((select auth.jwt() ->> 'role'), '');
  v_notification public.notification_queue%rowtype;
  v_kind text;
  v_snapshot jsonb;
  v_current_destination text;
  v_current_teacher_id uuid;
begin
  if v_runtime_role <> 'service_role' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'forbidden'
    );
  end if;

  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id;
  v_kind := pg_catalog.upper(pg_catalog.btrim(coalesce(
    v_notification.notification_kind,
    ''
  )));

  if v_kind not in (
    'TRIAL_TEACHER_REQUESTED',
    'TRIAL_MANAGEMENT_ACCEPTED'
  ) then
    return public.begin_notification_delivery_submission_pre_trial_lifecycle_impl(
      p_notification_id,
      p_claim_token,
      p_provider_instance_name,
      p_expected_destination,
      p_provider_destination,
      p_expected_message_body,
      p_integration_id,
      p_integration_version
    );
  end if;

  if v_notification.id is null
     or v_notification.source_id is null
     or pg_catalog.upper(pg_catalog.btrim(coalesce(
       v_notification.source_type,
       ''
     ))) <> 'TRIAL_OPPORTUNITY'
     or v_notification.tenant_id is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'invalid_trial_notification_identity'
    );
  end if;

  begin
    perform opportunity.id
    from public.opportunities as opportunity
    where opportunity.id = v_notification.source_id
      and opportunity.tenant_id = v_notification.tenant_id
    for share nowait;
    if not found then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'trial_notification_source_unavailable'
      );
    end if;

    perform link.id
    from public.enrollment_links as link
    where link.opportunity_id = v_notification.source_id
    order by link.id
    for share nowait;

    perform request.id
    from private.vendor_trial_teacher_requests as request
    where request.opportunity_id = v_notification.source_id
    order by request.id
    for share nowait;
  exception when lock_not_available then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'trial_notification_revalidation_busy'
    );
  end;

  v_snapshot := public.get_trial_notification_delivery_snapshot(
    v_notification.tenant_id,
    v_notification.source_id,
    v_kind
  );
  if coalesce((v_snapshot ->> 'ok')::boolean, false) is not true then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', case
        when coalesce((v_snapshot ->> 'retryable')::boolean, false)
          then 'RETRY'
        else 'REVIEW_REQUIRED'
      end,
      'reason', coalesce(
        v_snapshot ->> 'reason',
        'trial_notification_revalidation_failed'
      )
    );
  end if;

  v_current_destination := private.normalize_notification_destination(
    v_snapshot ->> 'destination'
  );
  begin
    v_current_teacher_id := nullif(v_snapshot ->> 'teacherId', '')::uuid;
  exception when invalid_text_representation then
    v_current_teacher_id := null;
  end;
  if v_current_destination is null
     or v_current_destination is distinct from
       private.normalize_notification_destination(p_expected_destination)
     or (
       v_current_destination like '%@g.us'
       and private.normalize_notification_destination(p_provider_destination)
         is distinct from v_current_destination
     )
     or (
       v_current_destination not like '%@g.us'
       and not private.notification_phones_same_recipient(
         v_current_destination,
         private.normalize_notification_destination(p_provider_destination)
       )
     )
     or (
       v_kind = 'TRIAL_TEACHER_REQUESTED'
       and v_notification.teacher_id is distinct from v_current_teacher_id
     )
     or (
       v_kind = 'TRIAL_MANAGEMENT_ACCEPTED'
       and v_notification.teacher_id is not null
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'trial_notification_authorized_snapshot_changed'
    );
  end if;

  return public.begin_notification_delivery_submission_pre_trial_lifecycle_impl(
    p_notification_id,
    p_claim_token,
    p_provider_instance_name,
    p_expected_destination,
    p_provider_destination,
    p_expected_message_body,
    p_integration_id,
    p_integration_version
  );
end;
$$;


--
-- Name: begin_notification_delivery_submission_pre_trial_lifecycle_impl(uuid, uuid, text, text, text, text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_notification_delivery_submission_pre_trial_lifecycle_impl(p_notification_id uuid, p_claim_token uuid, p_provider_instance_name text, p_expected_destination text, p_provider_destination text, p_expected_message_body text, p_integration_id uuid, p_integration_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_notification public.notification_queue%rowtype;
  v_instance public.whatsapp_instances%rowtype;
  v_connection private.tenant_integration_connections%rowtype;
  v_booking public.bookings%rowtype;
  v_reschedule public.reschedules%rowtype;
  v_appointment public.appointments%rowtype;
  v_conflict_requested public.attendance_confirmations%rowtype;
  v_conflict_canonical public.attendance_confirmations%rowtype;
  v_teacher public.profiles%rowtype;
  v_teacher_membership public.tenant_memberships%rowtype;
  v_student public.profiles%rowtype;
  v_tenant public.tenants%rowtype;
  v_instance_name text := pg_catalog.btrim(
    coalesce(p_provider_instance_name, '')
  );
  v_expected_destination text :=
    private.normalize_notification_destination(p_expected_destination);
  v_provider_destination text :=
    private.normalize_notification_destination(p_provider_destination);
  v_expected_message text := coalesce(p_expected_message_body, '');
  v_current_destination text;
  v_current_message text;
  v_kind text;
  v_source_type text;
  v_ref_date date;
  v_start_at timestamptz;
  v_class_time text;
  v_teacher_id uuid;
  v_student_id uuid;
  v_student_name text;
  v_class_link text;
  v_subject_id text;
  v_conflict_canonical_id uuid;
  v_is_conflict_replay boolean := false;
  v_receipt_id uuid;
  v_queue_result jsonb;
begin
  if p_notification_id is null
     or p_claim_token is null
     or p_integration_id is null
     or coalesce(p_integration_version, 0) < 1
     or v_expected_destination is null
     or v_provider_destination is null
     or char_length(v_expected_message) not between 1 and 4096
     or v_expected_message <> pg_catalog.btrim(v_expected_message)
     or (
       v_expected_destination like '%@g.us'
       and v_provider_destination <> v_expected_destination
     )
     or (
       v_expected_destination not like '%@g.us'
       and not private.notification_phones_same_recipient(
         v_expected_destination,
         v_provider_destination
       )
     )
     or char_length(v_instance_name) not between 3 and 120
     or v_instance_name <> pg_catalog.btrim(v_instance_name)
     or v_instance_name ~ '[[:cntrl:]]' then
    raise exception 'invalid_notification_delivery_submission'
      using errcode = '22023';
  end if;

  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id
  for update;

  if not found
     or v_notification.claim_token is distinct from p_claim_token
     or v_notification.status <> 'processing' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'notification_delivery_claim_lost'
    );
  end if;

  v_kind := upper(pg_catalog.btrim(coalesce(
    v_notification.notification_kind,
    ''
  )));

  -- Payment confirmations are always paired with the financial outbound
  -- ledger. This guard must precede the idempotent generic replay too: a
  -- payment already in SUBMITTING is still not a generic authorization.
  if private.canonical_payment_notification_kind(v_kind) =
      'PAYMENT_CONFIRMED_WHATSAPP' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'USE_PAYMENT_BRIDGE',
      'reason', 'payment_confirmation_requires_paired_submission'
    );
  end if;

  -- Idempotent replay for a lost RPC response. The same claim and exact sealed
  -- snapshot may receive the same authorization again; no second receipt is
  -- created and no different destination/message can be substituted.
  if v_notification.delivery_status = 'submitting' then
    if lower(coalesce(v_notification.provider_instance_name, '')) =
         lower(v_instance_name)
       and v_notification.lease_expires_at > now()
       and v_notification.provider_integration_id = p_integration_id
       and v_notification.provider_integration_version =
         p_integration_version
       and v_notification.provider_destination = v_provider_destination
       and v_notification.student_phone = v_expected_destination
       and v_notification.message_body = v_expected_message
       and (
         v_kind <> 'LESSON_REMINDER'
         or exists (
           select 1
           from public.automation_sent as receipt
           where receipt.notification_id = v_notification.id
             and receipt.notification_claim_token = p_claim_token
             and receipt.receipt_state = 'SEALED'
         )
       ) then
      if v_kind = 'CONFLICT_TEACHER_ALERT' then
        -- A lost begin response is not authority to send a conflict that was
        -- resolved before the replay. Re-run the locked source authorization.
        v_is_conflict_replay := true;
      else
        return pg_catalog.jsonb_build_object(
          'ok', true,
          'action', 'SUBMIT_AUTHORIZED',
          'notificationId', v_notification.id,
          'providerDestination', v_notification.provider_destination,
          'messageBody', v_notification.message_body
        );
      end if;
    else
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'notification_submitting_snapshot_mismatch'
      );
    end if;
  end if;

  if not v_is_conflict_replay
     and v_notification.delivery_status <> 'preparing' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'notification_delivery_claim_lost'
    );
  end if;

  if not v_is_conflict_replay
     and v_notification.lease_expires_at <= now() then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'notification_delivery_claim_expired'
    );
  end if;

  select instance.*
  into v_instance
  from public.whatsapp_instances as instance
  where instance.tenant_id = v_notification.tenant_id
    and lower(instance.instance_name) = lower(v_instance_name)
  for share;

  select connection.*
  into v_connection
  from private.tenant_integration_connections as connection
  where connection.id = p_integration_id
    and connection.tenant_id = v_notification.tenant_id
    and connection.provider = 'evolution'
  for share;

  if v_instance.id is null
     or lower(pg_catalog.btrim(coalesce(v_instance.status, ''))) not in (
       'connected', 'open'
     )
     or v_instance.integration_id is distinct from p_integration_id
     or v_instance.integration_version is distinct from p_integration_version
     or v_connection.id is null
     or v_connection.version is distinct from p_integration_version
     or v_connection.mode = 'DISABLED'
     or v_connection.status <> 'healthy' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'notification_provider_binding_changed'
    );
  end if;

  if v_kind = 'LESSON_REMINDER' then
    v_source_type := upper(pg_catalog.btrim(coalesce(
      v_notification.source_type,
      ''
    )));
    if v_notification.tenant_id is null
       or v_notification.source_id is null
       or v_source_type not in ('BOOKING', 'RESCHEDULE', 'APPOINTMENT')
       or v_notification.class_date is null then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'invalid_occurrence_identity'
      );
    end if;

    if v_source_type = 'BOOKING' then
      select booking.*
      into v_booking
      from public.bookings as booking
      where booking.id = v_notification.source_id
        and booking.tenant_id = v_notification.tenant_id
      for share;

      if not found
         or upper(pg_catalog.btrim(coalesce(v_booking.status, ''))) <>
           'SCHEDULED'
         or v_booking.teacher_id is null
         or v_booking.student_id is null
         or pg_catalog.btrim(coalesce(v_booking.time_slot, '')) !~
           '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
         or not (
           (
             v_booking.date is not null
             and v_booking.date = v_notification.class_date
           )
           or (
             v_booking.date is null
             and (
               v_booking.start_date is null
               or v_booking.start_date <= v_notification.class_date
             )
             and public.dow_name_to_int(v_booking.day_of_week) =
               extract(dow from v_notification.class_date)::integer
           )
         ) then
        return pg_catalog.jsonb_build_object(
          'ok', false,
          'action', 'REVIEW_REQUIRED',
          'reason', 'booking_occurrence_changed'
        );
      end if;

      v_ref_date := v_notification.class_date;
      v_class_time := pg_catalog.left(
        pg_catalog.btrim(v_booking.time_slot),
        5
      );
      v_start_at := (
        v_ref_date::text || ' ' || v_class_time
      )::timestamp at time zone 'America/Sao_Paulo';
      v_teacher_id := v_booking.teacher_id;
      v_student_id := v_booking.student_id;
    elsif v_source_type = 'RESCHEDULE' then
      select reschedule.*
      into v_reschedule
      from public.reschedules as reschedule
      where reschedule.id = v_notification.source_id
        and reschedule.tenant_id = v_notification.tenant_id
      for share;

      if not found
         or v_reschedule.used_at is not null
         or pg_catalog.btrim(coalesce(v_reschedule.date, '')) !~
           '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
         or v_reschedule.date::date <> v_notification.class_date
         or pg_catalog.btrim(coalesce(v_reschedule.time, '')) !~
           '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
         or v_reschedule.teacher_id is null
         or v_reschedule.student_id is null
         or coalesce(v_reschedule.notification_revision, 0) < 1 then
        return pg_catalog.jsonb_build_object(
          'ok', false,
          'action', 'REVIEW_REQUIRED',
          'reason', 'reschedule_occurrence_changed'
        );
      end if;

      v_ref_date := v_notification.class_date;
      v_class_time := pg_catalog.left(
        pg_catalog.btrim(v_reschedule.time),
        5
      );
      v_start_at := (
        v_ref_date::text || ' ' || v_class_time
      )::timestamp at time zone 'America/Sao_Paulo';
      v_teacher_id := v_reschedule.teacher_id;
      v_student_id := v_reschedule.student_id;
    else
      select appointment.*
      into v_appointment
      from public.appointments as appointment
      where appointment.id = v_notification.source_id
        and appointment.tenant_id = v_notification.tenant_id
      for share;

      if not found
         or lower(pg_catalog.btrim(coalesce(v_appointment.status, ''))) <>
           'scheduled'
         or v_appointment.start_time is null
         or coalesce(v_appointment.teacher_id, v_appointment.professor_id)
           is null
         or (
           v_appointment.teacher_id is not null
           and v_appointment.professor_id is not null
           and v_appointment.teacher_id <> v_appointment.professor_id
         ) then
        return pg_catalog.jsonb_build_object(
          'ok', false,
          'action', 'REVIEW_REQUIRED',
          'reason', 'appointment_occurrence_changed'
        );
      end if;

      v_ref_date := (
        v_appointment.start_time at time zone 'America/Sao_Paulo'
      )::date;
      if v_notification.class_date not in (
        v_ref_date,
        v_appointment.start_time::date
      ) then
        return pg_catalog.jsonb_build_object(
          'ok', false,
          'action', 'REVIEW_REQUIRED',
          'reason', 'appointment_class_date_changed'
        );
      end if;
      v_class_time := pg_catalog.to_char(
        v_appointment.start_time at time zone 'America/Sao_Paulo',
        'HH24:MI'
      );
      v_start_at := v_appointment.start_time;
      v_teacher_id := coalesce(
        v_appointment.teacher_id,
        v_appointment.professor_id
      );
      v_student_id := null;
    end if;

    if v_start_at - now() < interval '15 minutes'
       or v_start_at - now() > interval '45 minutes'
       or now() - v_notification.scheduled_for > interval '15 minutes' then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'lesson_reminder_outside_send_window'
      );
    end if;

    select profile.*
    into v_teacher
    from public.profiles as profile
    where profile.id = v_teacher_id
      and profile.tenant_id = v_notification.tenant_id
    for share;

    if not found
       or upper(pg_catalog.btrim(coalesce(v_teacher.role, ''))) <> 'TEACHER'
       or lower(pg_catalog.btrim(coalesce(
         v_teacher.lifecycle_status,
         ''
       ))) <> 'active'
       or coalesce(v_teacher.is_test_account, false)
       or coalesce(v_teacher.date_automation_enabled, false) is not true
       or not exists (
         select 1
         from public.tenant_memberships as membership
         where membership.user_id = v_teacher.id
           and membership.tenant_id = v_notification.tenant_id
           and membership.role = 'TEACHER'
           and membership.status = 'ACTIVE'
       ) then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'lesson_teacher_changed'
      );
    end if;

    v_class_link := private.safe_notification_text(
      v_teacher.meeting_link,
      300
    );
    if v_student_id is not null then
      select profile.*
      into v_student
      from public.profiles as profile
      where profile.id = v_student_id
        and profile.tenant_id = v_notification.tenant_id
      for share;

      if not found
         or upper(pg_catalog.btrim(coalesce(v_student.role, ''))) <> 'STUDENT'
         or lower(pg_catalog.btrim(coalesce(
           v_student.lifecycle_status,
           ''
         ))) <> 'active'
         or coalesce(v_student.is_test_account, false)
         or not exists (
           select 1
           from public.tenant_memberships as membership
           where membership.user_id = v_student.id
             and membership.tenant_id = v_notification.tenant_id
             and membership.role = 'STUDENT'
             and membership.status = 'ACTIVE'
         ) then
        return pg_catalog.jsonb_build_object(
          'ok', false,
          'action', 'REVIEW_REQUIRED',
          'reason', 'lesson_student_changed'
        );
      end if;

      v_student_name := private.safe_notification_text(
        v_student.full_name,
        180
      );
      v_current_destination := coalesce(
        private.normalize_notification_phone(v_student.attendance_phone),
        private.normalize_notification_phone(v_student.phone)
      );
      v_class_link := coalesce(
        nullif(private.safe_notification_text(
          v_student.meeting_link,
          300
        ), ''),
        v_class_link
      );
    else
      v_student_name := private.safe_notification_text(
        v_appointment.student_name,
        180
      );
      v_current_destination := private.normalize_notification_phone(
        v_appointment.student_phone
      );
    end if;

    select tenant.*
    into v_tenant
    from public.tenants as tenant
    where tenant.id = v_notification.tenant_id
    for share;

    if not found
       or v_student_name = ''
       or v_current_destination is null
       or private.safe_notification_text(v_teacher.full_name, 180) = ''
       or private.safe_notification_text(v_tenant.name, 180) = '' then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'lesson_canonical_payload_unavailable'
      );
    end if;

    v_current_message := private.render_lesson_notification_message(
      v_teacher.lesson_reminder_template,
      pg_catalog.split_part(v_student_name, ' ', 1),
      v_class_time,
      private.safe_notification_text(v_teacher.full_name, 180),
      private.safe_notification_text(v_tenant.name, 180),
      v_class_link
    );

    if v_current_destination <> v_expected_destination
       or not private.notification_phones_same_recipient(
         v_current_destination,
         v_provider_destination
       )
       or v_current_message is distinct from v_expected_message then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'lesson_authorized_snapshot_changed'
      );
    end if;

    v_subject_id := v_notification.tenant_id || ':' || v_source_type || ':' ||
      v_notification.source_id::text;

    insert into public.automation_sent (
      kind,
      subject_id,
      ref_date,
      notification_id,
      notification_claim_token,
      receipt_state
    ) values (
      'CLASS_REMINDER',
      v_subject_id,
      v_ref_date,
      v_notification.id,
      p_claim_token,
      'SEALED'
    )
    on conflict (kind, subject_id, ref_date) do nothing
    returning id into v_receipt_id;

    if v_receipt_id is null then
      v_queue_result := public.finalize_notification_delivery(
        v_notification.id,
        p_claim_token,
        'skipped',
        null,
        null,
        'occurrence_already_notified',
        0
      );
      if coalesce((v_queue_result ->> 'ok')::boolean, false) is not true then
        raise exception 'occurrence_duplicate_queue_finalize_failed';
      end if;
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'ALREADY_NOTIFIED',
        'reason', 'occurrence_already_notified'
      );
    end if;
  elsif v_kind = 'CONFLICT_TEACHER_ALERT' then
    v_source_type := upper(pg_catalog.btrim(coalesce(
      v_notification.source_type,
      ''
    )));
    if v_notification.tenant_id is null
       or v_notification.source_id is null
       or v_notification.class_date is null
       or v_source_type <> 'ATTENDANCE_CONFIRMATION' then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'invalid_conflict_identity'
      );
    end if;

    -- Discover the root without waiting while the queue row is locked. The
    -- pointer is re-read and compared after every authoritative row is locked.
    select coalesce(
      confirmation.canonical_confirmation_id,
      confirmation.id
    )
    into v_conflict_canonical_id
    from public.attendance_confirmations as confirmation
    where confirmation.id = v_notification.source_id;

    if not found or v_conflict_canonical_id is null then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'attendance_conflict_changed'
      );
    end if;

    -- Conflict writers lock attendance rows before touching a pending queue.
    -- NOWAIT makes this inverse queue->source authorization fail closed instead
    -- of ever participating in a lock cycle; the worker retries from PREPARING.
    begin
      select confirmation.*
      into v_conflict_canonical
      from public.attendance_confirmations as confirmation
      where confirmation.id = v_conflict_canonical_id
      for share nowait;

      select confirmation.*
      into v_conflict_requested
      from public.attendance_confirmations as confirmation
      where confirmation.id = v_notification.source_id
      for share nowait;

      perform 1
      from public.attendance_confirmations as confirmation
      where coalesce(
        confirmation.canonical_confirmation_id,
        confirmation.id
      ) = v_conflict_canonical_id
      order by confirmation.id
      for share nowait;

      if v_conflict_canonical.teacher_id is not null then
        select profile.*
        into v_teacher
        from public.profiles as profile
        where profile.id = v_conflict_canonical.teacher_id
        for share nowait;

        select membership.*
        into v_teacher_membership
        from public.tenant_memberships as membership
        where membership.user_id = v_conflict_canonical.teacher_id
          and membership.tenant_id = v_notification.tenant_id
        for share nowait;
      end if;
    exception
      when lock_not_available then
        return pg_catalog.jsonb_build_object(
          'ok', false,
          'action', 'RETRY',
          'reason', 'attendance_conflict_revalidation_busy'
        );
    end;

    if v_conflict_requested.id is null
       or v_conflict_canonical.id is null
       or coalesce(
         v_conflict_requested.canonical_confirmation_id,
         v_conflict_requested.id
       ) is distinct from v_conflict_canonical_id
       or coalesce(
         v_conflict_canonical.canonical_confirmation_id,
         v_conflict_canonical.id
       ) is distinct from v_conflict_canonical.id
       or v_conflict_requested.tenant_id is distinct from
         v_notification.tenant_id
       or v_conflict_canonical.tenant_id is distinct from
         v_notification.tenant_id
       or v_conflict_requested.class_date is distinct from
         v_notification.class_date
       or v_conflict_canonical.class_date is distinct from
         v_notification.class_date
       or v_conflict_requested.teacher_id is distinct from
         v_conflict_canonical.teacher_id
       or v_conflict_canonical.teacher_id is null
       or exists (
         select 1
         from public.attendance_confirmations as member
         where coalesce(member.canonical_confirmation_id, member.id) =
             v_conflict_canonical_id
           and (
             member.tenant_id is distinct from v_conflict_canonical.tenant_id
             or member.class_date is distinct from
               v_conflict_canonical.class_date
             or member.teacher_id is distinct from
               v_conflict_canonical.teacher_id
             or member.student_id is distinct from
               v_conflict_canonical.student_id
             or upper(pg_catalog.btrim(coalesce(member.status, ''))) <>
               'CONFLICT'
             or upper(pg_catalog.btrim(coalesce(
               member.student_response,
               ''
             ))) <> 'TEACHER_NO_SHOW'
             or member.resolved_at is not null
             or member.resolution_verdict is not null
             or member.response_editable_until is null
             or member.response_editable_until > now()
           )
       ) then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'attendance_conflict_changed'
      );
    end if;

    if v_teacher.id is null
       or v_teacher.id is distinct from v_conflict_canonical.teacher_id
       or v_teacher.tenant_id is distinct from v_notification.tenant_id
       or upper(pg_catalog.btrim(coalesce(v_teacher.role, ''))) <> 'TEACHER'
       or lower(pg_catalog.btrim(coalesce(
         v_teacher.lifecycle_status,
         ''
       ))) <> 'active'
       or v_teacher.is_test_account is distinct from false
       or v_teacher_membership.user_id is distinct from v_teacher.id
       or v_teacher_membership.tenant_id is distinct from
         v_notification.tenant_id
       or v_teacher_membership.role is distinct from 'TEACHER'
       or v_teacher_membership.status is distinct from 'ACTIVE' then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'attendance_conflict_teacher_changed'
      );
    end if;

    v_current_destination := coalesce(
      private.normalize_notification_phone(v_teacher.phone),
      private.normalize_notification_phone(v_teacher.attendance_phone)
    );
    v_current_message := private.render_conflict_teacher_alert_message(
      v_teacher.full_name,
      v_conflict_canonical.student_name,
      v_conflict_canonical.class_date,
      v_conflict_canonical.class_time
    );

    if v_current_destination is null
       or v_current_destination <> v_expected_destination
       or not private.notification_phones_same_recipient(
         v_current_destination,
         v_provider_destination
       )
       or v_current_message is distinct from v_expected_message then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'attendance_conflict_authorized_snapshot_changed'
      );
    end if;
  else
    -- Other kinds already have purpose-specific TypeScript revalidation. Bind
    -- the exact prepared snapshot so response recovery cannot substitute it.
    v_current_destination := v_expected_destination;
    v_current_message := v_expected_message;
  end if;

  if v_is_conflict_replay then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'SUBMIT_AUTHORIZED',
      'notificationId', v_notification.id,
      'providerDestination', v_notification.provider_destination,
      'messageBody', v_notification.message_body
    );
  end if;

  update public.notification_queue as notification
  set delivery_status = 'submitting',
      provider_instance_name = v_instance.instance_name,
      provider_destination = v_provider_destination,
      provider_integration_id = p_integration_id,
      provider_integration_version = p_integration_version,
      student_phone = v_current_destination,
      message_body = v_current_message,
      lease_expires_at = now() + interval '10 minutes',
      last_error = null,
      updated_at = now()
  where notification.id = v_notification.id
    and notification.status = 'processing'
    and notification.delivery_status = 'preparing'
    and notification.claim_token = p_claim_token
    and notification.lease_expires_at > now()
  returning notification.* into v_notification;

  if not found then
    raise exception 'notification_submission_transition_failed';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_AUTHORIZED',
    'notificationId', v_notification.id,
    'status', v_notification.status,
    'deliveryStatus', v_notification.delivery_status,
    'providerInstanceName', v_notification.provider_instance_name,
    'providerDestination', v_notification.provider_destination,
    'messageBody', v_notification.message_body,
    'integrationId', v_notification.provider_integration_id,
    'integrationVersion', v_notification.provider_integration_version
  );
end;
$_$;


--
-- Name: begin_payment_confirmation_delivery_submission(uuid, uuid, uuid, uuid, text, text, text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_payment_confirmation_delivery_submission(p_notification_id uuid, p_notification_claim_token uuid, p_outbound_attempt_id uuid, p_outbound_claim_token uuid, p_provider_instance_name text, p_expected_destination text, p_provider_destination text, p_integration_id uuid, p_integration_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_notification public.notification_queue%rowtype;
  v_outbound public.asaas_outbound_message_attempts%rowtype;
  v_profile public.profiles%rowtype;
  v_instance public.whatsapp_instances%rowtype;
  v_connection private.tenant_integration_connections%rowtype;
  v_instance_name text := pg_catalog.btrim(
    coalesce(p_provider_instance_name, '')
  );
  v_expected_destination text := private.normalize_notification_phone(
    p_expected_destination
  );
  v_provider_destination text := private.normalize_notification_phone(
    p_provider_destination
  );
  v_current_destination text;
  v_payment_status text;
  v_tenant_whatsapp_enabled boolean := false;
  v_student_notifications_enabled boolean := false;
  v_lifecycle_blocked boolean := false;
  v_suppression_reason text;
  v_queue_result jsonb;
begin
  if p_notification_id is null
     or p_notification_claim_token is null
     or p_outbound_attempt_id is null
     or p_outbound_claim_token is null
     or char_length(v_instance_name) not between 3 and 120
     or v_expected_destination is null
     or v_provider_destination is null
     or not private.notification_phones_same_recipient(
       v_expected_destination,
       v_provider_destination
     )
     or p_integration_id is null
     or coalesce(p_integration_version, 0) <= 0 then
    raise exception 'invalid_payment_confirmation_submission'
      using errcode = '22023';
  end if;

  -- Unlocked discovery only supplies the immutable advisory-lock scope. Every
  -- predicate is checked again after the advisory and row locks are held.
  select outbound.*
  into v_outbound
  from public.asaas_outbound_message_attempts as outbound
  where outbound.id = p_outbound_attempt_id;

  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id;

  if v_outbound.id is null or v_notification.id is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'claim_lost'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || v_outbound.tenant_id || ':' ||
      v_outbound.student_id::text,
      0
    )
  );

  -- Canonical lock order for this bridge: student advisory, financial row,
  -- queue row, then the mutable source/profile/configuration rows.
  select outbound.*
  into v_outbound
  from public.asaas_outbound_message_attempts as outbound
  where outbound.id = p_outbound_attempt_id
  for update;

  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id
  for update;

  -- Idempotent replay after a committed begin whose HTTP response was lost.
  -- Only the exact paired claim and immutable provider snapshot are allowed to
  -- receive authorization again.
  if v_outbound.id is not null
     and v_notification.id is not null
     and v_outbound.status = 'SUBMITTING'
     and v_outbound.submit_attempt_count = 1
     and v_outbound.lease_expires_at > now()
     and v_outbound.claim_token = p_outbound_claim_token
     and v_outbound.notification_queue_id = v_notification.id
     and v_notification.status = 'processing'
     and v_notification.delivery_status = 'submitting'
     and v_notification.lease_expires_at > now()
     and v_notification.claim_token = p_notification_claim_token
     and lower(coalesce(v_outbound.provider_instance_name, '')) =
       lower(v_instance_name)
     and lower(coalesce(v_notification.provider_instance_name, '')) =
       lower(v_instance_name)
     and v_outbound.provider_destination = v_provider_destination
     and v_notification.provider_destination = v_provider_destination
     and v_notification.provider_integration_id = p_integration_id
     and v_notification.provider_integration_version = p_integration_version
     and private.normalize_notification_phone(v_notification.student_phone) =
       v_expected_destination then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'SUBMITTING',
      'status', v_notification.status,
      'deliveryStatus', v_notification.delivery_status,
      'financialStatus', v_outbound.status,
      'notificationId', v_notification.id,
      'outboundAttemptId', v_outbound.id,
      'providerInstanceName', v_notification.provider_instance_name,
      'providerDestination', v_notification.provider_destination,
      'messageBody', v_notification.message_body,
      'integrationId', v_notification.provider_integration_id,
      'integrationVersion', v_notification.provider_integration_version
    );
  end if;

  if v_outbound.id is null
     or v_notification.id is null
     or v_outbound.status <> 'CLAIMED'
     or v_outbound.claim_token is distinct from p_outbound_claim_token
     or v_outbound.lease_expires_at <= now()
     or v_outbound.submit_attempt_count <> 0
     or v_notification.status <> 'processing'
     or v_notification.delivery_status <> 'preparing'
     or v_notification.claim_token is distinct from
       p_notification_claim_token
     or v_notification.lease_expires_at <= now() then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'claim_lost'
    );
  end if;

  if v_notification.tenant_id is distinct from v_outbound.tenant_id
     or v_notification.student_id is distinct from v_outbound.student_id
     or v_notification.source_id is null
     or v_notification.source_id::text is distinct from
       pg_catalog.btrim(v_outbound.provider_entity_id)
     or upper(pg_catalog.btrim(coalesce(
       v_notification.source_type,
       ''
     ))) <> 'ASAAS_PAYMENT'
     or private.canonical_payment_notification_kind(
       v_notification.notification_kind
     ) <> 'PAYMENT_CONFIRMED_WHATSAPP'
     or upper(pg_catalog.btrim(coalesce(
       v_outbound.notification_kind,
       ''
     ))) <> 'PAYMENT_CONFIRMED_WHATSAPP'
     or (
       v_outbound.notification_queue_id is not null
       and v_outbound.notification_queue_id <> v_notification.id
     )
     or (
       v_outbound.provider_instance_name is not null
       and lower(v_outbound.provider_instance_name) <>
         lower(v_instance_name)
     )
     or v_outbound.provider_message_id is not null
     or v_notification.provider_message_id is not null
     or (
       v_notification.provider_instance_name is not null
       and lower(v_notification.provider_instance_name) <>
         lower(v_instance_name)
     )
     or (
       v_notification.provider_destination is not null
       and v_notification.provider_destination <> v_provider_destination
     )
     or (
       v_outbound.provider_destination is not null
       and v_outbound.provider_destination <> v_provider_destination
     )
     or (
       v_notification.provider_integration_id is not null
       and v_notification.provider_integration_id <> p_integration_id
     )
     or (
       v_notification.provider_integration_version is not null
       and v_notification.provider_integration_version <>
         p_integration_version
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'payment_confirmation_binding_mismatch'
    );
  end if;

  select profile.*
  into v_profile
  from public.profiles as profile
  where profile.id = v_outbound.student_id
    and profile.tenant_id = v_outbound.tenant_id
  for update;

  if found then
    v_current_destination := private.normalize_notification_phone(
      case
        when v_profile.guardian_id is not null
          or nullif(pg_catalog.btrim(coalesce(v_profile.guardian_cpf, '')), '')
            is not null
          then v_profile.guardian_phone
        else v_profile.phone
      end
    );
  end if;

  v_lifecycle_blocked := v_profile.id is null
    or v_profile.role is distinct from 'STUDENT'
    or coalesce(v_profile.is_test_account, false)
    or lower(pg_catalog.btrim(coalesce(v_profile.lifecycle_status, ''))) <>
      'active'
    or (
      select count(*)
      from public.tenant_memberships as membership
      where membership.user_id = v_outbound.student_id
    ) <> 1
    or not exists (
      select 1
      from public.tenant_memberships as membership
      where membership.user_id = v_outbound.student_id
        and membership.tenant_id = v_outbound.tenant_id
        and membership.role = 'STUDENT'
        and membership.status = 'ACTIVE'
    )
    or exists (
      select 1
      from public.student_offboarding_operations as operation
      where operation.tenant_id = v_outbound.tenant_id
        and operation.student_id = v_outbound.student_id
        and operation.status in (
          'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
          'UNKNOWN', 'BLOCKED'
        )
    )
    or exists (
      select 1
      from public.student_account_deletion_claims as deletion
      where deletion.tenant_id = v_outbound.tenant_id
        and deletion.student_id = v_outbound.student_id
        and deletion.status in (
          'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
          'UNKNOWN', 'BLOCKED'
        )
    );

  select upper(pg_catalog.btrim(coalesce(payment.status, '')))
  into v_payment_status
  from public.student_payments as payment
  where payment.id::text = v_outbound.provider_entity_id
    and payment.tenant_id = v_outbound.tenant_id
    and payment.student_id = v_outbound.student_id
  for update;

  if not found then
    v_payment_status := null;
  end if;

  select coalesce(tenant.whatsapp_enabled, false)
  into v_tenant_whatsapp_enabled
  from public.tenants as tenant
  where tenant.id = v_outbound.tenant_id
  for share;

  select coalesce(settings.student_notifications_enabled, false)
  into v_student_notifications_enabled
  from public.tenant_admin_settings as settings
  where settings.tenant_id = v_outbound.tenant_id
  for share;

  select instance.*
  into v_instance
  from public.whatsapp_instances as instance
  where instance.tenant_id = v_outbound.tenant_id
    and lower(instance.instance_name) = lower(v_instance_name)
  for share;

  select connection.*
  into v_connection
  from private.tenant_integration_connections as connection
  where connection.id = p_integration_id
    and connection.tenant_id = v_outbound.tenant_id
    and connection.provider = 'evolution'
  for share;

  if v_instance.id is null
     or lower(pg_catalog.btrim(coalesce(v_instance.status, ''))) not in (
       'connected', 'open'
     )
     or v_instance.integration_id is distinct from p_integration_id
     or v_instance.integration_version is distinct from
       p_integration_version
     or v_connection.id is null
     or v_connection.version is distinct from p_integration_version
     or v_connection.mode = 'DISABLED'
     or v_connection.status <> 'healthy' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'payment_confirmation_provider_binding_changed'
    );
  end if;

  v_suppression_reason := case
    when v_lifecycle_blocked then 'student_lifecycle_inactive_before_send'
    when private.normalize_notification_phone(v_notification.student_phone)
      is distinct from v_expected_destination
      or v_current_destination is distinct from v_expected_destination
      then 'payment_confirmation_destination_changed'
    when coalesce(v_payment_status, '') not in (
      'RECEIVED', 'RECEIVED_IN_CASH', 'PAGO'
    )
      then 'payment_state_changed_before_notification_send'
    when not coalesce(v_tenant_whatsapp_enabled, false)
      or not coalesce(v_student_notifications_enabled, false)
      then 'student_notifications_disabled_before_send'
    else null
  end;

  if v_suppression_reason is not null then
    v_queue_result := public.finalize_notification_delivery(
      v_notification.id,
      p_notification_claim_token,
      'skipped',
      null,
      null,
      v_suppression_reason,
      0
    );

    if coalesce((v_queue_result ->> 'ok')::boolean, false) is not true then
      raise exception 'payment_confirmation_queue_suppression_failed';
    end if;

    update public.asaas_outbound_message_attempts as outbound
    set notification_queue_id = v_notification.id,
        status = 'SUPPRESSED',
        lease_expires_at = now(),
        last_error = v_suppression_reason,
        updated_at = now()
    where outbound.id = v_outbound.id
      and outbound.status = 'CLAIMED'
      and outbound.claim_token = p_outbound_claim_token
      and outbound.submit_attempt_count = 0
    returning outbound.* into v_outbound;

    if not found then
      raise exception 'payment_confirmation_ledger_suppression_failed';
    end if;

    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'reason', v_suppression_reason,
      'status', v_outbound.status,
      'notificationStatus', v_queue_result ->> 'status'
    );
  end if;

  update public.asaas_outbound_message_attempts as outbound
  set notification_queue_id = v_notification.id,
      provider_instance_name = v_instance.instance_name,
      provider_destination = v_provider_destination,
      status = 'SUBMITTING',
      submit_attempt_count = 1,
      lease_expires_at = now() + interval '10 minutes',
      last_error = null,
      updated_at = now()
  where outbound.id = v_outbound.id
    and outbound.status = 'CLAIMED'
    and outbound.claim_token = p_outbound_claim_token
    and outbound.lease_expires_at > now()
    and outbound.submit_attempt_count = 0
  returning outbound.* into v_outbound;

  if not found then
    raise exception 'payment_confirmation_outbound_transition_failed';
  end if;

  update public.notification_queue as notification
  set delivery_status = 'submitting',
      provider_instance_name = v_instance.instance_name,
      provider_destination = v_provider_destination,
      provider_integration_id = p_integration_id,
      provider_integration_version = p_integration_version,
      lease_expires_at = now() + interval '10 minutes',
      last_error = null,
      updated_at = now()
  where notification.id = v_notification.id
    and notification.status = 'processing'
    and notification.delivery_status = 'preparing'
    and notification.claim_token = p_notification_claim_token
    and notification.lease_expires_at > now()
  returning notification.* into v_notification;

  if not found then
    raise exception 'payment_confirmation_queue_transition_failed';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SUBMITTING',
    'status', v_notification.status,
    'deliveryStatus', v_notification.delivery_status,
    'financialStatus', v_outbound.status,
    'notificationId', v_notification.id,
    'outboundAttemptId', v_outbound.id,
    'providerInstanceName', v_notification.provider_instance_name,
    'providerDestination', v_notification.provider_destination,
    'messageBody', v_notification.message_body,
    'integrationId', v_notification.provider_integration_id,
    'integrationVersion', v_notification.provider_integration_version
  );
end;
$$;


--
-- Name: begin_sdr_effects(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_sdr_effects(p_tenant_id text, p_phone text, p_token uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  update public.sdr_conversation_work set phase='APPLYING',lease_until=now()+interval '10 minutes',updated_at=now()
  where tenant_id=p_tenant_id and phone=p_phone and lease_token=p_token and lease_until>now()
    and phase='GENERATING' and latest_msg_id=claimed_msg_id;
  return found;
end;
$$;


--
-- Name: begin_student_account_deletion(text, uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_student_account_deletion(p_tenant_id text, p_student_id uuid, p_requested_by uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  profile_row public.profiles%rowtype;
  claim_row public.student_account_deletion_claims%rowtype;
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  billing_cpf text;
  cpf_hash text;
  safe_lease integer := greatest(60, least(coalesce(p_lease_seconds, 300), 600));
  retry_after integer;
  action text;
begin
  if normalized_tenant is null or p_student_id is null or p_claim_token is null then
    raise exception using errcode = '22023', message = 'invalid_student_deletion_claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' || p_student_id::text,
      0
    )
  );

  select deletion.* into claim_row
    from public.student_account_deletion_claims as deletion
   where deletion.student_id = p_student_id
   for update;

  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_student_id
   for update;
  if not found then
    if claim_row.id is null
       or claim_row.tenant_id is distinct from normalized_tenant
       or claim_row.status not in ('PROVIDER_COMPLETE', 'COMPLETED')
    then
      return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'profile_missing_before_provider_complete');
    end if;
    if claim_row.status = 'COMPLETED' then
      return jsonb_build_object('ok', true, 'action', 'ALREADY_COMPLETED', 'claim_id', claim_row.id);
    end if;
    update public.student_account_deletion_claims
       set claim_token = p_claim_token,
           requested_by = p_requested_by,
           lease_expires_at = now() + make_interval(secs => safe_lease),
           updated_at = now()
     where id = claim_row.id
     returning * into claim_row;
    return jsonb_build_object(
      'ok', true,
      'action', 'FINALIZE_REQUIRED',
      'claim_id', claim_row.id,
      'claim_token', claim_row.claim_token,
      'tenant_id', claim_row.tenant_id,
      'student_id', claim_row.student_id,
      'customer_id', claim_row.customer_id,
      'subscription_id', claim_row.subscription_id,
      'subscription_deleted', claim_row.subscription_deleted,
      'customer_deleted', claim_row.customer_deleted
    );
  end if;
  if profile_row.tenant_id is distinct from normalized_tenant
     or profile_row.role is distinct from 'STUDENT'
     or lower(trim(coalesce(profile_row.lifecycle_status, ''))) <> 'active'
     or profile_row.is_test_account is not true
  then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'profile_not_deletable');
  end if;

  if (
    select count(*)
      from public.tenant_memberships as membership
     where membership.user_id = p_student_id
  ) <> 1 or not exists (
    select 1
      from public.tenant_memberships as membership
     where membership.user_id = p_student_id
       and membership.tenant_id = normalized_tenant
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'membership_scope_changed');
  end if;
  if exists (
    select 1
      from public.asaas_student_billing_period_claims as billing_claim
     where billing_claim.tenant_id = normalized_tenant
       and billing_claim.student_id = p_student_id
       and billing_claim.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN')
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'billing_creation_in_flight');
  end if;
  if exists (
    select 1
      from public.asaas_provider_creation_attempts as creation
     where creation.tenant_id = normalized_tenant
       and creation.lifecycle_student_id = p_student_id
       and creation.lifecycle_released_at is null
       and creation.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN', 'SUCCEEDED', 'BLOCKED')
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'provider_creation_in_flight');
  end if;
  if exists (
    select 1
      from public.student_overdue_card_charge_claims as charge
     where charge.tenant_id = normalized_tenant
       and charge.student_id = p_student_id
       and (
         charge.status in ('SUBMITTING', 'UNKNOWN')
         or (charge.status = 'PROCESSING' and charge.lease_expires_at > now())
         or (
           charge.status = 'SUCCEEDED'
           and not exists (
             select 1 from public.student_payments as payment
              where payment.tenant_id = normalized_tenant
                and payment.student_id = p_student_id
                and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = charge.asaas_payment_id
                and upper(trim(coalesce(payment.status, ''))) in ('RECEIVED', 'RECEIVED_IN_CASH')
           )
         )
       )
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'overdue_charge_in_flight');
  end if;
  if exists (
    select 1 from public.student_billing_method_operations as billing_method
     where billing_method.tenant_id = normalized_tenant
       and billing_method.student_id = p_student_id
       and billing_method.status in ('CLAIMED', 'MUTATING', 'UNKNOWN', 'BLOCKED')
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'billing_method_mutation_in_flight');
  end if;
  update public.asaas_outbound_message_attempts
     set status = 'SUPPRESSED',
         lease_expires_at = now(),
         last_error = 'student_deletion_requested_before_send',
         updated_at = now()
   where tenant_id = normalized_tenant
     and student_id = p_student_id
     and status = 'CLAIMED'
     and submit_attempt_count = 0;
  if exists (
    select 1 from public.asaas_outbound_message_attempts as message_attempt
     where message_attempt.tenant_id = normalized_tenant
       and message_attempt.student_id = p_student_id
       and message_attempt.status in ('SUBMITTING', 'UNKNOWN')
  ) then
    return jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'outbound_message_in_flight'
    );
  end if;

  billing_cpf := regexp_replace(
    case
      when profile_row.guardian_id is not null
        or nullif(trim(coalesce(profile_row.guardian_cpf, '')), '') is not null
        then coalesce(profile_row.guardian_cpf, '')
      else coalesce(profile_row.cpf, '')
    end,
    '[^0-9]', '', 'g'
  );
  if length(billing_cpf) <> 11 then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'billing_cpf_invalid');
  end if;
  cpf_hash := encode(extensions.digest(pg_catalog.convert_to(billing_cpf, 'UTF8'), 'sha256'), 'hex');

  insert into public.student_account_deletion_claims (
    tenant_id, student_id, requested_by, status, claim_token,
    lease_expires_at, customer_id, subscription_id, billing_cpf_hash,
    snapshot, subscription_deleted, customer_deleted
  ) values (
    normalized_tenant, p_student_id, p_requested_by, 'CLAIMED', p_claim_token,
    now() + make_interval(secs => safe_lease),
    nullif(trim(coalesce(profile_row.asaas_customer_id, '')), ''),
    nullif(trim(coalesce(profile_row.subscription_id, '')), ''),
    cpf_hash,
    jsonb_build_object(
      'tenant_id', normalized_tenant,
      'student_id', p_student_id,
      'role', profile_row.role,
      'lifecycle_status', profile_row.lifecycle_status,
      'is_test_account', profile_row.is_test_account,
      'customer_id', nullif(trim(coalesce(profile_row.asaas_customer_id, '')), ''),
      'subscription_id', nullif(trim(coalesce(profile_row.subscription_id, '')), ''),
      'billing_cpf_hash', cpf_hash
    ),
    nullif(trim(coalesce(profile_row.subscription_id, '')), '') is null,
    nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '') is null
  ) on conflict (student_id) do nothing;

  select deletion.* into claim_row
    from public.student_account_deletion_claims as deletion
   where deletion.student_id = p_student_id
   for update;

  if claim_row.tenant_id is distinct from normalized_tenant
     or claim_row.customer_id is distinct from nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
     or claim_row.subscription_id is distinct from nullif(trim(coalesce(profile_row.subscription_id, '')), '')
     or claim_row.billing_cpf_hash is distinct from cpf_hash
  then
    update public.student_account_deletion_claims
       set status = 'BLOCKED', last_error = 'deletion_snapshot_mismatch', updated_at = now()
     where id = claim_row.id and status <> 'COMPLETED';
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'snapshot_mismatch', 'claim_id', claim_row.id);
  end if;

  if claim_row.status = 'COMPLETED' then
    return jsonb_build_object('ok', true, 'action', 'ALREADY_COMPLETED', 'claim_id', claim_row.id);
  end if;
  if claim_row.status = 'BLOCKED' then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'claim_id', claim_row.id);
  end if;
  if claim_row.status = 'CLAIMED'
     and claim_row.claim_token <> p_claim_token
     and claim_row.lease_expires_at > now()
  then
    retry_after := greatest(1, ceil(extract(epoch from (claim_row.lease_expires_at - now())))::integer);
    return jsonb_build_object('ok', true, 'action', 'IN_PROGRESS', 'claim_id', claim_row.id, 'retry_after_seconds', retry_after);
  end if;

  action := case
    when claim_row.status in ('PROVIDER_MUTATING', 'UNKNOWN') then 'RECONCILE_REQUIRED'
    when claim_row.status = 'PROVIDER_COMPLETE' then 'FINALIZE_REQUIRED'
    else 'PROCEED'
  end;
  update public.student_account_deletion_claims
     set claim_token = p_claim_token,
         requested_by = p_requested_by,
         lease_expires_at = now() + make_interval(secs => safe_lease),
         updated_at = now()
   where id = claim_row.id
   returning * into claim_row;

  return jsonb_build_object(
    'ok', true,
    'action', action,
    'claim_id', claim_row.id,
    'claim_token', claim_row.claim_token,
    'tenant_id', claim_row.tenant_id,
    'student_id', claim_row.student_id,
    'customer_id', claim_row.customer_id,
    'subscription_id', claim_row.subscription_id,
    'billing_cpf', billing_cpf,
    'subscription_deleted', claim_row.subscription_deleted,
    'customer_deleted', claim_row.customer_deleted
  );
end;
$$;


--
-- Name: begin_student_billing_method_operation(text, uuid, uuid, text, text, text, text, text, text, integer, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_student_billing_method_operation(p_tenant_id text, p_student_id uuid, p_requested_by uuid, p_customer_id text, p_subscription_id text, p_source_billing_type text, p_target_billing_type text, p_card_last4 text, p_integration_id text, p_integration_version integer, p_integration_environment text, p_integration_mode text, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  operation_row public.student_billing_method_operations%rowtype;
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  normalized_customer text := nullif(trim(coalesce(p_customer_id, '')), '');
  normalized_subscription text := nullif(trim(coalesce(p_subscription_id, '')), '');
  normalized_source text := upper(trim(coalesce(p_source_billing_type, '')));
  normalized_target text := upper(trim(coalesce(p_target_billing_type, '')));
  normalized_last4 text := nullif(regexp_replace(coalesce(p_card_last4, ''), '[^0-9]', '', 'g'), '');
  normalized_integration_id text := nullif(trim(coalesce(p_integration_id, '')), '');
  normalized_integration_environment text := lower(trim(coalesce(p_integration_environment, '')));
  normalized_integration_mode text := upper(trim(coalesce(p_integration_mode, '')));
  expected_integration_snapshot jsonb;
  safe_lease integer := greatest(60, least(coalesce(p_lease_seconds, 300), 600));
  retry_after integer;
begin
  if normalized_tenant is null or p_student_id is null or p_claim_token is null
     or normalized_customer is null or normalized_subscription is null
     or normalized_source not in ('PIX', 'BOLETO', 'CREDIT_CARD')
     or normalized_target not in ('PIX', 'BOLETO', 'CREDIT_CARD')
     or (normalized_target = 'CREDIT_CARD' and normalized_last4 !~ '^[0-9]{4}$')
     or (normalized_target <> 'CREDIT_CARD' and normalized_last4 is not null)
     or normalized_integration_id is null
     or coalesce(p_integration_version, 0) < 1
     or normalized_integration_environment not in ('platform', 'production', 'sandbox')
     or normalized_integration_mode not in ('PLATFORM_MANAGED_ROOT', 'PLATFORM_MANAGED_SUBACCOUNT', 'TENANT_BYOK')
  then
    raise exception using errcode = '22023', message = 'invalid_student_billing_method_operation';
  end if;
  expected_integration_snapshot := jsonb_build_object(
    'integration_id', normalized_integration_id,
    'version', p_integration_version,
    'environment', normalized_integration_environment,
    'mode', normalized_integration_mode
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' || p_student_id::text,
      0
    )
  );

  if not exists (
    select 1 from public.profiles as profile
     where profile.id = p_student_id
       and profile.tenant_id = normalized_tenant
       and profile.role = 'STUDENT'
       and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
       and nullif(trim(coalesce(profile.asaas_customer_id, '')), '') = normalized_customer
       and nullif(trim(coalesce(profile.subscription_id, '')), '') = normalized_subscription
  ) or (
    select count(*) from public.tenant_memberships as membership
     where membership.user_id = p_student_id
  ) <> 1 or not exists (
    select 1 from public.tenant_memberships as membership
     where membership.user_id = p_student_id
       and membership.tenant_id = normalized_tenant
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'student_lifecycle_inactive');
  end if;

  if exists (
    select 1 from public.student_offboarding_operations as offboarding
     where offboarding.tenant_id = normalized_tenant
       and offboarding.student_id = p_student_id
       and offboarding.status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
  ) or exists (
    select 1 from public.student_account_deletion_claims as deletion
     where deletion.tenant_id = normalized_tenant
       and deletion.student_id = p_student_id
       and deletion.status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'lifecycle_operation_active');
  end if;
  if exists (
    select 1 from public.asaas_provider_creation_attempts as creation
     where creation.tenant_id = normalized_tenant
       and creation.lifecycle_student_id = p_student_id
       and creation.lifecycle_released_at is null
       and creation.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN', 'SUCCEEDED', 'BLOCKED')
  ) or exists (
    select 1 from public.asaas_student_billing_period_claims as billing
     where billing.tenant_id = normalized_tenant
       and billing.student_id = p_student_id
       and billing.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN')
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'billing_creation_in_flight');
  end if;
  if exists (
    select 1 from public.student_overdue_card_charge_claims as charge
     where charge.tenant_id = normalized_tenant
       and charge.student_id = p_student_id
       and (
         charge.status in ('SUBMITTING', 'UNKNOWN')
         or (charge.status = 'PROCESSING' and charge.lease_expires_at > now())
         or (
           charge.status = 'SUCCEEDED'
           and not exists (
             select 1 from public.student_payments as payment
              where payment.tenant_id = normalized_tenant
                and payment.student_id = p_student_id
                and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = charge.asaas_payment_id
                and upper(trim(coalesce(payment.status, ''))) in ('RECEIVED', 'RECEIVED_IN_CASH')
           )
         )
       )
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'overdue_charge_in_flight');
  end if;

  select operation.* into operation_row
    from public.student_billing_method_operations as operation
   where operation.tenant_id = normalized_tenant
     and operation.student_id = p_student_id
     and operation.status in ('CLAIMED', 'MUTATING', 'UNKNOWN', 'BLOCKED')
   for update;

  if not found then
    insert into public.student_billing_method_operations (
      tenant_id, student_id, requested_by, customer_id, subscription_id,
      source_billing_type, target_billing_type, card_last4,
      integration_snapshot, status,
      claim_token, lease_expires_at
    ) values (
      normalized_tenant, p_student_id, p_requested_by, normalized_customer,
      normalized_subscription, normalized_source, normalized_target,
      normalized_last4, expected_integration_snapshot, 'CLAIMED', p_claim_token,
      now() + make_interval(secs => safe_lease)
    ) returning * into operation_row;
    return jsonb_build_object(
      'ok', true,
      'action', 'SUBMIT_ONCE',
      'operation_id', operation_row.id,
      'claim_token', operation_row.claim_token,
      'target_billing_type', operation_row.target_billing_type,
      'card_last4', operation_row.card_last4
    );
  end if;

  if operation_row.customer_id is distinct from normalized_customer
     or operation_row.subscription_id is distinct from normalized_subscription
     or operation_row.target_billing_type is distinct from normalized_target
     or operation_row.card_last4 is distinct from normalized_last4
     or operation_row.integration_snapshot is distinct from expected_integration_snapshot
  then
    update public.student_billing_method_operations
       set status = 'BLOCKED',
           last_error = 'billing_method_binding_mismatch',
           lease_expires_at = now(),
           updated_at = now()
     where id = operation_row.id;
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'binding_mismatch', 'operation_id', operation_row.id);
  end if;
  if operation_row.status = 'BLOCKED' then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', coalesce(operation_row.last_error, 'operation_blocked'), 'operation_id', operation_row.id);
  end if;
  if operation_row.status in ('CLAIMED', 'MUTATING')
     and operation_row.claim_token is distinct from p_claim_token
     and operation_row.lease_expires_at > now()
  then
    retry_after := greatest(1, ceil(extract(epoch from (operation_row.lease_expires_at - now())))::integer);
    return jsonb_build_object('ok', true, 'action', 'IN_PROGRESS', 'operation_id', operation_row.id, 'retry_after_seconds', retry_after);
  end if;

  if operation_row.status in ('MUTATING', 'UNKNOWN') then
    update public.student_billing_method_operations
       set status = 'UNKNOWN',
           requested_by = p_requested_by,
           claim_token = p_claim_token,
           lease_expires_at = now() + make_interval(secs => safe_lease),
           updated_at = now()
     where id = operation_row.id
     returning * into operation_row;
    return jsonb_build_object(
      'ok', true,
      'action', 'RECONCILE_REQUIRED',
      'operation_id', operation_row.id,
      'claim_token', operation_row.claim_token,
      'target_billing_type', operation_row.target_billing_type,
      'card_last4', operation_row.card_last4
    );
  end if;

  update public.student_billing_method_operations
     set requested_by = p_requested_by,
         claim_token = p_claim_token,
         lease_expires_at = now() + make_interval(secs => safe_lease),
         updated_at = now()
   where id = operation_row.id
     and status = 'CLAIMED'
   returning * into operation_row;
  return jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_ONCE',
    'operation_id', operation_row.id,
    'claim_token', operation_row.claim_token,
    'target_billing_type', operation_row.target_billing_type,
    'card_last4', operation_row.card_last4
  );
end;
$_$;


--
-- Name: begin_student_complementary_generation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_student_complementary_generation(p_request_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.assert_active_student_learning_mutation();
  return public.begin_student_complementary_generation_core(p_request_key);
end;
$$;


--
-- Name: begin_student_complementary_generation_core(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_student_complementary_generation_core(p_request_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_id uuid := auth.uid();
  v_profile record;
  v_existing public.student_complementary_generation_reservations%rowtype;
  v_active public.student_complementary_generation_reservations%rowtype;
  v_reservation public.student_complementary_generation_reservations%rowtype;
  v_batch public.student_generated_activity_batches%rowtype;
  v_pending_count integer;
  v_daily_count integer;
  v_activities jsonb := '[]'::jsonb;
  v_now timestamptz := pg_catalog.now();
  v_today date := (v_now at time zone 'America/Sao_Paulo')::date;
begin
  if v_student_id is null or p_request_key is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  select profile.tenant_id, profile.role
    into v_profile
    from public.profiles as profile
   where profile.id = v_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  -- The profile lock serializes tabs. Expire stale leases before inspecting the
  -- request or creating another partial-unique RESERVED row.
  update public.student_complementary_generation_reservations
     set status = 'EXPIRED',
         decision_code = 'LEASE_EXPIRED',
         completed_at = coalesce(completed_at, v_now),
         updated_at = v_now
   where student_id = v_student_id
     and status = 'RESERVED'
     and lease_expires_at <= v_now;

  select *
    into v_existing
    from public.student_complementary_generation_reservations as reservation
   where reservation.student_id = v_student_id
     and reservation.request_key = p_request_key
   for update;

  if found then
    if v_existing.status in ('RELEASED', 'EXPIRED')
       or (
         v_existing.status = 'DENIED'
         and v_existing.decision_code = 'GENERATION_IN_PROGRESS'
       ) then
      -- A provider failure or expired lease must not permanently poison the
      -- stable UI request key. If persistence actually succeeded before the
      -- response was lost, recover it as committed without paying the provider
      -- again; otherwise rotate the lease token on the same reservation row.
      select *
        into v_batch
        from public.student_generated_activity_batches as batch
       where batch.student_id = v_student_id
         and batch.tenant_id = v_profile.tenant_id
         and batch.request_key = p_request_key::text
         and coalesce((batch.result ->> 'created')::boolean, false) is true
       order by batch.created_at desc, batch.id desc
       limit 1;

      if found then
        update public.student_complementary_generation_reservations
           set status = 'COMMITTED',
               decision_code = 'COMMITTED',
               batch_id = v_batch.id,
               completed_at = coalesce(completed_at, v_now),
               updated_at = v_now
         where id = v_existing.id
        returning * into v_existing;

        return pg_catalog.jsonb_build_object(
          'allowed', false,
          'code', 'ALREADY_COMMITTED',
          'reservationId', v_existing.id,
          'leaseToken', null,
          'leaseExpiresAt', v_existing.lease_expires_at,
          'requestKey', v_existing.request_key,
          'replay', true,
          'status', v_existing.status,
          'activities', coalesce(v_batch.result -> 'activities', '[]'::jsonb)
        );
      end if;

      select pg_catalog.count(*)::integer
        into v_pending_count
        from (
          select pending.*
            from public.student_activities as pending
           where pending.student_id = v_student_id
             and pending.tenant_id = v_profile.tenant_id
             and pending.status = 'PENDING'
           order by pending.created_at desc, pending.id desc
           limit 4
        ) as activity;

      if v_pending_count > 0 then
        select coalesce(
                 pg_catalog.jsonb_agg(
                   (
                     pg_catalog.to_jsonb(activity) - 'content'
                   ) || pg_catalog.jsonb_build_object(
                     'content', private.safe_student_complementary_content(
                       activity.type,
                       activity.content
                     )
                   )
                   order by activity.created_at desc, activity.id desc
                 ),
                 '[]'::jsonb
               )
          into v_activities
          from (
            select pending.*
              from public.student_activities as pending
             where pending.student_id = v_student_id
               and pending.tenant_id = v_profile.tenant_id
               and pending.status = 'PENDING'
             order by pending.created_at desc, pending.id desc
             limit 4
          ) as activity;

        return pg_catalog.jsonb_build_object(
          'allowed', false,
          'code', 'PENDING_PACKAGE',
          'reservationId', v_existing.id,
          'leaseToken', null,
          'leaseExpiresAt', null,
          'requestKey', v_existing.request_key,
          'replay', true,
          'status', v_existing.status,
          'activities', v_activities
        );
      end if;

      select *
        into v_active
        from public.student_complementary_generation_reservations as reservation
       where reservation.student_id = v_student_id
         and reservation.status = 'RESERVED'
         and reservation.id <> v_existing.id
       limit 1;

      if found then
        return pg_catalog.jsonb_build_object(
          'allowed', false,
          'code', 'GENERATION_IN_PROGRESS',
          'reservationId', v_existing.id,
          'leaseToken', null,
          'leaseExpiresAt', v_active.lease_expires_at,
          'requestKey', v_existing.request_key,
          'replay', true,
          'status', v_existing.status,
          'activities', '[]'::jsonb
        );
      end if;

      -- A denied second-tab request has not consumed a generation slot yet.
      -- Reusing that key may start work only if today's cost fence still has
      -- room. Released/expired requests already occupy their original slot.
      if v_existing.status = 'DENIED' then
        select pg_catalog.count(*)::integer
          into v_daily_count
          from public.student_complementary_generation_reservations as reservation
         where reservation.student_id = v_student_id
           and reservation.status in (
             'RESERVED',
             'COMMITTED',
             'RELEASED',
             'EXPIRED'
           )
           and (
             reservation.created_at at time zone 'America/Sao_Paulo'
           )::date = v_today;

        if v_daily_count >= 3 then
          update public.student_complementary_generation_reservations
             set decision_code = 'DAILY_LIMIT_REACHED',
                 completed_at = coalesce(completed_at, v_now),
                 updated_at = v_now
           where id = v_existing.id
          returning * into v_existing;

          return pg_catalog.jsonb_build_object(
            'allowed', false,
            'code', 'DAILY_LIMIT_REACHED',
            'reservationId', v_existing.id,
            'leaseToken', null,
            'leaseExpiresAt', null,
            'requestKey', v_existing.request_key,
            'replay', true,
            'status', v_existing.status,
            'activities', '[]'::jsonb
          );
        end if;
      end if;

      update public.student_complementary_generation_reservations
         set lease_token = pg_catalog.gen_random_uuid(),
             status = 'RESERVED',
             decision_code = 'RESERVED',
             lease_expires_at = v_now + interval '5 minutes',
             batch_id = null,
             failure_reason = null,
             completed_at = null,
             created_at = case
               when v_existing.status = 'DENIED' then v_now
               else created_at
             end,
             updated_at = v_now
       where id = v_existing.id
      returning * into v_existing;

      return pg_catalog.jsonb_build_object(
        'allowed', true,
        'code', 'RESERVED',
        'reservationId', v_existing.id,
        'leaseToken', v_existing.lease_token,
        'leaseExpiresAt', v_existing.lease_expires_at,
        'requestKey', v_existing.request_key,
        'replay', true,
        'status', v_existing.status,
        'activities', '[]'::jsonb
      );
    end if;

    -- Replaying a still-active key must never hand the lease token to a second
    -- provider invocation. The original Edge request owns the only active run.
    if v_existing.status = 'RESERVED' then
      return pg_catalog.jsonb_build_object(
        'allowed', false,
        'code', 'GENERATION_IN_PROGRESS',
        'reservationId', v_existing.id,
        'leaseToken', null,
        'leaseExpiresAt', v_existing.lease_expires_at,
        'requestKey', v_existing.request_key,
        'replay', true,
        'status', v_existing.status,
        'activities', '[]'::jsonb
      );
    end if;

    if v_existing.status = 'COMMITTED' and v_existing.batch_id is not null then
      select coalesce(batch.result -> 'activities', '[]'::jsonb)
        into v_activities
        from public.student_generated_activity_batches as batch
       where batch.id = v_existing.batch_id
         and batch.student_id = v_student_id;
    elsif v_existing.decision_code = 'PENDING_PACKAGE' then
      select coalesce(
               pg_catalog.jsonb_agg(
                 (
                   pg_catalog.to_jsonb(activity) - 'content'
                 ) || pg_catalog.jsonb_build_object(
                   'content', private.safe_student_complementary_content(
                     activity.type,
                     activity.content
                   )
                 )
                 order by activity.created_at desc, activity.id desc
               ),
               '[]'::jsonb
             )
        into v_activities
        from (
          select pending.*
            from public.student_activities as pending
           where pending.student_id = v_student_id
             and pending.tenant_id = v_profile.tenant_id
             and pending.status = 'PENDING'
           order by pending.created_at desc, pending.id desc
           limit 4
        ) as activity;
    end if;

    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', case
        when v_existing.status = 'COMMITTED' then 'ALREADY_COMMITTED'
        else v_existing.decision_code
      end,
      'reservationId', v_existing.id,
      'leaseToken', case
        when v_existing.status = 'RESERVED' then v_existing.lease_token
        else null
      end,
      'leaseExpiresAt', v_existing.lease_expires_at,
      'requestKey', v_existing.request_key,
      'replay', true,
      'status', v_existing.status,
      'activities', v_activities
    );
  end if;

  select pg_catalog.count(*)::integer
    into v_pending_count
    from public.student_activities as activity
   where activity.student_id = v_student_id
     and activity.tenant_id = v_profile.tenant_id
     and activity.status = 'PENDING';

  if v_pending_count > 0 then
    select coalesce(
             pg_catalog.jsonb_agg(
               (
                 pg_catalog.to_jsonb(activity) - 'content'
               ) || pg_catalog.jsonb_build_object(
                 'content', private.safe_student_complementary_content(
                   activity.type,
                   activity.content
                 )
               )
               order by activity.created_at desc, activity.id desc
             ),
             '[]'::jsonb
           )
      into v_activities
      from (
        select pending.*
          from public.student_activities as pending
         where pending.student_id = v_student_id
           and pending.tenant_id = v_profile.tenant_id
           and pending.status = 'PENDING'
         order by pending.created_at desc, pending.id desc
         limit 4
      ) as activity;

    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'PENDING_PACKAGE',
      'reservationId', null,
      'leaseToken', null,
      'leaseExpiresAt', null,
      'requestKey', p_request_key,
      'replay', false,
      'status', 'DENIED',
      'activities', v_activities
    );
  end if;

  select *
    into v_active
    from public.student_complementary_generation_reservations as reservation
   where reservation.student_id = v_student_id
     and reservation.status = 'RESERVED'
   limit 1;

  if found then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'GENERATION_IN_PROGRESS',
      'reservationId', null,
      'leaseToken', null,
      'leaseExpiresAt', v_active.lease_expires_at,
      'requestKey', p_request_key,
      'replay', false,
      'status', 'DENIED',
      'activities', '[]'::jsonb
    );
  end if;

  select pg_catalog.count(*)::integer
    into v_daily_count
    from public.student_complementary_generation_reservations as reservation
   where reservation.student_id = v_student_id
     and reservation.status in ('RESERVED', 'COMMITTED', 'RELEASED', 'EXPIRED')
     and (reservation.created_at at time zone 'America/Sao_Paulo')::date =
           v_today;

  if v_daily_count >= 3 then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'DAILY_LIMIT_REACHED',
      'reservationId', null,
      'leaseToken', null,
      'leaseExpiresAt', null,
      'requestKey', p_request_key,
      'replay', false,
      'status', 'DENIED',
      'activities', '[]'::jsonb
    );
  end if;

  insert into public.student_complementary_generation_reservations (
    tenant_id,
    student_id,
    request_key,
    lease_token,
    status,
    decision_code,
    lease_expires_at,
    created_at,
    updated_at
  ) values (
    v_profile.tenant_id,
    v_student_id,
    p_request_key,
    pg_catalog.gen_random_uuid(),
    'RESERVED',
    'RESERVED',
    v_now + interval '5 minutes',
    v_now,
    v_now
  ) returning * into v_reservation;

  return pg_catalog.jsonb_build_object(
    'allowed', true,
    'code', 'RESERVED',
    'reservationId', v_reservation.id,
    'leaseToken', v_reservation.lease_token,
    'leaseExpiresAt', v_reservation.lease_expires_at,
    'requestKey', p_request_key,
    'replay', false,
    'status', v_reservation.status,
    'activities', '[]'::jsonb
  );
end;
$$;


--
-- Name: FUNCTION begin_student_complementary_generation_core(p_request_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.begin_student_complementary_generation_core(p_request_key uuid) IS 'Reserves one five-minute generation lease, blocks duplicate tabs/pending packs and enforces a three-per-day cost fence.';


--
-- Name: begin_student_offboarding(text, uuid, uuid, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_student_offboarding(p_tenant_id text, p_student_id uuid, p_requested_by uuid, p_target_status text, p_reason text, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  profile_row public.profiles%rowtype;
  operation_row public.student_offboarding_operations%rowtype;
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  normalized_target text := lower(trim(coalesce(p_target_status, '')));
  normalized_reason text := nullif(trim(coalesce(p_reason, '')), '');
  payment_rows jsonb;
  safe_lease integer := greatest(60, least(coalesce(p_lease_seconds, 300), 600));
  retry_after integer;
  action text;
begin
  if normalized_tenant is null or p_student_id is null or p_claim_token is null
     or normalized_target not in ('suspended', 'offboarded')
  then
    raise exception using errcode = '22023', message = 'invalid_student_offboarding_claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' || p_student_id::text,
      0
    )
  );

  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_student_id
   for update;
  if not found
     or profile_row.tenant_id is distinct from normalized_tenant
     or profile_row.role is distinct from 'STUDENT'
  then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'profile_scope_changed');
  end if;
  if lower(trim(coalesce(profile_row.lifecycle_status, ''))) = normalized_target then
    return jsonb_build_object('ok', true, 'action', 'ALREADY_COMPLETED');
  end if;
  if lower(trim(coalesce(profile_row.lifecycle_status, ''))) = 'offboarded' then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'profile_already_offboarded');
  end if;

  if (
    select count(*) from public.tenant_memberships as membership
     where membership.user_id = p_student_id
  ) <> 1 or not exists (
    select 1 from public.tenant_memberships as membership
     where membership.user_id = p_student_id
       and membership.tenant_id = normalized_tenant
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'membership_scope_changed');
  end if;
  if exists (
    select 1
      from public.asaas_student_billing_period_claims as billing_claim
     where billing_claim.tenant_id = normalized_tenant
       and billing_claim.student_id = p_student_id
       and billing_claim.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN')
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'billing_creation_in_flight');
  end if;
  if exists (
    select 1
      from public.asaas_provider_creation_attempts as creation
     where creation.tenant_id = normalized_tenant
       and creation.lifecycle_student_id = p_student_id
       and creation.lifecycle_released_at is null
       and creation.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN', 'SUCCEEDED', 'BLOCKED')
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'provider_creation_in_flight');
  end if;
  if exists (
    select 1
      from public.student_overdue_card_charge_claims as charge
     where charge.tenant_id = normalized_tenant
       and charge.student_id = p_student_id
       and (
         charge.status in ('SUBMITTING', 'UNKNOWN')
         or (charge.status = 'PROCESSING' and charge.lease_expires_at > now())
         or (
           charge.status = 'SUCCEEDED'
           and not exists (
             select 1 from public.student_payments as payment
              where payment.tenant_id = normalized_tenant
                and payment.student_id = p_student_id
                and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = charge.asaas_payment_id
                and upper(trim(coalesce(payment.status, ''))) in ('RECEIVED', 'RECEIVED_IN_CASH')
           )
         )
       )
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'overdue_charge_in_flight');
  end if;
  if exists (
    select 1 from public.student_billing_method_operations as billing_method
     where billing_method.tenant_id = normalized_tenant
       and billing_method.student_id = p_student_id
       and billing_method.status in ('CLAIMED', 'MUTATING', 'UNKNOWN', 'BLOCKED')
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'billing_method_mutation_in_flight');
  end if;
  update public.asaas_outbound_message_attempts
     set status = 'SUPPRESSED',
         lease_expires_at = now(),
         last_error = 'student_offboarding_requested_before_send',
         updated_at = now()
   where tenant_id = normalized_tenant
     and student_id = p_student_id
     and status = 'CLAIMED'
     and submit_attempt_count = 0;
  if exists (
    select 1 from public.asaas_outbound_message_attempts as message_attempt
     where message_attempt.tenant_id = normalized_tenant
       and message_attempt.student_id = p_student_id
       and message_attempt.status in ('SUBMITTING', 'UNKNOWN')
  ) then
    return jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'outbound_message_in_flight'
    );
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'id', payment.id,
      'asaas_payment_id', coalesce(nullif(trim(coalesce(payment.asaas_payment_id, '')), ''), nullif(trim(coalesce(payment.asaas_id, '')), '')),
      'status', payment.status,
      'due_date', payment.due_date
    ) order by payment.id), '[]'::jsonb)
    into payment_rows
    from public.student_payments as payment
   where normalized_target = 'offboarded'
     and payment.tenant_id = normalized_tenant
     and payment.student_id = p_student_id
     and upper(coalesce(payment.status, '')) = 'PENDING'
     and payment.due_date >= current_date;

  if normalized_target = 'offboarded' and exists (
    select 1
      from public.student_payments as payment
     where payment.tenant_id = normalized_tenant
       and payment.student_id = p_student_id
       and upper(coalesce(payment.status, '')) = 'PENDING'
       and payment.due_date >= current_date
       and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') is not null
       and nullif(trim(coalesce(payment.asaas_id, '')), '') is not null
       and trim(payment.asaas_payment_id) <> trim(payment.asaas_id)
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'payment_provider_binding_divergent');
  end if;
  if normalized_target = 'offboarded' and exists (
    select 1
      from (
        select coalesce(
                 nullif(trim(coalesce(payment.asaas_payment_id, '')), ''),
                 nullif(trim(coalesce(payment.asaas_id, '')), '')
               ) as provider_id
          from public.student_payments as payment
         where payment.tenant_id = normalized_tenant
           and payment.student_id = p_student_id
           and upper(coalesce(payment.status, '')) = 'PENDING'
           and payment.due_date >= current_date
      ) as binding
     where binding.provider_id is not null
     group by binding.provider_id
    having count(*) > 1
  ) then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'payment_provider_binding_duplicate');
  end if;

  select operation.* into operation_row
    from public.student_offboarding_operations as operation
   where operation.tenant_id = normalized_tenant
     and operation.student_id = p_student_id
     and operation.status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
   for update;

  if not found then
    insert into public.student_offboarding_operations (
      tenant_id, student_id, requested_by, source_lifecycle_status,
      target_lifecycle_status, reason, status, claim_token, lease_expires_at,
      customer_id, subscription_id, enrollment_payment_id, payment_snapshot, snapshot
    ) values (
      normalized_tenant, p_student_id, p_requested_by,
      lower(trim(coalesce(profile_row.lifecycle_status, 'active'))),
      normalized_target, normalized_reason, 'CLAIMED', p_claim_token,
      now() + make_interval(secs => safe_lease),
      nullif(trim(coalesce(profile_row.asaas_customer_id, '')), ''),
      nullif(trim(coalesce(profile_row.subscription_id, '')), ''),
      nullif(trim(coalesce(profile_row.enrollment_payment_id, '')), ''),
      payment_rows,
      jsonb_build_object(
        'tenant_id', normalized_tenant,
        'student_id', p_student_id,
        'role', profile_row.role,
        'lifecycle_status', lower(trim(coalesce(profile_row.lifecycle_status, 'active'))),
        'customer_id', nullif(trim(coalesce(profile_row.asaas_customer_id, '')), ''),
        'subscription_id', nullif(trim(coalesce(profile_row.subscription_id, '')), ''),
        'enrollment_payment_id', nullif(trim(coalesce(profile_row.enrollment_payment_id, '')), ''),
        'payment_ids', payment_rows
      )
    ) returning * into operation_row;
  end if;

  if operation_row.target_lifecycle_status is distinct from normalized_target
     or operation_row.source_lifecycle_status is distinct from lower(trim(coalesce(profile_row.lifecycle_status, 'active')))
     or operation_row.customer_id is distinct from nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
     or operation_row.subscription_id is distinct from nullif(trim(coalesce(profile_row.subscription_id, '')), '')
     or operation_row.enrollment_payment_id is distinct from nullif(trim(coalesce(profile_row.enrollment_payment_id, '')), '')
     or exists (
       select 1
         from jsonb_array_elements(operation_row.payment_snapshot) as entry
         left join public.student_payments as payment
           on payment.id = (entry ->> 'id')::uuid
          and payment.tenant_id = normalized_tenant
          and payment.student_id = p_student_id
        where payment.id is null
           or coalesce(
                nullif(trim(coalesce(payment.asaas_payment_id, '')), ''),
                nullif(trim(coalesce(payment.asaas_id, '')), '')
              ) is distinct from nullif(entry ->> 'asaas_payment_id', '')
           or payment.due_date is distinct from (entry ->> 'due_date')::date
     )
  then
    update public.student_offboarding_operations
       set status = 'BLOCKED', last_error = 'offboarding_snapshot_mismatch', updated_at = now()
     where id = operation_row.id;
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'snapshot_mismatch', 'operation_id', operation_row.id);
  end if;

  if operation_row.status = 'BLOCKED' then
    return jsonb_build_object('ok', false, 'action', 'REVIEW_REQUIRED', 'reason', coalesce(operation_row.last_error, 'operation_blocked'), 'operation_id', operation_row.id);
  end if;

  if operation_row.status = 'CLAIMED'
     and operation_row.claim_token <> p_claim_token
     and operation_row.lease_expires_at > now()
  then
    retry_after := greatest(1, ceil(extract(epoch from (operation_row.lease_expires_at - now())))::integer);
    return jsonb_build_object('ok', true, 'action', 'IN_PROGRESS', 'operation_id', operation_row.id, 'retry_after_seconds', retry_after);
  end if;

  action := case
    when operation_row.status in ('PROVIDER_MUTATING', 'UNKNOWN') then 'RECONCILE_REQUIRED'
    when operation_row.status = 'PROVIDER_COMPLETE' then 'FINALIZE_REQUIRED'
    else 'PROCEED'
  end;
  update public.student_offboarding_operations
     set claim_token = p_claim_token,
         requested_by = p_requested_by,
         lease_expires_at = now() + make_interval(secs => safe_lease),
         updated_at = now()
   where id = operation_row.id
   returning * into operation_row;

  return jsonb_build_object(
    'ok', true,
    'action', action,
    'operation_id', operation_row.id,
    'claim_token', operation_row.claim_token,
    'source_lifecycle_status', operation_row.source_lifecycle_status,
    'target_lifecycle_status', operation_row.target_lifecycle_status,
    'customer_id', operation_row.customer_id,
    'subscription_id', operation_row.subscription_id,
    'enrollment_payment_id', operation_row.enrollment_payment_id,
    'payment_snapshot', operation_row.payment_snapshot,
    'reason', operation_row.reason
  );
end;
$$;


--
-- Name: begin_student_offboarding_pre_suspension_future_charge_impl(text, uuid, uuid, text, text, text, date, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_student_offboarding_pre_suspension_future_charge_impl(p_tenant_id text, p_student_id uuid, p_requested_by uuid, p_target_status text, p_reason text, p_billing_policy text, p_effective_end_date date, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_target text := lower(pg_catalog.btrim(coalesce(p_target_status, '')));
  normalized_policy text := upper(pg_catalog.btrim(coalesce(p_billing_policy, '')));
  normalized_reason text := nullif(
    pg_catalog.btrim(coalesce(p_reason, '')),
    ''
  );
  business_today date := (pg_catalog.now() at time zone 'America/Sao_Paulo')::date;
  v_effective_end_date date := p_effective_end_date;
  business_period date;
  cancel_from date;
  base_result jsonb;
  operation_id uuid;
  operation_row public.student_offboarding_operations%rowtype;
  desired_payments jsonb := '[]'::jsonb;
  desired_preserved_payments jsonb := '[]'::jsonb;
  expected_subscription_final_status text;
begin
  if normalized_reason is null or pg_catalog.length(normalized_reason) > 500 then
    raise exception using
      errcode = '22023', message = 'student_offboarding_reason_required';
  end if;
  if v_effective_end_date is null
     or v_effective_end_date < date '2020-01-01'
     or v_effective_end_date > business_today
  then
    raise exception using
      errcode = '22023',
      message = 'student_offboarding_effective_end_date_invalid';
  end if;
  business_period := pg_catalog.date_trunc('month', v_effective_end_date)::date;

  if normalized_target = 'suspended' then
    if normalized_policy not in ('', 'KEEP_OPEN_INVOICES') then
      raise exception using
        errcode = '22023',
        message = 'student_offboarding_billing_policy_invalid';
    end if;
    normalized_policy := 'KEEP_OPEN_INVOICES';
    cancel_from := null;
    expected_subscription_final_status := 'INACTIVE';
  elsif normalized_target = 'offboarded' then
    if normalized_policy not in (
      'CHARGE_CURRENT_MONTH', 'WAIVE_CURRENT_MONTH'
    ) then
      raise exception using
        errcode = '22023',
        message = 'student_offboarding_billing_policy_required';
    end if;
    cancel_from := case normalized_policy
      when 'WAIVE_CURRENT_MONTH' then business_period
      else (business_period + interval '1 month')::date
    end;
    expected_subscription_final_status := case normalized_policy
      when 'WAIVE_CURRENT_MONTH' then 'NOT_FOUND'
      else 'INACTIVE'
    end;
  else
    raise exception using
      errcode = '22023',
      message = 'student_offboarding_target_invalid';
  end if;

  -- The existing function owns all lifecycle/in-flight communication fences.
  -- This wrapper runs in the same transaction and takes the same advisory
  -- lock, then replaces the still-unsubmitted invoice snapshot atomically.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || p_tenant_id || ':' ||
        p_student_id::text,
      0
    )
  );
  -- A BLOCKED operation that never crossed the provider fence is safe to
  -- release under this same student advisory lock. Doing this inside begin
  -- makes crash recovery independent from a follow-up RPC and its old token.
  update public.student_offboarding_operations as operation
     set status = 'ABORTED',
         lease_expires_at = pg_catalog.now(),
         completed_at = pg_catalog.now(),
         snapshot = operation.snapshot || pg_catalog.jsonb_build_object(
           'pre_provider_block_released_at', pg_catalog.now(),
           'pre_provider_block_last_error', operation.last_error
         ),
         updated_at = pg_catalog.now()
   where operation.tenant_id = p_tenant_id
     and operation.student_id = p_student_id
     and operation.status = 'BLOCKED'
     and operation.provider_started_at is null;

  -- Reject an implicit refund before creating a new durable operation. This
  -- runs after safe BLOCKED recovery so even a changed retry decision cannot
  -- leave the previous pre-provider claim as a permanent student fence.
  if normalized_target = 'offboarded'
     and normalized_policy = 'WAIVE_CURRENT_MONTH'
     and exists (
       select 1
         from public.student_payments as payment
        where payment.tenant_id = p_tenant_id
          and payment.student_id = p_student_id
          and payment.payment_type = 'SUBSCRIPTION'
          and payment.due_date >= business_period
          and payment.due_date < (business_period + interval '1 month')::date
          and upper(pg_catalog.btrim(coalesce(payment.status, ''))) not in (
            'PENDING', 'OVERDUE', 'CANCELLED'
          )
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'current_period_not_waivable'
    );
  end if;

  -- Serialize membership mutations with operation creation. Once the claim is
  -- visible, the lifecycle guard below keeps this authority frozen through the
  -- provider round-trip.
  perform 1
    from public.tenant_memberships as membership
   where membership.user_id = p_student_id
   for share;
  base_result := public.begin_student_offboarding(
    p_tenant_id,
    p_student_id,
    p_requested_by,
    normalized_target,
    normalized_reason,
    p_claim_token,
    p_lease_seconds
  );

  if coalesce(base_result ->> 'action', '') in (
    'ALREADY_COMPLETED', 'IN_PROGRESS', 'REVIEW_REQUIRED'
  ) or coalesce((base_result ->> 'ok')::boolean, false) is false then
    return base_result;
  end if;

  begin
    operation_id := (base_result ->> 'operation_id')::uuid;
  exception when invalid_text_representation then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'offboarding_operation_invalid'
    );
  end;

  if normalized_target = 'offboarded' then
    if exists (
      select 1
        from public.student_payments as payment
       where payment.tenant_id = p_tenant_id
         and payment.student_id = p_student_id
         and upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
           'PENDING', 'OVERDUE'
         )
         and payment.payment_type = 'SUBSCRIPTION'
         and payment.due_date >= cancel_from
         and nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '')
               is not null
         and nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '')
               is not null
         and pg_catalog.btrim(payment.asaas_payment_id) <>
               pg_catalog.btrim(payment.asaas_id)
    ) then
      update public.student_offboarding_operations
         set status = 'BLOCKED',
             last_error = 'payment_provider_binding_divergent',
             updated_at = pg_catalog.now()
       where id = operation_id;
      return pg_catalog.jsonb_build_object(
        'ok', false, 'action', 'REVIEW_REQUIRED',
        'reason', 'payment_provider_binding_divergent',
        'operation_id', operation_id
      );
    end if;

    select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'id', payment.id,
      'asaas_payment_id', coalesce(
        nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), ''),
        nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '')
      ),
      'status', payment.status,
      'due_date', payment.due_date,
      'value', payment.value
    ) order by payment.id), '[]'::jsonb)
      into desired_payments
      from public.student_payments as payment
     where payment.tenant_id = p_tenant_id
       and payment.student_id = p_student_id
       and payment.payment_type = 'SUBSCRIPTION'
       and upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
         'PENDING', 'OVERDUE'
       )
       and payment.due_date >= cancel_from;

    if normalized_policy = 'CHARGE_CURRENT_MONTH' then
      select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'id', payment.id,
        'asaas_payment_id', coalesce(
          nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), ''),
          nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '')
        ),
        'status', payment.status,
        'provider_status', payment.provider_status,
        'due_date', payment.due_date,
        'value', payment.value
      ) order by payment.id), '[]'::jsonb)
        into desired_preserved_payments
        from public.student_payments as payment
       where payment.tenant_id = p_tenant_id
         and payment.student_id = p_student_id
         and payment.payment_type = 'SUBSCRIPTION'
         and payment.due_date >= business_period
         and payment.due_date <
           (business_period + interval '1 month')::date
         and upper(pg_catalog.btrim(coalesce(payment.status, ''))) not in (
           'CANCELLED', 'DELETED', 'REFUNDED', 'REVERSED'
         );
    end if;

    if exists (
      select 1
        from pg_catalog.jsonb_array_elements(desired_payments) as entry
       where nullif(entry ->> 'asaas_payment_id', '') is not null
       group by entry ->> 'asaas_payment_id'
      having pg_catalog.count(*) > 1
    ) then
      update public.student_offboarding_operations
         set status = 'BLOCKED',
             last_error = 'payment_provider_binding_duplicate',
             updated_at = pg_catalog.now()
       where id = operation_id;
      return pg_catalog.jsonb_build_object(
        'ok', false, 'action', 'REVIEW_REQUIRED',
        'reason', 'payment_provider_binding_duplicate',
        'operation_id', operation_id
      );
    end if;
  end if;

  select operation.* into operation_row
    from public.student_offboarding_operations as operation
   where operation.id = operation_id
     and operation.claim_token = p_claim_token
   for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'claim_lost'
    );
  end if;

  if operation_row.reason is distinct from normalized_reason then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'offboarding_reason_snapshot_mismatch',
           updated_at = pg_catalog.now()
     where id = operation_id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'offboarding_reason_snapshot_mismatch',
      'operation_id', operation_id
    );
  end if;

  if normalized_policy = 'CHARGE_CURRENT_MONTH' and (
       pg_catalog.jsonb_array_length(desired_preserved_payments) <> 1
       or exists (
         select 1
           from pg_catalog.jsonb_array_elements(
             desired_preserved_payments
           ) as entry
          where nullif(entry ->> 'asaas_payment_id', '') is null
       )
     )
  then
    update public.student_offboarding_operations
       set status = case
             when provider_started_at is null then 'ABORTED'
             else 'BLOCKED'
           end,
           last_error = 'preserved_current_payment_invalid',
           lease_expires_at = case
             when provider_started_at is null then pg_catalog.now()
             else lease_expires_at
           end,
           completed_at = case
             when provider_started_at is null then pg_catalog.now()
             else completed_at
           end,
           updated_at = pg_catalog.now()
     where id = operation_id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'preserved_current_payment_invalid',
      'operation_id', operation_id
    );
  end if;

  if operation_row.billing_policy is null then
    if operation_row.status <> 'CLAIMED'
       or operation_row.provider_started_at is not null
    then
      update public.student_offboarding_operations
         set status = 'BLOCKED',
             last_error = 'billing_policy_missing_after_provider_start',
             updated_at = pg_catalog.now()
       where id = operation_id;
      return pg_catalog.jsonb_build_object(
        'ok', false, 'action', 'REVIEW_REQUIRED',
        'reason', 'billing_policy_missing_after_provider_start',
        'operation_id', operation_id
      );
    end if;
    update public.student_offboarding_operations
       set billing_policy = normalized_policy,
           billing_period_start = business_period,
           billing_cancel_from_date = cancel_from,
           effective_end_date = v_effective_end_date,
           payment_snapshot = desired_payments,
           preserved_payment_snapshot = desired_preserved_payments,
           provider_subscription_final_status =
             expected_subscription_final_status,
           snapshot = snapshot || pg_catalog.jsonb_build_object(
             'billing_policy', normalized_policy,
             'billing_period_start', business_period,
             'billing_cancel_from_date', cancel_from,
             'effective_end_date', v_effective_end_date,
             'reason', normalized_reason,
             'payment_ids', desired_payments,
             'preserved_payment_ids', desired_preserved_payments,
             'provider_subscription_final_status',
               expected_subscription_final_status
           ),
           updated_at = pg_catalog.now()
     where id = operation_id
     returning * into operation_row;
  elsif operation_row.billing_policy is distinct from normalized_policy
     or operation_row.billing_period_start is distinct from business_period
     or operation_row.billing_cancel_from_date is distinct from cancel_from
     or operation_row.effective_end_date is distinct from v_effective_end_date
     or operation_row.provider_subscription_final_status is distinct from
       expected_subscription_final_status
     or (
       operation_row.provider_started_at is null
       and operation_row.status = 'CLAIMED'
       and (
         operation_row.payment_snapshot is distinct from desired_payments
         or operation_row.preserved_payment_snapshot is distinct from
           desired_preserved_payments
       )
     )
  then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'offboarding_billing_snapshot_mismatch',
           updated_at = pg_catalog.now()
     where id = operation_id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'offboarding_billing_snapshot_mismatch',
      'operation_id', operation_id
    );
  end if;

  return base_result || pg_catalog.jsonb_build_object(
    'billing_policy', operation_row.billing_policy,
    'billing_period_start', operation_row.billing_period_start,
    'billing_cancel_from_date', operation_row.billing_cancel_from_date,
    'effective_end_date', operation_row.effective_end_date,
    'reason', operation_row.reason,
    'payment_snapshot', operation_row.payment_snapshot,
    'preserved_payment_snapshot', operation_row.preserved_payment_snapshot,
    'provider_subscription_final_status',
      operation_row.provider_subscription_final_status
  );
end;
$$;


--
-- Name: begin_student_offboarding_with_billing_policy(text, uuid, uuid, text, text, text, date, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_student_offboarding_with_billing_policy(p_tenant_id text, p_student_id uuid, p_requested_by uuid, p_target_status text, p_reason text, p_billing_policy text, p_effective_end_date date, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_target text := pg_catalog.lower(
    pg_catalog.btrim(coalesce(p_target_status, ''))
  );
  normalized_policy text := pg_catalog.upper(
    pg_catalog.btrim(coalesce(p_billing_policy, ''))
  );
  normalized_reason text := nullif(
    pg_catalog.btrim(coalesce(p_reason, '')),
    ''
  );
  business_today date := (
    pg_catalog.now() at time zone 'America/Sao_Paulo'
  )::date;
  business_period date;
  cancel_from date;
  base_result jsonb;
  operation_id uuid;
  operation_row public.student_offboarding_operations%rowtype;
  desired_payments jsonb := '[]'::jsonb;
  initialize_snapshot boolean := false;
begin
  if normalized_target <> 'suspended' then
    return
      public.begin_student_offboarding_pre_suspension_future_charge_impl(
        p_tenant_id,
        p_student_id,
        p_requested_by,
        p_target_status,
        p_reason,
        p_billing_policy,
        p_effective_end_date,
        p_claim_token,
        p_lease_seconds
      );
  end if;

  if normalized_reason is null
     or pg_catalog.length(normalized_reason) > 500
  then
    raise exception using
      errcode = '22023', message = 'student_offboarding_reason_required';
  end if;
  if p_effective_end_date is null
     or p_effective_end_date < date '2020-01-01'
     or p_effective_end_date > business_today
  then
    raise exception using
      errcode = '22023',
      message = 'student_offboarding_effective_end_date_invalid';
  end if;
  if normalized_policy not in ('', 'KEEP_OPEN_INVOICES') then
    raise exception using
      errcode = '22023',
      message = 'student_offboarding_billing_policy_invalid';
  end if;

  normalized_policy := 'KEEP_OPEN_INVOICES';
  business_period := pg_catalog.date_trunc(
    'month', p_effective_end_date
  )::date;
  cancel_from := (business_period + interval '1 month')::date;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || p_tenant_id || ':' ||
        p_student_id::text,
      0
    )
  );

  -- A BLOCKED operation that never crossed Asaas is locally reversible.  The
  -- next begin can replace it under the same student advisory lock.
  update public.student_offboarding_operations as operation
     set status = 'ABORTED',
         lease_expires_at = pg_catalog.now(),
         completed_at = pg_catalog.now(),
         snapshot = operation.snapshot || pg_catalog.jsonb_build_object(
           'pre_provider_block_released_at', pg_catalog.now(),
           'pre_provider_block_last_error', operation.last_error
         ),
         updated_at = pg_catalog.now()
   where operation.tenant_id = p_tenant_id
     and operation.student_id = p_student_id
     and operation.status = 'BLOCKED'
     and operation.provider_started_at is null;

  perform 1
    from public.tenant_memberships as membership
   where membership.user_id = p_student_id
   for share;

  base_result := public.begin_student_offboarding(
    p_tenant_id,
    p_student_id,
    p_requested_by,
    'suspended',
    normalized_reason,
    p_claim_token,
    p_lease_seconds
  );

  if coalesce(base_result ->> 'action', '') in (
       'ALREADY_COMPLETED', 'IN_PROGRESS', 'REVIEW_REQUIRED'
     )
     or coalesce((base_result ->> 'ok')::boolean, false) is false
  then
    return base_result;
  end if;

  begin
    operation_id := (base_result ->> 'operation_id')::uuid;
  exception when invalid_text_representation then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'offboarding_operation_invalid'
    );
  end;

  select operation.*
    into operation_row
    from public.student_offboarding_operations as operation
   where operation.id = operation_id
     and operation.claim_token = p_claim_token
   for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'claim_lost'
    );
  end if;

  if operation_row.reason is distinct from normalized_reason then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'offboarding_reason_snapshot_mismatch',
           updated_at = pg_catalog.now()
     where id = operation_id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'offboarding_reason_snapshot_mismatch',
      'operation_id', operation_id
    );
  end if;

  initialize_snapshot := operation_row.billing_policy is null
    or (
      operation_row.target_lifecycle_status = 'suspended'
      and operation_row.billing_policy = 'KEEP_OPEN_INVOICES'
      and operation_row.billing_cancel_from_date is null
    );

  if initialize_snapshot and (
       operation_row.status <> 'CLAIMED'
       or operation_row.provider_started_at is not null
     )
  then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error =
             'suspension_billing_snapshot_missing_after_provider_start',
           updated_at = pg_catalog.now()
     where id = operation_id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'suspension_billing_snapshot_missing_after_provider_start',
      'operation_id', operation_id
    );
  end if;

  if initialize_snapshot
     or (
       operation_row.status = 'CLAIMED'
       and operation_row.provider_started_at is null
     )
  then
    -- A settled, credited or otherwise non-deletable future charge cannot be
    -- turned into a silent refund/cancellation by suspension.  Stop before
    -- crossing the provider boundary and require financial reconciliation.
    if exists (
      select 1
        from public.student_payments as payment
       where payment.tenant_id = p_tenant_id
         and payment.student_id = p_student_id
         and payment.payment_type = 'SUBSCRIPTION'
         and payment.due_date >= cancel_from
         and pg_catalog.upper(pg_catalog.btrim(coalesce(
               payment.status,
               ''
             ))) not in (
               'PENDING', 'OVERDUE', 'CANCELLED', 'DELETED',
               'REFUNDED', 'REVERSED', 'NAO_RECEITA'
             )
    ) then
      update public.student_offboarding_operations
         set status = 'BLOCKED',
             last_error = 'future_payment_not_safely_cancellable',
             updated_at = pg_catalog.now()
       where id = operation_id;
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'future_payment_not_safely_cancellable',
        'operation_id', operation_id
      );
    end if;

    if exists (
      select 1
        from public.student_payments as payment
       where payment.tenant_id = p_tenant_id
         and payment.student_id = p_student_id
         and payment.payment_type = 'SUBSCRIPTION'
         and payment.due_date >= cancel_from
         and pg_catalog.upper(pg_catalog.btrim(coalesce(
               payment.status,
               ''
             ))) in ('PENDING', 'OVERDUE')
         and nullif(pg_catalog.btrim(coalesce(
               payment.asaas_payment_id,
               ''
             )), '') is not null
         and nullif(pg_catalog.btrim(coalesce(
               payment.asaas_id,
               ''
             )), '') is not null
         and pg_catalog.btrim(payment.asaas_payment_id) <>
               pg_catalog.btrim(payment.asaas_id)
    ) then
      update public.student_offboarding_operations
         set status = 'BLOCKED',
             last_error = 'payment_provider_binding_divergent',
             updated_at = pg_catalog.now()
       where id = operation_id;
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'payment_provider_binding_divergent',
        'operation_id', operation_id
      );
    end if;

    select coalesce(
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id', payment.id,
          'asaas_payment_id', coalesce(
            nullif(pg_catalog.btrim(coalesce(
              payment.asaas_payment_id,
              ''
            )), ''),
            nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '')
          ),
          'status', payment.status,
          'due_date', payment.due_date,
          'value', payment.value
        ) order by payment.id
      ),
      '[]'::jsonb
    )
      into desired_payments
      from public.student_payments as payment
     where payment.tenant_id = p_tenant_id
       and payment.student_id = p_student_id
       and payment.payment_type = 'SUBSCRIPTION'
       and payment.due_date >= cancel_from
       and pg_catalog.upper(pg_catalog.btrim(coalesce(
             payment.status,
             ''
           ))) in ('PENDING', 'OVERDUE');

    if exists (
      select 1
        from pg_catalog.jsonb_array_elements(desired_payments) as entry
       where nullif(entry ->> 'asaas_payment_id', '') is not null
       group by entry ->> 'asaas_payment_id'
      having pg_catalog.count(*) > 1
    ) then
      update public.student_offboarding_operations
         set status = 'BLOCKED',
             last_error = 'payment_provider_binding_duplicate',
             updated_at = pg_catalog.now()
       where id = operation_id;
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'payment_provider_binding_duplicate',
        'operation_id', operation_id
      );
    end if;
  end if;

  if initialize_snapshot then
    update public.student_offboarding_operations
       set billing_policy = 'KEEP_OPEN_INVOICES',
           billing_period_start = business_period,
           billing_cancel_from_date = cancel_from,
           effective_end_date = p_effective_end_date,
           payment_snapshot = desired_payments,
           preserved_payment_snapshot = '[]'::jsonb,
           provider_subscription_final_status = 'INACTIVE',
           snapshot = snapshot || pg_catalog.jsonb_build_object(
             'billing_policy', 'KEEP_OPEN_INVOICES',
             'billing_period_start', business_period,
             'billing_cancel_from_date', cancel_from,
             'effective_end_date', p_effective_end_date,
             'reason', normalized_reason,
             'payment_ids', desired_payments,
             'preserved_payment_ids', '[]'::jsonb,
             'provider_subscription_final_status', 'INACTIVE'
           ),
           updated_at = pg_catalog.now()
     where id = operation_id
     returning * into operation_row;
  elsif operation_row.billing_policy is distinct from 'KEEP_OPEN_INVOICES'
     or operation_row.billing_period_start is distinct from business_period
     or operation_row.billing_cancel_from_date is distinct from cancel_from
     or operation_row.effective_end_date is distinct from p_effective_end_date
     or operation_row.provider_subscription_final_status is distinct from
       'INACTIVE'
     or operation_row.preserved_payment_snapshot is distinct from '[]'::jsonb
     or (
       operation_row.status = 'CLAIMED'
       and operation_row.provider_started_at is null
       and operation_row.payment_snapshot is distinct from desired_payments
     )
  then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'offboarding_billing_snapshot_mismatch',
           updated_at = pg_catalog.now()
     where id = operation_id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'offboarding_billing_snapshot_mismatch',
      'operation_id', operation_id
    );
  end if;

  return base_result || pg_catalog.jsonb_build_object(
    'billing_policy', operation_row.billing_policy,
    'billing_period_start', operation_row.billing_period_start,
    'billing_cancel_from_date', operation_row.billing_cancel_from_date,
    'effective_end_date', operation_row.effective_end_date,
    'reason', operation_row.reason,
    'payment_snapshot', operation_row.payment_snapshot,
    'preserved_payment_snapshot', operation_row.preserved_payment_snapshot,
    'provider_subscription_final_status',
      operation_row.provider_subscription_final_status
  );
end;
$$;


--
-- Name: begin_student_reactivation(text, uuid, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_student_reactivation(p_tenant_id text, p_student_id uuid, p_requested_by uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  safe_lease integer := greatest(
    60, least(coalesce(p_lease_seconds, 300), 600)
  );
  profile_row public.profiles%rowtype;
  operation_row public.student_offboarding_operations%rowtype;
  action text;
  retry_after integer;
  business_today date := (pg_catalog.now() at time zone 'America/Sao_Paulo')::date;
begin
  if normalized_tenant is null
     or p_student_id is null
     or p_claim_token is null
  then
    raise exception using
      errcode = '22023', message = 'student_reactivation_arguments_invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' ||
        p_student_id::text,
      0
    )
  );

  -- A pre-provider BLOCKED reactivation is locally reversible. Release it and
  -- create/reclaim the next durable operation under the same advisory lock so
  -- a crashed coordinator cannot strand the student indefinitely.
  update public.student_offboarding_operations as operation
     set status = 'ABORTED',
         lease_expires_at = pg_catalog.now(),
         completed_at = pg_catalog.now(),
         snapshot = operation.snapshot || pg_catalog.jsonb_build_object(
           'pre_provider_block_released_at', pg_catalog.now(),
           'pre_provider_block_last_error', operation.last_error
         ),
         updated_at = pg_catalog.now()
   where operation.tenant_id = normalized_tenant
     and operation.student_id = p_student_id
     and operation.status = 'BLOCKED'
     and operation.provider_started_at is null;

  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_student_id
   for update;
  if not found
     or profile_row.tenant_id is distinct from normalized_tenant
     or profile_row.role is distinct from 'STUDENT'
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'profile_scope_changed'
    );
  end if;
  if lower(pg_catalog.btrim(coalesce(profile_row.lifecycle_status, ''))) = 'active' then
    return pg_catalog.jsonb_build_object('ok', true, 'action', 'ALREADY_COMPLETED');
  end if;
  if lower(pg_catalog.btrim(coalesce(profile_row.lifecycle_status, ''))) <> 'suspended' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'new_enrollment_required'
    );
  end if;
  if nullif(pg_catalog.btrim(coalesce(profile_row.asaas_customer_id, '')), '') is null
     or nullif(pg_catalog.btrim(coalesce(profile_row.subscription_id, '')), '') is null
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'subscription_binding_missing'
    );
  end if;
  if profile_row.due_day is null
     or profile_row.due_day < 1
     or profile_row.due_day > 31
     or profile_row.monthly_fee is null
     or profile_row.monthly_fee <= 0
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'subscription_billing_terms_invalid'
    );
  end if;
  perform 1
    from public.tenant_memberships as membership
   where membership.user_id = p_student_id
   for share;
  if (
    select pg_catalog.count(*)
      from public.tenant_memberships as membership
     where membership.user_id = p_student_id
  ) <> 1 or not exists (
    select 1
      from public.tenant_memberships as membership
     where membership.user_id = p_student_id
       and membership.tenant_id = normalized_tenant
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'membership_scope_changed'
    );
  end if;

  select operation.* into operation_row
    from public.student_offboarding_operations as operation
   where operation.tenant_id = normalized_tenant
     and operation.student_id = p_student_id
     and operation.status in (
       'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
       'UNKNOWN', 'BLOCKED'
     )
   for update;

  if not found then
    insert into public.student_offboarding_operations (
      tenant_id, student_id, requested_by, source_lifecycle_status,
      target_lifecycle_status, reason, status, claim_token, lease_expires_at,
      customer_id, subscription_id, enrollment_payment_id, payment_snapshot,
      snapshot, billing_policy, billing_period_start, effective_end_date,
      provider_subscription_final_status
    ) values (
      normalized_tenant, p_student_id, p_requested_by, 'suspended',
      'active', 'Reativado pela coordenação', 'CLAIMED', p_claim_token,
      pg_catalog.now() + pg_catalog.make_interval(secs => safe_lease),
      nullif(pg_catalog.btrim(profile_row.asaas_customer_id), ''),
      nullif(pg_catalog.btrim(profile_row.subscription_id), ''),
      nullif(pg_catalog.btrim(coalesce(profile_row.enrollment_payment_id, '')), ''),
      '[]'::jsonb,
      pg_catalog.jsonb_build_object(
        'tenant_id', normalized_tenant,
        'student_id', p_student_id,
        'role', profile_row.role,
        'lifecycle_status', 'suspended',
        'customer_id', nullif(pg_catalog.btrim(profile_row.asaas_customer_id), ''),
        'subscription_id', nullif(pg_catalog.btrim(profile_row.subscription_id), ''),
        'due_day', profile_row.due_day,
        'monthly_fee', profile_row.monthly_fee,
        'provider_subscription_final_status', 'ACTIVE'
      ),
      'KEEP_OPEN_INVOICES',
      pg_catalog.date_trunc('month', business_today)::date,
      business_today,
      'ACTIVE'
    ) returning * into operation_row;
  end if;

  if operation_row.target_lifecycle_status is distinct from 'active'
     or operation_row.source_lifecycle_status is distinct from 'suspended'
     or operation_row.customer_id is distinct from
       nullif(pg_catalog.btrim(profile_row.asaas_customer_id), '')
     or operation_row.subscription_id is distinct from
       nullif(pg_catalog.btrim(profile_row.subscription_id), '')
     or operation_row.snapshot -> 'due_day' is distinct from
       pg_catalog.to_jsonb(profile_row.due_day)
     or operation_row.snapshot -> 'monthly_fee' is distinct from
       pg_catalog.to_jsonb(profile_row.monthly_fee)
     or operation_row.provider_subscription_final_status is distinct from
       'ACTIVE'
     or operation_row.preserved_payment_snapshot is distinct from '[]'::jsonb
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'lifecycle_operation_in_flight'
    );
  end if;
  if operation_row.status = 'BLOCKED' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', coalesce(operation_row.last_error, 'operation_blocked')
    );
  end if;
  if operation_row.status = 'CLAIMED'
     and operation_row.claim_token <> p_claim_token
     and operation_row.lease_expires_at > pg_catalog.now()
  then
    retry_after := greatest(
      1,
      pg_catalog.ceil(extract(
        epoch from operation_row.lease_expires_at - pg_catalog.now()
      ))::integer
    );
    return pg_catalog.jsonb_build_object(
      'ok', true, 'action', 'IN_PROGRESS',
      'operation_id', operation_row.id,
      'retry_after_seconds', retry_after
    );
  end if;

  action := case
    when operation_row.status in ('PROVIDER_MUTATING', 'UNKNOWN')
      then 'RECONCILE_REQUIRED'
    when operation_row.status = 'PROVIDER_COMPLETE'
      then 'FINALIZE_REQUIRED'
    else 'PROCEED'
  end;
  update public.student_offboarding_operations
     set claim_token = p_claim_token,
         requested_by = p_requested_by,
         lease_expires_at = pg_catalog.now() +
           pg_catalog.make_interval(secs => safe_lease),
         updated_at = pg_catalog.now()
   where id = operation_row.id
   returning * into operation_row;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', action,
    'operation_id', operation_row.id,
    'claim_token', operation_row.claim_token,
    'source_lifecycle_status', operation_row.source_lifecycle_status,
    'target_lifecycle_status', operation_row.target_lifecycle_status,
    'customer_id', operation_row.customer_id,
    'subscription_id', operation_row.subscription_id,
    'due_day', operation_row.snapshot -> 'due_day',
    'monthly_fee', operation_row.snapshot -> 'monthly_fee',
    'enrollment_payment_id', operation_row.enrollment_payment_id,
    'billing_policy', operation_row.billing_policy,
    'billing_period_start', operation_row.billing_period_start,
    'effective_end_date', operation_row.effective_end_date,
    'payment_snapshot', operation_row.payment_snapshot,
    'provider_subscription_final_status',
      operation_row.provider_subscription_final_status
  );
end;
$$;


--
-- Name: bind_legacy_recurring_student_payment_from_webhook(text, uuid, uuid, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_legacy_recurring_student_payment_from_webhook(p_provider_event_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_expected_provider_subscription_id text, p_authoritative_payment jsonb, p_authoritative_subscription jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_event_id text := nullif(pg_catalog.btrim(coalesce(p_provider_event_id, '')), '');
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_expected_tenant_id, '')), '');
  normalized_customer text := nullif(pg_catalog.btrim(coalesce(p_expected_provider_customer_id, '')), '');
  normalized_subscription text := nullif(pg_catalog.btrim(coalesce(p_expected_provider_subscription_id, '')), '');
  inbox_row public.asaas_webhook_inbox%rowtype;
  payment_row public.student_payments%rowtype;
  profile_row public.profiles%rowtype;
  event_payment_id text;
  event_customer_id text;
  event_subscription_id text;
  event_reference text;
  event_status text;
  event_value numeric;
  event_due_date date;
  authoritative_payment_id text;
  authoritative_customer_id text;
  authoritative_subscription_id text;
  authoritative_payment_reference text;
  authoritative_payment_status text;
  authoritative_payment_value numeric;
  authoritative_due_date date;
  authoritative_parent_id text;
  authoritative_parent_customer_id text;
  authoritative_parent_reference text;
  authoritative_parent_status text;
  authoritative_parent_value numeric;
  expected_settled_status text;
  payment_binding_count integer;
  provider_profile_count integer;
begin
  if normalized_event_id is null
     or pg_catalog.length(normalized_event_id) > 240
     or p_expected_local_payment_id is null
     or p_expected_student_id is null
     or normalized_tenant is null
     or normalized_customer is null
     or normalized_subscription is null
     or pg_catalog.length(normalized_customer) > 240
     or pg_catalog.length(normalized_subscription) > 240
     or p_authoritative_payment is null
     or pg_catalog.jsonb_typeof(p_authoritative_payment) <> 'object'
     or p_authoritative_subscription is null
     or pg_catalog.jsonb_typeof(p_authoritative_subscription) <> 'object'
  then
    raise exception using
      errcode = '22023',
      message = 'legacy_recurring_binding_arguments_invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' ||
        p_expected_student_id::text,
      0
    )
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'legacy-recurring-payment-binding:' || normalized_tenant || ':' ||
        p_expected_local_payment_id::text,
      0
    )
  );

  select inbox.*
    into inbox_row
    from public.asaas_webhook_inbox as inbox
   where inbox.provider_event_id = normalized_event_id
   for update;

  if not found
     or inbox_row.status <> 'PROCESSING'
     or inbox_row.lease_owner is null
     or inbox_row.lease_expires_at is null
     or inbox_row.lease_expires_at <= pg_catalog.now()
     or inbox_row.event_name not in (
       'PAYMENT_RECEIVED', 'PAYMENT_RECEIVED_IN_CASH'
     )
     or nullif(pg_catalog.btrim(inbox_row.payload_hash), '') is null
     or nullif(pg_catalog.btrim(inbox_row.payload ->> 'id'), '')
          is distinct from normalized_event_id
     or nullif(pg_catalog.btrim(inbox_row.payload ->> 'event'), '')
          is distinct from inbox_row.event_name
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'legacy_recurring_trusted_webhook_evidence_missing'
    );
  end if;

  expected_settled_status := case inbox_row.event_name
    when 'PAYMENT_RECEIVED' then 'RECEIVED'
    when 'PAYMENT_RECEIVED_IN_CASH' then 'RECEIVED_IN_CASH'
    else null
  end;
  event_payment_id := nullif(pg_catalog.btrim(inbox_row.payload #>> '{payment,id}'), '');
  event_customer_id := nullif(pg_catalog.btrim(inbox_row.payload #>> '{payment,customer}'), '');
  event_subscription_id := nullif(pg_catalog.btrim(inbox_row.payload #>> '{payment,subscription}'), '');
  event_reference := nullif(pg_catalog.btrim(inbox_row.payload #>> '{payment,externalReference}'), '');
  event_status := upper(nullif(pg_catalog.btrim(inbox_row.payload #>> '{payment,status}'), ''));

  authoritative_payment_id := nullif(pg_catalog.btrim(p_authoritative_payment ->> 'id'), '');
  authoritative_customer_id := nullif(pg_catalog.btrim(p_authoritative_payment ->> 'customer'), '');
  authoritative_subscription_id := nullif(pg_catalog.btrim(p_authoritative_payment ->> 'subscription'), '');
  authoritative_payment_reference := nullif(pg_catalog.btrim(p_authoritative_payment ->> 'externalReference'), '');
  authoritative_payment_status := upper(nullif(pg_catalog.btrim(p_authoritative_payment ->> 'status'), ''));

  authoritative_parent_id := nullif(pg_catalog.btrim(p_authoritative_subscription ->> 'id'), '');
  authoritative_parent_customer_id := nullif(pg_catalog.btrim(p_authoritative_subscription ->> 'customer'), '');
  authoritative_parent_reference := nullif(pg_catalog.btrim(p_authoritative_subscription ->> 'externalReference'), '');
  authoritative_parent_status := upper(nullif(pg_catalog.btrim(p_authoritative_subscription ->> 'status'), ''));

  begin
    event_value := (inbox_row.payload #>> '{payment,value}')::numeric;
    event_due_date := (inbox_row.payload #>> '{payment,dueDate}')::date;
    authoritative_payment_value := (p_authoritative_payment ->> 'value')::numeric;
    authoritative_due_date := (p_authoritative_payment ->> 'dueDate')::date;
    authoritative_parent_value := (p_authoritative_subscription ->> 'value')::numeric;
  exception
    when invalid_text_representation or numeric_value_out_of_range or datetime_field_overflow then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'legacy_recurring_provider_evidence_invalid'
      );
  end;

  if event_payment_id is distinct from inbox_row.provider_entity_id
     or event_customer_id is distinct from normalized_customer
     or event_subscription_id is distinct from normalized_subscription
     or event_reference is not null
     or event_status is distinct from expected_settled_status
     or authoritative_payment_id is distinct from event_payment_id
     or authoritative_customer_id is distinct from event_customer_id
     or authoritative_subscription_id is distinct from event_subscription_id
     or authoritative_payment_reference is not null
     or authoritative_payment_status is distinct from event_status
     or authoritative_parent_id is distinct from event_subscription_id
     or authoritative_parent_customer_id is distinct from event_customer_id
     or authoritative_parent_reference is not null
     or authoritative_parent_status is null
     or p_authoritative_payment @> '{"deleted":true}'::jsonb
     or event_value is null
     or event_value::text in ('NaN', 'Infinity', '-Infinity')
     or event_value <= 0
     or authoritative_payment_value is null
     or authoritative_payment_value::text in ('NaN', 'Infinity', '-Infinity')
     or authoritative_payment_value <= 0
     or authoritative_parent_value is null
     or authoritative_parent_value::text in ('NaN', 'Infinity', '-Infinity')
     or authoritative_parent_value <= 0
     or pg_catalog.round(event_value, 2)
          is distinct from pg_catalog.round(authoritative_payment_value, 2)
     or pg_catalog.round(event_value, 2)
          is distinct from pg_catalog.round(authoritative_parent_value, 2)
     or event_due_date is null
     or authoritative_due_date is distinct from event_due_date
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'legacy_recurring_provider_evidence_mismatch'
    );
  end if;

  select pg_catalog.count(*)::integer
    into payment_binding_count
    from public.student_payments as payment
   where nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') = event_payment_id
      or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') = event_payment_id;

  if payment_binding_count <> 1 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'legacy_recurring_local_payment_not_unique'
    );
  end if;

  select payment.*
    into payment_row
    from public.student_payments as payment
   where payment.id = p_expected_local_payment_id
     and (
       nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') = event_payment_id
       or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') = event_payment_id
     )
   for update;

  if not found
     or payment_row.student_id is distinct from p_expected_student_id
     or payment_row.tenant_id is distinct from normalized_tenant
     or payment_row.provider_customer_id is not null
     or (
       nullif(pg_catalog.btrim(coalesce(payment_row.asaas_payment_id, '')), '') is not null
       and nullif(pg_catalog.btrim(coalesce(payment_row.asaas_id, '')), '') is not null
       and pg_catalog.btrim(payment_row.asaas_payment_id) <>
         pg_catalog.btrim(payment_row.asaas_id)
     )
     or pg_catalog.round(coalesce(payment_row.value, 0), 2)
          is distinct from pg_catalog.round(event_value, 2)
     or (
       payment_row.amount_cents is not null
       and payment_row.amount_cents is distinct from
         pg_catalog.round(event_value * 100)::integer
     )
     or payment_row.due_date is distinct from event_due_date
     or upper(pg_catalog.btrim(coalesce(payment_row.status, ''))) not in (
       'PENDING', 'OVERDUE', 'CONFIRMED'
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'legacy_recurring_local_payment_not_repairable'
    );
  end if;

  select profile.*
    into profile_row
    from public.profiles as profile
   where profile.id = p_expected_student_id
     and profile.tenant_id = normalized_tenant
     and profile.role = 'STUDENT'
     and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) in (
       'active', 'suspended', 'offboarded'
     )
     and coalesce(profile.is_test_account, false) is false
     and nullif(pg_catalog.btrim(coalesce(profile.asaas_customer_id, '')), '') =
       normalized_customer
     and nullif(pg_catalog.btrim(coalesce(profile.subscription_id, '')), '') =
       normalized_subscription
   for update;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'legacy_recurring_student_scope_not_corroborated'
    );
  end if;

  select pg_catalog.count(*)::integer
    into provider_profile_count
    from public.profiles as profile
   where profile.role = 'STUDENT'
     and (
       nullif(pg_catalog.btrim(coalesce(profile.asaas_customer_id, '')), '') =
         normalized_customer
       or nullif(pg_catalog.btrim(coalesce(profile.subscription_id, '')), '') =
         normalized_subscription
     );

  if provider_profile_count <> 1 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'legacy_recurring_provider_profile_not_unique'
    );
  end if;

  if (
    select pg_catalog.count(*)
      from public.tenant_memberships as membership
     where membership.user_id = p_expected_student_id
  ) <> 1
     or not exists (
       select 1
         from public.tenant_memberships as membership
        where membership.user_id = p_expected_student_id
          and membership.tenant_id = normalized_tenant
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'legacy_recurring_membership_not_corroborated'
    );
  end if;

  -- Do not rewrite status, dates, payload or updated_at here. The ordinary
  -- serialized payment event RPC applies the settlement immediately after
  -- this immutable identity gap is repaired.
  update public.student_payments as target
     set provider_customer_id = normalized_customer
   where target.id = payment_row.id
     and target.provider_customer_id is null;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'legacy_recurring_binding_changed_concurrently'
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'BOUND',
    'evidence_mode', 'AUTHORITATIVE_RECURRING_GET',
    'payment_id', payment_row.id,
    'tenant_id', normalized_tenant,
    'student_id', p_expected_student_id
  );
end;
$$;


--
-- Name: bind_legacy_recurring_student_payment_from_webhook_v2(text, uuid, uuid, text, text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_legacy_recurring_student_payment_from_webhook_v2(p_provider_event_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_expected_provider_subscription_id text, p_authoritative_payment jsonb, p_authoritative_subscription jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  payment_value numeric;
  current_subscription_value numeric;
  normalized_subscription jsonb;
begin
  if pg_catalog.jsonb_typeof(p_authoritative_payment) <> 'object'
     or pg_catalog.jsonb_typeof(p_authoritative_subscription) <> 'object'
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'legacy_recurring_provider_evidence_invalid'
    );
  end if;

  begin
    payment_value := (p_authoritative_payment ->> 'value')::numeric;
    current_subscription_value :=
      (p_authoritative_subscription ->> 'value')::numeric;
  exception
    when invalid_text_representation or numeric_value_out_of_range then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'legacy_recurring_provider_evidence_invalid'
      );
  end;

  if payment_value is null
     or payment_value::text in ('NaN', 'Infinity', '-Infinity')
     or payment_value <= 0
     or current_subscription_value is null
     or current_subscription_value::text in (
       'NaN', 'Infinity', '-Infinity'
     )
     or current_subscription_value <= 0
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'legacy_recurring_provider_evidence_invalid'
    );
  end if;

  normalized_subscription := pg_catalog.jsonb_set(
    p_authoritative_subscription,
    '{value}',
    pg_catalog.to_jsonb(payment_value),
    true
  );

  return public.bind_legacy_recurring_student_payment_from_webhook(
    p_provider_event_id,
    p_expected_local_payment_id,
    p_expected_student_id,
    p_expected_tenant_id,
    p_expected_provider_customer_id,
    p_expected_provider_subscription_id,
    p_authoritative_payment,
    normalized_subscription
  );
end;
$$;


--
-- Name: bind_legacy_student_payment_from_webhook(text, uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_legacy_student_payment_from_webhook(p_provider_event_id text, p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_provider_customer_id text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  normalized_event_id text := nullif(pg_catalog.btrim(coalesce(p_provider_event_id, '')), '');
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_expected_tenant_id, '')), '');
  normalized_customer text := nullif(pg_catalog.btrim(coalesce(p_expected_provider_customer_id, '')), '');
  inbox_row public.asaas_webhook_inbox%rowtype;
  payment_row public.student_payments%rowtype;
  profile_row public.profiles%rowtype;
  provider_payment_id text;
  provider_customer_id text;
  provider_subscription_id text;
  provider_external_reference text;
  provider_event_name text;
  payload_event_id text;
  provider_payment_status text;
  provider_value numeric;
  provider_due_date date;
  enrollment_offer_id uuid;
begin
  if normalized_event_id is null
     or pg_catalog.length(normalized_event_id) > 240
     or p_expected_local_payment_id is null
     or p_expected_student_id is null
     or normalized_tenant is null
     or normalized_customer is null
     or pg_catalog.length(normalized_customer) > 240
     or p_payload is null
     or pg_catalog.jsonb_typeof(p_payload) <> 'object'
  then
    raise exception using
      errcode = '22023',
      message = 'legacy_payment_binding_arguments_invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'legacy-payment-binding:' || normalized_tenant || ':' ||
        p_expected_local_payment_id::text,
      0
    )
  );

  select inbox.*
    into inbox_row
    from public.asaas_webhook_inbox as inbox
   where inbox.provider_event_id = normalized_event_id
   for update;

  if not found
     or inbox_row.status not in ('PROCESSING', 'TRIAGE', 'RETRY')
     or inbox_row.event_name not in (
       'PAYMENT_RECEIVED', 'PAYMENT_RECEIVED_IN_CASH'
     )
     or inbox_row.payload is distinct from p_payload
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'trusted_webhook_evidence_missing'
    );
  end if;

  provider_event_name := nullif(pg_catalog.btrim(p_payload ->> 'event'), '');
  payload_event_id := nullif(pg_catalog.btrim(p_payload ->> 'id'), '');
  provider_payment_id := nullif(
    pg_catalog.btrim(p_payload #>> '{payment,id}'),
    ''
  );
  provider_customer_id := nullif(
    pg_catalog.btrim(p_payload #>> '{payment,customer}'),
    ''
  );
  provider_subscription_id := nullif(
    pg_catalog.btrim(p_payload #>> '{payment,subscription}'),
    ''
  );
  provider_external_reference := nullif(
    pg_catalog.btrim(p_payload #>> '{payment,externalReference}'),
    ''
  );
  provider_payment_status := upper(nullif(
    pg_catalog.btrim(p_payload #>> '{payment,status}'),
    ''
  ));

  begin
    provider_value := (p_payload #>> '{payment,value}')::numeric;
    provider_due_date := (p_payload #>> '{payment,dueDate}')::date;
  exception
    when invalid_text_representation or numeric_value_out_of_range then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'provider_payment_evidence_invalid'
      );
  end;

  if payload_event_id is distinct from normalized_event_id
     or provider_event_name is distinct from inbox_row.event_name
     or provider_payment_id is distinct from inbox_row.provider_entity_id
     or provider_customer_id is distinct from normalized_customer
     or provider_payment_status is distinct from (
       case inbox_row.event_name
         when 'PAYMENT_RECEIVED' then 'RECEIVED'
         when 'PAYMENT_RECEIVED_IN_CASH' then 'RECEIVED_IN_CASH'
         else null
       end
     )
     or provider_value is null
     or provider_value::text in ('NaN', 'Infinity', '-Infinity')
     or provider_value <= 0
     or provider_due_date is null
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'provider_payment_evidence_mismatch'
    );
  end if;

  select payment.*
    into payment_row
    from public.student_payments as payment
   where payment.id = p_expected_local_payment_id
     and payment.asaas_payment_id = provider_payment_id
   for update;

  if not found
     or payment_row.student_id is distinct from p_expected_student_id
     or payment_row.tenant_id is distinct from normalized_tenant
     or payment_row.provider_customer_id is not null
     or pg_catalog.round(coalesce(payment_row.value, 0), 2)
          is distinct from pg_catalog.round(provider_value, 2)
     or payment_row.due_date is distinct from provider_due_date
     or upper(pg_catalog.btrim(coalesce(payment_row.status, ''))) not in (
       'PENDING', 'OVERDUE', 'CONFIRMED'
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'local_payment_binding_not_repairable'
    );
  end if;

  select profile.*
    into profile_row
    from public.profiles as profile
   where profile.id = p_expected_student_id
     and profile.tenant_id = normalized_tenant
     and profile.role = 'STUDENT'
     and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) = 'active'
     and coalesce(profile.is_test_account, false) is false
     and nullif(pg_catalog.btrim(coalesce(profile.asaas_customer_id, '')), '') =
           normalized_customer
   for update;

  if not found
     or (
       provider_subscription_id is not null
       and nullif(pg_catalog.btrim(coalesce(profile_row.subscription_id, '')), '')
            is distinct from provider_subscription_id
     )
     or (
       select pg_catalog.count(*)
         from public.tenant_memberships as membership
        where membership.user_id = p_expected_student_id
     ) <> 1
     or not exists (
       select 1
         from public.tenant_memberships as membership
        where membership.user_id = p_expected_student_id
          and membership.tenant_id = normalized_tenant
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'current_student_binding_not_corroborated'
    );
  end if;

  -- New enrollment references are independently tied to the consumed offer.
  -- Unknown reference formats remain fail-closed instead of being guessed.
  if provider_external_reference is null
     or provider_external_reference !~
       '^enrollment:[0-9a-fA-F-]{36}:subscription$'
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'provider_reference_not_repairable'
    );
  end if;

  begin
    enrollment_offer_id := pg_catalog.split_part(
      provider_external_reference,
      ':',
      2
    )::uuid;
  exception
    when invalid_text_representation then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'provider_reference_invalid'
      );
  end;

  if not exists (
    select 1
      from public.offers as offer
     where offer.id = enrollment_offer_id
       and offer.tenant_id = normalized_tenant
       and offer.kind = 'ENROLLMENT'
       and offer.consumed_by = p_expected_student_id
       and offer.processing_state = 'COMPLETED'
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'enrollment_reference_not_corroborated'
    );
  end if;

  update public.student_payments as target
     set provider_customer_id = normalized_customer,
         updated_at = pg_catalog.now()
   where target.id = payment_row.id
     and target.provider_customer_id is null;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'payment_binding_changed_concurrently'
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'BOUND',
    'payment_id', payment_row.id,
    'tenant_id', normalized_tenant,
    'student_id', p_expected_student_id
  );
end;
$_$;


--
-- Name: bind_student_account_deletion_integrations(uuid, uuid, text, integer, text, text, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_student_account_deletion_integrations(p_claim_id uuid, p_claim_token uuid, p_subscription_integration_id text, p_subscription_version integer, p_subscription_environment text, p_subscription_mode text, p_customer_integration_id text, p_customer_version integer, p_customer_environment text, p_customer_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  claim_row public.student_account_deletion_claims%rowtype;
  expected_snapshot jsonb;
begin
  select deletion.* into claim_row
    from public.student_account_deletion_claims as deletion
   where deletion.id = p_claim_id
   for update;
  if not found
     or claim_row.claim_token is distinct from p_claim_token
     or claim_row.status not in ('CLAIMED', 'PROVIDER_MUTATING', 'UNKNOWN')
  then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  if (claim_row.subscription_id is null) is distinct from (p_subscription_integration_id is null)
     or (claim_row.customer_id is null) is distinct from (p_customer_integration_id is null)
     or (p_subscription_integration_id is not null and (
       nullif(trim(p_subscription_integration_id), '') is null
       or coalesce(p_subscription_version, 0) < 1
       or p_subscription_environment not in ('platform', 'production', 'sandbox')
       or p_subscription_mode not in ('PLATFORM_MANAGED_ROOT', 'PLATFORM_MANAGED_SUBACCOUNT', 'TENANT_BYOK')
     ))
     or (p_customer_integration_id is not null and (
       nullif(trim(p_customer_integration_id), '') is null
       or coalesce(p_customer_version, 0) < 1
       or p_customer_environment not in ('platform', 'production', 'sandbox')
       or p_customer_mode not in ('PLATFORM_MANAGED_ROOT', 'PLATFORM_MANAGED_SUBACCOUNT', 'TENANT_BYOK')
     ))
  then
    update public.student_account_deletion_claims
       set status = 'BLOCKED', last_error = 'integration_snapshot_invalid', updated_at = now()
     where id = claim_row.id;
    return jsonb_build_object('ok', false, 'reason', 'integration_snapshot_invalid');
  end if;

  expected_snapshot := jsonb_build_object(
    'subscription', case when p_subscription_integration_id is null then null else jsonb_build_object(
      'integration_id', trim(p_subscription_integration_id),
      'version', p_subscription_version,
      'environment', p_subscription_environment,
      'mode', p_subscription_mode
    ) end,
    'customer', case when p_customer_integration_id is null then null else jsonb_build_object(
      'integration_id', trim(p_customer_integration_id),
      'version', p_customer_version,
      'environment', p_customer_environment,
      'mode', p_customer_mode
    ) end
  );

  if claim_row.integration_snapshot = '{}'::jsonb then
    update public.student_account_deletion_claims
       set integration_snapshot = expected_snapshot,
           status = case
             when subscription_deleted and customer_deleted
               then 'PROVIDER_COMPLETE'
             else status
           end,
           provider_completed_at = case
             when subscription_deleted and customer_deleted
               then coalesce(provider_completed_at, now())
             else provider_completed_at
           end,
           lease_expires_at = case
             when subscription_deleted and customer_deleted then now()
             else lease_expires_at
           end,
           updated_at = now()
     where id = claim_row.id;
    return jsonb_build_object(
      'ok', true,
      'action', case
        when claim_row.subscription_deleted and claim_row.customer_deleted
          then 'BOUND_PROVIDER_COMPLETE'
        else 'BOUND'
      end
    );
  end if;
  if claim_row.integration_snapshot is distinct from expected_snapshot then
    update public.student_account_deletion_claims
       set status = 'BLOCKED',
           last_error = 'integration_context_changed',
           lease_expires_at = now(),
           updated_at = now()
     where id = claim_row.id;
    return jsonb_build_object('ok', false, 'reason', 'integration_context_changed');
  end if;
  if claim_row.subscription_deleted and claim_row.customer_deleted then
    update public.student_account_deletion_claims
       set status = 'PROVIDER_COMPLETE',
           provider_completed_at = coalesce(provider_completed_at, now()),
           lease_expires_at = now(),
           updated_at = now()
     where id = claim_row.id;
    return jsonb_build_object('ok', true, 'action', 'ALREADY_BOUND_PROVIDER_COMPLETE');
  end if;
  return jsonb_build_object('ok', true, 'action', 'ALREADY_BOUND');
end;
$$;


--
-- Name: bind_student_asaas_creation_lifecycle(uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_student_asaas_creation_lifecycle(p_attempt_id uuid, p_claim_token uuid, p_tenant_id text, p_student_id uuid, p_binding_kind text, p_expected_customer_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  attempt_row public.asaas_provider_creation_attempts%rowtype;
  profile_row public.profiles%rowtype;
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  normalized_kind text := upper(trim(coalesce(p_binding_kind, '')));
  normalized_customer text := nullif(trim(coalesce(p_expected_customer_id, '')), '');
  normalized_provider_entity text;
  already_bound boolean;
  exact_succeeded_legacy_binding boolean := false;
begin
  if p_attempt_id is null or normalized_tenant is null or p_student_id is null
     or normalized_kind not in (
       'CUSTOMER', 'ENROLLMENT_PAYMENT', 'SUBSCRIPTION',
       'BILLING_PERIOD_PAYMENT', 'STUDENT_PAYMENT', 'TOPUP_ORDER'
     )
  then
    raise exception using errcode = '22023', message = 'invalid_student_creation_lifecycle_binding';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' || p_student_id::text,
      0
    )
  );

  select attempt.* into attempt_row
    from public.asaas_provider_creation_attempts as attempt
   where attempt.id = p_attempt_id
   for update;
  if not found
     or attempt_row.tenant_id is distinct from normalized_tenant
     or attempt_row.status not in ('CLAIMED', 'UNKNOWN', 'SUCCEEDED')
     or (attempt_row.status <> 'SUCCEEDED' and attempt_row.claim_token is distinct from p_claim_token)
     or (normalized_kind = 'CUSTOMER' and attempt_row.operation <> 'CUSTOMER_CREATE')
     or (normalized_kind in ('ENROLLMENT_PAYMENT', 'BILLING_PERIOD_PAYMENT', 'STUDENT_PAYMENT', 'TOPUP_ORDER') and attempt_row.operation <> 'PAYMENT_CREATE')
     or (normalized_kind = 'SUBSCRIPTION' and attempt_row.operation <> 'SUBSCRIPTION_CREATE')
  then
    return jsonb_build_object('ok', false, 'reason', 'creation_claim_lost');
  end if;

  already_bound := attempt_row.lifecycle_student_id is not null;
  normalized_provider_entity := nullif(
    trim(coalesce(attempt_row.provider_entity_id, '')),
    ''
  );
  if already_bound and (
    attempt_row.lifecycle_student_id is distinct from p_student_id
    or attempt_row.lifecycle_binding_kind is distinct from normalized_kind
    or attempt_row.lifecycle_expected_customer_id is distinct from normalized_customer
  ) then
    update public.asaas_provider_creation_attempts
       set lifecycle_last_error = 'student_creation_lifecycle_binding_mismatch',
           updated_at = now()
     where id = attempt_row.id;
    return jsonb_build_object('ok', false, 'reason', 'lifecycle_binding_mismatch');
  end if;

  -- CUSTOMER/SUBSCRIPTION/ENROLLMENT are singleton bindings on profiles. The
  -- logical creation key differs between some callers, so the lifecycle
  -- advisory lock must also prevent two distinct durable attempts from both
  -- observing the same null local field and crossing separate POST fences.
  if normalized_kind in ('CUSTOMER', 'ENROLLMENT_PAYMENT', 'SUBSCRIPTION')
     and exists (
       select 1
         from public.asaas_provider_creation_attempts as competing
        where competing.id <> attempt_row.id
          and competing.tenant_id = normalized_tenant
          and competing.lifecycle_student_id = p_student_id
          and competing.lifecycle_binding_kind = normalized_kind
          and competing.lifecycle_released_at is null
          and competing.status in (
            'CLAIMED', 'SUBMITTING', 'UNKNOWN', 'SUCCEEDED', 'BLOCKED'
          )
     )
  then
    return jsonb_build_object(
      'ok', false,
      'reason', 'singleton_creation_binding_in_flight'
    );
  end if;

  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_student_id
     and profile.tenant_id = normalized_tenant
     and profile.role = 'STUDENT'
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
   for share;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'student_lifecycle_inactive');
  end if;

  if normalized_kind = 'CUSTOMER' then
    exact_succeeded_legacy_binding := not already_bound
      and attempt_row.status = 'SUCCEEDED'
      and normalized_provider_entity is not null
      and nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
          is not distinct from normalized_provider_entity;
    if normalized_customer is not null
       or (
         nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '') is not null
         and (
           (not already_bound and not exact_succeeded_legacy_binding)
           or nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
              is distinct from normalized_provider_entity
         )
       )
    then
      return jsonb_build_object('ok', false, 'reason', 'student_customer_binding_changed');
    end if;
  elsif normalized_customer is null
        or nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
           is distinct from normalized_customer
  then
    return jsonb_build_object('ok', false, 'reason', 'student_customer_binding_changed');
  end if;

  if normalized_kind = 'ENROLLMENT_PAYMENT'
     and nullif(trim(coalesce(profile_row.enrollment_payment_id, '')), '') is not null
     and (
       (
         not already_bound
         and not (
           attempt_row.status = 'SUCCEEDED'
           and normalized_provider_entity is not null
           and nullif(trim(coalesce(profile_row.enrollment_payment_id, '')), '')
               is not distinct from normalized_provider_entity
         )
       )
       or nullif(trim(coalesce(profile_row.enrollment_payment_id, '')), '')
          is distinct from normalized_provider_entity
     )
  then
    return jsonb_build_object('ok', false, 'reason', 'student_payment_binding_changed');
  end if;
  if normalized_kind = 'SUBSCRIPTION'
     and nullif(trim(coalesce(profile_row.subscription_id, '')), '') is not null
     and (
       (
         not already_bound
         and not (
           attempt_row.status = 'SUCCEEDED'
           and normalized_provider_entity is not null
           and nullif(trim(coalesce(profile_row.subscription_id, '')), '')
               is not distinct from normalized_provider_entity
         )
       )
       or nullif(trim(coalesce(profile_row.subscription_id, '')), '')
          is distinct from normalized_provider_entity
     )
  then
    return jsonb_build_object('ok', false, 'reason', 'student_subscription_binding_changed');
  end if;
  if normalized_kind = 'TOPUP_ORDER' and (
    attempt_row.logical_key !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or attempt_row.external_reference is distinct from 'wolfie-topup-order:' || attempt_row.logical_key
    or not exists (
      select 1 from public.wolfie_topup_orders as topup
       where topup.id::text = attempt_row.logical_key
         and topup.tenant_id = normalized_tenant
         and topup.student_id = p_student_id
         and topup.status in ('PENDING', 'CREATING')
         and topup.provider_payment_id is null
    )
  ) then
    return jsonb_build_object('ok', false, 'reason', 'topup_order_binding_changed');
  end if;

  if (
    select count(*) from public.tenant_memberships as membership
     where membership.user_id = p_student_id
  ) <> 1 or not exists (
    select 1 from public.tenant_memberships as membership
     where membership.user_id = p_student_id
       and membership.tenant_id = normalized_tenant
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    return jsonb_build_object('ok', false, 'reason', 'student_membership_changed');
  end if;

  if exists (
    select 1 from public.student_offboarding_operations as operation
     where operation.tenant_id = normalized_tenant
       and operation.student_id = p_student_id
       and operation.status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
  ) or exists (
    select 1 from public.student_account_deletion_claims as deletion
     where deletion.tenant_id = normalized_tenant
       and deletion.student_id = p_student_id
       and deletion.status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
  ) or exists (
    select 1 from public.student_billing_method_operations as billing_method
     where billing_method.tenant_id = normalized_tenant
       and billing_method.student_id = p_student_id
       and billing_method.status in ('CLAIMED', 'MUTATING', 'UNKNOWN', 'BLOCKED')
  ) then
    return jsonb_build_object('ok', false, 'reason', 'lifecycle_operation_active');
  end if;

  update public.asaas_provider_creation_attempts
     set lifecycle_student_id = p_student_id,
         lifecycle_binding_kind = normalized_kind,
         lifecycle_expected_customer_id = normalized_customer,
         lifecycle_bound_at = coalesce(lifecycle_bound_at, now()),
         lifecycle_released_at = null,
         lifecycle_last_error = null,
         updated_at = now()
   where id = attempt_row.id;
  return jsonb_build_object(
    'ok', true,
    'action', case when already_bound then 'ALREADY_BOUND' else 'BOUND' end
  );
end;
$_$;


--
-- Name: bind_student_offboarding_integrations(uuid, uuid, text, integer, text, text, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bind_student_offboarding_integrations(p_operation_id uuid, p_claim_token uuid, p_subscription_integration_id text, p_subscription_version integer, p_subscription_environment text, p_subscription_mode text, p_payment_integration_id text, p_payment_version integer, p_payment_environment text, p_payment_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.student_offboarding_operations%rowtype;
  expected_snapshot jsonb;
  payment_required boolean;
begin
  select operation.* into operation_row
    from public.student_offboarding_operations as operation
   where operation.id = p_operation_id
   for update;
  if not found
     or operation_row.claim_token is distinct from p_claim_token
     or operation_row.status not in ('CLAIMED', 'PROVIDER_MUTATING', 'UNKNOWN')
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'claim_lost'
    );
  end if;

  payment_required := exists (
    select 1
      from pg_catalog.jsonb_array_elements(
        operation_row.payment_snapshot
      ) as entry
     where nullif(entry ->> 'asaas_payment_id', '') is not null
  );
  if (operation_row.subscription_id is null) is distinct from
       (p_subscription_integration_id is null)
     or payment_required is distinct from
       (p_payment_integration_id is not null)
     or (p_subscription_integration_id is not null and (
       nullif(pg_catalog.btrim(p_subscription_integration_id), '') is null
       or coalesce(p_subscription_version, 0) < 1
       or p_subscription_environment not in (
         'platform', 'production', 'sandbox'
       )
       or p_subscription_mode not in (
         'PLATFORM_MANAGED_ROOT', 'PLATFORM_MANAGED_SUBACCOUNT', 'TENANT_BYOK'
       )
     ))
     or (p_payment_integration_id is not null and (
       nullif(pg_catalog.btrim(p_payment_integration_id), '') is null
       or coalesce(p_payment_version, 0) < 1
       or p_payment_environment not in (
         'platform', 'production', 'sandbox'
       )
       or p_payment_mode not in (
         'PLATFORM_MANAGED_ROOT', 'PLATFORM_MANAGED_SUBACCOUNT', 'TENANT_BYOK'
       )
     ))
  then
    update public.student_offboarding_operations
       set status = case
             when provider_started_at is null then 'ABORTED'
             else 'BLOCKED'
           end,
           last_error = 'integration_snapshot_invalid',
           completed_at = case
             when provider_started_at is null then pg_catalog.now()
             else completed_at
           end,
           lease_expires_at = case
             when provider_started_at is null then pg_catalog.now()
             else lease_expires_at
           end,
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'integration_snapshot_invalid'
    );
  end if;

  expected_snapshot := pg_catalog.jsonb_build_object(
    'subscription', case
      when p_subscription_integration_id is null then null
      else pg_catalog.jsonb_build_object(
        'integration_id', pg_catalog.btrim(p_subscription_integration_id),
        'version', p_subscription_version,
        'environment', p_subscription_environment,
        'mode', p_subscription_mode
      )
    end,
    'payment', case
      when p_payment_integration_id is null then null
      else pg_catalog.jsonb_build_object(
        'integration_id', pg_catalog.btrim(p_payment_integration_id),
        'version', p_payment_version,
        'environment', p_payment_environment,
        'mode', p_payment_mode
      )
    end
  );

  if operation_row.integration_snapshot = '{}'::jsonb then
    update public.student_offboarding_operations
       set integration_snapshot = expected_snapshot,
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object('ok', true, 'action', 'BOUND');
  end if;
  if operation_row.integration_snapshot is distinct from expected_snapshot then
    update public.student_offboarding_operations
       set status = case
             when provider_started_at is null then 'ABORTED'
             else 'BLOCKED'
           end,
           last_error = 'integration_context_changed',
           lease_expires_at = pg_catalog.now(),
           completed_at = case
             when provider_started_at is null then pg_catalog.now()
             else completed_at
           end,
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'integration_context_changed'
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'action', 'ALREADY_BOUND'
  );
end;
$$;


--
-- Name: birthdays_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.birthdays_today() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', profile.id,
        'name', profile.full_name,
        'phone', profile.phone,
        'tenant_id', profile.tenant_id,
        'role', profile.role
      )
    ),
    '[]'::jsonb
  )
  from public.profiles as profile
  where upper(pg_catalog.btrim(coalesce(profile.role, ''))) in (
      'STUDENT', 'TEACHER'
    )
    and profile.birth_date is not null
    and pg_catalog.to_char(profile.birth_date, 'MM-DD') =
      pg_catalog.to_char(
        (now() at time zone 'America/Sao_Paulo')::date,
        'MM-DD'
      )
    and nullif(pg_catalog.btrim(profile.phone), '') is not null
    and lower(pg_catalog.btrim(coalesce(
      profile.lifecycle_status,
      ''
    ))) = 'active'
    and coalesce(profile.is_test_account, false) is false
    and profile.date_automation_enabled is distinct from false
    and exists (
      select 1
      from public.tenant_memberships as membership
      where membership.user_id = profile.id
        and membership.tenant_id = profile.tenant_id
        and membership.role = upper(pg_catalog.btrim(profile.role))
        and membership.status = 'ACTIVE'
    );
$$;


--
-- Name: book_interview_slot_with_notifications(uuid, timestamp with time zone, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.book_interview_slot_with_notifications(p_booking_token uuid, p_chosen_slot timestamp with time zone, p_candidate_message text, p_management_phone text DEFAULT NULL::text, p_management_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_application public.job_applications%rowtype;
  v_candidate_result jsonb;
  v_management_result jsonb;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception using errcode = '42501', message = 'service_role_required';
  end if;
  if p_booking_token is null or p_chosen_slot is null then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if p_chosen_slot < pg_catalog.now() + interval '3 hours'
     or p_chosen_slot > pg_catalog.now() + interval '8 days' then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_slot');
  end if;

  select application.*
    into v_application
    from public.job_applications as application
   where application.booking_token = p_booking_token
   for update;
  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'not_found');
  end if;
  if v_application.interview_slot is not null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'already_booked',
      'booked', v_application.interview_slot
    );
  end if;

  begin
    update public.job_applications as application
       set interview_slot = p_chosen_slot
     where application.id = v_application.id
       and application.interview_slot is null;
  exception when unique_violation then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'taken');
  end;
  v_application.interview_slot := p_chosen_slot;

  v_candidate_result := private.enqueue_interview_notification_internal(
    v_application.id,
    p_chosen_slot,
    'BOOKED',
    'CANDIDATE',
    v_application.whatsapp,
    p_candidate_message
  );
  v_management_result := private.enqueue_interview_notification_internal(
    v_application.id,
    p_chosen_slot,
    'BOOKED',
    'MANAGEMENT',
    p_management_phone,
    p_management_message
  );

  -- A confirmação só existe se candidato e gestão forem avisados. Retornar
  -- sucesso parcial criava uma entrevista invisível para uma das partes. Uma
  -- falha aqui aborta também o UPDATE do slot, pois tudo vive nesta transação.
  if not coalesce((v_candidate_result ->> 'ok')::boolean, false)
     or not coalesce((v_management_result ->> 'ok')::boolean, false) then
    raise exception using
      errcode = '23514',
      message = 'interview_notification_outbox_required',
      detail = pg_catalog.jsonb_build_object(
        'candidate', v_candidate_result,
        'management', v_management_result
      )::text;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'booked', p_chosen_slot,
    'candidate_notification', v_candidate_result,
    'management_notification', v_management_result
  );
end;
$$;


--
-- Name: brl_texto(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.brl_texto(v numeric) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  -- Troca ponto por vírgula e vírgula por ponto de uma vez (o '#' é o pivô).
  select replace(replace(replace(
           to_char(coalesce(v, 0), 'FM999G999G990D00'),
         '.', '#'), ',', '.'), '#', ',');
$$;


--
-- Name: cancel_teacher_training(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_teacher_training(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.teacher_training_sessions%rowtype;
begin
 select * into s from public.teacher_training_sessions where id=p_id for update;
 if not found or not private.training_manager(s.tenant_id,auth.uid()) then raise exception using errcode='42501',message='Apenas a gestão pode cancelar este treinamento.'; end if;
 if s.status='COMPLETED' or s.class_log_id is not null then raise exception 'O treinamento já foi lançado no fechamento.'; end if;
 if s.status in ('CANCELLED','DECLINED') then return; end if;
 update public.teacher_training_sessions set status='CANCELLED' where id=p_id;
 update public.appointments set status='cancelled' where id=s.appointment_id;
end;
$$;


--
-- Name: canonical_weekday_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonical_weekday_name(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
  select case public.dow_name_to_int(p_value)
    when 0 then 'Domingo'
    when 1 then 'Segunda'
    when 2 then 'Terça'
    when 3 then 'Quarta'
    when 4 then 'Quinta'
    when 5 then 'Sexta'
    when 6 then 'Sábado'
    else null
  end
$$;


--
-- Name: FUNCTION canonical_weekday_name(p_value text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.canonical_weekday_name(p_value text) IS 'Converte nomes de dia PT/EN, com ou sem acento/-feira, para a grafia canonica usada em bookings.';


--
-- Name: cap_trial_reschedule_deadline(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cap_trial_reschedule_deadline() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.expires_at := least(new.expires_at, new.created_at + interval '60 minutes', new.requested_start_time);
  return new;
end;
$$;


--
-- Name: cas_wolfie_realtime_session_analysis(uuid, uuid, text, jsonb, jsonb, jsonb, jsonb, text, text, integer, integer, boolean, timestamp with time zone, uuid, uuid, uuid, uuid, jsonb, jsonb, text, text, uuid, uuid, uuid, numeric, jsonb, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cas_wolfie_realtime_session_analysis(p_session_id uuid, p_student_id uuid, p_tenant_id text, p_expected_report jsonb, p_expected_memory jsonb, p_next_report jsonb, p_next_memory jsonb, p_next_stage text, p_next_scenario_status text, p_next_scenario_step integer, p_next_retry_count integer, p_needs_external_verification boolean, p_recorded_at timestamp with time zone, p_assistant_turn_id uuid, p_student_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_completion_marker jsonb, p_session_report jsonb, p_expected_current_stage text, p_expected_scenario_status text, p_expected_pending_retry_id uuid, p_complete_retry_id uuid DEFAULT NULL::uuid, p_retry_turn_id uuid DEFAULT NULL::uuid, p_retry_score numeric DEFAULT NULL::numeric, p_retry_feedback jsonb DEFAULT '{}'::jsonb, p_correction_turn_id uuid DEFAULT NULL::uuid, p_new_corrections jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_current_report jsonb;
  v_current_memory jsonb;
  v_current_stage text;
  v_current_status text;
  v_current_finished_at timestamptz;
  v_current_retry_count integer;
  v_current_pending_retry_id uuid;
  v_assistant_payload jsonb;
  v_student_payload jsonb;
  v_analysis_marker jsonb;
  v_final_marker jsonb;
  v_final_guidance jsonb;
  v_next_turn_fields jsonb;
  v_correction jsonb;
  v_correction_feedback jsonb;
  v_requires_retry boolean;
  v_pending_retry_exists boolean := false;
  v_pending_retry_context jsonb := '{}'::jsonb;
  v_retry_next_action text;
  v_new_required_count integer := 0;
  v_inserted_count integer := 0;
  v_canonical_stage text;
  v_canonical_status text;
  v_canonical_step integer;
  v_canonical_report jsonb;
  v_canonical_memory jsonb;
  v_last_index integer;
  v_report_generated_at timestamptz;
  v_accomplishments text[];
  v_marker_correction_count integer;
  updated_count integer;
  retry_updated_count integer;
  retry_already_completed boolean := false;
begin
  if pg_catalog.jsonb_typeof(coalesce(p_expected_report, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_expected_memory, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_next_report, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_next_memory, '{}'::jsonb)) <> 'object'
     or p_next_stage not in (
       'discovery', 'briefing', 'guided_build', 'practice', 'feedback',
       'retry', 'simulation', 'readaptation', 'improvisation',
       'assessment', 'report', 'completed'
     )
     or p_next_scenario_status not in (
       'active', 'awaiting_retry', 'completed', 'abandoned', 'failed'
     )
     or p_next_scenario_step < 1
     or p_next_retry_count < 0
     or p_recorded_at is null
     or p_assistant_turn_id is null
     or p_student_turn_id is null
     or p_client_turn_id is null
     or p_claim_token is null
     or p_completion_marker is null
     or pg_catalog.jsonb_typeof(p_completion_marker) <> 'object'
     or pg_catalog.octet_length(p_completion_marker::text) > 100000
     or p_completion_marker ->> 'status' <> 'completed'
     or p_completion_marker ->> 'clientTurnId' is distinct from p_client_turn_id::text
     or p_completion_marker ->> 'studentTurnId' is distinct from p_student_turn_id::text
     or p_completion_marker ->> 'assistantTurnId' is distinct from p_assistant_turn_id::text
     or coalesce(p_completion_marker ->> 'version', '') <> '1'
     or coalesce(p_completion_marker ->> 'correctionsCreated', '0') !~ '^[0-9]+$'
     or p_session_report is null
     or pg_catalog.jsonb_typeof(p_session_report) <> 'object'
     or pg_catalog.octet_length(p_session_report::text) > 250000
     or p_session_report ->> 'tenant_id' is distinct from p_tenant_id
     or p_session_report ->> 'student_id' is distinct from p_student_id::text
     or p_session_report ->> 'conversation_session_id' is distinct from p_session_id::text
     or nullif(pg_catalog.btrim(p_session_report ->> 'topic'), '') is null
     or pg_catalog.jsonb_typeof(p_session_report -> 'accomplishments') <> 'array'
     or pg_catalog.jsonb_array_length(p_session_report -> 'accomplishments') > 20
     or pg_catalog.jsonb_typeof(p_session_report -> 'primary_corrections') <> 'array'
     or pg_catalog.jsonb_array_length(p_session_report -> 'primary_corrections') > 20
     or pg_catalog.jsonb_typeof(p_session_report -> 'new_vocabulary') <> 'array'
     or pg_catalog.jsonb_array_length(p_session_report -> 'new_vocabulary') > 30
     or pg_catalog.jsonb_typeof(p_session_report -> 'rubric_scores') <> 'object'
     or p_expected_current_stage not in (
       'discovery', 'briefing', 'guided_build', 'practice', 'feedback',
       'retry', 'simulation', 'readaptation', 'improvisation',
       'assessment', 'report', 'completed'
     )
     or p_expected_scenario_status not in (
       'active', 'awaiting_retry', 'completed', 'abandoned', 'failed'
     )
     or (p_complete_retry_id is null) <> (p_retry_turn_id is null)
     or (p_retry_turn_id is not null and p_retry_turn_id <> p_student_turn_id)
     or pg_catalog.jsonb_typeof(coalesce(p_retry_feedback, '{}'::jsonb)) <> 'object'
     or pg_catalog.octet_length(coalesce(p_retry_feedback, '{}'::jsonb)::text) > 50000
     or (p_retry_score is not null and (p_retry_score < 0 or p_retry_score > 100))
     or pg_catalog.jsonb_typeof(coalesce(p_new_corrections, '[]'::jsonb)) <> 'array'
     or pg_catalog.jsonb_array_length(coalesce(p_new_corrections, '[]'::jsonb)) > 5
     or pg_catalog.octet_length(coalesce(p_new_corrections, '[]'::jsonb)::text) > 100000
     or (
       pg_catalog.jsonb_array_length(coalesce(p_new_corrections, '[]'::jsonb)) > 0
       and p_correction_turn_id is distinct from p_student_turn_id
     ) then
    raise exception using errcode = '22023', message = 'invalid_realtime_state_cas';
  end if;

  begin
    v_report_generated_at := nullif(
      pg_catalog.btrim(p_session_report ->> 'generated_at'),
      ''
    )::timestamptz;
  exception when others then
    raise exception using errcode = '22023', message = 'invalid_realtime_report_timestamp';
  end;
  if v_report_generated_at is null then
    raise exception using errcode = '22023', message = 'invalid_realtime_report_timestamp';
  end if;
  v_marker_correction_count := greatest(
    0,
    (p_completion_marker ->> 'correctionsCreated')::integer
  );

  select coalesce(report_json, '{}'::jsonb),
         coalesce(memory_summary, '{}'::jsonb),
         wolfie_sessions.current_stage,
         scenario_status,
         finished_at,
         retry_count
    into v_current_report,
         v_current_memory,
         v_current_stage,
         v_current_status,
         v_current_finished_at,
         v_current_retry_count
    from public.wolfie_sessions
   where id = p_session_id
     and student_id = p_student_id
     and tenant_id = p_tenant_id
   for update;

  if not found
     or v_current_finished_at is not null
     or v_current_stage = 'completed'
     or v_current_status in ('completed', 'abandoned', 'failed')
     or v_current_stage is distinct from p_expected_current_stage
     or v_current_status is distinct from p_expected_scenario_status
     or v_current_report <> coalesce(p_expected_report, '{}'::jsonb)
     or v_current_memory <> coalesce(p_expected_memory, '{}'::jsonb) then
    return pg_catalog.jsonb_build_object('persisted', false, 'reason', 'cas_mismatch');
  end if;

  -- Fence every side effect with the live database claim. A worker that was
  -- paused for two minutes cannot resume after another worker reclaimed and
  -- finalized the same assistant turn.
  select coalesce(structured_payload, '{}'::jsonb)
    into v_assistant_payload
    from public.wolfie_turns
   where id = p_assistant_turn_id
     and session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'wolfie'
     and source_kind = 'openai_realtime'
   for update;
  if not found then
    return pg_catalog.jsonb_build_object('persisted', false, 'reason', 'claim_turn_missing');
  end if;
  v_analysis_marker := v_assistant_payload -> 'realtimeAnalysis';
  if coalesce(v_analysis_marker ->> 'status', '') <> 'processing'
     or v_analysis_marker ->> 'claimToken' <> p_claim_token::text then
    return pg_catalog.jsonb_build_object('persisted', false, 'reason', 'claim_fenced');
  end if;

  select coalesce(structured_payload, '{}'::jsonb)
    into v_student_payload
    from public.wolfie_turns
   where id = p_student_turn_id
     and session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'student'
     and source_kind = 'openai_realtime'
   for update;
  if not found then
    return pg_catalog.jsonb_build_object('persisted', false, 'reason', 'student_turn_missing');
  end if;

  if pg_catalog.jsonb_array_length(coalesce(p_new_corrections, '[]'::jsonb)) > 0
     and p_correction_turn_id is distinct from p_student_turn_id then
    raise exception using errcode = '22023', message = 'invalid_realtime_correction_turn';
  end if;

  -- The evaluator's pending-retry premise is part of the compare-and-swap.
  -- If another writer created, completed or replaced that correction while
  -- the provider was evaluating, no part of this stale analysis may commit.
  select id
    into v_current_pending_retry_id
    from public.wolfie_corrections
   where session_id = p_session_id
     and status = 'active'
     and requires_retry = true
     and retry_completed = false
   order by created_at desc, id desc
   limit 1
   for update;
  if v_current_pending_retry_id is distinct from p_expected_pending_retry_id then
    return pg_catalog.jsonb_build_object(
      'persisted', false,
      'reason', 'retry_invariant_changed'
    );
  end if;

  if p_complete_retry_id is not null then
    update public.wolfie_corrections
       set retry_completed = true,
           retry_turn_id = p_retry_turn_id,
           retry_score = p_retry_score,
           retry_feedback = coalesce(retry_feedback, '{}'::jsonb)
             || coalesce(p_retry_feedback, '{}'::jsonb),
           retry_completed_at = coalesce(retry_completed_at, p_recorded_at)
     where id = p_complete_retry_id
       and session_id = p_session_id
       and status = 'active'
       and requires_retry = true
       and retry_completed = false;
    get diagnostics retry_updated_count = row_count;

    if retry_updated_count <> 1 then
      select exists (
        select 1
          from public.wolfie_corrections
         where id = p_complete_retry_id
           and session_id = p_session_id
           and status = 'active'
           and requires_retry = true
           and retry_completed = true
           and retry_turn_id = p_retry_turn_id
      ) into retry_already_completed;
      if not retry_already_completed then
        return pg_catalog.jsonb_build_object('persisted', false, 'reason', 'retry_fenced');
      end if;
    end if;
  end if;

  select pg_catalog.jsonb_build_object(
           'original', wrong_sentence,
           'corrected', correct_sentence,
           'naturalVersion', natural_sentence,
           'category', error_type,
           'priority', priority
         )
    into v_pending_retry_context
    from public.wolfie_corrections
   where session_id = p_session_id
     and status = 'active'
     and requires_retry = true
     and retry_completed = false
   order by created_at desc, id desc
   limit 1
   for update;
  v_pending_retry_exists := found;
  if not v_pending_retry_exists then
    v_pending_retry_context := '{}'::jsonb;
  end if;

  for v_correction in
    select value
      from pg_catalog.jsonb_array_elements(
        coalesce(p_new_corrections, '[]'::jsonb)
      )
  loop
    if pg_catalog.jsonb_typeof(v_correction) <> 'object'
       or nullif(pg_catalog.btrim(v_correction ->> 'wrong_sentence'), '') is null
       or nullif(pg_catalog.btrim(v_correction ->> 'correct_sentence'), '') is null
       or nullif(pg_catalog.btrim(v_correction ->> 'explanation_pt'), '') is null
       or pg_catalog.octet_length(v_correction ->> 'wrong_sentence') > 8000
       or pg_catalog.octet_length(v_correction ->> 'correct_sentence') > 8000
       or pg_catalog.octet_length(coalesce(v_correction ->> 'natural_sentence', '')) > 8000
       or pg_catalog.octet_length(v_correction ->> 'explanation_pt') > 8000
       or coalesce(v_correction ->> 'priority', '') not in ('low', 'medium', 'high')
       or coalesce(v_correction ->> 'requires_retry', 'false') not in ('true', 'false') then
      raise exception using errcode = '22023', message = 'invalid_realtime_correction';
    end if;
    v_correction_feedback := coalesce(
      v_correction -> 'retry_feedback',
      '{}'::jsonb
    );
    if pg_catalog.jsonb_typeof(v_correction_feedback) <> 'object'
       or pg_catalog.octet_length(v_correction_feedback::text) > 50000 then
      raise exception using errcode = '22023', message = 'invalid_realtime_correction_feedback';
    end if;
    v_requires_retry := coalesce(
      (v_correction ->> 'requires_retry')::boolean,
      false
    );
    if v_pending_retry_exists or v_new_required_count > 0 then
      v_requires_retry := false;
    end if;

    insert into public.wolfie_corrections (
      session_id,
      turn_id,
      wrong_sentence,
      correct_sentence,
      natural_sentence,
      explanation_pt,
      error_type,
      skill_focus,
      priority,
      requires_retry,
      retry_completed,
      retry_feedback
    ) values (
      p_session_id,
      p_correction_turn_id,
      pg_catalog.left(pg_catalog.btrim(v_correction ->> 'wrong_sentence'), 2000),
      pg_catalog.left(pg_catalog.btrim(v_correction ->> 'correct_sentence'), 2000),
      pg_catalog.left(pg_catalog.btrim(coalesce(v_correction ->> 'natural_sentence', '')), 2000),
      pg_catalog.left(pg_catalog.btrim(v_correction ->> 'explanation_pt'), 3000),
      pg_catalog.left(pg_catalog.btrim(coalesce(v_correction ->> 'error_type', 'general')), 80),
      nullif(pg_catalog.left(pg_catalog.btrim(coalesce(v_correction ->> 'skill_focus', '')), 80), ''),
      v_correction ->> 'priority',
      v_requires_retry,
      false,
      v_correction_feedback
    );
    v_inserted_count := v_inserted_count + 1;
    if v_requires_retry then
      v_new_required_count := 1;
      v_pending_retry_exists := true;
    end if;
  end loop;

  -- Re-read the invariant while the session is locked. A newer callback may
  -- never advance or finish a session while any canonical retry is open.
  select pg_catalog.jsonb_build_object(
           'original', wrong_sentence,
           'corrected', correct_sentence,
           'naturalVersion', natural_sentence,
           'category', error_type,
           'priority', priority
         )
    into v_pending_retry_context
    from public.wolfie_corrections
   where session_id = p_session_id
     and status = 'active'
     and requires_retry = true
     and retry_completed = false
   order by created_at desc, id desc
   limit 1
   for update;
  v_pending_retry_exists := found;
  if v_pending_retry_exists then
    v_retry_next_action := 'Retry the pending correction before advancing.';
    if nullif(pg_catalog.btrim(v_pending_retry_context ->> 'corrected'), '') is not null then
      v_retry_next_action := v_retry_next_action || ' ' || pg_catalog.left(
        pg_catalog.btrim(v_pending_retry_context ->> 'corrected'),
        1000
      );
    end if;
  else
    v_pending_retry_context := '{}'::jsonb;
  end if;

  -- The inverse invariant matters under retry races: an analyzer that saw a
  -- correction before another worker completed it must never leave the
  -- session awaiting a retry that no longer exists. Raising rolls back every
  -- optional correction/retry side effect and makes the turn re-analyzable.
  if not v_pending_retry_exists
     and (p_next_stage = 'retry' or p_next_scenario_status = 'awaiting_retry') then
    raise exception using
      errcode = '40001',
      message = 'realtime_retry_invariant_changed';
  end if;

  v_canonical_stage := case
    when v_pending_retry_exists then 'retry'
    else p_next_stage
  end;
  v_canonical_status := case
    when v_pending_retry_exists then 'awaiting_retry'
    else p_next_scenario_status
  end;
  v_canonical_step := case
    when v_pending_retry_exists then 6
    else p_next_scenario_step
  end;
  v_canonical_report := coalesce(p_next_report, '{}'::jsonb);
  v_canonical_memory := coalesce(p_next_memory, '{}'::jsonb);
  v_canonical_report := pg_catalog.jsonb_set(
    v_canonical_report,
    '{currentStage}',
    pg_catalog.to_jsonb(v_canonical_stage),
    true
  );
  v_canonical_report := pg_catalog.jsonb_set(
    v_canonical_report,
    '{scenarioStatus}',
    pg_catalog.to_jsonb(v_canonical_status),
    true
  );
  v_canonical_memory := pg_catalog.jsonb_set(
    v_canonical_memory,
    '{currentStage}',
    pg_catalog.to_jsonb(v_canonical_stage),
    true
  );
  if v_pending_retry_exists then
    v_canonical_report := v_canonical_report
      || pg_catalog.jsonb_build_object(
        'nextStep', v_retry_next_action,
        'pendingRetry', v_pending_retry_context
      );
    v_canonical_memory := v_canonical_memory
      || pg_catalog.jsonb_build_object(
        'recommendedNextStep', v_retry_next_action,
        'pendingRetry', v_pending_retry_context
      );
  end if;
  if pg_catalog.jsonb_typeof(v_canonical_report -> 'realtimeAnalyses') = 'array'
     and pg_catalog.jsonb_array_length(v_canonical_report -> 'realtimeAnalyses') > 0 then
    v_last_index := pg_catalog.jsonb_array_length(
      v_canonical_report -> 'realtimeAnalyses'
    ) - 1;
    v_canonical_report := pg_catalog.jsonb_set(
      v_canonical_report,
      array['realtimeAnalyses', v_last_index::text, 'stage'],
      pg_catalog.to_jsonb(v_canonical_stage),
      true
    );
    v_canonical_report := pg_catalog.jsonb_set(
      v_canonical_report,
      array['realtimeAnalyses', v_last_index::text, 'scenarioStatus'],
      pg_catalog.to_jsonb(v_canonical_status),
      true
    );
    v_canonical_report := pg_catalog.jsonb_set(
      v_canonical_report,
      array['realtimeAnalyses', v_last_index::text, 'requiresRetry'],
      pg_catalog.to_jsonb(v_pending_retry_exists),
      true
    );
    if v_pending_retry_exists then
      v_canonical_report := pg_catalog.jsonb_set(
        v_canonical_report,
        array['realtimeAnalyses', v_last_index::text, 'retryCompleted'],
        'false'::jsonb,
        true
      );
      v_canonical_report := pg_catalog.jsonb_set(
        v_canonical_report,
        array['realtimeAnalyses', v_last_index::text, 'nextAction'],
        pg_catalog.to_jsonb(v_retry_next_action),
        true
      );
      v_canonical_report := pg_catalog.jsonb_set(
        v_canonical_report,
        array['realtimeAnalyses', v_last_index::text, 'pendingRetry'],
        v_pending_retry_context,
        true
      );
    end if;
  end if;

  update public.wolfie_sessions
     set current_stage = v_canonical_stage,
         scenario_status = v_canonical_status,
         scenario_step = v_canonical_step,
         retry_count = case
           when pg_catalog.jsonb_array_length(
             coalesce(p_new_corrections, '[]'::jsonb)
           ) > 0 then v_current_retry_count + v_new_required_count
           else greatest(
             v_current_retry_count + v_new_required_count,
             p_next_retry_count
           )
         end,
         needs_external_verification =
           coalesce(needs_external_verification, false)
           or coalesce(p_needs_external_verification, false),
         report_json = v_canonical_report,
         memory_summary = v_canonical_memory,
         last_activity_at = p_recorded_at,
         updated_at = p_recorded_at,
         finished_at = case
           when v_canonical_status = 'completed' then p_recorded_at
           else finished_at
         end
   where id = p_session_id
     and student_id = p_student_id
     and tenant_id = p_tenant_id
     and finished_at is null
     and current_stage <> 'completed'
     and scenario_status not in ('completed', 'abandoned', 'failed');
  get diagnostics updated_count = row_count;
  if updated_count <> 1 then
    raise exception using
      errcode = '40001',
      message = 'realtime_state_cas_lost_after_lock';
  end if;

  select coalesce(
           pg_catalog.array_agg(
             pg_catalog.left(item.value, 500)
             order by item.ordinality
           ),
           '{}'::text[]
         )
    into v_accomplishments
    from pg_catalog.jsonb_array_elements_text(
      p_session_report -> 'accomplishments'
    ) with ordinality as item(value, ordinality);

  -- The canonical JSON report, its materialized projection and both turn
  -- markers commit together. A crash can therefore never finish a session
  -- while leaving its report stale or its analysis marker in `processing`.
  insert into public.wolfie_session_reports as existing_report (
    tenant_id,
    student_id,
    conversation_session_id,
    activity_session_id,
    topic,
    objective,
    difficulty,
    accomplishments,
    primary_corrections,
    new_vocabulary,
    recurring_error,
    best_phrase,
    review_point,
    next_step,
    practice_mission,
    rubric_scores,
    generated_by_model,
    generated_at
  ) values (
    p_tenant_id,
    p_student_id,
    p_session_id,
    null,
    pg_catalog.left(pg_catalog.btrim(p_session_report ->> 'topic'), 1000),
    nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'objective', '')), 4000), ''),
    nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'difficulty', '')), 100), ''),
    v_accomplishments,
    p_session_report -> 'primary_corrections',
    p_session_report -> 'new_vocabulary',
    nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'recurring_error', '')), 4000), ''),
    nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'best_phrase', '')), 4000), ''),
    nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'review_point', '')), 4000), ''),
    case
      when v_pending_retry_exists then v_retry_next_action
      else nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'next_step', '')), 4000), '')
    end,
    case
      when v_pending_retry_exists then v_retry_next_action
      else nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'practice_mission', '')), 4000), '')
    end,
    p_session_report -> 'rubric_scores',
    nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'generated_by_model', '')), 200), ''),
    v_report_generated_at
  )
  on conflict (conversation_session_id)
    where conversation_session_id is not null
  do update set
    tenant_id = excluded.tenant_id,
    student_id = excluded.student_id,
    topic = excluded.topic,
    objective = excluded.objective,
    difficulty = excluded.difficulty,
    accomplishments = excluded.accomplishments,
    primary_corrections = excluded.primary_corrections,
    new_vocabulary = excluded.new_vocabulary,
    recurring_error = excluded.recurring_error,
    best_phrase = excluded.best_phrase,
    review_point = excluded.review_point,
    next_step = excluded.next_step,
    practice_mission = excluded.practice_mission,
    rubric_scores = excluded.rubric_scores,
    generated_by_model = excluded.generated_by_model,
    generated_at = excluded.generated_at
  where existing_report.student_id = p_student_id
    and existing_report.tenant_id = p_tenant_id
    and existing_report.generated_at <= excluded.generated_at;

  v_final_guidance := coalesce(
    p_completion_marker -> 'realtimeGuidance',
    '{}'::jsonb
  );
  if pg_catalog.jsonb_typeof(v_final_guidance) = 'object' then
    v_final_guidance := v_final_guidance
      || pg_catalog.jsonb_build_object(
        'currentStage', v_canonical_stage,
        'scenarioStatus', v_canonical_status,
        'requiresRetry', v_pending_retry_exists
      );
    if v_pending_retry_exists then
      v_final_guidance := v_final_guidance
        || pg_catalog.jsonb_build_object(
          'nextAction', v_retry_next_action,
          'pendingRetry', v_pending_retry_context
        );
    end if;
  else
    v_final_guidance := '{}'::jsonb;
  end if;
  v_marker_correction_count := greatest(
    v_marker_correction_count,
    v_inserted_count
  );
  v_final_marker := p_completion_marker
    || pg_catalog.jsonb_build_object(
      'currentStage', v_canonical_stage,
      'scenarioStatus', v_canonical_status,
      'correctionsCreated', v_marker_correction_count,
      'requiresRetry', v_pending_retry_exists,
      'persistence', pg_catalog.jsonb_build_object(
        'sessionState', true,
        'sessionReport', true,
        'turnMarkers', true
      ),
      'realtimeGuidance', v_final_guidance
    );
  if v_pending_retry_exists then
    v_final_marker := v_final_marker
      || pg_catalog.jsonb_build_object(
        'retryCompleted', false,
        'nextAction', v_retry_next_action,
        'pendingRetry', v_pending_retry_context
      );
  end if;
  v_next_turn_fields := pg_catalog.jsonb_build_object(
    'eligibleForCorrection', true,
    'learnerIntent', v_final_marker -> 'learnerIntent',
    'realtimeAnalysis', v_final_marker
  );

  update public.wolfie_turns
     set structured_payload = v_student_payload || v_next_turn_fields,
         message_type = case
           when v_marker_correction_count > 0 then 'correction'
           else 'feedback'
         end,
         requires_retry = v_pending_retry_exists
   where id = p_student_turn_id;
  update public.wolfie_turns
     set structured_payload = v_assistant_payload || v_next_turn_fields,
         message_type = case
           when v_marker_correction_count > 0 then 'correction'
           else 'feedback'
         end,
         stage = v_canonical_stage,
         requires_retry = v_pending_retry_exists
   where id = p_assistant_turn_id;

  return pg_catalog.jsonb_build_object(
    'persisted', true,
    'stage', v_canonical_stage,
    'scenarioStatus', v_canonical_status,
    'correctionsCreated', v_marker_correction_count,
    'requiredRetryCreated', v_new_required_count = 1,
    'marker', v_final_marker
  );
end;
$_$;


--
-- Name: FUNCTION cas_wolfie_realtime_session_analysis(p_session_id uuid, p_student_id uuid, p_tenant_id text, p_expected_report jsonb, p_expected_memory jsonb, p_next_report jsonb, p_next_memory jsonb, p_next_stage text, p_next_scenario_status text, p_next_scenario_step integer, p_next_retry_count integer, p_needs_external_verification boolean, p_recorded_at timestamp with time zone, p_assistant_turn_id uuid, p_student_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_completion_marker jsonb, p_session_report jsonb, p_expected_current_stage text, p_expected_scenario_status text, p_expected_pending_retry_id uuid, p_complete_retry_id uuid, p_retry_turn_id uuid, p_retry_score numeric, p_retry_feedback jsonb, p_correction_turn_id uuid, p_new_corrections jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.cas_wolfie_realtime_session_analysis(p_session_id uuid, p_student_id uuid, p_tenant_id text, p_expected_report jsonb, p_expected_memory jsonb, p_next_report jsonb, p_next_memory jsonb, p_next_stage text, p_next_scenario_status text, p_next_scenario_step integer, p_next_retry_count integer, p_needs_external_verification boolean, p_recorded_at timestamp with time zone, p_assistant_turn_id uuid, p_student_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_completion_marker jsonb, p_session_report jsonb, p_expected_current_stage text, p_expected_scenario_status text, p_expected_pending_retry_id uuid, p_complete_retry_id uuid, p_retry_turn_id uuid, p_retry_score numeric, p_retry_feedback jsonb, p_correction_turn_id uuid, p_new_corrections jsonb) IS 'Fenced atomic commit for Realtime state, materialized report, turn markers, corrections and optional retry completion.';


--
-- Name: central_instance_for_tenant(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.central_instance_for_tenant(p_tenant text) RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT whatsapp_instance FROM (
    SELECT whatsapp_instance,
      CASE WHEN role='SCHOOL_ADMIN' THEN 0 WHEN role='SUPER_ADMIN' THEN 1 WHEN role='TEACHER' THEN 2 ELSE 3 END AS pri
    FROM profiles
    WHERE tenant_id = p_tenant
      AND whatsapp_instance IS NOT NULL AND whatsapp_instance <> ''
      AND role IN ('SCHOOL_ADMIN','SUPER_ADMIN','TEACHER')
    ORDER BY pri
    LIMIT 1
  ) z;
$$;


--
-- Name: change_booking_schedule(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_booking_schedule(p_booking_id uuid, p_day_of_week text, p_time_slot text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_actor_id uuid := auth.uid();
  v_actor_role text;
  v_actor_tenant text;
  v_actor_name text;
  v_booking public.bookings%rowtype;
  v_teacher_name text;
  v_student_name text;
  v_day text;
  v_day_number integer;
  v_time text;
  v_group_jid text;
  v_message text;
  v_notification_id uuid;
begin
  if v_actor_id is null then
    raise exception using errcode = '42501', message = 'Sessão expirada. Entre novamente.';
  end if;

  select p.role, p.tenant_id, p.full_name
    into v_actor_role, v_actor_tenant, v_actor_name
    from public.profiles as p
   where p.id = v_actor_id;

  if v_actor_role is null
     or v_actor_role not in ('TEACHER', 'SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN') then
    raise exception using errcode = '42501', message = 'Seu perfil não pode alterar agendas.';
  end if;

  select b.*
    into v_booking
    from public.bookings as b
   where b.id = p_booking_id
   for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'Aula não encontrada.';
  end if;

  if v_booking.tenant_id is distinct from v_actor_tenant then
    raise exception using errcode = '42501', message = 'Aula fora da sua escola.';
  end if;

  if v_actor_role = 'TEACHER' and v_booking.teacher_id is distinct from v_actor_id then
    raise exception using errcode = '42501', message = 'Você só pode alterar alunos da sua própria agenda.';
  end if;

  if v_booking.status is distinct from 'SCHEDULED' then
    raise exception using errcode = '22023', message = 'Somente aulas ativas podem ter o horário alterado.';
  end if;

  v_day := case lower(trim(coalesce(p_day_of_week, '')))
    when 'segunda' then 'Segunda'
    when 'terça' then 'Terça'
    when 'terca' then 'Terça'
    when 'quarta' then 'Quarta'
    when 'quinta' then 'Quinta'
    when 'sexta' then 'Sexta'
    when 'sábado' then 'Sábado'
    when 'sabado' then 'Sábado'
    else null
  end;

  v_day_number := case v_day
    when 'Segunda' then 1
    when 'Terça' then 2
    when 'Quarta' then 3
    when 'Quinta' then 4
    when 'Sexta' then 5
    when 'Sábado' then 6
    else null
  end;

  v_time := left(trim(coalesce(p_time_slot, '')), 5);
  if v_day is null then
    raise exception using errcode = '22023', message = 'Escolha um dia válido de segunda a sábado.';
  end if;
  if v_time !~ '^(0[0-9]|1[0-9]|2[0-3]):(00|30)$' then
    raise exception using errcode = '22023', message = 'Escolha um horário em intervalos de 30 minutos.';
  end if;

  if v_booking.day_of_week in (v_day, case when v_day = 'Terça' then 'Terca' else v_day end)
     and left(v_booking.time_slot, 5) = v_time then
    return jsonb_build_object(
      'ok', true,
      'changed', false,
      'booking_id', v_booking.id,
      'day_of_week', v_day,
      'time_slot', v_time,
      'notification_queued', false
    );
  end if;

  -- Serializa tentativas para o mesmo professor/aluno e fecha a janela entre
  -- o teste de conflito e o update (o índice legado não cobre esses dois casos).
  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'schedule:teacher:' || v_booking.teacher_id::text || ':' || v_day || ':' || v_time,
      0
    )
  );
  perform pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'schedule:student:' || v_booking.student_id::text || ':' || v_day || ':' || v_time,
      0
    )
  );

  if not exists (
    select 1
      from public.teacher_availability as availability
     where availability.teacher_id = v_booking.teacher_id
       and availability.tenant_id = v_booking.tenant_id
       and availability.day_of_week = v_day_number
       and availability.start_time = v_time::time
  ) then
    raise exception using errcode = '23514', message = 'O novo horário não está na disponibilidade cadastrada do professor.';
  end if;

  if exists (
    select 1
      from public.bookings as conflict
     where conflict.id <> v_booking.id
       and conflict.tenant_id = v_booking.tenant_id
       and conflict.teacher_id = v_booking.teacher_id
       and conflict.status = 'SCHEDULED'
       and conflict.day_of_week in (v_day, case when v_day = 'Terça' then 'Terca' else v_day end)
       and left(conflict.time_slot, 5) = v_time
  ) then
    raise exception using errcode = '23P01', message = 'O professor já possui uma aula nesse dia e horário.';
  end if;

  if exists (
    select 1
      from public.bookings as conflict
     where conflict.id <> v_booking.id
       and conflict.tenant_id = v_booking.tenant_id
       and conflict.student_id = v_booking.student_id
       and conflict.status = 'SCHEDULED'
       and conflict.day_of_week in (v_day, case when v_day = 'Terça' then 'Terca' else v_day end)
       and left(conflict.time_slot, 5) = v_time
  ) then
    raise exception using errcode = '23P01', message = 'O aluno já possui uma aula nesse dia e horário.';
  end if;

  select p.full_name into v_teacher_name
    from public.profiles as p where p.id = v_booking.teacher_id;
  select p.full_name into v_student_name
    from public.profiles as p where p.id = v_booking.student_id;

  update public.bookings
     set day_of_week = v_day,
         time_slot = v_time
   where id = v_booking.id;

  insert into public.audit_logs (
    tenant_id,
    user_id,
    user_role,
    action,
    resource_type,
    resource_id,
    old_values,
    new_values,
    diff
  ) values (
    v_booking.tenant_id,
    v_actor_id,
    v_actor_role,
    'booking_schedule_changed',
    'booking',
    v_booking.id::text,
    jsonb_build_object(
      'day_of_week', v_booking.day_of_week,
      'time_slot', left(v_booking.time_slot, 5),
      'teacher_id', v_booking.teacher_id,
      'student_id', v_booking.student_id
    ),
    jsonb_build_object(
      'day_of_week', v_day,
      'time_slot', v_time,
      'teacher_id', v_booking.teacher_id,
      'student_id', v_booking.student_id
    ),
    jsonb_build_object(
      'day_of_week', jsonb_build_array(v_booking.day_of_week, v_day),
      'time_slot', jsonb_build_array(left(v_booking.time_slot, 5), v_time)
    )
  );

  select nullif(trim(p.teachers_group_id), '')
    into v_group_jid
    from public.profiles as p
   where p.tenant_id = v_booking.tenant_id
     and p.role in ('SCHOOL_ADMIN', 'SUPER_ADMIN')
     and nullif(trim(p.teachers_group_id), '') is not null
   order by case when p.role = 'SCHOOL_ADMIN' then 0 else 1 end, p.created_at
   limit 1;

  -- Grupo operacional legado da Wise Wolf. Um grupo configurado no perfil da
  -- direção sempre tem precedência sobre este fallback.
  v_group_jid := coalesce(v_group_jid, '120363403699904869@g.us');
  v_message := format(
    E'🔄 *ALTERAÇÃO DE AGENDA*\n\n👨‍🏫 Professor: *%s*\n👤 Aluno: *%s*\n\nAntes: %s às %s\nAgora: *%s às %s*\n\nAlterado por: %s\n_Ajuste combinado entre professor e aluno._',
    coalesce(v_teacher_name, 'Professor'),
    coalesce(v_student_name, 'Aluno'),
    v_booking.day_of_week,
    left(v_booking.time_slot, 5),
    v_day,
    v_time,
    coalesce(v_actor_name, v_actor_role)
  );

  insert into public.notification_queue (
    tenant_id,
    teacher_id,
    student_id,
    student_name,
    student_phone,
    message_body,
    scheduled_for,
    status,
    source_id,
    source_type,
    notification_kind
  ) values (
    v_booking.tenant_id,
    v_booking.teacher_id,
    v_booking.student_id,
    v_student_name,
    v_group_jid,
    v_message,
    now(),
    'pending',
    v_booking.id,
    'BOOKING_SCHEDULE',
    'SCHEDULE_CHANGE_GROUP'
  )
  returning id into v_notification_id;

  return jsonb_build_object(
    'ok', true,
    'changed', true,
    'booking_id', v_booking.id,
    'day_of_week', v_day,
    'time_slot', v_time,
    'notification_queued', true,
    'notification_id', v_notification_id
  );
end;
$_$;


--
-- Name: FUNCTION change_booking_schedule(p_booking_id uuid, p_day_of_week text, p_time_slot text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.change_booking_schedule(p_booking_id uuid, p_day_of_week text, p_time_slot text) IS 'Altera somente dia/horário de booking próprio (professor) ou do tenant (gestão), audita e enfileira aviso ao grupo operacional.';


--
-- Name: check_and_unlock_achievements(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_and_unlock_achievements(p_student_id uuid, p_tenant_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_streak RECORD;
    v_mastered_count INTEGER;
    v_referral_count INTEGER;
    v_attendance_streak INTEGER;
    v_unlocked TEXT[] := '{}';
BEGIN
    -- Get streak
    SELECT * INTO v_streak FROM public.student_streaks WHERE student_id = p_student_id;

    -- Check FIRST_WEEK (7-day streak)
    IF v_streak IS NOT NULL AND v_streak.current_streak >= 7 THEN
        INSERT INTO public.student_achievements (student_id, achievement_code)
        VALUES (p_student_id, 'FIRST_WEEK')
        ON CONFLICT (student_id, achievement_code) DO NOTHING;
        IF FOUND THEN v_unlocked := array_append(v_unlocked, 'FIRST_WEEK'); END IF;
    END IF;

    -- Check FULL_MONTH (30-day streak)
    IF v_streak IS NOT NULL AND v_streak.current_streak >= 30 THEN
        INSERT INTO public.student_achievements (student_id, achievement_code)
        VALUES (p_student_id, 'FULL_MONTH')
        ON CONFLICT (student_id, achievement_code) DO NOTHING;
        IF FOUND THEN v_unlocked := array_append(v_unlocked, 'FULL_MONTH'); END IF;
    END IF;

    -- Check CENTURY (100 mastered SRS cards)
    SELECT COUNT(*) INTO v_mastered_count
    FROM public.student_srs_cards
    WHERE student_id = p_student_id AND status = 'MASTERED';

    IF v_mastered_count >= 100 THEN
        INSERT INTO public.student_achievements (student_id, achievement_code)
        VALUES (p_student_id, 'CENTURY')
        ON CONFLICT (student_id, achievement_code) DO NOTHING;
        IF FOUND THEN v_unlocked := array_append(v_unlocked, 'CENTURY'); END IF;
    END IF;

    -- Check FIRST_REFERRAL and AMBASSADOR
    SELECT COUNT(*) INTO v_referral_count
    FROM public.affiliate_conversions
    WHERE referrer_id = p_student_id AND status = 'REWARD_RELEASED';

    IF v_referral_count >= 1 THEN
        INSERT INTO public.student_achievements (student_id, achievement_code)
        VALUES (p_student_id, 'FIRST_REFERRAL')
        ON CONFLICT (student_id, achievement_code) DO NOTHING;
        IF FOUND THEN v_unlocked := array_append(v_unlocked, 'FIRST_REFERRAL'); END IF;
    END IF;

    IF v_referral_count >= 5 THEN
        INSERT INTO public.student_achievements (student_id, achievement_code)
        VALUES (p_student_id, 'AMBASSADOR')
        ON CONFLICT (student_id, achievement_code) DO NOTHING;
        IF FOUND THEN v_unlocked := array_append(v_unlocked, 'AMBASSADOR'); END IF;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'newly_unlocked', to_jsonb(v_unlocked),
        'total_checked', 5
    );
END;
$$;


--
-- Name: check_registration_availability(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_registration_availability(p_cpf text, p_tenant_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_clean_cpf text;
    v_exists boolean;
BEGIN
    -- Limpa o CPF (deixa apenas números)
    v_clean_cpf := regexp_replace(p_cpf, '\D', '', 'g');

    -- Verifica se já existe perfil com este CPF na unidade
    SELECT EXISTS (
        SELECT 1 
        FROM profiles 
        WHERE cpf = v_clean_cpf 
        AND tenant_id = p_tenant_id
    ) INTO v_exists;

    IF v_exists THEN
        RETURN json_build_object(
            'available', false,
            'message', 'Este CPF já está matriculado nesta unidade. Acesse sua conta ou recupere a senha.'
        );
    ELSE
        RETURN json_build_object(
            'available', true,
            'message', 'CPF disponível'
        );
    END IF;
END;
$$;


--
-- Name: claim_asaas_outbound_message(text, uuid, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_asaas_outbound_message(p_tenant_id text, p_student_id uuid, p_provider_entity_id text, p_notification_kind text, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  attempt_row public.asaas_outbound_message_attempts%rowtype;
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  normalized_provider_id text := nullif(pg_catalog.btrim(coalesce(p_provider_entity_id, '')), '');
  normalized_kind text := upper(pg_catalog.btrim(coalesce(p_notification_kind, '')));
  safe_lease integer := greatest(60, least(coalesce(p_lease_seconds, 300), 600));
begin
  if normalized_tenant is null or p_student_id is null
     or normalized_provider_id is null or length(normalized_provider_id) > 240
     or normalized_kind !~ '^[A-Z0-9_]{1,80}$' or p_claim_token is null
  then
    raise exception using errcode = '22023', message = 'invalid_outbound_message_claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' || p_student_id::text,
      0
    )
  );

  if not exists (
    select 1 from public.profiles as profile
     where profile.id = p_student_id
       and profile.tenant_id = normalized_tenant
       and profile.role = 'STUDENT'
       and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) = 'active'
  ) or (
    select count(*) from public.tenant_memberships as membership
     where membership.user_id = p_student_id
  ) <> 1 or not exists (
    select 1 from public.tenant_memberships as membership
     where membership.user_id = p_student_id
       and membership.tenant_id = normalized_tenant
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'student_lifecycle_inactive'
    );
  end if;

  if exists (
    select 1 from public.student_offboarding_operations as operation
     where operation.tenant_id = normalized_tenant
       and operation.student_id = p_student_id
       and operation.status in (
         'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED'
       )
  ) or exists (
    select 1 from public.student_account_deletion_claims as deletion
     where deletion.tenant_id = normalized_tenant
       and deletion.student_id = p_student_id
       and deletion.status in (
         'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED'
       )
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'lifecycle_operation_active'
    );
  end if;

  insert into public.asaas_outbound_message_attempts (
    tenant_id, student_id, provider_entity_id, notification_kind,
    claim_token, lease_expires_at
  ) values (
    normalized_tenant, p_student_id, normalized_provider_id, normalized_kind,
    p_claim_token, now() + pg_catalog.make_interval(secs => safe_lease)
  ) on conflict (tenant_id, provider_entity_id, notification_kind) do nothing;

  select message_attempt.* into attempt_row
    from public.asaas_outbound_message_attempts as message_attempt
   where message_attempt.tenant_id = normalized_tenant
     and message_attempt.provider_entity_id = normalized_provider_id
     and message_attempt.notification_kind = normalized_kind
   for update;

  if attempt_row.student_id is distinct from p_student_id then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'outbound_message_student_mismatch',
      'attempt_id', attempt_row.id
    );
  end if;
  if attempt_row.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED')
     or attempt_row.submit_attempt_count > 0
  then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'action', 'ALREADY_FINAL',
      'attempt_id', attempt_row.id, 'status', attempt_row.status
    );
  end if;
  if attempt_row.claim_token is distinct from p_claim_token
     and attempt_row.lease_expires_at > now()
  then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'action', 'IN_PROGRESS',
      'attempt_id', attempt_row.id, 'status', attempt_row.status
    );
  end if;

  update public.asaas_outbound_message_attempts
     set claim_token = p_claim_token,
         lease_expires_at = now() + pg_catalog.make_interval(secs => safe_lease),
         updated_at = now()
   where id = attempt_row.id
   returning * into attempt_row;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'action', 'SUBMIT_ONCE', 'attempt_id', attempt_row.id,
    'claim_token', attempt_row.claim_token, 'status', attempt_row.status
  );
end;
$_$;


--
-- Name: claim_asaas_payment_split_message(text, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_asaas_payment_split_message(p_tenant_id text, p_payment_id uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.asaas_payment_split_message_attempts%rowtype;
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  safe_lease integer := greatest(60, least(coalesce(p_lease_seconds, 300), 600));
begin
  if normalized_tenant is null or p_payment_id is null or p_claim_token is null then
    raise exception using errcode = '22023', message = 'invalid_payment_split_message_claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'payment-split-message:' || normalized_tenant || ':' || p_payment_id::text,
      0
    )
  );

  perform 1
    from public.student_payments as payment
   where payment.id = p_payment_id
     and payment.tenant_id = normalized_tenant
     and upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
       'RECEIVED', 'RECEIVED_IN_CASH'
     )
     and coalesce(payment.value, 0) > 0
   for update;
  if not found
     or not exists (
       select 1
         from public.payment_split_settings as setting
        where setting.tenant_id = normalized_tenant
          and setting.is_active
     )
     or not exists (
       select 1
         from public.tenants as tenant
        where tenant.id = normalized_tenant
          and tenant.whatsapp_enabled is true
          and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) in (
            'active', 'trial', 'trialing'
          )
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'payment_split_scope_or_state_invalid'
    );
  end if;

  insert into public.asaas_payment_split_message_attempts (
    tenant_id,
    payment_id,
    claim_token,
    lease_expires_at
  ) values (
    normalized_tenant,
    p_payment_id,
    p_claim_token,
    pg_catalog.now() + pg_catalog.make_interval(secs => safe_lease)
  ) on conflict (tenant_id, payment_id) do nothing;

  select attempt.* into attempt_row
    from public.asaas_payment_split_message_attempts as attempt
   where attempt.tenant_id = normalized_tenant
     and attempt.payment_id = p_payment_id
   for update;

  if attempt_row.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED')
     or attempt_row.submit_attempt_count > 0
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_FINAL',
      'attempt_id', attempt_row.id,
      'status', attempt_row.status
    );
  end if;
  if attempt_row.claim_token is distinct from p_claim_token
     and attempt_row.lease_expires_at > pg_catalog.now()
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'attempt_id', attempt_row.id,
      'status', attempt_row.status
    );
  end if;

  update public.asaas_payment_split_message_attempts
     set claim_token = p_claim_token,
         lease_expires_at = pg_catalog.now()
           + pg_catalog.make_interval(secs => safe_lease),
         updated_at = pg_catalog.now()
   where id = attempt_row.id
   returning * into attempt_row;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_ONCE',
    'attempt_id', attempt_row.id,
    'claim_token', attempt_row.claim_token,
    'status', attempt_row.status
  );
end;
$$;


--
-- Name: claim_asaas_provider_creation(text, text, text, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_asaas_provider_creation(p_tenant_id text, p_operation text, p_logical_key text, p_external_reference text, p_request_fingerprint text, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  attempt_row public.asaas_provider_creation_attempts%rowtype;
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  normalized_operation text := upper(trim(coalesce(p_operation, '')));
  normalized_key text := nullif(trim(coalesce(p_logical_key, '')), '');
  normalized_reference text := nullif(
    trim(coalesce(p_external_reference, '')),
    ''
  );
  normalized_fingerprint text := lower(trim(coalesce(
    p_request_fingerprint,
    ''
  )));
  safe_lease integer := greatest(60, least(coalesce(p_lease_seconds, 300), 600));
  retry_after integer;
begin
  if normalized_tenant is null
     or normalized_operation not in (
       'CUSTOMER_CREATE', 'PAYMENT_CREATE', 'SUBSCRIPTION_CREATE'
     )
     or normalized_key is null
     or length(normalized_key) > 240
     or normalized_reference is null
     or length(normalized_reference) > 240
     or normalized_fingerprint !~ '^[a-f0-9]{64}$'
     or p_claim_token is null
  then
    raise exception using
      errcode = '22023',
      message = 'invalid_asaas_creation_claim';
  end if;

  if not exists (
    select 1 from public.tenants as tenant
     where tenant.id = normalized_tenant
  ) then
    raise exception using errcode = '23503', message = 'tenant_not_found';
  end if;

  -- The unique key is the durable concurrency primitive. The row lock is held
  -- only for this short database transaction; no provider call occurs here.
  insert into public.asaas_provider_creation_attempts (
    tenant_id,
    operation,
    logical_key,
    external_reference,
    request_fingerprint,
    claim_token,
    lease_expires_at
  ) values (
    normalized_tenant,
    normalized_operation,
    normalized_key,
    normalized_reference,
    normalized_fingerprint,
    p_claim_token,
    now() + make_interval(secs => safe_lease)
  )
  on conflict (tenant_id, operation, logical_key) do nothing;

  select attempt.*
    into attempt_row
    from public.asaas_provider_creation_attempts as attempt
   where attempt.tenant_id = normalized_tenant
     and attempt.operation = normalized_operation
     and attempt.logical_key = normalized_key
   for update;

  if attempt_row.external_reference is distinct from normalized_reference
     or attempt_row.request_fingerprint is distinct from normalized_fingerprint
  then
    if attempt_row.status <> 'SUCCEEDED' then
      update public.asaas_provider_creation_attempts
         set status = 'BLOCKED',
             lease_expires_at = now(),
             last_error = 'logical_creation_input_mismatch',
             updated_at = now()
       where id = attempt_row.id;
    end if;

    insert into public.asaas_reconciliation_issues (
      tenant_id,
      source,
      kind,
      severity,
      local_entity_id,
      fingerprint,
      details
    ) values (
      attempt_row.tenant_id,
      'CREATION_GUARD',
      'ASAAS_CREATION_INPUT_MISMATCH',
      'CRITICAL',
      attempt_row.id::text,
      'asaas-creation:' || attempt_row.id::text,
      jsonb_build_object(
        'operation', attempt_row.operation,
        'logicalKey', attempt_row.logical_key
      )
    ) on conflict do nothing;

    return jsonb_build_object(
      'ok', false,
      'reason', 'creation_input_mismatch',
      'attempt_id', attempt_row.id,
      'action', 'REVIEW_REQUIRED'
    );
  end if;

  if attempt_row.status = 'SUCCEEDED' then
    return jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_SUCCEEDED',
      'attempt_id', attempt_row.id,
      'provider_entity_id', attempt_row.provider_entity_id,
      'provider_status', attempt_row.provider_status,
      'status', attempt_row.status
    );
  end if;

  if attempt_row.status in ('FAILED', 'BLOCKED') then
    return jsonb_build_object(
      'ok', false,
      'reason', 'creation_requires_manual_review',
      'action', 'REVIEW_REQUIRED',
      'attempt_id', attempt_row.id,
      'status', attempt_row.status
    );
  end if;

  if attempt_row.status = 'SUBMITTING'
     and attempt_row.lease_expires_at <= now()
  then
    update public.asaas_provider_creation_attempts
       set status = 'UNKNOWN',
           claim_token = p_claim_token,
           lease_expires_at = now() + make_interval(secs => safe_lease),
           next_attempt_at = now(),
           last_error = 'provider_submit_outcome_unknown_after_lease_expiry',
           updated_at = now()
     where id = attempt_row.id
     returning * into attempt_row;
  end if;

  if attempt_row.status = 'CLAIMED'
     and attempt_row.claim_token <> p_claim_token
     and attempt_row.lease_expires_at > now()
  then
    retry_after := greatest(
      1,
      ceil(extract(epoch from (attempt_row.lease_expires_at - now())))::integer
    );
    return jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'attempt_id', attempt_row.id,
      'status', attempt_row.status,
      'retry_after_seconds', retry_after
    );
  end if;

  if attempt_row.status = 'SUBMITTING'
     and attempt_row.lease_expires_at > now()
  then
    retry_after := greatest(
      1,
      ceil(extract(epoch from (attempt_row.lease_expires_at - now())))::integer
    );
    return jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'attempt_id', attempt_row.id,
      'status', attempt_row.status,
      'retry_after_seconds', retry_after
    );
  end if;

  if attempt_row.status in ('RETRY', 'UNKNOWN')
     and attempt_row.next_attempt_at > now()
  then
    retry_after := greatest(
      1,
      ceil(extract(epoch from (attempt_row.next_attempt_at - now())))::integer
    );
    return jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'attempt_id', attempt_row.id,
      'status', attempt_row.status,
      'retry_after_seconds', retry_after
    );
  end if;

  if attempt_row.status = 'UNKNOWN' then
    update public.asaas_provider_creation_attempts
       set claim_token = p_claim_token,
           lease_expires_at = now() + make_interval(secs => safe_lease),
           updated_at = now()
     where id = attempt_row.id
     returning * into attempt_row;

    return jsonb_build_object(
      'ok', true,
      'action', 'RECONCILE_REQUIRED',
      'attempt_id', attempt_row.id,
      'external_reference', attempt_row.external_reference,
      'claim_token', attempt_row.claim_token,
      'status', attempt_row.status
    );
  end if;

  if attempt_row.submit_attempt_count > 0 then
    update public.asaas_provider_creation_attempts
       set status = 'UNKNOWN',
           claim_token = p_claim_token,
           lease_expires_at = now() + make_interval(secs => safe_lease),
           next_attempt_at = now(),
           last_error = 'submit_already_started_reconciliation_required',
           updated_at = now()
     where id = attempt_row.id
     returning * into attempt_row;

    return jsonb_build_object(
      'ok', true,
      'action', 'RECONCILE_REQUIRED',
      'attempt_id', attempt_row.id,
      'external_reference', attempt_row.external_reference,
      'claim_token', attempt_row.claim_token,
      'status', attempt_row.status
    );
  end if;

  -- CLAIMED with an expired lease or RETRY before any POST is safe to reclaim.
  update public.asaas_provider_creation_attempts
     set status = 'CLAIMED',
         claim_token = p_claim_token,
         lease_expires_at = now() + make_interval(secs => safe_lease),
         next_attempt_at = now(),
         last_error = null,
         updated_at = now()
   where id = attempt_row.id
   returning * into attempt_row;

  return jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_ONCE',
    'attempt_id', attempt_row.id,
    'external_reference', attempt_row.external_reference,
    'claim_token', attempt_row.claim_token,
    'status', attempt_row.status
  );
end;
$_$;


--
-- Name: claim_asaas_student_billing_period(text, uuid, date, text, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_asaas_student_billing_period(p_tenant_id text, p_student_id uuid, p_due_date date, p_source text, p_source_key text, p_request_fingerprint text, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  period_start date := date_trunc('month', p_due_date)::date;
  period_end date := (
    date_trunc('month', p_due_date) + interval '1 month'
  )::date;
  competing_claim public.asaas_student_billing_period_claims%rowtype;
begin
  if normalized_tenant is null
     or p_student_id is null
     or p_due_date is null
  then
    raise exception using
      errcode = '22023',
      message = 'invalid_student_billing_period_claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-period-month:' || normalized_tenant || ':' ||
        p_student_id::text || ':' || period_start::text,
      0
    )
  );

  select billing_claim.* into competing_claim
    from public.asaas_student_billing_period_claims as billing_claim
   where billing_claim.tenant_id = normalized_tenant
     and billing_claim.student_id = p_student_id
     and billing_claim.due_date >= period_start
     and billing_claim.due_date < period_end
     and billing_claim.due_date <> p_due_date
   order by billing_claim.created_at, billing_claim.id
   limit 1
   for update;
  if found then
    return jsonb_build_object(
      'ok', false,
      'action', 'CONFLICT',
      'reason', 'billing_period_month_owned_by_another_flow',
      'attempt_id', competing_claim.id,
      'status', competing_claim.status,
      'provider_entity_id', competing_claim.provider_entity_id
    );
  end if;

  return public.claim_asaas_student_billing_period_exact_impl(
    normalized_tenant,
    p_student_id,
    p_due_date,
    p_source,
    p_source_key,
    p_request_fingerprint,
    p_claim_token,
    p_lease_seconds
  );
end;
$$;


--
-- Name: claim_asaas_student_billing_period_exact_impl(text, uuid, date, text, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_asaas_student_billing_period_exact_impl(p_tenant_id text, p_student_id uuid, p_due_date date, p_source text, p_source_key text, p_request_fingerprint text, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  claim_row public.asaas_student_billing_period_claims%rowtype;
  normalized_tenant text := nullif(
    pg_catalog.btrim(coalesce(p_tenant_id, '')),
    ''
  );
  normalized_source text := upper(
    pg_catalog.btrim(coalesce(p_source, ''))
  );
  normalized_key text := nullif(
    pg_catalog.btrim(coalesce(p_source_key, '')),
    ''
  );
  normalized_fingerprint text := lower(
    pg_catalog.btrim(coalesce(p_request_fingerprint, ''))
  );
  safe_lease integer := greatest(
    60,
    least(coalesce(p_lease_seconds, 300), 600)
  );
  retry_after integer;
begin
  if normalized_tenant is null
     or p_student_id is null
     or p_due_date is null
     or normalized_source not in ('MANUAL_PIX', 'SUBSCRIPTION')
     or normalized_key is null
     or length(normalized_key) > 240
     or normalized_fingerprint !~ '^[a-f0-9]{64}$'
     or p_claim_token is null
  then
    raise exception using
      errcode = '22023',
      message = 'invalid_student_billing_period_claim';
  end if;

  if not exists (
    select 1
      from public.profiles as profile
     where profile.id = p_student_id
       and profile.tenant_id = normalized_tenant
       and profile.role = 'STUDENT'
  ) then
    raise exception using
      errcode = '42501',
      message = 'student_billing_period_scope_mismatch';
  end if;

  select billing_claim.*
    into claim_row
    from public.asaas_student_billing_period_claims as billing_claim
   where billing_claim.tenant_id = normalized_tenant
     and billing_claim.student_id = p_student_id
     and billing_claim.due_date = p_due_date
   for update;

  if not found then
    insert into public.asaas_student_billing_period_claims (
      tenant_id,
      student_id,
      due_date,
      source,
      source_key,
      request_fingerprint,
      claim_token,
      lease_expires_at
    ) values (
      normalized_tenant,
      p_student_id,
      p_due_date,
      normalized_source,
      normalized_key,
      normalized_fingerprint,
      p_claim_token,
      now() + pg_catalog.make_interval(secs => safe_lease)
    )
    returning * into claim_row;
  end if;

  if claim_row.source is distinct from normalized_source
     or claim_row.source_key is distinct from normalized_key
  then
    insert into public.asaas_reconciliation_issues (
      tenant_id,
      source,
      kind,
      severity,
      local_entity_id,
      fingerprint,
      details
    ) values (
      normalized_tenant,
      'CREATION_GUARD',
      'STUDENT_BILLING_PERIOD_CONFLICT',
      'CRITICAL',
      claim_row.id::text,
      'student-billing-period:' || claim_row.id::text || ':' || normalized_source,
      pg_catalog.jsonb_build_object(
        'studentId', p_student_id,
        'dueDate', p_due_date,
        'winningSource', claim_row.source,
        'blockedSource', normalized_source
      )
    ) on conflict do nothing;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'CONFLICT',
      'reason', 'billing_period_owned_by_another_flow',
      'attempt_id', claim_row.id,
      'status', claim_row.status,
      'provider_entity_id', claim_row.provider_entity_id
    );
  end if;

  if claim_row.request_fingerprint is distinct from normalized_fingerprint then
    if claim_row.status <> 'BOUND' then
      update public.asaas_student_billing_period_claims
         set status = 'BLOCKED',
             last_error = 'billing_period_input_mismatch',
             lease_expires_at = now(),
             updated_at = now()
       where id = claim_row.id;
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'billing_period_input_mismatch',
      'attempt_id', claim_row.id
    );
  end if;

  if claim_row.status = 'BOUND' then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_BOUND',
      'attempt_id', claim_row.id,
      'provider_entity_id', claim_row.provider_entity_id,
      'status', claim_row.status
    );
  end if;

  if claim_row.status in ('FAILED', 'BLOCKED') then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'attempt_id', claim_row.id,
      'status', claim_row.status
    );
  end if;

  if claim_row.status in ('SUBMITTING', 'UNKNOWN')
     and claim_row.lease_expires_at > now()
     and claim_row.claim_token is distinct from p_claim_token
  then
    retry_after := greatest(
      1,
      ceil(extract(epoch from (claim_row.lease_expires_at - now())))::integer
    );
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'attempt_id', claim_row.id,
      'status', claim_row.status,
      'retry_after_seconds', retry_after
    );
  end if;

  if claim_row.status in ('SUBMITTING', 'UNKNOWN') then
    update public.asaas_student_billing_period_claims
       set status = 'UNKNOWN',
           claim_token = p_claim_token,
           lease_expires_at = now() + pg_catalog.make_interval(
             secs => safe_lease
           ),
           updated_at = now()
     where id = claim_row.id
     returning * into claim_row;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'RECONCILE_REQUIRED',
      'attempt_id', claim_row.id,
      'claim_token', claim_row.claim_token,
      'status', claim_row.status
    );
  end if;

  if claim_row.status = 'CLAIMED'
     and claim_row.claim_token is distinct from p_claim_token
     and claim_row.lease_expires_at > now()
  then
    retry_after := greatest(
      1,
      ceil(extract(epoch from (claim_row.lease_expires_at - now())))::integer
    );
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'attempt_id', claim_row.id,
      'status', claim_row.status,
      'retry_after_seconds', retry_after
    );
  end if;

  update public.asaas_student_billing_period_claims
     set status = 'CLAIMED',
         claim_token = p_claim_token,
         lease_expires_at = now() + pg_catalog.make_interval(
           secs => safe_lease
         ),
         updated_at = now()
   where id = claim_row.id
   returning * into claim_row;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_ONCE',
    'attempt_id', claim_row.id,
    'claim_token', claim_row.claim_token,
    'status', claim_row.status
  );
end;
$_$;


--
-- Name: claim_asaas_subscription_mutation(text, uuid, text, text, text, text, text, jsonb, jsonb, jsonb, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_asaas_subscription_mutation(p_tenant_id text, p_student_id uuid, p_customer_id text, p_subscription_id text, p_mutation_kind text, p_intent_key text, p_request_fingerprint text, p_expected_state jsonb, p_desired_state jsonb, p_integration_snapshot jsonb, p_requested_by uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_tenant text := nullif(pg_catalog.btrim(p_tenant_id), '');
  v_customer text := nullif(pg_catalog.btrim(p_customer_id), '');
  v_subscription text := nullif(pg_catalog.btrim(p_subscription_id), '');
  v_kind text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    p_mutation_kind, ''
  )));
  v_intent text := nullif(pg_catalog.btrim(p_intent_key), '');
  v_fingerprint text := pg_catalog.lower(pg_catalog.btrim(coalesce(
    p_request_fingerprint, ''
  )));
  v_lease integer := greatest(
    60,
    least(coalesce(p_lease_seconds, 300), 600)
  );
  v_operation public.asaas_subscription_mutation_operations%rowtype;
  v_retry_after integer;
begin
  if v_tenant is null or p_student_id is null or v_customer is null
     or v_subscription is null or v_kind not in ('PLAN_VALUE', 'MAX_PAYMENTS')
     or v_intent is null or pg_catalog.char_length(v_intent) > 240
     or v_fingerprint !~ '^[a-f0-9]{64}$'
     or p_claim_token is null
     or pg_catalog.jsonb_typeof(p_integration_snapshot) <> 'object'
     or p_integration_snapshot = '{}'::jsonb
     or not private.validate_subscription_mutation_state(
       v_kind, p_expected_state, p_desired_state
     )
  then
    raise exception 'invalid_subscription_mutation_claim'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || v_tenant || ':' || p_student_id::text,
      0
    )
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'asaas-subscription-mutation:' || v_tenant || ':' || v_subscription,
      0
    )
  );

  if not private.student_subscription_mutation_scope_valid(
    v_tenant, p_student_id, v_customer, v_subscription
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED',
      'reason', 'student_subscription_scope_changed'
    );
  end if;

  update public.asaas_subscription_mutation_operations as operation
     set status = 'UNKNOWN',
         lease_expires_at = pg_catalog.now(),
         last_error = coalesce(
           operation.last_error,
           'submit_lease_expired_reconciliation_required'
         ),
         updated_at = pg_catalog.now()
   where operation.tenant_id = v_tenant
     and operation.subscription_id = v_subscription
     and operation.status = 'SUBMITTING'
     and operation.lease_expires_at <= pg_catalog.now();
  update public.asaas_subscription_mutation_operations as operation
     set status = 'FAILED',
         lease_expires_at = pg_catalog.now(),
         completed_at = pg_catalog.now(),
         last_error = coalesce(
           operation.last_error,
           'claim_expired_before_provider_submit'
         ),
         updated_at = pg_catalog.now()
   where operation.tenant_id = v_tenant
     and operation.subscription_id = v_subscription
     and operation.status = 'CLAIMED'
     and operation.submit_attempt_count = 0
     and operation.lease_expires_at <= pg_catalog.now();

  select operation.* into v_operation
    from public.asaas_subscription_mutation_operations as operation
   where operation.tenant_id = v_tenant
     and operation.subscription_id = v_subscription
     and operation.intent_key = v_intent
   for update;

  if found then
    if v_operation.student_id is distinct from p_student_id
       or v_operation.customer_id is distinct from v_customer
       or v_operation.mutation_kind is distinct from v_kind
       or v_operation.request_fingerprint is distinct from v_fingerprint
       or v_operation.desired_state is distinct from p_desired_state
       or v_operation.integration_snapshot is distinct from p_integration_snapshot
       or (
         v_operation.status in ('CLAIMED', 'FAILED')
         and v_operation.expected_state is distinct from p_expected_state
       )
    then
      update public.asaas_subscription_mutation_operations
         set status = 'BLOCKED',
             lease_expires_at = pg_catalog.now(),
             last_error = 'subscription_mutation_intent_mismatch',
             updated_at = pg_catalog.now()
       where id = v_operation.id and status <> 'SUCCEEDED';
      return pg_catalog.jsonb_build_object(
        'ok', false, 'action', 'REVIEW_REQUIRED',
        'reason', 'subscription_mutation_intent_mismatch',
        'operation_id', v_operation.id
      );
    end if;
    if v_operation.status = 'SUCCEEDED' then
      return pg_catalog.jsonb_build_object(
        'ok', true, 'action', 'ALREADY_SUCCEEDED',
        'operation_id', v_operation.id,
        'observed_state', v_operation.observed_state
      );
    end if;
    if v_operation.status in ('SUBMITTING', 'UNKNOWN') then
      update public.asaas_subscription_mutation_operations
         set claim_token = p_claim_token,
             lease_expires_at = pg_catalog.now()
               + pg_catalog.make_interval(secs => v_lease),
             updated_at = pg_catalog.now()
       where id = v_operation.id
       returning * into v_operation;
      return pg_catalog.jsonb_build_object(
        'ok', true, 'action', 'RECONCILE_REQUIRED',
        'operation_id', v_operation.id,
        'claim_token', v_operation.claim_token,
        'status', v_operation.status
      );
    end if;
    if v_operation.status = 'BLOCKED' then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'action', 'REVIEW_REQUIRED',
        'reason', coalesce(v_operation.last_error, 'mutation_requires_review'),
        'operation_id', v_operation.id
      );
    end if;
    if v_operation.status = 'FAILED' then
      update public.asaas_subscription_mutation_operations
         set status = 'CLAIMED',
             claim_token = p_claim_token,
             lease_expires_at = pg_catalog.now()
               + pg_catalog.make_interval(secs => v_lease),
             submit_attempt_count = 0,
             provider_http_status = null,
             observed_state = null,
             submitted_at = null,
             completed_at = null,
             last_error = null,
             updated_at = pg_catalog.now()
       where id = v_operation.id
       returning * into v_operation;
      return pg_catalog.jsonb_build_object(
        'ok', true, 'action', 'SUBMIT_ONCE',
        'operation_id', v_operation.id,
        'claim_token', v_operation.claim_token
      );
    end if;
    if v_operation.claim_token is distinct from p_claim_token
       and v_operation.lease_expires_at > pg_catalog.now()
    then
      v_retry_after := greatest(
        1,
        pg_catalog.ceil(
          pg_catalog.date_part(
            'epoch',
            v_operation.lease_expires_at - pg_catalog.now()
          )
        )::integer
      );
      return pg_catalog.jsonb_build_object(
        'ok', true, 'action', 'IN_PROGRESS',
        'operation_id', v_operation.id,
        'retry_after_seconds', v_retry_after
      );
    end if;
    update public.asaas_subscription_mutation_operations
       set claim_token = p_claim_token,
           lease_expires_at = pg_catalog.now()
             + pg_catalog.make_interval(secs => v_lease),
           updated_at = pg_catalog.now()
     where id = v_operation.id
     returning * into v_operation;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'action', 'SUBMIT_ONCE',
      'operation_id', v_operation.id,
      'claim_token', v_operation.claim_token
    );
  end if;

  select operation.* into v_operation
    from public.asaas_subscription_mutation_operations as operation
   where operation.tenant_id = v_tenant
     and operation.subscription_id = v_subscription
     and operation.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN', 'BLOCKED')
   for update;
  if found then
    if v_operation.status in ('SUBMITTING', 'UNKNOWN')
       and v_operation.student_id is not distinct from p_student_id
       and v_operation.customer_id is not distinct from v_customer
       and v_operation.mutation_kind is not distinct from v_kind
       and v_operation.request_fingerprint is not distinct from v_fingerprint
       and v_operation.desired_state is not distinct from p_desired_state
       and v_operation.integration_snapshot is not distinct from p_integration_snapshot
    then
      update public.asaas_subscription_mutation_operations
         set claim_token = p_claim_token,
             lease_expires_at = pg_catalog.now()
               + pg_catalog.make_interval(secs => v_lease),
             updated_at = pg_catalog.now()
       where id = v_operation.id
       returning * into v_operation;
      return pg_catalog.jsonb_build_object(
        'ok', true, 'action', 'RECONCILE_REQUIRED',
        'operation_id', v_operation.id,
        'claim_token', v_operation.claim_token,
        'status', v_operation.status
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', v_operation.status = 'CLAIMED',
      'action', case
        when v_operation.status = 'CLAIMED' then 'IN_PROGRESS'
        else 'REVIEW_REQUIRED'
      end,
      'reason', 'subscription_mutation_in_flight',
      'operation_id', v_operation.id
    );
  end if;

  insert into public.asaas_subscription_mutation_operations (
    tenant_id, student_id, customer_id, subscription_id, mutation_kind,
    intent_key, request_fingerprint, expected_state, desired_state,
    integration_snapshot, requested_by, status, claim_token, lease_expires_at
  ) values (
    v_tenant, p_student_id, v_customer, v_subscription, v_kind,
    v_intent, v_fingerprint, p_expected_state, p_desired_state,
    p_integration_snapshot, p_requested_by, 'CLAIMED', p_claim_token,
    pg_catalog.now() + pg_catalog.make_interval(secs => v_lease)
  ) returning * into v_operation;

  return pg_catalog.jsonb_build_object(
    'ok', true, 'action', 'SUBMIT_ONCE',
    'operation_id', v_operation.id,
    'claim_token', v_operation.claim_token
  );
end;
$_$;


--
-- Name: claim_asaas_teacher_transfer(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_asaas_teacher_transfer(p_closing_id uuid, p_actor_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  closing_row public.teacher_closings%rowtype;
  teacher_row public.profiles%rowtype;
  actor_role text;
  attempt_row public.asaas_teacher_transfer_attempts%rowtype;
  teacher_nf_exempt boolean := false;
  require_nf boolean := false;
  external_ref text;
  normalized_pix_key text;
  normalized_pix_type text;
  destination_hash text;
  description_snapshot text;
begin
  if p_closing_id is null or p_actor_id is null or p_claim_token is null then
    raise exception using errcode = '22023', message = 'transfer_claim_arguments_required';
  end if;

  select closing.* into closing_row
    from public.teacher_closings as closing
   where closing.id = p_closing_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'closing_not_found');
  end if;

  select profile.role into actor_role
    from public.profiles as profile
   where profile.id = p_actor_id
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active';

  if actor_role is null or (
    actor_role <> 'SUPER_ADMIN'
    and not exists (
      select 1 from public.tenant_memberships as membership
       where membership.user_id = p_actor_id
         and membership.tenant_id = closing_row.tenant_id
         and membership.role = 'SCHOOL_ADMIN'
         and membership.status = 'ACTIVE'
    )
  ) then
    return jsonb_build_object('ok', false, 'reason', 'not_authorized');
  end if;

  select teacher.* into teacher_row
    from public.profiles as teacher
    join public.tenant_memberships as membership
      on membership.user_id = teacher.id
     and membership.tenant_id = closing_row.tenant_id
     and membership.role = 'TEACHER'
     and membership.status = 'ACTIVE'
   where teacher.id = closing_row.teacher_id
     and teacher.role = 'TEACHER'
     and lower(trim(coalesce(teacher.lifecycle_status, ''))) = 'active'
   for share of teacher, membership;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'teacher_membership_inactive');
  end if;

  teacher_nf_exempt := coalesce(teacher_row.nf_exempt, false);
  select coalesce(tenant.require_nf_for_transfer, false)
    into require_nf
    from public.tenants as tenant
   where tenant.id = closing_row.tenant_id;
  if require_nf and not teacher_nf_exempt and exists (
    select 1
      from public.teacher_closings as prior
     where prior.teacher_id = closing_row.teacher_id
       and prior.tenant_id = closing_row.tenant_id
       and prior.id <> closing_row.id
       and prior.status in ('PAID_WAITING_NF', 'REJECTED', 'REJEITADO')
       and coalesce(prior.total_amount, 0) > 0
       and nullif(trim(prior.nf_link), '') is null
  ) then
    return jsonb_build_object('ok', false, 'reason', 'fiscal_lock_pending_invoice');
  end if;

  if coalesce(closing_row.total_amount, 0) <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'invalid_amount');
  end if;

  normalized_pix_type := upper(trim(coalesce(teacher_row.pix_key_type, '')));
  if normalized_pix_type = 'TELEFONE' then
    normalized_pix_type := 'PHONE';
  end if;
  if normalized_pix_type not in ('CPF', 'CNPJ', 'EMAIL', 'PHONE', 'EVP') then
    return jsonb_build_object('ok', false, 'reason', 'teacher_pix_key_type_invalid');
  end if;

  normalized_pix_key := trim(coalesce(teacher_row.pix_key, ''));
  if normalized_pix_type in ('CPF', 'CNPJ', 'PHONE') then
    normalized_pix_key := regexp_replace(normalized_pix_key, '\D', '', 'g');
  end if;
  if normalized_pix_key = ''
     or length(normalized_pix_key) > 180
     or (normalized_pix_type = 'CPF' and normalized_pix_key !~ '^\d{11}$')
     or (normalized_pix_type = 'CNPJ' and normalized_pix_key !~ '^\d{14}$')
     or (normalized_pix_type = 'PHONE' and normalized_pix_key !~ '^\d{10,15}$')
     or (normalized_pix_type = 'EMAIL' and normalized_pix_key !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$')
     or (normalized_pix_type = 'EVP' and normalized_pix_key !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
  then
    return jsonb_build_object('ok', false, 'reason', 'teacher_pix_key_invalid');
  end if;

  destination_hash := pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(normalized_pix_type || ':' || normalized_pix_key, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  description_snapshot := left(
    'Pagamento Professor - ' ||
    regexp_replace(trim(coalesce(teacher_row.full_name, 'Professor')), '[\r\n\t]+', ' ', 'g') ||
    ' - Ref: ' ||
    regexp_replace(trim(coalesce(closing_row.month_year::text, 'sem-periodo')), '[\r\n\t]+', ' ', 'g'),
    300
  );

  select attempt.* into attempt_row
    from public.asaas_teacher_transfer_attempts as attempt
   where attempt.closing_id = p_closing_id
   for update;

  if found then
    if attempt_row.status in ('SUBMITTED', 'UNKNOWN') then
      update public.asaas_teacher_transfer_attempts
         set claim_token = p_claim_token,
             lease_expires_at = now() + interval '5 minutes',
             updated_at = now()
       where id = attempt_row.id;
      return jsonb_build_object(
        'ok', true,
        'action', 'RECONCILE_REQUIRED',
        'attempt_id', attempt_row.id,
        'tenant_id', attempt_row.tenant_id,
        'expected_amount', attempt_row.expected_amount,
        'destination_fingerprint', attempt_row.destination_fingerprint,
        'external_reference', attempt_row.external_reference,
        'created_at', attempt_row.created_at,
        'provider_transfer_id', attempt_row.provider_transfer_id,
        'claim_token', p_claim_token,
        'status', attempt_row.status
      );
    elsif attempt_row.status = 'COMPLETED' then
      return jsonb_build_object(
        'ok', true,
        'action', 'ALREADY_COMPLETED',
        'attempt_id', attempt_row.id,
        'tenant_id', attempt_row.tenant_id,
        'provider_transfer_id', attempt_row.provider_transfer_id,
        'status', attempt_row.status
      );
    elsif attempt_row.status = 'CLAIMED' then
      if attempt_row.lease_expires_at > now() then
        return jsonb_build_object(
          'ok', true,
          'action', 'IN_PROGRESS',
          'attempt_id', attempt_row.id,
          'tenant_id', attempt_row.tenant_id
        );
      end if;

      -- Crash window: the provider POST may have succeeded before the Edge
      -- Function persisted its response. Never submit again. Reclaim only for
      -- a GET reconciliation by id/externalReference.
      update public.asaas_teacher_transfer_attempts
         set claim_token = p_claim_token,
             lease_expires_at = now() + interval '5 minutes',
             status = 'UNKNOWN',
             last_error = 'submit_outcome_unknown_after_lease_expiry',
             updated_at = now()
       where id = attempt_row.id;
      return jsonb_build_object(
        'ok', true,
        'action', 'RECONCILE_REQUIRED',
        'attempt_id', attempt_row.id,
        'tenant_id', attempt_row.tenant_id,
        'expected_amount', attempt_row.expected_amount,
        'destination_fingerprint', attempt_row.destination_fingerprint,
        'external_reference', attempt_row.external_reference,
        'created_at', attempt_row.created_at,
        'provider_transfer_id', attempt_row.provider_transfer_id,
        'claim_token', p_claim_token,
        'status', 'UNKNOWN'
      );
    else
      return jsonb_build_object(
        'ok', false,
        'reason', 'attempt_requires_manual_review',
        'attempt_id', attempt_row.id,
        'status', attempt_row.status
      );
    end if;
  end if;

  if closing_row.asaas_transfer_id is not null
     or closing_row.status in ('PAID_WAITING_NF', 'UNDER_REVIEW', 'COMPLETED', 'PAGO')
  then
    return jsonb_build_object('ok', false, 'reason', 'closing_already_paid_or_submitted');
  end if;

  external_ref := 'wisewolf-teacher-closing:' || p_closing_id::text;
  insert into public.asaas_teacher_transfer_attempts (
    closing_id, tenant_id, requested_by, external_reference, expected_amount,
    destination_pix_key, destination_pix_key_type, destination_fingerprint,
    transfer_description, claim_token, lease_expires_at
  ) values (
    p_closing_id, closing_row.tenant_id, p_actor_id, external_ref,
    closing_row.total_amount, normalized_pix_key, normalized_pix_type,
    destination_hash, description_snapshot, p_claim_token,
    now() + interval '5 minutes'
  ) returning * into attempt_row;

  return jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_ONCE',
    'attempt_id', attempt_row.id,
    'tenant_id', attempt_row.tenant_id,
    'external_reference', attempt_row.external_reference,
    'expected_amount', attempt_row.expected_amount,
    'destination_pix_key', attempt_row.destination_pix_key,
    'destination_pix_key_type', attempt_row.destination_pix_key_type,
    'destination_fingerprint', attempt_row.destination_fingerprint,
    'transfer_description', attempt_row.transfer_description,
    'claim_token', attempt_row.claim_token,
    'status', attempt_row.status
  );
end;
$_$;


--
-- Name: claim_attendance_confirmation_deliveries(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_attendance_confirmation_deliveries(p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, tenant_id text, token text, student_id uuid, student_name text, attendance_phone text, teacher_id uuid, teacher_name text, class_date date, class_time text, source_id text, source_type text, send_attempts integer, claim_token uuid, delivery_key text, session_key text, session_end_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_today date := (pg_catalog.now() at time zone 'America/Sao_Paulo')::date;
begin
  perform private.refresh_attendance_confirmation_sessions(v_today - 1, v_today);

  -- A lost worker is not proof of a failed provider call. Keep it visible for
  -- manual review and never deliver it a second time automatically.
  update public.attendance_confirmations ac
     set delivery_status = 'AMBIGUOUS',
         last_delivery_error = 'claim_lease_expired_delivery_outcome_unknown',
         delivery_claim_expires_at = null
   where ac.delivery_status = 'PROCESSING'
     and ac.delivery_claim_expires_at is not null
     and ac.delivery_claim_expires_at <= pg_catalog.now();

  -- Transactional anti-ghost check. A missing occurrence still cancels the
  -- business audit, but AMBIGUOUS means the provider outcome is unknown and its
  -- delivery state/error must remain terminal. PROCESSING is left untouched.
  update public.attendance_confirmations ac
     set status = 'CANCELLED',
         delivery_status = case
           when ac.delivery_status = 'PENDING' then 'CANCELLED'
           else ac.delivery_status
         end,
         last_delivery_error = case
           when ac.delivery_status = 'PENDING' then 'occurrence_not_found'
           else ac.last_delivery_error
         end
   where ac.class_date between v_today - 1 and v_today
     and ac.sent_at is null
     and ac.student_response is null
     and ac.status = 'PENDING'
     and ac.delivery_status in ('PENDING', 'AMBIGUOUS')
     and ac.delivery_key is not null
     and ac.source_id is not null
     and ac.source_type is not null
     and not exists (
       select 1
         from public.attendance_confirmations member
         join public.upcoming_classes uc
           on uc.source_id::text = member.source_id
          and uc.source_type = member.source_type
          and uc.class_date = member.class_date
        where coalesce(member.canonical_confirmation_id, member.id) = ac.id
     );

  return query
  with candidates as (
    select ac.id
      from public.attendance_confirmations ac
     where ac.class_date between v_today - 1 and v_today
       and ac.sent_at is null
       and ac.student_response is null
       and ac.status = 'PENDING'
       and ac.delivery_status = 'PENDING'
       and ac.delivery_key is not null
       and coalesce(ac.canonical_confirmation_id, ac.id) = ac.id
       and ac.send_attempts < 8
       and ac.token_expires_at > pg_catalog.now()
       and ac.session_end_at is not null
       and ac.session_end_at + interval '10 minutes' <= pg_catalog.now()
       and exists (
         select 1
           from public.profiles sp
          where sp.id = ac.student_id
            and sp.tenant_id = ac.tenant_id
            and sp.role = 'STUDENT'
            and sp.is_test_account is false
            and pg_catalog.lower(pg_catalog.btrim(sp.lifecycle_status)) = 'active'
            and exists (
              select 1
                from public.tenant_memberships membership
               where membership.user_id = sp.id
                 and membership.tenant_id = ac.tenant_id
                 and membership.role = 'STUDENT'
                 and membership.status = 'ACTIVE'
            )
       )
       and exists (
         select 1
           from public.profiles tp
          where tp.id = ac.teacher_id
            and tp.tenant_id = ac.tenant_id
            and tp.role = 'TEACHER'
            and tp.is_test_account is false
            and pg_catalog.lower(pg_catalog.btrim(tp.lifecycle_status)) = 'active'
            and exists (
              select 1
                from public.tenant_memberships membership
               where membership.user_id = tp.id
                 and membership.tenant_id = ac.tenant_id
                 and membership.role = 'TEACHER'
                 and membership.status = 'ACTIVE'
            )
       )
     order by ac.class_date, ac.class_time, ac.created_at, ac.id
     for update skip locked
     limit v_limit
  ), claimed as (
    update public.attendance_confirmations ac
       set delivery_status = 'PROCESSING',
           delivery_claim_token = extensions.gen_random_uuid(),
           delivery_claimed_at = pg_catalog.now(),
           delivery_claim_expires_at = pg_catalog.now() + interval '5 minutes',
           send_attempts = ac.send_attempts + 1,
           last_delivery_error = null
      from candidates c
     where ac.id = c.id
    returning ac.*
  )
  select
    c.id,
    c.tenant_id,
    c.token,
    c.student_id,
    c.student_name,
    (
      select case
        when pg_catalog.length(pg_catalog.regexp_replace(
               coalesce(sp.attendance_phone, ''), '[^0-9]', '', 'g'
             )) >= 10
          then sp.attendance_phone
        when pg_catalog.length(pg_catalog.regexp_replace(
               coalesce(sp.phone, ''), '[^0-9]', '', 'g'
             )) >= 10
          then sp.phone
      end
        from public.profiles sp
       where sp.id = c.student_id
         and sp.tenant_id = c.tenant_id
         and sp.role = 'STUDENT'
       limit 1
    ) as attendance_phone,
    c.teacher_id,
    c.teacher_name,
    c.class_date,
    c.class_time,
    c.source_id,
    c.source_type,
    c.send_attempts,
    c.delivery_claim_token as claim_token,
    c.delivery_key,
    c.session_key,
    c.session_end_at
  from claimed c
  order by c.class_date, c.class_time, c.created_at, c.id;
end;
$$;


--
-- Name: claim_enrollment_offer(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_enrollment_offer(p_offer_id uuid, p_profile jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_email text;
  v_existing_role text;
  v_opportunity_id uuid;
  v_payload jsonb;
  v_dependent boolean;
  v_fee numeric;
  v_phone text;
  v_cpf text;
  v_invite_id uuid;
  v_referrer_id uuid;
  v_referrer_role text;
  v_referrer_teacher_id uuid;
  v_referrer_student_id uuid;
  v_vendor_role text;
  v_vendor_tenant text;
  v_commission_rate integer;
  v_enrollment_link_id uuid;
  v_desired_module text;
  v_desired_book_part text;
  o public.offers%ROWTYPE;
  v_opp public.opportunities%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'UNAUTHORIZED');
  END IF;

  SELECT opportunity_id
    INTO v_opportunity_id
    FROM public.offers
   WHERE id = p_offer_id
     AND kind = 'ENROLLMENT';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'OFFER_NOT_FOUND');
  END IF;

  -- Mesma ordem de locks da emissão: opportunity -> offer.
  IF v_opportunity_id IS NOT NULL THEN
    SELECT * INTO v_opp
      FROM public.opportunities
     WHERE id = v_opportunity_id
     FOR UPDATE;
  END IF;

  SELECT * INTO o
    FROM public.offers
   WHERE id = p_offer_id
     AND kind = 'ENROLLMENT'
   FOR UPDATE;

  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'OFFER_NOT_FOUND'); END IF;
  IF o.revoked_at IS NOT NULL THEN RETURN jsonb_build_object('success', false, 'error', 'OFFER_REVOKED'); END IF;
  IF o.consumed_at IS NOT NULL AND o.consumed_by IS DISTINCT FROM v_user THEN
    RETURN jsonb_build_object('success', false, 'error', 'OFFER_CONSUMED');
  END IF;
  IF o.consumed_at IS NULL AND o.expires_at <= now() THEN
    RETURN jsonb_build_object('success', false, 'error', 'OFFER_EXPIRED');
  END IF;

  IF v_opportunity_id IS NOT NULL THEN
    IF v_opp.id IS NULL OR v_opp.tenant_id IS DISTINCT FROM o.tenant_id THEN
      RETURN jsonb_build_object('success', false, 'error', 'OPPORTUNITY_INVALID');
    END IF;
    IF v_opp.conversion_status = 'LOST' THEN
      RETURN jsonb_build_object('success', false, 'error', 'OPPORTUNITY_CLOSED');
    END IF;
    IF v_opp.conversion_status = 'WON'
       AND (v_opp.student_id IS NULL OR v_opp.student_id IS DISTINCT FROM v_user) THEN
      RETURN jsonb_build_object('success', false, 'error', 'OPPORTUNITY_CONVERTED');
    END IF;
  END IF;

  SELECT p.role
    INTO v_existing_role
    FROM public.profiles p
   WHERE p.id = v_user
   FOR UPDATE;
  IF FOUND AND v_existing_role IS DISTINCT FROM 'STUDENT' THEN
    RETURN jsonb_build_object('success', false, 'error', 'PROFILE_ROLE_NOT_ALLOWED');
  END IF;

  SELECT lower(trim(u.email))
    INTO v_email
    FROM auth.users u
   WHERE u.id = v_user;
  IF v_email IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'USER_NOT_FOUND');
  END IF;

  v_payload := COALESCE(o.payload, '{}'::jsonb) || jsonb_build_object(
    'unitId', o.tenant_id,
    'requiresEnrollment', o.requires_enrollment,
    'enrollmentFee', o.enrollment_fee,
    'opportunityId', o.opportunity_id,
    'vendorId', o.vendor_id
  );
  v_dependent := COALESCE((v_payload ->> 'isDependent')::boolean, false);
  v_fee := GREATEST(COALESCE(o.enrollment_fee, 0), 0);
  v_phone := regexp_replace(COALESCE(p_profile ->> 'phone', ''), '[^0-9]', '', 'g');
  v_cpf := regexp_replace(COALESCE(p_profile ->> 'cpf', ''), '[^0-9]', '', 'g');

  IF length(trim(COALESCE(p_profile ->> 'full_name', ''))) < 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'INVALID_NAME');
  END IF;
  IF length(v_phone) < 10 THEN
    RETURN jsonb_build_object('success', false, 'error', 'INVALID_PHONE');
  END IF;
  IF NOT v_dependent AND length(v_cpf) <> 11 THEN
    RETURN jsonb_build_object('success', false, 'error', 'INVALID_CPF');
  END IF;

  -- --------------------------------------------------------------------------
  -- Determinação do Nível Pedagógico Inicial (CEFR) e Livro Inicial
  -- --------------------------------------------------------------------------
  v_desired_module := pg_catalog.upper(pg_catalog.btrim(coalesce(
    v_payload ->> 'module',
    v_payload ->> 'studentLevel',
    v_payload ->> 'level',
    ''
  )));

  -- Fallback 1: Buscar do feedback da aula experimental vinculada à oportunidade
  IF (v_desired_module IS NULL OR v_desired_module = '') AND o.opportunity_id IS NOT NULL THEN
    SELECT pg_catalog.upper(pg_catalog.btrim(tf.recommended_level))
      INTO v_desired_module
      FROM public.trial_feedback tf
     WHERE tf.opportunity_id = o.opportunity_id
       AND tf.recommended_level IS NOT NULL
       AND pg_catalog.btrim(tf.recommended_level) <> ''
     ORDER BY tf.created_at DESC
     LIMIT 1;
  END IF;

  -- Fallback 2: Buscar do cadastro do CRM (crm_leads) por e-mail ou telefone
  IF v_desired_module IS NULL OR v_desired_module = '' THEN
    SELECT CASE 
             WHEN pg_catalog.upper(cl.level) LIKE '%A2%' THEN 'A2'
             WHEN pg_catalog.upper(cl.level) LIKE '%B1%' THEN 'B1'
             WHEN pg_catalog.upper(cl.level) LIKE '%B2%' THEN 'B2'
             WHEN pg_catalog.upper(cl.level) LIKE '%C1%' THEN 'C1'
             WHEN pg_catalog.upper(cl.level) LIKE '%C2%' THEN 'C2'
             WHEN pg_catalog.upper(cl.level) LIKE '%A1%' THEN 'A1'
             ELSE NULL
           END
      INTO v_desired_module
      FROM public.crm_leads cl
     WHERE (cl.email IS NOT NULL AND lower(cl.email) = lower(v_email))
        OR (v_phone IS NOT NULL AND length(v_phone) >= 10 AND regexp_replace(coalesce(cl.phone, ''), '[^0-9]', '', 'g') = v_phone)
     ORDER BY cl.created_at DESC
     LIMIT 1;
  END IF;

  -- Normalização para níveis CEFR válidos (padrão de entrada seguro: A1)
  IF v_desired_module IS NULL OR v_desired_module NOT IN ('A1', 'A2', 'B1', 'B2', 'C1', 'C2') THEN
    v_desired_module := 'A1';
  END IF;

  -- Obtenção do primeiro marco ativo do catálogo pedagógico
  SELECT catalog.book_part
    INTO v_desired_book_part
    FROM public.pedagogical_evaluation_catalog as catalog
   WHERE catalog.module = v_desired_module
     AND catalog.active is true
   ORDER BY catalog.part ASC
   LIMIT 1;

  IF v_desired_book_part IS NULL THEN
    v_desired_book_part := v_desired_module || '-1';
  END IF;

  -- A indicação é derivada do convite por e-mail e tenant, nunca de UUID no URL.
  SELECT ri.id, ri.referrer_id, rp.role
    INTO v_invite_id, v_referrer_id, v_referrer_role
    FROM public.referral_invites ri
    JOIN public.profiles rp ON rp.id = ri.referrer_id
   WHERE lower(trim(ri.invitee_email)) = v_email
     AND ri.status = 'PENDING'
     AND ri.expires_at > now()
     AND (ri.tenant_id IS NULL OR ri.tenant_id = o.tenant_id)
     AND rp.tenant_id = o.tenant_id
     AND ri.referrer_id <> v_user
   ORDER BY ri.created_at DESC
   LIMIT 1
   FOR UPDATE OF ri;

  IF v_invite_id IS NOT NULL THEN
    IF v_referrer_role IN ('TEACHER', 'SCHOOL_ADMIN', 'COORDINATOR') THEN
      v_referrer_teacher_id := v_referrer_id;
    ELSIF v_referrer_role = 'STUDENT' THEN
      v_referrer_student_id := v_referrer_id;
    END IF;
  END IF;

  PERFORM set_config('app.enrollment_claim', '1', true);

  UPDATE public.offers
     SET consumed_at = COALESCE(consumed_at, now()),
         consumed_by = COALESCE(consumed_by, v_user),
         usage_count = COALESCE(usage_count, 0)
           + CASE WHEN consumed_at IS NULL THEN 1 ELSE 0 END,
         last_used_at = now()
   WHERE id = o.id;

  INSERT INTO public.profiles (
    id, email, full_name, role, tenant_id, phone, cpf, postal_code,
    address, address_number, status_financial, monthly_fee, due_day,
    module, current_book_part, contract_accepted, documentation_status, accepted_at,
    class_frequency, signature_ip, student_signature_url,
    signed_document_url, wise_wolf_signature_token, enrollment_fee,
    enrollment_fee_paid, professor_id, professor_id2, start_date,
    guardian_id, guardian_name, guardian_cpf, guardian_email,
    guardian_phone, attendance_phone, referrer_teacher_id,
    referrer_student_id
  )
  VALUES (
    v_user,
    v_email,
    trim(p_profile ->> 'full_name'),
    'STUDENT',
    o.tenant_id,
    v_phone,
    CASE WHEN v_dependent THEN NULL ELSE v_cpf END,
    NULLIF(p_profile ->> 'postal_code', ''),
    NULLIF(p_profile ->> 'address', ''),
    NULLIF(p_profile ->> 'address_number', ''),
    'PENDING',
    (v_payload ->> 'value')::numeric,
    (v_payload ->> 'dueDay')::integer,
    v_desired_module,
    v_desired_book_part,
    true,
    'APPROVED',
    now(),
    COALESCE(v_payload ->> 'classesPerWeek', '1') || 'x',
    COALESCE(NULLIF(p_profile ->> 'signature_ip', ''), 'Via Web'),
    NULLIF(p_profile ->> 'student_signature_url', ''),
    NULLIF(p_profile ->> 'signed_document_url', ''),
    gen_random_uuid()::text,
    v_fee,
    v_fee <= 0,
    NULLIF(v_payload ->> 'professorId', '')::uuid,
    NULLIF(v_payload ->> 'professorId2', '')::uuid,
    NULLIF(v_payload ->> 'startDate', '')::date,
    CASE WHEN v_dependent THEN NULLIF(v_payload ->> 'guardianId', '')::uuid ELSE NULL END,
    CASE WHEN v_dependent THEN NULLIF(v_payload ->> 'guardianName', '') ELSE NULL END,
    CASE WHEN v_dependent THEN regexp_replace(COALESCE(v_payload ->> 'guardianCpf', ''), '[^0-9]', '', 'g') ELSE NULL END,
    CASE WHEN v_dependent THEN NULLIF(v_payload ->> 'guardianEmail', '') ELSE NULL END,
    CASE WHEN v_dependent THEN regexp_replace(COALESCE(v_payload ->> 'guardianPhone', ''), '[^0-9]', '', 'g') ELSE NULL END,
    CASE WHEN v_dependent THEN regexp_replace(COALESCE(v_payload ->> 'studentPhone', ''), '[^0-9]', '', 'g') ELSE NULL END,
    v_referrer_teacher_id,
    v_referrer_student_id
  )
  ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email,
    full_name = EXCLUDED.full_name,
    role = 'STUDENT',
    tenant_id = EXCLUDED.tenant_id,
    phone = EXCLUDED.phone,
    cpf = EXCLUDED.cpf,
    postal_code = EXCLUDED.postal_code,
    address = EXCLUDED.address,
    address_number = EXCLUDED.address_number,
    status_financial = 'PENDING',
    monthly_fee = EXCLUDED.monthly_fee,
    due_day = EXCLUDED.due_day,
    module = CASE
      WHEN public.profiles.module IS NULL OR public.profiles.module IN ('General', '') THEN EXCLUDED.module
      ELSE public.profiles.module
    END,
    current_book_part = CASE
      WHEN public.profiles.current_book_part IS NULL OR public.profiles.current_book_part = 'A1-1' THEN EXCLUDED.current_book_part
      ELSE public.profiles.current_book_part
    END,
    contract_accepted = true,
    documentation_status = EXCLUDED.documentation_status,
    accepted_at = COALESCE(public.profiles.accepted_at, EXCLUDED.accepted_at),
    class_frequency = EXCLUDED.class_frequency,
    signature_ip = EXCLUDED.signature_ip,
    student_signature_url = COALESCE(EXCLUDED.student_signature_url, public.profiles.student_signature_url),
    signed_document_url = COALESCE(EXCLUDED.signed_document_url, public.profiles.signed_document_url),
    wise_wolf_signature_token = COALESCE(public.profiles.wise_wolf_signature_token, EXCLUDED.wise_wolf_signature_token),
    enrollment_fee = EXCLUDED.enrollment_fee,
    enrollment_fee_paid = CASE
      WHEN EXCLUDED.enrollment_fee <= 0 THEN true
      ELSE COALESCE(public.profiles.enrollment_fee_paid, false)
    END,
    professor_id = EXCLUDED.professor_id,
    professor_id2 = EXCLUDED.professor_id2,
    start_date = EXCLUDED.start_date,
    guardian_id = EXCLUDED.guardian_id,
    guardian_name = EXCLUDED.guardian_name,
    guardian_cpf = EXCLUDED.guardian_cpf,
    guardian_email = EXCLUDED.guardian_email,
    guardian_phone = EXCLUDED.guardian_phone,
    attendance_phone = EXCLUDED.attendance_phone,
    referrer_teacher_id = COALESCE(public.profiles.referrer_teacher_id, EXCLUDED.referrer_teacher_id),
    referrer_student_id = COALESCE(public.profiles.referrer_student_id, EXCLUDED.referrer_student_id);

  IF v_invite_id IS NOT NULL
     AND (v_referrer_teacher_id IS NOT NULL OR v_referrer_student_id IS NOT NULL) THEN
    UPDATE public.referral_invites
       SET status = 'CONVERTED',
           converted_at = COALESCE(converted_at, now()),
           converted_student_id = v_user
     WHERE id = v_invite_id
       AND status = 'PENDING';
  END IF;

  IF o.opportunity_id IS NOT NULL THEN
    UPDATE public.opportunities
       SET conversion_status = 'WON',
           student_id = v_user
     WHERE id = o.opportunity_id;
  END IF;

  SELECT el.id
    INTO v_enrollment_link_id
    FROM public.enrollment_links el
   WHERE el.offer_id = o.id
   LIMIT 1;

  UPDATE public.enrollment_links
     SET status = 'USED',
         used_at = COALESCE(used_at, now())
   WHERE offer_id = o.id
     AND status = 'PENDING';

  IF o.vendor_id IS NOT NULL THEN
    SELECT p.role, p.tenant_id, COALESCE(p.commission_rate, 3000)
      INTO v_vendor_role, v_vendor_tenant, v_commission_rate
      FROM public.profiles p
     WHERE p.id = o.vendor_id;

    IF v_vendor_role = 'SALESPERSON'
       AND v_vendor_tenant = o.tenant_id THEN
      INSERT INTO public.vendor_commissions (
        vendor_id, student_id, enrollment_link_id, offer_id,
        amount_brl, status, tenant_id
      )
      VALUES (
        o.vendor_id, v_user, v_enrollment_link_id, o.id,
        v_commission_rate, 'PENDING', o.tenant_id
      )
      ON CONFLICT (offer_id) WHERE offer_id IS NOT NULL DO NOTHING;
    END IF;
  END IF;

  -- Registro de auditoria do posicionamento inicial
  IF to_regclass('public.pedagogical_placement_audit') IS NOT NULL THEN
    INSERT INTO public.pedagogical_placement_audit (
      tenant_id,
      student_id,
      actor_id,
      previous_module,
      previous_book_part,
      new_module,
      new_book_part,
      reason
    ) VALUES (
      o.tenant_id,
      v_user,
      v_user,
      NULL,
      NULL,
      v_desired_module,
      v_desired_book_part,
      'Posicionamento pedagógico inicial na matrícula autorizada'
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'offer_id', o.id,
    'payload', v_payload || jsonb_build_object('_offerId', o.id)
  );
END;
$$;


--
-- Name: claim_financial_report_message(text, text, text, date, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_financial_report_message(p_tenant_id text, p_notification_kind text, p_subject_id text, p_ref_date date, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.financial_report_message_attempts%rowtype;
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  normalized_kind text := upper(pg_catalog.btrim(coalesce(p_notification_kind, '')));
  normalized_subject text := nullif(pg_catalog.btrim(coalesce(p_subject_id, '')), '');
  safe_lease integer := greatest(60, least(coalesce(p_lease_seconds, 300), 600));
begin
  if normalized_tenant is null
     or normalized_kind not in (
       'DRE_REPORT', 'WEEKLY_DIGEST', 'MONTHLY_CLOSING'
     )
     or normalized_subject is null
     or length(normalized_subject) > 240
     or p_ref_date is null
     or p_claim_token is null
     or (
       normalized_kind = 'WEEKLY_DIGEST'
       and normalized_subject <> normalized_tenant
     )
     or (
       normalized_kind = 'DRE_REPORT'
       and normalized_subject not in (
         normalized_tenant,
         normalized_tenant || ':manual'
       )
     )
  then
    raise exception using errcode = '22023', message = 'invalid_financial_report_message_claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'financial-report-message:' || normalized_tenant || ':'
        || normalized_kind || ':' || normalized_subject || ':' || p_ref_date::text,
      0
    )
  );

  if not private.financial_report_message_exact_scope_active(
    normalized_tenant,
    normalized_kind,
    normalized_subject,
    p_ref_date
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'financial_report_scope_inactive'
    );
  end if;

  insert into public.financial_report_message_attempts (
    tenant_id,
    notification_kind,
    subject_id,
    ref_date,
    claim_token,
    lease_expires_at
  ) values (
    normalized_tenant,
    normalized_kind,
    normalized_subject,
    p_ref_date,
    p_claim_token,
    pg_catalog.now() + pg_catalog.make_interval(secs => safe_lease)
  ) on conflict (tenant_id, notification_kind, subject_id, ref_date) do nothing;

  select attempt.* into attempt_row
    from public.financial_report_message_attempts as attempt
   where attempt.tenant_id = normalized_tenant
     and attempt.notification_kind = normalized_kind
     and attempt.subject_id = normalized_subject
     and attempt.ref_date = p_ref_date
   for update;

  if attempt_row.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED')
     or attempt_row.submit_attempt_count > 0
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_FINAL',
      'attempt_id', attempt_row.id,
      'status', attempt_row.status
    );
  end if;
  if attempt_row.claim_token is distinct from p_claim_token
     and attempt_row.lease_expires_at > pg_catalog.now()
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'attempt_id', attempt_row.id,
      'status', attempt_row.status
    );
  end if;

  update public.financial_report_message_attempts
     set claim_token = p_claim_token,
         lease_expires_at = pg_catalog.now()
           + pg_catalog.make_interval(secs => safe_lease),
         updated_at = pg_catalog.now()
   where id = attempt_row.id
   returning * into attempt_row;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_ONCE',
    'attempt_id', attempt_row.id,
    'claim_token', attempt_row.claim_token,
    'status', attempt_row.status
  );
end;
$$;


--
-- Name: claim_hub_fulfillment_outbox(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_hub_fulfillment_outbox(p_checkout_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 10) RETURNS TABLE(id bigint, checkout_id uuid, channel text, recipient text, recipient_name text, product_family text, plan_code text, plan_name text, attempt_count integer, lease_token uuid, provider_dispatch_started_at timestamp with time zone, metadata jsonb)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with quarantined as (
    update public.hub_fulfillment_outbox as queued
    set status = 'UNCERTAIN',
        lease_token = null,
        lease_expires_at = null,
        last_error = 'provider_outcome_unknown',
        updated_at = pg_catalog.now()
    where queued.status in ('PENDING', 'PROCESSING')
      and queued.provider_dispatch_started_at is not null
      and (
        (
          queued.status = 'PENDING'
          and queued.next_attempt_at <= pg_catalog.now()
        )
        or (
          queued.status = 'PROCESSING'
          and queued.lease_expires_at <= pg_catalog.now()
        )
      )
      and (
        queued.channel = 'WHATSAPP'
        or queued.provider_dispatch_started_at <=
          pg_catalog.now() - interval '23 hours'
      )
    returning queued.id
  ), candidates as (
    select queued.id
    from public.hub_fulfillment_outbox as queued
    where (p_checkout_id is null or queued.checkout_id = p_checkout_id)
      and queued.attempt_count < 8
      and (
        (
          queued.status = 'PENDING'
          and queued.next_attempt_at <= pg_catalog.now()
        )
        or (
          queued.status = 'PROCESSING'
          and queued.lease_expires_at <= pg_catalog.now()
        )
      )
      and (
        queued.provider_dispatch_started_at is null
        or (
          queued.channel = 'EMAIL'
          and queued.provider_dispatch_started_at >
            pg_catalog.now() - interval '23 hours'
        )
      )
      and not exists (
        select 1
        from quarantined
        where quarantined.id = queued.id
      )
    order by queued.next_attempt_at, queued.created_at, queued.id
    limit greatest(least(p_limit, 10), 1)
    for update skip locked
  ), claimed as (
    update public.hub_fulfillment_outbox as queued
    set status = 'PROCESSING',
        attempt_count = queued.attempt_count + 1,
        lease_token = pg_catalog.gen_random_uuid(),
        lease_expires_at = pg_catalog.now() + interval '5 minutes',
        last_error = null,
        updated_at = pg_catalog.now()
    from candidates
    where queued.id = candidates.id
    returning
      queued.id,
      queued.checkout_id,
      queued.channel,
      queued.recipient,
      queued.recipient_name,
      queued.product_family,
      queued.plan_code,
      queued.plan_name,
      queued.attempt_count,
      queued.lease_token,
      queued.provider_dispatch_started_at,
      queued.metadata
  )
  select * from claimed;
$$;


--
-- Name: FUNCTION claim_hub_fulfillment_outbox(p_checkout_id uuid, p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_hub_fulfillment_outbox(p_checkout_id uuid, p_limit integer) IS 'Claims due Hub deliveries with tokenized leases, quarantining ambiguous provider outcomes. Service role only.';


--
-- Name: claim_invite_offer_server(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_invite_offer_server(p_offer_id uuid, p_kind text, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  claimed_offer record;
BEGIN
  IF p_kind IS NULL
    OR p_kind NOT IN ('TEACHER_INVITE', 'VENDOR_INVITE')
    OR p_claim_token IS NULL
  THEN
    RAISE EXCEPTION 'invalid_invite_claim' USING ERRCODE = '22023';
  END IF;

  UPDATE public.offers AS offer
  SET invite_claim_token = p_claim_token,
      invite_claimed_at = now()
  WHERE offer.id = p_offer_id
    AND offer.kind = p_kind
    AND offer.invite_security_version >= 1
    AND private.tenant_is_operational(offer.tenant_id)
    AND offer.consumed_at IS NULL
    AND offer.revoked_at IS NULL
    AND offer.expires_at > now()
    AND (
      offer.invite_claim_token IS NULL
      OR offer.invite_claimed_at IS NULL
      OR offer.invite_claimed_at <= now() - interval '15 minutes'
    )
  RETURNING offer.id, offer.kind, offer.tenant_id, offer.payload
  INTO claimed_offer;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invite_unavailable' USING ERRCODE = 'P0002';
  END IF;
  IF claimed_offer.tenant_id IS NULL
    OR jsonb_typeof(claimed_offer.payload) IS DISTINCT FROM 'object'
  THEN
    RAISE EXCEPTION 'invalid_persisted_invite' USING ERRCODE = '22023';
  END IF;

  RETURN claimed_offer.payload
    || jsonb_build_object(
      'kind', claimed_offer.kind,
      'tenantId', claimed_offer.tenant_id,
      '_offerId', claimed_offer.id
    );
END;
$$;


--
-- Name: claim_management_group_message(text, text, text, date, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_management_group_message(p_tenant_id text, p_notification_kind text, p_subject_id text, p_ref_date date, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  attempt_row public.management_group_message_attempts%rowtype;
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  normalized_kind text := upper(pg_catalog.btrim(coalesce(p_notification_kind, '')));
  normalized_subject text := nullif(pg_catalog.btrim(coalesce(p_subject_id, '')), '');
  safe_lease integer := greatest(60, least(coalesce(p_lease_seconds, 300), 600));
begin
  if normalized_tenant is null
     or normalized_kind not in ('PAYMENT_CONFIRMED', 'MONTHLY_PAYMENT_CLOSE')
     or normalized_subject is null
     or pg_catalog.length(normalized_subject) > 240
     or p_ref_date is null
     or p_claim_token is null
     or (
       normalized_kind = 'MONTHLY_PAYMENT_CLOSE'
       and normalized_subject <> normalized_tenant
     )
     or (
       normalized_kind = 'PAYMENT_CONFIRMED'
       and normalized_subject !~
         '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
     )
  then
    raise exception using
      errcode = '22023',
      message = 'invalid_management_group_message_claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'management-group-message:' || normalized_tenant || ':' ||
        normalized_kind || ':' || normalized_subject || ':' || p_ref_date::text,
      0
    )
  );

  if not private.management_group_message_exact_scope_active(
    normalized_tenant,
    normalized_kind,
    normalized_subject,
    p_ref_date
  ) then
    return jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'management_message_scope_inactive'
    );
  end if;

  insert into public.management_group_message_attempts (
    tenant_id,
    notification_kind,
    subject_id,
    ref_date,
    claim_token,
    lease_expires_at
  ) values (
    normalized_tenant,
    normalized_kind,
    normalized_subject,
    p_ref_date,
    p_claim_token,
    pg_catalog.now() + pg_catalog.make_interval(secs => safe_lease)
  ) on conflict (tenant_id, notification_kind, subject_id, ref_date) do nothing;

  select attempt.*
    into attempt_row
    from public.management_group_message_attempts as attempt
   where attempt.tenant_id = normalized_tenant
     and attempt.notification_kind = normalized_kind
     and attempt.subject_id = normalized_subject
     and attempt.ref_date = p_ref_date
   for update;

  if attempt_row.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED')
     or attempt_row.submit_attempt_count > 0
  then
    return jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_FINAL',
      'attempt_id', attempt_row.id,
      'status', attempt_row.status
    );
  end if;
  if attempt_row.claim_token is distinct from p_claim_token
     and attempt_row.lease_expires_at > pg_catalog.now()
  then
    return jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'attempt_id', attempt_row.id,
      'status', attempt_row.status
    );
  end if;

  update public.management_group_message_attempts
     set claim_token = p_claim_token,
         lease_expires_at = pg_catalog.now()
           + pg_catalog.make_interval(secs => safe_lease),
         updated_at = pg_catalog.now()
   where id = attempt_row.id
   returning * into attempt_row;

  return jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_ONCE',
    'attempt_id', attempt_row.id,
    'claim_token', attempt_row.claim_token,
    'status', attempt_row.status
  );
end;
$_$;


--
-- Name: claim_management_payment_notification(text, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_management_payment_notification(p_tenant_id text, p_payment_id uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_outbox public.management_payment_notification_outbox%rowtype;
  v_tenant_id text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  v_replacement_kind text;
  v_lease_seconds integer := greatest(
    60,
    least(coalesce(p_lease_seconds, 300), 600)
  );
begin
  if v_tenant_id is null or p_payment_id is null or p_claim_token is null then
    raise exception 'invalid_management_payment_notification_claim'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'management-payment-notification:' || v_tenant_id || ':' ||
        p_payment_id::text,
      0
    )
  );

  select outbox.*
  into v_outbox
  from public.management_payment_notification_outbox as outbox
  where outbox.tenant_id = v_tenant_id
    and outbox.payment_id = p_payment_id
  for update;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'durable_payment_notification_intent_missing'
    );
  end if;

  if v_outbox.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED')
     or v_outbox.submit_attempt_count > 0 then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_FINAL',
      'attempt_id', v_outbox.id,
      'status', v_outbox.status,
      'notification_kind', v_outbox.notification_kind
    );
  end if;

  v_replacement_kind :=
    private.management_payment_notification_replacement_kind(
      v_outbox.tenant_id,
      v_outbox.payment_id
    );
  if v_replacement_kind is not null
     and v_replacement_kind is distinct from v_outbox.notification_kind then
    update public.management_payment_notification_outbox
    set notification_kind = v_replacement_kind,
        status = 'PENDING',
        claim_token = null,
        lease_expires_at = null,
        configured_destination_snapshot = null,
        provider_destination = null,
        provider_instance_name = null,
        provider_integration_id = null,
        provider_integration_version = null,
        provider_endpoint_hash = null,
        provider_credential_hash = null,
        message_body = null,
        source_snapshot = null,
        source_snapshot_hash = null,
        snapshot_hash = null,
        last_error = 'management_payment_notification_kind_regenerated',
        updated_at = pg_catalog.now()
    where id = v_outbox.id
      and submit_attempt_count = 0;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'RETRY',
      'attempt_id', v_outbox.id,
      'status', 'PENDING',
      'notification_kind', v_replacement_kind,
      'reason', 'management_payment_notification_kind_regenerated'
    );
  end if;

  if not private.management_payment_notification_scope_active(
    v_outbox.tenant_id,
    v_outbox.payment_id,
    v_outbox.notification_kind
  ) then
    v_replacement_kind :=
      private.management_payment_notification_replacement_kind(
        v_outbox.tenant_id,
        v_outbox.payment_id
      );
    if v_replacement_kind is not null
       and v_replacement_kind is distinct from v_outbox.notification_kind then
      update public.management_payment_notification_outbox
      set notification_kind = v_replacement_kind,
          status = 'PENDING',
          claim_token = null,
          lease_expires_at = null,
          configured_destination_snapshot = null,
          provider_destination = null,
          provider_instance_name = null,
          provider_integration_id = null,
          provider_integration_version = null,
          provider_endpoint_hash = null,
          provider_credential_hash = null,
          message_body = null,
          source_snapshot = null,
          source_snapshot_hash = null,
          snapshot_hash = null,
          last_error = 'management_payment_notification_kind_regenerated',
          updated_at = pg_catalog.now()
      where id = v_outbox.id
        and submit_attempt_count = 0;
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'RETRY',
        'status', 'PENDING',
        'notification_kind', v_replacement_kind,
        'reason', 'management_payment_notification_kind_regenerated'
      );
    end if;

    update public.management_payment_notification_outbox
    set status = 'SUPPRESSED',
        lease_expires_at = pg_catalog.now(),
        last_error = 'management_payment_notification_scope_inactive',
        updated_at = pg_catalog.now()
    where id = v_outbox.id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'attempt_id', v_outbox.id,
      'status', 'SUPPRESSED',
      'reason', 'management_payment_notification_scope_inactive'
    );
  end if;

  if v_outbox.status in ('CLAIMED', 'PREPARED')
     and v_outbox.claim_token is distinct from p_claim_token
     and v_outbox.lease_expires_at > pg_catalog.now() then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'attempt_id', v_outbox.id,
      'status', v_outbox.status,
      'notification_kind', v_outbox.notification_kind
    );
  end if;

  update public.management_payment_notification_outbox
  set status = 'CLAIMED',
      claim_token = p_claim_token,
      lease_expires_at = pg_catalog.now()
        + pg_catalog.make_interval(secs => v_lease_seconds),
      configured_destination_snapshot = null,
      provider_destination = null,
      provider_instance_name = null,
      provider_integration_id = null,
      provider_integration_version = null,
      provider_endpoint_hash = null,
      provider_credential_hash = null,
      message_body = null,
      source_snapshot = null,
      source_snapshot_hash = null,
      snapshot_hash = null,
      last_error = null,
      updated_at = pg_catalog.now()
  where id = v_outbox.id
    and submit_attempt_count = 0
  returning * into v_outbox;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_ONCE',
    'attempt_id', v_outbox.id,
    'claim_token', v_outbox.claim_token,
    'status', v_outbox.status,
    'tenant_id', v_outbox.tenant_id,
    'payment_id', v_outbox.payment_id,
    'notification_kind', v_outbox.notification_kind
  );
end;
$$;


--
-- Name: claim_next_asaas_webhook_event(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_next_asaas_webhook_event(p_worker_token uuid, p_lease_seconds integer DEFAULT 240) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  worker_lock public.asaas_automation_worker_locks%rowtype;
  claimed public.asaas_webhook_inbox%rowtype;
  safe_lease integer := greatest(30, least(coalesce(p_lease_seconds, 240), 600));
begin
  if p_worker_token is null then
    raise exception using errcode = '22023', message = 'worker_token_required';
  end if;

  insert into public.asaas_automation_worker_locks (worker_name)
  values ('webhook')
  on conflict (worker_name) do nothing;

  select lock_row.*
    into worker_lock
    from public.asaas_automation_worker_locks as lock_row
   where lock_row.worker_name = 'webhook'
   for update;

  if worker_lock.lease_owner is not null
     and worker_lock.lease_owner <> p_worker_token
     and worker_lock.lease_expires_at > now()
  then
    return null;
  end if;

  update public.asaas_automation_worker_locks
     set lease_owner = p_worker_token,
         lease_expires_at = now() + make_interval(secs => safe_lease),
         updated_at = now()
   where worker_name = 'webhook';

  update public.asaas_webhook_inbox
     set status = 'RETRY',
         lease_owner = null,
         lease_expires_at = null,
         next_attempt_at = now(),
         last_error = coalesce(last_error, 'processing_lease_expired'),
         updated_at = now()
   where status = 'PROCESSING'
     and lease_expires_at <= now();

  select inbox.*
    into claimed
    from public.asaas_webhook_inbox as inbox
   where inbox.status in ('RECEIVED', 'RETRY')
     and inbox.next_attempt_at <= now()
     and not exists (
       select 1
         from public.asaas_webhook_inbox as earlier
        where earlier.provider_entity_id = inbox.provider_entity_id
          and earlier.status in ('RECEIVED', 'RETRY', 'PROCESSING')
          and (
            coalesce(earlier.event_created_at, 'infinity'::timestamptz),
            earlier.received_at,
            earlier.provider_event_id
          ) < (
            coalesce(inbox.event_created_at, 'infinity'::timestamptz),
            inbox.received_at,
            inbox.provider_event_id
          )
     )
   order by
     inbox.next_attempt_at asc,
     inbox.event_created_at asc nulls last,
     inbox.received_at asc,
     inbox.provider_event_id asc
   for update skip locked
   limit 1;

  if claimed.provider_event_id is null then
    update public.asaas_automation_worker_locks
       set lease_owner = null,
           lease_expires_at = null,
           updated_at = now()
     where worker_name = 'webhook'
       and lease_owner = p_worker_token;
    return null;
  end if;

  update public.asaas_webhook_inbox
     set status = 'PROCESSING',
         attempt_count = least(attempt_count + 1, 100),
         lease_owner = p_worker_token,
         lease_expires_at = now() + make_interval(secs => safe_lease),
         updated_at = now()
   where provider_event_id = claimed.provider_event_id;

  return jsonb_build_object(
    'provider_event_id', claimed.provider_event_id,
    'event_name', claimed.event_name,
    'provider_entity_id', claimed.provider_entity_id,
    'event_created_at', claimed.event_created_at,
    'payload', claimed.payload,
    'attempt_count', claimed.attempt_count + 1
  );
end;
$$;


--
-- Name: notification_queue; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.notification_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    teacher_id uuid,
    student_id uuid,
    student_name text,
    student_phone text NOT NULL,
    message_body text NOT NULL,
    scheduled_for timestamp with time zone NOT NULL,
    status text DEFAULT 'pending'::text,
    attempts integer DEFAULT 0 NOT NULL,
    last_error text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    source_id uuid,
    source_type text,
    class_date date,
    notification_kind text DEFAULT 'LESSON_REMINDER'::text,
    idempotency_key text,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    claim_token uuid,
    lease_expires_at timestamp with time zone,
    provider_instance_name text,
    provider_destination text,
    provider_integration_id uuid,
    provider_integration_version bigint,
    provider_message_id text,
    provider_http_status integer,
    delivery_status text DEFAULT 'queued'::text NOT NULL,
    accepted_at timestamp with time zone,
    sent_at timestamp with time zone,
    delivered_at timestamp with time zone,
    read_at timestamp with time zone,
    dead_letter_at timestamp with time zone,
    max_attempts integer DEFAULT 5 NOT NULL,
    CONSTRAINT notification_queue_delivery_status_check CHECK ((delivery_status = ANY (ARRAY['queued'::text, 'preparing'::text, 'submitting'::text, 'accepted'::text, 'sent'::text, 'delivered'::text, 'read'::text, 'failed'::text, 'uncertain'::text, 'skipped'::text]))),
    CONSTRAINT notification_queue_idempotency_key_check CHECK (((idempotency_key IS NULL) OR (((char_length(idempotency_key) >= 1) AND (char_length(idempotency_key) <= 320)) AND (idempotency_key = btrim(idempotency_key)) AND (idempotency_key !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT notification_queue_kind_canonical_check CHECK (((notification_kind IS NULL) OR ((notification_kind = upper(btrim(notification_kind))) AND ((char_length(notification_kind) >= 1) AND (char_length(notification_kind) <= 80)) AND (notification_kind !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT notification_queue_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 20))),
    CONSTRAINT notification_queue_provider_destination_check CHECK (((provider_destination IS NULL) OR (((provider_destination ~ '^[0-9]{12,15}$'::text) OR (provider_destination ~ '^[0-9]{10,25}@g[.]us$'::text)) AND (provider_destination = btrim(provider_destination))))),
    CONSTRAINT notification_queue_provider_http_status_check CHECK (((provider_http_status IS NULL) OR ((provider_http_status >= 100) AND (provider_http_status <= 599)))),
    CONSTRAINT notification_queue_provider_identity_check CHECK ((((provider_message_id IS NULL) AND ((delivery_status <> ALL (ARRAY['accepted'::text, 'sent'::text, 'delivered'::text, 'read'::text])) OR (status = 'sent'::text))) OR ((provider_instance_name IS NOT NULL) AND ((char_length(provider_instance_name) >= 3) AND (char_length(provider_instance_name) <= 120)) AND (provider_instance_name = btrim(provider_instance_name)) AND (provider_instance_name !~ '[[:cntrl:]]'::text) AND ((char_length(provider_message_id) >= 1) AND (char_length(provider_message_id) <= 320)) AND (provider_message_id = btrim(provider_message_id)) AND (provider_message_id !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT notification_queue_provider_integration_check CHECK ((((provider_integration_id IS NULL) AND (provider_integration_version IS NULL)) OR ((provider_integration_id IS NOT NULL) AND (provider_integration_version IS NOT NULL) AND (provider_integration_version > 0)))),
    CONSTRAINT notification_queue_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'sent'::text, 'failed'::text, 'skipped'::text]))),
    CONSTRAINT notification_queue_submitting_binding_check CHECK (((delivery_status <> 'submitting'::text) OR ((provider_instance_name IS NOT NULL) AND (provider_destination IS NOT NULL) AND (provider_integration_id IS NOT NULL) AND (provider_integration_version IS NOT NULL) AND (provider_integration_version > 0))))
);


--
-- Name: claim_notification_delivery_batch(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_notification_delivery_batch(p_limit integer DEFAULT 50, p_lease_seconds integer DEFAULT 120) RETURNS SETOF public.notification_queue
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 200));
  v_lease_seconds integer := greatest(
    30,
    least(coalesce(p_lease_seconds, 120), 600)
  );
  v_stale_pair record;
  v_stale_outbound public.asaas_outbound_message_attempts%rowtype;
  v_stale_notification public.notification_queue%rowtype;
begin
  -- A crash before SUBMITTING is provably side-effect free. Release the
  -- financial CLAIMED row for a retry, or retain it as SUPPRESSED when the
  -- queue has exhausted its attempts. Both paths use lifecycle -> attempt ->
  -- queue and prevent an expired CLAIMED fence from blocking the student.
  for v_stale_pair in
    select
      notification.id as notification_id,
      outbound.id as outbound_id,
      outbound.tenant_id,
      outbound.student_id
    from public.notification_queue as notification
    join public.asaas_outbound_message_attempts as outbound
      on outbound.notification_queue_id is null
     and outbound.tenant_id = notification.tenant_id
     and outbound.student_id = notification.student_id
     and outbound.provider_entity_id = notification.source_id::text
     and upper(pg_catalog.btrim(coalesce(
       outbound.notification_kind,
       ''
     ))) = 'PAYMENT_CONFIRMED_WHATSAPP'
    where notification.status = 'processing'
      and notification.delivery_status = 'preparing'
      and notification.lease_expires_at <= now()
      and upper(pg_catalog.btrim(coalesce(
        notification.source_type,
        ''
      ))) = 'ASAAS_PAYMENT'
      and private.canonical_payment_notification_kind(
        notification.notification_kind
      ) = 'PAYMENT_CONFIRMED_WHATSAPP'
      and outbound.status = 'CLAIMED'
      and outbound.submit_attempt_count = 0
    order by notification.lease_expires_at, notification.id
    limit 200
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'student-billing-lifecycle:' || v_stale_pair.tenant_id || ':' ||
        v_stale_pair.student_id::text,
        0
      )
    );

    select outbound.*
    into v_stale_outbound
    from public.asaas_outbound_message_attempts as outbound
    where outbound.id = v_stale_pair.outbound_id
    for update;

    if not found then
      continue;
    end if;

    select notification.*
    into v_stale_notification
    from public.notification_queue as notification
    where notification.id = v_stale_pair.notification_id
    for update;

    if v_stale_outbound.status = 'CLAIMED'
       and v_stale_outbound.submit_attempt_count = 0
       and v_stale_outbound.notification_queue_id is null
       and v_stale_notification.status = 'processing'
       and v_stale_notification.delivery_status = 'preparing'
       and v_stale_notification.lease_expires_at <= now()
       and v_stale_outbound.provider_entity_id =
         v_stale_notification.source_id::text then
      if v_stale_notification.attempts >=
         v_stale_notification.max_attempts then
        update public.asaas_outbound_message_attempts as outbound
        set notification_queue_id = v_stale_notification.id,
            status = 'SUPPRESSED',
            lease_expires_at = now(),
            last_error = 'payment_confirmation_delivery_attempts_exhausted',
            updated_at = now()
        where outbound.id = v_stale_outbound.id;

        update public.notification_queue as notification
        set status = 'failed',
            delivery_status = 'failed',
            dead_letter_at = coalesce(notification.dead_letter_at, now()),
            last_error = 'notification_delivery_attempts_exhausted',
            claim_token = null,
            lease_expires_at = null,
            updated_at = now()
        where notification.id = v_stale_notification.id;
      else
        delete from public.asaas_outbound_message_attempts as outbound
        where outbound.id = v_stale_outbound.id;

        update public.notification_queue as notification
        set status = 'pending',
            delivery_status = 'queued',
            next_attempt_at = now(),
            dead_letter_at = null,
            last_error = 'notification_preparation_lease_expired',
            claim_token = null,
            lease_expires_at = null,
            updated_at = now()
        where notification.id = v_stale_notification.id;
      end if;
    end if;
  end loop;

  -- A paired payment submission must never leave only the queue terminal. Work
  -- through bounded candidates without row locks, then use the canonical
  -- lifecycle -> financial attempt -> queue order and revalidate both states.
  -- This converts a crash after SUBMITTING to UNKNOWN/UNCERTAIN atomically.
  for v_stale_pair in
    select
      notification.id as notification_id,
      outbound.id as outbound_id,
      outbound.tenant_id,
      outbound.student_id
    from public.notification_queue as notification
    join public.asaas_outbound_message_attempts as outbound
      on outbound.notification_queue_id = notification.id
    where notification.status = 'processing'
      and notification.delivery_status = 'submitting'
      and notification.lease_expires_at <= now()
      and outbound.status = 'SUBMITTING'
      and outbound.submit_attempt_count = 1
    order by notification.lease_expires_at, notification.id
    limit 200
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'student-billing-lifecycle:' || v_stale_pair.tenant_id || ':' ||
        v_stale_pair.student_id::text,
        0
      )
    );

    select outbound.*
    into v_stale_outbound
    from public.asaas_outbound_message_attempts as outbound
    where outbound.id = v_stale_pair.outbound_id
    for update;

    if not found then
      continue;
    end if;

    select notification.*
    into v_stale_notification
    from public.notification_queue as notification
    where notification.id = v_stale_pair.notification_id
    for update;

    if v_stale_outbound.status = 'SUBMITTING'
       and v_stale_outbound.submit_attempt_count = 1
       and v_stale_outbound.notification_queue_id =
         v_stale_notification.id
       and v_stale_notification.status = 'processing'
       and v_stale_notification.delivery_status = 'submitting'
       and v_stale_notification.lease_expires_at <= now() then
      update public.asaas_outbound_message_attempts as outbound
      set status = 'UNKNOWN',
          provider_delivery_status =
            private.merge_notification_delivery_status(
              coalesce(outbound.provider_delivery_status, 'submitting'),
              'uncertain'
            ),
          lease_expires_at = now(),
          last_error = coalesce(
            outbound.last_error,
            'payment_confirmation_submission_lease_expired'
          ),
          updated_at = now()
      where outbound.id = v_stale_outbound.id;

      update public.notification_queue as notification
      set status = 'failed',
          delivery_status = 'uncertain',
          dead_letter_at = coalesce(notification.dead_letter_at, now()),
          last_error = coalesce(
            notification.last_error,
            'notification_submission_lease_expired'
          ),
          claim_token = null,
          lease_expires_at = null,
          updated_at = now()
      where notification.id = v_stale_notification.id;
    end if;
  end loop;

  -- During a rolling cutover, an already-running legacy worker can still set
  -- only STATUS=PROCESSING after this migration lands. It may subsequently
  -- cross the provider boundary without a claim token. Once stale, that state
  -- is ambiguous and must fail closed instead of remaining stuck or retrying.
  update public.notification_queue as notification
  set status = 'failed',
      delivery_status = 'uncertain',
      dead_letter_at = coalesce(notification.dead_letter_at, now()),
      last_error = coalesce(
        notification.last_error,
        'legacy_worker_delivery_state_uncertain'
      ),
      claim_token = null,
      lease_expires_at = null,
      updated_at = now()
  where notification.status = 'processing'
    and notification.delivery_status = 'queued'
    and notification.claim_token is null
    and notification.lease_expires_at is null
    and notification.updated_at <= now() - interval '10 minutes';

  -- A claim that expired before SUBMITTING is safe to retry. At max attempts it
  -- is dead-lettered instead of being claimed forever.
  update public.notification_queue as notification
  set status = case
        when notification.attempts >= notification.max_attempts
          then 'failed'
        else 'pending'
      end,
      delivery_status = case
        when notification.attempts >= notification.max_attempts
          then 'failed'
        else 'queued'
      end,
      next_attempt_at = case
        when notification.attempts >= notification.max_attempts
          then notification.next_attempt_at
        else now()
      end,
      dead_letter_at = case
        when notification.attempts >= notification.max_attempts
          then coalesce(notification.dead_letter_at, now())
        else null
      end,
      last_error = case
        when notification.attempts >= notification.max_attempts
          then 'notification_delivery_attempts_exhausted'
        else 'notification_preparation_lease_expired'
      end,
      claim_token = null,
      lease_expires_at = null,
      updated_at = now()
  where notification.status = 'processing'
    and notification.delivery_status = 'preparing'
    and notification.lease_expires_at <= now()
    and not exists (
      select 1
      from public.asaas_outbound_message_attempts as outbound
      where outbound.notification_queue_id is null
        and outbound.tenant_id = notification.tenant_id
        and outbound.student_id = notification.student_id
        and outbound.provider_entity_id = notification.source_id::text
        and outbound.status = 'CLAIMED'
        and outbound.submit_attempt_count = 0
        and upper(pg_catalog.btrim(coalesce(
          outbound.notification_kind,
          ''
        ))) = 'PAYMENT_CONFIRMED_WHATSAPP'
    );

  -- Once SUBMITTING began, a crash or timeout has an ambiguous side effect.
  -- The row is terminally uncertain and must be reconciled, never blind-retried.
  update public.notification_queue as notification
  set status = 'failed',
      delivery_status = 'uncertain',
      dead_letter_at = coalesce(notification.dead_letter_at, now()),
      last_error = coalesce(
        notification.last_error,
        'notification_submission_lease_expired'
      ),
      claim_token = null,
      lease_expires_at = null,
      updated_at = now()
  where notification.status = 'processing'
    and notification.delivery_status = 'submitting'
    and notification.lease_expires_at <= now()
    and not exists (
      select 1
      from public.asaas_outbound_message_attempts as outbound
      where outbound.notification_queue_id = notification.id
        and outbound.status = 'SUBMITTING'
        and outbound.submit_attempt_count = 1
    );

  update public.notification_queue as notification
  set status = 'failed',
      delivery_status = 'failed',
      dead_letter_at = coalesce(notification.dead_letter_at, now()),
      last_error = coalesce(
        notification.last_error,
        'notification_delivery_attempts_exhausted'
      ),
      claim_token = null,
      lease_expires_at = null,
      updated_at = now()
  where notification.status = 'pending'
    and notification.delivery_status = 'queued'
    and notification.attempts >= notification.max_attempts;

  return query
  with due as (
    select notification.id
    from public.notification_queue as notification
    where notification.status = 'pending'
      and notification.delivery_status = 'queued'
      and notification.attempts < notification.max_attempts
      and notification.scheduled_for <= now()
      and notification.next_attempt_at <= now()
    order by
      notification.next_attempt_at,
      notification.scheduled_for,
      notification.created_at,
      notification.id
    for update skip locked
    limit v_limit
  )
  update public.notification_queue as notification
  set status = 'processing',
      delivery_status = 'preparing',
      attempts = notification.attempts + 1,
      claim_token = gen_random_uuid(),
      lease_expires_at = now() + pg_catalog.make_interval(
        secs => v_lease_seconds
      ),
      last_error = null,
      updated_at = now()
  from due
  where notification.id = due.id
  returning notification.*;
end;
$$;


--
-- Name: claim_opportunity(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_opportunity(p_opp_id uuid, p_teacher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_opp RECORD;
    v_result JSONB;
BEGIN
    -- Atomic UPDATE with WHERE status='OPEN' — only one teacher can win
    UPDATE public.opportunities
    SET
        status = 'CLAIMED',
        claimed_by = p_teacher_id,
        claimed_at = now(),
        winner_teacher_id = p_teacher_id
    WHERE id = p_opp_id
      AND status = 'OPEN'
    RETURNING * INTO v_opp;

    -- If no rows updated, the opportunity was already claimed or doesn't exist
    IF v_opp IS NULL THEN
        -- Check if it exists at all
        PERFORM 1 FROM public.opportunities WHERE id = p_opp_id;
        IF NOT FOUND THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'OPPORTUNITY_NOT_FOUND',
                'message', 'Esta oportunidade não existe.'
            );
        ELSE
            RETURN jsonb_build_object(
                'success', false,
                'error', 'ALREADY_CLAIMED',
                'message', 'Esta vaga já foi preenchida por outro professor.'
            );
        END IF;
    END IF;

    -- Success
    RETURN jsonb_build_object(
        'success', true,
        'opportunity_id', v_opp.id,
        'student_name', v_opp.student_name,
        'student_phone', v_opp.student_phone,
        'claimed_by', p_teacher_id,
        'claimed_at', v_opp.claimed_at
    );
END;
$$;


--
-- Name: FUNCTION claim_opportunity(p_opp_id uuid, p_teacher_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_opportunity(p_opp_id uuid, p_teacher_id uuid) IS 'Atomically claims an OPEN opportunity. Returns error if already claimed (409 logic).';


--
-- Name: claim_opportunity_atomic(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_opportunity_atomic(p_opportunity_id uuid, p_teacher_id uuid, p_claim_generation integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
  v_appointment public.appointments%rowtype;
begin
  v_result := public.claim_opportunity_atomic_pre_crm_status_impl(
    p_opportunity_id,
    p_teacher_id,
    p_claim_generation
  );
  if coalesce((v_result ->> 'ok')::boolean, false) is not true then
    return v_result;
  end if;

  select appointment.*
    into v_appointment
    from public.appointments as appointment
    join public.opportunities as opportunity
      on opportunity.trial_appointment_id = appointment.id
     and opportunity.tenant_id = appointment.tenant_id
   where opportunity.id = p_opportunity_id
     and opportunity.status = 'CLAIMED'
     and opportunity.winner_teacher_id = p_teacher_id
     and opportunity.professor_id = p_teacher_id;
  if found then
    perform pg_catalog.set_config(
      'app.crm_trial_outcome_opportunity',
      p_opportunity_id::text,
      true
    );
    update public.crm_leads as lead
       set status = 'SCHEDULED',
           scheduled_at = v_appointment.start_time
     where lead.opportunity_id = p_opportunity_id
       and lead.tenant_id = v_appointment.tenant_id
       and lead.status not in ('TRIAL_DONE', 'WON', 'LOST');
    perform pg_catalog.set_config(
      'app.crm_trial_outcome_opportunity',
      '',
      true
    );
  end if;

  return v_result;
end;
$$;


--
-- Name: claim_opportunity_atomic_pre_crm_status_impl(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_opportunity_atomic_pre_crm_status_impl(p_opportunity_id uuid, p_teacher_id uuid, p_claim_generation integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_runtime_role text := coalesce((select auth.jwt() ->> 'role'), '');
  v_result jsonb;
  v_opportunity public.opportunities%rowtype;
  v_appointment public.appointments%rowtype;
  v_teacher public.profiles%rowtype;
  v_tenant public.tenants%rowtype;
  v_destination text;
  v_message text;
begin
  if v_runtime_role <> 'service_role' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'forbidden'
    );
  end if;
  v_result := public.claim_opportunity_atomic_pre_outbox_impl(
    p_opportunity_id,
    p_teacher_id,
    p_claim_generation
  );
  if coalesce((v_result ->> 'ok')::boolean, false) is not true
     or coalesce((v_result ->> 'idempotent')::boolean, false) is true then
    return v_result;
  end if;

  select opportunity.*
  into v_opportunity
  from public.opportunities as opportunity
  where opportunity.id = p_opportunity_id
  for update;
  if not found then
    raise exception 'trial_management_outbox_source_missing'
      using errcode = '40001';
  end if;

  -- The underlying claim RPC also schedules internal TRAINING opportunities.
  -- This outbox belongs only to the public trial funnel; preserve the existing
  -- training behavior without manufacturing a misleading trial notification.
  if v_opportunity.kind is distinct from 'TRIAL' then
    return v_result;
  end if;

  select appointment.*
  into v_appointment
  from public.appointments as appointment
  where appointment.id = v_opportunity.trial_appointment_id;
  select profile.*
  into v_teacher
  from public.profiles as profile
  where profile.id = p_teacher_id;
  select tenant.*
  into v_tenant
  from public.tenants as tenant
  where tenant.id = v_opportunity.tenant_id;

  if v_opportunity.status <> 'CLAIMED'
     or v_opportunity.winner_teacher_id <> p_teacher_id
     or v_opportunity.professor_id <> p_teacher_id
     or v_appointment.tenant_id <> v_opportunity.tenant_id
     or v_teacher.tenant_id <> v_opportunity.tenant_id
     or v_tenant.id <> v_opportunity.tenant_id then
    raise exception 'trial_management_outbox_binding_changed'
      using errcode = '40001';
  end if;

  v_destination := coalesce(
    private.trial_management_destination(v_opportunity.tenant_id),
    ''
  );
  v_message := '🔔 *AULA EXPERIMENTAL ACEITA — '
    || private.safe_notification_text(v_tenant.name, 120) || '*' || E'\n\n'
    || '👨🏫 *Professor:* '
    || private.safe_notification_text(v_teacher.full_name, 120) || E'\n'
    || '🎓 *Aluno:* '
    || private.safe_notification_text(v_opportunity.student_name, 120)
    || E'\n'
    || '📅 *Data:* '
    || pg_catalog.to_char(
      v_appointment.start_time at time zone 'America/Sao_Paulo',
      'DD/MM/YYYY HH24:MI'
    ) || E'\n\n'
    || '✅ Agendamento confirmado no sistema.';

  insert into public.notification_queue (
    tenant_id,
    student_name,
    student_phone,
    message_body,
    scheduled_for,
    status,
    delivery_status,
    next_attempt_at,
    notification_kind,
    source_id,
    source_type,
    class_date,
    idempotency_key
  ) values (
    v_opportunity.tenant_id,
    v_opportunity.student_name,
    v_destination,
    v_message,
    pg_catalog.now(),
    'pending',
    'queued',
    pg_catalog.now(),
    'TRIAL_MANAGEMENT_ACCEPTED',
    v_opportunity.id,
    'TRIAL_OPPORTUNITY',
    (v_appointment.start_time at time zone 'America/Sao_Paulo')::date,
    'trial-management-accepted:' || v_opportunity.id::text || ':'
      || p_claim_generation::text
  )
  on conflict (tenant_id, idempotency_key)
    where idempotency_key is not null
  do nothing;

  return v_result;
end;
$$;


--
-- Name: claim_opportunity_atomic_pre_outbox_impl(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_opportunity_atomic_pre_outbox_impl(p_opportunity_id uuid, p_teacher_id uuid, p_claim_generation integer) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  v_opportunity public.opportunities%rowtype;
  v_existing_appointment public.appointments%rowtype;
  v_appointment_id uuid;
  v_slot jsonb;
  v_slot_date date;
  v_slot_time time without time zone;
  v_start_time timestamptz;
  v_kind text;
  v_teacher_name text;
begin
  if p_opportunity_id is null or p_teacher_id is null
     or p_claim_generation is null or p_claim_generation < 1 then
    return jsonb_build_object('ok', false, 'error', 'invalid_request');
  end if;

  select opportunity.*
    into v_opportunity
    from public.opportunities as opportunity
   where opportunity.id = p_opportunity_id
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'opportunity_not_found');
  end if;
  if v_opportunity.tenant_id is null then
    return jsonb_build_object('ok', false, 'error', 'opportunity_inconsistent');
  end if;
  if v_opportunity.claim_generation is distinct from p_claim_generation then
    return jsonb_build_object('ok', false, 'error', 'claim_link_expired');
  end if;

  if not exists (
    select 1
      from public.tenants as tenant
     where tenant.id = v_opportunity.tenant_id
       and lower(trim(coalesce(tenant.saas_status, ''))) in (
         'active', 'trial', 'trialing'
       )
  ) then
    return jsonb_build_object('ok', false, 'error', 'tenant_not_operational');
  end if;

  select profile.full_name
    into v_teacher_name
    from public.profiles as profile
    join public.tenant_memberships as membership
      on membership.user_id = profile.id
     and membership.tenant_id = v_opportunity.tenant_id
     and membership.role = 'TEACHER'
     and membership.status = 'ACTIVE'
   where profile.id = p_teacher_id
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active';

  if not found then
    return jsonb_build_object(
      'ok', false,
      'error', 'teacher_not_active_for_tenant'
    );
  end if;

  v_kind := upper(coalesce(v_opportunity.kind, 'TRIAL'));
  if v_kind not in ('TRIAL', 'TRAINING') then
    return jsonb_build_object('ok', false, 'error', 'invalid_opportunity_kind');
  end if;

  -- Serializa tambem claims de oportunidades diferentes pelo mesmo professor.
  -- Sem isto, duas transacoes poderiam enxergar a agenda livre ao mesmo tempo.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_teacher_id::text, 0)
  );

  -- Retry do vencedor devolve exatamente o vinculo ja persistido e nao cria
  -- outro appointment nem repete efeitos externos.
  if v_opportunity.winner_teacher_id = p_teacher_id
     and v_opportunity.trial_appointment_id is not null then
    select appointment.*
      into v_existing_appointment
      from public.appointments as appointment
     where appointment.id = v_opportunity.trial_appointment_id
       and appointment.tenant_id = v_opportunity.tenant_id
       and (
         appointment.teacher_id = p_teacher_id
         or appointment.professor_id = p_teacher_id
       );

    if not found then
      return jsonb_build_object('ok', false, 'error', 'opportunity_inconsistent');
    end if;

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'opportunityId', v_opportunity.id,
      'appointmentId', v_existing_appointment.id,
      'tenantId', v_opportunity.tenant_id,
      'kind', v_kind,
      'studentName', v_opportunity.student_name,
      'studentPhone', v_opportunity.student_phone,
      'startTime', v_existing_appointment.start_time,
      'teacherName', coalesce(nullif(trim(v_teacher_name), ''), 'Professor(a)')
    );
  end if;

  if upper(coalesce(v_opportunity.status, '')) <> 'OPEN' then
    return jsonb_build_object(
      'ok', false,
      'error', case
        when v_opportunity.winner_teacher_id is not null
          then 'opportunity_already_claimed'
        else 'opportunity_not_open'
      end
    );
  end if;
  if v_opportunity.winner_teacher_id is not null
     or v_opportunity.professor_id is not null
     or v_opportunity.trial_appointment_id is not null then
    return jsonb_build_object('ok', false, 'error', 'opportunity_inconsistent');
  end if;

  if jsonb_typeof(v_opportunity.slots_proposed) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'invalid_opportunity_slot');
  end if;
  if jsonb_array_length(v_opportunity.slots_proposed) <> 1 then
    return jsonb_build_object('ok', false, 'error', 'invalid_opportunity_slot');
  end if;
  v_slot := v_opportunity.slots_proposed -> 0;
  if coalesce(v_slot ->> 'date', '') !~ '^\d{4}-\d{2}-\d{2}$'
     or coalesce(v_slot ->> 'time', '') !~ '^(?:[01]\d|2[0-3]):[0-5]\d$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_opportunity_slot');
  end if;

  begin
    v_slot_date := (v_slot ->> 'date')::date;
    v_slot_time := (v_slot ->> 'time')::time;
  exception
    when datetime_field_overflow or invalid_datetime_format then
      return jsonb_build_object('ok', false, 'error', 'invalid_opportunity_slot');
  end;

  v_start_time := (v_slot_date + v_slot_time) at time zone 'America/Sao_Paulo';
  if v_start_time <= pg_catalog.now() then
    return jsonb_build_object('ok', false, 'error', 'opportunity_slot_expired');
  end if;
  if v_start_time > pg_catalog.now() + interval '366 days' then
    return jsonb_build_object('ok', false, 'error', 'opportunity_slot_too_far');
  end if;

  if exists (
    select 1
      from public.appointments as appointment
     where appointment.tenant_id = v_opportunity.tenant_id
       and (
         appointment.teacher_id = p_teacher_id
         or appointment.professor_id = p_teacher_id
       )
       and lower(coalesce(appointment.status, '')) in ('scheduled', 'confirmed')
       and appointment.start_time > v_start_time - interval '30 minutes'
       and appointment.start_time < v_start_time + interval '30 minutes'
  ) or exists (
    select 1
      from public.bookings as booking
     where booking.tenant_id = v_opportunity.tenant_id
       and booking.teacher_id = p_teacher_id
       and lower(coalesce(booking.status, 'scheduled')) not in (
         'cancelled', 'canceled', 'inactive'
       )
       and public.dow_name_to_int(booking.day_of_week) =
         extract(dow from v_slot_date)::integer
       and (booking.date is null or booking.date = v_slot_date)
       and case
         when trim(coalesce(booking.time_slot, '')) ~
              '^(?:[01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$'
         then abs(extract(epoch from (
           left(trim(booking.time_slot), 5)::time - v_slot_time
         ))) < 1800
         else false
       end
  ) then
    return jsonb_build_object('ok', false, 'error', 'teacher_schedule_conflict');
  end if;

  insert into public.appointments (
    tenant_id,
    teacher_id,
    professor_id,
    student_name,
    student_phone,
    start_time,
    status,
    type
  ) values (
    v_opportunity.tenant_id,
    p_teacher_id,
    p_teacher_id,
    v_opportunity.student_name,
    v_opportunity.student_phone,
    v_start_time,
    'scheduled',
    case when v_kind = 'TRAINING' then 'training' else 'experimental' end
  )
  returning id into v_appointment_id;

  update public.opportunities
     set status = 'CLAIMED',
         winner_teacher_id = p_teacher_id,
         professor_id = p_teacher_id,
         accepted_slot = v_slot,
         trial_appointment_id = v_appointment_id,
         trial_status = 'SCHEDULED',
         conversion_status = 'OPEN'
   where id = v_opportunity.id
     and upper(coalesce(status, '')) = 'OPEN';

  if not found then
    raise exception 'atomic_opportunity_claim_lost_lock'
      using errcode = '40001';
  end if;

  return jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'opportunityId', v_opportunity.id,
    'appointmentId', v_appointment_id,
    'tenantId', v_opportunity.tenant_id,
    'kind', v_kind,
    'studentName', v_opportunity.student_name,
    'studentPhone', v_opportunity.student_phone,
    'startTime', v_start_time,
    'teacherName', coalesce(nullif(trim(v_teacher_name), ''), 'Professor(a)')
  );
end;
$_$;


--
-- Name: claim_plan_changes_awaiting_billing(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_plan_changes_awaiting_billing(p_tenant_id text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_lease_seconds integer DEFAULT 900) RETURNS TABLE(id uuid, tenant_id text, student_id uuid, student_name text, asaas_subscription_id text, to_monthly_fee numeric, to_frequency text, update_pending_payments boolean, billing_attempts integer, billing_claim_token uuid, billing_lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := greatest(
    1,
    least(coalesce(p_limit, 50), 50)
  );
  v_lease_seconds integer := greatest(
    60,
    least(coalesce(p_lease_seconds, 900), 3600)
  );
  v_tenant_id text := nullif(pg_catalog.btrim(p_tenant_id), '');
begin
  if p_tenant_id is not null and v_tenant_id is null then
    raise exception using
      errcode = '22023',
      message = 'tenant_id_required_when_scoped';
  end if;

  return query
  with candidates as materialized (
    select queued.id
      from public.student_plan_changes as queued
     where queued.billing_sync_status = 'PENDING'
       and queued.status = 'SIGNED'
       and queued.asaas_subscription_id is not null
       and (v_tenant_id is null or queued.tenant_id = v_tenant_id)
       and (
         queued.billing_claim_token is null
         or queued.billing_lease_expires_at <= pg_catalog.clock_timestamp()
       )
       and (
         queued.billing_attempts < 6
         or queued.billing_claim_token is not null
       )
       and not exists (
         select 1
           from public.student_plan_changes as earlier
          where earlier.tenant_id = queued.tenant_id
            and earlier.asaas_subscription_id = queued.asaas_subscription_id
            and earlier.billing_sync_status = 'PENDING'
            and earlier.status = 'SIGNED'
            and (
              coalesce(earlier.signed_at, earlier.created_at),
              earlier.created_at,
              earlier.id
            ) < (
              coalesce(queued.signed_at, queued.created_at),
              queued.created_at,
              queued.id
            )
       )
       and not exists (
         select 1
           from public.asaas_subscription_mutation_operations as operation
          where operation.tenant_id = queued.tenant_id
            and operation.subscription_id = queued.asaas_subscription_id
            and operation.status in (
              'CLAIMED', 'SUBMITTING', 'UNKNOWN', 'BLOCKED'
            )
            and operation.intent_key <> 'plan-change:' || queued.id::text
       )
     order by queued.signed_at nulls last, queued.created_at, queued.id
     limit v_limit
     for update of queued skip locked
  ), claimed as (
    update public.student_plan_changes as queued
       set billing_claim_token = pg_catalog.gen_random_uuid(),
           billing_lease_expires_at = pg_catalog.clock_timestamp()
             + pg_catalog.make_interval(secs => v_lease_seconds),
           billing_claimed_at = pg_catalog.clock_timestamp(),
           billing_attempts = least(
             queued.billing_attempts + 1,
             6
           )
      from candidates
     where queued.id = candidates.id
    returning
      queued.id,
      queued.tenant_id,
      queued.student_id,
      queued.asaas_subscription_id,
      queued.to_monthly_fee,
      queued.to_frequency,
      queued.update_pending_payments,
      queued.billing_attempts,
      queued.billing_claim_token,
      queued.billing_lease_expires_at
  )
  select
    claimed.id,
    claimed.tenant_id,
    claimed.student_id,
    student.full_name,
    claimed.asaas_subscription_id,
    claimed.to_monthly_fee,
    claimed.to_frequency,
    claimed.update_pending_payments,
    claimed.billing_attempts,
    claimed.billing_claim_token,
    claimed.billing_lease_expires_at
  from claimed
  join public.profiles as student
    on student.id = claimed.student_id
  order by claimed.id;
end;
$$;


--
-- Name: claim_public_intake_quota(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_public_intake_quota(p_intake_kind text, p_client_hash text, p_request_limit integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'private', 'pg_temp'
    AS $_$
declare
  current_window timestamptz := date_trunc('hour', clock_timestamp());
  updated_count integer;
begin
  if p_intake_kind not in ('resume_upload')
    or p_client_hash !~ '^[0-9a-f]{64}$'
    or p_request_limit not between 1 and 20
  then
    return false;
  end if;

  insert into private.public_intake_rate_limits (
    intake_kind,
    client_hash,
    window_started_at,
    request_count
  )
  values (p_intake_kind, p_client_hash, current_window, 1)
  on conflict (intake_kind, client_hash, window_started_at)
  do update set request_count = private.public_intake_rate_limits.request_count + 1
  returning request_count into updated_count;

  delete from private.public_intake_rate_limits
  where window_started_at < clock_timestamp() - interval '48 hours';

  return updated_count <= p_request_limit;
end;
$_$;


--
-- Name: claim_rejection_email(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_rejection_email(p_student_id uuid, p_reason text, p_reason_hash text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_profile public.profiles%rowtype;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception
      using errcode = '42501', message = 'Service role required';
  end if;
  if p_reason_hash !~ '^[0-9a-f]{64}$' then
    raise exception
      using errcode = '22023', message = 'Invalid rejection reason hash';
  end if;

  select p.*
    into v_profile
    from public.profiles as p
   where p.id = p_student_id
     and p.role = 'STUDENT'
   for update;

  if not found
     or v_profile.documentation_status is distinct from 'REJECTED'
     or btrim(coalesce(v_profile.rejection_reason, ''))
       is distinct from btrim(coalesce(p_reason, '')) then
    raise exception
      using errcode = '55000', message = 'Rejection state changed';
  end if;

  if v_profile.rejection_email_reason_hash = p_reason_hash
     and v_profile.rejection_email_sent_at is not null then
    return 'already_sent';
  end if;

  if v_profile.rejection_email_reason_hash = p_reason_hash
     and v_profile.rejection_email_claimed_at
       > now() - interval '10 minutes' then
    return 'in_progress';
  end if;

  update public.profiles as p
     set rejection_email_reason_hash = p_reason_hash,
         rejection_email_claimed_at = now(),
         rejection_email_sent_at = null
   where p.id = p_student_id;

  return 'claimed';
end;
$_$;


--
-- Name: claim_saas_owner_activation(uuid, text, text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_saas_owner_activation(p_checkout_id uuid, p_tenant_id text, p_owner_email text, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  checkout_row public.saas_checkout_intents%rowtype;
  attempt_row public.saas_owner_activation_attempts%rowtype;
  other_attempt public.saas_owner_activation_attempts%rowtype;
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  normalized_email text := lower(nullif(pg_catalog.btrim(coalesce(p_owner_email, '')), ''));
  calculated_payload_hash text;
  safe_lease integer := greatest(
    60,
    least(coalesce(p_lease_seconds, 300), 600)
  );
begin
  if p_checkout_id is null or normalized_tenant is null
     or normalized_email is null or length(normalized_email) > 320
     or p_claim_token is null
  then
    raise exception using
      errcode = '22023', message = 'invalid_saas_owner_activation_claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-activation-email:' || normalized_email,
      0
    )
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-activation:' || p_checkout_id::text,
      0
    )
  );

  select checkout.* into checkout_row
    from public.saas_checkout_intents as checkout
   where checkout.id = p_checkout_id
   for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'saas_checkout_not_found';
  end if;
  if checkout_row.tenant_id is distinct from normalized_tenant
     or lower(pg_catalog.btrim(checkout_row.owner_email)) is distinct from normalized_email
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_owner_activation_binding_mismatch'
    );
  end if;
  if checkout_row.status not in (
    'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED'
  ) then
    select attempt.* into attempt_row
      from public.saas_owner_activation_attempts as attempt
     where attempt.checkout_id = p_checkout_id
     for update;
    if not found then
      insert into public.saas_owner_activation_attempts (
        checkout_id,
        tenant_id,
        owner_email,
        status,
        claim_token,
        lease_expires_at,
        completed_at,
        last_error
      ) values (
        p_checkout_id,
        normalized_tenant,
        normalized_email,
        'SUPPRESSED',
        p_claim_token,
        pg_catalog.now(),
        pg_catalog.now(),
        'saas_checkout_not_eligible_for_activation'
      )
      returning * into attempt_row;
    elsif attempt_row.status = 'CLAIMED'
       and attempt_row.submit_attempt_count = 0
    then
      update public.saas_owner_activation_attempts
         set status = 'SUPPRESSED',
             provider_payload = null,
             provider_payload_sha256 = null,
             provider_payload_staged_at = null,
             lease_expires_at = pg_catalog.now(),
             completed_at = pg_catalog.now(),
             last_error = 'saas_checkout_not_eligible_for_activation',
             updated_at = pg_catalog.now()
       where checkout_id = p_checkout_id
       returning * into attempt_row;
    elsif attempt_row.status = 'CLAIMED' then
      -- A previous provider attempt is already ambiguous. Cancellation may
      -- stop a new retry before mark, but it must never erase that evidence.
      update public.saas_owner_activation_attempts
         set status = 'UNKNOWN',
             lease_expires_at = pg_catalog.now(),
             completed_at = null,
             last_error = 'checkout_ineligible_after_ambiguous_delivery',
             updated_at = pg_catalog.now()
       where checkout_id = p_checkout_id
       returning * into attempt_row;
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_FINAL',
      'status', attempt_row.status,
      'checkout_id', p_checkout_id,
      'reason', 'saas_checkout_not_eligible_for_activation'
    );
  end if;

  -- Recovery tokens belong to the auth user/email, not to a checkout. Only
  -- one checkout may own activation delivery for an email at a time; a later
  -- paid checkout reuses the existing account and never invalidates its link.
  for other_attempt in
    select attempt.*
      from public.saas_owner_activation_attempts as attempt
      join public.saas_checkout_intents as other_checkout
        on other_checkout.id = attempt.checkout_id
     where attempt.owner_email = normalized_email
       and attempt.checkout_id <> p_checkout_id
       and attempt.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN')
       and other_checkout.status in ('PROVISIONING', 'PROVISIONING_FAILED')
     order by attempt.created_at, attempt.checkout_id
     for update of attempt, other_checkout
  loop
    -- Never terminalize another checkout from this claim. Its own durable
    -- inbox must resume it and atomically finish its checkout. Mutating it
    -- here could strand that checkout in PROVISIONING forever.
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'status', other_attempt.status,
      'checkout_id', p_checkout_id,
      'owner_activation_checkout_id', other_attempt.checkout_id
    );
  end loop;

  insert into public.saas_owner_activation_attempts (
    checkout_id,
    tenant_id,
    owner_email,
    claim_token,
    lease_expires_at
  ) values (
    p_checkout_id,
    normalized_tenant,
    normalized_email,
    p_claim_token,
    pg_catalog.now() + pg_catalog.make_interval(secs => safe_lease)
  ) on conflict (checkout_id) do nothing;

  select attempt.* into attempt_row
    from public.saas_owner_activation_attempts as attempt
   where attempt.checkout_id = p_checkout_id
   for update;

  if attempt_row.tenant_id is distinct from normalized_tenant
     or attempt_row.owner_email is distinct from normalized_email
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_owner_activation_attempt_mismatch'
    );
  end if;

  if attempt_row.status = 'SUPPRESSED'
     and attempt_row.submit_attempt_count = 0
     and attempt_row.provider_payload is null
     and attempt_row.last_error in (
       'saas_owner_identity_not_ready_before_activation',
       'saas_owner_access_not_ready_before_activation'
     )
  then
    perform 1
      from public.tenants as tenant
     where tenant.id = attempt_row.tenant_id
       and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) = 'active'
     for update;
    if found then
      update public.saas_owner_activation_attempts
         set status = 'CLAIMED',
             owner_user_id = null,
             claim_token = p_claim_token,
             lease_expires_at = pg_catalog.now()
               + pg_catalog.make_interval(secs => safe_lease),
             completed_at = null,
             last_error = null,
             updated_at = pg_catalog.now()
       where checkout_id = p_checkout_id
       returning * into attempt_row;
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'SUBMIT_ONCE',
        'status', 'CLAIMED',
        'checkout_id', attempt_row.checkout_id,
        'claim_token', attempt_row.claim_token
      );
    end if;
  end if;

  if attempt_row.status in ('SENT', 'FAILED', 'SUPPRESSED') then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_FINAL',
      'status', attempt_row.status,
      'checkout_id', attempt_row.checkout_id
    );
  end if;

  -- The recovery link belongs to the deleted auth identity. Once a provider
  -- boundary was crossed it must never be replayed against a replacement
  -- UUID; terminalize visibly, clear the unusable bearer, and let the access
  -- repair path bind a new confirmed identity without another automatic send.
  if attempt_row.submit_attempt_count > 0
     and attempt_row.owner_user_id is null
  then
    update public.saas_owner_activation_attempts
       set status = 'FAILED',
           owner_identity_marker_checkout_id = null,
           provider_payload = null,
           provider_payload_sha256 = null,
           provider_payload_staged_at = null,
           lease_expires_at = pg_catalog.now(),
           completed_at = pg_catalog.now(),
           last_error = 'activation_owner_identity_removed_after_submit',
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id
     returning * into attempt_row;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_FINAL',
      'status', 'FAILED',
      'checkout_id', attempt_row.checkout_id,
      'reason', 'activation_owner_identity_removed_after_submit'
    );
  end if;

  -- generateLink mutates GoTrue before the exact provider payload can be
  -- staged. Never hand an expired, payload-less first-generation claim to a
  -- second worker: it could generate a newer token and let the stale worker
  -- invalidate it. Expire to a visible/manual failure instead; the public
  -- self-service recovery flow remains available.
  if attempt_row.status = 'CLAIMED'
     and attempt_row.submit_attempt_count = 0
     and attempt_row.provider_payload is null
     and attempt_row.claim_token is distinct from p_claim_token
     and attempt_row.lease_expires_at <= pg_catalog.now()
  then
    update public.saas_owner_activation_attempts
       set status = 'FAILED',
           lease_expires_at = pg_catalog.now(),
           completed_at = pg_catalog.now(),
           last_error = 'activation_generation_claim_expired',
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id
     returning * into attempt_row;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_FINAL',
      'status', 'FAILED',
      'checkout_id', attempt_row.checkout_id,
      'reason', 'activation_generation_claim_expired'
    );
  end if;

  if attempt_row.provider_payload is not null then
    calculated_payload_hash := pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(attempt_row.provider_payload, 'UTF8'),
        'sha256'
      ),
      'hex'
    );
  end if;
  if (attempt_row.submit_attempt_count > 0
        and attempt_row.provider_payload is null)
     or attempt_row.provider_payload_sha256 is distinct from
       calculated_payload_hash
  then
    if attempt_row.status = 'CLAIMED'
       and attempt_row.submit_attempt_count = 0
    then
      update public.saas_owner_activation_attempts
         set status = 'SUPPRESSED',
             provider_payload = null,
             provider_payload_sha256 = null,
             provider_payload_staged_at = null,
             lease_expires_at = pg_catalog.now(),
             completed_at = pg_catalog.now(),
             last_error = 'activation_staged_payload_invalid_before_submit',
             updated_at = pg_catalog.now()
       where checkout_id = p_checkout_id;
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'ALREADY_FINAL',
        'status', 'SUPPRESSED',
        'checkout_id', p_checkout_id,
        'reason', 'activation_staged_payload_invalid_before_submit'
      );
    end if;

    update public.saas_owner_activation_attempts
       set status = case
             when status = 'CLAIMED' then 'UNKNOWN'
             else status
           end,
           lease_expires_at = pg_catalog.now(),
           completed_at = null,
           last_error = 'activation_staged_payload_invalid_after_submit',
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'status', case
        when attempt_row.status = 'CLAIMED' then 'UNKNOWN'
        else attempt_row.status
      end,
      'checkout_id', p_checkout_id,
      'reason', 'activation_staged_payload_invalid_after_submit'
    );
  end if;

  -- A profile deleted after staging clears the FK with ON DELETE SET NULL.
  -- Since submit_attempt_count=0 proves the provider boundary was never
  -- crossed, discard that unsent link and generate a new one for the eventual
  -- replacement identity.
  if attempt_row.status = 'CLAIMED'
     and attempt_row.submit_attempt_count = 0
     and attempt_row.provider_payload is not null
     and attempt_row.owner_user_id is null
  then
    update public.saas_owner_activation_attempts
       set provider_payload = null,
           provider_payload_sha256 = null,
           provider_payload_staged_at = null,
           owner_identity_marker_checkout_id = null,
           last_error = 'activation_staged_identity_removed_before_submit',
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id
     returning * into attempt_row;
  end if;

  -- A staged recovery token has a shorter validity window than the provider
  -- idempotency record. Before SUBMITTING it is provably unsent, so an expired
  -- staged payload can be cleared and regenerated safely.
  if attempt_row.status = 'CLAIMED'
     and attempt_row.submit_attempt_count = 0
     and attempt_row.provider_payload is not null
     and attempt_row.provider_payload_staged_at
       <= pg_catalog.now() - interval '50 minutes'
  then
    update public.saas_owner_activation_attempts
       set owner_user_id = null,
           owner_identity_marker_checkout_id = null,
           provider_payload = null,
           provider_payload_sha256 = null,
           provider_payload_staged_at = null,
           last_error = 'activation_staged_payload_expired_before_submit',
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id
     returning * into attempt_row;
  end if;

  if attempt_row.status = 'SUBMITTING'
     and attempt_row.lease_expires_at > pg_catalog.now()
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'status', attempt_row.status,
      'checkout_id', attempt_row.checkout_id
    );
  end if;

  if attempt_row.status in ('SUBMITTING', 'UNKNOWN') then
    if attempt_row.submitted_at is null
       or attempt_row.submitted_at
          <= pg_catalog.now() - interval '50 minutes'
       or attempt_row.submit_attempt_count >= 5
    then
      update public.saas_owner_activation_attempts
         set status = 'FAILED',
             provider_payload = null,
             provider_payload_sha256 = null,
             provider_payload_staged_at = null,
             lease_expires_at = pg_catalog.now(),
             completed_at = pg_catalog.now(),
             last_error = 'activation_retry_window_closed',
             updated_at = pg_catalog.now()
       where checkout_id = p_checkout_id
       returning * into attempt_row;
      return pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'ALREADY_FINAL',
        'status', 'FAILED',
        'checkout_id', attempt_row.checkout_id,
        'reason', 'activation_idempotency_window_closed'
      );
    end if;

    update public.saas_owner_activation_attempts
       set status = 'CLAIMED',
           claim_token = p_claim_token,
           lease_expires_at = pg_catalog.now()
             + pg_catalog.make_interval(secs => safe_lease),
           completed_at = null,
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id
     returning * into attempt_row;

    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'RESUME_IDEMPOTENT',
      'status', attempt_row.status,
      'checkout_id', attempt_row.checkout_id,
      'claim_token', attempt_row.claim_token,
      'provider_payload', attempt_row.provider_payload
    );
  end if;

  if attempt_row.claim_token is distinct from p_claim_token
     and attempt_row.lease_expires_at > pg_catalog.now()
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'status', attempt_row.status,
      'checkout_id', attempt_row.checkout_id
    );
  end if;

  update public.saas_owner_activation_attempts
     set claim_token = p_claim_token,
         lease_expires_at = pg_catalog.now()
           + pg_catalog.make_interval(secs => safe_lease),
         last_error = null,
         updated_at = pg_catalog.now()
   where checkout_id = p_checkout_id
   returning * into attempt_row;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', case
      when attempt_row.submit_attempt_count = 0
        and attempt_row.provider_payload is null then 'SUBMIT_ONCE'
      else 'RESUME_IDEMPOTENT'
    end,
    'status', attempt_row.status,
    'checkout_id', attempt_row.checkout_id,
    'claim_token', attempt_row.claim_token,
    'provider_payload', attempt_row.provider_payload
  );
end;
$$;


--
-- Name: claim_sdr_notice(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_sdr_notice(p_tenant_id text, p_phone text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.sdr_conversation_work%rowtype; token uuid:=gen_random_uuid();
begin
  insert into public.sdr_conversation_work(tenant_id,phone,payload,latest_msg_id,completed_msg_id)
  values(p_tenant_id,p_phone,'{}'::jsonb,'','') on conflict(tenant_id,phone) do nothing;
  select * into w from public.sdr_conversation_work where tenant_id=p_tenant_id and phone=p_phone for update;
  if w.phase<>'IDLE' or w.latest_msg_id is distinct from w.completed_msg_id then
    return jsonb_build_object('claimed',false);
  end if;
  update public.sdr_conversation_work set phase='APPLYING',lease_token=token,
    claimed_msg_id=latest_msg_id,lease_until=now()+interval '10 minutes',updated_at=now()
    where tenant_id=p_tenant_id and phone=p_phone;
  return jsonb_build_object('claimed',true,'token',token);
end; $$;


--
-- Name: claim_sdr_work(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_sdr_work(p_tenant_id text, p_phone text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.sdr_conversation_work%rowtype; token uuid := gen_random_uuid();
begin
  select * into w from public.sdr_conversation_work where tenant_id=p_tenant_id and phone=p_phone for update;
  if not found or w.phase='REVIEW' or (w.latest_msg_id is not distinct from w.completed_msg_id and w.phase<>'APPLYING')
    or w.available_at>now() or w.lease_until>now() then return jsonb_build_object('claimed',false); end if;
  if w.phase='APPLYING' or w.attempts>=3 then
    update public.sdr_conversation_work set phase='REVIEW',updated_at=now() where tenant_id=p_tenant_id and phone=p_phone;
    update public.crm_leads set ai_handoff=true,ai_handoff_at=now()
      where tenant_id=p_tenant_id and regexp_replace(phone,'[^0-9]','','g')=p_phone;
    return jsonb_build_object('claimed',false,'review',true);
  end if;
  update public.sdr_conversation_work set phase='GENERATING',lease_token=token,attempts=attempts+1,
    lease_until=now()+interval '3 minutes',claimed_msg_id=latest_msg_id,updated_at=now()
    where tenant_id=p_tenant_id and phone=p_phone;
  return jsonb_build_object('claimed',true,'token',token,'payload',w.payload);
end;
$$;


--
-- Name: claim_student_opportunity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_student_opportunity(p_opp_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text; v_tenant text; v_lifecycle text; v_my_name text;
  v_opp record; v_moved int;
  v_adm record;
BEGIN
  SELECT role, tenant_id, COALESCE(lifecycle_status,'active'), full_name
    INTO v_role, v_tenant, v_lifecycle, v_my_name FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('TEACHER','teacher') THEN RAISE EXCEPTION 'Apenas professores aceitam alunos do mural'; END IF;
  IF v_lifecycle <> 'active' THEN RAISE EXCEPTION 'Perfil inativo'; END IF;

  -- claim atômico
  UPDATE student_opportunities
     SET status = 'CLAIMED', claimed_by = auth.uid(), claimed_at = now()
   WHERE id = p_opp_id AND status = 'OPEN' AND tenant_id = v_tenant
     AND from_teacher_id IS DISTINCT FROM auth.uid()
  RETURNING * INTO v_opp;
  IF v_opp.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Essa oportunidade já foi aceita por outro professor.');
  END IF;

  -- transfere o aluno (espelha reassign_student_teacher)
  UPDATE bookings SET teacher_id = auth.uid()
   WHERE student_id = v_opp.student_id AND tenant_id = v_tenant AND teacher_id = v_opp.from_teacher_id;
  GET DIAGNOSTICS v_moved = ROW_COUNT;
  UPDATE profiles SET professor_id = auth.uid()
   WHERE id = v_opp.student_id AND (professor_id = v_opp.from_teacher_id OR professor_id IS NULL);
  UPDATE profiles SET professor_id2 = auth.uid()
   WHERE id = v_opp.student_id AND professor_id2 = v_opp.from_teacher_id;

  -- avisa o diretor pela central
  FOR v_adm IN
    SELECT full_name, phone FROM profiles
    WHERE tenant_id = v_tenant AND role IN ('SCHOOL_ADMIN','SUPER_ADMIN') AND COALESCE(phone,'') <> '' LIMIT 1
  LOOP
    INSERT INTO notification_queue
      (tenant_id, teacher_id, student_id, student_name, student_phone, message_body,
       scheduled_for, status, source_id, source_type, notification_kind)
    VALUES
      (v_tenant, NULL, v_opp.student_id, v_adm.full_name, v_adm.phone,
       '✅ Mural de realocação: *' || v_my_name || '* aceitou o aluno *' || COALESCE(v_opp.student_name,'?') ||
       '* (' || COALESCE(v_opp.schedule,'') || '), que era do professor ' || COALESCE(v_opp.from_teacher_name,'?') ||
       '. Bookings transferidos: ' || v_moved || '.',
       now(), 'pending', v_opp.id, 'reallocation', 'REALLOCATION_CLAIMED');
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'student_name', v_opp.student_name, 'bookings_transferidos', v_moved);
END; $$;


--
-- Name: claim_student_overdue_card_charge(text, uuid, text, text, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_student_overdue_card_charge(p_tenant_id text, p_student_id uuid, p_subscription_id text, p_payment_id text, p_requested_by uuid, p_claim_token uuid, p_lease_seconds integer DEFAULT 300) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  claim_row public.student_overdue_card_charge_claims%rowtype;
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  normalized_subscription text := nullif(trim(coalesce(p_subscription_id, '')), '');
  normalized_payment text := nullif(trim(coalesce(p_payment_id, '')), '');
  safe_lease integer := greatest(60, least(coalesce(p_lease_seconds, 300), 600));
  retry_after integer;
  lifecycle_operation_active boolean := false;
begin
  if normalized_tenant is null
     or p_student_id is null
     or normalized_subscription is null
     or normalized_payment is null
     or p_claim_token is null
  then
    raise exception using errcode = '22023', message = 'invalid_overdue_charge_claim';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' || p_student_id::text,
      0
    )
  );
  if not exists (
    select 1 from public.profiles as profile
     where profile.id = p_student_id
       and profile.tenant_id = normalized_tenant
       and profile.role = 'STUDENT'
       and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
  ) or (
    select count(*) from public.tenant_memberships as membership
     where membership.user_id = p_student_id
  ) <> 1 or not exists (
    select 1 from public.tenant_memberships as membership
     where membership.user_id = p_student_id
       and membership.tenant_id = normalized_tenant
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    return jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'student_lifecycle_inactive'
    );
  end if;

  -- These tables are created later in this same migration. Dynamic lookup
  -- keeps migration parsing ordered while still enforcing the final runtime
  -- contract under the same advisory lock.
  if pg_catalog.to_regclass('public.student_offboarding_operations') is not null then
    execute $sql$
      select exists (
        select 1 from public.student_offboarding_operations
         where tenant_id = $1 and student_id = $2
           and status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
      )
    $sql$ into lifecycle_operation_active using normalized_tenant, p_student_id;
  end if;
  if not lifecycle_operation_active
     and pg_catalog.to_regclass('public.student_account_deletion_claims') is not null
  then
    execute $sql$
      select exists (
        select 1 from public.student_account_deletion_claims
         where tenant_id = $1 and student_id = $2
           and status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
      )
    $sql$ into lifecycle_operation_active using normalized_tenant, p_student_id;
  end if;
  if not lifecycle_operation_active
     and pg_catalog.to_regclass('public.student_billing_method_operations') is not null
  then
    execute $sql$
      select exists (
        select 1 from public.student_billing_method_operations
         where tenant_id = $1 and student_id = $2
           and status in ('CLAIMED', 'MUTATING', 'UNKNOWN', 'BLOCKED')
      )
    $sql$ into lifecycle_operation_active using normalized_tenant, p_student_id;
  end if;
  if lifecycle_operation_active then
    return jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'lifecycle_operation_active'
    );
  end if;

  insert into public.student_overdue_card_charge_claims (
    tenant_id,
    student_id,
    asaas_subscription_id,
    asaas_payment_id,
    status,
    requested_by,
    claim_token,
    lease_expires_at,
    processing_started_at,
    updated_at
  ) values (
    normalized_tenant,
    p_student_id,
    normalized_subscription,
    normalized_payment,
    'PROCESSING',
    p_requested_by,
    p_claim_token,
    now() + make_interval(secs => safe_lease),
    now(),
    now()
  ) on conflict (asaas_payment_id) do nothing;

  select charge.*
    into claim_row
    from public.student_overdue_card_charge_claims as charge
   where charge.asaas_payment_id = normalized_payment
   for update;

  if claim_row.tenant_id is distinct from normalized_tenant
     or claim_row.student_id is distinct from p_student_id
     or claim_row.asaas_subscription_id is distinct from normalized_subscription
  then
    if claim_row.status <> 'SUCCEEDED' then
      update public.student_overdue_card_charge_claims
         set status = 'BLOCKED',
             last_error = 'overdue_charge_binding_mismatch',
             lease_expires_at = now(),
             updated_at = now()
       where id = claim_row.id;
    end if;
    return jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'binding_mismatch',
      'claim_id', claim_row.id
    );
  end if;

  if claim_row.status = 'SUCCEEDED' then
    return jsonb_build_object(
      'ok', true,
      'action', 'COMPLETED',
      'claim_id', claim_row.id,
      'provider_status', claim_row.provider_status
    );
  end if;

  -- Once submission starts, no lease expiry can authorize another POST. The
  -- only safe next action is provider GET/manual reconciliation.
  if claim_row.status in ('SUBMITTING', 'UNKNOWN', 'BLOCKED') then
    return jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'provider_outcome_requires_reconciliation',
      'claim_id', claim_row.id,
      'status', claim_row.status
    );
  end if;

  if claim_row.status = 'PROCESSING'
     and claim_row.claim_token <> p_claim_token
     and claim_row.lease_expires_at > now()
  then
    retry_after := greatest(
      1,
      ceil(extract(epoch from (claim_row.lease_expires_at - now())))::integer
    );
    return jsonb_build_object(
      'ok', true,
      'action', 'IN_PROGRESS',
      'claim_id', claim_row.id,
      'retry_after_seconds', retry_after
    );
  end if;

  -- PROCESSING has not crossed the submit fence. DECLINED is a proven
  -- deterministic rejection, so a new card may safely start a new attempt.
  update public.student_overdue_card_charge_claims
     set status = 'PROCESSING',
         attempt_count = case
           when claim_token = p_claim_token and status = 'PROCESSING'
             then attempt_count
           else attempt_count + 1
         end,
         requested_by = p_requested_by,
         claim_token = p_claim_token,
         lease_expires_at = now() + make_interval(secs => safe_lease),
         processing_started_at = now(),
         provider_status = null,
         provider_http_status = null,
         last_error = null,
         submitted_at = null,
         completed_at = null,
         updated_at = now()
   where id = claim_row.id
   returning * into claim_row;

  return jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_ONCE',
    'claim_id', claim_row.id,
    'claim_token', claim_row.claim_token
  );
end;
$_$;


--
-- Name: claim_whatsapp_outbound(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_whatsapp_outbound(p_tenant_id text, p_message_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_message public.whatsapp_messages%rowtype;
  v_conversation public.whatsapp_conversations%rowtype;
  v_instance public.whatsapp_instances%rowtype;
begin
  if p_message_id is null
     or not private.whatsapp_inbox_actor_has_role(
       p_actor_id,
       p_tenant_id,
       array['SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR']::text[]
     ) then
    raise exception 'whatsapp_outbound_claim_forbidden'
      using errcode = '42501';
  end if;

  select message.*
  into v_message
  from public.whatsapp_messages as message
  where message.id = p_message_id
    and message.tenant_id = p_tenant_id
    and message.direction = 'out'
    and message.sent_by_user_id = p_actor_id
  for update;

  if not found then
    raise exception 'whatsapp_outbound_not_found' using errcode = 'P0002';
  end if;

  select conversation.*
  into strict v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = v_message.conversation_id
    and conversation.tenant_id = p_tenant_id;

  select instance.*
  into strict v_instance
  from public.whatsapp_instances as instance
  where instance.id = v_message.instance_id
    and instance.tenant_id = p_tenant_id;

  if not private.whatsapp_inbox_instance_is_eligible(
    p_tenant_id,
    v_instance.id
  ) then
    return jsonb_build_object(
      'ok', true,
      'claimed', false,
      'messageId', v_message.id,
      'status', v_message.status,
      'error', 'inbox_unavailable'
    );
  end if;

  if not private.whatsapp_inbox_remote_jid_is_allowed(
    p_tenant_id,
    v_conversation.remote_jid
  ) then
    return jsonb_build_object(
      'ok', true,
      'claimed', false,
      'messageId', v_message.id,
      'status', v_message.status,
      'error', 'destination_unavailable'
    );
  end if;

  if v_message.status = 'dispatching' then
    if v_message.lease_until <= pg_catalog.now() then
      -- Não há idempotency-key garantida pelo provedor. Depois que um envio
      -- começou, lease vencida significa resultado ambíguo, nunca retry cego.
      update public.whatsapp_messages as message
      set status = 'uncertain',
          lease_until = null,
          error_code = 'dispatch_lease_expired'
      where message.id = v_message.id
      returning message.* into v_message;
    end if;

    return jsonb_build_object(
      'ok', true,
      'claimed', false,
      'messageId', v_message.id,
      'status', v_message.status,
      'leaseUntil', v_message.lease_until
    );
  end if;

  if v_message.status <> 'queued'
     or v_message.next_attempt_at > pg_catalog.now() then
    return jsonb_build_object(
      'ok', true,
      'claimed', false,
      'messageId', v_message.id,
      'status', v_message.status,
      'error', null
    );
  end if;

  update public.whatsapp_messages as message
  set status = 'dispatching',
      attempt_count = message.attempt_count + 1,
      lease_until = pg_catalog.now() + interval '2 minutes',
      dispatch_started_at = coalesce(
        message.dispatch_started_at,
        pg_catalog.now()
      ),
      error_code = null
  where message.id = v_message.id
    and message.status = 'queued'
  returning message.* into v_message;

  return jsonb_build_object(
    'ok', true,
    'claimed', true,
    'messageId', v_message.id,
    'conversationId', v_message.conversation_id,
    'instanceId', v_instance.id,
    'instanceName', v_instance.instance_name,
    'remoteJid', v_conversation.remote_jid,
    'body', v_message.body,
    'status', v_message.status,
    'attemptCount', v_message.attempt_count,
    'leaseUntil', v_message.lease_until
  );
end;
$$;


--
-- Name: claim_with_token(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_with_token(p_opp_id uuid, p_teacher_id uuid, p_token_hash text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_claim_result JSONB;
    v_consumed BOOLEAN := false;
BEGIN
    -- 1. If token hash provided, check consumed_tokens
    IF p_token_hash IS NOT NULL THEN
        -- Check if this token was already used
        SELECT EXISTS (
            SELECT 1 FROM public.consumed_tokens
            WHERE token_hash = p_token_hash
        ) INTO v_consumed;

        IF v_consumed THEN
            -- Log token reuse attempt
            INSERT INTO public.security_events (
                event_type, severity, actor_id, source, details
            ) VALUES (
                'TOKEN_REUSE', 'MEDIUM', p_teacher_id, 'SYSTEM',
                jsonb_build_object('entity_type', 'opportunity', 'entity_id', p_opp_id::text, 'token_hash_prefix', left(p_token_hash, 8))
            );

            RETURN jsonb_build_object(
                'success', false,
                'error', 'TOKEN_ALREADY_CONSUMED',
                'message', 'Este link já foi utilizado.'
            );
        END IF;
    END IF;

    -- 2. Execute the atomic claim
    SELECT public.claim_opportunity(p_opp_id, p_teacher_id) INTO v_claim_result;

    -- 3. If claim succeeded and token hash provided, consume the token
    IF (v_claim_result->>'success')::boolean AND p_token_hash IS NOT NULL THEN
        INSERT INTO public.consumed_tokens (token_hash, consumed_by, metadata)
        VALUES (p_token_hash, p_teacher_id, jsonb_build_object(
            'opportunity_id', p_opp_id,
            'consumed_at', now()
        ))
        ON CONFLICT (token_hash) DO NOTHING;
    END IF;

    RETURN v_claim_result;
END;
$$;


--
-- Name: claim_wolfie_ai_request(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_wolfie_ai_request(p_student_id uuid, p_request_key uuid, p_operation text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.claim_wolfie_ai_request(
    private.active_tenant_id(p_student_id),
    p_student_id,
    p_request_key,
    p_operation
  );
$$;


--
-- Name: claim_wolfie_ai_request(text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_wolfie_ai_request(p_tenant_id text, p_student_id uuid, p_request_key uuid, p_operation text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_test_fixture boolean;
  v_request public.wolfie_ai_requests%rowtype;
  v_has_request boolean := false;
  v_lease_token uuid;
  v_rate_cap integer;
  v_recent_attempts integer;
begin
  if p_tenant_id is null
     or pg_catalog.btrim(p_tenant_id) = ''
     or p_student_id is null
     or p_request_key is null then
    raise exception 'invalid_ai_request_identity';
  end if;
  if p_operation is null
     or p_operation not in ('GENERATE', 'EVALUATE', 'SPEECH') then
    raise exception 'invalid_ai_operation';
  end if;

  select coalesce(profile.is_test_account, false)
    into v_profile_test_fixture
    from public.profiles as profile
    join public.tenant_memberships as membership
      on membership.user_id = profile.id
     and membership.tenant_id = p_tenant_id
     and membership.status = 'ACTIVE'
     and membership.role = 'STUDENT'
   where profile.id = p_student_id
     and profile.role = 'STUDENT'
   for update of profile;

  if not found then
    raise exception 'student_active_tenant_membership_not_found';
  end if;

  select *
    into v_request
    from public.wolfie_ai_requests as request
   where request.tenant_id = p_tenant_id
     and request.student_id = p_student_id
     and request.request_key = p_request_key
   for update;
  v_has_request := found;

  if v_has_request and v_request.operation <> p_operation then
    raise exception 'ai_request_key_reused_for_another_operation';
  end if;

  if v_profile_test_fixture then
    if v_has_request then
      update public.wolfie_ai_requests
         set status = 'COMPLETED',
             response_payload = '{"skipped":"test_fixture"}'::jsonb,
             error_code = null,
             test_fixture = true,
             lease_expires_at = pg_catalog.now(),
             completed_at = pg_catalog.now(),
             updated_at = pg_catalog.now()
       where id = v_request.id
       returning * into v_request;
    else
      insert into public.wolfie_ai_requests (
        tenant_id,
        student_id,
        request_key,
        operation,
        status,
        attempt_count,
        response_payload,
        test_fixture,
        completed_at
      ) values (
        p_tenant_id,
        p_student_id,
        p_request_key,
        p_operation,
        'COMPLETED',
        0,
        '{"skipped":"test_fixture"}'::jsonb,
        true,
        pg_catalog.now()
      )
      returning * into v_request;
    end if;

    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'status', v_request.status,
      'tenantId', v_request.tenant_id,
      'requestKey', v_request.request_key,
      'operation', v_request.operation,
      'attemptCount', v_request.attempt_count,
      'leaseToken', null,
      'leaseExpiresAt', v_request.lease_expires_at,
      'responsePayload', v_request.response_payload,
      'testFixture', true
    );
  end if;

  if v_has_request and v_request.status = 'COMPLETED' then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'status', v_request.status,
      'tenantId', v_request.tenant_id,
      'requestKey', v_request.request_key,
      'operation', v_request.operation,
      'attemptCount', v_request.attempt_count,
      'leaseToken', null,
      'leaseExpiresAt', v_request.lease_expires_at,
      'responsePayload', v_request.response_payload,
      'errorCode', v_request.error_code,
      'testFixture', v_request.test_fixture
    );
  end if;

  if v_has_request
     and v_request.status = 'PROCESSING'
     and v_request.lease_expires_at > pg_catalog.now() then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'status', v_request.status,
      'tenantId', v_request.tenant_id,
      'requestKey', v_request.request_key,
      'operation', v_request.operation,
      'attemptCount', v_request.attempt_count,
      'leaseToken', null,
      'leaseExpiresAt', v_request.lease_expires_at,
      'responsePayload', '{}'::jsonb,
      'errorCode', null,
      'testFixture', false
    );
  end if;

  if v_has_request and v_request.attempt_count >= 3 then
    if v_request.status = 'PROCESSING' then
      update public.wolfie_ai_requests
         set status = 'FAILED',
             error_code = 'AI_RETRY_LIMIT_EXCEEDED',
             completed_at = pg_catalog.now(),
             updated_at = pg_catalog.now()
       where id = v_request.id
       returning * into v_request;
    end if;

    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'status', 'FAILED',
      'tenantId', v_request.tenant_id,
      'requestKey', v_request.request_key,
      'operation', v_request.operation,
      'attemptCount', v_request.attempt_count,
      'leaseToken', null,
      'leaseExpiresAt', v_request.lease_expires_at,
      'responsePayload', v_request.response_payload,
      'errorCode',
        coalesce(v_request.error_code, 'AI_RETRY_LIMIT_EXCEEDED'),
      'testFixture', false
    );
  end if;

  v_rate_cap := case p_operation when 'EVALUATE' then 40 else 20 end;
  select coalesce(pg_catalog.sum(request.attempt_count), 0)::integer
    into v_recent_attempts
    from public.wolfie_ai_requests as request
   where request.tenant_id = p_tenant_id
     and request.student_id = p_student_id
     and request.operation = p_operation
     and request.updated_at >= pg_catalog.now() - interval '1 hour';

  if v_recent_attempts >= v_rate_cap then
    raise exception using
      errcode = 'P0001',
      message = 'wolfie_ai_rate_limit_exceeded';
  end if;

  v_lease_token := gen_random_uuid();
  if v_has_request then
    update public.wolfie_ai_requests
       set status = 'PROCESSING',
           lease_token = v_lease_token,
           lease_expires_at = pg_catalog.now() + interval '45 seconds',
           attempt_count = attempt_count + 1,
           response_payload = '{}'::jsonb,
           error_code = null,
           completed_at = null,
           updated_at = pg_catalog.now()
     where id = v_request.id
     returning * into v_request;
  else
    insert into public.wolfie_ai_requests (
      tenant_id,
      student_id,
      request_key,
      operation,
      status,
      lease_token,
      lease_expires_at,
      attempt_count,
      test_fixture
    ) values (
      p_tenant_id,
      p_student_id,
      p_request_key,
      p_operation,
      'PROCESSING',
      v_lease_token,
      pg_catalog.now() + interval '45 seconds',
      1,
      false
    )
    returning * into v_request;
  end if;

  return pg_catalog.jsonb_build_object(
    'claimed', true,
    'status', v_request.status,
    'tenantId', v_request.tenant_id,
    'requestKey', v_request.request_key,
    'operation', v_request.operation,
    'attemptCount', v_request.attempt_count,
    'leaseToken', v_request.lease_token,
    'leaseExpiresAt', v_request.lease_expires_at,
    'responsePayload', '{}'::jsonb,
    'errorCode', null,
    'testFixture', false
  );
end;
$$;


--
-- Name: claim_wolfie_live_grant(text, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_wolfie_live_grant(p_tenant_id text, p_student_id uuid, p_session_id uuid, p_max_seconds integer DEFAULT 600) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_balance jsonb;
  v_enforced boolean;
  v_remaining_seconds integer;
  v_plan_remaining_seconds integer;
  v_reserved_seconds integer;
  v_client_max_seconds integer;
  v_reserved_plan_seconds integer;
  v_reserved_credit_seconds integer;
  v_grant_id uuid;
  v_recent_grants integer;
  v_classic_handoff_at timestamptz;
begin
  if p_tenant_id is null
     or p_student_id is null
     or p_session_id is null
     or p_max_seconds is null
     or p_max_seconds not between 35 and 600 then
    raise exception 'invalid_live_grant_request';
  end if;

  select session.classic_handoff_at
    into v_classic_handoff_at
    from public.wolfie_sessions as session
    join public.tenant_memberships as membership
      on membership.user_id = session.student_id
     and membership.tenant_id = session.tenant_id
     and membership.status = 'ACTIVE'
     and membership.role = 'STUDENT'
   where session.id = p_session_id
     and session.student_id = p_student_id
     and session.tenant_id = p_tenant_id
     and session.finished_at is null
     and session.scenario_status not in ('completed', 'abandoned', 'failed')
   for update of session;
  if not found then
    raise exception 'live_grant_session_scope_not_found';
  end if;
  if v_classic_handoff_at is not null then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'allowed', false,
      'reason', 'classic_handoff'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'wolfie-live:' || p_tenant_id || ':' || p_student_id::text,
      0
    )
  );

  -- A setup that never reached OpenAI expires without charging the learner.
  update public.wolfie_live_grants
     set status = 'RELEASED',
         settled_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where tenant_id = p_tenant_id
     and student_id = p_student_id
     and status = 'RESERVED'
     and reservation_expires_at <= pg_catalog.now();

  -- ACTIVE leases are never released by SQL alone. The provider call must be
  -- hung up by the trusted Edge Function first; otherwise an old WebRTC call
  -- could keep running after a new grant is issued.

  select pg_catalog.count(*)::integer
    into v_recent_grants
    from public.wolfie_live_grants as grant_row
   where grant_row.tenant_id = p_tenant_id
     and grant_row.student_id = p_student_id
     and grant_row.created_at >= pg_catalog.now() - interval '1 hour'
     and grant_row.status <> 'RELEASED';
  if v_recent_grants >= 12 then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'allowed', false,
      'reason', 'live_rate_limited'
    );
  end if;

  if exists (
    select 1
      from public.wolfie_live_grants as grant_row
     where grant_row.tenant_id = p_tenant_id
       and grant_row.student_id = p_student_id
       and grant_row.status in ('RESERVED', 'ACTIVE', 'CLOSING')
  ) then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'allowed', false,
      'reason', 'student_live_connection_exists'
    );
  end if;

  v_balance := public.wolfie_live_balance(p_tenant_id, p_student_id);
  v_enforced := coalesce((v_balance ->> 'enforced')::boolean, false);
  if v_enforced then
    v_remaining_seconds := greatest(
      coalesce((v_balance ->> 'remainingSeconds')::integer, 0),
      0
    );
    -- Twenty seconds stay reserved beyond the client-visible deadline. This
    -- covers the ten-second scheduler cadence plus the bounded provider
    -- teardown request, so a modified client cannot consume unreserved time.
    if v_remaining_seconds < 35 then
      return pg_catalog.jsonb_build_object(
        'claimed', false,
        'allowed', false,
        'reason', 'insufficient_session_balance',
        'balance', v_balance
      );
    end if;
    v_reserved_seconds := least(p_max_seconds, v_remaining_seconds);
    v_plan_remaining_seconds := greatest(
      coalesce((v_balance ->> 'planRemainingSeconds')::integer, 0),
      0
    );
    v_reserved_plan_seconds := least(
      v_reserved_seconds,
      v_plan_remaining_seconds
    );
    v_reserved_credit_seconds := v_reserved_seconds
      - v_reserved_plan_seconds;
  else
    v_reserved_seconds := p_max_seconds;
    v_reserved_plan_seconds := p_max_seconds;
    v_reserved_credit_seconds := 0;
  end if;
  v_client_max_seconds := v_reserved_seconds - 20;
  if v_client_max_seconds < 15 then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'allowed', false,
      'reason', 'insufficient_session_balance',
      'balance', v_balance
    );
  end if;

  insert into public.wolfie_live_grants (
    tenant_id,
    student_id,
    session_id,
    status,
    enforced,
    reserved_seconds,
    client_max_seconds,
    reserved_plan_seconds,
    reserved_credit_seconds,
    reservation_expires_at,
    lease_expires_at
  ) values (
    p_tenant_id,
    p_student_id,
    p_session_id,
    'RESERVED',
    v_enforced,
    v_reserved_seconds,
    v_client_max_seconds,
    v_reserved_plan_seconds,
    v_reserved_credit_seconds,
    pg_catalog.now() + interval '60 seconds',
    pg_catalog.now() + interval '60 seconds'
  )
  returning id into v_grant_id;

  return pg_catalog.jsonb_build_object(
    'claimed', true,
    'allowed', true,
    'grantId', v_grant_id,
    'maxSeconds', v_client_max_seconds,
    'enforced', v_enforced,
    'balance', v_balance
  );
exception
  when unique_violation then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'allowed', false,
      'reason', 'student_live_connection_exists'
    );
end;
$$;


--
-- Name: claim_wolfie_live_grants_for_cleanup(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_wolfie_live_grants_for_cleanup(p_limit integer DEFAULT 100) RETURNS TABLE(grant_id uuid, tenant_id text, student_id uuid, provider_call_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 200);
begin
  return query
  with candidates as (
    select grant_row.id
      from public.wolfie_live_grants as grant_row
     where (
       grant_row.status = 'ACTIVE'
       and grant_row.lease_expires_at <= pg_catalog.now()
     ) or (
       grant_row.status = 'CLOSING'
       and (
         grant_row.cleanup_lease_expires_at is null
         or grant_row.cleanup_lease_expires_at <= pg_catalog.now()
       )
     )
     order by coalesce(
       grant_row.close_requested_at,
       grant_row.lease_expires_at
     ) asc
     for update skip locked
     limit v_limit
  ), claimed as (
    update public.wolfie_live_grants as grant_row
       set status = 'CLOSING',
           close_requested_at = coalesce(
             grant_row.close_requested_at,
             grant_row.lease_expires_at
           ),
           close_reason = coalesce(
             grant_row.close_reason,
             'LEASE_EXPIRED'
           ),
           cleanup_lease_expires_at = pg_catalog.now() + interval '9 seconds',
           updated_at = pg_catalog.now()
      from candidates
     where grant_row.id = candidates.id
     returning
       grant_row.id,
       grant_row.tenant_id,
       grant_row.student_id,
       grant_row.provider_call_id
  )
  select
    claimed.id,
    claimed.tenant_id,
    claimed.student_id,
    claimed.provider_call_id
  from claimed;
end;
$$;


--
-- Name: claim_wolfie_realtime_analysis(uuid, uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_wolfie_realtime_analysis(p_session_id uuid, p_assistant_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_resume_confirmed boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  current_payload jsonb;
  current_marker jsonb;
  claim_marker jsonb;
  marker_status text;
  prior_claimed_at timestamptz;
  claimed_at timestamptz := clock_timestamp();
  session_stage text;
  session_status text;
  session_finished_at timestamptz;
  session_classic_handoff_at timestamptz;
begin
  if p_session_id is null
     or p_assistant_turn_id is null
     or p_client_turn_id is null
     or p_claim_token is null then
    raise exception using errcode = '22023', message = 'invalid_realtime_claim';
  end if;

  select current_stage, scenario_status, finished_at, classic_handoff_at
    into session_stage, session_status, session_finished_at,
         session_classic_handoff_at
    from public.wolfie_sessions
   where id = p_session_id
   for share;
  if not found then
    raise exception using errcode = 'P0002', message = 'wolfie_session_not_found';
  end if;
  if session_finished_at is not null
     or session_stage = 'completed'
     or session_status in ('completed', 'abandoned', 'failed') then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'marker', pg_catalog.jsonb_build_object(
        'version', 1,
        'status', 'unavailable',
        'reason', 'session_finished',
        'currentStage', session_stage,
        'scenarioStatus', session_status
      )
    );
  end if;
  if session_classic_handoff_at is not null then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'marker', pg_catalog.jsonb_build_object(
        'version', 1,
        'status', 'unavailable',
        'reason', 'classic_handoff',
        'classicHandoffAt', session_classic_handoff_at
      )
    );
  end if;

  select coalesce(structured_payload, '{}'::jsonb)
    into current_payload
    from public.wolfie_turns
   where id = p_assistant_turn_id
     and session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'wolfie'
     and source_kind = 'openai_realtime'
   for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'realtime_turn_not_found';
  end if;

  current_marker := current_payload -> 'realtimeAnalysis';
  marker_status := coalesce(current_marker ->> 'status', '');
  if marker_status in ('completed', 'unavailable')
     or (marker_status = 'awaiting_confirmation' and not p_resume_confirmed) then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'marker', current_marker
    );
  end if;

  if marker_status = 'processing' then
    begin
      prior_claimed_at := nullif(current_marker ->> 'claimedAt', '')::timestamptz;
    exception when others then
      prior_claimed_at := null;
    end;
    if prior_claimed_at is not null
       and claimed_at - prior_claimed_at < interval '2 minutes' then
      return pg_catalog.jsonb_build_object(
        'claimed', false,
        'marker', current_marker
      );
    end if;
  end if;

  claim_marker := pg_catalog.jsonb_build_object(
    'version', 1,
    'status', 'processing',
    'source', 'server_post_turn',
    'configurationSource', 'persisted_session',
    'clientTurnId', p_client_turn_id,
    'assistantTurnId', p_assistant_turn_id,
    'claimToken', p_claim_token,
    'claimedAt', claimed_at,
    'resumedAfterConfirmation',
      marker_status = 'awaiting_confirmation' and p_resume_confirmed
  );

  update public.wolfie_turns
     set structured_payload = current_payload || pg_catalog.jsonb_build_object(
       'eligibleForCorrection', false,
       'realtimeAnalysis', claim_marker
     )
   where id = p_assistant_turn_id;

  return pg_catalog.jsonb_build_object(
    'claimed', true,
    'marker', claim_marker
  );
end;
$$;


--
-- Name: FUNCTION claim_wolfie_realtime_analysis(p_session_id uuid, p_assistant_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_resume_confirmed boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_wolfie_realtime_analysis(p_session_id uuid, p_assistant_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_resume_confirmed boolean) IS 'Claims one Realtime post-turn analysis with a database lock and stale-claim recovery.';


--
-- Name: claim_wolfie_realtime_fact_confirmation(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_wolfie_realtime_fact_confirmation(p_session_id uuid, p_student_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_confirmed_transcript text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  current_payload jsonb;
  current_content text;
  current_confirmation jsonb;
  confirmation_status text;
  current_transcript text;
  normalized_current text;
  normalized_requested text;
  prior_claimed_at timestamptz;
  claimed_at timestamptz := clock_timestamp();
  claim_marker jsonb;
begin
  if p_session_id is null
     or p_student_turn_id is null
     or p_client_turn_id is null
     or p_claim_token is null
     or nullif(pg_catalog.btrim(p_confirmed_transcript), '') is null
     or pg_catalog.octet_length(p_confirmed_transcript) > 32000 then
    raise exception using
      errcode = '22023',
      message = 'invalid_realtime_fact_confirmation_claim';
  end if;

  normalized_requested := pg_catalog.lower(
    pg_catalog.regexp_replace(
      pg_catalog.btrim(p_confirmed_transcript),
      '\s+',
      ' ',
      'g'
    )
  );

  select coalesce(structured_payload, '{}'::jsonb),
         coalesce(content, '')
    into current_payload, current_content
    from public.wolfie_turns
   where id = p_student_turn_id
     and session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'student'
     and source_kind = 'openai_realtime'
   for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'realtime_turn_not_found';
  end if;

  current_confirmation := current_payload -> 'factualConfirmation';
  confirmation_status := coalesce(
    current_confirmation ->> 'status',
    ''
  );
  current_transcript := coalesce(
    current_confirmation ->> 'confirmedTranscript',
    ''
  );
  normalized_current := pg_catalog.lower(
    pg_catalog.regexp_replace(
      pg_catalog.btrim(current_transcript),
      '\s+',
      ' ',
      'g'
    )
  );

  if confirmation_status = 'confirmed' then
    if normalized_current is distinct from normalized_requested then
      return pg_catalog.jsonb_build_object(
        'claimed', false,
        'conflict', true,
        'status', 'confirmed'
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'conflict', false,
      'idempotent', true,
      'status', 'confirmed',
      'confirmation', current_confirmation
    );
  end if;

  if confirmation_status in ('processing', 'retryable')
     and normalized_current is distinct from normalized_requested then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'conflict', true,
      'status', confirmation_status
    );
  end if;

  if confirmation_status = 'processing' then
    begin
      prior_claimed_at := nullif(
        current_confirmation ->> 'claimedAt',
        ''
      )::timestamptz;
    exception when others then
      prior_claimed_at := null;
    end;
    if prior_claimed_at is not null
       and claimed_at - prior_claimed_at < interval '2 minutes' then
      return pg_catalog.jsonb_build_object(
        'claimed', false,
        'conflict', false,
        'idempotent', false,
        'status', 'processing',
        'confirmation', current_confirmation
      );
    end if;
  end if;

  claim_marker := pg_catalog.jsonb_build_object(
    'version', 1,
    'status', 'processing',
    'clientTurnId', p_client_turn_id,
    'studentTurnId', p_student_turn_id,
    'claimToken', p_claim_token,
    'claimedAt', claimed_at,
    'confirmedTranscript', pg_catalog.btrim(p_confirmed_transcript),
    'originalRoughTranscript', current_content
  );

  update public.wolfie_turns
     set structured_payload = current_payload || pg_catalog.jsonb_build_object(
       'factualConfirmation', claim_marker
     )
   where id = p_student_turn_id;

  return pg_catalog.jsonb_build_object(
    'claimed', true,
    'conflict', false,
    'idempotent', false,
    'status', 'processing',
    'confirmation', claim_marker
  );
end;
$$;


--
-- Name: FUNCTION claim_wolfie_realtime_fact_confirmation(p_session_id uuid, p_student_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_confirmed_transcript text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.claim_wolfie_realtime_fact_confirmation(p_session_id uuid, p_student_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_confirmed_transcript text) IS 'Locks a Realtime student turn and idempotently claims one transcript confirmation.';


--
-- Name: claim_wolfie_topup_order_creation(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_wolfie_topup_order_creation(p_tenant_id text, p_student_id uuid, p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_order public.wolfie_topup_orders%rowtype;
begin
  if p_tenant_id is null or p_student_id is null or p_order_id is null then
    raise exception 'invalid_wolfie_topup_creation_claim';
  end if;
  select *
    into v_order
    from public.wolfie_topup_orders
   where id = p_order_id
     and tenant_id = p_tenant_id
     and student_id = p_student_id
   for update;
  if not found then
    raise exception using errcode = '42501', message = 'topup_order_not_owned';
  end if;
  if v_order.provider_payment_id is not null then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'reason', 'payment_already_linked',
      'paymentId', v_order.provider_payment_id
    );
  end if;
  if v_order.status not in ('PENDING', 'CREATING') then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'reason', pg_catalog.lower(v_order.status)
    );
  end if;
  if v_order.status = 'CREATING'
     and v_order.creation_lease_expires_at > pg_catalog.now() then
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'reason', 'creation_in_progress',
      'retryAfter', v_order.creation_lease_expires_at
    );
  end if;
  if v_order.creation_attempts >= 20 then
    update public.wolfie_topup_orders
       set status = 'RECONCILIATION_REQUIRED',
           reconciliation_required = true,
           updated_at = pg_catalog.now()
     where id = v_order.id;
    return pg_catalog.jsonb_build_object(
      'claimed', false,
      'reason', 'reconciliation_required'
    );
  end if;

  update public.wolfie_topup_orders
     set status = 'CREATING',
         creation_lease_expires_at = pg_catalog.now() + interval '90 seconds',
         creation_attempts = creation_attempts + 1,
         updated_at = pg_catalog.now()
   where id = v_order.id;
  return pg_catalog.jsonb_build_object(
    'claimed', true,
    'orderId', v_order.id
  );
end;
$$;


--
-- Name: classify_saas_owner_activation_identity(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classify_saas_owner_activation_identity(p_checkout_id uuid, p_claim_token uuid, p_owner_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.saas_owner_activation_attempts%rowtype;
  checkout_row public.saas_checkout_intents%rowtype;
  auth_user_row auth.users%rowtype;
  normalized_email text;
  marker_text text;
  marker_checkout_id uuid;
  expected_marker_checkout_id uuid;
  tenant_ready boolean := false;
  established_account boolean := false;
begin
  if p_checkout_id is null or p_claim_token is null
     or p_owner_user_id is null
  then
    raise exception using
      errcode = '22023', message = 'invalid_saas_owner_identity_classification';
  end if;

  select checkout.* into checkout_row
    from public.saas_checkout_intents as checkout
   where checkout.id = p_checkout_id
   for update;
  if checkout_row.id is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_owner_activation_checkout_missing'
    );
  end if;
  perform 1 from public.tenants as tenant
   where tenant.id = checkout_row.tenant_id
     and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) = 'active'
   for update;
  tenant_ready := found;
  if checkout_row.status not in (
    'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED'
  )
     or not tenant_ready
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_REQUIRED',
      'reason', 'saas_checkout_not_operational_for_identity_classification'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-activation:' || p_checkout_id::text,
      0
    )
  );

  select attempt.* into attempt_row
    from public.saas_owner_activation_attempts as attempt
   where attempt.checkout_id = p_checkout_id
   for update;
  if not found
     or attempt_row.status <> 'CLAIMED'
     or attempt_row.claim_token is distinct from p_claim_token
     or attempt_row.lease_expires_at <= pg_catalog.now()
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_owner_identity_classification_claim_lost'
    );
  end if;
  if checkout_row.tenant_id is distinct from attempt_row.tenant_id
     or lower(pg_catalog.btrim(checkout_row.owner_email))
       is distinct from attempt_row.owner_email
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_REQUIRED',
      'reason', 'saas_checkout_not_operational_for_identity_classification'
    );
  end if;

  normalized_email := lower(pg_catalog.btrim(attempt_row.owner_email));
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-activation-email:' || normalized_email,
      0
    )
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-access-user:' || p_owner_user_id::text,
      0
    )
  );
  select auth_user.* into auth_user_row
    from auth.users as auth_user
   where auth_user.id = p_owner_user_id
     and auth_user.deleted_at is null
     and auth_user.email_confirmed_at is not null
     and (
       auth_user.banned_until is null
       or auth_user.banned_until <= pg_catalog.now()
     )
   for update;
  if not found
     or lower(pg_catalog.btrim(coalesce(auth_user_row.email, '')))
       is distinct from attempt_row.owner_email
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_owner_identity_not_operational'
    );
  end if;

  marker_text := pg_catalog.btrim(coalesce(
    auth_user_row.raw_app_meta_data
      ->> 'saas_owner_activation_checkout_id',
    ''
  ));
  if marker_text <> '' then
    begin
      marker_checkout_id := marker_text::uuid;
    exception when invalid_text_representation then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'saas_owner_identity_marker_invalid'
      );
    end;
  end if;

  expected_marker_checkout_id := coalesce(
    attempt_row.owner_identity_marker_checkout_id,
    p_checkout_id
  );
  if attempt_row.owner_user_id = p_owner_user_id
     and attempt_row.provider_payload is not null
     and marker_checkout_id = expected_marker_checkout_id
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'CHECKOUT_IDENTITY',
      'marker_checkout_id', marker_checkout_id
    );
  end if;

  established_account := auth_user_row.last_sign_in_at is not null
    or auth_user_row.recovery_sent_at is not null
    or exists (
      select 1 from public.tenant_memberships as membership
       where membership.user_id = p_owner_user_id
         and membership.status = 'ACTIVE'
    )
    or exists (
      select 1 from public.profiles as profile
       where profile.id = p_owner_user_id
         and not (
           profile.tenant_id is null
           and profile.role = 'STUDENT'
           and profile.status_financial = 'PENDING'
           and lower(pg_catalog.btrim(coalesce(
             profile.lifecycle_status,
             ''
           ))) = 'active'
         )
    )
    or exists (
      select 1 from public.hub_accounts as account
       where account.owner_user_id = p_owner_user_id
    )
    or exists (
      select 1 from public.hub_memberships as membership
       where membership.user_id = p_owner_user_id
    )
    or exists (
      select 1 from auth.sessions as session
       where session.user_id = p_owner_user_id
    )
    or exists (
      select 1 from auth.mfa_factors as factor
       where factor.user_id = p_owner_user_id
    );
  if established_account or marker_checkout_id is null then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'EXISTING_ACCOUNT'
    );
  end if;
  if marker_checkout_id = p_checkout_id then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'CHECKOUT_IDENTITY',
      'marker_checkout_id', marker_checkout_id
    );
  end if;
  if private.saas_owner_identity_is_dormant_for_activation(
       p_checkout_id,
       p_owner_user_id,
       marker_checkout_id,
       attempt_row.owner_email
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'DORMANT_CHECKOUT_IDENTITY',
      'marker_checkout_id', marker_checkout_id
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', false,
    'action', 'REVIEW_REQUIRED',
    'reason', 'saas_owner_identity_requires_manual_review'
  );
end;
$$;


--
-- Name: cleanup_expired_idempotency_keys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_idempotency_keys() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    DELETE FROM public.idempotency_keys WHERE expires_at < now();
$$;


--
-- Name: closing_divergences(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.closing_divergences(p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_jwt_role text; v_caller_role text; v_tenant text; v_month text;
  v_start date; v_end date; v_rows jsonb;
BEGIN
  v_jwt_role := COALESCE(current_setting('request.jwt.claims', true)::json->>'role', '');
  SELECT role, tenant_id INTO v_caller_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_jwt_role IN ('anon','authenticated') THEN
    IF v_caller_role IS NULL OR v_caller_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
      RAISE EXCEPTION 'Apenas a direção pode ver divergências de fechamento';
    END IF;
  END IF;

  v_month := COALESCE(p_month, to_char(current_date,'YYYY-MM'));
  IF v_month !~ '^\d{4}-\d{2}$' THEN RAISE EXCEPTION 'Mês inválido (use YYYY-MM)'; END IF;
  v_start := (v_month||'-01')::date;
  v_end   := (date_trunc('month', v_start) + INTERVAL '1 month')::date;

  WITH previstas AS (
    SELECT b.teacher_id, b.student_id, d::date AS dia, b.time_slot,
           row_number() OVER (PARTITION BY b.teacher_id, b.student_id, d ORDER BY b.time_slot) AS rn
    FROM bookings b
    JOIN profiles t ON t.id = b.teacher_id
    CROSS JOIN generate_series(v_start, v_end - 1, '1 day') d
    WHERE COALESCE(b.status,'SCHEDULED') = 'SCHEDULED'
      AND b.student_id IS NOT NULL
      AND dow_name_to_int(b.day_of_week) = EXTRACT(dow FROM d)::int
      -- aluno que ainda não começou não gera pendência
      AND (b.start_date IS NULL OR d >= b.start_date)
      -- e nada no futuro: aula que ainda não aconteceu não está "faltando"
      AND d <= current_date
      -- perfis de teste/treinamento não geram pendência
      AND is_billable_student(b.student_id)
      AND (v_caller_role = 'SUPER_ADMIN' OR t.tenant_id = v_tenant)
  ), lancadas AS (
    -- Sem filtrar por professor: aula COBERTA por outro professor foi dada, não
    -- está faltando. Sem isso o João Pedro de 07/07 (transferido do Mateus para a
    -- Debora) aparecia como pendência do Mateus.
    SELECT cl.student_id, cl.class_date, count(*) AS n
    FROM class_logs cl
    WHERE cl.class_date >= v_start AND cl.class_date < v_end
    GROUP BY 1,2
  ), faltando AS (
    SELECT p.teacher_id, p.student_id, p.dia, p.time_slot
    FROM previstas p
    LEFT JOIN lancadas l ON l.student_id = p.student_id AND l.class_date = p.dia
    WHERE p.rn > COALESCE(l.n, 0)
  )
  SELECT jsonb_agg(x ORDER BY x->>'teacher_name', x->>'student_name')
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
      'teacher_id', f.teacher_id,
      'teacher_name', trim(t.full_name),
      'student_id', f.student_id,
      'student_name', trim(COALESCE(s.full_name,'Aluno não cadastrado')),
      'aulas_sem_lancamento', count(*),
      'valor_estimado', round(count(*) * COALESCE(
        (SELECT rate FROM teacher_pay_tiers tp WHERE tp.tenant_id = t.tenant_id AND tp.min_students = 1), 0), 2),
      'datas', jsonb_agg(to_char(f.dia,'DD/MM') ORDER BY f.dia)
    ) AS x
    FROM faltando f
    JOIN profiles t ON t.id = f.teacher_id
    LEFT JOIN profiles s ON s.id = f.student_id
    GROUP BY f.teacher_id, t.full_name, t.tenant_id, f.student_id, s.full_name
  ) z;

  RETURN jsonb_build_object('month', v_month, 'rows', COALESCE(v_rows,'[]'::jsonb));
END;
$_$;


--
-- Name: FUNCTION closing_divergences(p_month text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.closing_divergences(p_month text) IS 'Aulas que a agenda previa no mês e que ninguém lançou, por professor e aluno. Não inclui aluno antes do start_date nem datas futuras. Serve para o diretor cobrar o lançamento ANTES de aprovar a folha, em vez de descobrir conferindo à mão.';


--
-- Name: collect_wolfie_healthcheck(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.collect_wolfie_healthcheck() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_resp    record;
  v_healthy boolean;
  v_reason  text;
BEGIN
  SELECT status_code, content INTO v_resp
  FROM net._http_response
  WHERE created > now() - interval '20 minutes'
  ORDER BY id DESC LIMIT 1;

  IF v_resp.status_code IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'sem_resposta');
  END IF;

  BEGIN
    v_healthy := (v_resp.content::jsonb ->> 'healthy')::boolean;
    v_reason  := COALESCE(v_resp.content::jsonb ->> 'reason', '');
  EXCEPTION WHEN others THEN
    v_healthy := false;
    v_reason  := 'resposta ilegível do healthcheck';
  END;

  RETURN public.record_wolfie_health('realtime', COALESCE(v_healthy, false), v_reason);
END;
$$;


--
-- Name: commit_student_complementary_generation(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commit_student_complementary_generation(p_student_id uuid, p_reservation_id uuid, p_lease_token uuid, p_request_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile record;
  v_reservation public.student_complementary_generation_reservations%rowtype;
  v_batch public.student_generated_activity_batches%rowtype;
  v_now timestamptz := pg_catalog.now();
begin
  if p_student_id is null
     or p_reservation_id is null
     or p_lease_token is null
     or p_request_key is null then
    raise exception using
      errcode = '42501',
      message = 'generation_reservation_required';
  end if;

  select profile.tenant_id, profile.role
    into v_profile
    from public.profiles as profile
   where profile.id = p_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  select *
    into v_reservation
    from public.student_complementary_generation_reservations as reservation
   where reservation.id = p_reservation_id
     and reservation.student_id = p_student_id
     and reservation.tenant_id = v_profile.tenant_id
     and reservation.request_key = p_request_key
   for update;

  if not found or v_reservation.lease_token is distinct from p_lease_token then
    raise exception using
      errcode = '42501',
      message = 'generation_reservation_not_owned';
  end if;

  if v_reservation.status = 'COMMITTED' then
    select *
      into v_batch
     from public.student_generated_activity_batches as batch
     where batch.id = v_reservation.batch_id
       and batch.student_id = p_student_id
       and batch.tenant_id = v_profile.tenant_id
       and batch.request_key = p_request_key::text;

    if not found then
      raise exception using
        errcode = 'P0001',
        message = 'generated_activity_batch_not_persisted';
    end if;

    return pg_catalog.jsonb_build_object(
      'reservationId', v_reservation.id,
      'requestKey', v_reservation.request_key,
      'status', v_reservation.status,
      'code', 'ALREADY_COMMITTED',
      'batchId', v_reservation.batch_id,
      'replay', true,
      'activities', coalesce(v_batch.result -> 'activities', '[]'::jsonb)
    );
  end if;

  if v_reservation.status <> 'RESERVED' then
    raise exception using
      errcode = 'P0001',
      message = 'generation_reservation_not_active';
  end if;

  if v_reservation.lease_expires_at <= v_now then
    raise exception using
      errcode = 'P0001',
      message = 'generation_reservation_expired';
  end if;

  select *
    into v_batch
    from public.student_generated_activity_batches as batch
   where batch.student_id = p_student_id
     and batch.tenant_id = v_profile.tenant_id
     and batch.request_key = p_request_key::text
   order by batch.created_at desc, batch.id desc
   limit 1;

  if not found
     or coalesce((v_batch.result ->> 'created')::boolean, false) is not true then
    raise exception using
      errcode = 'P0001',
      message = 'generated_activity_batch_not_persisted';
  end if;

  update public.student_complementary_generation_reservations
     set status = 'COMMITTED',
         decision_code = 'COMMITTED',
         batch_id = v_batch.id,
         completed_at = v_now,
         updated_at = v_now
   where id = v_reservation.id
  returning * into v_reservation;

  return pg_catalog.jsonb_build_object(
    'reservationId', v_reservation.id,
    'requestKey', v_reservation.request_key,
    'status', v_reservation.status,
    'code', v_reservation.decision_code,
    'batchId', v_batch.id,
    'replay', false,
    'activities', coalesce(v_batch.result -> 'activities', '[]'::jsonb)
  );
end;
$$;


--
-- Name: FUNCTION commit_student_complementary_generation(p_student_id uuid, p_reservation_id uuid, p_lease_token uuid, p_request_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commit_student_complementary_generation(p_student_id uuid, p_reservation_id uuid, p_lease_token uuid, p_request_key uuid) IS 'Service-only commit of a student generation lease after its idempotent four-pack was persisted.';


--
-- Name: commit_wolfie_classic_exchange(uuid, uuid, text, uuid, text, text, jsonb, jsonb, integer, uuid, text, text, jsonb, text, jsonb, numeric, text, text, text, jsonb, text, text, integer, boolean, jsonb, jsonb, jsonb, timestamp with time zone, uuid, numeric, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.commit_wolfie_classic_exchange(p_session_id uuid, p_student_id uuid, p_tenant_id text, p_client_turn_id uuid, p_expected_current_stage text, p_expected_scenario_status text, p_expected_report jsonb, p_expected_memory jsonb, p_expected_retry_count integer, p_expected_pending_retry_id uuid, p_student_content text, p_student_stage text, p_student_payload jsonb, p_student_language_code text, p_student_speech_metrics jsonb, p_transcription_confidence numeric, p_assistant_content text, p_assistant_message_type text, p_assistant_language_code text, p_response_payload jsonb, p_next_stage text, p_next_scenario_status text, p_next_scenario_step integer, p_needs_external_verification boolean, p_next_report jsonb, p_next_memory jsonb, p_session_config jsonb, p_recorded_at timestamp with time zone, p_complete_retry_id uuid DEFAULT NULL::uuid, p_retry_score numeric DEFAULT NULL::numeric, p_retry_feedback jsonb DEFAULT '{}'::jsonb, p_new_corrections jsonb DEFAULT '[]'::jsonb, p_session_report jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_current_stage text;
  v_current_status text;
  v_current_report jsonb;
  v_current_memory jsonb;
  v_current_retry_count integer;
  v_current_finished_at timestamptz;
  v_realtime_anchor uuid;
  v_classic_anchor uuid;
  v_classic_handoff_at timestamptz;
  v_current_pending_retry_id uuid;
  v_existing_student_id uuid;
  v_existing_assistant_id uuid;
  v_existing_student_content text;
  v_existing_response jsonb;
  v_student_turn_id uuid;
  v_assistant_turn_id uuid;
  v_next_turn_index integer;
  v_correction jsonb;
  v_correction_feedback jsonb;
  v_requires_retry boolean;
  v_pending_retry_exists boolean := false;
  v_new_required_count integer := 0;
  v_inserted_corrections integer := 0;
  v_retry_updated integer := 0;
  v_canonical_stage text;
  v_canonical_status text;
  v_canonical_step integer;
  v_canonical_report jsonb;
  v_canonical_memory jsonb;
  v_canonical_response jsonb;
  v_commit_marker jsonb;
  v_report_generated_at timestamptz;
  v_accomplishments text[];
  v_experience_mode text;
  v_correction_mode text;
  v_language_mode text;
  v_difficulty text;
  v_scenario_context text;
  v_student_goal text;
  v_target_skill text;
  v_planned_duration integer;
  v_time_limit integer;
  v_config_snapshot jsonb;
begin
  if p_session_id is null
     or p_student_id is null
     or nullif(pg_catalog.btrim(p_tenant_id), '') is null
     or p_client_turn_id is null
     or p_expected_current_stage not in (
       'discovery', 'briefing', 'guided_build', 'practice', 'feedback',
       'retry', 'simulation', 'readaptation', 'improvisation',
       'assessment', 'report', 'completed'
     )
     or p_expected_scenario_status not in (
       'active', 'awaiting_retry', 'completed', 'abandoned', 'failed'
     )
     or p_student_stage not in (
       'discovery', 'briefing', 'guided_build', 'practice', 'feedback',
       'retry', 'simulation', 'readaptation', 'improvisation',
       'assessment', 'report', 'completed'
     )
     or p_next_stage not in (
       'discovery', 'briefing', 'guided_build', 'practice', 'feedback',
       'retry', 'simulation', 'readaptation', 'improvisation',
       'assessment', 'report', 'completed'
     )
     or p_next_scenario_status not in (
       'active', 'awaiting_retry', 'completed'
     )
     or p_next_scenario_step not between 1 and 12
     or p_expected_retry_count < 0
     or p_recorded_at is null
     or nullif(pg_catalog.btrim(p_student_content), '') is null
     or pg_catalog.octet_length(p_student_content) > 32000
     or nullif(pg_catalog.btrim(p_assistant_content), '') is null
     or pg_catalog.octet_length(p_assistant_content) > 32000
     or p_assistant_message_type not in (
       'question', 'correction', 'explanation', 'simulation', 'feedback',
       'instruction'
     )
     or (p_student_language_code is not null and p_student_language_code not in ('pt-BR', 'en-US', 'mixed'))
     or (p_assistant_language_code is not null and p_assistant_language_code not in ('pt-BR', 'en-US', 'mixed'))
     or (p_transcription_confidence is not null and (p_transcription_confidence < 0 or p_transcription_confidence > 1))
     or pg_catalog.jsonb_typeof(coalesce(p_expected_report, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_expected_memory, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_next_report, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_next_memory, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_student_payload, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_student_speech_metrics, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_response_payload, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_session_config, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_retry_feedback, '{}'::jsonb)) <> 'object'
     or pg_catalog.jsonb_typeof(coalesce(p_new_corrections, '[]'::jsonb)) <> 'array'
     or pg_catalog.jsonb_array_length(coalesce(p_new_corrections, '[]'::jsonb)) > 5
     or pg_catalog.octet_length(coalesce(p_expected_report, '{}'::jsonb)::text) > 250000
     or pg_catalog.octet_length(coalesce(p_expected_memory, '{}'::jsonb)::text) > 250000
     or pg_catalog.octet_length(coalesce(p_next_report, '{}'::jsonb)::text) > 250000
     or pg_catalog.octet_length(coalesce(p_next_memory, '{}'::jsonb)::text) > 250000
     or pg_catalog.octet_length(coalesce(p_response_payload, '{}'::jsonb)::text) > 250000
     or pg_catalog.octet_length(coalesce(p_new_corrections, '[]'::jsonb)::text) > 100000
     or nullif(pg_catalog.btrim(p_response_payload ->> 'chatResponse'), '') is null
     or p_response_payload ->> 'current_stage' is distinct from p_next_stage
     or p_response_payload ->> 'scenario_status' is distinct from p_next_scenario_status
     or (p_complete_retry_id is null and p_retry_score is not null)
     or (p_complete_retry_id is not null and p_complete_retry_id is distinct from p_expected_pending_retry_id)
     or (p_retry_score is not null and (p_retry_score < 0 or p_retry_score > 100)) then
    raise exception using
      errcode = '22023',
      message = 'invalid_classic_exchange_commit';
  end if;

  v_experience_mode := p_session_config ->> 'experience_mode';
  v_correction_mode := p_session_config ->> 'correction_mode';
  v_language_mode := p_session_config ->> 'language_mode';
  v_difficulty := p_session_config ->> 'difficulty';
  v_scenario_context := nullif(p_session_config ->> 'scenario_context', '');
  v_student_goal := nullif(p_session_config ->> 'student_goal', '');
  v_target_skill := nullif(p_session_config ->> 'target_skill', '');
  v_config_snapshot := p_session_config -> 'config_snapshot';
  begin
    v_planned_duration := nullif(p_session_config ->> 'planned_duration_minutes', '')::integer;
    v_time_limit := nullif(p_session_config ->> 'time_limit_seconds', '')::integer;
  exception when others then
    raise exception using errcode = '22023', message = 'invalid_classic_session_timing';
  end;
  if v_experience_mode not in (
       'free_conversation', 'guided_lesson', 'roleplay', 'presentation',
       'global_meeting', 'interview', 'exam', 'writing', 'pronunciation',
       'vocabulary', 'storytelling', 'child_mission', 'teen_challenge',
       'examiner', 'fluency', 'emergency'
     )
     or v_correction_mode not in ('immediate', 'end', 'selective', 'examiner')
     or v_language_mode not in ('pt_support', 'bilingual', 'immersive', 'english_rescue')
     or v_difficulty not in ('supportive', 'balanced', 'challenging', 'adaptive')
     or (v_planned_duration is not null and v_planned_duration not between 1 and 240)
     or (v_time_limit is not null and v_time_limit not between 10 and 86400)
     or pg_catalog.jsonb_typeof(coalesce(v_config_snapshot, '{}'::jsonb)) <> 'object'
     or pg_catalog.octet_length(coalesce(v_config_snapshot, '{}'::jsonb)::text) > 100000 then
    raise exception using errcode = '22023', message = 'invalid_classic_session_config';
  end if;

  select current_stage,
         scenario_status,
         coalesce(report_json, '{}'::jsonb),
         coalesce(memory_summary, '{}'::jsonb),
         greatest(0, coalesce(retry_count, 0)),
         finished_at,
         realtime_first_client_turn_id,
         classic_first_client_turn_id,
         classic_handoff_at
    into v_current_stage,
         v_current_status,
         v_current_report,
         v_current_memory,
         v_current_retry_count,
         v_current_finished_at,
         v_realtime_anchor,
         v_classic_anchor,
         v_classic_handoff_at
    from public.wolfie_sessions
   where id = p_session_id
     and student_id = p_student_id
     and tenant_id = p_tenant_id
   for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'wolfie_session_not_found';
  end if;
  if v_realtime_anchor is not null and v_classic_handoff_at is null then
    raise exception using errcode = '55000', message = 'wolfie_session_transport_mismatch';
  end if;

  select id, content
    into v_existing_student_id, v_existing_student_content
    from public.wolfie_turns
   where session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'student'
     and source_kind = 'classic';
  select id, coalesce(structured_payload -> 'classicResponse', structured_payload)
    into v_existing_assistant_id, v_existing_response
    from public.wolfie_turns
   where session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'wolfie'
     and source_kind = 'classic';
  if (v_existing_student_id is null) <> (v_existing_assistant_id is null) then
    raise exception using errcode = '55000', message = 'classic_exchange_incomplete';
  end if;
  if v_existing_student_id is not null then
    if v_existing_student_content is distinct from pg_catalog.btrim(p_student_content) then
      raise exception using errcode = '22023', message = 'classic_client_turn_id_reused';
    end if;
    return pg_catalog.jsonb_build_object(
      'persisted', true,
      'idempotent', true,
      'studentTurnId', v_existing_student_id,
      'assistantTurnId', v_existing_assistant_id,
      'stage', coalesce(v_existing_response ->> 'current_stage', v_current_stage),
      'scenarioStatus', coalesce(v_existing_response ->> 'scenario_status', v_current_status),
      'retryCount', v_current_retry_count,
      'responsePayload', coalesce(v_existing_response, '{}'::jsonb)
    );
  end if;

  select id
    into v_current_pending_retry_id
    from public.wolfie_corrections
   where session_id = p_session_id
     and status = 'active'
     and requires_retry = true
     and retry_completed = false
   order by created_at desc, id desc
   limit 1
   for update;

  if v_current_finished_at is not null
     or v_current_stage = 'completed'
     or v_current_status in ('completed', 'abandoned', 'failed')
     or v_current_stage is distinct from p_expected_current_stage
     or v_current_status is distinct from p_expected_scenario_status
     or v_current_report <> coalesce(p_expected_report, '{}'::jsonb)
     or v_current_memory <> coalesce(p_expected_memory, '{}'::jsonb)
     or v_current_retry_count <> p_expected_retry_count then
    return pg_catalog.jsonb_build_object('persisted', false, 'reason', 'cas_mismatch');
  end if;
  if v_current_pending_retry_id is distinct from p_expected_pending_retry_id then
    return pg_catalog.jsonb_build_object(
      'persisted', false,
      'reason', 'retry_invariant_changed'
    );
  end if;

  select coalesce(max(turn_index), -1) + 1
    into v_next_turn_index
    from public.wolfie_turns
   where session_id = p_session_id;

  insert into public.wolfie_turns (
    session_id,
    speaker,
    content,
    turn_index,
    message_type,
    stage,
    structured_payload,
    requires_retry,
    language_code,
    speech_metrics,
    transcription_confidence,
    source_kind,
    client_turn_id
  ) values (
    p_session_id,
    'student',
    pg_catalog.btrim(p_student_content),
    v_next_turn_index,
    'instruction',
    p_student_stage,
    coalesce(p_student_payload, '{}'::jsonb),
    p_expected_pending_retry_id is not null,
    p_student_language_code,
    coalesce(p_student_speech_metrics, '{}'::jsonb),
    p_transcription_confidence,
    'classic',
    p_client_turn_id
  ) returning id into v_student_turn_id;
  v_next_turn_index := v_next_turn_index + 1;

  -- Retry completion is fenced by the exact pending id and points to the
  -- immutable learner evidence turn inserted above.
  if p_complete_retry_id is not null then
    update public.wolfie_corrections
       set retry_completed = true,
           retry_turn_id = v_student_turn_id,
           retry_score = p_retry_score,
           retry_feedback = coalesce(retry_feedback, '{}'::jsonb)
             || coalesce(p_retry_feedback, '{}'::jsonb),
           retry_completed_at = p_recorded_at
     where id = p_complete_retry_id
       and session_id = p_session_id
       and status = 'active'
       and requires_retry = true
       and retry_completed = false;
    get diagnostics v_retry_updated = row_count;
    if v_retry_updated <> 1 then
      raise exception using errcode = '40001', message = 'classic_retry_fenced';
    end if;
  end if;

  select exists (
    select 1
      from public.wolfie_corrections
     where session_id = p_session_id
       and status = 'active'
       and requires_retry = true
       and retry_completed = false
  ) into v_pending_retry_exists;

  for v_correction in
    select value
      from pg_catalog.jsonb_array_elements(
        coalesce(p_new_corrections, '[]'::jsonb)
      )
  loop
    if pg_catalog.jsonb_typeof(v_correction) <> 'object'
       or nullif(pg_catalog.btrim(v_correction ->> 'wrong_sentence'), '') is null
       or nullif(pg_catalog.btrim(v_correction ->> 'correct_sentence'), '') is null
       or nullif(pg_catalog.btrim(v_correction ->> 'explanation_pt'), '') is null
       or pg_catalog.octet_length(v_correction ->> 'wrong_sentence') > 8000
       or pg_catalog.octet_length(v_correction ->> 'correct_sentence') > 8000
       or pg_catalog.octet_length(coalesce(v_correction ->> 'natural_sentence', '')) > 8000
       or pg_catalog.octet_length(v_correction ->> 'explanation_pt') > 12000
       or coalesce(v_correction ->> 'priority', '') not in ('low', 'medium', 'high')
       or coalesce(v_correction ->> 'requires_retry', 'false') not in ('true', 'false') then
      raise exception using errcode = '22023', message = 'invalid_classic_correction';
    end if;
    v_correction_feedback := coalesce(v_correction -> 'retry_feedback', '{}'::jsonb);
    if pg_catalog.jsonb_typeof(v_correction_feedback) <> 'object'
       or pg_catalog.octet_length(v_correction_feedback::text) > 50000 then
      raise exception using errcode = '22023', message = 'invalid_classic_correction_feedback';
    end if;
    v_requires_retry := coalesce((v_correction ->> 'requires_retry')::boolean, false);
    if v_pending_retry_exists or v_new_required_count > 0 then
      v_requires_retry := false;
    end if;

    insert into public.wolfie_corrections (
      session_id,
      turn_id,
      wrong_sentence,
      correct_sentence,
      natural_sentence,
      explanation_pt,
      error_type,
      skill_focus,
      priority,
      requires_retry,
      retry_completed,
      retry_feedback
    ) values (
      p_session_id,
      v_student_turn_id,
      pg_catalog.left(pg_catalog.btrim(v_correction ->> 'wrong_sentence'), 2000),
      pg_catalog.left(pg_catalog.btrim(v_correction ->> 'correct_sentence'), 2000),
      pg_catalog.left(pg_catalog.btrim(coalesce(v_correction ->> 'natural_sentence', '')), 2000),
      pg_catalog.left(pg_catalog.btrim(v_correction ->> 'explanation_pt'), 3000),
      pg_catalog.left(pg_catalog.btrim(coalesce(v_correction ->> 'error_type', 'general')), 80),
      nullif(pg_catalog.left(pg_catalog.btrim(coalesce(v_correction ->> 'skill_focus', '')), 80), ''),
      v_correction ->> 'priority',
      v_requires_retry,
      false,
      v_correction_feedback
    );
    v_inserted_corrections := v_inserted_corrections + 1;
    if v_requires_retry then
      v_new_required_count := 1;
      v_pending_retry_exists := true;
    end if;
  end loop;

  select exists (
    select 1
      from public.wolfie_corrections
     where session_id = p_session_id
       and status = 'active'
       and requires_retry = true
       and retry_completed = false
  ) into v_pending_retry_exists;

  if not v_pending_retry_exists
     and (p_next_stage = 'retry' or p_next_scenario_status = 'awaiting_retry') then
    raise exception using
      errcode = '40001',
      message = 'classic_retry_invariant_changed';
  end if;

  v_canonical_stage := case when v_pending_retry_exists then 'retry' else p_next_stage end;
  v_canonical_status := case when v_pending_retry_exists then 'awaiting_retry' else p_next_scenario_status end;
  v_canonical_step := case when v_pending_retry_exists then 6 else p_next_scenario_step end;
  v_canonical_report := coalesce(p_next_report, '{}'::jsonb)
    || pg_catalog.jsonb_build_object(
      'currentStage', v_canonical_stage,
      'scenarioStatus', v_canonical_status
    );
  v_canonical_memory := coalesce(p_next_memory, '{}'::jsonb)
    || pg_catalog.jsonb_build_object('currentStage', v_canonical_stage);
  v_canonical_response := coalesce(p_response_payload, '{}'::jsonb)
    || pg_catalog.jsonb_build_object(
      'current_stage', v_canonical_stage,
      'scenario_status', v_canonical_status,
      'requires_retry', v_pending_retry_exists,
      'retry_completed',
        coalesce((p_response_payload ->> 'retry_completed')::boolean, false)
        and not v_pending_retry_exists
    );

  v_commit_marker := pg_catalog.jsonb_build_object(
    'version', 1,
    'status', 'completed',
    'source', 'classic_atomic_commit',
    'clientTurnId', p_client_turn_id,
    'studentTurnId', v_student_turn_id,
    'stage', v_canonical_stage,
    'scenarioStatus', v_canonical_status,
    'retryCount', v_current_retry_count + v_new_required_count,
    'correctionsCreated', v_inserted_corrections,
    'committedAt', p_recorded_at
  );

  insert into public.wolfie_turns (
    session_id,
    speaker,
    content,
    turn_index,
    message_type,
    stage,
    structured_payload,
    requires_retry,
    language_code,
    speech_metrics,
    source_kind,
    client_turn_id
  ) values (
    p_session_id,
    'wolfie',
    pg_catalog.btrim(p_assistant_content),
    v_next_turn_index,
    p_assistant_message_type,
    v_canonical_stage,
    v_canonical_response || pg_catalog.jsonb_build_object(
      'classicResponse', v_canonical_response,
      'classicCommit', v_commit_marker
    ),
    v_pending_retry_exists,
    p_assistant_language_code,
    '{}'::jsonb,
    'classic',
    p_client_turn_id
  ) returning id into v_assistant_turn_id;

  v_commit_marker := v_commit_marker
    || pg_catalog.jsonb_build_object('assistantTurnId', v_assistant_turn_id);
  update public.wolfie_turns
     set structured_payload = coalesce(structured_payload, '{}'::jsonb)
       || pg_catalog.jsonb_build_object('classicCommit', v_commit_marker)
   where id = v_student_turn_id;
  update public.wolfie_turns
     set structured_payload = coalesce(structured_payload, '{}'::jsonb)
       || pg_catalog.jsonb_build_object('classicCommit', v_commit_marker)
   where id = v_assistant_turn_id;

  update public.wolfie_sessions
     set experience_mode = v_experience_mode,
         correction_mode = v_correction_mode,
         language_mode = v_language_mode,
         difficulty = v_difficulty,
         scenario_context = v_scenario_context,
         student_goal = v_student_goal,
         target_skill = v_target_skill,
         planned_duration_minutes = v_planned_duration,
         time_limit_seconds = v_time_limit,
         current_stage = v_canonical_stage,
         scenario_status = v_canonical_status,
         scenario_step = v_canonical_step,
         retry_count = v_current_retry_count + v_new_required_count,
         needs_external_verification =
           coalesce(needs_external_verification, false)
           or coalesce(p_needs_external_verification, false),
         report_json = v_canonical_report,
         memory_summary = v_canonical_memory,
         config_snapshot = v_config_snapshot,
         classic_first_client_turn_id = coalesce(
           classic_first_client_turn_id,
           p_client_turn_id
         ),
         turn_count = greatest(0, coalesce(turn_count, 0)) + 1,
         student_word_count = greatest(0, coalesce(student_word_count, 0))
           + cardinality(pg_catalog.regexp_split_to_array(pg_catalog.btrim(p_student_content), '\s+')),
         wolfie_word_count = greatest(0, coalesce(wolfie_word_count, 0))
           + cardinality(pg_catalog.regexp_split_to_array(pg_catalog.btrim(p_assistant_content), '\s+')),
         last_activity_at = p_recorded_at,
         updated_at = p_recorded_at,
         finished_at = case
           when v_canonical_status = 'completed' then p_recorded_at
           else null
         end
   where id = p_session_id
     and student_id = p_student_id
     and tenant_id = p_tenant_id;

  if p_session_report is not null then
    if pg_catalog.jsonb_typeof(p_session_report) <> 'object'
       or pg_catalog.octet_length(p_session_report::text) > 250000
       or p_session_report ->> 'tenant_id' is distinct from p_tenant_id
       or p_session_report ->> 'student_id' is distinct from p_student_id::text
       or p_session_report ->> 'conversation_session_id' is distinct from p_session_id::text
       or nullif(pg_catalog.btrim(p_session_report ->> 'topic'), '') is null
       or pg_catalog.jsonb_typeof(p_session_report -> 'accomplishments') <> 'array'
       or pg_catalog.jsonb_array_length(p_session_report -> 'accomplishments') > 20
       or pg_catalog.jsonb_typeof(p_session_report -> 'primary_corrections') <> 'array'
       or pg_catalog.jsonb_array_length(p_session_report -> 'primary_corrections') > 20
       or pg_catalog.jsonb_typeof(p_session_report -> 'new_vocabulary') <> 'array'
       or pg_catalog.jsonb_array_length(p_session_report -> 'new_vocabulary') > 30
       or pg_catalog.jsonb_typeof(p_session_report -> 'rubric_scores') <> 'object' then
      raise exception using errcode = '22023', message = 'invalid_classic_session_report';
    end if;
    begin
      v_report_generated_at := nullif(
        pg_catalog.btrim(p_session_report ->> 'generated_at'),
        ''
      )::timestamptz;
    exception when others then
      raise exception using errcode = '22023', message = 'invalid_classic_report_timestamp';
    end;
    if v_report_generated_at is null then
      raise exception using errcode = '22023', message = 'invalid_classic_report_timestamp';
    end if;
    select coalesce(
             pg_catalog.array_agg(
               pg_catalog.left(item.value, 500)
               order by item.ordinality
             ),
             '{}'::text[]
           )
      into v_accomplishments
      from pg_catalog.jsonb_array_elements_text(
        p_session_report -> 'accomplishments'
      ) with ordinality as item(value, ordinality);

    insert into public.wolfie_session_reports as existing_report (
      tenant_id,
      student_id,
      conversation_session_id,
      activity_session_id,
      topic,
      objective,
      difficulty,
      accomplishments,
      primary_corrections,
      new_vocabulary,
      recurring_error,
      best_phrase,
      review_point,
      next_step,
      practice_mission,
      rubric_scores,
      generated_by_model,
      generated_at
    ) values (
      p_tenant_id,
      p_student_id,
      p_session_id,
      null,
      pg_catalog.left(pg_catalog.btrim(p_session_report ->> 'topic'), 1000),
      nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'objective', '')), 4000), ''),
      nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'difficulty', '')), 100), ''),
      v_accomplishments,
      p_session_report -> 'primary_corrections',
      p_session_report -> 'new_vocabulary',
      nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'recurring_error', '')), 4000), ''),
      nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'best_phrase', '')), 4000), ''),
      nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'review_point', '')), 4000), ''),
      nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'next_step', '')), 4000), ''),
      nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'practice_mission', '')), 4000), ''),
      p_session_report -> 'rubric_scores',
      nullif(pg_catalog.left(pg_catalog.btrim(coalesce(p_session_report ->> 'generated_by_model', '')), 200), ''),
      v_report_generated_at
    )
    on conflict (conversation_session_id)
      where conversation_session_id is not null
    do update set
      tenant_id = excluded.tenant_id,
      student_id = excluded.student_id,
      topic = excluded.topic,
      objective = excluded.objective,
      difficulty = excluded.difficulty,
      accomplishments = excluded.accomplishments,
      primary_corrections = excluded.primary_corrections,
      new_vocabulary = excluded.new_vocabulary,
      recurring_error = excluded.recurring_error,
      best_phrase = excluded.best_phrase,
      review_point = excluded.review_point,
      next_step = excluded.next_step,
      practice_mission = excluded.practice_mission,
      rubric_scores = excluded.rubric_scores,
      generated_by_model = excluded.generated_by_model,
      generated_at = excluded.generated_at
    where existing_report.student_id = p_student_id
      and existing_report.tenant_id = p_tenant_id;
  end if;

  return pg_catalog.jsonb_build_object(
    'persisted', true,
    'idempotent', false,
    'studentTurnId', v_student_turn_id,
    'assistantTurnId', v_assistant_turn_id,
    'stage', v_canonical_stage,
    'scenarioStatus', v_canonical_status,
    'retryCount', v_current_retry_count + v_new_required_count,
    'correctionsCreated', v_inserted_corrections,
    'responsePayload', v_canonical_response,
    'marker', v_commit_marker
  );
end;
$$;


--
-- Name: FUNCTION commit_wolfie_classic_exchange(p_session_id uuid, p_student_id uuid, p_tenant_id text, p_client_turn_id uuid, p_expected_current_stage text, p_expected_scenario_status text, p_expected_report jsonb, p_expected_memory jsonb, p_expected_retry_count integer, p_expected_pending_retry_id uuid, p_student_content text, p_student_stage text, p_student_payload jsonb, p_student_language_code text, p_student_speech_metrics jsonb, p_transcription_confidence numeric, p_assistant_content text, p_assistant_message_type text, p_assistant_language_code text, p_response_payload jsonb, p_next_stage text, p_next_scenario_status text, p_next_scenario_step integer, p_needs_external_verification boolean, p_next_report jsonb, p_next_memory jsonb, p_session_config jsonb, p_recorded_at timestamp with time zone, p_complete_retry_id uuid, p_retry_score numeric, p_retry_feedback jsonb, p_new_corrections jsonb, p_session_report jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.commit_wolfie_classic_exchange(p_session_id uuid, p_student_id uuid, p_tenant_id text, p_client_turn_id uuid, p_expected_current_stage text, p_expected_scenario_status text, p_expected_report jsonb, p_expected_memory jsonb, p_expected_retry_count integer, p_expected_pending_retry_id uuid, p_student_content text, p_student_stage text, p_student_payload jsonb, p_student_language_code text, p_student_speech_metrics jsonb, p_transcription_confidence numeric, p_assistant_content text, p_assistant_message_type text, p_assistant_language_code text, p_response_payload jsonb, p_next_stage text, p_next_scenario_status text, p_next_scenario_step integer, p_needs_external_verification boolean, p_next_report jsonb, p_next_memory jsonb, p_session_config jsonb, p_recorded_at timestamp with time zone, p_complete_retry_id uuid, p_retry_score numeric, p_retry_feedback jsonb, p_new_corrections jsonb, p_session_report jsonb) IS 'Exact-snapshot, idempotent transaction for one complete classic Wolfie exchange.';


--
-- Name: complete_attendance_confirmation_delivery(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_attendance_confirmation_delivery(p_confirmation_id uuid, p_claim_token uuid, p_provider_message_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.attendance_confirmations%rowtype;
begin
  if p_confirmation_id is null or p_claim_token is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'claim_invalido');
  end if;

  if nullif(pg_catalog.btrim(coalesce(p_provider_message_id, '')), '') is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'error', 'provider_message_id_obrigatorio'
    );
  end if;

  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = p_confirmation_id
   for update;

  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'nao_encontrado');
  end if;

  if c.delivery_status = 'SENT'
     and c.delivery_claim_token = p_claim_token then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'already', true,
      'sent_at', c.sent_at
    );
  end if;

  if c.delivery_status <> 'PROCESSING'
     or c.delivery_claim_token is distinct from p_claim_token then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'error', 'claim_obsoleto',
      'delivery_status', c.delivery_status
    );
  end if;

  update public.attendance_confirmations ac
     set delivery_status = 'SENT',
         sent_at = coalesce(ac.sent_at, pg_catalog.now()),
         delivery_claim_expires_at = null,
         provider_message_id = pg_catalog.left(pg_catalog.btrim(p_provider_message_id), 255),
         last_delivery_error = null
   where ac.id = c.id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'sent_at', pg_catalog.now(),
    'delivery_key', c.delivery_key
  );
end;
$$;


--
-- Name: complete_enrollment_offer(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_enrollment_offer(p_offer_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
  v_opportunity_id uuid;
  v_tenant_id text;
begin
  v_result := public.complete_enrollment_offer_pre_crm_won_impl(
    p_offer_id,
    p_user_id
  );
  if coalesce((v_result ->> 'success')::boolean, false) is not true then
    return v_result;
  end if;

  select opportunity.id, opportunity.tenant_id
    into v_opportunity_id, v_tenant_id
    from public.offers as offer
    join public.opportunities as opportunity
      on opportunity.id = offer.opportunity_id
     and opportunity.tenant_id = offer.tenant_id
   where offer.id = p_offer_id
     and offer.kind = 'ENROLLMENT'
     and opportunity.kind = 'TRIAL'
     and opportunity.conversion_status = 'WON'
     and opportunity.student_id = p_user_id;
  if found then
    perform pg_catalog.set_config(
      'app.crm_trial_outcome_opportunity',
      v_opportunity_id::text,
      true
    );
    update public.crm_leads as lead
       set status = 'WON',
           student_id = p_user_id,
           last_status_change = pg_catalog.clock_timestamp()
     where lead.opportunity_id = v_opportunity_id
       and lead.tenant_id = v_tenant_id;
    perform pg_catalog.set_config(
      'app.crm_trial_outcome_opportunity',
      '',
      true
    );
  end if;

  return v_result;
end;
$$;


--
-- Name: complete_enrollment_offer_authoritative_impl(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_enrollment_offer_authoritative_impl(p_offer_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_role text := coalesce(auth.jwt() ->> 'role', '');
  v_opportunity_id uuid;
  v_enrollment_link_id uuid;
  v_invite_id uuid;
  v_duration integer;
  v_fee numeric;
  v_commission_rate integer;
  v_vendor_role text;
  v_vendor_tenant text;
  o public.offers%rowtype;
  p public.profiles%rowtype;
  v_opp public.opportunities%rowtype;
begin
  if v_role <> 'service_role' then
    return jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  end if;

  select opportunity_id
    into v_opportunity_id
    from public.offers
   where id = p_offer_id
     and kind = 'ENROLLMENT';
  if not found then
    return jsonb_build_object('success', false, 'error', 'OFFER_NOT_FOUND');
  end if;

  if v_opportunity_id is not null then
    select *
      into v_opp
      from public.opportunities
     where id = v_opportunity_id
     for update;
  end if;

  select *
    into o
    from public.offers
   where id = p_offer_id
     and kind = 'ENROLLMENT'
   for update;

  if not found then return jsonb_build_object('success', false, 'error', 'OFFER_NOT_FOUND'); end if;
  if o.processing_by is distinct from p_user_id then
    return jsonb_build_object('success', false, 'error', 'ATTEMPT_OWNER_MISMATCH');
  end if;
  if o.processing_state = 'COMPLETED' and o.consumed_by = p_user_id then
    return jsonb_build_object(
      'success', true,
      'already_completed', true,
      'correlation_id', o.processing_correlation_id
    );
  end if;
  if o.revoked_at is not null then return jsonb_build_object('success', false, 'error', 'OFFER_REVOKED'); end if;

  select * into p from public.profiles where id = p_user_id for update;
  if not found or p.tenant_id is distinct from o.tenant_id or p.role is distinct from 'STUDENT' then
    return jsonb_build_object('success', false, 'error', 'PROFILE_INVALID');
  end if;

  v_duration := coalesce(nullif(o.payload ->> 'planDuration', '')::integer, 1);
  v_fee := greatest(coalesce(o.enrollment_fee, 0), 0);

  if nullif(p.asaas_customer_id, '') is null then
    return jsonb_build_object('success', false, 'error', 'CUSTOMER_PENDING');
  end if;
  if v_duration = 0 then
    if nullif(o.metadata ->> 'one_time_payment_id', '') is null
       or nullif(o.metadata ->> 'one_time_paid_at', '') is null then
      return jsonb_build_object('success', false, 'error', 'PAYMENT_PENDING');
    end if;
  elsif nullif(p.subscription_id, '') is null then
    return jsonb_build_object('success', false, 'error', 'SUBSCRIPTION_PENDING');
  end if;
  if v_fee > 0 and coalesce(p.enrollment_fee_paid, false) is false then
    return jsonb_build_object('success', false, 'error', 'ENROLLMENT_FEE_PENDING');
  end if;

  v_invite_id := nullif(o.metadata ->> 'referral_invite_id', '')::uuid;

  update public.offers
     set consumed_at = coalesce(consumed_at, now()),
         consumed_by = coalesce(consumed_by, p_user_id),
         usage_count = coalesce(usage_count, 0)
           + case when consumed_at is null then 1 else 0 end,
         last_used_at = now(),
         processing_state = 'COMPLETED',
         processing_updated_at = now(),
         processing_completed_at = coalesce(processing_completed_at, now()),
         processing_error_code = null,
         processing_error_message = null
   where id = o.id;

  if v_invite_id is not null then
    update public.referral_invites
       set status = 'CONVERTED',
           converted_at = coalesce(converted_at, now()),
           converted_student_id = p_user_id
     where id = v_invite_id
       and status = 'PENDING';
  end if;

  if o.opportunity_id is not null then
    update public.opportunities
       set conversion_status = 'WON',
           student_id = p_user_id
     where id = o.opportunity_id
       and (student_id is null or student_id = p_user_id);
  end if;

  select el.id
    into v_enrollment_link_id
    from public.enrollment_links el
   where el.offer_id = o.id
   limit 1;

  update public.enrollment_links
     set status = 'USED',
         used_at = coalesce(used_at, now())
   where offer_id = o.id
     and status in ('PENDING', 'PROCESSING');

  if o.vendor_id is not null then
    select pr.role, pr.tenant_id, coalesce(pr.commission_rate, 3000)
      into v_vendor_role, v_vendor_tenant, v_commission_rate
      from public.profiles pr
     where pr.id = o.vendor_id;

    if v_vendor_role = 'SALESPERSON'
       and v_vendor_tenant = o.tenant_id then
      insert into public.vendor_commissions (
        vendor_id, student_id, enrollment_link_id, offer_id,
        amount_brl, status, tenant_id
      )
      values (
        o.vendor_id, p_user_id, v_enrollment_link_id, o.id,
        v_commission_rate, 'PENDING', o.tenant_id
      )
      on conflict (offer_id) where offer_id is not null do nothing;
    end if;
  end if;

  return jsonb_build_object(
    'success', true,
    'processing_state', 'COMPLETED',
    'correlation_id', o.processing_correlation_id
  );
end;
$$;


--
-- Name: complete_enrollment_offer_pre_crm_won_impl(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_enrollment_offer_pre_crm_won_impl(p_offer_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_runtime_role text := coalesce((select auth.jwt() ->> 'role'), '');
  v_opportunity_id uuid;
  v_opportunity public.opportunities%rowtype;
  v_offer public.offers%rowtype;
begin
  if v_runtime_role <> 'service_role' then
    return pg_catalog.jsonb_build_object(
      'success', false, 'error', 'FORBIDDEN'
    );
  end if;

  select offer.opportunity_id
  into v_opportunity_id
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.kind = 'ENROLLMENT';
  if not found then
    return pg_catalog.jsonb_build_object(
      'success', false, 'error', 'OFFER_NOT_FOUND'
    );
  end if;
  if v_opportunity_id is null then
    return public.complete_enrollment_offer_pre_trial_lifecycle_impl(
      p_offer_id,
      p_user_id
    );
  end if;

  perform private.lock_trial_conversion_graph(v_opportunity_id);
  select opportunity.*
  into v_opportunity
  from public.opportunities as opportunity
  where opportunity.id = v_opportunity_id;
  select offer.*
  into v_offer
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.opportunity_id = v_opportunity_id
    and offer.kind = 'ENROLLMENT';

  if v_offer.id is null then
    return pg_catalog.jsonb_build_object(
      'success', false, 'error', 'OFFER_NOT_FOUND'
    );
  end if;
  if v_offer.processing_state = 'COMPLETED'
     and v_offer.consumed_by = p_user_id
     and v_opportunity.conversion_status = 'WON'
     and v_opportunity.student_id = p_user_id then
    return public.complete_enrollment_offer_pre_trial_lifecycle_impl(
      p_offer_id,
      p_user_id
    );
  end if;
  if v_opportunity.conversion_status <> 'OPEN' then
    return pg_catalog.jsonb_build_object(
      'success', false, 'error', 'OPPORTUNITY_CLOSED'
    );
  end if;
  if v_opportunity.feedback_required
     and not private.trial_feedback_is_complete(v_opportunity_id) then
    return pg_catalog.jsonb_build_object(
      'success', false, 'error', 'TRIAL_FEEDBACK_REQUIRED'
    );
  end if;
  if v_offer.revoked_at is not null
     or exists (
       select 1
       from public.enrollment_links as link
       where link.offer_id = p_offer_id
         and link.opportunity_id = v_opportunity_id
         and link.status = 'EXPIRED'
     ) then
    return pg_catalog.jsonb_build_object(
      'success', false, 'error', 'OFFER_REVOKED'
    );
  end if;

  return public.complete_enrollment_offer_pre_trial_lifecycle_impl(
    p_offer_id,
    p_user_id
  );
end;
$$;


--
-- Name: complete_enrollment_offer_pre_schedule_impl(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_enrollment_offer_pre_schedule_impl(p_offer_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  offer_row public.offers%rowtype;
  profile_row public.profiles%rowtype;
  payment_id text;
  payment_row public.student_payments%rowtype;
  payment_count integer;
  plan_duration integer;
  enrollment_payment_id text;
  profile_enrollment_payment_id text;
  offer_enrollment_payment_id text;
  enrollment_payment_uses_profile_fallback boolean := false;
  profile_fee_offer_binding_count integer := 0;
  subscription_activation_offer boolean := false;
  required_billing_payment_id text;
  expected_payment_value numeric;
  payment_ids text[] := array[]::text[];
begin
  select offer.* into offer_row
    from public.offers as offer
   where offer.id = p_offer_id
     and offer.kind = 'ENROLLMENT';
  if not found then
    return jsonb_build_object('success', false, 'error', 'OFFER_NOT_FOUND');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || offer_row.tenant_id || ':' ||
        p_user_id::text,
      0
    )
  );

  select offer.* into offer_row
    from public.offers as offer
   where offer.id = p_offer_id
     and offer.kind = 'ENROLLMENT'
   for update;
  if not found then
    return jsonb_build_object('success', false, 'error', 'OFFER_NOT_FOUND');
  end if;
  if not private.tenant_is_operational(offer_row.tenant_id) then
    return jsonb_build_object(
      'success', false,
      'error', 'TENANT_UNAVAILABLE'
    );
  end if;
  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_user_id
     and profile.tenant_id = offer_row.tenant_id
     and profile.role = 'STUDENT'
   for update;
  if not found
     or lower(trim(coalesce(profile_row.lifecycle_status, ''))) <> 'active'
     or (
       select count(*) from public.tenant_memberships as membership
        where membership.user_id = p_user_id
     ) <> 1
     or not exists (
       select 1 from public.tenant_memberships as membership
        where membership.user_id = p_user_id
          and membership.tenant_id = offer_row.tenant_id
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
     )
     or exists (
       select 1 from public.student_offboarding_operations as operation
        where operation.tenant_id = offer_row.tenant_id
          and operation.student_id = p_user_id
          and operation.status in (
            'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
            'UNKNOWN', 'BLOCKED'
          )
     )
     or exists (
       select 1 from public.student_account_deletion_claims as deletion
        where deletion.tenant_id = offer_row.tenant_id
          and deletion.student_id = p_user_id
          and deletion.status in (
            'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
            'UNKNOWN', 'BLOCKED'
          )
     )
  then
    return jsonb_build_object(
      'success', false,
      'error', 'STUDENT_LIFECYCLE_INACTIVE'
    );
  end if;

  plan_duration := coalesce(
    nullif(offer_row.payload ->> 'planDuration', '')::integer,
    1
  );
  profile_enrollment_payment_id := nullif(trim(coalesce(
    profile_row.enrollment_payment_id,
    ''
  )), '');
  offer_enrollment_payment_id := nullif(trim(coalesce(
    offer_row.metadata ->> 'enrollment_payment_id',
    ''
  )), '');
  subscription_activation_offer := greatest(
    coalesce(offer_row.enrollment_fee, 0), 0
  ) <= 0
    and (
      coalesce(
        nullif(trim(coalesce(
          offer_row.metadata ->> 'subscription_activation_payment_id',
          ''
        )), ''),
        nullif(trim(coalesce(
          offer_row.metadata ->> 'activation_payment_id',
          ''
        )), '')
      ) is not null
    );
  if offer_enrollment_payment_id is not null
     and profile_enrollment_payment_id is not null
     and offer_enrollment_payment_id <> profile_enrollment_payment_id
  then
    return jsonb_build_object(
      'success', false,
      'error', 'PAYMENT_BINDING_CHANGED'
    );
  end if;
  if offer_enrollment_payment_id is null
     and profile_enrollment_payment_id is not null
     and not subscription_activation_offer
  then
    select count(*) into profile_fee_offer_binding_count
      from public.offers as bound_offer
     where bound_offer.tenant_id = offer_row.tenant_id
       and bound_offer.kind = 'ENROLLMENT'
       and bound_offer.id <> p_offer_id
       and (
         bound_offer.processing_by = p_user_id
         or bound_offer.consumed_by = p_user_id
       )
       and nullif(trim(coalesce(
         bound_offer.metadata ->> 'enrollment_payment_id',
         ''
       )), '') = profile_enrollment_payment_id;
    if profile_fee_offer_binding_count <> 0 then
      return jsonb_build_object(
        'success', false,
        'error', 'PAYMENT_BINDING_CHANGED'
      );
    end if;
  end if;
  -- Offer metadata is authoritative for an offer-scoped fee. The profile is a
  -- compatibility fallback only for standalone/legacy fees with no offer id.
  enrollment_payment_id := coalesce(
    offer_enrollment_payment_id,
    profile_enrollment_payment_id
  );
  enrollment_payment_uses_profile_fallback :=
    offer_enrollment_payment_id is null
    and profile_enrollment_payment_id is not null;
  required_billing_payment_id := case
    when plan_duration = 0 then nullif(trim(coalesce(
      offer_row.metadata ->> 'one_time_payment_id',
      ''
    )), '')
    when offer_row.payload ->> 'enableProRata' = 'true'
      and coalesce(
            nullif(offer_row.payload ->> 'proRataValue', '')::numeric,
            0
          ) > 0
      then nullif(trim(coalesce(
        offer_row.metadata ->> 'pro_rata_charge_id',
        ''
      )), '')
    when greatest(coalesce(offer_row.enrollment_fee, 0), 0) <= 0
      then coalesce(
      nullif(trim(coalesce(
        offer_row.metadata ->> 'subscription_activation_payment_id',
        ''
      )), ''),
      nullif(trim(coalesce(
        offer_row.metadata ->> 'activation_payment_id',
        ''
      )), '')
    )
    else null
  end;

  if greatest(coalesce(offer_row.enrollment_fee, 0), 0) > 0
     and enrollment_payment_id is null
  then
    return jsonb_build_object(
      'success', false,
      'error', 'PAYMENT_EVENT_NOT_SETTLED'
    );
  elsif greatest(coalesce(offer_row.enrollment_fee, 0), 0) > 0 then
    payment_ids := pg_catalog.array_append(
      payment_ids,
      enrollment_payment_id
    );
  end if;
  if required_billing_payment_id is not null
     and required_billing_payment_id <> all(payment_ids)
  then
    payment_ids := pg_catalog.array_append(
      payment_ids,
      required_billing_payment_id
    );
  end if;
  if (
    plan_duration = 0
    or greatest(coalesce(offer_row.enrollment_fee, 0), 0) <= 0
    or (
      offer_row.payload ->> 'enableProRata' = 'true'
      and coalesce(
            nullif(offer_row.payload ->> 'proRataValue', '')::numeric,
            0
          ) > 0
    )
  ) and required_billing_payment_id is null then
    return jsonb_build_object(
      'success', false,
      'error', 'PAYMENT_EVENT_NOT_SETTLED'
    );
  end if;
  if enrollment_payment_id is not null
     and enrollment_payment_id = required_billing_payment_id
  then
    return jsonb_build_object(
      'success', false,
      'error', 'PAYMENT_BINDING_AMBIGUOUS'
    );
  end if;

  foreach payment_id in array payment_ids
  loop
    if payment_id is null then
      continue;
    end if;
    if exists (
      select 1
        from public.student_payments as payment
       where (
         nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = payment_id
         or nullif(trim(coalesce(payment.asaas_id, '')), '') = payment_id
       )
         and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') is not null
         and nullif(trim(coalesce(payment.asaas_id, '')), '') is not null
         and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') <>
             nullif(trim(coalesce(payment.asaas_id, '')), '')
    ) then
      return jsonb_build_object(
        'success', false,
        'error', 'PAYMENT_PROVIDER_ALIAS_DIVERGENCE'
      );
    end if;
    select count(*) into payment_count
      from public.student_payments as payment
     where nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = payment_id
        or nullif(trim(coalesce(payment.asaas_id, '')), '') = payment_id;
    if payment_count > 1 then
      return jsonb_build_object(
        'success', false,
        'error', 'PAYMENT_BINDING_AMBIGUOUS'
      );
    end if;
    if payment_count = 0 then
      return jsonb_build_object(
        'success', false,
        'error', 'PAYMENT_EVENT_NOT_PERSISTED'
      );
    end if;
    if payment_count = 1 then
      select payment.* into payment_row
        from public.student_payments as payment
       where nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = payment_id
          or nullif(trim(coalesce(payment.asaas_id, '')), '') = payment_id
       for update;
      expected_payment_value := case
        when payment_id = enrollment_payment_id
          then greatest(coalesce(offer_row.enrollment_fee, 0), 0)
        when payment_id = nullif(trim(coalesce(
               offer_row.metadata ->> 'pro_rata_charge_id',
               ''
             )), '')
          and offer_row.payload ->> 'enableProRata' = 'true'
          and coalesce(
                nullif(offer_row.payload ->> 'proRataValue', '')::numeric,
                0
              ) > 0
          then coalesce(
            nullif(offer_row.payload ->> 'proRataValue', '')::numeric,
            0
          )
        else coalesce(nullif(offer_row.payload ->> 'value', '')::numeric, 0)
      end;
      if payment_row.tenant_id is distinct from offer_row.tenant_id
         or payment_row.student_id is distinct from p_user_id
         or nullif(trim(coalesce(payment_row.provider_customer_id, '')), '')
           is distinct from nullif(trim(coalesce(
             profile_row.asaas_customer_id,
             ''
           )), '')
         or upper(trim(coalesce(payment_row.status, ''))) in (
           'REFUNDED', 'CANCELLED', 'DELETED', 'CHARGEBACK',
           'CHARGEBACK_REQUESTED', 'RECEIVED_IN_CASH_UNDONE'
         )
         or upper(trim(coalesce(payment_row.provider_status, ''))) in (
           'REFUNDED', 'CANCELLED', 'DELETED', 'CHARGEBACK',
           'CHARGEBACK_REQUESTED', 'RECEIVED_IN_CASH_UNDONE'
         )
         or not (
           upper(trim(coalesce(payment_row.status, ''))) in (
             'RECEIVED', 'RECEIVED_IN_CASH', 'PAGO'
           )
           or upper(trim(coalesce(payment_row.provider_status, ''))) in (
             'RECEIVED', 'RECEIVED_IN_CASH', 'PAGO'
           )
         )
         or round(coalesce(payment_row.value, 0), 2)
           is distinct from round(expected_payment_value, 2)
         or (
           payment_id = enrollment_payment_id
           and enrollment_payment_uses_profile_fallback
           and lower(trim(coalesce(
             payment_row.raw_payload #>> '{payment,externalReference}',
             ''
           ))) is distinct from
             'enrollment:' || p_offer_id::text || ':fee'
         )
      then
        return jsonb_build_object(
          'success', false,
          'error', 'PAYMENT_EVENT_NOT_SETTLED'
        );
      end if;
    end if;
  end loop;

  if offer_row.invite_security_version < 1 then
    return jsonb_build_object('success', false, 'error', 'OFFER_REVOKED');
  end if;
  if not private.tenant_is_operational(offer_row.tenant_id) then
    return jsonb_build_object('success', false, 'error', 'TENANT_UNAVAILABLE');
  end if;
  return public.complete_enrollment_offer_authoritative_impl(
    p_offer_id,
    p_user_id
  );
end;
$$;


--
-- Name: complete_enrollment_offer_pre_trial_lifecycle_impl(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_enrollment_offer_pre_trial_lifecycle_impl(p_offer_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_runtime_role text := coalesce((select auth.jwt() ->> 'role'), '');
  v_offer record;
  v_profile record;
  v_duration integer;
  v_pro_rata_value numeric;
  v_error_message text;
begin
  if v_runtime_role <> 'service_role' then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'FORBIDDEN'
    );
  end if;

  select
    offer.tenant_id,
    offer.payload,
    offer.metadata,
    offer.enrollment_fee,
    offer.processing_by,
    offer.processing_state,
    offer.consumed_by,
    offer.invite_security_version,
    offer.revoked_at
  into v_offer
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.kind = 'ENROLLMENT';
  if not found then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'OFFER_NOT_FOUND'
    );
  end if;
  if v_offer.invite_security_version < 1
    or v_offer.revoked_at is not null
    or not private.tenant_is_operational(v_offer.tenant_id)
  then
    return public.complete_enrollment_offer_pre_schedule_impl(
      p_offer_id,
      p_user_id
    );
  end if;
  if v_offer.processing_state = 'COMPLETED'
    and v_offer.consumed_by = p_user_id
  then
    return public.complete_enrollment_offer_pre_schedule_impl(
      p_offer_id,
      p_user_id
    );
  end if;

  begin
    perform private.assert_materialized_enrollment_schedule(
      p_offer_id,
      p_user_id
    );
  exception
    when exclusion_violation or check_violation
      or insufficient_privilege or unique_violation or deadlock_detected
  then
    get stacked diagnostics v_error_message = message_text;
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'SCHEDULE_UNAVAILABLE',
      'reason', v_error_message
    );
  end;

  -- A assercao acima bloqueia a oferta. Recarrega payload/metadata depois de
  -- qualquer writer anterior terminar para que IDs financeiros antigos nunca
  -- sejam usados na decisao de conclusao.
  select
    offer.tenant_id,
    offer.payload,
    offer.metadata,
    offer.enrollment_fee,
    offer.processing_by,
    offer.processing_state,
    offer.consumed_by,
    offer.invite_security_version,
    offer.revoked_at
  into v_offer
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.kind = 'ENROLLMENT'
  for update;
  if not found
    or v_offer.processing_by is distinct from p_user_id
    or v_offer.invite_security_version < 1
    or v_offer.revoked_at is not null
  then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'SCHEDULE_UNAVAILABLE'
    );
  end if;
  if not private.tenant_is_operational(v_offer.tenant_id) then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'TENANT_UNAVAILABLE'
    );
  end if;

  select
    profile.tenant_id,
    profile.asaas_customer_id,
    profile.subscription_id,
    profile.enrollment_payment_id,
    profile.enrollment_fee_paid
  into v_profile
  from public.profiles as profile
  where profile.id = p_user_id
  for update;
  if not found or v_profile.tenant_id is distinct from v_offer.tenant_id then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'PROFILE_INVALID'
    );
  end if;

  begin
    v_duration := coalesce(
      nullif(v_offer.payload ->> 'planDuration', '')::integer,
      1
    );
    v_pro_rata_value := case
      when v_offer.payload ->> 'enableProRata' = 'true' then coalesce(
        nullif(v_offer.payload ->> 'proRataValue', '')::numeric,
        0
      )
      else 0
    end;
  exception when others then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'BILLING_SCOPE_INVALID'
    );
  end;

  if v_offer.payload ->> 'proRataFormulaVersion'
       is distinct from 'weekly-frequency-times-4-v1'
    or v_offer.payload ->> 'proRataIntervalStartInclusive'
       is distinct from v_offer.payload ->> 'startDate'
    or v_offer.payload ->> 'proRataIntervalEndExclusive'
       is distinct from v_offer.payload ->> 'firstBillingDate'
    or v_offer.metadata ->> 'pro_rata_formula_version'
       is distinct from 'weekly-frequency-times-4-v1'
    or v_offer.metadata ->> 'pro_rata_interval_start_inclusive'
       is distinct from v_offer.payload ->> 'proRataIntervalStartInclusive'
    or v_offer.metadata ->> 'pro_rata_interval_end_exclusive'
       is distinct from v_offer.payload ->> 'proRataIntervalEndExclusive'
    or v_offer.metadata -> 'pro_rata_class_count'
       is distinct from v_offer.payload -> 'proRataClassCount'
    or v_offer.metadata -> 'price_per_class'
       is distinct from v_offer.payload -> 'pricePerClass'
    or v_offer.metadata -> 'pro_rata_value'
       is distinct from v_offer.payload -> 'proRataValue'
  then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'BILLING_SCOPE_INVALID'
    );
  end if;

  if v_offer.processing_by is distinct from p_user_id
    or v_offer.metadata ->> 'financial_profile_offer_id'
       is distinct from p_offer_id::text
    or nullif(v_profile.asaas_customer_id, '') is null
    or v_profile.asaas_customer_id
       is distinct from nullif(v_offer.metadata ->> 'asaas_customer_id', '')
  then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'CUSTOMER_SCOPE_PENDING'
    );
  end if;

  if nullif(v_profile.subscription_id, '')
       is distinct from nullif(v_offer.metadata ->> 'subscription_id', '')
  then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'SUBSCRIPTION_SCOPE_PENDING'
    );
  end if;

  if nullif(v_profile.enrollment_payment_id, '')
       is distinct from nullif(
         v_offer.metadata ->> 'enrollment_payment_id',
         ''
       )
  then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'ENROLLMENT_FEE_SCOPE_PENDING'
    );
  end if;

  if v_duration <> 0 and nullif(v_profile.subscription_id, '') is null then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'SUBSCRIPTION_SCOPE_PENDING'
    );
  end if;

  if coalesce(v_offer.enrollment_fee, 0) > 0 and (
    coalesce(v_profile.enrollment_fee_paid, false) is false
    or nullif(v_profile.enrollment_payment_id, '') is null
  ) then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'ENROLLMENT_FEE_SCOPE_PENDING'
    );
  end if;

  if v_pro_rata_value > 0
    and nullif(v_offer.metadata ->> 'pro_rata_charge_id', '') is null
  then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'PRO_RATA_CHARGE_PENDING'
    );
  end if;

  return public.complete_enrollment_offer_pre_schedule_impl(
    p_offer_id,
    p_user_id
  );
end;
$$;


--
-- Name: FUNCTION complete_enrollment_offer_pre_trial_lifecycle_impl(p_offer_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_enrollment_offer_pre_trial_lifecycle_impl(p_offer_id uuid, p_user_id uuid) IS 'Conclui matrícula somente com obrigações financeiras explicitamente habilitadas na oferta.';


--
-- Name: complete_learning_activity(uuid, integer, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_learning_activity(p_activity_id uuid, p_score integer DEFAULT 100, p_time_spent_seconds integer DEFAULT 0, p_evidence jsonb DEFAULT '{}'::jsonb, p_request_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.assert_active_student_learning_mutation();
  return public.complete_learning_activity_core(
    p_activity_id,
    p_score,
    p_time_spent_seconds,
    p_evidence,
    p_request_key
  );
end;
$$;


--
-- Name: complete_learning_activity_core(uuid, integer, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_learning_activity_core(p_activity_id uuid, p_score integer DEFAULT 100, p_time_spent_seconds integer DEFAULT 0, p_evidence jsonb DEFAULT '{}'::jsonb, p_request_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_student_id uuid := auth.uid();
  v_profile record;
  v_activity record;
  v_enrollment public.student_path_enrollments%rowtype;
  v_current record;
  v_existing_attempt public.student_learning_activity_attempts%rowtype;
  v_request_key text := nullif(
    pg_catalog.btrim(coalesce(p_request_key, '')),
    ''
  );
  v_evidence jsonb := coalesce(p_evidence, '{}'::jsonb) - 'completedAt';
  v_request_payload jsonb;
  v_progression jsonb;
  v_result jsonb;
  v_streak integer;
  v_wolfie_conversation_id uuid;
  v_wolfie_session record;
  v_passed boolean := coalesce(p_score >= 60, false);
  v_status text := case
    when coalesce(p_score >= 60, false) then 'COMPLETED'
    else 'IN_PROGRESS'
  end;
  v_now timestamptz := pg_catalog.now();
begin
  if v_student_id is null or p_activity_id is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  if p_score is null
     or p_score not between 0 and 100
     or p_time_spent_seconds is null
     or p_time_spent_seconds not between 0 and 86400
     or p_evidence is null
     or pg_catalog.jsonb_typeof(p_evidence) is distinct from 'object'
     or p_evidence = '{}'::jsonb
     or pg_catalog.pg_column_size(p_evidence) > 32768
     or v_request_key is null
     or pg_catalog.length(v_request_key) not between 8 and 180 then
    raise exception using
      errcode = '22023',
      message = 'invalid_learning_activity_completion';
  end if;

  v_request_payload := pg_catalog.jsonb_build_object(
    'score', p_score,
    'timeSpentSeconds', p_time_spent_seconds,
    'evidence', v_evidence
  );

  select profile.tenant_id, profile.role
    into v_profile
    from public.profiles as profile
   where profile.id = v_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  select
    activity.id,
    activity.unit_id,
    activity.type,
    unit.path_id,
    unit.skill_focus,
    path.tenant_id as path_tenant_id
    into v_activity
    from public.unit_activities as activity
    join public.learning_units as unit
      on unit.id = activity.unit_id
    join public.learning_paths as path
      on path.id = unit.path_id
   where activity.id = p_activity_id
     and activity.type not in ('quiz', 'grammar_drill', 'reading')
     and path.active is true
     and (
       path.tenant_id is null
       or path.tenant_id = v_profile.tenant_id
     );

  if not found then
    raise exception using
      errcode = '42501',
      message = 'learning_activity_not_available';
  end if;

  -- Legacy non-quiz runners are self-attested. Bind the evidence to the actual
  -- activity and score, but do not let this unverified score alter skill models.
  -- Rich, type-specific evidence can replace this transitional contract later.
  if v_evidence ->> 'activityType' is distinct from v_activity.type
     or coalesce((v_evidence ->> 'score') ~ '^[0-9]+$', false) is not true
     or (v_evidence ->> 'score')::integer <> p_score then
    raise exception using
      errcode = '22023',
      message = 'invalid_learning_activity_evidence';
  end if;

  if v_activity.type = 'speaking_wolfie'
     and (
       coalesce((v_evidence ->> 'learnerTurns') ~ '^[0-9]+$', false)
         is not true
       or pg_catalog.length(v_evidence ->> 'learnerTurns') > 4
       or (v_evidence ->> 'learnerTurns')::integer not between 2 and 1000
       or pg_catalog.jsonb_typeof(v_evidence -> 'sessionCompleted')
            is distinct from 'boolean'
       or (v_evidence ->> 'sessionCompleted')::boolean is not true
       or p_score not between 60 and 100
     ) then
    raise exception using
      errcode = '22023',
      message = 'invalid_speaking_activity_evidence';
  end if;

  if v_activity.type = 'speaking_wolfie' then
    begin
      v_wolfie_conversation_id :=
        (v_evidence ->> 'wolfieConversationId')::uuid;
    exception
      when invalid_text_representation then
        raise exception using
          errcode = '22023',
          message = 'invalid_speaking_activity_evidence';
    end;

    if v_wolfie_conversation_id is null then
      raise exception using
        errcode = '22023',
        message = 'invalid_speaking_activity_evidence';
    end if;

    v_evidence := pg_catalog.jsonb_set(
      v_evidence,
      '{wolfieConversationId}',
      pg_catalog.to_jsonb(v_wolfie_conversation_id::text),
      true
    );
    v_request_payload := pg_catalog.jsonb_build_object(
      'score', p_score,
      'timeSpentSeconds', p_time_spent_seconds,
      'evidence', v_evidence
    );

    select session.id, coalesce(session.turn_count, 0) as turn_count
      into v_wolfie_session
      from public.wolfie_sessions as session
     where session.id = v_wolfie_conversation_id
       and session.student_id = v_student_id
       and session.tenant_id = v_profile.tenant_id;

    if not found
       or v_wolfie_session.turn_count < 2
       or v_wolfie_session.turn_count <
            (v_evidence ->> 'learnerTurns')::integer then
      raise exception using
        errcode = '22023',
        message = 'invalid_speaking_activity_evidence';
    end if;
  end if;

  -- Resolve an exact request replay before requiring an ACTIVE enrollment. The
  -- first call may have completed the final activity and closed the enrollment
  -- even if its HTTP response never reached the client.
  if v_request_key is not null then
    select *
      into v_existing_attempt
      from public.student_learning_activity_attempts as attempt
     where attempt.student_id = v_student_id
       and attempt.request_key = v_request_key
     for update;

    if found then
      if v_existing_attempt.activity_id is distinct from p_activity_id
         or v_existing_attempt.attempt_kind <> 'COMPLETION'
         or v_existing_attempt.request_payload is distinct from v_request_payload then
        raise exception using
          errcode = '22023',
          message = 'idempotency_key_reused';
      end if;

      return v_existing_attempt.result || pg_catalog.jsonb_build_object(
        'alreadyApplied', true
      );
    end if;
  end if;

  if v_activity.type = 'speaking_wolfie'
     and exists (
       select 1
         from public.student_learning_activity_attempts as attempt
        where attempt.student_id = v_student_id
          and attempt.attempt_kind = 'COMPLETION'
          and attempt.activity_id is distinct from p_activity_id
          and pg_catalog.lower(
                attempt.request_payload #>>
                  '{evidence,wolfieConversationId}'
              ) =
                v_wolfie_conversation_id::text
     ) then
    raise exception using
      errcode = '22023',
      message = 'invalid_speaking_activity_evidence';
  end if;

  select *
    into v_enrollment
    from public.student_path_enrollments as enrollment
   where enrollment.student_id = v_student_id
     and enrollment.path_id = v_activity.path_id
     and enrollment.tenant_id = v_profile.tenant_id
     and enrollment.status = 'ACTIVE'
     and enrollment.completed_at is null
   for update;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'active_learning_enrollment_required';
  end if;

  select next_activity.activity_id, next_activity.unit_id
    into v_current
    from private.next_incomplete_learning_activity(
      v_student_id,
      v_activity.path_id
    ) as next_activity;

  if not found or v_current.activity_id <> p_activity_id then
    raise exception using
      errcode = 'P0001',
      message = 'learning_activity_not_current';
  end if;

  insert into public.student_activity_progress (
    student_id,
    activity_id,
    unit_id,
    status,
    score,
    attempts,
    time_spent_seconds,
    completed_at,
    last_attempt_at
  ) values (
    v_student_id,
    p_activity_id,
    v_activity.unit_id,
    v_status,
    p_score,
    1,
    p_time_spent_seconds,
    case when v_passed then v_now else null end,
    v_now
  )
  on conflict (student_id, activity_id) do update
    set status = case
          when excluded.status = 'COMPLETED' then 'COMPLETED'
          else 'IN_PROGRESS'
        end,
        score = greatest(
          coalesce(public.student_activity_progress.score, 0),
          excluded.score
        ),
        attempts =
          coalesce(public.student_activity_progress.attempts, 0) + 1,
        time_spent_seconds = least(
          2147483647,
          coalesce(public.student_activity_progress.time_spent_seconds, 0)
            + excluded.time_spent_seconds
        ),
        completed_at = case
          when excluded.status = 'COMPLETED' then coalesce(
            public.student_activity_progress.completed_at,
            v_now
          )
          else public.student_activity_progress.completed_at
        end,
        last_attempt_at = v_now;

  v_streak := private.record_student_learning_practice(
    v_student_id,
    p_score,
    'unverified_completion',
    array[]::text[],
    v_now
  );

  if v_passed then
    v_progression := private.advance_student_learning_enrollment(
      v_enrollment.id,
      v_student_id,
      v_activity.path_id,
      v_now
    );
  else
    v_progression := pg_catalog.jsonb_build_object(
      'nextActivityId', p_activity_id,
      'currentUnitId', v_activity.unit_id,
      'pathCompleted', false
    );
  end if;

  v_result := pg_catalog.jsonb_build_object(
    'activityId', p_activity_id,
    'score', p_score,
    'passed', v_passed,
    'status', v_status,
    'xpEarned', 0,
    'streakCount', v_streak,
    'alreadyApplied', false
  ) || v_progression;

  insert into public.student_learning_activity_attempts (
    tenant_id,
    student_id,
    enrollment_id,
    activity_id,
    attempt_kind,
    request_key,
    request_payload,
    score,
    passed,
    result,
    created_at
  ) values (
    v_profile.tenant_id,
    v_student_id,
    v_enrollment.id,
    p_activity_id,
    'COMPLETION',
    v_request_key,
    v_request_payload,
    p_score,
    v_passed,
    v_result,
    v_now
  );

  return v_result;
end;
$_$;


--
-- Name: FUNCTION complete_learning_activity_core(p_activity_id uuid, p_score integer, p_time_spent_seconds integer, p_evidence jsonb, p_request_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_learning_activity_core(p_activity_id uuid, p_score integer, p_time_spent_seconds integer, p_evidence jsonb, p_request_key text) IS 'Records the current non-quiz learning-path attempt without XP; a required request key makes pass/fail retries idempotent and scores below 60 do not advance.';


--
-- Name: complete_oral_test(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_oral_test(p_test_id uuid, p_score integer, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_tenant_id text;
  v_test public.oral_tests%rowtype;
begin
  if v_uid is null then
    raise exception
      using errcode = '28000', message = 'Authentication required';
  end if;
  if p_score is not null and (p_score < 0 or p_score > 10) then
    raise exception
      using errcode = '22023', message = 'Score must be between 0 and 10';
  end if;
  if char_length(coalesce(p_notes, '')) > 4000 then
    raise exception
      using errcode = '22023', message = 'Notes are too long';
  end if;

  select p.role, p.tenant_id
    into v_role, v_tenant_id
    from public.profiles as p
   where p.id = v_uid;

  select ot.*
    into v_test
    from public.oral_tests as ot
   where ot.id = p_test_id
   for update;

  if not found then
    raise exception
      using errcode = '42501', message = 'Oral test is unavailable';
  end if;
  if v_test.status in ('DONE', 'SKIPPED') then
    raise exception
      using errcode = '22023', message = 'Oral test is already closed';
  end if;

  if not (
    v_role = 'SUPER_ADMIN'
    or (
      v_role = 'SCHOOL_ADMIN'
      and v_tenant_id = v_test.tenant_id
    )
    or (
      v_role = 'TEACHER'
      and v_tenant_id = v_test.tenant_id
      and v_test.examiner_id = v_uid
      and v_test.native_teacher_id is distinct from v_uid
    )
  ) then
    raise exception
      using errcode = '42501', message = 'Caller cannot complete this oral test';
  end if;

  update public.oral_tests as ot
     set status = 'DONE',
         done_at = now(),
         score = p_score,
         notes = nullif(btrim(coalesce(p_notes, '')), '')
   where ot.id = v_test.id;

  return jsonb_build_object(
    'test_id', v_test.id,
    'status', 'DONE',
    'done_at', now()
  );
end;
$$;


--
-- Name: complete_student_complementary_activity(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_student_complementary_activity(p_activity_id uuid, p_evidence jsonb, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.assert_active_student_learning_mutation();
  return public.complete_student_complementary_activity_lifecycle_core(
    p_activity_id,
    p_evidence,
    p_request_key
  );
end;
$$;


--
-- Name: FUNCTION complete_student_complementary_activity(p_activity_id uuid, p_evidence jsonb, p_request_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_student_complementary_activity(p_activity_id uuid, p_evidence jsonb, p_request_key text) IS 'Server-authoritative complementary completion with canonical replay and consistent valid-practice streak semantics.';


--
-- Name: complete_student_complementary_activity_core(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_student_complementary_activity_core(p_activity_id uuid, p_evidence jsonb, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_student_id uuid := auth.uid();
  v_profile record;
  v_activity public.student_activities%rowtype;
  v_existing_attempt public.student_complementary_activity_attempts%rowtype;
  v_request_key text := pg_catalog.btrim(coalesce(p_request_key, ''));
  v_evidence jsonb := coalesce(p_evidence, '{}'::jsonb) - 'completedAt';
  v_content_json jsonb;
  v_questions jsonb;
  v_question jsonb;
  v_answer jsonb;
  v_question_id jsonb;
  v_checklist jsonb;
  v_expected_checklist jsonb;
  v_question_count integer;
  v_checklist_count integer;
  v_distinct_checklist_count integer;
  v_option_count integer;
  v_selected_index integer;
  v_correct_index integer;
  v_correct_count integer := 0;
  v_score integer;
  v_expected_question_id text;
  v_question_results jsonb := '[]'::jsonb;
  v_passed boolean;
  v_status text;
  v_streak integer;
  v_result jsonb;
  v_now timestamptz := pg_catalog.now();
  i integer;
begin
  if v_student_id is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  if p_activity_id is null
     or pg_catalog.length(v_request_key) not between 8 and 180
     or p_evidence is null
     or pg_catalog.jsonb_typeof(p_evidence) is distinct from 'object'
     or p_evidence = '{}'::jsonb
     or pg_catalog.pg_column_size(p_evidence) > 32768 then
    raise exception using
      errcode = '22023',
      message = 'invalid_complementary_activity_completion';
  end if;

  select
    profile.tenant_id,
    profile.role,
    coalesce(profile.streak_count, 0) as streak_count
    into v_profile
    from public.profiles as profile
   where profile.id = v_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  select *
    into v_activity
    from public.student_activities as activity
   where activity.id = p_activity_id
     and activity.student_id = v_student_id
     and activity.tenant_id = v_profile.tenant_id
   for update;

  if not found then
    raise exception using
      errcode = '42501',
      message = 'complementary_activity_not_owned';
  end if;

  select *
    into v_existing_attempt
    from public.student_complementary_activity_attempts as attempt
   where attempt.student_id = v_student_id
     and attempt.request_key = v_request_key
   for update;

  if found then
    if v_existing_attempt.activity_id <> p_activity_id
       or v_existing_attempt.evidence is distinct from v_evidence then
      raise exception using
        errcode = '22023',
        message = 'idempotency_key_reused';
    end if;

    return v_existing_attempt.result || pg_catalog.jsonb_build_object(
      'alreadyApplied', true
    );
  end if;

  if v_evidence ->> 'activityId' is distinct from p_activity_id::text
     or v_evidence ->> 'activityType' is distinct from v_activity.type
     or coalesce(v_evidence ->> 'contentMode', '')
          not in ('legacy', 'structured') then
    raise exception using
      errcode = '22023',
      message = 'invalid_complementary_activity_evidence';
  end if;

  begin
    v_content_json := v_activity.content::jsonb;
  exception
    when others then
      v_content_json := null;
  end;

  if v_evidence ->> 'contentMode' = 'structured'
     and pg_catalog.jsonb_typeof(v_content_json) is distinct from 'object' then
    raise exception using
      errcode = '22023',
      message = 'invalid_complementary_activity_evidence';
  elsif v_evidence ->> 'contentMode' = 'legacy'
        and pg_catalog.jsonb_typeof(v_content_json) = 'object' then
    raise exception using
      errcode = '22023',
      message = 'invalid_complementary_activity_evidence';
  end if;

  if v_evidence ->> 'contentMode' = 'structured'
     and v_activity.type in ('quiz', 'grammar') then
    v_questions := case v_activity.type
      when 'grammar' then v_content_json -> 'exercises'
      else v_content_json -> 'questions'
    end;

    if pg_catalog.jsonb_typeof(v_questions) is distinct from 'array' then
      raise exception using
        errcode = '22023',
        message = 'invalid_complementary_activity_evidence';
    end if;

    v_question_count := pg_catalog.jsonb_array_length(v_questions);
    if v_question_count not between 1 and 20
       or pg_catalog.jsonb_typeof(v_evidence -> 'answers')
            is distinct from 'array'
       or pg_catalog.jsonb_array_length(v_evidence -> 'answers')
            <> v_question_count
       or pg_catalog.jsonb_typeof(v_evidence -> 'questionIds')
            is distinct from 'array'
       or pg_catalog.jsonb_array_length(v_evidence -> 'questionIds')
            <> v_question_count
       or v_evidence ? 'questionResults'
       or v_evidence ? 'scorePercentage' then
      raise exception using
        errcode = '22023',
        message = 'invalid_complementary_activity_evidence';
    end if;

    for i in 0 .. v_question_count - 1 loop
      v_question := v_questions -> i;
      v_answer := v_evidence -> 'answers' -> i;
      v_question_id := v_evidence -> 'questionIds' -> i;
      v_expected_question_id := coalesce(
        nullif(pg_catalog.btrim(v_question ->> 'id'), ''),
        'question-' || (i + 1)::text
      );

      if pg_catalog.jsonb_typeof(v_question) is distinct from 'object'
         or pg_catalog.jsonb_typeof(v_question -> 'options')
              is distinct from 'array'
         or coalesce(
              coalesce(
                v_question ->> 'correct',
                v_question ->> 'correctIndex',
                v_question ->> 'correct_option_index'
              ) ~ '^[0-9]+$',
              false
            ) is not true
         or pg_catalog.jsonb_typeof(v_answer) is distinct from 'number'
         or v_answer::text !~ '^[0-9]+$'
         or pg_catalog.length(v_answer::text) > 2
         or pg_catalog.jsonb_typeof(v_question_id) is distinct from 'string'
         or v_question_id #>> '{}' is distinct from v_expected_question_id then
        raise exception using
          errcode = '22023',
          message = 'invalid_complementary_activity_evidence';
      end if;

      v_option_count := pg_catalog.jsonb_array_length(v_question -> 'options');
      v_selected_index := v_answer::text::integer;
      v_correct_index := coalesce(
        v_question ->> 'correct',
        v_question ->> 'correctIndex',
        v_question ->> 'correct_option_index'
      )::integer;

      if v_option_count < 2
         or v_selected_index >= v_option_count
         or v_correct_index >= v_option_count
         or v_selected_index < 0
         or v_correct_index < 0 then
        raise exception using
          errcode = '22023',
          message = 'invalid_complementary_activity_evidence';
      end if;

      if v_selected_index = v_correct_index then
        v_correct_count := v_correct_count + 1;
      end if;

      v_question_results := v_question_results || pg_catalog.jsonb_build_array(
        pg_catalog.jsonb_build_object(
          'questionId', v_expected_question_id,
          'selectedIndex', v_selected_index,
          'correct', v_selected_index = v_correct_index,
          'correctIndex', v_correct_index,
          'explanation', coalesce(
            nullif(pg_catalog.btrim(v_question ->> 'exp'), ''),
            nullif(pg_catalog.btrim(v_question ->> 'explanation'), ''),
            nullif(pg_catalog.btrim(v_question ->> 'explanation_pt'), ''),
            nullif(pg_catalog.btrim(v_question ->> 'feedback'), '')
          )
        )
      );
    end loop;

    v_score := pg_catalog.round(
      (v_correct_count::numeric / v_question_count::numeric) * 100
    );
    v_passed := v_score >= 60;
  else
    if v_evidence ? 'answers'
       or v_evidence ? 'questionIds'
       or v_evidence ? 'questionResults'
       or v_evidence ? 'scorePercentage'
       or not private.learning_text_array_is_valid(
         v_evidence -> 'checklistCompleted',
         1,
         12,
         500
       )
       or pg_catalog.length(
            pg_catalog.btrim(coalesce(v_evidence ->> 'reflection', ''))
          ) not between 20 and 1200 then
      raise exception using
        errcode = '22023',
        message = 'invalid_complementary_activity_evidence';
    end if;

    select
      pg_catalog.jsonb_agg(
        pg_catalog.to_jsonb(
          pg_catalog.btrim(item.value #>> '{}')
        )
        order by item.ordinality
      ),
      pg_catalog.count(*)::integer,
      pg_catalog.count(
        distinct pg_catalog.lower(
          pg_catalog.btrim(item.value #>> '{}')
        )
      )::integer
      into
        v_checklist,
        v_checklist_count,
        v_distinct_checklist_count
      from pg_catalog.jsonb_array_elements(
        v_evidence -> 'checklistCompleted'
      ) with ordinality as item(value, ordinality);

    if v_distinct_checklist_count <> v_checklist_count then
      raise exception using
        errcode = '22023',
        message = 'invalid_complementary_activity_evidence';
    end if;

    if v_evidence ->> 'contentMode' = 'structured' then
      v_expected_checklist := case
        when pg_catalog.jsonb_typeof(v_content_json -> 'checklist') = 'array'
             and pg_catalog.jsonb_array_length(
                   v_content_json -> 'checklist'
                 ) > 0 then v_content_json -> 'checklist'
        when pg_catalog.jsonb_typeof(v_content_json -> 'steps') = 'array'
             and pg_catalog.jsonb_array_length(
                   v_content_json -> 'steps'
                 ) > 0 then v_content_json -> 'steps'
        when pg_catalog.jsonb_typeof(v_content_json -> 'preparation') = 'array'
             and pg_catalog.jsonb_array_length(
                   v_content_json -> 'preparation'
                 ) > 0 then v_content_json -> 'preparation'
        else null
      end;

      if not private.learning_text_array_is_valid(
        v_expected_checklist,
        1,
        12,
        500
      ) then
        raise exception using
          errcode = '22023',
          message = 'invalid_complementary_activity_evidence';
      end if;

      select pg_catalog.jsonb_agg(
               pg_catalog.to_jsonb(
                 pg_catalog.btrim(item.value #>> '{}')
               )
               order by item.ordinality
             )
        into v_expected_checklist
        from pg_catalog.jsonb_array_elements(v_expected_checklist)
             with ordinality as item(value, ordinality);

      if v_checklist is distinct from v_expected_checklist then
        raise exception using
          errcode = '22023',
          message = 'invalid_complementary_activity_evidence';
      end if;
    end if;

    -- Legacy free-text activities have no server-authored checklist to match;
    -- they still receive the strict bounded/nonempty/distinct evidence guard.
    v_score := null;
    v_passed := true;
  end if;

  if v_activity.status = 'COMPLETED' then
    return pg_catalog.jsonb_build_object(
      'activityId', v_activity.id,
      'status', v_activity.status,
      'passed', true,
      'scorePercentage', null,
      'questionResults', '[]'::jsonb,
      'completedAt', v_activity.completed_at,
      'alreadyApplied', true,
      'evidenceAccepted', true,
      'streakCount', coalesce(v_profile.streak_count, 0),
      'xpEarned', 0
    );
  end if;

  if v_activity.status <> 'PENDING' then
    raise exception using
      errcode = 'P0001',
      message = 'complementary_activity_not_pending';
  end if;

  v_status := case when v_passed then 'COMPLETED' else 'PENDING' end;

  if v_passed then
    update public.student_activities
       set status = 'COMPLETED',
           completion_evidence = v_evidence,
           completion_request_key = v_request_key,
           completed_by = v_student_id,
           completed_at = v_now,
           updated_at = v_now
     where id = p_activity_id
    returning * into v_activity;

    -- Only the first successful completion updates the practice clock/streak.
    -- Objective quiz/grammar scores are server-derived; reflective activities
    -- intentionally use an unmapped type so no skill score is fabricated.
    v_streak := private.record_student_learning_practice(
      v_student_id,
      coalesce(v_score, 0),
      case v_activity.type
        when 'quiz' then 'quiz'
        when 'grammar' then 'grammar_drill'
        else 'complementary_completion'
      end,
      array[]::text[],
      v_now
    );
  else
    v_streak := coalesce(v_profile.streak_count, 0);
  end if;

  v_result := pg_catalog.jsonb_build_object(
    'activityId', v_activity.id,
    'status', v_status,
    'passed', v_passed,
    'scorePercentage', v_score,
    'questionResults', v_question_results,
    'completedAt', case when v_passed then v_activity.completed_at else null end,
    'alreadyApplied', false,
    'evidenceAccepted', true,
    'streakCount', v_streak,
    'xpEarned', 0
  );

  insert into public.student_complementary_activity_attempts (
    tenant_id,
    student_id,
    activity_id,
    request_key,
    evidence,
    score,
    passed,
    result,
    created_at
  ) values (
    v_profile.tenant_id,
    v_student_id,
    p_activity_id,
    v_request_key,
    v_evidence,
    v_score,
    v_passed,
    v_result,
    v_now
  );

  return v_result;
end;
$_$;


--
-- Name: FUNCTION complete_student_complementary_activity_core(p_activity_id uuid, p_evidence jsonb, p_request_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_student_complementary_activity_core(p_activity_id uuid, p_evidence jsonb, p_request_key text) IS 'Server-grades objective complementary evidence, pass-gates completion, records practice once, and awards no XP.';


--
-- Name: complete_student_complementary_activity_lifecycle_core(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_student_complementary_activity_lifecycle_core(p_activity_id uuid, p_evidence jsonb, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_id uuid := auth.uid();
  v_request_key text := pg_catalog.btrim(coalesce(p_request_key, ''));
  v_profile record;
  v_activity public.student_activities%rowtype;
  v_existing_attempt public.student_complementary_activity_attempts%rowtype;
  v_result jsonb;
  v_canonical_result jsonb;
  v_evidence jsonb := coalesce(p_evidence, '{}'::jsonb) - 'completedAt';
  v_activity_type text;
  v_streak integer;
  v_now timestamptz := pg_catalog.now();
begin
  if v_student_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if p_activity_id is null
     or pg_catalog.length(v_request_key) not between 8 and 180
     or p_evidence is null
     or pg_catalog.jsonb_typeof(p_evidence) is distinct from 'object'
     or p_evidence = '{}'::jsonb
     or pg_catalog.pg_column_size(p_evidence) > 32768 then
    raise exception using
      errcode = '22023',
      message = 'invalid_complementary_activity_completion';
  end if;

  select
    profile.tenant_id,
    profile.role,
    profile.lifecycle_status,
    profile.status,
    coalesce(profile.streak_count, 0) as streak_count
    into v_profile
    from public.profiles as profile
   where profile.id = v_student_id
   for update;
  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null
     or pg_catalog.lower(pg_catalog.btrim(coalesce(
          v_profile.lifecycle_status,
          'active'
        ))) <> 'active'
     or pg_catalog.lower(pg_catalog.btrim(coalesce(
          v_profile.status,
          'Ativo'
        ))) in ('inativo', 'inactive', 'arquivado', 'cancelado', 'trancado') then
    raise exception using
      errcode = '42501',
      message = 'inactive_student_learning_mutation_forbidden';
  end if;

  select *
    into v_activity
    from public.student_activities as activity
   where activity.id = p_activity_id
     and activity.student_id = v_student_id
     and activity.tenant_id = v_profile.tenant_id
   for update;
  if not found then
    raise exception using
      errcode = '42501',
      message = 'complementary_activity_not_owned';
  end if;

  -- Preserve strict same-key idempotency before resolving a stale completed
  -- tab with a different key.
  select *
    into v_existing_attempt
    from public.student_complementary_activity_attempts as attempt
   where attempt.student_id = v_student_id
     and attempt.request_key = v_request_key
   for update;
  if found then
    if v_existing_attempt.activity_id <> p_activity_id
       or v_existing_attempt.evidence is distinct from v_evidence then
      raise exception using errcode = '22023', message = 'idempotency_key_reused';
    end if;
    return v_existing_attempt.result || pg_catalog.jsonb_build_object(
      'alreadyApplied', true,
      'canonicalResultAvailable', true
    );
  end if;

  if v_activity.status = 'COMPLETED' then
    select attempt.result
      into v_canonical_result
      from public.student_complementary_activity_attempts as attempt
     where attempt.student_id = v_student_id
       and attempt.activity_id = p_activity_id
       and attempt.passed is true
     order by
       (attempt.request_key = v_activity.completion_request_key) desc,
       attempt.created_at desc,
       attempt.id desc
     limit 1;

    if v_canonical_result is not null then
      return v_canonical_result || pg_catalog.jsonb_build_object(
        'alreadyApplied', true,
        'canonicalResultAvailable', true
      );
    end if;

    return pg_catalog.jsonb_build_object(
      'activityId', v_activity.id,
      'status', 'COMPLETED',
      'passed', true,
      'scorePercentage', null,
      'questionResults', '[]'::jsonb,
      'completedAt', v_activity.completed_at,
      'alreadyApplied', true,
      'evidenceAccepted', false,
      'canonicalResultAvailable', false,
      'streakCount', v_profile.streak_count,
      'xpEarned', 0
    );
  end if;

  v_result := public.complete_student_complementary_activity_core(
    p_activity_id,
    p_evidence,
    v_request_key
  );

  if coalesce((v_result ->> 'alreadyApplied')::boolean, false)
     and coalesce((v_result ->> 'passed')::boolean, false)
     and (
       not (v_result ? 'scorePercentage')
       or v_result -> 'scorePercentage' = 'null'::jsonb
     ) then
    select attempt.result
      into v_canonical_result
      from public.student_complementary_activity_attempts as attempt
     where attempt.student_id = v_student_id
       and attempt.activity_id = p_activity_id
       and attempt.passed is true
     order by attempt.created_at desc, attempt.id desc
     limit 1;

    if v_canonical_result is not null then
      v_result := v_canonical_result || pg_catalog.jsonb_build_object(
        'alreadyApplied', true,
        'canonicalResultAvailable', true
      );
    end if;
  end if;

  if not coalesce((v_result ->> 'alreadyApplied')::boolean, false)
     and not coalesce((v_result ->> 'passed')::boolean, false) then
    v_activity_type := v_activity.type;

    if v_activity_type in ('quiz', 'grammar') then
      v_streak := private.record_student_learning_practice(
        v_student_id,
        coalesce(nullif(v_result ->> 'scorePercentage', '')::integer, 0),
        case v_activity_type
          when 'grammar' then 'grammar_drill'
          else 'quiz'
        end,
        array[]::text[],
        v_now
      );
      v_result := v_result || pg_catalog.jsonb_build_object(
        'streakCount', v_streak
      );

      update public.student_complementary_activity_attempts as attempt
         set result = v_result
       where attempt.student_id = v_student_id
         and attempt.activity_id = p_activity_id
         and attempt.request_key = v_request_key;
    end if;
  end if;

  return v_result;
end;
$$;


--
-- Name: FUNCTION complete_student_complementary_activity_lifecycle_core(p_activity_id uuid, p_evidence jsonb, p_request_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_student_complementary_activity_lifecycle_core(p_activity_id uuid, p_evidence jsonb, p_request_key text) IS 'Server-authoritative complementary completion with canonical replay and consistent valid-practice streak semantics.';


--
-- Name: complete_teacher_offboarding(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_teacher_offboarding(p_teacher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  caller_id uuid := (SELECT auth.uid());
  caller_tenant text;
  caller_role text;
  remaining_count integer;
  active_membership_count integer;
  cancelled_notification_count integer := 0;
  invalidated_session_count integer := 0;
BEGIN
  caller_tenant := private.active_tenant_id(caller_id);
  caller_role := private.active_tenant_role(caller_id);

  IF caller_id IS NULL
    OR caller_tenant IS NULL
    OR caller_role NOT IN ('SCHOOL_ADMIN', 'SUPER_ADMIN')
  THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;

  -- Serializa duas tentativas administrativas para o mesmo professor e mantém
  -- a verificação abaixo coerente com a transição de lifecycle.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('teacher-offboarding:' || p_teacher_id::text, 0)
  );

  IF NOT EXISTS (
    SELECT 1
    FROM public.tenant_memberships AS membership
    WHERE membership.user_id = p_teacher_id
      AND membership.tenant_id = caller_tenant
      AND membership.role = 'TEACHER'
      AND membership.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'teacher_scope_denied' USING ERRCODE = '42501';
  END IF;

  SELECT count(*)
  INTO remaining_count
  FROM public.bookings AS booking
  WHERE booking.teacher_id = p_teacher_id
    AND booking.tenant_id = caller_tenant
    AND booking.status IS DISTINCT FROM 'CANCELLED';

  IF remaining_count > 0 THEN
    RETURN jsonb_build_object(
      'status', 'PENDING_REASSIGN',
      'remaining', remaining_count,
      'message', 'Ainda ha aulas ativas para reatribuir.'
    );
  END IF;

  UPDATE public.tenant_memberships
  SET status = 'REVOKED',
      is_primary = false,
      updated_at = now()
  WHERE user_id = p_teacher_id
    AND tenant_id = caller_tenant
    AND role = 'TEACHER'
    AND status = 'ACTIVE';

  -- Uma mensagem já aceita pelo provedor não pode ser recolhida. As que ainda
  -- pertencem à fila local, inclusive leases em processamento, deixam de ser
  -- elegíveis para retry e ficam observáveis como suprimidas pelo desligamento.
  UPDATE public.notification_queue
  SET status = 'skipped',
      last_error = 'teacher_offboarded',
      updated_at = now()
  WHERE tenant_id = caller_tenant
    AND teacher_id = p_teacher_id
    AND status IN ('pending', 'processing');
  GET DIAGNOSTICS cancelled_notification_count = ROW_COUNT;

  SELECT count(*)
  INTO active_membership_count
  FROM public.tenant_memberships AS membership
  WHERE membership.user_id = p_teacher_id
    AND membership.status = 'ACTIVE';

  IF active_membership_count = 0 THEN
    DELETE FROM public.tenant_user_contexts
    WHERE user_id = p_teacher_id;

    UPDATE public.profiles
    SET status = 'Inativo',
        lifecycle_status = 'offboarded',
        offboarding_status = 'COMPLETED',
        offboarding_completed_at = now(),
        date_automation_enabled = false
    WHERE id = p_teacher_id;
  ELSE
    -- lifecycle_status é global ao usuário. Se ele ainda trabalha em outra
    -- escola, preservamos o estado ativo e apenas trocamos o contexto revogado.
    UPDATE public.tenant_user_contexts AS context
    SET tenant_id = replacement.tenant_id,
        updated_at = now()
    FROM (
      SELECT membership.tenant_id
      FROM public.tenant_memberships AS membership
      WHERE membership.user_id = p_teacher_id
        AND membership.status = 'ACTIVE'
      ORDER BY membership.is_primary DESC, membership.created_at, membership.id
      LIMIT 1
    ) AS replacement
    WHERE context.user_id = p_teacher_id
      AND context.tenant_id = caller_tenant;
  END IF;

  -- Equivale ao sign-out global no lado persistido do GoTrue: refresh tokens
  -- ligados às sessões são removidos por cascata. O SQL dinâmico mantém a
  -- migration reaplicável em ambientes de validação sem o schema Auth.
  IF active_membership_count = 0
     AND pg_catalog.to_regclass('auth.sessions') IS NOT NULL THEN
    EXECUTE 'DELETE FROM auth.sessions WHERE user_id = $1'
      USING p_teacher_id;
    GET DIAGNOSTICS invalidated_session_count = ROW_COUNT;
  END IF;

  RETURN jsonb_build_object(
    'status', 'COMPLETED',
    'remainingActiveMemberships', active_membership_count,
    'notificationsCancelled', cancelled_notification_count,
    'sessionsInvalidated', invalidated_session_count,
    'accountAccessRevoked', active_membership_count = 0
  );
END;
$_$;


--
-- Name: confirm_my_class_log(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_my_class_log(p_class_log_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  c public.class_logs%rowtype;
begin
  if v_uid is null or p_class_log_id is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  select cl.*
    into c
    from public.class_logs cl
   where cl.id = p_class_log_id
     and cl.student_id = v_uid
   for update;

  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'nao_encontrado');
  end if;

  if coalesce(c.student_confirmed, false) then
    return pg_catalog.jsonb_build_object('ok', true, 'already', true);
  end if;

  update public.class_logs cl
     set student_confirmed = true
   where cl.id = c.id;

  return pg_catalog.jsonb_build_object('ok', true, 'already', false);
end;
$$;


--
-- Name: confirm_vendor_commission_on_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_vendor_commission_on_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('RECEIVED','RECEIVED_IN_CASH') AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    UPDATE vendor_commissions
       SET status='CONFIRMED', confirmed_at=COALESCE(confirmed_at, now())
     WHERE student_id = NEW.student_id AND status='PENDING';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: confirm_vendor_trial_interest_atomic(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_vendor_trial_interest_atomic(p_link_token text, p_legacy_opportunity_id uuid, p_confirm boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_runtime_role text := coalesce((select auth.jwt() ->> 'role'), '');
  v_result jsonb;
  v_opportunity_id uuid;
  v_opportunity public.opportunities%rowtype;
  v_request private.vendor_trial_teacher_requests%rowtype;
  v_teacher public.profiles%rowtype;
  v_tenant public.tenants%rowtype;
  v_destination text;
  v_message text;
  v_claim_url text;
begin
  if v_runtime_role <> 'service_role' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'forbidden'
    );
  end if;
  v_result := public.confirm_vendor_trial_interest_pre_outbox_impl(
    p_link_token,
    p_legacy_opportunity_id,
    p_confirm
  );
  if coalesce((v_result ->> 'ok')::boolean, false) is not true
     or coalesce((v_result ->> 'newlyRequested')::boolean, false) is not true
     or p_confirm is not true then
    return v_result;
  end if;

  v_opportunity_id := (v_result ->> 'opportunityId')::uuid;
  select opportunity.*
  into v_opportunity
  from public.opportunities as opportunity
  where opportunity.id = v_opportunity_id
  for update;
  select request.*
  into v_request
  from private.vendor_trial_teacher_requests as request
  where request.opportunity_id = v_opportunity.id
  for update;
  select profile.*
  into v_teacher
  from public.profiles as profile
  where profile.id = v_request.target_teacher_id;
  select tenant.*
  into v_tenant
  from public.tenants as tenant
  where tenant.id = v_opportunity.tenant_id;

  if v_request.status <> 'AWAITING_TEACHER'
     or v_request.tenant_id <> v_opportunity.tenant_id
     or v_teacher.tenant_id <> v_opportunity.tenant_id
     or v_tenant.id <> v_opportunity.tenant_id then
    raise exception 'trial_teacher_outbox_binding_changed'
      using errcode = '40001';
  end if;

  v_destination := coalesce(
    private.normalize_notification_phone(v_teacher.phone),
    ''
  );
  v_claim_url := private.secure_trial_portal_origin(v_opportunity.tenant_id)
    || '/claim-opportunity?id=' || v_opportunity.id::text
    || '&g=' || v_opportunity.claim_generation::text;
  v_message := 'Nova solicitação individual de aula experimental — '
    || private.safe_notification_text(v_tenant.name, 120) || '.' || E'\n'
    || 'Horário pedido: '
    || pg_catalog.to_char(
      v_request.slot_start at time zone 'America/Sao_Paulo',
      'DD/MM/YYYY "às" HH24:MI'
    ) || '.' || E'\n'
    || 'Confirme somente se puder atender. Nenhuma aula foi agendada ainda:'
    || E'\n' || v_claim_url;

  insert into public.notification_queue (
    tenant_id,
    teacher_id,
    student_name,
    student_phone,
    message_body,
    scheduled_for,
    status,
    delivery_status,
    next_attempt_at,
    notification_kind,
    source_id,
    source_type,
    class_date,
    idempotency_key
  ) values (
    v_opportunity.tenant_id,
    v_teacher.id,
    v_opportunity.student_name,
    v_destination,
    v_message,
    pg_catalog.now(),
    'pending',
    'queued',
    pg_catalog.now(),
    'TRIAL_TEACHER_REQUESTED',
    v_opportunity.id,
    'TRIAL_OPPORTUNITY',
    (v_request.slot_start at time zone 'America/Sao_Paulo')::date,
    'trial-teacher-requested:' || v_opportunity.id::text || ':'
      || v_opportunity.claim_generation::text
  )
  on conflict (tenant_id, idempotency_key)
    where idempotency_key is not null
  do nothing;

  return v_result;
end;
$$;


--
-- Name: confirm_vendor_trial_interest_pre_outbox_impl(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_vendor_trial_interest_pre_outbox_impl(p_link_token text, p_legacy_opportunity_id uuid, p_confirm boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_link_id uuid;
  v_lookup_opportunity_id uuid;
  v_link public.enrollment_links%rowtype;
  v_opportunity public.opportunities%rowtype;
  v_request private.vendor_trial_teacher_requests%rowtype;
  v_appointment public.appointments%rowtype;
  v_teacher_name text;
  v_vendor_id uuid;
  v_slot_start timestamptz;
  v_conflict boolean;
  v_base jsonb;
begin
  if p_confirm is null
     or p_legacy_opportunity_id is not null
     or nullif(trim(coalesce(p_link_token, '')), '') is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_lookup');
  end if;
  if p_link_token is not null
     and (
       length(trim(p_link_token)) not between 20 and 512
       or trim(p_link_token) !~ '^[A-Za-z0-9._~-]+$'
     ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_lookup');
  end if;

  select link.id, link.opportunity_id
    into v_link_id, v_lookup_opportunity_id
    from public.enrollment_links as link
   where link.link_token = trim(p_link_token)
     and link.purpose = 'TRIAL_CONFIRMATION'
     and link.offer_id is null
   limit 1;

  if v_link_id is null or v_lookup_opportunity_id is null then
    return jsonb_build_object('ok', false, 'error', 'link_not_found');
  end if;

  -- Match the canonical lock order: opportunity before dependent records.
  select opportunity.*
    into v_opportunity
    from public.opportunities as opportunity
   where opportunity.id = v_lookup_opportunity_id
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'link_not_found');
  end if;

  select link.*
    into v_link
    from public.enrollment_links as link
   where link.id = v_link_id
     and link.opportunity_id = v_opportunity.id
   for update;

  if not found
     or v_link.tenant_id is distinct from v_opportunity.tenant_id
     or v_link.purpose <> 'TRIAL_CONFIRMATION'
     or v_link.offer_id is not null then
    return jsonb_build_object('ok', false, 'error', 'link_inconsistent');
  end if;

  select request.*
    into v_request
    from private.vendor_trial_teacher_requests as request
   where request.opportunity_id = v_opportunity.id
     and request.enrollment_link_id = v_link.id
     and request.tenant_id = v_opportunity.tenant_id
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'link_inconsistent');
  end if;
  if not private.tenant_is_operational(v_opportunity.tenant_id) then
    return jsonb_build_object('ok', false, 'error', 'tenant_not_operational');
  end if;
  if v_link.status = 'EXPIRED'
     or v_request.status = 'EXPIRED'
     or v_link.expires_at <= now()
     or v_request.slot_start <= now() + interval '5 minutes' then
    return jsonb_build_object('ok', false, 'error', 'link_expired');
  end if;
  if v_link.status = 'PROCESSING'
     or v_request.status = 'CANCELED' then
    return jsonb_build_object('ok', false, 'error', 'link_unavailable');
  end if;

  select profile.full_name
    into v_teacher_name
    from public.profiles as profile
    join public.tenant_memberships as membership
      on membership.user_id = profile.id
     and membership.tenant_id = v_opportunity.tenant_id
     and membership.role = 'TEACHER'
     and membership.status = 'ACTIVE'
   where profile.id = v_request.target_teacher_id
     and v_link.professor_id = profile.id
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
   for share of profile, membership;

  if not found then
    return jsonb_build_object(
      'ok', false, 'error', 'teacher_not_active_for_tenant'
    );
  end if;

  v_vendor_id := coalesce(
    v_request.requested_by,
    v_link.created_by_vendor_id,
    v_opportunity.created_by_vendor_id
  );
  if (
    v_request.requested_by is not null
    and v_request.requested_by <> v_vendor_id
  ) or (
    v_link.created_by_vendor_id is not null
    and v_link.created_by_vendor_id <> v_vendor_id
  ) or (
    v_opportunity.created_by_vendor_id is not null
    and v_opportunity.created_by_vendor_id <> v_vendor_id
  ) or v_vendor_id is null
     or not exists (
       select 1
         from public.tenant_memberships as membership
         join public.profiles as profile
           on profile.id = membership.user_id
        where membership.user_id = v_vendor_id
          and membership.tenant_id = v_opportunity.tenant_id
          and membership.role in ('SALESPERSON', 'COMMERCIAL')
          and membership.status = 'ACTIVE'
          and lower(trim(coalesce(profile.lifecycle_status, 'active'))) = 'active'
     ) then
    return jsonb_build_object('ok', false, 'error', 'vendor_tenant_mismatch');
  end if;

  if v_opportunity.student_id is not null
     and not exists (
       select 1
         from public.tenant_memberships as membership
         join public.profiles as profile
           on profile.id = membership.user_id
        where membership.user_id = v_opportunity.student_id
          and membership.tenant_id = v_opportunity.tenant_id
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
          and lower(trim(coalesce(profile.lifecycle_status, 'active'))) = 'active'
     ) then
    return jsonb_build_object('ok', false, 'error', 'student_tenant_mismatch');
  end if;

  begin
    if coalesce(v_opportunity.slots_proposed #>> '{0,start_time}', '') !~
       '(?:[zZ]|[+-][0-9]{2}:[0-9]{2})$' then
      return jsonb_build_object('ok', false, 'error', 'link_inconsistent');
    end if;
    v_slot_start :=
      (v_opportunity.slots_proposed #>> '{0,start_time}')::timestamptz;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      return jsonb_build_object('ok', false, 'error', 'link_inconsistent');
  end;
  if v_slot_start is distinct from v_request.slot_start then
    return jsonb_build_object('ok', false, 'error', 'link_inconsistent');
  end if;

  v_base := jsonb_build_object(
    'ok', true,
    'tenantId', v_opportunity.tenant_id,
    'opportunityId', v_opportunity.id,
    'teacherId', v_request.target_teacher_id,
    'studentName', coalesce(v_link.student_name, v_opportunity.student_name),
    'teacherName', coalesce(nullif(trim(v_teacher_name), ''), 'Professor(a)'),
    'startsAt', v_request.slot_start,
    'claimGeneration', v_opportunity.claim_generation
  );

  if v_request.status = 'ACCEPTED' then
    select appointment.*
      into v_appointment
      from public.appointments as appointment
     where appointment.id = v_request.accepted_appointment_id
       and appointment.id = v_opportunity.trial_appointment_id
       and appointment.tenant_id = v_opportunity.tenant_id
       and appointment.teacher_id = v_request.target_teacher_id
       and appointment.professor_id = v_request.target_teacher_id
       and appointment.start_time = v_request.slot_start;

    if not found
       or upper(coalesce(v_opportunity.status, '')) <> 'CLAIMED'
       or v_opportunity.winner_teacher_id is distinct from
            v_request.target_teacher_id
       or v_opportunity.professor_id is distinct from
            v_request.target_teacher_id then
      return jsonb_build_object('ok', false, 'error', 'link_inconsistent');
    end if;

    return v_base || jsonb_build_object(
      'confirmed', true,
      'requested', true,
      'idempotent', true,
      'newlyRequested', false,
      'appointmentId', v_appointment.id,
      'state', 'CONFIRMED'
    );
  end if;

  if v_request.status = 'AWAITING_TEACHER' then
    if v_link.status <> 'USED'
       or v_link.student_confirmed_at is null
       or v_opportunity.trial_appointment_id is not null then
      return jsonb_build_object('ok', false, 'error', 'link_inconsistent');
    end if;
    return v_base || jsonb_build_object(
      'confirmed', false,
      'requested', true,
      'conflict', false,
      'idempotent', true,
      'newlyRequested', false,
      'state', 'AWAITING_TEACHER'
    );
  end if;

  if v_request.status <> 'AWAITING_STUDENT'
     or v_link.status <> 'PENDING'
     or upper(coalesce(v_opportunity.status, '')) <> 'OPEN'
     or v_opportunity.winner_teacher_id is not null
     or v_opportunity.professor_id is not null
     or v_opportunity.trial_appointment_id is not null then
    return jsonb_build_object('ok', false, 'error', 'link_inconsistent');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_request.target_teacher_id::text, 0)
  );

  v_conflict := private.secure_trial_schedule_conflict(
    v_opportunity.tenant_id,
    v_request.target_teacher_id,
    v_request.slot_start,
    null,
    v_link.id
  );

  if not p_confirm then
    return v_base || jsonb_build_object(
      'confirmed', false,
      'requested', false,
      'conflict', v_conflict,
      'idempotent', false,
      'newlyRequested', false,
      'state', 'AWAITING_STUDENT'
    );
  end if;
  if v_conflict then
    return v_base || jsonb_build_object(
      'ok', false,
      'error', 'teacher_schedule_conflict',
      'confirmed', false,
      'requested', false,
      'conflict', true,
      'state', 'AWAITING_STUDENT'
    );
  end if;

  update public.enrollment_links
     set status = 'USED',
         used_at = now(),
         student_confirmed_at = now()
   where id = v_link.id
     and status = 'PENDING'
     and purpose = 'TRIAL_CONFIRMATION';
  if not found then
    raise exception 'vendor_trial_interest_lost_lock'
      using errcode = '40001';
  end if;

  update private.vendor_trial_teacher_requests
     set status = 'AWAITING_TEACHER',
         student_confirmed_at = now(),
         updated_at = now()
   where id = v_request.id
     and status = 'AWAITING_STUDENT';
  if not found then
    raise exception 'vendor_trial_request_lost_lock'
      using errcode = '40001';
  end if;

  return v_base || jsonb_build_object(
    'confirmed', false,
    'requested', true,
    'conflict', false,
    'idempotent', false,
    'newlyRequested', true,
    'state', 'AWAITING_TEACHER'
  );
end;
$_$;


--
-- Name: FUNCTION confirm_vendor_trial_interest_pre_outbox_impl(p_link_token text, p_legacy_opportunity_id uuid, p_confirm boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.confirm_vendor_trial_interest_pre_outbox_impl(p_link_token text, p_legacy_opportunity_id uuid, p_confirm boolean) IS 'Service-only. Public confirmation records interest; only authenticated teacher claim creates an appointment.';


--
-- Name: consume_offer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_offer(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_offer RECORD;
BEGIN
    UPDATE public.offers
    SET consumed_at = now()
    WHERE id = p_offer_id
      AND consumed_at IS NULL
      AND revoked_at IS NULL
      AND expires_at > now()
    RETURNING * INTO v_offer;

    IF v_offer IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'OFFER_UNAVAILABLE');
    END IF;

    RETURN jsonb_build_object('success', true, 'offer_id', v_offer.id);
END;
$$;


--
-- Name: consume_saas_checkout_rate_limit(text, integer, interval); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_saas_checkout_rate_limit(p_rate_key text, p_max_requests integer DEFAULT 5, p_window interval DEFAULT '01:00:00'::interval) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  current_row public.saas_checkout_rate_limits%ROWTYPE;
BEGIN
  IF nullif(trim(p_rate_key), '') IS NULL
     OR p_max_requests < 1
     OR p_window <= interval '0 seconds' THEN
    RETURN false;
  END IF;

  INSERT INTO public.saas_checkout_rate_limits (rate_key)
  VALUES (p_rate_key)
  ON CONFLICT (rate_key) DO NOTHING;

  SELECT *
  INTO current_row
  FROM public.saas_checkout_rate_limits
  WHERE rate_key = p_rate_key
  FOR UPDATE;

  IF current_row.window_started_at + p_window <= now() THEN
    UPDATE public.saas_checkout_rate_limits
    SET window_started_at = now(),
        request_count = 1,
        updated_at = now()
    WHERE rate_key = p_rate_key;
    RETURN true;
  END IF;

  IF current_row.request_count >= p_max_requests THEN
    RETURN false;
  END IF;

  UPDATE public.saas_checkout_rate_limits
  SET request_count = request_count + 1,
      updated_at = now()
  WHERE rate_key = p_rate_key;
  RETURN true;
END;
$$;


--
-- Name: consume_student_heart(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_student_heart(p_request_key text, p_reason text DEFAULT 'WRONG_ANSWER'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.assert_active_student_learning_mutation();
  return public.consume_student_heart_core(p_request_key, p_reason);
end;
$$;


--
-- Name: consume_student_heart_core(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_student_heart_core(p_request_key text, p_reason text DEFAULT 'WRONG_ANSWER'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_id uuid := auth.uid();
  v_request_key text := pg_catalog.btrim(coalesce(p_request_key, ''));
  v_reason text := pg_catalog.upper(
    pg_catalog.btrim(coalesce(p_reason, 'WRONG_ANSWER'))
  );
  v_now timestamptz := pg_catalog.now();
  v_status jsonb;
  v_existing public.student_heart_consumptions%rowtype;
  v_tenant_id text;
  v_hearts_before integer;
  v_hearts_after integer;
  v_anchor timestamptz;
  v_consumed boolean;
begin
  if v_student_id is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  if pg_catalog.length(v_request_key) not between 8 and 180
     or pg_catalog.length(v_reason) not between 1 and 120 then
    raise exception using
      errcode = '22023',
      message = 'invalid_heart_consumption_request';
  end if;

  -- The refresh locks the profile row, serializing consumption and regeneration.
  v_status := private.refresh_student_hearts(v_student_id, v_now);
  v_tenant_id := v_status ->> 'tenantId';

  select *
    into v_existing
    from public.student_heart_consumptions as consumption
   where consumption.student_id = v_student_id
     and consumption.request_key = v_request_key;

  if found then
    if v_existing.reason <> v_reason then
      raise exception using
        errcode = '22023',
        message = 'idempotency_key_reused';
    end if;

    return v_status || pg_catalog.jsonb_build_object(
      'consumed', v_existing.consumed,
      'alreadyApplied', true,
      'heartsAtAttempt', v_existing.hearts_after
    );
  end if;

  v_hearts_before := (v_status ->> 'hearts')::integer;
  v_hearts_after := greatest(0, v_hearts_before - 1);
  v_consumed := v_hearts_before > 0;

  select profile.hearts_updated_at
    into v_anchor
    from public.profiles as profile
   where profile.id = v_student_id;

  if v_consumed then
    if v_hearts_before >= 5 then
      v_anchor := v_now;
    end if;

    update public.profiles
       set hearts = v_hearts_after,
           hearts_updated_at = v_anchor,
           hearts_full_notified = false
     where id = v_student_id;
  end if;

  insert into public.student_heart_consumptions (
    tenant_id,
    student_id,
    request_key,
    reason,
    hearts_before,
    hearts_after,
    consumed,
    created_at
  ) values (
    v_tenant_id,
    v_student_id,
    v_request_key,
    v_reason,
    v_hearts_before,
    v_hearts_after,
    v_consumed,
    v_now
  );

  return pg_catalog.jsonb_build_object(
    'tenantId', v_tenant_id,
    'hearts', v_hearts_after,
    'maxHearts', 5,
    'heartsUpdatedAt', v_anchor,
    'nextHeartAt', case
      when v_hearts_after < 5 then v_anchor + interval '30 minutes'
      else null
    end,
    'consumed', v_consumed,
    'alreadyApplied', false,
    'heartsAtAttempt', v_hearts_after
  );
end;
$$;


--
-- Name: FUNCTION consume_student_heart_core(p_request_key text, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.consume_student_heart_core(p_request_key text, p_reason text) IS 'Atomically regenerates and consumes one student heart, fenced by a caller request key.';


--
-- Name: consume_tenant_settings_rate_limit(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_tenant_settings_rate_limit(p_tenant_id text, p_action_key text, p_limit integer, p_window_seconds integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  current_count integer;
BEGIN
  IF p_tenant_id IS NULL
    OR p_action_key IS NULL
    OR length(p_action_key) NOT BETWEEN 2 AND 80
    OR p_limit NOT BETWEEN 1 AND 1000
    OR p_window_seconds NOT BETWEEN 10 AND 86400
  THEN
    RAISE EXCEPTION 'invalid_rate_limit_parameters' USING ERRCODE = '22023';
  END IF;

  INSERT INTO private.tenant_configuration_rate_limits AS rate_limit (
    tenant_id,
    action_key,
    window_started_at,
    request_count
  )
  VALUES (p_tenant_id, p_action_key, clock_timestamp(), 1)
  ON CONFLICT (tenant_id, action_key) DO UPDATE
  SET window_started_at = CASE
        WHEN rate_limit.window_started_at
          <= clock_timestamp() - make_interval(secs => p_window_seconds)
        THEN clock_timestamp()
        ELSE rate_limit.window_started_at
      END,
      request_count = CASE
        WHEN rate_limit.window_started_at
          <= clock_timestamp() - make_interval(secs => p_window_seconds)
        THEN 1
        ELSE rate_limit.request_count + 1
      END
  RETURNING request_count INTO current_count;

  RETURN current_count <= p_limit;
END;
$$;


--
-- Name: contratos_para_renovar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.contratos_para_renovar(p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare
  v_jwt text;
  v_role text;
  v_tenant text;
  v_vencendo jsonb;
  v_encerrado jsonb;
begin
  v_jwt := coalesce(current_setting('request.jwt.claims', true)::json->>'role', '');
  select role, tenant_id into v_role, v_tenant from public.profiles where id = auth.uid();

  if v_jwt in ('anon', 'authenticated') then
    if v_role is null or v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') then
      return jsonb_build_object('error', 'sem_permissao');
    end if;
    if v_role = 'SUPER_ADMIN' then v_tenant := coalesce(p_tenant, v_tenant); end if;
  else
    v_tenant := coalesce(p_tenant, v_tenant);
  end if;

  if v_tenant is null then
    return jsonb_build_object('error', 'escola_nao_identificada');
  end if;

  -- VENCENDO: ainda há aula paga pela frente, dentro de 90 dias.
  select coalesce(jsonb_agg(x order by x.termina), '[]'::jsonb) into v_vencendo
  from (
    select trim(p.full_name) as aluno,
           p.id as student_id,
           coalesce(p.monthly_fee, 0)::numeric(10,2) as mensalidade,
           public.fim_do_servico(p.asaas_subscription_end_date) as termina,
           (public.fim_do_servico(p.asaas_subscription_end_date) - current_date)::int as dias,
           -- A Asaas já parou de gerar cobrança? Muda a urgência: não basta
           -- renovar, é preciso religar o faturamento.
           (upper(coalesce(p.asaas_subscription_status, '')) in ('EXPIRED', 'INACTIVE', 'NOT_FOUND')) as cobranca_parada,
           g.professor,
           g.horarios
      from public.profiles p
      cross join lateral (
        select
          (select trim(t.full_name)
             from public.class_logs cl
             join public.profiles t on t.id = cl.teacher_id
            where cl.student_id = p.id and cl.class_date >= current_date - 90
            group by t.full_name order by count(*) desc limit 1) as professor,
          (select string_agg(distinct b.day_of_week || ' ' || b.time_slot, ', ')
             from public.bookings b
            where b.student_id = p.id and b.status = 'SCHEDULED') as horarios
      ) g
     where p.tenant_id = v_tenant
       and p.role = 'STUDENT'
       and public.is_student_notifiable(p.id)
       and p.asaas_subscription_end_date is not null
       and public.fim_do_servico(p.asaas_subscription_end_date) >= current_date
       and public.fim_do_servico(p.asaas_subscription_end_date) <= current_date + 90
       and exists (select 1 from public.class_logs cl
                    where cl.student_id = p.id and cl.class_date >= current_date - 60)
  ) x;

  -- ENCERRADO: o mês pago já passou e o aluno continua tendo aula.
  select coalesce(jsonb_agg(x order by x.termina nulls first), '[]'::jsonb) into v_encerrado
  from (
    select trim(p.full_name) as aluno,
           p.id as student_id,
           coalesce(p.monthly_fee, 0)::numeric(10,2) as mensalidade,
           coalesce(p.asaas_subscription_status, '?') as situacao,
           public.fim_do_servico(p.asaas_subscription_end_date) as termina,
           (current_date - public.fim_do_servico(p.asaas_subscription_end_date))::int as dias_de_graca,
           (select count(*) from public.v_payable_class_logs v
             where v.student_id = p.id and v.class_date >= current_date - 60)::int as aulas_60d
      from public.profiles p
     where p.tenant_id = v_tenant
       and p.role = 'STUDENT'
       and public.is_student_notifiable(p.id)
       and coalesce(p.subscription_id, '') <> ''
       and (
         -- Sem data (assinatura sumiu) mas com status morto, ou data já passada.
         (p.asaas_subscription_end_date is null
           and upper(coalesce(p.asaas_subscription_status, '')) in ('EXPIRED', 'INACTIVE', 'NOT_FOUND'))
         or public.fim_do_servico(p.asaas_subscription_end_date) < current_date
       )
       and exists (select 1 from public.class_logs cl
                    where cl.student_id = p.id and cl.class_date >= current_date - 60)
  ) x;

  return jsonb_build_object(
    'ok', true,
    'sincronizado_em', (select max(asaas_subscription_synced_at)
                          from public.profiles where tenant_id = v_tenant),
    'vencendo', jsonb_build_object(
      'itens', v_vencendo,
      'qtd', jsonb_array_length(v_vencendo),
      'mensal', (select coalesce(sum((i->>'mensalidade')::numeric), 0)
                   from jsonb_array_elements(v_vencendo) i)
    ),
    'encerrado', jsonb_build_object(
      'itens', v_encerrado,
      'qtd', jsonb_array_length(v_encerrado),
      'mensal', (select coalesce(sum((i->>'mensalidade')::numeric), 0)
                   from jsonb_array_elements(v_encerrado) i)
    )
  );
end;
$$;


--
-- Name: coverages_for_teacher(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.coverages_for_teacher(p_teacher uuid, p_from date, p_to date) RETURNS TABLE(coverage_id uuid, booking_id uuid, student_id uuid, class_date date, class_time text, papel text, outro_professor text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
BEGIN
  IF p_teacher IS NULL OR p_from IS NULL OR p_to IS NULL
     OR p_to < p_from OR p_to > p_from + 366 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'intervalo_invalido';
  END IF;
  IF coalesce(auth.role(), '') <> 'service_role' AND v_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'authentication_required';
  END IF;

  RETURN QUERY
  SELECT coverage.id,
         coverage.booking_id,
         coverage.student_id,
         coverage.class_date,
         coverage.class_time,
         CASE WHEN coverage.original_teacher_id = p_teacher
              THEN 'cedida' ELSE 'assumida' END,
         coalesce(other_profile.full_name, '')
    FROM public.class_coverages AS coverage
    LEFT JOIN public.profiles AS other_profile
      ON other_profile.id = CASE
        WHEN coverage.original_teacher_id = p_teacher
          THEN coverage.cover_teacher_id
        ELSE coverage.original_teacher_id
      END
   WHERE lower(coverage.status) = 'confirmed'
     AND coverage.class_date BETWEEN p_from AND p_to
     AND (
       coverage.original_teacher_id = p_teacher
       OR coverage.cover_teacher_id = p_teacher
     )
     AND EXISTS (
       SELECT 1
         FROM public.tenant_memberships AS teacher_membership
        WHERE teacher_membership.user_id = p_teacher
          AND teacher_membership.tenant_id = coverage.tenant_id
          AND teacher_membership.role = 'TEACHER'
          AND teacher_membership.status = 'ACTIVE'
     )
     AND (
       coalesce(auth.role(), '') = 'service_role'
       OR EXISTS (
         SELECT 1
           FROM public.tenant_memberships AS actor_membership
          WHERE actor_membership.user_id = v_actor_id
            AND actor_membership.tenant_id = coverage.tenant_id
            AND actor_membership.status = 'ACTIVE'
            AND (
              (v_actor_id = p_teacher AND actor_membership.role = 'TEACHER')
              OR (
                v_actor_id <> p_teacher
                AND actor_membership.role IN ('SCHOOL_ADMIN', 'COORDINATOR')
              )
            )
       )
     );
END;
$$;


--
-- Name: coverages_for_teacher_in_tenant(text, uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.coverages_for_teacher_in_tenant(p_tenant text, p_teacher uuid, p_from date, p_to date) RETURNS TABLE(coverage_id uuid, booking_id uuid, student_id uuid, class_date date, class_time text, papel text, outro_professor text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_actor_id uuid := auth.uid();
BEGIN
  IF p_tenant IS NULL OR p_teacher IS NULL OR p_from IS NULL OR p_to IS NULL
     OR p_to < p_from OR p_to > p_from + 366 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'intervalo_invalido';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles AS profile
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = profile.id
       AND membership.tenant_id = p_tenant
       AND membership.role = 'TEACHER'
       AND membership.status = 'ACTIVE'
     WHERE profile.id = p_teacher
       AND profile.role = 'TEACHER'
       AND lower(coalesce(profile.lifecycle_status, '')) = 'active'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'professor_nao_encontrado';
  END IF;

  IF coalesce(auth.role(), '') <> 'service_role' THEN
    IF v_actor_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'authentication_required';
    END IF;
    IF NOT EXISTS (
      SELECT 1
        FROM public.tenant_memberships AS membership
       WHERE membership.user_id = v_actor_id
         AND membership.tenant_id = p_tenant
         AND membership.status = 'ACTIVE'
         AND (
           (v_actor_id = p_teacher AND membership.role = 'TEACHER')
           OR (
             v_actor_id <> p_teacher
             AND membership.role IN ('SCHOOL_ADMIN', 'COORDINATOR')
           )
         )
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'forbidden';
    END IF;
  END IF;

  RETURN QUERY
  SELECT coverage.id,
         coverage.booking_id,
         coverage.student_id,
         coverage.class_date,
         coverage.class_time,
         CASE WHEN coverage.original_teacher_id = p_teacher
              THEN 'cedida' ELSE 'assumida' END,
         coalesce(other_profile.full_name, '')
    FROM public.class_coverages AS coverage
    LEFT JOIN public.profiles AS other_profile
      ON other_profile.id = CASE
        WHEN coverage.original_teacher_id = p_teacher
          THEN coverage.cover_teacher_id
        ELSE coverage.original_teacher_id
      END
   WHERE coverage.tenant_id = p_tenant
     AND lower(coverage.status) = 'confirmed'
     AND coverage.class_date BETWEEN p_from AND p_to
     AND (
       coverage.original_teacher_id = p_teacher
       OR coverage.cover_teacher_id = p_teacher
     );
END;
$$;


--
-- Name: create_absence_with_coverage(uuid, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_absence_with_coverage(p_teacher_id uuid, p_starts date, p_ends date, p_reason text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_role TEXT;
    v_tenant TEXT;
    v_absence_id UUID;
    v_affected_bookings INT;
BEGIN
    SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
    IF v_role NOT IN ('TEACHER','teacher','SCHOOL_ADMIN','SUPER_ADMIN') THEN RAISE EXCEPTION 'Sem permissão'; END IF;
    IF p_teacher_id <> auth.uid() AND v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
        RAISE EXCEPTION 'Apenas o próprio professor ou admin pode criar ausência';
    END IF;

    INSERT INTO teacher_absences (teacher_id, tenant_id, starts_at, ends_at, reason, notes)
    VALUES (p_teacher_id, v_tenant, p_starts, p_ends, p_reason, p_notes)
    RETURNING id INTO v_absence_id;

    -- Contar bookings afetados no período (não cria cobertura — admin atribui manualmente depois)
    SELECT COUNT(*) INTO v_affected_bookings FROM bookings b WHERE b.teacher_id = p_teacher_id;

    RETURN jsonb_build_object(
        'absence_id', v_absence_id,
        'affected_bookings_estimate', v_affected_bookings,
        'message', 'Ausência registrada. Admin pode atribuir coberturas em /admin → Coberturas.'
    );
END;
$$;


--
-- Name: create_broadcast(text, text, text, text, text, jsonb, text, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_broadcast(p_student_name text, p_student_phone text, p_date text, p_time text, p_interests text, p_preferred_slots jsonb, p_tenant_id text, p_actor_id uuid, p_idempotency_key text, p_message_text text, p_destination text, p_instance text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_existing_key RECORD;
    v_opp_id UUID;
    v_rate_count INTEGER;
    v_slot JSONB;
    v_day_of_week INTEGER;
BEGIN
    -- 1. IDEMPOTENCY CHECK
    IF p_idempotency_key IS NOT NULL THEN
        -- Cleanup old keys first
        PERFORM public.cleanup_expired_idempotency_keys();

        SELECT * INTO v_existing_key
        FROM public.idempotency_keys
        WHERE key = p_idempotency_key;

        IF v_existing_key IS NOT NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'deduplicated', true,
                'opportunity_id', v_existing_key.result_id
            );
        END IF;
    END IF;

    -- 2. RATE LIMIT CHECK (max 10 broadcasts per minute per tenant)
    SELECT COUNT(*) INTO v_rate_count
    FROM public.broadcast_rate_limits
    WHERE tenant_id = p_tenant_id
      AND created_at > now() - INTERVAL '1 minute';

    IF v_rate_count >= 10 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'RATE_LIMITED',
            'message', 'Limite de disparos atingido. Aguarde 1 minuto.'
        );
    END IF;

    -- 3. INSERT OPPORTUNITY
    v_day_of_week := EXTRACT(DOW FROM (p_date || 'T' || p_time || ':00')::timestamp);

    v_slot := jsonb_build_object(
        'day', v_day_of_week,
        'time', p_time,
        'date', p_date
    );

    INSERT INTO public.opportunities (
        student_name, student_phone, slots_proposed, status,
        tenant_id, interests, user_id, preferred_slots
    ) VALUES (
        p_student_name, p_student_phone, jsonb_build_array(v_slot), 'OPEN',
        p_tenant_id, p_interests, p_actor_id, p_preferred_slots
    )
    RETURNING id INTO v_opp_id;

    -- 4. INSERT OUTBOX MESSAGE (same transaction!)
    INSERT INTO public.outbox_messages (
        channel, destination, payload, status, correlation_id, tenant_id, actor_id
    ) VALUES (
        'whatsapp',
        p_destination,
        jsonb_build_object(
            'instance', p_instance,
            'text', p_message_text,
            'opportunity_id', v_opp_id
        ),
        'PENDING',
        v_opp_id,
        p_tenant_id,
        p_actor_id
    );

    -- 5. SAVE IDEMPOTENCY KEY
    IF p_idempotency_key IS NOT NULL THEN
        INSERT INTO public.idempotency_keys (key, tenant_id, result_id)
        VALUES (p_idempotency_key, p_tenant_id, v_opp_id)
        ON CONFLICT (key) DO NOTHING;
    END IF;

    -- 6. TRACK RATE LIMIT
    INSERT INTO public.broadcast_rate_limits (tenant_id, actor_id)
    VALUES (p_tenant_id, p_actor_id);

    RETURN jsonb_build_object(
        'success', true,
        'opportunity_id', v_opp_id,
        'deduplicated', false
    );
END;
$$;


--
-- Name: FUNCTION create_broadcast(p_student_name text, p_student_phone text, p_date text, p_time text, p_interests text, p_preferred_slots jsonb, p_tenant_id text, p_actor_id uuid, p_idempotency_key text, p_message_text text, p_destination text, p_instance text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_broadcast(p_student_name text, p_student_phone text, p_date text, p_time text, p_interests text, p_preferred_slots jsonb, p_tenant_id text, p_actor_id uuid, p_idempotency_key text, p_message_text text, p_destination text, p_instance text) IS 'Atomically creates an opportunity + outbox message. Idempotent via key. Rate limited.';


--
-- Name: create_enrollment_offer(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_enrollment_offer(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_tenant_id text;
  v_actor_role text;
  v_lead_id uuid;
  v_opportunity_id uuid;
begin
  if pg_catalog.jsonb_typeof(coalesce(p_payload, '{}'::jsonb))
       is distinct from 'object'
     or not p_payload ? 'leadId' then
    return public.create_enrollment_offer_pre_crm_lead_lock_impl(p_payload);
  end if;

  begin
    v_lead_id := (p_payload ->> 'leadId')::uuid;
    v_opportunity_id := (p_payload ->> 'opportunityId')::uuid;
  exception when invalid_text_representation then
    raise exception 'invalid_trial_lead_binding' using errcode = '22023';
  end;
  if v_lead_id is null or v_opportunity_id is null then
    raise exception 'invalid_trial_lead_binding' using errcode = '22023';
  end if;

  select actor.actor_id, actor.tenant_id, actor.actor_role
    into v_actor_id, v_tenant_id, v_actor_role
    from private.secure_trial_actor_context() as actor;
  if v_actor_id is null
     or v_actor_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    raise exception 'permission_denied' using errcode = '42501';
  end if;

  if not exists (
    select 1
      from public.opportunities as opportunity
     where opportunity.id = v_opportunity_id
       and opportunity.tenant_id = v_tenant_id
  ) then
    raise exception 'trial_lead_link_required' using errcode = '23514';
  end if;
  begin
    perform private.lock_trial_conversion_graph(v_opportunity_id);
  exception when no_data_found then
    raise exception 'trial_lead_link_required' using errcode = '23514';
  end;

  perform lead.id
    from public.crm_leads as lead
   where lead.id = v_lead_id
     and lead.tenant_id = v_tenant_id
     and lead.opportunity_id = v_opportunity_id
     and pg_catalog.upper(pg_catalog.btrim(coalesce(lead.status, ''))) =
       'TRIAL_DONE'
   for update;
  if not found then
    raise exception 'trial_lead_link_required' using errcode = '23514';
  end if;

  return public.create_enrollment_offer_pre_crm_lead_lock_impl(
    p_payload - 'leadId'
  );
end;
$$;


--
-- Name: create_enrollment_offer_authoritative_impl(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_enrollment_offer_authoritative_impl(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
  v_role text := public._my_role();
  v_caller_tenant text := public._my_tenant_id();
  v_tenant text;
  v_payload jsonb := COALESCE(p_payload, '{}'::jsonb);
  v_value numeric;
  v_due_day integer;
  v_duration integer;
  v_frequency integer;
  v_requires boolean;
  v_fee numeric;
  v_start_date date;
  v_opportunity_id uuid;
  v_vendor_id uuid;
  v_professor_id uuid;
  v_professor_id2 uuid;
  v_guardian_id uuid;
  v_vendor_role text;
  v_vendor_tenant text;
  v_link_origin text;
  v_id uuid;
  v_opp public.opportunities%ROWTYPE;
  v_guardian public.profiles%ROWTYPE;
BEGIN
  IF jsonb_typeof(v_payload) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'payload invalido';
  END IF;

  IF v_role IS NULL OR v_role NOT IN (
    'SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR', 'TEACHER', 'SALESPERSON'
  ) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  v_tenant := COALESCE(NULLIF(v_payload ->> 'unitId', ''), v_caller_tenant);
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'tenant invalido'; END IF;
  IF v_role <> 'SUPER_ADMIN' AND v_tenant IS DISTINCT FROM v_caller_tenant THEN
    RAISE EXCEPTION 'forbidden: tenant invalido';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenants t WHERE t.id = v_tenant) THEN
    RAISE EXCEPTION 'tenant invalido';
  END IF;

  BEGIN
    v_value := NULLIF(v_payload ->> 'value', '')::numeric;
    v_due_day := NULLIF(v_payload ->> 'dueDay', '')::integer;
    v_duration := COALESCE(NULLIF(v_payload ->> 'planDuration', '')::integer, 1);
    v_frequency := COALESCE(NULLIF(v_payload ->> 'classesPerWeek', '')::integer, 1);
    v_start_date := NULLIF(v_payload ->> 'startDate', '')::date;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'dados comerciais invalidos';
  END;

  IF v_value IS NULL OR v_value <= 0 THEN RAISE EXCEPTION 'valor mensal invalido'; END IF;
  IF v_due_day IS NULL OR v_due_day < 1 OR v_due_day > 31 THEN RAISE EXCEPTION 'vencimento invalido'; END IF;
  IF v_duration NOT IN (0, 1, 6, 12) THEN RAISE EXCEPTION 'duracao invalida'; END IF;
  IF v_frequency < 1 OR v_frequency > 7 THEN RAISE EXCEPTION 'frequencia invalida'; END IF;

  v_requires := v_duration <> 0;
  BEGIN
    v_fee := CASE
      WHEN NOT v_requires THEN 0
      ELSE GREATEST(COALESCE(NULLIF(v_payload ->> 'enrollmentFee', '')::numeric, 0), 0)
    END;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'taxa de matricula invalida';
  END;

  IF NULLIF(v_payload ->> 'opportunityId', '') IS NOT NULL THEN
    BEGIN
      v_opportunity_id := (v_payload ->> 'opportunityId')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'oportunidade invalida';
    END;

    SELECT * INTO v_opp
      FROM public.opportunities
     WHERE id = v_opportunity_id
       AND tenant_id = v_tenant
     FOR UPDATE;

    IF NOT FOUND THEN RAISE EXCEPTION 'oportunidade invalida'; END IF;
    IF v_opp.conversion_status IN ('WON', 'LOST') THEN
      RAISE EXCEPTION 'oportunidade ja encerrada';
    END IF;
    IF v_opp.trial_status IS DISTINCT FROM 'DONE' THEN
      RAISE EXCEPTION 'aula experimental ainda nao concluida';
    END IF;
  END IF;

  IF v_role = 'SALESPERSON' THEN
    v_vendor_id := auth.uid();
  ELSIF NULLIF(v_payload ->> 'vendorId', '') IS NOT NULL THEN
    BEGIN
      v_vendor_id := (v_payload ->> 'vendorId')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'vendedor invalido';
    END;
  ELSIF v_opportunity_id IS NOT NULL THEN
    v_vendor_id := v_opp.created_by_vendor_id;
  END IF;

  IF v_vendor_id IS NOT NULL THEN
    SELECT p.role, p.tenant_id
      INTO v_vendor_role, v_vendor_tenant
      FROM public.profiles p
     WHERE p.id = v_vendor_id;
    IF v_vendor_role IS DISTINCT FROM 'SALESPERSON'
       OR v_vendor_tenant IS DISTINCT FROM v_tenant THEN
      RAISE EXCEPTION 'vendedor invalido';
    END IF;
  END IF;

  IF NULLIF(v_payload ->> 'professorId', '') IS NOT NULL THEN
    BEGIN
      v_professor_id := (v_payload ->> 'professorId')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'professor invalido';
    END;
    IF NOT EXISTS (
      SELECT 1 FROM public.profiles p
       WHERE p.id = v_professor_id
         AND p.tenant_id = v_tenant
         AND p.role = 'TEACHER'
    ) THEN
      RAISE EXCEPTION 'professor invalido';
    END IF;
  END IF;

  IF NULLIF(v_payload ->> 'professorId2', '') IS NOT NULL THEN
    BEGIN
      v_professor_id2 := (v_payload ->> 'professorId2')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'segundo professor invalido';
    END;
    IF NOT EXISTS (
      SELECT 1 FROM public.profiles p
       WHERE p.id = v_professor_id2
         AND p.tenant_id = v_tenant
         AND p.role = 'TEACHER'
    ) THEN
      RAISE EXCEPTION 'segundo professor invalido';
    END IF;
  END IF;

  IF COALESCE((v_payload ->> 'isDependent')::boolean, false) THEN
    BEGIN
      v_guardian_id := NULLIF(v_payload ->> 'guardianId', '')::uuid;
    EXCEPTION WHEN OTHERS THEN
      RAISE EXCEPTION 'responsavel invalido';
    END;
    SELECT * INTO v_guardian
      FROM public.profiles p
     WHERE p.id = v_guardian_id
       AND p.tenant_id = v_tenant
       AND NULLIF(p.cpf, '') IS NOT NULL;
    IF NOT FOUND THEN RAISE EXCEPTION 'responsavel invalido'; END IF;

    v_payload := v_payload || jsonb_build_object(
      'guardianId', v_guardian.id,
      'guardianCpf', v_guardian.cpf,
      'guardianName', v_guardian.full_name,
      'guardianEmail', v_guardian.email,
      'guardianPhone', v_guardian.phone,
      'guardianPostalCode', v_guardian.postal_code,
      'guardianAddress', v_guardian.address,
      'guardianAddressNumber', v_guardian.address_number
    );
  END IF;

  v_link_origin := NULLIF(v_payload ->> '_linkOrigin', '');
  IF v_link_origin NOT IN (
    'https://app.wisewolflanguage.com.br',
    'https://system.wisewolflanguage.com.br'
  ) THEN
    v_link_origin := 'https://system.wisewolflanguage.com.br';
  END IF;

  v_payload := (v_payload - '_linkOrigin')
    || jsonb_build_object(
      'unitId', v_tenant,
      'value', v_value,
      'dueDay', v_due_day,
      'planDuration', v_duration,
      'classesPerWeek', v_frequency,
      'requiresEnrollment', v_requires,
      'enrollmentFee', v_fee,
      'opportunityId', v_opportunity_id,
      'vendorId', v_vendor_id,
      'professorId', v_professor_id,
      'professorId2', v_professor_id2
    );

  IF v_opportunity_id IS NOT NULL THEN
    UPDATE public.offers
       SET revoked_at = now(),
           revoked_by = auth.uid()
     WHERE kind = 'ENROLLMENT'
       AND opportunity_id = v_opportunity_id
       AND consumed_at IS NULL
       AND revoked_at IS NULL;

    UPDATE public.enrollment_links
       SET status = 'EXPIRED'
     WHERE opportunity_id = v_opportunity_id
       AND status = 'PENDING';
  END IF;

  INSERT INTO public.offers (
    kind, tenant_id, payload, expires_at, created_by,
    requires_enrollment, enrollment_fee, opportunity_id, vendor_id
  )
  VALUES (
    'ENROLLMENT', v_tenant, v_payload, now() + interval '30 days', auth.uid(),
    v_requires, v_fee, v_opportunity_id, v_vendor_id
  )
  RETURNING id INTO v_id;

  IF v_opportunity_id IS NOT NULL THEN
    INSERT INTO public.enrollment_links (
      tenant_id, opportunity_id, offer_id, link_token, link_url,
      student_name, student_phone, professor_id, professor_id2,
      plan_duration, classes_per_week, monthly_fee, due_day,
      enrollment_fee, start_date, status, created_by_vendor_id
    )
    VALUES (
      v_tenant,
      v_opportunity_id,
      v_id,
      'offer_' || v_id::text,
      v_link_origin || '/matricula?offer=' || v_id::text,
      NULLIF(v_payload ->> 'studentName', ''),
      NULLIF(v_payload ->> 'studentPhone', ''),
      v_professor_id,
      v_professor_id2,
      v_duration,
      v_frequency,
      v_value,
      v_due_day,
      v_fee,
      v_start_date,
      'PENDING',
      v_vendor_id
    );
  END IF;

  RETURN v_id;
END;
$$;


--
-- Name: create_enrollment_offer_pre_crm_lead_lock_impl(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_enrollment_offer_pre_crm_lead_lock_impl(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := (select auth.uid());
  v_tenant_id text := private.active_tenant_id(v_actor_id);
  v_role text := private.active_tenant_role(v_actor_id);
  v_request_id uuid;
  v_safe_payload jsonb;
  v_fingerprint text;
  v_offer_id uuid;
  v_existing_fingerprint text;
begin
  if v_actor_id is null or v_tenant_id is null
     or coalesce(v_role, '') not in (
       'SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN', 'SALESPERSON'
     ) then
    raise exception 'permission_denied' using errcode = '42501';
  end if;

  -- requestId is required only for the durable retry protocol. Calls from old
  -- integrations remain compatible but are intentionally not retry-safe.
  if pg_catalog.jsonb_typeof(coalesce(p_payload, '{}'::jsonb))
       is distinct from 'object'
     or not (p_payload ? 'requestId') then
    return public.create_enrollment_offer_pre_trial_offer_authority_impl(
      p_payload
    );
  end if;

  begin
    v_request_id := nullif(
      pg_catalog.btrim(coalesce(p_payload ->> 'requestId', '')),
      ''
    )::uuid;
  exception when invalid_text_representation then
    raise exception 'invalid_enrollment_offer_request_id'
      using errcode = '22023';
  end;
  if v_request_id is null then
    raise exception 'invalid_enrollment_offer_request_id'
      using errcode = '22023';
  end if;

  v_safe_payload := p_payload - 'requestId';
  v_fingerprint := private.enrollment_offer_payload_fingerprint(v_safe_payload);

  insert into private.enrollment_offer_command_receipts (
    tenant_id, actor_id, request_id, payload_fingerprint
  ) values (
    v_tenant_id, v_actor_id, v_request_id, v_fingerprint
  ) on conflict do nothing
  returning offer_id into v_offer_id;

  if not found then
    select receipt.payload_fingerprint, receipt.offer_id
      into v_existing_fingerprint, v_offer_id
      from private.enrollment_offer_command_receipts as receipt
     where receipt.tenant_id = v_tenant_id
       and receipt.actor_id = v_actor_id
       and receipt.request_id = v_request_id
     for update;
    if v_existing_fingerprint is distinct from v_fingerprint then
      raise exception 'idempotency_key_reused' using errcode = '23505';
    end if;
    if v_offer_id is null then
      raise exception 'enrollment_offer_request_incomplete'
        using errcode = '40001';
    end if;
    return v_offer_id;
  end if;

  v_offer_id := public.create_enrollment_offer_pre_trial_offer_authority_impl(
    v_safe_payload
  );
  if not exists (
    select 1
      from public.offers as offer
     where offer.id = v_offer_id
       and offer.tenant_id = v_tenant_id
       and offer.kind = 'ENROLLMENT'
       and offer.revoked_at is null
  ) then
    raise exception 'enrollment_offer_scope_mismatch' using errcode = '23514';
  end if;

  update private.enrollment_offer_command_receipts
     set offer_id = v_offer_id,
         completed_at = pg_catalog.now()
   where tenant_id = v_tenant_id
     and actor_id = v_actor_id
     and request_id = v_request_id
     and payload_fingerprint = v_fingerprint;
  if not found then
    raise exception 'enrollment_offer_receipt_lost_lock' using errcode = '40001';
  end if;
  return v_offer_id;
end;
$$;


--
-- Name: create_enrollment_offer_pre_schedule_impl(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_enrollment_offer_pre_schedule_impl(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  actor_role text := private.active_tenant_role(actor_id);
  active_tenant_id text := private.active_tenant_id(actor_id);
  safe_payload jsonb;
  target_user_id uuid;
  enrollment_offer_id uuid;
  school_snapshot jsonb;
BEGIN
  IF actor_id IS NULL
    OR active_tenant_id IS NULL
    OR coalesce(actor_role, '') NOT IN (
      'SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR', 'TEACHER', 'SALESPERSON'
    )
  THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  IF NOT private.tenant_is_operational(active_tenant_id) THEN
    RAISE EXCEPTION 'tenant_inactive' USING ERRCODE = '42501';
  END IF;
  IF p_payload IS NULL
    OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
    OR pg_column_size(p_payload) > 65536
  THEN
    RAISE EXCEPTION 'invalid_enrollment_offer' USING ERRCODE = '22023';
  END IF;
  IF p_payload ? 'tenantId'
    OR (
      p_payload ? 'unitId'
      AND p_payload ->> 'unitId' IS DISTINCT FROM active_tenant_id
    )
  THEN
    RAISE EXCEPTION 'cross_tenant_enrollment_denied' USING ERRCODE = '42501';
  END IF;

  FOR target_user_id IN
    SELECT candidate.user_id
    FROM (
      VALUES
        (nullif(p_payload ->> 'professorId', ''), 'TEACHER'),
        (nullif(p_payload ->> 'professorId2', ''), 'TEACHER'),
        (nullif(p_payload ->> 'vendorId', ''), 'SALESPERSON')
    ) AS supplied(raw_user_id, required_role)
    CROSS JOIN LATERAL (
      SELECT supplied.raw_user_id::uuid AS user_id
    ) AS candidate
    WHERE supplied.raw_user_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM public.tenant_memberships AS membership
        WHERE membership.user_id = candidate.user_id
          AND membership.tenant_id = active_tenant_id
          AND membership.role = supplied.required_role
          AND membership.status = 'ACTIVE'
      )
  LOOP
    RAISE EXCEPTION 'inactive_enrollment_actor' USING ERRCODE = '42501';
  END LOOP;

  IF nullif(p_payload ->> 'guardianId', '') IS NOT NULL THEN
    BEGIN
      target_user_id := (p_payload ->> 'guardianId')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'invalid_guardian' USING ERRCODE = '22023';
    END;
    IF NOT EXISTS (
      SELECT 1
      FROM public.tenant_memberships AS membership
      WHERE membership.user_id = target_user_id
        AND membership.tenant_id = active_tenant_id
        AND membership.status = 'ACTIVE'
    ) THEN
      RAISE EXCEPTION 'inactive_guardian' USING ERRCODE = '42501';
    END IF;
  END IF;

  school_snapshot := private.contract_school_info(active_tenant_id);
  safe_payload := (
    p_payload - 'tenantId' - 'unitId' - '_schoolInfo' - 'schoolInfo'
  ) || jsonb_build_object(
    'unitId', active_tenant_id,
    '_schoolInfo', school_snapshot
  );
  enrollment_offer_id := public.create_enrollment_offer_authoritative_impl(
    safe_payload
  );
  UPDATE public.offers
  SET invite_security_version = 1
  WHERE id = enrollment_offer_id
    AND tenant_id = active_tenant_id
    AND kind = 'ENROLLMENT';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'enrollment_offer_scope_mismatch' USING ERRCODE = '42501';
  END IF;
  RETURN enrollment_offer_id;
END;
$$;


--
-- Name: create_enrollment_offer_pre_trial_lifecycle_impl(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_enrollment_offer_pre_trial_lifecycle_impl(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := (select auth.uid());
  v_tenant_id text := private.active_tenant_id(v_actor_id);
  v_safe_payload jsonb;
  v_offer_id uuid;
begin
  if v_actor_id is null or v_tenant_id is null then
    raise exception 'permission_denied' using errcode = '42501';
  end if;

  v_safe_payload := private.prepare_enrollment_offer_payload(
    p_payload,
    v_tenant_id
  );
  v_offer_id := public.create_enrollment_offer_pre_schedule_impl(
    v_safe_payload
  );

  insert into private.enrollment_offer_schedule_slots (
    offer_id,
    tenant_id,
    slot_index,
    teacher_id,
    day_of_week,
    day_name,
    class_time,
    start_date
  )
  select
    v_offer_id,
    v_tenant_id,
    item.ordinality::smallint,
    (item.slot ->> 'teacherId')::uuid,
    public.dow_name_to_int(item.slot ->> 'day')::smallint,
    public.canonical_weekday_name(item.slot ->> 'day'),
    (item.slot ->> 'time')::time,
    (v_safe_payload ->> 'startDate')::date
  from pg_catalog.jsonb_array_elements(v_safe_payload -> 'schedule')
    with ordinality as item(slot, ordinality)
  order by item.ordinality;

  update public.offers as offer
  set metadata = coalesce(offer.metadata, '{}'::jsonb)
      || pg_catalog.jsonb_build_object(
        'pro_rata_formula_version', 'weekly-frequency-times-4-v1',
        'pro_rata_interval_start_inclusive',
          v_safe_payload ->> 'proRataIntervalStartInclusive',
        'pro_rata_interval_end_exclusive',
          v_safe_payload ->> 'proRataIntervalEndExclusive',
        'pro_rata_class_count', v_safe_payload -> 'proRataClassCount',
        'price_per_class', v_safe_payload -> 'pricePerClass',
        'pro_rata_value', v_safe_payload -> 'proRataValue'
      )
  where offer.id = v_offer_id;

  perform private.lock_and_validate_enrollment_schedule(v_offer_id, null);
  return v_offer_id;
end;
$$;


--
-- Name: create_enrollment_offer_pre_trial_offer_authority_impl(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_enrollment_offer_pre_trial_offer_authority_impl(p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := (select auth.uid());
  v_tenant_id text := private.active_tenant_id(v_actor_id);
  v_opportunity_id uuid;
  v_opportunity public.opportunities%rowtype;
  v_offer_id uuid;
begin
  if pg_catalog.jsonb_typeof(coalesce(p_payload, '{}'::jsonb))
       is distinct from 'object' then
    return public.create_enrollment_offer_pre_trial_lifecycle_impl(p_payload);
  end if;

  begin
    v_opportunity_id := nullif(
      pg_catalog.btrim(coalesce(p_payload ->> 'opportunityId', '')),
      ''
    )::uuid;
  exception when invalid_text_representation then
    return public.create_enrollment_offer_pre_trial_lifecycle_impl(p_payload);
  end;

  if v_opportunity_id is null then
    return public.create_enrollment_offer_pre_trial_lifecycle_impl(p_payload);
  end if;
  if v_actor_id is null or v_tenant_id is null then
    raise exception 'permission_denied' using errcode = '42501';
  end if;

  perform private.lock_trial_conversion_graph(v_opportunity_id);
  select opportunity.*
  into v_opportunity
  from public.opportunities as opportunity
  where opportunity.id = v_opportunity_id;

  if v_opportunity.tenant_id is distinct from v_tenant_id
     or v_opportunity.kind is distinct from 'TRIAL'
     or v_opportunity.status is distinct from 'CLAIMED'
     or v_opportunity.conversion_status is distinct from 'OPEN'
     or v_opportunity.trial_status is distinct from 'DONE' then
    raise exception 'trial_opportunity_not_eligible'
      using errcode = '23514';
  end if;
  if v_opportunity.feedback_required
     and not private.trial_feedback_is_complete(v_opportunity_id) then
    raise exception 'trial_feedback_required' using errcode = '23514';
  end if;
  if exists (
    select 1
    from public.offers as offer
    where offer.opportunity_id = v_opportunity_id
      and offer.kind = 'ENROLLMENT'
      and offer.revoked_at is null
      and offer.consumed_at is null
      and (
        offer.processing_by is not null
        or offer.processing_state <> 'NOT_STARTED'
      )
  ) or exists (
    select 1
    from public.enrollment_links as link
    where link.opportunity_id = v_opportunity_id
      and link.status = 'PROCESSING'
  ) then
    raise exception 'enrollment_in_progress' using errcode = '55000';
  end if;

  v_offer_id := public.create_enrollment_offer_pre_trial_lifecycle_impl(
    p_payload
  );
  if not exists (
    select 1
    from public.offers as offer
    where offer.id = v_offer_id
      and offer.opportunity_id = v_opportunity_id
      and offer.tenant_id = v_tenant_id
      and offer.kind = 'ENROLLMENT'
      and offer.revoked_at is null
  ) then
    raise exception 'enrollment_offer_scope_mismatch' using errcode = '23514';
  end if;
  return v_offer_id;
end;
$$;


--
-- Name: create_invite_offer(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invite_offer(p_kind text, p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  actor_id uuid := (SELECT auth.uid());
  actor_role text := private.active_tenant_role(actor_id);
  active_tenant_id text := private.active_tenant_id(actor_id);
  safe_payload jsonb;
  offer_id uuid;
BEGIN
  IF actor_id IS NULL
    OR active_tenant_id IS NULL
    OR coalesce(actor_role, '') NOT IN (
      'SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR'
    )
  THEN
    RAISE EXCEPTION 'permission_denied' USING ERRCODE = '42501';
  END IF;
  IF NOT private.tenant_is_operational(active_tenant_id) THEN
    RAISE EXCEPTION 'tenant_inactive' USING ERRCODE = '42501';
  END IF;
  IF p_kind IS NULL
    OR p_kind NOT IN ('TEACHER_INVITE', 'VENDOR_INVITE')
    OR p_payload IS NULL
    OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
    OR pg_column_size(p_payload) > 32768
  THEN
    RAISE EXCEPTION 'invalid_invite_payload' USING ERRCODE = '22023';
  END IF;
  IF p_payload ? 'tenant_id'
    OR (
      p_payload ? 'tenantId'
      AND p_payload ->> 'tenantId' IS DISTINCT FROM active_tenant_id
    )
  THEN
    RAISE EXCEPTION 'cross_tenant_invite_denied' USING ERRCODE = '42501';
  END IF;

  IF p_kind = 'TEACHER_INVITE' THEN
    IF EXISTS (
      SELECT 1
      FROM jsonb_object_keys(p_payload) AS supplied(key)
      WHERE supplied.key NOT IN (
        'kind', 'tenantId', 'hourlyRate', 'subject'
      )
    )
      OR jsonb_typeof(p_payload -> 'hourlyRate') IS DISTINCT FROM 'number'
      OR (p_payload ->> 'hourlyRate')::numeric NOT BETWEEN 1 AND 10000
      OR jsonb_typeof(p_payload -> 'subject') IS DISTINCT FROM 'string'
      OR length(trim(p_payload ->> 'subject')) NOT BETWEEN 2 AND 120
    THEN
      RAISE EXCEPTION 'invalid_teacher_invite' USING ERRCODE = '22023';
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1
      FROM jsonb_object_keys(p_payload) AS supplied(key)
      WHERE supplied.key NOT IN (
        'kind', 'tenantId', 'commissionRate', 'suggestedName'
      )
    )
      OR jsonb_typeof(p_payload -> 'commissionRate') IS DISTINCT FROM 'number'
      OR (p_payload ->> 'commissionRate')::numeric NOT BETWEEN 1 AND 10000000
      OR (p_payload ->> 'commissionRate')::numeric
        <> trunc((p_payload ->> 'commissionRate')::numeric)
      OR (
        p_payload ? 'suggestedName'
        AND p_payload -> 'suggestedName' IS DISTINCT FROM 'null'::jsonb
        AND (
          jsonb_typeof(p_payload -> 'suggestedName') IS DISTINCT FROM 'string'
          OR length(trim(p_payload ->> 'suggestedName')) > 120
        )
      )
    THEN
      RAISE EXCEPTION 'invalid_vendor_invite' USING ERRCODE = '22023';
    END IF;
  END IF;

  safe_payload := (p_payload - 'tenant_id' - 'tenantId' - 'kind')
    || jsonb_build_object(
      'kind', p_kind,
      'tenantId', active_tenant_id
    );
  IF p_kind = 'TEACHER_INVITE' THEN
    safe_payload := safe_payload || jsonb_build_object(
      'hourlyRate', (p_payload ->> 'hourlyRate')::numeric,
      'subject', trim(p_payload ->> 'subject'),
      'schoolInfo', private.contract_school_info(active_tenant_id)
    );
  END IF;

  INSERT INTO public.offers (
    kind,
    tenant_id,
    payload,
    expires_at,
    created_by,
    invite_security_version
  )
  VALUES (
    p_kind,
    active_tenant_id,
    safe_payload,
    now() + CASE
      WHEN p_kind = 'TEACHER_INVITE' THEN interval '48 hours'
      ELSE interval '7 days'
    END,
    actor_id,
    1
  )
  RETURNING id INTO offer_id;

  RETURN offer_id;
END;
$$;


--
-- Name: create_student_plan_change(uuid, text, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_student_plan_change(p_student_id uuid, p_to_frequency text, p_to_fee numeric, p_update_pending_payments boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  target_tenant_id text;
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'Sem permissão'
    );
  END IF;
  SELECT student.tenant_id
  INTO target_tenant_id
  FROM public.profiles AS student
  WHERE student.id = p_student_id
    AND student.role = 'STUDENT';
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'Aluno não encontrado'
    );
  END IF;
  IF NOT private.legacy_role_rpc_target_allowed(target_tenant_id) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'Sem permissão'
    );
  END IF;
  RETURN public.create_student_plan_change_unchecked(
    p_student_id,
    p_to_frequency,
    p_to_fee,
    p_update_pending_payments
  );
END;
$$;


--
-- Name: create_student_plan_change_unchecked(uuid, text, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_student_plan_change_unchecked(p_student_id uuid, p_to_frequency text, p_to_fee numeric, p_update_pending_payments boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_tenant text;
  v_from_freq text;
  v_from_fee numeric;
  v_fidelity text;
  v_token text;
  v_freq text;
begin
  select tenant_id, class_frequency, monthly_fee, fidelity_plan
    into v_tenant, v_from_freq, v_from_fee, v_fidelity
    from public.profiles
   where id = p_student_id and role = 'STUDENT';

  if v_tenant is null then
    return jsonb_build_object('ok', false, 'error', 'Aluno não encontrado');
  end if;

  if not (v_tenant = public._my_tenant_id()
          and public._my_role() = any (array['SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN'])) then
    return jsonb_build_object('ok', false, 'error', 'Sem permissão');
  end if;

  v_freq := lower(btrim(coalesce(p_to_frequency, '')));
  if v_freq !~ '^[1-9][0-9]?x$' then
    return jsonb_build_object('ok', false, 'error', 'Frequência inválida (use algo como "6x")');
  end if;

  if p_to_fee is null or p_to_fee <= 0 then
    return jsonb_build_object('ok', false, 'error', 'Informe o novo valor da mensalidade');
  end if;

  if v_freq = lower(coalesce(v_from_freq, '')) and p_to_fee = v_from_fee then
    return jsonb_build_object('ok', false, 'error', 'O plano proposto é igual ao atual');
  end if;

  update public.student_plan_changes
     set status = 'CANCELLED', cancelled_at = now()
   where student_id = p_student_id and status = 'PENDING';

  insert into public.student_plan_changes (
    tenant_id, student_id, created_by,
    from_frequency, to_frequency, from_monthly_fee, to_monthly_fee, fidelity_plan,
    update_pending_payments
  ) values (
    v_tenant, p_student_id, auth.uid(),
    v_from_freq, v_freq, v_from_fee, p_to_fee, v_fidelity,
    coalesce(p_update_pending_payments, true)
  )
  returning token into v_token;

  return jsonb_build_object('ok', true, 'token', v_token);
end;
$_$;


--
-- Name: create_teacher_transfer(uuid, uuid, jsonb, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_teacher_transfer(p_student_id uuid, p_to_teacher uuid, p_slots jsonb, p_cutover date, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
  IF NOT private.can_create_teacher_transfer(p_student_id, p_to_teacher) THEN
    RAISE EXCEPTION 'teacher_transfer_tenant_mismatch' USING ERRCODE = '42501';
  END IF;

  IF p_cutover IS NULL
    OR p_cutover < current_date
    OR jsonb_typeof(p_slots) IS DISTINCT FROM 'array'
    OR jsonb_array_length(p_slots) < 1
    OR jsonb_array_length(p_slots) > 14
    OR length(coalesce(p_reason, '')) > 1000
  THEN
    RAISE EXCEPTION 'invalid_teacher_transfer_payload' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_slots) AS slot
    WHERE jsonb_typeof(slot) IS DISTINCT FROM 'object'
      OR slot->>'day_of_week' NOT IN (
        'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'
      )
      OR coalesce(slot->>'time_slot', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
  ) OR EXISTS (
    SELECT 1
    FROM jsonb_array_elements(p_slots) AS slot
    GROUP BY slot->>'day_of_week', slot->>'time_slot'
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'invalid_teacher_transfer_slots' USING ERRCODE = '22023';
  END IF;

  RETURN public.create_teacher_transfer_unchecked(
    p_student_id,
    p_to_teacher,
    p_slots,
    p_cutover,
    p_reason
  );
END;
$_$;


--
-- Name: FUNCTION create_teacher_transfer(p_student_id uuid, p_to_teacher uuid, p_slots jsonb, p_cutover date, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_teacher_transfer(p_student_id uuid, p_to_teacher uuid, p_slots jsonb, p_cutover date, p_reason text) IS 'Creates a transfer only when student, target teacher and active admin context share the same tenant.';


--
-- Name: create_teacher_transfer_unchecked(uuid, uuid, jsonb, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_teacher_transfer_unchecked(p_student_id uuid, p_to_teacher uuid, p_slots jsonb, p_cutover date, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_tenant text; v_from uuid; v_token text; v_conflict int;
BEGIN
    SELECT tenant_id, professor_id INTO v_tenant, v_from FROM public.profiles WHERE id = p_student_id;
    IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'Aluno não encontrado'); END IF;
    -- Autorização: admin do mesmo tenant
    IF NOT (v_tenant = _my_tenant_id() AND _my_role() = ANY (ARRAY['SCHOOL_ADMIN','SUPER_ADMIN'])) THEN
        RETURN jsonb_build_object('ok', false, 'error', 'Sem permissão');
    END IF;
    IF p_to_teacher = v_from THEN
        RETURN jsonb_build_object('ok', false, 'error', 'O novo professor é o mesmo professor atual');
    END IF;
    IF jsonb_array_length(COALESCE(p_slots, '[]'::jsonb)) = 0 THEN
        RETURN jsonb_build_object('ok', false, 'error', 'Selecione ao menos um horário');
    END IF;
    -- Conflito: o novo professor já tem booking recorrente em algum slot proposto?
    SELECT count(*) INTO v_conflict
    FROM jsonb_array_elements(p_slots) s
    JOIN public.bookings b
      ON b.teacher_id = p_to_teacher
     AND b.day_of_week IS NOT NULL
     AND b.day_of_week = (s->>'day_of_week')
     AND b.time_slot = (s->>'time_slot');
    IF v_conflict > 0 THEN
        RETURN jsonb_build_object('ok', false, 'error', 'O novo professor já tem aula em um dos horários escolhidos');
    END IF;

    INSERT INTO public.teacher_transfers
        (tenant_id, student_id, from_teacher_id, to_teacher_id, proposed_slots, cutover_date, reason, created_by)
    VALUES (v_tenant, p_student_id, v_from, p_to_teacher, p_slots, p_cutover, p_reason, auth.uid())
    RETURNING token INTO v_token;

    RETURN jsonb_build_object('ok', true, 'token', v_token);
END;
$$;


--
-- Name: create_trial_reschedule_confirmation(text, uuid, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_trial_reschedule_confirmation(p_tenant_id text, p_opportunity_id uuid, p_appointment_id uuid, p_teacher_id uuid, p_lead_id uuid, p_requested_start_time timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare
  v_appointment public.appointments%rowtype;
  v_pending public.trial_reschedule_requests%rowtype;
  v_request public.trial_reschedule_requests%rowtype;
begin
  select appointment.*
    into v_appointment
    from public.appointments as appointment
   where appointment.id = p_appointment_id
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'appointment_not_found');
  end if;
  if v_appointment.tenant_id is distinct from p_tenant_id
     or coalesce(v_appointment.teacher_id, v_appointment.professor_id) is distinct from p_teacher_id then
    return jsonb_build_object('ok', false, 'error', 'appointment_owner_mismatch');
  end if;
  if lower(coalesce(v_appointment.status, '')) not in (
    'scheduled', 'confirmed', 'no_show'
  ) then
    return jsonb_build_object('ok', false, 'error', 'appointment_not_scheduled');
  end if;
  if p_requested_start_time is null or p_requested_start_time <= now() then
    return jsonb_build_object('ok', false, 'error', 'requested_time_not_future');
  end if;
  if p_requested_start_time = v_appointment.start_time then
    return jsonb_build_object('ok', true, 'created', false, 'same_time', true);
  end if;
  if not exists (
    select 1
      from public.opportunities as opportunity
     where opportunity.id = p_opportunity_id
       and opportunity.tenant_id = p_tenant_id
       and opportunity.trial_appointment_id = p_appointment_id
       and coalesce(opportunity.winner_teacher_id, opportunity.professor_id) = p_teacher_id
       and upper(coalesce(opportunity.trial_status, 'SCHEDULED')) not in (
         'DONE', 'COMPLETED', 'CANCELLED', 'CANCELED'
       )
       and not exists (
         select 1
           from public.class_logs as class_log
          where class_log.appointment_id = p_appointment_id::text
       )
  ) then
    return jsonb_build_object('ok', false, 'error', 'opportunity_mismatch');
  end if;

  select request.*
    into v_pending
    from public.trial_reschedule_requests as request
   where request.appointment_id = p_appointment_id
     and request.status = 'PENDING'
   for update;

  if found
     and v_pending.requested_start_time = p_requested_start_time
     and v_pending.from_start_time = v_appointment.start_time
     and v_pending.expires_at > now() then
    return jsonb_build_object(
      'ok', true,
      'created', false,
      'request_id', v_pending.id,
      'reply_code', v_pending.reply_code
    );
  end if;

  update public.trial_reschedule_requests
     set status = 'SUPERSEDED', responded_at = now()
   where appointment_id = p_appointment_id
     and status = 'PENDING';

  insert into public.trial_reschedule_requests (
    tenant_id,
    opportunity_id,
    appointment_id,
    teacher_id,
    lead_id,
    from_start_time,
    requested_start_time,
    expires_at
  ) values (
    p_tenant_id,
    p_opportunity_id,
    p_appointment_id,
    p_teacher_id,
    p_lead_id,
    v_appointment.start_time,
    p_requested_start_time,
    least(now() + interval '24 hours', p_requested_start_time)
  )
  returning * into v_request;

  return jsonb_build_object(
    'ok', true,
    'created', true,
    'request_id', v_request.id,
    'reply_code', v_request.reply_code
  );
end;
$$;


--
-- Name: create_vendor_trial_link_secure(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_vendor_trial_link_secure(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_id uuid;
  v_tenant_id text;
  v_actor_role text;
  v_request_id uuid;
  v_teacher_id uuid;
  v_teacher_name text;
  v_student_name text;
  v_student_phone text;
  v_weekday integer;
  v_slot_time time without time zone;
  v_local_now timestamp without time zone;
  v_slot_date date;
  v_start_time timestamptz;
  v_slot jsonb;
  v_opportunity_id uuid;
  v_link_id uuid;
  v_link_token text;
  v_link_url text;
  v_fingerprint text;
  v_existing_fingerprint text;
  v_existing_response jsonb;
  v_response jsonb;
begin
  if jsonb_typeof(p_payload) is distinct from 'object'
     or not p_payload ?& array[
       'requestId', 'teacherId', 'studentName',
       'studentPhone', 'weekday', 'time'
     ]
     or (select count(*) from jsonb_object_keys(p_payload)) <> 6 then
    return jsonb_build_object('ok', false, 'error', 'invalid_payload');
  end if;

  begin
    v_request_id := (p_payload ->> 'requestId')::uuid;
    v_teacher_id := (p_payload ->> 'teacherId')::uuid;
    v_weekday := (p_payload ->> 'weekday')::integer;
    v_slot_time := (p_payload ->> 'time')::time;
  exception
    when invalid_text_representation
       or invalid_datetime_format
       or datetime_field_overflow then
      return jsonb_build_object('ok', false, 'error', 'invalid_payload');
  end;

  if jsonb_typeof(p_payload -> 'weekday') <> 'number'
     or v_weekday not between 0 and 6
     or coalesce(p_payload ->> 'time', '') !~
        '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_slot');
  end if;

  v_student_name := trim(coalesce(p_payload ->> 'studentName', ''));
  v_student_phone := regexp_replace(
    coalesce(p_payload ->> 'studentPhone', ''), '[^0-9]', '', 'g'
  );
  if length(v_student_name) not between 2 and 160 then
    return jsonb_build_object('ok', false, 'error', 'invalid_student_name');
  end if;
  if length(v_student_phone) not between 10 and 15 then
    return jsonb_build_object('ok', false, 'error', 'invalid_student_phone');
  end if;

  select actor.actor_id, actor.tenant_id, actor.actor_role
    into v_actor_id, v_tenant_id, v_actor_role
    from private.secure_trial_actor_context() as actor;

  if v_actor_id is null or v_actor_role <> 'SALESPERSON' then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if not private.tenant_is_operational(v_tenant_id) then
    return jsonb_build_object('ok', false, 'error', 'tenant_not_operational');
  end if;

  select profile.full_name
    into v_teacher_name
    from public.profiles as profile
    join public.tenant_memberships as membership
      on membership.user_id = profile.id
     and membership.tenant_id = v_tenant_id
     and membership.role = 'TEACHER'
     and membership.status = 'ACTIVE'
   where profile.id = v_teacher_id
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
   for share of profile, membership;

  if not found then
    return jsonb_build_object(
      'ok', false, 'error', 'teacher_not_active_for_tenant'
    );
  end if;

  v_local_now := now() at time zone 'America/Sao_Paulo';
  v_slot_date := v_local_now::date +
    ((v_weekday - extract(dow from v_local_now)::integer + 7) % 7);
  v_start_time := (v_slot_date + v_slot_time)
    at time zone 'America/Sao_Paulo';
  if v_start_time < now() + interval '1 hour' then
    v_slot_date := v_slot_date + 7;
    v_start_time := (v_slot_date + v_slot_time)
      at time zone 'America/Sao_Paulo';
  end if;
  if v_start_time > now() + interval '31 days' then
    return jsonb_build_object('ok', false, 'error', 'invalid_slot');
  end if;

  v_fingerprint := private.secure_trial_payload_fingerprint(p_payload);
  select receipt.payload_fingerprint, receipt.response
    into v_existing_fingerprint, v_existing_response
    from private.secure_trial_command_receipts as receipt
   where receipt.tenant_id = v_tenant_id
     and receipt.actor_id = v_actor_id
     and receipt.command = 'VENDOR_TRIAL_LINK'
     and receipt.request_id = v_request_id;
  if found then
    if v_existing_fingerprint <> v_fingerprint then
      return jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    return coalesce(v_existing_response, '{}'::jsonb)
      || jsonb_build_object('idempotent', true);
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_teacher_id::text, 0)
  );

  select receipt.payload_fingerprint, receipt.response
    into v_existing_fingerprint, v_existing_response
    from private.secure_trial_command_receipts as receipt
   where receipt.tenant_id = v_tenant_id
     and receipt.actor_id = v_actor_id
     and receipt.command = 'VENDOR_TRIAL_LINK'
     and receipt.request_id = v_request_id;
  if found then
    if v_existing_fingerprint <> v_fingerprint then
      return jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    return coalesce(v_existing_response, '{}'::jsonb)
      || jsonb_build_object('idempotent', true);
  end if;

  if private.secure_trial_schedule_conflict(
    v_tenant_id, v_teacher_id, v_start_time, null, null
  ) then
    return jsonb_build_object(
      'ok', false, 'error', 'teacher_schedule_conflict'
    );
  end if;

  insert into private.secure_trial_command_receipts (
    tenant_id, actor_id, command, request_id, payload_fingerprint
  ) values (
    v_tenant_id, v_actor_id, 'VENDOR_TRIAL_LINK',
    v_request_id, v_fingerprint
  )
  on conflict do nothing;

  if not found then
    select receipt.payload_fingerprint, receipt.response
      into v_existing_fingerprint, v_existing_response
      from private.secure_trial_command_receipts as receipt
     where receipt.tenant_id = v_tenant_id
       and receipt.actor_id = v_actor_id
       and receipt.command = 'VENDOR_TRIAL_LINK'
       and receipt.request_id = v_request_id;
    if v_existing_fingerprint <> v_fingerprint then
      return jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    return coalesce(v_existing_response, '{}'::jsonb)
      || jsonb_build_object('idempotent', true);
  end if;

  v_slot := jsonb_build_object(
    'day', v_weekday,
    'date', to_char(v_slot_date, 'YYYY-MM-DD'),
    'time', to_char(v_slot_time, 'HH24:MI'),
    'formatted', to_char(v_slot_date, 'DD/MM/YYYY') || ' às ' ||
      to_char(v_slot_time, 'HH24:MI'),
    'start_time', v_start_time
  );
  v_link_token := pg_catalog.encode(
    extensions.gen_random_bytes(24), 'hex'
  );
  v_link_url := private.secure_trial_portal_origin(v_tenant_id)
    || '/experimental?token=' || v_link_token;

  insert into public.opportunities (
    tenant_id, student_name, student_phone, slots_proposed,
    status, kind, conversion_status, created_by_vendor_id,
    opened_at, claim_generation
  ) values (
    v_tenant_id, v_student_name, v_student_phone,
    jsonb_build_array(v_slot), 'OPEN', 'TRIAL', 'OPEN', v_actor_id,
    now(), 1
  )
  returning id into v_opportunity_id;

  insert into public.enrollment_links (
    tenant_id, opportunity_id, link_token, link_url,
    student_name, student_phone, professor_id,
    status, created_by_vendor_id, purpose, expires_at
  ) values (
    v_tenant_id, v_opportunity_id, v_link_token, v_link_url,
    v_student_name, v_student_phone, v_teacher_id,
    'PENDING', v_actor_id, 'TRIAL_CONFIRMATION', v_start_time
  )
  returning id into v_link_id;

  insert into private.vendor_trial_teacher_requests (
    tenant_id, opportunity_id, enrollment_link_id,
    target_teacher_id, requested_by, slot_start, status
  ) values (
    v_tenant_id, v_opportunity_id, v_link_id,
    v_teacher_id, v_actor_id, v_start_time, 'AWAITING_STUDENT'
  );

  v_response := jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'opportunityId', v_opportunity_id,
    'linkId', v_link_id,
    'confirmationUrl', v_link_url,
    'teacherName', coalesce(nullif(trim(v_teacher_name), ''), 'Professor(a)'),
    'startsAt', v_start_time,
    'state', 'AWAITING_STUDENT'
  );

  update private.secure_trial_command_receipts
     set response = v_response,
         completed_at = now()
   where tenant_id = v_tenant_id
     and actor_id = v_actor_id
     and command = 'VENDOR_TRIAL_LINK'
     and request_id = v_request_id;

  return v_response;
end;
$_$;


--
-- Name: create_wolfie_activity_session(uuid, text, text, text, text, text, uuid, uuid, jsonb, jsonb, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_wolfie_activity_session(p_student_id uuid, p_subject text, p_cefr_level text, p_sector text, p_phase text, p_modality text, p_source_session_id uuid, p_request_key uuid, p_activity_content jsonb, p_answer_key jsonb, p_reused_terms text[], p_introduced_terms text[]) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.create_wolfie_activity_session(
    private.active_tenant_id(p_student_id),
    p_student_id,
    p_subject,
    p_cefr_level,
    p_sector,
    p_phase,
    p_modality,
    p_source_session_id,
    p_request_key,
    p_activity_content,
    p_answer_key,
    p_reused_terms,
    p_introduced_terms
  );
$$;


--
-- Name: create_wolfie_activity_session(text, uuid, text, text, text, text, text, uuid, uuid, jsonb, jsonb, text[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_wolfie_activity_session(p_tenant_id text, p_student_id uuid, p_subject text, p_cefr_level text, p_sector text, p_phase text, p_modality text, p_source_session_id uuid, p_request_key uuid, p_activity_content jsonb, p_answer_key jsonb, p_reused_terms text[], p_introduced_terms text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session public.wolfie_activity_sessions%rowtype;
begin
  if p_tenant_id is null
     or pg_catalog.btrim(p_tenant_id) = ''
     or p_student_id is null
     or p_request_key is null then
    raise exception 'invalid_activity_request_identity';
  end if;

  if not exists (
    select 1
      from public.profiles as profile
      join public.tenant_memberships as membership
        on membership.user_id = profile.id
       and membership.tenant_id = p_tenant_id
       and membership.status = 'ACTIVE'
       and membership.role = 'STUDENT'
     where profile.id = p_student_id
       and profile.role = 'STUDENT'
  ) then
    raise exception 'student_active_tenant_membership_not_found';
  end if;

  begin
    insert into public.wolfie_activity_sessions (
      tenant_id,
      student_id,
      subject,
      cefr_level,
      sector,
      phase,
      modality,
      source_session_id,
      request_key,
      activity_content,
      reused_terms,
      introduced_terms
    ) values (
      p_tenant_id,
      p_student_id,
      p_subject,
      p_cefr_level,
      nullif(pg_catalog.btrim(p_sector), ''),
      p_phase,
      p_modality,
      p_source_session_id,
      p_request_key,
      coalesce(p_activity_content, '{}'::jsonb),
      coalesce(p_reused_terms, '{}'::text[]),
      coalesce(p_introduced_terms, '{}'::text[])
    )
    returning * into v_session;

    insert into public.wolfie_activity_keys (session_id, answer_key)
    values (v_session.id, coalesce(p_answer_key, '{}'::jsonb));
  exception
    when unique_violation then
      select session.*
        into v_session
        from public.wolfie_activity_sessions as session
       where session.tenant_id = p_tenant_id
         and session.student_id = p_student_id
         and session.request_key = p_request_key;
      if not found then
        raise;
      end if;
      if v_session.subject is distinct from p_subject
         or v_session.cefr_level is distinct from p_cefr_level
         or v_session.phase is distinct from p_phase
         or v_session.modality is distinct from p_modality
         or v_session.source_session_id is distinct from p_source_session_id then
        raise exception 'activity_request_key_reused';
      end if;
  end;

  return pg_catalog.to_jsonb(v_session);
end;
$$;


--
-- Name: crm_leads_dedupe_before_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.crm_leads_dedupe_before_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tail text;
  v_existing_id uuid;
BEGIN
  v_tail := right(regexp_replace(COALESCE(NEW.phone,''), '\D', '', 'g'), 10);
  IF length(v_tail) < 10 THEN
    RETURN NEW; -- sem telefone válido: deixa inserir normalmente
  END IF;

  SELECT id INTO v_existing_id
  FROM crm_leads
  WHERE tenant_id = NEW.tenant_id
    AND right(regexp_replace(COALESCE(phone,''), '\D', '', 'g'), 10) = v_tail
  ORDER BY created_at ASC
  LIMIT 1;

  IF v_existing_id IS NULL THEN
    RETURN NEW; -- telefone novo: insere
  END IF;

  -- já existe: enriquece o canônico com o que veio de novo (sem sobrescrever o que já tem)
  UPDATE crm_leads SET
    name  = COALESCE(name,  NEW.name),
    goal  = COALESCE(goal,  NEW.goal),
    level = COALESCE(level, NEW.level),
    notes = COALESCE(notes, NEW.notes)
  WHERE id = v_existing_id;

  RETURN NULL; -- pula o insert do duplicado (sem lançar erro)
END;
$$;


--
-- Name: defer_plan_change_billing_claim(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.defer_plan_change_billing_claim(p_id uuid, p_claim_token uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_plan_change public.student_plan_changes%rowtype;
begin
  if p_id is null or p_claim_token is null then
    raise exception 'plan_change_claim_arguments_required'
      using errcode = '22023';
  end if;
  select queued.* into v_plan_change
    from public.student_plan_changes as queued
   where queued.id = p_id
   for update;
  if not found
     or v_plan_change.billing_sync_status <> 'PENDING'
     or v_plan_change.billing_claim_token is distinct from p_claim_token
  then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;
  update public.student_plan_changes
     set billing_claim_token = null,
         billing_lease_expires_at = null,
         billing_claimed_at = null,
         billing_attempts = greatest(billing_attempts - 1, 0),
         billing_sync_error = nullif(
           pg_catalog.left(coalesce(p_reason, ''), 500),
           ''
         )
   where id = v_plan_change.id
     and billing_claim_token = p_claim_token;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'status', 'PENDING', 'deferred', true
  );
end;
$$;


--
-- Name: delete_collection(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_collection(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  target_tenant_id text;
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  SELECT collection.tenant_id
  INTO target_tenant_id
  FROM public.pedagogical_collections AS collection
  WHERE collection.id = p_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'nao_encontrado'
    );
  END IF;
  IF NOT private.legacy_role_rpc_target_allowed(target_tenant_id) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  RETURN public.delete_collection_unchecked(p_id);
END;
$$;


--
-- Name: delete_collection_unchecked(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_collection_unchecked(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; c_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;
  SELECT tenant_id INTO c_tenant FROM pedagogical_collections WHERE id = p_id;
  IF c_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'nao_encontrado'); END IF;
  IF v_role = 'SCHOOL_ADMIN' AND c_tenant <> v_tenant THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;
  DELETE FROM pedagogical_collections WHERE id = p_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: delete_learning_unit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_learning_unit(p_unit_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_path_id uuid;
  v_deleted_id uuid;
begin
  if p_unit_id is null then
    raise exception using
      errcode = '22023',
      message = 'learning_unit_id_required';
  end if;

  select unit.path_id
    into v_path_id
    from public.learning_units as unit
   where unit.id = p_unit_id;

  perform private.lock_mutable_learning_path(v_path_id);

  delete from public.learning_units as unit
   where unit.id = p_unit_id
     and unit.path_id = v_path_id
  returning unit.id into v_deleted_id;

  if v_deleted_id is null then
    raise exception using
      errcode = '55000',
      message = 'learning_unit_changed_during_mutation';
  end if;

  return pg_catalog.jsonb_build_object(
    'unitId', v_deleted_id,
    'pathId', v_path_id,
    'deleted', true
  );
end;
$$;


--
-- Name: delete_niche(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_niche(p_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  RETURN public.delete_niche_unchecked(p_key);
END;
$$;


--
-- Name: delete_niche_unchecked(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_niche_unchecked(p_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;
  IF p_key = 'GENERAL' THEN RETURN jsonb_build_object('ok', false, 'error', 'general_protegido'); END IF;

  UPDATE pedagogical_materials   SET niche = 'GENERAL' WHERE tenant_id = v_tenant AND niche = p_key;
  UPDATE pedagogical_collections SET niche = 'GENERAL' WHERE tenant_id = v_tenant AND niche = p_key;
  DELETE FROM tenant_niches WHERE tenant_id = v_tenant AND key = p_key;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'nao_encontrado'); END IF;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: delete_recurring_expense(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_recurring_expense(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; v_n int;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;
  -- Os lançamentos já materializados ficam (ON DELETE SET NULL): a despesa
  -- aconteceu, apagar o molde não desfaz o mês passado.
  DELETE FROM recurring_expenses WHERE id = p_id AND tenant_id = v_tenant;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RETURN jsonb_build_object('error','nao_encontrada'); END IF;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: delete_tenant_data(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_tenant_data(p_tenant_id text, p_confirm_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_role TEXT;
    v_count_profiles INT;
    v_count_bookings INT;
BEGIN
    SELECT role INTO v_role FROM profiles WHERE id = auth.uid();
    IF v_role <> 'SUPER_ADMIN' THEN RAISE EXCEPTION 'Only SUPER_ADMIN can delete tenant data'; END IF;
    IF p_confirm_text <> ('DELETE ' || p_tenant_id) THEN
        RAISE EXCEPTION 'Confirmation text must be: DELETE % (recebido: %)', p_tenant_id, p_confirm_text;
    END IF;

    -- Anonimizar PII em profiles (mantém id pra integridade referencial)
    UPDATE profiles SET
        full_name = '[REMOVED]',
        email = 'deleted+' || id::TEXT || '@anonymized.local',
        phone = NULL,
        cpf = NULL,
        rg = NULL,
        address = NULL,
        avatar_url = NULL,
        whatsapp_instance = NULL,
        meeting_link = NULL,
        pix_key = NULL,
        accumulated_context = NULL,
        student_profile_json = NULL
    WHERE tenant_id = p_tenant_id;
    GET DIAGNOSTICS v_count_profiles = ROW_COUNT;

    -- Limpar dados sensíveis nas outras tabelas
    DELETE FROM wolfie_corrections WHERE session_id IN (SELECT id FROM wolfie_sessions WHERE student_id IN (SELECT id FROM profiles WHERE tenant_id = p_tenant_id));
    DELETE FROM wolfie_turns WHERE session_id IN (SELECT id FROM wolfie_sessions WHERE student_id IN (SELECT id FROM profiles WHERE tenant_id = p_tenant_id));
    DELETE FROM wolfie_sessions WHERE student_id IN (SELECT id FROM profiles WHERE tenant_id = p_tenant_id);
    DELETE FROM student_vocab_reviews WHERE student_id IN (SELECT id FROM profiles WHERE tenant_id = p_tenant_id);
    DELETE FROM student_activity_progress WHERE student_id IN (SELECT id FROM profiles WHERE tenant_id = p_tenant_id);
    DELETE FROM student_path_enrollments WHERE student_id IN (SELECT id FROM profiles WHERE tenant_id = p_tenant_id);
    DELETE FROM student_skill_scores WHERE student_id IN (SELECT id FROM profiles WHERE tenant_id = p_tenant_id);
    DELETE FROM wolf_intelligence WHERE tenant_id = p_tenant_id;
    DELETE FROM notification_queue WHERE tenant_id = p_tenant_id;
    DELETE FROM bookings WHERE tenant_id = p_tenant_id;
    GET DIAGNOSTICS v_count_bookings = ROW_COUNT;
    DELETE FROM class_logs WHERE tenant_id = p_tenant_id;
    DELETE FROM reschedules WHERE tenant_id = p_tenant_id;

    -- Marcar tenant como CANCELLED (não deletar — compliance fiscal)
    UPDATE tenants SET saas_status = 'CANCELLED', name = '[REMOVED]'
    WHERE id = p_tenant_id;

    RETURN jsonb_build_object(
        'status', 'OK',
        'tenant_id', p_tenant_id,
        'profiles_anonymized', v_count_profiles,
        'bookings_deleted', v_count_bookings
    );
END;
$$;


--
-- Name: delete_tenant_integration_secret(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_tenant_integration_secret(p_tenant_id text, p_provider text, p_actor_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  stored_secret_id uuid;
  actor_role text;
BEGIN
  IF p_provider NOT IN ('asaas', 'evolution', 'openai', 'openrouter') THEN
    RAISE EXCEPTION 'invalid_provider' USING ERRCODE = '22023';
  END IF;

  IF NOT private.tenant_is_operational(p_tenant_id) THEN
    RAISE EXCEPTION 'tenant_not_operational' USING ERRCODE = '55000';
  END IF;

  actor_role := private.active_tenant_role(p_actor_id);
  IF p_actor_id IS NULL
    OR actor_role NOT IN ('SCHOOL_ADMIN', 'SUPER_ADMIN')
    OR private.active_tenant_id(p_actor_id) IS DISTINCT FROM p_tenant_id
  THEN
    RAISE EXCEPTION 'cross_tenant_access_denied' USING ERRCODE = '42501';
  END IF;

  DELETE FROM private.tenant_secret_registry AS registry
  WHERE registry.tenant_id = p_tenant_id
    AND registry.provider = p_provider
  RETURNING registry.vault_secret_id INTO stored_secret_id;

  IF stored_secret_id IS NULL THEN
    RETURN false;
  END IF;

  DELETE FROM vault.secrets WHERE id = stored_secret_id;

  INSERT INTO public.tenant_configuration_audit (
    tenant_id,
    actor_id,
    actor_role,
    action,
    section,
    changes
  )
  VALUES (
    p_tenant_id,
    p_actor_id,
    actor_role,
    'credential_removed',
    'integrations',
    jsonb_build_object('provider', p_provider, 'configured', false)
  );

  RETURN true;
END;
$$;


--
-- Name: delete_unit_activity(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_unit_activity(p_activity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_path_id uuid;
  v_unit_id uuid;
  v_deleted_id uuid;
begin
  if p_activity_id is null then
    raise exception using
      errcode = '22023',
      message = 'unit_activity_id_required';
  end if;

  select unit.path_id, activity.unit_id
    into v_path_id, v_unit_id
    from public.unit_activities as activity
    join public.learning_units as unit
      on unit.id = activity.unit_id
   where activity.id = p_activity_id;

  perform private.lock_mutable_learning_path(v_path_id);

  delete from public.unit_activities as activity
   where activity.id = p_activity_id
     and activity.unit_id = v_unit_id
  returning activity.id into v_deleted_id;

  if v_deleted_id is null then
    raise exception using
      errcode = '55000',
      message = 'unit_activity_changed_during_mutation';
  end if;

  return pg_catalog.jsonb_build_object(
    'activityId', v_deleted_id,
    'unitId', v_unit_id,
    'pathId', v_path_id,
    'deleted', true
  );
end;
$$;


--
-- Name: detect_due_oral_tests(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_due_oral_tests(p_tenant text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_tenant_id text;
  v_count integer;
begin
  if p_tenant is null or btrim(p_tenant) = '' then
    raise exception
      using errcode = '22023', message = 'Tenant is required';
  end if;

  if coalesce(auth.role(), '') <> 'service_role' then
    if v_uid is null then
      raise exception
        using errcode = '28000', message = 'Authentication required';
    end if;

    select p.role, p.tenant_id
      into v_role, v_tenant_id
      from public.profiles as p
     where p.id = v_uid;

    if v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN')
       or (
         v_role <> 'SUPER_ADMIN'
         and v_tenant_id is distinct from p_tenant
       ) then
      raise exception
        using errcode = '42501', message = 'Administrator role required';
    end if;
  end if;

  with base as (
    select
      p.id as student_id,
      p.tenant_id,
      (
        select min(cl.class_date)::date
          from public.class_logs as cl
         where cl.student_id = p.id
      ) as first_class,
      (
        select max(ot.done_at)::date
          from public.oral_tests as ot
         where ot.student_id = p.id
           and ot.status = 'DONE'
      ) as last_done
    from public.profiles as p
    where p.tenant_id = p_tenant
      and p.role = 'STUDENT'
      and coalesce(p.lifecycle_status, 'active') = 'active'
      and coalesce(p.is_test_account, false) is false
  ),
  eligible as (
    select
      base.student_id,
      base.tenant_id,
      coalesce(base.last_done, base.first_class) as baseline
    from base
    where base.first_class is not null
      and coalesce(base.last_done, base.first_class)
        <= (current_date - interval '45 days')::date
  ),
  native_teacher as (
    select ranked.student_id, ranked.teacher_id
      from (
        select
          cl.student_id,
          cl.teacher_id,
          row_number() over (
            partition by cl.student_id
            order by count(*) desc, cl.teacher_id
          ) as position
        from public.class_logs as cl
        join eligible as e on e.student_id = cl.student_id
        where cl.teacher_id is not null
        group by cl.student_id, cl.teacher_id
      ) as ranked
     where ranked.position = 1
  ),
  inserted as (
    insert into public.oral_tests (
      tenant_id,
      student_id,
      native_teacher_id,
      status,
      cycle_start,
      due_date
    )
    select
      e.tenant_id,
      e.student_id,
      nt.teacher_id,
      'DUE',
      e.baseline,
      (e.baseline + interval '45 days')::date
    from eligible as e
    left join native_teacher as nt on nt.student_id = e.student_id
    on conflict (student_id, cycle_start) do nothing
    returning 1
  )
  select count(*) into v_count from inserted;

  return v_count;
end;
$$;


--
-- Name: director_pending_counts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.director_pending_counts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id text;
  v_today date := pg_catalog.timezone(
    'America/Sao_Paulo', pg_catalog.now()
  )::date;
  v_counts jsonb;
  v_payment_notification_attention integer := 0;
  v_unlinked_payments integer := 0;
  v_asaas_attention integer := 0;
  v_latest_run_id uuid;
begin
  if not private.can_execute_legacy_role_rpc(
    array['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) then
    return '{}'::jsonb;
  end if;

  v_tenant_id := private.active_tenant_id((select auth.uid()));
  v_counts := coalesce(
    public.director_pending_counts_unchecked(),
    '{}'::jsonb
  );

  if v_tenant_id is not null then
    select pg_catalog.count(*)::integer
      into v_payment_notification_attention
      from public.management_payment_notification_outbox as outbox
     where outbox.tenant_id = v_tenant_id
       and outbox.status in ('SUBMITTING', 'FAILED', 'UNKNOWN');

    select pg_catalog.count(distinct coalesce(
             nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), ''),
             nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), ''),
             payment.id::text
           ))::integer
      into v_unlinked_payments
      from public.student_payments as payment
     where payment.tenant_id = v_tenant_id
       and payment.student_id is null
       and upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
         'PENDING', 'OVERDUE', 'CONFIRMED', 'RECEIVED', 'RECEIVED_IN_CASH'
       );

    select run.id
      into v_latest_run_id
      from public.asaas_reconciliation_runs as run
     where run.status = 'COMPLETED'
       and run.metrics ->> 'tenantId' = v_tenant_id
       and run.window_end - run.window_start >= 44
       and run.window_start <= v_today - 45
       and run.window_end >= v_today - 1
       and run.finished_at >= pg_catalog.now() - interval '36 hours'
     order by run.finished_at desc nulls last, run.started_at desc
     limit 1;

    if v_latest_run_id is not null then
      select pg_catalog.count(distinct coalesce(
               issue.provider_entity_id,
               issue.local_entity_id,
               issue.kind
             ))::integer
        into v_asaas_attention
        from public.asaas_reconciliation_issues as issue
       where issue.run_id = v_latest_run_id
         and issue.tenant_id = v_tenant_id
         and issue.resolved_at is null
         and issue.severity in ('HIGH', 'CRITICAL')
         and issue.kind <> 'PAYMENT_TENANT_OR_STUDENT_UNRESOLVED';
    else
      -- A day-only deploy smoke test must never replace the operational
      -- audit. If no 45-day-or-wider run exists, surface that absence as one
      -- action instead of declaring the provider fully reconciled.
      v_asaas_attention := 1;
    end if;
  end if;

  return v_counts || pg_catalog.jsonb_build_object(
    'avisos_pagamento', coalesce(v_payment_notification_attention, 0),
    'pagamentos_sem_aluno', coalesce(v_unlinked_payments, 0),
    'conciliacao_asaas', coalesce(v_asaas_attention, 0)
  );
end;
$$;


--
-- Name: director_pending_counts_unchecked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.director_pending_counts_unchecked() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_role text;
  v_tenant text;
  v_recon jsonb;
  v_renov jsonb;
begin
  select role, tenant_id into v_role, v_tenant from profiles where id = auth.uid();
  if v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then return '{}'::jsonb; end if;

  v_recon := financial_reconciliation(v_tenant);
  v_renov := contratos_para_renovar(v_tenant);

  return jsonb_build_object(
    'acolhimento', (select count(*) from profiles
        where tenant_id = v_tenant and role = 'STUDENT' and documentation_status = 'PENDING'),
    'presenca', (select count(*) from attendance_confirmations ac
        join class_logs cl on cl.id = ac.class_log_id
        where cl.tenant_id = v_tenant and ac.status = 'CONFLICT'),
    'materiais', (select count(*) from pedagogical_materials
        where tenant_id = v_tenant and approval_status = 'PENDING'),
    'trials', (select count(*) from appointments a
        where a.tenant_id = v_tenant and a.type in ('experimental', 'training')
          and a.status = 'scheduled' and a.start_time <= now()
          and a.start_time >= '2026-06-01'::timestamptz
          and not exists (select 1 from class_logs cl where cl.appointment_id = a.id::text)),
    -- `reschedules.date` é TEXT e guarda 'Pendente' quando ainda não foi
    -- agendada — comparar com data aqui daria erro de cast, então o filtro é
    -- por igualdade de texto mesmo.
    'reposicoes', (select count(*) from reschedules r
        where r.tenant_id = v_tenant and r.used_at is null and r.date = 'Pendente'),
    'reposicoes_vencidas', (select count(*) from reschedules r
        where r.tenant_id = v_tenant and r.used_at is null
          and r.date <> 'Pendente'
          and r.date ~ '^\d{4}-\d{2}-\d{2}$'
          and r.date < to_char(now() at time zone 'America/Sao_Paulo', 'YYYY-MM-DD')),
    'pagamentos_retidos', (select count(*) from class_logs
        where tenant_id = v_tenant and coalesce(payment_hold, false) = true),
    'fechamentos', (select count(*) from teacher_closings
        where tenant_id = v_tenant and status = 'PENDENTE'),
    'sem_assinatura', coalesce((alunos_sem_assinatura(v_tenant)->>'alunos')::int, 0),
    'reconciliacao', coalesce((v_recon->'sem_cobertura'->>'qtd')::int, 0)
                   + coalesce((v_recon->'cobrado_sem_estudar'->>'qtd')::int, 0)
                   + coalesce((v_recon->'arquivado_com_fatura'->>'qtd')::int, 0)
                   + coalesce((v_recon->'pago_sem_nf'->>'qtd')::int, 0)
                   + coalesce((v_recon->'parado_com_nf'->>'qtd')::int, 0)
                   + coalesce((v_recon->'aula_nao_lancada'->>'qtd')::int, 0)
                   + coalesce((v_renov->'vencendo'->>'qtd')::int, 0)
                   + coalesce((v_renov->'encerrado'->>'qtd')::int, 0)
  );
end;
$_$;


--
-- Name: director_teacher_margin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.director_teacher_margin(p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_jwt_role text; v_caller_role text; v_tenant text; v_month text; v_rows jsonb; v_total jsonb;
BEGIN
  v_jwt_role := COALESCE(current_setting('request.jwt.claims', true)::json->>'role', '');
  SELECT role, tenant_id INTO v_caller_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_jwt_role IN ('anon','authenticated') THEN
    IF v_caller_role IS NULL OR v_caller_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
      RAISE EXCEPTION 'Apenas a direção pode ver custo e margem';
    END IF;
  END IF;

  v_month := COALESCE(p_month, to_char(current_date,'YYYY-MM'));
  IF v_month !~ '^\d{4}-\d{2}$' THEN RAISE EXCEPTION 'Mês inválido (use YYYY-MM)'; END IF;

  WITH custo AS (
    SELECT v.teacher_id,
           COALESCE(v.student_id::text, 'appt:' || COALESCE(v.appointment_id, v.id::text)) AS grp,
           max(v.student_id::text) AS student_id,
           max(COALESCE(sp.full_name, ap.student_name, 'Aluno não cadastrado')) AS student_name,
           bool_or(v.subtype = 'AULA EXPERIMENTAL') AS experimental,
           count(*) AS aulas, sum(v.rate_efetivo) AS custo
    FROM v_payable_class_logs v
    JOIN profiles t ON t.id = v.teacher_id
    LEFT JOIN profiles sp ON sp.id = v.student_id
    LEFT JOIN appointments ap ON ap.id::text = v.appointment_id
    WHERE to_char(v.class_date,'YYYY-MM') = v_month
      AND (v_caller_role = 'SUPER_ADMIN' OR t.tenant_id = v_tenant)
    GROUP BY v.teacher_id, COALESCE(v.student_id::text, 'appt:' || COALESCE(v.appointment_id, v.id::text))
  ), receita AS (
    SELECT sp.student_id, sum(greatest(round(coalesce(sp.value, 0) - coalesce(sp.refunded_amount, 0), 2), 0)) AS receita
    FROM student_payments sp
    WHERE sp.status IN ('RECEIVED','RECEIVED_IN_CASH')
      AND to_char(COALESCE(sp.credited_at::date, sp.paid_at::date, sp.payment_date, sp.due_date),'YYYY-MM') = v_month
    GROUP BY sp.student_id
  )
  SELECT jsonb_agg(x ORDER BY x->>'teacher_name', x->>'student_name')
    INTO v_rows
  FROM (
    SELECT jsonb_build_object(
      'teacher_id', c.teacher_id, 'teacher_name', trim(t.full_name),
      'student_id', c.student_id, 'student_name', trim(c.student_name),
      'experimental', c.experimental,
      'aulas', c.aulas, 'custo', round(c.custo,2),
      'receita', round(COALESCE(r.receita,0),2),
      'margem', round(COALESCE(r.receita,0) - c.custo, 2)
    ) AS x
    FROM custo c
    JOIN profiles t ON t.id = c.teacher_id
    LEFT JOIN receita r ON r.student_id::text = c.student_id
  ) z;

  WITH custo AS (
    SELECT sum(v.rate_efetivo) AS custo, count(*) AS aulas
    FROM v_payable_class_logs v JOIN profiles t ON t.id = v.teacher_id
    WHERE to_char(v.class_date,'YYYY-MM') = v_month
      AND (v_caller_role = 'SUPER_ADMIN' OR t.tenant_id = v_tenant)
  ), receita AS (
    SELECT sum(greatest(round(coalesce(sp.value, 0) - coalesce(sp.refunded_amount, 0), 2), 0)) AS receita
    FROM student_payments sp JOIN profiles s ON s.id = sp.student_id
    WHERE sp.status IN ('RECEIVED','RECEIVED_IN_CASH')
      AND to_char(COALESCE(sp.credited_at::date, sp.paid_at::date, sp.payment_date, sp.due_date),'YYYY-MM') = v_month
      AND (v_caller_role = 'SUPER_ADMIN' OR s.tenant_id = v_tenant)
  )
  SELECT jsonb_build_object(
    'aulas', COALESCE((SELECT aulas FROM custo),0),
    'custo', round(COALESCE((SELECT custo FROM custo),0),2),
    'receita', round(COALESCE((SELECT receita FROM receita),0),2),
    'margem', round(COALESCE((SELECT receita FROM receita),0) - COALESCE((SELECT custo FROM custo),0),2)
  ) INTO v_total;

  RETURN jsonb_build_object('month', v_month, 'rows', COALESCE(v_rows,'[]'::jsonb), 'total', v_total);
END;
$_$;


--
-- Name: FUNCTION director_teacher_margin(p_month text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.director_teacher_margin(p_month text) IS 'Custo e margem por professor com receita recebida liquida de refunded_amount. CONFIRMED nao e caixa.';


--
-- Name: dispute_wolfie_pending_correction(text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispute_wolfie_pending_correction(p_tenant_id text, p_student_id uuid, p_session_id uuid, p_reason text DEFAULT 'learner_disputed'::text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  session_stage text;
  session_status text;
  pending_correction public.wolfie_corrections%rowtype;
  disputed_on timestamptz := now();
begin
  select current_stage, scenario_status
    into session_stage, session_status
    from public.wolfie_sessions
   where id = p_session_id
     and student_id = p_student_id
     and tenant_id = p_tenant_id
   for update;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'owned_wolfie_session_not_found';
  end if;

  select *
    into pending_correction
    from public.wolfie_corrections
   where session_id = p_session_id
     and status = 'active'
     and requires_retry
     and not retry_completed
   order by created_at desc, id desc
   limit 1
   for update;

  if pending_correction.id is null then
    return pg_catalog.jsonb_build_object(
      'correctionId', null,
      'currentStage', session_stage,
      'scenarioStatus', session_status
    );
  end if;

  update public.wolfie_corrections
     set status = 'disputed',
         status_reason = left(
           coalesce(nullif(btrim(p_reason), ''), 'learner_disputed'),
           1000
         ),
         disputed_at = disputed_on,
         requires_retry = false
   where id = pending_correction.id
     and session_id = p_session_id
     and status = 'active';

  session_stage := case
    when session_stage = 'retry' then 'practice'
    else session_stage
  end;
  session_status := case
    when session_status = 'awaiting_retry' then 'active'
    else session_status
  end;

  update public.wolfie_sessions
     set current_stage = session_stage,
         scenario_status = session_status,
         retry_count = greatest(0, coalesce(retry_count, 0) - 1),
         last_activity_at = disputed_on,
         updated_at = disputed_on
   where id = p_session_id
     and student_id = p_student_id
     and tenant_id = p_tenant_id;

  return pg_catalog.jsonb_build_object(
    'correctionId', pending_correction.id,
    'correctSentence', pending_correction.correct_sentence,
    'explanationPt', pending_correction.explanation_pt,
    'errorType', pending_correction.error_type,
    'currentStage', session_stage,
    'scenarioStatus', session_status,
    'disputedAt', disputed_on
  );
end;
$$;


--
-- Name: dow_name_to_int(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dow_name_to_int(p text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  SELECT CASE lower(split_part(
           translate(coalesce(p, ''), 'áàâãéêíóôõúüçÁÀÂÃÉÊÍÓÔÕÚÜÇ', 'aaaaeeiooouucAAAAEEIOOOUUC'),
           '-', 1))
    WHEN 'domingo'  THEN 0  WHEN 'sunday'    THEN 0
    WHEN 'segunda'  THEN 1  WHEN 'monday'    THEN 1
    WHEN 'terca'    THEN 2  WHEN 'tuesday'   THEN 2
    WHEN 'quarta'   THEN 3  WHEN 'wednesday' THEN 3
    WHEN 'quinta'   THEN 4  WHEN 'thursday'  THEN 4
    WHEN 'sexta'    THEN 5  WHEN 'friday'    THEN 5
    WHEN 'sabado'   THEN 6  WHEN 'saturday'  THEN 6
    ELSE -1
  END
$$;


--
-- Name: dre_gerencial(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_gerencial(p_month text DEFAULT NULL::text, p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_jwt_role text; v_caller_role text; v_tenant text; v_month text;
  v_receita numeric; v_deducoes numeric;
  v_custo_aulas numeric; v_custo_ajustes numeric; v_custo_outros numeric;
  v_desp_vendedor numeric; v_desp_indicacao numeric; v_desp_ledger numeric;
  v_barrado numeric;
  v_aulas int; v_alunos int;
  v_receita_liq numeric; v_custo numeric; v_lucro_bruto numeric;
  v_despesas numeric; v_resultado numeric;
  v_linhas jsonb; v_linhas_ledger jsonb; v_alertas jsonb := '[]'::jsonb;
begin
  v_jwt_role := coalesce(
    nullif(btrim(current_setting('request.jwt.claims', true)), '')::jsonb ->> 'role',
    ''
  );
  select role, tenant_id into v_caller_role, v_tenant from profiles where id = auth.uid();
  if v_jwt_role in ('anon','authenticated') then
    if v_caller_role is null or v_caller_role not in ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') then
      raise exception 'Apenas a direção pode ver o resultado da escola';
    end if;
    if v_caller_role = 'SUPER_ADMIN' then v_tenant := coalesce(p_tenant, v_tenant); end if;
  else
    v_tenant := coalesce(p_tenant, v_tenant);
  end if;
  if v_tenant is null then raise exception 'Escola não identificada'; end if;

  v_month := coalesce(p_month, to_char(current_date,'YYYY-MM'));
  if v_month !~ '^\d{4}-\d{2}$' then raise exception 'Mês inválido (use YYYY-MM)'; end if;

  SELECT COALESCE(sum(greatest(round(coalesce(value, 0) - coalesce(refunded_amount, 0), 2), 0)),0) INTO v_receita
  FROM student_payments
  WHERE tenant_id = v_tenant AND status IN ('RECEIVED','RECEIVED_IN_CASH')
    AND to_char(COALESCE(credited_at, paid_at, payment_date, due_date),'YYYY-MM') = v_month;

  select coalesce(sum(custo_aulas),0), coalesce(sum(aulas),0)
    into v_custo_aulas, v_aulas
  from v_teacher_cost_competencia
  where tenant_id = v_tenant and month_year = v_month;

  select coalesce(sum(amount),0) into v_custo_ajustes
  from closing_adjustments
  where tenant_id = v_tenant and month_year = v_month;

  select count(distinct v.student_id) into v_alunos
  from v_payable_class_logs v join profiles t on t.id = v.teacher_id
  where t.tenant_id = v_tenant and to_char(v.class_date,'YYYY-MM') = v_month
    and v.student_id is not null;

  select coalesce(sum(amount_brl),0) into v_desp_vendedor
  from vendor_commissions
  where tenant_id = v_tenant and status='PAID' and to_char(paid_at,'YYYY-MM') = v_month;

  select coalesce(sum(amount_brl),0) into v_desp_indicacao
  from referral_rewards
  where tenant_id = v_tenant and status='PAID' and to_char(paid_at,'YYYY-MM') = v_month;

  select
    coalesce(sum(t.valor) filter (where not t.barrado and t.kind = 'DEDUCAO'), 0),
    coalesce(sum(t.valor) filter (where not t.barrado and t.kind = 'CUSTO'),   0),
    coalesce(sum(t.valor) filter (where not t.barrado and t.kind = 'DESPESA'), 0),
    coalesce(sum(t.valor) filter (where t.barrado), 0),
    coalesce(jsonb_agg(jsonb_build_object(
        'code', t.code, 'label', t.label, 'kind', t.kind,
        'valor', round(t.valor,2), 'fonte','caixa (saídas classificadas)',
        'sort', t.sort_order) order by t.sort_order)
      filter (where not t.barrado), '[]'::jsonb)
    into v_deducoes, v_custo_outros, v_desp_ledger, v_barrado, v_linhas_ledger
  from (
    select
      coalesce(a.code,       '6.9.99') as code,
      coalesce(a.label,      'Outras despesas') as label,
      coalesce(a.kind,       'DESPESA') as kind,
      coalesce(a.sort_order, 990) as sort_order,
      not coalesce(a.ledger_allowed, true) as barrado,
      sum(ft.amount) as valor
    from financial_transactions ft
    left join dre_category_map m on m.tenant_id = ft.tenant_id and m.category = ft.category
    left join dre_accounts a on a.code = coalesce(ft.account_code, m.account_code)
    WHERE ft.tenant_id = v_tenant AND ft.type = 'SAIDA'
      AND ft.category IS DISTINCT FROM 'teacher_payout'
      AND ft.refund_student_payment_id IS NULL
      AND to_char(COALESCE(ft.occurred_at, ft.created_at),'YYYY-MM') = v_month
    group by 1,2,3,4,5
  ) t;

  v_receita_liq := v_receita - v_deducoes;
  v_custo       := v_custo_aulas + v_custo_ajustes + v_custo_outros;
  v_lucro_bruto := v_receita_liq - v_custo;
  v_despesas    := v_desp_vendedor + v_desp_indicacao + v_desp_ledger;
  v_resultado   := v_lucro_bruto - v_despesas;

  with fixas as (
    select unnest(array[
      jsonb_build_object('code','3.1.01','label','Mensalidades',           'kind','RECEITA','valor',round(v_receita,2),        'fonte','student_payments recebidos',        'sort',110),
      jsonb_build_object('code','5.1.01','label','Repasse a professores',  'kind','CUSTO',  'valor',round(v_custo_aulas,2),    'fonte','v_payable_class_logs (competência)','sort',310),
      jsonb_build_object('code','5.1.02','label','Ajustes de fechamento',  'kind','CUSTO',  'valor',round(v_custo_ajustes,2),  'fonte','closing_adjustments',               'sort',320),
      jsonb_build_object('code','6.1.01','label','Comissões de vendedores','kind','DESPESA','valor',round(v_desp_vendedor,2),  'fonte','vendor_commissions pagas',          'sort',410),
      jsonb_build_object('code','6.1.02','label','Programa de indicações', 'kind','DESPESA','valor',round(v_desp_indicacao,2), 'fonte','referral_rewards pagas',            'sort',420)
    ]) as l
  ), ledger as (
    select e.value as l from jsonb_array_elements(v_linhas_ledger) e
  )
  select coalesce(jsonb_agg((t.l - 'sort') order by (t.l->>'sort')::int), '[]'::jsonb)
    into v_linhas
  from (select l from fixas union all select l from ledger) t;

  if v_desp_ledger = 0 and v_deducoes = 0 and v_custo_outros = 0 then
    v_alertas := v_alertas || jsonb_build_object(
      'nivel','critico',
      'texto','Nenhuma despesa operacional lançada no mês (ferramentas, internet, impostos, aluguel). O resultado abaixo está SUPERESTIMADO — ele desconta só o custo com professor.');
  end if;
  if v_barrado > 0 then
    v_alertas := v_alertas || jsonb_build_object(
      'nivel','atencao',
      'texto','R$ ' || translate(to_char(v_barrado,'FM999,999,990.00'), ',.', '.,') || ' em saídas do caixa foram lançadas em contas que já vêm por competência (repasse, ajustes, comissões, indicações). O valor foi IGNORADO no resultado para não contar duas vezes — reclassifique a categoria.');
  end if;
  if v_custo_aulas = 0 and v_receita > 0 then
    v_alertas := v_alertas || jsonb_build_object(
      'nivel','atencao',
      'texto','Houve receita mas nenhuma aula pagável lançada no mês. Verifique lançamentos pendentes de professor.');
  end if;
  if exists (select 1 from teacher_closings tc
              where tc.tenant_id = v_tenant and tc.month_year = v_month
                and tc.status <> 'PAGO') then
    v_alertas := v_alertas || jsonb_build_object(
      'nivel','info',
      'texto','O fechamento deste mês ainda não foi pago. O custo já está reconhecido aqui por competência, mas ainda não saiu do caixa.');
  end if;

  return jsonb_build_object(
    'month', v_month,
    'regime','competencia',
    'receita_bruta',   round(v_receita,2),
    'deducoes',        round(v_deducoes,2),
    'receita_liquida', round(v_receita_liq,2),
    'custo_servicos',  round(v_custo,2),
    'lucro_bruto',     round(v_lucro_bruto,2),
    'margem_bruta_pct', round(100 * v_lucro_bruto / nullif(v_receita_liq,0), 1),
    'despesas_operacionais', round(v_despesas,2),
    'resultado',       round(v_resultado,2),
    'margem_liquida_pct', round(100 * v_resultado / nullif(v_receita_liq,0), 1),
    'indicadores', jsonb_build_object(
      'aulas', v_aulas,
      'alunos_atendidos', v_alunos,
      'receita_por_aluno', round(v_receita / nullif(v_alunos,0), 2),
      'custo_por_aula', round((v_custo_aulas + v_custo_ajustes) / nullif(v_aulas,0), 2)
    ),
    'linhas', v_linhas,
    'alertas', v_alertas
  );
end;
$_$;


--
-- Name: FUNCTION dre_gerencial(p_month text, p_tenant text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.dre_gerencial(p_month text, p_tenant text) IS 'DRE por competência: recebimentos líquidos de refunded_amount; custos pela aula. Aceita workers internos sem claims; CONFIRMED não é receita.';


--
-- Name: dre_report_targets(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_report_targets(p_force_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_hoje date; v_dow int;
BEGIN
  -- Horário de Brasília: o cron roda em UTC, mas "dia 1" e "segunda-feira" são
  -- do calendário do diretor. Sem o ajuste, o relatório mensal sairia no dia 31.
  v_hoje := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_dow  := EXTRACT(ISODOW FROM v_hoje)::int;

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
             'tenant_id', s.tenant_id,
             'escola',    COALESCE(t.name, s.tenant_id),
             'destino',   s.destino,
             'cadencia',  s.cadencia,
             -- Mensal fecha o mês anterior; diária e semanal olham o mês corrente.
             'month', CASE WHEN s.cadencia = 'mensal'
                           THEN to_char(v_hoje - interval '1 month','YYYY-MM')
                           ELSE to_char(v_hoje,'YYYY-MM') END,
             'ref_date', v_hoje,
             'instancia', (SELECT p.whatsapp_instance FROM profiles p
                            WHERE p.tenant_id = s.tenant_id
                              AND p.role IN ('SCHOOL_ADMIN','SUPER_ADMIN')
                              AND COALESCE(p.whatsapp_instance,'') <> ''
                            LIMIT 1)))
      FROM dre_report_settings s
      LEFT JOIN tenants t ON t.id = s.tenant_id
     WHERE s.is_active
       AND (p_force_tenant IS NOT NULL AND s.tenant_id = p_force_tenant
            OR p_force_tenant IS NULL AND (
                 s.cadencia = 'diaria'
              OR (s.cadencia = 'semanal' AND s.dia_semana = v_dow)
              OR (s.cadencia = 'mensal'  AND EXTRACT(DAY FROM v_hoje) = 1)))
  ), '[]'::jsonb);
END;
$$;


--
-- Name: dre_uncategorized_expenses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dre_uncategorized_expenses() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;

  RETURN jsonb_build_object(
    'contas', (SELECT jsonb_agg(jsonb_build_object('code',code,'label',label,'kind',kind) ORDER BY sort_order)
                 FROM dre_accounts WHERE is_active AND ledger_allowed),
    'pendentes', COALESCE((
      SELECT jsonb_agg(p ORDER BY p->>'category')
        FROM (
          SELECT jsonb_build_object(
                   'category', ft.category,
                   'lancamentos', count(*)::int,
                   'total', round(sum(ft.amount),2),
                   'exemplos', (array_agg(DISTINCT ft.description)
                                FILTER (WHERE COALESCE(btrim(ft.description),'') <> ''))[1:4]
                 ) AS p
            FROM financial_transactions ft
            LEFT JOIN dre_category_map m
              ON m.tenant_id = ft.tenant_id AND m.category = ft.category
           WHERE ft.tenant_id = v_tenant
             AND ft.type = 'SAIDA'
             AND ft.account_code IS NULL
             AND m.account_code IS NULL
             AND COALESCE(btrim(ft.category),'') <> ''
           GROUP BY ft.category
        ) s), '[]'::jsonb)
  );
END;
$$;


--
-- Name: enable_whatsapp_inbox(text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enable_whatsapp_inbox(p_tenant_id text, p_instance_name text, p_actor_id uuid, p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_instance public.whatsapp_instances%rowtype;
begin
  if p_enabled is null
     or nullif(pg_catalog.btrim(p_tenant_id), '') is null
     or nullif(pg_catalog.btrim(p_instance_name), '') is null then
    raise exception 'invalid_whatsapp_inbox_configuration'
      using errcode = '22023';
  end if;

  if not private.whatsapp_inbox_actor_has_role(
    p_actor_id,
    p_tenant_id,
    array['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) then
    raise exception 'whatsapp_inbox_configuration_forbidden'
      using errcode = '42501';
  end if;

  select instance.*
  into v_instance
  from public.whatsapp_instances as instance
  where instance.tenant_id = p_tenant_id
    and lower(instance.instance_name) = lower(pg_catalog.btrim(p_instance_name))
  for update;

  if not found then
    raise exception 'whatsapp_instance_not_found' using errcode = 'P0002';
  end if;

  if p_enabled and not exists (
    select 1
    from public.tenant_memberships as membership
    join public.profiles as owner
      on owner.id = membership.user_id
     and lower(pg_catalog.btrim(coalesce(owner.lifecycle_status, '')))
       = 'active'
    where membership.user_id = v_instance.user_id
      and membership.tenant_id = p_tenant_id
      and membership.role = 'SCHOOL_ADMIN'
      and membership.status = 'ACTIVE'
  ) then
    raise exception 'whatsapp_inbox_requires_school_admin_instance'
      using errcode = '42501';
  end if;

  update public.whatsapp_instances as instance
  set inbox_enabled = p_enabled,
      inbox_enabled_at = case when p_enabled then pg_catalog.now() else null end,
      inbox_enabled_by = case when p_enabled then p_actor_id else null end,
      updated_at = pg_catalog.now()
  where instance.id = v_instance.id
    and instance.tenant_id = p_tenant_id
  returning instance.* into v_instance;

  return jsonb_build_object(
    'ok', true,
    'tenantId', v_instance.tenant_id,
    'instanceId', v_instance.id,
    'instanceName', v_instance.instance_name,
    'inboxEnabled', v_instance.inbox_enabled,
    'inboxEnabledAt', v_instance.inbox_enabled_at
  );
end;
$$;


--
-- Name: enforce_active_class_coverage_slot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_active_class_coverage_slot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_time text;
  v_day_number integer;
  v_day_name text;
  v_class_start timestamptz;
BEGIN
  IF pg_catalog.lower(coalesce(NEW.status, ''))
       NOT IN ('pending', 'confirmed') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' AND pg_catalog.lower(NEW.status) <> 'pending' THEN
    IF pg_catalog.lower(NEW.status) <> 'confirmed'
       OR coalesce(auth.role(), '') <> 'service_role'
       OR NEW.token IS NOT NULL
       OR NEW.invite_expires_at IS NOT NULL
       OR NEW.confirmed_at IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = '42501', MESSAGE = 'active_coverage_must_start_pending';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    OR NEW.booking_id IS DISTINCT FROM OLD.booking_id
    OR NEW.original_teacher_id IS DISTINCT FROM OLD.original_teacher_id
    OR NEW.cover_teacher_id IS DISTINCT FROM OLD.cover_teacher_id
    OR NEW.student_id IS DISTINCT FROM OLD.student_id
    OR NEW.absence_id IS DISTINCT FROM OLD.absence_id
    OR NEW.class_date IS DISTINCT FROM OLD.class_date
    OR pg_catalog.left(coalesce(NEW.class_time, ''), 5)
       IS DISTINCT FROM pg_catalog.left(coalesce(OLD.class_time, ''), 5)
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501', MESSAGE = 'active_coverage_identity_immutable';
  END IF;
  IF TG_OP = 'UPDATE'
     AND pg_catalog.lower(NEW.status) = 'confirmed'
     AND pg_catalog.lower(coalesce(OLD.status, '')) <> 'confirmed'
     AND coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501', MESSAGE = 'coverage_confirmation_requires_service';
  END IF;
  IF NEW.tenant_id IS NULL OR NEW.booking_id IS NULL
     OR NEW.original_teacher_id IS NULL OR NEW.cover_teacher_id IS NULL
     OR NEW.student_id IS NULL OR NEW.absence_id IS NULL
     OR NEW.class_date IS NULL
     OR NEW.original_teacher_id = NEW.cover_teacher_id THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'active_coverage_invalid';
  END IF;

  v_time := pg_catalog.left(
    pg_catalog.btrim(coalesce(NEW.class_time, '')),
    5
  );
  IF v_time !~ '^(0[0-9]|1[0-9]|2[0-3]):(00|30)$' THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'active_coverage_time_invalid';
  END IF;
  NEW.class_time := v_time;
  v_class_start := (
    NEW.class_date::text || ' ' || v_time || ':00-03'
  )::timestamptz;
  IF v_class_start <= pg_catalog.now() THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'active_coverage_already_started';
  END IF;
  IF pg_catalog.lower(NEW.status) = 'pending' THEN
    IF coalesce(NEW.token, '') !~ '^[0-9a-fA-F]{32}$' THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514', MESSAGE = 'active_coverage_invite_invalid';
    END IF;
    NEW.invite_expires_at := coalesce(
      NEW.invite_expires_at,
      least(v_class_start, pg_catalog.now() + interval '48 hours')
    );
    IF NEW.invite_expires_at IS NULL
       OR NEW.invite_expires_at <= pg_catalog.now()
       OR NEW.invite_expires_at > v_class_start THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514', MESSAGE = 'active_coverage_invite_invalid';
    END IF;
    NEW.token := pg_catalog.lower(NEW.token);
  ELSIF pg_catalog.lower(NEW.status) = 'confirmed' AND TG_OP = 'UPDATE' THEN
    IF pg_catalog.lower(coalesce(OLD.status, '')) <> 'pending'
       OR OLD.invite_expires_at IS NULL
       OR OLD.invite_expires_at <= pg_catalog.now()
       OR coalesce(OLD.token, '') !~ '^[0-9a-fA-F]{32}$' THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514', MESSAGE = 'coverage_confirmation_invalid';
    END IF;
  END IF;

  v_day_number := extract(dow FROM NEW.class_date)::integer;
  v_day_name := CASE v_day_number
    WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Segunda' WHEN 2 THEN 'Terça'
    WHEN 3 THEN 'Quarta' WHEN 4 THEN 'Quinta' WHEN 5 THEN 'Sexta'
    WHEN 6 THEN 'Sábado'
  END;

  -- Ordem global: booking row -> occurrence -> teacher -> schedule.
  -- O SELECT detalhado abaixo revalida os campos depois que todos os locks
  -- foram adquiridos, mas a linha precisa ser tomada primeiro para nao inverter
  -- a ordem usada pela RPC do grupo.
  PERFORM 1
    FROM public.bookings AS booking
   WHERE booking.id = NEW.booking_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'active_coverage_booking_invalid';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'coverage:' || NEW.booking_id::text || ':' || NEW.class_date::text,
      0
    )
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'coverage-teacher:' || NEW.cover_teacher_id::text || ':' ||
      NEW.class_date::text || ':' || v_time,
      0
    )
  );
  PERFORM private.lock_coverage_absence_pair(
    NEW.original_teacher_id,
    NEW.cover_teacher_id,
    NEW.class_date
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'schedule:teacher:' || NEW.cover_teacher_id::text || ':' ||
      public.fold_accents(v_day_name) || ':' || v_time,
      0
    )
  );

  SELECT booking.*
    INTO v_booking
    FROM public.bookings AS booking
   WHERE booking.id = NEW.booking_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_booking.tenant_id IS DISTINCT FROM NEW.tenant_id
     OR v_booking.teacher_id IS DISTINCT FROM NEW.original_teacher_id
     OR v_booking.student_id IS DISTINCT FROM NEW.student_id
     OR pg_catalog.upper(coalesce(v_booking.status, '')) <>
          'SCHEDULED'
     OR pg_catalog.left(coalesce(v_booking.time_slot, ''), 5) <>
          v_time
     OR (
       v_booking.date IS NOT NULL
       AND v_booking.date IS DISTINCT FROM NEW.class_date
     )
     OR (
       v_booking.date IS NULL
       AND public.fold_accents(v_booking.day_of_week) <>
           public.fold_accents(v_day_name)
     )
     OR (
       v_booking.date IS NULL
       AND v_booking.start_date IS NOT NULL
       AND NEW.class_date < v_booking.start_date
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'active_coverage_booking_invalid';
  END IF;

  PERFORM 1
    FROM public.teacher_absences AS absence
   WHERE absence.id = NEW.absence_id
     AND absence.tenant_id = NEW.tenant_id
     AND absence.teacher_id = NEW.original_teacher_id
     AND pg_catalog.lower(coalesce(absence.status, '')) = 'active'
     AND absence.starts_at::date <= NEW.class_date
     AND absence.ends_at::date >= NEW.class_date
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'active_coverage_absence_invalid';
  END IF;

  IF NOT private.can_access_teacher_projection(
       NEW.original_teacher_id,
       pg_catalog.to_char(NEW.class_date, 'YYYY-MM')
     )
     OR NOT private.can_access_teacher_projection(
       NEW.cover_teacher_id,
       pg_catalog.to_char(NEW.class_date, 'YYYY-MM')
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'active_coverage_finance_scope_ambiguous';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles AS teacher
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = teacher.id
       AND membership.tenant_id = NEW.tenant_id
       AND membership.role = 'TEACHER'
       AND membership.status = 'ACTIVE'
     WHERE teacher.id = NEW.original_teacher_id
       AND teacher.tenant_id = NEW.tenant_id
       AND teacher.role = 'TEACHER'
       AND pg_catalog.lower(coalesce(
             teacher.lifecycle_status, 'active'
           )) NOT IN ('suspended', 'offboarded')
       AND 1 = (
         SELECT count(DISTINCT active_membership.tenant_id)
           FROM public.tenant_memberships AS active_membership
          WHERE active_membership.user_id = teacher.id
            AND active_membership.role = 'TEACHER'
            AND active_membership.status = 'ACTIVE'
       )
  ) OR NOT EXISTS (
    SELECT 1
      FROM public.profiles AS teacher
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = teacher.id
       AND membership.tenant_id = NEW.tenant_id
       AND membership.role = 'TEACHER'
       AND membership.status = 'ACTIVE'
     WHERE teacher.id = NEW.cover_teacher_id
       AND teacher.tenant_id = NEW.tenant_id
       AND teacher.role = 'TEACHER'
       AND pg_catalog.lower(coalesce(
             teacher.lifecycle_status, 'active'
           )) NOT IN ('suspended', 'offboarded')
       AND 1 = (
         SELECT count(DISTINCT active_membership.tenant_id)
           FROM public.tenant_memberships AS active_membership
          WHERE active_membership.user_id = teacher.id
            AND active_membership.role = 'TEACHER'
            AND active_membership.status = 'ACTIVE'
       )
  ) OR NOT EXISTS (
    SELECT 1
      FROM public.profiles AS student
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = student.id
       AND membership.tenant_id = NEW.tenant_id
       AND membership.role = 'STUDENT'
       AND membership.status = 'ACTIVE'
     WHERE student.id = NEW.student_id
       AND student.role = 'STUDENT'
       AND pg_catalog.lower(coalesce(
             student.lifecycle_status, 'active'
           )) NOT IN ('suspended', 'offboarded')
  ) OR NOT EXISTS (
    SELECT 1
      FROM public.teacher_availability AS availability
     WHERE availability.tenant_id = NEW.tenant_id
       AND availability.teacher_id = NEW.cover_teacher_id
       AND availability.day_of_week = v_day_number
       AND (
         availability.start_time = v_time::time
         OR (
           availability.end_time IS NOT NULL
           AND availability.start_time <= v_time::time
           AND availability.end_time > v_time::time
         )
       )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'active_coverage_member_unavailable';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.teacher_absences AS absence
     WHERE absence.tenant_id = NEW.tenant_id
       AND absence.teacher_id = NEW.cover_teacher_id
       AND pg_catalog.lower(coalesce(absence.status, '')) = 'active'
       AND absence.starts_at::date <= NEW.class_date
       AND absence.ends_at::date >= NEW.class_date
  ) OR EXISTS (
    SELECT 1
      FROM public.bookings AS conflict
     WHERE conflict.tenant_id = NEW.tenant_id
       AND conflict.teacher_id = NEW.cover_teacher_id
       AND pg_catalog.upper(coalesce(conflict.status, '')) <>
           'CANCELLED'
       AND pg_catalog.left(coalesce(conflict.time_slot, ''), 5) =
           v_time
       AND (
         conflict.date = NEW.class_date
         OR (
           conflict.date IS NULL
           AND public.fold_accents(conflict.day_of_week) =
               public.fold_accents(v_day_name)
           AND (
             conflict.start_date IS NULL
             OR conflict.start_date <= NEW.class_date
           )
         )
       )
  ) OR EXISTS (
    SELECT 1
      FROM public.reschedules AS reschedule
     WHERE reschedule.tenant_id = NEW.tenant_id
       AND reschedule.teacher_id = NEW.cover_teacher_id
       AND public.parse_lesson_date(reschedule.date) = NEW.class_date
       AND pg_catalog.left(reschedule.time::text, 5) = v_time
       AND reschedule.used_at IS NULL
  ) OR EXISTS (
    SELECT 1
      FROM public.appointments AS appointment
     WHERE appointment.tenant_id = NEW.tenant_id
       AND (
         appointment.teacher_id = NEW.cover_teacher_id
         OR appointment.professor_id = NEW.cover_teacher_id
       )
       AND pg_catalog.lower(coalesce(appointment.status, ''))
           IN ('scheduled', 'confirmed')
       AND pg_catalog.abs(extract(
             epoch FROM (appointment.start_time - v_class_start)
           )) < 1800
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23P01', MESSAGE = 'active_coverage_schedule_conflict';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.class_coverages AS coverage
     WHERE coverage.id IS DISTINCT FROM NEW.id
       AND coverage.tenant_id = NEW.tenant_id
       AND (
         (
           coverage.booking_id = NEW.booking_id
           AND coverage.class_date = NEW.class_date
         )
         OR (
           coverage.cover_teacher_id = NEW.cover_teacher_id
           AND coverage.class_date = NEW.class_date
           AND pg_catalog.left(coverage.class_time, 5) = v_time
         )
       )
       AND (
         pg_catalog.lower(coverage.status) = 'confirmed'
         OR (
           pg_catalog.lower(coverage.status) = 'pending'
           AND pg_catalog.now() < coalesce(
             coverage.invite_expires_at,
             (
               coverage.class_date::text || ' ' ||
               pg_catalog.left(coverage.class_time, 5) || ':00-03'
             )::timestamptz
           )
         )
       )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23505', MESSAGE = 'active_coverage_slot_conflict';
  END IF;

  RETURN NEW;
END;
$_$;


--
-- Name: enforce_can_oral_test_admin_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_can_oral_test_admin_only() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_tenant_id text;
begin
  if old.can_oral_test is distinct from new.can_oral_test
     and new.can_oral_test is true
     and new.role <> 'TEACHER' then
    raise exception
      using
        errcode = '23514',
        message = 'Only teacher profiles can be eligible for oral tests';
  end if;

  if old.can_oral_test is distinct from new.can_oral_test
     and v_uid is not null then
    select p.role, p.tenant_id
      into v_role, v_tenant_id
      from public.profiles as p
     where p.id = v_uid;

    if v_role is null
       or v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN')
       or (
         v_role <> 'SUPER_ADMIN'
         and v_tenant_id is distinct from new.tenant_id
       ) then
      raise exception
        using
          errcode = '42501',
          message = 'Only tenant administrators can change oral-test eligibility';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: enforce_profile_authorization_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_profile_authorization_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  actor_id uuid := (select auth.uid());
  actor_role text;
  privileged_runtime boolean := current_user in (
    'postgres', 'service_role', 'supabase_admin'
  );
begin
  if privileged_runtime then return new; end if;

  select profile.role into actor_role
  from public.profiles as profile
  where profile.id = actor_id;
  if actor_role = 'SUPER_ADMIN' then return new; end if;

  if new.id is distinct from old.id
     or new.role is distinct from old.role
     or new.tenant_id is distinct from old.tenant_id
     or new.whatsapp_instance is distinct from old.whatsapp_instance
     or new.whatsapp_instance_id is distinct from old.whatsapp_instance_id
     or new.whatsapp_instance_name is distinct from old.whatsapp_instance_name
     or new.whatsapp_token is distinct from old.whatsapp_token then
    raise exception 'authorization-managed profile fields cannot be changed by this role'
      using errcode = '42501';
  end if;

  if actor_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    if new.monthly_fee is distinct from old.monthly_fee
       or new.monthly_tuition is distinct from old.monthly_tuition
       or new.fidelity_plan is distinct from old.fidelity_plan
       or new.due_day is distinct from old.due_day
       or new.subscription_id is distinct from old.subscription_id
       or new.asaas_customer_id is distinct from old.asaas_customer_id
       or new.asaas_subscription_status is distinct from old.asaas_subscription_status
       or new.asaas_subscription_end_date is distinct from old.asaas_subscription_end_date
       or new.asaas_subscription_synced_at is distinct from old.asaas_subscription_synced_at
       or new.status_financial is distinct from old.status_financial
       or new.enrollment_fee is distinct from old.enrollment_fee
       or new.enrollment_fee_paid is distinct from old.enrollment_fee_paid
       or new.enrollment_payment_id is distinct from old.enrollment_payment_id
       or new.paid_through is distinct from old.paid_through
       or new.prepaid_months is distinct from old.prepaid_months
       or new.hourly_rate is distinct from old.hourly_rate
       or new.commission_rate is distinct from old.commission_rate then
      raise exception 'financial profile fields cannot be changed by this role'
        using errcode = '42501';
    end if;
  end if;

  if actor_role = 'TEACHER' and old.id <> actor_id then
    if new.email is distinct from old.email
       or new.phone is distinct from old.phone
       or new.cpf is distinct from old.cpf
       or new.rg is distinct from old.rg
       or new.birth_date is distinct from old.birth_date
       or new.cnpj is distinct from old.cnpj
       or new.cnpj_company_name is distinct from old.cnpj_company_name
       or new.address is distinct from old.address
       or new.address_number is distinct from old.address_number
       or new.postal_code is distinct from old.postal_code
       or new.bank_name is distinct from old.bank_name
       or new.agency is distinct from old.agency
       or new.account_number is distinct from old.account_number
       or new.pix_key is distinct from old.pix_key
       or new.pix_key_type is distinct from old.pix_key_type
       or new.guardian_name is distinct from old.guardian_name
       or new.guardian_cpf is distinct from old.guardian_cpf
       or new.guardian_email is distinct from old.guardian_email
       or new.guardian_phone is distinct from old.guardian_phone
       or new.guardian_id is distinct from old.guardian_id
       or new.private_notes is distinct from old.private_notes
       or new.signature_ip is distinct from old.signature_ip
       or new.signature_url is distinct from old.signature_url
       or new.contract_url is distinct from old.contract_url
       or new.student_signature_url is distinct from old.student_signature_url
       or new.signed_document_url is distinct from old.signed_document_url
       or new.wise_wolf_signature_token is distinct from old.wise_wolf_signature_token
       or new.typed_signature is distinct from old.typed_signature
       or new.signature_hash is distinct from old.signature_hash
       or new.user_ip is distinct from old.user_ip then
      raise exception 'private profile fields cannot be changed by a teacher'
        using errcode = '42501';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: enforce_storage_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_storage_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  current_usage_bytes bigint;
  limit_gb numeric;
  limit_bytes bigint;
  owner_tenant_id text;
BEGIN
  -- 1. Resolve tenant_id (TEXT)
  SELECT tenant_id INTO owner_tenant_id
  FROM profiles
  WHERE id = NEW.owner; 

  IF (owner_tenant_id IS NOT NULL) THEN
    -- 2. Get Limit from JSONB or Default
    -- We try to find 'storage_limit' inside the 'features' JSON column.
    SELECT COALESCE((sp.features->>'storage_limit')::numeric, 10) INTO limit_gb
    FROM tenants t
    LEFT JOIN saas_plans sp ON t.plan_id = sp.id
    WHERE t.id = owner_tenant_id;

    -- Double safety: if join fails entirely, limit_gb is null
    IF limit_gb IS NULL THEN
        limit_gb := 10;
    END IF;

    limit_bytes := limit_gb * 1024 * 1024 * 1024;

    -- 3. Check Usage
    SELECT COALESCE(SUM((metadata->>'size')::bigint), 0) INTO current_usage_bytes
    FROM storage.objects sobj
    JOIN profiles p ON sobj.owner = p.id
    WHERE p.tenant_id = owner_tenant_id;

    IF (current_usage_bytes + (NEW.metadata->>'size')::bigint > limit_bytes) THEN
        RAISE EXCEPTION 'Limite de armazenamento excedido (Max: % GB). Faça upgrade.', limit_gb;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_student_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_student_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  current_count integer;
  limit_count integer;
  tenant_plan_id uuid;
BEGIN
  -- Only check on INSERT of a new student
  IF (NEW.role = 'student') THEN
    -- Get limit
    SELECT max_students INTO limit_count
    FROM tenants t
    JOIN saas_plans sp ON t.saas_plan_id = sp.id
    WHERE t.id = NEW.tenant_id;

    -- Get current count
    SELECT count(*) INTO current_count
    FROM profiles
    WHERE tenant_id = NEW.tenant_id AND role = 'student';

    -- Check
    IF (current_count >= limit_count) THEN
      RAISE EXCEPTION 'Limite de alunos atingido para o plano atual (Max: %). Faça upgrade para adicionar mais.', limit_count;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_teacher_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_teacher_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_limit INT;
    v_current INT;
BEGIN
    IF NEW.role NOT IN ('TEACHER','teacher') THEN RETURN NEW; END IF;
    IF NEW.tenant_id IS NULL THEN RETURN NEW; END IF;

    SELECT teacher_limit INTO v_limit FROM tenants WHERE id = NEW.tenant_id;
    IF v_limit IS NULL OR v_limit <= 0 THEN RETURN NEW; END IF;

    SELECT COUNT(*) INTO v_current FROM profiles
        WHERE tenant_id = NEW.tenant_id AND role IN ('TEACHER','teacher')
        AND (status IS NULL OR status NOT IN ('Inativo','inactive','SUSPENDED'));

    IF v_current >= v_limit THEN
        RAISE EXCEPTION 'Limite de % professores atingido para este tenant. Faça upgrade do plano.', v_limit
            USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_asaas_webhook_event(text, text, text, timestamp with time zone, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_asaas_webhook_event(p_event_id text, p_event_name text, p_entity_id text, p_event_created_at timestamp with time zone, p_payload jsonb, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  existing_row public.asaas_webhook_inbox%rowtype;
  inserted boolean := false;
begin
  if nullif(trim(p_event_id), '') is null
     or length(p_event_id) > 240
     or nullif(trim(p_event_name), '') is null
     or length(p_event_name) > 120
     or nullif(trim(p_entity_id), '') is null
     or length(p_entity_id) > 240
     or p_payload is null
     or nullif(trim(p_payload_hash), '') is null
  then
    raise exception using errcode = '22023', message = 'invalid_asaas_webhook_event';
  end if;

  insert into public.asaas_webhook_inbox (
    provider_event_id,
    event_name,
    provider_entity_id,
    event_created_at,
    payload,
    payload_hash
  ) values (
    trim(p_event_id),
    trim(p_event_name),
    trim(p_entity_id),
    p_event_created_at,
    p_payload,
    trim(p_payload_hash)
  )
  on conflict (provider_event_id) do nothing;
  inserted := found;

  select inbox.*
    into existing_row
    from public.asaas_webhook_inbox as inbox
   where inbox.provider_event_id = trim(p_event_id)
   for update;

  if existing_row.payload_hash is distinct from trim(p_payload_hash) then
    update public.asaas_webhook_inbox
       set status = 'TRIAGE',
           delivery_count = delivery_count + 1,
           last_received_at = now(),
           last_error = 'duplicate_event_id_payload_mismatch',
           updated_at = now()
     where provider_event_id = trim(p_event_id);

    insert into public.asaas_reconciliation_issues (
      source, kind, severity, provider_entity_id, fingerprint, details
    ) values (
      'WEBHOOK', 'DUPLICATE_EVENT_PAYLOAD_MISMATCH', 'CRITICAL',
      trim(p_event_id), 'webhook-payload-mismatch:' || trim(p_event_id),
      jsonb_build_object('event', trim(p_event_name), 'entityId', trim(p_entity_id))
    )
    on conflict do nothing;

    return jsonb_build_object(
      'inserted', false,
      'duplicate', true,
      'processable', false,
      'status', 'TRIAGE'
    );
  end if;

  if not inserted then
    update public.asaas_webhook_inbox
       set delivery_count = delivery_count + 1,
           last_received_at = now(),
           updated_at = now()
     where provider_event_id = trim(p_event_id);
  end if;

  return jsonb_build_object(
    'inserted', inserted,
    'duplicate', not inserted,
    'processable', existing_row.status not in ('PROCESSED', 'TRIAGE', 'DEAD_LETTER'),
    'status', existing_row.status
  );
end;
$$;


--
-- Name: enqueue_attendance_confirmations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_attendance_confirmations() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  v_count integer := 0;
  r record;
  v_today date := (now() at time zone 'America/Sao_Paulo')::date;
begin
  with occurrence_base as (
    select
      uc.source_id,
      uc.source_type,
      uc.tenant_id,
      case
        when coalesce(confirmed_coverage.match_count, 0) = 1
          then confirmed_coverage.cover_teacher_id
        else uc.teacher_id
      end as teacher_id,
      uc.student_id,
      uc.student_name_override,
      uc.student_phone_override,
      uc.class_date,
      uc.time_text,
      uc.start_at
    from public.upcoming_classes uc
    left join lateral (
      select
        count(*)::integer as match_count,
        count(*) filter (
          where case
                  when btrim(coalesce(coverage.class_time, ''))
                       ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
                       and btrim(coalesce(uc.time_text, ''))
                       ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
                  then left(btrim(coverage.class_time), 5)::time =
                       left(btrim(uc.time_text), 5)::time
                  else false
                end
        )::integer as time_match_count,
        (array_agg(coverage.cover_teacher_id order by coverage.id))[1]
          as cover_teacher_id
      from public.class_coverages coverage
      where uc.source_type = 'booking'
        and coverage.booking_id::text = uc.source_id::text
        and coverage.tenant_id = uc.tenant_id
        and coverage.student_id is not distinct from uc.student_id
        and coverage.class_date = uc.class_date
        and lower(coalesce(coverage.status, '')) = 'confirmed'
    ) confirmed_coverage on true
    -- Ambiguous historical corruption must not address a confirmation to an
    -- arbitrary teacher. The coverage constraints normally keep this <= 1.
    where coalesce(confirmed_coverage.match_count, 0) = 0
       or (
         confirmed_coverage.match_count = 1
         and confirmed_coverage.time_match_count = 1
       )
  ), upcoming_base as (
    select
      uc.*,
      sp.full_name as profile_student_name,
      tp.full_name as profile_teacher_name,
      selected_phone.phone as selected_phone,
      coalesce(
        uc.student_id::text,
        nullif(regexp_replace(coalesce(selected_phone.phone, ''), '\D', '', 'g'), ''),
        uc.source_id::text
      ) as participant_key
    from occurrence_base uc
    left join public.profiles sp
      on sp.id = uc.student_id
     and sp.tenant_id = uc.tenant_id
     and sp.role = 'STUDENT'
     and sp.is_test_account is false
     and lower(btrim(sp.lifecycle_status)) = 'active'
     and exists (
       select 1
         from public.tenant_memberships membership
        where membership.user_id = sp.id
          and membership.tenant_id = uc.tenant_id
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
     )
    left join public.profiles tp
      on tp.id = uc.teacher_id
     and tp.tenant_id = uc.tenant_id
     and tp.role = 'TEACHER'
     and tp.is_test_account is false
     and lower(btrim(tp.lifecycle_status)) = 'active'
     and exists (
       select 1
         from public.tenant_memberships membership
        where membership.user_id = tp.id
          and membership.tenant_id = uc.tenant_id
          and membership.role = 'TEACHER'
          and membership.status = 'ACTIVE'
     )
    cross join lateral (
      select case
        when length(regexp_replace(coalesce(sp.attendance_phone, ''), '\D', '', 'g')) >= 10
          then sp.attendance_phone
        when length(regexp_replace(coalesce(sp.phone, ''), '\D', '', 'g')) >= 10
          then sp.phone
        when length(regexp_replace(coalesce(uc.student_phone_override, ''), '\D', '', 'g')) >= 10
          then uc.student_phone_override
      end as phone
    ) selected_phone
    where uc.class_date between v_today - 1 and v_today
      and tp.id is not null
      and sp.id is not null
  ), upcoming_lagged as (
    select
      u.*,
      lag(u.start_at) over (
        partition by u.tenant_id, u.teacher_id, u.participant_key, u.class_date
        order by u.start_at, u.source_id
      ) as previous_start_at
    from upcoming_base u
  ), upcoming_marked as (
    select
      u.*,
      case
        when u.previous_start_at is null then 1
        when u.start_at - u.previous_start_at > interval '30 minutes' then 1
        else 0
      end as starts_group
    from upcoming_lagged u
  ), upcoming_grouped as (
    select
      u.*,
      sum(u.starts_group) over (
        partition by u.tenant_id, u.teacher_id, u.participant_key, u.class_date
        order by u.start_at, u.source_id
        rows between unbounded preceding and current row
      ) as group_number
    from upcoming_marked u
  ), ready_sessions as (
    select
      u.*,
      max(u.start_at) over (
        partition by u.tenant_id, u.teacher_id, u.participant_key,
                     u.class_date, u.group_number
      ) as last_start_at
    from upcoming_grouped u
  )
  insert into public.attendance_confirmations (
    tenant_id, source_id, source_type, teacher_id, student_id,
    student_name, student_phone, class_date, class_time, teacher_name,
    token, token_expires_at, session_end_at, status
  )
  select
    ready.tenant_id,
    ready.source_id::text,
    ready.source_type,
    ready.teacher_id,
    ready.student_id,
    coalesce(ready.profile_student_name, ready.student_name_override),
    ready.selected_phone,
    ready.class_date,
    ready.time_text,
    ready.profile_teacher_name,
    encode(extensions.gen_random_bytes(12), 'hex'),
    now() + interval '7 days',
    ready.last_start_at + interval '30 minutes',
    'PENDING'
  from ready_sessions ready
  where ready.last_start_at <= now() - interval '40 minutes'
    and ready.last_start_at >= now() - interval '8 hours'
    and ready.selected_phone is not null
  on conflict (source_id, source_type, class_date) do nothing;

  get diagnostics v_count = row_count;

  perform private.refresh_attendance_confirmation_sessions(
    v_today - 2,
    v_today
  );

  for r in
    select ac.id
      from public.attendance_confirmations ac
     where ac.status in ('PENDING', 'AWAITING_TEACHER', 'ATTENDANCE_MISMATCH', 'CONFLICT')
       and ac.class_date >= v_today - 2
     order by ac.class_date, ac.class_time, ac.id
  loop
    perform public.reconcile_attendance_confirmation(r.id);
  end loop;

  return v_count;
end;
$_$;


--
-- Name: enqueue_interview_notification(uuid, timestamp with time zone, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_interview_notification(p_application_id uuid, p_expected_slot timestamp with time zone, p_event text, p_audience text, p_destination text, p_message_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception using errcode = '42501', message = 'service_role_required';
  end if;
  return private.enqueue_interview_notification_internal(
    p_application_id,
    p_expected_slot,
    p_event,
    p_audience,
    p_destination,
    p_message_body
  );
end;
$$;


--
-- Name: enqueue_nf_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_nf_reminders() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  r record;
  v_count int := 0;
  v_msg text;
  v_ja int;
  v_ultimo timestamptz;
BEGIN
  FOR r IN
    SELECT tc.teacher_id, tc.tenant_id, p.full_name, p.phone,
           count(*) AS n,
           sum(tc.total_amount) AS total,
           string_agg(tc.month_year || ' (R$ ' || replace(to_char(COALESCE(tc.total_amount,0),'FM999990.00'),'.',',') || ')', ', ' ORDER BY tc.month_year) AS lista,
           bool_or(tc.status IN ('REJECTED','REJEITADO')) AS tem_rejeitada
    FROM teacher_closings tc
    JOIN profiles p ON p.id = tc.teacher_id
    WHERE tc.status IN ('PAID_WAITING_NF', 'REJECTED', 'REJEITADO')
      AND COALESCE(tc.nf_link, '') = ''
      AND COALESCE(tc.total_amount, 0) > 0
      AND COALESCE(p.phone, '') <> ''
      AND COALESCE(p.nf_exempt, false) = false
      AND COALESCE(p.lifecycle_status, 'active') = 'active'
      AND tc.tenant_id IS NOT NULL
    GROUP BY tc.teacher_id, tc.tenant_id, p.full_name, p.phone
  LOOP
    SELECT count(*), max(created_at) INTO v_ja, v_ultimo
    FROM notification_queue
    WHERE source_id = r.teacher_id AND notification_kind = 'NF_REMINDER'
      AND created_at > now() - interval '30 days';
    IF v_ja >= 3 OR (v_ultimo IS NOT NULL AND v_ultimo > now() - interval '3 days') THEN
      CONTINUE;
    END IF;

    v_msg :=
      'Oi, ' || COALESCE(NULLIF(split_part(r.full_name, ' ', 1), ''), 'professor') || '! Aqui é da coordenação da Wise Wolf 🐺' || E'\n\n' ||
      CASE WHEN r.n = 1
        THEN 'Passando um lembrete rapidinho: seu fechamento de ' || r.lista || ' já foi pago, e agora só falta a sua nota fiscal. 🙏'
        ELSE 'Passando um lembrete rapidinho: seus fechamentos de ' || r.lista || ' já foram pagos, e agora só faltam as notas fiscais (pode ser uma NFS-e por fechamento). 🙏'
      END || E'\n\n' ||
      CASE WHEN r.tem_rejeitada
        THEN 'Obs.: há nota recusada entre elas — confere o motivo no painel antes de reenviar.' || E'\n\n'
        ELSE ''
      END ||
      'A emissão é pelo portal gov.br/nfse ou pelo app MEI, no valor do fechamento, e o PDF você anexa na aba "Notas Fiscais" do sistema. ' ||
      'Qualquer dúvida na emissão, chama a gente por aqui! 💜';

    INSERT INTO notification_queue
      (tenant_id, teacher_id, student_id, student_name, student_phone, message_body,
       scheduled_for, status, source_id, source_type, notification_kind)
    VALUES
      (r.tenant_id, NULL, NULL, r.full_name, r.phone, v_msg,
       now(), 'pending', r.teacher_id, 'teacher_nf', 'NF_REMINDER');

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('lembretes_enfileirados', v_count);
END;
$_$;


--
-- Name: enqueue_sdr_work(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_sdr_work(p_tenant_id text, p_phone text, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare v_id text := p_payload->>'msgId';
begin
  if coalesce(v_id,'')='' or p_phone !~ '^[0-9]{10,15}$' or jsonb_typeof(p_payload)<>'object'
    or length(p_payload::text)>20000 then raise exception 'invalid_sdr_input'; end if;
  if exists(select 1 from public.ai_wa_messages where tenant_id=p_tenant_id and phone=p_phone
    and agent='sdr' and direction='in' and meta->>'msg_id'=v_id) then return; end if;
  insert into public.sdr_conversation_work(tenant_id,phone,payload,latest_msg_id,available_at)
  values(p_tenant_id,p_phone,p_payload,v_id,now()+interval '2 seconds')
  on conflict(tenant_id,phone) do nothing;
  perform 1 from public.sdr_conversation_work where tenant_id=p_tenant_id and phone=p_phone for update;
  if exists(select 1 from public.ai_wa_messages where tenant_id=p_tenant_id and phone=p_phone
    and agent='sdr' and direction='in' and meta->>'msg_id'=v_id) then return; end if;
  insert into public.ai_wa_messages(tenant_id,phone,agent,direction,content,meta)
  values(p_tenant_id,p_phone,'sdr','in',left(coalesce(p_payload->>'text','[mídia]'),4000),
    jsonb_build_object('msg_id',v_id,'kind','sdr_queued'));
  update public.sdr_conversation_work set payload=p_payload,latest_msg_id=v_id,attempts=0,
    available_at=now()+interval '2 seconds',updated_at=now(),
    phase=case when phase='REVIEW' and not exists(
      select 1 from public.crm_leads l where l.tenant_id=p_tenant_id
        and regexp_replace(l.phone,'[^0-9]','','g')=p_phone
        and l.ai_handoff=true and l.ai_handoff_at>now()-interval '72 hours'
    ) then 'IDLE' else phase end
  where tenant_id=p_tenant_id and phone=p_phone;
end;
$_$;


--
-- Name: enqueue_whatsapp_webhook_event(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_whatsapp_webhook_event(p_tenant_id text, p_instance_name text, p_event_type text, p_event_key text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_instance_id uuid;
  v_instance_name text;
  v_event public.whatsapp_webhook_inbox%rowtype;
  v_inserted boolean := false;
begin
  if nullif(pg_catalog.btrim(p_tenant_id), '') is null
     or nullif(pg_catalog.btrim(p_instance_name), '') is null
     or nullif(pg_catalog.btrim(p_event_type), '') is null
     or nullif(pg_catalog.btrim(p_event_key), '') is null
     or p_payload is null
     or jsonb_typeof(p_payload) <> 'object'
     or pg_column_size(p_payload) > 1048576 then
    raise exception 'invalid_whatsapp_webhook_event' using errcode = '22023';
  end if;

  select instance.id, instance.instance_name
  into v_instance_id, v_instance_name
  from public.whatsapp_instances as instance
  where instance.tenant_id = p_tenant_id
    and lower(instance.instance_name) = lower(pg_catalog.btrim(p_instance_name))
    and private.whatsapp_inbox_instance_is_eligible(
      instance.tenant_id,
      instance.id
    );

  if not found then
    raise exception 'whatsapp_inbox_unavailable' using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'wa-event:' || p_tenant_id || ':' || v_instance_id::text || ':' ||
      pg_catalog.btrim(p_event_key),
      0
    )
  );

  select event.*
  into v_event
  from public.whatsapp_webhook_inbox as event
  where event.tenant_id = p_tenant_id
    and event.instance_name = v_instance_name
    and event.event_key = pg_catalog.btrim(p_event_key)
  for update;

  if found then
    if v_event.status <> 'processed' then
      -- Falhas e entregas interrompidas voltam a received. O consumidor faz
      -- a conclusão com WHERE status = 'received', portanto não há janela em
      -- que um retry legítimo fique permanentemente órfão.
      update public.whatsapp_webhook_inbox as event
      set event_type = pg_catalog.btrim(p_event_type),
          payload = p_payload,
          status = 'received',
          attempt_count = event.attempt_count + 1,
          available_at = pg_catalog.now(),
          lease_until = null,
          last_error = null,
          processed_at = null
      where event.id = v_event.id
      returning event.* into v_event;
    end if;
  else
    insert into public.whatsapp_webhook_inbox (
      tenant_id,
      instance_id,
      instance_name,
      event_type,
      event_key,
      payload
    )
    values (
      p_tenant_id,
      v_instance_id,
      v_instance_name,
      pg_catalog.btrim(p_event_type),
      pg_catalog.btrim(p_event_key),
      p_payload
    )
    returning * into v_event;
    v_inserted := true;
  end if;

  -- Evento já processado é um no-op idempotente; seu payload e contador não
  -- são reabertos por redelivery tardia do provedor.
  if v_event.status = 'processed' then
    select event.*
    into strict v_event
    from public.whatsapp_webhook_inbox as event
    where event.id = v_event.id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'eventId', v_event.id,
    'inserted', v_inserted,
    'status', v_event.status
  );
end;
$$;


--
-- Name: enroll_student_learning_path(uuid, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enroll_student_learning_path(p_path_id uuid, p_switch_current boolean DEFAULT false, p_reason text DEFAULT NULL::text, p_student_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_path_active boolean;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  if exists (
    select 1
      from public.profiles as actor
     where actor.id = auth.uid()
       and actor.role = 'STUDENT'
  ) then
    perform private.assert_active_student_learning_mutation();
  end if;

  if p_path_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  select path.active
    into v_path_active
    from public.learning_paths as path
   where path.id = p_path_id
   for update;
  if not found or v_path_active is not true then
    raise exception using errcode = '42501', message = 'learning_path_not_available';
  end if;

  return public.enroll_student_learning_path_core(
    p_path_id,
    p_switch_current,
    p_reason,
    p_student_id
  );
end;
$$;


--
-- Name: enroll_student_learning_path_core(uuid, boolean, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enroll_student_learning_path_core(p_path_id uuid, p_switch_current boolean DEFAULT false, p_reason text DEFAULT NULL::text, p_student_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor record;
  v_target_id uuid := coalesce(p_student_id, auth.uid());
  v_target record;
  v_path record;
  v_active public.student_path_enrollments%rowtype;
  v_existing public.student_path_enrollments%rowtype;
  v_enrollment public.student_path_enrollments%rowtype;
  v_next record;
  v_reason text := nullif(pg_catalog.btrim(coalesce(p_reason, '')), '');
  v_now timestamptz := pg_catalog.now();
  v_event_type text;
  v_switched boolean := false;
begin
  if v_actor_id is null or p_path_id is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  if v_reason is not null and pg_catalog.length(v_reason) > 500 then
    raise exception using
      errcode = '22023',
      message = 'invalid_learning_enrollment_reason';
  end if;

  select profile.id, profile.role, profile.tenant_id
    into v_actor
    from public.profiles as profile
   where profile.id = v_actor_id;

  if not found or v_actor.role not in (
    'STUDENT',
    'TEACHER',
    'SCHOOL_ADMIN',
    'SUPER_ADMIN'
  ) then
    raise exception using
      errcode = '42501',
      message = 'learning_enrollment_actor_not_authorized';
  end if;

  if v_actor.role = 'STUDENT' and v_target_id <> v_actor_id then
    raise exception using
      errcode = '42501',
      message = 'student_can_only_enroll_self';
  end if;

  select profile.id, profile.role, profile.tenant_id
    into v_target
    from public.profiles as profile
   where profile.id = v_target_id
   for update;

  if not found
     or v_target.role <> 'STUDENT'
     or v_target.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  if v_actor.role = 'TEACHER'
     and not public._teacher_can_access_student(
       v_target_id,
       v_target.tenant_id
     ) then
    raise exception using
      errcode = '42501',
      message = 'teacher_student_scope_required';
  elsif v_actor.role = 'SCHOOL_ADMIN'
        and v_actor.tenant_id is distinct from v_target.tenant_id then
    raise exception using
      errcode = '42501',
      message = 'learning_enrollment_tenant_mismatch';
  end if;

  select path.id, path.tenant_id, path.active
    into v_path
    from public.learning_paths as path
   where path.id = p_path_id
     and path.active is true
     and (
       path.tenant_id is null
       or path.tenant_id = v_target.tenant_id
     );

  if not found then
    raise exception using
      errcode = '42501',
      message = 'learning_path_not_available';
  end if;

  select next_activity.activity_id, next_activity.unit_id
    into v_next
    from private.next_incomplete_learning_activity(
      v_target_id,
      p_path_id
    ) as next_activity;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'learning_path_has_no_available_activities';
  end if;

  select *
    into v_active
    from public.student_path_enrollments as enrollment
   where enrollment.student_id = v_target_id
     and enrollment.status = 'ACTIVE'
     and enrollment.completed_at is null
   order by enrollment.started_at desc nulls last, enrollment.id desc
   limit 1
   for update;

  if found and v_active.path_id = p_path_id then
    if v_active.current_unit_id is distinct from v_next.unit_id then
      update public.student_path_enrollments
         set current_unit_id = v_next.unit_id,
             updated_at = v_now
       where id = v_active.id
      returning * into v_active;
    end if;

    return pg_catalog.jsonb_build_object(
      'enrollmentId', v_active.id,
      'studentId', v_target_id,
      'pathId', p_path_id,
      'status', v_active.status,
      'currentUnitId', v_active.current_unit_id,
      'alreadyEnrolled', true,
      'switched', false
    );
  end if;

  if found then
    if coalesce(p_switch_current, false) is not true then
      raise exception using
        errcode = 'P0001',
        message = 'active_path_switch_required';
    end if;

    if v_reason is null then
      raise exception using
        errcode = '22023',
        message = 'learning_path_switch_reason_required';
    end if;

    update public.student_path_enrollments
       set status = 'SWITCHED',
           status_reason = v_reason,
           completed_at = v_now,
           ended_at = v_now,
           updated_at = v_now
     where id = v_active.id;

    insert into public.student_path_enrollment_history (
      enrollment_id,
      tenant_id,
      student_id,
      path_id,
      event_type,
      from_status,
      to_status,
      reason,
      actor_id,
      occurred_at
    ) values (
      v_active.id,
      v_active.tenant_id,
      v_target_id,
      v_active.path_id,
      'SWITCHED_OUT',
      'ACTIVE',
      'SWITCHED',
      v_reason,
      v_actor_id,
      v_now
    );
    v_switched := true;
  end if;

  select *
    into v_existing
    from public.student_path_enrollments as enrollment
   where enrollment.student_id = v_target_id
     and enrollment.path_id = p_path_id
   for update;

  if found then
    update public.student_path_enrollments
       set tenant_id = v_target.tenant_id,
           status = 'ACTIVE',
           status_reason = v_reason,
           current_unit_id = v_next.unit_id,
           started_at = v_now,
           completed_at = null,
           ended_at = null,
           assigned_by = case
             when v_actor.role = 'STUDENT' then null
             else v_actor_id
           end,
           updated_at = v_now
     where id = v_existing.id
    returning * into v_enrollment;
    v_event_type := 'REACTIVATED';
  else
    insert into public.student_path_enrollments (
      student_id,
      path_id,
      tenant_id,
      current_unit_id,
      started_at,
      completed_at,
      assigned_by,
      status,
      status_reason,
      ended_at,
      updated_at
    ) values (
      v_target_id,
      p_path_id,
      v_target.tenant_id,
      v_next.unit_id,
      v_now,
      null,
      case when v_actor.role = 'STUDENT' then null else v_actor_id end,
      'ACTIVE',
      v_reason,
      null,
      v_now
    )
    returning * into v_enrollment;
    v_event_type := 'ENROLLED';
  end if;

  insert into public.student_path_enrollment_history (
    enrollment_id,
    tenant_id,
    student_id,
    path_id,
    event_type,
    from_status,
    to_status,
    reason,
    actor_id,
    occurred_at
  ) values (
    v_enrollment.id,
    v_enrollment.tenant_id,
    v_target_id,
    p_path_id,
    v_event_type,
    case when v_event_type = 'REACTIVATED' then v_existing.status else null end,
    'ACTIVE',
    v_reason,
    v_actor_id,
    v_now
  );

  return pg_catalog.jsonb_build_object(
    'enrollmentId', v_enrollment.id,
    'studentId', v_target_id,
    'pathId', p_path_id,
    'status', v_enrollment.status,
    'currentUnitId', v_enrollment.current_unit_id,
    'alreadyEnrolled', false,
    'switched', v_switched
  );
end;
$$;


--
-- Name: FUNCTION enroll_student_learning_path_core(p_path_id uuid, p_switch_current boolean, p_reason text, p_student_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enroll_student_learning_path_core(p_path_id uuid, p_switch_current boolean, p_reason text, p_student_id uuid) IS 'Creates or resumes one active path and requires an explicit reason when switching away from another active enrollment.';


--
-- Name: experimentais_sem_confirmacao(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.experimentais_sem_confirmacao(p_month text DEFAULT NULL::text) RETURNS TABLE(class_log_id uuid, teacher_id uuid, teacher_name text, aluno text, class_date date, appointment_status text, trial_status text, situacao text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT cl.id, cl.teacher_id, p.full_name,
         COALESCE(ap.student_name, 'Sem nome'), cl.class_date,
         COALESCE(ap.status,'(sem agendamento)'), COALESCE(op.trial_status,'(nulo)'),
         CASE
           WHEN COALESCE(ap.status,'') = 'no_show' OR COALESCE(op.trial_status,'') = 'NO_SHOW_STUDENT'
             THEN 'aluno faltou'
           ELSE 'comparecimento não registrado'
         END
  FROM class_logs cl
  JOIN profiles p ON p.id = cl.teacher_id
  LEFT JOIN appointments ap ON ap.id::text = cl.appointment_id
  LEFT JOIN opportunities op ON op.trial_appointment_id = ap.id
  WHERE cl.subtype = 'AULA EXPERIMENTAL'
    AND cl.appointment_id IS NOT NULL
    AND to_char(cl.class_date,'YYYY-MM') = COALESCE(p_month, to_char(current_date,'YYYY-MM'))
    AND NOT EXISTS (SELECT 1 FROM v_payable_class_logs v WHERE v.id = cl.id)
  ORDER BY p.full_name, cl.class_date;
$$;


--
-- Name: expire_referral_invites(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_referral_invites() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    UPDATE public.referral_invites
    SET status = 'EXPIRED'
    WHERE status = 'PENDING' AND expires_at < now();
END;
$$;


--
-- Name: expire_stale_conversions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_stale_conversions() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_expired_count INTEGER := 0;
    v_prospect RECORD;
    v_settings RECORD;
BEGIN
    FOR v_prospect IN
        SELECT p.id, p.tenant_id, p.referrer_code, p.created_at
        FROM public.prospects p
        WHERE p.status IN ('VERIFIED', 'TRIAL_SCHEDULED', 'TRIAL_DONE')
          AND p.promoted_at IS NULL
    LOOP
        SELECT * INTO v_settings FROM public.tenant_referral_settings
        WHERE tenant_id = v_prospect.tenant_id;

        IF v_settings IS NOT NULL AND
           v_prospect.created_at < now() - make_interval(
               days => COALESCE(v_settings.trial_to_signup_window_days, 30)
           )
        THEN
            UPDATE public.prospects SET
                status = 'EXPIRED',
                updated_at = now()
            WHERE id = v_prospect.id;

            v_expired_count := v_expired_count + 1;

            -- Notify referrer via outbox if they have a code
            IF v_prospect.referrer_code IS NOT NULL THEN
                INSERT INTO public.outbox_messages (
                    channel, destination, payload, status,
                    tenant_id, correlation_id
                )
                SELECT
                    'whatsapp',
                    prof.phone,
                    jsonb_build_object(
                        'type', 'REFERRAL_EXPIRED',
                        'prospect_name', (SELECT full_name FROM public.prospects WHERE id = v_prospect.id),
                        'text', '⏳ Sua indicação expirou. Convide-o novamente!'
                    ),
                    'PENDING',
                    v_prospect.tenant_id,
                    v_prospect.id
                FROM public.affiliate_codes ac
                JOIN public.profiles prof ON prof.id = ac.owner_id
                WHERE ac.code = v_prospect.referrer_code
                LIMIT 1;
            END IF;
        END IF;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'expired_count', v_expired_count);
END;
$$;


--
-- Name: expire_trial_opportunity_atomic(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_trial_opportunity_atomic(p_tenant_id text, p_opportunity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_runtime_role text := coalesce((select auth.jwt() ->> 'role'), '');
  v_opportunity public.opportunities%rowtype;
  v_request private.vendor_trial_teacher_requests%rowtype;
  v_slot_date date;
  v_slot_time time without time zone;
  v_slot_start timestamptz;
  v_due boolean := false;
begin
  if v_runtime_role <> 'service_role' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'forbidden'
    );
  end if;
  if nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '') is null
     or p_opportunity_id is null then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'invalid_request'
    );
  end if;

  begin
    perform private.lock_trial_conversion_graph(p_opportunity_id);
  exception when no_data_found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'opportunity_not_found'
    );
  end;
  select opportunity.*
  into v_opportunity
  from public.opportunities as opportunity
  where opportunity.id = p_opportunity_id;

  if v_opportunity.tenant_id is distinct from p_tenant_id
     or v_opportunity.kind <> 'TRIAL' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'opportunity_not_found'
    );
  end if;
  if v_opportunity.status = 'EXPIRED'
     and v_opportunity.conversion_status = 'LOST' then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'expired', false,
      'idempotent', true,
      'state', 'EXPIRED'
    );
  end if;
  if v_opportunity.status <> 'OPEN'
     or v_opportunity.conversion_status <> 'OPEN' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'error', 'opportunity_not_expirable',
      'state', v_opportunity.status
    );
  end if;

  select request.*
  into v_request
  from private.vendor_trial_teacher_requests as request
  where request.opportunity_id = p_opportunity_id;

  v_due := coalesce(v_opportunity.opened_at, v_opportunity.created_at)
    <= pg_catalog.now() - case when v_request.id is null
      then interval '60 minutes' else interval '48 hours' end;
  if v_request.id is not null
     and v_request.status in ('AWAITING_STUDENT', 'AWAITING_TEACHER')
     and v_request.slot_start <= pg_catalog.now() + interval '5 minutes' then
    v_due := true;
  end if;
  if exists (
    select 1
    from public.enrollment_links as link
    where link.opportunity_id = p_opportunity_id
      and link.purpose = 'TRIAL_CONFIRMATION'
      and link.status = 'PENDING'
      and link.expires_at <= pg_catalog.now()
  ) then
    v_due := true;
  end if;

  if pg_catalog.jsonb_typeof(v_opportunity.slots_proposed) = 'array'
     and pg_catalog.jsonb_array_length(v_opportunity.slots_proposed) > 0
     and coalesce(v_opportunity.slots_proposed #>> '{0,date}', '')
       ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     and coalesce(v_opportunity.slots_proposed #>> '{0,time}', '')
       ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$' then
    begin
      v_slot_date := (v_opportunity.slots_proposed #>> '{0,date}')::date;
      v_slot_time := (v_opportunity.slots_proposed #>> '{0,time}')::time;
      v_slot_start := (v_slot_date + v_slot_time)
        at time zone 'America/Sao_Paulo';
      if v_slot_start <= pg_catalog.now() then
        v_due := true;
      end if;
    exception
      when invalid_datetime_format or datetime_field_overflow then
        null;
    end;
  end if;

  if not v_due then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'expired', false,
      'idempotent', false,
      'state', 'NOT_DUE'
    );
  end if;

  update public.enrollment_links as link
  set status = 'EXPIRED'
  where link.opportunity_id = p_opportunity_id
    and link.purpose = 'TRIAL_CONFIRMATION'
    and link.status = 'PENDING';

  update private.vendor_trial_teacher_requests as request
  set status = 'EXPIRED',
      updated_at = pg_catalog.now()
  where request.opportunity_id = p_opportunity_id
    and request.status in ('AWAITING_STUDENT', 'AWAITING_TEACHER');

  update public.opportunities as opportunity
  set status = 'EXPIRED',
      conversion_status = 'LOST',
      lost_reason = case
        when v_request.status = 'AWAITING_STUDENT' then coalesce(
          nullif(pg_catalog.btrim(opportunity.lost_reason), ''),
          'STUDENT_CONFIRMATION_EXPIRED'
        )
        else null
      end
  where opportunity.id = p_opportunity_id
    and opportunity.tenant_id = p_tenant_id
    and opportunity.status = 'OPEN'
    and opportunity.conversion_status = 'OPEN';
  if not found then
    raise exception 'trial_expiration_lost_lock' using errcode = '40001';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'expired', true,
    'idempotent', false,
    'state', 'EXPIRED'
  );
end;
$_$;


--
-- Name: expire_trial_reschedule_confirmation(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.expire_trial_reschedule_confirmation(p_tenant_id text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_request public.trial_reschedule_requests%rowtype;
begin
  select * into v_request from public.trial_reschedule_requests
  where id = p_request_id and tenant_id = p_tenant_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'request_not_found'); end if;
  -- Same lock order as the teacher acceptance RPC: appointment then request.
  perform 1 from public.appointments where id = v_request.appointment_id for update;
  select * into v_request from public.trial_reschedule_requests
  where id = p_request_id and tenant_id = p_tenant_id for update;
  if v_request.status = 'PENDING' and
     least(v_request.expires_at, v_request.created_at + interval '60 minutes') <= now() then
    update public.trial_reschedule_requests
    set status = 'EXPIRED', responded_at = now(), response_text = 'teacher_acceptance_timeout'
    where id = p_request_id;
    return jsonb_build_object('ok', true, 'expired', true);
  end if;
  return jsonb_build_object('ok', true, 'expired', v_request.status = 'EXPIRED');
end;
$$;


--
-- Name: export_tenant_data(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.export_tenant_data(p_tenant_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_role TEXT;
    v_caller_tenant TEXT;
    v_result JSONB := '{}'::JSONB;
BEGIN
    SELECT role, tenant_id INTO v_role, v_caller_tenant FROM profiles WHERE id = auth.uid();
    IF v_role <> 'SUPER_ADMIN' AND (v_role <> 'SCHOOL_ADMIN' OR v_caller_tenant <> p_tenant_id) THEN
        RAISE EXCEPTION 'Acesso negado';
    END IF;

    v_result := jsonb_build_object(
        'export_metadata', jsonb_build_object(
            'tenant_id', p_tenant_id,
            'exported_at', now(),
            'exported_by', auth.uid()
        ),
        'tenant', (SELECT row_to_json(t) FROM tenants t WHERE t.id = p_tenant_id),
        'profiles', COALESCE((SELECT jsonb_agg(row_to_json(p)) FROM profiles p WHERE p.tenant_id = p_tenant_id), '[]'::JSONB),
        'bookings', COALESCE((SELECT jsonb_agg(row_to_json(b)) FROM bookings b WHERE b.tenant_id = p_tenant_id), '[]'::JSONB),
        'class_logs', COALESCE((SELECT jsonb_agg(row_to_json(c)) FROM class_logs c WHERE c.tenant_id = p_tenant_id), '[]'::JSONB),
        'reschedules', COALESCE((SELECT jsonb_agg(row_to_json(r)) FROM reschedules r WHERE r.tenant_id = p_tenant_id), '[]'::JSONB),
        'opportunities', COALESCE((SELECT jsonb_agg(row_to_json(o)) FROM opportunities o WHERE o.tenant_id = p_tenant_id), '[]'::JSONB),
        'student_payments', COALESCE((SELECT jsonb_agg(row_to_json(sp)) FROM student_payments sp WHERE sp.tenant_id = p_tenant_id), '[]'::JSONB),
        'teacher_closings', COALESCE((SELECT jsonb_agg(row_to_json(tc)) FROM teacher_closings tc WHERE tc.tenant_id = p_tenant_id), '[]'::JSONB),
        'student_pricing_plans', COALESCE((SELECT jsonb_agg(row_to_json(spp)) FROM student_pricing_plans spp WHERE spp.tenant_id = p_tenant_id), '[]'::JSONB),
        'vendor_commissions', COALESCE((SELECT jsonb_agg(row_to_json(vc)) FROM vendor_commissions vc WHERE vc.tenant_id = p_tenant_id), '[]'::JSONB),
        'wolf_intelligence', COALESCE((SELECT jsonb_agg(row_to_json(wi)) FROM wolf_intelligence wi WHERE wi.tenant_id = p_tenant_id), '[]'::JSONB),
        'audit_logs', COALESCE((SELECT jsonb_agg(row_to_json(al)) FROM audit_logs al WHERE al.tenant_id = p_tenant_id), '[]'::JSONB)
    );
    RETURN v_result;
END;
$$;


--
-- Name: fail_attendance_confirmation_delivery(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_attendance_confirmation_delivery(p_confirmation_id uuid, p_claim_token uuid, p_error_code text, p_ambiguous boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  c public.attendance_confirmations%rowtype;
  v_error text := pg_catalog.left(
    coalesce(nullif(pg_catalog.btrim(p_error_code), ''), 'delivery_failed'),
    500
  );
  v_status text;
  v_cancelled boolean := false;
  v_occurrence_missing boolean := false;
begin
  if p_confirmation_id is null or p_claim_token is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'claim_invalido');
  end if;

  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = p_confirmation_id
   for update;

  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'nao_encontrado');
  end if;

  if c.delivery_status <> 'PROCESSING'
     or c.delivery_claim_token is distinct from p_claim_token then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'error', 'claim_obsoleto',
      'delivery_status', c.delivery_status
    );
  end if;

  if v_error in ('occurrence_not_found', 'occurrence_cancelled') then
    select not exists (
      select 1
        from public.attendance_confirmations member
        join public.upcoming_classes uc
          on uc.source_id::text = member.source_id
         and uc.source_type = member.source_type
         and uc.class_date = member.class_date
       where coalesce(member.canonical_confirmation_id, member.id) = c.id
    )
    into v_occurrence_missing;
  end if;

  if not coalesce(p_ambiguous, false)
     and v_error in ('occurrence_not_found', 'occurrence_cancelled')
     and v_occurrence_missing then
    v_status := 'CANCELLED';
    v_cancelled := true;
  elsif v_error = 'stale_delivery_suppressed' then
    -- A stale message must not go out, but delivery age says nothing about
    -- whether the lesson itself existed. Preserve the business audit status.
    v_status := 'FAILED';
  elsif not coalesce(p_ambiguous, false)
        and v_error in ('occurrence_not_found', 'occurrence_cancelled') then
    -- The worker's stale view disagreed with the authoritative agenda. Fail the
    -- delivery terminally without cancelling a real lesson.
    v_status := 'FAILED';
  elsif coalesce(p_ambiguous, false) then
    v_status := 'AMBIGUOUS';
  elsif c.send_attempts >= 8 then
    v_status := 'FAILED';
  else
    v_status := 'PENDING';
  end if;

  update public.attendance_confirmations ac
     set delivery_status = v_status,
         status = case when v_cancelled then 'CANCELLED' else ac.status end,
         delivery_claim_expires_at = null,
         last_delivery_error = v_error
   where ac.id = c.id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'delivery_status', v_status,
    'retryable', v_status = 'PENDING',
    'ambiguous', v_status = 'AMBIGUOUS',
    'cancelled', v_cancelled
  );
end;
$$;


--
-- Name: outbox_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.outbox_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    channel text DEFAULT 'whatsapp'::text NOT NULL,
    destination text NOT NULL,
    payload jsonb NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 5 NOT NULL,
    next_retry_at timestamp with time zone DEFAULT now() NOT NULL,
    last_error text,
    correlation_id uuid,
    tenant_id text,
    actor_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    last_attempt_at timestamp with time zone,
    CONSTRAINT outbox_messages_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'PROCESSING'::text, 'SENT'::text, 'FAILED'::text, 'RETRY'::text, 'DLQ'::text])))
);


--
-- Name: TABLE outbox_messages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.outbox_messages IS 'Transactional outbox for reliable message delivery. Worker polls PENDING items.';


--
-- Name: fetch_outbox_batch(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fetch_outbox_batch(p_batch_size integer DEFAULT 10) RETURNS SETOF public.outbox_messages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_ids UUID[];
BEGIN
    SELECT ARRAY_AGG(id) INTO v_ids
    FROM (
        SELECT id
        FROM public.outbox_messages
        WHERE status IN ('PENDING', 'RETRY')
          AND next_retry_at <= now()
        ORDER BY created_at ASC
        LIMIT p_batch_size
        FOR UPDATE SKIP LOCKED
    ) sub;

    IF v_ids IS NULL OR array_length(v_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    UPDATE public.outbox_messages
    SET status = 'PROCESSING',
        last_attempt_at = now()
    WHERE id = ANY(v_ids);

    RETURN QUERY
    SELECT *
    FROM public.outbox_messages
    WHERE id = ANY(v_ids);
END;
$$;


--
-- Name: FUNCTION fetch_outbox_batch(p_batch_size integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.fetch_outbox_batch(p_batch_size integer) IS 'Atomically fetches and locks a batch of outbox messages for processing. Uses SKIP LOCKED.';


--
-- Name: fill_class_log_occurrence_time(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fill_class_log_occurrence_time() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_time text;
  v_supplied_time time := new.start_time;
  v_authoritative_time time;
  v_confirmation_time time;
  v_source_date date;
  v_slot_day int;
  v_appt_type text;
  v_source_count int;
begin
  v_source_count := pg_catalog.num_nonnulls(
    new.booking_id, new.reschedule_id, new.appointment_id
  );

  -- Logs puramente administrativos/legados continuam fora desta regra. Uma
  -- ocorrencia que declara origem, porem, deve declarar exatamente uma.
  if v_source_count = 0 then
    return new;
  elsif v_source_count <> 1 then
    raise exception using
      errcode = '23514',
      message = 'class_log_must_have_exactly_one_source';
  end if;

  if new.class_date is null then
    raise exception using
      errcode = '23514',
      message = 'class_log_source_date_required';
  end if;

  if new.booking_id is not null then
    select pg_catalog.left(pg_catalog.btrim(b.time_slot), 5)::time
      into v_authoritative_time
      from public.bookings b
     where b.id::text = new.booking_id
       and b.tenant_id = new.tenant_id
       and b.status = 'SCHEDULED'
       and b.student_id is not null
       and b.student_id = new.student_id
       and b.start_date is not null
       and b.start_date <= new.class_date
       and public.dow_name_to_int(b.day_of_week) = extract(dow from new.class_date)::int
       and pg_catalog.btrim(b.time_slot) ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
       and (
         (
           b.teacher_id = new.teacher_id
           and not exists (
             select 1
               from public.class_coverages c
              where c.booking_id = b.id
                and c.tenant_id = new.tenant_id
                and c.class_date = new.class_date
                and c.status = 'confirmed'
                and c.cover_teacher_id is distinct from new.teacher_id
           )
         )
         or exists (
           select 1
             from public.class_coverages c
            where c.booking_id = b.id
              and c.tenant_id = new.tenant_id
              and c.class_date = new.class_date
              and c.status = 'confirmed'
              and c.cover_teacher_id = new.teacher_id
         )
       )
     limit 1;

    if not found then
      raise exception using
        errcode = '23514',
        message = 'class_log_booking_origin_invalid';
    end if;

  elsif new.reschedule_id is not null then
    select pg_catalog.left(pg_catalog.btrim(r.time), 5)::time
      into v_authoritative_time
      from public.reschedules r
     where r.id::text = new.reschedule_id
       and r.tenant_id = new.tenant_id
       and r.teacher_id = new.teacher_id
       and r.student_id = new.student_id
       and public.parse_lesson_date(r.date) = new.class_date
       and (
         r.used_at is null
         or (
           tg_op = 'UPDATE'
           and old.reschedule_id is not distinct from new.reschedule_id
         )
       )
       and pg_catalog.btrim(r.time) ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
     limit 1;

    if not found then
      raise exception using
        errcode = '23514',
        message = 'class_log_reschedule_origin_invalid';
    end if;

  elsif new.appointment_id ~* '^trial_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    -- Compatibilidade estrita com TrialsToContracts: antes de existir um
    -- appointment real, a tela gravava `trial_<opportunity_uuid>`. Nao basta o
    -- prefixo: a oportunidade deve estar concluida, sem appointment, pertencer
    -- ao mesmo tenant/professor e fornecer o horario autoritativo.
    select
      case when pg_catalog.lower(coalesce(o.kind, 'TRIAL')) = 'training'
           then 'training' else 'experimental' end,
      public.parse_lesson_date(slot.value ->> 'date'),
      pg_catalog.left(pg_catalog.btrim(slot.value ->> 'time'), 5)::time,
      case
        when pg_catalog.btrim(coalesce(slot.value ->> 'day', '')) ~ '^[0-6]$'
          then pg_catalog.btrim(slot.value ->> 'day')::int
        else public.dow_name_to_int(slot.value ->> 'day')
      end
      into v_appt_type, v_source_date, v_authoritative_time, v_slot_day
      from public.opportunities o
      cross join lateral (
        select item.value
          from pg_catalog.jsonb_array_elements(
            case when pg_catalog.jsonb_typeof(o.slots_proposed) = 'array'
                 then o.slots_proposed else '[]'::jsonb end
          ) with ordinality as item(value, position)
         where pg_catalog.btrim(item.value ->> 'time')
               ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
         order by item.position
         limit 1
      ) slot
     where o.id = pg_catalog.substr(new.appointment_id, 7)::uuid
       and o.tenant_id = new.tenant_id
       and o.winner_teacher_id = new.teacher_id
       and o.status = 'CLAIMED'
       and o.trial_status = 'DONE'
       and o.trial_appointment_id is null
     limit 1;

    if not found
       or new.student_id is not null
       or new.presence is distinct from 'COMPLETED'
       or new.subtype is distinct from (
         case when v_appt_type = 'training'
              then 'TREINAMENTO'
              else 'AULA EXPERIMENTAL' end
       )
    then
      raise exception using
        errcode = '23514',
        message = 'class_log_synthetic_appointment_invalid';
    end if;

    if v_source_date is not null then
      -- O consumidor legado enviava "hoje" quando nao havia appointment. Essa
      -- unica divergencia conhecida e aceita, mas o snapshot gravado e forcado
      -- para a data proposta; uma data arbitraria continua sendo fraude.
      if new.class_date is distinct from v_source_date
         and new.class_date is distinct from
             (pg_catalog.now() at time zone 'America/Sao_Paulo')::date
      then
        raise exception using
          errcode = '23514',
          message = 'class_log_synthetic_appointment_date_mismatch';
      end if;
      new.class_date := v_source_date;
      new.date := v_source_date;
    elsif v_slot_day is null
       or v_slot_day <> extract(dow from new.class_date)::int
    then
      raise exception using
        errcode = '23514',
        message = 'class_log_synthetic_appointment_date_invalid';
    end if;

  elsif new.appointment_id
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
  then
    select
      pg_catalog.lower(coalesce(a.type, 'experimental')),
      (a.start_time at time zone 'America/Sao_Paulo')::time
      into v_appt_type, v_authoritative_time
      from public.appointments a
     where a.id::text = new.appointment_id
       and a.tenant_id = new.tenant_id
       and a.start_time is not null
       and (a.start_time at time zone 'America/Sao_Paulo')::date = new.class_date
       and pg_catalog.lower(coalesce(a.status, '')) in ('scheduled', 'completed')
       and pg_catalog.lower(coalesce(a.type, '')) in ('experimental', 'training')
       and (
         coalesce(a.teacher_id, a.professor_id) = new.teacher_id
         or exists (
           select 1
             from public.opportunities o
            where o.trial_appointment_id = a.id
              and o.tenant_id = new.tenant_id
              and o.winner_teacher_id = new.teacher_id
         )
       )
     limit 1;

    if not found
       or new.student_id is not null
       or new.presence is distinct from 'COMPLETED'
    then
      raise exception using
        errcode = '23514',
        message = 'class_log_appointment_origin_invalid';
    end if;

    new.subtype := case when v_appt_type = 'training'
                        then 'TREINAMENTO'
                        else 'AULA EXPERIMENTAL' end;

  else
    raise exception using
      errcode = '23514',
      message = 'class_log_appointment_origin_invalid';
  end if;

  -- A confirmacao enviada ao aluno e o snapshot historico mais forte. Ela so
  -- pode sobrescrever a fonte depois que tenant, professor, aluno e data foram
  -- validados acima.
  select pg_catalog.left(pg_catalog.btrim(ac.class_time), 5)::time
    into v_confirmation_time
    from public.attendance_confirmations ac
   where ac.tenant_id = new.tenant_id
     and ac.class_date = new.class_date
     and ac.teacher_id = new.teacher_id
     and ac.student_id is not distinct from new.student_id
     and pg_catalog.btrim(ac.class_time)
         ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
     and (
       ac.class_log_id = new.id
       or (ac.source_type = 'booking' and ac.source_id = new.booking_id)
       or (ac.source_type = 'reschedule' and ac.source_id = new.reschedule_id)
       or (ac.source_type = 'appointment' and ac.source_id = new.appointment_id)
     )
   order by (ac.class_log_id = new.id) desc nulls last, ac.created_at desc, ac.id desc
   limit 1;

  if found then
    v_authoritative_time := v_confirmation_time;
  end if;

  if v_authoritative_time is null then
    raise exception using
      errcode = '23514',
      message = 'class_log_occurrence_time_required';
  end if;

  if v_supplied_time is not null
     and v_supplied_time is distinct from v_authoritative_time
  then
    raise exception using
      errcode = '23514',
      message = 'class_log_occurrence_time_mismatch';
  end if;

  new.start_time := v_authoritative_time;
  new.date := new.class_date;

  return new;
end;
$_$;


--
-- Name: fim_do_servico(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fim_do_servico(p_ultima_cobranca date) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  -- A última parcela paga o mês seguinte de aula.
  select case when p_ultima_cobranca is null then null
              else (p_ultima_cobranca + interval '1 month')::date end;
$$;


--
-- Name: finalize_invite_offer_server(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_invite_offer_server(p_offer_id uuid, p_kind text, p_claim_token uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  offer_tenant_id text;
  offer_payload jsonb;
  expected_role text;
BEGIN
  expected_role := CASE p_kind
    WHEN 'TEACHER_INVITE' THEN 'TEACHER'
    WHEN 'VENDOR_INVITE' THEN 'SALESPERSON'
    ELSE NULL
  END;
  IF expected_role IS NULL OR p_claim_token IS NULL OR p_user_id IS NULL THEN
    RAISE EXCEPTION 'invalid_invite_finalize' USING ERRCODE = '22023';
  END IF;

  SELECT offer.tenant_id, offer.payload
  INTO offer_tenant_id, offer_payload
  FROM public.offers AS offer
  WHERE offer.id = p_offer_id
    AND offer.kind = p_kind
    AND offer.invite_claim_token = p_claim_token
    AND offer.invite_security_version >= 1
    AND offer.consumed_at IS NULL
    AND offer.revoked_at IS NULL
    AND offer.expires_at > now()
    AND offer.invite_claimed_at > now() - interval '15 minutes'
  FOR UPDATE;

  IF offer_tenant_id IS NULL THEN
    RAISE EXCEPTION 'invite_claim_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF NOT private.tenant_is_operational(offer_tenant_id) THEN
    RAISE EXCEPTION 'tenant_inactive' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.tenant_memberships AS membership
    WHERE membership.user_id = p_user_id
      AND membership.tenant_id = offer_tenant_id
      AND membership.role = expected_role
      AND membership.status = 'ACTIVE'
  ) THEN
    RAISE EXCEPTION 'invite_profile_scope_mismatch' USING ERRCODE = '42501';
  END IF;
  IF p_kind = 'TEACHER_INVITE' AND NOT EXISTS (
    SELECT 1
    FROM public.tenant_contract_records AS contract
    WHERE contract.tenant_id = offer_tenant_id
      AND contract.user_id = p_user_id
      AND contract.contract_kind = 'TEACHER'
      AND contract.legal_snapshot = offer_payload -> 'schoolInfo'
      AND contract.commercial_snapshot -> 'hourlyRate'
        = offer_payload -> 'hourlyRate'
      AND contract.commercial_snapshot ->> 'subject'
        = offer_payload ->> 'subject'
  ) THEN
    RAISE EXCEPTION 'invite_contract_snapshot_missing' USING ERRCODE = '42501';
  END IF;

  UPDATE public.offers
  SET consumed_at = now(),
      consumed_by = p_user_id,
      invite_claim_token = NULL,
      invite_claimed_at = NULL
  WHERE id = p_offer_id;

  RETURN true;
END;
$$;


--
-- Name: finalize_notification_delivery(uuid, uuid, text, text, integer, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_notification_delivery(p_notification_id uuid, p_claim_token uuid, p_outcome text, p_provider_message_id text, p_provider_http_status integer, p_error text, p_retry_delay_seconds integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_notification public.notification_queue%rowtype;
  v_financial_outbound public.asaas_outbound_message_attempts%rowtype;
  v_outcome text := lower(pg_catalog.btrim(coalesce(p_outcome, '')));
  v_provider_message_id text := nullif(
    pg_catalog.btrim(coalesce(p_provider_message_id, '')),
    ''
  );
  v_error text := nullif(
    pg_catalog.left(pg_catalog.btrim(coalesce(p_error, '')), 500),
    ''
  );
  v_retry_delay integer := greatest(
    0,
    least(coalesce(p_retry_delay_seconds, 0), 86400)
  );
  v_reconcile jsonb;
  v_was_preparing boolean := false;
begin
  if p_notification_id is null
     or p_claim_token is null
     or v_outcome not in (
       'accepted', 'sent', 'delivered', 'read',
       'failed', 'uncertain', 'skipped'
     )
     or (
       p_provider_http_status is not null
       and p_provider_http_status not between 100 and 599
     )
     or (
       v_provider_message_id is not null
       and char_length(v_provider_message_id) > 320
     ) then
    raise exception 'invalid_notification_delivery_result'
      using errcode = '22023';
  end if;

  -- The unlocked read only discovers immutable lock scope. Payment delivery
  -- uses lifecycle -> provider -> financial attempt -> queue; all predicates
  -- are checked again after those locks are held.
  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id;

  if found
     and private.canonical_payment_notification_kind(
       v_notification.notification_kind
     ) = 'PAYMENT_CONFIRMED_WHATSAPP'
     and upper(pg_catalog.btrim(coalesce(
       v_notification.source_type,
       ''
     ))) = 'ASAAS_PAYMENT' then
    select outbound.*
    into v_financial_outbound
    from public.asaas_outbound_message_attempts as outbound
    where outbound.notification_queue_id = v_notification.id
       or (
         outbound.notification_queue_id is null
         and outbound.tenant_id = v_notification.tenant_id
         and outbound.student_id = v_notification.student_id
         and outbound.provider_entity_id = v_notification.source_id::text
         and upper(pg_catalog.btrim(coalesce(
           outbound.notification_kind,
           ''
         ))) = 'PAYMENT_CONFIRMED_WHATSAPP'
       )
    order by (outbound.notification_queue_id = v_notification.id) desc
    limit 1;

    if found then
      perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'student-billing-lifecycle:' || v_financial_outbound.tenant_id ||
          ':' || v_financial_outbound.student_id::text,
          0
        )
      );
    end if;
  end if;

  if v_notification.id is not null
     and v_provider_message_id is not null
     and v_notification.provider_instance_name is not null then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'notification-provider:' || v_notification.tenant_id || ':' ||
        lower(v_notification.provider_instance_name) || ':' ||
        v_provider_message_id,
        0
      )
    );
  end if;

  if v_financial_outbound.id is not null then
    select outbound.*
    into v_financial_outbound
    from public.asaas_outbound_message_attempts as outbound
    where outbound.id = v_financial_outbound.id
    for update;
  end if;

  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id
  for update;

  if not found
     or v_notification.claim_token is distinct from p_claim_token
     or v_notification.status <> 'processing'
     or v_notification.delivery_status not in ('preparing', 'submitting') then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'notification_delivery_claim_lost'
    );
  end if;

  v_was_preparing := v_notification.delivery_status = 'preparing';

  if v_outcome in ('accepted', 'sent', 'delivered', 'read') then
    if v_notification.delivery_status <> 'submitting'
       or v_notification.provider_instance_name is null
       or v_provider_message_id is null then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'provider_identity_required_after_submission'
      );
    end if;

    update public.notification_queue as notification
    set status = 'sent',
        delivery_status = private.merge_notification_delivery_status(
          notification.delivery_status,
          v_outcome
        ),
        provider_message_id = coalesce(
          notification.provider_message_id,
          v_provider_message_id
        ),
        provider_http_status = p_provider_http_status,
        accepted_at = coalesce(notification.accepted_at, now()),
        sent_at = case
          when v_outcome in ('sent', 'delivered', 'read')
            then coalesce(notification.sent_at, now())
          else notification.sent_at
        end,
        delivered_at = case
          when v_outcome in ('delivered', 'read')
            then coalesce(notification.delivered_at, now())
          else notification.delivered_at
        end,
        read_at = case
          when v_outcome = 'read' then coalesce(notification.read_at, now())
          else notification.read_at
        end,
        dead_letter_at = null,
        last_error = null,
        claim_token = null,
        lease_expires_at = null,
        updated_at = now()
    where notification.id = v_notification.id
      and (
        notification.provider_message_id is null
        or notification.provider_message_id = v_provider_message_id
      )
    returning notification.* into v_notification;

    if not found then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'provider_message_id_conflict'
      );
    end if;

    v_reconcile := public.reconcile_whatsapp_provider_delivery(
      v_notification.tenant_id,
      v_notification.provider_instance_name,
      v_provider_message_id,
      v_outcome,
      now()
    );

    select notification.*
    into strict v_notification
    from public.notification_queue as notification
    where notification.id = p_notification_id;

    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'FINALIZED',
      'notificationId', v_notification.id,
      'status', v_notification.status,
      'deliveryStatus', v_notification.delivery_status,
      'providerMessageId', v_notification.provider_message_id,
      'reconciled', coalesce((v_reconcile ->> 'ok')::boolean, false)
    );
  end if;

  if v_outcome = 'failed'
     and v_retry_delay > 0
     and v_notification.delivery_status = 'preparing'
     and v_notification.attempts < v_notification.max_attempts then
    update public.notification_queue as notification
    set status = 'pending',
        delivery_status = 'queued',
        next_attempt_at = now() + pg_catalog.make_interval(
          secs => v_retry_delay
        ),
        provider_message_id = null,
        provider_http_status = p_provider_http_status,
        accepted_at = null,
        sent_at = null,
        delivered_at = null,
        read_at = null,
        dead_letter_at = null,
        last_error = coalesce(v_error, 'notification_delivery_retry_scheduled'),
        claim_token = null,
        lease_expires_at = null,
        updated_at = now()
    where notification.id = v_notification.id
    returning notification.* into v_notification;

    -- No provider boundary was crossed. Release the financial CLAIMED fence so
    -- a later queue retry can acquire a fresh submit-once claim and lifecycle
    -- operations are not blocked by an expired operational lease forever.
    if v_financial_outbound.id is not null then
      delete from public.asaas_outbound_message_attempts as outbound
      where outbound.id = v_financial_outbound.id
        and outbound.status = 'CLAIMED'
        and outbound.submit_attempt_count = 0
        and outbound.notification_queue_id is null
        and outbound.tenant_id = v_notification.tenant_id
        and outbound.student_id = v_notification.student_id
        and outbound.provider_entity_id = v_notification.source_id::text
        and upper(pg_catalog.btrim(coalesce(
          outbound.notification_kind,
          ''
        ))) = 'PAYMENT_CONFIRMED_WHATSAPP';
    end if;

    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'RETRY_SCHEDULED',
      'notificationId', v_notification.id,
      'status', v_notification.status,
      'deliveryStatus', v_notification.delivery_status,
      'nextAttemptAt', v_notification.next_attempt_at
    );
  end if;

  update public.notification_queue as notification
  set status = case when v_outcome = 'skipped' then 'skipped' else 'failed' end,
      delivery_status = case
        when v_outcome = 'skipped' then 'skipped'
        when v_outcome = 'uncertain' then 'uncertain'
        else 'failed'
      end,
      provider_message_id = coalesce(
        notification.provider_message_id,
        v_provider_message_id
      ),
      provider_http_status = p_provider_http_status,
      dead_letter_at = case
        when v_outcome = 'skipped' then null
        else coalesce(notification.dead_letter_at, now())
      end,
      last_error = coalesce(
        v_error,
        case
          when v_outcome = 'uncertain' then 'notification_delivery_uncertain'
          when v_outcome = 'skipped' then 'notification_delivery_skipped'
          when notification.attempts >= notification.max_attempts
            then 'notification_delivery_attempts_exhausted'
          else 'notification_delivery_failed'
        end
      ),
      claim_token = null,
      lease_expires_at = null,
      updated_at = now()
  where notification.id = v_notification.id
  returning notification.* into v_notification;

  -- Exhaustion before POST is definitive and safe to suppress. Retaining the
  -- terminal identity prevents a later producer from sending the same payment
  -- confirmation through a new queue row.
  if v_was_preparing
     and v_outcome = 'failed'
     and v_financial_outbound.id is not null then
    update public.asaas_outbound_message_attempts as outbound
    set notification_queue_id = v_notification.id,
        status = 'SUPPRESSED',
        lease_expires_at = now(),
        last_error = coalesce(
          v_error,
          'payment_confirmation_delivery_attempts_exhausted'
        ),
        updated_at = now()
    where outbound.id = v_financial_outbound.id
      and outbound.status = 'CLAIMED'
      and outbound.submit_attempt_count = 0
      and outbound.tenant_id = v_notification.tenant_id
      and outbound.student_id = v_notification.student_id
      and outbound.provider_entity_id = v_notification.source_id::text
      and upper(pg_catalog.btrim(coalesce(
        outbound.notification_kind,
        ''
      ))) = 'PAYMENT_CONFIRMED_WHATSAPP';
  end if;

  if v_provider_message_id is not null
     and v_notification.provider_instance_name is not null
     and v_outcome in ('failed', 'uncertain') then
    perform public.reconcile_whatsapp_provider_delivery(
      v_notification.tenant_id,
      v_notification.provider_instance_name,
      v_provider_message_id,
      v_outcome,
      now()
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'TERMINAL',
    'notificationId', v_notification.id,
    'status', v_notification.status,
    'deliveryStatus', v_notification.delivery_status,
    'deadLetterAt', v_notification.dead_letter_at
  );
end;
$$;


--
-- Name: finalize_payment_confirmation_delivery(uuid, uuid, uuid, uuid, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_payment_confirmation_delivery(p_notification_id uuid, p_notification_claim_token uuid, p_outbound_attempt_id uuid, p_outbound_claim_token uuid, p_outcome text, p_provider_message_id text, p_provider_http_status integer, p_error text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_notification public.notification_queue%rowtype;
  v_outbound public.asaas_outbound_message_attempts%rowtype;
  v_outcome text := lower(pg_catalog.btrim(coalesce(p_outcome, '')));
  v_provider_message_id text := nullif(
    pg_catalog.btrim(coalesce(p_provider_message_id, '')),
    ''
  );
  v_error text := nullif(
    pg_catalog.left(pg_catalog.btrim(coalesce(p_error, '')), 500),
    ''
  );
  v_financial_status text;
  v_queue_result jsonb;
begin
  if p_notification_id is null
     or p_notification_claim_token is null
     or p_outbound_attempt_id is null
     or p_outbound_claim_token is null
     or v_outcome not in (
       'accepted', 'sent', 'delivered', 'read', 'failed', 'uncertain'
     )
     or (
       p_provider_http_status is not null
       and p_provider_http_status not between 100 and 599
     )
     or (
       v_provider_message_id is not null
       and char_length(v_provider_message_id) > 320
     ) then
    raise exception 'invalid_payment_confirmation_delivery_result'
      using errcode = '22023';
  end if;

  select outbound.*
  into v_outbound
  from public.asaas_outbound_message_attempts as outbound
  where outbound.id = p_outbound_attempt_id;

  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id;

  if v_outbound.id is null or v_notification.id is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'claim_lost'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || v_outbound.tenant_id || ':' ||
      v_outbound.student_id::text,
      0
    )
  );

  if v_provider_message_id is not null
     and v_outbound.provider_instance_name is not null then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'notification-provider:' || v_outbound.tenant_id || ':' ||
        lower(v_outbound.provider_instance_name) || ':' ||
        v_provider_message_id,
        0
      )
    );
  end if;

  select outbound.*
  into v_outbound
  from public.asaas_outbound_message_attempts as outbound
  where outbound.id = p_outbound_attempt_id
  for update;

  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id
  for update;

  if v_outbound.id is null
     or v_notification.id is null
     or v_outbound.status <> 'SUBMITTING'
     or v_outbound.submit_attempt_count <> 1
     or v_outbound.claim_token is distinct from p_outbound_claim_token
     or v_notification.status <> 'processing'
     or v_notification.delivery_status <> 'submitting'
     or v_notification.claim_token is distinct from
       p_notification_claim_token then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', 'claim_lost'
    );
  end if;

  if v_outbound.notification_queue_id is distinct from v_notification.id
     or v_outbound.tenant_id is distinct from v_notification.tenant_id
     or v_outbound.student_id is distinct from v_notification.student_id
     or v_notification.source_id is null
     or v_outbound.provider_entity_id is distinct from
       v_notification.source_id::text
     or upper(pg_catalog.btrim(coalesce(
       v_notification.source_type,
       ''
     ))) <> 'ASAAS_PAYMENT'
     or upper(pg_catalog.btrim(coalesce(
       v_outbound.notification_kind,
       ''
     ))) <> 'PAYMENT_CONFIRMED_WHATSAPP'
     or private.canonical_payment_notification_kind(
       v_notification.notification_kind
     ) <> 'PAYMENT_CONFIRMED_WHATSAPP'
     or v_notification.provider_instance_name is null
     or v_outbound.provider_instance_name is null
     or lower(v_outbound.provider_instance_name) <>
       lower(v_notification.provider_instance_name)
     or v_notification.provider_destination is null
     or v_outbound.provider_destination is null
     or v_outbound.provider_destination is distinct from
       v_notification.provider_destination
     or v_notification.provider_integration_id is null
     or v_notification.provider_integration_version is null
     or (
       v_outbound.provider_message_id is not null
       and v_outbound.provider_message_id is distinct from
         v_provider_message_id
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'payment_confirmation_binding_mismatch'
    );
  end if;

  v_financial_status := case
    when v_outcome in ('accepted', 'sent', 'delivered', 'read') then 'SENT'
    when v_outcome = 'failed' then 'FAILED'
    else 'UNKNOWN'
  end;

  v_queue_result := public.finalize_notification_delivery(
    v_notification.id,
    p_notification_claim_token,
    v_outcome,
    v_provider_message_id,
    p_provider_http_status,
    v_error,
    0
  );

  if coalesce((v_queue_result ->> 'ok')::boolean, false) is not true then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY',
      'reason', coalesce(
        v_queue_result ->> 'reason',
        'notification_delivery_finalize_failed'
      )
    );
  end if;

  -- A provider identity causes the generic finalizer to write the receipt and
  -- reconcile the linked financial row inside this same transaction. Accept
  -- that already-terminal state; without a provider id (FAILED/UNCERTAIN), this
  -- statement performs the sole SUBMITTING -> terminal transition. Either path
  -- still requires the original financial claim token and submit-once count.
  update public.asaas_outbound_message_attempts as outbound
  set provider_message_id = coalesce(
        outbound.provider_message_id,
        v_provider_message_id
      ),
      provider_delivery_status = case
        when outbound.status = 'SUBMITTING' then v_outcome
        else outbound.provider_delivery_status
      end,
      status = case
        when outbound.status = 'SUBMITTING' then v_financial_status
        else outbound.status
      end,
      provider_http_status = coalesce(
        p_provider_http_status,
        outbound.provider_http_status
      ),
      last_error = case
        when outbound.status <> 'SUBMITTING' then outbound.last_error
        when v_financial_status = 'SENT' then null
        else coalesce(
          v_error,
          case
            when v_financial_status = 'UNKNOWN'
              then 'notification_delivery_uncertain'
            else 'notification_delivery_failed'
          end
        )
      end,
      lease_expires_at = now(),
      updated_at = now()
  where outbound.id = v_outbound.id
    and outbound.status in ('SUBMITTING', 'SENT', 'FAILED', 'UNKNOWN')
    and outbound.claim_token = p_outbound_claim_token
    and outbound.submit_attempt_count = 1
    and (
      outbound.provider_message_id is null
      or outbound.provider_message_id = v_provider_message_id
    )
  returning outbound.* into v_outbound;

  if not found then
    raise exception 'payment_confirmation_ledger_finalize_failed';
  end if;

  select notification.*
  into strict v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'FINALIZED',
    'status', v_notification.status,
    'deliveryStatus', v_notification.delivery_status,
    'financialStatus', v_outbound.status,
    'providerMessageId', v_outbound.provider_message_id,
    'notificationId', v_notification.id,
    'outboundAttemptId', v_outbound.id
  );
end;
$$;


--
-- Name: finalize_student_account_deletion(uuid, uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_student_account_deletion(p_claim_id uuid, p_claim_token uuid, p_profile_absent boolean, p_auth_absent boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  claim_tenant_id text;
  claim_student_id uuid;
  changed_id uuid;
begin
  if p_profile_absent is not true or p_auth_absent is not true then
    return jsonb_build_object('ok', false, 'reason', 'local_deletion_unverified');
  end if;

  -- Resolve the immutable lock identity without holding a row lock, then take
  -- the lifecycle advisory before the claim row. This matches every begin/apply
  -- path and avoids operation-row/advisory lock inversion.
  select deletion.tenant_id, deletion.student_id
    into claim_tenant_id, claim_student_id
    from public.student_account_deletion_claims as deletion
   where deletion.id = p_claim_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || claim_tenant_id || ':' || claim_student_id::text,
      0
    )
  );

  update public.student_account_deletion_claims
     set status = 'COMPLETED', completed_at = now(), lease_expires_at = now(), updated_at = now()
   where id = p_claim_id
     and tenant_id = claim_tenant_id
     and student_id = claim_student_id
     and claim_token = p_claim_token
     and status = 'PROVIDER_COMPLETE'
     and subscription_deleted
     and customer_deleted
   returning id into changed_id;
  return jsonb_build_object('ok', changed_id is not null, 'reason', case when changed_id is null then 'claim_lost' else null end);
end;
$$;


--
-- Name: finalize_student_offboarding(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_student_offboarding(p_operation_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.student_offboarding_operations%rowtype;
  operation_tenant_id text;
  operation_student_id uuid;
  updated_profile_id uuid;
  cancelled_count integer := 0;
begin
  -- Take the lifecycle advisory before locking the operation row. `begin` and
  -- the active webhook RPC use this same order, preventing both the race and a
  -- row/advisory deadlock.
  select operation.tenant_id, operation.student_id
    into operation_tenant_id, operation_student_id
    from public.student_offboarding_operations as operation
   where operation.id = p_operation_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || operation_tenant_id || ':' || operation_student_id::text,
      0
    )
  );

  select operation.* into operation_row
    from public.student_offboarding_operations as operation
   where operation.id = p_operation_id
   for update;
  if not found
     or operation_row.tenant_id is distinct from operation_tenant_id
     or operation_row.student_id is distinct from operation_student_id
     or operation_row.claim_token is distinct from p_claim_token
     or operation_row.status <> 'PROVIDER_COMPLETE'
  then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  if (
    select count(*) from public.tenant_memberships as membership
     where membership.user_id = operation_row.student_id
  ) <> 1 or not exists (
    select 1 from public.tenant_memberships as membership
     where membership.user_id = operation_row.student_id
       and membership.tenant_id = operation_row.tenant_id
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    update public.student_offboarding_operations
       set status = 'BLOCKED', last_error = 'membership_scope_changed_before_finalize', updated_at = now()
     where id = operation_row.id;
    return jsonb_build_object('ok', false, 'reason', 'membership_scope_changed');
  end if;

  if exists (
    select 1
      from jsonb_array_elements(operation_row.payment_snapshot) as entry
      left join public.student_payments as payment
        on payment.id = (entry ->> 'id')::uuid
       and payment.tenant_id = operation_row.tenant_id
       and payment.student_id = operation_row.student_id
     where payment.id is null
        or coalesce(
             nullif(trim(coalesce(payment.asaas_payment_id, '')), ''),
             nullif(trim(coalesce(payment.asaas_id, '')), '')
           ) is distinct from nullif(entry ->> 'asaas_payment_id', '')
        or payment.due_date is distinct from (entry ->> 'due_date')::date
  ) or (
    operation_row.target_lifecycle_status = 'offboarded'
    and exists (
      select 1
        from public.student_payments as payment
       where payment.tenant_id = operation_row.tenant_id
         and payment.student_id = operation_row.student_id
         and upper(coalesce(payment.status, '')) = 'PENDING'
         and payment.due_date >= current_date
         and not exists (
           select 1
             from jsonb_array_elements(operation_row.payment_snapshot) as entry
            where (entry ->> 'id')::uuid = payment.id
         )
    )
  ) then
    update public.student_offboarding_operations
       set status = 'BLOCKED', last_error = 'payment_snapshot_changed_before_finalize', updated_at = now()
     where id = operation_row.id;
    return jsonb_build_object('ok', false, 'reason', 'payment_snapshot_changed');
  end if;

  update public.profiles as profile
     set lifecycle_status = operation_row.target_lifecycle_status,
         suspended_at = case when operation_row.target_lifecycle_status = 'suspended' then now() else null end,
         suspended_reason = case when operation_row.target_lifecycle_status = 'suspended' then operation_row.reason else null end,
         offboarding_status = case when operation_row.target_lifecycle_status = 'offboarded' then 'COMPLETED' else null end,
         offboarding_completed_at = case when operation_row.target_lifecycle_status = 'offboarded' then now() else null end,
         offboarding_reason = case when operation_row.target_lifecycle_status = 'offboarded' then operation_row.reason else null end
   where profile.id = operation_row.student_id
     and profile.tenant_id = operation_row.tenant_id
     and profile.role = 'STUDENT'
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = operation_row.source_lifecycle_status
     and nullif(trim(coalesce(profile.asaas_customer_id, '')), '') is not distinct from operation_row.customer_id
     and nullif(trim(coalesce(profile.subscription_id, '')), '') is not distinct from operation_row.subscription_id
     and nullif(trim(coalesce(profile.enrollment_payment_id, '')), '') is not distinct from operation_row.enrollment_payment_id
   returning profile.id into updated_profile_id;
  if updated_profile_id is null then
    update public.student_offboarding_operations
       set status = 'BLOCKED', last_error = 'profile_binding_changed_before_finalize', updated_at = now()
     where id = operation_row.id;
    return jsonb_build_object('ok', false, 'reason', 'profile_binding_changed');
  end if;

  if operation_row.target_lifecycle_status = 'offboarded' then
    with snapshot_ids as (
      select (entry ->> 'id')::uuid as id
        from jsonb_array_elements(operation_row.payment_snapshot) as entry
       where entry ? 'id'
    ), cancelled as (
      update public.student_payments as payment
         set status = 'CANCELLED', updated_at = now()
       where payment.id in (select id from snapshot_ids)
         and payment.tenant_id = operation_row.tenant_id
         and payment.student_id = operation_row.student_id
         and upper(coalesce(payment.status, '')) = 'PENDING'
       returning payment.id
    )
    select count(*) into cancelled_count from cancelled;
  end if;

  update public.student_offboarding_operations
     set status = 'COMPLETED', completed_at = now(), lease_expires_at = now(), updated_at = now()
   where id = operation_row.id;

  return jsonb_build_object(
    'ok', true,
    'action', 'COMPLETED',
    'future_payments_cancelled', cancelled_count
  );
end;
$$;


--
-- Name: finalize_student_offboarding_pre_schedule_notification_impl(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_student_offboarding_pre_schedule_notification_impl(p_operation_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.student_offboarding_operations%rowtype;
  operation_tenant_id text;
  operation_student_id uuid;
  updated_profile_id uuid;
  cancelled_count integer := 0;
  exempted_count integer := 0;
  schedules_cancelled integer := 0;
begin
  select operation.tenant_id, operation.student_id
    into operation_tenant_id, operation_student_id
    from public.student_offboarding_operations as operation
   where operation.id = p_operation_id;
  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || operation_tenant_id || ':' ||
        operation_student_id::text,
      0
    )
  );

  select operation.* into operation_row
    from public.student_offboarding_operations as operation
   where operation.id = p_operation_id
   for update;
  if not found
     or operation_row.tenant_id is distinct from operation_tenant_id
     or operation_row.student_id is distinct from operation_student_id
     or operation_row.claim_token is distinct from p_claim_token
     or operation_row.status <> 'PROVIDER_COMPLETE'
     or operation_row.target_lifecycle_status not in ('suspended', 'offboarded')
     or operation_row.billing_policy is null
     or operation_row.billing_period_start is null
     or operation_row.effective_end_date is null
     or operation_row.provider_subscription_final_status is distinct from (
       case
         when operation_row.target_lifecycle_status = 'suspended'
           then 'INACTIVE'
         when operation_row.billing_policy = 'WAIVE_CURRENT_MONTH'
           then 'NOT_FOUND'
         else 'INACTIVE'
       end
     )
     or (
       operation_row.billing_policy = 'CHARGE_CURRENT_MONTH'
       and pg_catalog.jsonb_array_length(
         operation_row.preserved_payment_snapshot
       ) <> 1
     )
     or (
       operation_row.billing_policy <> 'CHARGE_CURRENT_MONTH'
       and pg_catalog.jsonb_array_length(
         operation_row.preserved_payment_snapshot
       ) <> 0
     )
     or (
       operation_row.target_lifecycle_status = 'offboarded'
       and (
         operation_row.billing_policy not in (
           'CHARGE_CURRENT_MONTH', 'WAIVE_CURRENT_MONTH'
         )
         or operation_row.billing_cancel_from_date is null
       )
     )
  then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  if (
    select pg_catalog.count(*)
      from public.tenant_memberships as membership
     where membership.user_id = operation_row.student_id
  ) <> 1 or not exists (
    select 1
      from public.tenant_memberships as membership
     where membership.user_id = operation_row.student_id
       and membership.tenant_id = operation_row.tenant_id
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'membership_scope_changed_before_finalize',
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'membership_scope_changed'
    );
  end if;

  -- CHARGE_CURRENT_MONTH owns two disjoint snapshots: future open invoices to
  -- cancel and the single current-competence invoice to preserve. Revalidate
  -- the preserved row separately so it can never enter the cancellation CTE.
  if operation_row.billing_policy = 'CHARGE_CURRENT_MONTH' and (
    exists (
      select 1
        from pg_catalog.jsonb_array_elements(
          operation_row.preserved_payment_snapshot
        ) as entry
        left join public.student_payments as payment
          on payment.id = (entry ->> 'id')::uuid
         and payment.tenant_id = operation_row.tenant_id
         and payment.student_id = operation_row.student_id
       where payment.id is null
          or payment.payment_type is distinct from 'SUBSCRIPTION'
          or (
            nullif(
              pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), ''
            ) is not null
            and nullif(
              pg_catalog.btrim(coalesce(payment.asaas_id, '')), ''
            ) is not null
            and pg_catalog.btrim(payment.asaas_payment_id) <>
              pg_catalog.btrim(payment.asaas_id)
          )
          or coalesce(
               nullif(
                 pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), ''
               ),
               nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '')
             ) is distinct from nullif(entry ->> 'asaas_payment_id', '')
          or payment.due_date is distinct from (entry ->> 'due_date')::date
          or payment.due_date < operation_row.billing_period_start
          or payment.due_date >=
            (operation_row.billing_period_start + interval '1 month')::date
          or pg_catalog.round(coalesce(payment.value, 0), 2) is distinct from
             pg_catalog.round((entry ->> 'value')::numeric, 2)
          or upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
               'CANCELLED', 'DELETED', 'REFUNDED', 'REVERSED'
             )
    ) or exists (
      select 1
        from public.student_payments as payment
       where payment.tenant_id = operation_row.tenant_id
         and payment.student_id = operation_row.student_id
         and payment.payment_type = 'SUBSCRIPTION'
         and payment.due_date >= operation_row.billing_period_start
         and payment.due_date <
           (operation_row.billing_period_start + interval '1 month')::date
         and upper(pg_catalog.btrim(coalesce(payment.status, ''))) not in (
           'CANCELLED', 'DELETED', 'REFUNDED', 'REVERSED'
         )
         and not exists (
           select 1
             from pg_catalog.jsonb_array_elements(
               operation_row.preserved_payment_snapshot
             ) as entry
            where (entry ->> 'id')::uuid = payment.id
         )
    )
  ) then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'preserved_payment_snapshot_changed_before_finalize',
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'preserved_payment_snapshot_changed'
    );
  end if;

  if exists (
    select 1
      from pg_catalog.jsonb_array_elements(operation_row.payment_snapshot) as entry
      left join public.student_payments as payment
        on payment.id = (entry ->> 'id')::uuid
       and payment.tenant_id = operation_row.tenant_id
       and payment.student_id = operation_row.student_id
     where payment.id is null
        or coalesce(
             nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), ''),
             nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '')
           ) is distinct from nullif(entry ->> 'asaas_payment_id', '')
        or payment.due_date is distinct from (entry ->> 'due_date')::date
        or pg_catalog.round(coalesce(payment.value, 0), 2) is distinct from
           pg_catalog.round((entry ->> 'value')::numeric, 2)
        or upper(pg_catalog.btrim(coalesce(payment.status, ''))) not in (
             'PENDING', 'OVERDUE', 'CANCELLED'
           )
  ) or (
    operation_row.target_lifecycle_status = 'offboarded'
    and exists (
      select 1
        from public.student_payments as payment
       where payment.tenant_id = operation_row.tenant_id
         and payment.student_id = operation_row.student_id
         and payment.payment_type = 'SUBSCRIPTION'
         and upper(pg_catalog.btrim(coalesce(payment.status, ''))) <>
           'CANCELLED'
         and payment.due_date >= operation_row.billing_cancel_from_date
         and not exists (
           select 1
             from pg_catalog.jsonb_array_elements(
               operation_row.payment_snapshot
             ) as entry
            where (entry ->> 'id')::uuid = payment.id
         )
    )
  ) then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'payment_snapshot_changed_before_finalize',
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'payment_snapshot_changed'
    );
  end if;

  if operation_row.target_lifecycle_status = 'offboarded'
     and exists (
       select 1
         from public.monthly_payment_obligations as obligation
        where obligation.tenant_id = operation_row.tenant_id
          and obligation.student_id = operation_row.student_id
          and obligation.period_start >= operation_row.billing_cancel_from_date
          and (
            coalesce(obligation.settled_amount, 0) > 0
            or upper(pg_catalog.btrim(coalesce(obligation.status, ''))) in (
              'SETTLED', 'PAID', 'RECEIVED'
            )
          )
     )
  then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'settled_obligation_in_cancellation_period',
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'settled_obligation_in_cancellation_period'
    );
  end if;

  -- A waiver is not an implicit refund. If Asaas settled/confirmed the current
  -- competence while the operation was in flight, stop for human review.
  if operation_row.billing_policy = 'WAIVE_CURRENT_MONTH'
     and exists (
       select 1
         from public.student_payments as payment
        where payment.tenant_id = operation_row.tenant_id
          and payment.student_id = operation_row.student_id
          and payment.payment_type = 'SUBSCRIPTION'
          and payment.due_date >= operation_row.billing_period_start
          and payment.due_date <
            (operation_row.billing_period_start + interval '1 month')::date
          and upper(pg_catalog.btrim(coalesce(payment.status, ''))) not in (
            'PENDING', 'OVERDUE', 'CANCELLED', 'NAO_RECEITA'
          )
     )
  then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'current_period_not_waivable',
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'current_period_not_waivable'
    );
  end if;

  perform pg_catalog.set_config(
    'app.student_lifecycle_finalizer', operation_row.id::text, true
  );
  update public.profiles as profile
     set status = 'Inativo',
         lifecycle_status = operation_row.target_lifecycle_status,
         subscription_id = case
           when operation_row.target_lifecycle_status = 'offboarded'
             and operation_row.billing_policy = 'WAIVE_CURRENT_MONTH'
             then null
           else profile.subscription_id
         end,
         asaas_subscription_status =
           operation_row.provider_subscription_final_status,
         asaas_subscription_synced_at = pg_catalog.now(),
         suspended_at = case
           when operation_row.target_lifecycle_status = 'suspended'
             then pg_catalog.now()
           else null
         end,
         suspended_reason = case
           when operation_row.target_lifecycle_status = 'suspended'
             then operation_row.reason
           else null
         end,
         offboarding_status = case
           when operation_row.target_lifecycle_status = 'offboarded'
             then 'COMPLETED'
           else null
         end,
         offboarding_completed_at = case
           when operation_row.target_lifecycle_status = 'offboarded'
             then pg_catalog.now()
           else null
         end,
         offboarding_reason = case
           when operation_row.target_lifecycle_status = 'offboarded'
             then operation_row.reason
           else null
         end,
         offboarding_last_day = case
           when operation_row.target_lifecycle_status = 'offboarded'
             then operation_row.effective_end_date
           else null
         end
   where profile.id = operation_row.student_id
     and profile.tenant_id = operation_row.tenant_id
     and profile.role = 'STUDENT'
     and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) =
       operation_row.source_lifecycle_status
     and nullif(pg_catalog.btrim(coalesce(profile.asaas_customer_id, '')), '')
       is not distinct from operation_row.customer_id
     and nullif(pg_catalog.btrim(coalesce(profile.subscription_id, '')), '')
       is not distinct from operation_row.subscription_id
     and nullif(pg_catalog.btrim(coalesce(profile.enrollment_payment_id, '')), '')
       is not distinct from operation_row.enrollment_payment_id
   returning profile.id into updated_profile_id;
  if updated_profile_id is null then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'profile_binding_changed_before_finalize',
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'profile_binding_changed'
    );
  end if;

  if operation_row.target_lifecycle_status = 'offboarded' then
    with cancelled_bookings as (
      update public.bookings as booking
         set status = 'CANCELLED'
       where booking.tenant_id = operation_row.tenant_id
         and booking.student_id = operation_row.student_id
         and upper(pg_catalog.btrim(coalesce(booking.status, ''))) = 'SCHEDULED'
       returning booking.id
    )
    select pg_catalog.count(*) into schedules_cancelled
      from cancelled_bookings;

    with snapshot_ids as (
      select (entry ->> 'id')::uuid as id
        from pg_catalog.jsonb_array_elements(
          operation_row.payment_snapshot
        ) as entry
       where entry ? 'id'
    ), cancelled as (
      update public.student_payments as payment
         set status = 'CANCELLED', updated_at = pg_catalog.now()
       where payment.id in (select id from snapshot_ids)
         and payment.tenant_id = operation_row.tenant_id
         and payment.student_id = operation_row.student_id
         and upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
           'PENDING', 'OVERDUE'
         )
       returning payment.id
    )
    select pg_catalog.count(*) into cancelled_count from cancelled;

    insert into public.student_billing_exemptions (
      tenant_id,
      student_id,
      period_start,
      reason,
      offboarding_operation_id,
      created_by
    )
    select distinct
      operation_row.tenant_id,
      operation_row.student_id,
      period.period_start,
      'OFFBOARDING_CANCELLED',
      operation_row.id,
      operation_row.requested_by
    from (
      select pg_catalog.date_trunc(
        'month',
        (entry ->> 'due_date')::date
      )::date as period_start
      from pg_catalog.jsonb_array_elements(
        operation_row.payment_snapshot
      ) as entry
      union all
      select obligation.period_start
        from public.monthly_payment_obligations as obligation
       where obligation.tenant_id = operation_row.tenant_id
         and obligation.student_id = operation_row.student_id
         and obligation.period_start >= operation_row.billing_cancel_from_date
      union all
      select series.period_start::date
        from pg_catalog.generate_series(
          operation_row.billing_cancel_from_date::timestamptz,
          greatest(
            operation_row.billing_cancel_from_date,
            pg_catalog.date_trunc(
              'month',
              pg_catalog.now() at time zone 'America/Sao_Paulo'
            )::date
          )::timestamptz,
          interval '1 month'
        ) as series(period_start)
    ) as period
    on conflict (tenant_id, student_id, period_start) do nothing;
    get diagnostics exempted_count = row_count;

    update public.monthly_payment_obligations as obligation
       set status = 'EXCLUDED',
           payment_ids = '{}',
           billed_amount = 0,
           settled_amount = 0,
           details = coalesce(obligation.details, '{}'::jsonb) ||
             pg_catalog.jsonb_build_object(
               'excluded_reason', 'OFFBOARDING_CANCELLED',
               'offboarding_operation_id', operation_row.id
             ),
           updated_at = pg_catalog.now()
     where obligation.tenant_id = operation_row.tenant_id
       and obligation.student_id = operation_row.student_id
       and exists (
         select 1
           from public.student_billing_exemptions as exemption
          where exemption.tenant_id = obligation.tenant_id
            and exemption.student_id = obligation.student_id
            and exemption.period_start = obligation.period_start
       );
  end if;

  update public.student_offboarding_operations
     set status = 'COMPLETED',
         completed_at = pg_catalog.now(),
         lease_expires_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where id = operation_row.id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'COMPLETED',
    'billing_policy', operation_row.billing_policy,
    'billing_period_start', operation_row.billing_period_start,
    'effective_end_date', operation_row.effective_end_date,
    'provider_subscription_final_status',
      operation_row.provider_subscription_final_status,
    'payments_cancelled', cancelled_count,
    'billing_periods_exempted', exempted_count,
    'schedules_cancelled', schedules_cancelled
  );
end;
$$;


--
-- Name: finalize_student_offboarding_with_billing_policy(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_student_offboarding_with_billing_policy(p_operation_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.student_offboarding_operations%rowtype;
  operation_tenant_id text;
  operation_student_id uuid;
  base_result jsonb;
  released_teacher_ids jsonb := '[]'::jsonb;
  newly_cancelled_schedules integer := 0;
  schedules_cancelled integer := 0;
  newly_cancelled_payments integer := 0;
  student_notification_enabled boolean := false;
  teacher_notification_enabled boolean := false;
  student_row public.profiles%rowtype;
  tenant_name text;
  student_destination text;
  student_kind text;
  teacher_kind text;
  student_message text;
  teacher_message text;
  teacher_row record;
  notifications_queued integer := 0;
  inserted_count integer := 0;
  completed_result jsonb;
  final_result jsonb;
begin
  select operation.tenant_id, operation.student_id
    into operation_tenant_id, operation_student_id
    from public.student_offboarding_operations as operation
   where operation.id = p_operation_id;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'claim_lost'
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || operation_tenant_id || ':' ||
        operation_student_id::text,
      0
    )
  );

  select operation.*
    into operation_row
    from public.student_offboarding_operations as operation
   where operation.id = p_operation_id
   for update;
  if not found
     or operation_row.tenant_id is distinct from operation_tenant_id
     or operation_row.student_id is distinct from operation_student_id
     or operation_row.claim_token is distinct from p_claim_token
     or operation_row.target_lifecycle_status not in (
       'suspended', 'offboarded'
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'claim_lost'
    );
  end if;

  if operation_row.status = 'COMPLETED' then
    completed_result := operation_row.snapshot ->
      'student_lifecycle_finalize_result';
    if pg_catalog.jsonb_typeof(completed_result) = 'object' then
      return completed_result || pg_catalog.jsonb_build_object(
        'ok', true,
        'action', 'ALREADY_COMPLETED'
      );
    end if;

    -- Operations completed before this migration have no persisted response.
    -- Their provider/local mutation is still authoritative; derive only the
    -- non-financial counters that can be proven from the durable snapshot.
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'ALREADY_COMPLETED',
      'provider_subscription_final_status',
        operation_row.provider_subscription_final_status,
      'payments_cancelled', 0,
      'billing_periods_exempted', 0,
      'schedules_cancelled', coalesce(
        nullif(operation_row.snapshot ->> 'released_booking_count', '')::integer,
        0
      ),
      'released_teacher_ids', coalesce(
        operation_row.snapshot -> 'released_teacher_ids',
        '[]'::jsonb
      ),
      'notifications_queued', 0
    );
  end if;

  if operation_row.status <> 'PROVIDER_COMPLETE' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'claim_lost'
    );
  end if;

  if operation_row.target_lifecycle_status = 'suspended' then
    if operation_row.billing_policy is distinct from 'KEEP_OPEN_INVOICES'
       or operation_row.billing_period_start is null
       or operation_row.billing_cancel_from_date is distinct from
         (operation_row.billing_period_start + interval '1 month')::date
       or operation_row.effective_end_date is null
       or operation_row.provider_subscription_final_status is distinct from
         'INACTIVE'
       or operation_row.preserved_payment_snapshot is distinct from
         '[]'::jsonb
       or exists (
         select 1
           from pg_catalog.jsonb_array_elements(
             operation_row.payment_snapshot
           ) as entry
           left join public.student_payments as payment
             on payment.id = (entry ->> 'id')::uuid
            and payment.tenant_id = operation_row.tenant_id
            and payment.student_id = operation_row.student_id
          where payment.id is null
             or payment.payment_type is distinct from 'SUBSCRIPTION'
             or payment.due_date is distinct from
               (entry ->> 'due_date')::date
             or payment.due_date <
               operation_row.billing_cancel_from_date
             or pg_catalog.round(coalesce(payment.value, 0), 2)
                  is distinct from
                pg_catalog.round((entry ->> 'value')::numeric, 2)
             or coalesce(
                  nullif(pg_catalog.btrim(coalesce(
                    payment.asaas_payment_id,
                    ''
                  )), ''),
                  nullif(pg_catalog.btrim(coalesce(
                    payment.asaas_id,
                    ''
                  )), '')
                ) is distinct from
                nullif(entry ->> 'asaas_payment_id', '')
             or pg_catalog.upper(pg_catalog.btrim(coalesce(
                  payment.status,
                  ''
                ))) not in ('PENDING', 'OVERDUE', 'CANCELLED')
       )
       or exists (
         select 1
           from public.student_payments as payment
          where payment.tenant_id = operation_row.tenant_id
            and payment.student_id = operation_row.student_id
            and payment.payment_type = 'SUBSCRIPTION'
            and payment.due_date >=
              operation_row.billing_cancel_from_date
            and pg_catalog.upper(pg_catalog.btrim(coalesce(
                  payment.status,
                  ''
                ))) not in (
                  'CANCELLED', 'DELETED', 'REFUNDED', 'REVERSED',
                  'NAO_RECEITA'
                )
            and not exists (
              select 1
                from pg_catalog.jsonb_array_elements(
                  operation_row.payment_snapshot
                ) as entry
               where (entry ->> 'id')::uuid = payment.id
            )
       )
    then
      update public.student_offboarding_operations
         set status = 'BLOCKED',
             last_error =
               'suspension_payment_snapshot_changed_before_finalize',
             updated_at = pg_catalog.now()
       where id = operation_row.id;
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'suspension_payment_snapshot_changed'
      );
    end if;
  end if;

  -- Capture all teachers before the predecessor cancels offboarded bookings.
  -- The stable list is used both for one-notice-per-teacher idempotency and for
  -- send-time revalidation by the notification worker.
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(released.teacher_id)
      order by released.teacher_id
    ),
    '[]'::jsonb
  )
    into released_teacher_ids
    from (
      select distinct booking.teacher_id
        from public.bookings as booking
       where booking.tenant_id = operation_row.tenant_id
         and booking.student_id = operation_row.student_id
         and booking.teacher_id is not null
         and pg_catalog.upper(pg_catalog.btrim(coalesce(
               booking.status,
               ''
             ))) = 'SCHEDULED'
    ) as released;

  base_result :=
    public.finalize_student_offboarding_pre_schedule_notification_impl(
      p_operation_id,
      p_claim_token
    );
  if coalesce((base_result ->> 'ok')::boolean, false) is false
     or coalesce(base_result ->> 'action', '') <> 'COMPLETED'
  then
    return base_result;
  end if;

  with cancelled_bookings as (
    update public.bookings as booking
       set status = 'CANCELLED'
     where booking.tenant_id = operation_row.tenant_id
       and booking.student_id = operation_row.student_id
       and pg_catalog.upper(pg_catalog.btrim(coalesce(
             booking.status,
             ''
           ))) = 'SCHEDULED'
     returning booking.id
  )
  select pg_catalog.count(*)
    into newly_cancelled_schedules
    from cancelled_bookings;

  schedules_cancelled := coalesce(
    nullif(base_result ->> 'schedules_cancelled', '')::integer,
    0
  ) + newly_cancelled_schedules;

  if operation_row.target_lifecycle_status = 'suspended' then
    with snapshot_ids as (
      select (entry ->> 'id')::uuid as id
        from pg_catalog.jsonb_array_elements(
          operation_row.payment_snapshot
        ) as entry
       where entry ? 'id'
    ), cancelled as (
      update public.student_payments as payment
         set status = 'CANCELLED',
             updated_at = pg_catalog.now()
       where payment.id in (select id from snapshot_ids)
         and payment.tenant_id = operation_row.tenant_id
         and payment.student_id = operation_row.student_id
         and pg_catalog.upper(pg_catalog.btrim(coalesce(
               payment.status,
               ''
             ))) in ('PENDING', 'OVERDUE')
       returning payment.id
    )
    select pg_catalog.count(*)
      into newly_cancelled_payments
      from cancelled;

    if exists (
      select 1
        from pg_catalog.jsonb_array_elements(
          operation_row.payment_snapshot
        ) as entry
        left join public.student_payments as payment
          on payment.id = (entry ->> 'id')::uuid
         and payment.tenant_id = operation_row.tenant_id
         and payment.student_id = operation_row.student_id
       where payment.id is null
          or pg_catalog.upper(pg_catalog.btrim(coalesce(
               payment.status,
               ''
             ))) <> 'CANCELLED'
    ) then
      raise exception using
        errcode = '40001',
        message = 'suspension_local_payment_cancellation_incomplete';
    end if;
  end if;

  update public.student_offboarding_operations
     set snapshot = snapshot || pg_catalog.jsonb_build_object(
           'released_teacher_ids', released_teacher_ids,
           'released_booking_count', schedules_cancelled,
           'schedule_released_at', pg_catalog.now()
         ),
         updated_at = pg_catalog.now()
   where id = operation_row.id;

  select
    settings.student_notifications_enabled,
    settings.teacher_notifications_enabled
    into student_notification_enabled, teacher_notification_enabled
    from public.tenant_admin_settings as settings
   where settings.tenant_id = operation_row.tenant_id;
  student_notification_enabled := coalesce(
    student_notification_enabled,
    false
  );
  teacher_notification_enabled := coalesce(
    teacher_notification_enabled,
    false
  );

  select profile.*
    into student_row
    from public.profiles as profile
   where profile.id = operation_row.student_id
     and profile.tenant_id = operation_row.tenant_id
     and profile.role = 'STUDENT';
  select tenant.name
    into tenant_name
    from public.tenants as tenant
   where tenant.id = operation_row.tenant_id;

  student_kind := case operation_row.target_lifecycle_status
    when 'suspended' then 'STUDENT_SUSPENDED'
    else 'STUDENT_OFFBOARDED'
  end;
  teacher_kind := case operation_row.target_lifecycle_status
    when 'suspended' then 'TEACHER_STUDENT_SUSPENDED'
    else 'TEACHER_STUDENT_OFFBOARDED'
  end;

  student_destination := coalesce(
    private.normalize_notification_phone(student_row.attendance_phone),
    private.normalize_notification_phone(student_row.phone),
    private.normalize_notification_phone(student_row.guardian_phone)
  );
  student_message := case operation_row.target_lifecycle_status
    when 'suspended' then
      'Oi, ' || private.safe_notification_text(
        pg_catalog.split_part(coalesce(student_row.full_name, 'tudo bem'), ' ', 1),
        80
      ) || '! Passando para confirmar que sua jornada com a ' ||
      private.safe_notification_text(coalesce(tenant_name, 'nossa escola'), 120) ||
      ' ficará em pausa. Seus horários fixos foram liberados por enquanto. ' ||
      'Quando for o momento de retomar, nossa equipe estará pronta para ' ||
      'organizar uma nova agenda com carinho. Se precisar, conte com a gente.'
    else
      'Oi, ' || private.safe_notification_text(
        pg_catalog.split_part(coalesce(student_row.full_name, 'tudo bem'), ' ', 1),
        80
      ) || '! Registramos o encerramento da sua matrícula na ' ||
      private.safe_notification_text(coalesce(tenant_name, 'nossa escola'), 120) ||
      ', conforme alinhado com a equipe. Agradecemos por ter feito parte da ' ||
      'nossa escola. Seus horários fixos foram liberados e, se quiser voltar ' ||
      'no futuro, será um prazer receber você novamente. Conte com a gente.'
  end;

  if student_notification_enabled
     and coalesce(student_row.is_test_account, false) is false
     and student_destination is not null
  then
    insert into public.notification_queue (
      tenant_id,
      teacher_id,
      student_id,
      student_name,
      student_phone,
      message_body,
      scheduled_for,
      status,
      attempts,
      next_attempt_at,
      delivery_status,
      notification_kind,
      source_id,
      source_type,
      class_date,
      idempotency_key
    ) values (
      operation_row.tenant_id,
      null,
      operation_row.student_id,
      student_row.full_name,
      student_destination,
      student_message,
      pg_catalog.now(),
      'pending',
      0,
      pg_catalog.now(),
      'queued',
      student_kind,
      operation_row.id,
      'STUDENT_LIFECYCLE',
      null,
      'student-lifecycle:' || operation_row.id::text || ':student:' ||
        operation_row.target_lifecycle_status
    )
    on conflict (tenant_id, idempotency_key)
      where idempotency_key is not null
    do nothing;
    get diagnostics inserted_count = row_count;
    notifications_queued := notifications_queued + inserted_count;
  end if;

  if teacher_notification_enabled then
    for teacher_row in
      select
        profile.id,
        profile.full_name,
        coalesce(
          private.normalize_notification_phone(profile.phone),
          private.normalize_notification_phone(profile.attendance_phone)
        ) as destination
      from public.profiles as profile
      join pg_catalog.jsonb_array_elements_text(
        released_teacher_ids
      ) as released(teacher_id)
        on profile.id = released.teacher_id::uuid
     where profile.tenant_id = operation_row.tenant_id
       and profile.role = 'TEACHER'
       and pg_catalog.lower(pg_catalog.btrim(coalesce(
             profile.lifecycle_status,
             ''
           ))) = 'active'
       and coalesce(profile.is_test_account, false) is false
     order by profile.id
    loop
      if teacher_row.destination is null then
        continue;
      end if;

      teacher_message := case operation_row.target_lifecycle_status
        when 'suspended' then
          'Oi, ' || private.safe_notification_text(
            pg_catalog.split_part(
              coalesce(teacher_row.full_name, 'professor(a)'),
              ' ',
              1
            ),
            80
          ) || '! Atualização da coordenação: as aulas de ' ||
          private.safe_notification_text(
            coalesce(student_row.full_name, 'seu aluno'),
            120
          ) || ' ficarão em pausa, e os horários fixos já foram liberados ' ||
          'na sua agenda. Não é necessário manter esses slots reservados. ' ||
          'Se precisar de algum ajuste, fale com a coordenação.'
        else
          'Oi, ' || private.safe_notification_text(
            pg_catalog.split_part(
              coalesce(teacher_row.full_name, 'professor(a)'),
              ' ',
              1
            ),
            80
          ) || '! Atualização da coordenação: a matrícula de ' ||
          private.safe_notification_text(
            coalesce(student_row.full_name, 'seu aluno'),
            120
          ) || ' foi encerrada, e os horários fixos já foram liberados na ' ||
          'sua agenda. Obrigado por todo o acompanhamento. Se precisar de ' ||
          'algum ajuste, fale com a coordenação.'
      end;

      insert into public.notification_queue (
        tenant_id,
        teacher_id,
        student_id,
        student_name,
        student_phone,
        message_body,
        scheduled_for,
        status,
        attempts,
        next_attempt_at,
        delivery_status,
        notification_kind,
        source_id,
        source_type,
        class_date,
        idempotency_key
      ) values (
        operation_row.tenant_id,
        teacher_row.id,
        operation_row.student_id,
        student_row.full_name,
        teacher_row.destination,
        teacher_message,
        pg_catalog.now(),
        'pending',
        0,
        pg_catalog.now(),
        'queued',
        teacher_kind,
        operation_row.id,
        'STUDENT_LIFECYCLE',
        null,
        'student-lifecycle:' || operation_row.id::text || ':teacher:' ||
          teacher_row.id::text || ':' ||
          operation_row.target_lifecycle_status
      )
      on conflict (tenant_id, idempotency_key)
        where idempotency_key is not null
      do nothing;
      get diagnostics inserted_count = row_count;
      notifications_queued := notifications_queued + inserted_count;
    end loop;
  end if;

  final_result := base_result || pg_catalog.jsonb_build_object(
    'payments_cancelled', coalesce(
      nullif(base_result ->> 'payments_cancelled', '')::integer,
      0
    ) + newly_cancelled_payments,
    'schedules_cancelled', schedules_cancelled,
    'released_teacher_ids', released_teacher_ids,
    'notifications_queued', notifications_queued
  );

  update public.student_offboarding_operations
     set snapshot = snapshot || pg_catalog.jsonb_build_object(
           'student_lifecycle_finalize_result', final_result
         ),
         updated_at = pg_catalog.now()
   where id = operation_row.id;

  return final_result;
end;
$$;


--
-- Name: finalize_student_reactivation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_student_reactivation(p_operation_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.student_offboarding_operations%rowtype;
  operation_tenant_id text;
  operation_student_id uuid;
  changed_id uuid;
begin
  select operation.tenant_id, operation.student_id
    into operation_tenant_id, operation_student_id
    from public.student_offboarding_operations as operation
   where operation.id = p_operation_id;
  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || operation_tenant_id || ':' ||
        operation_student_id::text,
      0
    )
  );
  select operation.* into operation_row
    from public.student_offboarding_operations as operation
   where operation.id = p_operation_id
   for update;
  if not found
     or operation_row.claim_token is distinct from p_claim_token
     or operation_row.status <> 'PROVIDER_COMPLETE'
     or operation_row.source_lifecycle_status <> 'suspended'
     or operation_row.target_lifecycle_status <> 'active'
     or operation_row.provider_subscription_final_status is distinct from
       'ACTIVE'
  then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  if (
    select pg_catalog.count(*)
      from public.tenant_memberships as membership
     where membership.user_id = operation_row.student_id
  ) <> 1 or not exists (
    select 1
      from public.tenant_memberships as membership
     where membership.user_id = operation_row.student_id
       and membership.tenant_id = operation_row.tenant_id
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'membership_scope_changed_before_reactivation',
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'membership_scope_changed'
    );
  end if;

  perform pg_catalog.set_config(
    'app.student_lifecycle_finalizer', operation_row.id::text, true
  );
  update public.profiles as profile
     set status = 'Ativo',
         lifecycle_status = 'active',
         asaas_subscription_status =
           operation_row.provider_subscription_final_status,
         asaas_subscription_synced_at = pg_catalog.now(),
         suspended_at = null,
         suspended_reason = null,
         offboarding_status = null,
         offboarding_requested_at = null,
         offboarding_completed_at = null,
         offboarding_last_day = null,
         offboarding_reason = null
   where profile.id = operation_row.student_id
     and profile.tenant_id = operation_row.tenant_id
     and profile.role = 'STUDENT'
     and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) =
       'suspended'
     and nullif(pg_catalog.btrim(coalesce(profile.asaas_customer_id, '')), '')
       is not distinct from operation_row.customer_id
     and nullif(pg_catalog.btrim(coalesce(profile.subscription_id, '')), '')
       is not distinct from operation_row.subscription_id
     and operation_row.snapshot -> 'due_day' is not distinct from
       pg_catalog.to_jsonb(profile.due_day)
     and operation_row.snapshot -> 'monthly_fee' is not distinct from
       pg_catalog.to_jsonb(profile.monthly_fee)
   returning profile.id into changed_id;
  if changed_id is null then
    update public.student_offboarding_operations
       set status = 'BLOCKED',
           last_error = 'profile_binding_changed_before_reactivation',
           updated_at = pg_catalog.now()
     where id = operation_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'profile_binding_changed'
    );
  end if;

  update public.student_offboarding_operations
     set status = 'COMPLETED',
         completed_at = pg_catalog.now(),
         lease_expires_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where id = operation_row.id;
  -- The aggregate recompute deliberately preserves state while an operation is
  -- active. Mark this operation complete first; both changes still share this
  -- transaction/advisory lock and roll back together on any failure.
  perform public.recompute_student_financial_status(
    operation_row.tenant_id,
    operation_row.student_id
  );
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'COMPLETED',
    'provider_subscription_final_status',
      operation_row.provider_subscription_final_status
  );
end;
$$;


--
-- Name: finalize_whatsapp_outbound(text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_whatsapp_outbound(p_tenant_id text, p_message_id uuid, p_status text, p_provider_message_id text, p_error_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_message public.whatsapp_messages%rowtype;
  v_provider_echo public.whatsapp_messages%rowtype;
  v_requested_provider_message_id text := nullif(
    pg_catalog.btrim(coalesce(p_provider_message_id, '')),
    ''
  );
  v_provider_message_id text;
  v_error_code text := nullif(
    left(pg_catalog.btrim(coalesce(p_error_code, '')), 160),
    ''
  );
  v_next_status text;
  v_metadata jsonb;
begin
  if p_message_id is null
     or nullif(pg_catalog.btrim(p_tenant_id), '') is null
     or p_status not in ('sent', 'delivered', 'read', 'failed', 'uncertain')
     or (
       v_requested_provider_message_id is not null
       and char_length(v_requested_provider_message_id) > 320
     ) then
    raise exception 'invalid_whatsapp_outbound_result'
      using errcode = '22023';
  end if;

  select message.*
  into v_message
  from public.whatsapp_messages as message
  where message.id = p_message_id
    and message.tenant_id = p_tenant_id
    and message.direction = 'out';

  if not found then
    raise exception 'whatsapp_outbound_not_found' using errcode = 'P0002';
  end if;

  if v_message.provider_message_id is not null
     and v_requested_provider_message_id is not null
     and v_message.provider_message_id <> v_requested_provider_message_id then
    raise exception 'whatsapp_provider_message_id_is_immutable'
      using errcode = '22023';
  end if;

  v_provider_message_id := coalesce(
    v_requested_provider_message_id,
    v_message.provider_message_id
  );

  -- A ordem global é advisory(provider) -> linha da mensagem. O store usa a
  -- mesma ordem, evitando deadlock entre o eco do webhook e a resposta HTTP.
  if v_provider_message_id is not null then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'wa-provider:' || v_message.instance_id::text || ':' ||
        v_provider_message_id,
        0
      )
    );
  end if;

  select message.*
  into v_message
  from public.whatsapp_messages as message
  where message.id = p_message_id
    and message.tenant_id = p_tenant_id
    and message.direction = 'out'
  for update;

  if not found then
    raise exception 'whatsapp_outbound_not_found' using errcode = 'P0002';
  end if;

  if v_message.status = 'queued' then
    raise exception 'whatsapp_outbound_was_not_claimed'
      using errcode = '55000';
  end if;

  if v_message.provider_message_id is not null
     and v_provider_message_id is not null
     and v_message.provider_message_id <> v_provider_message_id then
    raise exception 'whatsapp_provider_message_id_is_immutable'
      using errcode = '22023';
  end if;

  v_metadata := v_message.metadata;
  if v_provider_message_id is not null then

    select echo.*
    into v_provider_echo
    from public.whatsapp_messages as echo
    where echo.instance_id = v_message.instance_id
      and echo.provider_message_id = v_provider_message_id
      and echo.id <> v_message.id
    for update;

    if found then
      if v_provider_echo.tenant_id <> p_tenant_id
         or v_provider_echo.conversation_id <> v_message.conversation_id
         or v_provider_echo.direction <> 'out'
         or v_provider_echo.client_request_id is not null
         or v_provider_echo.body <> v_message.body then
        raise exception 'whatsapp_provider_message_scope_conflict'
          using errcode = '23505';
      end if;
      v_metadata := v_metadata || v_provider_echo.metadata;
      delete from public.whatsapp_messages
      where id = v_provider_echo.id;
    end if;
  end if;

  v_next_status := private.merge_whatsapp_message_status(
    v_message.status,
    p_status
  );

  update public.whatsapp_messages as message
  set status = v_next_status,
      provider_message_id = coalesce(
        message.provider_message_id,
        v_provider_message_id
      ),
      metadata = v_metadata,
      lease_until = null,
      error_code = case
        when v_next_status in ('failed', 'uncertain')
        then coalesce(v_error_code, lower(v_next_status))
        else null
      end,
      sent_at = case
        when v_next_status in ('sent', 'delivered', 'read')
        then coalesce(message.sent_at, pg_catalog.now())
        else message.sent_at
      end,
      delivered_at = case
        when v_next_status in ('delivered', 'read')
        then coalesce(message.delivered_at, pg_catalog.now())
        else message.delivered_at
      end,
      read_at = case
        when v_next_status = 'read'
        then coalesce(message.read_at, pg_catalog.now())
        else message.read_at
      end
  where message.id = v_message.id
  returning message.* into v_message;

  return jsonb_build_object(
    'ok', true,
    'messageId', v_message.id,
    'status', v_message.status,
    'providerMessageId', v_message.provider_message_id
  );
end;
$$;


--
-- Name: finalize_wolfie_realtime_analysis(uuid, uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_wolfie_realtime_analysis(p_session_id uuid, p_student_turn_id uuid, p_assistant_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_marker jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  assistant_payload jsonb;
  student_payload jsonb;
  current_marker jsonb;
  marker_status text;
  next_fields jsonb;
begin
  if p_session_id is null
     or p_student_turn_id is null
     or p_assistant_turn_id is null
     or p_client_turn_id is null
     or p_claim_token is null
     or p_marker is null
     or pg_catalog.jsonb_typeof(p_marker) <> 'object'
     or pg_catalog.octet_length(p_marker::text) > 100000
     or coalesce(p_marker ->> 'status', '') not in (
       'completed', 'retryable', 'unavailable', 'awaiting_confirmation'
     )
     or p_marker ->> 'clientTurnId' is distinct from p_client_turn_id::text
     or p_marker ->> 'studentTurnId' is distinct from p_student_turn_id::text
     or p_marker ->> 'assistantTurnId' is distinct from p_assistant_turn_id::text
     or coalesce(p_marker ->> 'version', '') <> '1' then
    raise exception using errcode = '22023', message = 'invalid_realtime_marker';
  end if;

  select coalesce(structured_payload, '{}'::jsonb)
    into assistant_payload
    from public.wolfie_turns
   where id = p_assistant_turn_id
     and session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'wolfie'
     and source_kind = 'openai_realtime'
   for update;
  if not found then
    return false;
  end if;
  current_marker := assistant_payload -> 'realtimeAnalysis';
  marker_status := coalesce(current_marker ->> 'status', '');
  if marker_status in ('completed', 'unavailable', 'awaiting_confirmation') then
    return current_marker ->> 'studentTurnId' = p_student_turn_id::text
      and current_marker ->> 'assistantTurnId' = p_assistant_turn_id::text
      and current_marker ->> 'clientTurnId' = p_client_turn_id::text;
  end if;
  if marker_status <> 'processing'
     or current_marker ->> 'claimToken' <> p_claim_token::text then
    return false;
  end if;

  select coalesce(structured_payload, '{}'::jsonb)
    into student_payload
    from public.wolfie_turns
   where id = p_student_turn_id
     and session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'student'
     and source_kind = 'openai_realtime'
   for update;
  if not found then
    return false;
  end if;

  next_fields := pg_catalog.jsonb_build_object(
    'eligibleForCorrection', p_marker ->> 'status' = 'completed',
    'realtimeAnalysis', p_marker
  );
  if p_marker ? 'learnerIntent' then
    next_fields := next_fields || pg_catalog.jsonb_build_object(
      'learnerIntent', p_marker -> 'learnerIntent'
    );
  end if;

  update public.wolfie_turns
     set structured_payload = student_payload || next_fields
   where id = p_student_turn_id;
  update public.wolfie_turns
     set structured_payload = assistant_payload || next_fields
   where id = p_assistant_turn_id;
  return true;
end;
$$;


--
-- Name: FUNCTION finalize_wolfie_realtime_analysis(p_session_id uuid, p_student_turn_id uuid, p_assistant_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_marker jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalize_wolfie_realtime_analysis(p_session_id uuid, p_student_turn_id uuid, p_assistant_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_marker jsonb) IS 'Atomically finalizes the same server claim on both persisted Realtime turns.';


--
-- Name: finalize_wolfie_realtime_fact_confirmation(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_wolfie_realtime_fact_confirmation(p_session_id uuid, p_student_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_confirmation jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  current_payload jsonb;
  current_confirmation jsonb;
  current_status text;
  current_transcript text;
  requested_transcript text;
  requested_status text;
begin
  requested_status := coalesce(p_confirmation ->> 'status', '');
  if p_session_id is null
     or p_student_turn_id is null
     or p_client_turn_id is null
     or p_claim_token is null
     or p_confirmation is null
     or pg_catalog.jsonb_typeof(p_confirmation) <> 'object'
     or pg_catalog.octet_length(p_confirmation::text) > 100000
     or requested_status not in ('confirmed', 'retryable')
     or p_confirmation ->> 'clientTurnId' is distinct from p_client_turn_id::text
     or p_confirmation ->> 'studentTurnId' is distinct from p_student_turn_id::text
     or p_confirmation ->> 'claimToken' is distinct from p_claim_token::text
     or coalesce(p_confirmation ->> 'version', '') <> '1'
     or nullif(p_confirmation ->> 'confirmedTranscript', '') is null then
    raise exception using
      errcode = '22023',
      message = 'invalid_realtime_fact_confirmation';
  end if;

  select coalesce(structured_payload, '{}'::jsonb)
    into current_payload
    from public.wolfie_turns
   where id = p_student_turn_id
     and session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'student'
     and source_kind = 'openai_realtime'
   for update;
  if not found then
    return false;
  end if;

  current_confirmation := current_payload -> 'factualConfirmation';
  current_status := coalesce(current_confirmation ->> 'status', '');
  current_transcript := pg_catalog.lower(pg_catalog.regexp_replace(
    pg_catalog.btrim(coalesce(
      current_confirmation ->> 'confirmedTranscript',
      ''
    )),
    '\s+',
    ' ',
    'g'
  ));
  requested_transcript := pg_catalog.lower(pg_catalog.regexp_replace(
    pg_catalog.btrim(p_confirmation ->> 'confirmedTranscript'),
    '\s+',
    ' ',
    'g'
  ));

  if current_status = 'confirmed' then
    -- Never downgrade a confirmation when a release request races with a
    -- successful commit whose response was lost.
    return current_transcript = requested_transcript;
  end if;
  if current_status = 'retryable' then
    return requested_status = 'retryable'
      and current_confirmation ->> 'claimToken' = p_claim_token::text
      and current_transcript = requested_transcript;
  end if;
  if current_status <> 'processing'
     or current_confirmation ->> 'claimToken' <> p_claim_token::text
     or current_transcript <> requested_transcript then
    return false;
  end if;

  -- Merge against the locked, current payload. In particular, never replace a
  -- completed realtimeAnalysis marker with the snapshot read before facts ran.
  if requested_status = 'confirmed' then
    update public.wolfie_turns
       set content = p_confirmation ->> 'confirmedTranscript',
           structured_payload = current_payload || pg_catalog.jsonb_build_object(
             'factsConfirmedByLearner', true,
             'factualConfirmation', p_confirmation
           )
     where id = p_student_turn_id;
  else
    -- A failed fact write releases the fresh claim immediately. The same
    -- transcript can be claimed again without waiting for stale-lease expiry.
    update public.wolfie_turns
       set structured_payload = current_payload || pg_catalog.jsonb_build_object(
         'factualConfirmation', p_confirmation
       )
     where id = p_student_turn_id;
  end if;
  return true;
end;
$$;


--
-- Name: FUNCTION finalize_wolfie_realtime_fact_confirmation(p_session_id uuid, p_student_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_confirmation jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finalize_wolfie_realtime_fact_confirmation(p_session_id uuid, p_student_turn_id uuid, p_client_turn_id uuid, p_claim_token uuid, p_confirmation jsonb) IS 'Finalizes or immediately releases a claimed confirmation without regressing analysis state.';


--
-- Name: financial_reconciliation(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.financial_reconciliation(p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
declare
  v_jwt text;
  v_role text;
  v_tenant text;
  v_sem_cobertura jsonb;
  v_cobrado_sem_estudar jsonb;
  v_arquivado_com_fatura jsonb;
  v_pago_sem_nf jsonb;
  v_parado_com_nf jsonb;
  v_aula_nao_lancada jsonb;
begin
  v_jwt := coalesce(current_setting('request.jwt.claims', true)::json->>'role', '');
  select role, tenant_id into v_role, v_tenant from public.profiles where id = auth.uid();

  if v_jwt in ('anon', 'authenticated') then
    if v_role is null or v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') then
      return jsonb_build_object('error', 'sem_permissao');
    end if;
    if v_role = 'SUPER_ADMIN' then v_tenant := coalesce(p_tenant, v_tenant); end if;
  else
    v_tenant := coalesce(p_tenant, v_tenant);
  end if;

  if v_tenant is null then
    return jsonb_build_object('error', 'escola_nao_identificada');
  end if;

  -------------------------------------------------------------------------
  -- 1. MESES DE AULA ENTREGUES × MESES PAGOS.
  --
  -- Substitui o antigo `nunca_cobrado`, que contava BOLETOS e por isso acusava
  -- quem pagou o ano à vista num boleto só.
  --
  -- ⚠️ A primeira tentativa de conserto contava a cobertura a partir do
  -- PRIMEIRO PAGAMENTO, e escondia o caso oposto: uma aluna que estudou de
  -- fevereiro a julho sem pagar nada, pagou UM mês em 07/07 e passava a
  -- parecer em dia — os cinco meses anteriores sumiam da conta.
  --
  -- A régua correta compara SERVIÇO ENTREGUE com DINHEIRO RECEBIDO:
  --   meses_servico = desde a primeira aula até hoje
  --   meses_pagos   = total recebido / mensalidade
  --   deficit       = serviço − pago
  -- Quem pagou 12 e entregou 6 tem déficit negativo e não aparece. Quem
  -- entregou 7 e pagou 1 aparece com o tamanho real do buraco.
  --
  -- Tolerância de 2 meses: cobre atraso normal de boleto e o mês corrente
  -- ainda em curso, sem alarmar no dia seguinte ao vencimento.
  -------------------------------------------------------------------------
  select coalesce(jsonb_agg(x order by x.valor_estimado desc), '[]'::jsonb) into v_sem_cobertura
  from (
    select trim(p.full_name) as aluno,
           p.id as student_id,
           coalesce(p.monthly_fee, 0)::numeric(10,2) as mensalidade,
           c.inicio as primeira_aula,
           c.aulas_60d,
           c.recebido::numeric(10,2) as total_recebido,
           c.meses_servico,
           c.meses_pagos,
           (c.meses_servico - c.meses_pagos) as deficit_meses,
           ((c.meses_servico - c.meses_pagos) * coalesce(p.monthly_fee, 0))::numeric(10,2) as valor_estimado
      from public.profiles p
      cross join lateral (
        select
          (select count(*) from public.v_payable_class_logs v
            where v.student_id = p.id and v.class_date >= current_date - 60)::int as aulas_60d,
          coalesce((select sum(greatest(round(coalesce(sp.value, 0) - coalesce(sp.refunded_amount, 0), 2), 0)) from public.student_payments sp
                     where sp.student_id = p.id
                       and sp.status in ('RECEIVED', 'RECEIVED_IN_CASH')), 0) as recebido,
          -- O relógio começa quando o serviço começou, não quando alguém pagou.
          coalesce((select min(v.class_date) from public.v_payable_class_logs v
                     where v.student_id = p.id),
                   p.created_at::date) as inicio
      ) base
      cross join lateral (
        select base.aulas_60d,
               base.recebido,
               base.inicio,
               (floor((current_date - base.inicio) / 30.0)::int + 1) as meses_servico,
               floor(base.recebido / nullif(coalesce(p.monthly_fee, 0), 0))::int as meses_pagos
      ) c
     where p.tenant_id = v_tenant
       and p.role = 'STUDENT'
       and coalesce(p.monthly_fee, 0) > 0
       and public.is_student_notifiable(p.id)
       and c.aulas_60d > 0
       and (c.meses_servico - c.meses_pagos) >= 2
  ) x;

  -------------------------------------------------------------------------
  -- 2. COBRADO SEM ESTUDAR.
  -------------------------------------------------------------------------
  select coalesce(jsonb_agg(x order by x.em_aberto desc), '[]'::jsonb) into v_cobrado_sem_estudar
  from (
    select trim(p.full_name) as aluno,
           p.id as student_id,
           (select count(*) from public.student_payments sp
             where sp.student_id = p.id
               and sp.status not in ('RECEIVED', 'RECEIVED_IN_CASH', 'REFUNDED')
               and coalesce(sp.exclusion_reason, '') = '')::int as faturas_abertas,
           (select coalesce(sum(sp.value), 0) from public.student_payments sp
             where sp.student_id = p.id
               and sp.status not in ('RECEIVED', 'RECEIVED_IN_CASH', 'REFUNDED')
               and coalesce(sp.exclusion_reason, '') = '')::numeric(10,2) as em_aberto
      from public.profiles p
     where p.tenant_id = v_tenant
       and p.role = 'STUDENT'
       and public.is_student_notifiable(p.id)
       and not exists (select 1 from public.bookings b
                        where b.student_id = p.id and b.status = 'SCHEDULED')
       and not exists (select 1 from public.class_logs cl
                        where cl.student_id = p.id and cl.class_date >= current_date - 90)
       and exists (select 1 from public.student_payments sp
                    where sp.student_id = p.id
                      and sp.status not in ('RECEIVED', 'RECEIVED_IN_CASH', 'REFUNDED')
                      and coalesce(sp.exclusion_reason, '') = '')
  ) x;

  -------------------------------------------------------------------------
  -- 2b. ARQUIVADO COM FATURA EM ABERTO.
  -------------------------------------------------------------------------
  select coalesce(jsonb_agg(x order by x.em_aberto desc), '[]'::jsonb) into v_arquivado_com_fatura
  from (
    select trim(p.full_name) as aluno,
           p.id as student_id,
           coalesce(p.status, '-') as status,
           (select count(*) from public.student_payments sp
             where sp.student_id = p.id
               and sp.status not in ('RECEIVED', 'RECEIVED_IN_CASH', 'REFUNDED')
               and coalesce(sp.exclusion_reason, '') = '')::int as faturas_abertas,
           (select coalesce(sum(sp.value), 0) from public.student_payments sp
             where sp.student_id = p.id
               and sp.status not in ('RECEIVED', 'RECEIVED_IN_CASH', 'REFUNDED')
               and coalesce(sp.exclusion_reason, '') = '')::numeric(10,2) as em_aberto
      from public.profiles p
     where p.tenant_id = v_tenant
       and p.role = 'STUDENT'
       and not public.is_student_notifiable(p.id)
       and exists (select 1 from public.student_payments sp
                    where sp.student_id = p.id
                      and sp.status not in ('RECEIVED', 'RECEIVED_IN_CASH', 'REFUNDED')
                      and coalesce(sp.exclusion_reason, '') = '')
  ) x;

  -------------------------------------------------------------------------
  -- 3. FECHAMENTO PAGO SEM NOTA FISCAL.
  -------------------------------------------------------------------------
  select coalesce(jsonb_agg(x order by x.month_year), '[]'::jsonb) into v_pago_sem_nf
  from (
    select trim(t.full_name) as professor,
           c.month_year,
           c.status,
           coalesce(c.total_amount, 0)::numeric(10,2) as valor,
           coalesce(c.paid_at, c.updated_at)::date as pago_em
      from public.teacher_closings c
      join public.profiles t on t.id = c.teacher_id
     where c.tenant_id = v_tenant
       and upper(coalesce(c.status, '')) in ('PAGO', 'COMPLETED', 'PAID_WAITING_NF')
       and coalesce(btrim(c.nf_link), '') = ''
       and coalesce(c.total_amount, 0) > 0
       and coalesce(c.paid_at, c.updated_at) < now() - interval '30 days'
  ) x;

  -------------------------------------------------------------------------
  -- 4. FECHAMENTO PARADO COM NF ANEXADA.
  -------------------------------------------------------------------------
  select coalesce(jsonb_agg(x order by x.month_year), '[]'::jsonb) into v_parado_com_nf
  from (
    select trim(t.full_name) as professor,
           c.month_year,
           coalesce(c.total_amount, 0)::numeric(10,2) as valor,
           (current_date - c.updated_at::date)::int as dias_parado
      from public.teacher_closings c
      join public.profiles t on t.id = c.teacher_id
     where c.tenant_id = v_tenant
       and upper(coalesce(c.status, '')) = 'UNDER_REVIEW'
       and coalesce(btrim(c.nf_link), '') <> ''
       and c.updated_at < now() - interval '7 days'
  ) x;

  -------------------------------------------------------------------------
  -- 5. AULA CONFIRMADA E NUNCA LANÇADA.
  -------------------------------------------------------------------------
  select coalesce(jsonb_agg(x order by x.data), '[]'::jsonb) into v_aula_nao_lancada
  from (
    select trim(t.full_name) as professor,
           trim(s.full_name) as aluno,
           ac.class_date as data,
           (current_date - ac.class_date)::int as dias
      from public.attendance_confirmations ac
      left join public.profiles t on t.id = ac.teacher_id
      left join public.profiles s on s.id = ac.student_id
     where ac.status = 'AWAITING_TEACHER'
       and ac.class_date < current_date - 7
       and coalesce(t.tenant_id, s.tenant_id) = v_tenant
  ) x;

  return jsonb_build_object(
    'ok', true,
    'tenant', v_tenant,
    'gerado_em', now(),
    'sem_cobertura', jsonb_build_object(
      'itens', v_sem_cobertura,
      'qtd', jsonb_array_length(v_sem_cobertura),
      -- Estimativa, não conta a receber: é déficit × mensalidade atual. Serve
      -- para dimensionar o buraco, não para emitir boleto.
      'total', (select coalesce(sum((i->>'valor_estimado')::numeric), 0)
                  from jsonb_array_elements(v_sem_cobertura) i)
    ),
    'cobrado_sem_estudar', jsonb_build_object(
      'itens', v_cobrado_sem_estudar,
      'qtd', jsonb_array_length(v_cobrado_sem_estudar),
      'total', (select coalesce(sum((i->>'em_aberto')::numeric), 0)
                  from jsonb_array_elements(v_cobrado_sem_estudar) i)
    ),
    'arquivado_com_fatura', jsonb_build_object(
      'itens', v_arquivado_com_fatura,
      'qtd', jsonb_array_length(v_arquivado_com_fatura),
      'total', (select coalesce(sum((i->>'em_aberto')::numeric), 0)
                  from jsonb_array_elements(v_arquivado_com_fatura) i)
    ),
    'pago_sem_nf', jsonb_build_object(
      'itens', v_pago_sem_nf,
      'qtd', jsonb_array_length(v_pago_sem_nf),
      'total', (select coalesce(sum((i->>'valor')::numeric), 0)
                  from jsonb_array_elements(v_pago_sem_nf) i)
    ),
    'parado_com_nf', jsonb_build_object(
      'itens', v_parado_com_nf,
      'qtd', jsonb_array_length(v_parado_com_nf),
      'total', (select coalesce(sum((i->>'valor')::numeric), 0)
                  from jsonb_array_elements(v_parado_com_nf) i)
    ),
    'aula_nao_lancada', jsonb_build_object(
      'itens', v_aula_nao_lancada,
      'qtd', jsonb_array_length(v_aula_nao_lancada)
    )
  );
end;
$$;


--
-- Name: FUNCTION financial_reconciliation(p_tenant text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.financial_reconciliation(p_tenant text) IS 'Reconciliacao usa recebimento liquido de refunded_amount para cobertura; faturas ainda em aberto permanecem pelo bruto.';


--
-- Name: find_authorized_profile_by_cpf(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_authorized_profile_by_cpf(p_tenant_id text, p_cpf text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role text := public._my_role();
  v_tenant text := public._my_tenant_id();
  v_normalized_cpf text := pg_catalog.regexp_replace(
    coalesce(p_cpf, ''),
    '[^0-9]',
    '',
    'g'
  );
  v_profile_id uuid;
begin
  if auth.uid() is null
     or p_tenant_id is null
     or not (
       v_role = 'SUPER_ADMIN'
       or (v_role = 'SCHOOL_ADMIN' and v_tenant = p_tenant_id)
     ) then
    raise exception 'CPF lookup is not authorized' using errcode = '42501';
  end if;

  if v_normalized_cpf = '' then
    return null;
  end if;

  select profile.id
    into v_profile_id
    from public.profiles as profile
   where profile.tenant_id = p_tenant_id
     and pg_catalog.regexp_replace(
       coalesce(profile.cpf, ''),
       '[^0-9]',
       '',
       'g'
     ) = v_normalized_cpf
   order by profile.id
   limit 1;

  return v_profile_id;
end;
$$;


--
-- Name: finish_asaas_outbound_message(uuid, uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_asaas_outbound_message(p_attempt_id uuid, p_claim_token uuid, p_status text, p_provider_http_status integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.asaas_outbound_message_attempts%rowtype;
  normalized_status text := upper(pg_catalog.btrim(coalesce(p_status, '')));
begin
  if normalized_status not in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED') then
    raise exception using errcode = '22023', message = 'invalid_outbound_message_state';
  end if;
  select message_attempt.* into attempt_row
    from public.asaas_outbound_message_attempts as message_attempt
   where message_attempt.id = p_attempt_id
   for update;
  if not found or attempt_row.claim_token is distinct from p_claim_token then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;
  if attempt_row.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED') then
    return pg_catalog.jsonb_build_object(
      'ok', attempt_row.status = normalized_status,
      'status', attempt_row.status,
      'ignored_regression', attempt_row.status <> normalized_status
    );
  end if;
  if normalized_status = 'SUPPRESSED' then
    if attempt_row.status <> 'CLAIMED' or attempt_row.submit_attempt_count <> 0 then
      return pg_catalog.jsonb_build_object('ok', false, 'reason', 'invalid_suppression_transition');
    end if;
  elsif attempt_row.status <> 'SUBMITTING' or attempt_row.submit_attempt_count <> 1 then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'submit_not_started');
  end if;
  update public.asaas_outbound_message_attempts
     set status = normalized_status,
         provider_http_status = p_provider_http_status,
         last_error = nullif(pg_catalog.left(coalesce(p_error, ''), 500), ''),
         lease_expires_at = now(),
         updated_at = now()
   where id = attempt_row.id;
  return pg_catalog.jsonb_build_object('ok', true, 'status', normalized_status);
end;
$$;


--
-- Name: finish_asaas_payment_split_message(uuid, uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_asaas_payment_split_message(p_attempt_id uuid, p_claim_token uuid, p_status text, p_provider_http_status integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.asaas_payment_split_message_attempts%rowtype;
  normalized_status text := upper(pg_catalog.btrim(coalesce(p_status, '')));
begin
  if normalized_status not in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED') then
    raise exception using errcode = '22023', message = 'invalid_payment_split_message_state';
  end if;

  select attempt.* into attempt_row
    from public.asaas_payment_split_message_attempts as attempt
   where attempt.id = p_attempt_id
   for update;
  if not found or attempt_row.claim_token is distinct from p_claim_token then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;
  if attempt_row.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED') then
    return pg_catalog.jsonb_build_object(
      'ok', attempt_row.status = normalized_status,
      'status', attempt_row.status,
      'ignored_regression', attempt_row.status <> normalized_status
    );
  end if;
  if normalized_status = 'SUPPRESSED' then
    if attempt_row.status <> 'CLAIMED' or attempt_row.submit_attempt_count <> 0 then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'invalid_suppression_transition'
      );
    end if;
  elsif attempt_row.status <> 'SUBMITTING'
     or attempt_row.submit_attempt_count <> 1
  then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'submit_not_started');
  end if;

  update public.asaas_payment_split_message_attempts
     set status = normalized_status,
         provider_http_status = p_provider_http_status,
         last_error = nullif(
           pg_catalog.left(coalesce(p_error, ''), 500),
           ''
         ),
         lease_expires_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where id = attempt_row.id;
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'status', normalized_status
  );
end;
$$;


--
-- Name: finish_asaas_subscription_mutation(uuid, uuid, text, jsonb, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_asaas_subscription_mutation(p_operation_id uuid, p_claim_token uuid, p_status text, p_observed_state jsonb DEFAULT NULL::jsonb, p_provider_http_status integer DEFAULT NULL::integer, p_last_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation public.asaas_subscription_mutation_operations%rowtype;
  v_status text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_status, '')));
begin
  if v_status not in ('SUCCEEDED', 'FAILED', 'UNKNOWN', 'BLOCKED') then
    raise exception 'invalid_subscription_mutation_outcome'
      using errcode = '22023';
  end if;
  select operation.* into v_operation
    from public.asaas_subscription_mutation_operations as operation
   where operation.id = p_operation_id
   for update;
  if not found or v_operation.claim_token is distinct from p_claim_token then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;
  if v_operation.status = 'SUCCEEDED' then
    return pg_catalog.jsonb_build_object(
      'ok', v_status = 'SUCCEEDED'
        and p_observed_state is not distinct from v_operation.desired_state,
      'status', 'SUCCEEDED',
      'ignored_regression', v_status <> 'SUCCEEDED'
    );
  end if;
  if v_status = 'SUCCEEDED' and (
    pg_catalog.jsonb_typeof(p_observed_state) <> 'object'
    or p_observed_state is distinct from v_operation.desired_state
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'provider_postcondition_unverified'
    );
  end if;
  if (v_status = 'FAILED' and v_operation.status <> 'SUBMITTING')
     or (v_status = 'UNKNOWN' and v_operation.status <> 'SUBMITTING')
     or (
       v_status = 'SUCCEEDED'
       and v_operation.status not in ('SUBMITTING', 'UNKNOWN')
       and not (
         v_operation.status = 'CLAIMED'
         and v_operation.expected_state = v_operation.desired_state
       )
     )
     or (
       v_status = 'BLOCKED'
       and v_operation.status not in ('CLAIMED', 'SUBMITTING', 'UNKNOWN')
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'invalid_state_transition'
    );
  end if;
  update public.asaas_subscription_mutation_operations
     set status = v_status,
         observed_state = case
           when p_observed_state is null then observed_state
           else p_observed_state
         end,
         provider_http_status = p_provider_http_status,
         last_error = nullif(pg_catalog.left(coalesce(p_last_error, ''), 500), ''),
         completed_at = case
           when v_status in ('SUCCEEDED', 'FAILED', 'BLOCKED')
             then pg_catalog.now()
           else null
         end,
         lease_expires_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where id = v_operation.id;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'status', v_status, 'operation_id', v_operation.id
  );
end;
$$;


--
-- Name: finish_asaas_webhook_event(text, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_asaas_webhook_event(p_event_id text, p_worker_token uuid, p_outcome text, p_error text DEFAULT NULL::text, p_tenant_id text DEFAULT NULL::text, p_local_entity_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  inbox_row public.asaas_webhook_inbox%rowtype;
  final_status text;
  delay_seconds integer;
begin
  select inbox.*
    into inbox_row
    from public.asaas_webhook_inbox as inbox
   where inbox.provider_event_id = p_event_id
   for update;

  if inbox_row.provider_event_id is null
     or inbox_row.status <> 'PROCESSING'
     or inbox_row.lease_owner is distinct from p_worker_token
  then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  final_status := case upper(coalesce(p_outcome, ''))
    when 'PROCESSED' then 'PROCESSED'
    when 'TRIAGE' then 'TRIAGE'
    when 'DEAD_LETTER' then 'DEAD_LETTER'
    else case when inbox_row.attempt_count >= 12 then 'DEAD_LETTER' else 'RETRY' end
  end;
  delay_seconds := least(3600, greatest(15, (power(2, least(inbox_row.attempt_count, 8)) * 15)::integer));

  update public.asaas_webhook_inbox
     set status = final_status,
         lease_owner = null,
         lease_expires_at = null,
         next_attempt_at = case
           when final_status = 'RETRY' then now() + make_interval(secs => delay_seconds)
           else now()
         end,
         last_error = nullif(left(coalesce(p_error, ''), 500), ''),
         processed_at = case
           when final_status in ('PROCESSED', 'TRIAGE', 'DEAD_LETTER') then now()
           else null
         end,
         updated_at = now()
   where provider_event_id = p_event_id;

  if final_status in ('TRIAGE', 'DEAD_LETTER') then
    insert into public.asaas_reconciliation_issues (
      tenant_id, source, kind, severity, provider_entity_id,
      local_entity_id, fingerprint, details
    ) values (
      p_tenant_id,
      'WEBHOOK',
      case when final_status = 'TRIAGE' then 'WEBHOOK_TRIAGE' else 'WEBHOOK_DEAD_LETTER' end,
      case when final_status = 'TRIAGE' then 'HIGH' else 'CRITICAL' end,
      inbox_row.provider_entity_id,
      p_local_entity_id,
      lower(final_status) || ':' || p_event_id,
      jsonb_build_object(
        'providerEventId', p_event_id,
        'eventName', inbox_row.event_name,
        'attemptCount', inbox_row.attempt_count,
        'error', left(coalesce(p_error, 'unknown'), 500)
      )
    )
    on conflict do nothing;
  end if;

  return jsonb_build_object(
    'ok', true,
    'status', final_status,
    'retry_after_seconds', case when final_status = 'RETRY' then delay_seconds else null end
  );
end;
$$;


