--
-- Name: finish_management_payment_notification(uuid, uuid, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_management_payment_notification(p_attempt_id uuid, p_claim_token uuid, p_status text, p_provider_message_id text DEFAULT NULL::text, p_provider_http_status integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_outbox public.management_payment_notification_outbox%rowtype;
  v_status text := upper(pg_catalog.btrim(coalesce(p_status, '')));
  v_provider_message_id text := nullif(
    pg_catalog.left(
      pg_catalog.btrim(coalesce(p_provider_message_id, '')),
      320
    ),
    ''
  );
  v_error text := nullif(
    pg_catalog.left(pg_catalog.btrim(coalesce(p_error, '')), 500),
    ''
  );
  v_receipt private.whatsapp_provider_delivery_receipts%rowtype;
begin
  if v_status not in ('SENT', 'FAILED', 'UNKNOWN') then
    raise exception 'invalid_management_payment_notification_outcome'
      using errcode = '22023';
  end if;

  select outbox.*
  into v_outbox
  from public.management_payment_notification_outbox as outbox
  where outbox.id = p_attempt_id
  for update;

  if not found or v_outbox.claim_token is distinct from p_claim_token then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'claim_lost'
    );
  end if;
  if v_outbox.status in ('SENT', 'FAILED', 'UNKNOWN', 'SUPPRESSED') then
    return pg_catalog.jsonb_build_object(
      'ok', v_outbox.status = v_status,
      'status', v_outbox.status,
      'provider_delivery_status', v_outbox.provider_delivery_status,
      'ignored_regression', v_outbox.status <> v_status
    );
  end if;
  if v_outbox.status <> 'SUBMITTING'
     or v_outbox.submit_attempt_count <> 1
     or v_outbox.snapshot_hash is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'submit_not_started'
    );
  end if;

  -- A 2xx response without the provider identity cannot ever be correlated to
  -- an Evolution receipt. Keep it terminal UNKNOWN instead of claiming that
  -- the management group received the message.
  if v_status = 'SENT' and v_provider_message_id is null then
    v_status := 'UNKNOWN';
    v_error := 'provider_acceptance_without_message_id';
  end if;

  update public.management_payment_notification_outbox
  set status = case when v_status = 'SENT' then 'SUBMITTING' else v_status end,
      provider_message_id = v_provider_message_id,
      provider_http_status = p_provider_http_status,
      provider_delivery_status = case
        when v_status = 'SENT' then 'accepted'
        when v_status = 'FAILED' then 'failed'
        when v_status = 'UNKNOWN' then 'uncertain'
      end,
      last_error = v_error,
      accepted_at = case
        when v_status = 'SENT' then pg_catalog.now()
        else accepted_at
      end,
      lease_expires_at = pg_catalog.now(),
      updated_at = pg_catalog.now()
  where id = v_outbox.id
  returning * into v_outbox;

  -- A provider echo may win the race and be stored before the HTTP caller can
  -- persist its message id. Reconcile an already-visible receipt here; later
  -- receipts are bridged by the trigger above.
  if v_provider_message_id is not null then
    select receipt.*
    into v_receipt
    from private.whatsapp_provider_delivery_receipts as receipt
    where receipt.tenant_id = v_outbox.tenant_id
      and lower(receipt.provider_instance_name) = lower(
        v_outbox.provider_instance_name
      )
      and receipt.provider_message_id = v_provider_message_id;

    if found then
      perform private.apply_management_payment_notification_receipt(
        v_receipt.tenant_id,
        v_receipt.provider_instance_name,
        v_receipt.provider_message_id,
        v_receipt.delivery_status,
        v_receipt.accepted_at,
        v_receipt.delivered_at,
        v_receipt.read_at
      );
      select outbox.* into v_outbox
      from public.management_payment_notification_outbox as outbox
      where outbox.id = v_outbox.id;
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'status', v_outbox.status,
    'provider_delivery_status', v_outbox.provider_delivery_status
  );
end;
$$;


--
-- Name: finish_plan_change_billing_claim(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_plan_change_billing_claim(p_id uuid, p_claim_token uuid, p_ok boolean, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  plan_change public.student_plan_changes%rowtype;
  v_status text;
begin
  if p_id is null or p_claim_token is null or p_ok is null then
    raise exception using
      errcode = '22023',
      message = 'claim_completion_arguments_required';
  end if;

  select queued.*
    into plan_change
    from public.student_plan_changes as queued
   where queued.id = p_id
   for update;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'not_found'
    );
  end if;

  -- Monotonic terminal state: even a worker holding an obsolete token cannot
  -- turn a completed synchronization back into a retry or failure.
  if plan_change.billing_sync_status = 'SYNCED' then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'status', 'SYNCED',
      'applied', false,
      'ignored_regression', not p_ok
    );
  end if;

  if plan_change.billing_sync_status <> 'PENDING'
     or plan_change.billing_claim_token is distinct from p_claim_token
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'claim_lost',
      'status', plan_change.billing_sync_status
    );
  end if;

  v_status := case
    when p_ok then 'SYNCED'
    when plan_change.billing_attempts >= 6 then 'FAILED'
    else 'PENDING'
  end;

  update public.student_plan_changes as queued
     set billing_sync_status = v_status,
         billing_sync_error = case
           when p_ok then null
           else pg_catalog.left(
             coalesce(p_error, 'erro desconhecido'),
             500
           )
         end,
         billing_synced_at = case
           when p_ok then pg_catalog.clock_timestamp()
           else queued.billing_synced_at
         end,
         billing_claim_token = null,
         billing_lease_expires_at = null,
         billing_claimed_at = null
   where queued.id = plan_change.id
     and queued.billing_claim_token = p_claim_token;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'status', v_status,
    'applied', true
  );
end;
$$;


--
-- Name: finish_saas_owner_activation(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_saas_owner_activation(p_checkout_id uuid, p_claim_token uuid, p_status text, p_provider_message_id text DEFAULT NULL::text, p_last_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_status text := upper(pg_catalog.btrim(coalesce(p_status, '')));
  normalized_provider_id text := nullif(
    pg_catalog.btrim(coalesce(p_provider_message_id, '')),
    ''
  );
  changed_checkout_id uuid;
begin
  if p_checkout_id is null or p_claim_token is null
     or normalized_status not in ('SENT', 'FAILED', 'UNKNOWN')
     or length(coalesce(normalized_provider_id, '')) > 240
  then
    raise exception using
      errcode = '22023', message = 'invalid_saas_owner_activation_finish';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-activation:' || p_checkout_id::text,
      0
    )
  );

  update public.saas_owner_activation_attempts
     set status = normalized_status,
         provider_message_id = normalized_provider_id,
         provider_payload = case
           when normalized_status = 'UNKNOWN' then provider_payload
           else null
         end,
         provider_payload_sha256 = case
           when normalized_status = 'UNKNOWN' then provider_payload_sha256
           else null
         end,
         provider_payload_staged_at = case
           when normalized_status = 'UNKNOWN' then provider_payload_staged_at
           else null
         end,
         lease_expires_at = pg_catalog.now(),
         completed_at = pg_catalog.now(),
         last_error = nullif(left(coalesce(p_last_error, ''), 500), ''),
         updated_at = pg_catalog.now()
   where checkout_id = p_checkout_id
     and claim_token = p_claim_token
     and status = 'SUBMITTING'
     and submit_attempt_count between 1 and 5
   returning checkout_id into changed_checkout_id;

  return pg_catalog.jsonb_build_object(
    'ok', changed_checkout_id is not null,
    'action', case
      when changed_checkout_id is null then 'REVIEW_REQUIRED'
      else 'FINALIZED'
    end,
    'status', case
      when changed_checkout_id is null then null
      else normalized_status
    end,
    'reason', case
      when changed_checkout_id is null then 'activation_submit_state_lost'
      else null
    end
  );
end;
$$;


--
-- Name: finish_sdr_work(text, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_sdr_work(p_tenant_id text, p_phone text, p_token uuid, p_success boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare w public.sdr_conversation_work%rowtype;
begin
  select * into w from public.sdr_conversation_work where tenant_id=p_tenant_id and phone=p_phone for update;
  if not found or w.lease_token is distinct from p_token then return; end if;
  update public.sdr_conversation_work set
    completed_msg_id=case when p_success then claimed_msg_id else completed_msg_id end,
    phase=case when not p_success and phase='APPLYING' then 'REVIEW' else 'IDLE' end,
    available_at=case when p_success then available_at else now()+interval '1 minute' end,
    lease_token=null,lease_until=null,updated_at=now()
    where tenant_id=p_tenant_id and phone=p_phone;
  if not p_success and w.phase='APPLYING' then
    update public.crm_leads set ai_handoff=true,ai_handoff_at=now()
      where tenant_id=p_tenant_id and regexp_replace(phone,'[^0-9]','','g')=p_phone;
  end if;
end;
$$;


--
-- Name: finish_student_billing_method_operation(uuid, uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_student_billing_method_operation(p_operation_id uuid, p_claim_token uuid, p_outcome text, p_provider_http_status integer DEFAULT NULL::integer, p_last_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_outcome text := upper(trim(coalesce(p_outcome, '')));
  changed_id uuid;
begin
  if normalized_outcome not in ('COMPLETE', 'FAILED', 'UNKNOWN', 'BLOCKED') then
    raise exception using errcode = '22023', message = 'invalid_billing_method_outcome';
  end if;
  update public.student_billing_method_operations
     set status = case when normalized_outcome = 'COMPLETE' then 'COMPLETED' else normalized_outcome end,
         provider_http_status = p_provider_http_status,
         last_error = case when normalized_outcome = 'COMPLETE' then null else nullif(left(coalesce(p_last_error, ''), 500), '') end,
         completed_at = case when normalized_outcome in ('COMPLETE', 'FAILED', 'BLOCKED') then coalesce(completed_at, now()) else completed_at end,
         lease_expires_at = now(),
         updated_at = now()
   where id = p_operation_id
     and claim_token = p_claim_token
     and (
       (normalized_outcome = 'COMPLETE' and status in ('MUTATING', 'UNKNOWN'))
       or (normalized_outcome = 'FAILED' and status = 'MUTATING')
       or (normalized_outcome = 'UNKNOWN' and status in ('MUTATING', 'UNKNOWN'))
       or (normalized_outcome = 'BLOCKED' and status in ('CLAIMED', 'MUTATING', 'UNKNOWN', 'BLOCKED'))
       or (normalized_outcome = 'COMPLETE' and status = 'COMPLETED')
       or (normalized_outcome = status and status in ('FAILED', 'UNKNOWN', 'BLOCKED'))
     )
   returning id into changed_id;
  return jsonb_build_object('ok', changed_id is not null, 'reason', case when changed_id is null then 'claim_lost' else null end);
end;
$$;


--
-- Name: finish_student_overdue_card_charge(uuid, uuid, text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_student_overdue_card_charge(p_claim_id uuid, p_claim_token uuid, p_status text, p_provider_status text DEFAULT NULL::text, p_provider_http_status integer DEFAULT NULL::integer, p_last_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_status text := upper(trim(coalesce(p_status, '')));
  changed_id uuid;
begin
  if normalized_status not in ('SUCCEEDED', 'DECLINED', 'UNKNOWN', 'BLOCKED') then
    raise exception using errcode = '22023', message = 'invalid_overdue_charge_status';
  end if;

  update public.student_overdue_card_charge_claims
     set status = normalized_status,
         provider_status = nullif(trim(coalesce(p_provider_status, '')), ''),
         provider_http_status = p_provider_http_status,
         last_error = nullif(left(coalesce(p_last_error, ''), 500), ''),
         completed_at = case
           when normalized_status in ('SUCCEEDED', 'DECLINED', 'BLOCKED') then now()
           else null
         end,
         lease_expires_at = now(),
         updated_at = now()
   where id = p_claim_id
     and claim_token = p_claim_token
     and (
       (normalized_status = 'SUCCEEDED' and status in ('PROCESSING', 'SUBMITTING', 'UNKNOWN'))
       or (normalized_status = 'BLOCKED' and status in ('PROCESSING', 'SUBMITTING'))
       or (normalized_status in ('DECLINED', 'UNKNOWN') and status = 'SUBMITTING')
       or status = normalized_status
     )
   returning id into changed_id;

  return jsonb_build_object(
    'ok', changed_id is not null,
    'reason', case when changed_id is null then 'claim_lost' else null end
  );
end;
$$;


--
-- Name: finish_wolfie_ai_request(uuid, uuid, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_wolfie_ai_request(p_student_id uuid, p_request_key uuid, p_lease_token uuid, p_status text, p_response_payload jsonb DEFAULT '{}'::jsonb, p_error_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.finish_wolfie_ai_request(
    private.active_tenant_id(p_student_id),
    p_student_id,
    p_request_key,
    p_lease_token,
    p_status,
    p_response_payload,
    p_error_code
  );
$$;


--
-- Name: finish_wolfie_ai_request(text, uuid, uuid, uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_wolfie_ai_request(p_tenant_id text, p_student_id uuid, p_request_key uuid, p_lease_token uuid, p_status text, p_response_payload jsonb DEFAULT '{}'::jsonb, p_error_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request public.wolfie_ai_requests%rowtype;
begin
  if p_tenant_id is null
     or pg_catalog.btrim(p_tenant_id) = ''
     or p_student_id is null
     or p_request_key is null
     or p_lease_token is null then
    raise exception 'invalid_ai_request_identity';
  end if;
  if p_status is null or p_status not in ('COMPLETED', 'FAILED') then
    raise exception 'invalid_ai_final_status';
  end if;
  if pg_catalog.pg_column_size(
    coalesce(p_response_payload, '{}'::jsonb)
  ) > 1048576 then
    raise exception 'ai_response_payload_too_large';
  end if;

  if not exists (
    select 1
      from public.profiles as profile
      join public.tenant_memberships as membership
        on membership.user_id = profile.id
       and membership.tenant_id = p_tenant_id
       and membership.status = 'ACTIVE'
       and membership.role = 'STUDENT'
     where profile.id = p_student_id
       and profile.role = 'STUDENT'
  ) then
    raise exception 'student_active_tenant_membership_not_found';
  end if;

  select *
    into v_request
    from public.wolfie_ai_requests as request
   where request.tenant_id = p_tenant_id
     and request.student_id = p_student_id
     and request.request_key = p_request_key
   for update;

  if not found then
    raise exception 'ai_request_not_found';
  end if;

  if v_request.status = 'COMPLETED' then
    return pg_catalog.jsonb_build_object(
      'alreadyFinished', true,
      'status', v_request.status,
      'tenantId', v_request.tenant_id,
      'requestKey', v_request.request_key,
      'operation', v_request.operation,
      'attemptCount', v_request.attempt_count,
      'responsePayload', v_request.response_payload,
      'errorCode', v_request.error_code
    );
  end if;

  if v_request.status <> 'PROCESSING'
     or v_request.lease_token <> p_lease_token then
    raise exception 'ai_lease_not_owned';
  end if;

  update public.wolfie_ai_requests
     set status = p_status,
         response_payload = case
           when p_status = 'COMPLETED'
             then coalesce(p_response_payload, '{}'::jsonb)
           else '{}'::jsonb
         end,
         error_code = case
           when p_status = 'FAILED'
             then pg_catalog.left(
               coalesce(p_error_code, 'AI_PROVIDER_FAILED'),
               120
             )
           else null
         end,
         lease_expires_at = pg_catalog.now(),
         completed_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where id = v_request.id
   returning * into v_request;

  return pg_catalog.jsonb_build_object(
    'alreadyFinished', false,
    'status', v_request.status,
    'tenantId', v_request.tenant_id,
    'requestKey', v_request.request_key,
    'operation', v_request.operation,
    'attemptCount', v_request.attempt_count,
    'responsePayload', v_request.response_payload,
    'errorCode', v_request.error_code
  );
end;
$$;


