$$;


--
-- Name: freeze_asaas_enrollment_payment_request(uuid, uuid, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_asaas_enrollment_payment_request(p_attempt_id uuid, p_claim_token uuid, p_due_date date, p_description text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.asaas_provider_creation_attempts%rowtype;
  normalized_description text := nullif(trim(coalesce(p_description, '')), '');
  expected_snapshot jsonb;
  frozen_due_date date;
begin
  if p_attempt_id is null
     or p_due_date is null
     or normalized_description is null
     or length(normalized_description) > 500
  then
    raise exception using
      errcode = '22023',
      message = 'invalid_enrollment_payment_request_snapshot';
  end if;

  select attempt.*
    into attempt_row
    from public.asaas_provider_creation_attempts as attempt
   where attempt.id = p_attempt_id
   for update;

  if not found
     or attempt_row.operation <> 'PAYMENT_CREATE'
     or attempt_row.logical_key not like 'enrollment-fee:%'
     or (
       attempt_row.status <> 'SUCCEEDED'
       and attempt_row.claim_token is distinct from p_claim_token
     )
  then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  if attempt_row.request_snapshot = '{}'::jsonb then
    expected_snapshot := jsonb_build_object(
      'kind', 'ENROLLMENT_PAYMENT',
      'version', 1,
      'dueDate', p_due_date::text,
      'description', normalized_description,
      'subscription', null
    );
    update public.asaas_provider_creation_attempts
       set request_snapshot = expected_snapshot,
           updated_at = now()
     where id = attempt_row.id;
  else
    expected_snapshot := attempt_row.request_snapshot;
  end if;

  begin
    frozen_due_date := (expected_snapshot ->> 'dueDate')::date;
  exception when others then
    return jsonb_build_object(
      'ok', false,
      'reason', 'request_snapshot_invalid'
    );
  end;

  if expected_snapshot ->> 'kind' is distinct from 'ENROLLMENT_PAYMENT'
     or expected_snapshot ->> 'version' is distinct from '1'
     or expected_snapshot ->> 'description' is distinct from normalized_description
     or not (expected_snapshot ? 'subscription')
     or jsonb_typeof(expected_snapshot -> 'subscription') is distinct from 'null'
     or frozen_due_date is null
  then
    return jsonb_build_object(
      'ok', false,
      'reason', 'request_snapshot_mismatch'
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'request_snapshot', expected_snapshot,
    'due_date', frozen_due_date::text
  );
end;
$$;


--
-- Name: frequencia_efetiva(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.frequencia_efetiva(p_student uuid) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select coalesce(
    nullif((select count(distinct b.day_of_week || b.time_slot)
              from public.bookings b
             where b.student_id = p_student and b.status = 'SCHEDULED'), 0),
    nullif((regexp_replace(coalesce((select class_frequency from public.profiles where id = p_student), ''),
                           '\D', '', 'g'))::int, 0),
    0
  )::int;
$$;


--
-- Name: generate_affiliate_code(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_affiliate_code(p_owner_id uuid, p_owner_type text, p_tenant_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_code TEXT;
    v_existing RECORD;
    v_attempts INTEGER := 0;
BEGIN
    -- Check if user already has an active code
    SELECT * INTO v_existing FROM public.affiliate_codes
    WHERE owner_id = p_owner_id AND tenant_id = p_tenant_id AND active = true;

    IF v_existing IS NOT NULL THEN
        RETURN jsonb_build_object('success', true, 'code', v_existing.code, 'existing', true);
    END IF;

    -- Generate unique 8-char code
    LOOP
        v_code := 'WW' || upper(substring(replace(encode(gen_random_bytes(6), 'base64'), '/', ''), 1, 6));
        EXIT WHEN NOT EXISTS (SELECT 1 FROM public.affiliate_codes WHERE code = v_code);
        v_attempts := v_attempts + 1;
        IF v_attempts > 10 THEN
            RETURN jsonb_build_object('success', false, 'error', 'CODE_GENERATION_FAILED');
        END IF;
    END LOOP;

    INSERT INTO public.affiliate_codes (code, owner_id, owner_type, tenant_id)
    VALUES (v_code, p_owner_id, p_owner_type, p_tenant_id);

    RETURN jsonb_build_object('success', true, 'code', v_code, 'existing', false);
END;
$$;


--
-- Name: generate_monthly_student_payments(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_monthly_student_payments(p_tenant_id text, p_period_start date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  period_start date := date_trunc('month', p_period_start)::date;
  period_end date := (
    date_trunc('month', p_period_start) + interval '1 month'
  )::date;
  candidate record;
  locked_student record;
  payment_due_date date;
  inserted_count integer := 0;
  eligible_count integer := 0;
  inserted_now integer := 0;
  period_claim public.asaas_student_billing_period_claims%rowtype;
  period_source_key text;
  monthly_provider_id text;
begin
  if normalized_tenant is null or p_period_start is null then
    raise exception using
      errcode = '22023',
      message = 'tenant_and_period_required';
  end if;
  if not exists (
    select 1 from public.tenants as tenant
     where tenant.id = normalized_tenant
  ) then
    raise exception using errcode = '23503', message = 'tenant_not_found';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'monthly-student-payments:' || normalized_tenant || ':' ||
        period_start::text,
      0
    )
  );

  for candidate in
    select student.id
      from public.profiles as student
      join public.tenant_memberships as membership
        on membership.user_id = student.id
       and membership.tenant_id = normalized_tenant
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
     where student.role = 'STUDENT'
       and student.tenant_id = normalized_tenant
       and student.status = 'Ativo'
       and lower(trim(coalesce(student.lifecycle_status, ''))) = 'active'
       and coalesce(student.monthly_fee, 0) > 0
     order by student.id
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'student-billing-lifecycle:' || normalized_tenant || ':' ||
          candidate.id::text,
        0
      )
    );

    select
      student.id,
      student.monthly_fee,
      student.due_day
    into locked_student
      from public.profiles as student
      join public.tenant_memberships as membership
        on membership.user_id = student.id
       and membership.tenant_id = normalized_tenant
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
     where student.id = candidate.id
       and student.role = 'STUDENT'
       and student.tenant_id = normalized_tenant
       and student.status = 'Ativo'
       and lower(trim(coalesce(student.lifecycle_status, ''))) = 'active'
       and coalesce(student.monthly_fee, 0) > 0
       and (
         select count(*)
           from public.tenant_memberships as exact_membership
          where exact_membership.user_id = student.id
       ) = 1
       and not exists (
         select 1
           from public.student_offboarding_operations as operation
          where operation.tenant_id = normalized_tenant
            and operation.student_id = student.id
            and operation.status in (
              'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
              'UNKNOWN', 'BLOCKED'
            )
       )
       and not exists (
         select 1
           from public.student_account_deletion_claims as deletion
          where deletion.tenant_id = normalized_tenant
            and deletion.student_id = student.id
            and deletion.status in (
              'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
              'UNKNOWN', 'BLOCKED'
            )
       )
     for update of student, membership;
    if not found then
      continue;
    end if;

    eligible_count := eligible_count + 1;
    payment_due_date := make_date(
      extract(year from period_start)::integer,
      extract(month from period_start)::integer,
      least(
        greatest(coalesce(locked_student.due_day, 10), 1),
        extract(day from (period_end - interval '1 day'))::integer
      )
    );

    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'student-billing-period-month:' || normalized_tenant || ':' ||
          locked_student.id::text || ':' || period_start::text,
        0
      )
    );

    if exists (
      select 1
        from public.student_payments as existing
       where existing.student_id = locked_student.id
         and existing.tenant_id = normalized_tenant
         and existing.due_date >= period_start
         and existing.due_date < period_end
    ) then
      continue;
    end if;
    if exists (
      select 1
        from public.asaas_student_billing_period_claims as billing_claim
       where billing_claim.tenant_id = normalized_tenant
         and billing_claim.student_id = locked_student.id
         and billing_claim.due_date >= period_start
         and billing_claim.due_date < period_end
    ) then
      continue;
    end if;

    period_source_key := 'monthly-ledger:' || locked_student.id::text || ':' ||
      to_char(period_start, 'YYYY-MM');
    monthly_provider_id := 'MANUAL_MONTHLY_' ||
      to_char(period_start, 'YYYYMM') || '_' ||
      replace(locked_student.id::text, '-', '');

    insert into public.asaas_student_billing_period_claims (
      tenant_id,
      student_id,
      due_date,
      source,
      source_key,
      request_fingerprint,
      status,
      claim_token,
      lease_expires_at,
      provider_entity_id,
      updated_at
    ) values (
      normalized_tenant,
      locked_student.id,
      payment_due_date,
      'MONTHLY_LEDGER',
      period_source_key,
      pg_catalog.encode(
        extensions.digest(
          pg_catalog.convert_to(
            period_source_key || ':' || locked_student.monthly_fee::text,
            'UTF8'
          ),
          'sha256'
        ),
        'hex'
      ),
      'BOUND',
      gen_random_uuid(),
      now(),
      monthly_provider_id,
      now()
    ) on conflict (tenant_id, student_id, due_date) do nothing;

    select billing_claim.* into period_claim
      from public.asaas_student_billing_period_claims as billing_claim
     where billing_claim.tenant_id = normalized_tenant
       and billing_claim.student_id = locked_student.id
       and billing_claim.due_date = payment_due_date
     for update;
    if not found
       or period_claim.source is distinct from 'MONTHLY_LEDGER'
       or period_claim.source_key is distinct from period_source_key
       or period_claim.status is distinct from 'BOUND'
       or period_claim.provider_entity_id is distinct from monthly_provider_id
    then
      continue;
    end if;

    insert into public.student_payments (
      student_id,
      tenant_id,
      value,
      amount_cents,
      due_date,
      status,
      billing_type,
      asaas_payment_id,
      automation_key,
      description,
      created_at,
      updated_at
    )
    select
      locked_student.id,
      normalized_tenant,
      locked_student.monthly_fee,
      round(locked_student.monthly_fee * 100)::integer,
      payment_due_date,
      case when current_date > payment_due_date then 'OVERDUE' else 'PENDING' end,
      'MANUAL',
      monthly_provider_id,
      'monthly:' || normalized_tenant || ':' || locked_student.id::text || ':' ||
        to_char(period_start, 'YYYY-MM'),
      'Mensalidade ' || to_char(period_start, 'MM/YYYY'),
      now(),
      now()
     where not exists (
       select 1
         from public.student_payments as existing
        where existing.student_id = locked_student.id
          and existing.tenant_id = normalized_tenant
          and existing.due_date >= period_start
          and existing.due_date < period_end
     )
    on conflict (automation_key) where automation_key is not null do nothing;
    get diagnostics inserted_now = row_count;
    inserted_count := inserted_count + inserted_now;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'tenant_id', normalized_tenant,
    'period_start', period_start,
    'eligible', eligible_count,
    'created', inserted_count,
    'skipped', greatest(eligible_count - inserted_count, 0)
  );
end;
$$;


--
-- Name: gestao_alunos_sem_cobranca(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gestao_alunos_sem_cobranca(p_month text, p_tenant text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH com_aula AS (
    SELECT v.student_id, count(*)::int AS aulas, max(t.full_name) AS prof
      FROM v_payable_class_logs v JOIN profiles t ON t.id = v.teacher_id
     WHERE t.tenant_id = p_tenant AND to_char(v.class_date,'YYYY-MM') = p_month
       AND v.student_id IS NOT NULL
     GROUP BY 1
  ), cobrado AS (
    SELECT DISTINCT sp.student_id FROM student_payments sp
     WHERE sp.tenant_id = p_tenant AND sp.student_id IS NOT NULL
       AND to_char(COALESCE(sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM') = p_month
  ), faltando AS (
    SELECT p.full_name, c.prof, c.aulas, COALESCE(p.monthly_fee,0) AS mensalidade
      FROM com_aula c JOIN profiles p ON p.id = c.student_id
     WHERE NOT EXISTS (SELECT 1 FROM cobrado x WHERE x.student_id = c.student_id)
  )
  SELECT jsonb_build_object(
    'mes', p_month,
    'alunos', (SELECT count(*)::int FROM faltando),
    'aulas',  (SELECT COALESCE(sum(aulas),0)::int FROM faltando),
    'receita_nao_faturada', (SELECT round(COALESCE(sum(mensalidade),0),2) FROM faltando),
    'sem_mensalidade_cadastrada', (SELECT count(*)::int FROM faltando WHERE mensalidade = 0),
    'detalhe', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'aluno', trim(full_name), 'professor', prof, 'aulas', aulas, 'mensalidade', mensalidade)
        ORDER BY mensalidade DESC, aulas DESC) FROM faltando), '[]'::jsonb),
    -- Causa raiz, não sintoma: aluno sem assinatura nunca vai gerar cobrança.
    'causa_raiz_sem_assinatura_ativa', alunos_sem_assinatura(p_tenant)
  );
$$;


--
-- Name: gestao_change_booking_schedule(text, uuid, uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gestao_change_booking_schedule(p_tenant text, p_actor_id uuid, p_booking_id uuid, p_expected_student_id uuid, p_day_of_week text, p_time_slot text, p_group_jid text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_actor_role text;
  v_actor_name text;
  v_teacher_name text;
  v_student_name text;
  v_day text;
  v_day_number integer;
  v_time text;
  v_notification_id uuid;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'service_role_required';
  END IF;
  IF p_tenant IS NULL OR p_booking_id IS NULL
     OR p_expected_student_id IS NULL
     OR coalesce(length(btrim(p_request_id)), 0) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'parametros_invalidos');
  END IF;

  SELECT membership.role, actor.full_name
    INTO v_actor_role, v_actor_name
    FROM public.tenant_memberships AS membership
    JOIN public.profiles AS actor ON actor.id = membership.user_id
   WHERE membership.user_id = p_actor_id
     AND membership.tenant_id = p_tenant
     AND membership.status = 'ACTIVE'
     AND membership.role IN ('SCHOOL_ADMIN', 'COORDINATOR')
     AND lower(coalesce(actor.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
   LIMIT 1;
  IF v_actor_role IS NULL AND NOT private.management_group_execution_authorized(p_tenant, p_actor_id, p_request_id,
    jsonb_build_object('tipo','alterar_horario_aluno','booking_id',p_booking_id,'student_id',p_expected_student_id,'novo_dia',p_day_of_week,'novo_horario',p_time_slot), p_group_jid) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'actor_not_allowed';
  END IF;

  SELECT booking.*
    INTO v_booking
    FROM public.bookings AS booking
   WHERE booking.id = p_booking_id
   FOR UPDATE;
  IF NOT FOUND OR v_booking.tenant_id IS DISTINCT FROM p_tenant THEN
    RETURN jsonb_build_object('ok', false, 'error', 'aula_nao_encontrada');
  END IF;
  IF v_booking.student_id IS DISTINCT FROM p_expected_student_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'aula_nao_pertence_ao_aluno');
  END IF;
  IF upper(coalesce(v_booking.status, '')) <> 'SCHEDULED' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'aula_nao_ativa');
  END IF;
  IF v_booking.date IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'ocorrencia_pontual_exige_remarcacao_por_data'
    );
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles AS teacher
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = teacher.id
       AND membership.tenant_id = p_tenant
       AND membership.role = 'TEACHER'
       AND membership.status = 'ACTIVE'
     WHERE teacher.id = v_booking.teacher_id
       AND teacher.role = 'TEACHER'
       AND lower(coalesce(teacher.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
  ) OR NOT EXISTS (
    SELECT 1
      FROM public.profiles AS student
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = student.id
       AND membership.tenant_id = p_tenant
       AND membership.role = 'STUDENT'
       AND membership.status = 'ACTIVE'
     WHERE student.id = v_booking.student_id
       AND student.role = 'STUDENT'
       AND lower(coalesce(student.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'vinculos_da_aula_invalidos');
  END IF;

  v_day := CASE public.fold_accents(btrim(coalesce(p_day_of_week, '')))
    WHEN 'domingo' THEN 'Domingo'
    WHEN 'segunda' THEN 'Segunda'
    WHEN 'terca' THEN 'Terça'
    WHEN 'quarta' THEN 'Quarta'
    WHEN 'quinta' THEN 'Quinta'
    WHEN 'sexta' THEN 'Sexta'
    WHEN 'sabado' THEN 'Sábado'
    ELSE NULL
  END;
  v_day_number := CASE v_day
    WHEN 'Domingo' THEN 0 WHEN 'Segunda' THEN 1 WHEN 'Terça' THEN 2
    WHEN 'Quarta' THEN 3 WHEN 'Quinta' THEN 4 WHEN 'Sexta' THEN 5
    WHEN 'Sábado' THEN 6 ELSE NULL
  END;
  v_time := left(btrim(coalesce(p_time_slot, '')), 5);
  IF v_day IS NULL OR v_time !~ '^(0[0-9]|1[0-9]|2[0-3]):(00|30)$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'novo_horario_invalido');
  END IF;

  IF public.fold_accents(v_booking.day_of_week) = public.fold_accents(v_day)
     AND left(v_booking.time_slot, 5) = v_time THEN
    RETURN jsonb_build_object(
      'ok', true, 'changed', false, 'booking_id', v_booking.id,
      'day_of_week', v_day, 'time_slot', v_time
    );
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'schedule:teacher:' || v_booking.teacher_id::text || ':' ||
      public.fold_accents(v_day) || ':' || v_time,
      0
    )
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'schedule:student:' || v_booking.student_id::text || ':' ||
      public.fold_accents(v_day) || ':' || v_time,
      0
    )
  );

  IF NOT EXISTS (
    SELECT 1
      FROM public.teacher_availability AS availability
     WHERE availability.tenant_id = p_tenant
       AND availability.teacher_id = v_booking.teacher_id
       AND availability.day_of_week = v_day_number
       AND (
         availability.start_time = v_time::time
         OR (
           availability.end_time IS NOT NULL
           AND availability.start_time <= v_time::time
           AND availability.end_time > v_time::time
         )
       )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'professor_sem_disponibilidade');
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.bookings AS conflict
     WHERE conflict.id <> v_booking.id
       AND conflict.tenant_id = p_tenant
       AND conflict.teacher_id = v_booking.teacher_id
       AND upper(coalesce(conflict.status, '')) = 'SCHEDULED'
       AND public.fold_accents(conflict.day_of_week) = public.fold_accents(v_day)
       AND left(conflict.time_slot, 5) = v_time
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'conflito_professor');
  END IF;
  IF EXISTS (
    SELECT 1
      FROM public.bookings AS conflict
     WHERE conflict.id <> v_booking.id
       AND conflict.tenant_id = p_tenant
       AND conflict.student_id = v_booking.student_id
       AND upper(coalesce(conflict.status, '')) = 'SCHEDULED'
       AND public.fold_accents(conflict.day_of_week) = public.fold_accents(v_day)
       AND left(conflict.time_slot, 5) = v_time
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'conflito_aluno');
  END IF;
  IF EXISTS (
    SELECT 1
      FROM public.class_coverages AS coverage
     WHERE coverage.tenant_id = p_tenant
       AND coverage.cover_teacher_id = v_booking.teacher_id
       AND left(coverage.class_time, 5) = v_time
       AND extract(dow FROM coverage.class_date)::integer = v_day_number
       AND (
         coverage.class_date::text || ' ' ||
         left(coverage.class_time, 5) || ':00-03'
       )::timestamptz > now()
       AND (
         v_booking.start_date IS NULL
         OR coverage.class_date >= v_booking.start_date
       )
       AND (
         lower(coverage.status) = 'confirmed'
         OR (
           lower(coverage.status) = 'pending'
           AND now() < coalesce(
             coverage.invite_expires_at,
             (
               coverage.class_date::text || ' ' ||
               left(coverage.class_time, 5) || ':00-03'
             )::timestamptz
           )
         )
       )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'conflito_cobertura_ativa');
  END IF;

  SELECT profile.full_name INTO v_teacher_name
    FROM public.profiles AS profile
   WHERE profile.id = v_booking.teacher_id;
  SELECT profile.full_name INTO v_student_name
    FROM public.profiles AS profile
   WHERE profile.id = v_booking.student_id;
  IF v_teacher_name IS NULL OR v_student_name IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'vinculos_da_aula_invalidos');
  END IF;

  UPDATE public.bookings
     SET day_of_week = v_day,
         time_slot = v_time
   WHERE id = v_booking.id
     AND tenant_id = p_tenant
     AND student_id = p_expected_student_id;

  INSERT INTO public.audit_logs (
    tenant_id, user_id, user_role, action, resource_type, resource_id,
    old_values, new_values, diff
  ) VALUES (
    p_tenant, p_actor_id, v_actor_role,
    'booking_schedule_changed_via_management_group', 'booking',
    v_booking.id::text,
    jsonb_build_object(
      'day_of_week', v_booking.day_of_week,
      'time_slot', left(v_booking.time_slot, 5),
      'teacher_id', v_booking.teacher_id,
      'student_id', v_booking.student_id
    ),
    jsonb_build_object(
      'day_of_week', v_day,
      'time_slot', v_time,
      'teacher_id', v_booking.teacher_id,
      'student_id', v_booking.student_id,
      'request_id', left(btrim(p_request_id), 200)
    ),
    jsonb_build_object(
      'day_of_week', jsonb_build_array(v_booking.day_of_week, v_day),
      'time_slot', jsonb_build_array(left(v_booking.time_slot, 5), v_time)
    )
  );

  IF coalesce(p_group_jid, '') ~ '^[0-9]{8,25}@g[.]us$' THEN
    INSERT INTO public.notification_queue (
      tenant_id, teacher_id, student_id, student_name, student_phone,
      message_body, scheduled_for, status, source_id, source_type,
      notification_kind
    ) VALUES (
      p_tenant, v_booking.teacher_id, v_booking.student_id, v_student_name,
      p_group_jid,
      format(
        E'🔄 *ALTERAÇÃO DE AULA*\n\n👨‍🏫 Professor: *%s*\n👤 Aluno: *%s*\n\nAntes: %s às %s\nAgora: *%s às %s*\n\nAlterado por: %s',
        v_teacher_name, v_student_name, v_booking.day_of_week,
        left(v_booking.time_slot, 5), v_day, v_time,
        coalesce(v_actor_name, v_actor_role)
      ),
      now(), 'pending', v_booking.id, 'BOOKING_SCHEDULE',
      'SCHEDULE_CHANGE_GROUP'
    )
    RETURNING id INTO v_notification_id;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'changed', true,
    'booking_id', v_booking.id,
    'old_day', v_booking.day_of_week,
    'old_time', left(v_booking.time_slot, 5),
    'day_of_week', v_day,
    'time_slot', v_time,
    'notification_queued', v_notification_id IS NOT NULL
  );
END;
$_$;


--
-- Name: gestao_create_coverage_invite(text, uuid, uuid, uuid, date, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gestao_create_coverage_invite(p_tenant text, p_actor_id uuid, p_booking_id uuid, p_cover_teacher_id uuid, p_class_date date, p_class_time text, p_reason text, p_request_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_booking public.bookings%ROWTYPE;
  v_absence public.teacher_absences%ROWTYPE;
  v_coverage public.class_coverages%ROWTYPE;
  v_time text;
  v_day_number integer;
  v_day_name text;
  v_actor_role text;
  v_original_name text;
  v_cover_name text;
  v_cover_phone text;
  v_student_name text;
  v_token text;
  v_class_start timestamptz;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'service_role_required';
  END IF;

  IF p_tenant IS NULL OR p_booking_id IS NULL
     OR p_cover_teacher_id IS NULL OR p_class_date IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'parametros_invalidos');
  END IF;
  IF p_class_date < (now() AT TIME ZONE 'America/Sao_Paulo')::date
     OR p_class_date >
          (now() AT TIME ZONE 'America/Sao_Paulo')::date + 90 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'data_fora_da_janela');
  END IF;
  IF coalesce(length(btrim(p_reason)), 0) NOT BETWEEN 3 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'motivo_invalido');
  END IF;
  IF coalesce(length(btrim(p_request_id)), 0) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'request_id_invalido');
  END IF;
  v_time := left(btrim(coalesce(p_class_time, '')), 5);
  IF v_time !~ '^(0[0-9]|1[0-9]|2[0-3]):(00|30)$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'horario_invalido');
  END IF;

  SELECT membership.role
    INTO v_actor_role
    FROM public.tenant_memberships AS membership
    JOIN public.profiles AS actor
      ON actor.id = membership.user_id
   WHERE membership.user_id = p_actor_id
     AND membership.tenant_id = p_tenant
     AND membership.status = 'ACTIVE'
     AND membership.role IN ('SCHOOL_ADMIN', 'COORDINATOR')
     AND lower(coalesce(actor.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
   LIMIT 1;
  IF v_actor_role IS NULL AND NOT private.management_group_execution_authorized(p_tenant, p_actor_id, p_request_id,
    jsonb_build_object('tipo','cobertura_aula','booking_id',p_booking_id,'cover_teacher_id',p_cover_teacher_id,'class_date',p_class_date,'class_time',p_class_time,'motivo',p_reason)) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'actor_not_allowed';
  END IF;

  -- Idempotencia vem antes de criar qualquer artefato novo. A restricao UNIQUE
  -- continua como ultima barreira, mas o lock transforma chamadas simultaneas
  -- com a mesma chave em retry deterministico, sem erro 500 na perdedora.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'coverage-request:' || p_tenant || ':' ||
      left(btrim(p_request_id), 200),
      0
    )
  );
  SELECT coverage.*
    INTO v_coverage
    FROM public.class_coverages AS coverage
   WHERE coverage.tenant_id = p_tenant
     AND coverage.request_id = left(btrim(p_request_id), 200)
   FOR UPDATE;
  IF FOUND THEN
    IF v_coverage.booking_id IS DISTINCT FROM p_booking_id
       OR v_coverage.cover_teacher_id IS DISTINCT FROM p_cover_teacher_id
       OR v_coverage.class_date IS DISTINCT FROM p_class_date
       OR left(coalesce(v_coverage.class_time, ''), 5) IS DISTINCT FROM v_time THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'request_id_em_conflito'
      );
    END IF;
    IF lower(coalesce(v_coverage.status, '')) = 'pending'
       AND now() >= coalesce(
         v_coverage.invite_expires_at,
         (
           v_coverage.class_date::text || ' ' ||
           left(v_coverage.class_time, 5) || ':00-03'
         )::timestamptz
       ) THEN
      UPDATE public.class_coverages
         SET status = 'cancelled'
       WHERE id = v_coverage.id
         AND tenant_id = p_tenant
         AND lower(status) = 'pending';
      RETURN jsonb_build_object(
        'ok', true, 'idempotent', true,
        'coverage_id', v_coverage.id, 'status', 'cancelled'
      );
    END IF;
    SELECT profile.full_name
      INTO v_original_name
      FROM public.profiles AS profile
     WHERE profile.id = v_coverage.original_teacher_id;
    SELECT profile.full_name,
           CASE
             WHEN length(regexp_replace(
               coalesce(profile.attendance_phone, ''), '[^0-9]', '', 'g'
             )) BETWEEN 10 AND 15 THEN profile.attendance_phone
             WHEN length(regexp_replace(
               coalesce(profile.phone, ''), '[^0-9]', '', 'g'
             )) BETWEEN 10 AND 15 THEN profile.phone
             ELSE NULL
           END
      INTO v_cover_name, v_cover_phone
      FROM public.profiles AS profile
     WHERE profile.id = v_coverage.cover_teacher_id;
    SELECT profile.full_name
      INTO v_student_name
      FROM public.profiles AS profile
     WHERE profile.id = v_coverage.student_id;
    RETURN jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'coverage_id', v_coverage.id,
      'status', v_coverage.status,
      'token', v_coverage.token,
      'dispatched_at', v_coverage.dispatched_at,
      'class_date', v_coverage.class_date,
      'class_time', v_coverage.class_time,
      'student_name', btrim(coalesce(v_student_name, 'Aluno')),
      'original_teacher_name', btrim(coalesce(v_original_name, 'Professor')),
      'cover_teacher_name', btrim(coalesce(v_cover_name, 'Professor')),
      'cover_teacher_phone', v_cover_phone
    );
  END IF;

  SELECT booking.*
    INTO v_booking
    FROM public.bookings AS booking
   WHERE booking.id = p_booking_id
   FOR UPDATE;
  IF NOT FOUND OR v_booking.tenant_id IS DISTINCT FROM p_tenant THEN
    RETURN jsonb_build_object('ok', false, 'error', 'aula_nao_encontrada');
  END IF;
  IF upper(coalesce(v_booking.status, '')) <> 'SCHEDULED' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'aula_inativa');
  END IF;
  IF v_booking.teacher_id IS NULL OR v_booking.student_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'aula_sem_vinculos');
  END IF;
  IF v_booking.teacher_id = p_cover_teacher_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'mesmo_professor');
  END IF;

  IF left(coalesce(v_booking.time_slot, ''), 5) <> v_time THEN
    RETURN jsonb_build_object('ok', false, 'error', 'horario_nao_corresponde_aula');
  END IF;
  v_class_start := (
    p_class_date::text || ' ' || v_time || ':00-03'
  )::timestamptz;
  IF v_class_start <= now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'aula_no_passado');
  END IF;

  v_day_number := extract(dow FROM p_class_date)::integer;
  v_day_name := CASE v_day_number
    WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Segunda' WHEN 2 THEN 'Terca'
    WHEN 3 THEN 'Quarta' WHEN 4 THEN 'Quinta' WHEN 5 THEN 'Sexta'
    WHEN 6 THEN 'Sabado'
  END;
  IF v_booking.date IS NOT NULL THEN
    IF v_booking.date <> p_class_date THEN
      RETURN jsonb_build_object('ok', false, 'error', 'data_nao_corresponde_aula');
    END IF;
  ELSIF public.fold_accents(v_booking.day_of_week) <> lower(v_day_name) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'dia_nao_corresponde_aula');
  END IF;
  IF v_booking.date IS NULL
     AND v_booking.start_date IS NOT NULL
     AND p_class_date < v_booking.start_date THEN
    RETURN jsonb_build_object('ok', false, 'error', 'aula_antes_do_inicio');
  END IF;

  SELECT profile.full_name
    INTO v_original_name
   FROM public.profiles AS profile
   WHERE profile.id = v_booking.teacher_id
     AND profile.tenant_id = p_tenant
     AND profile.role = 'TEACHER'
     AND lower(coalesce(profile.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
     AND EXISTS (
       SELECT 1
         FROM public.tenant_memberships AS membership
        WHERE membership.user_id = profile.id
          AND membership.tenant_id = p_tenant
          AND membership.role = 'TEACHER'
          AND membership.status = 'ACTIVE'
     );
  IF v_original_name IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'professor_ausente_invalido');
  END IF;

  SELECT profile.full_name,
         CASE
           WHEN length(regexp_replace(
             coalesce(profile.attendance_phone, ''), '[^0-9]', '', 'g'
           )) BETWEEN 10 AND 15 THEN profile.attendance_phone
           WHEN length(regexp_replace(
             coalesce(profile.phone, ''), '[^0-9]', '', 'g'
           )) BETWEEN 10 AND 15 THEN profile.phone
           ELSE NULL
         END
    INTO v_cover_name, v_cover_phone
    FROM public.profiles AS profile
   WHERE profile.id = p_cover_teacher_id
     AND profile.tenant_id = p_tenant
     AND profile.role = 'TEACHER'
     AND lower(coalesce(profile.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
     AND EXISTS (
       SELECT 1
         FROM public.tenant_memberships AS membership
        WHERE membership.user_id = profile.id
          AND membership.tenant_id = p_tenant
          AND membership.role = 'TEACHER'
          AND membership.status = 'ACTIVE'
     );
  IF v_cover_name IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'substituto_invalido');
  END IF;
  IF EXISTS (
    SELECT membership.user_id
      FROM public.tenant_memberships AS membership
     WHERE membership.user_id IN (v_booking.teacher_id, p_cover_teacher_id)
       AND membership.role = 'TEACHER'
       AND membership.status = 'ACTIVE'
     GROUP BY membership.user_id
    HAVING count(DISTINCT membership.tenant_id) <> 1
  ) THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'cobertura_multiescola_nao_suportada'
    );
  END IF;
  IF NOT private.can_access_teacher_projection(v_booking.teacher_id, to_char(
       p_class_date, 'YYYY-MM'
     ))
     OR NOT private.can_access_teacher_projection(p_cover_teacher_id, to_char(
       p_class_date, 'YYYY-MM'
     )) THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'cobertura_multiescola_nao_suportada'
    );
  END IF;
  IF coalesce(regexp_replace(v_cover_phone, '[^0-9]', '', 'g'), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'substituto_sem_whatsapp');
  END IF;

  SELECT profile.full_name
    INTO v_student_name
    FROM public.profiles AS profile
   WHERE profile.id = v_booking.student_id
     AND profile.role = 'STUDENT'
     AND lower(coalesce(profile.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
     AND EXISTS (
       SELECT 1
         FROM public.tenant_memberships AS membership
        WHERE membership.user_id = profile.id
          AND membership.tenant_id = p_tenant
          AND membership.role = 'STUDENT'
          AND membership.status = 'ACTIVE'
     );
  IF v_student_name IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'aluno_invalido');
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.teacher_availability AS availability
     WHERE availability.tenant_id = p_tenant
       AND availability.teacher_id = p_cover_teacher_id
       AND availability.day_of_week = v_day_number
       AND (
         availability.start_time = v_time::time
         OR (
           availability.end_time IS NOT NULL
           AND availability.start_time <= v_time::time
           AND availability.end_time > v_time::time
         )
       )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'substituto_sem_disponibilidade');
  END IF;

  -- Um lock deterministico fecha a janela entre consultar conflitos e inserir.
  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'coverage:' || p_booking_id::text || ':' || p_class_date::text,
      0
    )
  );
  PERFORM pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'coverage-teacher:' || p_cover_teacher_id::text || ':' ||
      p_class_date::text || ':' || v_time,
      0
    )
  );
  PERFORM private.lock_coverage_absence_pair(
    v_booking.teacher_id,
    p_cover_teacher_id,
    p_class_date
  );

  IF EXISTS (
    SELECT 1
      FROM public.bookings AS conflict
     WHERE conflict.tenant_id = p_tenant
       AND conflict.teacher_id = p_cover_teacher_id
       AND upper(coalesce(conflict.status, '')) <> 'CANCELLED'
       AND left(coalesce(conflict.time_slot, ''), 5) = v_time
       AND (
         conflict.date = p_class_date
         OR (
           conflict.date IS NULL
           AND public.fold_accents(conflict.day_of_week) = lower(v_day_name)
           AND (
             conflict.start_date IS NULL
             OR conflict.start_date <= p_class_date
           )
         )
       )
  ) OR EXISTS (
    SELECT 1
      FROM public.reschedules AS reschedule
     WHERE reschedule.tenant_id = p_tenant
       AND reschedule.teacher_id = p_cover_teacher_id
       AND public.parse_lesson_date(reschedule.date) = p_class_date
       AND left(reschedule.time::text, 5) = v_time
       AND reschedule.used_at IS NULL
  ) OR EXISTS (
    SELECT 1
      FROM public.appointments AS appointment
     WHERE appointment.tenant_id = p_tenant
       AND (
         appointment.teacher_id = p_cover_teacher_id
         OR appointment.professor_id = p_cover_teacher_id
       )
       AND lower(coalesce(appointment.status, '')) IN ('scheduled', 'confirmed')
       AND abs(extract(epoch FROM (appointment.start_time - v_class_start))) < 1800
  ) OR EXISTS (
    SELECT 1
      FROM public.teacher_absences AS substitute_absence
     WHERE substitute_absence.tenant_id = p_tenant
       AND substitute_absence.teacher_id = p_cover_teacher_id
       AND lower(coalesce(substitute_absence.status, '')) = 'active'
       AND substitute_absence.starts_at::date <= p_class_date
       AND substitute_absence.ends_at::date >= p_class_date
  ) OR EXISTS (
    SELECT 1
      FROM public.class_coverages AS teacher_coverage
     WHERE teacher_coverage.tenant_id = p_tenant
       AND teacher_coverage.cover_teacher_id = p_cover_teacher_id
       AND teacher_coverage.class_date = p_class_date
       AND left(teacher_coverage.class_time, 5) = v_time
       AND (
         lower(teacher_coverage.status) = 'confirmed'
         OR (
           lower(teacher_coverage.status) = 'pending'
           AND now() < coalesce(
             teacher_coverage.invite_expires_at,
             (
               teacher_coverage.class_date::text || ' ' ||
               left(teacher_coverage.class_time, 5) || ':00-03'
             )::timestamptz
           )
         )
       )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'substituto_ocupado');
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.class_coverages AS coverage
     WHERE coverage.tenant_id = p_tenant
       AND coverage.booking_id = p_booking_id
       AND coverage.class_date = p_class_date
       AND (
         lower(coverage.status) = 'confirmed'
         OR (
           lower(coverage.status) = 'pending'
           AND now() < coalesce(
             coverage.invite_expires_at,
             (
               coverage.class_date::text || ' ' ||
               left(coverage.class_time, 5) || ':00-03'
             )::timestamptz
           )
         )
       )
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'cobertura_ja_existente');
  END IF;

  SELECT absence.*
    INTO v_absence
    FROM public.teacher_absences AS absence
   WHERE absence.tenant_id = p_tenant
     AND absence.teacher_id = v_booking.teacher_id
     AND lower(absence.status) = 'active'
     AND absence.starts_at::date <= p_class_date
     AND absence.ends_at::date >= p_class_date
   ORDER BY absence.created_at
   LIMIT 1
   FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO public.teacher_absences (
      tenant_id, teacher_id, starts_at, ends_at, reason, status
    ) VALUES (
      p_tenant, v_booking.teacher_id, p_class_date, p_class_date,
      btrim(p_reason), 'active'
    )
    RETURNING * INTO v_absence;
  END IF;

  v_token := encode(extensions.gen_random_bytes(16), 'hex');
  INSERT INTO public.class_coverages (
    tenant_id, original_teacher_id, cover_teacher_id, student_id,
    booking_id, absence_id, class_date, class_time, status, token,
    notes, dispatched_at, request_id, invite_expires_at
  ) VALUES (
    p_tenant, v_booking.teacher_id, p_cover_teacher_id, v_booking.student_id,
    p_booking_id, v_absence.id, p_class_date, v_time, 'pending', v_token,
    btrim(p_reason), NULL, left(btrim(p_request_id), 200),
    least(v_class_start, now() + interval '48 hours')
  )
  RETURNING * INTO v_coverage;

  INSERT INTO public.audit_logs (
    tenant_id, user_id, user_role, action, resource_type, resource_id,
    new_values
  ) VALUES (
    p_tenant, p_actor_id, v_actor_role,
    'coverage_requested_via_management_group', 'class_coverage',
    v_coverage.id::text,
    jsonb_build_object(
      'booking_id', p_booking_id,
      'student_id', v_booking.student_id,
      'original_teacher_id', v_booking.teacher_id,
      'cover_teacher_id', p_cover_teacher_id,
      'class_date', p_class_date,
      'class_time', v_time,
      'request_id', left(btrim(p_request_id), 200)
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'coverage_id', v_coverage.id,
    'absence_id', v_absence.id,
    'status', v_coverage.status,
    'token', v_token,
    'class_date', p_class_date,
    'class_time', v_time,
    'student_name', btrim(v_student_name),
    'original_teacher_name', btrim(v_original_name),
    'cover_teacher_name', btrim(v_cover_name),
    'cover_teacher_phone', v_cover_phone
  );
END;
$_$;


--
-- Name: gestao_faltas(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gestao_faltas(p_month text, p_tenant text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH aulas AS (
    SELECT cl.*, COALESCE(cl.subtype,'(não informado)') AS motivo
      FROM class_logs cl
     WHERE cl.tenant_id = p_tenant AND to_char(cl.class_date,'YYYY-MM') = p_month
  )
  SELECT jsonb_build_object(
    'mes', p_month,                     -- ← sem isto o dado é inutilizável
    'aulas_no_mes',        (SELECT count(*)::int FROM aulas),
    'faltas_de_aluno',     (SELECT count(*)::int FROM aulas WHERE presence = 'STUDENT_ABSENCE'),
    'faltas_de_professor', (SELECT count(*)::int FROM aulas WHERE presence = 'TEACHER_ABSENCE'),
    'reposicoes',          (SELECT count(*)::int FROM aulas WHERE subtype = 'REPOSIÇÃO'),
    'pct_falta_aluno',     (SELECT round(100.0 * count(*) FILTER (WHERE presence='STUDENT_ABSENCE')
                                          / NULLIF(count(*),0), 1) FROM aulas),
    'alunos_que_mais_faltaram_neste_mes', COALESCE((
      SELECT jsonb_agg(x ORDER BY (x->>'faltas')::int DESC) FROM (
        SELECT jsonb_build_object(
                 'aluno', trim(p.full_name), 'faltas', count(*)::int,
                 'motivos', (SELECT string_agg(DISTINCT a2.motivo, ', ')
                               FROM aulas a2 WHERE a2.student_id = a.student_id
                                AND a2.presence = 'STUDENT_ABSENCE')) AS x
          FROM aulas a JOIN profiles p ON p.id = a.student_id
         WHERE a.presence = 'STUDENT_ABSENCE' AND a.student_id IS NOT NULL
         GROUP BY a.student_id, p.full_name
         ORDER BY count(*) DESC LIMIT 8) y), '[]'::jsonb),
    'professores_que_faltaram_neste_mes', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('professor', trim(t.full_name), 'faltas', n) ORDER BY n DESC)
        FROM (SELECT a.teacher_id, count(*)::int AS n FROM aulas a
               WHERE a.presence = 'TEACHER_ABSENCE' GROUP BY 1) z
        JOIN profiles t ON t.id = z.teacher_id), '[]'::jsonb),
    'motivos_de_falta', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('motivo', motivo, 'vezes', n) ORDER BY n DESC)
        FROM (SELECT motivo, count(*)::int AS n FROM aulas
               WHERE presence = 'STUDENT_ABSENCE' GROUP BY 1 ORDER BY 2 DESC LIMIT 6) m), '[]'::jsonb)
  );
$$;


--
-- Name: gestao_financial_context(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gestao_financial_context(p_tenant text, p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_tenant, '')), '');
  normalized_month text := coalesce(
    nullif(pg_catalog.btrim(coalesce(p_month, '')), ''),
    pg_catalog.to_char(
      pg_catalog.now() at time zone 'America/Sao_Paulo',
      'YYYY-MM'
    )
  );
  month_start date;
  month_end date;
  receivables numeric := 0;
  delinquency jsonb := '{}'::jsonb;
  monthly_closures jsonb := '{}'::jsonb;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception using errcode = '42501', message = 'service_role_required';
  end if;
  if normalized_tenant is null
     or not exists (
       select 1 from public.tenants as tenant
        where tenant.id = normalized_tenant
     )
     or normalized_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$'
  then
    raise exception using
      errcode = '22023',
      message = 'invalid_management_financial_context_scope';
  end if;

  month_start := pg_catalog.to_date(normalized_month || '-01', 'YYYY-MM-DD');
  month_end := (month_start + interval '1 month')::date;
  if pg_catalog.to_char(month_start, 'YYYY-MM') <> normalized_month then
    raise exception using
      errcode = '22023',
      message = 'invalid_management_financial_context_scope';
  end if;

  -- These predicates deliberately mirror get_cashflow_unchecked(text). The
  -- only difference is that the trusted tenant is explicit instead of inferred
  -- from auth.uid(), which is null for a service_role Edge Function.
  select pg_catalog.jsonb_build_object(
           'total', pg_catalog.round(coalesce(sum(payment.value), 0), 2),
           'd1_30', pg_catalog.round(coalesce(sum(payment.value) filter (
             where current_date - payment.due_date between 1 and 30
           ), 0), 2),
           'd31_60', pg_catalog.round(coalesce(sum(payment.value) filter (
             where current_date - payment.due_date between 31 and 60
           ), 0), 2),
           'd60plus', pg_catalog.round(coalesce(sum(payment.value) filter (
             where current_date - payment.due_date > 60
           ), 0), 2),
           'count', count(*)::integer
         )
    into delinquency
    from public.student_payments as payment
   where payment.tenant_id = normalized_tenant
     and payment.status in ('OVERDUE', 'DUNNING_REQUESTED');

  select pg_catalog.round(coalesce(sum(payment.value), 0), 2)
    into receivables
    from public.student_payments as payment
   where payment.tenant_id = normalized_tenant
     and payment.status = 'PENDING'
     and payment.due_date >= month_start
     and payment.due_date < month_end;

  with requested_periods(label, period_start) as (
    values
      ('mes_consultado'::text, month_start),
      ('mes_anterior'::text, (month_start - interval '1 month')::date)
  )
  select coalesce(
           pg_catalog.jsonb_object_agg(
             period.label,
             case
               when closure.tenant_id is null then
                 pg_catalog.jsonb_build_object(
                   'mes', pg_catalog.to_char(period.period_start, 'YYYY-MM'),
                   'status', 'NOT_CALCULATED'
                 )
               else
                 pg_catalog.jsonb_build_object(
                   'mes', pg_catalog.to_char(period.period_start, 'YYYY-MM'),
                   'status', closure.status,
                   'atualizado_em', closure.updated_at,
                   'enviado_em', closure.sent_at,
                   'motivo_revisao', closure.review_reason,
                   'motivos_de_bloqueio', coalesce(
                     closure.snapshot -> 'blockers',
                     '[]'::jsonb
                   ),
                   'alunos', (
                     coalesce(closure.snapshot -> 'roster', '{}'::jsonb)
                       - 'items'
                   ) || pg_catalog.jsonb_build_object(
                     'pendentes', coalesce(
                       (
                         select pg_catalog.jsonb_agg(
                                  item.value order by item.value ->> 'student_name'
                                )
                           from pg_catalog.jsonb_array_elements(
                             coalesce(
                               closure.snapshot #> '{roster,items}',
                               '[]'::jsonb
                             )
                           ) as item(value)
                          where coalesce(item.value ->> 'status', '')
                                not in ('SETTLED', 'EXCLUDED')
                       ),
                       '[]'::jsonb
                     )
                   ),
                   'competencia', coalesce(
                     closure.snapshot -> 'competence',
                     '{}'::jsonb
                   ),
                   'caixa', coalesce(
                     closure.snapshot -> 'cash',
                     '{}'::jsonb
                   ),
                   'regras_rateio', coalesce(
                     closure.snapshot -> 'rules',
                     '{}'::jsonb
                   ),
                   'recebimentos_sem_aluno', coalesce(
                     (closure.snapshot ->> 'unclassified_cash_count')::integer,
                     0
                   ),
                   'conciliacoes_em_aberto', coalesce(
                     (closure.snapshot ->> 'open_reconciliation_count')::integer,
                     0
                   )
                 )
             end
           ),
           '{}'::jsonb
         )
    into monthly_closures
    from requested_periods as period
    left join public.monthly_payment_closures as closure
      on closure.tenant_id = normalized_tenant
     and closure.period_start = period.period_start;

  return pg_catalog.jsonb_build_object(
    'tenant_id', normalized_tenant,
    'mes', normalized_month,
    'inadimplencia', delinquency,
    'a_receber_no_mes', receivables,
    'fechamento_mensal', monthly_closures
  );
end;
$_$;


--
-- Name: gestao_lanca_ajuste(text, uuid, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gestao_lanca_ajuste(p_tenant text, p_teacher_id uuid, p_month text, p_descricao text, p_valor numeric, p_pedido_por text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_id uuid; v_sync boolean; v_teto numeric := 500;
BEGIN
  IF COALESCE(current_setting('request.jwt.claims', true)::json->>'role','') <> 'service_role' THEN
    RETURN jsonb_build_object('error','somente_pelo_assistente');
  END IF;
  IF p_month !~ '^\d{4}-\d{2}$' THEN RETURN jsonb_build_object('error','mes_invalido'); END IF;
  IF p_valor IS NULL OR p_valor = 0 THEN RETURN jsonb_build_object('error','valor_invalido'); END IF;
  IF abs(p_valor) > v_teto THEN
    RETURN jsonb_build_object('error','acima_do_teto','teto',v_teto);
  END IF;
  IF COALESCE(btrim(p_descricao),'') = '' THEN RETURN jsonb_build_object('error','motivo_obrigatorio'); END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_teacher_id
                   AND role = 'TEACHER' AND tenant_id = p_tenant) THEN
    RETURN jsonb_build_object('error','professor_invalido');
  END IF;

  INSERT INTO closing_adjustments (tenant_id, teacher_id, month_year, description, amount)
  VALUES (p_tenant, p_teacher_id, p_month,
          btrim(p_descricao) || COALESCE(' [via WhatsApp: ' || p_pedido_por || ']', ' [via WhatsApp]'),
          p_valor)
  RETURNING id INTO v_id;

  UPDATE teacher_closings SET total_amount = total_amount + p_valor, updated_at = now()
   WHERE teacher_id = p_teacher_id AND month_year = p_month AND status = 'PENDENTE';
  v_sync := FOUND;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'repasse_atualizado', v_sync);
END;
$_$;


--
-- Name: gestao_lanca_ajuste_idempotente(text, text, uuid, uuid, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gestao_lanca_ajuste_idempotente(p_tenant text, p_request_id text, p_actor_id uuid, p_teacher_id uuid, p_month text, p_descricao text, p_valor numeric, p_pedido_por text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_existing public.closing_adjustments%ROWTYPE;
  v_id uuid;
  v_sync boolean := false;
  v_refresh jsonb;
  v_actor_role text;
  v_actor_profile_role text;
  v_teto numeric := 500;
  v_request_id text := left(btrim(coalesce(p_request_id, '')), 200);
  v_closing_status text;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'service_role_required';
  END IF;
  IF p_tenant IS NULL OR p_teacher_id IS NULL
     OR length(v_request_id) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'parametros_invalidos');
  END IF;

  SELECT membership.role, actor.role
    INTO v_actor_role, v_actor_profile_role
    FROM public.tenant_memberships AS membership
    JOIN public.profiles AS actor ON actor.id = membership.user_id
   WHERE membership.user_id = p_actor_id
     AND membership.tenant_id = p_tenant
     AND membership.status = 'ACTIVE'
     AND membership.role IN ('SCHOOL_ADMIN', 'COORDINATOR')
     AND lower(coalesce(actor.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
   LIMIT 1;
  IF (v_actor_role IS NULL OR NOT (
    v_actor_role = 'SCHOOL_ADMIN' OR v_actor_profile_role = 'SUPER_ADMIN'
  )) AND NOT private.management_group_execution_authorized(p_tenant, p_actor_id, v_request_id,
    jsonb_build_object('tipo','ajuste_repasse','teacher_id',p_teacher_id,'mes',p_month,'valor',p_valor,'motivo',p_descricao)) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'actor_not_allowed';
  END IF;

  IF p_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'mes_invalido');
  END IF;
  IF p_valor IS NULL OR p_valor = 0 OR p_valor = 'NaN'::numeric THEN
    RETURN jsonb_build_object('ok', false, 'error', 'valor_invalido');
  END IF;
  IF abs(p_valor) > v_teto THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'acima_do_teto', 'teto', v_teto
    );
  END IF;
  IF length(btrim(coalesce(p_descricao, ''))) NOT BETWEEN 3 AND 200 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'motivo_invalido');
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles AS teacher
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = teacher.id
       AND membership.tenant_id = p_tenant
       AND membership.role = 'TEACHER'
       AND membership.status = 'ACTIVE'
     WHERE teacher.id = p_teacher_id
       AND teacher.role = 'TEACHER'
       AND lower(coalesce(teacher.lifecycle_status, '')) = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'professor_invalido');
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'management-adjustment:' || p_tenant || ':' || v_request_id,
      0
    )
  );
  PERFORM private.lock_teacher_closing_pair(
    p_tenant,
    p_month,
    p_teacher_id,
    NULL
  );
  SELECT adjustment.*
    INTO v_existing
    FROM public.closing_adjustments AS adjustment
   WHERE adjustment.tenant_id = p_tenant
     AND adjustment.request_id = v_request_id
   FOR UPDATE;
  IF FOUND THEN
    IF v_existing.teacher_id IS DISTINCT FROM p_teacher_id
       OR v_existing.month_year IS DISTINCT FROM p_month
       OR v_existing.amount IS DISTINCT FROM p_valor THEN
      RETURN jsonb_build_object('ok', false, 'error', 'request_id_em_conflito');
    END IF;
    RETURN jsonb_build_object(
      'ok', true,
      'id', v_existing.id,
      'idempotent', true,
      'repasse_atualizado', v_existing.closing_synced
    );
  END IF;

  SELECT closing.status
    INTO v_closing_status
    FROM public.teacher_closings AS closing
   WHERE closing.tenant_id = p_tenant
     AND closing.teacher_id = p_teacher_id
     AND closing.month_year = p_month
   ORDER BY closing.created_at
   LIMIT 1
   FOR UPDATE;
  IF v_closing_status IS NOT NULL AND v_closing_status <> 'PENDENTE' THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'fechamento_nao_pendente'
    );
  END IF;

  INSERT INTO public.closing_adjustments (
    tenant_id, teacher_id, month_year, description, amount, created_by,
    request_id, closing_synced
  ) VALUES (
    p_tenant,
    p_teacher_id,
    p_month,
    btrim(p_descricao) || ' [via WhatsApp: ' ||
      left(btrim(coalesce(p_pedido_por, 'gestor')), 80) || ']',
    p_valor,
    p_actor_id,
    v_request_id,
    false
  )
  RETURNING id INTO v_id;

  v_refresh := private.refresh_teacher_closing_snapshot(
    p_tenant,
    p_teacher_id,
    p_month,
    false
  );
  v_sync := coalesce((v_refresh ->> 'synced')::boolean, false);

  UPDATE public.closing_adjustments
     SET closing_synced = v_sync
   WHERE id = v_id;

  INSERT INTO public.audit_logs (
    tenant_id, user_id, user_role, action, resource_type, resource_id,
    new_values
  ) VALUES (
    p_tenant, p_actor_id, v_actor_role,
    'teacher_payout_adjusted_via_management_group', 'closing_adjustment',
    v_id::text,
    jsonb_build_object(
      'teacher_id', p_teacher_id,
      'month', p_month,
      'amount', p_valor,
      'request_id', v_request_id,
      'closing_synced', v_sync
    )
  );

  RETURN jsonb_build_object(
    'ok', true,
    'id', v_id,
    'idempotent', false,
    'repasse_atualizado', v_sync
  );
END;
$_$;


--
-- Name: gestao_lanca_conta(text, text, boolean, text, numeric, text, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gestao_lanca_conta(p_tenant text, p_request_id text, p_recorrente boolean, p_descricao text, p_valor numeric, p_account_code text, p_due_date date, p_start_month text DEFAULT NULL::text, p_pedido_por text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_claim_role text;
  v_allowed boolean;
  v_kind text;
  v_inserted int;
  v_start_month text;
  v_current_month text := to_char(current_date, 'YYYY-MM');
  v_day int;
  v_recurring_id uuid;
  v_transaction_id uuid;
  v_result jsonb;
  v_teto numeric := 10000;
BEGIN
  v_claim_role := COALESCE(
    current_setting('request.jwt.claims', true)::json->>'role', ''
  );
  IF v_claim_role <> 'service_role' THEN
    RETURN jsonb_build_object('error','somente_pelo_assistente');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM tenants WHERE id = p_tenant) THEN
    RETURN jsonb_build_object('error','escola_invalida');
  END IF;
  IF length(COALESCE(p_request_id,'')) NOT BETWEEN 8 AND 200 THEN
    RETURN jsonb_build_object('error','request_id_invalido');
  END IF;
  IF COALESCE(btrim(p_descricao),'') = '' THEN
    RETURN jsonb_build_object('error','descricao_obrigatoria');
  END IF;
  IF p_valor IS NULL OR p_valor <= 0 THEN
    RETURN jsonb_build_object('error','valor_invalido');
  END IF;
  IF p_valor > v_teto THEN
    RETURN jsonb_build_object('error','acima_do_teto','teto',v_teto);
  END IF;
  IF p_due_date IS NULL THEN
    RETURN jsonb_build_object('error','vencimento_obrigatorio');
  END IF;

  SELECT ledger_allowed, kind INTO v_allowed, v_kind
    FROM dre_accounts
   WHERE code = p_account_code AND is_active;
  IF v_allowed IS NULL OR v_kind NOT IN ('CUSTO','DESPESA','DEDUCAO') THEN
    RETURN jsonb_build_object('error','conta_invalida');
  END IF;
  IF NOT v_allowed THEN
    RETURN jsonb_build_object('error','conta_de_fonte_automatica');
  END IF;

  IF COALESCE(p_recorrente, false) THEN
    v_day := extract(day from p_due_date)::int;
    IF v_day NOT BETWEEN 1 AND 28 THEN
      RETURN jsonb_build_object('error','dia_invalido');
    END IF;
    v_start_month := COALESCE(p_start_month, to_char(p_due_date,'YYYY-MM'));
    IF v_start_month !~ '^\d{4}-\d{2}$' THEN
      RETURN jsonb_build_object('error','mes_inicial_invalido');
    END IF;
  END IF;

  -- Reserva o request_id antes de escrever dinheiro. Em duas confirmacoes
  -- simultaneas, a PK faz uma esperar a outra e somente uma cria lancamento.
  INSERT INTO gestao_finance_action_receipts
    (tenant_id, request_id, action_type, requested_by, result)
  VALUES
    (p_tenant, p_request_id,
     CASE WHEN COALESCE(p_recorrente,false) THEN 'conta_recorrente' ELSE 'conta_avulsa' END,
     NULLIF(left(btrim(COALESCE(p_pedido_por,'')), 80), ''),
     '{"processing":true}'::jsonb)
  ON CONFLICT (tenant_id, request_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  IF v_inserted = 0 THEN
    SELECT result INTO v_result
      FROM gestao_finance_action_receipts
     WHERE tenant_id = p_tenant AND request_id = p_request_id;
    RETURN COALESCE(v_result, '{}'::jsonb) || jsonb_build_object('ok',true,'duplicado',true);
  END IF;

  IF COALESCE(p_recorrente, false) THEN
    INSERT INTO recurring_expenses
      (tenant_id, label, amount, account_code, day_of_month, start_month,
       is_active, notes)
    VALUES
      (p_tenant, btrim(p_descricao), p_valor, p_account_code, v_day,
       v_start_month, true,
       'Cadastrada pelo grupo de gestao' ||
         CASE WHEN NULLIF(btrim(COALESCE(p_pedido_por,'')), '') IS NOT NULL
           THEN ' por ' || left(btrim(p_pedido_por),80) ELSE '' END)
    RETURNING id INTO v_recurring_id;

    -- Se ja vigora, materializa o mes atual agora. Nos meses seguintes o cron
    -- idempotente run_recurring_expenses assume o trabalho.
    IF v_start_month <= v_current_month THEN
      INSERT INTO financial_transactions
        (tenant_id, type, category, amount, amount_cents, description,
         occurred_at, account_code, recurring_expense_id, recurring_month)
      VALUES
        (p_tenant, 'SAIDA', 'despesa_recorrente', p_valor,
         round(p_valor * 100), btrim(p_descricao),
         make_date(extract(year from current_date)::int,
                   extract(month from current_date)::int, v_day)::timestamptz,
         p_account_code, v_recurring_id, v_current_month)
      RETURNING id INTO v_transaction_id;
    END IF;

    v_result := jsonb_build_object(
      'ok', true, 'tipo', 'conta_recorrente',
      'recurring_expense_id', v_recurring_id,
      'transaction_id', v_transaction_id,
      'mes_lancado', CASE WHEN v_transaction_id IS NOT NULL THEN v_current_month ELSE NULL END
    );
  ELSE
    INSERT INTO financial_transactions
      (tenant_id, type, category, amount, amount_cents, description,
       occurred_at, account_code)
    VALUES
      (p_tenant, 'SAIDA', 'conta_pagar_avulsa', p_valor,
       round(p_valor * 100), btrim(p_descricao),
       p_due_date::timestamptz, p_account_code)
    RETURNING id INTO v_transaction_id;

    v_result := jsonb_build_object(
      'ok', true, 'tipo', 'conta_avulsa',
      'transaction_id', v_transaction_id
    );
  END IF;

  UPDATE gestao_finance_action_receipts
     SET result = v_result
   WHERE tenant_id = p_tenant AND request_id = p_request_id;

  RETURN v_result;
END;
$_$;


--
-- Name: FUNCTION gestao_lanca_conta(p_tenant text, p_request_id text, p_recorrente boolean, p_descricao text, p_valor numeric, p_account_code text, p_due_date date, p_start_month text, p_pedido_por text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.gestao_lanca_conta(p_tenant text, p_request_id text, p_recorrente boolean, p_descricao text, p_valor numeric, p_account_code text, p_due_date date, p_start_month text, p_pedido_por text) IS 'Lanca conta avulsa ou recorrente confirmada no grupo de gestao; service_role, tenant-scoped e idempotente por request_id.';


--
-- Name: gestao_resolve_aluno(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gestao_resolve_aluno(p_tenant text, p_nome text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_termo text := public.fold_accents(btrim(coalesce(p_nome, '')));
  v_count integer;
  v_id uuid;
  v_nome text;
  v_candidates jsonb;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'service_role_required';
  END IF;
  IF length(v_termo) NOT BETWEEN 2 AND 100 THEN
    RETURN jsonb_build_object('error', 'nome_vazio');
  END IF;

  SELECT count(*), min(profile.full_name),
         jsonb_agg(btrim(profile.full_name) ORDER BY profile.full_name)
    INTO v_count, v_nome, v_candidates
    FROM public.profiles AS profile
    JOIN public.tenant_memberships AS membership
      ON membership.user_id = profile.id
     AND membership.tenant_id = p_tenant
     AND membership.role = 'STUDENT'
     AND membership.status = 'ACTIVE'
   WHERE profile.role = 'STUDENT'
     AND lower(coalesce(profile.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
     AND strpos(public.fold_accents(profile.full_name), v_termo) > 0;
  IF v_count = 0 THEN
    RETURN jsonb_build_object('error', 'aluno_nao_encontrado');
  END IF;
  IF v_count > 1 THEN
    RETURN jsonb_build_object(
      'error', 'aluno_ambiguo', 'candidatos', v_candidates
    );
  END IF;

  SELECT profile.id, btrim(profile.full_name)
    INTO v_id, v_nome
    FROM public.profiles AS profile
    JOIN public.tenant_memberships AS membership
      ON membership.user_id = profile.id
     AND membership.tenant_id = p_tenant
     AND membership.role = 'STUDENT'
     AND membership.status = 'ACTIVE'
   WHERE profile.role = 'STUDENT'
     AND lower(coalesce(profile.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
     AND strpos(public.fold_accents(profile.full_name), v_termo) > 0
   LIMIT 1;
  RETURN jsonb_build_object('ok', true, 'id', v_id, 'nome', v_nome);
END;
$$;


