    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT role FROM public.profiles WHERE id = auth.uid();
$$;


--
-- Name: get_auth_tenant_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_auth_tenant_id() RETURNS text
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT tenant_id FROM public.profiles WHERE id = auth.uid();
$$;


--
-- Name: get_authorized_guardian_directory(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_authorized_guardian_directory(p_tenant_id text) RETURNS TABLE(id uuid, full_name text, cpf text, email text, phone text, postal_code text, address text, address_number text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role text := public._my_role();
  v_tenant text := public._my_tenant_id();
begin
  if auth.uid() is null
     or p_tenant_id is null
     or not (
       v_role = 'SUPER_ADMIN'
       or (v_role = 'SCHOOL_ADMIN' and v_tenant = p_tenant_id)
     ) then
    raise exception 'guardian directory is not authorized'
      using errcode = '42501';
  end if;

  return query
  select
    profile.id,
    profile.full_name,
    profile.cpf,
    profile.email,
    profile.phone,
    profile.postal_code,
    profile.address,
    profile.address_number
  from public.profiles as profile
  where profile.tenant_id = p_tenant_id
    and profile.cpf is not null
    and profile.cpf <> ''
  order by profile.full_name, profile.id;
end;
$$;


--
-- Name: get_authorized_profile_dependents(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_authorized_profile_dependents(p_guardian_id uuid) RETURNS TABLE(id uuid, full_name text, email text, monthly_fee numeric, subscription_id text, status_financial text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role text := public._my_role();
  v_tenant text := public._my_tenant_id();
  v_guardian_tenant text;
begin
  select profile.tenant_id
    into v_guardian_tenant
    from public.profiles as profile
   where profile.id = p_guardian_id;

  if auth.uid() is null
     or v_guardian_tenant is null
     or not (
       v_role = 'SUPER_ADMIN'
       or (v_role = 'SCHOOL_ADMIN' and v_tenant = v_guardian_tenant)
     ) then
    raise exception 'dependent billing directory is not authorized'
      using errcode = '42501';
  end if;

  return query
  select
    profile.id,
    profile.full_name,
    profile.email,
    profile.monthly_fee,
    profile.subscription_id,
    profile.status_financial
  from public.profiles as profile
  where profile.tenant_id = v_guardian_tenant
    and profile.guardian_id = p_guardian_id
  order by profile.full_name, profile.id;
end;
$$;


--
-- Name: get_authorized_profile_private(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_authorized_profile_private(p_profile_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_role text := public._my_role();
  v_tenant text := public._my_tenant_id();
  v_target uuid := coalesce(p_profile_id, auth.uid());
  v_result jsonb;
begin
  if v_uid is null or v_target is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select pg_catalog.jsonb_build_object(
    'id', profile.id,
    'cpf', profile.cpf,
    'rg', profile.rg,
    'birth_date', profile.birth_date,
    'cnpj', profile.cnpj,
    'cnpj_company_name', profile.cnpj_company_name,
    'address', profile.address,
    'address_number', profile.address_number,
    'postal_code', profile.postal_code,
    'guardian_name', profile.guardian_name,
    'guardian_cpf', profile.guardian_cpf,
    'guardian_email', profile.guardian_email,
    'guardian_phone', profile.guardian_phone,
    'guardian_id', profile.guardian_id,
    'private_notes', profile.private_notes,
    'bank_name', profile.bank_name,
    'agency', profile.agency,
    'account_number', profile.account_number,
    'pix_key', profile.pix_key,
    'pix_key_type', profile.pix_key_type,
    'hourly_rate', profile.hourly_rate,
    'commission_rate', profile.commission_rate,
    'monthly_fee', profile.monthly_fee,
    'monthly_tuition', profile.monthly_tuition,
    'fidelity_plan', profile.fidelity_plan,
    'due_day', profile.due_day,
    'paid_through', profile.paid_through,
    'prepaid_months', profile.prepaid_months,
    'status_financial', profile.status_financial,
    'first_overdue_at', profile.first_overdue_at,
    'enrollment_fee', profile.enrollment_fee,
    'enrollment_fee_paid', profile.enrollment_fee_paid,
    'enrollment_payment_id', profile.enrollment_payment_id,
    'asaas_customer_id', profile.asaas_customer_id,
    'subscription_id', profile.subscription_id,
    'asaas_subscription_status', profile.asaas_subscription_status,
    'asaas_subscription_end_date', profile.asaas_subscription_end_date,
    'asaas_subscription_synced_at', profile.asaas_subscription_synced_at,
    'signature_ip', profile.signature_ip,
    'signature_url', profile.signature_url,
    'contract_url', profile.contract_url,
    'student_signature_url', profile.student_signature_url,
    'signed_document_url', profile.signed_document_url,
    'wise_wolf_signature_token', profile.wise_wolf_signature_token,
    'typed_signature', profile.typed_signature,
    'signature_hash', profile.signature_hash,
    'user_ip', profile.user_ip
  )
    into v_result
    from public.profiles as profile
   where profile.id = v_target
     and (
       profile.id = v_uid
       or v_role = 'SUPER_ADMIN'
       or (
         v_role = 'SCHOOL_ADMIN'
         and profile.tenant_id = v_tenant
       )
     );

  if v_result is null then
    raise exception 'profile private fields are not authorized'
      using errcode = '42501';
  end if;

  return v_result;
end;
$$;


--
-- Name: get_authorized_student_billing_summary(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_authorized_student_billing_summary(p_tenant_id text) RETURNS TABLE(id uuid, monthly_fee numeric, status_financial text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role text := public._my_role();
  v_tenant text := public._my_tenant_id();
begin
  if auth.uid() is null
     or p_tenant_id is null
     or not (
       v_role = 'SUPER_ADMIN'
       or (v_role = 'SCHOOL_ADMIN' and v_tenant = p_tenant_id)
     ) then
    raise exception 'student billing summary is not authorized'
      using errcode = '42501';
  end if;

  return query
  select profile.id, profile.monthly_fee, profile.status_financial
  from public.profiles as profile
  where profile.tenant_id = p_tenant_id
    and profile.role = 'STUDENT'
    and pg_catalog.lower(pg_catalog.btrim(coalesce(
      profile.lifecycle_status,
      ''
    ))) = 'active'
  order by profile.id;
end;
$$;


--
-- Name: get_cashflow(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cashflow(p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object('error', 'sem_permissao');
  END IF;
  RETURN public.get_cashflow_unchecked(p_month);
END;
$$;


--
-- Name: get_cashflow_unchecked(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_cashflow_unchecked(p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_tenant text;
  v_month text;
  v_month_start date;
  v_month_end date;
  v_in numeric;
  v_teacher numeric;
  v_vendor numeric;
  v_referral numeric;
  v_expense numeric;
begin
  select p.tenant_id
    into v_tenant
    from public.profiles p
   where p.id = auth.uid();

  v_month := coalesce(p_month, to_char(current_date, 'YYYY-MM'));
  if v_month !~ '^\d{4}-\d{2}$' then
    raise exception 'Mes invalido (use YYYY-MM)';
  end if;
  v_month_start := to_date(v_month || '-01', 'YYYY-MM-DD');
  if to_char(v_month_start, 'YYYY-MM') <> v_month then
    raise exception 'Mes invalido (use YYYY-MM)';
  end if;
  v_month_end := (v_month_start + interval '1 month')::date;

  select coalesce(sum(ft.amount), 0)
    into v_in
    from public.financial_transactions ft
   where ft.tenant_id = v_tenant
     and ft.type = 'ENTRADA'
     and ft.category is distinct from 'aporte_ou_movimentacao'
     and ft.occurred_at >= v_month_start
     and ft.occurred_at < v_month_end;

  select coalesce(sum(tc.total_amount), 0)
    into v_teacher
    from public.teacher_closings tc
   where tc.tenant_id = v_tenant
     and tc.status = 'PAGO'
     and coalesce(tc.paid_at, (tc.month_year || '-01')::date) >= v_month_start
     and coalesce(tc.paid_at, (tc.month_year || '-01')::date) < v_month_end;

  select coalesce(sum(vc.amount_brl), 0)
    into v_vendor
    from public.vendor_commissions vc
   where vc.tenant_id = v_tenant
     and vc.status = 'PAID'
     and vc.paid_at >= v_month_start
     and vc.paid_at < v_month_end;

  select coalesce(sum(rr.amount_brl), 0)
    into v_referral
    from public.referral_rewards rr
   where rr.tenant_id = v_tenant
     and rr.status = 'PAID'
     and rr.paid_at >= v_month_start
     and rr.paid_at < v_month_end;

  select coalesce(sum(ft.amount), 0)
    into v_expense
    from public.financial_transactions ft
   where ft.tenant_id = v_tenant
     and ft.type = 'SAIDA'
     and ft.category is distinct from 'teacher_payout'
     and ft.category is distinct from 'estorno_aporte_ou_movimentacao'
     and ft.account_code is distinct from '5.1.01'
     and ft.occurred_at >= v_month_start
     and ft.occurred_at < v_month_end;

  return jsonb_build_object(
    'month', v_month,
    'entradas', v_in,
    'saidas', jsonb_build_object(
      'professores', v_teacher,
      'vendedores', v_vendor,
      'indicacoes', v_referral,
      'despesas', v_expense,
      'total', v_teacher + v_vendor + v_referral + v_expense
    ),
    'saldo', v_in - (v_teacher + v_vendor + v_referral + v_expense),
    -- Valores ainda devidos permanecem brutos: estorno de dinheiro ja
    -- realizado nao reduz o principal de outra fatura em aberto.
    'inadimplencia', (
      select jsonb_build_object(
        'total', coalesce(sum(sp.value), 0),
        'd1_30', coalesce(sum(sp.value) filter (
          where current_date - sp.due_date between 1 and 30
        ), 0),
        'd31_60', coalesce(sum(sp.value) filter (
          where current_date - sp.due_date between 31 and 60
        ), 0),
        'd60plus', coalesce(sum(sp.value) filter (
          where current_date - sp.due_date > 60
        ), 0),
        'count', count(*)
      )
      from public.student_payments sp
      where sp.tenant_id = v_tenant
        and sp.status in ('OVERDUE', 'DUNNING_REQUESTED')
    ),
    'a_receber', (
      select coalesce(sum(sp.value), 0)
        from public.student_payments sp
       where sp.tenant_id = v_tenant
         and sp.status = 'PENDING'
         and sp.due_date >= v_month_start
         and sp.due_date < v_month_end
    ),
    'serie', (
      select jsonb_agg(
        jsonb_build_object('mes', series.month_year, 'entradas', series.amount)
        order by series.month_year
      )
      from (
        select
          to_char(months.month_start, 'YYYY-MM') as month_year,
          coalesce((
            select sum(ft.amount)
              from public.financial_transactions ft
             where ft.tenant_id = v_tenant
               and ft.type = 'ENTRADA'
               and ft.category is distinct from 'aporte_ou_movimentacao'
               and ft.occurred_at >= months.month_start
               and ft.occurred_at < months.month_start + interval '1 month'
          ), 0) as amount
        from generate_series(
          date_trunc('month', current_date) - interval '5 months',
          date_trunc('month', current_date),
          interval '1 month'
        ) as months(month_start)
      ) series
    )
  );
end;
$_$;


--
-- Name: FUNCTION get_cashflow_unchecked(p_month text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_cashflow_unchecked(p_month text) IS 'Implementacao owner-only do caixa por evento: ENTRADAS brutas no credito e SAIDAS de estorno na data real do provedor; valores em aberto permanecem brutos.';


--
-- Name: get_confirmation_public(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_confirmation_public(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_requested public.attendance_confirmations%rowtype;
  c public.attendance_confirmations%rowtype;
  v_now timestamptz := pg_catalog.now();
  v_expired boolean;
  v_cancelled boolean;
  v_can_correct boolean;
begin
  select ac.*
    into v_requested
    from public.attendance_confirmations ac
   where ac.token = p_token
   for update;

  if not found then
    return pg_catalog.jsonb_build_object('found', false);
  end if;

  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = coalesce(v_requested.canonical_confirmation_id, v_requested.id)
   for update;

  if not found then
    return pg_catalog.jsonb_build_object('found', false);
  end if;

  v_expired := v_requested.token_expires_at is null
    or v_requested.token_expires_at <= v_now;
  v_cancelled := c.status = 'CANCELLED' or c.delivery_status = 'CANCELLED';
  v_can_correct := not v_expired
    and not v_cancelled
    and c.status not in ('RESOLVED_PAID', 'RESOLVED_UNPAID')
    and (
      c.student_response is null
      or c.response_editable_until > v_now
    );

  if v_expired or v_cancelled then
    return pg_catalog.jsonb_build_object(
      'found', true,
      'already', c.student_response is not null,
      'status', c.status,
      'student_response', c.student_response,
      'allowed_responses', '[]'::jsonb,
      'can_correct', false,
      'editable_until', c.response_editable_until,
      'expired', v_expired,
      'cancelled', v_cancelled
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'found', true,
    'teacher_name', c.teacher_name,
    'student_name', c.student_name,
    'class_date', c.class_date,
    'class_time', c.class_time,
    'already', c.student_response is not null,
    'status', c.status,
    'student_response', c.student_response,
    'allowed_responses', pg_catalog.jsonb_build_array(
      'STUDENT_PRESENT',
      'TEACHER_NO_SHOW',
      'STUDENT_SELF_ABSENT',
      'CANCELLED_RESCHEDULED'
    ),
    'can_correct', v_can_correct,
    'editable_until', c.response_editable_until,
    'expired', false,
    'cancelled', false
  );
end;
$$;


--
-- Name: get_contract_public(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_contract_public(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  caller_id uuid := (SELECT auth.uid());
  caller_tenant_id text := private.active_tenant_id(caller_id);
  caller_role text := private.active_tenant_role(caller_id);
  contract_record record;
BEGIN
  IF caller_id IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501';
  END IF;

  IF caller_tenant_id IS NULL THEN
    RAISE EXCEPTION 'active_tenant_required' USING ERRCODE = '42501';
  END IF;
  IF caller_id IS DISTINCT FROM p_id
    AND coalesce(caller_role, '') NOT IN ('SCHOOL_ADMIN', 'SUPER_ADMIN')
  THEN
    RAISE EXCEPTION 'cross_tenant_contract_denied' USING ERRCODE = '42501';
  END IF;

  SELECT
    contract.party_snapshot,
    contract.legal_snapshot,
    contract.commercial_snapshot,
    contract.accepted_at,
    contract.accepted_ip
  INTO contract_record
  FROM public.tenant_contract_records AS contract
  WHERE contract.user_id = p_id
    AND contract.tenant_id = caller_tenant_id
    AND contract.contract_kind = 'TEACHER';

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  RETURN jsonb_build_object(
    'full_name', contract_record.party_snapshot ->> 'fullName',
    'rg', contract_record.party_snapshot ->> 'rg',
    'cpf', contract_record.party_snapshot ->> 'cpf',
    'address', contract_record.party_snapshot ->> 'address',
    'birth_date', contract_record.party_snapshot ->> 'birthDate',
    'hourly_rate', (contract_record.commercial_snapshot ->> 'hourlyRate')::numeric,
    'contract_accepted', true,
    'accepted_at', contract_record.accepted_at,
    'user_ip', contract_record.accepted_ip,
    'schoolInfo', contract_record.legal_snapshot
  );
END;
$$;


--
-- Name: get_dre_report_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dre_report_settings() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; r record;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;

  SELECT * INTO r FROM dre_report_settings WHERE tenant_id = v_tenant;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('configurado', false, 'is_active', false,
                              'cadencia','semanal','dia_semana',1,'destino','');
  END IF;
  RETURN jsonb_build_object(
    'configurado', true,
    'destino', r.destino, 'cadencia', r.cadencia, 'dia_semana', r.dia_semana,
    'is_active', r.is_active, 'ultimo_envio_at', r.ultimo_envio_at);
END;
$$;


--
-- Name: get_enrollment_progress(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_enrollment_progress(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  caller_id uuid := (SELECT auth.uid());
  enrollment_offer record;
BEGIN
  IF caller_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'UNAUTHORIZED');
  END IF;

  SELECT
    offer.tenant_id,
    offer.invite_security_version,
    offer.revoked_at,
    offer.consumed_at,
    offer.expires_at
  INTO enrollment_offer
  FROM public.offers AS offer
  WHERE offer.id = p_offer_id
    AND offer.kind = 'ENROLLMENT'
    AND (
      offer.processing_by = caller_id
      OR offer.consumed_by = caller_id
    );

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', true, 'status', 'NOT_STARTED');
  END IF;
  IF enrollment_offer.invite_security_version < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'OFFER_REVOKED');
  END IF;
  IF NOT private.tenant_is_operational(enrollment_offer.tenant_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'TENANT_UNAVAILABLE');
  END IF;
  IF enrollment_offer.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'OFFER_REVOKED');
  END IF;
  IF enrollment_offer.consumed_at IS NULL
    AND (
      enrollment_offer.expires_at IS NULL
      OR enrollment_offer.expires_at <= now()
    )
  THEN
    RETURN jsonb_build_object('success', false, 'error', 'OFFER_EXPIRED');
  END IF;

  RETURN public.get_enrollment_progress_authoritative_impl(p_offer_id);
END;
$$;


--
-- Name: get_enrollment_progress_authoritative_impl(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_enrollment_progress_authoritative_impl(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
  o public.offers%rowtype;
  p public.profiles%rowtype;
begin
  if v_user is null then
    return jsonb_build_object('success', false, 'error', 'UNAUTHORIZED');
  end if;

  select *
    into o
    from public.offers
   where id = p_offer_id
     and kind = 'ENROLLMENT'
     and (processing_by = v_user or consumed_by = v_user);
  if not found then
    return jsonb_build_object('success', true, 'status', 'NOT_STARTED');
  end if;

  select * into p from public.profiles where id = v_user;

  return jsonb_build_object(
    'success', true,
    'status', case
      when o.consumed_at is not null then 'COMPLETED'
      else o.processing_state
    end,
    'correlation_id', o.processing_correlation_id,
    'billing_type', o.metadata ->> 'billing_type',
    'error_code', o.processing_error_code,
    'error_message', o.processing_error_message,
    'profile', jsonb_strip_nulls(jsonb_build_object(
      'full_name', p.full_name,
      'email', p.email,
      'phone', p.phone,
      'cpf', p.cpf,
      'postal_code', p.postal_code,
      'address', p.address,
      'address_number', p.address_number,
      'typed_signature', p.typed_signature
    ))
  );
end;
$$;


--
-- Name: get_invite_offer_public(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_invite_offer_public(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  invite_offer record;
BEGIN
  SELECT
    offer.id,
    offer.kind,
    offer.tenant_id,
    offer.payload,
    offer.expires_at,
    offer.consumed_at,
    offer.revoked_at,
    offer.invite_security_version,
    offer.invite_claim_token,
    offer.invite_claimed_at
  INTO invite_offer
  FROM public.offers AS offer
  WHERE offer.id = p_offer_id
    AND offer.kind IN ('VENDOR_INVITE', 'TEACHER_INVITE');

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'OFFER_NOT_FOUND');
  END IF;
  IF invite_offer.consumed_at IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'OFFER_CONSUMED');
  END IF;
  IF invite_offer.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'OFFER_REVOKED');
  END IF;
  IF invite_offer.invite_security_version < 1 THEN
    RETURN jsonb_build_object('error', 'OFFER_REVOKED');
  END IF;
  IF invite_offer.expires_at IS NULL OR invite_offer.expires_at <= now() THEN
    RETURN jsonb_build_object('error', 'OFFER_EXPIRED');
  END IF;
  IF NOT private.tenant_is_operational(invite_offer.tenant_id) THEN
    RETURN jsonb_build_object('error', 'TENANT_UNAVAILABLE');
  END IF;
  IF invite_offer.invite_claim_token IS NOT NULL
    AND coalesce(invite_offer.invite_claimed_at, '-infinity'::timestamptz)
      > now() - interval '15 minutes'
  THEN
    RETURN jsonb_build_object('error', 'OFFER_PROCESSING');
  END IF;

  RETURN coalesce(invite_offer.payload, '{}'::jsonb)
    || jsonb_build_object(
      'kind', invite_offer.kind,
      'tenantId', invite_offer.tenant_id,
      '_offerId', invite_offer.id
    );
END;
$$;


--
-- Name: get_mei_radar(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_mei_radar(p_tenant text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_ano int := extract(year FROM now())::int;
  v_ini date := make_date(extract(year FROM now())::int, 1, 1);
  v_mes_atual_ini date := date_trunc('month', now())::date;
  v_meses_completos numeric := GREATEST(extract(month FROM now())::numeric - 1, 1);
  v_total numeric := 0;          -- ano inteiro (inclui mês corrente parcial)
  v_fechado numeric := 0;        -- só meses fechados
  v_asaas numeric := 0;
  v_manual numeric := 0;
  v_3m numeric := 0;             -- últimos 3 meses FECHADOS
  v_por_mes jsonb;
  v_teto numeric := 81000;
  v_tolerancia numeric := 97200;
  v_media numeric;
  v_ritmo numeric;
  v_proj_media numeric;
  v_proj_ritmo numeric;
BEGIN
  IF NOT mei_radar_caller_allowed() THEN
    RETURN jsonb_build_object('error', 'sem_permissao');
  END IF;

  -- receita bruta sem sobreposição: espelho Asaas + entradas manuais não vinculadas
  -- ↓ ESTA é a correção: torna a função chamável mais de uma vez na transação.
  DROP TABLE IF EXISTS _receitas;
  CREATE TEMP TABLE _receitas ON COMMIT DROP AS
    SELECT COALESCE(paid_at, payment_date)::date AS dia, value AS v
    FROM student_payments
    WHERE tenant_id = p_tenant AND status IN ('RECEIVED','RECEIVED_IN_CASH','CONFIRMED')
      AND COALESCE(paid_at, payment_date) >= v_ini
    UNION ALL
    SELECT occurred_at::date, amount
    FROM financial_transactions
    WHERE tenant_id = p_tenant AND type='ENTRADA' AND student_payment_id IS NULL
      AND occurred_at >= v_ini;

  SELECT COALESCE(sum(v),0) INTO v_total FROM _receitas;
  SELECT COALESCE(sum(v),0) INTO v_fechado FROM _receitas WHERE dia < v_mes_atual_ini;
  SELECT COALESCE(sum(v),0) INTO v_3m FROM _receitas
   WHERE dia >= (v_mes_atual_ini - interval '3 months') AND dia < v_mes_atual_ini;

  SELECT COALESCE(sum(value),0) INTO v_asaas FROM student_payments
  WHERE tenant_id = p_tenant AND status IN ('RECEIVED','RECEIVED_IN_CASH','CONFIRMED')
    AND COALESCE(paid_at, payment_date) >= v_ini;
  v_manual := v_total - v_asaas;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('mes', mes, 'valor', valor) ORDER BY mes), '[]'::jsonb)
  INTO v_por_mes
  FROM (SELECT to_char(dia,'YYYY-MM') AS mes, round(sum(v),2) AS valor FROM _receitas GROUP BY 1) m;

  v_media := v_fechado / v_meses_completos;
  v_ritmo := v_3m / LEAST(3, v_meses_completos);
  v_proj_media := round(v_media * 12, 2);
  -- acumulado fechado + ritmo recente para os meses restantes (incluindo o corrente)
  v_proj_ritmo := round(v_fechado + v_ritmo * (12 - v_meses_completos), 2);

  RETURN jsonb_build_object(
    'ano', v_ano,
    'receita_acumulada', round(v_total, 2),
    'receita_asaas', round(v_asaas, 2),
    'receita_manual', round(v_manual, 2),
    'por_mes', v_por_mes,
    'media_mensal', round(v_media, 2),
    'ritmo_3m', round(v_ritmo, 2),
    'projecao_media', v_proj_media,
    'projecao_ritmo_3m', v_proj_ritmo,
    'teto', v_teto,
    'teto_tolerancia', v_tolerancia,
    'pct_teto', round(100 * v_total / v_teto, 1),
    'pct_projecao_teto', round(100 * GREATEST(v_proj_media, v_proj_ritmo) / v_teto, 1),
    'das_mensal', 86.05,
    'simples_anexo3_estimado_ano', round(GREATEST(v_proj_media, v_proj_ritmo) * 0.06, 2)
  );
END;
$$;


--
-- Name: get_monthly_payment_closure_status(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_monthly_payment_closure_status(p_period_start date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  caller public.profiles%rowtype;
  target_period date := pg_catalog.date_trunc(
    'month',
    coalesce(
      p_period_start,
      pg_catalog.now() at time zone 'America/Sao_Paulo'
    )
  )::date;
  target_tenant text;
begin
  select profile.* into caller
    from public.profiles as profile
   where profile.id = (select auth.uid());
  if not found or caller.role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    raise exception using errcode = '42501', message = 'not_authorized';
  end if;
  target_tenant := caller.tenant_id;
  return coalesce(
    (
      select jsonb_build_object(
        'tenant_id', closure.tenant_id,
        'period_start', closure.period_start,
        'status', closure.status,
        'snapshot', closure.snapshot,
        'ready_at', closure.ready_at,
        'sent_at', closure.sent_at,
        'review_reason', closure.review_reason
      )
        from public.monthly_payment_closures as closure
       where closure.tenant_id = target_tenant
         and closure.period_start = target_period
    ),
    jsonb_build_object(
      'tenant_id', target_tenant,
      'period_start', target_period,
      'status', 'NOT_CALCULATED'
    )
  );
end;
$$;


