--
-- Name: get_my_referral_info(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_referral_info() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; st tenant_referral_settings%ROWTYPE; v_reward numeric;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  SELECT * INTO st FROM tenant_referral_settings WHERE tenant_id = v_tenant;
  v_reward := CASE WHEN v_role='TEACHER' THEN COALESCE(st.teacher_reward_brl, st.reward_amount_brl)
                   ELSE COALESCE(st.student_reward_brl, st.reward_amount_brl) END;
  RETURN jsonb_build_object(
    'enabled', COALESCE(st.enabled, false),
    'reward_brl', COALESCE(v_reward, 0),
    'converted', (SELECT count(*) FROM referral_rewards WHERE referrer_id = auth.uid()),
    'earned_total', (SELECT COALESCE(sum(amount_brl),0) FROM referral_rewards WHERE referrer_id = auth.uid()),
    'credit_balance', (SELECT COALESCE(sum(amount),0) FROM student_credits WHERE student_id = auth.uid() AND applied_at IS NULL AND (expires_at IS NULL OR expires_at > now()))
  );
END;
$$;


--
-- Name: get_my_teacher_directory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_teacher_directory() RETURNS TABLE(id uuid, full_name text, phone text, avatar_url text, meeting_link text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH caller AS (
    SELECT profile.id, profile.tenant_id, profile.professor_id, profile.professor_id2
    FROM public.profiles AS profile
    WHERE profile.id = (SELECT auth.uid())
      AND profile.role = 'STUDENT'
  ), teacher_ids AS (
    SELECT professor_id AS teacher_id FROM caller WHERE professor_id IS NOT NULL
    UNION
    SELECT professor_id2 FROM caller WHERE professor_id2 IS NOT NULL
    UNION
    SELECT booking.teacher_id
    FROM public.bookings AS booking
    JOIN caller ON caller.id = booking.student_id
  )
  SELECT teacher.id, teacher.full_name, teacher.phone, teacher.avatar_url, teacher.meeting_link
  FROM public.profiles AS teacher
  JOIN teacher_ids ON teacher_ids.teacher_id = teacher.id
  JOIN caller ON caller.tenant_id = teacher.tenant_id
  WHERE teacher.role = 'TEACHER';
$$;


