    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    tenant.id,
    tenant.name,
    tenant.domain,
    tenant.branding,
    tenant.student_limit,
    tenant.teacher_limit,
    tenant.whatsapp_enabled,
    tenant.school_info
  FROM public.tenants AS tenant
