--
-- Name: get_my_tenant_leaderboard(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_tenant_leaderboard(p_limit integer DEFAULT 5) RETURNS TABLE(full_name text, xp integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    COALESCE(NULLIF(student.league_display_name, ''), split_part(student.full_name, ' ', 1)) AS full_name,
    COALESCE(student.xp, 0) AS xp
  FROM public.profiles AS caller
  JOIN public.profiles AS student
    ON student.tenant_id = caller.tenant_id
   AND student.role = 'STUDENT'
  WHERE caller.id = (SELECT auth.uid())
    AND caller.role = 'STUDENT'
  ORDER BY COALESCE(student.xp, 0) DESC, student.id
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 5), 1), 20);
$$;


--
-- Name: get_my_tenant_memberships(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_tenant_memberships() RETURNS TABLE(tenant_id text, tenant_name text, domain text, branding jsonb, role text, is_primary boolean, is_active boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    tenant.id,
    tenant.name,
    tenant.domain,
    tenant.branding,
    membership.role,
    membership.is_primary,
    tenant.id = private.active_tenant_id((SELECT auth.uid()))
  FROM public.tenant_memberships AS membership
  JOIN public.tenants AS tenant ON tenant.id = membership.tenant_id
  WHERE membership.user_id = (SELECT auth.uid())
    AND membership.status = 'ACTIVE'
  ORDER BY
    (tenant.id = private.active_tenant_id((SELECT auth.uid()))) DESC,
    membership.is_primary DESC,
    tenant.name,
    tenant.id;
$$;


--
-- Name: get_nf_issuance_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_nf_issuance_context() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_uid uuid := (select auth.uid());
  v_tenant text;
  v_settings public.tenant_nf_settings%rowtype;
  v_pending jsonb;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'error', 'Não autenticado');
  end if;

  select tenant_id into v_tenant from public.profiles where id = v_uid;
  if v_tenant is null then
    return jsonb_build_object('ok', false, 'error', 'Perfil sem escola');
  end if;

  select * into v_settings
    from public.tenant_nf_settings
   where tenant_id = v_tenant and is_active;

  -- O fechamento autorizado MAIS RECENTE ainda sem nota.
  --
  -- ⚠️ Era `asc` (mais antigo primeiro) até o teste contra produção mostrar o
  -- estrago: um professor tem cinco fechamentos pagos de 2026-02 a 2026-06 sem
  -- NF, e o tour anunciaria "seu pagamento de fevereiro foi autorizado" por
  -- R$ 7,50 — seis meses atrasado e trivial. O pedido é "quando houver um NOVO
  -- pagamento autorizado", então o recente é o certo.
  --
  -- Os antigos não somem: cada um reaparece, um por vez, conforme o mais novo é
  -- resolvido. Cobrar NF atrasada em lote é trabalho do diretor no InvoiceManager,
  -- não de um modal que abre na frente do professor.
  select jsonb_build_object(
           'id', c.id,
           'month_year', c.month_year,
           'total_amount', c.total_amount,
           'total_lessons', c.total_lessons,
           'status', c.status
         )
    into v_pending
    from public.teacher_closings c
   where c.teacher_id = v_uid
     and public.nf_tour_is_pending(c.status, c.nf_link, c.nf_tour_ack_at)
   order by c.month_year desc
   limit 1;

  return jsonb_build_object(
    'ok', true,
    -- `configured` false = a escola ainda não preencheu o tomador. A tela mostra
    -- um aviso para procurar a coordenação em vez de instruções pela metade.
    'configured', v_settings.tenant_id is not null
                  and coalesce(btrim(v_settings.cnpj), '') <> '',
    'settings', case
      when v_settings.tenant_id is null then null
      else jsonb_build_object(
        'cnpj', v_settings.cnpj,
        'razao_social', v_settings.razao_social,
        'nome_fantasia', v_settings.nome_fantasia,
        'codigo_tributacao', v_settings.codigo_tributacao,
        'descricao_tributacao', v_settings.descricao_tributacao,
        'descricao_servico', v_settings.descricao_servico,
        'portal_url', v_settings.portal_url,
        'observacoes', v_settings.observacoes
      )
    end,
    'pending', v_pending
  );
end;
$_$;


--
-- Name: get_offer_public(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_offer_public(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  enrollment_offer record;
  school_info jsonb;
BEGIN
  SELECT
    offer.id,
    offer.tenant_id,
    offer.payload,
    offer.revoked_at,
    offer.consumed_at,
    offer.consumed_by,
    offer.expires_at,
    offer.requires_enrollment,
    offer.enrollment_fee,
    offer.opportunity_id,
    offer.vendor_id,
    offer.invite_security_version
  INTO enrollment_offer
  FROM public.offers AS offer
  WHERE offer.id = p_offer_id
    AND offer.kind = 'ENROLLMENT';

  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'OFFER_NOT_FOUND');
  END IF;
  IF enrollment_offer.revoked_at IS NOT NULL THEN
    RETURN jsonb_build_object('error', 'OFFER_REVOKED');
  END IF;
  IF enrollment_offer.invite_security_version < 1 THEN
    RETURN jsonb_build_object('error', 'OFFER_REVOKED');
  END IF;
  IF enrollment_offer.consumed_at IS NOT NULL
    AND enrollment_offer.consumed_by IS DISTINCT FROM (SELECT auth.uid())
  THEN
    RETURN jsonb_build_object('error', 'OFFER_CONSUMED');
  END IF;
  IF enrollment_offer.consumed_at IS NULL
    AND (
      enrollment_offer.expires_at IS NULL
      OR enrollment_offer.expires_at <= now()
    )
  THEN
    RETURN jsonb_build_object('error', 'OFFER_EXPIRED');
  END IF;
  IF NOT private.tenant_is_operational(enrollment_offer.tenant_id) THEN
    RETURN jsonb_build_object('error', 'TENANT_UNAVAILABLE');
  END IF;
  IF enrollment_offer.opportunity_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.opportunities AS opportunity
    WHERE opportunity.id = enrollment_offer.opportunity_id
      AND opportunity.tenant_id = enrollment_offer.tenant_id
      AND opportunity.conversion_status = 'WON'
      AND (
        opportunity.student_id IS NULL
        OR opportunity.student_id IS DISTINCT FROM (SELECT auth.uid())
      )
  ) THEN
    RETURN jsonb_build_object('error', 'OPPORTUNITY_CONVERTED');
  END IF;

  school_info := enrollment_offer.payload -> '_schoolInfo';
  IF jsonb_typeof(school_info) IS DISTINCT FROM 'object' THEN
    RETURN jsonb_build_object('error', 'OFFER_LEGAL_SNAPSHOT_MISSING');
  END IF;
  RETURN coalesce(enrollment_offer.payload, '{}'::jsonb)
    || jsonb_build_object(
      '_offerId', enrollment_offer.id,
      '_schoolInfo', school_info,
      'unitId', enrollment_offer.tenant_id,
      'requiresEnrollment', enrollment_offer.requires_enrollment,
      'enrollmentFee', enrollment_offer.enrollment_fee,
      'opportunityId', enrollment_offer.opportunity_id,
      'vendorId', enrollment_offer.vendor_id
    );
END;
$$;


--
-- Name: get_opportunity_teacher_dispatch_secure(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_opportunity_teacher_dispatch_secure(p_tenant_id text, p_opportunity_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request private.vendor_trial_teacher_requests%rowtype;
begin
  if nullif(trim(coalesce(p_tenant_id, '')), '') is null
     or p_opportunity_id is null
     or not exists (
       select 1
         from public.opportunities as opportunity
        where opportunity.id = p_opportunity_id
          and opportunity.tenant_id = p_tenant_id
     ) then
    return jsonb_build_object('ok', false, 'dispatchMode', 'NONE');
  end if;

  select request.*
    into v_request
    from private.vendor_trial_teacher_requests as request
   where request.tenant_id = p_tenant_id
     and request.opportunity_id = p_opportunity_id;

  if not found then
    return jsonb_build_object(
      'ok', true,
      'dispatchMode', 'GENERIC',
      'state', 'GENERIC'
    );
  end if;
  if v_request.status = 'AWAITING_TEACHER' then
    return jsonb_build_object(
      'ok', true,
      'dispatchMode', 'TARGETED',
      'state', v_request.status,
      'targetTeacherId', v_request.target_teacher_id
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'dispatchMode', 'NONE',
    'state', v_request.status
  );
end;
$$;


--
-- Name: FUNCTION get_opportunity_teacher_dispatch_secure(p_tenant_id text, p_opportunity_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_opportunity_teacher_dispatch_secure(p_tenant_id text, p_opportunity_id uuid) IS 'Service-only fail-closed dispatch guard. Directed trials never enter generic teacher broadcasts.';


--
-- Name: get_payment_split_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_payment_split_settings() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; r record; v_destino text; v_professores jsonb;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;

  SELECT d.destino INTO v_destino FROM dre_report_settings d WHERE d.tenant_id = v_tenant;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', p.id, 'nome', btrim(p.full_name),
           'pro_labore', EXISTS (SELECT 1 FROM payment_split_owner_teachers o
                                  WHERE o.tenant_id = v_tenant AND o.teacher_id = p.id))
         ORDER BY btrim(p.full_name)), '[]'::jsonb)
    INTO v_professores
    FROM profiles p
   WHERE p.tenant_id = v_tenant AND p.role = 'TEACHER'
     AND COALESCE(p.status,'Ativo') NOT IN ('Inativo','INACTIVE','Inactive');

  SELECT * INTO r FROM payment_split_settings WHERE tenant_id = v_tenant;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('configurado', false, 'is_active', false,
      'dizimo_pct', 10.00, 'investimento_pct', 10.00, 'escola_pct', 0.00,
      'prof_dizimo_pct', 10.00, 'prof_investimento_pct', 70.00, 'prof_prolabore_pct', 20.00,
      'professores', v_professores,
      'destino', COALESCE(v_destino,''), 'destino_configurado', v_destino IS NOT NULL);
  END IF;
  RETURN jsonb_build_object('configurado', true, 'is_active', r.is_active,
    'dizimo_pct', r.dizimo_pct, 'investimento_pct', r.investimento_pct,
    'escola_pct', r.escola_pct,
    'prof_dizimo_pct', r.prof_dizimo_pct,
    'prof_investimento_pct', r.prof_investimento_pct,
    'prof_prolabore_pct', r.prof_prolabore_pct,
    'professores', v_professores,
    'destino', COALESCE(v_destino,''), 'destino_configurado', v_destino IS NOT NULL,
    'updated_at', r.updated_at);
END;
$$;


--
-- Name: get_plan_change_public(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_plan_change_public(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v jsonb;
begin
  select jsonb_build_object(
           'student_name', p.full_name,
           'from_frequency', c.from_frequency,
           'to_frequency', c.to_frequency,
           'from_monthly_fee', c.from_monthly_fee,
           'to_monthly_fee', c.to_monthly_fee,
           'fidelity_plan', c.fidelity_plan,
           'due_day', p.due_day,
           'status', c.status,
           'signed_at', c.signed_at,
           'expired', (c.expires_at < now()),
           'school_name', t.name
         )
    into v
    from public.student_plan_changes c
    join public.profiles p on p.id = c.student_id
    left join public.tenants t on t.id = c.tenant_id
   where c.token = p_token;

  if v is null then
    return jsonb_build_object('ok', false, 'error', 'Proposta não encontrada');
  end if;

  return jsonb_build_object('ok', true, 'data', v);
end;
$$;


--
-- Name: get_referral_settings(); Type: FUNCTION; Schema: public; Owner: -
