    'teacher_reward_brl', COALESCE(st.teacher_reward_brl, 0),
    'min_payments', COALESCE(st.min_payments, 1),
    'monthly_cap', st.monthly_cap,
    'cooldown_days', COALESCE(st.cooldown_days, 0),
    'self_referral_block', COALESCE(st.self_referral_block, true),
