--
-- Name: get_student_credit_balance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_student_credit_balance(p_student_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; s_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id=auth.uid();
  SELECT tenant_id INTO s_tenant FROM profiles WHERE id=p_student_id;
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','TEACHER') THEN RETURN 0; END IF;
  IF v_role='SCHOOL_ADMIN' AND s_tenant<>v_tenant THEN RETURN 0; END IF;
  RETURN (SELECT COALESCE(sum(amount),0) FROM student_credits
          WHERE student_id=p_student_id AND applied_at IS NULL AND (expires_at IS NULL OR expires_at>now()));
END;
$$;


