--
-- Name: get_student_opt_in_leaderboard_core(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_student_opt_in_leaderboard_core(p_limit integer DEFAULT 5) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_id uuid := auth.uid();
  v_profile record;
  v_result jsonb;
begin
  if v_student_id is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  if p_limit is null or p_limit not between 1 and 50 then
    raise exception using
      errcode = '22023',
      message = 'invalid_leaderboard_limit';
  end if;

  select profile.tenant_id, profile.role
    into v_profile
    from public.profiles as profile
   where profile.id = v_student_id;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  select coalesce(
           pg_catalog.jsonb_agg(
             pg_catalog.jsonb_build_object(
               'displayName', ranked.display_name,
               'xp', ranked.xp
             )
             order by ranked.position
           ),
           '[]'::jsonb
         )
    into v_result
    from (
      select
        pg_catalog.row_number() over (
          order by coalesce(student.xp, 0) desc, student.id
        ) as position,
        coalesce(
          nullif(pg_catalog.btrim(student.league_display_name), ''),
          'Lobo ' || pg_catalog.row_number() over (
            order by coalesce(student.xp, 0) desc, student.id
          )::text
        ) as display_name,
        greatest(0, coalesce(student.xp, 0)) as xp
      from public.profiles as student
      where student.tenant_id = v_profile.tenant_id
        and student.role = 'STUDENT'
        and coalesce(student.league_opt_in, false) is true
      order by coalesce(student.xp, 0) desc, student.id
      limit p_limit
    ) as ranked;

  return v_result;
end;
$$;


--
-- Name: get_student_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_student_overview(p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
  v_profile jsonb;
begin
  v_result := public.get_student_overview_internal_20260824(p_student_id);

  if coalesce((v_result ->> 'can_edit_financial')::boolean, false) then
    return v_result;
  end if;

  v_profile := coalesce(v_result -> 'profile', '{}'::jsonb)
    - array['guardian_name', 'guardian_phone', 'status_financial']::text[];

  if v_result ? 'profile' then
    v_result := pg_catalog.jsonb_set(v_result, '{profile}', v_profile, false);
  end if;

  return v_result - array['financial', 'payments', 'audit']::text[];
end;
$$;


--
-- Name: FUNCTION get_student_overview(p_student_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_student_overview(p_student_id uuid) IS 'Ficha 360 com dados financeiros e do responsavel somente para direcao autorizada.';


--
-- Name: get_student_overview_internal_20260824(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_student_overview_internal_20260824(p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_tenant text;
  s public.profiles%rowtype;
  v_is_admin boolean := false;
  v_can boolean := false;
  v_result jsonb;
  v_att int;
  v_abs int;
  v_today date := (pg_catalog.now() at time zone 'America/Sao_Paulo')::date;
begin
  if v_uid is null then
    return pg_catalog.jsonb_build_object('error', 'sem_permissao');
  end if;

  select public._my_role(), public._my_tenant_id()
    into v_role, v_tenant;

  if v_role is null or (v_role <> 'SUPER_ADMIN' and v_tenant is null) then
    return pg_catalog.jsonb_build_object('error', 'sem_permissao');
  end if;

  select *
    into s
    from public.profiles p
   where p.id = p_student_id
     and p.role = 'STUDENT'
     and (v_role = 'SUPER_ADMIN' or p.tenant_id = v_tenant);
  if not found then
    return pg_catalog.jsonb_build_object('error', 'nao_encontrado');
  end if;

  v_is_admin := coalesce(v_role in ('SCHOOL_ADMIN', 'SUPER_ADMIN'), false);
  v_can := coalesce(
    v_role = 'SUPER_ADMIN'
    or (v_role = 'SCHOOL_ADMIN' and s.tenant_id = v_tenant)
    or (
      v_role = 'TEACHER'
      and s.tenant_id = v_tenant
      and (
        s.professor_id = v_uid
        or s.professor_id2 = v_uid
        or exists (
          select 1
            from public.bookings b
           where b.student_id = s.id
             and b.teacher_id = v_uid
             and b.tenant_id = s.tenant_id
             and b.status = 'SCHEDULED'
        )
      )
    ),
    false
  );

  if not v_can then
    return pg_catalog.jsonb_build_object('error', 'sem_permissao');
  end if;

  select
    count(*) filter (where cl.presence = 'COMPLETED' and cl.class_date >= v_today - 90),
    count(*) filter (where cl.presence = 'STUDENT_ABSENCE' and cl.class_date >= v_today - 90)
    into v_att, v_abs
    from public.class_logs cl
   where cl.student_id = p_student_id
     and cl.tenant_id = s.tenant_id;

  v_result := pg_catalog.jsonb_build_object(
    'profile', pg_catalog.jsonb_build_object(
      'id', s.id,
      'full_name', s.full_name,
      'avatar_url', s.avatar_url,
      'module', s.module,
      'phone', s.phone,
      'email', s.email,
      'is_kids', coalesce(s.is_kids, false),
      'guardian_name', s.guardian_name,
      'guardian_phone', s.guardian_phone,
      'occupation', s.occupation,
      'interests', s.interests,
      'meeting_link', s.meeting_link,
      'status_financial', s.status_financial,
      'start_date', s.start_date,
      'created_at', s.created_at,
      'class_frequency', s.class_frequency,
      'professor_id', s.professor_id,
      'professor_name', (select p.full_name from public.profiles p where p.id = s.professor_id)
    ),
    'frequency', pg_catalog.jsonb_build_object(
      'attended_90', v_att,
      'absent_90', v_abs,
      'rate', case when v_att + v_abs > 0 then pg_catalog.round(100.0 * v_att / (v_att + v_abs))::int else null end
    ),
    'gamification', pg_catalog.jsonb_build_object(
      'xp', coalesce(s.xp, 0),
      'level', coalesce(s.level, 1),
      'streak', coalesce(s.streak_count, 0),
      'hearts', coalesce(s.hearts, 5),
      'last_activity', s.last_activity
    ),
    'classes', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id', cl.id,
          'date', cl.class_date,
          'class_time', case when cl.start_time is not null then pg_catalog.to_char(cl.start_time, 'HH24:MI') else null end,
          'origin_type', case
            when cl.booking_id is not null then 'BOOKING'
            when cl.reschedule_id is not null then 'RESCHEDULE'
            when cl.appointment_id is not null then 'APPOINTMENT'
            else 'MANUAL'
          end,
          'booking_id', cl.booking_id,
          'reschedule_id', cl.reschedule_id,
          'appointment_id', cl.appointment_id,
          'presence', cl.presence,
          'subtype', cl.subtype,
          'content', coalesce(cl.content_covered, cl.content),
          'difficulties', cl.student_difficulties,
          'homework', cl.homework_assigned,
          'teacher_id', cl.teacher_id,
          'teacher', (select p.full_name from public.profiles p where p.id = cl.teacher_id)
        ) order by cl.class_date desc nulls last, cl.start_time desc nulls last, cl.created_at desc
      )
      from (
        select *
          from public.class_logs
         where student_id = p_student_id
           and tenant_id = s.tenant_id
         order by class_date desc nulls last, start_time desc nulls last, created_at desc
         limit 25
      ) cl
    ), '[]'::jsonb),
    'notes', coalesce((
      select pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id', n.id,
          'category', n.category,
          'note', n.note,
          'author_name', n.author_name,
          'created_at', n.created_at
        ) order by n.created_at desc
      )
      from public.student_teacher_notes n
      where n.student_id = p_student_id
        and n.tenant_id = s.tenant_id
    ), '[]'::jsonb)
  );

  if v_is_admin then
    v_result := v_result || pg_catalog.jsonb_build_object(
      'financial', pg_catalog.jsonb_build_object(
        'monthly_fee', s.monthly_fee,
        'due_day', s.due_day,
        'status_financial', s.status_financial,
        'first_overdue_at', s.first_overdue_at
      ),
      'payments', coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.jsonb_build_object(
            'value', sp.value,
            'status', sp.status,
            'due_date', sp.due_date,
            'paid_at', coalesce(sp.paid_at, sp.payment_date),
            'invoice_url', sp.invoice_url,
            'description', sp.description
          ) order by sp.due_date desc nulls last
        )
        from (
          select * from public.student_payments
           where student_id = p_student_id
             and tenant_id = s.tenant_id
           order by due_date desc nulls last
           limit 12
        ) sp
      ), '[]'::jsonb),
      'audit', coalesce((
        select pg_catalog.jsonb_agg(
          pg_catalog.jsonb_build_object(
            'field', a.field,
            'old_value', a.old_value,
            'new_value', a.new_value,
            'changed_at', a.changed_at,
            'changed_by', (select p.full_name from public.profiles p where p.id = a.changed_by)
          ) order by a.changed_at desc
        )
        from (
          select * from public.profile_audit_log
           where profile_id = p_student_id
             and tenant_id = s.tenant_id
           order by changed_at desc
           limit 20
        ) a
      ), '[]'::jsonb)
    );
  end if;

  return v_result || pg_catalog.jsonb_build_object(
    'can_edit_financial', v_is_admin,
    'viewer_role', v_role
  );
end;
$$;


