--
-- Name: get_teacher_activity_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_teacher_activity_report(p_teacher_id uuid, p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  actor_id uuid := auth.uid();
  actor_role text;
  actor_tenant_id text;
  target_teacher public.profiles%ROWTYPE;
  report_month text := coalesce(p_month, pg_catalog.to_char(current_date, 'YYYY-MM'));
  month_start date;
  hourly_rate numeric;
  report jsonb;
BEGIN
  IF actor_id IS NULL OR coalesce(auth.role(), '') <> 'authenticated' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'authentication_required';
  END IF;

  IF p_teacher_id IS NULL
    OR report_month !~ '^\d{4}-(0[1-9]|1[0-2])$'
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'invalid_teacher_report_scope';
  END IF;

  actor_tenant_id := private.active_tenant_id(actor_id);
  actor_role := private.active_tenant_role(actor_id);

  IF actor_tenant_id IS NULL
    OR actor_role IS NULL
    OR NOT private.tenant_is_operational(actor_tenant_id)
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'active_tenant_required';
  END IF;

  IF NOT (
    (actor_role = 'TEACHER' AND actor_id = p_teacher_id)
    OR actor_role IN ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN')
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'teacher_report_access_denied';
  END IF;

  SELECT profile.*
  INTO target_teacher
  FROM public.profiles AS profile
  WHERE profile.id = p_teacher_id
    AND profile.role = 'TEACHER'
    AND lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) = 'active'
    AND EXISTS (
      SELECT 1
      FROM public.tenant_memberships AS membership
      WHERE membership.user_id = profile.id
        AND membership.tenant_id = actor_tenant_id
        AND membership.role = 'TEACHER'
        AND membership.status = 'ACTIVE'
    );

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'teacher_report_access_denied';
  END IF;

  month_start := (report_month || '-01')::date;
  hourly_rate := coalesce(target_teacher.hourly_rate, 0);

  WITH lessons AS (
    SELECT
      class_log.class_date,
      class_log.presence,
      class_log.subtype,
      class_log.content_covered,
      student.full_name AS student,
      (
        class_log.presence NOT IN ('TEACHER_ABSENCE', 'Falta do Professor')
        AND class_log.subtype IS DISTINCT FROM 'REPOSIÇÃO'
        AND class_log.subtype IS DISTINCT FROM 'Teste Oral'
        AND coalesce(class_log.payment_hold, false) IS FALSE
      ) AS paid
    FROM public.class_logs AS class_log
    LEFT JOIN public.profiles AS student
      ON student.id = class_log.student_id
     AND (
       student.tenant_id = actor_tenant_id
       OR EXISTS (
         SELECT 1
         FROM public.tenant_memberships AS student_membership
         WHERE student_membership.user_id = student.id
           AND student_membership.tenant_id = actor_tenant_id
       )
     )
    WHERE class_log.teacher_id = p_teacher_id
      AND class_log.tenant_id = actor_tenant_id
      AND class_log.class_date >= month_start
      AND class_log.class_date < (month_start + INTERVAL '1 month')
    ORDER BY class_log.class_date, class_log.id
  )
  SELECT pg_catalog.jsonb_build_object(
    'teacher', pg_catalog.jsonb_build_object(
      'name', target_teacher.full_name,
      'email', target_teacher.email,
      'pix', target_teacher.pix_key,
      'hourly_rate', hourly_rate,
      'specializations', target_teacher.specializations
    ),
    'school', (
      SELECT tenant.name
      FROM public.tenants AS tenant
      WHERE tenant.id = actor_tenant_id
      LIMIT 1
    ),
    'month', report_month,
    'lessons', coalesce((
      SELECT pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'date', lesson.class_date,
          'student', lesson.student,
          'presence', lesson.presence,
          'subtype', lesson.subtype,
          'content', lesson.content_covered,
          'paid', lesson.paid,
          'value', CASE WHEN lesson.paid THEN hourly_rate ELSE 0 END
        )
        ORDER BY lesson.class_date
      )
      FROM lessons AS lesson
    ), '[]'::jsonb),
    'totals', (
      SELECT pg_catalog.jsonb_build_object(
        'total_lessons', count(*),
        'paid_lessons', count(*) FILTER (WHERE lesson.paid),
        'completed', count(*) FILTER (WHERE lesson.presence = 'COMPLETED'),
        'student_absences', count(*) FILTER (WHERE lesson.presence = 'STUDENT_ABSENCE'),
        'teacher_absences', count(*) FILTER (
          WHERE lesson.presence IN ('TEACHER_ABSENCE', 'Falta do Professor')
        ),
        'amount', coalesce(
          sum(CASE WHEN lesson.paid THEN hourly_rate ELSE 0 END),
          0
        )
      )
      FROM lessons AS lesson
    ),
    'closing', (
      SELECT pg_catalog.jsonb_build_object(
        'status', closing.status,
        'total_amount', closing.total_amount,
        'paid_at', closing.paid_at,
        'confirmation', closing.teacher_confirmation_status,
        'admin_notes', closing.admin_notes
      )
      FROM public.teacher_closings AS closing
      WHERE closing.teacher_id = p_teacher_id
        AND closing.tenant_id = actor_tenant_id
        AND closing.month_year = report_month
      ORDER BY closing.updated_at DESC NULLS LAST, closing.id
      LIMIT 1
    )
  )
  INTO report;

  RETURN report;
END;
$_$;


--
-- Name: get_teacher_closing_report(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_teacher_closing_report(p_teacher_id uuid, p_month text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT private.can_access_teacher_closing(p_teacher_id, p_month) THEN
    RAISE EXCEPTION 'teacher_finance_access_denied' USING ERRCODE = '42501';
  END IF;

  RETURN public.get_teacher_closing_report_unchecked(p_teacher_id, p_month);
END;
$$;


--
-- Name: FUNCTION get_teacher_closing_report(p_teacher_id uuid, p_month text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_teacher_closing_report(p_teacher_id uuid, p_month text) IS 'Tenant-aware facade for the legacy teacher closing report calculation.';


--
-- Name: get_teacher_closing_report_unchecked(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_teacher_closing_report_unchecked(p_teacher_id uuid, p_month text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_jwt_role text; v_caller_role text; v_students jsonb; v_resumo jsonb; v_excluidas jsonb;
  v_teacher jsonb; v_closing jsonb;
BEGIN
  v_jwt_role := COALESCE(current_setting('request.jwt.claims', true)::json->>'role', '');
  IF v_jwt_role IN ('anon', 'authenticated') THEN
    SELECT role INTO v_caller_role FROM profiles WHERE id = auth.uid();
    IF auth.uid() IS DISTINCT FROM p_teacher_id
       AND (v_caller_role IS NULL OR v_caller_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR')) THEN
      RAISE EXCEPTION 'Sem permissão para ver este relatório';
    END IF;
  END IF;

  IF p_month !~ '^\d{4}-\d{2}$' THEN
    RAISE EXCEPTION 'Mês inválido (use YYYY-MM)';
  END IF;

  SELECT jsonb_build_object('id', p.id, 'name', p.full_name, 'avatar_url', p.avatar_url)
    INTO v_teacher FROM profiles p WHERE p.id = p_teacher_id;

  SELECT jsonb_build_object('id', tc.id, 'status', tc.status, 'total_lessons', tc.total_lessons,
           'total_amount', tc.total_amount, 'paid_at', tc.paid_at, 'admin_notes', tc.admin_notes)
    INTO v_closing FROM teacher_closings tc
   WHERE tc.teacher_id = p_teacher_id AND tc.month_year = p_month LIMIT 1;

  WITH pagas AS (
    SELECT v.id, v.student_id, v.class_date, v.presence, v.subtype, v.appointment_id,
           v.rate_efetivo AS rate,
           (v.rate_override IS NOT NULL) AS overridden,
           v.reposicao_sem_origem,
           COALESCE(v.subtype = 'AULA EXPERIMENTAL', false) AS experimental,
           -- Nome de exibição: aluno cadastrado, senão o nome do agendamento da
           -- experimental/treinamento.
           COALESCE(sp.full_name, ap.student_name) AS nome,
           -- Chave de agrupamento: aluno cadastrado agrupa por perfil; experimental
           -- agrupa por agendamento, para cada uma virar a sua própria linha.
           COALESCE(v.student_id::text, 'appt:' || COALESCE(v.appointment_id, v.id::text)) AS grp
    FROM v_payable_class_logs v
    LEFT JOIN profiles sp ON sp.id = v.student_id
    LEFT JOIN appointments ap ON ap.id::text = v.appointment_id
    WHERE v.teacher_id = p_teacher_id
      AND to_char(v.class_date,'YYYY-MM') = p_month
  ), linhas AS (
    SELECT
      pg.grp,
      max(pg.student_id::text) AS student_id,
      max(COALESCE(pg.nome, 'Aluno não cadastrado')) AS student_name,
      pg.experimental,
      count(*) AS aulas,
      sum(pg.rate) AS valor,
      round(sum(pg.rate) / NULLIF(count(*),0), 2) AS valor_base,
      count(distinct pg.rate)::int AS qtd_tarifas,
      max(COALESCE(sp.lesson_duration_minutes, 30)) AS duracao_min,
      bool_or(pg.overridden) AS tem_ajuste,
      bool_or(pg.reposicao_sem_origem) AS revisar,
      count(distinct to_char(pg.class_date,'IYYY-IW')) AS semanas,
      max(sp.class_frequency) AS freq_perfil,
      count(*) FILTER (WHERE pg.presence <> 'COMPLETED') AS faltas_aluno,
      jsonb_agg(jsonb_build_object(
        'id', pg.id, 'date', pg.class_date, 'presence', pg.presence, 'subtype', pg.subtype,
        'valor', pg.rate, 'override', pg.overridden
      ) ORDER BY pg.class_date) AS detalhe
    FROM pagas pg
    LEFT JOIN profiles sp ON sp.id = pg.student_id
    GROUP BY pg.grp, pg.experimental
  )
  SELECT jsonb_agg(jsonb_build_object(
      'student_id', l.student_id,
      'student', trim(l.student_name),
      'tipo', CASE WHEN l.experimental THEN 'Aula experimental' ELSE 'Regular' END,
      'frequencia', CASE
        WHEN l.experimental THEN 'Aula experimental'
        WHEN l.freq_perfil IS NOT NULL AND l.freq_perfil ~ '^\d' THEN regexp_replace(l.freq_perfil,'^(\d+).*$','\1') || 'x por semana'
        WHEN l.semanas >= 3 AND round(l.aulas::numeric / l.semanas) >= 1
          THEN round(l.aulas::numeric / l.semanas) || 'x por semana'
        WHEN l.aulas = 1 THEN '1 aula'
        ELSE 'Aulas avulsas'
      END,
      'duracao_min', l.duracao_min,
      'aulas', l.aulas,
      'faltas_aluno', l.faltas_aluno,
      'valor_base', l.valor_base,
      'qtd_tarifas', l.qtd_tarifas,
      'valor', l.valor,
      'tem_ajuste', l.tem_ajuste,
      'revisar', l.revisar,
      'detalhe', l.detalhe
    ) ORDER BY l.experimental, trim(l.student_name))
  INTO v_students FROM linhas l;

  SELECT jsonb_build_object(
      'total_alunos', count(distinct v.student_id) FILTER (WHERE v.subtype IS DISTINCT FROM 'AULA EXPERIMENTAL' AND v.student_id IS NOT NULL),
      'aulas_regulares', count(*) FILTER (WHERE v.subtype IS DISTINCT FROM 'AULA EXPERIMENTAL'),
      'aulas_experimentais', count(*) FILTER (WHERE v.subtype = 'AULA EXPERIMENTAL'),
      'total_aulas', count(*),
      'valor_total', COALESCE(sum(v.rate_efetivo),0))
  INTO v_resumo
  FROM v_payable_class_logs v
  WHERE v.teacher_id = p_teacher_id AND to_char(v.class_date,'YYYY-MM') = p_month;

  -- Ajustes acordados com a direção entram no total e aparecem discriminados.
  -- valor_aulas fica preservado para a tela poder mostrar a composição.
  v_resumo := v_resumo || (
    SELECT jsonb_build_object(
      'valor_aulas', (v_resumo->>'valor_total')::numeric,
      'ajustes', COALESCE(sum(ca.amount),0),
      'ajustes_detalhe', COALESCE(jsonb_agg(jsonb_build_object(
          'descricao', ca.description, 'valor', ca.amount) ORDER BY ca.created_at), '[]'::jsonb),
      'valor_total', (v_resumo->>'valor_total')::numeric + COALESCE(sum(ca.amount),0))
    FROM closing_adjustments ca
    WHERE ca.teacher_id = p_teacher_id AND ca.month_year = p_month);

  SELECT jsonb_build_object(
      'falta_professor', count(*) FILTER (WHERE cl.presence IN ('TEACHER_ABSENCE','Falta do Professor')),
      'em_conflito', count(*) FILTER (WHERE COALESCE(cl.payment_hold,false)),
      'teste_oral', count(*) FILTER (WHERE cl.subtype = 'Teste Oral'),
      'nao_faturavel', count(*) FILTER (WHERE NOT is_billable_student(cl.student_id) AND cl.student_id IS NOT NULL),
      'reposicao_falta_aluno', count(*) FILTER (
         WHERE cl.subtype IN ('REPOSIÇÃO','REPOSIÇÃO_PROF')
           AND EXISTS (SELECT 1 FROM reschedules r2 WHERE r2.id::text = cl.reschedule_id AND r2.fault_type = 'STUDENT')),
      'duplicadas', count(*) FILTER (
         WHERE cl.presence NOT IN ('TEACHER_ABSENCE','Falta do Professor')
           AND cl.subtype IS DISTINCT FROM 'Teste Oral'
           AND COALESCE(cl.payment_hold,false) = false
           AND NOT EXISTS (SELECT 1 FROM v_payable_class_logs v2 WHERE v2.id = cl.id)
           AND is_billable_student(cl.student_id)))
  INTO v_excluidas
  FROM class_logs cl
  WHERE cl.teacher_id = p_teacher_id AND to_char(cl.class_date,'YYYY-MM') = p_month;

  RETURN jsonb_build_object(
    'teacher', v_teacher, 'month', p_month, 'closing', v_closing,
    'students', COALESCE(v_students, '[]'::jsonb),
    'resumo', v_resumo, 'excluidas', v_excluidas
  );
END;
$_$;


--
-- Name: get_teacher_opportunity_preview_secure(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_teacher_opportunity_preview_secure(p_opportunity_id uuid, p_claim_generation integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor_id uuid;
  v_tenant_id text;
  v_actor_role text;
  v_opportunity public.opportunities%rowtype;
  v_request private.vendor_trial_teacher_requests%rowtype;
BEGIN
  IF p_opportunity_id IS NULL
     OR p_claim_generation IS NULL
     OR p_claim_generation < 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_request');
  END IF;

  SELECT actor.actor_id, actor.tenant_id, actor.actor_role
    INTO v_actor_id, v_tenant_id, v_actor_role
    FROM private.secure_trial_actor_context() AS actor;

  IF v_actor_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF v_actor_role <> 'TEACHER' AND v_actor_role NOT IN ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF NOT private.tenant_is_operational(v_tenant_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'tenant_not_operational');
  END IF;
  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles AS profile
     WHERE profile.id = v_actor_id
       AND lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;

  SELECT opportunity.*
    INTO v_opportunity
    FROM public.opportunities AS opportunity
   WHERE opportunity.id = p_opportunity_id
     AND opportunity.tenant_id = v_tenant_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'opportunity_not_found');
  END IF;
  IF v_opportunity.claim_generation IS DISTINCT FROM p_claim_generation THEN
    RETURN jsonb_build_object('ok', false, 'error', 'claim_link_expired');
  END IF;

  SELECT request.*
    INTO v_request
    FROM private.vendor_trial_teacher_requests AS request
   WHERE request.opportunity_id = v_opportunity.id;

  IF FOUND AND v_actor_role = 'TEACHER' AND (
    v_request.target_teacher_id <> v_actor_id
    OR v_request.status NOT IN ('AWAITING_TEACHER', 'ACCEPTED')
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'opportunity_not_found');
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'id', v_opportunity.id,
    'student_name', v_opportunity.student_name,
    'slots_proposed', v_opportunity.slots_proposed,
    'status', v_opportunity.status,
    'kind', coalesce(v_opportunity.kind, 'TRIAL'),
    'interests', v_opportunity.interests,
    'winner_teacher_id', v_opportunity.winner_teacher_id,
    'trial_appointment_id', v_opportunity.trial_appointment_id,
    'claim_generation', v_opportunity.claim_generation,
    'is_staff_preview', (v_actor_role <> 'TEACHER'),
    'actor_role', v_actor_role
  );
END;
$$;


--
-- Name: get_teacher_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_teacher_overview(p_teacher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  target_tenant_id text;
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object('error', 'sem_permissao');
  END IF;
  SELECT teacher.tenant_id
  INTO target_tenant_id
  FROM public.profiles AS teacher
  WHERE teacher.id = p_teacher_id
    AND teacher.role = 'TEACHER';
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object('error', 'nao_encontrado');
  END IF;
  IF NOT private.legacy_role_rpc_target_allowed(target_tenant_id) THEN
    RETURN pg_catalog.jsonb_build_object('error', 'sem_permissao');
  END IF;
  RETURN public.get_teacher_overview_unchecked(p_teacher_id);
END;
$$;


--
-- Name: get_teacher_overview_unchecked(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_teacher_overview_unchecked(p_teacher_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_uid uuid := auth.uid(); v_role text; v_tenant text; t profiles%ROWTYPE;
  v_c30 int; v_a30 int; v_cmonth int; v_conf int; v_avg numeric; v_rc int;
  v_students int; v_linked int; v_earned numeric;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id=v_uid;
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN jsonb_build_object('error','sem_permissao'); END IF;
  SELECT * INTO t FROM profiles WHERE id=p_teacher_id AND role='TEACHER';
  IF NOT FOUND THEN RETURN jsonb_build_object('error','nao_encontrado'); END IF;
  IF v_role='SCHOOL_ADMIN' AND t.tenant_id <> v_tenant THEN RETURN jsonb_build_object('error','sem_permissao'); END IF;

  SELECT count(*) FILTER (WHERE presence='COMPLETED' AND class_date>=current_date-30),
         count(*) FILTER (WHERE presence='TEACHER_ABSENCE' AND class_date>=current_date-30),
         count(*) FILTER (WHERE presence='COMPLETED' AND class_date>=date_trunc('month',current_date))
    INTO v_c30, v_a30, v_cmonth FROM class_logs WHERE teacher_id=p_teacher_id;
  SELECT count(*) FILTER (WHERE status='CONFLICT'), avg(student_rating) FILTER (WHERE student_rating IS NOT NULL), count(student_rating)
    INTO v_conf, v_avg, v_rc FROM attendance_confirmations WHERE teacher_id=p_teacher_id;

  -- Carteira = a MESMA função que decide o turbo e a tarifa. Contar `bookings`
  -- direto trazia perfil de treinamento, aluno desligado e agendamento cancelado.
  SELECT count(*) INTO v_students FROM teacher_carteira(p_teacher_id);
  -- Vinculados = tudo que aparece na agenda dele. Fica exposto ao lado para o
  -- diretor entender a diferença em vez de achar que sumiu aluno da ficha.
  SELECT count(DISTINCT student_id) INTO v_linked FROM bookings WHERE teacher_id=p_teacher_id;

  -- Ganho do mês: a fonte do pagamento, não uma estimativa por tarifa média.
  SELECT round(coalesce(sum(v.rate_efetivo),0),2) INTO v_earned
    FROM v_payable_class_logs v
   WHERE v.teacher_id=p_teacher_id AND v.class_date>=date_trunc('month',current_date)::date;

  RETURN jsonb_build_object(
    'profile', jsonb_build_object('id',t.id,'full_name',t.full_name,'avatar_url',t.avatar_url,'email',t.email,'phone',t.phone,
       'status',t.status,'hourly_rate',t.hourly_rate,'commission_rate',t.commission_rate,'specializations',t.specializations,
       'pix_ok',(t.pix_key IS NOT NULL AND t.pix_key<>''),
       'contract_ok',(coalesce(t.contract_accepted,false) OR t.accepted_at IS NOT NULL OR t.documentation_status='APPROVED')),
    'metrics', jsonb_build_object('active_students',v_students,'linked_students',v_linked,
       'classes_30',v_c30,'teacher_absence_30',v_a30,
       'absence_rate', CASE WHEN v_c30+v_a30>0 THEN round(100.0*v_a30/(v_c30+v_a30))::int ELSE 0 END,
       'conflicts_open',coalesce(v_conf,0),'avg_rating',round(v_avg,1),'rating_count',coalesce(v_rc,0),
       'earnings_est', v_earned),
    'students', coalesce((SELECT jsonb_agg(jsonb_build_object('id',sp.id,'name',sp.full_name,'module',sp.module,
         'na_carteira', EXISTS (SELECT 1 FROM teacher_carteira(p_teacher_id) c WHERE c.student_id=sp.id)) ORDER BY sp.full_name)
       FROM (SELECT DISTINCT b.student_id FROM bookings b WHERE b.teacher_id=p_teacher_id) bb
       JOIN profiles sp ON sp.id=bb.student_id), '[]'::jsonb),
    'recent_classes', coalesce((SELECT jsonb_agg(jsonb_build_object('date',cl.class_date,'presence',cl.presence,
       'student',(SELECT full_name FROM profiles WHERE id=cl.student_id)) ORDER BY cl.class_date DESC NULLS LAST)
       FROM (SELECT * FROM class_logs WHERE teacher_id=p_teacher_id ORDER BY class_date DESC NULLS LAST LIMIT 20) cl), '[]'::jsonb),
    'closings', coalesce((SELECT jsonb_agg(jsonb_build_object('month',c.month_year,'amount',c.total_amount,'status',c.status,
       'confirmation',c.teacher_confirmation_status) ORDER BY c.month_year DESC)
       FROM (SELECT * FROM teacher_closings WHERE teacher_id=p_teacher_id ORDER BY month_year DESC LIMIT 6) c), '[]'::jsonb),
    'absences', coalesce((SELECT jsonb_agg(jsonb_build_object('starts_at',a.starts_at,'ends_at',a.ends_at,'reason',a.reason,'status',a.status) ORDER BY a.starts_at DESC)
       FROM teacher_absences a WHERE a.teacher_id=p_teacher_id), '[]'::jsonb),
    'audit', coalesce((SELECT jsonb_agg(jsonb_build_object('field',al.field,'old_value',al.old_value,'new_value',al.new_value,'changed_at',al.changed_at,
       'changed_by',(SELECT full_name FROM profiles WHERE id=al.changed_by)) ORDER BY al.changed_at DESC)
       FROM (SELECT * FROM profile_audit_log WHERE profile_id=p_teacher_id ORDER BY changed_at DESC LIMIT 20) al), '[]'::jsonb)
  );
END;
$$;


--
-- Name: FUNCTION get_teacher_overview_unchecked(p_teacher_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_teacher_overview_unchecked(p_teacher_id uuid) IS 'Ficha 360 do professor. active_students = teacher_carteira (a mesma que destrava o turbo); linked_students = tudo que aparece na agenda. earnings_est vem de v_payable_class_logs — nunca aulas × hourly_rate.';


--
-- Name: get_teacher_pending_trial_feedback_secure(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_teacher_pending_trial_feedback_secure() RETURNS TABLE(opportunity_id uuid, appointment_id uuid, student_name text, completed_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := (select auth.uid());
  v_tenant_id text := private.active_tenant_id(v_actor_id);
begin
  if v_actor_id is null
     or v_tenant_id is null
     or not private.tenant_is_operational(v_tenant_id)
     or not exists (
       select 1
       from public.profiles as profile
       join public.tenant_memberships as membership
         on membership.user_id = profile.id
        and membership.tenant_id = v_tenant_id
        and membership.role = 'TEACHER'
        and membership.status = 'ACTIVE'
       where profile.id = v_actor_id
         and profile.tenant_id = v_tenant_id
         and profile.role = 'TEACHER'
         and lower(pg_catalog.btrim(coalesce(
           profile.lifecycle_status,
           ''
         ))) = 'active'
     ) then
    return;
  end if;

  return query
  select
    opportunity.id,
    appointment.id,
    pg_catalog.left(
      pg_catalog.regexp_replace(
        coalesce(opportunity.student_name, ''),
        '[[:cntrl:]<>*_`~]+',
        ' ',
        'g'
      ),
      160
    ),
    class_log.created_at
  from public.opportunities as opportunity
  join public.appointments as appointment
    on appointment.id = opportunity.trial_appointment_id
   and appointment.tenant_id = opportunity.tenant_id
   and coalesce(appointment.teacher_id, appointment.professor_id) = v_actor_id
   and (
     appointment.teacher_id is null
     or appointment.teacher_id = v_actor_id
   )
   and (
     appointment.professor_id is null
     or appointment.professor_id = v_actor_id
   )
   and lower(coalesce(appointment.type, '')) = 'experimental'
  join lateral (
    select log.created_at
    from public.class_logs as log
    where log.appointment_id = appointment.id::text
      and log.tenant_id = v_tenant_id
      and log.teacher_id = v_actor_id
      and log.presence = 'COMPLETED'
    order by log.created_at desc, log.id desc
    limit 1
  ) as class_log on true
  where opportunity.tenant_id = v_tenant_id
    and opportunity.kind = 'TRIAL'
    and opportunity.status = 'CLAIMED'
    and opportunity.conversion_status = 'OPEN'
    and opportunity.feedback_required is true
    and opportunity.is_test_fixture is false
    and coalesce(
      opportunity.winner_teacher_id,
      opportunity.professor_id
    ) = v_actor_id
    and (
      opportunity.winner_teacher_id is null
      or opportunity.winner_teacher_id = v_actor_id
    )
    and (
      opportunity.professor_id is null
      or opportunity.professor_id = v_actor_id
    )
    and not exists (
      select 1
      from public.trial_feedback as feedback
      where feedback.opportunity_id = opportunity.id
    )
  order by class_log.created_at, opportunity.id;
end;
$$;


--
-- Name: get_tenant_overview(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tenant_overview(p_tenant_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t tenants%ROWTYPE; v_students int; v_teachers int; v_c30 int; v_last date; r jsonb;
BEGIN
  IF NOT is_super_admin() THEN RETURN jsonb_build_object('error','sem_permissao'); END IF;
  SELECT * INTO t FROM tenants WHERE id = p_tenant_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','nao_encontrado'); END IF;

  SELECT count(*) FILTER (WHERE role='STUDENT'), count(*) FILTER (WHERE role='TEACHER')
    INTO v_students, v_teachers FROM profiles WHERE tenant_id=p_tenant_id;
  SELECT count(*) FILTER (WHERE class_date>=current_date-30), max(class_date)
    INTO v_c30, v_last FROM class_logs WHERE tenant_id=p_tenant_id;

  r := jsonb_build_object(
    'tenant', jsonb_build_object('id',t.id,'name',t.name,'saas_status',t.saas_status,'domain',t.custom_domain,
       'owner_email',t.owner_email,'owner_phone',t.owner_phone,'created_at',t.created_at,
       'student_limit',t.student_limit,'teacher_limit',t.teacher_limit,'trial_ends_at',t.trial_ends_at,
       'current_period_end',t.current_period_end,'asaas_status',t.asaas_subaccount_status,'plan_id',t.plan_id,
       'plan_name',(SELECT name FROM saas_plans WHERE id=t.plan_id),'plan_price',(SELECT price FROM saas_plans WHERE id=t.plan_id)),
    'usage', jsonb_build_object('students',v_students,'teachers',v_teachers,
       'student_pct', CASE WHEN coalesce(t.student_limit,0)>0 THEN round(100.0*v_students/t.student_limit)::int ELSE 0 END,
       'classes_30',v_c30,'last_activity',v_last),
    'invoices', coalesce((SELECT jsonb_agg(jsonb_build_object('amount',i.amount,'status',i.status,'due_date',i.due_date,
       'paid_at',i.paid_at,'period',i.period_month) ORDER BY i.due_date DESC NULLS LAST)
       FROM (SELECT * FROM saas_invoices WHERE tenant_id=p_tenant_id ORDER BY due_date DESC NULLS LAST LIMIT 12) i), '[]'::jsonb),
    'plans', (SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'price',price) ORDER BY price) FROM saas_plans WHERE active IS NOT FALSE)
  );
  RETURN r;
END;
$$;


--
-- Name: get_tenant_plan_limits(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tenant_plan_limits(target_tenant_id uuid) RETURNS TABLE(storage_limit_gb numeric, max_students integer, max_users integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    sp.storage_limit_gb, 
    sp.max_students, 
    sp.max_users
  FROM tenants t
  JOIN saas_plans sp ON t.saas_plan_id = sp.id
  WHERE t.id = target_tenant_id;
END;
$$;


