--

CREATE FUNCTION public.get_tenant_secret_status(p_tenant_id text) RETURNS TABLE(provider text, environment text, status text, secret_last_four text, account_label text, last_validated_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT
    secret.provider,
    secret.environment,
    secret.status,
    secret.secret_last_four,
    secret.account_label,
    secret.last_validated_at,
