--
-- Name: get_tenant_teacher_pay(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tenant_teacher_pay() RETURNS TABLE(id uuid, full_name text, avatar_url text, role text, hourly_rate numeric, pix_key text, pix_key_type text, commission_rate integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id, p.full_name, p.avatar_url, p.role, p.hourly_rate, p.pix_key, p.pix_key_type, p.commission_rate
  FROM profiles p
  WHERE (_my_role() = 'SUPER_ADMIN')
     OR (_my_role() IN ('SCHOOL_ADMIN','COORDINATOR') AND p.tenant_id = _my_tenant_id());
$$;


--
-- Name: get_tenant_usage(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tenant_usage(p_tenant_id text DEFAULT NULL::text) RETURNS TABLE(tenant_id text, student_count integer, student_limit integer, teacher_count integer, teacher_limit integer, student_pct numeric, teacher_pct numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT
        t.id AS tenant_id,
        (SELECT COUNT(*)::INT FROM profiles WHERE tenant_id = t.id AND role IN ('STUDENT','student')) AS student_count,
        t.student_limit,
        (SELECT COUNT(*)::INT FROM profiles WHERE tenant_id = t.id AND role IN ('TEACHER','teacher')) AS teacher_count,
        t.teacher_limit,
        CASE WHEN t.student_limit > 0 THEN
            ROUND(((SELECT COUNT(*)::NUMERIC FROM profiles WHERE tenant_id = t.id AND role IN ('STUDENT','student')) / t.student_limit) * 100, 1)
        ELSE 0 END AS student_pct,
        CASE WHEN t.teacher_limit > 0 THEN
            ROUND(((SELECT COUNT(*)::NUMERIC FROM profiles WHERE tenant_id = t.id AND role IN ('TEACHER','teacher')) / t.teacher_limit) * 100, 1)
        ELSE 0 END AS teacher_pct
    FROM tenants t
    WHERE (p_tenant_id IS NULL OR t.id = p_tenant_id);
$$;


--
-- Name: get_tenant_whatsapp_instance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tenant_whatsapp_instance(target_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    director_id uuid;
    instance_name text;
BEGIN
    -- 1. Find the School Admin (Director) for the given Tenant
    SELECT id INTO director_id
    FROM public.profiles
    WHERE tenant_id = target_tenant_id::text
    AND role = 'SCHOOL_ADMIN'
    LIMIT 1;

    IF director_id IS NULL THEN
        RETURN NULL;
    END IF;

    -- 2. Find a CONNECTED WhatsApp instance for this Director
    SELECT wi.instance_name INTO instance_name
    FROM public.whatsapp_instances wi
    WHERE wi.user_id = director_id
    AND wi.status = 'connected'
    ORDER BY wi.created_at DESC
    LIMIT 1;

    RETURN instance_name;
END;
$$;


--
-- Name: get_transfer_public(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_transfer_public(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.teacher_transfers; v_student text; v_from text;
BEGIN
  SELECT * INTO t FROM public.teacher_transfers WHERE token = p_token;
  IF t.id IS NULL THEN RETURN jsonb_build_object('error','not_found'); END IF;
  SELECT full_name INTO v_student FROM public.profiles WHERE id = t.student_id;
  SELECT full_name INTO v_from FROM public.profiles WHERE id = t.from_teacher_id;
  RETURN jsonb_build_object(
    'status', t.status,
    'proposed_slots', t.proposed_slots,
    'cutover_date', t.cutover_date,
    'reason', t.reason,
    'student_name', v_student,
    'from_teacher', v_from
  );
END;
$$;


--
-- Name: get_trial_notification_delivery_snapshot(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_trial_notification_delivery_snapshot(p_tenant_id text, p_opportunity_id uuid, p_notification_kind text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_runtime_role text := coalesce((select auth.jwt() ->> 'role'), '');
  v_kind text := pg_catalog.upper(pg_catalog.btrim(coalesce(
    p_notification_kind,
    ''
  )));
  v_opportunity public.opportunities%rowtype;
  v_request private.vendor_trial_teacher_requests%rowtype;
  v_link public.enrollment_links%rowtype;
  v_appointment public.appointments%rowtype;
  v_teacher public.profiles%rowtype;
  v_destination text;
begin
  if v_runtime_role <> 'service_role' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'forbidden'
    );
  end if;
  if v_kind not in (
    'TRIAL_TEACHER_REQUESTED',
    'TRIAL_MANAGEMENT_ACCEPTED'
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'unsupported_trial_notification'
    );
  end if;

  select opportunity.*
  into v_opportunity
  from public.opportunities as opportunity
  where opportunity.id = p_opportunity_id
    and opportunity.tenant_id = p_tenant_id;
  if not found
     or v_opportunity.kind <> 'TRIAL'
     or not private.tenant_is_operational(p_tenant_id) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'trial_notification_source_unavailable'
    );
  end if;
  if v_opportunity.is_test_fixture then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'test_fixture_suppressed'
    );
  end if;

  select request.*
  into v_request
  from private.vendor_trial_teacher_requests as request
  where request.opportunity_id = v_opportunity.id
    and request.tenant_id = v_opportunity.tenant_id;

  if v_kind = 'TRIAL_TEACHER_REQUESTED' then
    if v_request.id is null
       or v_request.status <> 'AWAITING_TEACHER'
       or v_opportunity.status <> 'OPEN'
       or v_opportunity.conversion_status <> 'OPEN'
       or v_opportunity.winner_teacher_id is not null
       or v_opportunity.professor_id is not null
       or v_opportunity.trial_appointment_id is not null then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'reason', 'trial_teacher_request_no_longer_pending'
      );
    end if;

    select link.*
    into v_link
    from public.enrollment_links as link
    where link.id = v_request.enrollment_link_id
      and link.opportunity_id = v_opportunity.id
      and link.tenant_id = v_opportunity.tenant_id;
    select profile.*
    into v_teacher
    from public.profiles as profile
    where profile.id = v_request.target_teacher_id
      and profile.tenant_id = v_opportunity.tenant_id;

    if v_link.id is null
       or v_link.status <> 'USED'
       or v_link.purpose <> 'TRIAL_CONFIRMATION'
       or v_link.student_confirmed_at is null
       or v_request.slot_start <= pg_catalog.now() + interval '5 minutes'
       or v_teacher.id is null
       or v_teacher.role <> 'TEACHER'
       or lower(pg_catalog.btrim(coalesce(
         v_teacher.lifecycle_status,
         ''
       ))) <> 'active'
       or v_teacher.is_test_account is distinct from false
       or not exists (
         select 1
         from public.tenant_memberships as membership
         where membership.tenant_id = v_opportunity.tenant_id
           and membership.user_id = v_teacher.id
           and membership.role = 'TEACHER'
           and membership.status = 'ACTIVE'
       ) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'reason', 'trial_teacher_request_binding_changed'
      );
    end if;

    v_destination := private.normalize_notification_phone(v_teacher.phone);
    if v_destination is null then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'retryable', true,
        'reason', 'trial_teacher_destination_unavailable'
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'teacherId', v_teacher.id,
      'destination', v_destination
    );
  end if;

  if v_opportunity.status <> 'CLAIMED'
     or v_opportunity.conversion_status <> 'OPEN'
     or v_opportunity.trial_appointment_id is null
     or v_opportunity.winner_teacher_id is null
     or v_opportunity.professor_id is distinct from
       v_opportunity.winner_teacher_id then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'trial_acceptance_no_longer_valid'
    );
  end if;
  select appointment.*
  into v_appointment
  from public.appointments as appointment
  where appointment.id = v_opportunity.trial_appointment_id
    and appointment.tenant_id = v_opportunity.tenant_id
    and appointment.teacher_id = v_opportunity.winner_teacher_id
    and appointment.professor_id = v_opportunity.winner_teacher_id;
  select profile.*
  into v_teacher
  from public.profiles as profile
  where profile.id = v_opportunity.winner_teacher_id
    and profile.tenant_id = v_opportunity.tenant_id;
  if v_appointment.id is null
     or lower(coalesce(v_appointment.status, '')) not in (
       'scheduled', 'confirmed'
     )
     or v_appointment.start_time <= pg_catalog.now()
     or v_teacher.id is null
     or v_teacher.is_test_account is distinct from false
     or lower(pg_catalog.btrim(coalesce(
       v_teacher.lifecycle_status,
       ''
     ))) <> 'active'
     or not exists (
       select 1
       from public.tenant_memberships as membership
       where membership.tenant_id = v_opportunity.tenant_id
         and membership.user_id = v_teacher.id
         and membership.role = 'TEACHER'
         and membership.status = 'ACTIVE'
     )
     or (
       v_request.id is not null
       and (
         v_request.status <> 'ACCEPTED'
         or v_request.target_teacher_id <> v_teacher.id
         or v_request.accepted_appointment_id <> v_appointment.id
       )
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'trial_acceptance_binding_changed'
    );
  end if;

  v_destination := private.trial_management_destination(
    v_opportunity.tenant_id
  );
  if v_destination is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'retryable', true,
      'reason', 'trial_management_destination_unavailable'
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'teacherId', null,
    'destination', v_destination
  );
end;
$$;


--
-- Name: get_user_id_by_email(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_id_by_email(email_input text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  found_id UUID;
BEGIN
  -- Check if the configured user (admin) has permission or if we just allow it securely
  -- Since this returns only the ID (public info relative to privacy), it's acceptable for this flow
  
  SELECT id INTO found_id
  FROM auth.users
  WHERE email = email_input;
  
  RETURN found_id;
END;
$$;


