    AS $$
  SELECT commission_rate FROM profiles WHERE id = p_vendor AND role = 'SALESPERSON';
$$;


--
-- Name: get_vendor_overview(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_vendor_overview(p_vendor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_role text; v_tenant text; vp profiles%ROWTYPE;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id=v_uid;
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN jsonb_build_object('error','sem_permissao'); END IF;
  SELECT * INTO vp FROM profiles WHERE id=p_vendor_id AND role='SALESPERSON';
  IF NOT FOUND THEN RETURN jsonb_build_object('error','nao_encontrado'); END IF;
  IF v_role='SCHOOL_ADMIN' AND vp.tenant_id<>v_tenant THEN RETURN jsonb_build_object('error','sem_permissao'); END IF;

  RETURN jsonb_build_object(
    'profile', jsonb_build_object('id',vp.id,'full_name',vp.full_name,'avatar_url',vp.avatar_url,'email',vp.email,
       'phone',vp.phone,'status',vp.status,'commission_rate',vp.commission_rate,
       'pix_ok',(vp.pix_key IS NOT NULL AND vp.pix_key<>''),'pix_key',vp.pix_key),
    'commissions', coalesce((SELECT jsonb_agg(jsonb_build_object('id',vc.id,'amount',vc.amount_brl,'status',vc.status,
       'created_at',vc.created_at,'confirmed_at',vc.confirmed_at,'paid_at',vc.paid_at,
       'student',(SELECT full_name FROM profiles WHERE id=vc.student_id)) ORDER BY vc.created_at DESC)
       FROM vendor_commissions vc WHERE vc.vendor_id=p_vendor_id), '[]'::jsonb),
    'audit', coalesce((SELECT jsonb_agg(jsonb_build_object('field',a.field,'old_value',a.old_value,'new_value',a.new_value,
       'changed_at',a.changed_at,'changed_by',(SELECT full_name FROM profiles WHERE id=a.changed_by)) ORDER BY a.changed_at DESC)
       FROM (SELECT * FROM profile_audit_log WHERE profile_id=p_vendor_id ORDER BY changed_at DESC LIMIT 20) a), '[]'::jsonb)
  );
END;
$$;


