--

CREATE FUNCTION public.grade_quiz(p_activity_id uuid, p_answers integer[], p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.assert_active_student_learning_mutation();
  return public.grade_quiz_lifecycle_core(
    p_activity_id,
