--
-- Name: FUNCTION grade_quiz(p_activity_id uuid, p_answers integer[], p_request_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.grade_quiz(p_activity_id uuid, p_answers integer[], p_request_key text) IS 'Atomic server-authoritative quiz grading, progression, XP, streak and idempotent heart consumption.';


--
-- Name: grade_quiz_core(uuid, integer[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grade_quiz_core(p_activity_id uuid, p_answers integer[], p_request_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_student_id uuid := auth.uid();
  v_profile record;
  v_activity record;
  v_enrollment public.student_path_enrollments%rowtype;
  v_replay_attempt public.student_learning_activity_attempts%rowtype;
  v_request_key text := nullif(
    pg_catalog.btrim(coalesce(p_request_key, '')),
    ''
  );
  v_request_payload jsonb;
  v_current record;
  v_question jsonb;
  v_questions jsonb;
  v_option_count integer;
  v_correct_index integer;
  v_question_id text;
  v_question_results jsonb := '[]'::jsonb;
  v_total integer;
  v_correct integer := 0;
  v_score integer;
  v_passed boolean;
  v_status text;
  v_base_xp integer;
  v_xp_earned integer := 0;
  v_daily_xp integer;
  v_today date;
  v_new_xp integer;
  v_new_level integer;
  v_existing_award public.student_verified_xp_awards%rowtype;
  v_already_awarded boolean := false;
  v_progression jsonb;
  v_result jsonb;
  v_streak integer;
  v_now timestamptz := pg_catalog.now();
  i integer;
begin
  if v_student_id is null or p_activity_id is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  if v_request_key is not null
     and pg_catalog.length(v_request_key) not between 8 and 180 then
    raise exception using
      errcode = '22023',
      message = 'invalid_quiz_request_key';
  end if;

  v_request_payload := pg_catalog.jsonb_build_object(
    'answers', pg_catalog.to_jsonb(p_answers)
  );

  select
    profile.tenant_id,
    profile.role,
    coalesce(profile.xp, 0) as xp,
    coalesce(profile.level, 1) as level,
    coalesce(profile.daily_xp, 0) as daily_xp,
    profile.daily_xp_date,
    coalesce(profile.is_test_account, false) as is_test_account
    into v_profile
    from public.profiles as profile
   where profile.id = v_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  select
    activity.id,
    activity.unit_id,
    activity.type,
    activity.content,
    least(100, greatest(0, coalesce(activity.xp_reward, 30))) as xp_reward,
    unit.path_id,
    unit.skill_focus,
    path.tenant_id as path_tenant_id
    into v_activity
    from public.unit_activities as activity
    join public.learning_units as unit
      on unit.id = activity.unit_id
    join public.learning_paths as path
      on path.id = unit.path_id
   where activity.id = p_activity_id
     and activity.type in ('quiz', 'grammar_drill', 'reading')
     and path.active is true
     and (
       path.tenant_id is null
       or path.tenant_id = v_profile.tenant_id
     );

  if not found then
    raise exception using
      errcode = '42501',
      message = 'quiz_not_available_for_student';
  end if;

  -- Resolve a durable keyed replay before requiring an ACTIVE enrollment. This
  -- covers both failed and passing attempts, including the final quiz that may
  -- already have closed the path when the HTTP response is lost.
  if v_request_key is not null then
    select *
      into v_replay_attempt
      from public.student_learning_activity_attempts as attempt
     where attempt.student_id = v_student_id
       and attempt.request_key = v_request_key
     for update;

    if found then
      if v_replay_attempt.activity_id is distinct from p_activity_id
         or v_replay_attempt.attempt_kind <> 'QUIZ'
         or v_replay_attempt.request_payload is distinct from v_request_payload then
        raise exception using
          errcode = '22023',
          message = 'idempotency_key_reused';
      end if;

      return v_replay_attempt.result || pg_catalog.jsonb_build_object(
        'alreadyApplied', true
      );
    end if;
  end if;

  -- Compatibility for legacy two-argument callers: an exact replay of the most
  -- recent passing payload is safe even after progression closed the path.
  select *
    into v_replay_attempt
    from public.student_learning_activity_attempts as attempt
   where attempt.student_id = v_student_id
     and attempt.activity_id = p_activity_id
     and attempt.attempt_kind = 'QUIZ'
     and attempt.passed is true
   order by attempt.created_at desc, attempt.id desc
   limit 1;

  if found
     and v_replay_attempt.request_payload = v_request_payload then
    return v_replay_attempt.result || pg_catalog.jsonb_build_object(
      'alreadyApplied', true
    );
  end if;

  select *
    into v_enrollment
    from public.student_path_enrollments as enrollment
   where enrollment.student_id = v_student_id
     and enrollment.path_id = v_activity.path_id
     and enrollment.tenant_id = v_profile.tenant_id
     and enrollment.status = 'ACTIVE'
     and enrollment.completed_at is null
   for update;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'active_learning_enrollment_required';
  end if;

  select next_activity.activity_id, next_activity.unit_id
    into v_current
    from private.next_incomplete_learning_activity(
      v_student_id,
      v_activity.path_id
    ) as next_activity;

  if not found or v_current.activity_id <> p_activity_id then
    raise exception using
      errcode = 'P0001',
      message = 'learning_activity_not_current';
  end if;

  v_questions := case v_activity.type
    when 'grammar_drill' then v_activity.content -> 'exercises'
    else v_activity.content -> 'questions'
  end;

  if v_questions is null
     or pg_catalog.jsonb_typeof(v_questions) is distinct from 'array' then
    raise exception using
      errcode = '22023',
      message = 'invalid_quiz';
  end if;

  v_total := pg_catalog.jsonb_array_length(v_questions);
  if v_total < 1
     or v_total > 100
     or p_answers is null
     or pg_catalog.cardinality(p_answers) <> v_total then
    raise exception using
      errcode = '22023',
      message = 'invalid_answers';
  end if;

  for i in 0 .. v_total - 1 loop
    v_question := v_questions -> i;

    if pg_catalog.jsonb_typeof(v_question) is distinct from 'object'
       or pg_catalog.jsonb_typeof(v_question -> 'options')
            is distinct from 'array'
       or coalesce(
            coalesce(
              v_question ->> 'correct',
              v_question ->> 'correctIndex',
              v_question ->> 'correct_option_index'
            ) ~ '^[0-9]+$',
            false
          ) is not true then
      raise exception using
        errcode = '22023',
        message = 'invalid_quiz';
    end if;

    v_option_count := pg_catalog.jsonb_array_length(v_question -> 'options');
    v_correct_index := coalesce(
      v_question ->> 'correct',
      v_question ->> 'correctIndex',
      v_question ->> 'correct_option_index'
    )::integer;
    v_question_id := coalesce(
      nullif(pg_catalog.btrim(v_question ->> 'id'), ''),
      'question-' || (i + 1)::text
    );
    if v_option_count < 2
       or v_correct_index >= v_option_count
       or p_answers[i + 1] is null
       or p_answers[i + 1] < 0
       or p_answers[i + 1] >= v_option_count then
      raise exception using
        errcode = '22023',
        message = 'invalid_answers';
    end if;

    if p_answers[i + 1] = v_correct_index then
      v_correct := v_correct + 1;
    end if;

    v_question_results := v_question_results || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'questionId', v_question_id,
        'questionIndex', i,
        'selectedIndex', p_answers[i + 1],
        'correct', p_answers[i + 1] = v_correct_index,
        'correctIndex', v_correct_index,
        'explanation', coalesce(
          nullif(pg_catalog.btrim(v_question ->> 'exp'), ''),
          nullif(pg_catalog.btrim(v_question ->> 'explanation'), ''),
          nullif(pg_catalog.btrim(v_question ->> 'explanation_pt'), ''),
          nullif(pg_catalog.btrim(v_question ->> 'feedback'), '')
        )
      )
    );
  end loop;

  v_score := pg_catalog.round(
    (v_correct::numeric / v_total::numeric) * 100
  );
  v_passed := v_score >= 60;
  v_status := case when v_passed then 'COMPLETED' else 'IN_PROGRESS' end;
  v_base_xp := v_activity.xp_reward;
  v_today := (v_now at time zone 'America/Sao_Paulo')::date;

  insert into public.student_activity_progress (
    student_id,
    activity_id,
    unit_id,
    status,
    score,
    attempts,
    completed_at,
    last_attempt_at
  ) values (
    v_student_id,
    p_activity_id,
    v_activity.unit_id,
    v_status,
    v_score,
    1,
    case when v_passed then v_now else null end,
    v_now
  )
  on conflict (student_id, activity_id) do update
    set status = case
          when excluded.status = 'COMPLETED' then 'COMPLETED'
          else 'IN_PROGRESS'
        end,
        score = greatest(
          coalesce(public.student_activity_progress.score, 0),
          excluded.score
        ),
        attempts =
          coalesce(public.student_activity_progress.attempts, 0) + 1,
        completed_at = case
          when excluded.status = 'COMPLETED' then
            coalesce(public.student_activity_progress.completed_at, v_now)
          else null
        end,
        last_attempt_at = v_now;

  if v_passed then
    v_progression := private.advance_student_learning_enrollment(
      v_enrollment.id,
      v_student_id,
      v_activity.path_id,
      v_now
    );
  else
    v_progression := pg_catalog.jsonb_build_object(
      'nextActivityId', p_activity_id,
      'currentUnitId', v_activity.unit_id,
      'pathCompleted', false
    );
  end if;

  select *
    into v_existing_award
    from public.student_verified_xp_awards as award
   where award.student_id = v_student_id
     and award.source_type = 'LEARNING_PATH_QUIZ'
     and award.source_id = p_activity_id::text;
  v_already_awarded := found;

  v_new_xp := v_profile.xp;
  v_new_level := v_profile.level;

  if v_passed and not v_already_awarded then
    v_daily_xp := case
      when v_profile.daily_xp_date = v_today then v_profile.daily_xp
      else 0
    end;
    v_xp_earned := pg_catalog.round(
      v_base_xp * (v_score::numeric / 100)
    );
    v_xp_earned := least(
      v_xp_earned,
      greatest(0, 250 - v_daily_xp)
    );
    if v_profile.is_test_account then
      v_xp_earned := 0;
    end if;

    v_new_xp := v_profile.xp + v_xp_earned;
    v_new_level := pg_catalog.floor(v_new_xp / 1000) + 1;

    insert into public.student_verified_xp_awards (
      tenant_id,
      student_id,
      source_type,
      source_id,
      base_xp,
      xp_awarded,
      score_used,
      test_fixture
    ) values (
      v_profile.tenant_id,
      v_student_id,
      'LEARNING_PATH_QUIZ',
      p_activity_id::text,
      v_base_xp,
      v_xp_earned,
      v_score,
      v_profile.is_test_account
    );

    update public.profiles
       set xp = v_new_xp,
           level = v_new_level,
           daily_xp = v_daily_xp + v_xp_earned,
           daily_xp_date = v_today,
           last_activity = v_now
     where id = v_student_id;
  end if;

  v_streak := private.record_student_learning_practice(
    v_student_id,
    v_score,
    v_activity.type,
    v_activity.skill_focus,
    v_now
  );

  v_result := pg_catalog.jsonb_build_object(
    'score', v_score,
    'correctAnswers', v_correct,
    'totalQuestions', v_total,
    'questionResults', v_question_results,
    'passed', v_passed,
    'status', v_status,
    'xpEarned', v_xp_earned,
    'alreadyAwarded', v_already_awarded,
    'leveledUp', v_new_level > v_profile.level,
    'newLevel', v_new_level,
    'streakCount', v_streak
  ) || v_progression;

  insert into public.student_learning_activity_attempts (
    tenant_id,
    student_id,
    enrollment_id,
    activity_id,
    attempt_kind,
    request_key,
    request_payload,
    score,
    passed,
    result,
    created_at
  ) values (
    v_profile.tenant_id,
    v_student_id,
    v_enrollment.id,
    p_activity_id,
    'QUIZ',
    v_request_key,
    v_request_payload,
    v_score,
    v_passed,
    v_result,
    v_now
  );

  return v_result;
end;
$_$;


--
-- Name: FUNCTION grade_quiz_core(p_activity_id uuid, p_answers integer[], p_request_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.grade_quiz_core(p_activity_id uuid, p_answers integer[], p_request_key text) IS 'Server-authoritative ordered learning-path quiz attempt with keyed replay, pass-gated progression, skills, streak and idempotent XP.';


--
-- Name: grade_quiz_lifecycle_core(uuid, integer[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grade_quiz_lifecycle_core(p_activity_id uuid, p_answers integer[], p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_id uuid := auth.uid();
  v_request_key text := pg_catalog.btrim(coalesce(p_request_key, ''));
  v_result jsonb;
  v_heart_result jsonb;
  v_wrong_answers integer;
  v_consumed integer := 0;
  v_hearts integer;
  i integer;
begin
  if pg_catalog.length(v_request_key) not between 8 and 180 then
    raise exception using
      errcode = '22023',
      message = 'invalid_quiz_request_key';
  end if;

  v_result := public.grade_quiz_core(
    p_activity_id,
    p_answers,
    v_request_key
  );

  v_wrong_answers := least(
    5,
    greatest(
      0,
      coalesce(nullif(v_result ->> 'totalQuestions', '')::integer, 0)
        - coalesce(nullif(v_result ->> 'correctAnswers', '')::integer, 0)
    )
  );

  for i in 1 .. v_wrong_answers loop
    v_heart_result := public.consume_student_heart(
      'learning-heart-' || pg_catalog.md5(
        p_activity_id::text || ':' || v_request_key || ':' || i::text
      ),
      'WRONG_ANSWER'
    );
    v_hearts := nullif(v_heart_result ->> 'hearts', '')::integer;
    if coalesce((v_heart_result ->> 'consumed')::boolean, false)
       and not coalesce(
         (v_heart_result ->> 'alreadyApplied')::boolean,
         false
       ) then
      v_consumed := v_consumed + 1;
    end if;
  end loop;

  if v_hearts is null and v_student_id is not null then
    select coalesce(profile.hearts, 5)
      into v_hearts
      from public.profiles as profile
     where profile.id = v_student_id;
  end if;

  return v_result || pg_catalog.jsonb_build_object(
    'hearts', v_hearts,
    'heartsConsumed', v_consumed
  );
end;
$$;


--
-- Name: FUNCTION grade_quiz_lifecycle_core(p_activity_id uuid, p_answers integer[], p_request_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.grade_quiz_lifecycle_core(p_activity_id uuid, p_answers integer[], p_request_key text) IS 'Atomic server-authoritative quiz grading, progression, XP, streak and idempotent heart consumption.';


--
-- Name: grant_referral_reward_on_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_referral_reward_on_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('RECEIVED','RECEIVED_IN_CASH') AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    PERFORM process_referral_reward(NEW.student_id);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_ai_knowledge_embedding_config(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_ai_knowledge_embedding_config() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (
    new.embedding_model,
    new.embedding_dimensions
  ) is distinct from (
    old.embedding_model,
    old.embedding_dimensions
  ) and exists (
    select 1
    from public.ai_knowledge_chunks as chunk
    where chunk.knowledge_base_id = old.id
    limit 1
  ) then
    raise exception 'knowledge_base_embedding_config_is_immutable'
      using errcode = '23514';
  end if;
  return new;
end
$$;


--
-- Name: guard_enrollment_test_offer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_enrollment_test_offer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_is_test boolean := coalesce((new.payload ->> 'testMode')::boolean, false);
  v_was_test boolean := case
    when tg_op = 'UPDATE' then coalesce((old.payload ->> 'testMode')::boolean, false)
    else false
  end;
  v_jwt_role text := coalesce(auth.jwt() ->> 'role', '');
begin
  if new.kind = 'ENROLLMENT' and v_is_test and not v_was_test then
    if v_jwt_role <> 'service_role'
       and public._my_role() is distinct from 'SUPER_ADMIN' then
      raise exception 'forbidden: testMode exige SUPER_ADMIN';
    end if;

    new.payload := coalesce(new.payload, '{}'::jsonb) || jsonb_build_object(
      'testMode', true,
      'testFixtureKey', 'wise-wolf-primary-student:' || new.id::text
    );
  end if;

  return new;
exception
  when invalid_text_representation then
    raise exception 'testMode invalido';
end;
$$;


--
-- Name: guard_open_wolfie_realtime_turn_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_open_wolfie_realtime_turn_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  session_stage text;
  session_status text;
  session_finished_at timestamptz;
  session_classic_handoff_at timestamptz;
begin
  if new.source_kind is distinct from 'openai_realtime' then
    return new;
  end if;

  select current_stage, scenario_status, finished_at, classic_handoff_at
    into session_stage, session_status, session_finished_at,
         session_classic_handoff_at
    from public.wolfie_sessions
   where id = new.session_id
   for share;

  if not found then
    raise exception using
      errcode = '23503',
      message = 'wolfie_session_not_found';
  end if;
  if session_finished_at is not null
     or session_stage = 'completed'
     or session_status in ('completed', 'abandoned', 'failed') then
    raise exception using
      errcode = '55000',
      message = 'wolfie_realtime_session_finished';
  end if;
  if session_classic_handoff_at is not null then
    raise exception using
      errcode = '55000',
      message = 'wolfie_realtime_session_handed_off';
  end if;
  return new;
end;
$$;


--
-- Name: guard_profile_test_fixture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_profile_test_fixture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
declare
  v_jwt_role text := coalesce(auth.jwt() ->> 'role', '');
begin
  if row(new.is_test_account, new.test_fixture_key)
     is distinct from row(old.is_test_account, old.test_fixture_key)
     and coalesce(current_setting('app.enrollment_claim', true), '') <> '1'
     and v_jwt_role <> 'service_role'
     and public._my_role() is distinct from 'SUPER_ADMIN' then
    raise exception 'forbidden: marcador de fixture protegido';
  end if;
  return new;
end;
$$;


--
-- Name: guard_student_billing_period_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_student_billing_period_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || new.tenant_id || ':' || new.student_id::text,
      0
    )
  );
  if not exists (
    select 1
      from public.profiles as profile
     where profile.id = new.student_id
       and profile.tenant_id = new.tenant_id
       and profile.role = 'STUDENT'
       and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
  ) or exists (
    select 1
      from public.student_offboarding_operations as operation
     where operation.tenant_id = new.tenant_id
       and operation.student_id = new.student_id
       and operation.status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
  ) or exists (
    select 1
      from public.student_account_deletion_claims as deletion
     where deletion.tenant_id = new.tenant_id
       and deletion.student_id = new.student_id
       and deletion.status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
  ) or exists (
    select 1
      from public.asaas_provider_creation_attempts as creation
     where creation.tenant_id = new.tenant_id
       and creation.lifecycle_student_id = new.student_id
       and creation.lifecycle_released_at is null
       and creation.status in ('CLAIMED', 'SUBMITTING', 'UNKNOWN', 'SUCCEEDED', 'BLOCKED')
  ) or exists (
    select 1
      from public.student_billing_method_operations as billing_method
     where billing_method.tenant_id = new.tenant_id
       and billing_method.student_id = new.student_id
       and billing_method.status in ('CLAIMED', 'MUTATING', 'UNKNOWN', 'BLOCKED')
  ) then
    raise exception using
      errcode = '55000',
      message = 'student_billing_lifecycle_inactive';
  end if;
  return new;
end;
$$;


--
-- Name: guard_wolfie_profile_server_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_wolfie_profile_server_fields() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if current_user in ('authenticated', 'anon')
     and row(
       new.xp,
       new.level,
       new.daily_xp,
       new.daily_xp_date,
       new.role,
       new.tenant_id,
       new.is_test_account,
       new.hearts,
       new.hearts_updated_at,
       new.hearts_full_notified,
       new.streak_count,
       new.last_streak_date,
       new.last_activity
     ) is distinct from row(
       old.xp,
       old.level,
       old.daily_xp,
       old.daily_xp_date,
       old.role,
       old.tenant_id,
       old.is_test_account,
       old.hearts,
       old.hearts_updated_at,
       old.hearts_full_notified,
       old.streak_count,
       old.last_streak_date,
       old.last_activity
     ) then
    raise exception using
      errcode = '42501',
      message = 'profile_server_fields_are_read_only';
  end if;

  if current_user in ('authenticated', 'anon')
     and row(
       new.current_book_part,
       new.evaluation_unlocked,
       new.unlocked_tests
     ) is distinct from row(
       old.current_book_part,
       old.evaluation_unlocked,
       old.unlocked_tests
     ) then
    raise exception using
      errcode = '42501',
      message = 'pedagogical_progression_fields_are_read_only';
  end if;

  -- Placement changes use set_student_pedagogical_placement so module and book
  -- part cannot diverge. Teacher profiles keep using module as a specialization.
  if current_user in ('authenticated', 'anon')
     and old.role = 'STUDENT'
     and new.module is distinct from old.module
  then
    raise exception using
      errcode = '42501',
      message = 'pedagogical_module_is_not_self_editable';
  end if;

  return new;
end;
$$;


--
-- Name: guard_wolfie_session_turn_transport(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_wolfie_session_turn_transport() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  opposite_transport_exists boolean;
  realtime_anchor uuid;
  classic_anchor uuid;
  classic_handoff_at timestamptz;
begin
  select realtime_first_client_turn_id, classic_first_client_turn_id,
         wolfie_sessions.classic_handoff_at
    into realtime_anchor, classic_anchor, classic_handoff_at
    from public.wolfie_sessions
   where id = new.session_id
   for update;
  if not found then
    raise exception using
      errcode = '23503',
      message = 'wolfie_session_not_found';
  end if;

  if (
       new.source_kind = 'classic'
       and realtime_anchor is not null
       and classic_handoff_at is null
     ) or (
       new.source_kind = 'openai_realtime'
       and (classic_anchor is not null or classic_handoff_at is not null)
     ) then
    raise exception using
      errcode = '55000',
      message = 'wolfie_session_transport_mismatch';
  end if;

  select exists (
    select 1
      from public.wolfie_turns
     where session_id = new.session_id
       and source_kind <> new.source_kind
  ) into opposite_transport_exists;
  if opposite_transport_exists
     and not (
       new.source_kind = 'classic'
       and classic_handoff_at is not null
     ) then
    raise exception using
      errcode = '55000',
      message = 'wolfie_session_transport_mismatch';
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION guard_wolfie_session_turn_transport(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.guard_wolfie_session_turn_transport() IS 'Elects one writer transport per session and rejects classic/Realtime mixing under the session lock.';


--
-- Name: handle_contract_signed_hook(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_contract_signed_hook() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'pg_temp'
    AS $$
declare
  service_key text;
begin
  if new.contract_accepted is true
     and coalesce(old.contract_accepted, false) is false
     and coalesce(new.wa_welcome_sent, false) is false
     and coalesce(new.is_test_account, false) is false
     and coalesce(current_setting('app.enrollment_claim', true), '') <> '1' then
    begin
      select decrypted_secret
        into service_key
        from vault.decrypted_secrets
       where name = 'wisewolf_service_role_key'
       limit 1;

      if service_key is null or service_key = '' then
        raise exception 'service key ausente';
      end if;

      if new.phone is not null then
        insert into public.whatsapp_messages_log (
          student_id, phone, message_type, status
        )
        values (new.id, new.phone, 'WELCOME_ENROLLMENT', 'QUEUED');

        perform net.http_post(
          url := 'http://kong:8000/functions/v1/whatsapp-notificacao-matricula',
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || service_key
          ),
          body := jsonb_build_object('student_id', new.id),
          timeout_milliseconds := 60000
        );
      else
        raise warning 'handle_contract_signed_hook: profile % sem phone', new.id;
      end if;
    exception when others then
      raise warning 'handle_contract_signed_hook: falha para %: %', new.id, sqlerrm;
    end;
  end if;

  return new;
end;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.profiles (
    id, email, full_name, role, tenant_id, status_financial
  )
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NULLIF(NEW.raw_user_meta_data ->> 'full_name', ''), 'Novo Usuario'),
    'STUDENT',
    NULL,
    'PENDING'
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
END;
$$;


--
-- Name: handoff_wolfie_realtime_to_classic(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handoff_wolfie_realtime_to_classic(p_session_id uuid, p_student_id uuid, p_tenant_id text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_current_stage text;
  v_current_status text;
  v_finished_at timestamptz;
  v_realtime_anchor uuid;
  v_classic_anchor uuid;
  v_handoff_at timestamptz;
  v_requires_retry boolean;
  v_analysis_turn record;
  v_analysis_marker jsonb;
  v_claimed_at timestamptz;
  v_lease_checked_at timestamptz;
  v_stale_processing_turn_ids uuid[] := '{}'::uuid[];
  v_released_processing_count integer := 0;
begin
  if p_session_id is null
     or p_student_id is null
     or nullif(pg_catalog.btrim(p_tenant_id), '') is null then
    raise exception using errcode = '22023', message = 'invalid_classic_handoff';
  end if;

  select
    session.current_stage,
    session.scenario_status,
    session.finished_at,
    session.realtime_first_client_turn_id,
    session.classic_first_client_turn_id,
    session.classic_handoff_at
  into
    v_current_stage,
    v_current_status,
    v_finished_at,
    v_realtime_anchor,
    v_classic_anchor,
    v_handoff_at
  from public.wolfie_sessions as session
  where session.id = p_session_id
    and session.student_id = p_student_id
    and session.tenant_id = p_tenant_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'wolfie_session_not_found';
  end if;
  select
    v_current_status = 'awaiting_retry'
    or exists (
      select 1
        from public.wolfie_corrections as correction
       where correction.session_id = p_session_id
         and correction.status = 'active'
         and correction.requires_retry = true
         and correction.retry_completed = false
    )
    into v_requires_retry;
  if v_handoff_at is not null then
    return pg_catalog.jsonb_build_object(
      'handedOff', true,
      'idempotent', true,
      'reused', true,
      'sessionId', p_session_id,
      'classicHandoffAt', v_handoff_at,
      'currentStage', v_current_stage,
      'scenarioStatus', v_current_status,
      'requiresRetry', v_requires_retry,
      'releasedRealtimeClaims', 0
    );
  end if;
  if v_finished_at is not null
     or v_current_stage = 'completed'
     or v_current_status in ('completed', 'abandoned', 'failed') then
    raise exception using errcode = '55000', message = 'wolfie_session_finished';
  end if;
  if v_realtime_anchor is null then
    raise exception using errcode = '55000', message = 'realtime_anchor_required';
  end if;
  if v_classic_anchor is not null then
    raise exception using errcode = '55000', message = 'classic_transport_already_started';
  end if;
  if exists (
    select 1
      from public.wolfie_live_grants as live_grant
     where live_grant.session_id = p_session_id
       and live_grant.student_id = p_student_id
       and live_grant.tenant_id = p_tenant_id
       and live_grant.status in ('RESERVED', 'ACTIVE', 'CLOSING')
  ) then
    raise exception using errcode = '55000', message = 'wolfie_live_grant_still_open';
  end if;
  -- Mirror claim_wolfie_realtime_analysis exactly: a processing claim owns a
  -- two-minute lease only when claimedAt parses and has not expired. Lock the
  -- marker rows after the session row so claim, finalize and handoff cannot
  -- cross the transport boundary with different snapshots.
  v_lease_checked_at := pg_catalog.clock_timestamp();
  for v_analysis_turn in
    select
      turn.id,
      coalesce(turn.structured_payload, '{}'::jsonb) as structured_payload
    from public.wolfie_turns as turn
    where turn.session_id = p_session_id
      and turn.speaker = 'wolfie'
      and turn.source_kind = 'openai_realtime'
      and turn.structured_payload #>> '{realtimeAnalysis,status}' in (
        'processing',
        'awaiting_confirmation'
      )
    order by turn.id
    for update
  loop
    v_analysis_marker :=
      v_analysis_turn.structured_payload -> 'realtimeAnalysis';
    if v_analysis_marker ->> 'status' = 'awaiting_confirmation' then
      raise exception using
        errcode = '55000',
        message = 'wolfie_realtime_analysis_not_terminal';
    end if;

    begin
      v_claimed_at := nullif(v_analysis_marker ->> 'claimedAt', '')::timestamptz;
    exception when others then
      v_claimed_at := null;
    end;
    if v_claimed_at is not null
       and v_lease_checked_at - v_claimed_at < interval '2 minutes' then
      raise exception using
        errcode = '55000',
        message = 'wolfie_realtime_analysis_not_terminal';
    end if;

    v_stale_processing_turn_ids := pg_catalog.array_append(
      v_stale_processing_turn_ids,
      v_analysis_turn.id
    );
  end loop;

  v_handoff_at := pg_catalog.clock_timestamp();
  if pg_catalog.cardinality(v_stale_processing_turn_ids) > 0 then
    update public.wolfie_turns as turn
       set structured_payload =
         coalesce(turn.structured_payload, '{}'::jsonb)
         || pg_catalog.jsonb_build_object(
           'eligibleForCorrection', false,
           'realtimeAnalysis',
             coalesce(
               turn.structured_payload -> 'realtimeAnalysis',
               '{}'::jsonb
             ) || pg_catalog.jsonb_build_object(
               'status', 'unavailable',
               'reason', 'classic_handoff',
               'unavailableAt', v_handoff_at
             )
         )
     where turn.session_id = p_session_id
       and turn.id = any(v_stale_processing_turn_ids);
    get diagnostics v_released_processing_count = row_count;
  end if;

  update public.wolfie_sessions
     set classic_handoff_at = v_handoff_at,
         updated_at = v_handoff_at
   where id = p_session_id
     and student_id = p_student_id
     and tenant_id = p_tenant_id;

  return pg_catalog.jsonb_build_object(
    'handedOff', true,
    'idempotent', false,
    'reused', false,
    'sessionId', p_session_id,
    'classicHandoffAt', v_handoff_at,
    'currentStage', v_current_stage,
    'scenarioStatus', v_current_status,
    'requiresRetry', v_requires_retry,
    'releasedRealtimeClaims', v_released_processing_count
  );
end;
$$;


--
-- Name: hub_activate_paid_checkout(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_activate_paid_checkout(p_checkout_id uuid, p_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
begin
  v_account_id := private.hub_lock_provider_event_writer(p_checkout_id);
  if not exists (
    select 1
    from public.hub_accounts account
    where account.id = v_account_id
      and account.status = 'ACTIVE'
  ) then
    raise exception 'hub_account_inactive' using errcode = '55000';
  end if;
  return private.hub_activate_paid_checkout_provider_apply(
    p_checkout_id,
    p_payment_id
  );
end;
$$;


--
-- Name: FUNCTION hub_activate_paid_checkout(p_checkout_id uuid, p_payment_id text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hub_activate_paid_checkout(p_checkout_id uuid, p_payment_id text) IS 'Serializes paid Hub activation against durable provider cancellation.';


--
-- Name: hub_adopt_provider_creation_binding(uuid, uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_adopt_provider_creation_binding(p_attempt_id uuid, p_claim_token uuid, p_account_id uuid, p_checkout_id uuid, p_provider_entity_id text, p_provider_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_id text := nullif(pg_catalog.btrim(p_provider_entity_id), '');
  v_provider_status text := nullif(pg_catalog.btrim(p_provider_status), '');
  v_attempt public.asaas_provider_creation_attempts%rowtype;
  v_account public.hub_accounts%rowtype;
  v_checkout public.hub_checkout_sessions%rowtype;
  v_recorded jsonb;
begin
  perform private.hub_service_role_required();
  if p_attempt_id is null or p_account_id is null or p_checkout_id is null
     or v_provider_id is null
     or pg_catalog.char_length(v_provider_id) > 200 then
    raise exception 'invalid_hub_provider_creation_adoption'
      using errcode = '22023';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-provider-operation:' || p_account_id::text,
      0
    )
  );

  select account.* into v_account
  from public.hub_accounts as account
  where account.id = p_account_id
  for update;
  select checkout.* into v_checkout
  from public.hub_checkout_sessions as checkout
  where checkout.id = p_checkout_id
    and checkout.account_id = p_account_id
  for update;
  select attempt.* into v_attempt
  from public.asaas_provider_creation_attempts as attempt
  where attempt.id = p_attempt_id
  for update;
  if v_account.id is null or v_account.status <> 'ACTIVE'
     or v_checkout.id is null
     or v_checkout.status not in ('CREATED', 'PENDING')
     or v_attempt.id is null
     or v_attempt.tenant_id <> 'school-wise-wolf'
     or v_attempt.operation not in (
       'CUSTOMER_CREATE', 'SUBSCRIPTION_CREATE'
     )
     or exists (
       select 1
       from private.hub_provider_operations as operation
       where operation.account_id = p_account_id
         and operation.status in ('READY', 'IN_PROGRESS', 'BLOCKED')
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'account_lifecycle_fenced'
    );
  end if;

  if v_attempt.operation = 'CUSTOMER_CREATE' then
    if v_attempt.logical_key <> 'hub-account:' || p_account_id::text
       or v_attempt.external_reference <>
         'hub-account:' || p_account_id::text
       or (
         nullif(pg_catalog.btrim(v_account.asaas_customer_id), '') is not null
         and pg_catalog.btrim(v_account.asaas_customer_id) <> v_provider_id
       )
       or exists (
         select 1 from public.hub_accounts as other_account
         where other_account.id <> p_account_id
           and pg_catalog.btrim(other_account.asaas_customer_id) = v_provider_id
       ) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'reason', 'creation_scope_changed'
      );
    end if;
  elsif v_attempt.logical_key <> 'hub-checkout:' || p_checkout_id::text
     or v_attempt.external_reference <> 'hub:' || p_checkout_id::text
     or nullif(pg_catalog.btrim(v_account.asaas_customer_id), '') is null
     or (
       nullif(pg_catalog.btrim(v_checkout.asaas_subscription_id), '')
         is not null
       and pg_catalog.btrim(v_checkout.asaas_subscription_id) <> v_provider_id
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'creation_scope_changed'
    );
  end if;

  if v_attempt.status = 'SUCCEEDED' then
    if pg_catalog.btrim(v_attempt.provider_entity_id)
         is distinct from v_provider_id then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'reason', 'creation_scope_changed'
      );
    end if;
  else
    if p_claim_token is null
       or v_attempt.claim_token is distinct from p_claim_token
       or v_attempt.status not in ('CLAIMED', 'SUBMITTING', 'UNKNOWN') then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'reason', 'claim_lost'
      );
    end if;
    v_recorded := public.record_asaas_provider_creation_state(
      p_attempt_id,
      p_claim_token,
      'SUCCEEDED',
      v_provider_id,
      v_provider_status,
      null,
      null,
      pg_catalog.jsonb_build_object(
        'id', v_provider_id,
        'status', v_provider_status
      )
    );
    if coalesce((v_recorded ->> 'ok')::boolean, false) is not true then
      return coalesce(v_recorded, '{}'::jsonb) ||
        pg_catalog.jsonb_build_object('ok', false);
    end if;
  end if;

  if v_attempt.operation = 'CUSTOMER_CREATE' then
    update public.hub_accounts as account
    set asaas_customer_id = coalesce(account.asaas_customer_id, v_provider_id),
        updated_at = pg_catalog.clock_timestamp()
    where account.id = p_account_id
      and account.status = 'ACTIVE'
      and (
        account.asaas_customer_id is null
        or pg_catalog.btrim(account.asaas_customer_id) = v_provider_id
      );
    if not found then
      raise exception 'hub_provider_creation_adoption_lost'
        using errcode = '55000';
    end if;
  else
    update public.hub_checkout_sessions as checkout
    set asaas_subscription_id = coalesce(
          checkout.asaas_subscription_id, v_provider_id
        ),
        metadata = coalesce(checkout.metadata, '{}'::jsonb) ||
          pg_catalog.jsonb_build_object(
            'providerAdoptedAt', pg_catalog.clock_timestamp()
          ),
        updated_at = pg_catalog.clock_timestamp()
    where checkout.id = p_checkout_id
      and checkout.account_id = p_account_id
      and checkout.status in ('CREATED', 'PENDING')
      and (
        checkout.asaas_subscription_id is null
        or checkout.asaas_subscription_id = v_provider_id
      );
    if not found then
      raise exception 'hub_provider_creation_adoption_lost'
        using errcode = '55000';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'operation', v_attempt.operation,
    'providerEntityId', v_provider_id,
    'accountId', p_account_id,
    'checkoutId', p_checkout_id
  );
end;
$$;


--
-- Name: hub_adopt_wolfie_topup_provider_binding(uuid, uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_adopt_wolfie_topup_provider_binding(p_attempt_id uuid, p_claim_token uuid, p_account_id uuid, p_order_id uuid, p_provider_entity_id text, p_provider_status text, p_provider_customer_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_provider_id text := nullif(pg_catalog.btrim(p_provider_entity_id), '');
  v_provider_status text := nullif(pg_catalog.btrim(p_provider_status), '');
  v_customer_id text := nullif(pg_catalog.btrim(p_provider_customer_id), '');
  v_attempt public.asaas_provider_creation_attempts%rowtype;
  v_account public.hub_accounts%rowtype;
  v_order public.wolfie_topup_orders%rowtype;
  v_recorded jsonb;
begin
  perform private.hub_service_role_required();
  if p_attempt_id is null or p_account_id is null or p_order_id is null
     or v_provider_id is null or v_customer_id is null
     or pg_catalog.char_length(v_provider_id) > 200
     or pg_catalog.char_length(v_customer_id) > 200
  then
    raise exception 'invalid_hub_topup_provider_adoption'
      using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-provider-operation:' || p_account_id::text,
      0
    )
  );

  select account.* into v_account
    from public.hub_accounts as account
   where account.id = p_account_id
   for update;
  select orders.* into v_order
    from public.wolfie_topup_orders as orders
   where orders.id = p_order_id
   for update;
  select attempt.* into v_attempt
    from public.asaas_provider_creation_attempts as attempt
   where attempt.id = p_attempt_id
   for update;

  if v_account.id is null
     or v_account.status <> 'ACTIVE'
     or v_account.account_type <> 'PERSONAL'
     or v_order.id is null
     or v_order.tenant_id <> 'wolfie-direct'
     or v_order.student_id is distinct from v_account.owner_user_id
     or v_order.status not in ('PENDING', 'CREATING', 'AWAITING_PAYMENT')
     or nullif(pg_catalog.btrim(v_order.provider_customer_id), '')
       is distinct from v_customer_id
     or nullif(pg_catalog.btrim(v_account.asaas_customer_id), '')
       is distinct from v_customer_id
     or (
       v_order.provider_payment_id is not null
       and pg_catalog.btrim(v_order.provider_payment_id) <> v_provider_id
     )
     or not exists (
       select 1
         from public.hub_memberships as membership
        where membership.account_id = p_account_id
          and membership.user_id = v_order.student_id
          and membership.membership_role = 'OWNER'
          and membership.status = 'ACTIVE'
     )
     or v_attempt.id is null
     or v_attempt.tenant_id <> 'wolfie-direct'
     or v_attempt.operation <> 'PAYMENT_CREATE'
     or v_attempt.logical_key <> p_order_id::text
     or v_attempt.external_reference <>
       'wolfie-topup-order:' || p_order_id::text
     or exists (
       select 1
         from private.hub_provider_operations as operation
        where operation.account_id = p_account_id
          and operation.status in ('READY', 'IN_PROGRESS', 'BLOCKED')
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'reason', 'account_lifecycle_fenced'
    );
  end if;

  if v_attempt.status = 'SUCCEEDED' then
    if nullif(pg_catalog.btrim(v_attempt.provider_entity_id), '')
         is distinct from v_provider_id then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'reason', 'creation_scope_changed'
      );
    end if;
  else
    if p_claim_token is null
       or v_attempt.claim_token is distinct from p_claim_token
       or v_attempt.status not in ('CLAIMED', 'SUBMITTING', 'UNKNOWN')
    then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'reason', 'claim_lost'
      );
    end if;
    v_recorded := public.record_asaas_provider_creation_state(
      p_attempt_id,
      p_claim_token,
      'SUCCEEDED',
      v_provider_id,
      v_provider_status,
      null,
      null,
      pg_catalog.jsonb_build_object(
        'id', v_provider_id,
        'status', v_provider_status
      )
    );
    if coalesce((v_recorded ->> 'ok')::boolean, false) is not true then
      return coalesce(v_recorded, '{}'::jsonb) ||
        pg_catalog.jsonb_build_object('ok', false);
    end if;
  end if;

  update public.wolfie_topup_orders as orders
     set provider_payment_id = coalesce(
           orders.provider_payment_id,
           v_provider_id
         ),
         status = 'AWAITING_PAYMENT',
         reconciliation_required = false,
         creation_lease_expires_at = null,
         updated_at = pg_catalog.clock_timestamp()
   where orders.id = p_order_id
     and orders.tenant_id = 'wolfie-direct'
     and orders.student_id = v_account.owner_user_id
     and orders.provider_customer_id = v_customer_id
     and orders.status in ('PENDING', 'CREATING', 'AWAITING_PAYMENT')
     and (
       orders.provider_payment_id is null
       or orders.provider_payment_id = v_provider_id
     );
  if not found then
    raise exception 'hub_topup_provider_adoption_lost'
      using errcode = '55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'providerEntityId', v_provider_id,
    'accountId', p_account_id,
    'orderId', p_order_id
  );
end;
$$;


--
-- Name: hub_authorize_educator_planner_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_authorize_educator_planner_access(p_user_id uuid, p_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_account_id uuid;
  v_account_count integer;
  v_membership_role text;
  v_subject_role text;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if p_user_id is null then
    raise exception 'user_required' using errcode = '22023';
  end if;
  if not private.hub_is_enabled() then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'HUB_DISABLED'
    );
  end if;
  if not private.hub_profile_is_active(p_user_id) then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'PROFILE_INACTIVE'
    );
  end if;
  if exists (
    select 1
    from public.profiles as profile
    where profile.id = p_user_id
      and profile.tenant_id = 'wolfie-direct'
  ) then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'PRODUCT_SCOPE_FORBIDDEN'
    );
  end if;

  if p_account_id is null then
    select pg_catalog.count(*)::integer
      into v_account_count
    from public.hub_memberships as membership
    join public.hub_accounts as account
      on account.id = membership.account_id
     and account.status = 'ACTIVE'
    where membership.user_id = p_user_id
      and membership.status = 'ACTIVE';

    if v_account_count > 1 then
      return pg_catalog.jsonb_build_object(
        'allowed', false,
        'code', 'HUB_ACCOUNT_AMBIGUOUS'
      );
    end if;
  end if;

  select
    membership.account_id,
    membership.membership_role,
    membership.subject_role
  into v_account_id, v_membership_role, v_subject_role
  from public.hub_memberships as membership
  join public.hub_accounts as account
    on account.id = membership.account_id
   and account.status = 'ACTIVE'
  where membership.user_id = p_user_id
    and membership.status = 'ACTIVE'
    and (p_account_id is null or membership.account_id = p_account_id)
  order by membership.created_at, membership.id
  limit 1;

  if v_account_id is null then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'HUB_ACCOUNT_REQUIRED'
    );
  end if;
  if v_subject_role is distinct from 'EDUCATOR' then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'EDUCATOR_ROLE_REQUIRED',
      'accountId', v_account_id,
      'membershipRole', v_membership_role,
      'subjectRole', v_subject_role
    );
  end if;
  if not private.hub_user_has_educator_planner_access(
    v_account_id,
    p_user_id
  ) then
    return pg_catalog.jsonb_build_object(
      'allowed', false,
      'code', 'SUBSCRIPTION_REQUIRED'
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'allowed', true,
    'accountId', v_account_id,
    'membershipRole', v_membership_role,
    'subjectRole', v_subject_role
  );
end;
$$;


--
-- Name: hub_begin_core_cancellation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_begin_core_cancellation(p_account_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  select private.hub_begin_core_cancellation_internal(
    p_account_id,
    p_actor_user_id
  );
$$;


--
-- Name: FUNCTION hub_begin_core_cancellation(p_account_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hub_begin_core_cancellation(p_account_id uuid, p_actor_user_id uuid) IS 'Service-only synchronization barrier that blocks new Hub Core provider links while an authenticated manager cancels the existing Asaas recurrence.';


--
-- Name: hub_begin_provider_cancellation(text, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_begin_provider_cancellation(p_operation_kind text, p_account_id uuid, p_actor_user_id uuid, p_target_status text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_kind text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_operation_kind, '')));
  v_target_status text := nullif(pg_catalog.upper(pg_catalog.btrim(coalesce(p_target_status, ''))), '');
  v_reason text := pg_catalog.left(coalesce(nullif(pg_catalog.btrim(p_reason), ''), 'ADMIN_REQUEST'), 200);
  v_account public.hub_accounts%rowtype;
  v_account_row_version text;
  v_subscription public.hub_subscriptions%rowtype;
  v_logical_key text;
  v_operation private.hub_provider_operations%rowtype;
  v_provider_id text;
  v_checkout_id uuid;
  v_checkout_product_family text;
  v_count integer;
  v_snapshot jsonb;
begin
  perform private.hub_service_role_required();
  if p_account_id is null or v_kind not in ('ACCOUNT_STATUS', 'CORE_CANCELLATION') then
    raise exception 'invalid_hub_provider_operation' using errcode = '22023';
  end if;
  if v_kind = 'ACCOUNT_STATUS'
     and v_target_status not in ('SUSPENDED', 'CLOSED') then
    raise exception 'invalid_hub_provider_operation' using errcode = '22023';
  end if;
  if v_kind = 'CORE_CANCELLATION' and p_actor_user_id is null then
    raise exception 'invalid_hub_provider_operation' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('hub-provider-operation:' || p_account_id::text, 0)
  );
  select account.* into v_account
  from public.hub_accounts as account
  where account.id = p_account_id
  for update;
  if not found then
    raise exception 'hub_account_not_found' using errcode = 'P0002';
  end if;
  select account.xmin::text || ':' || account.cmin::text
    into v_account_row_version
  from public.hub_accounts as account
  where account.id = p_account_id;

  if v_kind = 'ACCOUNT_STATUS' then
    if p_actor_user_id is not null and not exists (
      select 1 from public.profiles as profile
      where profile.id = p_actor_user_id and profile.role = 'SUPER_ADMIN'
    ) then
      raise exception 'hub_status_actor_forbidden' using errcode = '42501';
    end if;
    -- A status target can recur after reactivation. Bind idempotency to the
    -- immutable source-state version, not eternally to account+target.
    v_logical_key := 'ACCOUNT_STATUS:' || p_account_id::text || ':' ||
      v_target_status || ':' || v_account.status || ':' ||
      pg_catalog.to_char(
        v_account.updated_at at time zone 'UTC',
        'YYYYMMDDHH24MISS.US'
      ) || ':' || v_account_row_version;
  else
    if v_account.status <> 'ACTIVE' then
      raise exception 'hub_account_inactive' using errcode = '42501';
    end if;
    if not exists (
      select 1 from public.hub_memberships as membership
      where membership.account_id = p_account_id
        and membership.user_id = p_actor_user_id
        and membership.status = 'ACTIVE'
        and membership.membership_role in ('OWNER', 'ADMIN')
    ) then
      raise exception 'hub_manager_required' using errcode = '42501';
    end if;
    select subscription.* into v_subscription
    from public.hub_subscriptions as subscription
    where subscription.account_id = p_account_id
      and subscription.product_family = 'HUB_CORE'
      and subscription.status = 'ACTIVE'
      and subscription.current_period_ends_at > pg_catalog.now()
    order by subscription.created_at desc, subscription.id desc
    limit 1 for update;
    if not found then
      raise exception 'hub_active_paid_subscription_required' using errcode = '55000';
    end if;
    if v_subscription.provider is distinct from 'ASAAS'
       or nullif(pg_catalog.btrim(v_subscription.provider_subscription_id), '') is null then
      raise exception 'hub_subscription_reconciliation_required' using errcode = '55000';
    end if;
    v_logical_key := 'CORE_CANCELLATION:' || p_account_id::text || ':' || v_subscription.id::text;
  end if;

  -- Resume one unfinished operation even if an unrelated account write moved
  -- updated_at after its immutable snapshot was captured.
  select operation.* into v_operation
  from private.hub_provider_operations as operation
  where operation.account_id = p_account_id
    and operation.operation_kind = v_kind
    and operation.status in ('READY', 'IN_PROGRESS')
  order by operation.created_at desc, operation.id desc
  limit 1
  for update;
  if found then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'action', 'RESUME', 'operationId', v_operation.id,
      'leaseToken', v_operation.lease_token, 'status', v_operation.status,
      'snapshot', v_operation.snapshot
    );
  end if;

  -- A provider POST that has crossed (or may have crossed) its durable submit
  -- boundary cannot be omitted from a cancellation snapshot. SUCCEEDED rows
  -- stop blocking only after their exact provider id is linked locally.
  if exists (
    select 1
    from public.asaas_provider_creation_attempts as attempt
    where (
        (
          attempt.tenant_id = 'school-wise-wolf'
          and attempt.operation = 'CUSTOMER_CREATE'
          and attempt.logical_key = 'hub-account:' || p_account_id::text
          and attempt.external_reference =
            'hub-account:' || p_account_id::text
          and (
            attempt.status in (
              'SUBMITTING', 'UNKNOWN', 'BLOCKED'
            )
            or (
              attempt.status = 'SUCCEEDED'
              and pg_catalog.btrim(attempt.provider_entity_id) is distinct from
                pg_catalog.btrim(v_account.asaas_customer_id)
            )
          )
        )
        or (
          attempt.tenant_id = 'school-wise-wolf'
          and attempt.operation = 'SUBSCRIPTION_CREATE'
          and exists (
            select 1
            from public.hub_checkout_sessions as creation_checkout
            where creation_checkout.account_id = p_account_id
              and (v_kind <> 'CORE_CANCELLATION'
                or creation_checkout.product_family = 'HUB_CORE')
              and attempt.logical_key =
                'hub-checkout:' || creation_checkout.id::text
              and attempt.external_reference =
                'hub:' || creation_checkout.id::text
              and (
                attempt.status in (
                  'SUBMITTING', 'UNKNOWN', 'BLOCKED'
                )
                or (
                  attempt.status = 'SUCCEEDED'
                  and pg_catalog.btrim(attempt.provider_entity_id)
                    is distinct from pg_catalog.btrim(
                      creation_checkout.asaas_subscription_id
                    )
                )
              )
          )
        )
        or (
          attempt.tenant_id = 'wolfie-direct'
          and attempt.operation = 'PAYMENT_CREATE'
          and v_account.account_type = 'PERSONAL'
          and exists (
            select 1
            from public.wolfie_topup_orders as topup
            where topup.tenant_id = 'wolfie-direct'
              and topup.student_id = v_account.owner_user_id
              and attempt.logical_key = topup.id::text
              and attempt.external_reference =
                'wolfie-topup-order:' || topup.id::text
              and (
                attempt.status in (
                  'SUBMITTING', 'UNKNOWN', 'BLOCKED'
                )
                or (
                  attempt.status = 'SUCCEEDED'
                  and pg_catalog.btrim(attempt.provider_entity_id)
                    is distinct from pg_catalog.btrim(
                      topup.provider_payment_id
                    )
                )
              )
          )
        )
      )
  ) then
    raise exception 'hub_provider_creation_reconciliation_required'
      using errcode = '55000';
  end if;

  -- A retry after successful finalization must remain idempotent. A later
  -- ACTIVE cycle has a different source status/version and therefore reaches
  -- the new logical key below.
  if v_kind = 'ACCOUNT_STATUS' and v_account.status = v_target_status then
    select operation.* into v_operation
    from private.hub_provider_operations as operation
    where operation.account_id = p_account_id
      and operation.operation_kind = 'ACCOUNT_STATUS'
      and operation.target_status = v_target_status
      and operation.status = 'SUCCEEDED'
    order by operation.completed_at desc nulls last, operation.id desc
    limit 1;
    if found then
      return pg_catalog.jsonb_build_object(
        'ok', true, 'action', 'ALREADY_SUCCEEDED',
        'operationId', v_operation.id, 'leaseToken', v_operation.lease_token,
        'status', v_operation.status, 'snapshot', v_operation.snapshot
      );
    end if;
  end if;

  select operation.* into v_operation
  from private.hub_provider_operations as operation
  where operation.logical_key = v_logical_key
  for update;
  if found then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', case when v_operation.status = 'SUCCEEDED'
        then 'ALREADY_SUCCEEDED' else 'RESUME' end,
      'operationId', v_operation.id,
      'leaseToken', v_operation.lease_token,
      'status', v_operation.status,
      'snapshot', v_operation.snapshot
    );
  end if;

  if nullif(pg_catalog.btrim(v_account.asaas_customer_id), '') is null then
    raise exception 'hub_customer_reconciliation_required' using errcode = '55000';
  end if;

  -- Freeze every local row that contributes to the immutable provider
  -- snapshot. The account row lock also fences concurrent FK-backed inserts
  -- until this begin transaction commits.
  perform subscription.id
  from public.hub_subscriptions as subscription
  join public.hub_plans as plan on plan.id = subscription.plan_id
  where subscription.account_id = p_account_id
    and (v_kind <> 'CORE_CANCELLATION'
      or subscription.product_family = 'HUB_CORE')
    and subscription.status in ('TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE')
    and not (subscription.provider is null
      and subscription.provider_subscription_id is null
      and plan.code = 'DISCOVERY')
  order by subscription.id
  for update of subscription;
  perform checkout.id
  from public.hub_checkout_sessions as checkout
  where checkout.account_id = p_account_id
    and (v_kind <> 'CORE_CANCELLATION'
      or checkout.product_family = 'HUB_CORE')
    and checkout.status in ('CREATED', 'PENDING', 'OVERDUE', 'PAID')
  order by checkout.id
  for update of checkout;

  -- Every active provider subscription must map to exactly one immutable
  -- checkout/customer tuple.  Include ids found on either active local
  -- subscriptions or open/paid checkouts so no scheduler escapes cancellation.
  for v_provider_id in
    select ids.provider_id
    from (
      select distinct pg_catalog.btrim(subscription.provider_subscription_id) as provider_id
      from public.hub_subscriptions as subscription
      join public.hub_plans as plan on plan.id = subscription.plan_id
      where subscription.account_id = p_account_id
        and (v_kind <> 'CORE_CANCELLATION'
          or subscription.product_family = 'HUB_CORE')
        and subscription.status in ('TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE')
        and not (subscription.provider is null
          and subscription.provider_subscription_id is null
          and plan.code = 'DISCOVERY')
      union
      select distinct pg_catalog.btrim(checkout.asaas_subscription_id)
      from public.hub_checkout_sessions as checkout
      where checkout.account_id = p_account_id
        and (v_kind <> 'CORE_CANCELLATION'
          or checkout.product_family = 'HUB_CORE')
        and checkout.status in ('CREATED', 'PENDING', 'OVERDUE', 'PAID')
        and nullif(pg_catalog.btrim(checkout.asaas_subscription_id), '') is not null
    ) as ids
    where nullif(ids.provider_id, '') is not null
    order by ids.provider_id
  loop
    if pg_catalog.char_length(v_provider_id) > 200 then
      raise exception 'hub_subscription_reconciliation_required' using errcode = '55000';
    end if;
    select pg_catalog.count(*)::integer,
           (pg_catalog.array_agg(checkout.id order by checkout.id))[1],
           pg_catalog.min(checkout.product_family)
      into v_count, v_checkout_id, v_checkout_product_family
    from public.hub_checkout_sessions as checkout
    where checkout.account_id = p_account_id
      and (v_kind <> 'CORE_CANCELLATION'
        or checkout.product_family = 'HUB_CORE')
      and checkout.asaas_subscription_id = v_provider_id;
    if v_count <> 1 or v_checkout_id is null then
      raise exception 'hub_subscription_reconciliation_required' using errcode = '55000';
    end if;
    if v_kind = 'CORE_CANCELLATION'
       and v_checkout_product_family <> 'HUB_CORE' then
      raise exception 'hub_subscription_reconciliation_required' using errcode = '55000';
    end if;
  end loop;

  -- A malformed active row without an id cannot be silently skipped.
  if exists (
    select 1 from public.hub_subscriptions as subscription
    join public.hub_plans as plan on plan.id = subscription.plan_id
    where subscription.account_id = p_account_id
      and (v_kind <> 'CORE_CANCELLATION'
        or subscription.product_family = 'HUB_CORE')
      and subscription.status in ('TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE')
      and not (subscription.provider is null
        and subscription.provider_subscription_id is null
        and plan.code = 'DISCOVERY')
      and (subscription.provider is distinct from 'ASAAS'
        or nullif(pg_catalog.btrim(subscription.provider_subscription_id), '') is null)
  ) or exists (
    select 1 from public.hub_checkout_sessions as checkout
    where checkout.account_id = p_account_id
      and (v_kind <> 'CORE_CANCELLATION'
        or checkout.product_family = 'HUB_CORE')
      and checkout.status in ('PENDING', 'OVERDUE', 'PAID')
      and nullif(pg_catalog.btrim(checkout.asaas_subscription_id), '') is null
  ) then
    raise exception 'hub_subscription_reconciliation_required' using errcode = '55000';
  end if;

  select pg_catalog.jsonb_build_object(
    'accountId', v_account.id,
    'accountStatus', v_account.status,
    'accountUpdatedAt', v_account.updated_at,
    'accountRowVersion', v_account_row_version,
    'providerCustomerId', pg_catalog.btrim(v_account.asaas_customer_id),
    'operationKind', v_kind,
    'targetStatus', v_target_status,
    'subscriptionId', v_subscription.id,
    'localSubscriptions', (
      select coalesce(pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'id', local_subscription.id,
          'productFamily', local_subscription.product_family,
          'status', local_subscription.status,
          'provider', local_subscription.provider,
          'providerSubscriptionId',
            local_subscription.provider_subscription_id
        ) order by local_subscription.id
      ), '[]'::jsonb)
      from public.hub_subscriptions as local_subscription
      join public.hub_plans as local_plan
        on local_plan.id = local_subscription.plan_id
      where local_subscription.account_id = p_account_id
        and (v_kind <> 'CORE_CANCELLATION'
          or local_subscription.product_family = 'HUB_CORE')
        and local_subscription.status in (
          'TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE'
        )
        and not (local_subscription.provider is null
          and local_subscription.provider_subscription_id is null
          and local_plan.code = 'DISCOVERY')
    ),
    'targets', coalesce(pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'providerSubscriptionId', checkout.asaas_subscription_id,
        'providerCustomerId', pg_catalog.btrim(v_account.asaas_customer_id),
        'checkoutId', checkout.id,
        'productFamily', checkout.product_family,
        'checkoutStatus', checkout.status
      ) order by checkout.asaas_subscription_id
    ) filter (where checkout.id is not null), '[]'::jsonb)
  ) into v_snapshot
  from public.hub_checkout_sessions as checkout
  where checkout.account_id = p_account_id
    and (v_kind <> 'CORE_CANCELLATION'
      or checkout.product_family = 'HUB_CORE')
    and checkout.asaas_subscription_id in (
      select distinct ids.provider_id from (
        select pg_catalog.btrim(subscription.provider_subscription_id) as provider_id
        from public.hub_subscriptions as subscription
        join public.hub_plans as plan on plan.id = subscription.plan_id
        where subscription.account_id = p_account_id
          and (v_kind <> 'CORE_CANCELLATION'
            or subscription.product_family = 'HUB_CORE')
          and subscription.status in ('TRIALING', 'INCOMPLETE', 'ACTIVE', 'PAST_DUE')
          and not (subscription.provider is null
            and subscription.provider_subscription_id is null
            and plan.code = 'DISCOVERY')
        union
        select pg_catalog.btrim(open_checkout.asaas_subscription_id)
        from public.hub_checkout_sessions as open_checkout
        where open_checkout.account_id = p_account_id
          and (v_kind <> 'CORE_CANCELLATION'
            or open_checkout.product_family = 'HUB_CORE')
          and open_checkout.status in ('CREATED', 'PENDING', 'OVERDUE', 'PAID')
          and nullif(pg_catalog.btrim(open_checkout.asaas_subscription_id), '') is not null
      ) as ids
    );

  insert into private.hub_provider_operations (
    logical_key, operation_kind, account_id, actor_user_id, target_status,
    reason, snapshot, snapshot_hash
  ) values (
    v_logical_key, v_kind, p_account_id, p_actor_user_id, v_target_status,
    v_reason, v_snapshot,
    pg_catalog.encode(
      extensions.digest(pg_catalog.convert_to(v_snapshot::text, 'UTF8'), 'sha256'),
      'hex'
    )
  ) returning * into v_operation;

  insert into private.hub_provider_operation_targets (
    operation_id, provider_subscription_id, provider_customer_id, checkout_id
  )
  select v_operation.id, item ->> 'providerSubscriptionId',
    item ->> 'providerCustomerId', (item ->> 'checkoutId')::uuid
  from pg_catalog.jsonb_array_elements(v_snapshot -> 'targets') as item;

  if v_kind = 'CORE_CANCELLATION' then
    perform private.hub_begin_core_cancellation_internal(p_account_id, p_actor_user_id);
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true, 'action', 'STARTED', 'operationId', v_operation.id,
    'leaseToken', v_operation.lease_token, 'status', v_operation.status,
    'snapshot', v_operation.snapshot
  );
end;
$$;


--
-- Name: hub_bind_checkout_provider_subscription(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_bind_checkout_provider_subscription(p_checkout_id uuid, p_subscription_id text, p_metadata_patch jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_checkout public.hub_checkout_sessions%rowtype;
  v_subscription_id text := nullif(pg_catalog.btrim(p_subscription_id), '');
  v_account_id uuid;
begin
  perform private.hub_service_role_required();
  if p_checkout_id is null or v_subscription_id is null
     or pg_catalog.char_length(v_subscription_id) > 200
     or p_metadata_patch is null
     or pg_catalog.jsonb_typeof(p_metadata_patch) <> 'object'
     or pg_catalog.pg_column_size(p_metadata_patch) > 8192 then
    raise exception 'invalid_hub_checkout_subscription_binding'
      using errcode = '22023';
  end if;
  select checkout.account_id into v_account_id
  from public.hub_checkout_sessions checkout
  where checkout.id = p_checkout_id;
  if not found then
    raise exception 'hub_checkout_not_found' using errcode = 'P0002';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'hub-provider-operation:' || v_account_id::text,
      0
    )
  );
  select checkout.* into v_checkout
  from public.hub_checkout_sessions checkout
  where checkout.id = p_checkout_id
  for update;
  if not found then
    raise exception 'hub_checkout_not_found' using errcode = 'P0002';
  end if;
  if v_checkout.status not in ('CREATED', 'PENDING')
     or (v_checkout.asaas_subscription_id is not null
       and v_checkout.asaas_subscription_id is distinct from v_subscription_id)
     or not exists (
       select 1 from public.hub_accounts account
       where account.id = v_checkout.account_id
         and account.status = 'ACTIVE'
     )
     or exists (
       select 1 from private.hub_provider_operations operation
       where operation.account_id = v_checkout.account_id
         and operation.status in ('READY', 'IN_PROGRESS', 'BLOCKED')
     ) then
    raise exception 'hub_checkout_subscription_mismatch' using errcode = '42501';
  end if;
  update public.hub_checkout_sessions checkout
  set asaas_subscription_id = coalesce(
        checkout.asaas_subscription_id, v_subscription_id
      ),
      metadata = coalesce(checkout.metadata, '{}'::jsonb) || p_metadata_patch,
      updated_at = pg_catalog.clock_timestamp()
  where checkout.id = p_checkout_id
  returning checkout.* into v_checkout;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'checkoutId', v_checkout.id,
    'subscriptionId', v_checkout.asaas_subscription_id
  );
end;
$$;


--
-- Name: hub_bind_provider_operation_integration(uuid, uuid, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_bind_provider_operation_integration(p_operation_id uuid, p_lease_token uuid, p_integration_id uuid, p_integration_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_operation private.hub_provider_operations%rowtype;
begin
  perform private.hub_service_role_required();
  if p_operation_id is null or p_lease_token is null or p_integration_id is null
     or p_integration_version is null or p_integration_version < 1 then
    raise exception 'invalid_hub_provider_integration_binding' using errcode = '22023';
  end if;
  select operation.* into v_operation from private.hub_provider_operations operation
  where operation.id = p_operation_id for update;
  if not found or v_operation.lease_token is distinct from p_lease_token then
    raise exception 'hub_provider_operation_claim_lost' using errcode = '55000';
  end if;
  if (v_operation.integration_id is not null and
      (v_operation.integration_id is distinct from p_integration_id or
       v_operation.integration_version is distinct from p_integration_version)) then
    raise exception 'hub_provider_integration_version_changed' using errcode = '55000';
  end if;
  update private.hub_provider_operations operation
  set integration_id = coalesce(operation.integration_id, p_integration_id),
      integration_version = coalesce(operation.integration_version, p_integration_version),
      updated_at = pg_catalog.clock_timestamp()
  where operation.id = p_operation_id;
  return pg_catalog.jsonb_build_object('ok', true);
end;
$$;


--
-- Name: hub_bootstrap(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_bootstrap(p_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with bootstrap as materialized (
    select private.hub_bootstrap_internal(p_account_id) as payload
  )
  select case
    when bootstrap.payload is null then null
    when pg_catalog.jsonb_typeof(bootstrap.payload) = 'object'
      and pg_catalog.jsonb_typeof(bootstrap.payload -> 'account') = 'object'
      then pg_catalog.jsonb_set(
        bootstrap.payload,
        '{account,metadata}'::text[],
        '{}'::jsonb,
        true
      )
    else bootstrap.payload
  end
  from bootstrap;
$$;


--
-- Name: FUNCTION hub_bootstrap(p_account_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hub_bootstrap(p_account_id uuid) IS 'Returns the legacy Hub bootstrap contract with shared account personalization metadata removed.';


