--
-- Name: hub_finalize_provider_cancellation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_finalize_provider_cancellation(p_operation_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation private.hub_provider_operations%rowtype;
  v_provider_ids text[];
  v_result jsonb;
begin
  v_operation := private.hub_assert_provider_operation_complete(p_operation_id, p_lease_token);
  if v_operation.status = 'SUCCEEDED' then
    return pg_catalog.jsonb_build_object('ok', true, 'idempotent', true,
      'operationId', v_operation.id);
  end if;
  select coalesce(pg_catalog.array_agg(target.provider_subscription_id order by target.provider_subscription_id), '{}'::text[])
    into v_provider_ids
  from private.hub_provider_operation_targets target
  where target.operation_id = v_operation.id;
  if v_operation.operation_kind = 'ACCOUNT_STATUS' then
    v_result := private.hub_finalize_account_status_internal(
      v_operation.account_id, v_operation.target_status, v_provider_ids,
      v_operation.actor_user_id, v_operation.reason
    );
  elsif v_operation.operation_kind = 'CORE_CANCELLATION' then
    v_result := private.hub_schedule_core_cancellation_internal(
      v_operation.account_id, v_operation.actor_user_id, v_provider_ids
    );
  else
    raise exception 'invalid_hub_provider_operation' using errcode = '55000';
  end if;
  update private.hub_provider_operations operation
  set status = 'SUCCEEDED', completed_at = coalesce(operation.completed_at, pg_catalog.clock_timestamp()),
      updated_at = pg_catalog.clock_timestamp()
  where operation.id = v_operation.id and operation.status <> 'SUCCEEDED';
  return coalesce(v_result, '{}'::jsonb) || pg_catalog.jsonb_build_object(
    'ok', true, 'operationId', v_operation.id
  );
end;
$$;


--
-- Name: hub_finalize_webhook_provider_cancellation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_finalize_webhook_provider_cancellation(p_operation_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_operation private.hub_provider_operations%rowtype;
begin
  v_operation := private.hub_assert_provider_operation_complete(
    p_operation_id, p_lease_token
  );
  if v_operation.operation_kind <> 'WEBHOOK_CANCELLATION' then
    raise exception 'invalid_hub_provider_operation' using errcode = '55000';
  end if;
  update private.hub_provider_operations operation
  set status = 'SUCCEEDED', completed_at = coalesce(
        operation.completed_at, pg_catalog.clock_timestamp()
      ), updated_at = pg_catalog.clock_timestamp()
  where operation.id = v_operation.id and operation.status <> 'SUCCEEDED';
  return pg_catalog.jsonb_build_object(
    'ok', true, 'operationId', v_operation.id,
    'idempotent', v_operation.status = 'SUCCEEDED'
  );
end;
$$;


--
-- Name: hub_get_member_profile(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_get_member_profile(p_account_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_result jsonb;
begin
  if v_user_id is null then
    raise exception 'authentication_required' using errcode = 'P0001';
  end if;
  if p_account_id is null then
    raise exception 'invalid_account_id' using errcode = '22023';
  end if;
  if not private.hub_has_account_access(p_account_id) then
    raise exception 'hub_account_access_denied' using errcode = '42501';
  end if;

  select pg_catalog.jsonb_build_object(
    'accountId', member_profile.account_id,
    'displayName', member_profile.display_name,
    'subjectRole', membership.subject_role,
    'onboarding_completed', member_profile.onboarding_completed,
    'level', member_profile.level,
    'role', member_profile.role,
    'goal', member_profile.goal,
    'interests', member_profile.interests,
    'preferred_modality', member_profile.preferred_modality,
    'personalized_at', member_profile.personalized_at
  )
  into v_result
  from public.hub_member_profiles as member_profile
  join public.hub_memberships as membership
    on membership.account_id = member_profile.account_id
   and membership.user_id = member_profile.user_id
   and membership.status = 'ACTIVE'
  where member_profile.account_id = p_account_id
    and member_profile.user_id = v_user_id;

  if v_result is null then
    raise exception 'hub_member_profile_missing' using errcode = 'P0001';
  end if;

  return v_result;
end;
$$;


--
-- Name: FUNCTION hub_get_member_profile(p_account_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hub_get_member_profile(p_account_id uuid) IS 'Returns only the authenticated member own isolated Hub profile.';


