--
-- Name: hub_rename_account(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_rename_account(p_account_id uuid, p_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_name text := pg_catalog.btrim(
    pg_catalog.regexp_replace(
      coalesce(p_name, ''),
      '[[:space:]]+',
      ' ',
      'g'
    )
  );
  v_updated_at timestamptz := pg_catalog.clock_timestamp();
begin
  if v_user_id is null then
    raise exception 'authentication_required' using errcode = 'P0001';
  end if;
  if p_account_id is null then
    raise exception 'invalid_account_id' using errcode = '22023';
  end if;
  if pg_catalog.char_length(v_name) < 1
     or pg_catalog.char_length(v_name) > 120 then
    raise exception 'invalid_account_name' using errcode = '22023';
  end if;
  if not private.hub_is_account_manager(p_account_id) then
    raise exception 'hub_manager_required' using errcode = '42501';
  end if;

  update public.hub_accounts as account
  set name = v_name,
      updated_at = v_updated_at
  where account.id = p_account_id
    and account.status = 'ACTIVE'
  returning account.updated_at into v_updated_at;

  if not found then
    raise exception 'hub_account_inactive_or_missing' using errcode = 'P0001';
  end if;

  return pg_catalog.jsonb_build_object(
    'accountId', p_account_id,
    'name', v_name,
    'updatedAt', v_updated_at
  );
end;
$$;


--
-- Name: FUNCTION hub_rename_account(p_account_id uuid, p_name text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hub_rename_account(p_account_id uuid, p_name text) IS 'Renames an active Hub account through a validated manager-only mutation.';


