--
-- Name: hub_upsert_collection(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_upsert_collection(p_id uuid, p_title text, p_niche text DEFAULT 'GENERAL'::text, p_level text DEFAULT NULL::text, p_cover text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id uuid;
  v_title text;
begin
  if not private.hub_is_internal_manager() then
    raise exception 'sem_permissao';
  end if;

  -- `nullif` é forma especial do SQL: prefixar com pg_catalog quebra em runtime
  -- dentro de `set search_path = ''`. Mesma pedra da migration do Wolfie.
  v_title := nullif(btrim(coalesce(p_title, '')), '');
  if v_title is null then
    raise exception 'titulo_obrigatorio';
  end if;

  if p_id is null then
    insert into public.hub_collections (title, niche, level_tag, cover_url)
    values (v_title, coalesce(nullif(btrim(p_niche), ''), 'GENERAL'), p_level, p_cover)
    returning id into v_id;
  else
    update public.hub_collections
       set title = v_title,
           niche = coalesce(nullif(btrim(p_niche), ''), 'GENERAL'),
           level_tag = p_level,
           cover_url = p_cover,
           updated_at = now()
     where id = p_id
    returning id into v_id;

    if v_id is null then
      raise exception 'colecao_inexistente';
    end if;
  end if;

  return v_id;
end;
$$;


--
-- Name: hub_validate_material_publication_sources(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hub_validate_material_publication_sources(p_material_id uuid, p_full_source_path text, p_preview_source_path text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.pedagogical_materials as material
    where material.id = p_material_id
      and material.tenant_id is not null
      and material.approval_status = 'APPROVED'
      and upper(coalesce(material.type, '')) <> 'LINK'
      and material.hub_catalog_opt_in is true
      and material.hub_commercial_approved is true
      and material.hub_publication_requested_by is not null
      and material.hub_publication_requested_at is not null
      and material.hub_rights_verified_by is not null
      and material.hub_rights_verified_at is not null
      and material.hub_rights_verified_by
        <> material.hub_publication_requested_by
      and material.hub_rights_basis in (
        'OWNED', 'LICENSED', 'PUBLIC_DOMAIN'
      )
      and char_length(btrim(coalesce(
        material.hub_rights_declaration,
        ''
      ))) between 20 and 2000
      and material.storage_object_path = p_full_source_path
      and material.hub_preview_source_path = p_preview_source_path
      and p_full_source_path <> p_preview_source_path
      and private.hub_material_object_has_provenance(
        p_full_source_path,
        material.tenant_id,
        material.uploaded_by
      )
      and private.hub_material_object_has_provenance(
        p_preview_source_path,
        material.tenant_id,
        null
      )
  );
$$;


--
-- Name: is_billable_student(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_billable_student(p_student uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_student IS NULL THEN true
    WHEN EXISTS (SELECT 1 FROM non_billable_profiles nb WHERE nb.profile_id = p_student) THEN false
    WHEN EXISTS (
      SELECT 1 FROM profiles p
      WHERE p.id = p_student
        AND p.full_name ~* '^\s*(teste\s*oral|treinamento|treino|aula\s*experimental)\y'
    ) THEN false
    ELSE true
  END;
$$;


--
-- Name: is_school_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_school_admin() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN (auth.jwt() ->> 'email' LIKE '%admin%') OR 
           EXISTS (
               SELECT 1 FROM profiles 
               WHERE id = auth.uid() 
               AND role IN ('SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR')
           );
END;
$$;


--
-- Name: is_student_notifiable(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_student_notifiable(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select
      profile.role = 'STUDENT'
      and pg_catalog.lower(pg_catalog.btrim(coalesce(
            profile.lifecycle_status,
            ''
          ))) = 'active'
      and pg_catalog.lower(pg_catalog.btrim(coalesce(
            profile.status,
            'Ativo'
          ))) not in (
            'inativo', 'inactive', 'arquivado', 'cancelado', 'trancado'
          )
      and pg_catalog.upper(pg_catalog.btrim(coalesce(
            profile.status_financial,
            'ACTIVE'
          ))) <> 'ARCHIVED'
    from public.profiles as profile
    where profile.id = p_id
      and (
        coalesce(auth.jwt() ->> 'role', '') = 'service_role'
        or auth.uid() = profile.id
        or (
          auth.uid() is null
          and session_user in ('postgres', 'supabase_admin')
        )
        or exists (
          select 1
            from public.profiles as actor
           where actor.id = auth.uid()
             and pg_catalog.upper(pg_catalog.btrim(coalesce(
                   actor.role,
                   ''
                 ))) = 'SUPER_ADMIN'
             and pg_catalog.lower(pg_catalog.btrim(coalesce(
                   actor.lifecycle_status,
                   ''
                 ))) = 'active'
        )
        or exists (
          select 1
            from public.profiles as actor
            join public.tenant_memberships as membership
              on membership.user_id = actor.id
             and membership.tenant_id = profile.tenant_id
             and membership.status = 'ACTIVE'
             and membership.role in (
               'SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'COORDINATOR',
               'TEACHER'
             )
           where actor.id = auth.uid()
             and actor.tenant_id = profile.tenant_id
             and pg_catalog.upper(pg_catalog.btrim(coalesce(
                   actor.role,
                   ''
                 ))) in (
                   'SUPER_ADMIN', 'SCHOOL_ADMIN', 'ADMIN', 'COORDINATOR',
                   'TEACHER'
                 )
             and pg_catalog.lower(pg_catalog.btrim(coalesce(
                   actor.lifecycle_status,
                   ''
                 ))) = 'active'
        )
      )
  ), false);
$$;


--
-- Name: is_super_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_super_admin() RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (SELECT 1 FROM profiles WHERE id = auth.uid() AND role = 'SUPER_ADMIN');
$$;


--
-- Name: is_teacher_notifiable(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_teacher_notifiable(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  -- Professor só recebe automação de mensagem se estiver ATIVO de verdade.
  -- lifecycle_status é a fonte de verdade (status é decorativo).
  SELECT COALESCE((
    SELECT p.role = 'TEACHER'
       AND COALESCE(p.lifecycle_status, 'active') = 'active'
       AND COALESCE(p.status, 'Ativo') NOT IN ('Inativo','INACTIVE','Inactive','Arquivado','Cancelado','Trancado')
    FROM profiles p WHERE p.id = p_id
  ), false);
$$;


--
-- Name: is_valid_cpf(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_valid_cpf(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  v_cpf text := regexp_replace(coalesce(p_value, ''), '[^0-9]', '', 'g');
  v_sum integer;
  v_digit integer;
  i integer;
begin
  if length(v_cpf) <> 11 or v_cpf ~ '^([0-9])\1{10}$' then
    return false;
  end if;

  v_sum := 0;
  for i in 1..9 loop
    v_sum := v_sum + substr(v_cpf, i, 1)::integer * (11 - i);
  end loop;
  v_digit := (v_sum * 10) % 11;
  if v_digit = 10 then v_digit := 0; end if;
  if v_digit <> substr(v_cpf, 10, 1)::integer then return false; end if;

  v_sum := 0;
  for i in 1..10 loop
    v_sum := v_sum + substr(v_cpf, i, 1)::integer * (12 - i);
  end loop;
  v_digit := (v_sum * 10) % 11;
  if v_digit = 10 then v_digit := 0; end if;
  return v_digit = substr(v_cpf, 11, 1)::integer;
end;
$_$;


--
-- Name: ledger_on_payment_received(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ledger_on_payment_received() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_receipt_should_exist boolean;
  v_receipt_existed boolean;
  v_cash_before boolean;
  v_relevant_change boolean;
  v_category text;
  v_refund_category text;
  v_gross_amount numeric;
  v_refund_delta numeric := 0;
  v_refund_event_fresh boolean := false;
  v_occurred_at timestamptz;
  v_existing_occurred_at timestamptz;
  v_removed_amount numeric;
  v_removed_count integer := 0;
  v_refund_inserted integer := 0;
  v_has_ledger boolean;
  v_existing_refund record;
  v_paid_teacher_closings jsonb;
  v_payment_competence text;
begin
  select exists (
           select 1
             from public.financial_transactions ft
            where ft.student_payment_id = new.id
         ),
         (
           select ft.occurred_at
             from public.financial_transactions ft
            where ft.student_payment_id = new.id
         )
    into v_receipt_existed, v_existing_occurred_at;

  v_cash_before := tg_op = 'UPDATE'
                   and (
                     old.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'NAO_RECEITA')
                     or v_receipt_existed
                   );
  v_receipt_should_exist :=
    new.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'NAO_RECEITA')
    or (
      new.status = 'REFUNDED'
      and (new.credited_at is not null or v_receipt_existed)
    );

  if tg_op = 'UPDATE'
     and coalesce(new.refunded_amount, 0) < coalesce(old.refunded_amount, 0) then
    raise exception using
      errcode = '23514',
      message = 'student_payment_refunded_amount_regression';
  end if;

  v_relevant_change := tg_op = 'INSERT'
    or old.status is distinct from new.status
    or old.tenant_id is distinct from new.tenant_id
    or old.student_id is distinct from new.student_id
    or old.value is distinct from new.value
    or old.refunded_amount is distinct from new.refunded_amount
    or old.credited_at is distinct from new.credited_at
    or old.last_provider_event_id is distinct from new.last_provider_event_id
    or old.last_provider_event_at is distinct from new.last_provider_event_at
    or old.paid_at is distinct from new.paid_at
    or old.payment_date is distinct from new.payment_date
    or old.due_date is distinct from new.due_date;

  -- Atualizacao recursiva feita abaixo apenas para espelhar a flag. Se nenhum
  -- campo contabil mudou, limita-se a restaurar a flag derivada.
  if not v_relevant_change then
    select exists (
      select 1
        from public.financial_transactions ft
       where ft.student_payment_id = new.id
    ) into v_has_ledger;

    if new.ledger_entry_created is distinct from v_has_ledger then
      update public.student_payments sp
         set ledger_entry_created = v_has_ledger
       where sp.id = new.id
         and sp.ledger_entry_created is distinct from v_has_ledger;
    end if;
    return new;
  end if;

  v_category := case
    when new.status = 'NAO_RECEITA' then 'aporte_ou_movimentacao'
    else 'MENSALIDADE'
  end;
  v_refund_category := case
    when new.status = 'NAO_RECEITA' then 'estorno_aporte_ou_movimentacao'
    else 'ESTORNO_MENSALIDADE'
  end;
  v_gross_amount := round(coalesce(new.value, 0), 2);
  v_occurred_at := coalesce(
    new.credited_at,
    new.paid_at,
    new.payment_date + interval '12 hours',
    new.due_date + interval '12 hours',
    v_existing_occurred_at,
    now()
  );

  -- O recebimento e imutavelmente bruto. Um estorno nunca reduz nem apaga esta
  -- linha: sua contrapartida vive em uma SAIDA datada pelo evento do provedor.
  if v_receipt_should_exist
     and new.tenant_id is not null
     and v_gross_amount > 0 then
    insert into public.financial_transactions (
      tenant_id,
      type,
      category,
      amount,
      amount_cents,
      student_payment_id,
      reference_id,
      occurred_at,
      description,
      created_at
    ) values (
      new.tenant_id,
      'ENTRADA',
      v_category,
      v_gross_amount,
      round(v_gross_amount * 100)::integer,
      new.id,
      new.student_id,
      v_occurred_at,
      case
        when new.status = 'NAO_RECEITA' then 'Movimentacao nao operacional (conciliacao automatica)'
        else 'Mensalidade (conciliacao automatica)'
      end,
      now()
    )
    on conflict (student_payment_id) where student_payment_id is not null
    do update set
      tenant_id = excluded.tenant_id,
      type = excluded.type,
      category = excluded.category,
      amount = excluded.amount,
      amount_cents = excluded.amount_cents,
      reference_id = excluded.reference_id,
      occurred_at = excluded.occurred_at,
      description = excluded.description;
  elsif new.status = 'REFUNDED' and v_receipt_existed then
    -- Nao destrua a entrada historica se a atualizacao de identidade/valor
    -- estiver incompleta. A divergencia fica explicita para conciliacao.
    insert into public.reconciliation_issues (
      tenant_id, kind, student_payment_id, details
    ) values (
      coalesce(new.tenant_id, 'master'),
      'REFUNDED_PAYMENT_RECEIPT_DATA_INVALID',
      new.id,
      jsonb_build_object(
        'status_novo', new.status,
        'tenant_id', new.tenant_id,
        'valor_bruto', new.value,
        'entrada_preservada', true,
        'registrado_em', now()
      )
    );
  else
    select ft.amount
      into v_removed_amount
      from public.financial_transactions ft
     where ft.student_payment_id = new.id
     for update;

    delete from public.financial_transactions ft
     where ft.student_payment_id = new.id;
    get diagnostics v_removed_count = row_count;

    if v_removed_count > 0 and v_cash_before then
      insert into public.reconciliation_issues (
        tenant_id,
        kind,
        student_payment_id,
        details
      ) values (
        coalesce(new.tenant_id, old.tenant_id, 'master'),
        case when new.tenant_id is null
          then 'PAYMENT_WITHOUT_TENANT'
          else 'PAYMENT_REVERSED'
        end,
        new.id,
        jsonb_build_object(
          'status_anterior', case when tg_op = 'UPDATE' then old.status else null end,
          'status_novo', new.status,
          'valor_bruto', new.value,
          'valor_estornado', new.refunded_amount,
          'valor_removido_do_caixa', v_removed_amount,
          'removido_em', now()
        )
      );
    end if;
  end if;

  -- Mudanca deliberada RECEIVED <-> NAO_RECEITA recategoriza tambem eventuais
  -- estornos, sem tocar em valor, ID ou data historica do evento.
  if new.tenant_id is not null then
    update public.financial_transactions ft
       set tenant_id = new.tenant_id,
           category = v_refund_category,
           reference_id = new.student_id,
           description = case
             when new.status = 'NAO_RECEITA'
               then 'Estorno de movimentacao nao operacional (evento Asaas)'
             else 'Estorno de mensalidade (evento Asaas)'
           end
     where ft.refund_student_payment_id = new.id
       and (
         ft.tenant_id is distinct from new.tenant_id
         or ft.category is distinct from v_refund_category
         or ft.reference_id is distinct from new.student_id
       );
  end if;

  -- Gate obrigatorio: um estorno so e SAIDA se houve ENTRADA comprovada.
  select exists (
    select 1
      from public.financial_transactions ft
     where ft.student_payment_id = new.id
  ) into v_has_ledger;

  if tg_op = 'INSERT' then
    v_refund_delta := round(coalesce(new.refunded_amount, 0), 2);
    v_refund_event_fresh := new.last_provider_event_id is not null
      and length(trim(new.last_provider_event_id)) between 1 and 240
      and new.last_provider_event_at is not null;
  else
    v_refund_delta := round(
      coalesce(new.refunded_amount, 0) - coalesce(old.refunded_amount, 0),
      2
    );
    v_refund_event_fresh := new.last_provider_event_id is not null
      and length(trim(new.last_provider_event_id)) between 1 and 240
      and new.last_provider_event_at is not null
      and (
        new.last_provider_event_id is distinct from old.last_provider_event_id
        or new.last_provider_event_at is distinct from old.last_provider_event_at
      );
  end if;

  if v_refund_delta > 0 and not v_has_ledger then
    -- Estorno anterior ao credito (por exemplo CONFIRMED -> REFUNDED) nao e
    -- saida de caixa: nenhum saldo havia sido disponibilizado. A issue abaixo
    -- guarda a explicacao, mas nenhuma movimentacao e sintetizada.
    null;
  elsif v_refund_delta > 0
        and v_refund_event_fresh
        and new.tenant_id is not null then
    insert into public.financial_transactions (
      tenant_id,
      type,
      category,
      amount,
      amount_cents,
      refund_student_payment_id,
      provider_event_id,
      reference_id,
      occurred_at,
      description,
      created_at
    ) values (
      new.tenant_id,
      'SAIDA',
      v_refund_category,
      v_refund_delta,
      round(v_refund_delta * 100)::integer,
      new.id,
      trim(new.last_provider_event_id),
      new.student_id,
      new.last_provider_event_at,
      case
        when new.status = 'NAO_RECEITA' then 'Estorno de movimentacao nao operacional (evento Asaas)'
        else 'Estorno de mensalidade (evento Asaas)'
      end,
      now()
    )
    on conflict (provider_event_id)
      where refund_student_payment_id is not null
        and provider_event_id is not null
    do nothing;
    get diagnostics v_refund_inserted = row_count;

    -- ON CONFLICT garante retry idempotente. Esta verificacao impede que um ID
    -- do provedor reutilizado ou um retry divergente seja aceito em silencio.
    select
      ft.refund_student_payment_id,
      ft.tenant_id,
      ft.type,
      ft.category,
      ft.amount,
      ft.occurred_at
      into v_existing_refund
      from public.financial_transactions ft
     where ft.refund_student_payment_id is not null
       and ft.provider_event_id = trim(new.last_provider_event_id);

    if not found
       or v_existing_refund.refund_student_payment_id is distinct from new.id
       or v_existing_refund.tenant_id is distinct from new.tenant_id
       or v_existing_refund.type is distinct from 'SAIDA'
       or v_existing_refund.category is distinct from v_refund_category
       or v_existing_refund.amount is distinct from v_refund_delta
       or v_existing_refund.occurred_at is distinct from new.last_provider_event_at then
      raise exception using
        errcode = '23505',
        message = 'refund_provider_event_conflict';
    end if;
  elsif v_refund_delta > 0 then
    insert into public.reconciliation_issues (
      tenant_id,
      kind,
      student_payment_id,
      details
    ) values (
      coalesce(new.tenant_id, 'master'),
      'REFUND_LEDGER_EVENT_CONTEXT_MISSING',
      new.id,
      jsonb_build_object(
        'valor_bruto', new.value,
        'valor_estornado_anterior', case
          when tg_op = 'UPDATE' then old.refunded_amount
          else 0
        end,
        'valor_estornado_novo', new.refunded_amount,
        'delta_sem_lancamento', v_refund_delta,
        'provider_event_id', new.last_provider_event_id,
        'provider_event_at', new.last_provider_event_at,
        'contexto_evento_novo', v_refund_event_fresh,
        'tenant_id_ausente', new.tenant_id is null,
        'data_sintetizada', false,
        'registrado_em', now()
      )
    );
  end if;

  if v_refund_delta > 0
     and not exists (
       select 1
         from public.financial_transactions ft
        where ft.student_payment_id = new.id
     ) then
    insert into public.reconciliation_issues (
      tenant_id, kind, student_payment_id, details
    ) values (
      coalesce(new.tenant_id, 'master'),
      'REFUND_WITHOUT_RECEIPT_LEDGER',
      new.id,
      jsonb_build_object(
        'valor_bruto', new.value,
        'delta_estornado', v_refund_delta,
        'provider_event_id', new.last_provider_event_id,
        'provider_event_at', new.last_provider_event_at,
        'entrada_sintetizada', false,
        'motivo', 'Nao ha data de credito comprovada para reconstruir a ENTRADA historica.',
        'registrado_em', now()
      )
    );
  end if;

  if v_refund_delta > 0 then
    insert into public.reconciliation_issues (
      tenant_id,
      kind,
      student_payment_id,
      details
    ) values (
      coalesce(new.tenant_id, 'master'),
      case
        when coalesce(new.refunded_amount, 0) < coalesce(new.value, 0)
          then 'PAYMENT_PARTIALLY_REFUNDED'
        else 'PAYMENT_FULLY_REFUNDED'
      end,
      new.id,
      jsonb_build_object(
        'valor_bruto', new.value,
        'valor_estornado_anterior', case
          when tg_op = 'UPDATE' then old.refunded_amount
          else 0
        end,
        'valor_estornado_novo', new.refunded_amount,
        'delta_estornado', v_refund_delta,
        'provider_event_id', new.last_provider_event_id,
        'provider_event_at', new.last_provider_event_at,
        'saida_criada', v_refund_inserted = 1,
        'registrado_em', now()
      )
    );
  end if;

  -- Um estorno posterior ao repasse do professor exige decisao humana. A
  -- mensalidade e o fechamento nao possuem regra de rateio reverso suficiente
  -- para debitar o professor com seguranca; por isso o trigger apenas abre uma
  -- issue com os fechamentos possivelmente afetados e nunca altera o repasse.
  if v_refund_delta > 0
     and new.student_id is not null then
    v_payment_competence := to_char(
      coalesce(new.due_date, new.payment_date, new.credited_at::date),
      'YYYY-MM'
    );

    select jsonb_agg(candidate.id order by candidate.id)
      into v_paid_teacher_closings
      from (
        select distinct tc.id
          from public.teacher_closings tc
         where tc.tenant_id = new.tenant_id
           and tc.month_year = v_payment_competence
           and upper(coalesce(tc.status, '')) in ('PAGO', 'PAID', 'COMPLETED')
           and exists (
             select 1
               from public.v_payable_class_logs pcl
              where pcl.teacher_id = tc.teacher_id
                and pcl.student_id = new.student_id
                and to_char(pcl.class_date, 'YYYY-MM') = v_payment_competence
           )
      ) candidate;

    if v_paid_teacher_closings is not null then
      insert into public.reconciliation_issues (
        tenant_id,
        kind,
        student_payment_id,
        details
      ) values (
        coalesce(new.tenant_id, 'master'),
        'REFUND_REQUIRES_TEACHER_PAYOUT_REVIEW',
        new.id,
        jsonb_build_object(
          'competencia', v_payment_competence,
          'fechamentos_pagos', v_paid_teacher_closings,
          'valor_bruto', new.value,
          'valor_estornado_anterior', case
            when tg_op = 'UPDATE' then old.refunded_amount
            else 0
          end,
          'valor_estornado_novo', new.refunded_amount,
          'acao_automatica', false,
          'motivo', 'Rateio ja liquidado exige revisao; nenhum debito automatico foi criado.',
          'registrado_em', now()
        )
      );
    end if;
  end if;

  select exists (
    select 1
      from public.financial_transactions ft
     where ft.student_payment_id = new.id
  ) into v_has_ledger;

  if new.ledger_entry_created is distinct from v_has_ledger then
    update public.student_payments sp
       set ledger_entry_created = v_has_ledger
     where sp.id = new.id
       and sp.ledger_entry_created is distinct from v_has_ledger;
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION ledger_on_payment_received(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.ledger_on_payment_received() IS 'Fonte unica do caixa de mensalidades: uma ENTRADA bruta pela data de credito e uma SAIDA por evento real de estorno; CONFIRMED nunca e caixa e NAO_RECEITA preserva a classificacao.';


--
-- Name: lesson_pays_teacher(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lesson_pays_teacher(p_log_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM v_payable_class_logs v WHERE v.id = p_log_id);
$$;


--
-- Name: link_class_log_to_confirmed_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_class_log_to_confirmed_coverage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_coverage_id uuid;
  v_match_count integer := 0;
BEGIN
  IF NEW.tenant_id IS NULL OR NEW.teacher_id IS NULL
     OR NEW.student_id IS NULL OR NEW.booking_id IS NULL
     OR NEW.class_date IS NULL OR NEW.start_time IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT count(*), (array_agg(coverage.id ORDER BY coverage.id))[1]
    INTO v_match_count, v_coverage_id
    FROM public.class_coverages AS coverage
   WHERE coverage.tenant_id = NEW.tenant_id
     AND pg_catalog.lower(coalesce(coverage.status, '')) = 'confirmed'
     AND coverage.class_log_id IS NULL
     AND coverage.cover_teacher_id = NEW.teacher_id
     AND coverage.student_id IS NOT DISTINCT FROM NEW.student_id
     AND coverage.booking_id::text = NEW.booking_id
     AND coverage.class_date = NEW.class_date
     AND coalesce(coverage.class_time, '') ~
           '^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
     AND CASE
           WHEN coalesce(coverage.class_time, '') ~
                  '^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
             THEN pg_catalog.left(coverage.class_time, 5)::time
         END = NEW.start_time;

  IF v_match_count > 1 THEN
    RAISE EXCEPTION USING
      ERRCODE = '21000', MESSAGE = 'coverage_log_link_ambiguous';
  END IF;
  IF v_match_count = 0 OR v_coverage_id IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM 1
    FROM public.class_coverages AS coverage
   WHERE coverage.id = v_coverage_id
   FOR UPDATE;
  UPDATE public.class_coverages
     SET class_log_id = NEW.id,
         class_log_match_kind = 'booking_time',
         moved_at = pg_catalog.now()
   WHERE id = v_coverage_id
     AND tenant_id = NEW.tenant_id
     AND pg_catalog.lower(coalesce(status, '')) = 'confirmed'
     AND class_log_id IS NULL;
  RETURN NEW;
END;
$_$;


--
-- Name: link_payment_to_student(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_payment_to_student(p_payment_id uuid, p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; v_n int;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles s
                  WHERE s.id = p_student_id AND s.role = 'STUDENT' AND s.tenant_id = v_tenant) THEN
    RETURN jsonb_build_object('error','aluno_invalido');
  END IF;

  -- Só pagamento REALMENTE órfão. Reatribuir um pagamento que já tem dono é
  -- outra operação, com outro risco (mover receita entre alunos), e não passa
  -- por aqui.
  UPDATE student_payments
     SET student_id = p_student_id, updated_at = now()
   WHERE id = p_payment_id AND tenant_id = v_tenant AND student_id IS NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RETURN jsonb_build_object('error','pagamento_nao_encontrado_ou_ja_vinculado'); END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: list_ad_spend_imports(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_ad_spend_imports() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
             'origem', i.origem, 'account_id', i.account_id, 'periodo', i.periodo,
             'amount', i.amount, 'imported_at', i.imported_at)
           ORDER BY i.periodo DESC, i.origem)
      FROM ad_spend_imports i WHERE i.tenant_id = v_tenant), '[]'::jsonb);
END;
$$;


--
-- Name: list_material_approvals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_material_approvals() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_role text := public._my_role();
  actor_tenant_id text := public._my_tenant_id();
  result jsonb;
begin
  if actor_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN')
     or actor_tenant_id is null
     or not public._my_tenant_is_operational() then
    return jsonb_build_object(
      'error', 'sem_permissao',
      'pending_count', 0,
      'items', '[]'::jsonb
    );
  end if;

  select jsonb_build_object(
    'pending_count', (
      select count(*)
      from public.pedagogical_materials as pending_material
      where pending_material.tenant_id = actor_tenant_id
        and pending_material.approval_status = 'PENDING'
    ),
    'items', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', material.id,
          'title', material.title,
          'type', material.type,
          'level_tag', material.level_tag,
          'category', material.category,
          'niche', material.niche,
          'file_url', material.file_url,
          'status', material.approval_status,
          'created_at', material.created_at,
          'author', (
            select profile.full_name
            from public.profiles as profile
            where profile.id = material.uploaded_by
          )
        )
        order by
          (material.approval_status = 'PENDING') desc,
          material.created_at desc
      )
      from (
        select scoped_material.*
        from public.pedagogical_materials as scoped_material
        where scoped_material.tenant_id = actor_tenant_id
          and scoped_material.approval_status in ('PENDING', 'REJECTED')
        order by scoped_material.created_at desc
        limit 80
      ) as material
    ), '[]'::jsonb)
  ) into result;

  return result;
end;
$$;


--
-- Name: list_niches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_niches() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tenant text;
BEGIN
  SELECT tenant_id INTO v_tenant FROM profiles WHERE id=auth.uid();
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('key',key,'label',label) ORDER BY label)
    FROM tenant_niches WHERE tenant_id=v_tenant), '[]'::jsonb);
END;
$$;


--
-- Name: list_payments_not_revenue(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_payments_not_revenue(p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_role text; v_tenant text; v_month text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;
  v_month := COALESCE(p_month, to_char(current_date,'YYYY-MM'));
  IF v_month !~ '^\d{4}-\d{2}$' THEN RETURN jsonb_build_object('error','mes_invalido'); END IF;

  RETURN jsonb_build_object(
    'month', v_month,
    'total', round(COALESCE((SELECT sum(sp.value) FROM student_payments sp
        WHERE sp.tenant_id = v_tenant AND sp.status = 'NAO_RECEITA'
          AND to_char(COALESCE(sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM') = v_month),0),2),
    'pagamentos', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'id', sp.id, 'value', sp.value, 'due_date', sp.due_date,
               'motivo', sp.exclusion_reason,
               'asaas', COALESCE(sp.asaas_payment_id, sp.asaas_id))
             ORDER BY sp.value DESC)
        FROM student_payments sp
       WHERE sp.tenant_id = v_tenant AND sp.status = 'NAO_RECEITA'
         AND to_char(COALESCE(sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM') = v_month), '[]'::jsonb)
  );
END;
$_$;


--
-- Name: list_pending_sdr_work(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pending_sdr_work() RETURNS TABLE(tenant_id text, phone text)
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  select w.tenant_id,w.phone from public.sdr_conversation_work w
  where w.phase<>'REVIEW' and (w.latest_msg_id is distinct from w.completed_msg_id or w.phase='APPLYING')
    and w.available_at<=now() and (w.lease_until is null or w.lease_until<=now())
  order by w.available_at limit 5;
$$;


--
-- Name: list_pending_trial_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pending_trial_sessions() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN '[]'::jsonb;
  END IF;
  RETURN public.list_pending_trial_sessions_unchecked();
END;
$$;


--
-- Name: list_pending_trial_sessions_unchecked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pending_trial_sessions_unchecked() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN '[]'::jsonb; END IF;

  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'appointment_id', a.id,
      'type',           a.type,
      'start_time',     a.start_time,
      'student_name',   a.student_name,
      'teacher_id',     tch.id,
      'teacher_name',   tch.full_name,
      'hourly_rate',    COALESCE(tch.hourly_rate, 0)
    ) ORDER BY a.start_time DESC)
    FROM appointments a
    LEFT JOIN opportunities o ON o.trial_appointment_id = a.id
    LEFT JOIN profiles tch ON tch.id = COALESCE(a.teacher_id, o.winner_teacher_id)
    WHERE a.type IN ('experimental','training')
      AND a.tenant_id = v_tenant
      AND a.status = 'scheduled'                 -- ainda não liquidada (completed/no_show/cancelled saem)
      AND a.start_time <= now()                  -- a hora já passou (realizada)
      AND a.start_time >= '2026-06-01'::timestamptz  -- ignora o passado histórico
      AND tch.id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM class_logs cl WHERE cl.appointment_id = a.id::text)
  ), '[]'::jsonb);
END;
$$;


--
-- Name: list_recurring_expenses(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_recurring_expenses() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; v_mes text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;
  v_mes := to_char(current_date,'YYYY-MM');

  RETURN jsonb_build_object(
    'month', v_mes,
    'contas', (SELECT jsonb_agg(jsonb_build_object('code',code,'label',label,'kind',kind) ORDER BY sort_order)
                 FROM dre_accounts WHERE is_active AND ledger_allowed AND kind IN ('CUSTO','DESPESA','DEDUCAO')),
    'despesas', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'id', r.id, 'label', r.label, 'amount', r.amount,
               'account_code', r.account_code, 'account_label', a.label,
               'day_of_month', r.day_of_month,
               'start_month', r.start_month, 'end_month', r.end_month,
               'is_active', r.is_active, 'notes', r.notes,
               -- vigente = ativa E dentro da janela do mês corrente
               'vigente', r.is_active AND r.start_month <= v_mes
                          AND (r.end_month IS NULL OR r.end_month >= v_mes),
               -- já materializada neste mês?
               'lancada_no_mes', EXISTS (SELECT 1 FROM financial_transactions ft
                                          WHERE ft.recurring_expense_id = r.id
                                            AND ft.recurring_month = v_mes))
             ORDER BY a.sort_order, r.label)
        FROM recurring_expenses r JOIN dre_accounts a ON a.code = r.account_code
       WHERE r.tenant_id = v_tenant), '[]'::jsonb),
    'total_mensal', COALESCE((SELECT sum(amount) FROM recurring_expenses
                               WHERE tenant_id = v_tenant AND is_active
                                 AND start_month <= v_mes
                                 AND (end_month IS NULL OR end_month >= v_mes)), 0)
  );
END;
$$;


--
-- Name: list_referrals_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_referrals_overview() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; r jsonb;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN jsonb_build_object('error','sem_permissao'); END IF;
  SELECT jsonb_build_object(
    'stats', jsonb_build_object(
      'total', (SELECT count(*) FROM referral_rewards WHERE tenant_id=v_tenant),
      'pending_payout', (SELECT COALESCE(sum(amount_brl),0) FROM referral_rewards WHERE tenant_id=v_tenant AND status='PENDING'),
      'credited', (SELECT COALESCE(sum(amount_brl),0) FROM referral_rewards WHERE tenant_id=v_tenant AND status='CREDITED'),
      'paid', (SELECT COALESCE(sum(amount_brl),0) FROM referral_rewards WHERE tenant_id=v_tenant AND status='PAID'),
      'invites_pending', (SELECT count(*) FROM referral_invites WHERE tenant_id=v_tenant AND status='PENDING')
    ),
    'rewards', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'id', rr.id, 'referrer', (SELECT full_name FROM profiles WHERE id=rr.referrer_id), 'role', rr.referrer_role,
        'referred', (SELECT full_name FROM profiles WHERE id=rr.referred_student_id),
        'amount', rr.amount_brl, 'status', rr.status, 'created_at', rr.created_at
      ) ORDER BY rr.created_at DESC)
      FROM (SELECT * FROM referral_rewards WHERE tenant_id=v_tenant ORDER BY created_at DESC LIMIT 100) rr), '[]'::jsonb)
  ) INTO r;
  RETURN r;
END;
$$;


--
-- Name: student_plan_changes; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.student_plan_changes (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    student_id uuid NOT NULL,
    created_by uuid,
    token text DEFAULT encode(extensions.gen_random_bytes(24), 'hex'::text) NOT NULL,
    from_frequency text,
    to_frequency text NOT NULL,
    from_monthly_fee numeric(10,2),
    to_monthly_fee numeric(10,2) NOT NULL,
    fidelity_plan text,
    status text DEFAULT 'PENDING'::text NOT NULL,
    typed_signature text,
    signature_ip text,
    signed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    expires_at timestamp with time zone DEFAULT (now() + '14 days'::interval) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    billing_sync_status text DEFAULT 'NOT_NEEDED'::text NOT NULL,
    billing_sync_error text,
    billing_synced_at timestamp with time zone,
    billing_attempts integer DEFAULT 0 NOT NULL,
    asaas_subscription_id text,
    update_pending_payments boolean DEFAULT true NOT NULL,
    billing_claim_token uuid,
    billing_lease_expires_at timestamp with time zone,
    billing_claimed_at timestamp with time zone,
    CONSTRAINT student_plan_changes_billing_claim_chk CHECK ((((billing_claim_token IS NULL) AND (billing_lease_expires_at IS NULL) AND (billing_claimed_at IS NULL)) OR ((billing_sync_status = 'PENDING'::text) AND (billing_claim_token IS NOT NULL) AND (billing_lease_expires_at IS NOT NULL) AND (billing_claimed_at IS NOT NULL)))),
    CONSTRAINT student_plan_changes_billing_sync_chk CHECK ((billing_sync_status = ANY (ARRAY['NOT_NEEDED'::text, 'PENDING'::text, 'SYNCED'::text, 'FAILED'::text]))),
    CONSTRAINT student_plan_changes_status_chk CHECK ((status = ANY (ARRAY['PENDING'::text, 'SIGNED'::text, 'CANCELLED'::text])))
);


--
-- Name: list_student_plan_changes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_student_plan_changes(p_student_id uuid) RETURNS SETOF public.student_plan_changes
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select c.*
    from public.student_plan_changes c
   where c.student_id = p_student_id
     and (
       c.student_id = (select auth.uid())
       or (c.tenant_id = public._my_tenant_id()
           and public._my_role() = any (array['SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN']))
     )
   order by c.created_at desc;
$$;


--
-- Name: list_student_renewal_cases(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_student_renewal_cases(p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  actor_role text := private.active_tenant_role(actor_id);
  actor_tenant text := private.active_tenant_id(actor_id);
  requested_tenant text := nullif(
    pg_catalog.btrim(coalesce(p_tenant, '')),
    ''
  );
  target_tenant text := actor_tenant;
  items jsonb;
begin
  if actor_id is null
     or actor_tenant is null
     or actor_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR')
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'forbidden'
    );
  end if;

  if requested_tenant is not null
     and requested_tenant is distinct from target_tenant
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'tenant_mismatch'
    );
  end if;

  if not private.tenant_is_operational(target_tenant) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'tenant_not_operational'
    );
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.to_jsonb(item)
      order by item.service_end_date, item.student_name, item.student_id
    ),
    '[]'::jsonb
  )
    into items
    from (
      select
        renewal.id,
        renewal.student_id_snapshot as student_id,
        coalesce(
          nullif(pg_catalog.btrim(student.full_name), ''),
          'Aluno removido'
        ) as student_name,
        renewal.service_end_date,
        renewal.monthly_fee_snapshot,
        renewal.status,
        renewal.last_contact_at,
        renewal.last_channel,
        renewal.next_action_at,
        renewal.interest_term_months,
        renewal.version,
        renewal.source_subscription_synced_at,
        renewal.updated_at,
        actor.full_name as updated_by_name,
        (
          student.id is not null
          and student.tenant_id = renewal.tenant_id
          and pg_catalog.lower(pg_catalog.btrim(coalesce(
            student.lifecycle_status,
            ''
          ))) = 'active'
          and private.active_tenant_id(student.id)
                is not distinct from renewal.tenant_id
          and private.active_tenant_role(student.id)
                is not distinct from 'STUDENT'
          and public.fim_do_servico(student.asaas_subscription_end_date)
                is not distinct from renewal.service_end_date
          and exists (
            select 1
              from public.tenant_memberships as membership
             where membership.user_id = student.id
               and membership.tenant_id = renewal.tenant_id
               and membership.role = 'STUDENT'
               and membership.status = 'ACTIVE'
          )
        ) as cycle_current,
        (
          select pg_catalog.count(*)::integer
            from public.student_renewal_case_events as event
           where event.tenant_id = renewal.tenant_id
             and event.renewal_case_id = renewal.id
        ) as event_count,
        (
          select event.created_at
            from public.student_renewal_case_events as event
           where event.tenant_id = renewal.tenant_id
             and event.renewal_case_id = renewal.id
           order by event.result_version desc, event.created_at desc, event.id desc
           limit 1
        ) as latest_action_at,
        (
          select event_note.note
            from public.student_renewal_case_events as event
            join public.student_renewal_case_event_notes as event_note
              on event_note.tenant_id = event.tenant_id
             and event_note.event_id = event.id
             and event_note.renewal_case_id = event.renewal_case_id
           where event.tenant_id = renewal.tenant_id
             and event.renewal_case_id = renewal.id
           order by event.result_version desc, event.created_at desc, event.id desc
           limit 1
        ) as latest_note
      from public.student_renewal_cases as renewal
      left join public.profiles as actor on actor.id = renewal.updated_by
      left join public.profiles as student on student.id = renewal.student_id
      where renewal.tenant_id = target_tenant
    ) as item;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'items', items
  );
end;
$$;


--
-- Name: list_students_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_students_overview() RETURNS TABLE(student_id uuid, full_name text, avatar_url text, module text, professor_id uuid, professor_name text, monthly_fee numeric, status_financial text, phone text, is_kids boolean, attended_90 integer, absent_90 integer, attendance_rate integer, last_class_date date, days_since_last integer, overdue_count integer, overdue_value numeric, xp integer, streak_count integer, last_activity timestamp with time zone, risk_level text, risk_score integer, risk_reasons text[], has_activity boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_role text; v_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = v_uid;
  IF v_role IS NULL THEN RETURN; END IF;
  RETURN QUERY
  WITH students AS (
    SELECT p.* FROM profiles p WHERE p.role = 'STUDENT'
      AND (v_role='SUPER_ADMIN'
        OR (v_role='SCHOOL_ADMIN' AND p.tenant_id=v_tenant)
        OR (v_role='TEACHER' AND (p.professor_id=v_uid OR p.professor_id2=v_uid
             OR EXISTS (SELECT 1 FROM bookings b WHERE b.student_id=p.id AND b.teacher_id=v_uid))))
  ),
  freq AS (
    SELECT cl.student_id,
      count(*) FILTER (WHERE cl.presence='COMPLETED' AND cl.class_date>=current_date-90) AS att90,
      count(*) FILTER (WHERE cl.presence='STUDENT_ABSENCE' AND cl.class_date>=current_date-90) AS abs90,
      count(*) FILTER (WHERE cl.presence='STUDENT_ABSENCE' AND cl.class_date>=current_date-45) AS abs45,
      max(cl.class_date) FILTER (WHERE cl.presence IN ('COMPLETED','STUDENT_ABSENCE')) AS last_cd
    FROM class_logs cl WHERE cl.student_id IN (SELECT id FROM students) GROUP BY cl.student_id
  ),
  pay AS (
    SELECT sp.student_id, count(*) FILTER (WHERE sp.status='OVERDUE') AS od_count,
      coalesce(sum(sp.value) FILTER (WHERE sp.status='OVERDUE'),0) AS od_value
    FROM student_payments sp WHERE sp.student_id IN (SELECT id FROM students) GROUP BY sp.student_id
  ),
  base AS (
    SELECT s.id, s.full_name, s.avatar_url, s.module, s.professor_id,
      s.monthly_fee, s.status_financial, s.phone, coalesce(s.is_kids,false) AS is_kids,
      coalesce(f.att90,0) AS att90, coalesce(f.abs90,0) AS abs90, coalesce(f.abs45,0) AS abs45,
      CASE WHEN coalesce(f.att90,0)+coalesce(f.abs90,0)>0 THEN round(100.0*f.att90/(f.att90+f.abs90))::int END AS rate,
      f.last_cd,
      CASE WHEN f.last_cd IS NOT NULL THEN (current_date-f.last_cd) END AS dsl,
      coalesce(pp.od_count,0) AS od_count, coalesce(pp.od_value,0) AS od_value,
      coalesce(s.xp,0) AS xp, coalesce(s.streak_count,0) AS streak, s.last_activity, s.offboarding_status,
      (EXISTS (SELECT 1 FROM bookings b WHERE b.student_id=s.id)
        OR EXISTS (SELECT 1 FROM student_payments sp2 WHERE sp2.student_id=s.id)) AS has_activity
    FROM students s LEFT JOIN freq f ON f.student_id=s.id LEFT JOIN pay pp ON pp.student_id=s.id
  ),
  scored AS (
    SELECT b.*,
      ((b.od_count>0)::int + (b.abs45>=2)::int + (b.offboarding_status IS NOT NULL AND b.offboarding_status<>'')::int) AS strong,
      ((b.dsl>30)::int + ((b.att90+b.abs90)>=4 AND b.rate<60)::int) AS weak,
      array_remove(ARRAY[
        CASE WHEN b.od_count>0 THEN 'Pagamento em atraso' END,
        CASE WHEN b.abs45>=2 THEN b.abs45||' faltas recentes' END,
        CASE WHEN b.offboarding_status IS NOT NULL AND b.offboarding_status<>'' THEN 'Saída solicitada' END,
        CASE WHEN b.dsl>30 THEN 'Inativo há '||b.dsl||' dias' END,
        CASE WHEN (b.att90+b.abs90)>=4 AND b.rate<60 THEN 'Frequência baixa ('||b.rate||'%)' END
      ], NULL) AS reasons
    FROM base b
  )
  SELECT sc.id, sc.full_name, sc.avatar_url, sc.module, sc.professor_id,
    (SELECT pr.full_name FROM profiles pr WHERE pr.id=sc.professor_id),
    sc.monthly_fee, sc.status_financial, sc.phone, sc.is_kids,
    sc.att90::int, sc.abs90::int, sc.rate, sc.last_cd, sc.dsl::int,
    sc.od_count::int, sc.od_value, sc.xp::int, sc.streak::int, sc.last_activity,
    CASE WHEN sc.strong>=2 OR (sc.strong>=1 AND sc.weak>=1) THEN 'HIGH'
         WHEN sc.strong=1 OR sc.weak>=2 THEN 'MEDIUM' ELSE 'LOW' END,
    (sc.strong*2+sc.weak)::int,
    CASE WHEN (sc.strong>=1 OR sc.weak>=2) THEN sc.reasons ELSE ARRAY[]::text[] END,
    sc.has_activity
  FROM scored sc
  ORDER BY (sc.strong*2+sc.weak) DESC, sc.full_name;
END;
$$;


--
-- Name: list_teacher_turbo_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_teacher_turbo_overview() RETURNS TABLE(teacher_id uuid, full_name text, tenant_id text, turbo_status text, turbo_active boolean, students_active integer, students_required integer, students_missing integer, streak_days integer, days_to_activate integer, active_since date, active_days integer, suspensions_open integer, suspension_since timestamp with time zone, last_absence_on date, blocked_by text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_tenant text;
  v_jwt_role text;
BEGIN
  v_jwt_role := COALESCE(
    NULLIF(current_setting('request.jwt.claims', true), '')::jsonb->>'role',
    ''
  );

  IF v_jwt_role = 'service_role' THEN
    v_role := 'SUPER_ADMIN';
  ELSE
    v_role := public._my_role();
    v_tenant := public._my_tenant_id();
  END IF;

  IF NOT COALESCE(v_role IN ('SCHOOL_ADMIN', 'SUPER_ADMIN'), false) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT p.id,
         p.full_name,
         p.tenant_id,
         s.j->>'status',
         COALESCE((s.j->>'active')::boolean, false),
         COALESCE((s.j->>'students_active')::integer, 0),
         COALESCE((s.j->>'students_required')::integer, 10),
         COALESCE((s.j->>'students_missing')::integer, 10),
         COALESCE((s.j->>'days_clean')::integer, 0),
         COALESCE((s.j->>'days_to_activate')::integer, 30),
         NULLIF(s.j->>'active_since', '')::date,
         COALESCE((s.j->>'active_days')::integer, 0),
         COALESCE((s.j->>'suspensions_open')::integer, 0),
         NULLIF(s.j->>'suspension_since', '')::timestamptz,
         NULLIF(s.j->>'last_confirmed_absence_on', '')::date,
         s.j->>'blocked_by'
  FROM public.profiles p
  CROSS JOIN LATERAL (
    SELECT public.teacher_turbo_status(p.id) AS j
  ) s
  WHERE p.role = 'TEACHER'
    AND COALESCE(p.lifecycle_status, 'active') <> 'offboarded'
    AND (v_role = 'SUPER_ADMIN' OR p.tenant_id = v_tenant)
  ORDER BY p.full_name;
END;
$$;


--
-- Name: FUNCTION list_teacher_turbo_overview(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_teacher_turbo_overview() IS 'Visao tenant-safe da diretoria: Turbo, carteira, dias de ofensiva/restantes/ativos, suspensoes e ultima falta de cada professor.';


--
-- Name: list_teachers_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_teachers_overview() RETURNS TABLE(teacher_id uuid, full_name text, avatar_url text, status text, hourly_rate numeric, commission_rate numeric, specializations text[], active_students integer, classes_30 integer, teacher_absence_30 integer, absence_rate integer, conflicts_open integer, avg_rating numeric, rating_count integer, earnings_est numeric, nf_pending boolean, pix_ok boolean, contract_ok boolean, alert_level text, alert_score integer, alert_reasons text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN;
  END IF;
  RETURN QUERY
  SELECT implementation.*
  FROM public.list_teachers_overview_unchecked() AS implementation;
END;
$$;


--
-- Name: list_teachers_overview_unchecked(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_teachers_overview_unchecked() RETURNS TABLE(teacher_id uuid, full_name text, avatar_url text, status text, hourly_rate numeric, commission_rate numeric, specializations text[], active_students integer, classes_30 integer, teacher_absence_30 integer, absence_rate integer, conflicts_open integer, avg_rating numeric, rating_count integer, earnings_est numeric, nf_pending boolean, pix_ok boolean, contract_ok boolean, alert_level text, alert_score integer, alert_reasons text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
DECLARE v_uid uuid := auth.uid(); v_role text; v_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = v_uid;
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN; END IF;
  RETURN QUERY
  WITH teachers AS (SELECT p.* FROM profiles p WHERE p.role='TEACHER' AND (v_role='SUPER_ADMIN' OR p.tenant_id=v_tenant)),
  cl AS (
    SELECT lg.teacher_id AS tid,
      count(*) FILTER (WHERE lg.presence='COMPLETED' AND lg.class_date>=current_date-30) AS c30,
      count(*) FILTER (WHERE lg.presence='TEACHER_ABSENCE' AND lg.class_date>=current_date-30) AS a30
    FROM class_logs lg WHERE lg.teacher_id IN (SELECT id FROM teachers) GROUP BY lg.teacher_id
  ),
  -- Carteira, não `count(distinct bookings.student_id)`: o segundo conta perfil
  -- de treinamento, aluno desligado e agendamento cancelado.
  stu AS (SELECT t.id AS tid, (SELECT count(*) FROM teacher_carteira(t.id)) AS n FROM teachers t),
  -- Ganho do mês pela fonte do pagamento.
  earn AS (
    SELECT v.teacher_id AS tid, round(coalesce(sum(v.rate_efetivo),0),2) AS valor
    FROM v_payable_class_logs v
    WHERE v.teacher_id IN (SELECT id FROM teachers)
      AND v.class_date >= date_trunc('month', current_date)::date
    GROUP BY v.teacher_id
  ),
  conf AS (SELECT ac.teacher_id AS tid, count(*) FILTER (WHERE ac.status='CONFLICT') AS conflicts,
      avg(ac.student_rating) FILTER (WHERE ac.student_rating IS NOT NULL) AS avg_r, count(ac.student_rating) AS rc
    FROM attendance_confirmations ac WHERE ac.teacher_id IN (SELECT id FROM teachers) GROUP BY ac.teacher_id),
  closings AS (SELECT tc.teacher_id AS tid, bool_or(tc.status='PENDENTE') AS nf_pending FROM teacher_closings tc WHERE tc.teacher_id IN (SELECT id FROM teachers) GROUP BY tc.teacher_id),
  base AS (
    SELECT t.id, t.full_name, t.avatar_url, t.status, t.hourly_rate, t.commission_rate, t.specializations,
      coalesce(s.n,0) AS students, coalesce(c.c30,0) AS c30, coalesce(c.a30,0) AS a30,
      coalesce(e.valor,0) AS earn_month,
      coalesce(cf.conflicts,0) AS conflicts, round(cf.avg_r,1) AS avg_r, coalesce(cf.rc,0) AS rc,
      coalesce(cl2.nf_pending,false) AS nf_pending,
      (t.pix_key IS NOT NULL AND t.pix_key<>'') AS pix_ok,
      (coalesce(t.contract_accepted,false) OR t.accepted_at IS NOT NULL OR t.documentation_status='APPROVED') AS contract_ok
    FROM teachers t
    LEFT JOIN cl c ON c.tid=t.id
    LEFT JOIN stu s ON s.tid=t.id
    LEFT JOIN earn e ON e.tid=t.id
    LEFT JOIN conf cf ON cf.tid=t.id
    LEFT JOIN closings cl2 ON cl2.tid=t.id
  ),
  scored AS (
    SELECT b.*,
      ((b.a30>=2)::int + (b.conflicts>0)::int + (b.nf_pending)::int) AS strong,
      ((b.rc>=3 AND b.avg_r<3.5)::int + (NOT b.pix_ok OR NOT b.contract_ok)::int) AS weak,
      CASE WHEN b.c30+b.a30>0 THEN round(100.0*b.a30/(b.c30+b.a30))::int ELSE 0 END AS abs_rate,
      array_remove(ARRAY[
        CASE WHEN b.a30>=2 THEN b.a30||' faltas do professor (30d)' END,
        CASE WHEN b.conflicts>0 THEN b.conflicts||' conflito(s) de presença' END,
        CASE WHEN b.nf_pending THEN 'Fechamento/NF pendente' END,
        CASE WHEN b.rc>=3 AND b.avg_r<3.5 THEN 'Avaliação baixa ('||b.avg_r||')' END,
        CASE WHEN NOT b.pix_ok THEN 'PIX não cadastrado' END,
        CASE WHEN NOT b.contract_ok THEN 'Contrato pendente' END
      ], NULL) AS reasons
    FROM base b
  )
  SELECT sc.id, sc.full_name, sc.avatar_url, sc.status, sc.hourly_rate::numeric, sc.commission_rate::numeric, sc.specializations,
    sc.students::int, sc.c30::int, sc.a30::int, sc.abs_rate, sc.conflicts::int, sc.avg_r::numeric, sc.rc::int,
    sc.earn_month::numeric, sc.nf_pending, sc.pix_ok, sc.contract_ok,
    CASE WHEN sc.strong>=2 OR (sc.strong>=1 AND sc.weak>=1) THEN 'HIGH' WHEN sc.strong=1 OR sc.weak>=2 THEN 'MEDIUM' ELSE 'LOW' END,
    (sc.strong*2+sc.weak)::int, sc.reasons
  FROM scored sc ORDER BY (sc.strong*2+sc.weak) DESC, sc.full_name;
END;
$$;


--
-- Name: list_tenant_teachers_for_transfer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_tenant_teachers_for_transfer() RETURNS TABLE(id uuid, full_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT p.id, p.full_name FROM profiles p
  WHERE p.role = 'TEACHER'
    AND p.tenant_id = (SELECT tenant_id FROM profiles WHERE id = auth.uid())
    AND COALESCE(p.lifecycle_status,'active') <> 'offboarded'
  ORDER BY p.full_name;
$$;


--
-- Name: list_tenants_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_tenants_overview() RETURNS TABLE(tenant_id text, name text, plan_name text, plan_price numeric, saas_status text, students integer, teachers integer, student_limit integer, usage_pct integer, classes_30 integer, last_activity date, overdue_invoices integer, trial_ends_at timestamp with time zone, mrr numeric, risk_level text, risk_score integer, risk_reasons text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
#variable_conflict use_column
BEGIN
  IF NOT is_super_admin() THEN RETURN; END IF;
  RETURN QUERY
  WITH t AS (SELECT * FROM tenants WHERE id <> 'master'),
  cnt AS (
    SELECT p.tenant_id AS tid, count(*) FILTER (WHERE p.role='STUDENT') AS students, count(*) FILTER (WHERE p.role='TEACHER') AS teachers
    FROM profiles p WHERE p.tenant_id IN (SELECT id FROM t) GROUP BY p.tenant_id
  ),
  act AS (
    SELECT lg.tenant_id AS tid, count(*) FILTER (WHERE lg.class_date>=current_date-30) AS c30, max(lg.class_date) AS last_cd
    FROM class_logs lg WHERE lg.tenant_id IN (SELECT id FROM t) GROUP BY lg.tenant_id
  ),
  inv AS (SELECT si.tenant_id AS tid, count(*) FILTER (WHERE si.status='OVERDUE') AS od FROM saas_invoices si WHERE si.tenant_id IN (SELECT id FROM t) GROUP BY si.tenant_id),
  base AS (
    SELECT t.id, t.name, pl.name AS plan_name, pl.price AS plan_price, t.saas_status,
      coalesce(c.students,0) AS students, coalesce(c.teachers,0) AS teachers, coalesce(t.student_limit,0) AS slimit,
      CASE WHEN coalesce(t.student_limit,0)>0 THEN round(100.0*coalesce(c.students,0)/t.student_limit)::int ELSE 0 END AS usage_pct,
      coalesce(a.c30,0) AS c30, a.last_cd, coalesce(i.od,0) AS od, t.trial_ends_at, t.plan_id,
      CASE WHEN t.saas_status='active' THEN pl.price ELSE 0 END AS mrr
    FROM t LEFT JOIN saas_plans pl ON pl.id=t.plan_id
    LEFT JOIN cnt c ON c.tid=t.id LEFT JOIN act a ON a.tid=t.id LEFT JOIN inv i ON i.tid=t.id
  ),
  scored AS (
    SELECT b.*,
      ((b.saas_status IN ('blocked','past_due'))::int + (b.od>0)::int
       + (b.trial_ends_at IS NOT NULL AND b.trial_ends_at::date < current_date AND b.plan_id IS NULL)::int
       + (b.plan_id IS NULL)::int) AS strong,
      ((b.students>0 AND b.c30=0)::int + (b.students=0)::int + (b.usage_pct>=80)::int) AS weak,
      array_remove(ARRAY[
        CASE WHEN b.saas_status='blocked' THEN 'Acesso bloqueado' WHEN b.saas_status='past_due' THEN 'Pagamento atrasado' END,
        CASE WHEN b.od>0 THEN b.od||' fatura(s) vencida(s)' END,
        CASE WHEN b.trial_ends_at IS NOT NULL AND b.trial_ends_at::date < current_date AND b.plan_id IS NULL THEN 'Trial expirado sem plano' END,
        CASE WHEN b.plan_id IS NULL THEN 'Sem plano atribuído' END,
        CASE WHEN b.students>0 AND b.c30=0 THEN 'Sem atividade (30d)' END,
        CASE WHEN b.students=0 THEN 'Sem alunos' END,
        CASE WHEN b.usage_pct>=80 THEN 'Perto do limite ('||b.usage_pct||'%)' END
      ], NULL) AS reasons
    FROM base b
  )
  SELECT sc.id, sc.name, sc.plan_name, sc.plan_price, sc.saas_status,
    sc.students::int, sc.teachers::int, sc.slimit::int, sc.usage_pct, sc.c30::int, sc.last_cd, sc.od::int, sc.trial_ends_at,
    coalesce(sc.mrr,0),
    CASE WHEN sc.strong>=2 OR (sc.strong>=1 AND sc.weak>=1) THEN 'HIGH'
         WHEN sc.strong=1 OR sc.weak>=2 THEN 'MEDIUM' ELSE 'LOW' END,
    (sc.strong*2+sc.weak)::int, sc.reasons
  FROM scored sc
  ORDER BY (sc.strong*2+sc.weak) DESC, sc.students DESC;
END;
$$;


--
-- Name: list_unlinked_payments(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_unlinked_payments(p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_role text; v_tenant text; v_month text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;
  v_month := COALESCE(p_month, to_char(current_date,'YYYY-MM'));
  IF v_month !~ '^\d{4}-\d{2}$' THEN RETURN jsonb_build_object('error','mes_invalido'); END IF;

  RETURN jsonb_build_object(
    'month', v_month,
    'pagamentos', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'id', sp.id, 'value', sp.value, 'status', sp.status,
               'due_date', sp.due_date,
               'pago_em', COALESCE(sp.paid_at::date, sp.payment_date),
               'billing_type', sp.billing_type,
               'asaas', COALESCE(sp.asaas_payment_id, sp.asaas_id),
               'descricao', sp.description,
               -- Pista barata contra duplicata: já existe pagamento do MESMO
               -- valor, no mesmo mês, com aluno? Foi assim que o recebimento em
               -- dinheiro da Ana Clara apareceu duas vezes.
               'mesmo_valor_ja_lancado', (
                  SELECT count(*)::int FROM student_payments o
                   WHERE o.tenant_id = sp.tenant_id AND o.student_id IS NOT NULL
                     AND o.value = sp.value
                     AND o.status IN ('RECEIVED','RECEIVED_IN_CASH')
                     AND to_char(COALESCE(o.paid_at, o.payment_date, o.due_date),'YYYY-MM')
                         = to_char(COALESCE(sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM')))
             ORDER BY sp.value DESC)
        FROM student_payments sp
       WHERE sp.tenant_id = v_tenant AND sp.student_id IS NULL
         AND sp.status IN ('RECEIVED','RECEIVED_IN_CASH')
         AND to_char(COALESCE(sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM') = v_month
    ), '[]'::jsonb),
    'alunos', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('id', p.id, 'nome', trim(p.full_name)) ORDER BY p.full_name)
        FROM profiles p
       WHERE p.tenant_id = v_tenant AND p.role = 'STUDENT'
         AND COALESCE(p.status_financial,'') <> 'ARCHIVED'), '[]'::jsonb)
  );
END;
$_$;


--
-- Name: list_unlogged_confirmed_classes(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_unlogged_confirmed_classes(p_days integer DEFAULT 180) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_tenant text;
  v_days integer;
  v_out jsonb;
begin
  if v_uid is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  select public._my_role(), public._my_tenant_id()
    into v_role, v_tenant;

  if not coalesce(v_role in ('SCHOOL_ADMIN', 'SUPER_ADMIN'), false)
     or (v_role <> 'SUPER_ADMIN' and v_tenant is null) then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  v_days := greatest(1, least(coalesce(p_days, 180), 365));

  with confirmations as (
    select
      ac.*,
      coalesce(
        case
          when pg_catalog.btrim(ac.class_time) ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
          then pg_catalog.left(pg_catalog.btrim(ac.class_time), 5)::time
        end,
        case when ac.source_type = 'booking' then (
          select pg_catalog.left(pg_catalog.btrim(b.time_slot), 5)::time
            from public.bookings b
           where b.id::text = ac.source_id
             and b.tenant_id = ac.tenant_id
             and b.student_id is not distinct from ac.student_id
             and pg_catalog.btrim(b.time_slot) ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
           limit 1
        ) end,
        case when ac.source_type = 'reschedule' then (
          select pg_catalog.left(pg_catalog.btrim(r.time), 5)::time
            from public.reschedules r
           where r.id::text = ac.source_id
             and r.tenant_id = ac.tenant_id
             and r.teacher_id = ac.teacher_id
             and r.student_id is not distinct from ac.student_id
             and pg_catalog.btrim(r.time) ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
           limit 1
        ) end
      ) as occurrence_time
    from public.attendance_confirmations ac
    where ac.source_type in ('booking', 'reschedule')
      and nullif(pg_catalog.btrim(ac.source_id), '') is not null
      and (v_role = 'SUPER_ADMIN' or ac.tenant_id = v_tenant)
  ), orphaned as (
    select
      ac.id,
      ac.teacher_id,
      ac.student_id,
      ac.student_name,
      ac.class_date,
      ac.class_time,
      ac.student_response,
      ac.source_type,
      coalesce(p.full_name, ac.teacher_name, 'Professor') as teacher_name,
      coalesce(public.teacher_student_rate(ac.teacher_id, ac.student_id, ac.class_date), 0) as rate
    from confirmations ac
    left join public.profiles p
      on p.id = ac.teacher_id
     and p.tenant_id = ac.tenant_id
    where ac.status = 'AWAITING_TEACHER'
      and ac.student_response in ('STUDENT_PRESENT', 'STUDENT_SELF_ABSENT')
      and ac.class_log_id is null
      and ac.teacher_id is not null
      and ac.class_date >= (pg_catalog.now() at time zone 'America/Sao_Paulo')::date - v_days
      and not exists (
        select 1
          from public.class_logs cl
         where cl.tenant_id = ac.tenant_id
           and cl.class_date = ac.class_date
           and (
             (ac.source_type = 'booking' and cl.booking_id = ac.source_id)
             or (ac.source_type = 'reschedule' and cl.reschedule_id = ac.source_id)
             or (
               ac.occurrence_time is not null
               and ac.student_id is not null
               and cl.teacher_id = ac.teacher_id
               and cl.student_id = ac.student_id
               and cl.start_time = ac.occurrence_time
             )
           )
      )
  )
  select pg_catalog.jsonb_build_object(
    'ok', true,
    'total', (select count(*) from orphaned),
    'valor_total', (select coalesce(sum(rate), 0) from orphaned),
    'teachers', coalesce((
      select pg_catalog.jsonb_agg(t order by (t ->> 'aulas')::int desc)
        from (
          select pg_catalog.jsonb_build_object(
            'teacher_id', o.teacher_id,
            'teacher_name', o.teacher_name,
            'aulas', count(*)::int,
            'valor', coalesce(sum(o.rate), 0),
            'mais_antiga', min(o.class_date),
            'classes', pg_catalog.jsonb_agg(
              pg_catalog.jsonb_build_object(
                'id', o.id,
                'student_name', o.student_name,
                'class_date', o.class_date,
                'class_time', o.class_time,
                'student_response', o.student_response,
                'valor', o.rate
              ) order by o.class_date, o.class_time
            )
          ) as t
          from orphaned o
          group by o.teacher_id, o.teacher_name
        ) grouped
    ), '[]'::jsonb)
  )
  into v_out;

  return v_out;
end;
$_$;


--
-- Name: list_vendors_overview(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_vendors_overview() RETURNS TABLE(vendor_id uuid, full_name text, avatar_url text, status text, commission_rate numeric, pix_ok boolean, matriculas integer, revenue_brought numeric, pending_count integer, pending_amount numeric, confirmed_unpaid numeric, paid_amount numeric, last_sale timestamp with time zone, alert_level text, alert_reasons text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
#variable_conflict use_column
DECLARE v_uid uuid := auth.uid(); v_role text; v_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id=v_uid;
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN; END IF;
  RETURN QUERY
  WITH v AS (SELECT * FROM profiles WHERE role='SALESPERSON' AND (v_role='SUPER_ADMIN' OR tenant_id=v_tenant)),
  c AS (
    SELECT vc.vendor_id AS vid, count(DISTINCT vc.student_id) AS matriculas, coalesce(sum(vc.amount_brl),0) AS revenue,
      count(*) FILTER (WHERE vc.status='PENDING') AS pend_c,
      coalesce(sum(vc.amount_brl) FILTER (WHERE vc.status='PENDING'),0) AS pend_a,
      coalesce(sum(vc.amount_brl) FILTER (WHERE vc.status='CONFIRMED'),0) AS conf_unpaid,
      coalesce(sum(vc.amount_brl) FILTER (WHERE vc.status='PAID'),0) AS paid_a, max(vc.created_at) AS last_sale
    FROM vendor_commissions vc WHERE vc.vendor_id IN (SELECT id FROM v) GROUP BY vc.vendor_id
  ),
  base AS (
    SELECT v.id, v.full_name, v.avatar_url, v.status, v.commission_rate,
      (v.pix_key IS NOT NULL AND v.pix_key<>'') AS pix_ok,
      coalesce(c.matriculas,0) AS matriculas, coalesce(c.revenue,0) AS revenue,
      coalesce(c.pend_c,0) AS pend_c, coalesce(c.pend_a,0) AS pend_a, coalesce(c.conf_unpaid,0) AS conf_unpaid, coalesce(c.paid_a,0) AS paid_a, c.last_sale
    FROM v LEFT JOIN c ON c.vid=v.id
  )
  SELECT b.id, b.full_name, b.avatar_url, b.status, b.commission_rate::numeric, b.pix_ok,
    b.matriculas::int, b.revenue::numeric, b.pend_c::int, b.pend_a::numeric, b.conf_unpaid::numeric, b.paid_a::numeric, b.last_sale,
    CASE WHEN b.conf_unpaid>0 AND NOT b.pix_ok THEN 'HIGH' WHEN b.conf_unpaid>0 OR NOT b.pix_ok THEN 'MEDIUM' ELSE 'LOW' END,
    array_remove(ARRAY[
      CASE WHEN b.conf_unpaid>0 THEN 'A pagar: R$ '||to_char(b.conf_unpaid,'FM999G990D00') END,
      CASE WHEN NOT b.pix_ok THEN 'PIX não cadastrado' END,
      CASE WHEN b.matriculas>0 AND b.last_sale < now()-interval '30 days' THEN 'Sem vendas há 30+ dias' END
    ], NULL)
  FROM base b ORDER BY b.conf_unpaid DESC, b.revenue DESC, b.full_name;
END;
$_$;


--
-- Name: log_profile_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_profile_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_by uuid := auth.uid(); PROC RECORD; vals text[][];
BEGIN
  IF NEW.role = 'STUDENT' THEN
    FOR PROC IN SELECT * FROM (VALUES
      ('full_name', OLD.full_name, NEW.full_name),
      ('module', OLD.module, NEW.module),
      ('monthly_fee', OLD.monthly_fee::text, NEW.monthly_fee::text),
      ('due_day', OLD.due_day::text, NEW.due_day::text),
      ('status_financial', OLD.status_financial, NEW.status_financial),
      ('professor_id', OLD.professor_id::text, NEW.professor_id::text),
      ('cpf', OLD.cpf, NEW.cpf), ('phone', OLD.phone, NEW.phone)
    ) AS t(field, oldv, newv) LOOP
      IF PROC.oldv IS DISTINCT FROM PROC.newv THEN
        INSERT INTO profile_audit_log (tenant_id, profile_id, changed_by, field, old_value, new_value)
        VALUES (NEW.tenant_id, NEW.id, v_by, PROC.field, PROC.oldv, PROC.newv); END IF;
    END LOOP;
  ELSIF NEW.role = 'TEACHER' THEN
    FOR PROC IN SELECT * FROM (VALUES
      ('full_name', OLD.full_name, NEW.full_name),
      ('hourly_rate', OLD.hourly_rate::text, NEW.hourly_rate::text),
      ('commission_rate', OLD.commission_rate::text, NEW.commission_rate::text),
      ('status', OLD.status, NEW.status), ('pix_key', OLD.pix_key, NEW.pix_key)
    ) AS t(field, oldv, newv) LOOP
      IF PROC.oldv IS DISTINCT FROM PROC.newv THEN
        INSERT INTO profile_audit_log (tenant_id, profile_id, changed_by, field, old_value, new_value)
        VALUES (NEW.tenant_id, NEW.id, v_by, PROC.field, PROC.oldv, PROC.newv); END IF;
    END LOOP;
  ELSIF NEW.role = 'SALESPERSON' THEN
    FOR PROC IN SELECT * FROM (VALUES
      ('full_name', OLD.full_name, NEW.full_name),
      ('commission_rate', OLD.commission_rate::text, NEW.commission_rate::text),
      ('status', OLD.status, NEW.status), ('pix_key', OLD.pix_key, NEW.pix_key)
    ) AS t(field, oldv, newv) LOOP
      IF PROC.oldv IS DISTINCT FROM PROC.newv THEN
        INSERT INTO profile_audit_log (tenant_id, profile_id, changed_by, field, old_value, new_value)
        VALUES (NEW.tenant_id, NEW.id, v_by, PROC.field, PROC.oldv, PROC.newv); END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: log_security_event(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_security_event(p_event_type text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    INSERT INTO public.signature_audit_log (event_type, metadata, created_at)
    VALUES (p_event_type, p_metadata, now());
END;
$$;


--
-- Name: log_security_event(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_security_event(p_event_type text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    INSERT INTO public.security_events (
        event_type,
        severity,
        source,
        tenant_id,
        actor_id,
        details
    ) VALUES (
        p_event_type,
        CASE
            WHEN p_event_type IN ('LEGACY_LINK_USED', 'TOKEN_CONSUMED') THEN 'LOW'
            WHEN p_event_type IN ('CLAIM_FAILED', 'TOKEN_REUSE') THEN 'MEDIUM'
            WHEN p_event_type IN ('TOKEN_FORGED', 'RLS_BYPASS_ATTEMPT') THEN 'HIGH'
            ELSE 'INFO'
        END,
        'SYSTEM',
        (SELECT tenant_id FROM public.profiles WHERE id = auth.uid()),
        auth.uid(),
        p_metadata || jsonb_build_object('entity_type', p_entity_type, 'entity_id', p_entity_id)
    );
END;
$$;


--
-- Name: log_security_event(text, text, text, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_security_event(p_event_type text, p_severity text DEFAULT 'INFO'::text, p_source text DEFAULT 'unknown'::text, p_tenant_id text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_details jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO public.security_events (event_type, severity, source, tenant_id, actor_id, details)
    VALUES (p_event_type, p_severity, p_source, p_tenant_id, p_actor_id, p_details)
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$$;


--
-- Name: log_teacher_classes(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.log_teacher_classes(p_entries jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_teacher_id uuid := auth.uid();
  v_role text;
  v_tenant text;
  v_profile record;
  v_entry jsonb;
  v_count int;

  -- por entrada
  v_ref text;
  v_booking_id text;
  v_reschedule_id text;
  v_appointment_id text;
  v_student_id uuid;
  v_class_date date;
  v_presence text;
  v_kind text;
  v_subtype text;
  v_fault_origin text;
  v_appt_type text;
  v_new_id uuid;
  v_skip_reason text;
  v_student_absence_count int;
  v_occurrence_time time;
  v_confirmation_time time;
  v_source_date date;
  v_slot_day int;
  v_constraint_name text;

  v_results jsonb := '[]'::jsonb;
  v_inserted_ids uuid[] := array[]::uuid[];
  v_inserted int := 0;
  v_skipped int := 0;
  v_reschedules_created int := 0;

  v_delta_amount numeric := 0;
  v_delta_lessons int := 0;
  v_projection jsonb;
begin
  ---------------------------------------------------------------------------
  -- 1. Autenticação e escopo. `teacher_id` é SEMPRE auth.uid(): não existe
  --    parâmetro para lançar aula em nome de outra pessoa.
  ---------------------------------------------------------------------------
  if v_teacher_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  select public._my_role(), public._my_tenant_id()
    into v_role, v_tenant;

  if not coalesce(v_role in ('TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN'), false)
     or v_tenant is null then
    raise exception using errcode = '42501', message = 'teacher_profile_required';
  end if;

  select p.id, v_tenant as tenant_id, v_role as role
    into v_profile
    from public.profiles p
   where p.id = v_teacher_id;

  if not found
     or v_profile.tenant_id is null then
    raise exception using errcode = '42501', message = 'teacher_profile_required';
  end if;

  if p_entries is null or pg_catalog.jsonb_typeof(p_entries) <> 'array' then
    raise exception using errcode = '22023', message = 'invalid_entries';
  end if;

  v_count := pg_catalog.jsonb_array_length(p_entries);
  if v_count < 1 or v_count > 100 then
    raise exception using errcode = '22023', message = 'invalid_entries_length';
  end if;

  ---------------------------------------------------------------------------
  -- 2. Uma entrada por vez. Nada aqui aborta o lote: entrada inválida ou já
  --    lançada vira `skipped` com motivo, e o resto do lote grava normalmente.
  --    (Antes, um 23505 no meio derrubava o insert inteiro e o professor
  --    relançava tudo na mão.)
  ---------------------------------------------------------------------------
  for v_entry in select value from pg_catalog.jsonb_array_elements(p_entries)
  loop
    v_ref := nullif(pg_catalog.btrim(coalesce(v_entry ->> 'ref', '')), '');
    v_booking_id := nullif(pg_catalog.btrim(coalesce(v_entry ->> 'booking_id', '')), '');
    v_reschedule_id := nullif(pg_catalog.btrim(coalesce(v_entry ->> 'reschedule_id', '')), '');
    v_appointment_id := nullif(pg_catalog.btrim(coalesce(v_entry ->> 'appointment_id', '')), '');
    v_presence := pg_catalog.btrim(coalesce(v_entry ->> 'presence', 'COMPLETED'));
    v_skip_reason := null;
    v_new_id := null;
    v_student_id := null;
    v_class_date := null;
    v_kind := null;
    v_subtype := null;
    v_fault_origin := null;
    v_appt_type := null;
    v_occurrence_time := null;
    v_confirmation_time := null;
    v_source_date := null;
    v_slot_day := null;
    v_constraint_name := null;

    -- student_id / class_date com validação de formato (entrada do navegador)
    begin
      v_student_id := nullif(pg_catalog.btrim(coalesce(v_entry ->> 'student_id', '')), '')::uuid;
    exception when others then
      v_student_id := null;
    end;

    begin
      v_class_date := (v_entry ->> 'class_date')::date;
    exception when others then
      v_class_date := null;
    end;

    if v_class_date is null then
      v_skip_reason := 'data_invalida';
    elsif v_class_date > (pg_catalog.now() at time zone 'America/Sao_Paulo')::date then
      -- aula no futuro nunca aconteceu: bloquear é mais barato que estornar
      v_skip_reason := 'aula_no_futuro';
    elsif v_class_date < ((pg_catalog.now() at time zone 'America/Sao_Paulo')::date - 120) then
      v_skip_reason := 'fora_da_janela';
    elsif v_presence not in ('COMPLETED', 'STUDENT_ABSENCE', 'TEACHER_ABSENCE', 'Falta Justificada') then
      v_skip_reason := 'presenca_invalida';
    elsif v_booking_id is null and v_reschedule_id is null and v_appointment_id is null then
      v_skip_reason := 'sem_origem';
    elsif pg_catalog.num_nonnulls(
      v_booking_id, v_reschedule_id, v_appointment_id
    ) <> 1 then
      v_skip_reason := 'origem_ambigua';
    end if;

    -----------------------------------------------------------------------
    -- 2a. A ORIGEM é deduzida do banco, não do que o cliente diz que é.
    -----------------------------------------------------------------------
    if v_skip_reason is null then
      if v_reschedule_id is not null then
        v_kind := 'REPOSICAO';

        select
          r.fault_type,
          r.student_id,
          case
            when pg_catalog.btrim(r.time) ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
            then pg_catalog.left(pg_catalog.btrim(r.time), 5)::time
          end
          into v_fault_origin, v_student_id, v_occurrence_time
          from public.reschedules r
         where r.id::text = v_reschedule_id
           and r.teacher_id = v_teacher_id
           and r.tenant_id = v_profile.tenant_id
           and r.used_at is null
           and public.parse_lesson_date(r.date) = v_class_date
           and pg_catalog.btrim(r.time)
               ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
         for update of r;

        if not found then
          v_skip_reason := 'reposicao_inexistente';
        else
          -- Lifecycle e integridade sao resolvidos no banco. Um valor TEACHER
          -- editado sem prova autoritativa nunca pode virar aula paga.
          if not private.reschedule_participants_are_active(
            v_reschedule_id::uuid,
            v_profile.tenant_id,
            v_teacher_id,
            v_student_id
          ) then
            v_skip_reason := 'participante_inativo';
          elsif v_fault_origin is not null
                and v_fault_origin not in ('STUDENT', 'TEACHER') then
            v_skip_reason := 'origem_reposicao_invalida';
          elsif v_fault_origin = 'TEACHER'
                and not private.teacher_reschedule_financial_origin_is_proven(
                  v_reschedule_id::uuid,
                  v_profile.tenant_id,
                  v_teacher_id,
                  v_student_id
                ) then
            v_skip_reason := 'reposicao_professor_sem_origem_comprovada';
          else
            -- Origem nula legada permanece conservadoramente nao paga.
            v_subtype := case
              when v_fault_origin = 'TEACHER' then 'REPOSIÇÃO_PROF'
              else 'REPOSIÇÃO'
            end;
          end if;
        end if;

      elsif v_appointment_id
            ~* '^trial_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      then
        select
          case when pg_catalog.lower(coalesce(o.kind, 'TRIAL')) = 'training'
               then 'training' else 'experimental' end,
          public.parse_lesson_date(slot.value ->> 'date'),
          pg_catalog.left(pg_catalog.btrim(slot.value ->> 'time'), 5)::time,
          case
            when pg_catalog.btrim(coalesce(slot.value ->> 'day', '')) ~ '^[0-6]$'
              then pg_catalog.btrim(slot.value ->> 'day')::int
            else public.dow_name_to_int(slot.value ->> 'day')
          end
          into v_appt_type, v_source_date, v_occurrence_time, v_slot_day
          from public.opportunities o
          cross join lateral (
            select item.value
              from pg_catalog.jsonb_array_elements(
                case when pg_catalog.jsonb_typeof(o.slots_proposed) = 'array'
                     then o.slots_proposed else '[]'::jsonb end
              ) with ordinality as item(value, position)
             where pg_catalog.btrim(item.value ->> 'time')
                   ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
             order by item.position
             limit 1
          ) slot
         where o.id = pg_catalog.substr(v_appointment_id, 7)::uuid
           and o.tenant_id = v_profile.tenant_id
           and o.winner_teacher_id = v_teacher_id
           and o.status = 'CLAIMED'
           and o.trial_status = 'DONE'
           and o.trial_appointment_id is null;

        if not found
           or v_presence <> 'COMPLETED'
           or (
             v_source_date is not null
             and v_source_date <> v_class_date
           )
           or (
             v_source_date is null
             and (
               v_slot_day is null
               or v_slot_day <> extract(dow from v_class_date)::int
             )
           )
        then
          v_skip_reason := 'agendamento_sintetico_invalido';
        elsif v_appt_type = 'training' then
          v_kind := 'TRAINING';
          v_subtype := 'TREINAMENTO';
        else
          v_kind := 'TRIAL';
          v_subtype := 'AULA EXPERIMENTAL';
        end if;
        v_student_id := null;

      elsif v_appointment_id is not null then
        select
          pg_catalog.lower(coalesce(a.type, 'experimental')),
          (a.start_time at time zone 'America/Sao_Paulo')::time
          into v_appt_type, v_occurrence_time
          from public.appointments a
         where a.id::text = v_appointment_id
           and a.tenant_id = v_profile.tenant_id
           and (a.start_time at time zone 'America/Sao_Paulo')::date = v_class_date
           and pg_catalog.lower(coalesce(a.status, '')) in ('scheduled', 'completed')
           and pg_catalog.lower(coalesce(a.type, '')) in ('experimental', 'training')
           and (
             coalesce(a.teacher_id, a.professor_id) = v_teacher_id
             or exists (
               select 1
                 from public.opportunities o
                where o.trial_appointment_id = a.id
                  and o.tenant_id = v_profile.tenant_id
                  and o.winner_teacher_id = v_teacher_id
             )
           );

        if not found then
          v_skip_reason := 'agendamento_inexistente';
        elsif v_presence <> 'COMPLETED' then
          v_skip_reason := 'presenca_invalida_para_agendamento';
        elsif v_appt_type = 'training' then
          v_kind := 'TRAINING';
          v_subtype := 'TREINAMENTO';
        else
          v_kind := 'TRIAL';
          v_subtype := 'AULA EXPERIMENTAL';
        end if;
        v_student_id := null; -- experimental/treino é lead, não aluno matriculado

      else
        v_kind := 'REGULAR';

        -- COBERTURA: quem lança é quem DEU a aula, não necessariamente o dono do
        -- agendamento. Aula assumida (`class_coverages.cover_teacher_id`) usa o
        -- booking do professor original — validar só por `b.teacher_id` recusaria
        -- o lançamento de quem realmente trabalhou.
        select
          b.student_id,
          case
            when pg_catalog.btrim(b.time_slot) ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
            then pg_catalog.left(pg_catalog.btrim(b.time_slot), 5)::time
          end
          into v_student_id, v_occurrence_time
          from public.bookings b
         where b.id::text = v_booking_id
           and b.tenant_id = v_profile.tenant_id
           and b.status = 'SCHEDULED'
           and b.start_date is not null
           and b.start_date <= v_class_date
           and public.dow_name_to_int(b.day_of_week)
               = extract(dow from v_class_date)::int
           and pg_catalog.btrim(b.time_slot)
               ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
           and (
             (
               b.teacher_id = v_teacher_id
               and not exists (
                 select 1
                   from public.class_coverages c
                  where c.booking_id = b.id
                    and c.tenant_id = v_profile.tenant_id
                    and c.class_date = v_class_date
                    and c.status = 'confirmed'
                    and c.cover_teacher_id is distinct from v_teacher_id
               )
             )
             or exists (
               select 1
                 from public.class_coverages c
                where c.booking_id = b.id
                  and c.tenant_id = v_profile.tenant_id
                  and c.class_date = v_class_date
                  and c.status = 'confirmed'
                  and c.cover_teacher_id = v_teacher_id
             )
           );

        if not found then
          v_skip_reason := 'agendamento_inexistente';

        -- E o inverso: quem CEDEU a aula não pode lançá-la. A tela já esconde,
        -- mas a trava do dinheiro tem de estar no servidor — lançar aula cedida
        -- pagaria dois professores pela mesma hora.
        elsif exists (
          select 1
            from public.class_coverages c
           where c.booking_id::text = v_booking_id
             and c.tenant_id = v_profile.tenant_id
             and c.class_date = v_class_date
             and c.status = 'confirmed'
             and c.original_teacher_id = v_teacher_id
             and c.cover_teacher_id is distinct from v_teacher_id
        ) then
          v_skip_reason := 'aula_cedida_para_outro_professor';

        else
          -- Motivo da falta (Doença/Trabalho/Viagem/Outros) só quando houve falta.
          v_subtype := case
            when v_presence = 'COMPLETED' then null
            else nullif(pg_catalog.btrim(coalesce(v_entry ->> 'absence_reason', '')), '')
          end;
        end if;
      end if;
    end if;

    -- Se houve confirmacao enviada ao aluno, seu horario e o snapshot
    -- historico autoritativo; a consulta so roda depois que a origem real foi
    -- validada no tenant/data/professor acima.
    if v_skip_reason is null then
      select pg_catalog.left(pg_catalog.btrim(ac.class_time), 5)::time
        into v_confirmation_time
        from public.attendance_confirmations ac
       where ac.tenant_id = v_profile.tenant_id
         and ac.class_date = v_class_date
         and ac.teacher_id = v_teacher_id
         and ac.student_id is not distinct from v_student_id
         and pg_catalog.btrim(ac.class_time)
             ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
         and (
           (ac.source_type = 'booking' and ac.source_id = v_booking_id)
           or (ac.source_type = 'reschedule' and ac.source_id = v_reschedule_id)
           or (ac.source_type = 'appointment' and ac.source_id = v_appointment_id)
         )
       order by ac.created_at desc, ac.id desc
       limit 1;

      if found then
        v_occurrence_time := v_confirmation_time;
      end if;
    end if;

    if v_skip_reason is null and v_occurrence_time is null then
      v_skip_reason := 'horario_da_ocorrencia_invalido';
    end if;

    -----------------------------------------------------------------------
    -- 2b. Anti-duplicata NO SERVIDOR. O guard antigo vivia no navegador e era
    --     fail-open: numa queda de rede ele liberava tudo.
    --     A identidade e tenant + professor + aluno + data + horario. Isso barra
    --     a origem recriada/cruzada sem impedir 16:30 e 17:00 no mesmo dia.
    -----------------------------------------------------------------------
    if v_skip_reason is null then
      if v_kind = 'REGULAR' and exists (
        select 1 from public.class_logs cl
         where cl.tenant_id = v_profile.tenant_id
           and cl.booking_id = v_booking_id
           and cl.class_date = v_class_date
      ) then
        v_skip_reason := 'ja_lancada';

      elsif v_kind = 'REPOSICAO' and exists (
        select 1 from public.class_logs cl
         where cl.tenant_id = v_profile.tenant_id
           and cl.reschedule_id = v_reschedule_id
      ) then
        v_skip_reason := 'ja_lancada';

      elsif v_student_id is not null and exists (
        select 1 from public.class_logs cl
         where cl.tenant_id = v_profile.tenant_id
           and cl.teacher_id = v_teacher_id
           and cl.student_id = v_student_id
           and cl.class_date = v_class_date
           and cl.start_time = v_occurrence_time
      ) then
        v_skip_reason := 'ocorrencia_ja_lancada';

      elsif v_kind in ('TRIAL', 'TRAINING') and exists (
        select 1 from public.class_logs cl
         where cl.tenant_id = v_profile.tenant_id
           and cl.appointment_id = v_appointment_id
      ) then
        v_skip_reason := 'ja_lancada';
      end if;
    end if;

    -----------------------------------------------------------------------
    -- 2c. Grava.
    -----------------------------------------------------------------------
    if v_skip_reason is null then
      begin
        insert into public.class_logs (
          tenant_id, teacher_id, student_id,
          booking_id, reschedule_id, appointment_id,
          presence, subtype,
          content_covered, content, observations,
          assessment_level, psychological_profile, teacher_verdict,
          date, class_date, start_time, created_at
        ) values (
          v_profile.tenant_id, v_teacher_id, v_student_id,
          case when v_kind = 'REGULAR' then v_booking_id else null end,
          case when v_kind = 'REPOSICAO' then v_reschedule_id else null end,
          case when v_kind in ('TRIAL', 'TRAINING') then v_appointment_id else null end,
          v_presence, v_subtype,
          nullif(pg_catalog.btrim(coalesce(v_entry ->> 'content_covered', '')), ''),
          nullif(pg_catalog.btrim(coalesce(v_entry ->> 'content_covered', '')), ''),
          nullif(pg_catalog.btrim(coalesce(v_entry ->> 'observations', '')), ''),
          case when v_kind = 'TRIAL' then nullif(pg_catalog.btrim(coalesce(v_entry ->> 'assessment_level', '')), '') end,
          case when v_kind = 'TRIAL' then nullif(pg_catalog.btrim(coalesce(v_entry ->> 'psychological_profile', '')), '') end,
          case when v_kind = 'TRIAL' then nullif(pg_catalog.btrim(coalesce(v_entry ->> 'teacher_verdict', '')), '') end,
          v_class_date, v_class_date, v_occurrence_time, pg_catalog.now()
        )
        returning id into v_new_id;
      exception when unique_violation then
        get stacked diagnostics v_constraint_name = constraint_name;
        if v_constraint_name = any (array[
          'uq_class_logs_student_occurrence',
          'uq_class_logs_booking_date',
          'unique_class_log_per_booking_date',
          'uq_class_logs_reschedule_id',
          'unique_class_log_per_reschedule',
          'uq_class_logs_appointment'
        ]::text[]) then
          v_skip_reason := 'ja_lancada';
          v_new_id := null;
        else
          raise;
        end if;
      end;
    end if;

    if v_skip_reason is null then
      v_inserted := v_inserted + 1;
      v_inserted_ids := pg_catalog.array_append(v_inserted_ids, v_new_id);

      ---------------------------------------------------------------------
      -- 2d. Consome a reposição — MARCA `used_at`, não apaga.
      --     Apagar destruía a prova de quem faltou (`reschedules.fault_type`),
      --     e é ela que decide se a reposição paga. Com a linha apagada, 12 dos
      --     13 class_logs ficaram apontando para nada e a regra nunca disparou
      --     (diagnóstico do commit 0bd4053). A lista de pendentes já filtra por
      --     "existe class_log apontando para esta reposição?", então a linha
      --     consumida não reaparece para lançar.
      ---------------------------------------------------------------------
      if v_kind = 'REPOSICAO' then
        update public.reschedules r
           set used_at = pg_catalog.now()
         where r.id::text = v_reschedule_id
           and r.teacher_id = v_teacher_id
           and r.tenant_id = v_profile.tenant_id
           and r.used_at is null;
      end if;

      ---------------------------------------------------------------------
      -- 2e. Falta gera reposição — e a ORIGEM fica gravada, que é o que
      --     permite pagar a reposição do professor lá na frente.
      --     Falta do professor: ilimitada (é o único caminho dele receber).
      --     Falta do aluno: 5 por mês.
      ---------------------------------------------------------------------
      if v_presence in ('TEACHER_ABSENCE', 'STUDENT_ABSENCE', 'Falta Justificada')
         and v_student_id is not null
         and coalesce(v_subtype, '') not in ('REPOSIÇÃO', 'REPOSIÇÃO_PROF')
      then
        if v_presence = 'TEACHER_ABSENCE' then
          insert into public.reschedules (
            tenant_id, teacher_id, student_id, original_booking_id,
            date, time, fault_type, created_at
          ) values (
            v_profile.tenant_id, v_teacher_id, v_student_id,
            case when v_kind = 'REGULAR' then v_booking_id::uuid else null end,
            'Pendente', 'Pendente', 'TEACHER', pg_catalog.now()
          );
          v_reschedules_created := v_reschedules_created + 1;
        else
          select count(*)::int
            into v_student_absence_count
            from public.reschedules r
           where r.student_id = v_student_id
             and r.tenant_id = v_profile.tenant_id
             and r.fault_type = 'STUDENT'
             and r.created_at >= pg_catalog.date_trunc('month', pg_catalog.now());

          if v_student_absence_count < 5 then
            insert into public.reschedules (
              tenant_id, teacher_id, student_id, original_booking_id,
              date, time, fault_type, created_at
            ) values (
              v_profile.tenant_id, v_teacher_id, v_student_id,
              case when v_kind = 'REGULAR' then v_booking_id::uuid else null end,
              'Pendente', 'Pendente', 'STUDENT', pg_catalog.now()
            );
            v_reschedules_created := v_reschedules_created + 1;
          end if;
        end if;
      end if;

      ---------------------------------------------------------------------
      -- 2f. Experimental lançada move o lead no CRM.
      ---------------------------------------------------------------------
      if v_kind = 'TRIAL' then
        update public.crm_leads l
           set status = 'TRIAL_DONE'
         where l.tenant_id = v_profile.tenant_id
           and l.phone is not null
           and l.phone in (
             select a.student_phone from public.appointments a
              where a.id::text = v_appointment_id
                and a.tenant_id = v_profile.tenant_id
                and a.student_phone is not null
           );
      end if;

    else
      v_skipped := v_skipped + 1;
    end if;

    v_results := v_results || pg_catalog.jsonb_build_object(
      'ref', v_ref,
      'id', v_new_id,
      'status', case when v_skip_reason is null then 'lancada' else 'ignorada' end,
      'reason', v_skip_reason,
      'kind', v_kind,
      'subtype', v_subtype
    );
  end loop;

  ---------------------------------------------------------------------------
  -- 3. Quanto isso virou de caixa — pela MESMA fonte que paga o professor
  --    (`v_payable_class_logs`). Nada de `aulas × tarifa` estimado: o valor por
  --    aula muda conforme a posição de antiguidade do aluno na carteira e o
  --    estado do turbo. Estimar aqui reproduziria exatamente a divergência que
  --    já gerou contestação em série no painel Financeiro.
  ---------------------------------------------------------------------------
  if pg_catalog.array_length(v_inserted_ids, 1) > 0 then
    select coalesce(sum(v.rate_efetivo), 0), count(*)::int
      into v_delta_amount, v_delta_lessons
      from public.v_payable_class_logs v
     where v.id = any(v_inserted_ids);

    -- Cada aula lançada recebe seu valor real (0 quando não entra na folha) e o
    -- motivo — é o que deixa a tela dizer a verdade em vez de fingir festa.
    select pg_catalog.jsonb_agg(
             r || pg_catalog.jsonb_build_object(
               'amount', coalesce(pay.rate_efetivo, 0),
               'paid', pay.id is not null,
               'unpaid_reason', case
                 when pay.id is not null then null
                 when r ->> 'id' is null then null
                 when cl.presence in ('TEACHER_ABSENCE', 'Falta do Professor') then 'falta_professor'
                 when cl.subtype = 'REPOSIÇÃO' then 'reposicao_falta_aluno'
                 when cl.subtype = 'Teste Oral' then 'teste_oral'
                 when coalesce(cl.payment_hold, false) then 'em_conferencia'
                 when cl.student_id is not null
                      and not public.is_billable_student(cl.student_id) then 'aluno_nao_faturavel'
                 else 'fora_da_folha'
               end
             )
           )
      into v_results
      from pg_catalog.jsonb_array_elements(v_results) r
      left join public.class_logs cl on cl.id::text = (r ->> 'id')
      left join public.v_payable_class_logs pay on pay.id::text = (r ->> 'id');
  end if;

  v_projection := public.teacher_pay_projection(v_teacher_id);

  return pg_catalog.jsonb_build_object(
    'inserted', v_inserted,
    'skipped', v_skipped,
    'reschedules_created', v_reschedules_created,
    'delta_amount', v_delta_amount,
    'delta_lessons', v_delta_lessons,
    'month_amount', coalesce((v_projection ->> 'amount_logged')::numeric, 0),
    'month_lessons', coalesce((v_projection ->> 'lessons_logged')::int, 0),
    'turbo_active', coalesce((v_projection -> 'turbo' ->> 'active')::boolean, false),
    'entries', coalesce(v_results, '[]'::jsonb)
  );
end;
$_$;


--
-- Name: FUNCTION log_teacher_classes(p_entries jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.log_teacher_classes(p_entries jsonb) IS 'Lanca aulas em lote e classifica reposicao paga somente quando a origem TEACHER possui prova autoritativa e os participantes seguem ativos.';


--
-- Name: manage_sdr_attention(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manage_sdr_attention(p_tenant_id text, p_lead_id uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare l public.crm_leads%rowtype; a private.sdr_attention_assignments%rowtype;
begin
  if not private.can_manage_sdr(p_tenant_id) then raise exception 'forbidden' using errcode='42501'; end if;
  if p_action not in ('take','release') then raise exception 'invalid_action'; end if;
  select * into l from public.crm_leads where tenant_id=p_tenant_id and id=p_lead_id;
  if not found then raise exception 'lead_not_found'; end if;
  -- Same lock order as the worker: conversation first, lead second.
  if nullif(regexp_replace(l.phone,'[^0-9]','','g'),'') is not null then
    insert into public.sdr_conversation_work(tenant_id,phone,payload,latest_msg_id,completed_msg_id)
      values(l.tenant_id,regexp_replace(l.phone,'[^0-9]','','g'),'{}','','') on conflict do nothing;
  end if;
  perform 1 from public.sdr_conversation_work w where w.tenant_id=l.tenant_id
    and w.phone=regexp_replace(l.phone,'[^0-9]','','g') for update;
  select * into l from public.crm_leads where tenant_id=p_tenant_id and id=p_lead_id for update;
  if not found then raise exception 'lead_not_found'; end if;
  select * into a from private.sdr_attention_assignments where lead_id=l.id;
  if a.resolved_at is null and a.owner_id is not null and a.owner_id<>auth.uid() and a.assigned_at>now()-interval '72 hours' then
    return jsonb_build_object('ok',false,'error','already_assigned');
  end if;
  if p_action='take' then
    if exists(select 1 from public.sdr_conversation_work w where w.tenant_id=l.tenant_id
      and w.phone=regexp_replace(l.phone,'[^0-9]','','g') and w.phase='APPLYING' and w.lease_until>now()) then
      return jsonb_build_object('ok',false,'error','send_in_progress');
    end if;
    update public.sdr_conversation_work set phase='IDLE',lease_token=null,lease_until=null
      where tenant_id=l.tenant_id and phone=regexp_replace(l.phone,'[^0-9]','','g') and phase='GENERATING';
    insert into private.sdr_attention_assignments(lead_id,tenant_id,owner_id,assigned_at)
    values(l.id,l.tenant_id,auth.uid(),now()) on conflict(lead_id)
    do update set owner_id=excluded.owner_id,assigned_at=excluded.assigned_at,resolved_at=null;
    update public.crm_leads set ai_handoff=true,ai_handoff_at=now() where id=l.id;
  else
    if a.owner_id is null or a.resolved_at is not null then return jsonb_build_object('ok',false,'error','take_first'); end if;
    perform 1 from public.sdr_conversation_work w where w.tenant_id=l.tenant_id
      and w.phone=regexp_replace(l.phone,'[^0-9]','','g') for update;
    if exists(select 1 from public.sdr_conversation_work w where w.tenant_id=l.tenant_id
      and w.phone=regexp_replace(l.phone,'[^0-9]','','g') and w.lease_until>now()) then
      return jsonb_build_object('ok',false,'error','send_in_progress');
    end if;
    update public.sdr_conversation_work set phase='IDLE',completed_msg_id=latest_msg_id,
      claimed_msg_id=latest_msg_id,lease_token=null,lease_until=null,attempts=0,updated_at=now()
      where tenant_id=l.tenant_id and phone=regexp_replace(l.phone,'[^0-9]','','g');
    update public.crm_leads set ai_handoff=false,ai_handoff_at=null where id=l.id;
    update private.sdr_attention_assignments set resolved_at=now() where lead_id=l.id;
  end if;
  return jsonb_build_object('ok',true);
end;
$$;


--
-- Name: management_payment_confirmation_pending(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.management_payment_confirmation_pending() RETURNS TABLE(payment_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select payment.id
    from public.student_payments as payment
    join public.profiles as student
      on student.id = payment.student_id
     and student.tenant_id = payment.tenant_id
     and student.role = 'STUDENT'
     and coalesce(student.is_test_account, false) is false
     and student.test_fixture_key is null
    join public.dre_report_settings as setting
      on setting.tenant_id = payment.tenant_id
     and setting.is_active
   where payment.status = 'CONFIRMED'
     and coalesce(payment.value, 0) > 0
     and payment.updated_at >= pg_catalog.now() - interval '7 days'
     and not exists (
       select 1
         from public.management_group_message_attempts as attempt
        where attempt.tenant_id = payment.tenant_id
          and attempt.notification_kind = 'PAYMENT_CONFIRMED'
          and attempt.subject_id = payment.id::text
          and attempt.ref_date = coalesce(payment.due_date, payment.created_at::date)
     )
   order by payment.updated_at, payment.id
   limit 30;
$$;


--
-- Name: management_payment_notification_attention(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.management_payment_notification_attention(p_limit integer DEFAULT 100) RETURNS TABLE(attempt_id uuid, tenant_id text, payment_id uuid, notification_kind text, status text, submit_attempt_count integer, provider_message_id text, provider_delivery_status text, updated_at timestamp with time zone, last_error text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    outbox.id,
    outbox.tenant_id,
    outbox.payment_id,
    outbox.notification_kind,
    outbox.status,
    outbox.submit_attempt_count,
    outbox.provider_message_id,
    outbox.provider_delivery_status,
    outbox.updated_at,
    outbox.last_error
  from public.management_payment_notification_outbox as outbox
  where outbox.status in ('SUBMITTING', 'FAILED', 'UNKNOWN')
  order by outbox.updated_at, outbox.id
  limit greatest(1, least(coalesce(p_limit, 100), 500))
$$;


--
-- Name: FUNCTION management_payment_notification_attention(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.management_payment_notification_attention(p_limit integer) IS 'Service-only attention queue for SUBMITTING, FAILED and UNKNOWN management payment deliveries.';


--
-- Name: management_payment_notification_pending(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.management_payment_notification_pending(p_limit integer DEFAULT 50) RETURNS TABLE(payment_id uuid, tenant_id text, notification_kind text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    outbox.payment_id,
    outbox.tenant_id,
    outbox.notification_kind
  from public.management_payment_notification_outbox as outbox
  where outbox.submit_attempt_count = 0
    and (
      outbox.status = 'PENDING'
      or (
        outbox.status in ('CLAIMED', 'PREPARED')
        and outbox.lease_expires_at <= pg_catalog.now()
      )
    )
  order by outbox.created_at, outbox.id
  limit greatest(1, least(coalesce(p_limit, 50), 200))
$$;


--
-- Name: FUNCTION management_payment_notification_pending(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.management_payment_notification_pending(p_limit integer) IS 'Unlimited-age sweep of durable pending settlement notifications; terminal or ambiguous attempts are never retried.';


--
-- Name: management_payment_notification_source_snapshot(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.management_payment_notification_source_snapshot(p_tenant_id text, p_payment_id uuid, p_notification_kind text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_kind text := upper(pg_catalog.btrim(coalesce(p_notification_kind, '')));
  v_snapshot jsonb;
begin
  if nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '') is null
     or p_payment_id is null
     or v_kind not in ('PAYMENT_SPLIT', 'PAYMENT_RECEIVED') then
    raise exception 'invalid_management_payment_notification_source'
      using errcode = '22023';
  end if;

  if v_kind = 'PAYMENT_SPLIT' then
    select public.payment_split_breakdown(p_payment_id)
    into v_snapshot;

    if pg_catalog.jsonb_typeof(v_snapshot) <> 'object'
       or v_snapshot ? 'error'
       or v_snapshot ->> 'tenant_id' is distinct from p_tenant_id then
      return null;
    end if;

    return v_snapshot || pg_catalog.jsonb_build_object(
      'is_test_fixture',
      private.management_payment_is_test_fixture(p_tenant_id, p_payment_id)
    );
  end if;

  select pg_catalog.jsonb_build_object(
    'payment_id', payment.id,
    'tenant_id', payment.tenant_id,
    'student_id', payment.student_id,
    'student_name', coalesce(
      nullif(pg_catalog.btrim(coalesce(student.full_name, '')), ''),
      'sem aluno vinculado'
    ),
    'value', payment.value,
    'status', upper(pg_catalog.btrim(coalesce(payment.status, ''))),
    'billing_type', payment.billing_type,
    'due_date', payment.due_date,
    'payment_date', payment.payment_date,
    'paid_at', payment.paid_at,
    'credited_at', payment.credited_at,
    'created_at', payment.created_at,
    'is_test_fixture', private.management_payment_is_test_fixture(
      payment.tenant_id,
      payment.id
    )
  )
  into v_snapshot
  from public.student_payments as payment
  left join public.profiles as student
    on student.id = payment.student_id
    and student.tenant_id = payment.tenant_id
  where payment.id = p_payment_id
    and payment.tenant_id = p_tenant_id;

  return v_snapshot;
end;
$$;


--
-- Name: mark_asaas_outbound_message_submitting(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_asaas_outbound_message_submitting(p_attempt_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.asaas_outbound_message_attempts%rowtype;
  lifecycle_blocked boolean;
  payment_notification_invalid boolean := false;
  communication_disabled boolean := false;
  source_payment_status text;
begin
  -- Read immutable scope first, then take the advisory lock, then lock/re-read
  -- the row. This keeps lock ordering aligned with begin_* and avoids a
  -- row-lock/advisory-lock deadlock.
  select message_attempt.* into attempt_row
    from public.asaas_outbound_message_attempts as message_attempt
   where message_attempt.id = p_attempt_id;
  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || attempt_row.tenant_id || ':' || attempt_row.student_id::text,
      0
    )
  );

  select message_attempt.* into attempt_row
    from public.asaas_outbound_message_attempts as message_attempt
   where message_attempt.id = p_attempt_id
   for update;
  if not found or attempt_row.status <> 'CLAIMED'
     or attempt_row.claim_token is distinct from p_claim_token
     or attempt_row.lease_expires_at <= now()
     or attempt_row.submit_attempt_count <> 0
  then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  lifecycle_blocked := not exists (
    select 1 from public.profiles as profile
     where profile.id = attempt_row.student_id
       and profile.tenant_id = attempt_row.tenant_id
       and profile.role = 'STUDENT'
       and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) = 'active'
  ) or (
    select count(*) from public.tenant_memberships as membership
     where membership.user_id = attempt_row.student_id
  ) <> 1 or not exists (
    select 1 from public.tenant_memberships as membership
     where membership.user_id = attempt_row.student_id
       and membership.tenant_id = attempt_row.tenant_id
       and membership.role = 'STUDENT'
       and membership.status = 'ACTIVE'
  ) or exists (
    select 1 from public.student_offboarding_operations as operation
     where operation.tenant_id = attempt_row.tenant_id
       and operation.student_id = attempt_row.student_id
       and operation.status in (
         'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED'
       )
  ) or exists (
    select 1 from public.student_account_deletion_claims as deletion
     where deletion.tenant_id = attempt_row.tenant_id
       and deletion.student_id = attempt_row.student_id
       and deletion.status in (
         'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED'
       )
  );

  if attempt_row.notification_kind in (
    'PAYMENT_CONFIRMED_CAPI', 'PAYMENT_CONFIRMED_WHATSAPP',
    'PAYMENT_DUE_REMINDER', 'PAYMENT_OVERDUE_3',
    'PAYMENT_OVERDUE_10', 'PAYMENT_OVERDUE_20'
  ) then
    select upper(pg_catalog.btrim(coalesce(payment.status, '')))
      into source_payment_status
      from public.student_payments as payment
     where payment.id::text = attempt_row.provider_entity_id
       and payment.tenant_id = attempt_row.tenant_id
       and payment.student_id = attempt_row.student_id
     for update;
    payment_notification_invalid := not found
      or case
        when attempt_row.notification_kind in (
          'PAYMENT_CONFIRMED_CAPI', 'PAYMENT_CONFIRMED_WHATSAPP'
        ) then source_payment_status not in ('RECEIVED', 'RECEIVED_IN_CASH', 'PAGO')
        when attempt_row.notification_kind = 'PAYMENT_DUE_REMINDER'
          then source_payment_status <> 'PENDING'
        else source_payment_status not in ('PENDING', 'OVERDUE')
      end;
  end if;

  if attempt_row.notification_kind in (
    'MANUAL_PIX_CREATED', 'PAYMENT_CONFIRMED_WHATSAPP',
    'PAYMENT_DUE_REMINDER', 'PAYMENT_OVERDUE_3',
    'PAYMENT_OVERDUE_10', 'PAYMENT_OVERDUE_20'
  ) then
    communication_disabled := true;
    select not (
      coalesce(tenant.whatsapp_enabled, false)
      and coalesce(settings.student_notifications_enabled, false)
    )
      into communication_disabled
      from public.tenants as tenant
      left join public.tenant_admin_settings as settings
        on settings.tenant_id = tenant.id
     where tenant.id = attempt_row.tenant_id;
  end if;

  if lifecycle_blocked or payment_notification_invalid
     or communication_disabled
  then
    update public.asaas_outbound_message_attempts
       set status = 'SUPPRESSED',
           lease_expires_at = now(),
           last_error = case
             when lifecycle_blocked then 'student_lifecycle_inactive_before_send'
             when payment_notification_invalid
               then 'payment_state_changed_before_notification_send'
             else 'student_notifications_disabled_before_send'
           end,
           updated_at = now()
     where id = attempt_row.id
       and status = 'CLAIMED'
       and submit_attempt_count = 0;
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'SUPPRESSED',
      'status', 'SUPPRESSED', 'reason', case
        when lifecycle_blocked then 'student_lifecycle_inactive'
        when payment_notification_invalid
          then 'payment_state_changed_before_notification_send'
        else 'student_notifications_disabled_before_send'
      end
    );
  end if;

  update public.asaas_outbound_message_attempts
     set status = 'SUBMITTING', submit_attempt_count = 1,
         lease_expires_at = now() + interval '10 minutes', updated_at = now()
   where id = attempt_row.id;
  return pg_catalog.jsonb_build_object('ok', true, 'status', 'SUBMITTING');
end;
$$;


--
-- Name: mark_asaas_payment_split_message_submitting(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_asaas_payment_split_message_submitting(p_attempt_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.asaas_payment_split_message_attempts%rowtype;
  payment_valid boolean := false;
begin
  select attempt.* into attempt_row
    from public.asaas_payment_split_message_attempts as attempt
   where attempt.id = p_attempt_id;
  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'payment-split-message:' || attempt_row.tenant_id || ':' || attempt_row.payment_id::text,
      0
    )
  );

  perform 1
    from public.student_payments as payment
   where payment.id = attempt_row.payment_id
     and payment.tenant_id = attempt_row.tenant_id
     and upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
       'RECEIVED', 'RECEIVED_IN_CASH'
     )
     and coalesce(payment.value, 0) > 0
   for update;
  payment_valid := found;

  select attempt.* into attempt_row
    from public.asaas_payment_split_message_attempts as attempt
   where attempt.id = p_attempt_id
   for update;
  if not found
     or attempt_row.status <> 'CLAIMED'
     or attempt_row.claim_token is distinct from p_claim_token
     or attempt_row.lease_expires_at <= pg_catalog.now()
     or attempt_row.submit_attempt_count <> 0
  then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  if not payment_valid
     or not exists (
       select 1
         from public.payment_split_settings as setting
        where setting.tenant_id = attempt_row.tenant_id
          and setting.is_active
     )
     or not exists (
       select 1
         from public.tenants as tenant
        where tenant.id = attempt_row.tenant_id
          and tenant.whatsapp_enabled is true
          and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) in (
            'active', 'trial', 'trialing'
          )
     )
  then
    update public.asaas_payment_split_message_attempts
       set status = 'SUPPRESSED',
           lease_expires_at = pg_catalog.now(),
           last_error = 'payment_split_scope_or_state_changed_before_send',
           updated_at = pg_catalog.now()
     where id = attempt_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'status', 'SUPPRESSED',
      'reason', 'payment_split_scope_or_state_changed_before_send'
    );
  end if;

  update public.asaas_payment_split_message_attempts
     set status = 'SUBMITTING',
         submit_attempt_count = 1,
         lease_expires_at = pg_catalog.now() + interval '10 minutes',
         updated_at = pg_catalog.now()
   where id = attempt_row.id;
  return pg_catalog.jsonb_build_object('ok', true, 'status', 'SUBMITTING');
end;
$$;


--
-- Name: mark_asaas_provider_creation_submitting(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_asaas_provider_creation_submitting(p_attempt_id uuid, p_claim_token uuid) RETURNS jsonb
