$$;


--
-- Name: mark_financial_report_message_submitting(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_financial_report_message_submitting(p_attempt_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  attempt_row public.financial_report_message_attempts%rowtype;
  monthly_source_locked boolean := true;
begin
  select attempt.* into attempt_row
    from public.financial_report_message_attempts as attempt
   where attempt.id = p_attempt_id;
  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'financial-report-message:' || attempt_row.tenant_id || ':'
        || attempt_row.notification_kind || ':' || attempt_row.subject_id
        || ':' || attempt_row.ref_date::text,
      0
    )
  );

  if attempt_row.notification_kind = 'MONTHLY_CLOSING' then
    perform 1
      from public.teacher_closings as closing
     where closing.tenant_id = attempt_row.tenant_id
       and closing.month_year ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'
       and attempt_row.ref_date::text = closing.month_year || '-01'
       and attempt_row.subject_id = closing.teacher_id::text || ':'
         || closing.month_year || ':' || closing.id::text || ':'
         || coalesce(closing.total_lessons, 0)::bigint::text || ':'
         || pg_catalog.round(
           coalesce(closing.total_amount, 0)::numeric * 100
         )::bigint::text
     for update;
    monthly_source_locked := found;
  end if;

  select attempt.* into attempt_row
    from public.financial_report_message_attempts as attempt
   where attempt.id = p_attempt_id
   for update;
  if not found
     or attempt_row.status <> 'CLAIMED'
     or attempt_row.claim_token is distinct from p_claim_token
     or attempt_row.lease_expires_at <= pg_catalog.now()
     or attempt_row.submit_attempt_count <> 0
  then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  if not monthly_source_locked
     or not private.financial_report_message_exact_scope_active(
    attempt_row.tenant_id,
    attempt_row.notification_kind,
    attempt_row.subject_id,
    attempt_row.ref_date
  ) then
    update public.financial_report_message_attempts
       set status = 'SUPPRESSED',
           lease_expires_at = pg_catalog.now(),
           last_error = 'financial_report_scope_changed_before_send',
           updated_at = pg_catalog.now()
     where id = attempt_row.id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'status', 'SUPPRESSED',
      'reason', 'financial_report_scope_changed_before_send'
    );
  end if;

  update public.financial_report_message_attempts
     set status = 'SUBMITTING',
         submit_attempt_count = 1,
         lease_expires_at = pg_catalog.now() + interval '10 minutes',
         updated_at = pg_catalog.now()
   where id = attempt_row.id;
  return pg_catalog.jsonb_build_object('ok', true, 'status', 'SUBMITTING');
end;
$_$;


--
-- Name: mark_management_group_message_submitting(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_management_group_message_submitting(p_attempt_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.management_group_message_attempts%rowtype;
  source_locked boolean := false;
begin
  select attempt.* into attempt_row
    from public.management_group_message_attempts as attempt
   where attempt.id = p_attempt_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'management-group-message:' || attempt_row.tenant_id || ':' ||
        attempt_row.notification_kind || ':' || attempt_row.subject_id || ':' ||
        attempt_row.ref_date::text,
      0
    )
  );

  if attempt_row.notification_kind = 'PAYMENT_CONFIRMED' then
    perform 1
      from public.student_payments as payment
     where payment.id::text = attempt_row.subject_id
       and payment.tenant_id = attempt_row.tenant_id
     for update;
    source_locked := found;
  elsif attempt_row.notification_kind = 'MONTHLY_PAYMENT_CLOSE' then
    perform 1
      from public.monthly_payment_closures as closure
     where closure.tenant_id = attempt_row.tenant_id
       and closure.period_start = attempt_row.ref_date
     for update;
    source_locked := found;
  end if;

  select attempt.* into attempt_row
    from public.management_group_message_attempts as attempt
   where attempt.id = p_attempt_id
   for update;
  if not found
     or attempt_row.status <> 'CLAIMED'
     or attempt_row.claim_token is distinct from p_claim_token
     or attempt_row.lease_expires_at <= pg_catalog.now()
     or attempt_row.submit_attempt_count <> 0
  then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  if not source_locked
     or not private.management_group_message_exact_scope_active(
       attempt_row.tenant_id,
       attempt_row.notification_kind,
       attempt_row.subject_id,
       attempt_row.ref_date
     )
  then
    update public.management_group_message_attempts
       set status = 'SUPPRESSED',
           lease_expires_at = pg_catalog.now(),
           last_error = 'management_message_scope_changed_before_send',
           updated_at = pg_catalog.now()
     where id = attempt_row.id;
    return jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'status', 'SUPPRESSED',
      'reason', 'management_message_scope_changed_before_send'
    );
  end if;

  update public.management_group_message_attempts
     set status = 'SUBMITTING',
         submit_attempt_count = 1,
         lease_expires_at = pg_catalog.now() + interval '10 minutes',
         updated_at = pg_catalog.now()
   where id = attempt_row.id;
  return jsonb_build_object('ok', true, 'status', 'SUBMITTING');
end;
$$;


--
-- Name: mark_monthly_payment_closure_sent(text, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_monthly_payment_closure_sent(p_tenant_id text, p_period_start date, p_attempt_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  normalized_period date := pg_catalog.date_trunc('month', p_period_start)::date;
begin
  if normalized_tenant is null or p_period_start is null or p_attempt_id is null then
    return false;
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'monthly-payment-closure:' || normalized_tenant || ':' || normalized_period::text,
      0
    )
  );
  if not exists (
    select 1
      from public.management_group_message_attempts as attempt
     where attempt.id = p_attempt_id
       and attempt.tenant_id = normalized_tenant
       and attempt.notification_kind = 'MONTHLY_PAYMENT_CLOSE'
       and attempt.subject_id = normalized_tenant
       and attempt.ref_date = normalized_period
       and attempt.status = 'SENT'
  ) then
    return false;
  end if;
  update public.monthly_payment_closures as closure
     set status = 'SENT',
         sent_at = coalesce(closure.sent_at, pg_catalog.now()),
         sent_attempt_id = p_attempt_id,
         updated_at = pg_catalog.now()
   where closure.tenant_id = normalized_tenant
     and closure.period_start = normalized_period
     and closure.snapshot_hash is not null;
  return found;
end;
$$;


--
-- Name: mark_notification_delivery_submitting(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_notification_delivery_submitting(p_notification_id uuid, p_claim_token uuid, p_provider_instance_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_notification public.notification_queue%rowtype;
  v_instance_name text := pg_catalog.btrim(
    coalesce(p_provider_instance_name, '')
  );
begin
  if p_notification_id is null
     or p_claim_token is null
     or char_length(v_instance_name) not between 3 and 120 then
    raise exception 'invalid_notification_delivery_submission'
      using errcode = '22023';
  end if;

  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id
  for update;

  if not found
     or v_notification.claim_token is distinct from p_claim_token
     or v_notification.status <> 'processing'
     or v_notification.delivery_status <> 'preparing' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'notification_delivery_claim_lost'
    );
  end if;

  if v_notification.lease_expires_at <= now() then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'notification_delivery_claim_expired'
    );
  end if;

  select instance.instance_name
  into v_instance_name
  from public.whatsapp_instances as instance
  where instance.tenant_id = v_notification.tenant_id
    and lower(instance.instance_name) = lower(v_instance_name)
    and lower(pg_catalog.btrim(coalesce(instance.status, '')))
      in ('connected', 'open')
  limit 1;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'notification_provider_instance_unavailable'
    );
  end if;

  update public.notification_queue as notification
  set delivery_status = 'submitting',
      provider_instance_name = v_instance_name,
      lease_expires_at = now() + interval '10 minutes',
      updated_at = now()
  where notification.id = v_notification.id
    and notification.claim_token = p_claim_token
    and notification.status = 'processing'
    and notification.delivery_status = 'preparing'
  returning notification.* into v_notification;

  return pg_catalog.jsonb_build_object(
    'ok', found,
    'notificationId', v_notification.id,
    'status', v_notification.status,
    'deliveryStatus', v_notification.delivery_status,
    'providerInstanceName', v_notification.provider_instance_name,
    'leaseExpiresAt', v_notification.lease_expires_at
  );
end;
$$;


--
-- Name: mark_opportunity_approved(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_opportunity_approved(p_opp_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    UPDATE opportunities SET conversion_status='interested', status='CLAIMED', updated_at=now()
    WHERE id = p_opp_id;
    RETURN jsonb_build_object('status','INTERESTED','opportunity_id',p_opp_id);
END $$;


--
-- Name: mark_opportunity_lost(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_opportunity_lost(p_opp_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    UPDATE opportunities SET conversion_status='lost', lost_reason=p_reason, status='LOST', updated_at=now()
    WHERE id = p_opp_id;
    RETURN jsonb_build_object('status','LOST','opportunity_id',p_opp_id);
END $$;


--
-- Name: mark_opportunity_lost(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_opportunity_lost(p_opportunity_id uuid, p_actor_id uuid, p_reason text DEFAULT 'Não especificado'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_opp RECORD;
BEGIN
    UPDATE public.opportunities SET
        conversion_status = 'LOST',
        lost_reason = p_reason
    WHERE id = p_opportunity_id
      AND conversion_status NOT IN ('WON', 'ENROLLED')
    RETURNING * INTO v_opp;

    IF v_opp IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'CANNOT_MARK_LOST',
            'message', 'Oportunidade já convertida ou não encontrada.');
    END IF;

    -- Audit
    INSERT INTO public.trial_feedback_audit (
        opportunity_id, actor_id, action, after_state
    ) VALUES (
        p_opportunity_id, p_actor_id, 'MARKED_LOST',
        jsonb_build_object('reason', p_reason)
    );

    RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: mark_opportunity_won(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_opportunity_won(p_opportunity_id uuid, p_student_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_opp RECORD;
BEGIN
    UPDATE public.opportunities SET
        conversion_status = 'WON',
        student_id = p_student_id
    WHERE id = p_opportunity_id
      AND conversion_status NOT IN ('WON', 'ENROLLED')
    RETURNING * INTO v_opp;

    IF v_opp IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'CANNOT_MARK_WON',
            'message', 'Oportunidade já convertida ou não encontrada.');
    END IF;

    -- Audit
    INSERT INTO public.trial_feedback_audit (
        opportunity_id, actor_id, action, after_state
    ) VALUES (
        p_opportunity_id, p_actor_id, 'MARKED_WON',
        jsonb_build_object('student_id', p_student_id)
    );

    RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: mark_saas_owner_activation_submitting(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_saas_owner_activation_submitting(p_checkout_id uuid, p_claim_token uuid, p_owner_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.saas_owner_activation_attempts%rowtype;
  checkout_row public.saas_checkout_intents%rowtype;
  checkout_found boolean := false;
  tenant_ready boolean := false;
  owner_access_ready boolean := false;
  calculated_payload_hash text;
begin
  if p_checkout_id is null or p_claim_token is null or p_owner_user_id is null then
    raise exception using
      errcode = '22023', message = 'invalid_saas_owner_activation_submit';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-activation:' || p_checkout_id::text,
      0
    )
  );

  select attempt.* into attempt_row
    from public.saas_owner_activation_attempts as attempt
   where attempt.checkout_id = p_checkout_id
   for update;
  if attempt_row.provider_payload is not null then
    calculated_payload_hash := pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(attempt_row.provider_payload, 'UTF8'),
        'sha256'
      ),
      'hex'
    );
  end if;
  if not found
     or attempt_row.status <> 'CLAIMED'
     or attempt_row.claim_token is distinct from p_claim_token
     or attempt_row.lease_expires_at <= pg_catalog.now()
     or attempt_row.submit_attempt_count not between 0 and 4
     or attempt_row.provider_payload is null
     or attempt_row.owner_user_id is distinct from p_owner_user_id
     or attempt_row.provider_payload_sha256 is distinct from
       calculated_payload_hash
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'action', 'REVIEW_REQUIRED', 'reason', 'activation_claim_lost'
    );
  end if;

  select checkout.* into checkout_row
    from public.saas_checkout_intents as checkout
   where checkout.id = p_checkout_id
   for update;
  checkout_found := found;

  if checkout_found then
    perform 1
      from public.tenants as tenant
     where tenant.id = checkout_row.tenant_id
       and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) = 'active'
     for update;
    tenant_ready := found;

  end if;

  if not checkout_found
     or checkout_row.status not in (
       'PAID', 'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED'
     )
     or checkout_row.tenant_id is distinct from attempt_row.tenant_id
     or lower(pg_catalog.btrim(checkout_row.owner_email))
       is distinct from attempt_row.owner_email
     or not tenant_ready
  then
    if attempt_row.submit_attempt_count = 0 then
      update public.saas_owner_activation_attempts
         set status = 'SUPPRESSED',
             owner_user_id = p_owner_user_id,
             initial_owner_user_id = coalesce(
               initial_owner_user_id,
               p_owner_user_id
             ),
             provider_payload = null,
             provider_payload_sha256 = null,
             provider_payload_staged_at = null,
             lease_expires_at = pg_catalog.now(),
             completed_at = pg_catalog.now(),
             last_error = 'saas_owner_access_not_ready_before_activation',
             updated_at = pg_catalog.now()
       where checkout_id = p_checkout_id;
    else
      -- At least one provider boundary was crossed previously. Preserve the
      -- exact payload and ambiguous audit instead of claiming suppression.
      update public.saas_owner_activation_attempts
         set status = 'UNKNOWN',
             lease_expires_at = pg_catalog.now(),
             completed_at = null,
             last_error = 'saas_owner_access_not_ready_after_delivery',
             updated_at = pg_catalog.now()
       where checkout_id = p_checkout_id;
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', case
        when attempt_row.submit_attempt_count = 0 then 'SUPPRESSED'
        else 'REVIEW_REQUIRED'
      end,
      'reason', 'saas_owner_access_not_ready_before_activation'
    );
  end if;

  owner_access_ready := private.ensure_saas_owner_access_locked(
    p_checkout_id,
    attempt_row.tenant_id,
    attempt_row.owner_email,
    p_owner_user_id,
    true
  );
  if not owner_access_ready then
    update public.saas_owner_activation_attempts
       set lease_expires_at = pg_catalog.now(),
           last_error = 'saas_owner_identity_changed_before_activation',
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id
       and claim_token = p_claim_token
       and status = 'CLAIMED';
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_owner_identity_changed_before_activation'
    );
  end if;

  -- The checkout completion and the irreversible email submit boundary share
  -- the same checkout/tenant locks. A concurrent refund/cancellation either
  -- linearizes before this block and is suppressed above, or after this
  -- authorization without ever being overwritten by application code.
  update public.saas_checkout_intents
     set status = 'PROVISIONED',
         provisioned_at = coalesce(provisioned_at, pg_catalog.now()),
         last_error = null,
         updated_at = pg_catalog.now()
   where id = p_checkout_id
     and status in ('PAID', 'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED')
     and tenant_id = attempt_row.tenant_id
     and lower(pg_catalog.btrim(owner_email)) = attempt_row.owner_email;
  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'saas_checkout_changed_before_activation';
  end if;

  update public.saas_owner_activation_attempts
     set status = 'SUBMITTING',
         submit_attempt_count = submit_attempt_count + 1,
         submitted_at = coalesce(submitted_at, pg_catalog.now()),
         lease_expires_at = pg_catalog.now() + interval '10 minutes',
         updated_at = pg_catalog.now()
   where checkout_id = p_checkout_id
     and claim_token = p_claim_token
     and status = 'CLAIMED'
     and lease_expires_at > pg_catalog.now()
     and owner_user_id = p_owner_user_id
     and provider_payload is not null
     and provider_payload_sha256 = calculated_payload_hash;
  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'saas_activation_identity_or_payload_changed_before_submit';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', case
      when attempt_row.submit_attempt_count = 0 then 'SUBMIT_ONCE'
      else 'RESUME_IDEMPOTENT'
    end,
    'status', 'SUBMITTING'
  );
end;
$$;


--
-- Name: mark_student_asaas_creation_submitting(uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_student_asaas_creation_submitting(p_attempt_id uuid, p_claim_token uuid, p_tenant_id text, p_student_id uuid, p_binding_kind text, p_expected_customer_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  bound jsonb;
begin
  bound := public.bind_student_asaas_creation_lifecycle(
    p_attempt_id,
    p_claim_token,
    p_tenant_id,
    p_student_id,
    p_binding_kind,
    p_expected_customer_id
  );
  if coalesce((bound ->> 'ok')::boolean, false) is not true then
    return bound;
  end if;
  return public.mark_asaas_provider_creation_submitting(
    p_attempt_id,
    p_claim_token
  );
end;
$$;


--
-- Name: mark_student_billing_method_mutating(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_student_billing_method_mutating(p_operation_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  operation_row public.student_billing_method_operations%rowtype;
  changed_id uuid;
begin
  select operation.* into operation_row
    from public.student_billing_method_operations as operation
   where operation.id = p_operation_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || operation_row.tenant_id || ':' || operation_row.student_id::text,
      0
    )
  );
  update public.student_billing_method_operations as operation
     set status = 'MUTATING',
         provider_started_at = coalesce(operation.provider_started_at, now()),
         lease_expires_at = now() + interval '10 minutes',
         updated_at = now()
   where operation.id = p_operation_id
     and operation.claim_token = p_claim_token
     and operation.status = 'CLAIMED'
     and operation.lease_expires_at > now()
     and exists (
       select 1 from public.profiles as profile
        where profile.id = operation.student_id
          and profile.tenant_id = operation.tenant_id
          and profile.role = 'STUDENT'
          and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
          and nullif(trim(coalesce(profile.asaas_customer_id, '')), '') = operation.customer_id
          and nullif(trim(coalesce(profile.subscription_id, '')), '') = operation.subscription_id
     )
     and (
       select count(*) from public.tenant_memberships as membership
        where membership.user_id = operation.student_id
     ) = 1
     and exists (
       select 1 from public.tenant_memberships as membership
        where membership.user_id = operation.student_id
          and membership.tenant_id = operation.tenant_id
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
     )
     and not exists (
       select 1 from public.student_offboarding_operations as offboarding
        where offboarding.tenant_id = operation.tenant_id
          and offboarding.student_id = operation.student_id
          and offboarding.status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
     )
     and not exists (
       select 1 from public.student_account_deletion_claims as deletion
        where deletion.tenant_id = operation.tenant_id
          and deletion.student_id = operation.student_id
          and deletion.status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED')
     )
   returning operation.id into changed_id;
  return jsonb_build_object('ok', changed_id is not null, 'reason', case when changed_id is null then 'claim_lost' else null end);
end;
$$;


--
-- Name: mark_student_overdue_card_charge_submitting(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_student_overdue_card_charge_submitting(p_claim_id uuid, p_claim_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  claim_row public.student_overdue_card_charge_claims%rowtype;
  changed_id uuid;
begin
  select charge.* into claim_row
    from public.student_overdue_card_charge_claims as charge
   where charge.id = p_claim_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || claim_row.tenant_id || ':' || claim_row.student_id::text,
      0
    )
  );

  update public.student_overdue_card_charge_claims as charge
     set status = 'SUBMITTING',
         submitted_at = now(),
         updated_at = now()
   where charge.id = p_claim_id
     and charge.claim_token = p_claim_token
     and charge.status = 'PROCESSING'
     and charge.lease_expires_at > now()
     and exists (
       select 1 from public.profiles as profile
        where profile.id = charge.student_id
          and profile.tenant_id = charge.tenant_id
          and profile.role = 'STUDENT'
          and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
          and nullif(trim(coalesce(profile.subscription_id, '')), '')
              = charge.asaas_subscription_id
     )
     and (
       select count(*) from public.tenant_memberships as membership
        where membership.user_id = charge.student_id
     ) = 1
     and exists (
       select 1 from public.tenant_memberships as membership
        where membership.user_id = charge.student_id
          and membership.tenant_id = charge.tenant_id
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
     )
     and not exists (
       select 1 from public.student_offboarding_operations as offboarding
        where offboarding.tenant_id = charge.tenant_id
          and offboarding.student_id = charge.student_id
          and offboarding.status in (
            'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED'
          )
     )
     and not exists (
       select 1 from public.student_account_deletion_claims as deletion
        where deletion.tenant_id = charge.tenant_id
          and deletion.student_id = charge.student_id
          and deletion.status in (
            'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN', 'BLOCKED'
          )
     )
   returning charge.id into changed_id;
  return jsonb_build_object(
    'ok', changed_id is not null,
    'reason', case when changed_id is null then 'claim_lost' else null end
  );
end;
$$;


--
-- Name: mark_training_complete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_training_complete(p_module_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_tenant_id text;
  v_module_id uuid;
begin
  if v_uid is null then
    raise exception
      using errcode = '28000', message = 'Authentication required';
  end if;

  select p.role, p.tenant_id
    into v_role, v_tenant_id
    from public.profiles as p
   where p.id = v_uid;

  if not found or v_tenant_id is null or v_role is null then
    raise exception
      using errcode = '42501', message = 'Active profile required';
  end if;

  select m.id
    into v_module_id
    from public.training_modules as m
   where m.id = p_module_id
     and m.tenant_id = v_tenant_id
     and m.active is true
     and (
       v_role = 'SUPER_ADMIN'
       or upper(v_role) = any (
         coalesce(
           array(
             select upper(target_role)
               from unnest(m.target_roles) as target_role
           ),
           array[]::text[]
         )
       )
     );

  if v_module_id is null then
    raise exception
      using errcode = '42501', message = 'Training module is unavailable';
  end if;

  insert into public.training_progress (
    tenant_id,
    teacher_id,
    user_id,
    user_role,
    module_id,
    status,
    completed_at
  )
  values (
    v_tenant_id,
    case when v_role = 'TEACHER' then v_uid else null end,
    v_uid,
    v_role,
    v_module_id,
    'COMPLETED',
    now()
  )
  on conflict (coalesce(user_id, teacher_id), module_id)
  do update
     set status = excluded.status,
         completed_at = excluded.completed_at,
         tenant_id = excluded.tenant_id,
         user_id = excluded.user_id,
         user_role = excluded.user_role;

  return jsonb_build_object(
    'status', 'OK',
    'module_id', v_module_id,
    'completed_at', now()
  );
end;
$$;


--
-- Name: mark_whatsapp_conversation_read(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_whatsapp_conversation_read(p_tenant_id text, p_conversation_id uuid, p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_latest_message_id uuid;
  v_read_at timestamptz := pg_catalog.now();
begin
  if p_conversation_id is null
     or not private.whatsapp_inbox_actor_has_role(
       p_actor_id,
       p_tenant_id,
       array['SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR']::text[]
     ) then
    raise exception 'whatsapp_conversation_read_forbidden'
      using errcode = '42501';
  end if;

  update public.whatsapp_conversations as conversation
  set unread_count = 0
  where conversation.id = p_conversation_id
    and conversation.tenant_id = p_tenant_id;

  if not found then
    raise exception 'whatsapp_conversation_not_found' using errcode = 'P0002';
  end if;

  select message.id
  into v_latest_message_id
  from public.whatsapp_messages as message
  where message.tenant_id = p_tenant_id
    and message.conversation_id = p_conversation_id
  order by message.occurred_at desc, message.id desc
  limit 1;

  insert into public.whatsapp_conversation_reads (
    tenant_id,
    conversation_id,
    user_id,
    last_read_message_id,
    last_read_at
  )
  values (
    p_tenant_id,
    p_conversation_id,
    p_actor_id,
    v_latest_message_id,
    v_read_at
  )
  on conflict (tenant_id, conversation_id, user_id) do update
  set last_read_message_id = excluded.last_read_message_id,
      last_read_at = greatest(
        whatsapp_conversation_reads.last_read_at,
        excluded.last_read_at
      );

  return jsonb_build_object(
    'ok', true,
    'conversationId', p_conversation_id,
    'lastReadMessageId', v_latest_message_id,
    'lastReadAt', v_read_at
  );
end;
$$;


--
-- Name: mark_wolfie_assignment_sent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_wolfie_assignment_sent(p_id uuid) RETURNS jsonb
