--
-- Name: match_teachers_for_plan(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_teachers_for_plan(p_tenant text, p_slots jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total int;
  v_result jsonb;
BEGIN
  v_total := jsonb_array_length(COALESCE(p_slots, '[]'::jsonb));
  IF v_total = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nenhum horário informado');
  END IF;

  WITH req AS (
    SELECT (s->>'dow')::int AS dow, substring((s->>'time') FOR 5) AS tm
    FROM jsonb_array_elements(p_slots) s
  ),
  daymap AS (
    SELECT * FROM (VALUES (0,'Domingo'),(1,'Segunda'),(2,'Terça'),(3,'Quarta'),(4,'Quinta'),(5,'Sexta'),(6,'Sábado')) AS d(dow, name)
  ),
  active_teachers AS (
    SELECT p.id, p.full_name, p.phone
    FROM profiles p
    WHERE p.tenant_id = p_tenant AND p.role = 'TEACHER'
      AND COALESCE(p.lifecycle_status,'active') = 'active'
      AND COALESCE(p.status,'Ativo') NOT IN ('Inativo','INACTIVE','Inactive','Arquivado','Cancelado','Trancado')
  ),
  coverage AS (
    SELECT t.id AS teacher_id, t.full_name, t.phone, r.dow, r.tm,
      EXISTS (
        SELECT 1 FROM teacher_availability ta
        WHERE ta.teacher_id = t.id AND ta.day_of_week = r.dow
          AND substring(ta.start_time::text FOR 5) = r.tm
      ) AS avail,
      NOT EXISTS (
        SELECT 1 FROM bookings b JOIN daymap dm ON dm.name = b.day_of_week
        WHERE b.teacher_id = t.id AND dm.dow = r.dow
          AND substring(COALESCE(b.time_slot,'') FOR 5) = r.tm
          AND COALESCE(b.status,'') NOT IN ('CANCELLED','CANCELED')
      ) AS free
    FROM active_teachers t CROSS JOIN req r
  ),
  scored AS (
    SELECT teacher_id, max(full_name) AS full_name, max(phone) AS phone,
      count(*) FILTER (WHERE avail AND free) AS covers,
      COALESCE(jsonb_agg(jsonb_build_object('dow', dow, 'time', tm) ORDER BY dow, tm)
               FILTER (WHERE NOT (avail AND free)), '[]'::jsonb) AS missing
    FROM coverage
    GROUP BY teacher_id
  )
  SELECT jsonb_build_object(
    'ok', true,
    'total_slots', v_total,
    'teachers', COALESCE(jsonb_agg(jsonb_build_object(
        'teacher_id', teacher_id, 'name', trim(full_name), 'phone', phone,
        'covers', covers, 'full', (covers = v_total), 'missing', missing
      ) ORDER BY (covers = v_total) DESC, covers DESC, trim(full_name)), '[]'::jsonb)
  ) INTO v_result
  FROM scored;

  RETURN v_result;
END;
$$;


--
-- Name: match_wise_wolf_knowledge(text, uuid, extensions.vector, integer, double precision); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.match_wise_wolf_knowledge(p_tenant_id text, p_knowledge_base_id uuid, p_query_embedding extensions.vector, p_match_count integer DEFAULT 8, p_min_similarity double precision DEFAULT 0.45) RETURNS TABLE(chunk_id uuid, document_id uuid, title text, content text, similarity double precision, chunk_index integer, metadata jsonb)
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select
    chunk.id,
    document.id,
    document.title,
    chunk.content,
    (
      1 - (
        chunk.embedding OPERATOR(extensions.<=>) p_query_embedding
      )
    )::double precision,
    chunk.chunk_index,
    document.metadata || chunk.metadata
  from public.ai_knowledge_chunks as chunk
  join public.ai_knowledge_documents as document
    on document.id = chunk.document_id
   and document.knowledge_base_id = chunk.knowledge_base_id
   and document.tenant_id = chunk.tenant_id
  join public.ai_knowledge_bases as base
    on base.id = chunk.knowledge_base_id
   and base.tenant_id = chunk.tenant_id
  where chunk.tenant_id = p_tenant_id
    and chunk.knowledge_base_id = p_knowledge_base_id
    and document.status = 'READY'
    and base.status = 'ACTIVE'
    and base.provider = 'OPENROUTER'
    and base.embedding_dimensions = 1536
    and 1 - (
      chunk.embedding OPERATOR(extensions.<=>) p_query_embedding
    ) >= greatest(
      -1::double precision,
      least(coalesce(p_min_similarity, 0.45), 1::double precision)
    )
  order by chunk.embedding OPERATOR(extensions.<=>) p_query_embedding
  limit least(greatest(coalesce(p_match_count, 8), 1), 20);
$$;


--
-- Name: materialize_enrollment_offer_schedule(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.materialize_enrollment_offer_schedule(p_offer_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_runtime_role text := coalesce((select auth.jwt() ->> 'role'), '');
  v_offer record;
  v_expected_count integer;
  v_booking_count integer;
  v_inserted_count integer := 0;
begin
  if v_runtime_role <> 'service_role' then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'FORBIDDEN'
    );
  end if;

  begin
    perform private.lock_and_validate_enrollment_schedule(
      p_offer_id,
      p_user_id
    );
  exception
    when exclusion_violation or check_violation
      or insufficient_privilege or unique_violation or deadlock_detected
  then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'SCHEDULE_UNAVAILABLE'
    );
  end;

  select
    offer.tenant_id,
    offer.payload,
    offer.processing_by,
    offer.processing_state,
    offer.revoked_at,
    offer.consumed_at
  into v_offer
  from public.offers as offer
  where offer.id = p_offer_id
    and offer.kind = 'ENROLLMENT'
  for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'OFFER_NOT_FOUND'
    );
  end if;
  if v_offer.processing_by is distinct from p_user_id then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'ATTEMPT_OWNER_MISMATCH'
    );
  end if;
  if v_offer.revoked_at is not null then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'OFFER_REVOKED'
    );
  end if;
  if not private.tenant_is_operational(v_offer.tenant_id) then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'TENANT_UNAVAILABLE'
    );
  end if;

  begin
    v_expected_count := (v_offer.payload ->> 'classesPerWeek')::integer;
  exception when others then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'SCHEDULE_INVALID'
    );
  end;

  if not exists (
    select 1
    from public.profiles as student
    join public.tenant_memberships as membership
      on membership.user_id = student.id
     and membership.tenant_id = student.tenant_id
     and membership.role = 'STUDENT'
     and membership.status = 'ACTIVE'
    where student.id = p_user_id
      and student.tenant_id = v_offer.tenant_id
      and student.role = 'STUDENT'
      and pg_catalog.lower(pg_catalog.btrim(student.lifecycle_status)) = 'active'
  ) then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'PROFILE_INVALID'
    );
  end if;

  if exists (
    select 1
    from private.enrollment_offer_schedule_slots as slot
    where slot.offer_id = p_offer_id
      and (
        slot.reserved_by is distinct from p_user_id
        or slot.status not in ('RESERVED', 'MATERIALIZED')
        or (
          slot.status = 'RESERVED'
          and slot.reservation_expires_at <= now()
        )
      )
  ) then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'error', 'SCHEDULE_RESERVATION_REQUIRED'
    );
  end if;

  with inserted as (
    insert into public.bookings (
      tenant_id,
      teacher_id,
      student_id,
      day_of_week,
      time_slot,
      start_date,
      status,
      enrollment_offer_id,
      enrollment_offer_slot_id
    )
    select
      slot.tenant_id,
      slot.teacher_id,
      p_user_id,
      slot.day_name,
      pg_catalog.to_char(slot.class_time, 'HH24:MI'),
      slot.start_date,
      'SCHEDULED',
      slot.offer_id,
      slot.id
    from private.enrollment_offer_schedule_slots as slot
    where slot.offer_id = p_offer_id
      and slot.status = 'RESERVED'
    order by slot.teacher_id, slot.day_of_week, slot.class_time, slot.slot_index
    on conflict (enrollment_offer_slot_id)
      where enrollment_offer_slot_id is not null
      do nothing
    returning id
  )
  select pg_catalog.count(*)::integer
  into v_inserted_count
  from inserted;

  update private.enrollment_offer_schedule_slots as slot
  set status = 'MATERIALIZED',
      reservation_expires_at = null,
      materialized_booking_id = booking.id,
      updated_at = now()
  from public.bookings as booking
  where slot.offer_id = p_offer_id
    and booking.enrollment_offer_slot_id = slot.id
    and booking.enrollment_offer_id = slot.offer_id
    and booking.tenant_id = slot.tenant_id
    and booking.teacher_id = slot.teacher_id
    and booking.student_id = p_user_id
    and public.dow_name_to_int(booking.day_of_week) = slot.day_of_week
    and pg_catalog.left(pg_catalog.btrim(booking.time_slot), 5)
        = pg_catalog.to_char(slot.class_time, 'HH24:MI')
    and booking.start_date is not distinct from slot.start_date
    and pg_catalog.upper(coalesce(booking.status, 'SCHEDULED')) = 'SCHEDULED';

  select pg_catalog.count(*)::integer
  into v_booking_count
  from private.enrollment_offer_schedule_slots as slot
  join public.bookings as booking
    on booking.id = slot.materialized_booking_id
   and booking.enrollment_offer_slot_id = slot.id
   and booking.enrollment_offer_id = slot.offer_id
   and booking.student_id = p_user_id
   and pg_catalog.upper(coalesce(booking.status, 'SCHEDULED')) = 'SCHEDULED'
  where slot.offer_id = p_offer_id
    and slot.status = 'MATERIALIZED'
    and slot.reserved_by = p_user_id;
  if v_booking_count <> v_expected_count then
    raise exception 'enrollment_schedule_materialization_incomplete'
      using errcode = '23P01';
  end if;

  update public.offers as offer
  set metadata = coalesce(offer.metadata, '{}'::jsonb)
      || pg_catalog.jsonb_build_object(
        'schedule_materialized_at', now(),
        'schedule_booking_count', v_booking_count
      )
  where offer.id = p_offer_id;

  return pg_catalog.jsonb_build_object(
    'success', true,
    'booking_count', v_booking_count,
    'idempotent', v_inserted_count = 0
  );
end;
$$;


--
-- Name: FUNCTION materialize_enrollment_offer_schedule(p_offer_id uuid, p_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.materialize_enrollment_offer_schedule(p_offer_id uuid, p_user_id uuid) IS 'Materializa idempotentemente a grade reservada antes de qualquer side effect no Asaas; uso exclusivo service_role.';


--
-- Name: meeting_links_to_verify(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.meeting_links_to_verify() RETURNS TABLE(student_id uuid, student_name text, meeting_link text, tem_aula boolean, verificado boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_column
DECLARE
  v_role   text;
  v_tenant text;
BEGIN
  SELECT p.role, p.tenant_id INTO v_role, v_tenant
  FROM public.profiles p WHERE p.id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN
     ('TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') THEN
    RAISE EXCEPTION 'sem_permissao';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    COALESCE(p.full_name, '?')::text,
    p.meeting_link,
    EXISTS (
      SELECT 1 FROM public.bookings b
      WHERE b.student_id = p.id AND b.status = 'SCHEDULED'
    ),
    p.meeting_link_verified_at IS NOT NULL
  FROM public.profiles p
  WHERE p.role = 'STUDENT'
    AND p.tenant_id = v_tenant
    AND COALESCE(p.status, 'Ativo') NOT IN ('Inativo', 'INACTIVE', 'Arquivado')
    AND p.meeting_link_verified_at IS NULL
  ORDER BY EXISTS (
    SELECT 1 FROM public.bookings b
    WHERE b.student_id = p.id AND b.status = 'SCHEDULED'
  ) DESC, p.full_name;
END;
$$;


--
-- Name: mei_radar_caller_allowed(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mei_radar_caller_allowed() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text;
BEGIN
  IF COALESCE(current_setting('request.jwt.claims', true), '') <> ''
     AND (current_setting('request.jwt.claims', true)::jsonb->>'role') = 'service_role' THEN
    RETURN true;
  END IF;
  SELECT role INTO v_role FROM profiles WHERE id = auth.uid();
  RETURN v_role IN ('SCHOOL_ADMIN', 'SUPER_ADMIN');
END; $$;


--
-- Name: mirror_monthly_tuition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mirror_monthly_tuition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- INSERT precisa entrar: matrícula nova grava `monthly_fee` e, sem espelho,
  -- `monthly_tuition` nasceria NULL — quem ainda lê a coluna antiga veria aluno
  -- sem mensalidade. Em BEFORE INSERT o registro OLD não existe, daí o TG_OP.
  if tg_op = 'INSERT' then
    if new.monthly_fee is not null then
      new.monthly_tuition := new.monthly_fee;
    end if;
    return new;
  end if;

  -- No UPDATE, só quando a mensalidade de verdade muda. Ver o aviso no topo.
  if new.monthly_fee is distinct from old.monthly_fee then
    new.monthly_tuition := new.monthly_fee;
  end if;
  return new;
end;
$$;


--
-- Name: monthly_closings_to_notify(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.monthly_closings_to_notify(p_month text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'teacher_id', tc.teacher_id, 'tenant_id', tc.tenant_id, 'month', tc.month_year,
    'lessons', tc.total_lessons, 'amount', tc.total_amount,
    'name', (SELECT full_name FROM profiles WHERE id=tc.teacher_id),
    'phone', (SELECT phone FROM profiles WHERE id=tc.teacher_id)
  )), '[]'::jsonb)
  FROM teacher_closings tc
  WHERE tc.month_year = p_month
    AND is_teacher_notifiable(tc.teacher_id);
$$;


--
-- Name: monthly_payment_closure_targets(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.monthly_payment_closure_targets() RETURNS TABLE(tenant_id text, period_start date)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with periods as (
    select pg_catalog.date_trunc(
             'month',
             pg_catalog.now() at time zone 'America/Sao_Paulo'
           )::date as period_start
    union all
    select (
      pg_catalog.date_trunc(
        'month',
        pg_catalog.now() at time zone 'America/Sao_Paulo'
      ) - interval '1 month'
    )::date
  )
  select setting.tenant_id, periods.period_start
    from public.dre_report_settings as setting
    join public.payment_split_settings as split
      on split.tenant_id = setting.tenant_id
     and split.is_active
    cross join periods
   where setting.is_active
   order by periods.period_start, setting.tenant_id;
$$;


--
-- Name: my_attendance_audits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_attendance_audits() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_result jsonb;
begin
  if v_uid is null then
    return '[]'::jsonb;
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', q.id,
        'teacher_name', q.teacher_name,
        'class_date', q.class_date,
        'class_time', q.class_time,
        'student_response', q.student_response,
        'status', q.status,
        'responded_at', q.responded_at,
        'student_rating', q.student_rating,
        'can_correct', q.can_correct,
        'editable_until', q.response_editable_until,
        'allowed_responses', case when q.can_correct then
          pg_catalog.jsonb_build_array(
            'STUDENT_PRESENT',
            'TEACHER_NO_SHOW',
            'STUDENT_SELF_ABSENT',
            'CANCELLED_RESCHEDULED'
          )
        else '[]'::jsonb end
      ) order by q.class_date desc, q.class_time desc, q.id
    ),
    '[]'::jsonb
  )
  into v_result
  from (
    select
      ac.id,
      ac.teacher_name,
      ac.class_date,
      ac.class_time,
      ac.student_response,
      ac.status,
      ac.responded_at,
      ac.student_rating,
      ac.response_editable_until,
      (
        ac.token_expires_at > pg_catalog.now()
        and ac.status not in ('CANCELLED', 'RESOLVED_PAID', 'RESOLVED_UNPAID')
        and (
          ac.student_response is null
          or ac.response_editable_until > pg_catalog.now()
        )
      ) as can_correct
    from public.attendance_confirmations ac
    where ac.student_id = v_uid
      and coalesce(ac.canonical_confirmation_id, ac.id) = ac.id
      and (
        ac.student_response is not null
        or (
          ac.token_expires_at > pg_catalog.now()
          and ac.status not in ('CANCELLED', 'RESOLVED_PAID', 'RESOLVED_UNPAID')
        )
      )
    order by ac.class_date desc, ac.class_time desc, ac.id
    limit 100
  ) q;

  return v_result;
end;
$$;


--
-- Name: my_attendance_conflict_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_attendance_conflict_count() RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_count integer := 0;
begin
  if v_uid is null or not exists (
    select 1
      from public.profiles p
     where p.id = v_uid
       and p.role = 'TEACHER'
  ) then
    return 0;
  end if;

  select count(*)::integer
    into v_count
    from public.attendance_confirmations ac
   where ac.teacher_id = v_uid
     and ac.status = 'CONFLICT'
     and coalesce(ac.canonical_confirmation_id, ac.id) = ac.id;

  return v_count;
end;
$$;


--
-- Name: my_training_modules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_training_modules() RETURNS TABLE(id uuid, title text, description text, video_url text, pdf_url text, thumbnail_url text, category text, is_mandatory boolean, order_index integer, target_roles text[], progress_status text, progress_completed_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with caller as (
    select
      p.id as user_id,
      p.role as user_role,
      p.tenant_id as user_tenant_id
    from public.profiles as p
    where p.id = (select auth.uid())
  )
  select
    m.id,
    m.title,
    m.description,
    m.video_url,
    m.pdf_url,
    m.thumbnail_url,
    m.category,
    m.is_mandatory,
    m.order_index,
    m.target_roles,
    coalesce(tp.status, 'NOT_STARTED'::text) as progress_status,
    tp.completed_at as progress_completed_at
  from caller as c
  join public.training_modules as m
    on m.tenant_id = c.user_tenant_id
  left join public.training_progress as tp
    on tp.module_id = m.id
   and coalesce(tp.user_id, tp.teacher_id) = c.user_id
  where m.active is true
    and (
      c.user_role = 'SUPER_ADMIN'
      or upper(c.user_role) = any (
        coalesce(
          array(
            select upper(target_role)
              from unnest(m.target_roles) as target_role
          ),
          array[]::text[]
        )
      )
    )
  order by m.order_index, m.created_at desc;
$$;


