--
-- Name: notify_outbox_inserted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_outbox_inserted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_supabase_url TEXT := 'https://api.wisewolflanguage.com.br';
    v_service_key TEXT;
BEGIN
    BEGIN
        SELECT decrypted_secret INTO v_service_key FROM vault.decrypted_secrets WHERE name = 'SERVICE_ROLE_KEY' LIMIT 1;
    EXCEPTION WHEN OTHERS THEN
        v_service_key := NULL;
    END;

    IF v_service_key IS NOT NULL THEN
        PERFORM extensions.http_post(
            url := v_supabase_url || '/functions/v1/process-outbox',
            headers := jsonb_build_object(
                'Authorization', 'Bearer ' || v_service_key,
                'Content-Type', 'application/json'
            ),
            body := jsonb_build_object(
                'trigger', 'pg_net',
                'msg_id', NEW.id::text
            )
        );
    END IF;

    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION notify_outbox_inserted(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.notify_outbox_inserted() IS 'pg_net fire-and-forget trigger. Calls process-outbox Edge Function on new outbox message. Non-blocking on failure.';


--
-- Name: notify_payment_split(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_payment_split() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_notification_kind text;
  v_status text := 'PENDING';
  v_error text;
  v_outbox_id uuid;
  v_service_key text;
  v_request_id bigint;
begin
  if new.status not in ('RECEIVED', 'RECEIVED_IN_CASH')
     or coalesce(new.value, 0) <= 0 then
    return new;
  end if;
  -- Legacy/unbound payments have no school and therefore no truthful
  -- management-group route.  They must remain reconcilable without either
  -- inventing a tenant or aborting the settlement on the outbox invariant.
  if nullif(pg_catalog.btrim(coalesce(new.tenant_id, '')), '') is null then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.status is not distinct from new.status then
    return new;
  end if;

  v_notification_kind := private.management_payment_notification_kind(
    new.tenant_id
  );
  if private.management_payment_is_test_fixture(new.tenant_id, new.id) then
    v_status := 'SUPPRESSED';
    v_error := 'test_fixture_suppressed';
  elsif v_notification_kind is null then
    v_status := 'SUPPRESSED';
    v_error := 'management_group_notification_disabled';
  end if;

  -- Test fixtures must remain suppressible even when the tenant has no active
  -- management destination.  The durable row still needs a canonical kind to
  -- satisfy its invariant; it will never be eligible for submission because
  -- SUPPRESSED is terminal.
  v_notification_kind := coalesce(v_notification_kind, 'PAYMENT_RECEIVED');

  insert into public.management_payment_notification_outbox (
    tenant_id,
    payment_id,
    notification_kind,
    status,
    lease_expires_at,
    last_error
  ) values (
    new.tenant_id,
    new.id,
    v_notification_kind,
    v_status,
    case when v_status = 'SUPPRESSED' then pg_catalog.now() else null end,
    v_error
  )
  on conflict (tenant_id, payment_id) do nothing
  returning id into v_outbox_id;

  if v_outbox_id is null or v_status <> 'PENDING' then
    return new;
  end if;

  -- The HTTP request is only a nudge. Its nested exception block cannot roll
  -- back the outbox INSERT above; the unlimited sweep is the recovery path.
  begin
    select secret.decrypted_secret
    into v_service_key
    from vault.decrypted_secrets as secret
    where secret.name = 'wisewolf_service_role_key'
    limit 1;

    if nullif(pg_catalog.btrim(coalesce(v_service_key, '')), '') is not null then
      select net.http_post(
        url := 'http://kong:8000/functions/v1/payment-split-notify',
        headers := pg_catalog.jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_service_key,
          'apikey', v_service_key
        ),
        body := pg_catalog.jsonb_build_object(
          'management_notification_payment_id',
          new.id
        ),
        timeout_milliseconds := 20000
      ) into v_request_id;
    end if;
  exception when others then
    raise warning 'management payment notification nudge failed: %', sqlerrm;
  end;

  return new;
end;
$$;


--
-- Name: observe_asaas_student_billing_schedule_event(text, text, text, text, text, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.observe_asaas_student_billing_schedule_event(p_provider_event_id text, p_event_name text, p_subscription_id text, p_customer_id text, p_provider_status text, p_provider_event_at timestamp with time zone, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_inbox public.asaas_webhook_inbox%rowtype;
  v_operation_id uuid;
  v_step_kind text;
  v_match_count integer;
begin
  if pg_catalog.upper(pg_catalog.btrim(coalesce(p_event_name, ''))) <>
       'SUBSCRIPTION_UPDATED'
     or pg_catalog.upper(pg_catalog.btrim(coalesce(
          p_provider_status, ''
        ))) <> 'ACTIVE'
     or pg_catalog.jsonb_typeof(p_payload -> 'subscription') <> 'object'
     or p_payload ->> 'id' is distinct from p_provider_event_id
     or pg_catalog.upper(pg_catalog.btrim(coalesce(
          p_payload ->> 'event', ''
        ))) <> 'SUBSCRIPTION_UPDATED'
     or p_payload #>> '{subscription,id}' is distinct from p_subscription_id
     or p_payload #>> '{subscription,customer}' is distinct from p_customer_id
  then
    return pg_catalog.jsonb_build_object(
      'handled', false,
      'reason', 'student_card_schedule_move_event_mismatch'
    );
  end if;

  select inbox.* into v_inbox
    from public.asaas_webhook_inbox as inbox
   where inbox.provider_event_id = p_provider_event_id;
  if not found
     or v_inbox.event_name <> 'SUBSCRIPTION_UPDATED'
     or v_inbox.provider_entity_id <> p_subscription_id
     or v_inbox.payload is distinct from p_payload
     or v_inbox.status <> 'PROCESSING'
     or v_inbox.lease_owner is null
     or v_inbox.lease_expires_at is null
     or v_inbox.lease_expires_at <= pg_catalog.clock_timestamp()
  then
    return pg_catalog.jsonb_build_object(
      'handled', false,
      'reason', 'student_card_schedule_move_inbox_not_claimed'
    );
  end if;

  select pg_catalog.count(*),
         (pg_catalog.array_agg(operation.id order by step.ordinal desc))[1],
         (pg_catalog.array_agg(step.step_kind order by step.ordinal desc))[1]
    into v_match_count, v_operation_id, v_step_kind
    from public.asaas_student_card_schedule_moves as operation
    join public.asaas_student_card_schedule_move_steps as step
      on step.operation_id = operation.id
   where operation.subscription_id = p_subscription_id
     and operation.customer_id = p_customer_id
     and operation.status <> 'FAILED'
     and step.step_kind in (
       'UPDATE_TARGET_SCHEDULE', 'RESTORE_ORIGINAL_SCHEDULE'
     )
     and step.status in ('SUBMITTING', 'UNKNOWN', 'SUCCEEDED')
     and step.submit_attempt_count = 1
     and step.submitted_at is not null
     and v_inbox.received_at >= step.submitted_at
     and v_inbox.received_at <= operation.accept_events_until
     and (p_payload -> 'subscription') @>
       pg_catalog.jsonb_build_object(
         'id', step.desired_after -> 'id',
         'customer', step.desired_after -> 'customer',
         'status', step.desired_after -> 'status',
         'value', step.desired_after -> 'value',
         'cycle', step.desired_after -> 'cycle',
         'billingType', step.desired_after -> 'billingType',
         'externalReference', step.desired_after -> 'externalReference'
       );

  if v_match_count <> 1 then
    return pg_catalog.jsonb_build_object(
      'handled', false,
      'reason', case when v_match_count = 0
        then 'no_expected_student_card_schedule_move_event'
        else 'ambiguous_student_card_schedule_move_event'
      end
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'handled', true,
    'operation_id', v_operation_id,
    'step_kind', v_step_kind,
    'duplicate', false,
    'authoritative_get_required', true
  );
end;
$$;


--
-- Name: ofertas_de_renovacao(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ofertas_de_renovacao(p_tenant text DEFAULT NULL::text, p_dias integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
#variable_conflict use_column
declare
  v_jwt text;
  v_role text;
  v_tenant text;
  v_dias int;
  v_itens jsonb;
begin
  v_jwt := coalesce(current_setting('request.jwt.claims', true)::json->>'role', '');
  select role, tenant_id into v_role, v_tenant from public.profiles where id = auth.uid();

  if v_jwt in ('anon', 'authenticated') then
    if v_role is null or v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') then
      return jsonb_build_object('error', 'sem_permissao');
    end if;
    if v_role = 'SUPER_ADMIN' then v_tenant := coalesce(p_tenant, v_tenant); end if;
  else
    v_tenant := coalesce(p_tenant, v_tenant);
  end if;

  if v_tenant is null then
    return jsonb_build_object('error', 'escola_nao_identificada');
  end if;

  v_dias := coalesce(p_dias,
                     (select dias_antes from public.renewal_offer_settings where tenant_id = v_tenant),
                     15);

  select coalesce(jsonb_agg(x order by x.termina), '[]'::jsonb) into v_itens
  from (
    select trim(p.full_name) as aluno,
           p.id as student_id,
           public.fim_do_servico(p.asaas_subscription_end_date) as termina,
           (public.fim_do_servico(p.asaas_subscription_end_date) - current_date)::int as dias,
           coalesce(p.monthly_fee, 0)::numeric(10,2) as paga_hoje,
           f.freq,
           prof.professor,
           pl.p12,
           'Oi ' || split_part(btrim(p.full_name), ' ', 1) || '! 🐺 '
             || 'Seus horários com '
             || coalesce(split_part(prof.professor, ' ', 1), 'seu professor')
             || ' vão até ' || to_char(public.fim_do_servico(p.asaas_subscription_end_date), 'DD/MM') || '.'
             || E'\n\n'
             || 'Quer seguir com a gente? Pode renovar por mais 6 meses mantendo sua mensalidade de R$ '
             || public.brl_texto(coalesce(p.monthly_fee, 0))
             || case
                  when pl.p12 is not null and pl.p12 < coalesce(p.monthly_fee, 0)
                    then ', ou fechar 12 meses e ela cai para R$ ' || public.brl_texto(pl.p12)
                         || ' — R$ ' || public.brl_texto(coalesce(p.monthly_fee, 0) - pl.p12)
                         || ' a menos por mês.'
                  when pl.p12 is not null
                    then ', ou fechar 12 meses por R$ ' || public.brl_texto(pl.p12) || '.'
                  else '.'
                end
             || E'\n\n'
             || 'Do jeito que for melhor pra você. Me avisa? 😊' as mensagem
      from public.profiles p
      cross join lateral (select public.frequencia_efetiva(p.id) as freq) f
      cross join lateral (
        select (select trim(t.full_name)
                  from public.class_logs cl
                  join public.profiles t on t.id = cl.teacher_id
                 where cl.student_id = p.id and cl.class_date >= current_date - 90
                 group by t.full_name order by count(*) desc limit 1) as professor
      ) prof
      cross join lateral (
        select (select monthly_price from public.student_pricing_plans sp
                 where sp.tenant_id = v_tenant and sp.active
                   and sp.classes_per_week = f.freq and sp.fidelity_months = 12 limit 1) as p12
      ) pl
     where p.tenant_id = v_tenant
       and p.role = 'STUDENT'
       and public.is_student_notifiable(p.id)
       -- Aluno mensal (sem data de fim) não recebe oferta. Regra do diretor.
       and p.asaas_subscription_end_date is not null
       and public.fim_do_servico(p.asaas_subscription_end_date) >= current_date
       and public.fim_do_servico(p.asaas_subscription_end_date) <= current_date + v_dias
       and exists (select 1 from public.class_logs cl
                    where cl.student_id = p.id and cl.class_date >= current_date - 60)
  ) x;

  return jsonb_build_object(
    'ok', true,
    'ativo', coalesce((select is_active from public.renewal_offer_settings where tenant_id = v_tenant), false),
    'dias_antes', v_dias,
    'itens', v_itens,
    'qtd', jsonb_array_length(v_itens)
  );
end;
$_$;


--
-- Name: on_class_log_reconcile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.on_class_log_reconcile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_conf_id uuid;
  v_src text;
  v_stype text;
begin
  if new.booking_id is not null then
    v_src := new.booking_id;
    v_stype := 'booking';
  elsif new.reschedule_id is not null then
    v_src := new.reschedule_id;
    v_stype := 'reschedule';
  elsif new.appointment_id is not null then
    v_src := new.appointment_id;
    v_stype := 'appointment';
  else
    return new;
  end if;

  select ac.id
    into v_conf_id
    from public.attendance_confirmations ac
   where ac.source_id = v_src
     and ac.source_type = v_stype
     and ac.class_date = coalesce(new.class_date, new.date)
     and ac.tenant_id = new.tenant_id
     and ac.teacher_id = new.teacher_id
     and ac.student_id is not distinct from new.student_id
   order by ac.created_at desc, ac.id
   limit 1;

  if v_conf_id is not null then
    perform public.reconcile_attendance_confirmation(v_conf_id);
  end if;
  return new;
end;
$$;


--
-- Name: open_reallocation_for_teacher(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_reallocation_for_teacher(p_teacher uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text; v_tenant text; v_tname text;
  v_created int := 0; v_notified int := 0;
  r record; t record;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RAISE EXCEPTION 'Apenas admin abre o mural de realocação';
  END IF;
  SELECT full_name INTO v_tname FROM profiles WHERE id = p_teacher AND tenant_id = v_tenant;
  IF v_tname IS NULL THEN RAISE EXCEPTION 'Professor não encontrado no tenant'; END IF;

  FOR r IN
    SELECT b.student_id, s.full_name,
           string_agg(DISTINCT b.day_of_week || ' ' || COALESCE(b.time_slot,''), ' · ') AS sched,
           array_agg(DISTINCT b.day_of_week) AS days
    FROM bookings b JOIN profiles s ON s.id = b.student_id
    WHERE b.teacher_id = p_teacher AND b.tenant_id = v_tenant
      AND COALESCE(s.lifecycle_status,'active') = 'active'
    GROUP BY b.student_id, s.full_name
  LOOP
    IF EXISTS (SELECT 1 FROM student_opportunities
               WHERE student_id = r.student_id AND status = 'OPEN') THEN CONTINUE; END IF;
    INSERT INTO student_opportunities
      (tenant_id, student_id, student_name, schedule, schedule_days, from_teacher_id, from_teacher_name)
    VALUES (v_tenant, r.student_id, r.full_name, r.sched, r.days, p_teacher, v_tname);
    v_created := v_created + 1;
  END LOOP;

  IF v_created > 0 THEN
    UPDATE profiles SET offboarding_status = 'REASSIGNING' WHERE id = p_teacher AND offboarding_status IN ('REQUESTED','APPROVED');
    -- avisa os demais professores ativos (1 mensagem, dedupe 3 dias)
    FOR t IN
      SELECT p.id, p.full_name, p.phone FROM profiles p
      WHERE p.tenant_id = v_tenant AND p.role IN ('TEACHER','teacher')
        AND COALESCE(p.lifecycle_status,'active') = 'active'
        AND p.id <> p_teacher AND COALESCE(p.phone,'') <> ''
        AND NOT EXISTS (SELECT 1 FROM notification_queue nq
                        WHERE nq.source_id = p.id AND nq.notification_kind = 'NEW_STUDENT_OPPS'
                          AND nq.created_at > now() - interval '3 days')
    LOOP
      INSERT INTO notification_queue
        (tenant_id, teacher_id, student_id, student_name, student_phone, message_body,
         scheduled_for, status, source_id, source_type, notification_kind)
      VALUES
        (v_tenant, NULL, NULL, t.full_name, t.phone,
         'Oi, ' || split_part(t.full_name,' ',1) || '! 🐺 Temos ' || v_created ||
         ' aluno(s) disponíveis no MURAL DE OPORTUNIDADES do seu portal — horários que podem encaixar na sua agenda. Quem aceitar primeiro fica com o aluno! Entra lá: https://system.wisewolflanguage.com.br 🎓',
         now(), 'pending', t.id, 'reallocation', 'NEW_STUDENT_OPPS');
      v_notified := v_notified + 1;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('ok', true, 'oportunidades_criadas', v_created, 'professores_avisados', v_notified);
END; $$;


--
-- Name: parse_lesson_date(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.parse_lesson_date(p_value text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO ''
    AS $_$
declare
  v_value text := pg_catalog.btrim(p_value);
begin
  if v_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
    return pg_catalog.make_date(
      pg_catalog.substr(v_value, 1, 4)::int,
      pg_catalog.substr(v_value, 6, 2)::int,
      pg_catalog.substr(v_value, 9, 2)::int
    );
  elsif v_value ~ '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' then
    return pg_catalog.make_date(
      pg_catalog.substr(v_value, 7, 4)::int,
      pg_catalog.substr(v_value, 4, 2)::int,
      pg_catalog.substr(v_value, 1, 2)::int
    );
  end if;

  return null;
exception when others then
  return null;
end;
$_$;


--
-- Name: payment_split_breakdown(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_split_breakdown(p_payment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_jwt_role text; v_caller_role text; v_caller_tenant text;
  v_pay record; v_tenant text; v_mes text; v_ini date; v_fim date;
  v_dizimo_pct numeric; v_investimento_pct numeric; v_ativo boolean;
  v_prof_dizimo_pct numeric; v_prof_investimento_pct numeric; v_prof_prolabore_pct numeric;
  v_custo numeric; v_aulas int; v_liquido numeric;
  v_professores jsonb; v_aluno text;
  v_na_base boolean; v_dizimo numeric; v_investimento numeric;
  v_pro_labore numeric; v_aulas_pl int; v_sobra numeric;
  v_escola_pct numeric; v_share numeric;
  v_base_pl numeric; v_base_prof numeric;
  v_dz_pl numeric; v_inv_pl numeric; v_esc_pl numeric; v_pl_pl numeric;
  v_dz_pr numeric; v_inv_pr numeric; v_pl_pr numeric; v_esc_pr numeric;
begin
  select coalesce(
           nullif(btrim(current_setting('request.jwt.claims', true)), '')::jsonb ->> 'role',
           ''
         )
    into v_jwt_role;

  select sp.id, sp.student_id, sp.value, sp.tenant_id, sp.description, sp.payment_type,
         coalesce(sp.paid_at, sp.payment_date, sp.due_date) as quando,
         sp.created_at
    into v_pay
    from student_payments sp where sp.id = p_payment_id;
  if not found then return jsonb_build_object('error','pagamento_nao_encontrado'); end if;

  v_tenant := coalesce(v_pay.tenant_id,
                       (select p.tenant_id from profiles p where p.id = v_pay.student_id));
  if v_tenant is null then return jsonb_build_object('error','escola_nao_identificada'); end if;

  if v_jwt_role in ('anon','authenticated') then
    select role, tenant_id into v_caller_role, v_caller_tenant
      from profiles where id = auth.uid();
    if v_caller_role is null or v_caller_role not in ('SCHOOL_ADMIN','SUPER_ADMIN') then
      return jsonb_build_object('error','sem_permissao');
    end if;
    if v_caller_role <> 'SUPER_ADMIN' and v_caller_tenant is distinct from v_tenant then
      return jsonb_build_object('error','sem_permissao');
    end if;
  end if;

  select s.dizimo_pct, s.investimento_pct, s.escola_pct, s.is_active,
         s.prof_dizimo_pct, s.prof_investimento_pct, s.prof_prolabore_pct
    into v_dizimo_pct, v_investimento_pct, v_escola_pct, v_ativo,
         v_prof_dizimo_pct, v_prof_investimento_pct, v_prof_prolabore_pct
    from payment_split_settings s where s.tenant_id = v_tenant;
  if not found then
    v_dizimo_pct := 10.00; v_investimento_pct := 10.00;
    v_escola_pct := 0.00; v_ativo := false;
    v_prof_dizimo_pct := 10.00; v_prof_investimento_pct := 70.00; v_prof_prolabore_pct := 20.00;
  end if;

  v_mes := to_char(coalesce(v_pay.quando, now()), 'YYYY-MM');
  v_ini := (v_mes || '-01')::date;
  v_fim := (date_trunc('month', v_ini) + interval '1 month - 1 day')::date;

  select btrim(p.full_name) into v_aluno from profiles p where p.id = v_pay.student_id;

  with aulas as (
    select b.teacher_id,
           d::date as dia,
           teacher_student_rate(b.teacher_id, b.student_id, d::date) as rate,
           exists (select 1 from payment_split_owner_teachers o
                    where o.tenant_id = v_tenant and o.teacher_id = b.teacher_id) as pro_labore
      from bookings b
      cross join generate_series(v_ini, v_fim, '1 day') d
     where b.student_id = v_pay.student_id
       and coalesce(b.status,'SCHEDULED') = 'SCHEDULED'
       and dow_name_to_int(b.day_of_week) = extract(dow from d)::int
       and (b.start_date is null or d >= b.start_date)
  )
  select coalesce(count(*),0)::int,
         coalesce(sum(a.rate) filter (where not a.pro_labore), 0),
         coalesce(count(*) filter (where a.pro_labore),0)::int
    into v_aulas, v_custo, v_aulas_pl
    from aulas a;

  select coalesce(jsonb_agg(jsonb_build_object(
           'teacher_id', z.teacher_id,
           'teacher_name', coalesce(btrim(t.full_name), 'Professor não identificado'),
           'aulas', z.n,
           'custo', case when z.pro_labore then null else round(z.custo,2) end,
           'descontado', not z.pro_labore) order by z.custo desc), '[]'::jsonb)
    into v_professores
    from (
      select b.teacher_id, count(*)::int as n,
             sum(teacher_student_rate(b.teacher_id, b.student_id, d::date)) as custo,
             exists (select 1 from payment_split_owner_teachers o
                      where o.tenant_id = v_tenant and o.teacher_id = b.teacher_id) as pro_labore
        from bookings b
        cross join generate_series(v_ini, v_fim, '1 day') d
       where b.student_id = v_pay.student_id
         and coalesce(b.status,'SCHEDULED') = 'SCHEDULED'
         and dow_name_to_int(b.day_of_week) = extract(dow from d)::int
         and (b.start_date is null or d >= b.start_date)
       group by b.teacher_id) z
    left join profiles t on t.id = z.teacher_id;

  v_liquido := greatest(coalesce(v_pay.value,0) - coalesce(v_custo,0), 0);
  v_na_base := (v_pay.student_id is not null);
  v_share := case when v_aulas > 0 then v_aulas_pl::numeric / v_aulas else 0 end;

  if not v_na_base then
    v_dizimo := 0; v_investimento := 0; v_pro_labore := 0; v_sobra := round(v_liquido, 2);
  else
    v_base_pl   := round(v_liquido * v_share, 2);
    v_base_prof := round(v_liquido - v_base_pl, 2);

    v_dz_pl  := round(v_base_pl * v_dizimo_pct / 100.0, 2);
    v_inv_pl := round(v_base_pl * v_investimento_pct / 100.0, 2);
    v_esc_pl := round(v_base_pl * coalesce(v_escola_pct,0) / 100.0, 2);
    v_pl_pl  := greatest(v_base_pl - v_dz_pl - v_inv_pl - v_esc_pl, 0);

    v_dz_pr  := round(v_base_prof * v_prof_dizimo_pct / 100.0, 2);
    v_inv_pr := round(v_base_prof * v_prof_investimento_pct / 100.0, 2);
    v_pl_pr  := round(v_base_prof * v_prof_prolabore_pct / 100.0, 2);
    v_esc_pr := greatest(v_base_prof - v_dz_pr - v_inv_pr - v_pl_pr, 0);

    v_dizimo       := v_dz_pl + v_dz_pr;
    v_investimento := v_inv_pl + v_inv_pr;
    v_pro_labore   := v_pl_pl + v_pl_pr;
    v_sobra := round(v_liquido - v_dizimo - v_investimento - v_pro_labore, 2);

    if v_sobra < 0 then
      v_pro_labore := round(v_pro_labore + v_sobra, 2);
      v_sobra := 0;
    end if;
  end if;

  return jsonb_build_object(
    'payment_id',   v_pay.id,
    'tenant_id',    v_tenant,
    'is_active',    coalesce(v_ativo,false),
    'month',        v_mes,
    'paid_at',      v_pay.quando,
    'ref_date',     coalesce(v_pay.created_at, now())::date,
    'student_id',   v_pay.student_id,
    'student_name', coalesce(v_aluno, 'sem aluno vinculado'),
    'sem_aluno',    (v_pay.student_id is null),
    'sem_agenda',   (v_aulas = 0),
    'na_base',      v_na_base,
    'description',  v_pay.description,
    'valor',        round(coalesce(v_pay.value,0),2),
    'aulas_previstas', v_aulas,
    'aulas_pro_labore', v_aulas_pl,
    'custo_professor', round(coalesce(v_custo,0),2),
    'pro_labore',   round(coalesce(v_pro_labore,0),2),
    'professores',  v_professores,
    'liquido',      round(v_liquido,2),
    'dizimo_pct',   case when v_liquido > 0 then round(v_dizimo * 100.0 / v_liquido, 2) else v_dizimo_pct end,
    'investimento_pct', case when v_liquido > 0 then round(v_investimento * 100.0 / v_liquido, 2) else v_investimento_pct end,
    'escola_pct',   v_escola_pct,
    'regra',        case when v_share >= 1 then 'direcao'
                         when v_share <= 0 then 'professor'
                         else 'misto' end,
    'dizimo',       v_dizimo,
    'investimento', v_investimento,
    'sobra',        v_sobra);
end;
$$;


--
-- Name: FUNCTION payment_split_breakdown(p_payment_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.payment_split_breakdown(p_payment_id uuid) IS 'Rateio de um pagamento sobre o líquido (valor − salário previsto do professor). Duas réguas preservadas; workers internos sem claims vazios são aceitos com segurança.';


--
-- Name: payment_split_pending(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_split_pending() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  return coalesce((
    select pg_catalog.jsonb_agg(
             pg_catalog.jsonb_build_object(
               'payment_id', candidate.id,
               'tenant_id', candidate.tenant_id
             )
             order by candidate.cash_at desc, candidate.id
           )
      from (
        select
          payment.id,
          payment.tenant_id,
          coalesce(payment.credited_at, payment.paid_at) as cash_at
        from public.student_payments as payment
        join public.payment_split_settings as setting
          on setting.tenant_id = payment.tenant_id
         and setting.is_active
        where payment.status in ('RECEIVED', 'RECEIVED_IN_CASH')
          and coalesce(payment.value, 0) > 0
          and coalesce(payment.credited_at, payment.paid_at)
                >= (pg_catalog.now() - interval '2 days')
          and not exists (
            select 1
              from public.automation_sent as sent
             where sent.kind = 'PAYMENT_SPLIT'
               and sent.subject_id = payment.id::text
          )
        order by coalesce(payment.credited_at, payment.paid_at) desc, payment.id
        limit 30
      ) as candidate
  ), '[]'::jsonb);
end;
$$;


--
-- Name: FUNCTION payment_split_pending(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.payment_split_pending() IS 'Seleciona para rateio apenas pagamentos efetivamente recebidos, usando data real de credito/recebimento.';


--
-- Name: payment_split_report(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_split_report(p_month text DEFAULT NULL::text, p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  v_jwt_role text; v_caller_role text; v_tenant text; v_month text;
begin
  v_jwt_role := coalesce(
    nullif(btrim(current_setting('request.jwt.claims', true)), '')::jsonb ->> 'role',
    ''
  );
  select role, tenant_id into v_caller_role, v_tenant from profiles where id = auth.uid();
  if v_jwt_role in ('anon','authenticated') then
    if v_caller_role is null or v_caller_role not in ('SCHOOL_ADMIN','SUPER_ADMIN') then
      return jsonb_build_object('error','sem_permissao');
    end if;
    if v_caller_role = 'SUPER_ADMIN' then v_tenant := coalesce(p_tenant, v_tenant); end if;
  else
    v_tenant := coalesce(p_tenant, v_tenant);
  end if;
  if v_tenant is null then return jsonb_build_object('error','escola_nao_identificada'); end if;

  v_month := coalesce(p_month, to_char(current_date,'YYYY-MM'));
  if v_month !~ '^\d{4}-\d{2}$' then return jsonb_build_object('error','mes_invalido'); end if;

  return (
  with pagos as (
    select sp.id, coalesce(sp.paid_at, sp.payment_date, sp.due_date) as quando
      from student_payments sp
     where sp.tenant_id = v_tenant
       and sp.status in ('RECEIVED','RECEIVED_IN_CASH')
       and coalesce(sp.value,0) > 0
       and to_char(coalesce(sp.paid_at, sp.payment_date, sp.due_date),'YYYY-MM') = v_month
  ), rateado as (
    select p.quando, payment_split_breakdown(p.id) as b from pagos p
  )
  select jsonb_build_object(
    'month', v_month,
    'pagamentos', coalesce((
      select jsonb_agg(jsonb_build_object(
               'payment_id',      r.b->>'payment_id',
               'aluno',           r.b->>'student_name',
               'quando',          r.quando,
               'valor',           (r.b->>'valor')::numeric,
               'custo_professor', (r.b->>'custo_professor')::numeric,
               'pro_labore',      (r.b->>'pro_labore')::numeric,
               'professores',     r.b->'professores',
               'liquido',         (r.b->>'liquido')::numeric,
               'dizimo',          (r.b->>'dizimo')::numeric,
               'investimento',    (r.b->>'investimento')::numeric,
               'sobra',           (r.b->>'sobra')::numeric,
               'sem_aluno',       (r.b->>'sem_aluno')::boolean,
               'na_base',         (r.b->>'na_base')::boolean)
             order by r.quando desc)
        from rateado r), '[]'::jsonb),
    'totais', (select jsonb_build_object(
        'pagamentos',      count(*)::int,
        'recebido',        round(coalesce(sum((r.b->>'valor')::numeric),0),2),
        'custo_professor', round(coalesce(sum((r.b->>'custo_professor')::numeric),0),2),
        'pro_labore',      round(coalesce(sum((r.b->>'pro_labore')::numeric),0),2),
        'liquido',         round(coalesce(sum((r.b->>'liquido')::numeric)
                                   filter (where (r.b->>'na_base')::boolean),0),2),
        'dizimo',          round(coalesce(sum((r.b->>'dizimo')::numeric),0),2),
        'investimento',    round(coalesce(sum((r.b->>'investimento')::numeric),0),2),
        'sobra',           round(coalesce(sum((r.b->>'sobra')::numeric),0),2),
        'fora_da_base',    round(coalesce(sum((r.b->>'valor')::numeric)
                                   filter (where not (r.b->>'na_base')::boolean),0),2),
        'fora_da_base_n',  count(*) filter (where not (r.b->>'na_base')::boolean)::int
      ) from rateado r),
    'sem_aluno', (select count(*)::int from rateado r where (r.b->>'sem_aluno')::boolean)));
end;
$_$;


--
-- Name: FUNCTION payment_split_report(p_month text, p_tenant text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.payment_split_report(p_month text, p_tenant text) IS 'Rateio de todos os pagamentos do mês com os totais de dízimo e investimento. Aceita workers internos sem claims e usa payment_split_breakdown como regra única.';


--
-- Name: post_ad_spend(text, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_ad_spend(p_origem text, p_account_id text, p_periodo text, p_amount numeric, p_descricao text DEFAULT NULL::text, p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_jwt_role text; v_role text; v_tenant text; v_tx uuid; v_anterior numeric;
  v_desc text; v_data date; v_acao text;
BEGIN
  v_jwt_role := COALESCE(current_setting('request.jwt.claims', true)::json->>'role', '');
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_jwt_role IN ('anon','authenticated') THEN
    IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
      RETURN jsonb_build_object('error','sem_permissao');
    END IF;
    IF v_role = 'SUPER_ADMIN' THEN v_tenant := COALESCE(p_tenant, v_tenant); END IF;
  ELSE
    v_tenant := COALESCE(p_tenant, v_tenant);
  END IF;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('error','escola_nao_identificada'); END IF;

  IF COALESCE(btrim(p_origem),'') = '' OR COALESCE(btrim(p_account_id),'') = '' THEN
    RETURN jsonb_build_object('error','origem_ou_conta_obrigatoria');
  END IF;
  IF p_periodo IS NULL OR p_periodo !~ '^\d{4}-\d{2}$' THEN
    RETURN jsonb_build_object('error','periodo_invalido');
  END IF;
  IF p_amount IS NULL OR p_amount < 0 THEN
    RETURN jsonb_build_object('error','valor_invalido');
  END IF;

  v_desc := COALESCE(NULLIF(btrim(p_descricao),''),
                     'Anúncios ' || btrim(p_origem) || ' · conta ' || btrim(p_account_id));
  -- Último dia do período: o gasto do mês pertence ao mês, e datar no dia 1
  -- faria o lançamento parecer anterior às aulas que ele gerou.
  v_data := (date_trunc('month', (p_periodo || '-01')::date) + interval '1 month - 1 day')::date;

  SELECT i.transaction_id, i.amount INTO v_tx, v_anterior
    FROM ad_spend_imports i
   WHERE i.tenant_id = v_tenant AND i.origem = btrim(p_origem)
     AND i.account_id = btrim(p_account_id) AND i.periodo = p_periodo;

  IF v_tx IS NOT NULL THEN
    UPDATE financial_transactions
       SET amount = p_amount, amount_cents = round(p_amount * 100),
           description = v_desc, occurred_at = v_data::timestamptz,
           account_code = '6.1.03'
     WHERE id = v_tx;
    v_acao := CASE WHEN COALESCE(v_anterior,-1) = p_amount THEN 'inalterado' ELSE 'atualizado' END;
  ELSE
    INSERT INTO financial_transactions
      (tenant_id, type, category, amount, amount_cents, description, occurred_at, account_code)
    VALUES
      (v_tenant, 'SAIDA', 'anuncios', p_amount, round(p_amount * 100), v_desc,
       v_data::timestamptz, '6.1.03')
    RETURNING id INTO v_tx;
    v_acao := 'criado';
  END IF;

  INSERT INTO ad_spend_imports (tenant_id, origem, account_id, periodo, amount, transaction_id, imported_by)
  VALUES (v_tenant, btrim(p_origem), btrim(p_account_id), p_periodo, p_amount, v_tx, auth.uid())
  ON CONFLICT (tenant_id, origem, account_id, periodo) DO UPDATE
    SET amount = EXCLUDED.amount, transaction_id = EXCLUDED.transaction_id,
        imported_at = now(), imported_by = EXCLUDED.imported_by;

  RETURN jsonb_build_object('ok', true, 'acao', v_acao, 'periodo', p_periodo,
                            'valor', p_amount, 'valor_anterior', v_anterior,
                            'transaction_id', v_tx);
END;
$_$;


--
-- Name: FUNCTION post_ad_spend(p_origem text, p_account_id text, p_periodo text, p_amount numeric, p_descricao text, p_tenant text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.post_ad_spend(p_origem text, p_account_id text, p_periodo text, p_amount numeric, p_descricao text, p_tenant text) IS 'Lança (ou atualiza) o gasto de uma conta de anúncio no caixa como SAIDA em 6.1.03 Marketing. Reimportar o mesmo período sobrescreve o valor — gasto de mês em curso cresce, não duplica.';


--
-- Name: prepare_whatsapp_outbound(text, text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_whatsapp_outbound(p_tenant_id text, p_instance_name text, p_conversation_id uuid, p_actor_id uuid, p_client_request_id uuid, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_instance public.whatsapp_instances%rowtype;
  v_conversation public.whatsapp_conversations%rowtype;
  v_message public.whatsapp_messages%rowtype;
  v_body text := pg_catalog.btrim(coalesce(p_body, ''));
  v_duplicate boolean := false;
begin
  if p_conversation_id is null
     or p_client_request_id is null
     or nullif(pg_catalog.btrim(p_tenant_id), '') is null
     or nullif(pg_catalog.btrim(p_instance_name), '') is null
     or v_body = ''
     or char_length(v_body) > 4096 then
    raise exception 'invalid_whatsapp_outbound' using errcode = '22023';
  end if;

  if not private.whatsapp_inbox_actor_has_role(
    p_actor_id,
    p_tenant_id,
    array['SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR']::text[]
  ) then
    raise exception 'whatsapp_outbound_forbidden' using errcode = '42501';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'wa-client-request:' || p_tenant_id || ':' || p_client_request_id::text,
      0
    )
  );

  select instance.*
  into v_instance
  from public.whatsapp_instances as instance
  where instance.tenant_id = p_tenant_id
    and lower(instance.instance_name) = lower(pg_catalog.btrim(p_instance_name))
    and private.whatsapp_inbox_instance_is_eligible(
      instance.tenant_id,
      instance.id
    )
  for share;

  if not found then
    raise exception 'whatsapp_inbox_unavailable' using errcode = '42501';
  end if;

  select conversation.*
  into v_conversation
  from public.whatsapp_conversations as conversation
  where conversation.id = p_conversation_id
    and conversation.tenant_id = p_tenant_id
    and conversation.instance_id = v_instance.id
  for update;

  if not found then
    raise exception 'whatsapp_conversation_not_found' using errcode = 'P0002';
  end if;

  -- Revalida o destino depois de travar a conversa e antes de qualquer
  -- handoff ou INSERT. Assim, uma conversa de grupo preservada no historico
  -- nao autoriza envio depois que a direcao troca ou desliga o grupo.
  if not private.whatsapp_inbox_remote_jid_is_allowed(
    p_tenant_id,
    v_conversation.remote_jid
  ) then
    raise exception 'whatsapp_conversation_destination_unavailable'
      using errcode = '42501';
  end if;

  select message.*
  into v_message
  from public.whatsapp_messages as message
  where message.tenant_id = p_tenant_id
    and message.client_request_id = p_client_request_id
  for update;

  if found then
    if v_message.conversation_id <> v_conversation.id
       or v_message.instance_id <> v_instance.id
       or v_message.sent_by_user_id is distinct from p_actor_id
       or v_message.direction <> 'out'
       or v_message.sender_kind <> 'human'
       or v_message.body <> v_body then
      raise exception 'whatsapp_client_request_reused'
        using errcode = '22023';
    end if;
    v_duplicate := true;
  else
    update public.whatsapp_conversations as conversation
    set handoff_active = true,
        human_handoff_until = pg_catalog.now() + interval '72 hours',
        assigned_to = p_actor_id
    where conversation.id = v_conversation.id
      and conversation.tenant_id = p_tenant_id
    returning conversation.* into v_conversation;

    perform private.apply_whatsapp_contact_handoff(
      p_tenant_id,
      v_conversation.phone,
      true
    );

    insert into public.whatsapp_messages (
      tenant_id,
      instance_id,
      conversation_id,
      client_request_id,
      direction,
      sender_kind,
      message_type,
      body,
      status,
      occurred_at,
      sent_by_user_id,
      metadata
    )
    values (
      p_tenant_id,
      v_instance.id,
      v_conversation.id,
      p_client_request_id,
      'out',
      'human',
      'text',
      v_body,
      'queued',
      pg_catalog.now(),
      p_actor_id,
      '{"source":"web_inbox"}'::jsonb
    )
    returning * into v_message;

    update public.whatsapp_conversations as conversation
    set last_message_at = v_message.occurred_at,
        last_message_preview = left(v_body, 500),
        last_message_direction = 'out'
    where conversation.id = v_conversation.id
      and conversation.tenant_id = p_tenant_id;
  end if;

  return jsonb_build_object(
    'ok', true,
    'duplicate', v_duplicate,
    'messageId', v_message.id,
    'conversationId', v_conversation.id,
    'instanceId', v_instance.id,
    'instanceName', v_instance.instance_name,
    'remoteJid', v_conversation.remote_jid,
    'status', v_message.status
  );
end;
$$;


--
-- Name: prepare_wolfie_activity_session(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_wolfie_activity_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile_test_fixture boolean;
  v_source_subject text;
  v_source_phase text;
  v_source_status text;
  v_source_rehearsal_count integer;
begin
  if new.tenant_id is null or pg_catalog.btrim(new.tenant_id) = '' then
    raise exception 'student_active_tenant_required';
  end if;

  select coalesce(profile.is_test_account, false)
    into v_profile_test_fixture
    from public.profiles as profile
    join public.tenant_memberships as membership
      on membership.user_id = profile.id
     and membership.tenant_id = new.tenant_id
     and membership.status = 'ACTIVE'
     and membership.role = 'STUDENT'
   where profile.id = new.student_id
     and profile.role = 'STUDENT';

  if not found then
    raise exception 'student_active_tenant_membership_not_found';
  end if;

  new.test_fixture := v_profile_test_fixture;

  if new.phase = 'readaptation' then
    if new.subject <> 'global_meetings'
       or new.source_session_id is null
       or new.source_session_id = new.id then
      raise exception 'invalid_readaptation_source';
    end if;

    select
      source.subject,
      source.phase,
      source.status,
      case
        when pg_catalog.jsonb_typeof(
          source.learner_state #> '{memorization,rehearsalCount}'
        ) = 'number'
          then (
            source.learner_state #>> '{memorization,rehearsalCount}'
          )::integer
        else 0
      end
      into
        v_source_subject,
        v_source_phase,
        v_source_status,
        v_source_rehearsal_count
      from public.wolfie_activity_sessions as source
     where source.id = new.source_session_id
       and source.student_id = new.student_id
       and source.tenant_id = new.tenant_id;

    if not found
       or v_source_subject <> 'global_meetings'
       or v_source_phase <> 'construction'
       or v_source_status <> 'COMPLETED'
       or v_source_rehearsal_count < 1 then
      raise exception 'invalid_readaptation_source';
    end if;
  elsif new.source_session_id is not null then
    raise exception 'source_session_requires_readaptation';
  end if;

  return new;
end;
$$;


--
-- Name: prevent_contract_tampering(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_contract_tampering() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF OLD.contract_accepted = true THEN
        IF (NEW.contract_accepted IS DISTINCT FROM OLD.contract_accepted) OR
           (NEW.typed_signature IS DISTINCT FROM OLD.typed_signature) OR
           (NEW.signature_hash IS DISTINCT FROM OLD.signature_hash) THEN
               RAISE EXCEPTION 'Integrity Error: Signed contract data cannot be modified.';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: process_referral_reward(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_referral_reward(p_student uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s profiles%ROWTYPE;
  st tenant_referral_settings%ROWTYPE;
  v_ref uuid; v_role text; v_amount numeric; v_min int; v_paid int; v_credit uuid; v_month_count int;
BEGIN
  SELECT * INTO s FROM profiles WHERE id = p_student;
  IF NOT FOUND THEN RETURN; END IF;
  v_ref := COALESCE(s.referrer_student_id, s.referrer_teacher_id);
  IF v_ref IS NULL OR v_ref = p_student THEN RETURN; END IF;  -- sem indicador / auto-indicação

  SELECT * INTO st FROM tenant_referral_settings WHERE tenant_id = s.tenant_id;
  IF NOT FOUND OR st.enabled IS NOT TRUE THEN RETURN; END IF;  -- programa desligado

  -- já recompensado?
  IF EXISTS (SELECT 1 FROM referral_rewards WHERE referred_student_id = p_student) THEN RETURN; END IF;

  -- mínimo de pagamentos
  v_min := COALESCE(st.min_payments, 1);
  SELECT count(*) INTO v_paid FROM student_payments WHERE student_id = p_student AND status IN ('RECEIVED','RECEIVED_IN_CASH');
  IF v_paid < v_min THEN RETURN; END IF;

  -- papel + valor
  IF s.referrer_student_id IS NOT NULL THEN
    v_role := 'STUDENT'; v_amount := COALESCE(st.student_reward_brl, st.reward_amount_brl, 0);
  ELSE
    v_role := 'TEACHER'; v_amount := COALESCE(st.teacher_reward_brl, st.reward_amount_brl, 0);
  END IF;
  IF v_amount <= 0 THEN RETURN; END IF;

  -- teto mensal por indicador
  IF st.monthly_cap IS NOT NULL AND st.monthly_cap > 0 THEN
    SELECT count(*) INTO v_month_count FROM referral_rewards
     WHERE referrer_id = v_ref AND created_at >= date_trunc('month', now());
    IF v_month_count >= st.monthly_cap THEN RETURN; END IF;
  END IF;

  IF v_role = 'STUDENT' THEN
    INSERT INTO student_credits (student_id, tenant_id, amount, source, source_ref, expires_at)
    VALUES (v_ref, s.tenant_id, v_amount, 'REFERRAL', p_student::text,
            CASE WHEN st.reward_expires_days IS NOT NULL THEN now() + (st.reward_expires_days || ' days')::interval END)
    RETURNING id INTO v_credit;
    INSERT INTO referral_rewards (tenant_id, referrer_id, referrer_role, referred_student_id, amount_brl, status, credit_id)
    VALUES (s.tenant_id, v_ref, v_role, p_student, v_amount, 'CREDITED', v_credit);
  ELSE
    INSERT INTO referral_rewards (tenant_id, referrer_id, referrer_role, referred_student_id, amount_brl, status)
    VALUES (s.tenant_id, v_ref, v_role, p_student, v_amount, 'PENDING');
  END IF;
END;
$$;


--
-- Name: promote_prospect_to_student(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.promote_prospect_to_student(p_prospect_id uuid, p_payment_id text, p_auth_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_prospect RECORD;
    v_tent_enroll RECORD;
    v_signature RECORD;
    v_profile_id UUID;
    v_enrollment_id UUID;
    v_affiliate_code RECORD;
    v_conversion_id UUID;
    v_settings RECORD;
BEGIN
    -- 1. Lock and fetch prospect
    SELECT * INTO v_prospect FROM public.prospects
    WHERE id = p_prospect_id FOR UPDATE;

    IF v_prospect IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'PROSPECT_NOT_FOUND');
    END IF;

    -- Idempotency: already promoted
    IF v_prospect.promoted_at IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', true,
            'already_promoted', true,
            'profile_id', v_prospect.promoted_to_id
        );
    END IF;

    -- 2. Fetch tentative enrollment
    SELECT * INTO v_tent_enroll FROM public.tentative_enrollments
    WHERE prospect_id = p_prospect_id
      AND status IN ('SIGNED', 'PAYMENT_PENDING')
    ORDER BY created_at DESC LIMIT 1
    FOR UPDATE;

    IF v_tent_enroll IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'NO_TENTATIVE_ENROLLMENT');
    END IF;

    -- 3. Fetch signature
    SELECT * INTO v_signature FROM public.enrollment_signatures
    WHERE prospect_id = p_prospect_id
    ORDER BY signed_at DESC LIMIT 1;

    -- 4. Set profile_id from auth user
    v_profile_id := p_auth_user_id;

    INSERT INTO public.profiles (
        id, full_name, email, phone, role, tenant_id,
        monthly_fee, due_day, class_frequency,
        status_financial, guardian_id,
        created_at
    ) VALUES (
        v_profile_id,
        v_prospect.full_name,
        v_prospect.email,
        v_prospect.phone,
        'STUDENT',
        v_prospect.tenant_id,
        v_tent_enroll.monthly_fee,
        v_tent_enroll.due_day,
        v_tent_enroll.classes_per_week,
        'ACTIVE',
        CASE WHEN v_prospect.guardian_id IS NOT NULL THEN v_prospect.guardian_id ELSE NULL END,
        now()
    );

    -- 5. Update tentative enrollment
    UPDATE public.tentative_enrollments SET
        status = 'ENROLLED',
        converted_to_enrollment_id = v_profile_id,
        updated_at = now()
    WHERE id = v_tent_enroll.id;

    -- 6. Handle affiliate conversion
    IF v_prospect.referrer_code IS NOT NULL THEN
        SELECT * INTO v_affiliate_code FROM public.affiliate_codes
        WHERE code = v_prospect.referrer_code AND active = true;

        IF v_affiliate_code IS NOT NULL THEN
            -- Get tenant settings
            SELECT * INTO v_settings FROM public.tenant_referral_settings
            WHERE tenant_id = v_prospect.tenant_id;

            -- Anti-fraud: self-referral check
            IF v_affiliate_code.owner_id::text != v_profile_id::text THEN
                INSERT INTO public.affiliate_conversions (
                    affiliate_code_id, referrer_id, referred_id,
                    tenant_id, status, payment_id,
                    reward_amount_brl
                ) VALUES (
                    v_affiliate_code.id,
                    v_affiliate_code.owner_id,
                    v_profile_id,
                    v_prospect.tenant_id,
                    'PAYMENT_CONFIRMED',
                    p_payment_id,
                    COALESCE(v_settings.reward_amount_brl, 25.00)
                )
                ON CONFLICT (referred_id, tenant_id) DO NOTHING
                RETURNING id INTO v_conversion_id;

                -- Release reward if conversion was created
                IF v_conversion_id IS NOT NULL THEN
                    PERFORM public.release_affiliate_reward(v_conversion_id);
                END IF;
            END IF;
        END IF;
    END IF;

    -- 7. Mark prospect as promoted
    UPDATE public.prospects SET
        promoted_at = now(),
        promoted_to_id = v_profile_id,
        status = 'ENROLLED',
        updated_at = now()
    WHERE id = p_prospect_id;

    RETURN jsonb_build_object(
        'success', true,
        'profile_id', v_profile_id,
        'enrollment_id', v_tent_enroll.id,
        'conversion_id', v_conversion_id
    );
END;
$$;


--
-- Name: propagate_enrollment_test_fixture(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propagate_enrollment_test_fixture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_fixture_key text;
begin
  if new.kind <> 'ENROLLMENT'
     or new.processing_by is null
     or not coalesce((new.payload ->> 'testMode')::boolean, false) then
    return new;
  end if;

  v_fixture_key := coalesce(
    nullif(new.payload ->> 'testFixtureKey', ''),
    'wise-wolf-primary-student:' || new.id::text
  );

  update public.profiles
     set is_test_account = true,
         test_fixture_key = v_fixture_key
   where id = new.processing_by
     and role = 'STUDENT';

  return new;
end;
$$;


--
-- Name: protect_absence_active_coverages(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_absence_active_coverages() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_day record;
BEGIN
  IF TG_OP = 'UPDATE' AND NOT (
    NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    OR NEW.teacher_id IS DISTINCT FROM OLD.teacher_id
    OR NEW.starts_at IS DISTINCT FROM OLD.starts_at
    OR NEW.ends_at IS DISTINCT FROM OLD.ends_at
    OR NEW.status IS DISTINCT FROM OLD.status
  ) THEN
    RETURN NEW;
  END IF;

  IF TG_OP <> 'INSERT' AND EXISTS (
    SELECT 1
      FROM public.class_coverages AS coverage
     WHERE coverage.absence_id = OLD.id
       AND coverage.tenant_id = OLD.tenant_id
       AND (
         (
           pg_catalog.lower(coverage.status) = 'confirmed'
           AND coverage.class_log_id IS NULL
         )
         OR (
           pg_catalog.lower(coverage.status) = 'pending'
           AND pg_catalog.now() < coalesce(
             coverage.invite_expires_at,
             (
               coverage.class_date::text || ' ' ||
               pg_catalog.left(coverage.class_time, 5) || ':00-03'
             )::timestamptz
           )
         )
       )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23P01', MESSAGE = 'absence_has_active_coverages';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  IF pg_catalog.lower(coalesce(NEW.status, '')) <> 'active' THEN
    RETURN NEW;
  END IF;
  IF NEW.tenant_id IS NULL OR NEW.teacher_id IS NULL
     OR NEW.starts_at IS NULL OR NEW.ends_at IS NULL
     OR NEW.ends_at::date < NEW.starts_at::date
     OR NEW.ends_at::date > NEW.starts_at::date + 366 THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'active_absence_period_invalid';
  END IF;

  FOR v_day IN
    SELECT day_value::date AS absence_date
      FROM pg_catalog.generate_series(
        NEW.starts_at::date,
        NEW.ends_at::date,
        interval '1 day'
      ) AS day_value
     ORDER BY day_value
  LOOP
    IF NOT pg_catalog.pg_try_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'coverage-absence:' || NEW.teacher_id::text || ':' ||
        v_day.absence_date::text,
        0
      )
    ) THEN
      -- O UPDATE/DELETE já possui row lock quando o BEFORE ROW executa. Nunca
      -- espere por uma cobertura que pode estar esperando essa mesma linha:
      -- aborte como serialização e deixe o chamador tentar novamente.
      RAISE EXCEPTION USING
        ERRCODE = '40001', MESSAGE = 'coverage_absence_concurrent_change';
    END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1
      FROM public.class_coverages AS coverage
     WHERE coverage.tenant_id = NEW.tenant_id
       AND coverage.cover_teacher_id = NEW.teacher_id
       AND coverage.class_date BETWEEN NEW.starts_at::date AND NEW.ends_at::date
       AND (
         coverage.class_date::text || ' ' ||
         pg_catalog.left(coverage.class_time, 5) || ':00-03'
       )::timestamptz > pg_catalog.now()
       AND (
         pg_catalog.lower(coverage.status) = 'confirmed'
         OR (
           pg_catalog.lower(coverage.status) = 'pending'
           AND pg_catalog.now() < coalesce(
             coverage.invite_expires_at,
             (
               coverage.class_date::text || ' ' ||
               pg_catalog.left(coverage.class_time, 5) || ':00-03'
             )::timestamptz
           )
         )
       )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23P01', MESSAGE = 'absence_conflicts_with_active_coverage';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_active_teacher_transfer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_active_teacher_transfer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF upper(coalesce(NEW.status, '')) NOT IN ('PENDING', 'ACCEPTED') THEN
    RETURN NEW;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'teacher-transfer:' || NEW.tenant_id || ':' || NEW.student_id::text,
      0
    )
  );

  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles AS student
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = student.id
       AND membership.tenant_id = NEW.tenant_id
       AND membership.role = 'STUDENT'
       AND membership.status = 'ACTIVE'
     WHERE student.id = NEW.student_id
       AND student.role = 'STUDENT'
       AND student.tenant_id = NEW.tenant_id
       AND lower(coalesce(student.lifecycle_status, 'active'))
             NOT IN ('suspended', 'offboarded')
  ) OR NOT EXISTS (
    SELECT 1
      FROM public.profiles AS teacher
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = teacher.id
       AND membership.tenant_id = NEW.tenant_id
       AND membership.role = 'TEACHER'
       AND membership.status = 'ACTIVE'
     WHERE teacher.id = NEW.to_teacher_id
       AND teacher.role = 'TEACHER'
       AND teacher.tenant_id = NEW.tenant_id
       AND lower(coalesce(teacher.lifecycle_status, 'active'))
             NOT IN ('suspended', 'offboarded')
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514', MESSAGE = 'teacher_transfer_primary_tenant_required';
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.teacher_transfers AS competing
     WHERE competing.tenant_id = NEW.tenant_id
       AND competing.student_id = NEW.student_id
       AND competing.id IS DISTINCT FROM NEW.id
       AND upper(coalesce(competing.status, '')) IN ('PENDING', 'ACCEPTED')
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23505', MESSAGE = 'active_teacher_transfer_exists';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: protect_appointment_coverage_slot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_appointment_coverage_slot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_local_start timestamp;
  v_floor_slot timestamp;
  v_lock record;
BEGIN
  IF NEW.tenant_id IS NULL OR NEW.start_time IS NULL
     OR pg_catalog.lower(coalesce(NEW.status, ''))
          NOT IN ('scheduled', 'confirmed') THEN
    RETURN NEW;
  END IF;

  v_local_start := NEW.start_time AT TIME ZONE 'America/Sao_Paulo';
  v_floor_slot := pg_catalog.date_trunc('hour', v_local_start) +
    (pg_catalog.floor(extract(minute FROM v_local_start) / 30) * 30) *
      interval '1 minute';

  FOR v_lock IN
    SELECT DISTINCT teacher_id, slot
      FROM unnest(ARRAY[NEW.teacher_id, NEW.professor_id]) AS teacher(teacher_id)
      CROSS JOIN unnest(ARRAY[v_floor_slot, v_floor_slot + interval '30 minutes'])
        AS candidate(slot)
     WHERE teacher_id IS NOT NULL
     ORDER BY teacher_id, slot
  LOOP
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'schedule:teacher:' || v_lock.teacher_id::text || ':' ||
        public.fold_accents(CASE extract(dow FROM v_lock.slot)::integer
          WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Segunda' WHEN 2 THEN 'Terça'
          WHEN 3 THEN 'Quarta' WHEN 4 THEN 'Quinta' WHEN 5 THEN 'Sexta'
          WHEN 6 THEN 'Sábado'
        END) || ':' || pg_catalog.to_char(v_lock.slot, 'HH24:MI'),
        0
      )
    );
  END LOOP;

  IF EXISTS (
    SELECT 1
      FROM public.class_coverages AS coverage
     WHERE coverage.tenant_id = NEW.tenant_id
       AND coverage.cover_teacher_id IN (NEW.teacher_id, NEW.professor_id)
       AND pg_catalog.lower(coverage.status) IN ('pending', 'confirmed')
       AND (
         coverage.class_date::text || ' ' ||
         pg_catalog.left(coverage.class_time, 5) || ':00-03'
       )::timestamptz > pg_catalog.now()
       AND (
         pg_catalog.lower(coverage.status) = 'confirmed'
         OR pg_catalog.now() < coalesce(
           coverage.invite_expires_at,
           (
             coverage.class_date::text || ' ' ||
             pg_catalog.left(coverage.class_time, 5) || ':00-03'
           )::timestamptz
         )
       )
       AND pg_catalog.abs(extract(
             epoch FROM (
               NEW.start_time - (
                 coverage.class_date::text || ' ' ||
                 pg_catalog.left(coverage.class_time, 5) || ':00-03'
               )::timestamptz
             )
           )) < 1800
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23P01', MESSAGE = 'appointment_conflicts_with_active_coverage';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_booking_source_coverage(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_booking_source_coverage() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NOT (
    NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    OR NEW.teacher_id IS DISTINCT FROM OLD.teacher_id
    OR NEW.student_id IS DISTINCT FROM OLD.student_id
    OR NEW.day_of_week IS DISTINCT FROM OLD.day_of_week
    OR NEW.time_slot IS DISTINCT FROM OLD.time_slot
    OR NEW.date IS DISTINCT FROM OLD.date
    OR NEW.start_date IS DISTINCT FROM OLD.start_date
    OR NEW.status IS DISTINCT FROM OLD.status
  ) THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
     FROM public.class_coverages AS coverage
     WHERE coverage.booking_id = OLD.id
       AND coverage.tenant_id = OLD.tenant_id
       AND (
         (
           pg_catalog.lower(coverage.status) = 'confirmed'
           AND coverage.class_log_id IS NULL
         )
         OR (
           pg_catalog.lower(coverage.status) = 'pending'
           AND pg_catalog.now() < coalesce(
             coverage.invite_expires_at,
             (
               coverage.class_date::text || ' ' ||
               pg_catalog.left(coverage.class_time, 5) || ':00-03'
             )::timestamptz
           )
         )
       )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23P01', MESSAGE = 'booking_has_active_coverage';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: protect_management_action_execution(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_management_action_execution() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status = 'executing' THEN
      RAISE EXCEPTION USING
        ERRCODE = '55006', MESSAGE = 'management_action_in_progress';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.status = 'executing' THEN
    IF NEW.action_id IS DISTINCT FROM OLD.action_id
       OR NEW.request_id IS DISTINCT FROM OLD.request_id
       OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
       OR NEW.group_jid IS DISTINCT FROM OLD.group_jid
       OR NEW.tool_name IS DISTINCT FROM OLD.tool_name
       OR NEW.risk_level IS DISTINCT FROM OLD.risk_level
       OR NEW.schema_version IS DISTINCT FROM OLD.schema_version
       OR NEW.acao IS DISTINCT FROM OLD.acao
       OR NEW.requested_by_jid IS DISTINCT FROM OLD.requested_by_jid
       OR NEW.requested_by_user_id IS DISTINCT FROM OLD.requested_by_user_id
       OR NEW.confirmed_by_jid IS DISTINCT FROM OLD.confirmed_by_jid
       OR NEW.confirmed_by_user_id IS DISTINCT FROM OLD.confirmed_by_user_id
       OR NEW.confirmed_at IS DISTINCT FROM OLD.confirmed_at
       OR NEW.status NOT IN ('executing', 'succeeded', 'failed') THEN
      RAISE EXCEPTION USING
        ERRCODE = '55006', MESSAGE = 'management_action_in_progress';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: protect_reschedule_coverage_slot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_reschedule_coverage_slot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_date date;
  v_time text;
  v_day text;
BEGIN
  IF NEW.teacher_id IS NULL OR NEW.tenant_id IS NULL OR NEW.used_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  v_date := public.parse_lesson_date(NEW.date);
  v_time := pg_catalog.left(pg_catalog.btrim(NEW.time::text), 5);
  IF v_date IS NULL
     OR v_time !~ '^(0[0-9]|1[0-9]|2[0-3]):[0-5][0-9]$' THEN
    RETURN NEW;
  END IF;
  v_day := CASE extract(dow FROM v_date)::integer
    WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Segunda' WHEN 2 THEN 'Terça'
    WHEN 3 THEN 'Quarta' WHEN 4 THEN 'Quinta' WHEN 5 THEN 'Sexta'
    WHEN 6 THEN 'Sábado'
  END;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'schedule:teacher:' || NEW.teacher_id::text || ':' ||
      public.fold_accents(v_day) || ':' || v_time,
      0
    )
  );

  IF EXISTS (
    SELECT 1
      FROM public.class_coverages AS coverage
     WHERE coverage.tenant_id = NEW.tenant_id
       AND coverage.cover_teacher_id = NEW.teacher_id
       AND coverage.class_date = v_date
       AND pg_catalog.left(coverage.class_time, 5) = v_time
       AND (
         coverage.class_date::text || ' ' ||
         pg_catalog.left(coverage.class_time, 5) || ':00-03'
       )::timestamptz > pg_catalog.now()
       AND (
         pg_catalog.lower(coverage.status) = 'confirmed'
         OR (
           pg_catalog.lower(coverage.status) = 'pending'
           AND pg_catalog.now() < coalesce(
             coverage.invite_expires_at,
             (
               coverage.class_date::text || ' ' ||
               pg_catalog.left(coverage.class_time, 5) || ':00-03'
             )::timestamptz
           )
         )
       )
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23P01', MESSAGE = 'reschedule_conflicts_with_active_coverage';
  END IF;
  RETURN NEW;
END;
$_$;


--
-- Name: protect_student_sensitive_profile_fields(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_student_sensitive_profile_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF auth.uid() = NEW.id
       AND COALESCE(current_setting('app.enrollment_claim', true), '') <> '1' THEN
      NEW.role := 'STUDENT';
      NEW.tenant_id := NULL;
      NEW.monthly_fee := NULL;
      NEW.due_day := NULL;
      NEW.subscription_id := NULL;
      NEW.status_financial := 'PENDING';
      NEW.contract_accepted := false;
      NEW.accepted_at := NULL;
      NEW.class_frequency := NULL;
      NEW.professor_id := NULL;
      NEW.professor_id2 := NULL;
      NEW.enrollment_fee := 0;
      NEW.enrollment_fee_paid := true;
      NEW.enrollment_payment_id := NULL;
      NEW.asaas_customer_id := NULL;
      NEW.referrer_teacher_id := NULL;
      NEW.referrer_student_id := NULL;
    END IF;
    RETURN NEW;
  END IF;

  IF auth.uid() = OLD.id
     AND OLD.role = 'STUDENT'
     AND COALESCE(current_setting('app.enrollment_claim', true), '') <> '1'
     AND ROW(
       NEW.role,
       NEW.tenant_id,
       NEW.monthly_fee,
       NEW.due_day,
       NEW.subscription_id,
       NEW.status_financial,
       NEW.contract_accepted,
       NEW.accepted_at,
       NEW.class_frequency,
       NEW.professor_id,
       NEW.professor_id2,
       NEW.enrollment_fee,
       NEW.enrollment_fee_paid,
       NEW.enrollment_payment_id,
       NEW.asaas_customer_id,
       NEW.referrer_teacher_id,
       NEW.referrer_student_id
     ) IS DISTINCT FROM ROW(
       OLD.role,
       OLD.tenant_id,
       OLD.monthly_fee,
       OLD.due_day,
       OLD.subscription_id,
       OLD.status_financial,
       OLD.contract_accepted,
       OLD.accepted_at,
       OLD.class_frequency,
       OLD.professor_id,
       OLD.professor_id2,
       OLD.enrollment_fee,
       OLD.enrollment_fee_paid,
       OLD.enrollment_payment_id,
       OLD.asaas_customer_id,
       OLD.referrer_teacher_id,
       OLD.referrer_student_id
     ) THEN
    RAISE EXCEPTION 'forbidden: campos contratuais exigem fluxo autorizado';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: provision_paid_saas_checkout(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_paid_saas_checkout(p_checkout_id uuid, p_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  checkout public.saas_checkout_intents%ROWTYPE;
  selected_plan public.saas_plans%ROWTYPE;
  provisioned_tenant_id text;
  period_end timestamptz;
BEGIN
  SELECT *
  INTO checkout
  FROM public.saas_checkout_intents
  WHERE id = p_checkout_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'saas_checkout_not_found' USING ERRCODE = 'P0002';
  END IF;

  IF checkout.asaas_payment_id IS NOT NULL
     AND nullif(p_payment_id, '') IS NOT NULL
     AND checkout.asaas_payment_id <> p_payment_id THEN
    RAISE EXCEPTION 'saas_checkout_payment_mismatch' USING ERRCODE = '42501';
  END IF;

  IF checkout.status = 'PROVISIONED' AND checkout.tenant_id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'ok', true,
      'already_provisioned', true,
      'checkout_id', checkout.id,
      'tenant_id', checkout.tenant_id,
      'owner_name', checkout.owner_name,
      'owner_email', checkout.owner_email
    );
  END IF;

  IF checkout.status NOT IN (
    'PAID',
    'PROVISIONING',
    'PROVISIONING_FAILED'
  ) THEN
    RAISE EXCEPTION 'saas_checkout_payment_not_confirmed'
      USING ERRCODE = '55000';
  END IF;

  SELECT *
  INTO selected_plan
  FROM public.saas_plans AS plan
  WHERE plan.id = checkout.plan_id
    AND plan.active IS TRUE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'active_saas_plan_required' USING ERRCODE = '55000';
  END IF;

  UPDATE public.saas_checkout_intents
  SET status = 'PROVISIONING',
      asaas_payment_id = COALESCE(nullif(p_payment_id, ''), asaas_payment_id),
      last_error = NULL,
      updated_at = now()
  WHERE id = checkout.id;

  provisioned_tenant_id := COALESCE(checkout.tenant_id, checkout.tenant_slug);
  period_end := CASE
    WHEN checkout.billing_cycle = 'YEARLY' THEN now() + interval '1 year'
    ELSE now() + interval '1 month'
  END;

  IF checkout.tenant_id IS NULL THEN
    INSERT INTO public.tenants (
      id,
      name,
      slug,
      owner_email,
      owner_phone,
      owner_cpf_cnpj,
      saas_status,
      plan_id,
      current_period_end,
      branding,
      tenant_type
    )
    VALUES (
      provisioned_tenant_id,
      checkout.school_name,
      checkout.tenant_slug,
      checkout.owner_email,
      checkout.owner_phone,
      checkout.owner_cpf_cnpj,
      'active',
      selected_plan.id,
      period_end,
      jsonb_build_object(
        'primaryColor', '#081a33',
        'secondaryColor', '#d5a94e'
      ),
      selected_plan.plan_type
    );
  END IF;

  INSERT INTO public.saas_invoices (
    tenant_id,
    amount,
    status,
    due_date,
    paid_at,
    asaas_payment_id,
    invoice_number,
    plan_snapshot,
    billing_period_start,
    billing_period_end,
    period_month
  )
  VALUES (
    provisioned_tenant_id,
    checkout.amount,
    'PAID',
    COALESCE(checkout.due_date::timestamptz, now()),
    COALESCE(checkout.paid_at, now()),
    COALESCE(nullif(p_payment_id, ''), checkout.asaas_payment_id),
    'WW-' || to_char(now(), 'YYYYMM') || '-' || left(checkout.id::text, 8),
    to_jsonb(selected_plan),
    current_date,
    period_end::date,
    to_char(current_date, 'YYYY-MM')
  )
  ON CONFLICT (asaas_payment_id) WHERE asaas_payment_id IS NOT NULL
  DO UPDATE SET
    status = 'PAID',
    paid_at = COALESCE(public.saas_invoices.paid_at, EXCLUDED.paid_at),
    tenant_id = EXCLUDED.tenant_id;

  IF checkout.lead_id IS NOT NULL THEN
    UPDATE public.saas_leads
    SET status = 'CONVERTED',
        converted_tenant_id = provisioned_tenant_id,
        updated_at = now()
    WHERE id = checkout.lead_id;
  END IF;

  UPDATE public.saas_checkout_intents
  SET tenant_id = provisioned_tenant_id,
      paid_at = COALESCE(paid_at, now()),
      updated_at = now()
  WHERE id = checkout.id;

  RETURN jsonb_build_object(
    'ok', true,
    'already_provisioned', false,
    'checkout_id', checkout.id,
    'tenant_id', provisioned_tenant_id,
    'owner_name', checkout.owner_name,
    'owner_email', checkout.owner_email
  );
EXCEPTION
  WHEN OTHERS THEN
    IF checkout.id IS NOT NULL THEN
      UPDATE public.saas_checkout_intents
      SET status = 'PROVISIONING_FAILED',
          last_error = left(SQLERRM, 500),
          updated_at = now()
      WHERE id = checkout.id;
    END IF;
    RAISE;
END;
$$;


--
-- Name: provision_tenant_from_lead(uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.provision_tenant_from_lead(p_lead_id uuid, p_tenant_slug text, p_trial_days integer DEFAULT 14, p_plan_id text DEFAULT 'starter'::text) RETURNS TABLE(tenant_id text, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_lead saas_leads%ROWTYPE;
    v_tenant_id TEXT;
BEGIN
    -- Apenas super_admin pode provisionar
    IF (SELECT role FROM profiles WHERE id = auth.uid()) <> 'SUPER_ADMIN' THEN
        RAISE EXCEPTION 'Only SUPER_ADMIN can provision tenants';
    END IF;

    SELECT * INTO v_lead FROM saas_leads WHERE id = p_lead_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Lead not found'; END IF;
    IF v_lead.converted_tenant_id IS NOT NULL THEN
        RETURN QUERY SELECT v_lead.converted_tenant_id, 'ALREADY_CONVERTED'::TEXT;
        RETURN;
    END IF;

    v_tenant_id := COALESCE(p_tenant_slug, gen_random_uuid()::TEXT);

    INSERT INTO tenants (id, name, slug, owner_email, owner_phone, owner_cpf_cnpj,
        saas_status, plan_id, trial_ends_at, branding, created_at)
    VALUES (v_tenant_id, v_lead.school_name, p_tenant_slug, v_lead.owner_email, v_lead.owner_phone, v_lead.owner_cpf_cnpj,
        'TRIAL', p_plan_id, now() + (p_trial_days || ' days')::INTERVAL,
        '{"primaryColor":"#7c3aed"}'::jsonb, now());

    UPDATE saas_leads SET status = 'TRIAL', converted_tenant_id = v_tenant_id, updated_at = now()
    WHERE id = p_lead_id;

    RETURN QUERY SELECT v_tenant_id, 'PROVISIONED'::TEXT;
END;
$$;


--
-- Name: rate_attendance(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_attendance(p_token text, p_stars integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_requested public.attendance_confirmations%rowtype;
  c public.attendance_confirmations%rowtype;
  v_canonical_id uuid;
begin
  if p_stars < 1 or p_stars > 5 then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'estrelas_invalidas');
  end if;

  select ac.*
    into v_requested
    from public.attendance_confirmations ac
   where ac.token = p_token
   for update;

  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'token_invalido');
  end if;

  v_canonical_id := coalesce(v_requested.canonical_confirmation_id, v_requested.id);
  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = v_canonical_id
   for update;

  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'confirmacao_invalida');
  end if;

  perform 1
    from public.attendance_confirmations ac
   where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
   order by ac.id
   for update;

  if v_requested.token_expires_at is null
     or v_requested.token_expires_at <= pg_catalog.now() then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'token_expirado');
  end if;

  if c.status = 'CANCELLED' or c.delivery_status = 'CANCELLED' then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'confirmacao_cancelada');
  end if;

  if c.student_response is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'resposta_obrigatoria');
  end if;

  if c.student_response <> 'STUDENT_PRESENT' then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'avaliacao_nao_permitida');
  end if;

  if c.student_rating is not null then
    return pg_catalog.jsonb_build_object('ok', true, 'already', true);
  end if;

  update public.attendance_confirmations ac
     set student_rating = p_stars
   where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id;

  return pg_catalog.jsonb_build_object('ok', true, 'stars', p_stars);
end;
$$;


--
-- Name: reassign_student_teacher(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reassign_student_teacher(p_student_id uuid, p_new_teacher_id uuid, p_effective_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_role TEXT;
    v_my_tenant TEXT;
    v_updated INT;
BEGIN
    SELECT role, tenant_id INTO v_role, v_my_tenant FROM profiles WHERE id = auth.uid();
    IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RAISE EXCEPTION 'Apenas admin reatribui alunos'; END IF;

    -- Verifica que ambos os professores existem no tenant
    IF NOT EXISTS (SELECT 1 FROM profiles WHERE id = p_new_teacher_id AND role IN ('TEACHER','teacher') AND tenant_id = v_my_tenant) THEN
        RAISE EXCEPTION 'Novo professor não encontrado ou outro tenant';
    END IF;

    -- Atualizar bookings: trocar teacher_id em todos os bookings futuros do aluno
    UPDATE bookings SET teacher_id = p_new_teacher_id
    WHERE student_id = p_student_id
      AND tenant_id = v_my_tenant
      AND (start_date IS NULL OR start_date <= p_effective_date OR start_date IS NULL);
    GET DIAGNOSTICS v_updated = ROW_COUNT;

    -- Atualizar profiles.professor_id (link primário)
    UPDATE profiles SET professor_id = p_new_teacher_id WHERE id = p_student_id;

    RETURN jsonb_build_object(
        'status','OK',
        'bookings_updated', v_updated,
        'student_id', p_student_id,
        'new_teacher_id', p_new_teacher_id
    );
END;
$$;


--
-- Name: recompute_student_financial_status(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_student_financial_status(p_tenant_id text, p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_tenant text := nullif(
    pg_catalog.btrim(coalesce(p_tenant_id, '')),
    ''
  );
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if normalized_tenant is null or p_student_id is null then
    raise exception 'invalid_student_financial_scope' using errcode = '22023';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' ||
        p_student_id::text,
      0
    )
  );

  if exists (
       select 1 from public.student_offboarding_operations as operation
        where operation.tenant_id = normalized_tenant
          and operation.student_id = p_student_id
          and operation.status in (
            'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN'
          )
     ) or exists (
       select 1 from public.student_account_deletion_claims as deletion
        where deletion.tenant_id = normalized_tenant
          and deletion.student_id = p_student_id
          and deletion.status in (
            'CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE',
            'UNKNOWN', 'BLOCKED'
          )
     )
  then
    perform 1
      from public.profiles as profile
     where profile.id = p_student_id
       and profile.tenant_id = normalized_tenant
       and profile.role = 'STUDENT'
     for share;
    if not found then
      return public.recompute_student_financial_status_pre_lifecycle_impl(
        normalized_tenant,
        p_student_id
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'PRESERVED',
      'reason', 'student_lifecycle_operation_active'
    );
  end if;

  return public.recompute_student_financial_status_pre_lifecycle_impl(
    normalized_tenant,
    p_student_id
  );
end;
$$;


--
-- Name: recompute_student_financial_status_pre_lifecycle_impl(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_student_financial_status_pre_lifecycle_impl(p_tenant_id text, p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_tenant text := nullif(
    pg_catalog.btrim(coalesce(p_tenant_id, '')),
    ''
  );
  profile_row public.profiles%rowtype;
  controlling_due_date date;
  derived_status text;
  payment_snapshot jsonb;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if normalized_tenant is null or p_student_id is null then
    raise exception 'invalid_student_financial_scope' using errcode = '22023';
  end if;

  -- This row lock serializes different payment webhooks for one student. The
  -- payment snapshots themselves have already committed before this RPC runs.
  select profile.*
    into profile_row
    from public.profiles as profile
   where profile.id = p_student_id
   for update;

  if profile_row.id is null then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'PROFILE_MISSING'
    );
  end if;
  if profile_row.tenant_id is distinct from normalized_tenant
     or profile_row.role is distinct from 'STUDENT'
  then
    raise exception 'student_financial_scope_mismatch' using errcode = '42501';
  end if;
  if pg_catalog.lower(pg_catalog.btrim(coalesce(
       profile_row.lifecycle_status,
       ''
     ))) <> 'active'
     or pg_catalog.upper(pg_catalog.btrim(coalesce(
       profile_row.status_financial,
       ''
     ))) = 'ARCHIVED'
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'PRESERVED',
      'status', profile_row.status_financial
    );
  end if;

  select pg_catalog.max(payment.due_date)
    into controlling_due_date
    from public.student_payments as payment
   where payment.tenant_id = normalized_tenant
     and payment.student_id = p_student_id
     and payment.due_date is not null
     and payment.due_date <= current_date
     and pg_catalog.upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
       'OVERDUE',
       'RECEIVED',
       'RECEIVED_IN_CASH',
       'PAGO',
       'PAYMENT_RECEIVED',
       'PAYMENT_RECEIVED_IN_CASH',
       'REFUNDED',
       'REVERSED'
     );

  if controlling_due_date is null then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NO_MATURED_PAYMENT',
      'status', profile_row.status_financial
    );
  end if;

  select
    case
      -- Multiple legacy rows may share a competence. Never clear a proven
      -- outstanding charge merely because another row on that day settled.
      when pg_catalog.bool_or(
        pg_catalog.upper(pg_catalog.btrim(coalesce(payment.status, ''))) =
          'OVERDUE'
      ) then 'OVERDUE'
      when pg_catalog.bool_or(
        pg_catalog.upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
          'RECEIVED',
          'RECEIVED_IN_CASH',
          'PAGO',
          'PAYMENT_RECEIVED',
          'PAYMENT_RECEIVED_IN_CASH'
        )
      ) then 'ACTIVE'
      when pg_catalog.bool_or(
        pg_catalog.upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
          'REFUNDED',
          'REVERSED'
        )
      ) then 'PENDING'
      -- CREATED/CONFIRMED/PENDING and the manual NAO_RECEITA accounting
      -- classification are not proof that a tuition payment granted access.
      else null
    end,
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'id', payment.id,
        'providerPaymentId', payment.asaas_payment_id,
        'status', payment.status,
        'providerStatus', payment.provider_status
      ) order by payment.id
    )
    into derived_status, payment_snapshot
    from public.student_payments as payment
   where payment.tenant_id = normalized_tenant
     and payment.student_id = p_student_id
     and payment.due_date = controlling_due_date;

  if derived_status is null then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NO_DECISIVE_CHANGE',
      'status', profile_row.status_financial,
      'controlling_due_date', controlling_due_date
    );
  end if;

  if pg_catalog.upper(pg_catalog.btrim(coalesce(
       profile_row.status_financial,
       ''
     ))) = derived_status
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'UNCHANGED',
      'status', derived_status,
      'controlling_due_date', controlling_due_date
    );
  end if;

  insert into public.student_financial_status_audit (
    tenant_id,
    student_id,
    previous_status,
    derived_status,
    controlling_due_date,
    payment_snapshot
  ) values (
    normalized_tenant,
    p_student_id,
    profile_row.status_financial,
    derived_status,
    controlling_due_date,
    coalesce(payment_snapshot, '[]'::jsonb)
  );

  update public.profiles as profile
     set status_financial = derived_status
   where profile.id = p_student_id
     and profile.tenant_id = normalized_tenant
     and profile.role = 'STUDENT'
     and pg_catalog.lower(pg_catalog.btrim(coalesce(
       profile.lifecycle_status,
       ''
     ))) = 'active'
     and pg_catalog.upper(pg_catalog.btrim(coalesce(
       profile.status_financial,
       ''
     ))) <> 'ARCHIVED';

  if not found then
    raise exception 'student_financial_profile_changed_during_recompute'
      using errcode = '40001';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'UPDATED',
    'status', derived_status,
    'controlling_due_date', controlling_due_date
  );
end;
$$;


--
-- Name: reconcile_attendance_confirmation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_attendance_confirmation(p_conf_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  requested public.attendance_confirmations%rowtype;
  c public.attendance_confirmations%rowtype;
  v_canonical_id uuid;
  v_status text;
  v_hold boolean := false;
  v_has_log boolean := false;
  v_has_payable_log boolean := false;
  v_all_teacher_absence boolean := false;
  v_has_completed boolean := false;
  v_has_student_absence boolean := false;
  v_reported text;
  v_msg text;
  v_schedule_at timestamptz;
begin
  select ac.*
    into requested
    from public.attendance_confirmations ac
   where ac.id = p_conf_id
   for update;
  if not found then return; end if;

  v_canonical_id := coalesce(requested.canonical_confirmation_id, requested.id);
  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = v_canonical_id
   for update;
  if not found then return; end if;

  perform 1
    from public.attendance_confirmations ac
   where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
   order by ac.id
   for update;

  if c.status in ('RESOLVED_PAID', 'RESOLVED_UNPAID') then
    perform private.apply_final_attendance_resolution(v_canonical_id);
    return;
  end if;

  with members as (
    select ac.*
      from public.attendance_confirmations ac
     where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
  ), logs as (
    select distinct cl.*
      from public.class_logs cl
     where cl.tenant_id = c.tenant_id
       and cl.teacher_id = c.teacher_id
       and cl.student_id is not distinct from c.student_id
       and cl.class_date = c.class_date
       and exists (
         select 1
           from members m
          where m.class_log_id = cl.id
             or (m.source_type = 'booking' and m.source_id = cl.booking_id)
             or (m.source_type = 'reschedule' and m.source_id = cl.reschedule_id)
             or (m.source_type = 'appointment' and m.source_id = cl.appointment_id)
       )
  )
  select
    count(*) > 0,
    coalesce(bool_or(l.presence not in ('TEACHER_ABSENCE', 'Falta do Professor')), false),
    coalesce(bool_and(l.presence in ('TEACHER_ABSENCE', 'Falta do Professor')), false),
    coalesce(bool_or(l.presence = 'COMPLETED'), false),
    coalesce(bool_or(l.presence in ('STUDENT_ABSENCE', 'Falta Justificada')), false),
    (array_agg(l.presence order by
      case l.presence
        when 'COMPLETED' then 1
        when 'STUDENT_ABSENCE' then 2
        when 'Falta Justificada' then 3
        when 'TEACHER_ABSENCE' then 4
        else 5
      end,
      l.created_at desc
    ))[1]
  into
    v_has_log,
    v_has_payable_log,
    v_all_teacher_absence,
    v_has_completed,
    v_has_student_absence,
    v_reported
  from logs l;

  if c.student_response is null and not v_has_log then
    v_status := 'PENDING';
  elsif c.student_response is not null and not v_has_log then
    v_status := 'AWAITING_TEACHER';
  elsif c.student_response is null and v_has_log then
    v_status := 'PENDING';
  elsif c.student_response = 'TEACHER_NO_SHOW' and v_has_payable_log then
    v_status := 'CONFLICT';
    v_hold := true;
  elsif c.student_response = 'TEACHER_NO_SHOW' then
    v_status := 'CONFIRMED';
  elsif c.student_response = 'STUDENT_PRESENT'
        and v_has_completed
        and not v_has_student_absence
        and not v_all_teacher_absence then
    v_status := 'CONFIRMED';
  elsif c.student_response = 'STUDENT_SELF_ABSENT'
        and v_has_student_absence
        and not v_has_completed
        and not v_all_teacher_absence then
    v_status := 'CONFIRMED';
  elsif c.student_response = 'CANCELLED_RESCHEDULED'
        and v_all_teacher_absence then
    v_status := 'CONFIRMED';
  else
    v_status := 'ATTENDANCE_MISMATCH';
  end if;

  -- Link each member to its exact financial slot while assigning the same
  -- session-level outcome to every member.
  update public.attendance_confirmations ac
     set class_log_id = coalesce((
           select cl.id
             from public.class_logs cl
            where cl.tenant_id = ac.tenant_id
              and cl.teacher_id = ac.teacher_id
              and cl.student_id is not distinct from ac.student_id
              and cl.class_date = ac.class_date
              and (
                cl.id = ac.class_log_id
                or (ac.source_type = 'booking' and ac.source_id = cl.booking_id)
                or (ac.source_type = 'reschedule' and ac.source_id = cl.reschedule_id)
                or (ac.source_type = 'appointment' and ac.source_id = cl.appointment_id)
              )
            order by (cl.id = ac.class_log_id) desc, cl.created_at desc, cl.id
            limit 1
         ), ac.class_log_id),
         teacher_reported = coalesce((
           select cl.presence
             from public.class_logs cl
            where cl.tenant_id = ac.tenant_id
              and cl.teacher_id = ac.teacher_id
              and cl.student_id is not distinct from ac.student_id
              and cl.class_date = ac.class_date
              and (
                cl.id = ac.class_log_id
                or (ac.source_type = 'booking' and ac.source_id = cl.booking_id)
                or (ac.source_type = 'reschedule' and ac.source_id = cl.reschedule_id)
                or (ac.source_type = 'appointment' and ac.source_id = cl.appointment_id)
              )
            order by (cl.id = ac.class_log_id) desc, cl.created_at desc, cl.id
            limit 1
         ), v_reported, ac.teacher_reported),
         status = v_status
   where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id;

  with members as (
    select ac.*
      from public.attendance_confirmations ac
     where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
  )
  update public.class_logs cl
     set verification_status = v_status,
         payment_hold = v_hold,
         student_confirmed = c.student_response is not null
   where cl.tenant_id = c.tenant_id
     and cl.teacher_id = c.teacher_id
     and cl.student_id is not distinct from c.student_id
     and cl.class_date = c.class_date
     and exists (
       select 1
         from members m
        where m.class_log_id = cl.id
           or (m.source_type = 'booking' and m.source_id = cl.booking_id)
           or (m.source_type = 'reschedule' and m.source_id = cl.reschedule_id)
           or (m.source_type = 'appointment' and m.source_id = cl.appointment_id)
     );

  if v_status <> 'CONFLICT' then
    update public.notification_queue nq
       set status = 'skipped',
           updated_at = now(),
           last_error = 'attendance_conflict_withdrawn_before_send'
     where nq.notification_kind = 'CONFLICT_TEACHER_ALERT'
       and nq.status = 'pending'
       and nq.source_id in (
         select ac.id
           from public.attendance_confirmations ac
          where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
       );
  end if;

  -- A hard alert is delayed until the answer can no longer be corrected. This
  -- prevents a transient tap from notifying or penalizing the teacher twice.
  if v_status = 'CONFLICT'
     and c.teacher_id is not null
     and c.tenant_id is not null then
    v_schedule_at := greatest(
      now(),
      coalesce(c.response_editable_until, now() + interval '30 minutes')
    );
    v_msg :=
      'Oi, ' || coalesce(nullif(split_part(c.teacher_name, ' ', 1), ''), 'professor') ||
      '! Aqui e da coordenacao da escola.' || E'\n\n' ||
      'Recebemos uma divergencia sobre a aula de ' ||
      to_char(c.class_date, 'DD/MM') ||
      coalesce(' as ' || left(c.class_time, 5), '') ||
      ' com ' || coalesce(c.student_name, 'o(a) aluno(a)') || '.' || E'\n' ||
      'Pode nos contar como foi essa aula? Enquanto analisamos, somente esta aula fica em revisao.';

    update public.notification_queue nq
       set status = 'pending',
           scheduled_for = v_schedule_at,
           message_body = v_msg,
           attempts = 0,
           last_error = null,
           updated_at = now()
     where nq.notification_kind = 'CONFLICT_TEACHER_ALERT'
       and nq.status = 'skipped'
       and nq.last_error in (
         'attendance_conflict_withdrawn_before_send',
         'attendance_conflict_resolved_before_send'
       )
       and nq.source_id in (
         select ac.id
           from public.attendance_confirmations ac
          where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
       );

    insert into public.notification_queue (
      tenant_id, teacher_id, student_id, student_name, student_phone,
      message_body, scheduled_for, status, source_id, source_type,
      class_date, notification_kind
    )
    select
      c.tenant_id,
      null,
      c.student_id,
      c.teacher_name,
      p.phone,
      v_msg,
      v_schedule_at,
      'pending',
      v_canonical_id,
      'attendance_confirmation',
      c.class_date,
      'CONFLICT_TEACHER_ALERT'
    from public.profiles p
    where p.id = c.teacher_id
      and p.tenant_id = c.tenant_id
      and p.role = 'TEACHER'
      and lower(btrim(p.lifecycle_status)) = 'active'
      and exists (
        select 1
          from public.tenant_memberships membership
         where membership.user_id = p.id
           and membership.tenant_id = c.tenant_id
           and membership.role = 'TEACHER'
           and membership.status = 'ACTIVE'
      )
      and coalesce(p.phone, '') <> ''
      and not exists (
        select 1
          from public.notification_queue nq
         where nq.notification_kind = 'CONFLICT_TEACHER_ALERT'
           and nq.source_id in (
             select ac.id
               from public.attendance_confirmations ac
              where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
           )
      );
  end if;
end;
$$;


--
-- Name: reconcile_student_payment_ledger(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_student_payment_ledger(p_limit integer DEFAULT 100, p_after_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_payment record;
  v_limit integer;
  v_processed integer := 0;
  v_inserted integer := 0;
  v_delta integer := 0;
  v_flags_corrected integer := 0;
  v_last_id uuid := null;
  v_has_more boolean := false;
  v_lock_acquired boolean;
  v_gross_amount numeric;
begin
  v_limit := greatest(1, least(coalesce(p_limit, 100), 1000));

  select pg_try_advisory_xact_lock(
    hashtextextended('wise-wolf:reconcile-student-payment-ledger', 0)
  ) into v_lock_acquired;

  if not v_lock_acquired then
    return jsonb_build_object(
      'busy', true,
      'processed', 0,
      'inserted', 0,
      'flags_corrected', 0,
      'next_after_id', null,
      'has_more', false
    );
  end if;

  for v_payment in
    select sp.*
      from public.student_payments sp
     where (
         sp.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'NAO_RECEITA')
         or (sp.status = 'REFUNDED' and sp.credited_at is not null)
       )
       and sp.tenant_id is not null
       and coalesce(sp.value, 0) > 0
       and (p_after_id is null or sp.id > p_after_id)
       and not exists (
         select 1
           from public.financial_transactions ft
          where ft.student_payment_id = sp.id
       )
     order by sp.id
     limit v_limit
     for update of sp
  loop
    v_processed := v_processed + 1;
    v_last_id := v_payment.id;
    v_gross_amount := round(coalesce(v_payment.value, 0), 2);

    insert into public.financial_transactions (
      tenant_id,
      type,
      category,
      amount,
      amount_cents,
      student_payment_id,
      reference_id,
      occurred_at,
      description,
      created_at
    ) values (
      v_payment.tenant_id,
      'ENTRADA',
      case
        when v_payment.status = 'NAO_RECEITA' then 'aporte_ou_movimentacao'
        else 'MENSALIDADE'
      end,
      v_gross_amount,
      round(v_gross_amount * 100)::integer,
      v_payment.id,
      v_payment.student_id,
      coalesce(
        v_payment.credited_at,
        v_payment.paid_at,
        v_payment.payment_date + interval '12 hours',
        v_payment.due_date + interval '12 hours',
        now()
      ),
      case
        when v_payment.status = 'NAO_RECEITA' then 'Movimentacao nao operacional (reconciliacao)'
        else 'Mensalidade (reconciliacao)'
      end,
      now()
    )
    on conflict (student_payment_id) where student_payment_id is not null
    do nothing;

    get diagnostics v_delta = row_count;
    v_inserted := v_inserted + v_delta;
  end loop;

  with ledger_state as (
    select
      sp.id,
      exists (
        select 1
          from public.financial_transactions ft
         where ft.student_payment_id = sp.id
      ) as has_ledger
    from public.student_payments sp
  ), corrected as (
    update public.student_payments sp
       set ledger_entry_created = ls.has_ledger
      from ledger_state ls
     where ls.id = sp.id
       and sp.ledger_entry_created is distinct from ls.has_ledger
    returning 1
  )
  select count(*) into v_flags_corrected from corrected;

  if v_last_id is not null then
    select exists (
      select 1
        from public.student_payments sp
       where (
           sp.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'NAO_RECEITA')
           or (sp.status = 'REFUNDED' and sp.credited_at is not null)
         )
         and sp.tenant_id is not null
         and coalesce(sp.value, 0) > 0
         and sp.id > v_last_id
         and not exists (
           select 1
             from public.financial_transactions ft
            where ft.student_payment_id = sp.id
         )
    ) into v_has_more;
  end if;

  return jsonb_build_object(
    'busy', false,
    'processed', v_processed,
    'inserted', v_inserted,
    'flags_corrected', v_flags_corrected,
    'next_after_id', v_last_id,
    'has_more', v_has_more
  );
end;
$$;


--
-- Name: FUNCTION reconcile_student_payment_ledger(p_limit integer, p_after_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reconcile_student_payment_ledger(p_limit integer, p_after_id uuid) IS 'Recria em paginas ENTRADAS brutas comprovadas sem ledger usando NOT EXISTS; nunca sintetiza SAIDAS historicas de estorno, serializa concorrencia e corrige a flag pela existencia real.';


--
-- Name: reconcile_whatsapp_provider_delivery(text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_whatsapp_provider_delivery(p_tenant_id text, p_instance_name text, p_provider_message_id text, p_provider_status text, p_occurred_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  v_instance_name text := lower(pg_catalog.btrim(coalesce(p_instance_name, '')));
  v_provider_message_id text := pg_catalog.btrim(
    coalesce(p_provider_message_id, '')
  );
  v_provider_status text := lower(
    pg_catalog.btrim(coalesce(p_provider_status, ''))
  );
  v_occurred_at timestamptz := coalesce(p_occurred_at, now());
  v_notification public.notification_queue%rowtype;
  v_discovered_notification public.notification_queue%rowtype;
  v_receipt private.whatsapp_provider_delivery_receipts%rowtype;
  v_outbound public.asaas_outbound_message_attempts%rowtype;
  v_discovered_outbound public.asaas_outbound_message_attempts%rowtype;
  v_merged text;
  v_outbound_merged text;
  v_financial_scope_locked boolean := false;
begin
  if v_tenant_id is null
     or char_length(v_instance_name) not between 3 and 120
     or char_length(v_provider_message_id) not between 1 and 320
     or v_provider_status not in (
       'accepted', 'sent', 'delivered', 'read', 'failed', 'uncertain'
     )
     or v_occurred_at < timestamptz '2000-01-01 00:00:00+00'
     or v_occurred_at > now() + interval '1 day' then
    raise exception 'invalid_whatsapp_provider_delivery'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from public.whatsapp_instances as instance
    where instance.tenant_id = v_tenant_id
      and lower(instance.instance_name) = v_instance_name
  ) then
    raise exception 'whatsapp_provider_instance_not_found'
      using errcode = 'P0002';
  end if;

  -- Discover a possible financial fence without taking row locks. When one is
  -- visible, its lifecycle advisory must precede the provider advisory and the
  -- attempt/queue row locks. This is the same global order used by offboarding,
  -- deletion, payment reversal and the paired delivery bridge.
  select notification.*
  into v_discovered_notification
  from public.notification_queue as notification
  where notification.tenant_id = v_tenant_id
    and lower(notification.provider_instance_name) = v_instance_name
    and notification.provider_message_id = v_provider_message_id;

  if found then
    select outbound.*
    into v_discovered_outbound
    from public.asaas_outbound_message_attempts as outbound
    where (
        outbound.notification_queue_id = v_discovered_notification.id
        or (
          outbound.notification_queue_id is null
          and outbound.tenant_id = v_discovered_notification.tenant_id
          and outbound.student_id = v_discovered_notification.student_id
          and outbound.provider_entity_id =
            v_discovered_notification.source_id::text
          and upper(pg_catalog.btrim(coalesce(
            outbound.notification_kind,
            ''
          ))) = 'PAYMENT_CONFIRMED_WHATSAPP'
          and private.canonical_payment_notification_kind(
            v_discovered_notification.notification_kind
          ) = 'PAYMENT_CONFIRMED_WHATSAPP'
        )
      )
    order by (outbound.notification_queue_id =
      v_discovered_notification.id) desc
    limit 1;

    if found then
      perform pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended(
          'student-billing-lifecycle:' || v_discovered_outbound.tenant_id ||
          ':' || v_discovered_outbound.student_id::text,
          0
        )
      );
      v_financial_scope_locked := true;
    end if;
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'notification-provider:' || v_tenant_id || ':' || v_instance_name || ':' ||
      v_provider_message_id,
      0
    )
  );

  if v_financial_scope_locked then
    select outbound.*
    into v_outbound
    from public.asaas_outbound_message_attempts as outbound
    where outbound.id = v_discovered_outbound.id
    for update;
  end if;

  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.tenant_id = v_tenant_id
    and lower(notification.provider_instance_name) = v_instance_name
    and notification.provider_message_id = v_provider_message_id
  for update;

  insert into private.whatsapp_provider_delivery_receipts as receipt (
    tenant_id,
    provider_instance_name,
    provider_message_id,
    delivery_status,
    accepted_at,
    sent_at,
    delivered_at,
    read_at,
    first_seen_at,
    last_seen_at
  ) values (
    v_tenant_id,
    v_instance_name,
    v_provider_message_id,
    v_provider_status,
    case when v_provider_status in ('accepted', 'sent', 'delivered', 'read')
      then v_occurred_at end,
    case when v_provider_status in ('sent', 'delivered', 'read')
      then v_occurred_at end,
    case when v_provider_status in ('delivered', 'read')
      then v_occurred_at end,
    case when v_provider_status = 'read' then v_occurred_at end,
    v_occurred_at,
    v_occurred_at
  )
  on conflict (tenant_id, provider_instance_name, provider_message_id)
  do update set
    delivery_status = private.merge_notification_delivery_status(
      receipt.delivery_status,
      excluded.delivery_status
    ),
    accepted_at = case
      when excluded.accepted_at is null then receipt.accepted_at
      else least(coalesce(receipt.accepted_at, excluded.accepted_at), excluded.accepted_at)
    end,
    sent_at = case
      when excluded.sent_at is null then receipt.sent_at
      else least(coalesce(receipt.sent_at, excluded.sent_at), excluded.sent_at)
    end,
    delivered_at = case
      when excluded.delivered_at is null then receipt.delivered_at
      else least(
        coalesce(receipt.delivered_at, excluded.delivered_at),
        excluded.delivered_at
      )
    end,
    read_at = case
      when excluded.read_at is null then receipt.read_at
      else least(coalesce(receipt.read_at, excluded.read_at), excluded.read_at)
    end,
    first_seen_at = least(receipt.first_seen_at, excluded.first_seen_at),
    last_seen_at = greatest(receipt.last_seen_at, excluded.last_seen_at),
    updated_at = now()
  returning receipt.* into v_receipt;

  if v_notification.id is not null then
    v_merged := private.merge_notification_delivery_status(
      v_notification.delivery_status,
      v_receipt.delivery_status
    );

    update public.notification_queue as notification
    set delivery_status = v_merged,
        status = case
          when v_merged in ('accepted', 'sent', 'delivered', 'read') then 'sent'
          when v_merged in ('failed', 'uncertain') then 'failed'
          else notification.status
        end,
        accepted_at = case
          when v_receipt.accepted_at is null then notification.accepted_at
          else least(
            coalesce(notification.accepted_at, v_receipt.accepted_at),
            v_receipt.accepted_at
          )
        end,
        sent_at = case
          when v_receipt.sent_at is null then notification.sent_at
          else least(
            coalesce(notification.sent_at, v_receipt.sent_at),
            v_receipt.sent_at
          )
        end,
        delivered_at = case
          when v_receipt.delivered_at is null then notification.delivered_at
          else least(
            coalesce(notification.delivered_at, v_receipt.delivered_at),
            v_receipt.delivered_at
          )
        end,
        read_at = case
          when v_receipt.read_at is null then notification.read_at
          else least(
            coalesce(notification.read_at, v_receipt.read_at),
            v_receipt.read_at
          )
        end,
        dead_letter_at = case
          when v_merged in ('failed', 'uncertain')
            then coalesce(notification.dead_letter_at, now())
          when v_merged in ('accepted', 'sent', 'delivered', 'read') then null
          else notification.dead_letter_at
        end,
        last_error = case
          when v_merged in ('accepted', 'sent', 'delivered', 'read') then null
          when v_merged = 'failed' then coalesce(
            notification.last_error,
            'provider_reported_failed'
          )
          when v_merged = 'uncertain' then coalesce(
            notification.last_error,
            'provider_delivery_uncertain'
          )
          else notification.last_error
        end,
        claim_token = null,
        lease_expires_at = null,
        updated_at = now()
    where notification.id = v_notification.id
    returning notification.* into v_notification;

    update private.whatsapp_provider_delivery_receipts as receipt
    set notification_id = coalesce(receipt.notification_id, v_notification.id),
        updated_at = now()
    where receipt.id = v_receipt.id
      and (
        receipt.notification_id is null
        or receipt.notification_id = v_notification.id
      );

    -- If the financial row was visible during discovery it is already locked
    -- in lifecycle -> provider -> attempt -> queue order. Never discover and
    -- lock a new attempt after locking the queue: a concurrent lifecycle
    -- operation uses the opposite order and would deadlock.
    if v_outbound.id is not null then
      if v_outbound.notification_queue_id is not null
         and v_outbound.notification_queue_id <> v_notification.id then
        raise exception 'financial_outbound_queue_identity_mismatch'
          using errcode = '23514';
      end if;

      if v_outbound.tenant_id is distinct from v_notification.tenant_id
         or v_outbound.student_id is distinct from v_notification.student_id
         or v_notification.source_id is null
         or v_outbound.provider_entity_id is distinct from
           v_notification.source_id::text
         or upper(pg_catalog.btrim(coalesce(
           v_notification.source_type,
           ''
         ))) <> 'ASAAS_PAYMENT'
         or upper(pg_catalog.btrim(coalesce(
           v_outbound.notification_kind,
           ''
         ))) <> 'PAYMENT_CONFIRMED_WHATSAPP'
         or private.canonical_payment_notification_kind(
           v_notification.notification_kind
         ) <> 'PAYMENT_CONFIRMED_WHATSAPP' then
        raise exception 'financial_outbound_queue_binding_mismatch'
          using errcode = '23514';
      end if;

      if (
        v_outbound.provider_instance_name is not null
        and lower(v_outbound.provider_instance_name) <> v_instance_name
      ) or (
        v_outbound.provider_message_id is not null
        and v_outbound.provider_message_id <> v_provider_message_id
      ) then
        raise exception 'financial_outbound_provider_identity_mismatch'
          using errcode = '23514';
      end if;

      v_outbound_merged := private.merge_notification_delivery_status(
        coalesce(
          v_outbound.provider_delivery_status,
          case v_outbound.status
            when 'SENT' then 'accepted'
            when 'FAILED' then 'failed'
            when 'UNKNOWN' then 'uncertain'
            else 'queued'
          end
        ),
        v_receipt.delivery_status
      );

      update public.asaas_outbound_message_attempts as outbound
      set notification_queue_id = coalesce(
            outbound.notification_queue_id,
            v_notification.id
          ),
          provider_instance_name = coalesce(
            outbound.provider_instance_name,
            v_notification.provider_instance_name
          ),
          provider_message_id = coalesce(
            outbound.provider_message_id,
            v_provider_message_id
          ),
          provider_delivery_status = v_outbound_merged,
          status = case
            when v_outbound_merged in (
              'accepted', 'sent', 'delivered', 'read'
            ) then 'SENT'
            when v_outbound_merged = 'failed' then 'FAILED'
            when v_outbound_merged = 'uncertain' then 'UNKNOWN'
            else outbound.status
          end,
          submit_attempt_count = case
            when v_outbound_merged in (
              'accepted', 'sent', 'delivered', 'read', 'failed', 'uncertain'
            ) then 1
            else outbound.submit_attempt_count
          end,
          lease_expires_at = now(),
          last_error = case
            when v_outbound_merged in (
              'accepted', 'sent', 'delivered', 'read'
            ) then null
            when v_outbound_merged = 'failed' then coalesce(
              outbound.last_error,
              'provider_reported_failed'
            )
            when v_outbound_merged = 'uncertain' then coalesce(
              outbound.last_error,
              'provider_delivery_uncertain'
            )
            else outbound.last_error
          end,
          updated_at = now()
      where outbound.id = v_outbound.id
        and outbound.status <> 'SUPPRESSED'
      returning outbound.* into v_outbound;
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'matched', v_notification.id is not null,
    'notificationId', v_notification.id,
    'financialAttemptId', v_outbound.id,
    'financialStatus', v_outbound.status,
    'providerStatus', v_receipt.delivery_status,
    'providerMessageId', v_receipt.provider_message_id
  );
end;
$$;


--
-- Name: record_asaas_provider_creation_state(uuid, uuid, text, text, text, integer, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_asaas_provider_creation_state(p_attempt_id uuid, p_claim_token uuid, p_status text, p_provider_entity_id text DEFAULT NULL::text, p_provider_status text DEFAULT NULL::text, p_http_status integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text, p_provider_response jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.asaas_provider_creation_attempts%rowtype;
  normalized_status text := upper(trim(coalesce(p_status, '')));
  normalized_provider_id text := nullif(trim(coalesce(
    p_provider_entity_id,
    ''
  )), '');
  delay_seconds integer;
begin
  if normalized_status not in (
    'RETRY', 'UNKNOWN', 'SUCCEEDED', 'FAILED', 'BLOCKED'
  ) then
    raise exception using
      errcode = '22023',
      message = 'invalid_asaas_creation_state';
  end if;

  select attempt.*
    into attempt_row
    from public.asaas_provider_creation_attempts as attempt
   where attempt.id = p_attempt_id
   for update;

  if not found or attempt_row.claim_token is distinct from p_claim_token then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  if attempt_row.status = 'SUCCEEDED' then
    return jsonb_build_object(
      'ok', normalized_status = 'SUCCEEDED'
        and attempt_row.provider_entity_id is not distinct from normalized_provider_id,
      'status', attempt_row.status,
      'provider_entity_id', attempt_row.provider_entity_id,
      'ignored_regression', normalized_status <> 'SUCCEEDED'
    );
  end if;

  if normalized_status = 'SUCCEEDED' and normalized_provider_id is null then
    raise exception using
      errcode = '22023',
      message = 'provider_entity_id_required';
  end if;

  if normalized_status = 'RETRY'
     and (
       attempt_row.status <> 'CLAIMED'
       or attempt_row.submit_attempt_count <> 0
     )
  then
    return jsonb_build_object('ok', false, 'reason', 'unsafe_retry_rejected');
  end if;

  if normalized_status in ('UNKNOWN', 'FAILED')
     and attempt_row.submit_attempt_count <> 1
  then
    return jsonb_build_object('ok', false, 'reason', 'submit_not_started');
  end if;

  if normalized_status = 'FAILED' and attempt_row.status <> 'SUBMITTING' then
    return jsonb_build_object('ok', false, 'reason', 'invalid_state_transition');
  end if;

  delay_seconds := least(
    3600,
    greatest(
      15,
      (power(2, least(attempt_row.reconciliation_count + 1, 8)) * 15)::integer
    )
  );

  update public.asaas_provider_creation_attempts
     set status = normalized_status,
         provider_entity_id = case
           when normalized_status = 'SUCCEEDED' then normalized_provider_id
           else provider_entity_id
         end,
         provider_status = coalesce(
           nullif(trim(coalesce(p_provider_status, '')), ''),
           provider_status
         ),
         last_http_status = p_http_status,
         last_error = nullif(left(coalesce(p_error, ''), 500), ''),
         provider_response = coalesce(p_provider_response, provider_response),
         lease_expires_at = now(),
         next_attempt_at = case
           when normalized_status in ('RETRY', 'UNKNOWN')
             then now() + make_interval(secs => delay_seconds)
           else now()
         end,
         reconciliation_count = reconciliation_count + case
           when normalized_status = 'UNKNOWN' then 1 else 0
         end,
         reconciled_at = case
           when attempt_row.status = 'UNKNOWN'
             or normalized_status = 'UNKNOWN'
             or (
               normalized_status = 'SUCCEEDED'
               and attempt_row.status <> 'SUBMITTING'
             )
             then now()
           else reconciled_at
         end,
         completed_at = case
           when normalized_status = 'SUCCEEDED' then now()
           else completed_at
         end,
         updated_at = now()
   where id = p_attempt_id;

  if normalized_status in ('UNKNOWN', 'FAILED', 'BLOCKED') then
    insert into public.asaas_reconciliation_issues (
      tenant_id,
      source,
      kind,
      severity,
      provider_entity_id,
      local_entity_id,
      fingerprint,
      details
    ) values (
      attempt_row.tenant_id,
      'CREATION_GUARD',
      'ASAAS_CREATION_' || normalized_status,
      case
        when normalized_status in ('UNKNOWN', 'BLOCKED') then 'CRITICAL'
        else 'HIGH'
      end,
      normalized_provider_id,
      attempt_row.id::text,
      'asaas-creation:' || attempt_row.id::text,
      jsonb_build_object(
        'operation', attempt_row.operation,
        'logicalKey', attempt_row.logical_key,
        'httpStatus', p_http_status,
        'error', left(coalesce(p_error, 'unknown'), 500)
      )
    ) on conflict do nothing;
  elsif normalized_status = 'SUCCEEDED' then
    update public.asaas_reconciliation_issues
       set resolved_at = coalesce(resolved_at, now()),
           resolution_note = coalesce(
             resolution_note,
             'provider entity recovered by creation guard'
           )
     where source = 'CREATION_GUARD'
       and fingerprint = 'asaas-creation:' || attempt_row.id::text
       and resolved_at is null;
  end if;

  return jsonb_build_object(
    'ok', true,
    'status', normalized_status,
    'attempt_id', p_attempt_id,
    'provider_entity_id', normalized_provider_id,
    'retry_after_seconds', case
      when normalized_status in ('RETRY', 'UNKNOWN') then delay_seconds
      else null
    end
  );
end;
$$;


--
-- Name: record_asaas_student_billing_period_state(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_asaas_student_billing_period_state(p_attempt_id uuid, p_claim_token uuid, p_status text, p_provider_entity_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  claim_row public.asaas_student_billing_period_claims%rowtype;
  normalized_status text := upper(pg_catalog.btrim(coalesce(p_status, '')));
  normalized_provider_id text := nullif(pg_catalog.btrim(coalesce(p_provider_entity_id, '')), '');
begin
  if normalized_status not in ('RETRY', 'UNKNOWN', 'BOUND', 'FAILED', 'BLOCKED') then
    raise exception using errcode = '22023', message = 'invalid_student_billing_period_state';
  end if;
  select billing_claim.* into claim_row
    from public.asaas_student_billing_period_claims as billing_claim
   where billing_claim.id = p_attempt_id
   for update;
  if not found or claim_row.claim_token is distinct from p_claim_token then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;
  if claim_row.status = 'BOUND' then
    return pg_catalog.jsonb_build_object(
      'ok', normalized_status = 'BOUND'
        and claim_row.provider_entity_id is not distinct from normalized_provider_id,
      'status', claim_row.status,
      'provider_entity_id', claim_row.provider_entity_id,
      'ignored_regression', normalized_status <> 'BOUND'
    );
  end if;
  if normalized_status = 'BOUND' and normalized_provider_id is null then
    raise exception using errcode = '22023', message = 'billing_period_provider_id_required';
  end if;
  if normalized_status = 'RETRY'
     and (claim_row.status <> 'CLAIMED' or claim_row.submit_attempt_count <> 0)
  then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'unsafe_retry_rejected');
  end if;
  if normalized_status in ('UNKNOWN', 'FAILED')
     and (claim_row.status <> 'SUBMITTING' or claim_row.submit_attempt_count <> 1)
  then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'submit_not_started');
  end if;
  if claim_row.provider_entity_id is not null
     and normalized_provider_id is not null
     and claim_row.provider_entity_id is distinct from normalized_provider_id
  then
    return pg_catalog.jsonb_build_object('ok', false, 'reason', 'provider_entity_id_mismatch');
  end if;

  update public.asaas_student_billing_period_claims
     set status = normalized_status,
         provider_entity_id = case
           when normalized_status = 'BOUND' then normalized_provider_id
           else provider_entity_id
         end,
         last_error = nullif(pg_catalog.left(coalesce(p_error, ''), 500), ''),
         lease_expires_at = now(),
         updated_at = now()
   where id = claim_row.id;
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'status', normalized_status,
    'provider_entity_id', normalized_provider_id
  );
end;
$$;


--
-- Name: record_asaas_teacher_transfer_state(uuid, uuid, text, text, text, integer, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_asaas_teacher_transfer_state(p_attempt_id uuid, p_claim_token uuid, p_status text, p_provider_transfer_id text DEFAULT NULL::text, p_provider_status text DEFAULT NULL::text, p_http_status integer DEFAULT NULL::integer, p_error text DEFAULT NULL::text, p_provider_response jsonb DEFAULT NULL::jsonb, p_destination_fingerprint text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.asaas_teacher_transfer_attempts%rowtype;
  attempt_closing_id uuid;
  normalized_status text := upper(trim(coalesce(p_status, '')));
  normalized_provider_transfer_id text := nullif(
    trim(coalesce(p_provider_transfer_id, '')),
    ''
  );
  attempt_provider_transfer_id text;
  closing_provider_transfer_id text;
  persisted_provider_transfer_id text;
  effective_provider_transfer_id text;
  closing_status text;
  closing_update_count integer := 0;
  teacher_nf_exempt boolean := false;
begin
  if normalized_status not in ('SUBMITTED', 'COMPLETED', 'FAILED', 'UNKNOWN', 'BLOCKED') then
    raise exception using errcode = '22023', message = 'invalid_transfer_attempt_status';
  end if;

  if p_provider_transfer_id is not null
     and normalized_provider_transfer_id is null
  then
    return jsonb_build_object('ok', false, 'reason', 'provider_transfer_id_invalid');
  end if;

  select attempt.closing_id into attempt_closing_id
    from public.asaas_teacher_transfer_attempts as attempt
   where attempt.id = p_attempt_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  -- The claim RPC locks the closing before the attempt. Keep the same lock
  -- order here so reconciliation cannot deadlock against a concurrent claim.
  select
    nullif(trim(coalesce(closing.asaas_transfer_id, '')), ''),
    coalesce(teacher.nf_exempt, false)
    into closing_provider_transfer_id, teacher_nf_exempt
    from public.teacher_closings as closing
    join public.profiles as teacher on teacher.id = closing.teacher_id
   where closing.id = attempt_closing_id
   for update of closing;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'closing_not_found');
  end if;

  select attempt.* into attempt_row
    from public.asaas_teacher_transfer_attempts as attempt
   where attempt.id = p_attempt_id
     and attempt.closing_id = attempt_closing_id
   for update;
  if not found or attempt_row.claim_token is distinct from p_claim_token then
    return jsonb_build_object('ok', false, 'reason', 'claim_lost');
  end if;

  attempt_provider_transfer_id := nullif(
    trim(coalesce(attempt_row.provider_transfer_id, '')),
    ''
  );

  if attempt_provider_transfer_id is not null
     and closing_provider_transfer_id is not null
     and attempt_provider_transfer_id is distinct from closing_provider_transfer_id
  then
    insert into public.asaas_reconciliation_issues (
      tenant_id, source, kind, severity, provider_entity_id,
      local_entity_id, fingerprint, details
    ) values (
      attempt_row.tenant_id,
      'TRANSFER',
      'TEACHER_TRANSFER_PROVIDER_ID_MISMATCH',
      'CRITICAL',
      attempt_provider_transfer_id,
      attempt_row.closing_id::text,
      'teacher-transfer:' || attempt_row.id::text || ':provider-id-mismatch',
      jsonb_build_object(
        'attemptId', attempt_row.id,
        'externalReference', attempt_row.external_reference,
        'attemptProviderTransferId', attempt_provider_transfer_id,
        'closingProviderTransferId', closing_provider_transfer_id,
        'incomingProviderTransferId', normalized_provider_transfer_id
      )
    ) on conflict do nothing;

    return jsonb_build_object(
      'ok', false,
      'reason', 'closing_provider_transfer_id_mismatch',
      'status', attempt_row.status
    );
  end if;

  persisted_provider_transfer_id := coalesce(
    attempt_provider_transfer_id,
    closing_provider_transfer_id
  );
  if persisted_provider_transfer_id is not null
     and normalized_provider_transfer_id is not null
     and normalized_provider_transfer_id is distinct from persisted_provider_transfer_id
  then
    return jsonb_build_object(
      'ok', false,
      'reason', 'provider_transfer_id_mismatch',
      'status', attempt_row.status
    );
  end if;
  effective_provider_transfer_id := coalesce(
    persisted_provider_transfer_id,
    normalized_provider_transfer_id
  );

  if normalized_status in ('SUBMITTED', 'COMPLETED')
     and effective_provider_transfer_id is null
  then
    return jsonb_build_object(
      'ok', false,
      'reason', 'provider_transfer_id_required',
      'status', attempt_row.status
    );
  end if;

  if attempt_row.status = 'COMPLETED' and normalized_status <> 'COMPLETED' then
    return jsonb_build_object('ok', true, 'status', 'COMPLETED', 'ignored_regression', true);
  end if;

  if normalized_status in ('SUBMITTED', 'COMPLETED')
     and p_destination_fingerprint is null
  then
    return jsonb_build_object(
      'ok', false,
      'reason', 'provider_destination_fingerprint_required',
      'status', attempt_row.status
    );
  end if;

  if p_destination_fingerprint is not null
     and attempt_row.destination_fingerprint is distinct from p_destination_fingerprint
  then
    return jsonb_build_object('ok', false, 'reason', 'destination_snapshot_mismatch');
  end if;

  update public.asaas_teacher_transfer_attempts
     set status = normalized_status,
         provider_transfer_id = effective_provider_transfer_id,
         provider_status = coalesce(p_provider_status, provider_status),
         last_http_status = p_http_status,
         last_error = nullif(left(coalesce(p_error, ''), 500), ''),
         provider_response = coalesce(p_provider_response, provider_response),
         submit_attempt_count = case
           when attempt_row.status = 'CLAIMED' and normalized_status in ('SUBMITTED', 'COMPLETED', 'UNKNOWN', 'FAILED')
             then 1
           else submit_attempt_count
         end,
         reconciliation_count = reconciliation_count + case
           when attempt_row.status in ('SUBMITTED', 'UNKNOWN') then 1 else 0 end,
         submitted_at = case
           when normalized_status in ('SUBMITTED', 'COMPLETED') then coalesce(submitted_at, now())
           else submitted_at
         end,
         reconciled_at = case
           when attempt_row.status in ('SUBMITTED', 'UNKNOWN') then now()
           else reconciled_at
         end,
         completed_at = case when normalized_status = 'COMPLETED' then now() else completed_at end,
         updated_at = now()
   where id = p_attempt_id;

  if normalized_status in ('SUBMITTED', 'COMPLETED')
     and effective_provider_transfer_id is not null
  then
    closing_status := case
      when normalized_status = 'COMPLETED' then
        case when teacher_nf_exempt
          then 'PAGO' else 'PAID_WAITING_NF' end
      else 'UNDER_REVIEW'
    end;

    update public.teacher_closings as closing
       set asaas_transfer_id = effective_provider_transfer_id,
           transfer_status = coalesce(p_provider_status, normalized_status),
           status = closing_status,
           paid_at = case when normalized_status = 'COMPLETED' then coalesce(closing.paid_at, now()) else closing.paid_at end,
           updated_at = now()
     where closing.id = attempt_row.closing_id
       and (
         closing.asaas_transfer_id is null
         or closing.asaas_transfer_id = effective_provider_transfer_id
       );

    get diagnostics closing_update_count = row_count;
    if closing_update_count <> 1 then
      raise exception 'teacher_closing_transfer_update_failed';
    end if;
  end if;

  if normalized_status in ('UNKNOWN', 'FAILED', 'BLOCKED') then
    insert into public.asaas_reconciliation_issues (
      tenant_id, source, kind, severity, provider_entity_id,
      local_entity_id, fingerprint, details
    ) values (
      attempt_row.tenant_id,
      'TRANSFER',
      'TEACHER_TRANSFER_' || normalized_status,
      case when normalized_status = 'UNKNOWN' then 'CRITICAL' else 'HIGH' end,
      effective_provider_transfer_id,
      attempt_row.closing_id::text,
      'teacher-transfer:' || attempt_row.id::text || ':' || normalized_status,
      jsonb_build_object(
        'attemptId', attempt_row.id,
        'externalReference', attempt_row.external_reference,
        'httpStatus', p_http_status,
        'error', left(coalesce(p_error, 'unknown'), 500)
      )
    ) on conflict do nothing;
  end if;

  return jsonb_build_object(
    'ok', true,
    'status', normalized_status,
    'provider_transfer_id', effective_provider_transfer_id
  );
end;
$$;


--
-- Name: record_student_account_deletion_provider_state(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_student_account_deletion_provider_state(p_claim_id uuid, p_claim_token uuid, p_resource text, p_outcome text, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_resource text := lower(trim(coalesce(p_resource, '')));
  normalized_outcome text := upper(trim(coalesce(p_outcome, '')));
  changed_id uuid;
begin
  if normalized_resource not in ('subscription', 'customer')
     or normalized_outcome not in ('STARTED', 'DELETED', 'ABSENT', 'UNKNOWN', 'FAILED')
  then
    raise exception using errcode = '22023', message = 'invalid_deletion_provider_state';
  end if;

  update public.student_account_deletion_claims
     set status = case
           when status = 'PROVIDER_COMPLETE' then 'PROVIDER_COMPLETE'
           when normalized_outcome in ('UNKNOWN', 'FAILED') then 'UNKNOWN'
           when (
             (normalized_resource = 'subscription' or subscription_deleted)
             and (normalized_resource = 'customer' or customer_deleted)
             and normalized_outcome in ('DELETED', 'ABSENT')
           ) then 'PROVIDER_COMPLETE'
           else 'PROVIDER_MUTATING'
         end,
         subscription_deleted = subscription_deleted or (
           normalized_resource = 'subscription' and normalized_outcome in ('DELETED', 'ABSENT')
         ),
         customer_deleted = customer_deleted or (
           normalized_resource = 'customer' and normalized_outcome in ('DELETED', 'ABSENT')
         ),
         provider_started_at = coalesce(provider_started_at, now()),
         provider_completed_at = case
           when status = 'PROVIDER_COMPLETE' then provider_completed_at
           when (
             (subscription_deleted or (normalized_resource = 'subscription' and normalized_outcome in ('DELETED', 'ABSENT')))
             and (customer_deleted or (normalized_resource = 'customer' and normalized_outcome in ('DELETED', 'ABSENT')))
           ) then now()
           else provider_completed_at
         end,
         last_error = case
           when status = 'PROVIDER_COMPLETE' then last_error
           else nullif(left(coalesce(p_error, ''), 500), '')
         end,
         updated_at = now()
   where id = p_claim_id
     and claim_token = p_claim_token
     and integration_snapshot <> '{}'::jsonb
     and status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN')
   returning id into changed_id;
  return jsonb_build_object('ok', changed_id is not null, 'reason', case when changed_id is null then 'claim_lost' else null end);
end;
$$;


--
-- Name: record_student_offboarding_provider_state(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_student_offboarding_provider_state(p_operation_id uuid, p_claim_token uuid, p_status text, p_error text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_status text := upper(trim(coalesce(p_status, '')));
  changed_id uuid;
begin
  if normalized_status not in ('MUTATING', 'COMPLETE', 'UNKNOWN') then
    raise exception using errcode = '22023', message = 'invalid_offboarding_provider_state';
  end if;
  update public.student_offboarding_operations
     set status = case
           when status = 'PROVIDER_COMPLETE' then 'PROVIDER_COMPLETE'
           when normalized_status = 'MUTATING' then 'PROVIDER_MUTATING'
           when normalized_status = 'COMPLETE' then 'PROVIDER_COMPLETE'
           else 'UNKNOWN'
         end,
         provider_started_at = coalesce(provider_started_at, now()),
         provider_completed_at = case
           when status = 'PROVIDER_COMPLETE' then provider_completed_at
           when normalized_status = 'COMPLETE' then now()
           else provider_completed_at
         end,
         last_error = case
           when status = 'PROVIDER_COMPLETE' then last_error
           else nullif(left(coalesce(p_error, ''), 500), '')
         end,
         updated_at = now()
   where id = p_operation_id
     and claim_token = p_claim_token
     and integration_snapshot <> '{}'::jsonb
     and status in ('CLAIMED', 'PROVIDER_MUTATING', 'PROVIDER_COMPLETE', 'UNKNOWN')
   returning id into changed_id;
  return jsonb_build_object('ok', changed_id is not null, 'reason', case when changed_id is null then 'claim_lost' else null end);
end;
$$;


--
-- Name: record_student_renewal_action(uuid, date, text, integer, uuid, text, timestamp with time zone, timestamp with time zone, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_student_renewal_action(p_student_id uuid, p_service_end_date date, p_action text, p_expected_version integer, p_request_id uuid, p_channel text DEFAULT NULL::text, p_contact_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_next_action_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_interest_term_months integer DEFAULT NULL::integer, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  actor_role text;
  actor_tenant text;
  actor_profile public.profiles%rowtype;
  actor_membership public.tenant_memberships%rowtype;
  student public.profiles%rowtype;
  student_membership public.tenant_memberships%rowtype;
  current_case public.student_renewal_cases%rowtype;
  replay_event public.student_renewal_case_events%rowtype;
  normalized_action text := pg_catalog.upper(
    pg_catalog.btrim(coalesce(p_action, ''))
  );
  normalized_channel text := nullif(
    pg_catalog.upper(pg_catalog.btrim(coalesce(p_channel, ''))),
    ''
  );
  normalized_note text := nullif(
    pg_catalog.btrim(coalesce(p_note, '')),
    ''
  );
  normalized_note_hash text;
  request_envelope jsonb;
  request_fingerprint text;
  source_service_end date;
  case_found boolean := false;
  current_status text;
  current_version integer;
  current_last_contact timestamptz;
  current_channel text;
  current_follow_up timestamptz;
  current_interest smallint;
  previous_status text;
  next_status text;
  next_last_contact timestamptz;
  next_channel text;
  next_follow_up timestamptz;
  next_interest smallint;
  effective_contact timestamptz;
  new_event_id uuid := pg_catalog.gen_random_uuid();
  actor_name_snapshot text;
begin
  if actor_id is null
     or p_student_id is null
     or p_service_end_date is null
     or p_request_id is null
     or p_expected_version is null
     or p_expected_version < 0
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'invalid_request'
    );
  end if;

  if normalized_action not in (
    'CONTACTED',
    'SCHEDULE_FOLLOW_UP',
    'RECORD_INTEREST',
    'AWAIT_FORMALIZATION',
    'RECORD_NOT_CONTINUING',
    'REOPEN'
  ) or (normalized_note is not null and pg_catalog.char_length(normalized_note) > 500)
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'invalid_action_payload'
    );
  end if;

  -- Reject irrelevant fields instead of silently changing the canonical
  -- request.  This makes a request_id identify one exact semantic action.
  if (normalized_action = 'CONTACTED' and (
        normalized_channel is null
        or normalized_channel not in ('WHATSAPP', 'PHONE', 'EMAIL', 'OTHER')
        or p_interest_term_months is not null
      ))
     or (normalized_action = 'SCHEDULE_FOLLOW_UP' and (
        normalized_channel is not null
        or p_contact_at is not null
        or p_next_action_at is null
        or p_interest_term_months is not null
      ))
     or (normalized_action = 'RECORD_INTEREST' and (
        normalized_channel is not null
        or p_contact_at is not null
        or p_next_action_at is not null
        or p_interest_term_months is null
        or p_interest_term_months not in (6, 12)
      ))
     or (normalized_action = 'AWAIT_FORMALIZATION' and (
        normalized_channel is not null
        or p_contact_at is not null
        or p_interest_term_months is not null
      ))
     or (normalized_action in ('RECORD_NOT_CONTINUING', 'REOPEN') and (
        normalized_channel is not null
        or p_contact_at is not null
        or p_next_action_at is not null
        or p_interest_term_months is not null
      ))
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'invalid_action_payload'
    );
  end if;

  actor_tenant := private.active_tenant_id(actor_id);
  actor_role := private.active_tenant_role(actor_id);
  if actor_tenant is null
     or actor_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN')
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'forbidden'
    );
  end if;

  if not private.tenant_is_operational(actor_tenant) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'tenant_not_operational'
    );
  end if;

  -- Keep the authority used by this command stable until commit.  The helper
  -- values are revalidated after locking the canonical profile/membership.
  select profile.*
    into actor_profile
    from public.profiles as profile
   where profile.id = actor_id
     and pg_catalog.lower(pg_catalog.btrim(coalesce(
       profile.lifecycle_status,
       ''
     ))) = 'active'
   for no key update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'forbidden'
    );
  end if;

  select membership.*
    into actor_membership
    from public.tenant_memberships as membership
   where membership.user_id = actor_id
     and membership.tenant_id = actor_tenant
     and membership.status = 'ACTIVE'
   for no key update;
  if not found
     or (
       actor_role <> 'SUPER_ADMIN'
       and actor_membership.role is distinct from actor_role
     )
     or private.active_tenant_id(actor_id) is distinct from actor_tenant
     or private.active_tenant_role(actor_id) is distinct from actor_role
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'forbidden'
    );
  end if;

  actor_name_snapshot := pg_catalog.left(
    coalesce(
      nullif(pg_catalog.btrim(actor_profile.full_name), ''),
      'Operador'
    ),
    200
  );
  normalized_note_hash := case
    when normalized_note is null then null
    else pg_catalog.encode(
      extensions.digest(
        pg_catalog.convert_to(normalized_note, 'UTF8'),
        'sha256'
      ),
      'hex'
    )
  end;
  request_envelope := pg_catalog.jsonb_build_object(
    'envelope_version', 1,
    'tenant_id', actor_tenant,
    'actor_id', actor_id,
    'student_id', p_student_id,
    'service_end_date', p_service_end_date,
    'action', normalized_action,
    'expected_version', p_expected_version,
    'channel', normalized_channel,
    'contact_at', case
      when p_contact_at is null then null
      else pg_catalog.to_char(
        p_contact_at at time zone 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      )
    end,
    'next_action_at', case
      when p_next_action_at is null then null
      else pg_catalog.to_char(
        p_next_action_at at time zone 'UTC',
        'YYYY-MM-DD"T"HH24:MI:SS.US"Z"'
      )
    end,
    'interest_term_months', p_interest_term_months,
    'note_sha256', normalized_note_hash
  );
  request_fingerprint := pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(request_envelope::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  -- The request lock is tenant-wide for this idempotency key.  It is acquired
  -- before the cycle lock so even accidental reuse across two students is
  -- serialized and resolved as a deterministic conflict.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-renewal-request:' || actor_tenant || ':' ||
      p_request_id::text,
      0
    )
  );

  select event.*
    into replay_event
    from public.student_renewal_case_events as event
   where event.tenant_id = actor_tenant
     and event.request_id = p_request_id;

  if found then
    if replay_event.request_envelope is distinct from request_envelope
       or replay_event.request_fingerprint is distinct from request_fingerprint
    then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'request_id_conflict'
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'replayed', true,
      'case_id', replay_event.renewal_case_id,
      'status', replay_event.to_status,
      'version', replay_event.result_version,
      'last_contact_at', replay_event.result_last_contact_at,
      'last_channel', replay_event.result_last_channel,
      'next_action_at', replay_event.result_next_action_at,
      'interest_term_months', replay_event.result_interest_term_months,
      'updated_by_name', replay_event.actor_name_snapshot
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-renewal:' || actor_tenant || ':' ||
      p_student_id::text || ':' || p_service_end_date::text,
      0
    )
  );

  -- Read the provider mirror only after taking the application lock, and keep
  -- the profile row locked through the ledger write.  A sync/correction cannot
  -- change subscription/end-date between validation and the event insert.
  select profile.*
   into student
    from public.profiles as profile
   where profile.id = p_student_id
   for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'student_not_found'
    );
  end if;

  if student.tenant_id is distinct from actor_tenant then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'tenant_mismatch'
    );
  end if;

  select membership.*
    into student_membership
    from public.tenant_memberships as membership
   where membership.user_id = student.id
     and membership.tenant_id = actor_tenant
     and membership.role = 'STUDENT'
     and membership.status = 'ACTIVE'
   for no key update;
  if not found
     or pg_catalog.lower(pg_catalog.btrim(coalesce(
       student.lifecycle_status,
       ''
     ))) <> 'active'
     or private.active_tenant_id(student.id) is distinct from actor_tenant
     or private.active_tenant_role(student.id) is distinct from 'STUDENT'
  then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'student_inactive'
    );
  end if;

  source_service_end := public.fim_do_servico(
    student.asaas_subscription_end_date
  );
  if source_service_end is null
     or source_service_end is distinct from p_service_end_date
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'error', 'renewal_cycle_changed',
      'current_service_end_date', source_service_end
    );
  end if;

  select renewal.*
    into current_case
    from public.student_renewal_cases as renewal
   where renewal.tenant_id = actor_tenant
     and renewal.student_id_snapshot = student.id
     and renewal.service_end_date = p_service_end_date
   for update;
  case_found := found;

  if case_found then
    -- Provider/customer fields are immutable opening snapshots, not the cycle
    -- identity.  A binding correction may continue this operational cycle as
    -- long as fim_do_servico still resolves to p_service_end_date.
    current_status := current_case.status;
    current_version := current_case.version;
    current_last_contact := current_case.last_contact_at;
    current_channel := current_case.last_channel;
    current_follow_up := current_case.next_action_at;
    current_interest := current_case.interest_term_months;
  else
    current_status := 'PENDING_CONTACT';
    current_version := 0;
    current_last_contact := null;
    current_channel := null;
    current_follow_up := null;
    current_interest := null;
  end if;

  if current_version is distinct from p_expected_version then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'error', 'version_conflict',
      'current_version', current_version
    );
  end if;

  next_status := current_status;
  next_last_contact := current_last_contact;
  next_channel := current_channel;
  next_follow_up := current_follow_up;
  next_interest := current_interest;

  if normalized_action = 'CONTACTED' then
    if current_status = 'NOT_CONTINUING_RECORDED'
    then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_transition'
      );
    end if;
    effective_contact := coalesce(p_contact_at, pg_catalog.now());
    if effective_contact > pg_catalog.now() + interval '5 minutes'
       or effective_contact < pg_catalog.now() - interval '365 days'
       or (
         p_next_action_at is not null
         and (
           p_next_action_at <= effective_contact
           or p_next_action_at > pg_catalog.now() + interval '365 days'
         )
       )
    then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_contact_timing'
      );
    end if;
    next_last_contact := effective_contact;
    next_channel := normalized_channel;
    next_follow_up := p_next_action_at;
    if current_status not in (
      'INTEREST_RECORDED', 'FORMALIZATION_PENDING'
    ) then
      next_status := case
        when p_next_action_at is null then 'AWAITING_REPLY'
        else 'FOLLOW_UP_SCHEDULED'
      end;
    end if;
  elsif normalized_action = 'SCHEDULE_FOLLOW_UP' then
    if current_status not in (
         'AWAITING_REPLY',
         'FOLLOW_UP_SCHEDULED',
         'INTEREST_RECORDED',
         'FORMALIZATION_PENDING'
       )
       or p_next_action_at is null
       or p_next_action_at <= pg_catalog.now()
       or p_next_action_at > pg_catalog.now() + interval '365 days'
    then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_transition'
      );
    end if;
    next_follow_up := p_next_action_at;
    if current_status in ('AWAITING_REPLY', 'FOLLOW_UP_SCHEDULED') then
      next_status := 'FOLLOW_UP_SCHEDULED';
    end if;
  elsif normalized_action = 'RECORD_INTEREST' then
    if current_status not in (
         'AWAITING_REPLY', 'FOLLOW_UP_SCHEDULED', 'INTEREST_RECORDED'
       )
    then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_transition'
      );
    end if;
    next_status := 'INTEREST_RECORDED';
    next_interest := p_interest_term_months::smallint;
    next_follow_up := null;
  elsif normalized_action = 'AWAIT_FORMALIZATION' then
    if current_status <> 'INTEREST_RECORDED'
       or current_interest not in (6, 12)
       or (
         p_next_action_at is not null
         and (
           p_next_action_at <= pg_catalog.now()
           or p_next_action_at > pg_catalog.now() + interval '365 days'
         )
       )
    then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_transition'
      );
    end if;
    next_status := 'FORMALIZATION_PENDING';
    next_follow_up := p_next_action_at;
  elsif normalized_action = 'RECORD_NOT_CONTINUING' then
    if current_status = 'NOT_CONTINUING_RECORDED' then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_transition'
      );
    end if;
    next_status := 'NOT_CONTINUING_RECORDED';
    next_follow_up := null;
    next_interest := null;
  elsif normalized_action = 'REOPEN' then
    if current_status not in (
      'NOT_CONTINUING_RECORDED', 'FORMALIZATION_PENDING'
    ) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_transition'
      );
    end if;
    next_status := 'PENDING_CONTACT';
    next_follow_up := null;
    next_interest := null;
  end if;

  previous_status := current_status;
  if not case_found then
    insert into public.student_renewal_cases (
      tenant_id,
      student_id,
      student_id_snapshot,
      service_end_date,
      source_customer_id,
      source_subscription_id,
      source_asaas_end_date,
      source_subscription_synced_at,
      monthly_fee_snapshot,
      due_day_snapshot,
      class_frequency_snapshot,
      status,
      last_contact_at,
      last_channel,
      next_action_at,
      interest_term_months,
      version,
      created_by,
      updated_by
    ) values (
      actor_tenant,
      student.id,
      student.id,
      p_service_end_date,
      nullif(pg_catalog.btrim(coalesce(student.asaas_customer_id, '')), ''),
      nullif(pg_catalog.btrim(coalesce(student.subscription_id, '')), ''),
      student.asaas_subscription_end_date,
      student.asaas_subscription_synced_at,
      greatest(coalesce(student.monthly_fee, 0::numeric), 0::numeric),
      student.due_day,
      nullif(pg_catalog.btrim(coalesce(student.class_frequency, '')), ''),
      next_status,
      next_last_contact,
      next_channel,
      next_follow_up,
      next_interest,
      1,
      actor_id,
      actor_id
    )
    returning * into current_case;
  else
    update public.student_renewal_cases as renewal
       set status = next_status,
           last_contact_at = next_last_contact,
           last_channel = next_channel,
           next_action_at = next_follow_up,
           interest_term_months = next_interest,
           version = current_version + 1,
           updated_by = actor_id,
           updated_at = pg_catalog.now()
     where renewal.id = current_case.id
       and renewal.tenant_id = actor_tenant
       and renewal.version = current_version
     returning renewal.* into current_case;
    if not found then
      raise exception 'renewal_case_compare_and_swap_lost'
        using errcode = '40001';
    end if;
  end if;

  insert into public.student_renewal_case_events (
    id,
    tenant_id,
    renewal_case_id,
    student_id,
    student_id_snapshot,
    actor_id,
    actor_name_snapshot,
    request_id,
    action,
    from_status,
    to_status,
    channel,
    contact_at,
    next_action_at,
    interest_term_months,
    request_envelope,
    request_fingerprint,
    result_version,
    result_last_contact_at,
    result_last_channel,
    result_next_action_at,
    result_interest_term_months
  ) values (
    new_event_id,
    actor_tenant,
    current_case.id,
    student.id,
    student.id,
    actor_id,
    actor_name_snapshot,
    p_request_id,
    normalized_action,
    previous_status,
    current_case.status,
    normalized_channel,
    effective_contact,
    next_follow_up,
    next_interest,
    request_envelope,
    request_fingerprint,
    current_case.version,
    current_case.last_contact_at,
    current_case.last_channel,
    current_case.next_action_at,
    current_case.interest_term_months
  );

  if normalized_note is not null then
    insert into public.student_renewal_case_event_notes (
      event_id,
      tenant_id,
      renewal_case_id,
      student_id,
      note
    ) values (
      new_event_id,
      actor_tenant,
      current_case.id,
      student.id,
      normalized_note
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'replayed', false,
    'case_id', current_case.id,
    'status', current_case.status,
    'version', current_case.version,
    'last_contact_at', current_case.last_contact_at,
    'last_channel', current_case.last_channel,
    'next_action_at', current_case.next_action_at,
    'interest_term_months', current_case.interest_term_months,
    'updated_by_name', actor_name_snapshot
  );
end;
$$;


--
-- Name: record_tenant_integration_verified(text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_tenant_integration_verified(p_tenant_id text, p_provider text, p_expected_version bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_updated boolean := false;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;

  if p_tenant_id is null
    or nullif(pg_catalog.btrim(p_tenant_id), '') is null
    or p_provider <> 'asaas'
    or p_expected_version is null
    or p_expected_version <= 0
  then
    raise exception 'invalid_integration_verification' using errcode = '22023';
  end if;

  update private.tenant_integration_connections as connection
     set status = 'healthy',
         last_verified_at = pg_catalog.clock_timestamp(),
         last_error_code = null,
         updated_at = pg_catalog.clock_timestamp()
   where connection.tenant_id = p_tenant_id
     and connection.provider = p_provider
     and connection.tenant_id = 'school-wise-wolf'
     and connection.mode = 'PLATFORM_MANAGED_ROOT'
     and connection.version = p_expected_version
     and connection.mode <> 'DISABLED'
     and connection.status in ('configured', 'healthy')
  returning true into v_updated;

  return coalesce(v_updated, false);
end;
$$;


--
-- Name: record_trial_feedback(uuid, uuid, text, text, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_trial_feedback(p_opportunity_id uuid, p_teacher_id uuid, p_recommended_level text, p_recommended_plan text, p_interest_score integer, p_notes text DEFAULT NULL::text, p_trial_status text DEFAULT 'DONE'::text, p_tenant_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_opp RECORD;
    v_existing_feedback RECORD;
    v_feedback_id UUID;
BEGIN
    -- 1. Lock and fetch opportunity
    SELECT * INTO v_opp FROM public.opportunities
    WHERE id = p_opportunity_id FOR UPDATE;

    IF v_opp IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'OPPORTUNITY_NOT_FOUND');
    END IF;

    -- 2. Validate teacher owns this opportunity
    IF v_opp.winner_teacher_id IS NOT NULL AND v_opp.winner_teacher_id != p_teacher_id THEN
        RETURN jsonb_build_object('success', false, 'error', 'NOT_ASSIGNED_TEACHER');
    END IF;

    -- 3. Validate trial_status transition
    IF v_opp.trial_status = 'DONE' AND p_trial_status != 'DONE' THEN
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_TRANSITION',
            'message', 'Cannot change status from DONE');
    END IF;

    -- 4. Upsert feedback (one per opportunity)
    SELECT * INTO v_existing_feedback FROM public.trial_feedback
    WHERE opportunity_id = p_opportunity_id;

    IF v_existing_feedback IS NOT NULL THEN
        UPDATE public.trial_feedback SET
            recommended_level = p_recommended_level,
            recommended_plan = p_recommended_plan,
            interest_score = p_interest_score,
            notes = COALESCE(p_notes, notes)
        WHERE opportunity_id = p_opportunity_id
        RETURNING id INTO v_feedback_id;
    ELSE
        INSERT INTO public.trial_feedback (
            tenant_id, opportunity_id, teacher_id,
            recommended_level, recommended_plan, interest_score, notes
        ) VALUES (
            COALESCE(p_tenant_id, v_opp.tenant_id), p_opportunity_id, p_teacher_id,
            p_recommended_level, p_recommended_plan, p_interest_score, p_notes
        )
        RETURNING id INTO v_feedback_id;
    END IF;

    -- 5. Update opportunity status
    UPDATE public.opportunities SET
        trial_status = p_trial_status,
        conversion_status = CASE
            WHEN p_trial_status IN ('NO_SHOW_STUDENT', 'CANCELLED') THEN 'LOST'
            WHEN p_trial_status = 'DONE' AND conversion_status = 'OPEN' THEN 'PENDING_FEEDBACK'
            ELSE conversion_status
        END,
        lost_reason = CASE
            WHEN p_trial_status = 'NO_SHOW_STUDENT' THEN 'Aluno não compareceu à aula experimental'
            WHEN p_trial_status = 'CANCELLED' THEN 'Aula experimental cancelada'
            ELSE lost_reason
        END
    WHERE id = p_opportunity_id;

    -- 6. Audit trail
    INSERT INTO public.trial_feedback_audit (
        opportunity_id, actor_id, action, before_state, after_state
    ) VALUES (
        p_opportunity_id, p_teacher_id,
        CASE WHEN v_existing_feedback IS NOT NULL THEN 'FEEDBACK_UPDATED' ELSE 'FEEDBACK_CREATED' END,
        CASE WHEN v_existing_feedback IS NOT NULL THEN
            jsonb_build_object(
                'level', v_existing_feedback.recommended_level,
                'plan', v_existing_feedback.recommended_plan,
                'score', v_existing_feedback.interest_score
            )
        ELSE NULL END,
        jsonb_build_object(
            'level', p_recommended_level,
            'plan', p_recommended_plan,
            'score', p_interest_score,
            'trial_status', p_trial_status
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'feedback_id', v_feedback_id,
        'trial_status', p_trial_status
    );
END;
$$;


--
-- Name: record_verified_pedagogical_quiz(uuid, text, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_verified_pedagogical_quiz(p_student_id uuid, p_book_part text, p_score integer, p_total_questions integer, p_answers jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_book_part text := pg_catalog.upper(
    pg_catalog.btrim(coalesce(p_book_part, ''))
  );
  v_profile record;
  v_existing public.student_verified_xp_awards%rowtype;
  v_percentage integer;
  v_passed boolean;
  v_modules text[] := array['A1', 'A2', 'B1', 'B2', 'C1', 'C2'];
  v_module text;
  v_part integer;
  v_module_index integer;
  v_next_part text;
  v_daily_xp integer;
  v_today date :=
    (pg_catalog.now() at time zone 'America/Sao_Paulo')::date;
  v_xp_earned integer := 0;
  v_new_xp integer;
  v_new_level integer;
  v_answer jsonb;
begin
  if p_student_id is null
     or v_book_part !~ '^(A1|A2|B1|B2|C1|C2)-[1-4]$'
     or p_total_questions is null
     or p_total_questions not between 1 and 100
     or p_score is null
     or p_score not between 0 and p_total_questions
     or p_answers is null
     or pg_catalog.jsonb_typeof(p_answers) <> 'array'
     or pg_catalog.jsonb_array_length(p_answers) <> p_total_questions
     or pg_catalog.pg_column_size(p_answers) > 16384 then
    raise exception using
      errcode = '22023',
      message = 'invalid_pedagogical_quiz_result';
  end if;

  for v_answer in
    select value
      from pg_catalog.jsonb_array_elements(p_answers)
  loop
    if pg_catalog.jsonb_typeof(v_answer) <> 'number'
       or v_answer::text !~ '^[0-9]+$' then
      raise exception using
        errcode = '22023',
        message = 'invalid_pedagogical_quiz_answers';
    end if;
  end loop;

  v_percentage := pg_catalog.round(
    (p_score::numeric / p_total_questions::numeric) * 100
  );
  v_passed := v_percentage >= 70;

  select
    profile.tenant_id,
    profile.role,
    profile.module,
    profile.current_book_part,
    profile.evaluation_unlocked,
    coalesce(profile.xp, 0) as xp,
    coalesce(profile.level, 1) as level,
    coalesce(profile.daily_xp, 0) as daily_xp,
    profile.daily_xp_date,
    coalesce(profile.is_test_account, false) as is_test_account
    into v_profile
    from public.profiles as profile
   where profile.id = p_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  select *
    into v_existing
    from public.student_verified_xp_awards as award
   where award.student_id = p_student_id
     and award.source_type = 'PEDAGOGICAL_QUIZ'
     and award.source_id = v_book_part;

  if found then
    return pg_catalog.jsonb_build_object(
      'alreadyAwarded', true,
      'passed', true,
      'score', p_score,
      'totalQuestions', p_total_questions,
      'percentage', v_percentage,
      'xpEarned', 0,
      'nextPart', v_profile.current_book_part,
      'newLevel', v_profile.level,
      'leveledUp', false
    );
  end if;

  if coalesce(
       v_profile.current_book_part,
       coalesce(v_profile.module, 'A1') || '-1'
     ) <> v_book_part
     or coalesce(v_profile.evaluation_unlocked, false) is not true then
    raise exception using
      errcode = 'P0001',
      message = 'pedagogical_quiz_not_unlocked';
  end if;

  insert into public.student_evaluations (
    student_id,
    book_part,
    score,
    total_questions,
    answers,
    completed_at,
    tenant_id
  ) values (
    p_student_id,
    v_book_part,
    p_score,
    p_total_questions,
    p_answers,
    pg_catalog.now(),
    v_profile.tenant_id
  );

  if not v_passed then
    update public.profiles
       set last_activity = pg_catalog.now()
     where id = p_student_id;
    return pg_catalog.jsonb_build_object(
      'alreadyAwarded', false,
      'passed', false,
      'score', p_score,
      'totalQuestions', p_total_questions,
      'percentage', v_percentage,
      'xpEarned', 0,
      'nextPart', v_book_part,
      'newLevel', v_profile.level,
      'leveledUp', false
    );
  end if;

  v_module := pg_catalog.split_part(v_book_part, '-', 1);
  v_part := pg_catalog.split_part(v_book_part, '-', 2)::integer;
  v_module_index := pg_catalog.array_position(v_modules, v_module);
  if v_part < 4 then
    v_next_part := v_module || '-' || (v_part + 1)::text;
  elsif v_module_index < pg_catalog.cardinality(v_modules) then
    v_next_part := v_modules[v_module_index + 1] || '-1';
  else
    v_next_part := 'COMPLETED';
  end if;

  v_daily_xp := case
    when v_profile.daily_xp_date = v_today then v_profile.daily_xp
    else 0
  end;
  v_xp_earned := pg_catalog.round(
    100 * (v_percentage::numeric / 100)
  );
  v_xp_earned := least(
    v_xp_earned,
    greatest(0, 250 - v_daily_xp)
  );
  if v_profile.is_test_account then
    v_xp_earned := 0;
  end if;
  v_new_xp := v_profile.xp + v_xp_earned;
  v_new_level := pg_catalog.floor(v_new_xp / 1000) + 1;

  insert into public.student_verified_xp_awards (
    tenant_id,
    student_id,
    source_type,
    source_id,
    base_xp,
    xp_awarded,
    score_used,
    test_fixture
  ) values (
    v_profile.tenant_id,
    p_student_id,
    'PEDAGOGICAL_QUIZ',
    v_book_part,
    100,
    v_xp_earned,
    v_percentage,
    v_profile.is_test_account
  );

  update public.profiles
     set current_book_part = v_next_part,
         evaluation_unlocked = false,
         module = case
           when v_next_part = 'COMPLETED' then module
           else pg_catalog.split_part(v_next_part, '-', 1)
         end,
         xp = v_new_xp,
         level = v_new_level,
         daily_xp = v_daily_xp + v_xp_earned,
         daily_xp_date = v_today,
         last_activity = pg_catalog.now()
   where id = p_student_id;

  return pg_catalog.jsonb_build_object(
    'alreadyAwarded', false,
    'passed', true,
    'score', p_score,
    'totalQuestions', p_total_questions,
    'percentage', v_percentage,
    'xpEarned', v_xp_earned,
    'nextPart', v_next_part,
    'newLevel', v_new_level,
    'leveledUp', v_new_level > v_profile.level
  );
end;
$_$;


--
-- Name: record_verified_pedagogical_quiz_v2(uuid, text, integer, integer, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_verified_pedagogical_quiz_v2(p_student_id uuid, p_book_part text, p_score integer, p_total_questions integer, p_answers jsonb, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_book_part text := pg_catalog.upper(
    pg_catalog.btrim(coalesce(p_book_part, ''))
  );
  v_request_key text := pg_catalog.btrim(coalesce(p_request_key, ''));
  v_next_part text;
  v_result jsonb;
  v_request_payload jsonb;
  v_existing_request public.pedagogical_evaluation_submission_requests%rowtype;
  v_profile record;
  v_streak integer;
begin
  if p_student_id is null
     or pg_catalog.length(v_request_key) not between 8 and 180 then
    raise exception using errcode = '22023', message = 'invalid_evaluation_submission_request';
  end if;

  select catalog.next_book_part
    into v_next_part
    from public.pedagogical_evaluation_catalog as catalog
   where catalog.book_part = v_book_part
     and catalog.active is true;
  if not found then
    raise exception using errcode = '22023', message = 'evaluation_not_published';
  end if;

  -- Serialize every submission for this student before consulting the request
  -- ledger. A same-key retry may read its canonical stored result after the
  -- stage advances; a different key must revalidate the live progression.
  select
    profile.tenant_id,
    coalesce(
      profile.current_book_part,
      coalesce(profile.module, 'A1') || '-1'
    ) as current_book_part,
    coalesce(profile.evaluation_unlocked, false) as evaluation_unlocked
    into v_profile
    from public.profiles as profile
   where profile.id = p_student_id
     and profile.role = 'STUDENT'
   for update;
  if not found or v_profile.tenant_id is null then
    raise exception using errcode = '42501', message = 'student_profile_required';
  end if;

  v_request_payload := pg_catalog.jsonb_build_object(
    'bookPart', v_book_part,
    'score', p_score,
    'totalQuestions', p_total_questions,
    'answers', p_answers
  );

  select request.*
    into v_existing_request
    from public.pedagogical_evaluation_submission_requests as request
   where request.student_id = p_student_id
     and request.request_key = v_request_key
   for update;
  if found then
    if v_existing_request.request_payload is distinct from v_request_payload
       or v_existing_request.result is null then
      raise exception using errcode = '22023', message = 'evaluation_submission_idempotency_conflict';
    end if;
    return v_existing_request.result || pg_catalog.jsonb_build_object(
      'alreadySubmitted', true
    );
  end if;

  -- The legacy recorder treats any existing XP award as a successful replay,
  -- even when a caller supplies a brand-new request and a failing score. Only
  -- the persisted request/fingerprint branch above is a legitimate replay.
  if v_profile.current_book_part <> v_book_part
     or exists (
       select 1
         from public.student_verified_xp_awards as award
        where award.student_id = p_student_id
          and award.source_type = 'PEDAGOGICAL_QUIZ'
          and award.source_id = v_book_part
     ) then
    raise exception using
      errcode = 'P0001',
      message = 'pedagogical_quiz_already_completed';
  end if;

  if v_profile.evaluation_unlocked is not true then
    raise exception using
      errcode = 'P0001',
      message = 'pedagogical_quiz_not_unlocked';
  end if;

  insert into public.pedagogical_evaluation_submission_requests (
    tenant_id,
    student_id,
    request_key,
    request_payload
  ) values (
    v_profile.tenant_id,
    p_student_id,
    v_request_key,
    v_request_payload
  );

  v_result := public.record_verified_pedagogical_quiz(
    p_student_id,
    v_book_part,
    p_score,
    p_total_questions,
    p_answers
  );

  if not coalesce((v_result ->> 'alreadyAwarded')::boolean, false) then
    v_streak := private.record_student_learning_practice(
      p_student_id,
      coalesce((v_result ->> 'percentage')::integer, 0),
      'quiz',
      array['grammar', 'vocabulary']::text[],
      pg_catalog.now()
    );
  else
    select coalesce(profile.streak_count, 0)
      into v_streak
      from public.profiles as profile
     where profile.id = p_student_id;
  end if;

  if coalesce((v_result ->> 'passed')::boolean, false)
     and not coalesce((v_result ->> 'alreadyAwarded')::boolean, false) then
    update public.profiles
       set current_book_part = coalesce(v_next_part, 'COMPLETED'),
           module = case
             when v_next_part is null then module
             else pg_catalog.split_part(v_next_part, '-', 1)
           end
     where id = p_student_id;

    v_result := pg_catalog.jsonb_set(
      v_result,
      '{nextPart}',
      pg_catalog.to_jsonb(coalesce(v_next_part, 'COMPLETED')),
      true
    );
  end if;

  v_result := v_result || pg_catalog.jsonb_build_object(
    'streakCount', coalesce(v_streak, 0),
    'alreadySubmitted', false
  );

  update public.pedagogical_evaluation_submission_requests
     set result = v_result,
         completed_at = pg_catalog.now()
   where student_id = p_student_id
     and request_key = v_request_key;

  return v_result;
end;
$$;


--
-- Name: record_wolfie_activity_attempt(uuid, uuid, jsonb, jsonb, integer, integer, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_wolfie_activity_attempt(p_session_id uuid, p_request_key uuid, p_response_payload jsonb, p_feedback_payload jsonb, p_score integer, p_duration_seconds integer DEFAULT 0, p_step_key text DEFAULT NULL::text, p_modality text DEFAULT 'text'::text, p_complete boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session public.wolfie_activity_sessions%rowtype;
  v_existing public.wolfie_activity_attempts%rowtype;
  v_parent public.wolfie_activity_attempts%rowtype;
  v_attempt public.wolfie_activity_attempts%rowtype;
  v_attempt_kind text;
  v_parent_attempt_id uuid;
  v_step_key text;
  v_parent_step_key text;
  v_response_payload jsonb;
  v_feedback_payload jsonb;
  v_requires_retry boolean;
  v_effective_complete boolean;
  v_retry_completed_for_response boolean;
  v_attempt_number integer;
  v_required_count integer;
  v_completed_count integer;
  v_pending_count integer;
  v_other_pending_count integer;
  v_meeting_section_count integer;
  v_result jsonb;
begin
  if p_request_key is null then
    raise exception 'request_key_required';
  end if;
  if p_score is null or p_score < 0 or p_score > 100 then
    raise exception 'score_out_of_range';
  end if;
  if p_duration_seconds is null
     or p_duration_seconds < 0
     or p_duration_seconds > 86400 then
    raise exception 'duration_out_of_range';
  end if;
  if p_modality is null
     or p_modality not in ('text', 'voice', 'mixed') then
    raise exception 'invalid_modality';
  end if;
  if p_complete is null then
    raise exception 'complete_flag_required';
  end if;
  if pg_catalog.pg_column_size(
    coalesce(p_response_payload, '{}'::jsonb)
  ) > 1048576
     or pg_catalog.pg_column_size(
       coalesce(p_feedback_payload, '{}'::jsonb)
     ) > 1048576 then
    raise exception 'attempt_payload_too_large';
  end if;

  v_step_key := nullif(
    pg_catalog.left(coalesce(p_step_key, ''), 120),
    ''
  );
  v_attempt_kind := coalesce(
    nullif(p_response_payload ->> 'attemptKind', ''),
    'initial'
  );
  if v_attempt_kind not in ('initial', 'retry') then
    raise exception 'invalid_attempt_kind';
  end if;
  v_requires_retry :=
    coalesce(p_feedback_payload ->> 'requiresRetry', 'false') = 'true';

  select *
    into v_session
    from public.wolfie_activity_sessions
   where id = p_session_id
   for update;

  if not found then
    raise exception 'session_not_found';
  end if;

  select *
    into v_existing
    from public.wolfie_activity_attempts
   where session_id = v_session.id
     and request_key = p_request_key;

  if found then
    return pg_catalog.jsonb_build_object(
      'alreadyProcessed', true,
      'alreadyCompleted', v_session.status = 'COMPLETED',
      'stepAlreadyAnswered', false,
      'requestKey', v_existing.request_key,
      'stepKey', v_existing.step_key,
      'attemptId', v_existing.id,
      'attemptNumber', v_existing.attempt_number,
      'score', v_existing.score,
      'responsePayload', v_existing.response_payload,
      'feedbackPayload', v_existing.feedback_payload
        || pg_catalog.jsonb_build_object(
          'requiresRetry',
            v_existing.requires_retry and not v_existing.retry_completed,
          'retryCompleted', v_existing.retry_completed or coalesce(
            v_existing.feedback_payload ->> 'retryCompleted',
            'false'
          ) = 'true'
        ),
      'requiresRetry',
        v_existing.requires_retry and not v_existing.retry_completed,
      'retryCompleted',
        v_existing.retry_completed or coalesce(
          v_existing.feedback_payload ->> 'retryCompleted',
          'false'
        ) = 'true',
      'parentAttemptId', v_existing.parent_attempt_id,
      'xpEarned', case
        when v_existing.completes_session
          and v_session.status = 'COMPLETED'
          then v_session.xp_earned
        else 0
      end,
      'leveledUp', false,
      'newLevel', null
    );
  end if;

  if v_session.status = 'COMPLETED' then
    return pg_catalog.jsonb_build_object(
      'alreadyProcessed', false,
      'alreadyCompleted', true,
      'stepAlreadyAnswered', false,
      'requestKey', p_request_key,
      'stepKey', v_step_key,
      'attemptId', null,
      'attemptNumber', v_session.attempt_count,
      'score', v_session.score,
      'requiresRetry', false,
      'retryCompleted', false,
      'parentAttemptId', null,
      'xpEarned', v_session.xp_earned,
      'leveledUp', false,
      'newLevel', null
    );
  end if;
  if v_session.status in ('ABANDONED', 'FAILED', 'EVALUATING') then
    raise exception 'session_not_writable';
  end if;

  if v_attempt_kind = 'retry' then
    begin
      v_parent_attempt_id :=
        nullif(p_response_payload ->> 'parentAttemptId', '')::uuid;
    exception
      when invalid_text_representation then
        raise exception 'invalid_parent_attempt_id';
    end;
    if v_parent_attempt_id is null then
      raise exception 'parent_attempt_required';
    end if;

    select *
      into v_parent
      from public.wolfie_activity_attempts
     where id = v_parent_attempt_id
       and session_id = v_session.id
       and student_id = v_session.student_id
       and tenant_id = v_session.tenant_id
     for update;

    if not found
       or not v_parent.requires_retry
       or v_parent.retry_completed then
      raise exception 'parent_attempt_not_retryable';
    end if;

    v_parent_step_key := coalesce(
      nullif(v_parent.response_payload ->> 'logicalStepKey', ''),
      v_parent.step_key
    );
    if v_parent_step_key is distinct from v_step_key then
      raise exception 'parent_attempt_step_mismatch';
    end if;
  elsif nullif(p_response_payload ->> 'parentAttemptId', '') is not null then
    raise exception 'initial_attempt_cannot_have_parent';
  end if;

  -- Guided Writing always requires at least one reformulation and keeps the
  -- retry chain open until the latest version meets the calibrated threshold.
  if v_session.subject = 'writing'
     and v_step_key = 'writing'
     and not p_complete
     and v_attempt_kind = 'initial' then
    v_requires_retry := true;
  end if;

  v_effective_complete := p_complete and not v_requires_retry;
  v_retry_completed_for_response :=
    v_parent_attempt_id is not null and not v_requires_retry;
  v_response_payload :=
    coalesce(p_response_payload, '{}'::jsonb)
    || pg_catalog.jsonb_build_object(
      'logicalStepKey', v_step_key,
      'attemptKind', v_attempt_kind,
      'parentAttemptId', v_parent_attempt_id
    );
  v_feedback_payload :=
    coalesce(p_feedback_payload, '{}'::jsonb)
    || pg_catalog.jsonb_build_object(
      'requiresRetry', v_requires_retry,
      'retryCompleted', v_retry_completed_for_response,
      'parentAttemptId', v_parent_attempt_id
    );

  select pg_catalog.count(*)::integer
    into v_other_pending_count
    from public.wolfie_activity_attempts as pending
   where pending.session_id = v_session.id
     and pending.requires_retry
     and not pending.retry_completed
     and pending.id is distinct from v_parent_attempt_id;

  if v_attempt_kind = 'initial' and v_other_pending_count > 0 then
    raise exception 'retry_required';
  end if;
  if v_effective_complete and v_other_pending_count > 0 then
    raise exception 'retry_required';
  end if;

  if not v_effective_complete then
    if v_session.subject = 'global_meetings' then
      if v_session.phase = 'construction'
         and v_step_key = any (
           array[
             'opening',
             'context',
             'data',
             'proposal',
             'next_steps',
             'closing'
           ]::text[]
         ) then
        if p_modality <> 'text'
           or nullif(
             pg_catalog.btrim(v_response_payload ->> 'text'),
             ''
           ) is null then
          raise exception 'invalid_meeting_section_response';
        end if;
      elsif coalesce(
        v_response_payload ->> 'completeWhenReady',
        'false'
      ) = 'true' then
        if (
          v_session.phase = 'construction'
          and v_step_key is distinct from 'construction_complete'
        ) or (
          v_session.phase = 'memorization'
          and v_step_key is distinct from 'memorization_complete'
        ) or (
          v_session.phase = 'readaptation'
          and v_step_key not in ('readaptation', 'readaptation_speech')
        ) or v_session.phase not in (
          'construction',
          'memorization',
          'readaptation'
        ) then
          raise exception 'invalid_meeting_final_step';
        end if;

        if v_session.phase = 'construction' then
          select pg_catalog.count(distinct attempt.step_key)
            into v_meeting_section_count
            from public.wolfie_activity_attempts as attempt
           where attempt.session_id = v_session.id
             and attempt.step_key = any (
               array[
                 'opening',
                 'context',
                 'data',
                 'proposal',
                 'next_steps',
                 'closing'
               ]::text[]
             )
             and nullif(
               pg_catalog.btrim(attempt.response_payload ->> 'text'),
               ''
             ) is not null;
          if v_meeting_section_count <> 6 then
            raise exception 'meeting_sections_incomplete';
          end if;
        elsif v_session.phase = 'memorization'
          and coalesce(
            (
              v_session.learner_state
                -> 'memorization'
                ->> 'rehearsalCount'
            )::integer,
            0
          ) < 1 then
          raise exception 'memorization_rehearsal_required';
        end if;

        if (
          p_modality = 'text'
          and nullif(
            pg_catalog.btrim(v_response_payload ->> 'text'),
            ''
          ) is null
        ) or (
          p_modality = 'voice'
          and coalesce(
            v_response_payload ->> 'audioAnalyzed',
            'false'
          ) <> 'true'
        ) or p_modality not in ('text', 'voice') then
          raise exception 'invalid_meeting_final_response';
        end if;
      else
        raise exception 'invalid_meeting_partial_attempt';
      end if;
    end if;

    v_attempt_number := v_session.attempt_count + 1;
    insert into public.wolfie_activity_attempts (
      session_id,
      tenant_id,
      student_id,
      request_key,
      attempt_number,
      step_key,
      modality,
      response_payload,
      feedback_payload,
      score,
      completes_session,
      attempt_kind,
      parent_attempt_id,
      requires_retry,
      retry_completed
    ) values (
      v_session.id,
      v_session.tenant_id,
      v_session.student_id,
      p_request_key,
      v_attempt_number,
      v_step_key,
      p_modality,
      v_response_payload,
      v_feedback_payload,
      p_score,
      false,
      v_attempt_kind,
      v_parent_attempt_id,
      v_requires_retry,
      false
    )
    returning * into v_attempt;

    if v_parent_attempt_id is not null then
      update public.wolfie_activity_attempts
         set retry_completed = true,
             retry_completed_by_attempt_id = v_attempt.id
       where id = v_parent_attempt_id;
    end if;

    select
      pg_catalog.count(*) filter (
        where attempt.requires_retry
      )::integer,
      pg_catalog.count(*) filter (
        where attempt.requires_retry and attempt.retry_completed
      )::integer,
      pg_catalog.count(*) filter (
        where attempt.requires_retry and not attempt.retry_completed
      )::integer
      into v_required_count, v_completed_count, v_pending_count
      from public.wolfie_activity_attempts as attempt
     where attempt.session_id = v_session.id;

    update public.wolfie_activity_sessions
       set attempt_count = v_attempt_number,
           duration_seconds = greatest(
             duration_seconds,
             least(p_duration_seconds, 86400)
           ),
           learner_state = case
             when v_session.subject = 'global_meetings'
              and v_session.phase = 'construction'
              and v_step_key = any (
                array[
                  'opening',
                  'context',
                  'data',
                  'proposal',
                  'next_steps',
                  'closing'
                ]::text[]
              ) then
               pg_catalog.jsonb_set(
                 pg_catalog.jsonb_set(
                   coalesce(learner_state, '{}'::jsonb),
                   array['sections']::text[],
                   case
                     when pg_catalog.jsonb_typeof(
                       learner_state -> 'sections'
                     ) = 'object'
                       then learner_state -> 'sections'
                     else '{}'::jsonb
                   end,
                   true
                 ),
                 array['sections', v_step_key]::text[],
                 pg_catalog.jsonb_build_object(
                   'original',
                     coalesce(v_response_payload ->> 'text', ''),
                   'corrected',
                     coalesce(
                       v_feedback_payload ->> 'correctedText',
                       v_response_payload ->> 'text',
                       ''
                     ),
                   'naturalVersion',
                     coalesce(
                       v_feedback_payload ->> 'naturalVersion',
                       v_feedback_payload ->> 'correctedText',
                       v_response_payload ->> 'text',
                       ''
                     ),
                   'score', p_score,
                   'attemptId', v_attempt.id,
                   'requiresRetry', v_requires_retry,
                   'retryCompleted',
                     v_retry_completed_for_response,
                   'parentAttemptId', v_parent_attempt_id,
                   'savedAt', pg_catalog.now(),
                   'responsePayload', v_response_payload,
                   'feedbackPayload', v_feedback_payload
                 ),
                 true
               )
             when v_session.subject in (
               'vocabulary',
               'grammar',
               'listening',
               'reading'
             ) and v_step_key like 'quiz:%' then
               pg_catalog.jsonb_set(
                 pg_catalog.jsonb_set(
                   coalesce(learner_state, '{}'::jsonb),
                   array['quizAnswers']::text[],
                   case
                     when pg_catalog.jsonb_typeof(
                       learner_state -> 'quizAnswers'
                     ) = 'object'
                       then learner_state -> 'quizAnswers'
                     else '{}'::jsonb
                   end,
                   true
                 ),
                 array[
                   'quizAnswers',
                   pg_catalog.substring(v_step_key, 6)
                 ]::text[],
                 v_feedback_payload || pg_catalog.jsonb_build_object(
                   'attemptId', v_attempt.id,
                   'attemptNumber', v_attempt_number,
                   'score', p_score,
                   'requiresRetry', v_requires_retry,
                   'retryCompleted', v_retry_completed_for_response,
                   'parentAttemptId', v_parent_attempt_id,
                   'selectedIndex',
                     v_response_payload -> 'selectedIndex',
                   'savedAt', pg_catalog.now()
                 ),
                 true
               )
             else learner_state
           end,
           required_retry_count = v_required_count,
           completed_retry_count = v_completed_count,
           report_json = coalesce(report_json, '{}'::jsonb)
             || pg_catalog.jsonb_build_object(
               'lastScore', p_score,
               'requiresRetry', v_requires_retry,
               'retryCompleted', v_retry_completed_for_response,
               'retryPrompt',
                 coalesce(v_feedback_payload ->> 'retryPrompt', ''),
               'strengths',
                 coalesce(
                   v_feedback_payload -> 'strengths',
                   '[]'::jsonb
                 ),
               'priorities',
                 coalesce(
                   v_feedback_payload -> 'priorities',
                   '[]'::jsonb
                 ),
               'attemptId', v_attempt.id,
               'parentAttemptId', v_parent_attempt_id,
               'latestAttempt', pg_catalog.jsonb_build_object(
                 'attemptId', v_attempt.id,
                 'attemptNumber', v_attempt_number,
                 'stepKey', v_step_key,
                 'modality', p_modality,
                 'score', p_score,
                 'requiresRetry', v_requires_retry,
                 'retryCompleted', v_retry_completed_for_response,
                 'parentAttemptId', v_parent_attempt_id,
                 'responsePayload', v_response_payload,
                 'feedbackPayload', v_feedback_payload,
                 'recordedAt', pg_catalog.now()
               ),
               'updatedAt', pg_catalog.now()
             ),
           status = case
             when v_pending_count > 0 then 'AWAITING_RETRY'
             else 'IN_PROGRESS'
           end,
           current_stage = case
             when v_pending_count > 0 then 'retry'
             else 'practice'
           end,
           last_activity_at = pg_catalog.now(),
           updated_at = pg_catalog.now()
     where id = v_session.id;

    return pg_catalog.jsonb_build_object(
      'alreadyProcessed', false,
      'alreadyCompleted', false,
      'stepAlreadyAnswered', false,
      'requestKey', p_request_key,
      'stepKey', v_step_key,
      'attemptId', v_attempt.id,
      'attemptNumber', v_attempt_number,
      'score', p_score,
      'requiresRetry', v_requires_retry,
      'retryCompleted', v_retry_completed_for_response,
      'parentAttemptId', v_parent_attempt_id,
      'xpEarned', 0,
      'leveledUp', false,
      'newLevel', null
    );
  end if;

  v_result := public.record_wolfie_activity_attempt_legacy(
    p_session_id,
    p_request_key,
    v_response_payload,
    v_feedback_payload,
    p_score,
    p_duration_seconds,
    v_step_key,
    p_modality,
    true
  );

  select *
    into v_attempt
    from public.wolfie_activity_attempts
   where session_id = v_session.id
     and request_key = p_request_key;

  if not found then
    return v_result;
  end if;

  update public.wolfie_activity_attempts
     set attempt_kind = v_attempt_kind,
         parent_attempt_id = v_parent_attempt_id,
         requires_retry = false
   where id = v_attempt.id
   returning * into v_attempt;

  if v_parent_attempt_id is not null then
    update public.wolfie_activity_attempts
       set retry_completed = true,
           retry_completed_by_attempt_id = v_attempt.id
     where id = v_parent_attempt_id;
  end if;

  select
    pg_catalog.count(*) filter (
      where attempt.requires_retry
    )::integer,
    pg_catalog.count(*) filter (
      where attempt.requires_retry and attempt.retry_completed
    )::integer,
    pg_catalog.count(*) filter (
      where attempt.requires_retry and not attempt.retry_completed
    )::integer
    into v_required_count, v_completed_count, v_pending_count
    from public.wolfie_activity_attempts as attempt
   where attempt.session_id = v_session.id;

  update public.wolfie_activity_sessions
     set required_retry_count = v_required_count,
         completed_retry_count = v_completed_count,
         report_json = coalesce(report_json, '{}'::jsonb)
           || pg_catalog.jsonb_build_object(
             'lastScore', p_score,
             'requiresRetry', false,
             'retryCompleted', v_retry_completed_for_response,
             'retryPrompt', '',
             'strengths',
               coalesce(
                 v_feedback_payload -> 'strengths',
                 '[]'::jsonb
               ),
             'priorities',
               coalesce(
                 v_feedback_payload -> 'priorities',
                 '[]'::jsonb
               ),
             'attemptId', v_attempt.id,
             'parentAttemptId', v_parent_attempt_id,
             'latestAttempt', pg_catalog.jsonb_build_object(
               'attemptId', v_attempt.id,
               'attemptNumber', v_attempt.attempt_number,
               'stepKey', v_step_key,
               'modality', p_modality,
               'score', p_score,
               'requiresRetry', false,
               'retryCompleted', v_retry_completed_for_response,
               'parentAttemptId', v_parent_attempt_id,
               'responsePayload', v_response_payload,
               'feedbackPayload', v_feedback_payload,
               'recordedAt', pg_catalog.now()
             ),
             'status', 'completed',
             'updatedAt', pg_catalog.now()
           ),
         current_stage = 'completed',
         last_activity_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where id = v_session.id;

  return v_result || pg_catalog.jsonb_build_object(
    'attemptId', v_attempt.id,
    'attemptNumber', v_attempt.attempt_number,
    'requiresRetry', false,
    'retryCompleted', v_retry_completed_for_response,
    'parentAttemptId', v_parent_attempt_id
  );
end;
$$;


--
-- Name: record_wolfie_activity_attempt_legacy(uuid, uuid, jsonb, jsonb, integer, integer, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_wolfie_activity_attempt_legacy(p_session_id uuid, p_request_key uuid, p_response_payload jsonb, p_feedback_payload jsonb, p_score integer, p_duration_seconds integer DEFAULT 0, p_step_key text DEFAULT NULL::text, p_modality text DEFAULT 'text'::text, p_complete boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session public.wolfie_activity_sessions%rowtype;
  v_existing_attempt public.wolfie_activity_attempts%rowtype;
  v_attempt_number integer;
  v_step_key text;
  v_meeting_section_count integer;
  v_base_xp integer;
  v_xp_earned integer := 0;
  v_profile_xp integer;
  v_profile_level integer;
  v_daily_xp integer;
  v_daily_xp_date date;
  v_profile_test_fixture boolean;
  v_effective_test_fixture boolean;
  v_today date :=
    (pg_catalog.now() at time zone 'America/Sao_Paulo')::date;
  v_new_xp integer;
  v_new_level integer;
begin
  if p_request_key is null then
    raise exception 'request_key_required';
  end if;
  if p_score is null or p_score < 0 or p_score > 100 then
    raise exception 'score_out_of_range';
  end if;
  if p_duration_seconds is null
     or p_duration_seconds < 0
     or p_duration_seconds > 86400 then
    raise exception 'duration_out_of_range';
  end if;
  if p_modality is null
     or p_modality not in ('text', 'voice', 'mixed') then
    raise exception 'invalid_modality';
  end if;
  if p_complete is null then
    raise exception 'complete_flag_required';
  end if;

  v_step_key := nullif(
    pg_catalog.left(coalesce(p_step_key, ''), 120),
    ''
  );

  select *
    into v_session
    from public.wolfie_activity_sessions
   where id = p_session_id
   for update;

  if not found then
    raise exception 'session_not_found';
  end if;

  select *
    into v_existing_attempt
    from public.wolfie_activity_attempts
   where session_id = v_session.id
     and request_key = p_request_key;

  if found then
    return pg_catalog.jsonb_build_object(
      'alreadyProcessed', true,
      'alreadyCompleted', v_session.status = 'COMPLETED',
      'stepAlreadyAnswered',
        v_existing_attempt.step_key like 'quiz:%',
      'requestKey', v_existing_attempt.request_key,
      'stepKey', v_existing_attempt.step_key,
      'attemptNumber', v_existing_attempt.attempt_number,
      'score', v_existing_attempt.score,
      'responsePayload', v_existing_attempt.response_payload,
      'feedbackPayload', v_existing_attempt.feedback_payload,
      'xpEarned', case
        when v_existing_attempt.completes_session
          and v_session.status = 'COMPLETED'
          then v_session.xp_earned
        else 0
      end,
      'leveledUp', false,
      'newLevel', null
    );
  end if;

  if v_step_key like 'quiz:%' then
    select *
      into v_existing_attempt
      from public.wolfie_activity_attempts
     where session_id = v_session.id
       and step_key = v_step_key;

    if found then
      return pg_catalog.jsonb_build_object(
        'alreadyProcessed', true,
        'alreadyCompleted', v_session.status = 'COMPLETED',
        'stepAlreadyAnswered', true,
        'requestKey', v_existing_attempt.request_key,
        'stepKey', v_existing_attempt.step_key,
        'attemptNumber', v_existing_attempt.attempt_number,
        'score', v_existing_attempt.score,
        'responsePayload', v_existing_attempt.response_payload,
        'feedbackPayload', v_existing_attempt.feedback_payload,
        'xpEarned', case
          when v_existing_attempt.completes_session
            and v_session.status = 'COMPLETED'
            then v_session.xp_earned
          else 0
        end,
        'leveledUp', false,
        'newLevel', null
      );
    end if;
  end if;

  if v_session.status = 'COMPLETED' then
    return pg_catalog.jsonb_build_object(
      'alreadyProcessed', false,
      'alreadyCompleted', true,
      'stepAlreadyAnswered', false,
      'requestKey', p_request_key,
      'stepKey', v_step_key,
      'attemptNumber', v_session.attempt_count,
      'score', v_session.score,
      'xpEarned', v_session.xp_earned,
      'leveledUp', false,
      'newLevel', null
    );
  end if;

  if v_session.subject = 'global_meetings' then
    if not p_complete then
      if v_session.phase <> 'construction' then
        raise exception 'invalid_meeting_partial_phase';
      end if;

      if v_step_key is null
         or not (
           v_step_key = any (
             array[
               'opening',
               'context',
               'data',
               'proposal',
               'next_steps',
               'closing'
             ]::text[]
           )
         ) then
        raise exception 'invalid_meeting_section';
      end if;
    else
      if v_session.phase not in (
        'construction',
        'memorization',
        'readaptation'
      ) or (
        v_session.phase = 'construction'
        and v_step_key is distinct from 'construction_complete'
      ) or (
        v_session.phase = 'memorization'
        and v_step_key is distinct from 'memorization_complete'
      ) or (
        v_session.phase = 'readaptation'
        and (
          v_step_key is null
          or v_step_key not in ('readaptation', 'readaptation_speech')
        )
      ) then
        raise exception 'invalid_meeting_final_step';
      end if;

      if v_session.phase = 'construction' then
        select pg_catalog.count(distinct attempt.step_key)
          into v_meeting_section_count
          from public.wolfie_activity_attempts as attempt
         where attempt.session_id = v_session.id
           and not attempt.completes_session
           and attempt.step_key = any (
             array[
               'opening',
               'context',
               'data',
               'proposal',
               'next_steps',
               'closing'
             ]::text[]
           )
           and nullif(
             pg_catalog.btrim(attempt.response_payload ->> 'text'),
             ''
           ) is not null;

        if v_meeting_section_count <> 6 then
          raise exception 'meeting_sections_incomplete';
        end if;

        if (
          p_modality = 'text'
          and nullif(
            pg_catalog.btrim(p_response_payload ->> 'text'),
            ''
          ) is null
        ) or (
          p_modality = 'voice'
          and coalesce(
            p_response_payload ->> 'audioAnalyzed',
            'false'
          ) <> 'true'
        ) or p_modality not in ('text', 'voice') then
          raise exception 'invalid_meeting_final_response';
        end if;
      elsif v_session.phase = 'memorization' then
        if coalesce(
          (
            v_session.learner_state
              -> 'memorization'
              ->> 'rehearsalCount'
          )::integer,
          0
        ) < 1 then
          raise exception 'memorization_rehearsal_required';
        end if;
      elsif v_step_key = 'readaptation' then
        if p_modality <> 'text'
           or nullif(
             pg_catalog.btrim(p_response_payload ->> 'text'),
             ''
           ) is null then
          raise exception 'invalid_readaptation_response';
        end if;
      elsif v_step_key = 'readaptation_speech' then
        if p_modality <> 'voice'
           or coalesce(
             p_response_payload ->> 'audioAnalyzed',
             'false'
           ) <> 'true' then
          raise exception 'invalid_readaptation_response';
        end if;
      end if;
    end if;
  end if;

  if v_session.status in ('ABANDONED', 'FAILED')
     or (v_session.status = 'EVALUATING' and not p_complete) then
    raise exception 'session_not_writable';
  end if;

  v_attempt_number := v_session.attempt_count + 1;
  insert into public.wolfie_activity_attempts (
    session_id,
    tenant_id,
    student_id,
    request_key,
    attempt_number,
    step_key,
    modality,
    response_payload,
    feedback_payload,
    score,
    completes_session
  ) values (
    v_session.id,
    v_session.tenant_id,
    v_session.student_id,
    p_request_key,
    v_attempt_number,
    v_step_key,
    p_modality,
    coalesce(p_response_payload, '{}'::jsonb),
    coalesce(p_feedback_payload, '{}'::jsonb),
    p_score,
    p_complete
  );

  update public.wolfie_activity_sessions
     set attempt_count = v_attempt_number,
         duration_seconds = greatest(
           duration_seconds,
           least(p_duration_seconds, 86400)
         ),
         learner_state = case
           when v_session.subject = 'global_meetings'
             and v_session.phase = 'construction'
             and not p_complete then
             pg_catalog.jsonb_set(
               pg_catalog.jsonb_set(
                 coalesce(learner_state, '{}'::jsonb),
                 array['sections']::text[],
                 case
                   when pg_catalog.jsonb_typeof(
                     learner_state -> 'sections'
                   ) = 'object'
                     then learner_state -> 'sections'
                   else '{}'::jsonb
                 end,
                 true
               ),
               array['sections', v_step_key]::text[],
               pg_catalog.jsonb_build_object(
                 'original',
                   coalesce(p_response_payload ->> 'text', ''),
                 'corrected',
                   coalesce(
                     p_feedback_payload ->> 'correctedText',
                     p_response_payload ->> 'text',
                     ''
                   ),
                 'naturalVersion',
                   coalesce(
                     p_feedback_payload ->> 'naturalVersion',
                     p_feedback_payload ->> 'correctedText',
                     p_response_payload ->> 'text',
                     ''
                   ),
                 'score', p_score,
                 'savedAt', pg_catalog.now(),
                 'responsePayload',
                   coalesce(p_response_payload, '{}'::jsonb),
                 'feedbackPayload',
                   coalesce(p_feedback_payload, '{}'::jsonb)
               ),
               true
             )
           else learner_state
         end,
         updated_at = pg_catalog.now()
   where id = v_session.id;

  if p_complete then
    v_base_xp := case
      when v_session.subject = 'global_meetings'
        and v_session.phase = 'readaptation' then 100
      when v_session.subject = 'global_meetings' then 75
      when v_session.subject = 'conversation' then 60
      else 50
    end;
    v_xp_earned :=
      pg_catalog.round(v_base_xp * (p_score::numeric / 100));

    select
      coalesce(profile.xp, 0),
      coalesce(profile.level, 1),
      coalesce(profile.daily_xp, 0),
      profile.daily_xp_date,
      coalesce(profile.is_test_account, false)
      into
        v_profile_xp,
        v_profile_level,
        v_daily_xp,
        v_daily_xp_date,
        v_profile_test_fixture
      from public.profiles as profile
     where profile.id = v_session.student_id
       and profile.tenant_id = v_session.tenant_id
       and profile.role = 'STUDENT'
     for update;

    if not found then
      raise exception 'profile_scope_not_found';
    end if;

    v_effective_test_fixture :=
      v_session.test_fixture or v_profile_test_fixture;
    if v_effective_test_fixture then
      v_xp_earned := 0;
    end if;

    if v_daily_xp_date is distinct from v_today then
      v_daily_xp := 0;
    end if;

    -- Practice remains unlimited, while XP farming is capped server-side.
    v_xp_earned := least(
      v_xp_earned,
      greatest(0, 250 - v_daily_xp)
    );
    v_new_xp := v_profile_xp + v_xp_earned;
    v_new_level := pg_catalog.floor(v_new_xp / 1000) + 1;

    update public.profiles
       set xp = v_new_xp,
           level = v_new_level,
           daily_xp = v_daily_xp + v_xp_earned,
           daily_xp_date = v_today,
           last_activity = pg_catalog.now()
     where id = v_session.student_id
       and tenant_id = v_session.tenant_id;

    update public.wolfie_activity_sessions
       set status = 'COMPLETED',
           score = p_score,
           xp_earned = v_xp_earned,
           test_fixture = v_effective_test_fixture,
           completed_at = pg_catalog.now(),
           updated_at = pg_catalog.now()
     where id = v_session.id;

    insert into public.wolfie_learning_events (
      tenant_id,
      student_id,
      session_id,
      event_type,
      subject,
      cefr_level,
      metadata,
      test_fixture
    ) values (
      v_session.tenant_id,
      v_session.student_id,
      v_session.id,
      'SESSION_COMPLETED',
      v_session.subject,
      v_session.cefr_level,
      pg_catalog.jsonb_build_object(
        'score', p_score,
        'xpEarned', v_xp_earned,
        'phase', v_session.phase
      ),
      v_effective_test_fixture
    );

    return pg_catalog.jsonb_build_object(
      'alreadyProcessed', false,
      'alreadyCompleted', false,
      'stepAlreadyAnswered', false,
      'requestKey', p_request_key,
      'stepKey', v_step_key,
      'attemptNumber', v_attempt_number,
      'score', p_score,
      'xpEarned', v_xp_earned,
      'leveledUp', v_new_level > v_profile_level,
      'newLevel', v_new_level
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'alreadyProcessed', false,
    'alreadyCompleted', false,
    'stepAlreadyAnswered', false,
    'requestKey', p_request_key,
    'stepKey', v_step_key,
    'attemptNumber', v_attempt_number,
    'score', p_score,
    'xpEarned', 0,
    'leveledUp', false,
    'newLevel', null
  );
end;
$$;


--
-- Name: record_wolfie_fact(text, uuid, text, text, text, text, boolean, uuid, uuid, text, numeric, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_wolfie_fact(p_tenant_id text, p_student_id uuid, p_fact_type text, p_subject_key text, p_value text, p_normalized_value text, p_negated boolean, p_source_session_id uuid, p_source_turn_id uuid, p_source_transcript text, p_transcription_confidence numeric, p_evidence jsonb DEFAULT '{}'::jsonb, p_explicitly_confirmed boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  active_fact public.wolfie_facts%rowtype;
  next_fact_id uuid;
  observed_at timestamptz := now();
  bounded_confidence numeric(4, 3);
  repeated_source_turn boolean := false;
begin
  if p_tenant_id is null
     or p_student_id is null
     or nullif(btrim(p_fact_type), '') is null
     or nullif(btrim(p_subject_key), '') is null
     or nullif(btrim(p_value), '') is null
     or nullif(btrim(p_normalized_value), '') is null then
    raise exception using
      errcode = '22023',
      message = 'invalid_wolfie_fact';
  end if;
  if jsonb_typeof(coalesce(p_evidence, '{}'::jsonb)) <> 'object' then
    raise exception using
      errcode = '22023',
      message = 'invalid_wolfie_fact_evidence';
  end if;
  if p_fact_type not in ('resides_in', 'is_from', 'born_in') then
    raise exception using
      errcode = '22023',
      message = 'unsupported_wolfie_fact_type';
  end if;

  bounded_confidence := greatest(
    0::numeric,
    least(coalesce(p_transcription_confidence, 0.900), 1::numeric)
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_tenant_id || ':' || p_student_id::text || ':' ||
      p_fact_type || ':' || p_subject_key,
      0
    )
  );

  select *
    into active_fact
    from public.wolfie_facts
   where tenant_id = p_tenant_id
     and student_id = p_student_id
     and fact_type = p_fact_type
     and subject_key = p_subject_key
     and status = 'active'
   for update;

  repeated_source_turn := active_fact.id is not null
    and p_source_turn_id is not null
    and active_fact.source_turn_id = p_source_turn_id;

  if coalesce(p_negated, false) then
    if active_fact.id is not null
       and active_fact.normalized_value = p_normalized_value then
      update public.wolfie_facts
         set status = 'disputed',
             verification_status = 'rejected',
             disputed_at = observed_at,
             valid_to = observed_at,
             source_session_id = p_source_session_id,
             source_turn_id = p_source_turn_id,
             source_transcript = left(p_source_transcript, 4000),
             transcription_confidence = bounded_confidence,
             evidence = coalesce(active_fact.evidence, '{}'::jsonb)
               || coalesce(p_evidence, '{}'::jsonb)
               || jsonb_build_object('negated_at', observed_at)
       where id = active_fact.id;
      return active_fact.id;
    end if;
    return null;
  end if;

  if active_fact.id is not null
     and active_fact.normalized_value = p_normalized_value then
    update public.wolfie_facts
       set occurrence_count = case
             when repeated_source_turn then occurrence_count
             else least(occurrence_count + 1, 1000000)
           end,
           verification_status = case
             when coalesce(p_explicitly_confirmed, false) then 'confirmed'
             else verification_status
           end,
           confirmed_at = case
             when coalesce(p_explicitly_confirmed, false)
               then coalesce(confirmed_at, observed_at)
             else confirmed_at
           end,
           source_kind = case
             when coalesce(p_explicitly_confirmed, false)
               then 'learner_confirmation'
             else source_kind
           end,
           confidence = greatest(confidence, bounded_confidence),
           source_session_id = p_source_session_id,
           source_turn_id = p_source_turn_id,
           source_transcript = left(p_source_transcript, 4000),
           transcription_confidence = bounded_confidence,
           evidence = coalesce(active_fact.evidence, '{}'::jsonb)
             || coalesce(p_evidence, '{}'::jsonb)
             || jsonb_build_object(
               case when repeated_source_turn
                 then 'last_replayed_at'
                 else 'last_observed_at'
               end,
               observed_at
             )
     where id = active_fact.id;
    return active_fact.id;
  end if;

  if active_fact.id is not null then
    update public.wolfie_facts
       set status = 'superseded',
           valid_to = observed_at
     where id = active_fact.id;
  end if;

  insert into public.wolfie_facts (
    tenant_id,
    student_id,
    fact_type,
    subject_key,
    value,
    normalized_value,
    status,
    verification_status,
    confidence,
    occurrence_count,
    version,
    source_kind,
    source_session_id,
    source_turn_id,
    source_transcript,
    transcription_confidence,
    evidence,
    supersedes_fact_id,
    valid_from,
    confirmed_at
  ) values (
    p_tenant_id,
    p_student_id,
    p_fact_type,
    p_subject_key,
    left(btrim(p_value), 1000),
    left(btrim(p_normalized_value), 1000),
    'active',
    case
      when coalesce(p_explicitly_confirmed, false) then 'confirmed'
      else 'observed'
    end,
    bounded_confidence,
    1,
    coalesce(active_fact.version, 0) + 1,
    case
      when coalesce(p_explicitly_confirmed, false)
        then 'learner_confirmation'
      else 'learner_statement'
    end,
    p_source_session_id,
    p_source_turn_id,
    left(p_source_transcript, 4000),
    bounded_confidence,
    coalesce(p_evidence, '{}'::jsonb)
      || jsonb_build_object('observed_at', observed_at),
    active_fact.id,
    observed_at,
    case
      when coalesce(p_explicitly_confirmed, false) then observed_at
      else null
    end
  )
  returning id into next_fact_id;

  if active_fact.id is not null then
    update public.wolfie_facts
       set superseded_by_fact_id = next_fact_id
     where id = active_fact.id;
  end if;

  return next_fact_id;
end;
$$;


--
-- Name: record_wolfie_health(text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_wolfie_health(p_check text, p_healthy boolean, p_detail text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_admin   record;
  v_msg     text;
  v_alerted boolean := false;
  v_was_ok  boolean;
BEGIN
  INSERT INTO public.wolfie_health_log (check_name, healthy, detail)
  VALUES (p_check, COALESCE(p_healthy, false), left(COALESCE(p_detail, ''), 500));

  IF COALESCE(p_healthy, false) THEN
    RETURN jsonb_build_object('ok', true, 'alerted', false);
  END IF;

  SELECT id, phone, tenant_id, whatsapp_instance INTO v_admin
  FROM profiles
  WHERE role = 'SCHOOL_ADMIN'
    AND whatsapp_instance IS NOT NULL AND phone IS NOT NULL
  ORDER BY tenant_id LIMIT 1;
  IF v_admin.id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'alerted', false, 'reason', 'sem_admin');
  END IF;

  -- Um alerta por check por dia.
  IF EXISTS (
    SELECT 1 FROM automation_sent
    WHERE kind = 'WOLFIE_HEALTH' AND subject_id = p_check AND ref_date = current_date
  ) THEN
    RETURN jsonb_build_object('ok', true, 'alerted', false, 'reason', 'ja_avisado_hoje');
  END IF;

  -- Estava saudável antes? Serve para o texto dizer se é queda nova.
  SELECT healthy INTO v_was_ok FROM public.wolfie_health_log
  WHERE check_name = p_check AND created_at < now()
  ORDER BY created_at DESC OFFSET 1 LIMIT 1;

  v_msg := '🚨 *Wolfie fora do ar*' || E'\n\n' ||
           'A verificação automática de *' || p_check || '* falhou.' || E'\n\n' ||
           'Motivo: ' || left(COALESCE(p_detail, 'sem detalhe'), 220) || E'\n\n' ||
           CASE WHEN COALESCE(v_was_ok, false)
                THEN 'Funcionava na verificação anterior — a quebra é recente.'
                ELSE 'Também falhou na verificação anterior.' END ||
           E'\n\nOs alunos caem no modo clássico enquanto isso.';

  INSERT INTO automation_sent (kind, subject_id, ref_date)
  VALUES ('WOLFIE_HEALTH', p_check, current_date);

  PERFORM net.http_post(
    url := 'https://api.2b.app.br/message/sendText/' || v_admin.whatsapp_instance,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', (SELECT decrypted_secret FROM vault.decrypted_secrets
                 WHERE name = 'evolution_api_key' LIMIT 1)
    ),
    body := jsonb_build_object(
      'number', v_admin.phone, 'text', v_msg, 'delay', 0, 'linkPreview', false
    )
  );
  v_alerted := true;

  RETURN jsonb_build_object('ok', true, 'alerted', v_alerted);
END;
$$;


--
-- Name: record_wolfie_meeting_memories(text, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_wolfie_meeting_memories(p_tenant_id text, p_student_id uuid, p_source_session_id uuid, p_attempt_id uuid, p_memories jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_candidate jsonb;
  v_candidate_evidence jsonb;
  v_expected record;
  v_expected_count integer;
  v_unique_key_count integer;
  v_rubric_dimension text;
begin
  if p_tenant_id is null
     or p_student_id is null
     or p_source_session_id is null
     or p_attempt_id is null
     or pg_catalog.jsonb_typeof(p_memories) is distinct from 'array'
     or pg_catalog.jsonb_array_length(p_memories) not between 1 and 5 then
    raise exception using
      errcode = '22023',
      message = 'invalid_wolfie_meeting_memory_batch';
  end if;

  select *
    into v_expected
    from private.wolfie_meeting_memory_candidates(p_attempt_id)
   limit 1;
  if not found then
    raise exception using
      errcode = '22023',
      message = 'non_durable_wolfie_meeting_attempt';
  end if;
  if v_expected.candidate_tenant_id is distinct from p_tenant_id
     or v_expected.candidate_student_id is distinct from p_student_id
     or v_expected.candidate_source_session_id
       is distinct from p_source_session_id then
    raise exception using
      errcode = '23503',
      message = 'invalid_wolfie_meeting_memory_lineage';
  end if;

  select pg_catalog.count(*)::integer
    into v_expected_count
    from private.wolfie_meeting_memory_candidates(p_attempt_id);
  if pg_catalog.jsonb_array_length(p_memories) <> v_expected_count then
    raise exception using
      errcode = '22023',
      message = 'incomplete_wolfie_meeting_memory_batch';
  end if;

  for v_candidate in
    select value from pg_catalog.jsonb_array_elements(p_memories)
  loop
    if pg_catalog.jsonb_typeof(v_candidate) <> 'object'
       or pg_catalog.jsonb_typeof(v_candidate -> 'evidence')
         is distinct from 'object'
       or pg_catalog.jsonb_typeof(v_candidate -> 'confidence')
         is distinct from 'number' then
      raise exception using
        errcode = '22023',
        message = 'invalid_wolfie_meeting_memory_candidate';
    end if;

    v_candidate_evidence := v_candidate -> 'evidence';
    select *
      into v_expected
      from private.wolfie_meeting_memory_candidates(p_attempt_id) as expected
     where expected.candidate_memory_key = v_candidate ->> 'memoryKey'
       and expected.candidate_kind = v_candidate ->> 'kind'
       and expected.candidate_dimension =
         v_candidate_evidence ->> 'dimension';
    if not found then
      raise exception using
        errcode = '22023',
        message = 'invalid_wolfie_meeting_memory_identity';
    end if;

    if v_candidate ->> 'content'
         is distinct from v_expected.candidate_content
       or (v_candidate ->> 'confidence')::numeric
         is distinct from v_expected.candidate_confidence
       or v_candidate_evidence ->> 'basis'
         is distinct from 'session_assessment'
       or v_candidate_evidence ->> 'policyVersion' is distinct from '1'
       or v_candidate_evidence ->> 'attemptId'
         is distinct from p_attempt_id::text
       or pg_catalog.jsonb_typeof(v_candidate_evidence -> 'score')
         is distinct from 'number'
       or (v_candidate_evidence ->> 'score')::numeric
         is distinct from
           (v_expected.candidate_evidence ->> 'score')::numeric
       or pg_catalog.jsonb_typeof(v_candidate_evidence -> 'dimensionScore')
         is distinct from 'number'
       or (v_candidate_evidence ->> 'dimensionScore')::numeric
         is distinct from
           (v_expected.candidate_evidence ->> 'dimensionScore')::numeric
       or pg_catalog.jsonb_typeof(v_candidate_evidence -> 'rubric')
         is distinct from 'object' then
      raise exception using
        errcode = '22023',
        message = 'invalid_wolfie_meeting_memory_evidence';
    end if;

    foreach v_rubric_dimension in array array[
      'taskCompletion',
      'structureAndFacilitation',
      'interactionAndTurnTaking',
      'clarificationAndQuestionHandling',
      'diplomacyAndNegotiation',
      'clarityAndConcision',
      'accuracyAndNaturalness',
      'decisionAndActionableClose'
    ]
    loop
      if pg_catalog.jsonb_typeof(
           v_candidate_evidence -> 'rubric' -> v_rubric_dimension
         ) is distinct from 'number'
         or (
           v_candidate_evidence -> 'rubric' ->> v_rubric_dimension
         )::numeric is distinct from (
           v_expected.candidate_evidence
             -> 'rubric'
             ->> v_rubric_dimension
         )::numeric then
        raise exception using
          errcode = '22023',
          message = 'invalid_wolfie_meeting_memory_rubric';
      end if;
    end loop;
  end loop;

  select pg_catalog.count(distinct candidate.value ->> 'memoryKey')::integer
    into v_unique_key_count
    from pg_catalog.jsonb_array_elements(p_memories) as candidate(value);
  if v_unique_key_count <> v_expected_count then
    raise exception using
      errcode = '22023',
      message = 'duplicate_wolfie_meeting_memory_candidate';
  end if;

  return private.persist_wolfie_meeting_attempt_memories(p_attempt_id);
end;
$$;


--
-- Name: FUNCTION record_wolfie_meeting_memories(p_tenant_id text, p_student_id uuid, p_source_session_id uuid, p_attempt_id uuid, p_memories jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.record_wolfie_meeting_memories(p_tenant_id text, p_student_id uuid, p_source_session_id uuid, p_attempt_id uuid, p_memories jsonb) IS 'Compatibility validator for canonical meeting memories; durable writes are derived atomically from the persisted activity attempt.';


--
-- Name: record_wolfie_realtime_exchange(uuid, uuid, text, text, text, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_wolfie_realtime_exchange(p_session_id uuid, p_client_turn_id uuid, p_user_transcript text, p_assistant_transcript text, p_input_method text, p_asr_confidence numeric, p_transcript_is_rough_guide boolean) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare
  session_stage text;
  next_turn_index integer;
  student_turn_id uuid;
  assistant_turn_id uuid;
  stored_student_content text;
  stored_assistant_content text;
  student_inserted boolean := false;
  assistant_inserted boolean := false;
  normalized_input_method text := lower(btrim(p_input_method));
  recorded_at timestamptz := now();
begin
  if p_session_id is null or p_client_turn_id is null then
    raise exception using
      errcode = '22023',
      message = 'invalid_realtime_exchange_identity';
  end if;
  if nullif(btrim(p_user_transcript), '') is null
     or char_length(p_user_transcript) > 4000
     or nullif(btrim(p_assistant_transcript), '') is null
     or char_length(p_assistant_transcript) > 4000 then
    raise exception using
      errcode = '22023',
      message = 'invalid_realtime_exchange_transcript';
  end if;
  if normalized_input_method = ''
     or char_length(normalized_input_method) > 40
     or normalized_input_method !~ '^[a-z0-9_-]+$' then
    raise exception using
      errcode = '22023',
      message = 'invalid_realtime_input_method';
  end if;
  if p_asr_confidence is not null
     and (p_asr_confidence < 0 or p_asr_confidence > 1) then
    raise exception using
      errcode = '22023',
      message = 'invalid_realtime_asr_confidence';
  end if;
  if normalized_input_method ~ '(audio|voice|microphone|mic)'
     and not coalesce(p_transcript_is_rough_guide, false) then
    raise exception using
      errcode = '22023',
      message = 'audio_transcript_must_be_rough_guide';
  end if;

  -- Locking the owning session serializes turn-index allocation and makes the
  -- user/assistant pair atomic under concurrent completion callbacks.
  select current_stage
    into session_stage
    from public.wolfie_sessions
   where id = p_session_id
   for update;
  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'wolfie_session_not_found';
  end if;

  select id, content
    into student_turn_id, stored_student_content
    from public.wolfie_turns
   where session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'student';
  select id, content
    into assistant_turn_id, stored_assistant_content
    from public.wolfie_turns
   where session_id = p_session_id
     and client_turn_id = p_client_turn_id
     and speaker = 'wolfie';

  if student_turn_id is not null
     and stored_student_content <> btrim(p_user_transcript) then
    raise exception using
      errcode = '22023',
      message = 'realtime_client_turn_id_reused';
  end if;
  if assistant_turn_id is not null
     and stored_assistant_content <> btrim(p_assistant_transcript) then
    raise exception using
      errcode = '22023',
      message = 'realtime_client_turn_id_reused';
  end if;
  if student_turn_id is not null and assistant_turn_id is not null then
    return pg_catalog.jsonb_build_object(
      'studentTurnId', student_turn_id,
      'assistantTurnId', assistant_turn_id,
      'inserted', false
    );
  end if;

  select coalesce(max(turn_index), -1) + 1
    into next_turn_index
    from public.wolfie_turns
   where session_id = p_session_id;

  if student_turn_id is null then
    insert into public.wolfie_turns (
      session_id,
      speaker,
      content,
      turn_index,
      message_type,
      stage,
      structured_payload,
      requires_retry,
      language_code,
      speech_metrics,
      transcription_confidence,
      source_kind,
      client_turn_id
    ) values (
      p_session_id,
      'student',
      btrim(p_user_transcript),
      next_turn_index,
      'instruction',
      session_stage,
      pg_catalog.jsonb_build_object(
        'source', 'openai_realtime',
        'clientTurnId', p_client_turn_id,
        'inputMethod', normalized_input_method,
        'transcriptIsRoughGuide',
          coalesce(p_transcript_is_rough_guide, false),
        'eligibleForFactExtraction', false,
        'eligibleForCorrection', false
      ),
      false,
      null,
      pg_catalog.jsonb_build_object(
        'asrConfidence', p_asr_confidence,
        'inputMethod', normalized_input_method,
        'transcriptIsRoughGuide',
          coalesce(p_transcript_is_rough_guide, false)
      ),
      p_asr_confidence,
      'openai_realtime',
      p_client_turn_id
    )
    returning id into student_turn_id;
    student_inserted := true;
    next_turn_index := next_turn_index + 1;
  end if;

  if assistant_turn_id is null then
    insert into public.wolfie_turns (
      session_id,
      speaker,
      content,
      turn_index,
      message_type,
      stage,
      structured_payload,
      requires_retry,
      language_code,
      speech_metrics,
      transcription_confidence,
      source_kind,
      client_turn_id
    ) values (
      p_session_id,
      'wolfie',
      btrim(p_assistant_transcript),
      next_turn_index,
      'feedback',
      session_stage,
      pg_catalog.jsonb_build_object(
        'source', 'openai_realtime',
        'clientTurnId', p_client_turn_id,
        'inputMethod', normalized_input_method,
        'transcriptIsRoughGuide',
          coalesce(p_transcript_is_rough_guide, false),
        'eligibleForFactExtraction', false,
        'eligibleForCorrection', false
      ),
      false,
      null,
      '{}'::jsonb,
      null,
      'openai_realtime',
      p_client_turn_id
    )
    returning id into assistant_turn_id;
    assistant_inserted := true;
  end if;

  update public.wolfie_sessions
     set turn_count = greatest(0, coalesce(turn_count, 0)) +
           case when student_inserted or assistant_inserted then 1 else 0 end,
         student_word_count = greatest(
           0,
           coalesce(student_word_count, 0)
         ) + case
           when student_inserted then
             cardinality(
               pg_catalog.regexp_split_to_array(
                 btrim(p_user_transcript),
                 '\s+'
               )
             )
           else 0
         end,
         wolfie_word_count = greatest(
           0,
           coalesce(wolfie_word_count, 0)
         ) + case
           when assistant_inserted then
             cardinality(
               pg_catalog.regexp_split_to_array(
                 btrim(p_assistant_transcript),
                 '\s+'
               )
             )
           else 0
         end,
         last_activity_at = recorded_at,
         updated_at = recorded_at
   where id = p_session_id;

  return pg_catalog.jsonb_build_object(
    'studentTurnId', student_turn_id,
    'assistantTurnId', assistant_turn_id,
    'inserted', student_inserted or assistant_inserted
  );
end;
$_$;


--
-- Name: record_wolfie_realtime_usage(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_wolfie_realtime_usage(p_session_id uuid, p_client_turn_id uuid, p_usage jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_updated integer := 0;
  v_total integer;
  v_input_text integer;
  v_input_audio integer;
  v_output_text integer;
  v_output_audio integer;
  v_cached integer;
begin
  if p_session_id is null
     or p_client_turn_id is null
     or p_usage is null
     or pg_catalog.jsonb_typeof(p_usage) <> 'object' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'invalid_input'
    );
  end if;

  if coalesce(p_usage ->> 'totalTokens', '') !~ '^\d{1,10}$'
     or coalesce(p_usage ->> 'inputTextTokens', '') !~ '^\d{1,10}$'
     or coalesce(p_usage ->> 'inputAudioTokens', '') !~ '^\d{1,10}$'
     or coalesce(p_usage ->> 'outputTextTokens', '') !~ '^\d{1,10}$'
     or coalesce(p_usage ->> 'outputAudioTokens', '') !~ '^\d{1,10}$'
     or coalesce(p_usage ->> 'cachedTokens', '') !~ '^\d{1,10}$' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'invalid_usage_values'
    );
  end if;

  v_total := least((p_usage ->> 'totalTokens')::numeric, 2147483647)::integer;
  v_input_text := least(
    (p_usage ->> 'inputTextTokens')::numeric,
    2147483647
  )::integer;
  v_input_audio := least(
    (p_usage ->> 'inputAudioTokens')::numeric,
    2147483647
  )::integer;
  v_output_text := least(
    (p_usage ->> 'outputTextTokens')::numeric,
    2147483647
  )::integer;
  v_output_audio := least(
    (p_usage ->> 'outputAudioTokens')::numeric,
    2147483647
  )::integer;
  v_cached := least(
    (p_usage ->> 'cachedTokens')::numeric,
    2147483647
  )::integer;

  update public.wolfie_turns as turn_row
     set tokens_used = v_total,
         usage_input_text_tokens = v_input_text,
         usage_input_audio_tokens = v_input_audio,
         usage_output_text_tokens = v_output_text,
         usage_output_audio_tokens = v_output_audio,
         usage_cached_tokens = v_cached
   where turn_row.session_id = p_session_id
     and turn_row.client_turn_id = p_client_turn_id
     and turn_row.speaker = 'wolfie'
     and turn_row.source_kind = 'openai_realtime';

  get diagnostics v_updated = row_count;
  return pg_catalog.jsonb_build_object(
    'ok', v_updated = 1,
    'updated', v_updated
  );
exception
  when others then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'usage_write_failed'
    );
end;
$_$;


--
-- Name: record_xp_event(uuid, text, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_xp_event(p_student_id uuid, p_tenant_id text, p_source text, p_amount integer, p_ref_id text DEFAULT NULL::text, p_dedupe_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_config RECORD;
    v_event_id UUID;
    v_actual_amount INTEGER;
    v_daily_xp INTEGER;
    v_goal RECORD;
    v_streak RECORD;
BEGIN
    -- 1. Check gamification is enabled for tenant
    SELECT * INTO v_config FROM public.tenant_xp_config
    WHERE tenant_id = p_tenant_id;

    IF v_config IS NULL OR NOT v_config.gamification_enabled THEN
        RETURN jsonb_build_object('success', false, 'error', 'GAMIFICATION_DISABLED');
    END IF;

    -- 2. Resolve actual amount from config if available
    v_actual_amount := CASE p_source
        WHEN 'ATTENDANCE' THEN COALESCE(v_config.xp_attendance, p_amount)
        WHEN 'HOMEWORK' THEN COALESCE(v_config.xp_homework, p_amount)
        WHEN 'SRS_CORRECT' THEN COALESCE(v_config.xp_srs_correct, p_amount)
        WHEN 'SRS_STREAK' THEN COALESCE(v_config.xp_srs_streak_5, p_amount)
        WHEN 'WARMUP' THEN COALESCE(v_config.xp_warmup, p_amount)
        WHEN 'TRIAL_CONVERTED' THEN COALESCE(v_config.xp_trial_converted, p_amount)
        WHEN 'REFERRAL' THEN COALESCE(v_config.xp_referral_converted, p_amount)
        ELSE p_amount
    END;

    -- 3. Idempotent insert
    INSERT INTO public.xp_events (student_id, tenant_id, source, amount, ref_id, dedupe_key)
    VALUES (p_student_id, p_tenant_id, p_source, v_actual_amount, p_ref_id,
            COALESCE(p_dedupe_key, p_source || ':' || COALESCE(p_ref_id, gen_random_uuid()::text)))
    ON CONFLICT (dedupe_key) DO NOTHING
    RETURNING id INTO v_event_id;

    IF v_event_id IS NULL THEN
        -- Already recorded (idempotent)
        RETURN jsonb_build_object('success', true, 'deduplicated', true);
    END IF;

    -- 4. Check daily goal progress
    SELECT SUM(amount) INTO v_daily_xp
    FROM public.xp_events
    WHERE student_id = p_student_id
      AND created_at >= date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo');

    SELECT * INTO v_goal FROM public.student_daily_goals
    WHERE student_id = p_student_id;

    -- 5. Update streak if daily goal met
    IF v_goal IS NOT NULL AND v_daily_xp >= v_goal.target_xp THEN
        SELECT * INTO v_streak FROM public.student_streaks
        WHERE student_id = p_student_id FOR UPDATE;

        IF v_streak IS NULL THEN
            INSERT INTO public.student_streaks (student_id, tenant_id, current_streak, longest_streak, last_activity_date)
            VALUES (p_student_id, p_tenant_id, 1, 1, CURRENT_DATE)
            ON CONFLICT (student_id) DO NOTHING;
        ELSIF v_streak.last_activity_date IS NULL OR v_streak.last_activity_date < CURRENT_DATE THEN
            -- Only increment if not already counted today
            IF v_streak.last_activity_date = CURRENT_DATE - 1 THEN
                -- Consecutive day
                UPDATE public.student_streaks SET
                    current_streak = current_streak + 1,
                    longest_streak = GREATEST(longest_streak, current_streak + 1),
                    last_activity_date = CURRENT_DATE,
                    updated_at = now()
                WHERE student_id = p_student_id;
            ELSIF v_streak.last_activity_date < CURRENT_DATE - 1 THEN
                -- Streak broken (freeze logic handled by cron)
                UPDATE public.student_streaks SET
                    current_streak = 1,
                    last_activity_date = CURRENT_DATE,
                    updated_at = now()
                WHERE student_id = p_student_id;
            END IF;
        END IF;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'event_id', v_event_id,
        'amount', v_actual_amount,
        'daily_xp', v_daily_xp,
        'goal_met', (v_goal IS NOT NULL AND v_daily_xp >= v_goal.target_xp)
    );
END;
$$;


--
-- Name: recover_notification_delivery_submission(uuid, uuid, uuid, uuid, text, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_notification_delivery_submission(p_notification_id uuid, p_notification_claim_token uuid, p_outbound_attempt_id uuid, p_outbound_claim_token uuid, p_provider_instance_name text, p_integration_id uuid, p_integration_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_notification public.notification_queue%rowtype;
  v_outbound public.asaas_outbound_message_attempts%rowtype;
  v_instance_name text := pg_catalog.btrim(coalesce(
    p_provider_instance_name,
    ''
  ));
  v_is_payment boolean;
begin
  if p_notification_id is null
     or p_notification_claim_token is null
     or p_integration_id is null
     or coalesce(p_integration_version, 0) < 1
     or char_length(v_instance_name) not between 3 and 120 then
    raise exception 'invalid_notification_submission_recovery'
      using errcode = '22023';
  end if;

  select notification.*
  into v_notification
  from public.notification_queue as notification
  where notification.id = p_notification_id;

  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'notification_not_found'
    );
  end if;

  v_is_payment := private.canonical_payment_notification_kind(
    v_notification.notification_kind
  ) = 'PAYMENT_CONFIRMED_WHATSAPP';

  if v_notification.claim_token is null
     and v_notification.status = 'skipped'
     and v_notification.last_error = 'occurrence_already_notified' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'ALREADY_NOTIFIED',
      'reason', v_notification.last_error
    );
  end if;

  if v_is_payment and p_outbound_attempt_id is not null then
    select outbound.*
    into v_outbound
    from public.asaas_outbound_message_attempts as outbound
    where outbound.id = p_outbound_attempt_id
      and outbound.claim_token = p_outbound_claim_token;

    if found
       and v_notification.claim_token is null
       and v_notification.status = 'skipped'
       and v_outbound.status = 'SUPPRESSED'
       and v_outbound.notification_queue_id = v_notification.id then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'SUPPRESSED',
        'reason', coalesce(
          v_notification.last_error,
          v_outbound.last_error,
          'payment_confirmation_suppressed'
        )
      );
    end if;
  end if;

  if v_notification.claim_token is distinct from
       p_notification_claim_token
     or v_notification.status <> 'processing' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'notification_claim_changed'
    );
  end if;

  if v_notification.delivery_status = 'preparing' then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'RETRY_BEGIN',
      'reason', 'notification_begin_not_committed'
    );
  end if;

  if v_notification.delivery_status <> 'submitting'
     or v_notification.lease_expires_at <= now()
     or lower(coalesce(v_notification.provider_instance_name, '')) <>
       lower(v_instance_name)
     or v_notification.provider_destination is null
     or v_notification.provider_integration_id <> p_integration_id
     or v_notification.provider_integration_version <>
       p_integration_version then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'notification_submission_snapshot_changed'
    );
  end if;


  -- Reuse the exact idempotent begin authorization after all begin responses
  -- are lost. Its stored destination/message arguments force the conflict
  -- branch to lock and revalidate the current source before any provider POST.
  if upper(pg_catalog.btrim(coalesce(
       v_notification.notification_kind,
       ''
     ))) = 'CONFLICT_TEACHER_ALERT' then
    return public.begin_notification_delivery_submission(
      v_notification.id,
      p_notification_claim_token,
      v_instance_name,
      v_notification.student_phone,
      v_notification.provider_destination,
      v_notification.message_body,
      p_integration_id,
      p_integration_version
    );
  end if;

  if v_is_payment then
    if p_outbound_attempt_id is null or p_outbound_claim_token is null then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'payment_submission_claim_missing'
      );
    end if;

    select outbound.*
    into v_outbound
    from public.asaas_outbound_message_attempts as outbound
    where outbound.id = p_outbound_attempt_id
      and outbound.claim_token = p_outbound_claim_token
      and outbound.notification_queue_id = v_notification.id;

    if not found
       or v_outbound.status <> 'SUBMITTING'
       or v_outbound.submit_attempt_count <> 1
       or v_outbound.lease_expires_at <= now()
       or lower(coalesce(v_outbound.provider_instance_name, '')) <>
         lower(v_instance_name)
       or v_outbound.provider_destination is distinct from
         v_notification.provider_destination then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'payment_submission_snapshot_changed'
      );
    end if;

    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'SUBMITTING',
      'providerDestination', v_notification.provider_destination,
      'messageBody', v_notification.message_body
    );
  end if;

  if p_outbound_attempt_id is not null
     or p_outbound_claim_token is not null
     or (
       upper(pg_catalog.btrim(coalesce(
         v_notification.notification_kind,
         ''
       ))) = 'LESSON_REMINDER'
       and not exists (
         select 1
         from public.automation_sent as receipt
         where receipt.notification_id = v_notification.id
           and receipt.notification_claim_token =
             p_notification_claim_token
           and receipt.receipt_state = 'SEALED'
       )
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'generic_submission_receipt_changed'
    );
  end if;

  if upper(pg_catalog.btrim(coalesce(
       v_notification.notification_kind,
       ''
     ))) = 'CONFLICT_TEACHER_ALERT' then
    -- Reuse the exact locked authorization path. The begin RPC recognizes the
    -- sealed snapshot as an idempotent replay and does not mutate it, but it
    -- does re-lock and revalidate the conflict before authorizing the POST.
    return public.begin_notification_delivery_submission(
      v_notification.id,
      p_notification_claim_token,
      v_instance_name,
      v_notification.student_phone,
      v_notification.provider_destination,
      v_notification.message_body,
      p_integration_id,
      p_integration_version
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SUBMIT_AUTHORIZED',
    'providerDestination', v_notification.provider_destination,
    'messageBody', v_notification.message_body
  );
end;
$$;


--
-- Name: refresh_monthly_payment_closure(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_monthly_payment_closure(p_tenant_id text, p_period_start date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_tenant text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  v_period_start date := pg_catalog.date_trunc('month', p_period_start)::date;
  v_period_end date := (pg_catalog.date_trunc('month', p_period_start) + interval '1 month')::date;
  business_today date := (pg_catalog.now() at time zone 'America/Sao_Paulo')::date;
  closure_row public.monthly_payment_closures%rowtype;
  expected_count integer := 0;
  settled_count integer := 0;
  blocked_count integer := 0;
  missing_count integer := 0;
  open_count integer := 0;
  waiting_credit_count integer := 0;
  review_count integer := 0;
  unclassified_count integer := 0;
  reconciliation_count integer := 0;
  competence_billed numeric := 0;
  competence_settled numeric := 0;
  cash_report jsonb := '{}'::jsonb;
  cash_totals jsonb := '{}'::jsonb;
  rules_snapshot jsonb := '{}'::jsonb;
  blockers jsonb := '[]'::jsonb;
  obligation_states jsonb := '[]'::jsonb;
  next_snapshot jsonb;
  next_hash text;
  next_status text;
  destination text;
begin
  if normalized_tenant is null
     or p_period_start is null
     or v_period_start > pg_catalog.date_trunc(
       'month',
       pg_catalog.now() at time zone 'America/Sao_Paulo'
     )::date
     or v_period_start < date '2020-01-01'
     or not exists (
       select 1 from public.tenants as tenant
        where tenant.id = normalized_tenant
     )
  then
    raise exception using
      errcode = '22023',
      message = 'monthly_payment_closure_arguments_invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'monthly-payment-closure:' || normalized_tenant || ':' || v_period_start::text,
      0
    )
  );

  insert into public.monthly_payment_closures (tenant_id, period_start)
  values (normalized_tenant, v_period_start)
  on conflict on constraint monthly_payment_closures_pkey do nothing;

  -- Freeze every student that was either billable when this month was first
  -- observed or already has a recurring invoice in the competence. Subsequent
  -- refreshes can add a newly enrolled student, but never remove a frozen row.
  insert into public.monthly_payment_obligations (
    tenant_id,
    period_start,
    student_id,
    roster_source,
    expected_amount
  )
  select
    normalized_tenant,
    v_period_start,
    candidate.student_id,
    case when candidate.active_roster then 'ACTIVE_ROSTER'
         else 'RECORDED_INVOICE' end,
    greatest(coalesce(profile.monthly_fee, candidate.invoice_amount, 0), 0)
  from (
    select
      profile.id as student_id,
      true as active_roster,
      null::numeric as invoice_amount
    from public.profiles as profile
    join public.tenant_memberships as membership
      on membership.user_id = profile.id
     and membership.tenant_id = normalized_tenant
     and membership.role = 'STUDENT'
     and membership.status = 'ACTIVE'
   where profile.tenant_id = normalized_tenant
     and profile.role = 'STUDENT'
     and profile.status = 'Ativo'
     and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) = 'active'
     and coalesce(profile.monthly_fee, 0) > 0
     and coalesce(profile.is_test_account, false) is false
     and profile.test_fixture_key is null
     and profile.created_at < v_period_end
     and (profile.start_date is null or profile.start_date < v_period_end)

    union

    select
      payment.student_id,
      false,
      max(payment.value)
    from public.student_payments as payment
    join public.profiles as profile on profile.id = payment.student_id
   where payment.tenant_id = normalized_tenant
     and payment.student_id is not null
     and payment.payment_type = 'SUBSCRIPTION'
     and pg_catalog.upper(pg_catalog.btrim(coalesce(
       payment.status,
       ''
     ))) not in ('CANCELLED', 'NAO_RECEITA')
     and payment.due_date >= v_period_start
     and payment.due_date < v_period_end
     and coalesce(payment.value, 0) > 0
     and coalesce(profile.is_test_account, false) is false
     and profile.test_fixture_key is null
   group by payment.student_id
  ) as candidate
  join public.profiles as profile on profile.id = candidate.student_id
  on conflict on constraint monthly_payment_obligations_pkey do nothing;

  with invoice_stats as (
    select
      obligation.tenant_id,
      obligation.period_start,
      obligation.student_id,
      count(payment.id) filter (
        where payment.id is not null
          and upper(pg_catalog.btrim(coalesce(payment.status, ''))) not in (
            'CANCELLED', 'NAO_RECEITA'
          )
      )::integer as live_count,
      count(payment.id) filter (
        where upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
          'RECEIVED', 'RECEIVED_IN_CASH'
        )
          and coalesce(payment.refunded_amount, 0) = 0
      )::integer as settled_count,
      count(payment.id) filter (
        where upper(pg_catalog.btrim(coalesce(payment.status, ''))) = 'CONFIRMED'
      )::integer as confirmed_count,
      count(payment.id) filter (
        where coalesce(payment.refunded_amount, 0) > 0
          or upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
            'REFUNDED', 'PARTIALLY_REFUNDED'
          )
      )::integer as refunded_count,
      round(coalesce(sum(payment.value) filter (
        where upper(pg_catalog.btrim(coalesce(payment.status, ''))) not in (
          'CANCELLED', 'NAO_RECEITA'
        )
      ), 0), 2) as billed_amount,
      round(coalesce(sum(payment.value - coalesce(payment.refunded_amount, 0)) filter (
        where upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
          'RECEIVED', 'RECEIVED_IN_CASH'
        )
      ), 0), 2) as settled_amount,
      coalesce(array_agg(payment.id order by payment.id) filter (
        where payment.id is not null
          and upper(pg_catalog.btrim(coalesce(payment.status, ''))) not in (
            'CANCELLED', 'NAO_RECEITA'
          )
      ), '{}'::uuid[]) as payment_ids,
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'payment_id', payment.id,
            'status', payment.status,
            'provider_status', payment.provider_status,
            'value', payment.value,
            'billing_type', payment.billing_type,
            'refunded_amount', payment.refunded_amount
          ) order by payment.id
        ) filter (where payment.id is not null),
        '[]'::jsonb
      ) as invoices
    from public.monthly_payment_obligations as obligation
    left join public.student_payments as payment
      on payment.tenant_id = obligation.tenant_id
     and payment.student_id = obligation.student_id
     and payment.payment_type = 'SUBSCRIPTION'
     and payment.due_date >= obligation.period_start
     and payment.due_date < (
       pg_catalog.date_trunc('month', obligation.period_start) + interval '1 month'
     )::date
   where obligation.tenant_id = normalized_tenant
     and obligation.period_start = v_period_start
   group by obligation.tenant_id, obligation.period_start, obligation.student_id
  )
  update public.monthly_payment_obligations as obligation
     set billed_amount = invoice.billed_amount,
         settled_amount = invoice.settled_amount,
         payment_ids = invoice.payment_ids,
         status = case
           when coalesce(
               obligation.details ->> 'excluded_reason',
               ''
             ) = 'LEGACY_POST_OFFBOARDING_NO_LIVE_INVOICE'
             and invoice.live_count = 0
             then 'EXCLUDED'
           when obligation.status = 'EXCLUDED'
             and coalesce(
               obligation.details ->> 'excluded_reason',
               ''
             ) <> 'LEGACY_POST_OFFBOARDING_NO_LIVE_INVOICE'
             then 'EXCLUDED'
           when invoice.live_count = 0 then 'MISSING_BILL'
           when invoice.refunded_count > 0 then 'REVIEW'
           when invoice.live_count > 1 then 'REVIEW'
           when invoice.settled_count = invoice.live_count then 'SETTLED'
           when invoice.confirmed_count > 0 then 'WAITING_CREDIT'
           else 'OPEN'
         end,
         details = coalesce(
           obligation.details,
           '{}'::jsonb
         ) || jsonb_build_object(
           'invoice_count', invoice.live_count,
           'settled_count', invoice.settled_count,
           'confirmed_count', invoice.confirmed_count,
           'refunded_count', invoice.refunded_count,
           'invoices', invoice.invoices
         ),
         updated_at = pg_catalog.now()
    from invoice_stats as invoice
   where obligation.tenant_id = invoice.tenant_id
     and obligation.period_start = invoice.period_start
     and obligation.student_id = invoice.student_id;

  select
    count(*)::integer,
    count(*) filter (where obligation.status in ('SETTLED', 'EXCLUDED'))::integer,
    count(*) filter (where obligation.status not in ('SETTLED', 'EXCLUDED'))::integer,
    count(*) filter (where obligation.status = 'MISSING_BILL')::integer,
    count(*) filter (where obligation.status = 'OPEN')::integer,
    count(*) filter (where obligation.status = 'WAITING_CREDIT')::integer,
    count(*) filter (where obligation.status = 'REVIEW')::integer,
    round(coalesce(sum(obligation.billed_amount), 0), 2),
    round(coalesce(sum(obligation.settled_amount), 0), 2),
    coalesce(
      jsonb_agg(
        jsonb_build_object(
          'student_id', obligation.student_id,
          'student_name', profile.full_name,
          'status', obligation.status,
          'expected_amount', obligation.expected_amount,
          'billed_amount', obligation.billed_amount,
          'settled_amount', obligation.settled_amount
        ) order by profile.full_name
      ),
      '[]'::jsonb
    )
  into
    expected_count,
    settled_count,
    blocked_count,
    missing_count,
    open_count,
    waiting_credit_count,
    review_count,
    competence_billed,
    competence_settled,
    obligation_states
  from public.monthly_payment_obligations as obligation
  join public.profiles as profile on profile.id = obligation.student_id
  where obligation.tenant_id = normalized_tenant
    and obligation.period_start = v_period_start;

  select count(*)::integer
    into unclassified_count
    from public.student_payments as payment
   where payment.tenant_id = normalized_tenant
     and payment.student_id is null
     and payment.status in ('RECEIVED', 'RECEIVED_IN_CASH')
     and coalesce(payment.value, 0) > 0
     and payment.exclusion_reason is null
     and coalesce(
       payment.credited_at,
       payment.paid_at,
       payment.payment_date::timestamptz,
       payment.due_date::timestamptz
     ) >= v_period_start::timestamptz
     and coalesce(
       payment.credited_at,
       payment.paid_at,
       payment.payment_date::timestamptz,
       payment.due_date::timestamptz
     ) < v_period_end::timestamptz;

  select count(*)::integer
    into reconciliation_count
    from public.asaas_reconciliation_issues as issue
   where issue.tenant_id = normalized_tenant
     and issue.resolved_at is null
     and issue.severity in ('HIGH', 'CRITICAL')
     and (
       issue.local_entity_id in (
         select unnest(obligation.payment_ids)::text
           from public.monthly_payment_obligations as obligation
          where obligation.tenant_id = normalized_tenant
            and obligation.period_start = v_period_start
       )
       or issue.provider_entity_id in (
         select payment.asaas_payment_id
           from public.monthly_payment_obligations as obligation
           join public.student_payments as payment
             on payment.id = any(obligation.payment_ids)
          where obligation.tenant_id = normalized_tenant
            and obligation.period_start = v_period_start
       )
     );

  cash_report := public.payment_split_report(
    pg_catalog.to_char(v_period_start, 'YYYY-MM'),
    normalized_tenant
  );
  cash_totals := coalesce(cash_report -> 'totais', '{}'::jsonb);

  select jsonb_build_object(
           'direction', jsonb_build_object(
             'tithe_pct', setting.dizimo_pct,
             'investment_pct', setting.investimento_pct,
             'school_pct', setting.escola_pct
           ),
           'contracted_teacher', jsonb_build_object(
             'tithe_pct', setting.prof_dizimo_pct,
             'investment_pct', setting.prof_investimento_pct,
             'prolabore_pct', setting.prof_prolabore_pct
           ),
           'is_active', setting.is_active
         )
    into rules_snapshot
    from public.payment_split_settings as setting
   where setting.tenant_id = normalized_tenant;
  rules_snapshot := coalesce(rules_snapshot, '{}'::jsonb);

  select setting.destino
    into destination
    from public.dre_report_settings as setting
   where setting.tenant_id = normalized_tenant
     and setting.is_active;

  if business_today < v_period_end then
    blockers := blockers || jsonb_build_array('period_not_ended');
  end if;
  if expected_count = 0 then
    blockers := blockers || jsonb_build_array('no_expected_students');
  end if;
  if missing_count > 0 then
    blockers := blockers || jsonb_build_array('students_without_invoice');
  end if;
  if open_count > 0 then
    blockers := blockers || jsonb_build_array('open_invoices');
  end if;
  if waiting_credit_count > 0 then
    blockers := blockers || jsonb_build_array('card_confirmed_waiting_cash');
  end if;
  if review_count > 0 then
    blockers := blockers || jsonb_build_array('obligations_under_review');
  end if;
  if unclassified_count > 0 then
    blockers := blockers || jsonb_build_array('unclassified_cash');
  end if;
  if reconciliation_count > 0 then
    blockers := blockers || jsonb_build_array('open_reconciliation');
  end if;
  if destination is null then
    blockers := blockers || jsonb_build_array('management_group_inactive');
  end if;
  if coalesce((rules_snapshot ->> 'is_active')::boolean, false) is false then
    blockers := blockers || jsonb_build_array('payment_split_inactive');
  end if;

  next_status := case
    when jsonb_array_length(blockers) = 0 then 'READY'
    when business_today < v_period_end then 'OPEN'
    else 'BLOCKED'
  end;

  next_snapshot := jsonb_build_object(
    'tenant_id', normalized_tenant,
    'period_start', v_period_start,
    'period_end', v_period_end - 1,
    'timezone', 'America/Sao_Paulo',
    'status', next_status,
    'blockers', blockers,
    'roster', jsonb_build_object(
      'expected_students', expected_count,
      'settled_students', settled_count,
      'blocked_students', blocked_count,
      'missing_invoice_students', missing_count,
      'open_students', open_count,
      'waiting_credit_students', waiting_credit_count,
      'review_students', review_count,
      'items', obligation_states
    ),
    'competence', jsonb_build_object(
      'billed', competence_billed,
      'settled', competence_settled
    ),
    'cash', cash_totals,
    'rules', rules_snapshot,
    'unclassified_cash_count', unclassified_count,
    'open_reconciliation_count', reconciliation_count,
    'calculated_at', pg_catalog.now()
  );
  next_hash := pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to((next_snapshot - 'calculated_at')::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );

  select closure.*
    into closure_row
    from public.monthly_payment_closures as closure
   where closure.tenant_id = normalized_tenant
     and closure.period_start = v_period_start
   for update;

  if closure_row.sent_at is not null then
    if closure_row.snapshot_hash is distinct from next_hash then
      update public.monthly_payment_closures as target
         set status = 'REVIEW',
             review_reason = 'source_changed_after_monthly_close',
             updated_at = pg_catalog.now()
       where target.tenant_id = normalized_tenant
         and target.period_start = v_period_start;
    end if;
    return jsonb_build_object(
      'ok', true,
      'tenant_id', normalized_tenant,
      'period_start', v_period_start,
      'status', case when closure_row.snapshot_hash is distinct from next_hash
                     then 'REVIEW' else closure_row.status end,
      'already_sent', true,
      'snapshot', closure_row.snapshot
    );
  end if;

  -- A rejeição ou um timeout ambíguo do POST é terminal para esta competência:
  -- nunca tentamos um segundo envio irreversível. Preserve REVIEW nos sweeps
  -- seguintes até que um gestor faça a conciliação manual.
  if closure_row.status = 'REVIEW'
     and closure_row.review_reason in (
       'monthly_message_failed',
       'monthly_message_unknown',
       'monthly_message_suppressed'
     )
  then
    return jsonb_build_object(
      'ok', true,
      'tenant_id', normalized_tenant,
      'period_start', v_period_start,
      'status', 'REVIEW',
      'ready', false,
      'delivery_review', true,
      'review_reason', closure_row.review_reason,
      'snapshot', closure_row.snapshot
    );
  end if;

  update public.monthly_payment_closures as target
     set status = next_status,
         expected_students = expected_count,
         settled_students = settled_count,
         blocked_students = blocked_count,
         unclassified_cash_count = unclassified_count,
         open_reconciliation_count = reconciliation_count,
         snapshot = next_snapshot,
         snapshot_hash = next_hash,
         group_destination_snapshot = case
           when next_status = 'READY' then destination
           else null
         end,
         ready_at = case
           when next_status = 'READY' then coalesce(ready_at, pg_catalog.now())
           else null
         end,
         review_reason = null,
         updated_at = pg_catalog.now()
   where target.tenant_id = normalized_tenant
     and target.period_start = v_period_start;

  return jsonb_build_object(
    'ok', true,
    'tenant_id', normalized_tenant,
    'period_start', v_period_start,
    'status', next_status,
    'ready', next_status = 'READY',
    'snapshot_hash', next_hash,
    'snapshot', next_snapshot
  );
end;
$$;


--
-- Name: refresh_monthly_payment_closure_financial(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_monthly_payment_closure_financial(p_tenant_id text, p_period_start date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_tenant text := nullif(
    pg_catalog.btrim(coalesce(p_tenant_id, '')),
    ''
  );
  normalized_period date := pg_catalog.date_trunc(
    'month',
    p_period_start
  )::date;
  base_result jsonb;
  dre_result jsonb;
  dre_snapshot jsonb;
  augmented_snapshot jsonb;
  closure_row public.monthly_payment_closures%rowtype;
begin
  -- The base function owns roster construction, blockers and the source hash.
  -- Its advisory transaction lock remains held until this wrapper returns.
  base_result := public.refresh_monthly_payment_closure(
    normalized_tenant,
    normalized_period
  );
  if coalesce((base_result ->> 'ok')::boolean, false) is false then
    return base_result;
  end if;

  select closure.*
    into closure_row
    from public.monthly_payment_closures as closure
   where closure.tenant_id = normalized_tenant
     and closure.period_start = normalized_period
   for update;
  if not found then
    raise exception using
      errcode = '55000',
      message = 'monthly_payment_closure_missing_after_refresh';
  end if;

  dre_result := public.dre_gerencial(
    pg_catalog.to_char(normalized_period, 'YYYY-MM'),
    normalized_tenant
  );
  if dre_result is null
     or pg_catalog.jsonb_typeof(dre_result) <> 'object'
     or dre_result ? 'error'
  then
    raise exception using
      errcode = '55000',
      message = 'monthly_payment_closure_dre_unavailable';
  end if;

  dre_snapshot := pg_catalog.jsonb_build_object(
    'month', dre_result -> 'month',
    'regime', dre_result -> 'regime',
    'receita_bruta', dre_result -> 'receita_bruta',
    'deducoes', dre_result -> 'deducoes',
    'receita_liquida', dre_result -> 'receita_liquida',
    'custo_servicos', dre_result -> 'custo_servicos',
    'lucro_bruto', dre_result -> 'lucro_bruto',
    'margem_bruta_pct', dre_result -> 'margem_bruta_pct',
    'despesas_operacionais', dre_result -> 'despesas_operacionais',
    'resultado', dre_result -> 'resultado',
    'margem_liquida_pct', dre_result -> 'margem_liquida_pct',
    'indicadores', coalesce(dre_result -> 'indicadores', '{}'::jsonb),
    'linhas', coalesce(dre_result -> 'linhas', '[]'::jsonb),
    'alertas', coalesce(dre_result -> 'alertas', '[]'::jsonb)
  );

  -- After delivery, the original snapshot remains immutable. Any late
  -- operating cost or expense moves the close to REVIEW instead of silently
  -- rewriting, re-sending or presenting a different historical result.
  if closure_row.sent_at is not null then
    if closure_row.snapshot -> 'dre' is distinct from dre_snapshot then
      update public.monthly_payment_closures as closure
         set status = 'REVIEW',
             review_reason = coalesce(
               closure.review_reason,
               'dre_changed_after_monthly_close'
             ),
             updated_at = pg_catalog.now()
       where closure.tenant_id = normalized_tenant
         and closure.period_start = normalized_period;
      return base_result || pg_catalog.jsonb_build_object(
        'status', 'REVIEW',
        'ready', false,
        'already_sent', true,
        'dre_changed_after_monthly_close', true,
        'snapshot', closure_row.snapshot
      );
    end if;
    return base_result || pg_catalog.jsonb_build_object(
      'snapshot', closure_row.snapshot
    );
  end if;

  augmented_snapshot := closure_row.snapshot ||
    pg_catalog.jsonb_build_object('dre', dre_snapshot);
  update public.monthly_payment_closures as closure
     set snapshot = augmented_snapshot,
         updated_at = pg_catalog.now()
   where closure.tenant_id = normalized_tenant
     and closure.period_start = normalized_period;

  -- snapshot_hash deliberately remains the hash of the payment/roster source.
  -- The DRE is versioned independently above and compared explicitly after a
  -- sent close. This preserves the base function's idempotent source check.
  return base_result || pg_catalog.jsonb_build_object(
    'snapshot', augmented_snapshot
  );
end;
$$;


--
-- Name: refresh_teacher_closing_snapshot(text, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_teacher_closing_snapshot(p_tenant text, p_teacher uuid, p_month text, p_allow_create boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'service_role_required';
  END IF;
  RETURN private.refresh_teacher_closing_snapshot(
    p_tenant,
    p_teacher,
    p_month,
    p_allow_create
  );
END;
$$;


--
-- Name: refresh_xp_totals_debounced(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_xp_totals_debounced() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_lock_id BIGINT := 8675309; -- Arbitrary fixed lock ID for this matview
    v_last_refresh TIMESTAMPTZ;
BEGIN
    -- Try to acquire advisory lock (non-blocking)
    IF pg_try_advisory_xact_lock(v_lock_id) THEN
        -- Check if matview was refreshed recently (simple approach: always refresh if lock acquired)
        -- The advisory lock + trigger timing naturally debounces (only one tx at a time)
        REFRESH MATERIALIZED VIEW CONCURRENTLY public.student_xp_totals;
    END IF;

    RETURN NEW;
EXCEPTION
    WHEN OTHERS THEN
        -- Never block XP insertion because of matview refresh failure
        RAISE WARNING 'Matview refresh failed (non-blocking): %', SQLERRM;
        RETURN NEW;
END;
$$;


--
-- Name: FUNCTION refresh_xp_totals_debounced(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.refresh_xp_totals_debounced() IS 'Debounced matview refresh using advisory lock. Fires per-statement (not per-row) to batch inserts.';


--
-- Name: register_advance_payment(uuid, numeric, integer, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_advance_payment(p_student uuid, p_total numeric, p_months integer, p_start date DEFAULT CURRENT_DATE, p_due_day integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_monthly numeric; v_through date;
BEGIN
  IF COALESCE(_my_role(),'') NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem permissão');
  END IF;
  IF p_months IS NULL OR p_months <= 0 OR p_total IS NULL OR p_total <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'meses/valor inválidos');
  END IF;
  v_monthly := round(p_total / p_months, 2);
  v_through := (p_start + (p_months || ' months')::interval)::date;
  UPDATE profiles SET
    monthly_fee = v_monthly, monthly_tuition = v_monthly,
    due_day = COALESCE(p_due_day, due_day, EXTRACT(day FROM p_start)::int),
    paid_through = v_through, prepaid_months = p_months,
    status_financial = 'ACTIVE'
  WHERE id = p_student AND role='STUDENT';
  RETURN jsonb_build_object('ok', true, 'monthly_equiv', v_monthly, 'paid_through', v_through, 'months', p_months);
END; $$;


--
-- Name: release_affiliate_reward(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_affiliate_reward(p_conversion_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_conv RECORD;
    v_settings RECORD;
    v_referrer RECORD;
    v_monthly_count INTEGER;
    v_last_reward TIMESTAMPTZ;
    v_fraud_flags JSONB := '[]'::jsonb;
BEGIN
    -- 1. Lock and fetch conversion
    SELECT * INTO v_conv FROM public.affiliate_conversions
    WHERE id = p_conversion_id FOR UPDATE;

    IF v_conv IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'CONVERSION_NOT_FOUND');
    END IF;

    -- 2. Idempotency: already released
    IF v_conv.status = 'REWARD_RELEASED' THEN
        RETURN jsonb_build_object('success', true, 'already_released', true);
    END IF;

    -- 3. Only process confirmed payments
    IF v_conv.status != 'PAYMENT_CONFIRMED' THEN
        RETURN jsonb_build_object('success', false, 'error', 'NOT_PAYMENT_CONFIRMED');
    END IF;

    -- 4. Fetch tenant settings
    SELECT * INTO v_settings FROM public.tenant_referral_settings
    WHERE tenant_id = v_conv.tenant_id;

    IF v_settings IS NULL OR NOT v_settings.enabled THEN
        RETURN jsonb_build_object('success', false, 'error', 'REFERRAL_DISABLED');
    END IF;

    -- 5. Anti-fraud: self-referral check
    IF v_settings.self_referral_block AND v_conv.referrer_id = v_conv.referred_id THEN
        UPDATE public.affiliate_conversions
        SET status = 'BLOCKED_FRAUD',
            fraud_flags = fraud_flags || '["SELF_REFERRAL"]'::jsonb
        WHERE id = p_conversion_id;
        RETURN jsonb_build_object('success', false, 'error', 'SELF_REFERRAL_BLOCKED');
    END IF;

    -- 6. Anti-fraud: monthly cap
    SELECT COUNT(*) INTO v_monthly_count
    FROM public.affiliate_conversions
    WHERE referrer_id = v_conv.referrer_id
      AND tenant_id = v_conv.tenant_id
      AND status = 'REWARD_RELEASED'
      AND reward_released_at >= date_trunc('month', now());

    IF v_monthly_count >= v_settings.monthly_cap THEN
        v_fraud_flags := v_fraud_flags || '["MONTHLY_CAP_EXCEEDED"]'::jsonb;
        UPDATE public.affiliate_conversions
        SET fraud_flags = v_fraud_flags
        WHERE id = p_conversion_id;
        RETURN jsonb_build_object('success', false, 'error', 'MONTHLY_CAP_EXCEEDED');
    END IF;

    -- 7. Anti-fraud: cooldown check
    SELECT MAX(reward_released_at) INTO v_last_reward
    FROM public.affiliate_conversions
    WHERE referrer_id = v_conv.referrer_id
      AND tenant_id = v_conv.tenant_id
      AND status = 'REWARD_RELEASED';

    IF v_last_reward IS NOT NULL AND
       v_last_reward > (now() - make_interval(days => v_settings.cooldown_days)) THEN
        v_fraud_flags := v_fraud_flags || '["COOLDOWN_ACTIVE"]'::jsonb;
        UPDATE public.affiliate_conversions SET fraud_flags = v_fraud_flags WHERE id = p_conversion_id;
        RETURN jsonb_build_object('success', false, 'error', 'COOLDOWN_ACTIVE');
    END IF;

    -- 8. Determine reward amount based on referrer type
    SELECT * INTO v_referrer FROM public.profiles WHERE id = v_conv.referrer_id;

    DECLARE
        v_reward NUMERIC(10,2);
    BEGIN
        IF v_referrer.role = 'TEACHER' THEN
            v_reward := v_settings.teacher_reward_brl;
        ELSE
            v_reward := v_settings.student_reward_brl;
        END IF;

        -- 9. Release reward
        UPDATE public.affiliate_conversions SET
            status = 'REWARD_RELEASED',
            reward_amount_brl = v_reward,
            reward_released_at = now(),
            fraud_flags = v_fraud_flags
        WHERE id = p_conversion_id;

        -- 10. Increment conversion counter
        UPDATE public.affiliate_codes
        SET total_conversions = total_conversions + 1
        WHERE id = v_conv.affiliate_code_id;

        RETURN jsonb_build_object(
            'success', true,
            'reward_amount', v_reward,
            'referrer_id', v_conv.referrer_id,
            'referrer_type', v_referrer.role
        );
    END;
END;
$$;


--
-- Name: release_asaas_webhook_worker(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_asaas_webhook_worker(p_worker_token uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.asaas_automation_worker_locks
     set lease_owner = null,
         lease_expires_at = null,
         updated_at = now()
   where worker_name = 'webhook'
     and lease_owner = p_worker_token;
$$;


--
-- Name: release_invite_offer_claim_server(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_invite_offer_claim_server(p_offer_id uuid, p_kind text, p_claim_token uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH released AS (
    UPDATE public.offers AS offer
    SET invite_claim_token = NULL,
        invite_claimed_at = NULL
    WHERE offer.id = p_offer_id
      AND offer.kind = p_kind
      AND offer.invite_claim_token = p_claim_token
      AND offer.consumed_at IS NULL
    RETURNING 1
  )
  SELECT EXISTS (SELECT 1 FROM released);
$$;


--
-- Name: release_student_asaas_creation_lifecycle(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_student_asaas_creation_lifecycle(p_attempt_id uuid, p_tenant_id text, p_student_id uuid, p_provider_entity_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.asaas_provider_creation_attempts%rowtype;
  profile_row public.profiles%rowtype;
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  normalized_provider_id text := nullif(trim(coalesce(p_provider_entity_id, '')), '');
  local_binding_matches boolean := false;
begin
  if p_attempt_id is null or normalized_tenant is null or p_student_id is null
     or normalized_provider_id is null
  then
    raise exception using errcode = '22023', message = 'invalid_student_creation_lifecycle_release';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' || p_student_id::text,
      0
    )
  );
  select attempt.* into attempt_row
    from public.asaas_provider_creation_attempts as attempt
   where attempt.id = p_attempt_id
   for update;
  if not found
     or attempt_row.tenant_id is distinct from normalized_tenant
     or attempt_row.lifecycle_student_id is distinct from p_student_id
     or attempt_row.lifecycle_bound_at is null
     or attempt_row.status <> 'SUCCEEDED'
     or attempt_row.provider_entity_id is distinct from normalized_provider_id
  then
    return jsonb_build_object('ok', false, 'reason', 'creation_binding_not_ready');
  end if;
  if attempt_row.lifecycle_released_at is not null then
    return jsonb_build_object('ok', true, 'action', 'ALREADY_RELEASED');
  end if;

  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_student_id
     and profile.tenant_id = normalized_tenant
     and profile.role = 'STUDENT'
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
   for share;
  if not found
     or (
       select count(*) from public.tenant_memberships as membership
        where membership.user_id = p_student_id
     ) <> 1
     or not exists (
       select 1 from public.tenant_memberships as membership
        where membership.user_id = p_student_id
          and membership.tenant_id = normalized_tenant
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
     )
  then
    return jsonb_build_object('ok', false, 'reason', 'student_lifecycle_changed');
  end if;

  local_binding_matches := case attempt_row.lifecycle_binding_kind
    when 'CUSTOMER' then
      nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
        is not distinct from normalized_provider_id
    when 'ENROLLMENT_PAYMENT' then
      nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
        is not distinct from attempt_row.lifecycle_expected_customer_id
      and nullif(trim(coalesce(profile_row.enrollment_payment_id, '')), '')
        is not distinct from normalized_provider_id
    when 'SUBSCRIPTION' then
      nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
        is not distinct from attempt_row.lifecycle_expected_customer_id
      and nullif(trim(coalesce(profile_row.subscription_id, '')), '')
        is not distinct from normalized_provider_id
    when 'BILLING_PERIOD_PAYMENT' then
      nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
        is not distinct from attempt_row.lifecycle_expected_customer_id
      and exists (
        select 1 from public.asaas_student_billing_period_claims as billing
         where billing.tenant_id = normalized_tenant
           and billing.student_id = p_student_id
           and billing.provider_entity_id = normalized_provider_id
           and billing.status = 'BOUND'
      )
      and (
        select count(*) from public.student_payments as payment
         where payment.tenant_id = normalized_tenant
           and payment.student_id = p_student_id
           and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = normalized_provider_id
           and nullif(trim(coalesce(payment.provider_customer_id, '')), '')
                is not distinct from attempt_row.lifecycle_expected_customer_id
           and upper(coalesce(payment.status, '')) = 'PENDING'
           and payment.due_date >= current_date
      ) = 1
    when 'STUDENT_PAYMENT' then
      nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
        is not distinct from attempt_row.lifecycle_expected_customer_id
      and (
        select count(*) from public.student_payments as payment
         where payment.tenant_id = normalized_tenant
           and payment.student_id = p_student_id
           and nullif(trim(coalesce(payment.asaas_payment_id, '')), '') = normalized_provider_id
           and nullif(trim(coalesce(payment.provider_customer_id, '')), '')
                is not distinct from attempt_row.lifecycle_expected_customer_id
           and upper(trim(coalesce(payment.status, ''))) in (
             'PENDING', 'OVERDUE', 'RECEIVED', 'RECEIVED_IN_CASH'
           )
      ) = 1
    when 'TOPUP_ORDER' then
      nullif(trim(coalesce(profile_row.asaas_customer_id, '')), '')
        is not distinct from attempt_row.lifecycle_expected_customer_id
      and exists (
        select 1 from public.wolfie_topup_orders as topup
         where topup.id::text = attempt_row.logical_key
           and topup.tenant_id = normalized_tenant
           and topup.student_id = p_student_id
           and topup.provider_payment_id = normalized_provider_id
           and topup.status = 'AWAITING_PAYMENT'
           and topup.reconciliation_required is false
      )
    else false
  end;
  if local_binding_matches is not true then
    update public.asaas_provider_creation_attempts
       set lifecycle_last_error = 'local_provider_binding_unverified',
           updated_at = now()
     where id = attempt_row.id;
    return jsonb_build_object('ok', false, 'reason', 'local_provider_binding_unverified');
  end if;

  update public.asaas_provider_creation_attempts
     set lifecycle_released_at = now(),
         lifecycle_last_error = null,
         updated_at = now()
   where id = attempt_row.id;
  return jsonb_build_object('ok', true, 'action', 'RELEASED');
end;
$$;


--
-- Name: release_student_complementary_generation(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_student_complementary_generation(p_reservation_id uuid, p_lease_token uuid, p_request_key uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.assert_active_student_learning_mutation();
  return public.release_student_complementary_generation_core(
    p_reservation_id,
    p_lease_token,
    p_request_key,
    p_reason
  );
end;
$$;


--
-- Name: release_student_complementary_generation_core(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_student_complementary_generation_core(p_reservation_id uuid, p_lease_token uuid, p_request_key uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_id uuid := auth.uid();
  v_profile record;
  v_reservation public.student_complementary_generation_reservations%rowtype;
  v_reason text := nullif(pg_catalog.btrim(coalesce(p_reason, '')), '');
  v_now timestamptz := pg_catalog.now();
begin
  if v_student_id is null
     or p_reservation_id is null
     or p_lease_token is null
     or p_request_key is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  if v_reason is not null and pg_catalog.length(v_reason) > 500 then
    raise exception using
      errcode = '22023',
      message = 'invalid_generation_release_reason';
  end if;

  select profile.tenant_id, profile.role
    into v_profile
    from public.profiles as profile
   where profile.id = v_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  select *
    into v_reservation
    from public.student_complementary_generation_reservations as reservation
   where reservation.id = p_reservation_id
     and reservation.student_id = v_student_id
     and reservation.tenant_id = v_profile.tenant_id
     and reservation.request_key = p_request_key
   for update;

  if not found or v_reservation.lease_token is distinct from p_lease_token then
    raise exception using
      errcode = '42501',
      message = 'generation_reservation_not_owned';
  end if;

  if v_reservation.status <> 'RESERVED' then
    return pg_catalog.jsonb_build_object(
      'reservationId', v_reservation.id,
      'requestKey', v_reservation.request_key,
      'status', v_reservation.status,
      'code', v_reservation.decision_code,
      'reason', v_reservation.failure_reason,
      'replay', true
    );
  end if;

  update public.student_complementary_generation_reservations
     set status = 'RELEASED',
         decision_code = 'RELEASED',
         failure_reason = v_reason,
         completed_at = v_now,
         updated_at = v_now
   where id = v_reservation.id
  returning * into v_reservation;

  return pg_catalog.jsonb_build_object(
    'reservationId', v_reservation.id,
    'requestKey', v_reservation.request_key,
    'status', v_reservation.status,
    'code', v_reservation.decision_code,
    'reason', v_reservation.failure_reason,
    'replay', false
  );
end;
$$;


--
-- Name: FUNCTION release_student_complementary_generation_core(p_reservation_id uuid, p_lease_token uuid, p_request_key uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.release_student_complementary_generation_core(p_reservation_id uuid, p_lease_token uuid, p_request_key uuid, p_reason text) IS 'Releases an owned generation lease after provider or persistence failure without allowing cost-limit bypass.';


--
-- Name: release_wolfie_live_grant(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_wolfie_live_grant(p_grant_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.wolfie_live_grants
     set status = 'RELEASED',
         settled_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where id = p_grant_id
     and status = 'RESERVED';
  return found;
end;
$$;


--
-- Name: rename_niche(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_niche(p_key text, p_label text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  RETURN public.rename_niche_unchecked(p_key, p_label);
END;
$$;


--
-- Name: rename_niche_unchecked(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rename_niche_unchecked(p_key text, p_label text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;
  IF p_label IS NULL OR length(trim(p_label)) < 2 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'label_invalido');
  END IF;
  UPDATE tenant_niches SET label = trim(p_label)
   WHERE tenant_id = v_tenant AND key = p_key;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'nao_encontrado'); END IF;
  RETURN jsonb_build_object('ok', true, 'key', p_key, 'label', trim(p_label));
END;
$$;


--
-- Name: reopen_enrollment_offer_for_unsettled_payment(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_enrollment_offer_for_unsettled_payment(p_offer_id uuid, p_user_id uuid, p_provider_payment_id text, p_reason text DEFAULT 'payment_refunded'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  offer_tenant text;
  offer_row public.offers%rowtype;
  profile_row public.profiles%rowtype;
  payment_id text := nullif(trim(coalesce(p_provider_payment_id, '')), '');
  normalized_reason text := lower(trim(coalesce(p_reason, '')));
  offer_fee_id text;
  profile_fee_id text;
  one_time_id text;
  pro_rata_id text;
  activation_primary_id text;
  activation_legacy_id text;
  payment_kind text;
  binding_count integer := 0;
  was_completed boolean;
  preserve_current_profile boolean := false;
  profiles_have_updated_at boolean := false;
begin
  select exists(
    select 1
    from pg_catalog.pg_attribute a
    join pg_catalog.pg_class c on c.oid = a.attrelid
    join pg_catalog.pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname = 'profiles'
      and a.attname = 'updated_at'
      and not a.attisdropped
      and a.attnum > 0
  ) into profiles_have_updated_at;

  if p_offer_id is null or p_user_id is null or payment_id is null
     or normalized_reason not in ('payment_refunded', 'payment_not_settled')
  then
    raise exception using
      errcode = '22023',
      message = 'invalid_enrollment_refund_reopen';
  end if;

  select offer.tenant_id into offer_tenant
    from public.offers as offer
   where offer.id = p_offer_id
     and offer.kind = 'ENROLLMENT';
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'offer_not_owned');
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || offer_tenant || ':' || p_user_id::text,
      0
    )
  );

  select offer.* into offer_row
    from public.offers as offer
   where offer.id = p_offer_id
     and offer.tenant_id = offer_tenant
     and offer.kind = 'ENROLLMENT'
   for update;
  if not found or (
    offer_row.processing_by is distinct from p_user_id
    and offer_row.consumed_by is distinct from p_user_id
  ) then
    return jsonb_build_object('ok', false, 'reason', 'offer_not_owned');
  end if;
  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_user_id
     and profile.tenant_id = offer_tenant
     and profile.role = 'STUDENT'
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'profile_not_found');
  end if;

  offer_fee_id := nullif(trim(coalesce(
    offer_row.metadata ->> 'enrollment_payment_id', ''
  )), '');
  profile_fee_id := nullif(trim(coalesce(
    profile_row.enrollment_payment_id, ''
  )), '');
  one_time_id := nullif(trim(coalesce(
    offer_row.metadata ->> 'one_time_payment_id', ''
  )), '');
  pro_rata_id := case
    when offer_row.payload ->> 'enableProRata' = 'true' then nullif(
      trim(coalesce(offer_row.metadata ->> 'pro_rata_charge_id', '')),
      ''
    )
    else null
  end;
  activation_primary_id := nullif(trim(coalesce(
    offer_row.metadata ->> 'subscription_activation_payment_id', ''
  )), '');
  activation_legacy_id := nullif(trim(coalesce(
    offer_row.metadata ->> 'activation_payment_id', ''
  )), '');
  if activation_primary_id is not null and activation_legacy_id is not null
     and activation_primary_id <> activation_legacy_id
  then
    return jsonb_build_object('ok', false, 'reason', 'payment_binding_ambiguous');
  end if;

  if payment_id = coalesce(offer_fee_id, profile_fee_id) then
    binding_count := binding_count + 1;
    payment_kind := 'ENROLLMENT_FEE';
  end if;
  if payment_id = one_time_id then
    binding_count := binding_count + 1;
    payment_kind := 'ONE_TIME';
  end if;
  if payment_id = pro_rata_id then
    binding_count := binding_count + 1;
    payment_kind := 'PRO_RATA';
  end if;
  if payment_id = coalesce(activation_primary_id, activation_legacy_id) then
    binding_count := binding_count + 1;
    payment_kind := 'ACTIVATION';
  end if;
  if binding_count = 0 then
    return jsonb_build_object('ok', false, 'reason', 'payment_not_bound');
  elsif binding_count > 1 then
    return jsonb_build_object('ok', false, 'reason', 'payment_binding_ambiguous');
  end if;

  preserve_current_profile := payment_kind = 'ENROLLMENT_FEE'
    and offer_fee_id = payment_id
    and profile_fee_id is not null
    and profile_fee_id <> payment_id;
  was_completed := offer_row.processing_state = 'COMPLETED';

  if not preserve_current_profile then
    if profiles_have_updated_at then
      update public.profiles
         set enrollment_fee_paid = case
               when payment_kind = 'ENROLLMENT_FEE' then false
               else enrollment_fee_paid
             end,
             status_financial = 'PENDING',
             updated_at = now()
       where id = p_user_id
         and tenant_id = offer_tenant;
    else
      update public.profiles
         set enrollment_fee_paid = case
               when payment_kind = 'ENROLLMENT_FEE' then false
               else enrollment_fee_paid
             end,
             status_financial = 'PENDING'
       where id = p_user_id
         and tenant_id = offer_tenant;
    end if;
  end if;

  update public.offers
     set metadata = case
           when payment_kind = 'ENROLLMENT_FEE'
             then coalesce(metadata, '{}'::jsonb) - 'enrollment_fee_paid_at'
           when payment_kind = 'ONE_TIME'
             then coalesce(metadata, '{}'::jsonb) - 'one_time_paid_at'
           when payment_kind = 'PRO_RATA'
             then coalesce(metadata, '{}'::jsonb) - 'pro_rata_paid_at'
           else coalesce(metadata, '{}'::jsonb)
             - 'subscription_activation_received_at'
         end,
         processing_state = 'AWAITING_PAYMENT',
         processing_updated_at = now(),
         processing_completed_at = null,
         processing_error_code = normalized_reason,
         processing_error_message = case
           when normalized_reason = 'payment_refunded'
             then 'Provider payment was fully refunded'
           else 'Provider payment is not settled'
         end
   where id = p_offer_id;

  if was_completed or preserve_current_profile then
    insert into public.asaas_reconciliation_issues (
      tenant_id, source, kind, severity, provider_entity_id,
      local_entity_id, fingerprint, details
    ) values (
      offer_tenant,
      'ENROLLMENT',
      case when preserve_current_profile
        then 'HISTORICAL_ENROLLMENT_PAYMENT_REFUNDED'
        when normalized_reason = 'payment_refunded'
          then 'ENROLLMENT_PAYMENT_REFUNDED_AFTER_COMPLETION'
        else 'ENROLLMENT_ACTIVATED_BEFORE_SETTLEMENT'
      end,
      case when normalized_reason = 'payment_refunded' then 'CRITICAL' else 'HIGH' end,
      payment_id,
      p_offer_id::text,
      'enrollment-unsettled:' || p_offer_id::text || ':' || payment_id,
      jsonb_build_object(
        'paymentKind', payment_kind,
        'reason', normalized_reason,
        'userId', p_user_id,
        'commercialSideEffectsPreserved', true,
        'currentProfileAccessPreserved', preserve_current_profile
      )
    ) on conflict do nothing;
  end if;

  return jsonb_build_object(
    'ok', true,
    'action', case when preserve_current_profile
      then 'HISTORICAL_OFFER_REOPENED'
      else 'REOPENED'
    end,
    'processing_state', 'AWAITING_PAYMENT',
    'payment_kind', payment_kind,
    'reason', normalized_reason,
    'was_completed', was_completed,
    'current_profile_access_preserved', preserve_current_profile
  );
end;
$$;


--
-- Name: reopen_trial_opportunity_for_broadcast(text, uuid, jsonb, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_trial_opportunity_for_broadcast(p_tenant_id text, p_opportunity_id uuid, p_slots_proposed jsonb, p_interests text, p_preferred_slots jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_opportunity public.opportunities%rowtype;
  v_appointment public.appointments%rowtype;
  v_requested_start timestamptz;
begin
  if jsonb_typeof(p_slots_proposed) <> 'array'
     or jsonb_array_length(p_slots_proposed) <> 1
     or coalesce(p_slots_proposed #>> '{0,date}', '')
       !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     or coalesce(p_slots_proposed #>> '{0,time}', '')
       !~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9]$'
     or coalesce(p_slots_proposed #>> '{0,day}', '') !~ '^[0-6]$' then
    return jsonb_build_object('ok', false, 'error', 'invalid_slots');
  end if;
  if p_preferred_slots is not null
     and jsonb_typeof(p_preferred_slots) <> 'array' then
    return jsonb_build_object(
      'ok', false, 'error', 'invalid_preferred_slots'
    );
  end if;
  if not private.tenant_is_operational(p_tenant_id) then
    return jsonb_build_object(
      'ok', false, 'error', 'tenant_not_operational'
    );
  end if;

  begin
    v_requested_start := (
      (p_slots_proposed #>> '{0,date}') || ' ' ||
      (p_slots_proposed #>> '{0,time}')
    )::timestamp at time zone 'America/Sao_Paulo';
  exception when others then
    return jsonb_build_object('ok', false, 'error', 'invalid_slots');
  end;
  if to_char(
       v_requested_start at time zone 'America/Sao_Paulo',
       'YYYY-MM-DD HH24:MI'
     ) <> (
       (p_slots_proposed #>> '{0,date}') || ' ' ||
       (p_slots_proposed #>> '{0,time}')
     )
     or v_requested_start <= now() + interval '5 minutes'
     or v_requested_start > now() + interval '366 days'
     or (p_slots_proposed #>> '{0,day}')::integer <>
       extract(
         dow from (v_requested_start at time zone 'America/Sao_Paulo')
       )::integer then
    return jsonb_build_object('ok', false, 'error', 'invalid_slots');
  end if;

  select opportunity.*
    into v_opportunity
    from public.opportunities as opportunity
   where opportunity.id = p_opportunity_id
     and opportunity.tenant_id = p_tenant_id
   for update;

  if not found then
    return jsonb_build_object(
      'ok', false, 'error', 'opportunity_not_found'
    );
  end if;
  if v_opportunity.status = 'OPEN'
     and coalesce(v_opportunity.kind, 'TRIAL') = 'TRIAL'
     and v_opportunity.winner_teacher_id is null
     and v_opportunity.professor_id is null
     and v_opportunity.trial_appointment_id is null
     and coalesce(v_opportunity.conversion_status, 'OPEN') = 'OPEN'
     and v_opportunity.slots_proposed = p_slots_proposed then
    update private.vendor_trial_teacher_requests
       set status = 'CANCELED',
           updated_at = now()
     where tenant_id = p_tenant_id
       and opportunity_id = p_opportunity_id
       and status in ('AWAITING_STUDENT', 'AWAITING_TEACHER');

    return jsonb_build_object(
      'ok', true,
      'idempotent', true,
      'opportunity_id', v_opportunity.id,
      'student_name', v_opportunity.student_name,
      'student_phone', v_opportunity.student_phone,
      'kind', coalesce(v_opportunity.kind, 'TRIAL'),
      'claim_generation', v_opportunity.claim_generation
    );
  end if;
  if v_opportunity.status <> 'CLAIMED'
     or coalesce(v_opportunity.kind, 'TRIAL') <> 'TRIAL'
     or v_opportunity.trial_status not in (
       'NO_SHOW_STUDENT', 'NO_SHOW_TEACHER'
     )
     or v_opportunity.trial_appointment_id is null
     or coalesce(v_opportunity.conversion_status, 'OPEN') <> 'OPEN' then
    return jsonb_build_object(
      'ok', false, 'error', 'opportunity_not_reopenable'
    );
  end if;

  select appointment.*
    into v_appointment
    from public.appointments as appointment
   where appointment.id = v_opportunity.trial_appointment_id
     and appointment.tenant_id = p_tenant_id
   for update;

  if not found then
    return jsonb_build_object(
      'ok', false, 'error', 'appointment_not_found'
    );
  end if;
  if lower(coalesce(v_appointment.status, '')) not in (
       'scheduled', 'no_show', 'cancelled', 'canceled'
     )
     or lower(coalesce(v_appointment.type, '')) <> 'experimental'
     or coalesce(v_appointment.teacher_id, v_appointment.professor_id)
       is distinct from coalesce(
         v_opportunity.winner_teacher_id,
         v_opportunity.professor_id
       )
     or exists (
       select 1
         from public.class_logs as class_log
        where class_log.appointment_id = v_appointment.id::text
     ) then
    return jsonb_build_object(
      'ok', false, 'error', 'appointment_finalized'
    );
  end if;

  update private.vendor_trial_teacher_requests
     set status = 'CANCELED',
         updated_at = now()
   where tenant_id = p_tenant_id
     and opportunity_id = p_opportunity_id
     and status in ('AWAITING_STUDENT', 'AWAITING_TEACHER');

  update public.appointments
     set status = 'cancelled'
   where id = v_appointment.id
     and lower(coalesce(status, '')) = 'scheduled';

  update public.trial_reschedule_requests
     set status = 'SUPERSEDED', responded_at = now()
   where appointment_id = v_appointment.id
     and status = 'PENDING';

  update public.opportunities
     set slots_proposed = p_slots_proposed,
         status = 'OPEN',
         winner_teacher_id = null,
         professor_id = null,
         accepted_slot = null,
         trial_appointment_id = null,
         trial_status = null,
         conversion_status = 'OPEN',
         opened_at = now(),
         claim_generation = v_opportunity.claim_generation + 1,
         interests = nullif(left(p_interests, 2000), ''),
         preferred_slots = p_preferred_slots
   where id = v_opportunity.id;

  return jsonb_build_object(
    'ok', true,
    'opportunity_id', v_opportunity.id,
    'student_name', v_opportunity.student_name,
    'student_phone', v_opportunity.student_phone,
    'kind', coalesce(v_opportunity.kind, 'TRIAL'),
    'claim_generation', v_opportunity.claim_generation + 1,
    'previous_appointment_id', v_appointment.id,
    'previous_appointment_status', v_appointment.status
  );
end;
$_$;


--
-- Name: reorder_learning_units(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_learning_units(p_path_id uuid, p_unit_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_existing_count integer;
  v_requested_count integer;
  v_unique_count integer;
  v_null_count integer;
  v_matched_count integer;
  v_min_order integer;
  v_max_order integer;
  v_temp_start bigint;
begin
  if p_path_id is null or p_unit_ids is null then
    raise exception using
      errcode = '22023',
      message = 'learning_unit_order_invalid';
  end if;

  perform private.lock_mutable_learning_path(p_path_id);

  select
    pg_catalog.count(*)::integer,
    pg_catalog.min(unit.order_index),
    pg_catalog.max(unit.order_index)
    into v_existing_count, v_min_order, v_max_order
    from public.learning_units as unit
   where unit.path_id = p_path_id;

  select
    pg_catalog.count(*)::integer,
    pg_catalog.count(distinct requested.id)::integer,
    pg_catalog.count(*) filter (where requested.id is null)::integer,
    pg_catalog.count(unit.id)::integer
    into
      v_requested_count,
      v_unique_count,
      v_null_count,
      v_matched_count
    from pg_catalog.unnest(p_unit_ids) as requested(id)
    left join public.learning_units as unit
      on unit.id = requested.id
     and unit.path_id = p_path_id;

  if v_requested_count <> v_existing_count
     or v_unique_count <> v_requested_count
     or v_null_count <> 0
     or v_matched_count <> v_requested_count then
    raise exception using
      errcode = '22023',
      message = 'learning_unit_order_invalid';
  end if;

  if v_existing_count > 0 then
    if greatest(v_max_order::bigint, v_existing_count::bigint)
         + v_existing_count::bigint <= 2147483647::bigint then
      v_temp_start := greatest(
        v_max_order::bigint,
        v_existing_count::bigint
      ) + 1;
    elsif least(v_min_order::bigint, 1::bigint)
            - v_existing_count::bigint >= -2147483648::bigint then
      v_temp_start := least(v_min_order::bigint, 1::bigint)
        - v_existing_count::bigint;
    else
      raise exception using
        errcode = '22003',
        message = 'learning_unit_order_range_exhausted';
    end if;

    with requested as (
      select item.id, item.ordinality
        from pg_catalog.unnest(p_unit_ids)
          with ordinality as item(id, ordinality)
    )
    update public.learning_units as unit
       set order_index = (
         v_temp_start + requested.ordinality::bigint - 1
       )::integer
      from requested
     where unit.id = requested.id
       and unit.path_id = p_path_id;

    with requested as (
      select item.id, item.ordinality
        from pg_catalog.unnest(p_unit_ids)
          with ordinality as item(id, ordinality)
    )
    update public.learning_units as unit
       set order_index = requested.ordinality::integer
      from requested
     where unit.id = requested.id
       and unit.path_id = p_path_id;
  end if;

  return pg_catalog.jsonb_build_object(
    'pathId', p_path_id,
    'unitIds', pg_catalog.to_jsonb(p_unit_ids),
    'reordered', true
  );
end;
$$;


--
-- Name: reorder_unit_activities(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_unit_activities(p_unit_id uuid, p_activity_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_path_id uuid;
  v_existing_count integer;
  v_requested_count integer;
  v_unique_count integer;
  v_null_count integer;
  v_matched_count integer;
  v_min_order integer;
  v_max_order integer;
  v_temp_start bigint;
begin
  if p_unit_id is null or p_activity_ids is null then
    raise exception using
      errcode = '22023',
      message = 'unit_activity_order_invalid';
  end if;

  select unit.path_id
    into v_path_id
    from public.learning_units as unit
   where unit.id = p_unit_id;

  perform private.lock_mutable_learning_path(v_path_id);

  select
    pg_catalog.count(*)::integer,
    pg_catalog.min(activity.order_index),
    pg_catalog.max(activity.order_index)
    into v_existing_count, v_min_order, v_max_order
    from public.unit_activities as activity
   where activity.unit_id = p_unit_id;

  select
    pg_catalog.count(*)::integer,
    pg_catalog.count(distinct requested.id)::integer,
    pg_catalog.count(*) filter (where requested.id is null)::integer,
    pg_catalog.count(activity.id)::integer
    into
      v_requested_count,
      v_unique_count,
      v_null_count,
      v_matched_count
    from pg_catalog.unnest(p_activity_ids) as requested(id)
    left join public.unit_activities as activity
      on activity.id = requested.id
     and activity.unit_id = p_unit_id;

  if v_requested_count <> v_existing_count
     or v_unique_count <> v_requested_count
     or v_null_count <> 0
     or v_matched_count <> v_requested_count then
    raise exception using
      errcode = '22023',
      message = 'unit_activity_order_invalid';
  end if;

  if v_existing_count > 0 then
    if greatest(v_max_order::bigint, v_existing_count::bigint)
         + v_existing_count::bigint <= 2147483647::bigint then
      v_temp_start := greatest(
        v_max_order::bigint,
        v_existing_count::bigint
      ) + 1;
    elsif least(v_min_order::bigint, 1::bigint)
            - v_existing_count::bigint >= -2147483648::bigint then
      v_temp_start := least(v_min_order::bigint, 1::bigint)
        - v_existing_count::bigint;
    else
      raise exception using
        errcode = '22003',
        message = 'unit_activity_order_range_exhausted';
    end if;

    with requested as (
      select item.id, item.ordinality
        from pg_catalog.unnest(p_activity_ids)
          with ordinality as item(id, ordinality)
    )
    update public.unit_activities as activity
       set order_index = (
         v_temp_start + requested.ordinality::bigint - 1
       )::integer
      from requested
     where activity.id = requested.id
       and activity.unit_id = p_unit_id;

    with requested as (
      select item.id, item.ordinality
        from pg_catalog.unnest(p_activity_ids)
          with ordinality as item(id, ordinality)
    )
    update public.unit_activities as activity
       set order_index = requested.ordinality::integer
      from requested
     where activity.id = requested.id
       and activity.unit_id = p_unit_id;
  end if;

  return pg_catalog.jsonb_build_object(
    'unitId', p_unit_id,
    'pathId', v_path_id,
    'activityIds', pg_catalog.to_jsonb(p_activity_ids),
    'reordered', true
  );
end;
$$;


--
-- Name: repair_authoritative_deleted_legacy_payment(uuid, uuid, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_authoritative_deleted_legacy_payment(p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_authoritative_payment jsonb, p_authoritative_subscription jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id text := nullif(pg_catalog.btrim(coalesce(p_expected_tenant_id, '')), '');
  v_reason text := nullif(pg_catalog.btrim(coalesce(p_reason, '')), '');
  v_payment public.student_payments%rowtype;
  v_profile public.profiles%rowtype;
  v_provider_payment_id text;
  v_provider_customer_id text;
  v_provider_subscription_id text;
  v_provider_status text;
  v_provider_value numeric;
  v_provider_refunded_value numeric;
  v_provider_due_date date;
  v_parent_id text;
  v_parent_customer_id text;
  v_parent_status text;
  v_payment_count integer;
  v_financial_status jsonb;
  v_action text := 'CANCELLED';
begin
  if p_expected_local_payment_id is null
     or v_tenant_id is null
     or p_authoritative_payment is null
     or pg_catalog.jsonb_typeof(p_authoritative_payment) <> 'object'
     or v_reason is null
     or pg_catalog.length(v_reason) not between 12 and 500
  then
    raise exception using
      errcode = '22023',
      message = 'authoritative_deleted_payment_repair_arguments_invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'authoritative-deleted-payment:' || p_expected_local_payment_id::text,
      0
    )
  );
  if p_expected_student_id is not null then
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'student-billing-lifecycle:' || v_tenant_id || ':' ||
          p_expected_student_id::text,
        0
      )
    );
  end if;

  v_provider_payment_id := nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'id'),
    ''
  );
  v_provider_customer_id := nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'customer'),
    ''
  );
  v_provider_subscription_id := nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'subscription'),
    ''
  );
  v_provider_status := upper(nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'status'),
    ''
  ));
  begin
    v_provider_value := (p_authoritative_payment ->> 'value')::numeric;
    v_provider_refunded_value := coalesce(
      nullif(pg_catalog.btrim(p_authoritative_payment ->> 'refundedValue'), ''),
      '0'
    )::numeric;
    v_provider_due_date := (p_authoritative_payment ->> 'dueDate')::date;
  exception
    when invalid_text_representation or numeric_value_out_of_range
      or datetime_field_overflow then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'authoritative_deleted_payment_snapshot_invalid'
      );
  end;

  if v_provider_payment_id is null
     or v_provider_customer_id is null
     or v_provider_subscription_id is null
     or v_provider_status not in ('PENDING', 'OVERDUE')
     or lower(coalesce(p_authoritative_payment ->> 'deleted', 'false')) <> 'true'
     or v_provider_value is null
     or v_provider_value::text in ('NaN', 'Infinity', '-Infinity')
     or v_provider_value <= 0
     or v_provider_refunded_value::text in ('NaN', 'Infinity', '-Infinity')
     or v_provider_refunded_value <> 0
     or v_provider_due_date is null
     or nullif(pg_catalog.btrim(p_authoritative_payment ->> 'paymentDate'), '') is not null
     or nullif(pg_catalog.btrim(p_authoritative_payment ->> 'creditDate'), '') is not null
     or nullif(pg_catalog.btrim(p_authoritative_payment ->> 'confirmedDate'), '') is not null
     or nullif(pg_catalog.btrim(p_authoritative_payment ->> 'clientPaymentDate'), '') is not null
     or (
       p_authoritative_payment ? 'refunds'
       and coalesce(p_authoritative_payment -> 'refunds', 'null'::jsonb)
             not in ('null'::jsonb, '[]'::jsonb)
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'authoritative_deleted_payment_not_repairable'
    );
  end if;

  if p_authoritative_subscription is null
     or pg_catalog.jsonb_typeof(p_authoritative_subscription) <> 'object'
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'authoritative_deleted_parent_snapshot_missing'
    );
  end if;
  v_parent_id := nullif(
    pg_catalog.btrim(p_authoritative_subscription ->> 'id'),
    ''
  );
  v_parent_customer_id := nullif(
    pg_catalog.btrim(p_authoritative_subscription ->> 'customer'),
    ''
  );
  v_parent_status := upper(nullif(
    pg_catalog.btrim(p_authoritative_subscription ->> 'status'),
    ''
  ));
  if v_parent_id is distinct from v_provider_subscription_id
     or v_parent_customer_id is distinct from v_provider_customer_id
     or v_parent_status is null
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'authoritative_deleted_parent_identity_mismatch'
    );
  end if;

  select pg_catalog.count(*)::integer
    into v_payment_count
    from public.student_payments as candidate
   where nullif(pg_catalog.btrim(coalesce(candidate.asaas_payment_id, '')), '') =
           v_provider_payment_id
      or nullif(pg_catalog.btrim(coalesce(candidate.asaas_id, '')), '') =
           v_provider_payment_id;
  if v_payment_count <> 1 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'local_provider_payment_not_unique'
    );
  end if;

  select payment.*
    into v_payment
    from public.student_payments as payment
   where payment.id = p_expected_local_payment_id
     and payment.tenant_id = v_tenant_id
     and (
       nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') =
         v_provider_payment_id
       or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') =
         v_provider_payment_id
     )
   for update;

  if not found
     or v_payment.student_id is distinct from p_expected_student_id
     or pg_catalog.round(coalesce(v_payment.value, 0), 2) is distinct from
          pg_catalog.round(v_provider_value, 2)
     or (
       v_payment.amount_cents is not null
       and v_payment.amount_cents is distinct from
             pg_catalog.round(v_provider_value * 100)::integer
     )
     or v_payment.due_date is distinct from v_provider_due_date
     or (
       upper(pg_catalog.btrim(coalesce(v_payment.status, ''))) not in (
         v_provider_status, 'CANCELLED'
       )
     )
     or (
       upper(pg_catalog.btrim(coalesce(v_payment.provider_status, ''))) not in (
         '', v_provider_status, 'DELETED'
       )
     )
     or v_payment.payment_date is not null
     or v_payment.paid_at is not null
     or v_payment.credited_at is not null
     or coalesce(v_payment.refunded_amount, 0) <> 0
     or coalesce(v_payment.ledger_entry_created, false)
     or exists (
       select 1
         from public.financial_transactions as transaction
        where transaction.student_payment_id = p_expected_local_payment_id
           or transaction.refund_student_payment_id = p_expected_local_payment_id
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'local_deleted_payment_snapshot_mismatch'
    );
  end if;

  if upper(pg_catalog.btrim(coalesce(v_payment.status, ''))) = 'CANCELLED'
     and upper(pg_catalog.btrim(coalesce(v_payment.provider_status, ''))) =
           'DELETED'
  then
    v_action := 'ALREADY_CANCELLED';
  end if;

  if p_expected_student_id is not null then
    select profile.*
      into v_profile
      from public.profiles as profile
     where profile.id = p_expected_student_id
       and profile.tenant_id = v_tenant_id
       and profile.role = 'STUDENT'
       and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) in (
         'active', 'suspended', 'offboarded'
       )
       and coalesce(profile.is_test_account, false) is false
       and nullif(
             pg_catalog.btrim(coalesce(profile.asaas_customer_id, '')),
             ''
           ) = v_provider_customer_id
     for update;
    if not found
       or exists (
         select 1
           from public.profiles as other_profile
          where other_profile.id <> p_expected_student_id
            and nullif(
                  pg_catalog.btrim(coalesce(other_profile.asaas_customer_id, '')),
                  ''
                ) = v_provider_customer_id
       )
    then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'deleted_payment_student_binding_not_corroborated'
      );
    end if;

  end if;

  update public.student_payments as payment
     set status = 'CANCELLED',
         provider_status = 'DELETED',
         exclusion_reason = coalesce(
           nullif(pg_catalog.btrim(coalesce(payment.exclusion_reason, '')), ''),
           'provider_deleted_legacy_reconciled'
         ),
         updated_at = pg_catalog.now()
   where payment.id = p_expected_local_payment_id
     and upper(pg_catalog.btrim(coalesce(payment.status, ''))) in (
           v_provider_status, 'CANCELLED'
         )
     and payment.payment_date is null
     and payment.paid_at is null
     and payment.credited_at is null;
  if not found then
    raise exception using
      errcode = '40001',
      message = 'authoritative_deleted_payment_changed_concurrently';
  end if;

  if p_expected_student_id is not null then
    select public.recompute_student_financial_status(
      v_tenant_id,
      p_expected_student_id
    ) into v_financial_status;
    if coalesce((v_financial_status ->> 'ok')::boolean, false) is false then
      raise exception using
        errcode = '55000',
        message = 'student_financial_status_recompute_failed';
    end if;
  end if;

  update public.asaas_reconciliation_issues as issue
     set resolved_at = coalesce(issue.resolved_at, pg_catalog.now()),
         resolution_note = coalesce(
           issue.resolution_note,
           'Resolved by fresh Asaas deleted=true snapshot with no cash: ' ||
             v_reason
         )
   where issue.provider_entity_id = v_provider_payment_id
     and issue.local_entity_id = p_expected_local_payment_id::text
     and issue.resolved_at is null
     and issue.kind in (
       'PROVIDER_PAYMENT_DELETED_LOCAL_OPEN',
       'PAYMENT_STATUS_MISMATCH'
     );

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', v_action,
    'payment_id', p_expected_local_payment_id,
    'student_id', p_expected_student_id,
    'provider_payment_id', v_provider_payment_id,
    'profile_subscription_adopted', false,
    'financial_status', v_financial_status ->> 'status_financial'
  );
end;
$$;


--
-- Name: repair_authoritative_legacy_payment_credit(uuid, text, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_authoritative_legacy_payment_credit(p_expected_local_payment_id uuid, p_expected_tenant_id text, p_authoritative_payment jsonb, p_authoritative_statement jsonb, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id text := nullif(pg_catalog.btrim(coalesce(p_expected_tenant_id, '')), '');
  v_reason text := nullif(pg_catalog.btrim(coalesce(p_reason, '')), '');
  v_payment public.student_payments%rowtype;
  v_provider_payment_id text;
  v_provider_customer_id text;
  v_provider_status text;
  v_provider_value numeric;
  v_provider_due_date date;
  v_provider_payment_date date;
  v_provider_credit_date date;
  v_statement_id text;
  v_statement_type text;
  v_statement_payment_id text;
  v_statement_value numeric;
  v_statement_date date;
  v_payment_count integer;
  v_gross_count integer;
  v_gross_amount numeric;
  v_refund_count integer;
  v_action text := 'CREDIT_DATE_REPAIRED';
begin
  if p_expected_local_payment_id is null
     or v_tenant_id is null
     or p_authoritative_payment is null
     or pg_catalog.jsonb_typeof(p_authoritative_payment) <> 'object'
     or p_authoritative_statement is null
     or pg_catalog.jsonb_typeof(p_authoritative_statement) <> 'object'
     or v_reason is null
     or pg_catalog.length(v_reason) not between 12 and 500
  then
    raise exception using
      errcode = '22023',
      message = 'authoritative_credit_repair_arguments_invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'authoritative-legacy-credit:' || p_expected_local_payment_id::text,
      0
    )
  );

  v_provider_payment_id := nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'id'),
    ''
  );
  v_provider_customer_id := nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'customer'),
    ''
  );
  v_provider_status := upper(nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'status'),
    ''
  ));
  v_statement_id := nullif(
    pg_catalog.btrim(p_authoritative_statement ->> 'id'),
    ''
  );
  v_statement_type := upper(nullif(
    pg_catalog.btrim(p_authoritative_statement ->> 'type'),
    ''
  ));
  v_statement_payment_id := coalesce(
    nullif(pg_catalog.btrim(p_authoritative_statement ->> 'paymentId'), ''),
    nullif(pg_catalog.btrim(p_authoritative_statement #>> '{payment,id}'), ''),
    case
      when pg_catalog.jsonb_typeof(p_authoritative_statement -> 'payment') =
             'string'
        then nullif(
          pg_catalog.btrim(p_authoritative_statement ->> 'payment'),
          ''
        )
      else null
    end
  );

  begin
    v_provider_value := (p_authoritative_payment ->> 'value')::numeric;
    v_provider_due_date := (p_authoritative_payment ->> 'dueDate')::date;
    v_provider_payment_date := (p_authoritative_payment ->> 'paymentDate')::date;
    v_provider_credit_date := (p_authoritative_payment ->> 'creditDate')::date;
    v_statement_value := (p_authoritative_statement ->> 'value')::numeric;
    v_statement_date := (p_authoritative_statement ->> 'date')::date;
  exception
    when invalid_text_representation or numeric_value_out_of_range
      or datetime_field_overflow then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'authoritative_credit_snapshot_invalid'
      );
  end;

  if v_provider_payment_id is null
     or v_provider_customer_id is null
     or v_provider_status <> 'RECEIVED'
     or lower(coalesce(p_authoritative_payment ->> 'deleted', 'false')) = 'true'
     or v_provider_value is null
     or v_provider_value::text in ('NaN', 'Infinity', '-Infinity')
     or v_provider_value <= 0
     or v_provider_due_date is null
     or v_provider_payment_date is null
     or v_provider_credit_date is null
     or v_statement_id is null
     or v_statement_type <> 'PAYMENT_RECEIVED'
     or v_statement_payment_id is distinct from v_provider_payment_id
     or v_statement_date is distinct from v_provider_credit_date
     or pg_catalog.round(coalesce(v_statement_value, 0), 2) is distinct from
          pg_catalog.round(v_provider_value, 2)
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'authoritative_credit_evidence_mismatch'
    );
  end if;

  select pg_catalog.count(*)::integer
    into v_payment_count
    from public.student_payments as candidate
   where nullif(pg_catalog.btrim(coalesce(candidate.asaas_payment_id, '')), '') =
           v_provider_payment_id
      or nullif(pg_catalog.btrim(coalesce(candidate.asaas_id, '')), '') =
           v_provider_payment_id;

  if v_payment_count <> 1 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'local_provider_payment_not_unique'
    );
  end if;

  select payment.*
    into v_payment
    from public.student_payments as payment
   where payment.id = p_expected_local_payment_id
     and payment.tenant_id = v_tenant_id
     and (
       nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') =
         v_provider_payment_id
       or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') =
         v_provider_payment_id
     )
   for update;

  if not found
     or upper(pg_catalog.btrim(coalesce(v_payment.status, ''))) <> 'RECEIVED'
     or (
       v_payment.provider_status is not null
       and upper(pg_catalog.btrim(v_payment.provider_status)) <> 'RECEIVED'
     )
     or (
       v_payment.provider_customer_id is not null
       and pg_catalog.btrim(v_payment.provider_customer_id) is distinct from
             v_provider_customer_id
     )
     or pg_catalog.round(coalesce(v_payment.value, 0), 2) is distinct from
          pg_catalog.round(v_provider_value, 2)
     or (
       v_payment.amount_cents is not null
       and v_payment.amount_cents is distinct from
             pg_catalog.round(v_provider_value * 100)::integer
     )
     or v_payment.due_date is distinct from v_provider_due_date
     or v_payment.payment_date is distinct from v_provider_payment_date
     or coalesce(v_payment.refunded_amount, 0) <> 0
     or (
       v_payment.credited_at is not null
       and v_payment.credited_at::date is distinct from v_provider_credit_date
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'local_credit_snapshot_mismatch'
    );
  end if;

  select pg_catalog.count(*)::integer, pg_catalog.max(transaction.amount)
    into v_gross_count, v_gross_amount
    from public.financial_transactions as transaction
   where transaction.student_payment_id = p_expected_local_payment_id
     and transaction.tenant_id = v_tenant_id
     and transaction.type = 'ENTRADA';
  select pg_catalog.count(*)::integer
    into v_refund_count
    from public.financial_transactions as transaction
   where transaction.refund_student_payment_id = p_expected_local_payment_id;

  if v_gross_count <> 1
     or pg_catalog.round(coalesce(v_gross_amount, 0), 2) is distinct from
          pg_catalog.round(v_provider_value, 2)
     or v_refund_count <> 0
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'local_credit_ledger_not_corroborated'
    );
  end if;

  if v_payment.credited_at is null then
    update public.student_payments as payment
       set credited_at = (
             v_provider_credit_date::timestamp + interval '12 hours'
           ) at time zone 'UTC',
           updated_at = pg_catalog.now()
     where payment.id = p_expected_local_payment_id
       and payment.credited_at is null;
    if not found then
      raise exception using
        errcode = '40001',
        message = 'authoritative_credit_changed_concurrently';
    end if;
  else
    v_action := 'ALREADY_REPAIRED';
  end if;

  update public.asaas_reconciliation_issues as issue
     set resolved_at = coalesce(issue.resolved_at, pg_catalog.now()),
         resolution_note = coalesce(
           issue.resolution_note,
           'Resolved by payment GET plus unique Asaas statement evidence: ' ||
             v_reason
         )
   where issue.provider_entity_id = v_provider_payment_id
     and issue.local_entity_id = p_expected_local_payment_id::text
     and issue.resolved_at is null
     and issue.kind in (
       'LOCAL_CREDIT_DATE_MISSING',
       'CREDIT_DATE_MISMATCH',
       'STATEMENT_CREDIT_DATE_MISMATCH',
       'LEDGER_GROSS_DATE_MISMATCH'
     );

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', v_action,
    'payment_id', p_expected_local_payment_id,
    'provider_payment_id', v_provider_payment_id,
    'credit_date', v_provider_credit_date
  );
end;
$$;


--
-- Name: repair_authoritative_unlinked_student_payment(uuid, uuid, text, jsonb, jsonb, jsonb, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_authoritative_unlinked_student_payment(p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_authoritative_payment jsonb, p_authoritative_subscription jsonb, p_authoritative_customer jsonb, p_sync_contract_due_day boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id text := nullif(pg_catalog.btrim(coalesce(p_expected_tenant_id, '')), '');
  v_reason text := nullif(pg_catalog.btrim(coalesce(p_reason, '')), '');
  v_cpf_hash text;
  v_email_hash text;
  v_phone_hash text;
  v_payment public.student_payments%rowtype;
  v_profile public.profiles%rowtype;
  v_provider_payment_id text;
  v_provider_customer_id text;
  v_customer_id text;
  v_provider_subscription_id text;
  v_provider_status text;
  v_provider_billing_type text;
  v_provider_value numeric;
  v_provider_due_date date;
  v_provider_payment_date date;
  v_provider_estimated_credit_date date;
  v_parent_id text;
  v_parent_customer_id text;
  v_parent_status text;
  v_parent_next_due_date date;
  v_identity_matches integer := 0;
  v_cpf_matches boolean := false;
  v_profile_cpf_hash text;
  v_guardian_cpf_hash text;
  v_profile_email_hash text;
  v_guardian_email_hash text;
  v_profile_phone_hash text;
  v_guardian_phone_hash text;
  v_payment_count integer;
  v_identity_candidate_count integer;
  v_gross_count integer;
  v_gross_amount numeric;
  v_refund_count integer;
  v_financial_status jsonb;
  v_already_bound boolean := false;
begin
  if p_expected_local_payment_id is null
     or p_expected_student_id is null
     or v_tenant_id is null
     or p_authoritative_payment is null
     or pg_catalog.jsonb_typeof(p_authoritative_payment) <> 'object'
     or p_authoritative_customer is null
     or pg_catalog.jsonb_typeof(p_authoritative_customer) <> 'object'
     or v_reason is null
     or pg_catalog.length(v_reason) not between 12 and 500
     or p_sync_contract_due_day is null
  then
    raise exception using
      errcode = '22023',
      message = 'authoritative_unlinked_payment_repair_arguments_invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || v_tenant_id || ':' ||
        p_expected_student_id::text,
      0
    )
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'authoritative-unlinked-payment:' || p_expected_local_payment_id::text,
      0
    )
  );

  v_provider_payment_id := nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'id'),
    ''
  );
  v_provider_customer_id := nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'customer'),
    ''
  );
  v_customer_id := nullif(
    pg_catalog.btrim(p_authoritative_customer ->> 'id'),
    ''
  );
  v_cpf_hash := case
    when nullif(
      pg_catalog.regexp_replace(
        coalesce(p_authoritative_customer ->> 'cpfCnpj', ''),
        '\D', '', 'g'
      ),
      ''
    ) is null then null
    else pg_catalog.encode(
      extensions.digest(
        pg_catalog.regexp_replace(
          p_authoritative_customer ->> 'cpfCnpj', '\D', '', 'g'
        ),
        'sha256'
      ),
      'hex'
    )
  end;
  v_email_hash := case
    when nullif(
      lower(pg_catalog.btrim(coalesce(p_authoritative_customer ->> 'email', ''))),
      ''
    ) is null then null
    else pg_catalog.encode(
      extensions.digest(
        lower(pg_catalog.btrim(p_authoritative_customer ->> 'email')),
        'sha256'
      ),
      'hex'
    )
  end;
  v_phone_hash := case
    when nullif(
      pg_catalog.regexp_replace(
        coalesce(
          nullif(pg_catalog.btrim(p_authoritative_customer ->> 'mobilePhone'), ''),
          nullif(pg_catalog.btrim(p_authoritative_customer ->> 'phone'), ''),
          ''
        ),
        '\D', '', 'g'
      ),
      ''
    ) is null then null
    else pg_catalog.encode(
      extensions.digest(
        pg_catalog.regexp_replace(
          coalesce(
            nullif(pg_catalog.btrim(p_authoritative_customer ->> 'mobilePhone'), ''),
            nullif(pg_catalog.btrim(p_authoritative_customer ->> 'phone'), '')
          ),
          '\D', '', 'g'
        ),
        'sha256'
      ),
      'hex'
    )
  end;
  v_provider_subscription_id := nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'subscription'),
    ''
  );
  v_provider_status := upper(nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'status'),
    ''
  ));
  v_provider_billing_type := upper(nullif(
    pg_catalog.btrim(p_authoritative_payment ->> 'billingType'),
    ''
  ));

  begin
    v_provider_value := (p_authoritative_payment ->> 'value')::numeric;
    v_provider_due_date := (p_authoritative_payment ->> 'dueDate')::date;
    v_provider_payment_date := nullif(
      pg_catalog.btrim(p_authoritative_payment ->> 'paymentDate'),
      ''
    )::date;
    v_provider_estimated_credit_date := nullif(
      pg_catalog.btrim(p_authoritative_payment ->> 'estimatedCreditDate'),
      ''
    )::date;
  exception
    when invalid_text_representation or numeric_value_out_of_range
      or datetime_field_overflow then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'authoritative_payment_snapshot_invalid'
      );
  end;

  if v_provider_payment_id is null
     or v_provider_customer_id is null
     or v_customer_id is distinct from v_provider_customer_id
     or v_cpf_hash is null
     or (v_email_hash is null and v_phone_hash is null)
     or v_provider_status not in (
       'PENDING', 'OVERDUE', 'CONFIRMED', 'RECEIVED'
     )
     or v_provider_value is null
     or v_provider_value::text in ('NaN', 'Infinity', '-Infinity')
     or v_provider_value <= 0
     or v_provider_due_date is null
     or coalesce((p_authoritative_payment ->> 'deleted')::boolean, false)
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'authoritative_payment_not_repairable'
    );
  end if;

  if v_provider_status = 'RECEIVED'
     and v_provider_payment_date is null
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'settled_provider_dates_incomplete'
    );
  end if;

  if v_provider_subscription_id is null then
    if p_authoritative_subscription is not null
       and pg_catalog.jsonb_typeof(p_authoritative_subscription) <> 'null'
    then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'unexpected_parent_subscription_snapshot'
      );
    end if;
  else
    if p_authoritative_subscription is null
       or pg_catalog.jsonb_typeof(p_authoritative_subscription) <> 'object'
    then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'parent_subscription_snapshot_missing'
      );
    end if;
    v_parent_id := nullif(
      pg_catalog.btrim(p_authoritative_subscription ->> 'id'),
      ''
    );
    v_parent_customer_id := nullif(
      pg_catalog.btrim(p_authoritative_subscription ->> 'customer'),
      ''
    );
    v_parent_status := upper(nullif(
      pg_catalog.btrim(p_authoritative_subscription ->> 'status'),
      ''
    ));
    begin
      v_parent_next_due_date := nullif(
        pg_catalog.btrim(p_authoritative_subscription ->> 'nextDueDate'),
        ''
      )::date;
    exception
      when invalid_text_representation or datetime_field_overflow then
        return pg_catalog.jsonb_build_object(
          'ok', false,
          'reason', 'parent_subscription_snapshot_invalid'
        );
    end;

    if v_parent_id is distinct from v_provider_subscription_id
       or v_parent_customer_id is distinct from v_provider_customer_id
       or v_parent_status <> 'ACTIVE'
       or coalesce((p_authoritative_subscription ->> 'deleted')::boolean, false)
    then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'parent_subscription_identity_mismatch'
      );
    end if;
  end if;

  select pg_catalog.count(*)::integer
    into v_payment_count
    from public.student_payments as candidate
   where nullif(pg_catalog.btrim(coalesce(candidate.asaas_payment_id, '')), '') =
           v_provider_payment_id
      or nullif(pg_catalog.btrim(coalesce(candidate.asaas_id, '')), '') =
           v_provider_payment_id;

  if v_payment_count <> 1 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'local_provider_payment_not_unique'
    );
  end if;

  select payment.*
    into v_payment
    from public.student_payments as payment
   where payment.id = p_expected_local_payment_id
     and (
       nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') =
         v_provider_payment_id
       or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') =
         v_provider_payment_id
     )
   for update;

  if not found
     or v_payment.tenant_id is distinct from v_tenant_id
     or pg_catalog.round(coalesce(v_payment.value, 0), 2) is distinct from
          pg_catalog.round(v_provider_value, 2)
     or (
       v_payment.amount_cents is not null
       and v_payment.amount_cents is distinct from
             pg_catalog.round(v_provider_value * 100)::integer
     )
     or v_payment.due_date is distinct from v_provider_due_date
     or upper(pg_catalog.btrim(coalesce(v_payment.status, ''))) is distinct from
          v_provider_status
     or (
       v_payment.provider_status is not null
       and upper(pg_catalog.btrim(v_payment.provider_status)) is distinct from
             v_provider_status
     )
     or (
       v_payment.provider_customer_id is not null
       and pg_catalog.btrim(v_payment.provider_customer_id) is distinct from
             v_provider_customer_id
     )
     or (
       v_payment.student_id is not null
       and v_payment.student_id is distinct from p_expected_student_id
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'local_payment_snapshot_mismatch'
    );
  end if;

  select pg_catalog.count(*)::integer, pg_catalog.max(transaction.amount)
    into v_gross_count, v_gross_amount
    from public.financial_transactions as transaction
   where transaction.student_payment_id = p_expected_local_payment_id
     and transaction.tenant_id = v_tenant_id
     and transaction.type = 'ENTRADA';
  select pg_catalog.count(*)::integer
    into v_refund_count
    from public.financial_transactions as transaction
   where transaction.refund_student_payment_id = p_expected_local_payment_id;

  if v_provider_status = 'RECEIVED' then
    if v_payment.payment_date is distinct from v_provider_payment_date
       or coalesce(v_payment.refunded_amount, 0) <> 0
       or v_gross_count <> 1
       or pg_catalog.round(coalesce(v_gross_amount, 0), 2) is distinct from
            pg_catalog.round(v_provider_value, 2)
       or v_refund_count <> 0
    then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'reason', 'settled_local_payment_ledger_not_corroborated'
      );
    end if;
  elsif v_payment.payment_date is not null
     or v_payment.paid_at is not null
     or v_payment.credited_at is not null
     or coalesce(v_payment.refunded_amount, 0) <> 0
     or coalesce(v_payment.ledger_entry_created, false)
     or v_gross_count <> 0
     or v_refund_count <> 0
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'open_local_payment_has_cash_evidence'
    );
  end if;

  v_already_bound := v_payment.student_id = p_expected_student_id
    and v_payment.provider_customer_id = v_provider_customer_id;

  select profile.*
    into v_profile
    from public.profiles as profile
   where profile.id = p_expected_student_id
     and profile.tenant_id = v_tenant_id
     and profile.role = 'STUDENT'
     and lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) =
           'active'
     and coalesce(profile.is_test_account, false) is false
   for update;

  if not found
     or (
       nullif(pg_catalog.btrim(coalesce(v_profile.asaas_customer_id, '')), '')
         is not null
       and pg_catalog.btrim(v_profile.asaas_customer_id) is distinct from
             v_provider_customer_id
     )
     or (
       v_provider_subscription_id is not null
       and nullif(pg_catalog.btrim(coalesce(v_profile.subscription_id, '')), '')
             is not null
       and pg_catalog.btrim(v_profile.subscription_id) is distinct from
             v_provider_subscription_id
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'student_profile_binding_mismatch'
    );
  end if;

  if (
    select pg_catalog.count(*)
      from public.tenant_memberships as membership
     where membership.user_id = p_expected_student_id
  ) <> 1
     or not exists (
       select 1
         from public.tenant_memberships as membership
        where membership.user_id = p_expected_student_id
          and membership.tenant_id = v_tenant_id
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'student_membership_not_corroborated'
    );
  end if;

  if exists (
       select 1
         from public.profiles as other_profile
        where other_profile.id <> p_expected_student_id
          and nullif(
                pg_catalog.btrim(coalesce(other_profile.asaas_customer_id, '')),
                ''
              ) = v_provider_customer_id
     )
     or (
       v_provider_subscription_id is not null
       and exists (
         select 1
           from public.profiles as other_profile
          where other_profile.id <> p_expected_student_id
            and nullif(
                  pg_catalog.btrim(coalesce(other_profile.subscription_id, '')),
                  ''
                ) = v_provider_subscription_id
       )
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'provider_identity_already_claimed'
    );
  end if;

  v_profile_cpf_hash := case
    when nullif(pg_catalog.regexp_replace(coalesce(v_profile.cpf, ''), '\D', '', 'g'), '') is null
      then null
    else pg_catalog.encode(
      extensions.digest(
        pg_catalog.regexp_replace(v_profile.cpf, '\D', '', 'g'),
        'sha256'
      ),
      'hex'
    )
  end;
  v_guardian_cpf_hash := case
    when nullif(pg_catalog.regexp_replace(coalesce(v_profile.guardian_cpf, ''), '\D', '', 'g'), '') is null
      then null
    else pg_catalog.encode(
      extensions.digest(
        pg_catalog.regexp_replace(v_profile.guardian_cpf, '\D', '', 'g'),
        'sha256'
      ),
      'hex'
    )
  end;
  v_profile_email_hash := case
    when nullif(lower(pg_catalog.btrim(coalesce(v_profile.email, ''))), '') is null
      then null
    else pg_catalog.encode(
      extensions.digest(lower(pg_catalog.btrim(v_profile.email)), 'sha256'),
      'hex'
    )
  end;
  v_guardian_email_hash := case
    when nullif(lower(pg_catalog.btrim(coalesce(v_profile.guardian_email, ''))), '') is null
      then null
    else pg_catalog.encode(
      extensions.digest(
        lower(pg_catalog.btrim(v_profile.guardian_email)),
        'sha256'
      ),
      'hex'
    )
  end;
  v_profile_phone_hash := case
    when nullif(pg_catalog.regexp_replace(coalesce(v_profile.phone, ''), '\D', '', 'g'), '') is null
      then null
    else pg_catalog.encode(
      extensions.digest(
        pg_catalog.regexp_replace(v_profile.phone, '\D', '', 'g'),
        'sha256'
      ),
      'hex'
    )
  end;
  v_guardian_phone_hash := case
    when nullif(pg_catalog.regexp_replace(coalesce(v_profile.guardian_phone, ''), '\D', '', 'g'), '') is null
      then null
    else pg_catalog.encode(
      extensions.digest(
        pg_catalog.regexp_replace(v_profile.guardian_phone, '\D', '', 'g'),
        'sha256'
      ),
      'hex'
    )
  end;

  v_cpf_matches :=
    coalesce(v_cpf_hash = v_profile_cpf_hash, false)
    or coalesce(v_cpf_hash = v_guardian_cpf_hash, false);
  if v_cpf_matches then
    v_identity_matches := v_identity_matches + 1;
  end if;
  if v_email_hash is not null and (
       coalesce(v_email_hash = v_profile_email_hash, false)
       or coalesce(v_email_hash = v_guardian_email_hash, false)
     )
  then
    v_identity_matches := v_identity_matches + 1;
  end if;
  if v_phone_hash is not null and (
       coalesce(v_phone_hash = v_profile_phone_hash, false)
       or coalesce(v_phone_hash = v_guardian_phone_hash, false)
     )
  then
    v_identity_matches := v_identity_matches + 1;
  end if;

  if v_cpf_matches is not true or v_identity_matches < 2 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'provider_customer_identity_not_corroborated',
      'matched_factors', v_identity_matches
    );
  end if;

  -- A guardian can legitimately be shared by siblings. In that case the
  -- identity tuple is ambiguous and this repair must stop instead of letting
  -- the caller choose a student id. Require CPF + contact to identify exactly
  -- one active student in the tenant.
  select pg_catalog.count(*)::integer
    into v_identity_candidate_count
    from public.profiles as candidate
    cross join lateral (
      select
        case when nullif(pg_catalog.regexp_replace(coalesce(candidate.cpf, ''), '\D', '', 'g'), '') is null
          then null else pg_catalog.encode(extensions.digest(pg_catalog.regexp_replace(candidate.cpf, '\D', '', 'g'), 'sha256'), 'hex') end as cpf_hash,
        case when nullif(pg_catalog.regexp_replace(coalesce(candidate.guardian_cpf, ''), '\D', '', 'g'), '') is null
          then null else pg_catalog.encode(extensions.digest(pg_catalog.regexp_replace(candidate.guardian_cpf, '\D', '', 'g'), 'sha256'), 'hex') end as guardian_cpf_hash,
        case when nullif(lower(pg_catalog.btrim(coalesce(candidate.email, ''))), '') is null
          then null else pg_catalog.encode(extensions.digest(lower(pg_catalog.btrim(candidate.email)), 'sha256'), 'hex') end as email_hash,
        case when nullif(lower(pg_catalog.btrim(coalesce(candidate.guardian_email, ''))), '') is null
          then null else pg_catalog.encode(extensions.digest(lower(pg_catalog.btrim(candidate.guardian_email)), 'sha256'), 'hex') end as guardian_email_hash,
        case when nullif(pg_catalog.regexp_replace(coalesce(candidate.phone, ''), '\D', '', 'g'), '') is null
          then null else pg_catalog.encode(extensions.digest(pg_catalog.regexp_replace(candidate.phone, '\D', '', 'g'), 'sha256'), 'hex') end as phone_hash,
        case when nullif(pg_catalog.regexp_replace(coalesce(candidate.guardian_phone, ''), '\D', '', 'g'), '') is null
          then null else pg_catalog.encode(extensions.digest(pg_catalog.regexp_replace(candidate.guardian_phone, '\D', '', 'g'), 'sha256'), 'hex') end as guardian_phone_hash
    ) as identity
   where candidate.tenant_id = v_tenant_id
     and candidate.role = 'STUDENT'
     and lower(pg_catalog.btrim(coalesce(candidate.lifecycle_status, ''))) = 'active'
     and coalesce(candidate.is_test_account, false) is false
     and (
       coalesce(v_cpf_hash = identity.cpf_hash, false)
       or coalesce(v_cpf_hash = identity.guardian_cpf_hash, false)
     )
     and (
       (
         v_email_hash is not null
         and (
           coalesce(v_email_hash = identity.email_hash, false)
           or coalesce(v_email_hash = identity.guardian_email_hash, false)
         )
       )
       or (
         v_phone_hash is not null
         and (
           coalesce(v_phone_hash = identity.phone_hash, false)
           or coalesce(v_phone_hash = identity.guardian_phone_hash, false)
         )
       )
     );
  if v_identity_candidate_count <> 1 then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'provider_customer_identity_not_unique',
      'candidate_count', v_identity_candidate_count
    );
  end if;

  perform pg_catalog.set_config('app.enrollment_claim', '1', true);
  update public.profiles as profile
     set asaas_customer_id = coalesce(
           nullif(pg_catalog.btrim(coalesce(profile.asaas_customer_id, '')), ''),
           v_provider_customer_id
         ),
         subscription_id = case
           when v_provider_subscription_id is null then profile.subscription_id
           else coalesce(
             nullif(pg_catalog.btrim(coalesce(profile.subscription_id, '')), ''),
             v_provider_subscription_id
           )
         end,
         asaas_subscription_status = case
           when v_provider_subscription_id is null
             then profile.asaas_subscription_status
           else v_parent_status
         end,
         asaas_subscription_synced_at = case
           when v_provider_subscription_id is null
             then profile.asaas_subscription_synced_at
           else pg_catalog.now()
         end,
         due_day = case
           when not p_sync_contract_due_day
             or v_parent_next_due_date is null then profile.due_day
           else extract(day from v_parent_next_due_date)::integer
         end
   where profile.id = p_expected_student_id
     and profile.tenant_id = v_tenant_id;
  perform pg_catalog.set_config('app.enrollment_claim', '', true);

  update public.student_payments as payment
     set student_id = p_expected_student_id,
         provider_customer_id = v_provider_customer_id,
         provider_status = v_provider_status,
         billing_type = coalesce(v_provider_billing_type, payment.billing_type),
         payment_date = case
           when v_provider_status = 'RECEIVED' then v_provider_payment_date
           else payment.payment_date
         end,
         estimated_credit_at = case
           when v_provider_estimated_credit_date is null
             then payment.estimated_credit_at
           else (
             v_provider_estimated_credit_date::timestamp + interval '12 hours'
           ) at time zone 'UTC'
         end,
         updated_at = pg_catalog.now()
   where payment.id = p_expected_local_payment_id
     and payment.tenant_id = v_tenant_id
     and (
       payment.student_id is null
       or payment.student_id = p_expected_student_id
     )
     and (
       payment.provider_customer_id is null
       or payment.provider_customer_id = v_provider_customer_id
     );

  if not found then
    raise exception using
      errcode = '40001',
      message = 'authoritative_unlinked_payment_changed_concurrently';
  end if;

  select public.recompute_student_financial_status(
    v_tenant_id,
    p_expected_student_id
  ) into v_financial_status;
  if coalesce((v_financial_status ->> 'ok')::boolean, false) is false then
    raise exception using
      errcode = '55000',
      message = 'student_financial_status_recompute_failed';
  end if;

  update public.asaas_reconciliation_issues as issue
     set resolved_at = coalesce(issue.resolved_at, pg_catalog.now()),
         resolution_note = coalesce(
           issue.resolution_note,
           'Resolved by authoritative provider/customer identity repair: ' ||
             v_reason
         )
   where issue.provider_entity_id = v_provider_payment_id
     and issue.local_entity_id = p_expected_local_payment_id::text
     and issue.resolved_at is null
     and issue.kind = 'PAYMENT_TENANT_OR_STUDENT_UNRESOLVED';

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', case when v_already_bound then 'ALREADY_BOUND' else 'BOUND' end,
    'payment_id', p_expected_local_payment_id,
    'student_id', p_expected_student_id,
    'tenant_id', v_tenant_id,
    'provider_payment_id', v_provider_payment_id,
    'identity_factors', v_identity_matches,
    'contract_due_day_synced',
      p_sync_contract_due_day and v_parent_next_due_date is not null,
    'financial_status', v_financial_status ->> 'status_financial'
  );
end;
$$;


--
-- Name: FUNCTION repair_authoritative_unlinked_student_payment(p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_authoritative_payment jsonb, p_authoritative_subscription jsonb, p_authoritative_customer jsonb, p_sync_contract_due_day boolean, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.repair_authoritative_unlinked_student_payment(p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_authoritative_payment jsonb, p_authoritative_subscription jsonb, p_authoritative_customer jsonb, p_sync_contract_due_day boolean, p_reason text) IS 'Internal identity and ledger primitive. External service access is revoked; use the integration-fenced wrapper.';


--
-- Name: repair_authoritative_unlinked_student_payment_fenced(uuid, uuid, text, uuid, bigint, text, jsonb, jsonb, jsonb, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_authoritative_unlinked_student_payment_fenced(p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_integration_id uuid, p_expected_integration_version bigint, p_expected_integration_mode text, p_authoritative_payment jsonb, p_authoritative_subscription jsonb, p_authoritative_customer jsonb, p_sync_contract_due_day boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id text := nullif(
    pg_catalog.btrim(coalesce(p_expected_tenant_id, '')),
    ''
  );
  v_expected_mode text := nullif(
    pg_catalog.btrim(coalesce(p_expected_integration_mode, '')),
    ''
  );
  v_connection private.tenant_integration_connections%rowtype;
  v_result jsonb;
begin
  if p_expected_local_payment_id is null
     or p_expected_student_id is null
     or v_tenant_id is null
     or p_expected_integration_id is null
     or p_expected_integration_version is null
     or p_expected_integration_version <= 0
     or v_expected_mode is null
  then
    raise exception using
      errcode = '22023',
      message = 'authoritative_unlinked_payment_fence_arguments_invalid';
  end if;

  -- Tenant lifecycle and integration rotation cannot cross the mutation.
  perform 1
    from public.tenants as tenant
   where tenant.id = v_tenant_id
   for share;
  if not found or not private.tenant_is_operational(v_tenant_id) then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'integration_fence_unavailable'
    );
  end if;

  select connection.*
    into v_connection
    from private.tenant_integration_connections as connection
   where connection.tenant_id = v_tenant_id
     and connection.provider = 'asaas'
   for share;

  if not found
     or v_tenant_id <> 'school-wise-wolf'
     or v_expected_mode <> 'PLATFORM_MANAGED_ROOT'
     or v_connection.id is distinct from p_expected_integration_id
     or v_connection.tenant_id is distinct from v_tenant_id
     or v_connection.provider is distinct from 'asaas'
     or v_connection.mode is distinct from v_expected_mode
     or v_connection.version is distinct from p_expected_integration_version
     or v_connection.status not in ('configured', 'healthy')
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'integration_fence_mismatch'
    );
  end if;

  v_result := public.repair_authoritative_unlinked_student_payment(
    p_expected_local_payment_id,
    p_expected_student_id,
    v_tenant_id,
    p_authoritative_payment,
    p_authoritative_subscription,
    p_authoritative_customer,
    p_sync_contract_due_day,
    p_reason
  );

  return v_result;
end;
$$;


--
-- Name: FUNCTION repair_authoritative_unlinked_student_payment_fenced(p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_integration_id uuid, p_expected_integration_version bigint, p_expected_integration_mode text, p_authoritative_payment jsonb, p_authoritative_subscription jsonb, p_authoritative_customer jsonb, p_sync_contract_due_day boolean, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.repair_authoritative_unlinked_student_payment_fenced(p_expected_local_payment_id uuid, p_expected_student_id uuid, p_expected_tenant_id text, p_expected_integration_id uuid, p_expected_integration_version bigint, p_expected_integration_mode text, p_authoritative_payment jsonb, p_authoritative_subscription jsonb, p_authoritative_customer jsonb, p_sync_contract_due_day boolean, p_reason text) IS 'Service-only authoritative legacy payment binding with an atomic tenant integration id/version fence at the database mutation boundary.';


--
-- Name: repair_saas_owner_access(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.repair_saas_owner_access(p_checkout_id uuid, p_owner_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.saas_owner_activation_attempts%rowtype;
  checkout_row public.saas_checkout_intents%rowtype;
  attempt_found boolean := false;
  tenant_ready boolean := false;
  access_ready boolean := false;
  require_marker boolean := false;
  repair_owner_user_id uuid;
begin
  if p_checkout_id is null then
    raise exception using
      errcode = '22023', message = 'invalid_saas_owner_access_repair';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-activation:' || p_checkout_id::text,
      0
    )
  );

  select checkout.* into checkout_row
    from public.saas_checkout_intents as checkout
   where checkout.id = p_checkout_id
   for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_REQUIRED',
      'reason', 'checkout_missing_for_owner_repair'
    );
  end if;

  select attempt.* into attempt_row
    from public.saas_owner_activation_attempts as attempt
   where attempt.checkout_id = p_checkout_id
   for update;
  attempt_found := found;

  if checkout_row.status not in (
    'PAID', 'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED'
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_REQUIRED',
      'reason', 'checkout_not_operational_for_owner_repair'
    );
  end if;

  if not attempt_found
     or attempt_row.status not in ('SENT', 'FAILED', 'SUPPRESSED')
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'terminal_activation_attempt_required'
    );
  end if;

  if attempt_row.status <> 'FAILED'
     and checkout_row.status <> 'PROVISIONED'
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_REQUIRED',
      'reason', 'checkout_not_operational_for_owner_repair'
    );
  end if;

  if checkout_row.tenant_id is distinct from attempt_row.tenant_id
     or lower(pg_catalog.btrim(checkout_row.owner_email))
       is distinct from attempt_row.owner_email
  then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_REQUIRED',
      'reason', 'checkout_not_operational_for_owner_repair'
    );
  end if;

  perform 1
    from public.tenants as tenant
   where tenant.id = checkout_row.tenant_id
     and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) = 'active'
   for update;
  tenant_ready := found;
  if not tenant_ready then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'NOT_REQUIRED',
      'reason', 'tenant_not_operational_for_owner_repair'
    );
  end if;

  repair_owner_user_id := p_owner_user_id;
  if repair_owner_user_id is null then
    if attempt_row.owner_user_id is null then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'action', 'REVIEW_REQUIRED',
        'reason', 'owner_identity_required_for_access_repair'
      );
    end if;
    -- A terminal attempt already bound to a live identity must be repaired
    -- with that exact identity. A null preflight may never manufacture a
    -- second auth user merely because an email lookup drifted.
    repair_owner_user_id := attempt_row.owner_user_id;
  elsif attempt_row.owner_user_id is not null
        and attempt_row.owner_user_id <> repair_owner_user_id
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'owner_identity_conflict_for_access_repair'
    );
  end if;
  require_marker := attempt_row.status in ('SENT', 'FAILED');
  access_ready := private.ensure_saas_owner_access_locked(
    p_checkout_id,
    attempt_row.tenant_id,
    attempt_row.owner_email,
    repair_owner_user_id,
    require_marker
  );
  if not access_ready then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'owner_access_repair_identity_invalid'
    );
  end if;

  if attempt_row.status = 'FAILED' then
    update public.saas_checkout_intents
       set status = 'PROVISIONED',
           provisioned_at = coalesce(provisioned_at, pg_catalog.now()),
           last_error = coalesce(last_error, 'activation_email_failed'),
           updated_at = pg_catalog.now()
     where id = p_checkout_id
       and status in (
         'PAID', 'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED'
       )
       and tenant_id = attempt_row.tenant_id
       and lower(pg_catalog.btrim(owner_email)) = attempt_row.owner_email;
    if not found then
      raise exception using
        errcode = 'P0001', message = 'saas_owner_access_repair_checkout_changed';
    end if;
  end if;

  update public.saas_owner_activation_attempts
     set owner_user_id = coalesce(owner_user_id, repair_owner_user_id),
         initial_owner_user_id = coalesce(
           initial_owner_user_id,
           repair_owner_user_id
         ),
         updated_at = pg_catalog.now()
   where checkout_id = p_checkout_id
     and status in ('SENT', 'FAILED', 'SUPPRESSED')
     and (
       owner_user_id is null
       or owner_user_id = repair_owner_user_id
     );
  if not found then
    raise exception using
      errcode = 'P0001', message = 'saas_owner_access_repair_binding_changed';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'REPAIRED',
    'status', attempt_row.status
  );
end;
$$;


--
-- Name: replace_teacher_availability(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_teacher_availability(p_teacher_id uuid, p_slots jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $_$
declare
  v_tenant_id text;
  v_inserted integer := 0;
begin
  if p_teacher_id is null then
    raise exception 'Professor é obrigatório.' using errcode = '22023';
  end if;

  if p_slots is null or jsonb_typeof(p_slots) <> 'array' then
    raise exception 'A disponibilidade deve ser uma lista.' using errcode = '22023';
  end if;

  select profile.tenant_id
    into v_tenant_id
    from public.profiles as profile
   where profile.id = p_teacher_id;

  if v_tenant_id is null then
    raise exception 'Professor não encontrado.' using errcode = 'P0002';
  end if;

  if exists (
    select 1
      from jsonb_array_elements(p_slots) as slot(value)
     where jsonb_typeof(slot.value) <> 'object'
        or not (slot.value ? 'day_of_week')
        or not (slot.value ? 'start_time')
        or coalesce(slot.value ->> 'day_of_week', '') !~ '^[0-6]$'
        or coalesce(slot.value ->> 'start_time', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        or (
          slot.value ? 'end_time'
          and nullif(slot.value ->> 'end_time', '') is not null
          and (slot.value ->> 'end_time') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
        )
  ) then
    raise exception 'Há um horário inválido na disponibilidade.' using errcode = '22023';
  end if;

  -- DELETE + INSERT vivem na mesma chamada e, portanto, na mesma transação.
  -- As políticas RLS existentes continuam sendo a fonte de autorização.
  delete from public.teacher_availability as availability
   where availability.teacher_id = p_teacher_id;

  insert into public.teacher_availability (
    teacher_id,
    tenant_id,
    day_of_week,
    start_time,
    end_time
  )
  select
    p_teacher_id,
    v_tenant_id,
    parsed.day_of_week,
    parsed.start_time,
    parsed.end_time
  from (
    select distinct
      (slot.value ->> 'day_of_week')::integer as day_of_week,
      (slot.value ->> 'start_time')::time as start_time,
      nullif(slot.value ->> 'end_time', '')::time as end_time
    from jsonb_array_elements(p_slots) as slot(value)
  ) as parsed;

  get diagnostics v_inserted = row_count;

  return jsonb_build_object(
    'ok', true,
    'teacherId', p_teacher_id,
    'publishedSlots', v_inserted
  );
end;
$_$;


--
-- Name: FUNCTION replace_teacher_availability(p_teacher_id uuid, p_slots jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.replace_teacher_availability(p_teacher_id uuid, p_slots jsonb) IS 'Substitui atomicamente a disponibilidade semanal do professor, preservando as políticas RLS de tenant e função.';


--
-- Name: request_custom_domain(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_custom_domain(p_domain text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_tenant TEXT;
    v_role TEXT;
    v_token TEXT;
BEGIN
    SELECT tenant_id, role INTO v_tenant, v_role FROM profiles WHERE id = auth.uid();
    IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RAISE EXCEPTION 'Acesso negado'; END IF;

    v_token := 'ww-verify-' || encode(gen_random_bytes(16), 'hex');

    UPDATE tenants SET
        custom_domain = LOWER(p_domain),
        custom_domain_verified = FALSE,
        custom_domain_dns_token = v_token
    WHERE id = v_tenant;

    RETURN jsonb_build_object(
        'domain', LOWER(p_domain),
        'dns_record_type', 'TXT',
        'dns_record_name', '_wisewolf-verify.' || LOWER(p_domain),
        'dns_record_value', v_token,
        'cname_target', 'app.wisewolflanguage.com.br',
        'instructions', 'Crie 2 registros DNS: (1) TXT para verificacao (2) CNAME apontando pro nosso app. Depois clique em Verificar.'
    );
END;
$$;


--
-- Name: request_prospect_otp(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_prospect_otp(p_full_name text, p_email text, p_phone text, p_tenant_id text, p_referrer_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_prospect_id UUID;
    v_otp_code TEXT;
    v_otp_hash TEXT;
BEGIN
    -- 1. Upsert Prospect
    INSERT INTO public.prospects (tenant_id, referrer_code, full_name, email, phone, status)
    VALUES (p_tenant_id, p_referrer_code, p_full_name, p_email, p_phone, 'PENDING_VERIFICATION')
    ON CONFLICT (phone, tenant_id) WHERE status NOT IN ('EXPIRED', 'CANCELLED')
    DO UPDATE SET
        full_name = EXCLUDED.full_name,
        email = EXCLUDED.email,
        referrer_code = COALESCE(EXCLUDED.referrer_code, prospects.referrer_code),
        updated_at = now()
    RETURNING id INTO v_prospect_id;

    -- 2. Generate 6-digit OTP
    v_otp_code := lpad(floor(random() * 1000000)::text, 6, '0');
    v_otp_hash := encode(digest(v_otp_code, 'sha256'), 'hex');

    -- 3. Insert OTP Token
    INSERT INTO public.otp_tokens (target_type, target_id, channel, destination, code_hash)
    VALUES ('PROSPECT_VERIFY', v_prospect_id, 'whatsapp', p_phone, v_otp_hash);

    -- 4. Insert into outbox_messages to trigger WhatsApp sender (via process-outbox edge function)
    INSERT INTO public.outbox_messages (event_type, payload)
    VALUES (
        'OTP_REQUESTED',
        jsonb_build_object(
            'phone', p_phone,
            'code', v_otp_code,
            'name', p_full_name,
            'tenant_id', p_tenant_id
        )
    );

    RETURN jsonb_build_object('success', true, 'prospect_id', v_prospect_id);
END;
$$;


--
-- Name: request_teacher_offboarding(text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_teacher_offboarding(p_reason text, p_last_day date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_role TEXT;
    v_active_students INT;
BEGIN
    SELECT role INTO v_role FROM profiles WHERE id = auth.uid();
    IF v_role NOT IN ('TEACHER','teacher') THEN RAISE EXCEPTION 'Apenas professores podem solicitar saída'; END IF;
    IF p_last_day < CURRENT_DATE THEN RAISE EXCEPTION 'Último dia não pode ser no passado'; END IF;

    SELECT COUNT(DISTINCT student_id) INTO v_active_students
    FROM bookings WHERE teacher_id = auth.uid();

    UPDATE profiles SET
        offboarding_status = 'REQUESTED',
        offboarding_requested_at = now(),
        offboarding_reason = p_reason,
        offboarding_last_day = p_last_day
    WHERE id = auth.uid();

    RETURN jsonb_build_object(
        'status','REQUESTED',
        'active_students', v_active_students,
        'last_day', p_last_day,
        'message','Solicitação enviada. Admin precisa reatribuir seus ' || v_active_students || ' alunos.'
    );
END;
$$;


--
-- Name: request_tenant_custom_domain_server(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_tenant_custom_domain_server(p_tenant_id text, p_actor_id uuid, p_domain text, p_dns_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  actor_role text := private.active_tenant_role(p_actor_id);
  normalized_domain text := lower(trim(trailing '.' FROM trim(p_domain)));
BEGIN
  IF NOT private.tenant_is_operational(p_tenant_id) THEN
    RAISE EXCEPTION 'tenant_not_operational' USING ERRCODE = '55000';
  END IF;

  IF p_actor_id IS NULL
    OR actor_role NOT IN ('SCHOOL_ADMIN', 'SUPER_ADMIN')
    OR private.active_tenant_id(p_actor_id) IS DISTINCT FROM p_tenant_id
  THEN
    RAISE EXCEPTION 'cross_tenant_access_denied' USING ERRCODE = '42501';
  END IF;
  IF length(normalized_domain) NOT BETWEEN 4 AND 253
    OR normalized_domain !~
      '^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$'
    OR normalized_domain = 'wisewolflanguage.com.br'
    OR normalized_domain LIKE '%.wisewolflanguage.com.br'
    OR p_dns_token !~ '^wwv-[0-9a-f]{32}$'
  THEN
    RAISE EXCEPTION 'invalid_custom_domain' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.tenants AS other_tenant
    WHERE lower(trim(trailing '.' FROM other_tenant.custom_domain)) = normalized_domain
      AND other_tenant.id <> p_tenant_id
  ) THEN
    RAISE EXCEPTION 'custom_domain_in_use' USING ERRCODE = '23505';
  END IF;

  UPDATE public.tenants
  SET custom_domain = normalized_domain,
      custom_domain_verified = false,
      custom_domain_dns_token = p_dns_token,
      custom_domain_verified_at = NULL
  WHERE id = p_tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'tenant_not_found' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.tenant_configuration_audit (
    tenant_id,
    actor_id,
    actor_role,
    action,
    section,
    changes
  )
  VALUES (
    p_tenant_id,
    p_actor_id,
    actor_role,
    'custom_domain_requested',
    'domains',
    jsonb_build_object('domain', normalized_domain, 'verified', false)
  );

  RETURN jsonb_build_object('ok', true, 'domain', normalized_domain);
END;
$_$;


--
-- Name: request_wolfie_live_grant_close(text, uuid, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_wolfie_live_grant_close(p_tenant_id text, p_student_id uuid, p_grant_id uuid, p_session_id uuid DEFAULT NULL::uuid, p_client_seconds integer DEFAULT NULL::integer, p_reason text DEFAULT 'CLIENT'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_grant public.wolfie_live_grants%rowtype;
  v_close_at timestamptz;
begin
  if p_tenant_id is null
     or p_student_id is null
     or p_grant_id is null
     or p_reason not in ('CLIENT', 'LEASE_EXPIRED')
     or (p_reason = 'CLIENT' and p_session_id is null)
     or (
       p_client_seconds is not null
       and p_client_seconds not between 0 and 3600
     ) then
    raise exception 'invalid_live_grant_close_request';
  end if;

  select *
    into v_grant
    from public.wolfie_live_grants
   where id = p_grant_id
     and student_id = p_student_id
     and tenant_id = p_tenant_id
     and (p_reason = 'LEASE_EXPIRED' or session_id = p_session_id)
   for update;
  if not found then
    raise exception using errcode = '42501', message = 'live_grant_not_owned';
  end if;

  if v_grant.status in ('SETTLED', 'EXPIRED', 'RELEASED') then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'alreadyClosed', true,
      'seconds', v_grant.consumed_seconds
    );
  end if;
  if v_grant.status = 'RESERVED' then
    update public.wolfie_live_grants
       set status = 'RELEASED',
           settled_at = pg_catalog.now(),
           updated_at = pg_catalog.now()
     where id = v_grant.id;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'alreadyClosed', true,
      'releasedReservation', true,
      'seconds', 0
    );
  end if;
  if v_grant.status not in ('ACTIVE', 'CLOSING')
     or v_grant.started_at is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'grant_not_active'
    );
  end if;

  if v_grant.status = 'ACTIVE' then
    if p_reason = 'LEASE_EXPIRED' then
      if v_grant.lease_expires_at > pg_catalog.now() then
        return pg_catalog.jsonb_build_object(
          'ok', false,
          'reason', 'lease_not_expired'
        );
      end if;
      v_close_at := v_grant.lease_expires_at;
    else
      v_close_at := least(pg_catalog.now(), v_grant.lease_expires_at);
    end if;

    update public.wolfie_live_grants
       set status = 'CLOSING',
           close_requested_at = v_close_at,
           close_reason = p_reason,
           client_reported_seconds = case
             when p_client_seconds is null then client_reported_seconds
             else p_client_seconds
           end,
           updated_at = pg_catalog.now()
     where id = v_grant.id
     returning * into v_grant;
  elsif p_client_seconds is not null
        and v_grant.client_reported_seconds is null then
    update public.wolfie_live_grants
       set client_reported_seconds = p_client_seconds,
           updated_at = pg_catalog.now()
     where id = v_grant.id
     returning * into v_grant;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'alreadyClosed', false,
    'grantId', v_grant.id,
    'providerCallId', v_grant.provider_call_id,
    'closeRequestedAt', v_grant.close_requested_at,
    'reason', v_grant.close_reason
  );
end;
$$;


--
-- Name: requeue_legacy_student_payment_binding_event(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.requeue_legacy_student_payment_binding_event(p_provider_event_id text, p_expected_local_payment_id uuid, p_expected_provider_payment_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_event_id text := nullif(pg_catalog.btrim(coalesce(p_provider_event_id, '')), '');
  normalized_payment_id text := nullif(pg_catalog.btrim(coalesce(p_expected_provider_payment_id, '')), '');
  inbox_row public.asaas_webhook_inbox%rowtype;
begin
  if normalized_event_id is null
     or normalized_payment_id is null
     or p_expected_local_payment_id is null
  then
    raise exception using
      errcode = '22023',
      message = 'legacy_payment_requeue_arguments_invalid';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'legacy-payment-requeue:' || normalized_event_id,
      0
    )
  );

  select inbox.*
    into inbox_row
    from public.asaas_webhook_inbox as inbox
   where inbox.provider_event_id = normalized_event_id
   for update;

  if not found
     or inbox_row.status <> 'TRIAGE'
     or inbox_row.last_error not in (
       'inactive_settlement_local_binding_incomplete',
       'legacy_recurring_authoritative_payment_not_found',
       'legacy_recurring_authoritative_subscription_not_found',
       'legacy_recurring_provider_lookup_rejected',
       'legacy_recurring_provider_identity_mismatch',
       'legacy_recurring_local_evidence_incomplete',
       'legacy_recurring_binding_database_rejected',
       'legacy_recurring_trusted_webhook_evidence_missing',
       'legacy_recurring_provider_evidence_invalid',
       'legacy_recurring_provider_evidence_mismatch',
       'legacy_recurring_local_payment_not_unique',
       'legacy_recurring_local_payment_not_repairable',
       'legacy_recurring_student_scope_not_corroborated',
       'legacy_recurring_provider_profile_not_unique',
       'legacy_recurring_membership_not_corroborated',
       'legacy_recurring_binding_changed_concurrently',
       'legacy_recurring_binding_not_applied'
     )
     or inbox_row.provider_entity_id <> normalized_payment_id
     or inbox_row.event_name not in (
       'PAYMENT_RECEIVED', 'PAYMENT_RECEIVED_IN_CASH'
     )
     or not exists (
       select 1
         from public.student_payments as payment
        where payment.id = p_expected_local_payment_id
          and (
            nullif(pg_catalog.btrim(coalesce(payment.asaas_payment_id, '')), '') = normalized_payment_id
            or nullif(pg_catalog.btrim(coalesce(payment.asaas_id, '')), '') = normalized_payment_id
          )
          and payment.provider_customer_id is null
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'triage_event_not_requeueable'
    );
  end if;

  update public.asaas_webhook_inbox
     set status = 'RETRY',
         lease_owner = null,
         lease_expires_at = null,
         next_attempt_at = pg_catalog.now(),
         processed_at = null,
         last_error = 'authorized_legacy_binding_repair',
         updated_at = pg_catalog.now()
   where provider_event_id = normalized_event_id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'REQUEUED',
    'provider_event_id', normalized_event_id
  );
end;
$$;


--
-- Name: reset_meeting_link_verification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_meeting_link_verification() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF NEW.meeting_link IS DISTINCT FROM OLD.meeting_link THEN
    NEW.meeting_link_verified_at := NULL;
    NEW.meeting_link_verified_by := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: resolve_attendance_conflict(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_attendance_conflict(p_confirmation_id uuid, p_pay boolean, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_response text;
  v_verdict text;
begin
  if p_pay is null then
    return jsonb_build_object('ok', false, 'error', 'p_pay_obrigatorio');
  end if;

  select canonical.student_response
    into v_response
    from public.attendance_confirmations requested
    join public.attendance_confirmations canonical
      on canonical.id = coalesce(
        requested.canonical_confirmation_id,
        requested.id
      )
   where requested.id = p_confirmation_id;

  v_verdict := case
    when v_response = 'TEACHER_NO_SHOW' and p_pay then 'TEACHER_PRESENT'
    when v_response = 'TEACHER_NO_SHOW' and not p_pay then 'TEACHER_ABSENT'
    when p_pay then 'PAY'
    else 'DO_NOT_PAY'
  end;

  return public.resolve_attendance_conflict_v2(
    p_confirmation_id,
    v_verdict,
    p_note
  );
end;
$$;


--
-- Name: resolve_attendance_conflict_v2(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_attendance_conflict_v2(p_confirmation_id uuid, p_verdict text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  requested public.attendance_confirmations%rowtype;
  c public.attendance_confirmations%rowtype;
  v_uid uuid := auth.uid();
  v_role text;
  v_tenant text;
  v_jwt_role text;
  v_canonical_id uuid;
  v_verdict text := upper(trim(coalesce(p_verdict, '')));
  v_pay boolean;
  v_final text;
  v_turbo jsonb;
  r record;
begin
  v_jwt_role := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'role',
    ''
  );

  if v_jwt_role = 'service_role' then
    v_role := 'SUPER_ADMIN';
  else
    v_role := public._my_role();
    v_tenant := public._my_tenant_id();
  end if;

  if not coalesce(v_role in ('SCHOOL_ADMIN', 'SUPER_ADMIN'), false) then
    return jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  select ac.*
    into requested
    from public.attendance_confirmations ac
   where ac.id = p_confirmation_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'nao_encontrado');
  end if;

  v_canonical_id := coalesce(requested.canonical_confirmation_id, requested.id);
  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = v_canonical_id
   for update;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'nao_encontrado');
  end if;

  perform 1
    from public.attendance_confirmations ac
   where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
   order by ac.id
   for update;

  if v_role = 'SCHOOL_ADMIN' and c.tenant_id is distinct from v_tenant then
    return jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  if v_verdict not in ('TEACHER_PRESENT', 'TEACHER_ABSENT', 'PAY', 'DO_NOT_PAY') then
    return jsonb_build_object('ok', false, 'error', 'veredito_invalido');
  end if;

  if c.status in ('RESOLVED_PAID', 'RESOLVED_UNPAID') then
    return jsonb_build_object('ok', true, 'already', true, 'status', c.status);
  end if;

  -- The director cannot make a final decision while the UI still promises the
  -- student that the answer is correctable.
  if c.response_editable_until is not null
     and c.response_editable_until > now() then
    return jsonb_build_object(
      'ok', false,
      'error', 'aguardando_janela_correcao',
      'editable_until', c.response_editable_until
    );
  end if;

  if c.teacher_id is null
     or c.tenant_id is null
     or not exists (
       select 1
         from public.profiles p
        where p.id = c.teacher_id
          and p.role = 'TEACHER'
          and p.tenant_id = c.tenant_id
     ) then
    return jsonb_build_object('ok', false, 'error', 'dados_inconsistentes');
  end if;

  -- A pending/light audit is not a financial dispute and therefore cannot be
  -- finalized by an administrator. Both resolvable states belong exclusively
  -- to the explicit teacher-no-show flow.
  if not coalesce(c.status in ('AWAITING_TEACHER', 'CONFLICT'), false) then
    return jsonb_build_object(
      'ok', false,
      'error', 'estado_invalido',
      'status', c.status
    );
  end if;

  if c.student_response is distinct from 'TEACHER_NO_SHOW' then
    return jsonb_build_object(
      'ok', false,
      'error', 'resposta_incompativel',
      'student_response', c.student_response
    );
  end if;

  -- This is the last gate before the authoritative multi-row UPDATE. It proves
  -- every source, participant, time, class log and grouping key without
  -- trusting browser-supplied or historically corrupted links.
  if not private.attendance_session_is_consistent(v_canonical_id) then
    return jsonb_build_object('ok', false, 'error', 'dados_inconsistentes');
  end if;

  -- PAY/DO_NOT_PAY remains an alias only after the same TEACHER_NO_SHOW guard,
  -- so an old client cannot turn an attendance mismatch into a penalty.
  if v_verdict in ('PAY', 'DO_NOT_PAY') then
    v_verdict := case when v_verdict = 'PAY'
                      then 'TEACHER_PRESENT'
                      else 'TEACHER_ABSENT' end;
  end if;

  v_pay := v_verdict in ('TEACHER_PRESENT', 'PAY');
  v_final := case when v_pay then 'RESOLVED_PAID' else 'RESOLVED_UNPAID' end;

  update public.attendance_confirmations ac
     set status = v_final,
         admin_resolution = nullif(left(coalesce(p_note, ''), 2000), ''),
         resolution_verdict = v_verdict,
         resolved_by = v_uid,
         resolved_at = now()
   where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id;

  perform private.apply_final_attendance_resolution(v_canonical_id);

  -- The scheduled alert has not left during the correction window. A final
  -- director decision makes it obsolete regardless of the verdict.
  update public.notification_queue nq
     set status = 'skipped',
         updated_at = now(),
         last_error = 'attendance_conflict_resolved_before_send'
   where nq.notification_kind = 'CONFLICT_TEACHER_ALERT'
     and nq.status = 'pending'
     and nq.source_id in (
       select ac.id
         from public.attendance_confirmations ac
        where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
     );

  for r in
    select ac.id
      from public.attendance_confirmations ac
     where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
  loop
    perform public.teacher_turbo_sync_attendance_dispute(r.id);
  end loop;

  v_turbo := public.teacher_turbo_status(c.teacher_id);

  return jsonb_build_object(
    'ok', true,
    'status', v_final,
    'verdict', v_verdict,
    'session_key', c.session_key,
    'turbo_status', v_turbo->>'status',
    'turbo_active', coalesce((v_turbo->>'active')::boolean, false),
    'turbo_action', case
      when c.student_response <> 'TEACHER_NO_SHOW' then 'NONE'
      when not v_pay then 'RESET'
      when v_turbo->>'status' = 'SUSPENDED' then 'SUSPENSION_REMAINS'
      when coalesce((v_turbo->>'active')::boolean, false) then 'RESTORED'
      else 'DISPUTE_CLEARED'
    end
  );
end;
$$;


--
-- Name: resolve_coverage_invite(text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_coverage_invite(p_token text, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_coverage public.class_coverages%ROWTYPE;
  v_booking public.bookings%ROWTYPE;
  v_apply jsonb;
  v_time text;
  v_day_number integer;
  v_day_name text;
  v_class_start timestamptz;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'service_role_required';
  END IF;
  IF coalesce(p_token, '') !~ '^[0-9a-fA-F]{32}$' OR p_accept IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'token_invalido');
  END IF;

  SELECT coverage.*
    INTO v_coverage
    FROM public.class_coverages AS coverage
   WHERE coverage.token = lower(p_token);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nao_encontrada');
  END IF;

  IF lower(v_coverage.status) = 'confirmed' THEN
    RETURN jsonb_build_object(
      'ok', true, 'already', true, 'status', 'confirmed',
      'class_date', v_coverage.class_date, 'class_time', v_coverage.class_time
    );
  END IF;
  IF lower(v_coverage.status) = 'declined' THEN
    RETURN jsonb_build_object(
      'ok', true, 'already', true, 'status', 'declined',
      'class_date', v_coverage.class_date, 'class_time', v_coverage.class_time
    );
  END IF;
  IF lower(v_coverage.status) <> 'pending' THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'indisponivel', 'status', v_coverage.status
    );
  END IF;
  IF now() >= coalesce(
    v_coverage.invite_expires_at,
    (
      v_coverage.class_date::text || ' ' ||
      left(v_coverage.class_time, 5) || ':00-03'
    )::timestamptz
  ) THEN
    UPDATE public.class_coverages
       SET status = 'cancelled'
     WHERE id = v_coverage.id AND lower(status) = 'pending'
     RETURNING * INTO v_coverage;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'expirado', 'status', 'cancelled'
      );
    END IF;
    SELECT coverage.* INTO v_coverage
      FROM public.class_coverages AS coverage
     WHERE coverage.token = lower(p_token);
    RETURN jsonb_build_object(
      'ok', lower(coalesce(v_coverage.status, '')) IN ('confirmed', 'declined'),
      'already', true, 'status', v_coverage.status,
      'class_date', v_coverage.class_date, 'class_time', v_coverage.class_time
    );
  END IF;

  IF NOT p_accept THEN
    UPDATE public.class_coverages
       SET status = 'declined', declined_at = now()
     WHERE id = v_coverage.id AND lower(status) = 'pending'
     RETURNING * INTO v_coverage;
    IF FOUND THEN
      RETURN jsonb_build_object(
        'ok', true, 'status', 'declined',
        'class_date', v_coverage.class_date,
        'class_time', v_coverage.class_time
      );
    END IF;
    SELECT coverage.* INTO v_coverage
      FROM public.class_coverages AS coverage
     WHERE coverage.token = lower(p_token);
    RETURN jsonb_build_object(
      'ok', lower(coalesce(v_coverage.status, '')) IN ('confirmed', 'declined'),
      'already', true, 'status', v_coverage.status,
      'class_date', v_coverage.class_date, 'class_time', v_coverage.class_time
    );
  END IF;

  -- O convite e apenas uma proposta. Entre o envio e o clique, vinculos,
  -- disponibilidade e agenda podem mudar; tudo e revalidado sob lock.
  v_time := left(btrim(coalesce(v_coverage.class_time, '')), 5);
  IF v_time !~ '^(0[0-9]|1[0-9]|2[0-3]):(00|30)$' THEN
    UPDATE public.class_coverages
       SET status = 'cancelled'
     WHERE id = v_coverage.id AND lower(status) = 'pending';
    RETURN jsonb_build_object(
      'ok', false, 'error', 'convite_inconsistente', 'status', 'cancelled'
    );
  END IF;
  v_class_start := (
    v_coverage.class_date::text || ' ' || v_time || ':00-03'
  )::timestamptz;
  v_day_number := extract(dow FROM v_coverage.class_date)::integer;
  v_day_name := CASE v_day_number
    WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Segunda' WHEN 2 THEN 'Terça'
    WHEN 3 THEN 'Quarta' WHEN 4 THEN 'Quinta' WHEN 5 THEN 'Sexta'
    WHEN 6 THEN 'Sábado'
  END;

  -- Mesma ordem global do trigger e da criacao: booking antes dos advisory
  -- locks. A segunda leitura abaixo faz a revalidacao completa.
  SELECT booking.*
    INTO v_booking
    FROM public.bookings AS booking
   WHERE booking.id = v_coverage.booking_id
   FOR UPDATE;
  IF NOT FOUND THEN
    UPDATE public.class_coverages
       SET status = 'cancelled'
     WHERE id = v_coverage.id AND lower(status) = 'pending';
    RETURN jsonb_build_object(
      'ok', false, 'error', 'aula_nao_esta_mais_disponivel',
      'status', 'cancelled'
    );
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'coverage:' || v_coverage.booking_id::text || ':' ||
      v_coverage.class_date::text,
      0
    )
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'coverage-teacher:' || v_coverage.cover_teacher_id::text || ':' ||
      v_coverage.class_date::text || ':' || v_time,
      0
    )
  );
  PERFORM private.lock_coverage_absence_pair(
    v_coverage.original_teacher_id,
    v_coverage.cover_teacher_id,
    v_coverage.class_date
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'schedule:teacher:' || v_coverage.cover_teacher_id::text || ':' ||
      public.fold_accents(v_day_name) || ':' || v_time,
      0
    )
  );

  -- A linha do convite vem depois dos locks compartilhados. Assim dois
  -- convites diferentes para o mesmo substituto/horario nao seguram a linha um
  -- do outro enquanto esperam o advisory, evitando um ciclo de deadlock.
  SELECT coverage.*
    INTO v_coverage
    FROM public.class_coverages AS coverage
   WHERE coverage.token = lower(p_token)
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'nao_encontrada');
  END IF;
  IF lower(v_coverage.status) = 'confirmed' THEN
    RETURN jsonb_build_object(
      'ok', true, 'already', true, 'status', 'confirmed',
      'class_date', v_coverage.class_date, 'class_time', v_coverage.class_time
    );
  END IF;
  IF lower(v_coverage.status) = 'declined' THEN
    RETURN jsonb_build_object(
      'ok', true, 'already', true, 'status', 'declined',
      'class_date', v_coverage.class_date, 'class_time', v_coverage.class_time
    );
  END IF;
  IF lower(v_coverage.status) <> 'pending' THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'indisponivel', 'status', v_coverage.status
    );
  END IF;
  IF now() >= coalesce(
    v_coverage.invite_expires_at,
    (
      v_coverage.class_date::text || ' ' ||
      left(v_coverage.class_time, 5) || ':00-03'
    )::timestamptz
  ) THEN
    UPDATE public.class_coverages
       SET status = 'cancelled'
     WHERE id = v_coverage.id AND lower(status) = 'pending';
    RETURN jsonb_build_object(
      'ok', false, 'error', 'expirado', 'status', 'cancelled'
    );
  END IF;

  SELECT booking.*
    INTO v_booking
    FROM public.bookings AS booking
   WHERE booking.id = v_coverage.booking_id
   FOR UPDATE;
  IF NOT FOUND
     OR v_booking.tenant_id IS DISTINCT FROM v_coverage.tenant_id
     OR v_booking.teacher_id IS DISTINCT FROM v_coverage.original_teacher_id
     OR v_booking.student_id IS DISTINCT FROM v_coverage.student_id
     OR upper(coalesce(v_booking.status, '')) <> 'SCHEDULED'
     OR left(coalesce(v_booking.time_slot, ''), 5) <> v_time
     OR (
       v_booking.date IS NOT NULL
       AND v_booking.date IS DISTINCT FROM v_coverage.class_date
     )
     OR (
       v_booking.date IS NULL
       AND public.fold_accents(v_booking.day_of_week) <>
           public.fold_accents(v_day_name)
     )
     OR (
       v_booking.date IS NULL
       AND v_booking.start_date IS NOT NULL
       AND v_coverage.class_date < v_booking.start_date
     ) THEN
    UPDATE public.class_coverages
       SET status = 'cancelled'
     WHERE id = v_coverage.id AND lower(status) = 'pending';
    RETURN jsonb_build_object(
      'ok', false, 'error', 'aula_nao_esta_mais_disponivel',
      'status', 'cancelled'
    );
  END IF;

  PERFORM 1
    FROM public.teacher_absences AS absence
   WHERE absence.id = v_coverage.absence_id
     AND absence.tenant_id = v_coverage.tenant_id
     AND absence.teacher_id = v_coverage.original_teacher_id
     AND lower(coalesce(absence.status, '')) = 'active'
     AND absence.starts_at::date <= v_coverage.class_date
     AND absence.ends_at::date >= v_coverage.class_date
   FOR UPDATE;
  IF NOT FOUND THEN
    UPDATE public.class_coverages
       SET status = 'cancelled'
     WHERE id = v_coverage.id AND lower(status) = 'pending';
    RETURN jsonb_build_object(
      'ok', false, 'error', 'falta_original_nao_esta_mais_ativa',
      'status', 'cancelled'
    );
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.profiles AS teacher
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = teacher.id
       AND membership.tenant_id = v_coverage.tenant_id
       AND membership.role = 'TEACHER'
       AND membership.status = 'ACTIVE'
     WHERE teacher.id = v_coverage.cover_teacher_id
       AND teacher.role = 'TEACHER'
       AND lower(coalesce(teacher.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
  ) OR NOT EXISTS (
    SELECT 1
      FROM public.profiles AS student
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = student.id
       AND membership.tenant_id = v_coverage.tenant_id
       AND membership.role = 'STUDENT'
       AND membership.status = 'ACTIVE'
     WHERE student.id = v_coverage.student_id
       AND student.role = 'STUDENT'
       AND lower(coalesce(student.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
  ) OR NOT EXISTS (
    SELECT 1
      FROM public.teacher_availability AS availability
     WHERE availability.tenant_id = v_coverage.tenant_id
       AND availability.teacher_id = v_coverage.cover_teacher_id
       AND availability.day_of_week = v_day_number
       AND (
         availability.start_time = v_time::time
         OR (
           availability.end_time IS NOT NULL
           AND availability.start_time <= v_time::time
           AND availability.end_time > v_time::time
         )
       )
  ) THEN
    UPDATE public.class_coverages
       SET status = 'cancelled'
     WHERE id = v_coverage.id AND lower(status) = 'pending';
    RETURN jsonb_build_object(
      'ok', false, 'error', 'substituto_nao_esta_mais_disponivel',
      'status', 'cancelled'
    );
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.teacher_absences AS absence
     WHERE absence.tenant_id = v_coverage.tenant_id
       AND absence.teacher_id = v_coverage.cover_teacher_id
       AND lower(coalesce(absence.status, '')) = 'active'
       AND absence.starts_at::date <= v_coverage.class_date
       AND absence.ends_at::date >= v_coverage.class_date
  ) OR EXISTS (
    SELECT 1
      FROM public.bookings AS conflict
     WHERE conflict.tenant_id = v_coverage.tenant_id
       AND conflict.teacher_id = v_coverage.cover_teacher_id
       AND upper(coalesce(conflict.status, '')) <> 'CANCELLED'
       AND left(coalesce(conflict.time_slot, ''), 5) = v_time
       AND (
         conflict.date = v_coverage.class_date
         OR (
           conflict.date IS NULL
           AND public.fold_accents(conflict.day_of_week) =
               public.fold_accents(v_day_name)
           AND (
             conflict.start_date IS NULL
             OR conflict.start_date <= v_coverage.class_date
           )
         )
       )
  ) OR EXISTS (
    SELECT 1
      FROM public.reschedules AS reschedule
     WHERE reschedule.tenant_id = v_coverage.tenant_id
       AND reschedule.teacher_id = v_coverage.cover_teacher_id
       AND public.parse_lesson_date(reschedule.date) = v_coverage.class_date
       AND left(reschedule.time::text, 5) = v_time
       AND reschedule.used_at IS NULL
  ) OR EXISTS (
    SELECT 1
      FROM public.appointments AS appointment
     WHERE appointment.tenant_id = v_coverage.tenant_id
       AND (
         appointment.teacher_id = v_coverage.cover_teacher_id
         OR appointment.professor_id = v_coverage.cover_teacher_id
       )
       AND lower(coalesce(appointment.status, '')) IN ('scheduled', 'confirmed')
       AND abs(extract(epoch FROM (appointment.start_time - v_class_start))) < 1800
  ) OR EXISTS (
    SELECT 1
      FROM public.class_coverages AS other_coverage
     WHERE other_coverage.id <> v_coverage.id
       AND other_coverage.tenant_id = v_coverage.tenant_id
       AND other_coverage.cover_teacher_id = v_coverage.cover_teacher_id
       AND other_coverage.class_date = v_coverage.class_date
       AND left(other_coverage.class_time, 5) = v_time
       AND lower(other_coverage.status) = 'confirmed'
  ) OR EXISTS (
    SELECT 1
      FROM public.class_coverages AS other_coverage
     WHERE other_coverage.id <> v_coverage.id
       AND other_coverage.tenant_id = v_coverage.tenant_id
       AND other_coverage.booking_id = v_coverage.booking_id
       AND other_coverage.class_date = v_coverage.class_date
       AND lower(other_coverage.status) = 'confirmed'
  ) THEN
    UPDATE public.class_coverages
       SET status = 'cancelled'
     WHERE id = v_coverage.id AND lower(status) = 'pending';
    RETURN jsonb_build_object(
      'ok', false, 'error', 'conflito_criado_apos_o_convite',
      'status', 'cancelled'
    );
  END IF;

  -- Se dois convites legados chegaram ao mesmo substituto/horario, o primeiro
  -- aceite valido vence e invalida os demais links ainda pendentes.
  UPDATE public.class_coverages
     SET status = 'cancelled'
   WHERE id <> v_coverage.id
     AND tenant_id = v_coverage.tenant_id
     AND (
       (
         cover_teacher_id = v_coverage.cover_teacher_id
         AND class_date = v_coverage.class_date
         AND left(class_time, 5) = v_time
       )
       OR (
         booking_id = v_coverage.booking_id
         AND class_date = v_coverage.class_date
       )
     )
     AND lower(status) = 'pending';

  UPDATE public.class_coverages
     SET status = 'confirmed', confirmed_at = now()
   WHERE id = v_coverage.id AND lower(status) = 'pending';

  SELECT public.apply_coverage_acceptance(v_coverage.id) INTO v_apply;
  IF coalesce((v_apply ->> 'ok')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'coverage_financial_application_failed';
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'status', 'confirmed', 'application', v_apply,
    'class_date', v_coverage.class_date, 'class_time', v_coverage.class_time
  );
END;
$_$;


--
-- Name: resolve_enrollment_payment_observation_binding(text, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_enrollment_payment_observation_binding(p_tenant_id text, p_student_id uuid, p_provider_payment_id text, p_external_reference text, p_outcome text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  normalized_tenant text := nullif(trim(coalesce(p_tenant_id, '')), '');
  normalized_payment_id text := nullif(
    trim(coalesce(p_provider_payment_id, '')),
    ''
  );
  normalized_reference text := nullif(
    lower(trim(coalesce(p_external_reference, ''))),
    ''
  );
  normalized_outcome text := upper(trim(coalesce(p_outcome, '')));
  profile_row public.profiles%rowtype;
  offer_row public.offers%rowtype;
  reference_parts text[];
  resolved_kind text;
  resolved_purpose text;
  candidate record;
  candidate_count integer := 0;
  candidate_offer_id uuid;
  candidate_kind text;
  candidate_reference text;
  profile_payment_id text;
  offer_payment_id text;
  fee_fallback_payment_count integer := 0;
begin
  if normalized_tenant is null
     or p_student_id is null
     or normalized_payment_id is null
     or length(normalized_payment_id) > 240
     or normalized_outcome not in ('SETTLED', 'PENDING', 'UNSETTLED')
     or length(coalesce(normalized_reference, '')) > 500
  then
    raise exception using
      errcode = '22023',
      message = 'invalid_enrollment_payment_binding_resolution';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'student-billing-lifecycle:' || normalized_tenant || ':' ||
        p_student_id::text,
      0
    )
  );

  select profile.* into profile_row
    from public.profiles as profile
   where profile.id = p_student_id
     and profile.tenant_id = normalized_tenant
     and profile.role = 'STUDENT'
   for share;
  if not found then
    return jsonb_build_object('ok', true, 'action', 'NONE');
  end if;
  profile_payment_id := nullif(trim(coalesce(
    profile_row.enrollment_payment_id,
    ''
  )), '');

  if normalized_reference = p_student_id::text then
    if profile_payment_id = normalized_payment_id then
      return jsonb_build_object(
        'ok', true,
        'action', 'BOUND',
        'offer_id', null,
        'payment_kind', 'ENROLLMENT_FEE',
        'external_reference', p_student_id::text
      );
    end if;
    return jsonb_build_object('ok', true, 'action', 'NONE');
  end if;

  if normalized_reference is not null then
    reference_parts := pg_catalog.regexp_match(
      normalized_reference,
      '^enrollment:([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}):(fee|one-time|pro-rata|subscription)$'
    );
    if reference_parts is null then
      return jsonb_build_object('ok', true, 'action', 'NONE');
    end if;
    resolved_purpose := reference_parts[2];
    resolved_kind := case resolved_purpose
      when 'fee' then 'ENROLLMENT_FEE'
      when 'one-time' then 'ONE_TIME'
      when 'pro-rata' then 'PRO_RATA'
      else 'SUBSCRIPTION_ACTIVATION'
    end;

    select offer.* into offer_row
      from public.offers as offer
     where offer.id = reference_parts[1]::uuid
       and offer.tenant_id = normalized_tenant
       and offer.kind = 'ENROLLMENT'
       and (
         offer.processing_by = p_student_id
         or offer.consumed_by = p_student_id
       )
     for share;
    if not found then
      return jsonb_build_object('ok', false, 'reason', 'offer_not_owned');
    end if;

    offer_payment_id := case resolved_kind
      when 'ENROLLMENT_FEE' then nullif(trim(coalesce(
        offer_row.metadata ->> 'enrollment_payment_id',
        ''
      )), '')
      when 'ONE_TIME' then nullif(trim(coalesce(
        offer_row.metadata ->> 'one_time_payment_id',
        ''
      )), '')
      when 'PRO_RATA' then nullif(trim(coalesce(
        offer_row.metadata ->> 'pro_rata_charge_id',
        ''
      )), '')
      else coalesce(
        nullif(trim(coalesce(
          offer_row.metadata ->> 'subscription_activation_payment_id',
          ''
        )), ''),
        nullif(trim(coalesce(
          offer_row.metadata ->> 'activation_payment_id',
          ''
        )), '')
      )
    end;

    if resolved_kind = 'ENROLLMENT_FEE' then
      if offer_payment_id is not null
         and offer_payment_id <> normalized_payment_id
      then
        return jsonb_build_object(
          'ok', false,
          'reason', 'enrollment_payment_binding_mismatch'
        );
      elsif offer_payment_id is null then
        if profile_payment_id is distinct from normalized_payment_id then
          return jsonb_build_object(
            'ok', false,
            'reason', 'enrollment_payment_binding_mismatch'
          );
        end if;
        select count(*) into fee_fallback_payment_count
          from public.student_payments as payment
         where payment.tenant_id = normalized_tenant
           and payment.student_id = p_student_id
           and (
             nullif(trim(coalesce(payment.asaas_payment_id, '')), '') =
               normalized_payment_id
             or nullif(trim(coalesce(payment.asaas_id, '')), '') =
               normalized_payment_id
           )
           and lower(trim(coalesce(
             payment.raw_payload #>> '{payment,externalReference}',
             ''
           ))) = normalized_reference
           and not exists (
             select 1
               from public.offers as competing_offer
              where competing_offer.id <> offer_row.id
                and competing_offer.tenant_id = normalized_tenant
                and competing_offer.kind = 'ENROLLMENT'
                and (
                  competing_offer.processing_by = p_student_id
                  or competing_offer.consumed_by = p_student_id
                )
                and nullif(trim(coalesce(
                  competing_offer.metadata ->> 'enrollment_payment_id',
                  ''
                )), '') = normalized_payment_id
           );
        if fee_fallback_payment_count <> 1 then
          return jsonb_build_object(
            'ok', false,
            'reason', 'enrollment_payment_binding_mismatch'
          );
        end if;
      end if;
    elsif resolved_kind in ('ONE_TIME', 'PRO_RATA') then
      if resolved_kind = 'PRO_RATA' and (
        offer_row.payload ->> 'enableProRata' is distinct from 'true'
        or coalesce(
          nullif(offer_row.payload ->> 'proRataValue', '')::numeric,
          0
        ) <= 0
        or offer_row.payload ->> 'proRataFormulaVersion'
             is distinct from 'weekly-frequency-times-4-v1'
      ) then
        return jsonb_build_object(
          'ok', false,
          'reason', 'pro_rata_scope_invalid'
        );
      end if;
      if offer_payment_id is not null
         and offer_payment_id <> normalized_payment_id
      then
        return jsonb_build_object(
          'ok', false,
          'reason', case resolved_kind
            when 'ONE_TIME' then 'one_time_payment_binding_mismatch'
            else 'pro_rata_payment_binding_mismatch'
          end
        );
      elsif offer_payment_id is null and normalized_outcome <> 'SETTLED' then
        return jsonb_build_object(
          'ok', false,
          'reason', case resolved_kind
            when 'ONE_TIME' then 'one_time_payment_binding_mismatch'
            else 'pro_rata_payment_binding_pending'
          end
        );
      end if;
    else
      -- Taxa e pro-rata sao as provas de ativacao quando aplicaveis. Depois da
      -- primeira ativacao, parcelas mensais seguintes sao financeiro normal:
      -- nunca devem reabrir a oferta nem virar divergencia de matricula.
      if greatest(coalesce(offer_row.enrollment_fee, 0), 0) > 0
         or (
              offer_row.payload ->> 'enableProRata' = 'true'
              and coalesce(
                nullif(offer_row.payload ->> 'proRataValue', '')::numeric,
                0
              ) > 0
            )
      then
        return jsonb_build_object('ok', true, 'action', 'NONE');
      elsif offer_payment_id is not null
            and offer_payment_id <> normalized_payment_id
      then
        return jsonb_build_object('ok', true, 'action', 'NONE');
      elsif offer_payment_id is null and normalized_outcome <> 'SETTLED' then
        return jsonb_build_object('ok', true, 'action', 'NONE');
      end if;
    end if;

    return jsonb_build_object(
      'ok', true,
      'action', 'BOUND',
      'offer_id', offer_row.id,
      'payment_kind', resolved_kind,
      'external_reference', 'enrollment:' || offer_row.id::text || ':' ||
        resolved_purpose
    );
  end if;

  for candidate in
    select distinct binding.offer_id, binding.payment_kind,
           binding.external_reference
      from (
        select offer.id as offer_id,
               match.payment_kind,
               'enrollment:' || offer.id::text || ':' || match.purpose
                 as external_reference
          from public.offers as offer
          cross join lateral (
            values
              (
                'ENROLLMENT_FEE'::text,
                'fee'::text,
                nullif(trim(coalesce(
                  offer.metadata ->> 'enrollment_payment_id',
                  ''
                )), '')
              ),
              (
                'ONE_TIME'::text,
                'one-time'::text,
                nullif(trim(coalesce(
                  offer.metadata ->> 'one_time_payment_id',
                  ''
                )), '')
              ),
              (
                'PRO_RATA'::text,
                'pro-rata'::text,
                nullif(trim(coalesce(
                  offer.metadata ->> 'pro_rata_charge_id',
                  ''
                )), '')
              ),
              (
                'SUBSCRIPTION_ACTIVATION'::text,
                'subscription'::text,
                nullif(trim(coalesce(
                  offer.metadata ->> 'subscription_activation_payment_id',
                  ''
                )), '')
              ),
              (
                'SUBSCRIPTION_ACTIVATION'::text,
                'subscription'::text,
                nullif(trim(coalesce(
                  offer.metadata ->> 'activation_payment_id',
                  ''
                )), '')
              )
          ) as match(payment_kind, purpose, bound_payment_id)
         where offer.tenant_id = normalized_tenant
           and offer.kind = 'ENROLLMENT'
           and (
             offer.processing_by = p_student_id
             or offer.consumed_by = p_student_id
           )
           and match.bound_payment_id = normalized_payment_id
           and (
             match.payment_kind <> 'PRO_RATA'
             or (
               offer.payload ->> 'enableProRata' = 'true'
               and coalesce(
                 nullif(offer.payload ->> 'proRataValue', '')::numeric,
                 0
               ) > 0
               and offer.payload ->> 'proRataFormulaVersion'
                 = 'weekly-frequency-times-4-v1'
             )
           )
      ) as binding
  loop
    candidate_count := candidate_count + 1;
    candidate_offer_id := candidate.offer_id;
    candidate_kind := candidate.payment_kind;
    candidate_reference := candidate.external_reference;
  end loop;

  if candidate_count = 0 and profile_payment_id = normalized_payment_id then
    return jsonb_build_object(
      'ok', true,
      'action', 'BOUND',
      'offer_id', null,
      'payment_kind', 'ENROLLMENT_FEE',
      'external_reference', p_student_id::text
    );
  elsif candidate_count = 0 then
    return jsonb_build_object('ok', true, 'action', 'NONE');
  elsif candidate_count > 1 then
    return jsonb_build_object(
      'ok', false,
      'reason', 'enrollment_payment_binding_ambiguous',
      'offer_count', candidate_count
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'action', 'BOUND',
    'offer_id', candidate_offer_id,
    'payment_kind', candidate_kind,
    'external_reference', candidate_reference
  );
end;
$_$;


--
-- Name: resolve_public_tenant(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_public_tenant(p_hostname text) RETURNS TABLE(id text, name text, slug text, custom_domain text, custom_domain_verified boolean, branding jsonb, school_info jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  WITH normalized AS (
    SELECT lower(trim(trailing '.' FROM trim(p_hostname))) AS hostname
  )
  SELECT
    tenant.id,
    tenant.name,
    tenant.slug,
    tenant.custom_domain,
    tenant.custom_domain_verified,
    jsonb_strip_nulls(jsonb_build_object(
      'primaryColor', tenant.branding -> 'primaryColor',
      'secondaryColor', tenant.branding -> 'secondaryColor',
      'logoUrl', tenant.branding -> 'logoUrl',
      'faviconUrl', tenant.branding -> 'faviconUrl'
    )),
    NULL::jsonb
  FROM public.tenants AS tenant
  CROSS JOIN normalized
  WHERE normalized.hostname <> ''
    AND private.tenant_is_operational(tenant.id)
    AND (
      (
        normalized.hostname LIKE '%.wisewolflanguage.com.br'
        AND split_part(normalized.hostname, '.', 2) = 'wisewolflanguage'
        AND tenant.slug = split_part(normalized.hostname, '.', 1)
      )
      OR (
        tenant.custom_domain_verified IS TRUE
        AND lower(trim(trailing '.' FROM tenant.custom_domain)) = normalized.hostname
      )
    )
  ORDER BY tenant.custom_domain_verified DESC
  LIMIT 1;
$$;


--
-- Name: resolve_repaired_asaas_webhook_issue(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_repaired_asaas_webhook_issue(p_provider_event_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_event_id text := nullif(pg_catalog.btrim(coalesce(p_provider_event_id, '')), '');
begin
  if normalized_event_id is null
     or not exists (
       select 1
         from public.asaas_webhook_inbox as inbox
        where inbox.provider_event_id = normalized_event_id
          and inbox.status = 'PROCESSED'
     )
  then
    return false;
  end if;

  update public.asaas_reconciliation_issues
     set resolved_at = coalesce(resolved_at, pg_catalog.now()),
         resolution_note = coalesce(
           resolution_note,
           'legacy provider binding repaired and webhook processed'
         )
   where source = 'WEBHOOK'
     and fingerprint = 'triage:' || normalized_event_id
     and resolved_at is null;
  return true;
end;
$$;


--
-- Name: resolve_tenant_by_host(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_tenant_by_host(p_host text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    SELECT id FROM tenants
    WHERE LOWER(custom_domain) = LOWER(p_host) AND custom_domain_verified = TRUE
    LIMIT 1;
$$;


--
-- Name: resolve_tenant_integration_for_service(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_tenant_integration_for_service(p_tenant_id text, p_provider text, p_capability text, p_purpose text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  connection_record private.tenant_integration_connections%rowtype;
  tenant_whatsapp_enabled boolean;
  decrypted_api_key text;
  credential_environment text;
  historical_reversal boolean := false;
begin
  if p_tenant_id is null
    or nullif(pg_catalog.btrim(p_tenant_id), '') is null
    or p_provider is null
    or p_capability is null
    or p_purpose is null
    or p_provider not in ('evolution', 'asaas')
  then
    raise exception 'integration_request_not_allowed' using errcode = '42501';
  end if;

  historical_reversal := p_provider = 'asaas'
    and p_capability = 'webhook.consume'
    and p_purpose = 'payment.reversal';

  if not private.tenant_is_operational(p_tenant_id)
    and not historical_reversal
  then
    raise exception 'integration_capability_unavailable' using errcode = '42501';
  end if;

  if p_provider = 'asaas' and p_tenant_id <> 'school-wise-wolf' then
    raise exception 'integration_capability_unavailable' using errcode = '42501';
  end if;

  if p_provider = 'evolution' then
    if not coalesce(
      p_capability = 'automation.whatsapp'
      and p_purpose in (
        'instance.create',
        'instance.connect',
        'instance.connection_state',
        'instance.logout',
        'instance.delete',
        'message.send_text',
        'group.list',
        'chat.list',
        'chat.history',
        'webhook.configure'
      ),
      false
    )
    then
      raise exception 'integration_request_not_allowed' using errcode = '42501';
    end if;

    select tenant.whatsapp_enabled
      into tenant_whatsapp_enabled
      from public.tenants as tenant
     where tenant.id = p_tenant_id;
    if tenant_whatsapp_enabled is not true then
      raise exception 'integration_capability_unavailable' using errcode = '42501';
    end if;
  elsif not coalesce((
    (p_capability = 'billing.school' and p_purpose in (
      'customer.create',
      'customer.read',
      'customer.update',
      'customer.delete',
      'payment.create',
      'payment.read',
      'payment.update',
      'payment.delete',
      'subscription.create',
      'subscription.read',
      'subscription.update',
      'subscription.delete',
      'dunning.create'
    ))
    or (
      p_capability = 'webhook.consume'
      and p_purpose in ('payment.event', 'payment.reversal')
    )
    or (
      p_capability = 'reconciliation.read'
      and p_purpose in ('payment.list', 'transfer.list')
    )
    or (
      p_capability = 'payout.teacher'
      and p_purpose in ('transfer.submit', 'transfer.read')
    )
  ), false) then
    raise exception 'integration_request_not_allowed' using errcode = '42501';
  end if;

  select connection.*
    into connection_record
    from private.tenant_integration_connections as connection
   where connection.tenant_id = p_tenant_id
     and connection.provider = p_provider;

  if not found then
    raise exception 'integration_connection_unavailable' using errcode = '55000';
  end if;

  -- This receipt authorizes only an already authenticated historical provider
  -- reversal. It intentionally contains no endpoint or credential and may
  -- survive tenant suspension or integration offboarding.
  if historical_reversal then
    if connection_record.tenant_id <> 'school-wise-wolf'
      or connection_record.provider <> 'asaas'
    then
      raise exception 'integration_capability_unavailable' using errcode = '42501';
    end if;

    return pg_catalog.jsonb_build_object(
      'integrationId', connection_record.id,
      'tenantId', connection_record.tenant_id,
      'provider', connection_record.provider,
      'mode', 'HISTORICAL_WEBHOOK',
      'version', connection_record.version,
      'baseUrl', null,
      'apiKey', null,
      'environment', null
    );
  end if;

  if connection_record.mode = 'DISABLED'
    or (
      connection_record.status <> 'healthy'
      and not (
        connection_record.provider = 'asaas'
        and connection_record.mode = 'PLATFORM_MANAGED_ROOT'
        and connection_record.tenant_id = 'school-wise-wolf'
        and connection_record.status = 'configured'
      )
    )
  then
    raise exception 'integration_connection_unavailable' using errcode = '55000';
  end if;

  if p_provider = 'evolution' then
    if connection_record.mode = 'TENANT_BYOK' then
      select decrypted_secret.decrypted_secret
        into decrypted_api_key
        from private.tenant_secret_registry as registry
        join vault.decrypted_secrets as decrypted_secret
          on decrypted_secret.id = registry.vault_secret_id
       where registry.tenant_id = p_tenant_id
         and registry.provider = p_provider
         and registry.status = 'healthy'
         and registry.last_validated_at is not null;
      if nullif(pg_catalog.btrim(decrypted_api_key), '') is null then
        raise exception 'integration_credential_unavailable' using errcode = '55000';
      end if;
    elsif connection_record.mode <> 'PLATFORM_MANAGED' then
      raise exception 'integration_mode_not_supported' using errcode = '55000';
    end if;
  elsif connection_record.mode = 'PLATFORM_MANAGED_ROOT'
    and connection_record.tenant_id = 'school-wise-wolf'
  then
    credential_environment := 'platform';
  else
    raise exception 'integration_mode_not_supported' using errcode = '55000';
  end if;

  return pg_catalog.jsonb_build_object(
    'integrationId', connection_record.id,
    'tenantId', connection_record.tenant_id,
    'provider', connection_record.provider,
    'mode', connection_record.mode,
    'version', connection_record.version,
    'baseUrl', case
      when connection_record.provider = 'evolution'
        and connection_record.mode = 'TENANT_BYOK'
      then connection_record.connection_config ->> 'baseUrl'
      else null
    end,
    'apiKey', case
      when connection_record.mode in (
        'TENANT_BYOK', 'PLATFORM_MANAGED_SUBACCOUNT'
      )
      then decrypted_api_key
      else null
    end,
    'environment', credential_environment
  );
end;
$$;


--
-- Name: FUNCTION resolve_tenant_integration_for_service(p_tenant_id text, p_provider text, p_capability text, p_purpose text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_tenant_integration_for_service(p_tenant_id text, p_provider text, p_capability text, p_purpose text) IS 'Fail-closed tenant integration broker composing Evolution WhatsApp and scoped Asaas capabilities; historical reversals receive only a secret-free authorization receipt.';


--
-- Name: respond_teacher_transfer(text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_teacher_transfer(p_token text, p_accept boolean, p_decline_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.teacher_transfers; v_dir_phone text; v_dir_name text; v_student text; v_to text;
BEGIN
  SELECT * INTO t FROM public.teacher_transfers WHERE token = p_token FOR UPDATE;
  IF t.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','not_found'); END IF;
  IF t.status <> 'PENDING' THEN RETURN jsonb_build_object('ok',false,'error','already_decided'); END IF;

  IF p_accept THEN
    UPDATE public.teacher_transfers SET status='ACCEPTED', decided_at=now() WHERE id=t.id;
    PERFORM public.apply_teacher_transfer(t.id);  -- move bookings, atualiza professor, vira APPLIED, notifica
    RETURN jsonb_build_object('ok',true,'status','ACCEPTED');
  ELSE
    UPDATE public.teacher_transfers SET status='DECLINED', decided_at=now(), decline_reason=p_decline_reason WHERE id=t.id;
    SELECT full_name INTO v_student FROM public.profiles WHERE id = t.student_id;
    SELECT full_name INTO v_to FROM public.profiles WHERE id = t.to_teacher_id;
    SELECT phone, full_name INTO v_dir_phone, v_dir_name FROM public.profiles
      WHERE tenant_id = t.tenant_id AND role IN ('SCHOOL_ADMIN','SUPER_ADMIN') ORDER BY role DESC LIMIT 1;
    PERFORM public._enqueue_school_whatsapp(
      t.tenant_id, v_dir_phone, v_dir_name,
      'Transferência RECUSADA: ' || COALESCE(v_to,'') || ' não aceitou assumir ' || COALESCE(v_student,'') ||
      COALESCE('. Motivo: ' || p_decline_reason, '') || '. Proponha outro arranjo.');
    RETURN jsonb_build_object('ok',true,'status','DECLINED');
  END IF;
END;
$$;


--
-- Name: respond_trial_reschedule_confirmation(uuid, uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_trial_reschedule_confirmation(p_request_id uuid, p_teacher_id uuid, p_accept boolean, p_response_text text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
declare
  v_request public.trial_reschedule_requests%rowtype;
  v_appointment public.appointments%rowtype;
  v_local timestamp;
  v_date text;
  v_time text;
  v_day_number integer;
  v_day_name text;
begin
  select request.*
    into v_request
    from public.trial_reschedule_requests as request
   where request.id = p_request_id;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'request_not_found');
  end if;
  if v_request.teacher_id is distinct from p_teacher_id then
    return jsonb_build_object('ok', false, 'error', 'teacher_mismatch');
  end if;

  select appointment.*
    into v_appointment
    from public.appointments as appointment
   where appointment.id = v_request.appointment_id
   for update;

  select request.*
    into v_request
    from public.trial_reschedule_requests as request
   where request.id = p_request_id
   for update;

  if v_request.status <> 'PENDING' then
    return jsonb_build_object(
      'ok', true,
      'already_answered', true,
      'status', v_request.status
    );
  end if;
  if v_request.expires_at <= now() or v_request.requested_start_time <= now() then
    update public.trial_reschedule_requests
       set status = 'EXPIRED', response_text = left(p_response_text, 500), responded_at = now()
     where id = v_request.id;
    return jsonb_build_object('ok', false, 'error', 'request_expired');
  end if;
  if not coalesce(p_accept, false) then
    update public.trial_reschedule_requests
       set status = 'DECLINED', response_text = left(p_response_text, 500), responded_at = now()
     where id = v_request.id;
    return jsonb_build_object('ok', true, 'accepted', false, 'status', 'DECLINED');
  end if;
  if v_appointment.id is null
     or lower(coalesce(v_appointment.status, '')) not in (
       'scheduled', 'confirmed', 'no_show'
     )
     or coalesce(v_appointment.teacher_id, v_appointment.professor_id) is distinct from p_teacher_id
     or v_appointment.start_time is distinct from v_request.from_start_time
     or not exists (
       select 1
         from public.opportunities as opportunity
        where opportunity.id = v_request.opportunity_id
          and opportunity.trial_appointment_id = v_request.appointment_id
          and coalesce(opportunity.winner_teacher_id, opportunity.professor_id) = p_teacher_id
          and upper(coalesce(opportunity.trial_status, 'SCHEDULED')) not in (
            'DONE', 'COMPLETED', 'CANCELLED', 'CANCELED'
          )
     )
     or exists (
       select 1
         from public.class_logs as class_log
        where class_log.appointment_id = v_request.appointment_id::text
     ) then
    update public.trial_reschedule_requests
       set status = 'SUPERSEDED', response_text = left(p_response_text, 500), responded_at = now()
     where id = v_request.id;
    return jsonb_build_object('ok', false, 'error', 'appointment_changed');
  end if;

  v_local := timezone('America/Sao_Paulo', v_request.requested_start_time);
  v_date := to_char(v_local, 'YYYY-MM-DD');
  v_time := to_char(v_local, 'HH24:MI');
  v_day_number := extract(dow from v_local)::integer;
  v_day_name := case v_day_number
    when 0 then 'domingo'
    when 1 then 'segunda'
    when 2 then 'terca'
    when 3 then 'quarta'
    when 4 then 'quinta'
    when 5 then 'sexta'
    when 6 then 'sabado'
  end;

  if exists (
    select 1
      from public.appointments as conflict
     where conflict.id <> v_appointment.id
       and coalesce(conflict.teacher_id, conflict.professor_id) = p_teacher_id
       and lower(coalesce(conflict.status, '')) in ('scheduled', 'confirmed')
       and abs(extract(epoch from (conflict.start_time - v_request.requested_start_time))) < 1800
  ) or exists (
    select 1
      from public.bookings as conflict
     where conflict.teacher_id = p_teacher_id
       and upper(coalesce(conflict.status, '')) <> 'CANCELLED'
       and left(coalesce(conflict.time_slot, ''), 5) ~ '^[0-2][0-9]:[0-5][0-9]$'
       and (
         conflict.date::text = v_date
         or (
           lower(translate(coalesce(conflict.day_of_week, ''), 'áàâãäéèêëíìîïóòôõöúùûüç', 'aaaaaeeeeiiiiooooouuuuc')) = v_day_name
         )
       )
       and abs(extract(epoch from (
         (v_date || ' ' || left(conflict.time_slot, 5))::timestamp - v_local
       ))) < 1800
  ) then
    update public.trial_reschedule_requests
       set status = 'CONFLICT', response_text = left(p_response_text, 500), responded_at = now()
     where id = v_request.id;
    return jsonb_build_object('ok', false, 'error', 'teacher_conflict');
  end if;

  update public.appointments
     set start_time = v_request.requested_start_time,
         status = 'scheduled'
   where id = v_appointment.id;

  update public.opportunities
     set slots_proposed = jsonb_build_array(jsonb_build_object(
       'day', v_day_number,
       'date', v_date,
       'time', v_time,
       'formatted', to_char(v_local, 'DD/MM/YYYY') || ' (' ||
         case v_day_number
           when 0 then 'Domingo'
           when 1 then 'Segunda'
           when 2 then 'Terça'
           when 3 then 'Quarta'
           when 4 then 'Quinta'
           when 5 then 'Sexta'
           when 6 then 'Sábado'
         end || ')'
     )),
         status = 'CLAIMED',
         trial_status = 'SCHEDULED',
         conversion_status = 'OPEN',
         lost_reason = null
   where id = v_request.opportunity_id
     and trial_appointment_id = v_request.appointment_id;

  update public.trial_reschedule_requests
     set status = 'ACCEPTED', response_text = left(p_response_text, 500), responded_at = now()
   where id = v_request.id;

  return jsonb_build_object('ok', true, 'accepted', true, 'status', 'ACCEPTED');
end;
$_$;


--
-- Name: resync_student_dispatches(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resync_student_dispatches(p_student uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_conf int; v_notif int;
BEGIN
  -- Cancela confirmações PENDENTES sem resposta cujo dia-da-semana não bate com nenhum booking atual.
  WITH upd AS (
    UPDATE attendance_confirmations ac
       SET status='CANCELLED',
           admin_resolution = COALESCE(ac.admin_resolution,'') || ' [resync: dia fora da grade atual]'
     WHERE ac.status='PENDING' AND ac.student_response IS NULL
       AND (p_student IS NULL OR ac.student_id = p_student)
       AND ac.student_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM bookings b WHERE b.student_id=ac.student_id
                       AND dow_name_to_int(b.day_of_week)=EXTRACT(dow FROM ac.class_date)::int)
     RETURNING 1
  ) SELECT count(*) INTO v_conf FROM upd;

  -- Remove lembretes ainda na fila (pending) de dias que não batem com a grade atual.
  WITH del AS (
    DELETE FROM notification_queue nq
     WHERE nq.status='pending'
       AND (p_student IS NULL OR nq.student_id = p_student)
       AND nq.student_id IS NOT NULL AND nq.class_date IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM bookings b WHERE b.student_id=nq.student_id
                       AND dow_name_to_int(b.day_of_week)=EXTRACT(dow FROM nq.class_date)::int)
     RETURNING 1
  ) SELECT count(*) INTO v_notif FROM del;

  RETURN jsonb_build_object('confirmacoes_canceladas', v_conf, 'lembretes_removidos', v_notif);
END; $$;


--
-- Name: review_material(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_material(p_id uuid, p_approve boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  actor_role text := public._my_role();
  actor_tenant_id text := public._my_tenant_id();
  affected_rows integer;
begin
  if p_id is null or p_approve is null then
    return jsonb_build_object('ok', false, 'error', 'entrada_invalida');
  end if;

  if actor_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN')
     or actor_tenant_id is null
     or not public._my_tenant_is_operational() then
    return jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  if p_approve then
    update public.pedagogical_materials as material
       set approval_status = 'APPROVED',
           scope = 'TENANT',
           reviewed_by = (select auth.uid()),
           reviewed_at = now(),
           rejection_reason = null
     where material.id = p_id
       and material.tenant_id = actor_tenant_id;
  else
    update public.pedagogical_materials as material
       set approval_status = 'REJECTED',
           reviewed_by = (select auth.uid()),
           reviewed_at = now(),
           rejection_reason = nullif(
             left(btrim(coalesce(p_reason, '')), 2000),
             ''
           )
     where material.id = p_id
       and material.tenant_id = actor_tenant_id;
  end if;

  get diagnostics affected_rows = row_count;
  if affected_rows <> 1 then
    return jsonb_build_object('ok', false, 'error', 'nao_encontrado');
  end if;

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: review_srs_card(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_srs_card(p_card_id uuid, p_student_id uuid, p_quality integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_card RECORD;
    v_new_ef NUMERIC(4,2);
    v_new_interval INTEGER;
    v_new_reps INTEGER;
    v_new_lapses INTEGER;
    v_new_status TEXT;
    v_tenant_id TEXT;
BEGIN
    -- 1. Fetch and lock card
    SELECT * INTO v_card FROM public.student_srs_cards
    WHERE id = p_card_id AND student_id = p_student_id
    FOR UPDATE;

    IF v_card IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'CARD_NOT_FOUND');
    END IF;

    -- Get tenant for XP
    SELECT tenant_id INTO v_tenant_id FROM public.profiles WHERE id = p_student_id;

    -- 2. SM-2 Algorithm
    IF p_quality < 3 THEN
        -- Failed: reset
        v_new_reps := 0;
        v_new_interval := 0;
        v_new_lapses := v_card.lapses + 1;
        v_new_ef := GREATEST(1.30, v_card.ease_factor - 0.20);
        v_new_status := 'LEARNING';
    ELSE
        -- Passed
        v_new_lapses := v_card.lapses;
        v_new_reps := v_card.repetitions + 1;

        -- Calculate new ease factor
        v_new_ef := v_card.ease_factor + (0.1 - (5 - p_quality) * (0.08 + (5 - p_quality) * 0.02));
        v_new_ef := GREATEST(1.30, v_new_ef);

        -- Calculate interval
        IF v_new_reps = 1 THEN
            v_new_interval := 1;
        ELSIF v_new_reps = 2 THEN
            v_new_interval := 6;
        ELSE
            v_new_interval := CEIL(v_card.interval_days * v_new_ef);
        END IF;

        -- Status
        IF v_new_interval > 21 AND v_new_reps >= 5 THEN
            v_new_status := 'MASTERED';
        ELSE
            v_new_status := 'REVIEWING';
        END IF;
    END IF;

    -- 3. Update card
    UPDATE public.student_srs_cards SET
        ease_factor = v_new_ef,
        interval_days = v_new_interval,
        repetitions = v_new_reps,
        lapses = v_new_lapses,
        status = v_new_status,
        next_review_at = now() + make_interval(days => v_new_interval),
        last_reviewed_at = now()
    WHERE id = p_card_id;

    -- 4. Award XP if correct
    IF p_quality >= 3 AND v_tenant_id IS NOT NULL THEN
        PERFORM public.record_xp_event(
            p_student_id,
            v_tenant_id,
            'SRS_CORRECT',
            5,
            v_card.vocab_item_id::text,
            'srs:' || p_card_id || ':' || CURRENT_DATE
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'new_interval', v_new_interval,
        'new_ease', v_new_ef,
        'new_status', v_new_status,
        'next_review', (now() + make_interval(days => v_new_interval))
    );
END;
$$;


--
-- Name: reward_teacher_referral(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reward_teacher_referral() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE st tenant_referral_settings%ROWTYPE; v_amount numeric;
BEGIN
  IF NEW.role <> 'TEACHER' OR NEW.referrer_teacher_id IS NULL OR NEW.referrer_teacher_id = NEW.id THEN
    RETURN NEW;
  END IF;
  SELECT * INTO st FROM tenant_referral_settings WHERE tenant_id = NEW.tenant_id;
  IF NOT FOUND OR st.enabled IS NOT TRUE THEN RETURN NEW; END IF;
  -- mesmo valor da indicação (teacher_reward_brl)
  v_amount := COALESCE(st.teacher_reward_brl, st.reward_amount_brl, 0);
  IF v_amount <= 0 THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM referral_rewards WHERE referred_student_id = NEW.id) THEN RETURN NEW; END IF;

  INSERT INTO referral_rewards (tenant_id, referrer_id, referrer_role, referred_student_id, amount_brl, status)
  VALUES (NEW.tenant_id, NEW.referrer_teacher_id, 'TEACHER', NEW.id, v_amount, 'PENDING');
  RETURN NEW;
END;
$$;


--
-- Name: run_monthly_teacher_closing(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_monthly_teacher_closing(p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_month text;
  v_created integer := 0;
  v_updated integer := 0;
  v_carried integer := 0;
  v_inserted integer := 0;
  v_updated_ids uuid[] := '{}';
  v_refresh jsonb;
  v_state text;
  v_teacher record;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'service_role_required';
  END IF;
  v_month := coalesce(
    p_month,
    to_char(current_date - interval '1 month', 'YYYY-MM')
  );
  IF v_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid_month';
  END IF;

  FOR v_teacher IN
    SELECT teacher.id AS teacher_id, teacher.tenant_id
      FROM public.profiles AS teacher
     WHERE teacher.role = 'TEACHER'
       AND teacher.tenant_id IS NOT NULL
       AND lower(coalesce(teacher.lifecycle_status, 'active'))
             NOT IN ('suspended', 'offboarded')
       AND EXISTS (
         SELECT 1
           FROM public.tenant_memberships AS membership
          WHERE membership.user_id = teacher.id
            AND membership.tenant_id = teacher.tenant_id
            AND membership.role = 'TEACHER'
            AND membership.status = 'ACTIVE'
       )
       AND (
         EXISTS (
           SELECT 1 FROM public.class_logs AS class_log
            WHERE class_log.tenant_id = teacher.tenant_id
              AND class_log.teacher_id = teacher.id
              AND to_char(class_log.class_date, 'YYYY-MM') = v_month
         ) OR EXISTS (
           SELECT 1 FROM public.teacher_closings AS closing
            WHERE closing.tenant_id = teacher.tenant_id
              AND closing.teacher_id = teacher.id
              AND closing.month_year = v_month
              AND closing.status = 'PENDENTE'
         ) OR EXISTS (
           SELECT 1 FROM public.closing_adjustments AS adjustment
            WHERE adjustment.tenant_id = teacher.tenant_id
              AND adjustment.teacher_id = teacher.id
              AND adjustment.month_year = v_month
         ) OR EXISTS (
           SELECT 1
             FROM private.teacher_pending_carryover_in_tenant(
               teacher.tenant_id,
               teacher.id
             )
         )
       )
     ORDER BY teacher.tenant_id, teacher.id
  LOOP
    PERFORM private.lock_teacher_closing_pair(
      v_teacher.tenant_id,
      v_month,
      v_teacher.teacher_id,
      NULL
    );

    INSERT INTO public.closing_carryovers (
      class_log_id, teacher_id, origin_month, absorbed_month, amount
    )
    SELECT carryover.class_log_id,
           v_teacher.teacher_id,
           carryover.origin_month,
           v_month,
           carryover.amount
      FROM private.teacher_pending_carryover_in_tenant(
        v_teacher.tenant_id,
        v_teacher.teacher_id
      ) AS carryover
    ON CONFLICT (class_log_id) DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    v_carried := v_carried + v_inserted;

    v_refresh := private.refresh_teacher_closing_snapshot(
      v_teacher.tenant_id,
      v_teacher.teacher_id,
      v_month,
      true
    );
    v_state := coalesce(v_refresh ->> 'state', '');
    IF v_state = 'created' THEN
      v_created := v_created + 1;
    ELSIF v_state = 'updated' THEN
      v_updated := v_updated + 1;
      v_updated_ids := v_updated_ids || v_teacher.teacher_id;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'month', v_month,
    'created', v_created,
    'updated', v_updated,
    'carried_over', v_carried,
    'updated_teacher_ids', to_jsonb(v_updated_ids)
  );
END;
$_$;


--
-- Name: run_recurring_expenses(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_recurring_expenses(p_month text DEFAULT NULL::text, p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_role text; v_tenant text; v_month text; v_scope text;
  v_criados int := 0; v_pulados int := 0; v_total numeric := 0;
  r record; v_data date;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();

  IF v_role IS NULL THEN
    -- Sem usuário = cron/service_role: roda para todos (ou o tenant pedido).
    v_scope := p_tenant;
  ELSIF v_role IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    v_scope := CASE WHEN v_role = 'SUPER_ADMIN' THEN COALESCE(p_tenant, v_tenant) ELSE v_tenant END;
  ELSE
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;

  v_month := COALESCE(p_month, to_char(current_date,'YYYY-MM'));
  IF v_month !~ '^\d{4}-\d{2}$' THEN RETURN jsonb_build_object('error','mes_invalido'); END IF;

  FOR r IN
    SELECT re.* FROM recurring_expenses re
     WHERE re.is_active
       AND (v_scope IS NULL OR re.tenant_id = v_scope)
       AND re.start_month <= v_month
       AND (re.end_month IS NULL OR re.end_month >= v_month)
  LOOP
    v_data := make_date(split_part(v_month,'-',1)::int, split_part(v_month,'-',2)::int, r.day_of_month);

    -- ON CONFLICT no índice único: se já foi materializada, não duplica.
    -- Idempotência garantida pelo banco, não pela ordem das chamadas.
    -- ⚠️ O índice é PARCIAL, então o predicado tem de ser repetido aqui — sem o
    -- WHERE o Postgres não infere o índice e devolve "no unique or exclusion
    -- constraint matching the ON CONFLICT specification". É a mesma pedra em que
    -- uq_bookings_no_dup_active já fez tropeçar.
    INSERT INTO financial_transactions
      (tenant_id, type, category, amount, amount_cents, description,
       occurred_at, account_code, recurring_expense_id, recurring_month)
    VALUES
      (r.tenant_id, 'SAIDA', 'despesa_recorrente', r.amount, round(r.amount * 100),
       r.label, v_data::timestamptz, r.account_code, r.id, v_month)
    ON CONFLICT (recurring_expense_id, recurring_month)
      WHERE recurring_expense_id IS NOT NULL DO NOTHING;

    IF FOUND THEN
      v_criados := v_criados + 1; v_total := v_total + r.amount;
    ELSE
      v_pulados := v_pulados + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'month', v_month,
                            'criados', v_criados, 'ja_existiam', v_pulados,
                            'total_lancado', v_total);
END;
$_$;


--
-- Name: FUNCTION run_recurring_expenses(p_month text, p_tenant text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.run_recurring_expenses(p_month text, p_tenant text) IS 'Materializa as despesas recorrentes vigentes como SAIDA no caixa. Idempotente por índice único (recurring_expense_id, recurring_month) — pode rodar quantas vezes quiser.';


--
-- Name: run_saas_billing(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_saas_billing() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_generated int; v_overdue int; v_blocked int; v_pastdue int; v_reactivated int;
BEGIN
  -- 1) Marca faturas PENDENTES vencidas como OVERDUE
  UPDATE saas_invoices SET status='OVERDUE'
   WHERE status='PENDING' AND due_date < current_date;
  GET DIAGNOSTICS v_overdue = ROW_COUNT;

  -- 2) Gera fatura do ciclo para escolas ativas com plano cujo período acabou (idempotente por mês)
  INSERT INTO saas_invoices (tenant_id, amount, status, due_date, period_month, created_at)
  SELECT t.id, pl.price, 'PENDING',
         COALESCE(t.current_period_end::date, current_date + 5),
         to_char(COALESCE(t.current_period_end, now()), 'YYYY-MM'),
         now()
  FROM tenants t JOIN saas_plans pl ON pl.id = t.plan_id
  WHERE t.id <> 'master' AND t.saas_status IN ('active','past_due') AND t.plan_id IS NOT NULL
    AND (t.current_period_end IS NULL OR t.current_period_end::date <= current_date)
  ON CONFLICT (tenant_id, period_month) DO NOTHING;
  GET DIAGNOSTICS v_generated = ROW_COUNT;

  -- avança o período das que acabaram de ser faturadas
  UPDATE tenants
     SET current_period_end = (date_trunc('month', COALESCE(current_period_end, now())) + interval '1 month')::timestamptz
   WHERE id <> 'master' AND saas_status IN ('active','past_due') AND plan_id IS NOT NULL
     AND (current_period_end IS NULL OR current_period_end::date <= current_date);

  -- 3) Suspensão automática por inadimplência
  -- past_due: tem fatura vencida
  UPDATE tenants SET saas_status='past_due'
   WHERE id<>'master' AND saas_status='active'
     AND EXISTS (SELECT 1 FROM saas_invoices i WHERE i.tenant_id=tenants.id AND i.status='OVERDUE');
  GET DIAGNOSTICS v_pastdue = ROW_COUNT;

  -- blocked: fatura vencida há mais de 10 dias
  UPDATE tenants SET saas_status='blocked'
   WHERE id<>'master' AND saas_status IN ('active','past_due')
     AND EXISTS (SELECT 1 FROM saas_invoices i WHERE i.tenant_id=tenants.id AND i.status='OVERDUE' AND i.due_date < current_date - 10);
  GET DIAGNOSTICS v_blocked = ROW_COUNT;

  -- 4) Reativa quem quitou (past_due sem nenhuma fatura vencida) — não reativa 'blocked' (manual)
  UPDATE tenants SET saas_status='active'
   WHERE id<>'master' AND saas_status='past_due'
     AND NOT EXISTS (SELECT 1 FROM saas_invoices i WHERE i.tenant_id=tenants.id AND i.status='OVERDUE');
  GET DIAGNOSTICS v_reactivated = ROW_COUNT;

  RETURN jsonb_build_object('generated',v_generated,'marked_overdue',v_overdue,'past_due',v_pastdue,'blocked',v_blocked,'reactivated',v_reactivated);
END;
$$;


--
-- Name: saas_metrics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saas_metrics() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE r jsonb;
BEGIN
  IF NOT is_super_admin() THEN RETURN jsonb_build_object('error','sem_permissao'); END IF;

  SELECT jsonb_build_object(
    'total_tenants', count(*) FILTER (WHERE t.id <> 'master'),
    'active_tenants', count(*) FILTER (WHERE t.id <> 'master' AND t.saas_status = 'active'),
    'blocked_tenants', count(*) FILTER (WHERE t.id <> 'master' AND t.saas_status IN ('blocked','past_due')),
    'paying_tenants', count(*) FILTER (WHERE t.id <> 'master' AND t.plan_id IS NOT NULL AND t.saas_status = 'active'),
    'no_plan', count(*) FILTER (WHERE t.id <> 'master' AND t.plan_id IS NULL),
    'mrr', coalesce(sum(pl.price) FILTER (WHERE t.saas_status = 'active' AND t.id <> 'master'), 0),
    'arr', coalesce(sum(pl.price) FILTER (WHERE t.saas_status = 'active' AND t.id <> 'master'), 0) * 12,
    'arpu', round(coalesce(sum(pl.price) FILTER (WHERE t.saas_status='active' AND t.id<>'master'),0)
                  / nullif(count(*) FILTER (WHERE t.id<>'master' AND t.plan_id IS NOT NULL AND t.saas_status='active'),0), 2),
    'trials_expiring', count(*) FILTER (WHERE t.trial_ends_at IS NOT NULL AND t.trial_ends_at::date BETWEEN current_date AND current_date + 7),
    'total_students', (SELECT count(*) FROM profiles WHERE role='STUDENT'),
    'total_teachers', (SELECT count(*) FROM profiles WHERE role='TEACHER'),
    'overdue_invoices', (SELECT count(*) FROM saas_invoices WHERE status='OVERDUE'),
    'overdue_amount', (SELECT coalesce(sum(amount),0) FROM saas_invoices WHERE status='OVERDUE')
  ) INTO r
  FROM tenants t LEFT JOIN saas_plans pl ON pl.id = t.plan_id;
  RETURN r;
END;
$$;


--
-- Name: save_dre_report_settings(text, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_dre_report_settings(p_destino text, p_cadencia text, p_dia_semana integer DEFAULT 1, p_is_active boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; v_destino text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;

  v_destino := btrim(COALESCE(p_destino,''));
  IF v_destino = '' THEN RETURN jsonb_build_object('error','destino_obrigatorio'); END IF;
  -- Grupo do WhatsApp termina em @g.us; fora isso tem de ser telefone com DDD.
  IF v_destino NOT LIKE '%@g.us'
     AND length(regexp_replace(v_destino,'\D','','g')) < 10 THEN
    RETURN jsonb_build_object('error','destino_invalido');
  END IF;
  IF p_cadencia NOT IN ('diaria','semanal','mensal') THEN
    RETURN jsonb_build_object('error','cadencia_invalida');
  END IF;
  IF p_dia_semana IS NULL OR p_dia_semana NOT BETWEEN 1 AND 7 THEN
    RETURN jsonb_build_object('error','dia_invalido');
  END IF;

  INSERT INTO dre_report_settings (tenant_id, destino, cadencia, dia_semana, is_active)
  VALUES (v_tenant, v_destino, p_cadencia, p_dia_semana, COALESCE(p_is_active,true))
  ON CONFLICT (tenant_id) DO UPDATE
    SET destino = EXCLUDED.destino, cadencia = EXCLUDED.cadencia,
        dia_semana = EXCLUDED.dia_semana, is_active = EXCLUDED.is_active,
        updated_at = now();

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: save_hub_educator_plan_run(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_hub_educator_plan_run(p_run_id uuid, p_actor_id uuid, p_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_run public.hub_educator_plan_runs%rowtype;
  v_learner public.hub_educator_learners%rowtype;
  v_access jsonb;
  v_plan_id uuid;
  v_memory jsonb;
  v_memory_proposal jsonb;
  v_has_memory_proposal boolean;
  v_memory_proposal_status text;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'service_role' then
    raise exception 'service_role_required' using errcode = '42501';
  end if;
  if p_run_id is null or p_actor_id is null then
    raise exception 'invalid_planner_save' using errcode = '22023';
  end if;

  select run.*
    into v_run
  from public.hub_educator_plan_runs as run
  where run.id = p_run_id
  for update;

  if not found then
    raise exception 'hub_planner_run_not_found' using errcode = 'P0002';
  end if;
  if v_run.created_by <> p_actor_id
     or (p_account_id is not null and v_run.account_id <> p_account_id) then
    raise exception 'hub_planner_run_forbidden' using errcode = '42501';
  end if;

  v_access := public.hub_authorize_educator_planner_access(
    p_actor_id,
    v_run.account_id
  );
  if v_access ->> 'allowed' <> 'true' then
    raise exception 'hub_planner_access_denied' using errcode = '42501';
  end if;

  select learner.*
    into v_learner
  from public.hub_educator_learners as learner
  where learner.account_id = v_run.account_id
    and learner.id = v_run.learner_id;

  if not found then
    raise exception 'hub_planner_learner_not_found' using errcode = 'P0002';
  end if;
  if v_access ->> 'membershipRole' = 'MEMBER'
     and v_learner.created_by <> p_actor_id then
    raise exception 'hub_planner_learner_forbidden' using errcode = '42501';
  end if;

  if not exists (
    select 1
    from public.hub_usage_events as usage_event
    where usage_event.account_id = v_run.account_id
      and usage_event.subscription_id = v_run.subscription_id
      and usage_event.user_id = v_run.created_by
      and usage_event.feature_key = 'educator_ai.generate'
      and usage_event.request_key = v_run.request_key
  ) then
    raise exception 'hub_planner_usage_not_committed' using errcode = '42501';
  end if;

  if v_run.status = 'SAVED' then
    select plan.id
      into v_plan_id
    from public.hub_educator_plans as plan
    where plan.run_id = v_run.id;
    if v_plan_id is null then
      raise exception 'hub_planner_saved_run_inconsistent' using errcode = 'P0002';
    end if;
    select pg_catalog.to_jsonb(memory.*)
      into v_memory
    from public.hub_educator_memory as memory
    where memory.account_id = v_run.account_id
      and memory.learner_id = v_run.learner_id
      and memory.created_by = v_run.created_by;
    select proposal.verification_status
      into v_memory_proposal_status
    from public.hub_educator_memory_proposals as proposal
    where proposal.run_id = v_run.id;
    return pg_catalog.jsonb_build_object(
      'saved', true,
      'idempotent', true,
      'lessonPlanId', v_plan_id,
      'runId', v_run.id,
      'memory', v_memory,
      'memoryProposalStatus', v_memory_proposal_status
    );
  end if;

  if v_run.status <> 'DRAFT' or v_run.expires_at <= pg_catalog.now() then
    raise exception 'hub_planner_run_expired' using errcode = '22023';
  end if;

  insert into public.hub_educator_plans (
    account_id,
    learner_id,
    created_by,
    run_id,
    objective,
    task_mode,
    duration_minutes,
    bilingual,
    teacher_request,
    plan,
    model_id,
    prompt_version
  ) values (
    v_run.account_id,
    v_run.learner_id,
    v_run.created_by,
    v_run.id,
    coalesce(v_run.plan ->> 'objective', ''),
    v_run.task_mode,
    v_run.duration_minutes,
    v_run.bilingual,
    v_run.teacher_request,
    v_run.plan,
    v_run.model_id,
    v_run.prompt_version
  )
  on conflict (run_id) do nothing
  returning id into v_plan_id;

  if v_plan_id is null then
    select plan.id
      into v_plan_id
    from public.hub_educator_plans as plan
    where plan.run_id = v_run.id;
  end if;
  if v_plan_id is null then
    raise exception 'hub_planner_plan_persistence_failed' using errcode = 'P0002';
  end if;

  v_memory_proposal := coalesce(
    v_run.plan -> 'student_memory_update',
    '{}'::jsonb
  );
  v_has_memory_proposal := pg_catalog.jsonb_typeof(v_memory_proposal) = 'object'
    and exists (
      select 1
      from pg_catalog.jsonb_each(v_memory_proposal) as item(key, value)
      where item.key <> 'confidence_level'
        and (
          (
            pg_catalog.jsonb_typeof(item.value) = 'string'
            and pg_catalog.btrim(item.value #>> '{}') <> ''
          )
          or (
            pg_catalog.jsonb_typeof(item.value) = 'array'
            and pg_catalog.jsonb_array_length(item.value) > 0
          )
        )
    );

  if v_has_memory_proposal then
    insert into public.hub_educator_memory_proposals (
      account_id,
      learner_id,
      created_by,
      run_id,
      proposal
    ) values (
      v_run.account_id,
      v_run.learner_id,
      v_run.created_by,
      v_run.id,
      v_memory_proposal
    )
    on conflict (run_id) do nothing;
    v_memory_proposal_status := 'PROPOSED';
  end if;

  select pg_catalog.to_jsonb(memory.*)
    into v_memory
  from public.hub_educator_memory as memory
  where memory.account_id = v_run.account_id
    and memory.learner_id = v_run.learner_id
    and memory.created_by = v_run.created_by;

  update public.hub_educator_plan_runs as run
  set status = 'SAVED',
      saved_at = pg_catalog.now()
  where run.id = v_run.id;

  return pg_catalog.jsonb_build_object(
    'saved', true,
    'idempotent', false,
    'lessonPlanId', v_plan_id,
    'runId', v_run.id,
    'memory', v_memory,
    'memoryProposalStatus', v_memory_proposal_status
  );
end;
$$;


--
-- Name: save_nf_settings(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_nf_settings(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_tenant text := public._my_tenant_id();
  v_role text := public._my_role();
begin
  if v_uid is null or v_tenant is null then
    return jsonb_build_object('ok', false, 'error', 'Não autenticado');
  end if;

  if v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    return jsonb_build_object('ok', false, 'error', 'Sem permissão');
  end if;

  insert into public.tenant_nf_settings as t (
    tenant_id, cnpj, razao_social, nome_fantasia, codigo_tributacao,
    descricao_tributacao, descricao_servico, portal_url, observacoes,
    is_active, updated_by, updated_at
  ) values (
    v_tenant,
    btrim(p_payload->>'cnpj'),
    btrim(p_payload->>'razao_social'),
    btrim(p_payload->>'nome_fantasia'),
    btrim(p_payload->>'codigo_tributacao'),
    btrim(p_payload->>'descricao_tributacao'),
    btrim(p_payload->>'descricao_servico'),
    btrim(p_payload->>'portal_url'),
    btrim(p_payload->>'observacoes'),
    coalesce((p_payload->>'is_active')::boolean, true),
    v_uid,
    now()
  )
  on conflict (tenant_id) do update set
    cnpj                 = excluded.cnpj,
    razao_social         = excluded.razao_social,
    nome_fantasia        = excluded.nome_fantasia,
    codigo_tributacao    = excluded.codigo_tributacao,
    descricao_tributacao = excluded.descricao_tributacao,
    descricao_servico    = excluded.descricao_servico,
    portal_url           = excluded.portal_url,
    observacoes          = excluded.observacoes,
    is_active            = excluded.is_active,
    updated_by           = excluded.updated_by,
    updated_at           = now();

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: save_payment_split_settings(numeric, numeric, boolean, numeric, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_payment_split_settings(p_dizimo_pct numeric, p_investimento_pct numeric, p_is_active boolean DEFAULT true, p_escola_pct numeric DEFAULT 0.00, p_prof_dizimo_pct numeric DEFAULT 10.00, p_prof_investimento_pct numeric DEFAULT 70.00, p_prof_prolabore_pct numeric DEFAULT 20.00) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;
  IF p_dizimo_pct IS NULL OR p_investimento_pct IS NULL OR p_escola_pct IS NULL
     OR p_prof_dizimo_pct IS NULL OR p_prof_investimento_pct IS NULL OR p_prof_prolabore_pct IS NULL
     OR p_dizimo_pct < 0 OR p_investimento_pct < 0 OR p_escola_pct < 0
     OR p_prof_dizimo_pct < 0 OR p_prof_investimento_pct < 0 OR p_prof_prolabore_pct < 0 THEN
    RETURN jsonb_build_object('error','percentual_invalido');
  END IF;
  IF p_dizimo_pct + p_investimento_pct + p_escola_pct > 100 THEN
    RETURN jsonb_build_object('error','percentual_acima_de_100');
  END IF;
  IF p_prof_dizimo_pct + p_prof_investimento_pct + p_prof_prolabore_pct > 100 THEN
    RETURN jsonb_build_object('error','percentual_professor_acima_de_100');
  END IF;
  -- Ligar sem destino deixaria o aviso morrendo em silêncio a cada pagamento.
  IF COALESCE(p_is_active,true)
     AND NOT EXISTS (SELECT 1 FROM dre_report_settings d
                      WHERE d.tenant_id = v_tenant AND COALESCE(d.destino,'') <> '') THEN
    RETURN jsonb_build_object('error','sem_grupo_configurado');
  END IF;

  INSERT INTO payment_split_settings
    (tenant_id, dizimo_pct, investimento_pct, escola_pct, is_active,
     prof_dizimo_pct, prof_investimento_pct, prof_prolabore_pct)
  VALUES (v_tenant, p_dizimo_pct, p_investimento_pct, p_escola_pct, COALESCE(p_is_active,true),
          p_prof_dizimo_pct, p_prof_investimento_pct, p_prof_prolabore_pct)
  ON CONFLICT (tenant_id) DO UPDATE
    SET dizimo_pct = EXCLUDED.dizimo_pct, investimento_pct = EXCLUDED.investimento_pct,
        escola_pct = EXCLUDED.escola_pct, is_active = EXCLUDED.is_active,
        prof_dizimo_pct = EXCLUDED.prof_dizimo_pct,
        prof_investimento_pct = EXCLUDED.prof_investimento_pct,
        prof_prolabore_pct = EXCLUDED.prof_prolabore_pct,
        updated_at = now();

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: save_planner_ai_run(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_planner_ai_run(p_run_id uuid, p_actor_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  run_row public.planner_ai_runs%rowtype;
  memory_row jsonb;
  lesson_plan_id uuid;
  materials_text text;
  has_memory boolean;
begin
  select *
    into run_row
    from public.planner_ai_runs
   where id = p_run_id
   for update;

  if not found then
    raise exception 'planner_run_not_found' using errcode = 'P0002';
  end if;

  if run_row.teacher_id <> p_actor_id then
    raise exception 'planner_run_forbidden' using errcode = '42501';
  end if;

  if run_row.status = 'SAVED' then
    select id
      into lesson_plan_id
      from public.lesson_plans
     where planner_run_id = run_row.id;
    if lesson_plan_id is null then
      raise exception 'planner_saved_run_inconsistent' using errcode = 'P0002';
    end if;
    return lesson_plan_id;
  end if;

  if run_row.status <> 'DRAFT' or run_row.expires_at <= now() then
    raise exception 'planner_run_expired' using errcode = '22023';
  end if;

  select coalesce(string_agg(material ->> 'title', ', '), '')
    into materials_text
    from jsonb_array_elements(
      case
        when jsonb_typeof(run_row.result -> 'materials') = 'array'
          then run_row.result -> 'materials'
        else '[]'::jsonb
      end
    ) as material;

  insert into public.lesson_plans (
    tenant_id,
    teacher_id,
    student_id,
    plan_date,
    objectives,
    content,
    materials,
    ai_memory,
    custom_prompt,
    ai_suggestions,
    task_mode,
    duration_minutes,
    bilingual,
    structured_plan,
    student_memory_update,
    source_materials,
    model_id,
    prompt_version,
    response_id,
    planner_run_id
  )
  values (
    run_row.tenant_id,
    run_row.teacher_id,
    run_row.student_id,
    current_date,
    coalesce(run_row.result ->> 'objective', ''),
    coalesce(
      run_row.result ->> 'legacy_content',
      run_row.result ->> 'overview',
      ''
    ),
    materials_text,
    coalesce(run_row.result ->> 'ai_memory_reflection', ''),
    run_row.teacher_request,
    coalesce(run_row.result ->> 'overview', ''),
    run_row.task_mode,
    run_row.duration_minutes,
    run_row.bilingual,
    run_row.result - 'legacy_content',
    coalesce(run_row.result -> 'student_memory_update', '{}'::jsonb),
    run_row.retrieved_sources,
    run_row.model_id,
    run_row.prompt_version,
    run_row.response_id,
    run_row.id
  )
  on conflict (planner_run_id)
  do update set planner_run_id = excluded.planner_run_id
  returning id into lesson_plan_id;

  memory_row := coalesce(
    run_row.result -> 'student_memory_update',
    '{}'::jsonb
  );
  has_memory :=
    coalesce(memory_row ->> 'lesson_objective', '') <> ''
    or coalesce(memory_row ->> 'homework_assigned', '') <> ''
    or coalesce(memory_row ->> 'recommended_next_step', '') <> ''
    or jsonb_array_length(
      case when jsonb_typeof(memory_row -> 'content_practiced') = 'array'
        then memory_row -> 'content_practiced' else '[]'::jsonb end
    ) > 0
    or jsonb_array_length(
      case when jsonb_typeof(memory_row -> 'new_vocabulary') = 'array'
        then memory_row -> 'new_vocabulary' else '[]'::jsonb end
    ) > 0
    or jsonb_array_length(
      case when jsonb_typeof(memory_row -> 'recurring_errors') = 'array'
        then memory_row -> 'recurring_errors' else '[]'::jsonb end
    ) > 0
    or jsonb_array_length(
      case when jsonb_typeof(memory_row -> 'corrections_mastered') = 'array'
        then memory_row -> 'corrections_mastered' else '[]'::jsonb end
    ) > 0
    or jsonb_array_length(
      case when jsonb_typeof(memory_row -> 'strengths_observed') = 'array'
        then memory_row -> 'strengths_observed' else '[]'::jsonb end
    ) > 0
    or jsonb_array_length(
      case when jsonb_typeof(memory_row -> 'notes_to_verify') = 'array'
        then memory_row -> 'notes_to_verify' else '[]'::jsonb end
    ) > 0;

  if has_memory then
    insert into public.student_learning_memories (
      tenant_id,
      student_id,
      source_type,
      source_ref,
      occurred_at,
      lesson_objective,
      content_practiced,
      new_vocabulary,
      recurring_errors,
      corrections_mastered,
      strengths_observed,
      homework_assigned,
      recommended_next_step,
      confidence_level,
      notes_to_verify,
      verification_status,
      metadata,
      created_by
    )
    values (
      run_row.tenant_id,
      run_row.student_id,
      'PLANNER_AI',
      run_row.id::text,
      now(),
      coalesce(memory_row ->> 'lesson_objective', ''),
      array(
        select jsonb_array_elements_text(
          case when jsonb_typeof(memory_row -> 'content_practiced') = 'array'
            then memory_row -> 'content_practiced' else '[]'::jsonb end
        )
      ),
      array(
        select jsonb_array_elements_text(
          case when jsonb_typeof(memory_row -> 'new_vocabulary') = 'array'
            then memory_row -> 'new_vocabulary' else '[]'::jsonb end
        )
      ),
      array(
        select jsonb_array_elements_text(
          case when jsonb_typeof(memory_row -> 'recurring_errors') = 'array'
            then memory_row -> 'recurring_errors' else '[]'::jsonb end
        )
      ),
      array(
        select jsonb_array_elements_text(
          case when jsonb_typeof(memory_row -> 'corrections_mastered') = 'array'
            then memory_row -> 'corrections_mastered' else '[]'::jsonb end
        )
      ),
      array(
        select jsonb_array_elements_text(
          case when jsonb_typeof(memory_row -> 'strengths_observed') = 'array'
            then memory_row -> 'strengths_observed' else '[]'::jsonb end
        )
      ),
      coalesce(memory_row ->> 'homework_assigned', ''),
      coalesce(memory_row ->> 'recommended_next_step', ''),
      case
        when memory_row ->> 'confidence_level' in ('LOW', 'MEDIUM', 'HIGH')
          then memory_row ->> 'confidence_level'
        else 'LOW'
      end,
      array(
        select jsonb_array_elements_text(
          case when jsonb_typeof(memory_row -> 'notes_to_verify') = 'array'
            then memory_row -> 'notes_to_verify' else '[]'::jsonb end
        )
      ),
      'PROPOSED',
      jsonb_build_object(
        'planner_run_id',
        run_row.id,
        'planned_not_observed',
        true
      ),
      p_actor_id
    )
    on conflict (tenant_id, student_id, source_type, source_ref)
    do nothing;
  end if;

  update public.planner_ai_runs
     set status = 'SAVED',
         saved_at = now()
   where id = run_row.id;

  return lesson_plan_id;
end
$$;


--
-- Name: save_realtime_settings(boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_realtime_settings(p_enabled boolean, p_monthly_token_quota bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id text;
  v_role text;
begin
  v_tenant_id := private.active_tenant_id(v_user_id);
  v_role := private.active_tenant_role(v_user_id);

  if v_user_id is null
     or v_tenant_id is null
     or v_role is null
     or v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN')
     or not exists (
       select 1
         from public.tenant_memberships as membership
        where membership.user_id = v_user_id
          and membership.tenant_id = v_tenant_id
          and membership.status = 'ACTIVE'
     ) then
    raise exception using errcode = '42501', message = 'sem_permissao';
  end if;
  if p_monthly_token_quota is null or p_monthly_token_quota < 0 then
    raise exception using errcode = '22023', message = 'cota_invalida';
  end if;

  insert into public.tenant_realtime_settings as settings (
    tenant_id,
    enabled,
    monthly_token_quota,
    updated_at,
    updated_by
  ) values (
    v_tenant_id,
    coalesce(p_enabled, false),
    p_monthly_token_quota,
    pg_catalog.now(),
    v_user_id
  )
  on conflict (tenant_id) do update
    set enabled = excluded.enabled,
        monthly_token_quota = excluded.monthly_token_quota,
        updated_at = excluded.updated_at,
        updated_by = excluded.updated_by;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'tenantId', v_tenant_id,
    'enabled', coalesce(p_enabled, false),
    'quota', p_monthly_token_quota
  );
end;
$$;


--
-- Name: save_referral_settings(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_referral_settings(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;
  INSERT INTO tenant_referral_settings (tenant_id, enabled, student_reward_brl, teacher_reward_brl, min_payments, monthly_cap, cooldown_days, self_referral_block, reward_expires_days, updated_at, updated_by)
  VALUES (v_tenant,
    COALESCE((p->>'enabled')::boolean, false),
    COALESCE((p->>'student_reward_brl')::numeric, 0),
    COALESCE((p->>'teacher_reward_brl')::numeric, 0),
    COALESCE((p->>'min_payments')::int, 1),
    COALESCE(NULLIF(p->>'monthly_cap','')::int, 0),
    COALESCE((p->>'cooldown_days')::int, 0),
    COALESCE((p->>'self_referral_block')::boolean, true),
    COALESCE(NULLIF(p->>'reward_expires_days','')::int, 0),
    now(), auth.uid())
  ON CONFLICT (tenant_id) DO UPDATE SET
    enabled=EXCLUDED.enabled, student_reward_brl=EXCLUDED.student_reward_brl, teacher_reward_brl=EXCLUDED.teacher_reward_brl,
    min_payments=EXCLUDED.min_payments, monthly_cap=EXCLUDED.monthly_cap, cooldown_days=EXCLUDED.cooldown_days,
    self_referral_block=EXCLUDED.self_referral_block, reward_expires_days=EXCLUDED.reward_expires_days,
    updated_at=now(), updated_by=auth.uid();
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: save_renewal_offer_settings(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_renewal_offer_settings(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_uid uuid := (select auth.uid());
  v_tenant text := public._my_tenant_id();
  v_role text := public._my_role();
  v_dias int;
begin
  if v_uid is null or v_tenant is null then
    return jsonb_build_object('ok', false, 'error', 'Não autenticado');
  end if;
  if v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    return jsonb_build_object('ok', false, 'error', 'Sem permissão');
  end if;

  v_dias := coalesce((p_payload->>'dias_antes')::int, 15);
  if v_dias < 1 or v_dias > 90 then
    return jsonb_build_object('ok', false, 'error', 'Antecedência deve ficar entre 1 e 90 dias');
  end if;

  insert into public.renewal_offer_settings (tenant_id, is_active, dias_antes, assinatura, updated_by, updated_at)
  values (v_tenant,
          coalesce((p_payload->>'is_active')::boolean, false),
          v_dias,
          btrim(p_payload->>'assinatura'),
          v_uid, now())
  on conflict (tenant_id) do update set
    is_active  = excluded.is_active,
    dias_antes = excluded.dias_antes,
    assinatura = excluded.assinatura,
    updated_by = excluded.updated_by,
    updated_at = now();

  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: save_student_generated_activities(uuid, jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_student_generated_activities(p_student_id uuid, p_activities jsonb, p_request_key uuid, p_reservation_id uuid, p_lease_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_profile record;
  v_reservation public.student_complementary_generation_reservations%rowtype;
  v_existing public.student_generated_activity_batches%rowtype;
  v_batch_id uuid;
  v_request_key text := p_request_key::text;
  v_item jsonb;
  v_type text;
  v_title text;
  v_description text;
  v_content text;
  v_content_json jsonb;
  v_difficulty text;
  v_category text;
  v_seen_types text[] := array[]::text[];
  v_position integer;
  v_pending_count integer;
  v_inserted public.student_activities%rowtype;
  v_activities jsonb := '[]'::jsonb;
  v_result jsonb;
  v_now timestamptz := pg_catalog.now();
begin
  if p_student_id is null
     or p_request_key is null
     or p_reservation_id is null
     or p_lease_token is null then
    raise exception using
      errcode = '42501',
      message = 'generation_reservation_required';
  end if;

  if p_activities is null
     or pg_catalog.jsonb_typeof(p_activities) is distinct from 'array'
     or pg_catalog.jsonb_array_length(p_activities) <> 4
     or pg_catalog.pg_column_size(p_activities) > 65536 then
    raise exception using
      errcode = '22023',
      message = 'invalid_generated_activity_batch';
  end if;

  select profile.tenant_id, profile.role
    into v_profile
    from public.profiles as profile
   where profile.id = p_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  select *
    into v_reservation
    from public.student_complementary_generation_reservations as reservation
   where reservation.id = p_reservation_id
     and reservation.student_id = p_student_id
     and reservation.tenant_id = v_profile.tenant_id
     and reservation.request_key = p_request_key
   for update;

  if not found or v_reservation.lease_token is distinct from p_lease_token then
    raise exception using
      errcode = '42501',
      message = 'generation_reservation_not_owned';
  end if;

  select *
    into v_existing
    from public.student_generated_activity_batches as batch
   where batch.student_id = p_student_id
     and batch.request_key = v_request_key
   for update;

  if found then
    if v_existing.request_payload is distinct from p_activities then
      raise exception using
        errcode = '22023',
        message = 'idempotency_key_reused';
    end if;

    if v_reservation.status not in ('RESERVED', 'COMMITTED')
       or (
         v_reservation.status = 'COMMITTED'
         and v_reservation.batch_id is distinct from v_existing.id
       ) then
      raise exception using
        errcode = 'P0001',
        message = 'generation_reservation_not_active';
    end if;

    if v_reservation.status = 'RESERVED'
       and v_reservation.lease_expires_at <= v_now then
      raise exception using
        errcode = 'P0001',
        message = 'generation_reservation_expired';
    end if;

    if v_reservation.batch_id is null then
      update public.student_complementary_generation_reservations
         set batch_id = v_existing.id,
             updated_at = v_now
       where id = v_reservation.id;
    end if;

    return v_existing.result || pg_catalog.jsonb_build_object(
      'alreadyApplied', true
    );
  end if;

  if v_reservation.status <> 'RESERVED' then
    raise exception using
      errcode = 'P0001',
      message = 'generation_reservation_not_active';
  end if;

  if v_reservation.lease_expires_at <= v_now then
    raise exception using
      errcode = 'P0001',
      message = 'generation_reservation_expired';
  end if;

  for v_item, v_position in
    select value, ordinality::integer
      from pg_catalog.jsonb_array_elements(p_activities)
           with ordinality
  loop
    if pg_catalog.jsonb_typeof(v_item) is distinct from 'object' then
      raise exception using
        errcode = '22023',
        message = 'invalid_generated_activity';
    end if;

    v_type := pg_catalog.lower(
      pg_catalog.btrim(coalesce(v_item ->> 'type', ''))
    );
    v_title := pg_catalog.btrim(coalesce(v_item ->> 'title', ''));
    v_description := pg_catalog.btrim(
      coalesce(v_item ->> 'description', '')
    );
    v_difficulty := pg_catalog.upper(
      pg_catalog.btrim(coalesce(v_item ->> 'difficulty', ''))
    );
    v_category := nullif(
      pg_catalog.btrim(coalesce(v_item ->> 'category', '')),
      ''
    );

    if v_type not in ('reading', 'grammar', 'quiz', 'conversation')
       or v_type = any(v_seen_types)
       or pg_catalog.length(v_title) not between 3 and 160
       or pg_catalog.length(v_description) > 1000
       or v_difficulty not in ('BEGINNER', 'INTERMEDIATE', 'ADVANCED')
       or (v_category is not null and pg_catalog.length(v_category) > 160)
       or pg_catalog.jsonb_typeof(v_item -> 'content')
            is distinct from 'string' then
      raise exception using
        errcode = '22023',
        message = 'invalid_generated_activity';
    end if;

    v_content := v_item ->> 'content';
    if pg_catalog.octet_length(v_content) not between 2 and 16000 then
      raise exception using
        errcode = '22023',
        message = 'invalid_generated_activity_content';
    end if;

    begin
      v_content_json := v_content::jsonb;
    exception
      when others then
        raise exception using
          errcode = '22023',
          message = 'invalid_generated_activity_content';
    end;

    if coalesce(
      private.generated_activity_content_is_valid(
        v_type,
        v_content_json
      ),
      false
    ) is not true then
      raise exception using
        errcode = '22023',
        message = 'invalid_generated_activity_content';
    end if;

    v_seen_types := pg_catalog.array_append(v_seen_types, v_type);
  end loop;

  if not (
    'reading' = any(v_seen_types)
    and 'grammar' = any(v_seen_types)
    and 'quiz' = any(v_seen_types)
    and 'conversation' = any(v_seen_types)
  ) then
    raise exception using
      errcode = '22023',
      message = 'invalid_generated_activity_type_set';
  end if;

  select pg_catalog.count(*)::integer
    into v_pending_count
    from public.student_activities as activity
   where activity.student_id = p_student_id
     and activity.tenant_id = v_profile.tenant_id
     and activity.status = 'PENDING';

  -- Packs are atomic from the learner's point of view. Any unfinished item
  -- means the previous four-pack is still active and a new generation would
  -- create a confusing mixed queue.
  if v_pending_count > 0 then
    raise exception using
      errcode = 'P0001',
      message = 'pending_complementary_package_exists';
  end if;

  v_batch_id := pg_catalog.gen_random_uuid();
  insert into public.student_generated_activity_batches (
    id,
    tenant_id,
    student_id,
    request_key,
    request_payload,
    result,
    created_at
  ) values (
    v_batch_id,
    v_profile.tenant_id,
    p_student_id,
    v_request_key,
    p_activities,
    '{}'::jsonb,
    v_now
  );

  for v_item, v_position in
    select value, ordinality::integer
      from pg_catalog.jsonb_array_elements(p_activities)
           with ordinality
  loop
    v_type := pg_catalog.lower(
      pg_catalog.btrim(v_item ->> 'type')
    );
    v_title := pg_catalog.btrim(v_item ->> 'title');
    v_description := nullif(
      pg_catalog.btrim(coalesce(v_item ->> 'description', '')),
      ''
    );
    v_content := v_item ->> 'content';
    v_difficulty := pg_catalog.upper(
      pg_catalog.btrim(v_item ->> 'difficulty')
    );
    v_category := nullif(
      pg_catalog.btrim(coalesce(v_item ->> 'category', '')),
      ''
    );

    insert into public.student_activities (
      student_id,
      tenant_id,
      type,
      title,
      description,
      content,
      difficulty,
      category,
      xp_reward,
      status,
      generated_by_ai,
      generation_batch_id,
      generation_position,
      created_at,
      updated_at
    ) values (
      p_student_id,
      v_profile.tenant_id,
      v_type,
      v_title,
      v_description,
      v_content,
      v_difficulty,
      v_category,
      0,
      'PENDING',
      true,
      v_batch_id,
      v_position,
      v_now,
      v_now
    )
    returning * into v_inserted;

    v_activities := v_activities || pg_catalog.jsonb_build_array(
      (
        pg_catalog.to_jsonb(v_inserted) - 'content'
      ) || pg_catalog.jsonb_build_object(
        'content', private.safe_student_complementary_content(
          v_inserted.type,
          v_inserted.content
        )
      )
    );
  end loop;

  v_result := pg_catalog.jsonb_build_object(
    'batchId', v_batch_id,
    'requestKey', v_request_key,
    'alreadyApplied', false,
    'created', true,
    'quotaReached', false,
    'activities', v_activities
  );

  update public.student_generated_activity_batches
     set result = v_result
   where id = v_batch_id;

  update public.student_complementary_generation_reservations
     set batch_id = v_batch_id,
         updated_at = v_now
   where id = v_reservation.id;

  return v_result;
end;
$$;


--
-- Name: FUNCTION save_student_generated_activities(p_student_id uuid, p_activities jsonb, p_request_key uuid, p_reservation_id uuid, p_lease_token uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.save_student_generated_activities(p_student_id uuid, p_activities jsonb, p_request_key uuid, p_reservation_id uuid, p_lease_token uuid) IS 'Service-only persistence of one validated four-type generated activity pack bound to an active student reservation, with zero XP and request idempotency.';


--
-- Name: schedule_manual_trial_secure(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_manual_trial_secure(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_tenant_id text;
  v_actor_role text;
  v_request_id uuid;
  v_lead_id uuid;
  v_lead public.crm_leads%rowtype;
  v_receipt_fingerprint text;
  v_receipt_response jsonb;
  v_has_receipt boolean := false;
  v_response jsonb;
  v_opportunity_id uuid;
  v_payload_phone text;
  v_lead_phone text;
begin
  if pg_catalog.jsonb_typeof(coalesce(p_payload, '{}'::jsonb))
       is distinct from 'object' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'invalid_payload'
    );
  end if;

  if not p_payload ? 'leadId' then
    return public.schedule_manual_trial_secure_pre_crm_binding_impl(
      p_payload
    );
  end if;

  if not p_payload ?& array[
       'requestId', 'leadId', 'teacherId', 'studentName',
       'studentPhone', 'startsAt'
     ]
     or (select pg_catalog.count(*)
           from pg_catalog.jsonb_object_keys(p_payload)) <> 6 then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'invalid_payload'
    );
  end if;

  begin
    v_request_id := (p_payload ->> 'requestId')::uuid;
    v_lead_id := (p_payload ->> 'leadId')::uuid;
  exception when invalid_text_representation then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'invalid_payload'
    );
  end;

  select actor.actor_id, actor.tenant_id, actor.actor_role
    into v_actor_id, v_tenant_id, v_actor_role
    from private.secure_trial_actor_context() as actor;
  if v_actor_id is null
     or v_actor_role not in ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN') then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  -- The legacy five-key scheduler remains available to coordinators.  Binding
  -- a CRM row follows the narrower CRM authority and is director-only here;
  -- do not let SECURITY DEFINER bypass the crm_leads RLS role boundary.
  if v_actor_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;

  select lead.*
    into v_lead
    from public.crm_leads as lead
   where lead.id = v_lead_id
     and lead.tenant_id = v_tenant_id
   for update;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'lead_not_found'
    );
  end if;

  select receipt.payload_fingerprint, receipt.response
    into v_receipt_fingerprint, v_receipt_response
    from private.secure_trial_command_receipts as receipt
   where receipt.tenant_id = v_tenant_id
     and receipt.actor_id = v_actor_id
     and receipt.command = 'MANUAL_SCHEDULE'
     and receipt.request_id = v_request_id;
  v_has_receipt := found;

  -- A retry may reuse only the receipt that originally bound this exact lead.
  -- A new request for an already-linked lead must never create a second trial.
  if v_lead.opportunity_id is not null then
    if not v_has_receipt then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'error', 'lead_already_has_trial',
        'opportunityId', v_lead.opportunity_id
      );
    end if;
    if v_receipt_fingerprint is distinct from
         private.secure_trial_payload_fingerprint(p_payload - 'leadId') then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    begin
      v_opportunity_id := (v_receipt_response ->> 'opportunityId')::uuid;
    exception when invalid_text_representation then
      v_opportunity_id := null;
    end;
    if v_opportunity_id is distinct from v_lead.opportunity_id then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    return coalesce(v_receipt_response, '{}'::jsonb)
      || pg_catalog.jsonb_build_object(
        'idempotent', true,
        'leadId', v_lead_id
      );
  end if;

  -- A receipt with no matching lead binding belongs to the legacy five-key
  -- command (or to another lead) and cannot be adopted retroactively.
  if v_has_receipt then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'idempotency_key_reused'
    );
  end if;

  if pg_catalog.upper(pg_catalog.btrim(coalesce(v_lead.status, 'NEW')))
       not in ('NEW', 'CONTACTED', 'SCHEDULED') then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'lead_not_schedulable'
    );
  end if;
  if pg_catalog.lower(pg_catalog.btrim(coalesce(v_lead.name, '')))
       is distinct from
       pg_catalog.lower(pg_catalog.btrim(coalesce(
         p_payload ->> 'studentName', ''
       ))) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'lead_identity_mismatch'
    );
  end if;

  v_payload_phone := private.normalize_notification_phone(
    p_payload ->> 'studentPhone'
  );
  v_lead_phone := private.normalize_notification_phone(v_lead.phone);
  if (v_payload_phone is null) is distinct from (v_lead_phone is null)
     or (
       v_payload_phone is not null
       and not private.notification_phones_same_recipient(
         v_payload_phone,
         v_lead_phone
       )
     ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'lead_identity_mismatch'
    );
  end if;

  v_response := public.schedule_manual_trial_secure_pre_crm_binding_impl(
    p_payload - 'leadId'
  );
  if coalesce((v_response ->> 'ok')::boolean, false) is not true then
    return v_response;
  end if;
  begin
    v_opportunity_id := (v_response ->> 'opportunityId')::uuid;
  exception when invalid_text_representation then
    raise exception 'manual trial returned an invalid opportunity'
      using errcode = 'XX000';
  end;
  if v_opportunity_id is null then
    raise exception 'manual trial returned no opportunity'
      using errcode = 'XX000';
  end if;

  perform pg_catalog.set_config(
    'app.crm_trial_binding_lead',
    v_lead_id::text,
    true
  );
  perform pg_catalog.set_config(
    'app.crm_trial_binding_opportunity',
    v_opportunity_id::text,
    true
  );
  update public.crm_leads as lead
     set opportunity_id = v_opportunity_id,
         status = 'CONTACTED',
         scheduled_at = null
   where lead.id = v_lead_id
     and lead.tenant_id = v_tenant_id
     and lead.opportunity_id is null;
  if not found then
    raise exception 'crm lead binding lost its row lock'
      using errcode = '40001';
  end if;
  perform pg_catalog.set_config('app.crm_trial_binding_lead', '', true);
  perform pg_catalog.set_config(
    'app.crm_trial_binding_opportunity',
    '',
    true
  );

  return v_response || pg_catalog.jsonb_build_object('leadId', v_lead_id);
exception
  when unique_violation then
    raise exception 'trial opportunity is already bound to another lead'
      using errcode = '23505';
end;
$$;


--
-- Name: FUNCTION schedule_manual_trial_secure(p_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.schedule_manual_trial_secure(p_payload jsonb) IS 'Schedules a secure manual trial; optional leadId atomically binds the CRM lead to the authoritative opportunity.';


--
-- Name: schedule_manual_trial_secure_pre_crm_binding_impl(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_manual_trial_secure_pre_crm_binding_impl(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_id uuid;
  v_tenant_id text;
  v_actor_role text;
  v_request_id uuid;
  v_teacher_id uuid;
  v_teacher_name text;
  v_student_name text;
  v_student_phone text;
  v_start_time timestamptz;
  v_local_date date;
  v_local_time time without time zone;
  v_slot jsonb;
  v_opportunity_id uuid;
  v_confirmation_url text;
  v_fingerprint text;
  v_existing_fingerprint text;
  v_existing_response jsonb;
  v_response jsonb;
begin
  if jsonb_typeof(p_payload) is distinct from 'object'
     or not p_payload ?& array[
       'requestId', 'teacherId', 'studentName', 'studentPhone', 'startsAt'
     ]
     or (select count(*) from jsonb_object_keys(p_payload)) <> 5 then
    return jsonb_build_object('ok', false, 'error', 'invalid_payload');
  end if;

  begin
    v_request_id := (p_payload ->> 'requestId')::uuid;
    v_teacher_id := (p_payload ->> 'teacherId')::uuid;
    if coalesce(p_payload ->> 'startsAt', '') !~
       '(?:[zZ]|[+-][0-9]{2}:[0-9]{2})$' then
      return jsonb_build_object('ok', false, 'error', 'invalid_start_time');
    end if;
    v_start_time := (p_payload ->> 'startsAt')::timestamptz;
  exception
    when invalid_text_representation
       or invalid_datetime_format
       or datetime_field_overflow then
      return jsonb_build_object('ok', false, 'error', 'invalid_payload');
  end;

  v_student_name := trim(coalesce(p_payload ->> 'studentName', ''));
  v_student_phone := regexp_replace(
    coalesce(p_payload ->> 'studentPhone', ''), '[^0-9]', '', 'g'
  );
  if length(v_student_name) not between 2 and 160 then
    return jsonb_build_object('ok', false, 'error', 'invalid_student_name');
  end if;
  if v_student_phone = '' then
    v_student_phone := null;
  elsif length(v_student_phone) not between 10 and 15 then
    return jsonb_build_object('ok', false, 'error', 'invalid_student_phone');
  end if;
  if v_start_time <= now() + interval '5 minutes'
     or v_start_time > now() + interval '366 days' then
    return jsonb_build_object('ok', false, 'error', 'invalid_start_time');
  end if;

  select actor.actor_id, actor.tenant_id, actor.actor_role
    into v_actor_id, v_tenant_id, v_actor_role
    from private.secure_trial_actor_context() as actor;

  if v_actor_id is null
     or v_actor_role not in ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN') then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if not private.tenant_is_operational(v_tenant_id) then
    return jsonb_build_object('ok', false, 'error', 'tenant_not_operational');
  end if;

  select profile.full_name
    into v_teacher_name
    from public.profiles as profile
    join public.tenant_memberships as membership
      on membership.user_id = profile.id
     and membership.tenant_id = v_tenant_id
     and membership.role = 'TEACHER'
     and membership.status = 'ACTIVE'
   where profile.id = v_teacher_id
     and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
   for share of profile, membership;

  if not found then
    return jsonb_build_object(
      'ok', false, 'error', 'teacher_not_active_for_tenant'
    );
  end if;

  v_fingerprint := private.secure_trial_payload_fingerprint(p_payload);
  select receipt.payload_fingerprint, receipt.response
    into v_existing_fingerprint, v_existing_response
    from private.secure_trial_command_receipts as receipt
   where receipt.tenant_id = v_tenant_id
     and receipt.actor_id = v_actor_id
     and receipt.command = 'MANUAL_SCHEDULE'
     and receipt.request_id = v_request_id;
  if found then
    if v_existing_fingerprint <> v_fingerprint then
      return jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    return coalesce(v_existing_response, '{}'::jsonb)
      || jsonb_build_object('idempotent', true);
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_teacher_id::text, 0)
  );

  select receipt.payload_fingerprint, receipt.response
    into v_existing_fingerprint, v_existing_response
    from private.secure_trial_command_receipts as receipt
   where receipt.tenant_id = v_tenant_id
     and receipt.actor_id = v_actor_id
     and receipt.command = 'MANUAL_SCHEDULE'
     and receipt.request_id = v_request_id;
  if found then
    if v_existing_fingerprint <> v_fingerprint then
      return jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    return coalesce(v_existing_response, '{}'::jsonb)
      || jsonb_build_object('idempotent', true);
  end if;

  if private.secure_trial_schedule_conflict(
    v_tenant_id, v_teacher_id, v_start_time, null, null
  ) then
    return jsonb_build_object(
      'ok', false, 'error', 'teacher_schedule_conflict'
    );
  end if;

  insert into private.secure_trial_command_receipts (
    tenant_id, actor_id, command, request_id, payload_fingerprint
  ) values (
    v_tenant_id, v_actor_id, 'MANUAL_SCHEDULE',
    v_request_id, v_fingerprint
  )
  on conflict do nothing;

  if not found then
    select receipt.payload_fingerprint, receipt.response
      into v_existing_fingerprint, v_existing_response
      from private.secure_trial_command_receipts as receipt
     where receipt.tenant_id = v_tenant_id
       and receipt.actor_id = v_actor_id
       and receipt.command = 'MANUAL_SCHEDULE'
       and receipt.request_id = v_request_id;
    if v_existing_fingerprint <> v_fingerprint then
      return jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    return coalesce(v_existing_response, '{}'::jsonb)
      || jsonb_build_object('idempotent', true);
  end if;

  v_local_date := (v_start_time at time zone 'America/Sao_Paulo')::date;
  v_local_time := (v_start_time at time zone 'America/Sao_Paulo')::time;
  v_slot := jsonb_build_object(
    'day', extract(dow from v_local_date)::integer,
    'date', to_char(v_local_date, 'YYYY-MM-DD'),
    'time', to_char(v_local_time, 'HH24:MI'),
    'formatted', to_char(v_local_date, 'DD/MM/YYYY') || ' às ' ||
      to_char(v_local_time, 'HH24:MI'),
    'start_time', v_start_time
  );

  insert into public.opportunities (
    tenant_id, student_name, student_phone, slots_proposed,
    status, kind, conversion_status, opened_at, claim_generation
  ) values (
    v_tenant_id, v_student_name, v_student_phone,
    jsonb_build_array(v_slot), 'OPEN', 'TRIAL', 'OPEN', now(), 1
  )
  returning id into v_opportunity_id;

  insert into private.vendor_trial_teacher_requests (
    tenant_id, opportunity_id, target_teacher_id,
    requested_by, slot_start, status, student_confirmed_at
  ) values (
    v_tenant_id, v_opportunity_id, v_teacher_id,
    v_actor_id, v_start_time, 'AWAITING_TEACHER', now()
  );

  v_confirmation_url := private.secure_trial_portal_origin(v_tenant_id)
    || '/claim-opportunity?id=' || v_opportunity_id::text || '&g=1';

  v_response := jsonb_build_object(
    'ok', true,
    'idempotent', false,
    'opportunityId', v_opportunity_id,
    'teacherName', coalesce(nullif(trim(v_teacher_name), ''), 'Professor(a)'),
    'startsAt', v_start_time,
    'state', 'AWAITING_TEACHER',
    'teacherConfirmationUrl', v_confirmation_url
  );

  update private.secure_trial_command_receipts
     set response = v_response,
         completed_at = now()
   where tenant_id = v_tenant_id
     and actor_id = v_actor_id
     and command = 'MANUAL_SCHEDULE'
     and request_id = v_request_id;

  return v_response;
end;
$_$;


--
-- Name: schedule_oral_test(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_oral_test(p_test_id uuid, p_examiner_id uuid, p_scheduled_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_tenant_id text;
  v_test public.oral_tests%rowtype;
begin
  if v_uid is null then
    raise exception
      using errcode = '28000', message = 'Authentication required';
  end if;
  if p_scheduled_at is null then
    raise exception
      using errcode = '22023', message = 'Schedule date is required';
  end if;

  select p.role, p.tenant_id
    into v_role, v_tenant_id
    from public.profiles as p
   where p.id = v_uid;

  if v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    raise exception
      using errcode = '42501', message = 'Administrator role required';
  end if;

  select ot.*
    into v_test
    from public.oral_tests as ot
   where ot.id = p_test_id
   for update;

  if not found
     or (
       v_role <> 'SUPER_ADMIN'
       and v_test.tenant_id is distinct from v_tenant_id
     ) then
    raise exception
      using errcode = '42501', message = 'Oral test is outside the allowed tenant';
  end if;
  if v_test.status in ('DONE', 'SKIPPED') then
    raise exception
      using errcode = '22023', message = 'Completed oral tests cannot be scheduled';
  end if;

  if p_examiner_id is not null
     and not exists (
       select 1
         from public.profiles as examiner
        where examiner.id = p_examiner_id
          and examiner.role = 'TEACHER'
          and examiner.tenant_id = v_test.tenant_id
          and examiner.can_oral_test is true
          and examiner.id is distinct from v_test.native_teacher_id
     ) then
    raise exception
      using errcode = '42501', message = 'Examiner is not eligible for this oral test';
  end if;

  update public.oral_tests as ot
     set examiner_id = p_examiner_id,
         scheduled_at = p_scheduled_at,
         status = 'SCHEDULED'
   where ot.id = v_test.id;

  return jsonb_build_object(
    'test_id', v_test.id,
    'status', 'SCHEDULED',
    'scheduled_at', p_scheduled_at,
    'examiner_id', p_examiner_id
  );
end;
$$;


--
-- Name: schedule_reschedule(uuid, date, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_reschedule(p_reschedule_id uuid, p_date date, p_time time without time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor_role text := public._my_role();
  v_actor_tenant text := public._my_tenant_id();
  v_reschedule public.reschedules%rowtype;
  v_result jsonb;
begin
  if v_actor_id is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  if v_actor_tenant is null
     or not coalesce(v_actor_role in (
       'TEACHER', 'SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN'
     ), false)
     or not coalesce(public._my_tenant_is_operational(), false)
  then
    raise exception using
      errcode = '42501',
      message = 'reschedule_schedule_not_authorized';
  end if;

  if p_reschedule_id is null or p_date is null or p_time is null then
    raise exception using
      errcode = '22023',
      message = 'invalid_reschedule_slot';
  end if;

  select reschedule.*
    into v_reschedule
    from public.reschedules as reschedule
   where reschedule.id = p_reschedule_id
     and reschedule.tenant_id = v_actor_tenant
     and reschedule.used_at is null
   for update of reschedule;

  if not found then
    raise exception using
      errcode = 'P0002',
      message = 'reschedule_not_found_or_consumed';
  end if;

  if v_actor_role = 'TEACHER'
     and v_reschedule.teacher_id is distinct from v_actor_id
  then
    raise exception using
      errcode = '42501',
      message = 'reschedule_schedule_not_authorized';
  end if;

  if v_actor_role = 'TEACHER'
     and (p_date + p_time) <= (
       pg_catalog.now() at time zone 'America/Sao_Paulo'
     )
  then
    raise exception using
      errcode = '22023',
      message = 'teacher_reschedule_slot_must_be_future';
  end if;

  if not private.reschedule_participants_are_active(
    v_reschedule.id,
    v_reschedule.tenant_id,
    v_reschedule.teacher_id,
    v_reschedule.student_id
  ) then
    raise exception using
      errcode = '55000',
      message = 'reschedule_participant_inactive';
  end if;

  update public.reschedules as reschedule
     set date = pg_catalog.to_char(p_date, 'YYYY-MM-DD'),
         time = pg_catalog.to_char(p_time, 'HH24:MI')
   where reschedule.id = v_reschedule.id;

  select pg_catalog.jsonb_build_object(
           'id', reschedule.id,
           'date', reschedule.date,
           'time', reschedule.time,
           'notification_revision', reschedule.notification_revision
         )
    into v_result
    from public.reschedules as reschedule
   where reschedule.id = v_reschedule.id;

  return v_result;
end;
$$;


--
-- Name: FUNCTION schedule_reschedule(p_reschedule_id uuid, p_date date, p_time time without time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.schedule_reschedule(p_reschedule_id uuid, p_date date, p_time time without time zone) IS 'Agenda um credito de reposicao existente alterando somente data e hora. Identidade, tenant e origem financeira nao sao aceitos como entrada.';


--
-- Name: schedule_student_vocab_review(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_student_vocab_review(p_activity_id uuid, p_term text, p_translation text, p_example text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.assert_active_student_learning_mutation();
  return public.schedule_student_vocab_review_core(
    p_activity_id,
    p_term,
    p_translation,
    p_example
  );
end;
$$;


--
-- Name: schedule_student_vocab_review_core(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_student_vocab_review_core(p_activity_id uuid, p_term text, p_translation text, p_example text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_id uuid := auth.uid();
  v_profile record;
  v_activity record;
  v_enrollment public.student_path_enrollments%rowtype;
  v_current record;
  v_card jsonb;
  v_term text := pg_catalog.btrim(coalesce(p_term, ''));
  v_translation text := pg_catalog.btrim(coalesce(p_translation, ''));
  v_example text := nullif(pg_catalog.btrim(coalesce(p_example, '')), '');
  v_review public.student_vocab_reviews%rowtype;
  v_now timestamptz := pg_catalog.now();
begin
  if v_student_id is null or p_activity_id is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  if pg_catalog.length(v_term) not between 1 and 200
     or pg_catalog.length(v_translation) not between 1 and 500
     or (v_example is not null and pg_catalog.length(v_example) > 2000) then
    raise exception using
      errcode = '22023',
      message = 'invalid_vocab_review_card';
  end if;

  select profile.tenant_id, profile.role
    into v_profile
    from public.profiles as profile
   where profile.id = v_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  select
    activity.id,
    activity.unit_id,
    activity.content,
    unit.path_id
    into v_activity
    from public.unit_activities as activity
    join public.learning_units as unit
      on unit.id = activity.unit_id
    join public.learning_paths as path
      on path.id = unit.path_id
   where activity.id = p_activity_id
     and activity.type = 'vocab_cards'
     and path.active is true
     and (
       path.tenant_id is null
       or path.tenant_id = v_profile.tenant_id
     );

  if not found
     or pg_catalog.jsonb_typeof(v_activity.content -> 'cards')
          is distinct from 'array' then
    raise exception using
      errcode = '42501',
      message = 'vocab_activity_not_available';
  end if;

  select *
    into v_enrollment
    from public.student_path_enrollments as enrollment
   where enrollment.student_id = v_student_id
     and enrollment.path_id = v_activity.path_id
     and enrollment.tenant_id = v_profile.tenant_id
     and enrollment.status = 'ACTIVE'
     and enrollment.completed_at is null
   for update;

  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'active_learning_enrollment_required';
  end if;

  select next_activity.activity_id, next_activity.unit_id
    into v_current
    from private.next_incomplete_learning_activity(
      v_student_id,
      v_activity.path_id
    ) as next_activity;

  if not found or v_current.activity_id <> p_activity_id then
    raise exception using
      errcode = 'P0001',
      message = 'learning_activity_not_current';
  end if;

  select card.value
    into v_card
    from pg_catalog.jsonb_array_elements(
      v_activity.content -> 'cards'
    ) as card(value)
   where pg_catalog.jsonb_typeof(card.value) = 'object'
     and pg_catalog.btrim(coalesce(card.value ->> 'term', '')) = v_term
     and pg_catalog.btrim(coalesce(card.value ->> 'translation', '')) =
           v_translation
     and nullif(
           pg_catalog.btrim(coalesce(card.value ->> 'example', '')),
           ''
         ) is not distinct from v_example
   limit 1;

  if not found then
    raise exception using
      errcode = '22023',
      message = 'vocab_review_card_not_in_activity';
  end if;

  insert into public.student_vocab_reviews (
    tenant_id,
    student_id,
    term,
    translation,
    example,
    source_activity_id,
    interval_days,
    consecutive_correct,
    next_review_at,
    created_at,
    updated_at
  ) values (
    v_profile.tenant_id,
    v_student_id,
    v_term,
    v_translation,
    v_example,
    p_activity_id,
    1,
    0,
    v_now + interval '1 day',
    v_now,
    v_now
  )
  on conflict (student_id, term) do update
    set tenant_id = excluded.tenant_id,
        translation = excluded.translation,
        example = excluded.example,
        source_activity_id = excluded.source_activity_id,
        interval_days = 1,
        consecutive_correct = 0,
        next_review_at = excluded.next_review_at,
        updated_at = v_now
  returning * into v_review;

  return pg_catalog.jsonb_build_object(
    'reviewId', v_review.id,
    'term', v_review.term,
    'intervalDays', v_review.interval_days,
    'consecutiveCorrect', v_review.consecutive_correct,
    'totalReviews', v_review.total_reviews,
    'nextReviewAt', v_review.next_review_at
  );
end;
$$;


--
-- Name: FUNCTION schedule_student_vocab_review_core(p_activity_id uuid, p_term text, p_translation text, p_example text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.schedule_student_vocab_review_core(p_activity_id uuid, p_term text, p_translation text, p_example text) IS 'Schedules an owned card from the current vocab activity without trusting browser scope.';


