-- Name: schedule_teacher_training(text, text, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_teacher_training(p_tenant text, p_request_id text, p_trainer uuid, p_trainee uuid, p_start timestamp with time zone) RETURNS jsonb
