--
-- Name: sdr_available_trial_slots(text, date, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sdr_available_trial_slots(p_tenant_id text, p_from date, p_days integer DEFAULT 14, p_teacher_id uuid DEFAULT NULL::uuid) RETURNS TABLE(date text, "time" text, teacher_id uuid, teacher_name text, phone text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  if p_days not between 1 and 14 or p_from is null
    or p_from<(now() at time zone 'America/Sao_Paulo')::date
    or p_from>(now() at time zone 'America/Sao_Paulo')::date+90 then raise exception 'invalid_date_range'; end if;
  return query
  with candidates as (
    select distinct d::date as slot_date,a.start_time,p.id,p.full_name,p.phone,
      (d::date+a.start_time) at time zone 'America/Sao_Paulo' starts
    from generate_series(p_from::timestamp,(p_from+p_days-1)::timestamp,interval '1 day') d
    join public.teacher_availability a on a.tenant_id=p_tenant_id and a.day_of_week=extract(dow from d)::integer
    join public.profiles p on p.id=a.teacher_id and p.lifecycle_status='active'
    join public.tenant_memberships m on m.user_id=p.id and m.tenant_id=p_tenant_id and m.role='TEACHER' and m.status='ACTIVE'
    where (p_teacher_id is null or p.id=p_teacher_id) and nullif(trim(p.phone),'') is not null
      and coalesce(p.status,'') not in ('Inativo','INACTIVE','Inactive','Arquivado','Cancelado','Trancado')
      and a.day_of_week between 1 and 6 and a.start_time between time '07:00' and time '21:30'
  ) select to_char(c.slot_date,'YYYY-MM-DD'),to_char(c.start_time,'HH24:MI'),c.id,c.full_name,c.phone from candidates c
  where c.starts>now()
    and not private.secure_trial_schedule_conflict(p_tenant_id,c.id,c.starts,null,null)
    and not exists(select 1 from public.bookings b where b.tenant_id=p_tenant_id and b.teacher_id=c.id
      and b.date=c.slot_date and lower(coalesce(b.status,'scheduled')) not in ('cancelled','canceled','inactive')
      and left(b.time_slot,5)~'^[0-2][0-9]:[0-5][0-9]$'
      and abs(extract(epoch from (left(b.time_slot,5)::time-c.start_time)))<1800)
    and not exists(select 1 from private.enrollment_offer_schedule_slots s where s.tenant_id=p_tenant_id and s.teacher_id=c.id
      and s.status='RESERVED' and s.reservation_expires_at>now() and s.day_of_week=extract(dow from c.slot_date)::integer
      and s.start_date<=c.slot_date and abs(extract(epoch from (s.class_time-c.start_time)))<1800)
    and not exists(select 1 from public.reschedules r where r.tenant_id=p_tenant_id and r.teacher_id=c.id and r.used_at is null
      and r.date=c.slot_date::text and left(r.time,5)~'^[0-2][0-9]:[0-5][0-9]$'
      and abs(extract(epoch from (left(r.time,5)::time-c.start_time)))<1800)
    and not exists(select 1 from public.class_coverages cc where cc.tenant_id=p_tenant_id and cc.cover_teacher_id=c.id
      and cc.class_date=c.slot_date and upper(cc.status) in ('PENDING','CONFIRMED','ACCEPTED','COMPLETED')
      and left(cc.class_time,5)~'^[0-2][0-9]:[0-5][0-9]$'
      and abs(extract(epoch from (left(cc.class_time,5)::time-c.start_time)))<1800)
  order by 1,2,3;
end;
$_$;


--
-- Name: sdr_operations_dashboard(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sdr_operations_dashboard(p_tenant_id text, p_days integer DEFAULT 7) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; since_at timestamptz;
begin
  if not private.can_manage_sdr(p_tenant_id) then raise exception 'forbidden' using errcode='42501'; end if;
  if p_days not in (7,30) then raise exception 'invalid_period'; end if;
  since_at:=now()-make_interval(days=>p_days);
  with cohort as (
    select l.* from public.crm_leads l where l.tenant_id=p_tenant_id and l.ai_handled=true and l.created_at>=since_at
  ), messages as (
    select m.*,lag(m.content) over(partition by m.phone order by m.created_at,m.id) previous_content,
      lag(m.created_at) over(partition by m.phone order by m.created_at,m.id) previous_at
    from public.ai_wa_messages m where m.tenant_id=p_tenant_id and m.agent='sdr'
      and m.direction='out' and m.created_at>=since_at and m.meta->>'entregue'='true'
  ), queue as (
    select l.id,l.name,l.phone,l.status,
      case when w.phase='REVIEW' then 'delivery_review'
        when l.ai_handoff=true and (l.ai_handoff_at is null or l.ai_handoff_at>now()-interval '72 hours') then 'human_requested'
        when w.latest_msg_id is distinct from w.completed_msg_id and w.updated_at<now()-interval '10 minutes' then 'unanswered'
        when o.status='EXPIRED' and o.lost_reason is null and o.opened_at>now()-interval '3 days' then 'teacher_timeout'
        when r.status in ('DECLINED','CONFLICT') then 'teacher_declined'
        when l.status in ('SCHEDULED','TRIAL') and ap.start_time<now()-interval '2 hours'
          and not exists(select 1 from public.class_logs cl where cl.appointment_id=ap.id::text) then 'missing_class_result'
      end reason,
      case when w.phase='REVIEW' then w.updated_at
        when l.ai_handoff=true then coalesce(l.ai_handoff_at,l.last_status_change,l.created_at)
        when w.latest_msg_id is distinct from w.completed_msg_id then w.updated_at
        when o.status='EXPIRED' then o.opened_at+interval '60 minutes'
        when r.status in ('DECLINED','CONFLICT') then r.responded_at else ap.start_time end waiting_since,
      case when a.resolved_at is null and a.assigned_at>now()-interval '72 hours' then a.owner_id end owner_id,
      case when a.resolved_at is null and a.assigned_at>now()-interval '72 hours' then p.full_name end owner_name,a.resolved_at,
      case when w.phase='REVIEW' then 1 when l.ai_handoff=true then 2 else 3 end priority
    from public.crm_leads l
    left join public.sdr_conversation_work w on w.tenant_id=l.tenant_id and w.phone=regexp_replace(l.phone,'[^0-9]','','g')
    left join lateral (select oo.* from public.opportunities oo where oo.tenant_id=l.tenant_id and oo.kind='TRIAL' and not coalesce(oo.is_test_fixture,false)
      and (oo.id=l.opportunity_id or (l.opportunity_id is null and regexp_replace(oo.student_phone,'[^0-9]','','g')=regexp_replace(l.phone,'[^0-9]','','g')))
      and oo.created_at>now()-interval '30 days' order by oo.created_at desc limit 1) o on true
    left join public.appointments ap on ap.id=o.trial_appointment_id and ap.tenant_id=l.tenant_id
    left join lateral(select rr.status,rr.responded_at from public.trial_reschedule_requests rr
      where rr.tenant_id=l.tenant_id and rr.lead_id=l.id order by rr.created_at desc limit 1) r on true
    left join private.sdr_attention_assignments a on a.lead_id=l.id
    left join public.profiles p on p.id=a.owner_id
    where l.tenant_id=p_tenant_id and l.ai_handled=true and l.status not in ('WON','LOST')
  ), actionable as (select * from queue where reason is not null and (resolved_at is null or waiting_since>resolved_at)), acceptance as (
    select extract(epoch from(o.claimed_at-o.opened_at))/60 minutes from public.opportunities o
      where o.tenant_id=p_tenant_id and o.kind='TRIAL' and o.opened_at>=since_at and o.claimed_at>=o.opened_at and not coalesce(o.is_test_fixture,false)
      and exists(select 1 from public.crm_leads l where l.tenant_id=o.tenant_id and l.ai_handled=true
        and (l.opportunity_id=o.id or regexp_replace(l.phone,'[^0-9]','','g')=regexp_replace(o.student_phone,'[^0-9]','','g')))
    union all
    select extract(epoch from(r.responded_at-r.created_at))/60 from public.trial_reschedule_requests r
      where r.tenant_id=p_tenant_id and r.created_at>=since_at and r.status='ACCEPTED' and r.responded_at>=r.created_at
      and exists(select 1 from public.crm_leads l where l.id=r.lead_id and l.tenant_id=r.tenant_id and l.ai_handled=true)
  )
  select jsonb_build_object('generated_at',now(),'viewer_id',auth.uid(),'days',p_days,'metrics',jsonb_build_object(
    'leads', (select count(*) from cohort),
    'trials', (select count(*) from cohort c where exists(select 1 from public.opportunities o where o.id=c.opportunity_id and o.tenant_id=c.tenant_id and o.kind='TRIAL' and o.trial_appointment_id is not null)),
    'enrollments',(select count(*) from cohort where status='WON'),
    'unanswered',(select count(*) from actionable where reason='unanswered'),
    'attention',(select count(*) from actionable),
    'sent',(select count(*) from messages),
    'suspected_duplicates',(select count(*) from messages where previous_at>created_at-interval '5 minutes'
      and length(regexp_replace(content,'[^[:alnum:]]','','g'))>0
      and lower(regexp_replace(content,'[^[:alnum:]]','','g'))=lower(regexp_replace(previous_content,'[^[:alnum:]]','','g'))),
    'acceptance_minutes',(select round(avg(minutes)::numeric,1) from acceptance),
    'acceptance_samples',(select count(*) from acceptance),
    'delivery_failures',(select count(*) from public.ai_wa_messages m where m.tenant_id=p_tenant_id and m.agent='sdr'
      and m.direction='out' and m.created_at>=since_at and (m.meta->>'entregue'='false' or m.meta->>'delivery_outcome' in ('rejected','ambiguous')))
  ),'attention',coalesce((select jsonb_agg(to_jsonb(q) order by q.priority,q.waiting_since) from
      (select * from actionable order by priority,waiting_since limit 100) q),'[]'::jsonb)) into result;
  return result;
end;
$$;


--
-- Name: send_kids_weekly_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_kids_weekly_report() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  r          record;
  v_count    int := 0;
  v_done     int;
  v_xp_week  int;
  v_msg      text;
  v_week     date := date_trunc('week', now())::date;
begin
  for r in
    select p.id, p.full_name, p.guardian_name, p.guardian_phone, p.tenant_id, p.streak_count
    from profiles p
    where p.role = 'STUDENT'
      and coalesce(p.is_kids, false) = true
      and p.guardian_phone is not null
  loop
    -- atividades concluídas nos últimos 7 dias
    select count(*) into v_done
    from student_activity_progress
    where student_id = r.id and status = 'COMPLETED'
      and completed_at >= now() - interval '7 days';

    -- XP estimado da semana (soma do xp_reward * score/100 das atividades concluídas)
    select coalesce(sum(round(a.xp_reward * (sap.score::numeric/100))), 0) into v_xp_week
    from student_activity_progress sap
    join unit_activities a on a.id = sap.activity_id
    where sap.student_id = r.id and sap.status='COMPLETED'
      and sap.completed_at >= now() - interval '7 days';

    -- só envia se houve atividade na semana
    if v_done = 0 then continue; end if;

    v_msg := 'Olá, ' || coalesce(split_part(r.guardian_name,' ',1), 'responsável') ||
      '! 🐺📚 Resumo semanal de ' || coalesce(split_part(r.full_name,' ',1),'seu filho(a)') ||
      ' no Wise Wolf:' || chr(10) ||
      '✅ ' || v_done || ' lições concluídas' || chr(10) ||
      '⭐ ' || v_xp_week || ' XP conquistados' || chr(10) ||
      '🔥 ' || coalesce(r.streak_count,0) || ' dias de ofensiva' || chr(10) ||
      'Continue incentivando! 💜';

    begin
      insert into notification_queue
        (tenant_id, student_id, student_name, student_phone, message_body,
         scheduled_for, status, source_id, source_type, class_date, notification_kind)
      values
        (r.tenant_id, r.id, r.guardian_name, r.guardian_phone, v_msg,
         now(), 'pending', r.id, 'KIDS_WEEKLY', v_week, 'KIDS_WEEKLY_REPORT');
      v_count := v_count + 1;
    exception when unique_violation then null; -- já enviado nesta semana
    end;
  end loop;
  return v_count;
end;
$$;


--
-- Name: set_ai_handoff(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ai_handoff(p_kind text, p_id uuid, p_handoff boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role text;
  v_tenant text;
  v_row_tenant text;
begin
  select role, tenant_id into v_role, v_tenant from profiles where id = auth.uid();
  if v_role is null or v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') then
    return jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  if p_kind = 'lead' then
    select tenant_id into v_row_tenant from crm_leads where id = p_id;
    if v_row_tenant is null then return jsonb_build_object('ok', false, 'error', 'nao_encontrado'); end if;
    if v_row_tenant <> v_tenant and v_role <> 'SUPER_ADMIN' then
      return jsonb_build_object('ok', false, 'error', 'outro_tenant');
    end if;
    update crm_leads
       set ai_handoff = coalesce(p_handoff, false),
           ai_handoff_at = case when coalesce(p_handoff, false) then now() else null end
     where id = p_id;

  elsif p_kind = 'candidato' then
    select tenant_id into v_row_tenant from job_applications where id = p_id;
    if v_row_tenant is null then return jsonb_build_object('ok', false, 'error', 'nao_encontrado'); end if;
    if v_row_tenant <> v_tenant and v_role <> 'SUPER_ADMIN' then
      return jsonb_build_object('ok', false, 'error', 'outro_tenant');
    end if;
    update job_applications
       set ai_handoff = coalesce(p_handoff, false),
           ai_handoff_at = case when coalesce(p_handoff, false) then now() else null end
     where id = p_id;

  else
    return jsonb_build_object('ok', false, 'error', 'kind_invalido');
  end if;

  return jsonb_build_object('ok', true, 'handoff', coalesce(p_handoff, false));
end;
$$;


--
-- Name: set_ai_team_config(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ai_team_config(p_config jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  actor public.profiles%rowtype;
begin
  select * into actor
    from public.profiles
   where id = (select auth.uid());

  if actor.id is null
     or actor.tenant_id is null
     or actor.role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    return jsonb_build_object('ok', false, 'error', 'SEM_PERMISSAO');
  end if;
  if p_config is null
     or jsonb_typeof(p_config) <> 'object'
     or pg_column_size(p_config) > 30000 then
    return jsonb_build_object('ok', false, 'error', 'CONFIG_INVALIDA');
  end if;

  update public.tenants
     set ai_team_config = p_config
   where id = actor.tenant_id;

  return jsonb_build_object('ok', found);
end;
$$;


--
-- Name: set_class_log_rate(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_class_log_rate(p_log_id uuid, p_rate numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_caller_role text; v_caller_tenant text; v_log class_logs%ROWTYPE;
  v_month text; v_paid int; v_amount numeric; v_recalc boolean := false;
BEGIN
  SELECT role, tenant_id INTO v_caller_role, v_caller_tenant FROM profiles WHERE id = auth.uid();
  IF v_caller_role IS NULL OR v_caller_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RAISE EXCEPTION 'Apenas o diretor pode alterar o valor de uma aula';
  END IF;

  SELECT * INTO v_log FROM class_logs WHERE id = p_log_id;
  IF v_log.id IS NULL THEN RAISE EXCEPTION 'Aula não encontrada'; END IF;
  IF v_caller_role = 'SCHOOL_ADMIN' AND v_log.tenant_id IS DISTINCT FROM v_caller_tenant THEN
    RAISE EXCEPTION 'Sem permissão: aula de outra escola';
  END IF;
  IF p_rate IS NOT NULL AND (p_rate < 0 OR p_rate > 500) THEN
    RAISE EXCEPTION 'Valor fora do intervalo permitido (0 a 500)';
  END IF;

  UPDATE class_logs SET rate_override = p_rate WHERE id = p_log_id;

  -- Recalcula o fechamento PENDENTE do mês da aula (mesma fórmula do
  -- run_monthly_teacher_closing, agora com COALESCE do override).
  v_month := to_char(COALESCE(v_log.class_date, v_log.date), 'YYYY-MM');
  SELECT count(*), round(COALESCE(sum(COALESCE(cl.rate_override, teacher_student_rate(cl.teacher_id, cl.student_id, cl.class_date))),0), 2)
    INTO v_paid, v_amount
  FROM class_logs cl
  WHERE cl.teacher_id = v_log.teacher_id AND to_char(cl.class_date,'YYYY-MM') = v_month
    AND cl.presence NOT IN ('TEACHER_ABSENCE','Falta do Professor')
    AND cl.subtype IS DISTINCT FROM 'Teste Oral'
    AND COALESCE(cl.payment_hold,false) = false
    AND is_billable_student(cl.student_id);

  UPDATE teacher_closings SET
    total_lessons = v_paid,
    total_amount  = v_amount,
    updated_at    = now(),
    teacher_confirmation_status = CASE WHEN teacher_confirmation_status='OK' THEN 'PENDENTE' ELSE teacher_confirmation_status END,
    teacher_confirmation_date   = CASE WHEN teacher_confirmation_status='OK' THEN NULL ELSE teacher_confirmation_date END
  WHERE teacher_id = v_log.teacher_id AND month_year = v_month AND status = 'PENDENTE';
  v_recalc := FOUND;

  IF v_recalc THEN
    -- Valor mudou: libera o reaviso de fechamento (mesmo padrão do recalc diário)
    DELETE FROM automation_sent
     WHERE kind='MONTHLY_CLOSING' AND subject_id = v_log.teacher_id::text || ':' || v_month;
  END IF;

  RETURN jsonb_build_object('ok', true, 'log_id', p_log_id, 'rate_override', p_rate,
    'month', v_month, 'closing_recalculada', v_recalc);
END;
$$;


--
-- Name: set_class_log_rate_override(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_class_log_rate_override(p_log_id uuid, p_value numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_jwt_role text; v_caller_role text; v_caller_tenant text;
  v_log_tenant text; v_teacher uuid; v_month text;
BEGIN
  -- Autorização: só SCHOOL_ADMIN/COORDINATOR (no próprio tenant) ou SUPER_ADMIN.
  v_jwt_role := COALESCE(current_setting('request.jwt.claims', true)::json->>'role', '');
  IF v_jwt_role IN ('anon', 'authenticated') THEN
    SELECT role, tenant_id INTO v_caller_role, v_caller_tenant FROM profiles WHERE id = auth.uid();
    IF v_caller_role IS NULL OR v_caller_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
      RAISE EXCEPTION 'Apenas administradores podem alterar o valor de um lançamento';
    END IF;
  END IF;

  IF p_value IS NOT NULL AND p_value < 0 THEN
    RAISE EXCEPTION 'O valor não pode ser negativo';
  END IF;

  SELECT tenant_id, teacher_id, to_char(class_date,'YYYY-MM')
    INTO v_log_tenant, v_teacher, v_month
  FROM class_logs WHERE id = p_log_id;

  IF v_teacher IS NULL THEN
    RAISE EXCEPTION 'Lançamento não encontrado';
  END IF;

  -- Admin/coordenador só mexe no próprio tenant (super_admin passa livre).
  IF v_caller_role IN ('SCHOOL_ADMIN','COORDINATOR') AND v_caller_tenant IS DISTINCT FROM v_log_tenant THEN
    RAISE EXCEPTION 'Sem permissão para alterar lançamento de outro tenant';
  END IF;

  UPDATE class_logs SET rate_override = p_value WHERE id = p_log_id;

  -- Mantém o fechamento PENDENTE do mês em dia (congela PAGO/PAID_WAITING_NF).
  -- Mesma regra de cálculo do run_monthly_teacher_closing.
  UPDATE teacher_closings tc SET
    total_lessons = sub.paid,
    total_amount  = sub.amount,
    updated_at    = now(),
    teacher_confirmation_status = CASE WHEN tc.teacher_confirmation_status='OK' THEN 'PENDENTE' ELSE tc.teacher_confirmation_status END,
    teacher_confirmation_date   = CASE WHEN tc.teacher_confirmation_status='OK' THEN NULL ELSE tc.teacher_confirmation_date END
  FROM (
    SELECT count(*) AS paid,
      round(COALESCE(sum(COALESCE(cl.rate_override, teacher_student_rate(cl.teacher_id, cl.student_id, cl.class_date))),0), 2) AS amount
    FROM class_logs cl
    WHERE cl.teacher_id = v_teacher AND to_char(cl.class_date,'YYYY-MM') = v_month
      AND cl.presence NOT IN ('TEACHER_ABSENCE','Falta do Professor')
      AND cl.subtype IS DISTINCT FROM 'Teste Oral'
      AND COALESCE(cl.payment_hold,false) = false
      AND is_billable_student(cl.student_id)
  ) sub
  WHERE tc.teacher_id = v_teacher AND tc.month_year = v_month AND tc.status = 'PENDENTE';

  RETURN jsonb_build_object('ok', true, 'log_id', p_log_id, 'rate_override', p_value,
    'teacher_id', v_teacher, 'month', v_month);
END;
$$;


--
-- Name: set_closing_adjustment(uuid, text, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_closing_adjustment(p_teacher_id uuid, p_month text, p_description text, p_amount numeric, p_delete_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  v_actor_id uuid := auth.uid();
  v_is_service boolean := coalesce(auth.role(), '') = 'service_role';
  v_tenant text;
  v_old public.closing_adjustments%ROWTYPE;
  v_id uuid;
  v_refresh jsonb;
  v_sync boolean := false;
  v_closing_status text;
  v_expected_teacher uuid;
  v_expected_month text;
BEGIN
  IF p_delete_id IS NOT NULL THEN
    SELECT adjustment.*
      INTO v_old
      FROM public.closing_adjustments AS adjustment
     WHERE adjustment.id = p_delete_id;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', true, 'removido', p_delete_id);
    END IF;
    v_tenant := v_old.tenant_id;
    v_expected_teacher := v_old.teacher_id;
    v_expected_month := v_old.month_year;

    IF NOT v_is_service AND NOT (
      EXISTS (
        SELECT 1 FROM public.profiles AS actor
         WHERE actor.id = v_actor_id
           AND actor.role = 'SUPER_ADMIN'
           AND lower(coalesce(actor.lifecycle_status, 'active'))
                 NOT IN ('suspended', 'offboarded')
      ) OR EXISTS (
        SELECT 1
          FROM public.tenant_memberships AS membership
          JOIN public.profiles AS actor
            ON actor.id = membership.user_id
         WHERE membership.user_id = v_actor_id
           AND membership.tenant_id = v_tenant
           AND membership.status = 'ACTIVE'
           AND membership.role IN (
             'SCHOOL_ADMIN', 'COORDINATOR'
           )
           AND lower(coalesce(actor.lifecycle_status, 'active'))
                 NOT IN ('suspended', 'offboarded')
      )
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'sem_permissao';
    END IF;

    PERFORM private.lock_teacher_closing_pair(
      v_tenant,
      v_old.month_year,
      v_old.teacher_id,
      NULL
    );
    SELECT adjustment.*
      INTO v_old
      FROM public.closing_adjustments AS adjustment
     WHERE adjustment.id = p_delete_id
       AND adjustment.tenant_id = v_tenant
     FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('ok', true, 'removido', p_delete_id);
    END IF;
    IF v_old.teacher_id IS DISTINCT FROM v_expected_teacher
       OR v_old.month_year IS DISTINCT FROM v_expected_month THEN
      RAISE EXCEPTION USING
        ERRCODE = '40001', MESSAGE = 'closing_adjustment_changed';
    END IF;

    SELECT closing.status
      INTO v_closing_status
      FROM public.teacher_closings AS closing
     WHERE closing.tenant_id = v_tenant
       AND closing.teacher_id = v_old.teacher_id
       AND closing.month_year = v_old.month_year
     ORDER BY closing.created_at
     LIMIT 1
     FOR UPDATE;
    IF v_closing_status IS NOT NULL AND v_closing_status <> 'PENDENTE' THEN
      RETURN jsonb_build_object(
        'ok', false, 'error', 'fechamento_nao_pendente'
      );
    END IF;

    DELETE FROM public.closing_adjustments
     WHERE id = v_old.id
       AND tenant_id = v_tenant;
    v_refresh := private.refresh_teacher_closing_snapshot(
      v_tenant,
      v_old.teacher_id,
      v_old.month_year,
      false
    );
    v_sync := coalesce((v_refresh ->> 'synced')::boolean, false);
    RETURN jsonb_build_object(
      'ok', true,
      'removido', p_delete_id,
      'repasse_atualizado', v_sync
    );
  END IF;

  SELECT teacher.tenant_id
    INTO v_tenant
    FROM public.profiles AS teacher
   WHERE teacher.id = p_teacher_id
     AND teacher.role = 'TEACHER'
     AND teacher.tenant_id IS NOT NULL
     AND lower(coalesce(teacher.lifecycle_status, 'active'))
           NOT IN ('suspended', 'offboarded')
     AND EXISTS (
       SELECT 1
         FROM public.tenant_memberships AS membership
        WHERE membership.user_id = teacher.id
          AND membership.tenant_id = teacher.tenant_id
          AND membership.role = 'TEACHER'
          AND membership.status = 'ACTIVE'
     );
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'professor_nao_encontrado';
  END IF;

  IF NOT v_is_service AND NOT (
    EXISTS (
      SELECT 1 FROM public.profiles AS actor
       WHERE actor.id = v_actor_id
         AND actor.role = 'SUPER_ADMIN'
         AND lower(coalesce(actor.lifecycle_status, 'active'))
               NOT IN ('suspended', 'offboarded')
    ) OR EXISTS (
      SELECT 1
        FROM public.tenant_memberships AS membership
        JOIN public.profiles AS actor
          ON actor.id = membership.user_id
       WHERE membership.user_id = v_actor_id
         AND membership.tenant_id = v_tenant
         AND membership.status = 'ACTIVE'
         AND membership.role IN ('SCHOOL_ADMIN', 'COORDINATOR')
         AND lower(coalesce(actor.lifecycle_status, 'active'))
               NOT IN ('suspended', 'offboarded')
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'sem_permissao';
  END IF;
  IF p_month IS NULL OR p_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'mes_invalido';
  END IF;
  IF length(btrim(coalesce(p_description, ''))) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'motivo_invalido';
  END IF;
  IF p_amount IS NULL OR p_amount = 0 OR p_amount = 'NaN'::numeric THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'valor_invalido';
  END IF;

  PERFORM private.lock_teacher_closing_pair(
    v_tenant,
    p_month,
    p_teacher_id,
    NULL
  );
  SELECT closing.status
    INTO v_closing_status
    FROM public.teacher_closings AS closing
   WHERE closing.tenant_id = v_tenant
     AND closing.teacher_id = p_teacher_id
     AND closing.month_year = p_month
   ORDER BY closing.created_at
   LIMIT 1
   FOR UPDATE;
  IF v_closing_status IS NOT NULL AND v_closing_status <> 'PENDENTE' THEN
    RETURN jsonb_build_object(
      'ok', false, 'error', 'fechamento_nao_pendente'
    );
  END IF;

  INSERT INTO public.closing_adjustments (
    tenant_id, teacher_id, month_year, description, amount, created_by,
    closing_synced
  ) VALUES (
    v_tenant, p_teacher_id, p_month, btrim(p_description), p_amount,
    v_actor_id, false
  )
  RETURNING id INTO v_id;
  v_refresh := private.refresh_teacher_closing_snapshot(
    v_tenant,
    p_teacher_id,
    p_month,
    false
  );
  v_sync := coalesce((v_refresh ->> 'synced')::boolean, false);
  UPDATE public.closing_adjustments
     SET closing_synced = v_sync
   WHERE id = v_id;

  RETURN jsonb_build_object(
    'ok', true,
    'id', v_id,
    'valor', p_amount,
    'repasse_atualizado', v_sync,
    'aviso', CASE WHEN v_sync THEN NULL
      ELSE 'O ajuste foi registrado; o fechamento ainda não existe.' END
  );
END;
$_$;


--
-- Name: set_dre_category_account(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_dre_category_account(p_category text, p_account_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; v_allowed boolean;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;
  IF COALESCE(btrim(p_category),'') = '' THEN
    RETURN jsonb_build_object('error','categoria_obrigatoria');
  END IF;

  SELECT ledger_allowed INTO v_allowed
    FROM dre_accounts WHERE code = p_account_code AND is_active;
  IF v_allowed IS NULL THEN RETURN jsonb_build_object('error','conta_invalida'); END IF;
  -- Conta alimentada por competência não recebe lançamento do caixa. Deixar
  -- mapear aqui é abrir a porta da dupla contagem.
  IF NOT v_allowed THEN RETURN jsonb_build_object('error','conta_de_fonte_automatica'); END IF;

  INSERT INTO dre_category_map (tenant_id, category, account_code)
  VALUES (v_tenant, btrim(p_category), p_account_code)
  ON CONFLICT (tenant_id, category) DO UPDATE SET account_code = EXCLUDED.account_code;

  RETURN jsonb_build_object('ok', true, 'category', btrim(p_category), 'account_code', p_account_code);
END;
$$;


--
-- Name: set_material_collection(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_material_collection(p_material_id uuid, p_collection_id uuid, p_part_number integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  target_tenant_id text;
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  SELECT material.tenant_id
  INTO target_tenant_id
  FROM public.pedagogical_materials AS material
  WHERE material.id = p_material_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'material_nao_encontrado'
    );
  END IF;
  IF NOT private.legacy_role_rpc_target_allowed(target_tenant_id) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  RETURN public.set_material_collection_unchecked(
    p_material_id, p_collection_id, p_part_number
  );
END;
$$;


--
-- Name: set_material_collection_unchecked(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_material_collection_unchecked(p_material_id uuid, p_collection_id uuid, p_part_number integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; m_tenant text; c_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;
  SELECT tenant_id INTO m_tenant FROM pedagogical_materials WHERE id = p_material_id;
  IF m_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'material_nao_encontrado'); END IF;
  IF v_role = 'SCHOOL_ADMIN' AND m_tenant <> v_tenant THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;
  IF p_collection_id IS NOT NULL THEN
    SELECT tenant_id INTO c_tenant FROM pedagogical_collections WHERE id = p_collection_id;
    IF c_tenant IS NULL OR c_tenant <> m_tenant THEN
      RETURN jsonb_build_object('ok', false, 'error', 'colecao_invalida');
    END IF;
  END IF;
  UPDATE pedagogical_materials
    SET collection_id = p_collection_id, part_number = p_part_number
  WHERE id = p_material_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: set_payment_not_revenue(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_payment_not_revenue(p_payment_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; v_status text; v_n int;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;

  SELECT sp.status INTO v_status FROM student_payments sp
   WHERE sp.id = p_payment_id AND sp.tenant_id = v_tenant;
  IF v_status IS NULL THEN RETURN jsonb_build_object('error','pagamento_nao_encontrado'); END IF;
  IF v_status = 'NAO_RECEITA' THEN RETURN jsonb_build_object('error','ja_excluido'); END IF;

  UPDATE student_payments
     SET status = 'NAO_RECEITA',
         -- O status original vai no motivo: é o que permite desfazer.
         exclusion_reason = COALESCE(NULLIF(btrim(p_reason),''), 'Não é receita da escola')
                            || ' [status anterior: ' || v_status || ']',
         updated_at = now()
   WHERE id = p_payment_id AND tenant_id = v_tenant;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RETURN jsonb_build_object('error','pagamento_nao_encontrado'); END IF;

  -- O lançamento no caixa continua existindo (o dinheiro entrou de verdade),
  -- mas deixa de se chamar mensalidade. Só a etiqueta muda.
  UPDATE financial_transactions
     SET category = 'aporte_ou_movimentacao'
   WHERE student_payment_id = p_payment_id AND type = 'ENTRADA';

  RETURN jsonb_build_object('ok', true, 'status_anterior', v_status);
END;
$$;


--
-- Name: set_payment_split_owner_teacher(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_payment_split_owner_teacher(p_teacher uuid, p_pro_labore boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; v_t_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;

  -- O professor tem de ser da MESMA escola. Sem isso, um diretor marcaria
  -- professor de outra escola e mexeria na base do dízimo dela.
  SELECT tenant_id INTO v_t_tenant FROM profiles WHERE id = p_teacher AND role = 'TEACHER';
  IF v_t_tenant IS NULL THEN RETURN jsonb_build_object('error','professor_invalido'); END IF;
  IF v_role <> 'SUPER_ADMIN' AND v_t_tenant IS DISTINCT FROM v_tenant THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;

  IF COALESCE(p_pro_labore,false) THEN
    INSERT INTO payment_split_owner_teachers (tenant_id, teacher_id)
    VALUES (v_t_tenant, p_teacher) ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM payment_split_owner_teachers
     WHERE tenant_id = v_t_tenant AND teacher_id = p_teacher;
  END IF;

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: set_referral_reward_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_referral_reward_status(p_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role text;
  v_tenant text;
  v_afetadas int;
begin
  select role, tenant_id into v_role, v_tenant from profiles where id = auth.uid();
  if coalesce(v_role, '') not in ('SCHOOL_ADMIN','SUPER_ADMIN') then
    return jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;
  if p_status not in ('PENDING','PAID','CANCELLED','CREDITED') then
    return jsonb_build_object('ok', false, 'error', 'status_invalido');
  end if;

  update referral_rewards
     set status = p_status,
         paid_at = case when p_status = 'PAID'
                        then coalesce(paid_at, now()) else paid_at end
   where id = p_id
     and (v_role = 'SUPER_ADMIN' or tenant_id = v_tenant);

  get diagnostics v_afetadas = row_count;
  if v_afetadas = 0 then
    return jsonb_build_object('ok', false, 'error', 'nao_encontrado');
  end if;
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: set_student_academic_status(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_student_academic_status(p_student_id uuid, p_status text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor record;
  v_student record;
  v_clean_status text := pg_catalog.btrim(coalesce(p_status, ''));
  v_target_status text;
  v_target_lifecycle text;
begin
  if v_actor_id is null or p_student_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  -- Normaliza status aceitos
  if pg_catalog.lower(v_clean_status) in ('ativo', 'active') then
    v_target_status := 'Ativo';
    v_target_lifecycle := 'active';
  elsif pg_catalog.lower(v_clean_status) in ('inativo', 'inactive', 'pausado', 'suspended', 'pausa temporária') then
    v_target_status := 'Inativo';
    v_target_lifecycle := 'suspended';
  elsif pg_catalog.lower(v_clean_status) in ('trancado', 'locked') then
    v_target_status := 'Inativo';
    v_target_lifecycle := 'suspended';
  else
    raise exception using errcode = '22023', message = 'invalid_student_status';
  end if;

  select profile.role, profile.tenant_id
    into v_actor
    from public.profiles as profile
   where profile.id = v_actor_id;

  if not found or v_actor.role not in ('TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') then
    raise exception using errcode = '42501', message = 'staff_role_required';
  end if;

  select
    profile.id,
    profile.role,
    profile.tenant_id,
    profile.status,
    profile.lifecycle_status
    into v_student
    from public.profiles as profile
   where profile.id = p_student_id
   for update;

  if not found or v_student.role <> 'STUDENT' or v_student.tenant_id is null then
    raise exception using errcode = '42501', message = 'student_not_found';
  end if;

  if v_actor.role = 'SUPER_ADMIN' then
    null;
  elsif v_actor.tenant_id is null or v_actor.tenant_id <> v_student.tenant_id then
    raise exception using errcode = '42501', message = 'student_not_available';
  elsif v_actor.role = 'TEACHER' and not public._teacher_can_access_student(p_student_id, v_student.tenant_id) then
    raise exception using errcode = '42501', message = 'teacher_student_link_required';
  end if;

  -- Se for pausar/inativar, cancela bookings futuros agendados para liberar os horários
  if v_target_lifecycle = 'suspended' then
    update public.bookings
       set status = 'CANCELLED'
     where student_id = p_student_id
       and tenant_id = v_student.tenant_id
       and status in ('SCHEDULED', 'scheduled')
       and start_date >= CURRENT_DATE;
  end if;

  update public.profiles
     set status = v_target_status,
         lifecycle_status = v_target_lifecycle
   where id = p_student_id;

  return pg_catalog.jsonb_build_object(
    'studentId', p_student_id,
    'status', v_target_status,
    'lifecycleStatus', v_target_lifecycle,
    'updatedBy', v_actor_id,
    'actorRole', v_actor.role
  );
end;
$$;


--
-- Name: set_student_month_pay(uuid, uuid, text, numeric, integer, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_student_month_pay(p_teacher_id uuid, p_student_id uuid, p_month text, p_rate numeric DEFAULT NULL::numeric, p_duration_minutes integer DEFAULT NULL::integer, p_clear_rate boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_jwt_role text; v_caller_role text; v_caller_tenant text;
  v_teacher_tenant text; v_afetadas int := 0;
BEGIN
  v_jwt_role := COALESCE(current_setting('request.jwt.claims', true)::json->>'role', '');
  IF v_jwt_role IN ('anon', 'authenticated') THEN
    SELECT role, tenant_id INTO v_caller_role, v_caller_tenant FROM profiles WHERE id = auth.uid();
    IF v_caller_role IS NULL OR v_caller_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
      RAISE EXCEPTION 'Apenas a direção pode alterar valores de pagamento';
    END IF;
  END IF;

  SELECT tenant_id INTO v_teacher_tenant FROM profiles WHERE id = p_teacher_id;
  IF v_teacher_tenant IS NULL THEN RAISE EXCEPTION 'Professor não encontrado'; END IF;
  IF v_caller_role IN ('SCHOOL_ADMIN','COORDINATOR') AND v_caller_tenant IS DISTINCT FROM v_teacher_tenant THEN
    RAISE EXCEPTION 'Sem permissão para alterar pagamento de professor de outra escola';
  END IF;
  IF p_month !~ '^\d{4}-\d{2}$' THEN RAISE EXCEPTION 'Mês inválido (use YYYY-MM)'; END IF;
  IF p_rate IS NOT NULL AND p_rate < 0 THEN RAISE EXCEPTION 'O valor não pode ser negativo'; END IF;
  IF p_duration_minutes IS NOT NULL AND (p_duration_minutes <= 0 OR p_duration_minutes > 600) THEN
    RAISE EXCEPTION 'Duração inválida (informe entre 1 e 600 minutos)';
  END IF;

  IF p_clear_rate OR p_rate IS NOT NULL THEN
    UPDATE class_logs cl
       SET rate_override = CASE WHEN p_clear_rate THEN NULL ELSE p_rate END
     WHERE cl.teacher_id = p_teacher_id
       AND cl.student_id IS NOT DISTINCT FROM p_student_id
       AND to_char(cl.class_date,'YYYY-MM') = p_month
       AND EXISTS (SELECT 1 FROM v_payable_class_logs v WHERE v.id = cl.id);
    GET DIAGNOSTICS v_afetadas = ROW_COUNT;
  END IF;

  IF p_duration_minutes IS NOT NULL AND p_student_id IS NOT NULL THEN
    UPDATE profiles SET lesson_duration_minutes = p_duration_minutes WHERE id = p_student_id;
  END IF;

  UPDATE teacher_closings tc SET
    total_lessons = sub.paid, total_amount = sub.amount, updated_at = now(),
    teacher_confirmation_status = CASE WHEN tc.teacher_confirmation_status = 'OK' THEN 'PENDENTE' ELSE tc.teacher_confirmation_status END,
    teacher_confirmation_date   = CASE WHEN tc.teacher_confirmation_status = 'OK' THEN NULL ELSE tc.teacher_confirmation_date END
  FROM (
    SELECT count(*) AS paid, round(COALESCE(sum(v.rate_efetivo),0), 2) AS amount
    FROM v_payable_class_logs v
    WHERE v.teacher_id = p_teacher_id AND to_char(v.class_date,'YYYY-MM') = p_month
  ) sub
  WHERE tc.teacher_id = p_teacher_id AND tc.month_year = p_month AND tc.status = 'PENDENTE';

  RETURN jsonb_build_object('ok', true, 'aulas_ajustadas', v_afetadas,
    'teacher_id', p_teacher_id, 'student_id', p_student_id, 'month', p_month);
END;
$_$;


--
-- Name: FUNCTION set_student_month_pay(p_teacher_id uuid, p_student_id uuid, p_month text, p_rate numeric, p_duration_minutes integer, p_clear_rate boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_student_month_pay(p_teacher_id uuid, p_student_id uuid, p_month text, p_rate numeric, p_duration_minutes integer, p_clear_rate boolean) IS 'Diretor ajusta o valor base e/ou a duração da aula de UM aluno no mês inteiro. Substitui a edição aula-a-aula (set_class_log_rate_override), que continua existindo para casos pontuais.';


--
-- Name: set_student_payment_paid_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_student_payment_paid_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_cash_now boolean;
  v_cash_before boolean;
begin
  v_cash_now := new.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'NAO_RECEITA');
  v_cash_before := tg_op = 'UPDATE'
                   and old.status in ('RECEIVED', 'RECEIVED_IN_CASH', 'NAO_RECEITA');

  if new.status = 'CONFIRMED' then
    new.paid_at := null;
  elsif v_cash_now then
    if new.credited_at is not null then
      new.paid_at := new.credited_at;
    elsif new.paid_at is null
          or not v_cash_before
          or (
            tg_op = 'UPDATE'
            and (
              old.payment_date is distinct from new.payment_date
              or old.due_date is distinct from new.due_date
            )
          ) then
      new.paid_at := coalesce(
        new.payment_date + interval '12 hours',
        new.due_date + interval '12 hours',
        now()
      );
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION set_student_payment_paid_at(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_student_payment_paid_at() IS 'Preenche student_payments.paid_at a partir de payment_date (meio-dia, para não trocar de mês entre UTC e BRT). Existe para que a data do caixa não dependa de qual escritor gravou o pagamento.';


--
-- Name: set_student_pedagogical_evaluation_access(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_student_pedagogical_evaluation_access(p_student_id uuid, p_expected_book_part text, p_unlocked boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_expected text := pg_catalog.upper(
    pg_catalog.btrim(coalesce(p_expected_book_part, ''))
  );
  v_actor record;
  v_student record;
begin
  if v_actor_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if p_student_id is null or p_unlocked is null then
    raise exception using errcode = '22023', message = 'invalid_evaluation_access_request';
  end if;

  select profile.role, profile.tenant_id
    into v_actor
    from public.profiles as profile
   where profile.id = v_actor_id;
  if not found
     or v_actor.role not in (
       'TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR'
     )
     or (v_actor.role <> 'SUPER_ADMIN' and v_actor.tenant_id is null) then
    raise exception using errcode = '42501', message = 'authorized_staff_profile_required';
  end if;

  select
    profile.id,
    profile.tenant_id,
    profile.role,
    coalesce(profile.current_book_part, coalesce(profile.module, 'A1') || '-1')
      as current_book_part,
    profile.lifecycle_status,
    profile.status
    into v_student
    from public.profiles as profile
   where profile.id = p_student_id
   for update;
  if not found
     or v_student.role <> 'STUDENT'
     or v_student.tenant_id is null
     or pg_catalog.lower(pg_catalog.btrim(coalesce(
          v_student.lifecycle_status,
          'active'
        ))) <> 'active'
     or pg_catalog.lower(pg_catalog.btrim(coalesce(
          v_student.status,
          'Ativo'
        ))) in ('inativo', 'inactive', 'arquivado', 'cancelado', 'trancado') then
    raise exception using errcode = '42501', message = 'student_not_available';
  end if;

  if v_actor.role = 'SUPER_ADMIN' then
    null;
  elsif v_actor.tenant_id <> v_student.tenant_id then
    raise exception using errcode = '42501', message = 'student_not_available';
  elsif v_actor.role = 'TEACHER'
        and not public._teacher_can_access_student(
          p_student_id,
          v_student.tenant_id
        ) then
    raise exception using errcode = '42501', message = 'teacher_student_link_required';
  end if;

  if v_expected <> v_student.current_book_part then
    raise exception using errcode = '40001', message = 'stale_pedagogical_book_part';
  end if;
  if not exists (
    select 1
      from public.pedagogical_evaluation_catalog as catalog
     where catalog.book_part = v_expected
       and catalog.active is true
  ) then
    raise exception using errcode = '22023', message = 'evaluation_not_published';
  end if;

  update public.profiles
     set evaluation_unlocked = p_unlocked
   where id = p_student_id;

  insert into public.pedagogical_evaluation_access_audit (
    tenant_id,
    student_id,
    actor_id,
    book_part,
    unlocked
  ) values (
    v_student.tenant_id,
    p_student_id,
    v_actor_id,
    v_expected,
    p_unlocked
  );

  return pg_catalog.jsonb_build_object(
    'studentId', p_student_id,
    'bookPart', v_expected,
    'unlocked', p_unlocked
  );
end;
$$;


--
-- Name: set_student_pedagogical_placement(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_student_pedagogical_placement(p_student_id uuid, p_module text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_actor_id uuid := auth.uid();
  v_actor record;
  v_student record;
  v_module text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_module, '')));
  v_reason text := nullif(pg_catalog.btrim(coalesce(p_reason, '')), '');
  v_book_part text;
begin
  if v_actor_id is null or p_student_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if v_module not in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')
     or v_reason is null
     or pg_catalog.length(v_reason) not between 5 and 500 then
    raise exception using errcode = '22023', message = 'invalid_pedagogical_placement';
  end if;

  select profile.role, profile.tenant_id
    into v_actor
    from public.profiles as profile
   where profile.id = v_actor_id;
  if not found
     or v_actor.role not in (
       'TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR'
     ) then
    raise exception using errcode = '42501', message = 'staff_role_required';
  end if;

  select
    profile.id,
    profile.role,
    profile.tenant_id,
    profile.module,
    profile.current_book_part,
    profile.lifecycle_status,
    profile.status
    into v_student
    from public.profiles as profile
   where profile.id = p_student_id
   for update;
  if not found
     or v_student.role <> 'STUDENT'
     or v_student.tenant_id is null then
    raise exception using errcode = '42501', message = 'student_not_available';
  end if;

  if v_actor.role = 'SUPER_ADMIN' then
    null;
  elsif v_actor.tenant_id is null
        or v_actor.tenant_id <> v_student.tenant_id then
    raise exception using errcode = '42501', message = 'student_not_available';
  elsif v_actor.role = 'TEACHER'
        and not public._teacher_can_access_student(
          p_student_id,
          v_student.tenant_id
        ) then
    raise exception using errcode = '42501', message = 'teacher_student_link_required';
  end if;

  -- Reapplying the same placement is a true no-op: ordinary profile edits must
  -- never send a student from part 2 back to part 1 or clear an evaluation that
  -- was already released. Only a real module change starts its first published
  -- milestone. Advanced CEFR badges without a published milestone keep the
  -- existing COMPLETED convention instead of inventing `${module}-1`.
  if pg_catalog.upper(pg_catalog.btrim(coalesce(v_student.module, ''))) = v_module
     and nullif(
       pg_catalog.btrim(coalesce(v_student.current_book_part, '')),
       ''
     ) is not null then
    v_book_part := pg_catalog.btrim(v_student.current_book_part);
  else
    select catalog.book_part
      into v_book_part
      from public.pedagogical_evaluation_catalog as catalog
     where catalog.module = v_module
       and catalog.active is true
     order by catalog.part asc
     limit 1;
    if not found then
      v_book_part := 'COMPLETED';
    end if;
  end if;

  if pg_catalog.upper(pg_catalog.btrim(coalesce(v_student.module, ''))) = v_module
     and coalesce(v_student.current_book_part, '') = v_book_part then
    return pg_catalog.jsonb_build_object(
      'studentId', p_student_id,
      'module', v_module,
      'bookPart', v_book_part,
      'alreadyApplied', true
    );
  end if;

  update public.profiles
     set module = v_module,
         current_book_part = v_book_part,
         evaluation_unlocked = false,
         unlocked_tests = '{}'::text[]
   where id = p_student_id;

  insert into public.pedagogical_placement_audit (
    tenant_id,
    student_id,
    actor_id,
    previous_module,
    previous_book_part,
    new_module,
    new_book_part,
    reason
  ) values (
    v_student.tenant_id,
    p_student_id,
    v_actor_id,
    v_student.module,
    v_student.current_book_part,
    v_module,
    v_book_part,
    v_reason
  );

  return pg_catalog.jsonb_build_object(
    'studentId', p_student_id,
    'module', v_module,
    'bookPart', v_book_part,
    'alreadyApplied', false
  );
end;
$_$;


--
-- Name: set_student_plan_entitlement(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_student_plan_entitlement(p_plan_id uuid, p_feature_key text, p_limit_value integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_tenant_id text;
  v_role text;
  v_limit_value integer;
  v_access_mode text;
begin
  v_tenant_id := private.active_tenant_id(v_user_id);
  v_role := private.active_tenant_role(v_user_id);

  if v_user_id is null
     or v_tenant_id is null
     or v_role is null
     or v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN')
     or not exists (
       select 1
         from public.tenant_memberships as membership
        where membership.user_id = v_user_id
          and membership.tenant_id = v_tenant_id
          and membership.status = 'ACTIVE'
     ) then
    raise exception using errcode = '42501', message = 'sem_permissao';
  end if;
  if p_feature_key is distinct from 'wolfie.live_minutes' then
    raise exception using
      errcode = '22023',
      message = 'apenas_voz_ao_vivo_pode_ter_limite';
  end if;
  if p_limit_value is null or p_limit_value < 0 then
    raise exception using errcode = '22023', message = 'limite_invalido';
  end if;
  if p_plan_id is not null and not exists (
    select 1
      from public.student_pricing_plans as pricing_plan
     where pricing_plan.id = p_plan_id
       and pricing_plan.tenant_id = v_tenant_id
  ) then
    raise exception using errcode = '23503', message = 'plano_fora_do_tenant';
  end if;

  v_limit_value := p_limit_value;
  v_access_mode := case
    when v_limit_value = 0 then 'UNLIMITED'
    else 'LIMITED'
  end;

  if p_plan_id is null then
    insert into public.student_plan_entitlements as entitlement (
      tenant_id,
      plan_id,
      feature_key,
      limit_value,
      reset_period,
      access_mode
    ) values (
      v_tenant_id,
      null,
      p_feature_key,
      v_limit_value,
      'MONTH',
      v_access_mode
    )
    on conflict (tenant_id, feature_key) where plan_id is null do update
      set limit_value = excluded.limit_value,
          reset_period = excluded.reset_period,
          access_mode = excluded.access_mode;
  else
    insert into public.student_plan_entitlements as entitlement (
      tenant_id,
      plan_id,
      feature_key,
      limit_value,
      reset_period,
      access_mode
    ) values (
      v_tenant_id,
      p_plan_id,
      p_feature_key,
      v_limit_value,
      'MONTH',
      v_access_mode
    )
    on conflict on constraint student_plan_entitlements_unique do update
      set limit_value = excluded.limit_value,
          reset_period = excluded.reset_period,
          access_mode = excluded.access_mode;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'tenantId', v_tenant_id,
    'planId', p_plan_id,
    'featureKey', p_feature_key,
    'limit', v_limit_value,
    'accessMode', v_access_mode
  );
end;
$$;


--
-- Name: set_student_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_student_status(p_student_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  target_tenant_id text;
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  SELECT student.tenant_id
  INTO target_tenant_id
  FROM public.profiles AS student
  WHERE student.id = p_student_id
    AND student.role = 'STUDENT';
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'nao_encontrado'
    );
  END IF;
  IF NOT private.legacy_role_rpc_target_allowed(target_tenant_id) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  RETURN public.set_student_status_unchecked(p_student_id, p_status);
END;
$$;


--
-- Name: set_student_status_unchecked(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_student_status_unchecked(p_student_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; s_tenant text; v_new text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','COORDINATOR') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;

  v_new := CASE
    WHEN lower(trim(p_status)) IN ('ativo','active')   THEN 'Ativo'
    WHEN lower(trim(p_status)) IN ('inativo','inactive') THEN 'Inativo'
    ELSE NULL END;
  IF v_new IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'status_invalido'); END IF;

  SELECT tenant_id INTO s_tenant FROM profiles WHERE id = p_student_id AND role = 'STUDENT';
  IF s_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'nao_encontrado'); END IF;
  IF v_role IN ('SCHOOL_ADMIN','COORDINATOR') AND s_tenant <> v_tenant THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;

  UPDATE profiles SET status = v_new WHERE id = p_student_id;
  RETURN jsonb_build_object('ok', true, 'status', v_new);
END;
$$;


--
-- Name: set_teacher_oral_test_eligibility(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_teacher_oral_test_eligibility(p_teacher_id uuid, p_enabled boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_tenant_id text;
  v_target_tenant_id text;
begin
  if v_uid is null then
    raise exception
      using errcode = '28000', message = 'Authentication required';
  end if;

  select p.role, p.tenant_id
    into v_role, v_tenant_id
    from public.profiles as p
   where p.id = v_uid;

  if v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN') then
    raise exception
      using errcode = '42501', message = 'Administrator role required';
  end if;

  select p.tenant_id
    into v_target_tenant_id
    from public.profiles as p
   where p.id = p_teacher_id
     and p.role = 'TEACHER'
     and (
       v_role = 'SUPER_ADMIN'
       or p.tenant_id = v_tenant_id
     )
   for update;

  if not found then
    raise exception
      using errcode = '42501', message = 'Teacher is outside the allowed tenant';
  end if;

  update public.profiles as p
     set can_oral_test = p_enabled
   where p.id = p_teacher_id
     and p.tenant_id = v_target_tenant_id;

  return jsonb_build_object(
    'teacher_id', p_teacher_id,
    'enabled', p_enabled
  );
end;
$$;


--
-- Name: set_trial_booking_tenant(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_trial_booking_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE teacher_tenant text;
BEGIN
  SELECT profile.tenant_id INTO teacher_tenant
  FROM public.profiles AS profile
  WHERE profile.id = NEW.teacher_id;

  IF teacher_tenant IS NULL THEN
    RAISE EXCEPTION 'trial booking teacher has no tenant' USING ERRCODE = '23514';
  END IF;
  IF NEW.tenant_id IS NOT NULL AND NEW.tenant_id <> teacher_tenant THEN
    RAISE EXCEPTION 'trial booking tenant mismatch' USING ERRCODE = '42501';
  END IF;
  NEW.tenant_id := teacher_tenant;
  RETURN NEW;
END;
$$;


--
-- Name: set_vendor_commission_status(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_vendor_commission_status(p_commission_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role text;
  v_tenant text;
  v_afetadas int;
begin
  select role, tenant_id into v_role, v_tenant from profiles where id = auth.uid();
  if coalesce(v_role, '') not in ('SCHOOL_ADMIN','SUPER_ADMIN') then
    return jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;
  if p_status not in ('PENDING','CONFIRMED','PAID','CANCELLED') then
    return jsonb_build_object('ok', false, 'error', 'status_invalido');
  end if;

  update vendor_commissions
     set status = p_status,
         confirmed_at = case when p_status in ('CONFIRMED','PAID')
                             then coalesce(confirmed_at, now()) else confirmed_at end,
         paid_at = case when p_status = 'PAID'
                        then coalesce(paid_at, now()) else paid_at end
   where id = p_commission_id
     and (v_role = 'SUPER_ADMIN' or tenant_id = v_tenant);

  get diagnostics v_afetadas = row_count;
  if v_afetadas = 0 then
    -- Mesma resposta para "não existe" e "não é sua": responder coisas
    -- diferentes contaria a um diretor quais ids existem na outra escola.
    return jsonb_build_object('ok', false, 'error', 'nao_encontrado');
  end if;
  return jsonb_build_object('ok', true);
end;
$$;


--
-- Name: set_whatsapp_conversation_handoff(text, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_whatsapp_conversation_handoff(p_tenant_id text, p_conversation_id uuid, p_actor_id uuid, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_conversation public.whatsapp_conversations%rowtype;
begin
  if p_conversation_id is null
     or p_active is null
     or not private.whatsapp_inbox_actor_has_role(
       p_actor_id,
       p_tenant_id,
       array['SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR']::text[]
     ) then
    raise exception 'whatsapp_conversation_handoff_forbidden'
      using errcode = '42501';
  end if;

  update public.whatsapp_conversations as conversation
  set handoff_active = p_active,
      human_handoff_until = case
        when p_active then pg_catalog.now() + interval '72 hours'
        else null
      end,
      assigned_to = case when p_active then p_actor_id else null end
  where conversation.id = p_conversation_id
    and conversation.tenant_id = p_tenant_id
  returning conversation.* into v_conversation;

  if not found then
    raise exception 'whatsapp_conversation_not_found' using errcode = 'P0002';
  end if;

  perform private.apply_whatsapp_contact_handoff(
    p_tenant_id,
    v_conversation.phone,
    p_active
  );

  return jsonb_build_object(
    'ok', true,
    'conversationId', v_conversation.id,
    'handoffActive', v_conversation.handoff_active,
    'handoffUntil', v_conversation.human_handoff_until
  );
end;
$$;


--
-- Name: set_whatsapp_webhook_auth_version(text, text, smallint, uuid, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_whatsapp_webhook_auth_version(p_tenant_id text, p_instance_name text, p_version smallint, p_integration_id uuid, p_integration_version bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tenant_id text := nullif(pg_catalog.btrim(coalesce(p_tenant_id, '')), '');
  v_instance_name text := nullif(
    pg_catalog.btrim(coalesce(p_instance_name, '')),
    ''
  );
  v_instance public.whatsapp_instances%rowtype;
begin
  if v_tenant_id is null
     or v_instance_name is null
     or p_version not in (1, 2, 3)
     or p_integration_id is null
     or coalesce(p_integration_version, 0) <= 0 then
    raise exception 'invalid_whatsapp_webhook_auth_version'
      using errcode = '22023';
  end if;

  update public.whatsapp_instances as instance
  set webhook_auth_version = p_version,
      updated_at = now()
  where instance.tenant_id = v_tenant_id
    and lower(instance.instance_name) = lower(v_instance_name)
    and instance.integration_id = p_integration_id
    and instance.integration_version = p_integration_version
    and exists (
      select 1
      from private.tenant_integration_connections as connection
      where connection.id = p_integration_id
        and connection.tenant_id = v_tenant_id
        and connection.provider = 'evolution'
        and connection.version = p_integration_version
    )
  returning instance.* into v_instance;

  if not found then
    if exists (
      select 1
      from public.whatsapp_instances as instance
      where instance.tenant_id = v_tenant_id
        and lower(instance.instance_name) = lower(v_instance_name)
    ) then
      raise exception 'whatsapp_instance_integration_binding_stale'
        using errcode = '55000';
    end if;

    raise exception 'whatsapp_instance_not_found' using errcode = 'P0002';
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'tenantId', v_instance.tenant_id,
    'instanceName', v_instance.instance_name,
    'webhookAuthVersion', v_instance.webhook_auth_version,
    'integrationId', v_instance.integration_id,
    'integrationVersion', v_instance.integration_version
  );
end;
$$;


--
-- Name: set_wolfie_activity_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_wolfie_activity_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  new.updated_at = pg_catalog.now();
  return new;
end;
$$;


--
-- Name: settle_confirmed_class(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_confirmed_class(p_confirmation_id uuid, p_pay boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_role text;
  v_tenant text;
  c public.attendance_confirmations%rowtype;
  v_presence text;
  v_log_id uuid;
  v_existing_log_id uuid;
  v_occurrence_time time;
  v_constraint_name text;
begin
  if v_uid is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  select public._my_role(), public._my_tenant_id()
    into v_role, v_tenant;

  if not coalesce(v_role in ('SCHOOL_ADMIN', 'SUPER_ADMIN'), false)
     or (v_role <> 'SUPER_ADMIN' and v_tenant is null) then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'sem_permissao');
  end if;

  if p_pay is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'decisao_obrigatoria');
  end if;

  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = p_confirmation_id
     and (v_role = 'SUPER_ADMIN' or ac.tenant_id = v_tenant)
   for update;
  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'nao_encontrado');
  end if;

  if c.class_log_id is not null
     or c.status in ('CONFIRMED', 'RESOLVED_PAID', 'RESOLVED_UNPAID') then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'already', true,
      'status', c.status,
      'class_log_id', c.class_log_id
    );
  end if;

  if c.status is distinct from 'AWAITING_TEACHER' then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'status_invalido');
  end if;

  if c.tenant_id is null
     or c.teacher_id is null
     or c.student_id is null
     or c.class_date is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'confirmacao_incompleta');
  end if;

  if not coalesce(
    c.student_response in ('STUDENT_PRESENT', 'STUDENT_SELF_ABSENT'),
    false
  ) then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'resposta_do_aluno_nao_permite');
  end if;

  if not coalesce(c.source_type in ('booking', 'reschedule'), false)
     or nullif(pg_catalog.btrim(c.source_id), '') is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'origem_invalida');
  end if;

  if not (
    (
      c.source_type = 'booking'
      and exists (
        select 1
          from public.bookings b
         where b.id::text = c.source_id
           and b.tenant_id = c.tenant_id
           and b.student_id is not distinct from c.student_id
           and (
             b.teacher_id = c.teacher_id
             or exists (
               select 1
                 from public.class_coverages coverage
                where coverage.booking_id = b.id
                  and coverage.class_date = c.class_date
                  and coverage.status = 'confirmed'
                  and coverage.cover_teacher_id = c.teacher_id
             )
           )
      )
    )
    or (
      c.source_type = 'reschedule'
      and exists (
        select 1
          from public.reschedules r
         where r.id::text = c.source_id
           and r.tenant_id = c.tenant_id
           and r.teacher_id = c.teacher_id
           and r.student_id is not distinct from c.student_id
      )
    )
  ) then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'origem_invalida');
  end if;

  if exists (
    select 1
      from public.class_logs cl
     where cl.tenant_id = c.tenant_id
       and cl.class_date = c.class_date
       and (
         (c.source_type = 'booking' and cl.booking_id = c.source_id)
         or (c.source_type = 'reschedule' and cl.reschedule_id = c.source_id)
       )
  ) then
    perform public.reconcile_attendance_confirmation(c.id);
    return pg_catalog.jsonb_build_object('ok', true, 'already', true, 'error', 'ja_lancado');
  end if;

  v_occurrence_time := case
    when pg_catalog.btrim(c.class_time) ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
    then pg_catalog.left(pg_catalog.btrim(c.class_time), 5)::time
    else null
  end;

  if v_occurrence_time is null and c.source_type = 'booking' then
    select pg_catalog.left(pg_catalog.btrim(b.time_slot), 5)::time
      into v_occurrence_time
      from public.bookings b
     where b.id::text = c.source_id
       and b.tenant_id = c.tenant_id
       and b.student_id is not distinct from c.student_id
       and pg_catalog.btrim(b.time_slot) ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
     limit 1;
  end if;

  if v_occurrence_time is null and c.source_type = 'reschedule' then
    select pg_catalog.left(pg_catalog.btrim(r.time), 5)::time
      into v_occurrence_time
      from public.reschedules r
     where r.id::text = c.source_id
       and r.tenant_id = c.tenant_id
       and r.teacher_id = c.teacher_id
       and r.student_id is not distinct from c.student_id
       and pg_catalog.btrim(r.time) ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9])?$'
     limit 1;
  end if;

  if p_pay and v_occurrence_time is null then
    return pg_catalog.jsonb_build_object('ok', false, 'error', 'horario_da_ocorrencia_invalido');
  end if;

  if v_occurrence_time is not null and c.student_id is not null then
    select cl.id
      into v_existing_log_id
      from public.class_logs cl
     where cl.tenant_id = c.tenant_id
       and cl.teacher_id = c.teacher_id
       and cl.student_id = c.student_id
       and cl.class_date = c.class_date
       and cl.start_time = v_occurrence_time
     order by cl.created_at, cl.id
     limit 1;
  end if;

  if v_existing_log_id is not null then
    update public.attendance_confirmations
           set status = 'RESOLVED_UNPAID',
               admin_resolution = 'Ocorrência já lançada em outro agendamento; duplicata não paga',
           resolved_by = v_uid,
           resolved_at = pg_catalog.now()
     where id = c.id;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'already', true,
      'duplicate_occurrence', true,
      'existing_class_log_id', v_existing_log_id
    );
  end if;

  if not p_pay then
    update public.attendance_confirmations
       set status = 'RESOLVED_UNPAID',
           admin_resolution = 'Diretor decidiu não lançar/pagar esta aula',
           resolved_by = v_uid,
           resolved_at = pg_catalog.now()
     where id = c.id;
    return pg_catalog.jsonb_build_object('ok', true, 'paid', false);
  end if;

  v_presence := case
    when c.student_response = 'STUDENT_PRESENT' then 'COMPLETED'
    else 'STUDENT_ABSENCE'
  end;

  begin
    insert into public.class_logs (
      tenant_id,
      teacher_id,
      student_id,
      booking_id,
      reschedule_id,
      presence,
      date,
      class_date,
      start_time,
      observations,
      created_at
    ) values (
      c.tenant_id,
      c.teacher_id,
      c.student_id,
      case when c.source_type = 'booking' then c.source_id end,
      case when c.source_type = 'reschedule' then c.source_id end,
      v_presence,
      c.class_date,
      c.class_date,
      v_occurrence_time,
      'Regularizada pela direção a partir da confirmação do aluno',
      pg_catalog.now()
    )
    returning id into v_log_id;
  exception when unique_violation then
    get stacked diagnostics v_constraint_name = constraint_name;

    if not (
      v_constraint_name = any (array[
        'uq_class_logs_student_occurrence',
        'uq_class_logs_booking_date',
        'unique_class_log_per_booking_date',
        'uq_class_logs_reschedule_id',
        'unique_class_log_per_reschedule'
      ]::text[])
    ) then
      raise;
    end if;

    select cl.id
      into v_existing_log_id
      from public.class_logs cl
     where cl.tenant_id = c.tenant_id
       and cl.class_date = c.class_date
       and (
         (c.source_type = 'booking' and cl.booking_id = c.source_id)
         or (c.source_type = 'reschedule' and cl.reschedule_id = c.source_id)
         or (
           cl.teacher_id = c.teacher_id
           and cl.student_id = c.student_id
           and cl.start_time = v_occurrence_time
         )
       )
     order by cl.created_at, cl.id
     limit 1;

    if v_existing_log_id is null then
      raise;
    end if;

    update public.attendance_confirmations
       set status = 'RESOLVED_UNPAID',
           admin_resolution = 'Ocorrência já lançada simultaneamente; duplicata não paga',
           resolved_by = v_uid,
           resolved_at = pg_catalog.now()
     where id = c.id;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'already', true,
      'duplicate_occurrence', true,
      'existing_class_log_id', v_existing_log_id
    );
  end;

  update public.attendance_confirmations
     set status = 'RESOLVED_PAID',
         class_log_id = v_log_id,
         admin_resolution = 'Lançada pela direção a partir da confirmação do aluno',
         resolved_by = v_uid,
         resolved_at = pg_catalog.now()
   where id = c.id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'paid', true,
    'class_log_id', v_log_id,
    'presence', v_presence
  );
end;
$_$;


--
-- Name: settle_trial_session(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_trial_session(p_appointment_id uuid, p_attended boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  target_tenant_id text;
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  SELECT appointment.tenant_id
  INTO target_tenant_id
  FROM public.appointments AS appointment
  WHERE appointment.id = p_appointment_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'nao_encontrado'
    );
  END IF;
  IF NOT private.legacy_role_rpc_target_allowed(target_tenant_id) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  RETURN public.settle_trial_session_unchecked(
    p_appointment_id, p_attended
  );
END;
$$;


--
-- Name: settle_trial_session_unchecked(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_trial_session_unchecked(p_appointment_id uuid, p_attended boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; a_tenant text; a_type text; a_start timestamptz;
        v_teacher uuid; v_subtype text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;

  SELECT ap.tenant_id, ap.type, ap.start_time, COALESCE(ap.teacher_id, o.winner_teacher_id)
    INTO a_tenant, a_type, a_start, v_teacher
    FROM appointments ap
    LEFT JOIN opportunities o ON o.trial_appointment_id = ap.id
    WHERE ap.id = p_appointment_id;

  IF a_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'nao_encontrado'); END IF;
  IF v_role = 'SCHOOL_ADMIN' AND a_tenant <> v_tenant THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;
  IF EXISTS (SELECT 1 FROM class_logs cl WHERE cl.appointment_id = p_appointment_id::text) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ja_lancado');
  END IF;
  IF v_teacher IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'sem_professor'); END IF;

  v_subtype := CASE WHEN a_type = 'training' THEN 'TREINAMENTO' ELSE 'AULA EXPERIMENTAL' END;

  IF p_attended THEN
    INSERT INTO class_logs (tenant_id, teacher_id, appointment_id, presence, subtype, date, class_date, created_at)
    VALUES (a_tenant, v_teacher, p_appointment_id::text, 'COMPLETED', v_subtype,
            (a_start AT TIME ZONE 'America/Sao_Paulo')::date,
            (a_start AT TIME ZONE 'America/Sao_Paulo')::date, now());
    UPDATE appointments SET status = 'completed' WHERE id = p_appointment_id;
    RETURN jsonb_build_object('ok', true, 'paid', true);
  ELSE
    UPDATE appointments SET status = 'no_show' WHERE id = p_appointment_id;
    RETURN jsonb_build_object('ok', true, 'paid', false);
  END IF;
END;
$$;


--
-- Name: settle_wolfie_live_grant(text, uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_wolfie_live_grant(p_tenant_id text, p_student_id uuid, p_grant_id uuid, p_client_seconds integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_grant public.wolfie_live_grants%rowtype;
  v_consumed_seconds integer;
  v_plan_seconds integer;
  v_credit_seconds integer;
  v_close_at timestamptz;
  v_final_status text;
begin
  if p_tenant_id is null
     or p_student_id is null
     or p_grant_id is null then
    raise exception 'invalid_live_grant_settlement';
  end if;

  select *
    into v_grant
    from public.wolfie_live_grants
   where id = p_grant_id
     and student_id = p_student_id
     and tenant_id = p_tenant_id
   for update;
  if not found then
    raise exception using errcode = '42501', message = 'live_grant_not_owned';
  end if;

  if v_grant.status in ('SETTLED', 'EXPIRED') then
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'alreadySettled', true,
      'seconds', v_grant.consumed_seconds
    );
  end if;
  if v_grant.status = 'RESERVED' then
    update public.wolfie_live_grants
       set status = 'RELEASED',
           settled_at = pg_catalog.now(),
           updated_at = pg_catalog.now()
     where id = v_grant.id;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'releasedReservation', true,
      'seconds', 0
    );
  end if;
  if v_grant.status <> 'CLOSING'
     or v_grant.started_at is null
     or v_grant.close_requested_at is null then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'reason', 'grant_not_closing'
    );
  end if;

  -- Browser time is diagnostic only. Billing ends at the server-authored
  -- close timestamp (or the exact lease deadline for forced expiry).
  v_close_at := least(
    v_grant.close_requested_at,
    v_grant.lease_expires_at,
    pg_catalog.now()
  );
  v_consumed_seconds := case
    when v_grant.close_reason = 'LEASE_EXPIRED' then
      v_grant.reserved_seconds
    else least(
      v_grant.client_max_seconds,
      greatest(
        1,
        pg_catalog.ceil(
          extract(epoch from (v_close_at - v_grant.started_at))
        )::integer
      )
    )
  end;
  v_plan_seconds := least(
    v_consumed_seconds,
    v_grant.reserved_plan_seconds
  );
  v_credit_seconds := v_consumed_seconds - v_plan_seconds;

  insert into public.student_live_minutes (
    tenant_id,
    student_id,
    session_id,
    seconds,
    source,
    grant_id,
    plan_seconds,
    credit_seconds,
    created_at
  ) values (
    v_grant.tenant_id,
    v_grant.student_id,
    v_grant.session_id,
    v_consumed_seconds,
    'openai_realtime_grant',
    v_grant.id,
    v_plan_seconds,
    v_credit_seconds,
    v_grant.started_at
  )
  on conflict (grant_id) where grant_id is not null do nothing;

  v_final_status := case
    when v_grant.close_reason = 'LEASE_EXPIRED' then 'EXPIRED'
    else 'SETTLED'
  end;

  update public.wolfie_live_grants
     set status = v_final_status,
         consumed_seconds = v_consumed_seconds,
         client_reported_seconds = least(
           greatest(
             coalesce(p_client_seconds, client_reported_seconds, 0),
             0
           ),
           3600
         ),
         cleanup_lease_expires_at = null,
         settled_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where id = v_grant.id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'alreadySettled', false,
    'seconds', v_consumed_seconds
  );
end;
$$;


--
-- Name: sign_student_plan_change(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sign_student_plan_change(p_token text, p_typed_signature text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_change public.student_plan_changes%rowtype;
  v_name text;
  v_subscription text;
begin
  select * into v_change from public.student_plan_changes where token = p_token for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'Proposta não encontrada');
  end if;

  if v_change.status = 'SIGNED' then
    return jsonb_build_object('ok', true, 'already', true);
  end if;

  if v_change.status = 'CANCELLED' then
    return jsonb_build_object('ok', false, 'error', 'Esta proposta foi substituída por outra. Peça o link novo à escola.');
  end if;

  if v_change.expires_at < now() then
    return jsonb_build_object('ok', false, 'error', 'Esta proposta expirou. Peça um link novo à escola.');
  end if;

  select full_name, subscription_id into v_name, v_subscription
    from public.profiles where id = v_change.student_id;

  if public.normalize_signature_name(p_typed_signature) is distinct from public.normalize_signature_name(v_name)
     or btrim(coalesce(p_typed_signature, '')) = '' then
    return jsonb_build_object('ok', false, 'error', 'A assinatura precisa ser exatamente o nome completo do aluno.');
  end if;

  -- AQUI o plano passa a valer. Antes desta linha, a escola cobra o valor antigo.
  update public.profiles
     set monthly_fee = v_change.to_monthly_fee,
         class_frequency = v_change.to_frequency
   where id = v_change.student_id;

  update public.student_plan_changes
     set status = 'SIGNED',
         typed_signature = btrim(p_typed_signature),
         signature_ip = coalesce(
           nullif(btrim(split_part(current_setting('request.headers', true)::json ->> 'x-forwarded-for', ',', 1)), ''),
           'Via Web (Digital)'
         ),
         signed_at = now(),
         asaas_subscription_id = v_subscription,
         -- Sem assinatura recorrente não há nada a sincronizar: a escola cobra na
         -- mão e o status fica NOT_NEEDED em vez de PENDING para sempre.
         billing_sync_status = case
           when nullif(btrim(coalesce(v_subscription, '')), '') is null then 'NOT_NEEDED'
           else 'PENDING'
         end
   where id = v_change.id;

  return jsonb_build_object('ok', true, 'already', false);
end;
$$;


--
-- Name: spin_roulette(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.spin_roulette(p_spin_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE s public.roulette_spins; v_min int; v_max int; v_cents int;
BEGIN
  SELECT * INTO s FROM roulette_spins WHERE id = p_spin_id FOR UPDATE;
  IF s.id IS NULL THEN RETURN jsonb_build_object('ok',false,'error','not_found'); END IF;
  IF s.teacher_id <> auth.uid() THEN RETURN jsonb_build_object('ok',false,'error','forbidden'); END IF;
  IF s.status <> 'available' THEN RETURN jsonb_build_object('ok',false,'error','already_spun'); END IF;

  -- faixas de prêmio (centavos) por tier
  IF s.tier >= 200 THEN v_min := 1500; v_max := 3000;
  ELSIF s.tier >= 80 THEN v_min := 800; v_max := 2500;
  ELSE v_min := 500; v_max := 1500; END IF;

  v_cents := v_min + floor(random() * (v_max - v_min + 1))::int;
  UPDATE roulette_spins
     SET status='spun', prize_cents=v_cents,
         prize_label='Bônus R$ ' || to_char(v_cents/100.0,'FM999G990D00'),
         spun_at=now()
   WHERE id = s.id;
  RETURN jsonb_build_object('ok',true,'prize_cents',v_cents,'prize_label','Bônus R$ ' || to_char(v_cents/100.0,'FM999G990D00'));
END; $_$;


--
-- Name: stage_saas_owner_activation_payload(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stage_saas_owner_activation_payload(p_checkout_id uuid, p_claim_token uuid, p_owner_user_id uuid, p_provider_payload text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  attempt_row public.saas_owner_activation_attempts%rowtype;
  checkout_row public.saas_checkout_intents%rowtype;
  payload_json jsonb;
  payload_hash text;
  recipient text;
  identity_marker_text text;
  identity_marker_checkout_id uuid;
  tenant_ready boolean := false;
  owner_identity_ready boolean := false;
begin
  if p_checkout_id is null or p_claim_token is null
     or p_owner_user_id is null or p_provider_payload is null
     or length(p_provider_payload) not between 2 and 50000
  then
    raise exception using
      errcode = '22023', message = 'invalid_saas_owner_activation_payload';
  end if;
  begin
    payload_json := p_provider_payload::jsonb;
  exception when others then
    raise exception using
      errcode = '22023', message = 'invalid_saas_owner_activation_payload';
  end;
  if pg_catalog.jsonb_typeof(payload_json) <> 'object'
     or pg_catalog.jsonb_typeof(payload_json -> 'to') <> 'array'
     or pg_catalog.jsonb_array_length(payload_json -> 'to') <> 1
  then
    raise exception using
      errcode = '22023', message = 'invalid_saas_owner_activation_payload';
  end if;
  recipient := lower(nullif(pg_catalog.btrim(payload_json #>> '{to,0}'), ''));
  if recipient is null
     or length(coalesce(payload_json ->> 'html', '')) not between 1 and 40000
     or payload_json ->> 'subject' <> 'Ative seu acesso à Wise Wolf'
  then
    raise exception using
      errcode = '22023', message = 'invalid_saas_owner_activation_payload';
  end if;

  payload_hash := pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(p_provider_payload, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-activation:' || p_checkout_id::text,
      0
    )
  );

  select attempt.* into attempt_row
    from public.saas_owner_activation_attempts as attempt
   where attempt.checkout_id = p_checkout_id
   for update;
  if not found
     or attempt_row.status <> 'CLAIMED'
     or attempt_row.claim_token is distinct from p_claim_token
     or attempt_row.lease_expires_at <= pg_catalog.now()
     or attempt_row.submit_attempt_count <> 0
     or attempt_row.owner_email is distinct from recipient
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'activation_payload_claim_lost'
    );
  end if;

  select checkout.* into checkout_row
    from public.saas_checkout_intents as checkout
   where checkout.id = p_checkout_id
   for update;
  if found then
    perform 1
      from public.tenants as tenant
     where tenant.id = checkout_row.tenant_id
       and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) = 'active'
     for update;
    tenant_ready := found;
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'saas-owner-access-user:' || p_owner_user_id::text,
        0
      )
    );
    select pg_catalog.btrim(coalesce(
      auth_user.raw_app_meta_data
        ->> 'saas_owner_activation_checkout_id',
      ''
    ))
      into identity_marker_text
      from auth.users as auth_user
     where auth_user.id = p_owner_user_id
       and auth_user.deleted_at is null
       and auth_user.email_confirmed_at is not null
       and (
         auth_user.banned_until is null
         or auth_user.banned_until <= pg_catalog.now()
       )
       and lower(pg_catalog.btrim(coalesce(auth_user.email, '')))
         = attempt_row.owner_email
     for update of auth_user;
    owner_identity_ready := found;
    if owner_identity_ready then
      begin
        identity_marker_checkout_id := identity_marker_text::uuid;
      exception when invalid_text_representation then
        owner_identity_ready := false;
      end;
    end if;
    owner_identity_ready := owner_identity_ready and (
      identity_marker_checkout_id = p_checkout_id
      or private.saas_owner_identity_is_dormant_for_activation(
        p_checkout_id,
        p_owner_user_id,
        identity_marker_checkout_id,
        attempt_row.owner_email
      )
    );
  end if;

  if checkout_row.id is null
     or checkout_row.status not in (
       'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED'
     )
     or checkout_row.tenant_id is distinct from attempt_row.tenant_id
     or lower(pg_catalog.btrim(checkout_row.owner_email))
       is distinct from attempt_row.owner_email
     or not tenant_ready
  then
    update public.saas_owner_activation_attempts
       set status = 'SUPPRESSED',
           owner_user_id = p_owner_user_id,
           initial_owner_user_id = coalesce(
             initial_owner_user_id,
             p_owner_user_id
           ),
           owner_identity_marker_checkout_id = coalesce(
             owner_identity_marker_checkout_id,
             identity_marker_checkout_id
           ),
           provider_payload = null,
           provider_payload_sha256 = null,
           provider_payload_staged_at = null,
           lease_expires_at = pg_catalog.now(),
           completed_at = pg_catalog.now(),
           last_error = 'saas_owner_identity_not_ready_before_activation',
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id;
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'SUPPRESSED',
      'reason', 'saas_owner_identity_not_ready_before_activation'
    );
  end if;

  if not owner_identity_ready then
    update public.saas_owner_activation_attempts
       set lease_expires_at = pg_catalog.now(),
           last_error = 'saas_owner_identity_not_ready_before_activation',
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id
       and claim_token = p_claim_token
       and status = 'CLAIMED';
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_owner_identity_not_ready_before_activation'
    );
  end if;

  if attempt_row.provider_payload is not null then
    return pg_catalog.jsonb_build_object(
      'ok', attempt_row.provider_payload_sha256 = payload_hash
        and attempt_row.owner_user_id = p_owner_user_id
        and attempt_row.owner_identity_marker_checkout_id =
          identity_marker_checkout_id,
      'action', case
        when attempt_row.provider_payload_sha256 = payload_hash
          and attempt_row.owner_user_id = p_owner_user_id
          and attempt_row.owner_identity_marker_checkout_id =
            identity_marker_checkout_id
          then 'STAGED'
        else 'REVIEW_REQUIRED'
      end,
      'reason', case
        when attempt_row.provider_payload_sha256 = payload_hash
          and attempt_row.owner_user_id = p_owner_user_id
          and attempt_row.owner_identity_marker_checkout_id =
            identity_marker_checkout_id then null
        else 'activation_payload_is_immutable'
      end,
      'payload_sha256', attempt_row.provider_payload_sha256
    );
  end if;

  update public.saas_owner_activation_attempts
     set owner_user_id = p_owner_user_id,
         initial_owner_user_id = coalesce(
           initial_owner_user_id,
           p_owner_user_id
         ),
         owner_identity_marker_checkout_id = identity_marker_checkout_id,
         provider_payload = p_provider_payload,
         provider_payload_sha256 = payload_hash,
         provider_payload_staged_at = pg_catalog.now(),
         updated_at = pg_catalog.now()
   where checkout_id = p_checkout_id
     and claim_token = p_claim_token
     and status = 'CLAIMED'
     and lease_expires_at > pg_catalog.now()
     and submit_attempt_count = 0
     and owner_user_id is null
     and provider_payload is null;
  if not found then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'activation_claim_changed_before_payload_stage'
    );
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'STAGED',
    'payload_sha256', payload_hash
  );
end;
$$;


--
-- Name: store_whatsapp_provider_message(text, text, text, text, text, text, text, text, timestamp with time zone, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_whatsapp_provider_message(p_tenant_id text, p_instance_name text, p_remote_jid text, p_provider_message_id text, p_direction text, p_sender_kind text, p_message_type text, p_body text, p_occurred_at timestamp with time zone, p_display_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_instance_id uuid;
  v_instance_name text;
  v_remote_jid text := lower(pg_catalog.btrim(coalesce(p_remote_jid, '')));
  v_provider_message_id text := pg_catalog.btrim(
    coalesce(p_provider_message_id, '')
  );
  v_phone text := case
    when v_remote_jid like '%@g.us' then null
    else nullif(
      pg_catalog.regexp_replace(
        coalesce(
          nullif(p_phone, ''),
          pg_catalog.split_part(v_remote_jid, '@', 1)
        ),
        '[^0-9]',
        '',
        'g'
      ),
      ''
    )
  end;
  v_status text := coalesce(
    nullif(pg_catalog.btrim(p_status), ''),
    case when p_direction = 'in' then 'received' else 'sent' end
  );
  v_body text := coalesce(p_body, '');
  v_occurred_at timestamptz := coalesce(p_occurred_at, pg_catalog.now());
  v_conversation public.whatsapp_conversations%rowtype;
  v_message public.whatsapp_messages%rowtype;
  v_candidate_ids uuid[] := '{}'::uuid[];
  v_duplicate boolean := false;
  v_new_message boolean := false;
  v_status_only boolean;
  v_preview text;
  v_webhook_event_id uuid;
  v_contact_kind text := case
    when v_remote_jid like '%@g.us' then 'group' else 'unknown'
  end;
  v_contact_name text;
  v_display_name text;
begin
  if nullif(pg_catalog.btrim(p_tenant_id), '') is null
     or nullif(pg_catalog.btrim(p_instance_name), '') is null
     or v_remote_jid = ''
     or position('@' in v_remote_jid) <= 1
     or v_provider_message_id = ''
     or p_direction not in ('in', 'out')
     or p_sender_kind not in (
       'contact', 'human', 'ai', 'automation', 'system'
     )
     or p_message_type not in (
       'text', 'audio', 'image', 'video', 'document', 'sticker',
       'location', 'contact', 'reaction', 'poll', 'system', 'unknown'
     )
     or v_status not in (
       'received', 'queued', 'sent', 'delivered',
       'read', 'failed', 'uncertain'
     )
     or char_length(v_body) > 16384
     or p_metadata is null
     or jsonb_typeof(p_metadata) <> 'object'
     or pg_column_size(p_metadata) > 32768
     or (v_phone is not null and v_phone !~ '^[0-9]{10,15}$')
     or v_occurred_at < timestamptz '2000-01-01 00:00:00+00'
     or v_occurred_at > pg_catalog.now() + interval '1 day' then
    raise exception 'invalid_whatsapp_provider_message'
      using errcode = '22023';
  end if;

  select instance.id, instance.instance_name
  into v_instance_id, v_instance_name
  from public.whatsapp_instances as instance
  where instance.tenant_id = p_tenant_id
    and lower(instance.instance_name) = lower(pg_catalog.btrim(p_instance_name))
    and private.whatsapp_inbox_instance_is_eligible(
      instance.tenant_id,
      instance.id
    );

  if not found then
    raise exception 'whatsapp_inbox_unavailable' using errcode = '42501';
  end if;

  if not private.whatsapp_inbox_remote_jid_is_allowed(
    p_tenant_id,
    v_remote_jid
  ) then
    raise exception 'whatsapp_remote_jid_not_allowed'
      using errcode = '42501';
  end if;

  if v_contact_kind <> 'group' and v_phone is not null then
    select resolved.contact_kind, resolved.display_name
    into v_contact_kind, v_contact_name
    from private.resolve_whatsapp_contact(p_tenant_id, v_phone) as resolved;
  end if;
  v_display_name := nullif(
    left(
      pg_catalog.btrim(
        pg_catalog.regexp_replace(
          coalesce(v_contact_name, p_display_name, ''),
          '[[:cntrl:]]',
          ' ',
          'g'
        )
      ),
      160
    ),
    ''
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'wa-provider:' || v_instance_id::text || ':' || v_provider_message_id,
      0
    )
  );

  insert into public.whatsapp_conversations (
    tenant_id,
    instance_id,
    instance_name,
    remote_jid,
    contact_kind,
    display_name,
    phone
  )
  values (
    p_tenant_id,
    v_instance_id,
    v_instance_name,
    v_remote_jid,
    v_contact_kind,
    v_display_name,
    v_phone
  )
  on conflict (instance_id, remote_jid) do update
  set contact_kind = case
        when excluded.contact_kind <> 'unknown' then excluded.contact_kind
        else whatsapp_conversations.contact_kind
      end,
      display_name = coalesce(
        excluded.display_name,
        whatsapp_conversations.display_name
      ),
      phone = coalesce(excluded.phone, whatsapp_conversations.phone)
  returning * into v_conversation;

  select message.*
  into v_message
  from public.whatsapp_messages as message
  where message.instance_id = v_instance_id
    and message.provider_message_id = v_provider_message_id
  for update;

  if not found and p_direction = 'out' then
    -- O eco fromMe pode chegar antes da resposta HTTP do envio. Só vinculamos
    -- por corpo/tempo quando existe um único candidato; dois textos iguais
    -- ficam separados para nunca fundir mensagens por adivinhação.
    select coalesce(pg_catalog.array_agg(candidate.id), '{}'::uuid[])
    into v_candidate_ids
    from (
      select candidate_message.id
      from public.whatsapp_messages as candidate_message
      where candidate_message.tenant_id = p_tenant_id
        and candidate_message.instance_id = v_instance_id
        and candidate_message.conversation_id = v_conversation.id
        and candidate_message.direction = 'out'
        and candidate_message.provider_message_id is null
        and candidate_message.status in (
          'queued', 'dispatching', 'uncertain'
        )
        and candidate_message.body = v_body
        and candidate_message.created_at >= pg_catalog.now() - interval '10 minutes'
      order by candidate_message.created_at desc, candidate_message.id desc
      limit 2
      for update
    ) as candidate;

    if pg_catalog.cardinality(v_candidate_ids) = 1 then
      select message.*
      into v_message
      from public.whatsapp_messages as message
      where message.id = v_candidate_ids[1]
      for update;
    end if;
  end if;

  v_status_only := p_message_type = 'unknown'
    or pg_catalog.btrim(v_body) = ''
    or pg_catalog.btrim(v_body) = '[Mensagem não suportada]';

  if v_message.id is null then
    insert into public.whatsapp_messages (
      tenant_id,
      instance_id,
      conversation_id,
      provider_message_id,
      direction,
      sender_kind,
      message_type,
      body,
      status,
      occurred_at,
      metadata,
      sent_at,
      delivered_at,
      read_at
    )
    values (
      p_tenant_id,
      v_instance_id,
      v_conversation.id,
      v_provider_message_id,
      p_direction,
      p_sender_kind,
      p_message_type,
      v_body,
      v_status,
      v_occurred_at,
      p_metadata,
      case when v_status in ('sent', 'delivered', 'read')
        then v_occurred_at else null end,
      case when v_status in ('delivered', 'read')
        then v_occurred_at else null end,
      case when v_status = 'read' then v_occurred_at else null end
    )
    returning * into v_message;
    v_new_message := true;
  else
    v_duplicate := true;
    if v_message.tenant_id <> p_tenant_id
       or v_message.instance_id <> v_instance_id
       or v_message.conversation_id <> v_conversation.id
       or v_message.direction <> p_direction then
      raise exception 'whatsapp_provider_message_scope_conflict'
        using errcode = '23505';
    end if;

    update public.whatsapp_messages as message
    set provider_message_id = coalesce(
          message.provider_message_id,
          v_provider_message_id
        ),
        sender_kind = case
          when v_status_only then message.sender_kind
          else p_sender_kind
        end,
        message_type = case
          when v_status_only then message.message_type
          else p_message_type
        end,
        body = case
          when v_status_only then message.body
          else v_body
        end,
        status = private.merge_whatsapp_message_status(
          message.status,
          v_status
        ),
        occurred_at = least(
          message.occurred_at,
          v_occurred_at
        ),
        metadata = message.metadata || p_metadata,
        lease_until = case
          when private.merge_whatsapp_message_status(message.status, v_status)
            = 'dispatching'
          then message.lease_until
          else null
        end,
        error_code = case
          when v_status in ('sent', 'delivered', 'read', 'received') then null
          else message.error_code
        end,
        sent_at = case
          when v_status in ('sent', 'delivered', 'read')
          then coalesce(message.sent_at, v_occurred_at)
          else message.sent_at
        end,
        delivered_at = case
          when v_status in ('delivered', 'read')
          then coalesce(message.delivered_at, v_occurred_at)
          else message.delivered_at
        end,
        read_at = case
          when v_status = 'read'
          then coalesce(message.read_at, v_occurred_at)
          else message.read_at
        end
    where message.id = v_message.id
    returning message.* into v_message;
  end if;

  v_preview := left(
    case
      when nullif(pg_catalog.btrim(v_message.body), '') is not null
      then v_message.body
      else '[' || v_message.message_type || ']'
    end,
    500
  );

  update public.whatsapp_conversations as conversation
  set unread_count = conversation.unread_count + case
        when v_new_message
          and v_message.direction = 'in'
          and p_metadata ->> 'source' = 'webhook'
        then 1 else 0
      end,
      last_message_at = case
        when conversation.last_message_at is null
          or conversation.last_message_at <= v_message.occurred_at
        then v_message.occurred_at
        else conversation.last_message_at
      end,
      last_message_preview = case
        when conversation.last_message_at is null
          or conversation.last_message_at <= v_message.occurred_at
        then v_preview
        else conversation.last_message_preview
      end,
      last_message_direction = case
        when conversation.last_message_at is null
          or conversation.last_message_at <= v_message.occurred_at
        then v_message.direction
        else conversation.last_message_direction
      end
  where conversation.id = v_conversation.id
    and conversation.tenant_id = p_tenant_id
  returning conversation.* into v_conversation;

  if coalesce(p_metadata ->> 'webhookEventId', '') ~*
    '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
  then
    v_webhook_event_id := (p_metadata ->> 'webhookEventId')::uuid;
    update public.whatsapp_webhook_inbox as event
    set status = 'processed',
        processed_at = coalesce(event.processed_at, pg_catalog.now()),
        lease_until = null,
        last_error = null
    where event.id = v_webhook_event_id
      and event.tenant_id = p_tenant_id
      and event.instance_id = v_instance_id;
  elsif nullif(p_metadata ->> 'eventKey', '') is not null then
    update public.whatsapp_webhook_inbox as event
    set status = 'processed',
        processed_at = coalesce(event.processed_at, pg_catalog.now()),
        lease_until = null,
        last_error = null
    where event.tenant_id = p_tenant_id
      and event.instance_id = v_instance_id
      and event.event_key = p_metadata ->> 'eventKey';
  end if;

  return jsonb_build_object(
    'ok', true,
    'duplicate', v_duplicate,
    'conversationId', v_conversation.id,
    'messageId', v_message.id,
    'status', v_message.status
  );
end;
$_$;


--
-- Name: store_whatsapp_provider_messages(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.store_whatsapp_provider_messages(p_tenant_id text, p_instance_name text, p_messages jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_item jsonb;
  v_result jsonb;
  v_stored integer := 0;
  v_inserted integer := 0;
  v_duplicates integer := 0;
begin
  if p_messages is null
     or jsonb_typeof(p_messages) <> 'array'
     or pg_catalog.octet_length(p_messages::text) > 524288 then
    raise exception 'invalid_whatsapp_provider_message_batch'
      using errcode = '22023';
  end if;

  if jsonb_array_length(p_messages) not between 1 and 200 then
    raise exception 'invalid_whatsapp_provider_message_batch_size'
      using errcode = '22023';
  end if;

  for v_item in
    select item.value
    from jsonb_array_elements(p_messages) as item(value)
  loop
    if jsonb_typeof(v_item) <> 'object'
       or nullif(v_item ->> 'remoteJid', '') is null
       or nullif(v_item ->> 'providerMessageId', '') is null
       or nullif(v_item ->> 'direction', '') is null
       or nullif(v_item ->> 'senderKind', '') is null
       or nullif(v_item ->> 'messageType', '') is null
       or nullif(v_item ->> 'occurredAt', '') is null
       or (
         v_item ? 'metadata'
         and jsonb_typeof(v_item -> 'metadata') <> 'object'
       ) then
      raise exception 'invalid_whatsapp_provider_message_batch_item'
        using errcode = '22023';
    end if;

    v_result := public.store_whatsapp_provider_message(
      p_tenant_id,
      p_instance_name,
      v_item ->> 'remoteJid',
      v_item ->> 'providerMessageId',
      v_item ->> 'direction',
      v_item ->> 'senderKind',
      v_item ->> 'messageType',
      coalesce(v_item ->> 'body', ''),
      (v_item ->> 'occurredAt')::timestamptz,
      v_item ->> 'displayName',
      v_item ->> 'phone',
      case
        when v_item ->> 'status' = 'unknown' then null
        else v_item ->> 'status'
      end,
      coalesce(v_item -> 'metadata', '{}'::jsonb)
        || '{"source":"sync"}'::jsonb
    );

    v_stored := v_stored + 1;
    if coalesce((v_result ->> 'duplicate')::boolean, false) then
      v_duplicates := v_duplicates + 1;
    else
      v_inserted := v_inserted + 1;
    end if;
  end loop;

  return jsonb_build_object(
    'ok', true,
    'stored', v_inserted,
    'processed', v_stored,
    'inserted', v_inserted,
    'duplicates', v_duplicates
  );
end;
$$;


--
-- Name: student_lifecycle_operation_attention(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.student_lifecycle_operation_attention() RETURNS TABLE(operation_id uuid, tenant_id text, student_id uuid, source_lifecycle_status text, target_lifecycle_status text, operation_status text, provider_started_at timestamp with time zone, provider_completed_at timestamp with time zone, last_error text, updated_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    operation.id,
    operation.tenant_id,
    operation.student_id,
    operation.source_lifecycle_status,
    operation.target_lifecycle_status,
    operation.status,
    operation.provider_started_at,
    operation.provider_completed_at,
    operation.last_error,
    operation.updated_at
  from public.student_offboarding_operations as operation
  where coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
    and operation.status in ('UNKNOWN', 'BLOCKED')
  order by operation.updated_at, operation.id;
$$;


--
-- Name: submit_enrollment_signature(uuid, uuid, uuid, text, text, text, text, text, text, inet, text, jsonb, text, text, text, text, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_enrollment_signature(p_tenant_id uuid, p_prospect_id uuid, p_tentative_enrollment_id uuid, p_contract_text text, p_contract_hash text, p_signer_full_name text, p_signer_cpf text, p_signer_email text, p_signer_phone text, p_signer_ip inet, p_signer_user_agent text, p_signer_geo jsonb, p_otp_method text, p_otp_code text, p_acceptance_text text, p_visual_signature_data text, p_evidence_payload jsonb, p_evidence_hmac text, p_is_guardian_signature boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_otp_valid BOOLEAN := false;
    v_otp_token RECORD;
    v_signature_id UUID;
    v_cpf_hash TEXT;
    v_cpf_encrypted BYTEA;
BEGIN
    -- 1. Validate OTP
    SELECT * INTO v_otp_token
    FROM public.otp_tokens
    WHERE target_id = p_prospect_id
      AND target_type = 'PROSPECT_VERIFY'
      AND verified_at IS NOT NULL
    ORDER BY created_at DESC
    LIMIT 1;

    -- If no verified token found or it was verified more than 2 hours ago, reject
    IF v_otp_token IS NULL OR v_otp_token.verified_at < now() - INTERVAL '2 hours' THEN
        RETURN jsonb_build_object('success', false, 'error', 'OTP_NOT_VERIFIED_OR_EXPIRED');
    END IF;

    -- 2. Hash & Encrypt CPF
    v_cpf_hash := encode(digest(p_signer_cpf, 'sha256'), 'hex');
    -- A simple symmetric encryption for CPF (in a real scenario, use a specific KMS key)
    v_cpf_encrypted := pgp_sym_encrypt(p_signer_cpf, current_setting('app.settings.encryption_key', true));

    -- 3. Insert Signature
    INSERT INTO public.enrollment_signatures (
        tenant_id,
        prospect_id,
        tentative_enrollment_id,
        contract_text,
        contract_hash,
        signer_full_name,
        signer_cpf_hash,
        signer_cpf_encrypted,
        signer_email,
        signer_phone,
        signer_ip,
        signer_user_agent,
        signer_geo,
        otp_method,
        otp_verified_at,
        acceptance_text,
        visual_signature_data,
        evidence_payload,
        evidence_hmac,
        is_guardian_signature,
        status
    ) VALUES (
        p_tenant_id,
        p_prospect_id,
        p_tentative_enrollment_id,
        p_contract_text,
        p_contract_hash,
        p_signer_full_name,
        v_cpf_hash,
        v_cpf_encrypted,
        p_signer_email,
        p_signer_phone,
        p_signer_ip,
        p_signer_user_agent,
        p_signer_geo,
        p_otp_method,
        v_otp_token.verified_at,
        p_acceptance_text,
        p_visual_signature_data,
        p_evidence_payload,
        p_evidence_hmac,
        p_is_guardian_signature,
        'SIGNED'
    ) RETURNING id INTO v_signature_id;

    -- 4. Audit Log
    INSERT INTO public.signature_audit_log (signature_id, event, payload, ip_hash)
    VALUES (
        v_signature_id,
        'SIGNATURE_CONFIRMED',
        jsonb_build_object(
            'signer_ip', p_signer_ip,
            'user_agent', p_signer_user_agent,
            'geo', p_signer_geo
        ),
        encode(digest(p_signer_ip::text, 'sha256'), 'hex')
    );

    -- 5. Update Tentative Enrollment
    UPDATE public.tentative_enrollments
    SET status = 'SIGNED'
    WHERE id = p_tentative_enrollment_id;

    RETURN jsonb_build_object('success', true, 'signature_id', v_signature_id);
END;
$$;


--
-- Name: submit_student_vocab_review(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_student_vocab_review(p_review_id uuid, p_correct boolean, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.assert_active_student_learning_mutation();
  return public.submit_student_vocab_review_core(
    p_review_id,
    p_correct,
    p_request_key
  );
end;
$$;


--
-- Name: submit_student_vocab_review_core(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_student_vocab_review_core(p_review_id uuid, p_correct boolean, p_request_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student_id uuid := auth.uid();
  v_profile record;
  v_request_key text := pg_catalog.btrim(coalesce(p_request_key, ''));
  v_existing public.student_vocab_review_attempts%rowtype;
  v_review public.student_vocab_reviews%rowtype;
  v_interval integer;
  v_streak integer;
  v_result jsonb;
  v_now timestamptz := pg_catalog.now();
begin
  if v_student_id is null or p_review_id is null then
    raise exception using
      errcode = '42501',
      message = 'authentication_required';
  end if;

  if p_correct is null
     or pg_catalog.length(v_request_key) not between 8 and 180 then
    raise exception using
      errcode = '22023',
      message = 'invalid_vocab_review_submission';
  end if;

  select profile.tenant_id, profile.role
    into v_profile
    from public.profiles as profile
   where profile.id = v_student_id
   for update;

  if not found
     or v_profile.role <> 'STUDENT'
     or v_profile.tenant_id is null then
    raise exception using
      errcode = '42501',
      message = 'student_profile_required';
  end if;

  select *
    into v_existing
    from public.student_vocab_review_attempts as attempt
   where attempt.student_id = v_student_id
     and attempt.request_key = v_request_key
   for update;

  if found then
    if v_existing.review_id <> p_review_id
       or v_existing.correct is distinct from p_correct then
      raise exception using
        errcode = '22023',
        message = 'idempotency_key_reused';
    end if;

    return v_existing.result || pg_catalog.jsonb_build_object(
      'alreadyApplied', true
    );
  end if;

  select *
    into v_review
    from public.student_vocab_reviews as review
   where review.id = p_review_id
     and review.student_id = v_student_id
     and review.tenant_id = v_profile.tenant_id
   for update;

  if not found then
    raise exception using
      errcode = '42501',
      message = 'vocab_review_not_owned';
  end if;

  v_interval := case
    when p_correct is false then 1
    when v_review.interval_days >= 60 then 120
    when v_review.interval_days >= 30 then 60
    when v_review.interval_days >= 14 then 30
    when v_review.interval_days >= 7 then 14
    when v_review.interval_days >= 3 then 7
    when v_review.interval_days >= 1 then 3
    else 1
  end;

  update public.student_vocab_reviews
     set interval_days = v_interval,
         consecutive_correct = case
           when p_correct then v_review.consecutive_correct + 1
           else 0
         end,
         total_reviews = v_review.total_reviews + 1,
         next_review_at = v_now + pg_catalog.make_interval(days => v_interval),
         last_reviewed_at = v_now,
         updated_at = v_now
   where id = p_review_id
  returning * into v_review;

  -- A submitted review is real practice, but it is not an objective skill
  -- assessment. Record attendance/streak once while leaving skill scores alone.
  v_streak := private.record_student_learning_practice(
    v_student_id,
    case when p_correct then 100 else 0 end,
    'vocab_review',
    array[]::text[],
    v_now
  );

  v_result := pg_catalog.jsonb_build_object(
    'reviewId', v_review.id,
    'correct', p_correct,
    'intervalDays', v_review.interval_days,
    'consecutiveCorrect', v_review.consecutive_correct,
    'totalReviews', v_review.total_reviews,
    'nextReviewAt', v_review.next_review_at,
    'streakCount', v_streak,
    'alreadyApplied', false
  );

  insert into public.student_vocab_review_attempts (
    tenant_id,
    student_id,
    review_id,
    request_key,
    correct,
    result,
    created_at
  ) values (
    v_profile.tenant_id,
    v_student_id,
    p_review_id,
    v_request_key,
    p_correct,
    v_result,
    v_now
  );

  return v_result;
end;
$$;


--
-- Name: FUNCTION submit_student_vocab_review_core(p_review_id uuid, p_correct boolean, p_request_key text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.submit_student_vocab_review_core(p_review_id uuid, p_correct boolean, p_request_key text) IS 'Applies one idempotent server-side SRS transition and records zero-XP practice.';


