-- Name: suppress_exempt_monthly_payment_obligation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suppress_exempt_monthly_payment_obligation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1
      from public.student_billing_exemptions as exemption
     where exemption.tenant_id = new.tenant_id
       and exemption.student_id = new.student_id
       and exemption.period_start = new.period_start
  ) then
    return null;
  end if;
  return new;
end;
$$;


--
-- Name: suppress_saas_owner_activation(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suppress_saas_owner_activation(p_checkout_id uuid, p_claim_token uuid, p_owner_user_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  normalized_reason text := lower(
    pg_catalog.btrim(coalesce(p_reason, ''))
  );
  attempt_row public.saas_owner_activation_attempts%rowtype;
  checkout_row public.saas_checkout_intents%rowtype;
  tenant_ready boolean := false;
  owner_access_ready boolean := false;
  changed_checkout_id uuid;
begin
  if p_checkout_id is null or p_claim_token is null
     or p_owner_user_id is null
     or normalized_reason not in (
       'existing_owner_account', 'owner_activation_not_required'
     )
  then
    raise exception using
      errcode = '22023', message = 'invalid_saas_owner_activation_suppression';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'saas-owner-activation:' || p_checkout_id::text,
      0
    )
  );

  select attempt.* into attempt_row
    from public.saas_owner_activation_attempts as attempt
   where attempt.checkout_id = p_checkout_id
   for update;
  if not found
     or attempt_row.claim_token is distinct from p_claim_token
     or attempt_row.status <> 'CLAIMED'
     or attempt_row.submit_attempt_count <> 0
     or attempt_row.lease_expires_at <= pg_catalog.now()
     or not (
       (
         attempt_row.provider_payload is null
         and attempt_row.owner_user_id is null
       )
       or (
         attempt_row.provider_payload is not null
         and attempt_row.owner_user_id = p_owner_user_id
       )
     )
  then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'activation_claim_lost'
    );
  end if;

  select checkout.* into checkout_row
    from public.saas_checkout_intents as checkout
   where checkout.id = p_checkout_id
   for update;
  if found then
    perform 1
      from public.tenants as tenant
     where tenant.id = checkout_row.tenant_id
       and lower(pg_catalog.btrim(coalesce(tenant.saas_status, ''))) = 'active'
     for update;
    tenant_ready := found;
  end if;

  if checkout_row.id is null
     or checkout_row.status not in (
       'PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED'
     )
     or checkout_row.tenant_id is distinct from attempt_row.tenant_id
     or lower(pg_catalog.btrim(checkout_row.owner_email))
       is distinct from attempt_row.owner_email
     or not tenant_ready
  then
    update public.saas_owner_activation_attempts
       set status = 'SUPPRESSED',
           owner_user_id = p_owner_user_id,
           initial_owner_user_id = coalesce(
             initial_owner_user_id,
             p_owner_user_id
           ),
           provider_payload = null,
           provider_payload_sha256 = null,
           provider_payload_staged_at = null,
           lease_expires_at = pg_catalog.now(),
           completed_at = pg_catalog.now(),
           last_error = 'saas_owner_access_not_ready_before_activation',
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id;
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'action', 'SUPPRESSED',
      'status', 'SUPPRESSED',
      'reason', 'saas_owner_access_not_ready_before_activation'
    );
  end if;

  owner_access_ready := private.ensure_saas_owner_access_locked(
    p_checkout_id,
    attempt_row.tenant_id,
    attempt_row.owner_email,
    p_owner_user_id,
    false
  );
  if not owner_access_ready then
    update public.saas_owner_activation_attempts
       set lease_expires_at = pg_catalog.now(),
           last_error = 'saas_owner_identity_not_ready_before_suppression',
           updated_at = pg_catalog.now()
     where checkout_id = p_checkout_id
       and claim_token = p_claim_token
       and status = 'CLAIMED';
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'action', 'REVIEW_REQUIRED',
      'reason', 'saas_owner_identity_not_ready_before_suppression'
    );
  end if;

  update public.saas_checkout_intents
     set status = 'PROVISIONED',
         provisioned_at = coalesce(provisioned_at, pg_catalog.now()),
         last_error = null,
         updated_at = pg_catalog.now()
   where id = p_checkout_id
     and status in ('PROVISIONING', 'PROVISIONING_FAILED', 'PROVISIONED')
     and tenant_id = attempt_row.tenant_id
     and lower(pg_catalog.btrim(owner_email)) = attempt_row.owner_email;
  if not found then
    raise exception using
      errcode = 'P0001',
      message = 'saas_checkout_changed_before_activation_suppression';
  end if;

  update public.saas_owner_activation_attempts
     set status = 'SUPPRESSED',
         owner_user_id = p_owner_user_id,
         initial_owner_user_id = coalesce(
           initial_owner_user_id,
           p_owner_user_id
         ),
         provider_payload = null,
         provider_payload_sha256 = null,
         provider_payload_staged_at = null,
         lease_expires_at = pg_catalog.now(),
         completed_at = pg_catalog.now(),
         last_error = normalized_reason,
         updated_at = pg_catalog.now()
   where checkout_id = p_checkout_id
     and claim_token = p_claim_token
     and status = 'CLAIMED'
     and submit_attempt_count = 0
     and lease_expires_at > pg_catalog.now()
     and (
       (provider_payload is null and owner_user_id = p_owner_user_id)
       or (
         provider_payload is null and owner_user_id is null
       )
       or (
         provider_payload is not null and owner_user_id = p_owner_user_id
       )
     )
   returning checkout_id into changed_checkout_id;
  if changed_checkout_id is null then
    raise exception using
      errcode = 'P0001',
      message = 'saas_activation_claim_changed_during_suppression';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true,
    'action', 'SUPPRESSED',
    'status', 'SUPPRESSED',
    'reason', normalized_reason
  );
end;
$$;


--
-- Name: suspend_overdue_students(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suspend_overdue_students(p_grace_days integer DEFAULT 15) RETURNS TABLE(suspended_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_count INT := 0;
    v_student RECORD;
BEGIN
    FOR v_student IN
        SELECT DISTINCT p.id, p.tenant_id, MIN(sp.due_date) as first_overdue
        FROM profiles p
        JOIN student_payments sp ON sp.student_id = p.id
        WHERE p.role IN ('STUDENT','student')
          AND COALESCE(p.status_financial,'ACTIVE') NOT IN ('SUSPENDED','INACTIVE')
          AND sp.status IN ('PENDING','OVERDUE')
          AND sp.due_date < (now() - (p_grace_days || ' days')::INTERVAL)
        GROUP BY p.id, p.tenant_id
    LOOP
        UPDATE profiles SET
            status_financial = 'SUSPENDED',
            suspended_at = now(),
            suspended_reason = 'Inadimplência superior a ' || p_grace_days || ' dias',
            first_overdue_at = COALESCE(first_overdue_at, v_student.first_overdue::TIMESTAMPTZ)
        WHERE id = v_student.id;
        v_count := v_count + 1;
    END LOOP;

    -- Mover de OVERDUE → ACTIVE quando aluno regulariza
    UPDATE profiles SET
        status_financial = 'ACTIVE',
        suspended_at = NULL,
        suspended_reason = NULL
    WHERE role IN ('STUDENT','student')
      AND status_financial = 'SUSPENDED'
      AND NOT EXISTS (
          SELECT 1 FROM student_payments sp
          WHERE sp.student_id = profiles.id
            AND sp.status IN ('PENDING','OVERDUE')
            AND sp.due_date < (now() - INTERVAL '1 day')
      );

    RETURN QUERY SELECT v_count;
END;
$$;


--
-- Name: sweep_stale_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sweep_stale_outbox() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_stale_count INTEGER := 0;
    v_recovered_count INTEGER := 0;
BEGIN
    -- 1. Recover stuck PROCESSING messages (orphaned by crashed workers)
    WITH recovered AS (
        UPDATE public.outbox_messages
        SET status = 'RETRY',
            next_retry_at = now(),
            last_error = COALESCE(last_error, '') || ' | recovered from stuck PROCESSING at ' || now()
        WHERE status = 'PROCESSING'
          AND last_attempt_at < now() - INTERVAL '5 minutes'
        RETURNING id
    )
    SELECT COUNT(*) INTO v_recovered_count FROM recovered;

    -- 2. Move messages with too many attempts to DLQ
    WITH dlq AS (
        UPDATE public.outbox_messages
        SET status = 'DLQ',
            processed_at = now()
        WHERE status = 'RETRY'
          AND attempt_count >= max_attempts
        RETURNING id
    )
    SELECT COUNT(*) INTO v_stale_count FROM dlq;

    RETURN jsonb_build_object(
        'success', true,
        'recovered_from_stuck', v_recovered_count,
        'moved_to_dlq', v_stale_count,
        'ts', now()
    );
END;
$$;


--
-- Name: switch_my_tenant(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.switch_my_tenant(p_tenant_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  caller_id uuid := (SELECT auth.uid());
  selected_role text;
BEGIN
  IF caller_id IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501';
  END IF;

  SELECT membership.role
  INTO selected_role
  FROM public.tenant_memberships AS membership
  WHERE membership.user_id = caller_id
    AND membership.tenant_id = p_tenant_id
    AND membership.status = 'ACTIVE';

  IF selected_role IS NULL THEN
    RAISE EXCEPTION 'tenant_membership_required' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.tenant_user_contexts (user_id, tenant_id)
  VALUES (caller_id, p_tenant_id)
  ON CONFLICT (user_id) DO UPDATE
  SET tenant_id = EXCLUDED.tenant_id,
      updated_at = now();

  RETURN jsonb_build_object(
    'ok', true,
    'tenant_id', p_tenant_id,
    'role', selected_role
  );
END;
$$;


--
-- Name: sync_financial_transaction_amounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_financial_transaction_amounts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_amount_changed boolean;
  v_cents_changed boolean;
begin
  if tg_op = 'INSERT' then
    if new.amount is null and new.amount_cents is not null then
      new.amount := new.amount_cents / 100.0;
    elsif new.amount is not null and new.amount_cents is null then
      new.amount_cents := round(new.amount * 100)::integer;
    elsif new.amount is not null
          and new.amount_cents is not null
          and new.amount_cents <> round(new.amount * 100)::integer then
      raise exception using
        errcode = '23514',
        message = 'financial_transaction_amount_mismatch';
    end if;
  else
    v_amount_changed := new.amount is distinct from old.amount;
    v_cents_changed := new.amount_cents is distinct from old.amount_cents;

    if v_amount_changed and not v_cents_changed then
      new.amount_cents := case
        when new.amount is null then null
        else round(new.amount * 100)::integer
      end;
    elsif v_cents_changed and not v_amount_changed then
      new.amount := case
        when new.amount_cents is null then null
        else new.amount_cents / 100.0
      end;
    elsif v_amount_changed and v_cents_changed
          and (
            new.amount is null
            or new.amount_cents is null
            or new.amount_cents <> round(new.amount * 100)::integer
          ) then
      raise exception using
        errcode = '23514',
        message = 'financial_transaction_amount_mismatch';
    elsif new.amount is not null
          and new.amount_cents is not null
          and new.amount_cents <> round(new.amount * 100)::integer then
      raise exception using
        errcode = '23514',
        message = 'financial_transaction_amount_mismatch';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: FUNCTION sync_financial_transaction_amounts(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sync_financial_transaction_amounts() IS 'Mantém financial_transactions.amount e amount_cents em sincronia; roda BEFORE, então também salva quem insere só um dos dois lados.';


--
-- Name: sync_student_payment_amounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_student_payment_amounts() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_value_changed boolean;
  v_cents_changed boolean;
begin
  if tg_op = 'INSERT' then
    if new.value is null and new.amount_cents is not null then
      new.value := new.amount_cents / 100.0;
    elsif new.value is not null and new.amount_cents is null then
      new.amount_cents := round(new.value * 100)::integer;
    elsif new.value is not null
          and new.amount_cents is not null
          and new.amount_cents <> round(new.value * 100)::integer then
      raise exception using
        errcode = '23514',
        message = 'student_payment_amount_mismatch';
    end if;
  else
    v_value_changed := new.value is distinct from old.value;
    v_cents_changed := new.amount_cents is distinct from old.amount_cents;

    if v_value_changed and not v_cents_changed then
      new.amount_cents := case
        when new.value is null then null
        else round(new.value * 100)::integer
      end;
    elsif v_cents_changed and not v_value_changed then
      new.value := case
        when new.amount_cents is null then null
        else new.amount_cents / 100.0
      end;
    elsif v_value_changed and v_cents_changed
          and not (
            new.value is null and new.amount_cents is null
          )
          and (
            new.value is null
            or new.amount_cents is null
            or new.amount_cents <> round(new.value * 100)::integer
          ) then
      raise exception using
        errcode = '23514',
        message = 'student_payment_amount_mismatch';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: teacher_agendas_today(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_agendas_today() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'teacher_id', agenda.teacher_id,
        'name', agenda.teacher_name,
        'phone', agenda.teacher_phone,
        'tenant_id', agenda.tenant_id,
        'classes', agenda.classes
      )
    ),
    '[]'::jsonb
  )
  from (
    select
      upcoming.teacher_id,
      teacher.full_name as teacher_name,
      teacher.phone as teacher_phone,
      teacher.tenant_id,
      pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'time', upcoming.time_text,
          'student', coalesce(student.full_name, upcoming.student_name_override)
        )
        order by upcoming.time_text
      ) as classes
    from public.upcoming_classes as upcoming
    join public.profiles as teacher on teacher.id = upcoming.teacher_id
    left join public.profiles as student on student.id = upcoming.student_id
    where upcoming.class_date =
        (now() at time zone 'America/Sao_Paulo')::date
      and nullif(pg_catalog.btrim(teacher.phone), '') is not null
      and upper(pg_catalog.btrim(coalesce(teacher.role, ''))) = 'TEACHER'
      and lower(pg_catalog.btrim(coalesce(
        teacher.lifecycle_status,
        ''
      ))) = 'active'
      and coalesce(teacher.is_test_account, false) is false
      and teacher.date_automation_enabled is distinct from false
      and exists (
        select 1
        from public.tenant_memberships as membership
        where membership.user_id = teacher.id
          and membership.tenant_id = teacher.tenant_id
          and membership.role = 'TEACHER'
          and membership.status = 'ACTIVE'
      )
    group by
      upcoming.teacher_id,
      teacher.full_name,
      teacher.phone,
      teacher.tenant_id
  ) as agenda;
$$;


--
-- Name: teacher_attach_invoice(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_attach_invoice(p_closing_id uuid, p_nf_link text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_teacher_id uuid := auth.uid();
  v_active_tenant_id text;
  v_active_role text;
  closing_row public.teacher_closings%ROWTYPE;
  object_path text;
  current_status text;
  next_status text;
BEGIN
  IF v_teacher_id IS NULL OR coalesce(auth.role(), '') <> 'authenticated' THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'authentication_required';
  END IF;

  v_active_tenant_id := private.active_tenant_id(v_teacher_id);
  v_active_role := private.active_tenant_role(v_teacher_id);

  IF v_active_tenant_id IS NULL
    OR v_active_role <> 'TEACHER'
    OR NOT private.tenant_is_operational(v_active_tenant_id)
    OR NOT EXISTS (
      SELECT 1
      FROM public.profiles AS profile
      JOIN public.tenant_memberships AS membership
        ON membership.user_id = profile.id
       AND membership.tenant_id = v_active_tenant_id
       AND membership.role = 'TEACHER'
       AND membership.status = 'ACTIVE'
      WHERE profile.id = v_teacher_id
        AND profile.role = 'TEACHER'
        AND lower(pg_catalog.btrim(coalesce(profile.lifecycle_status, ''))) = 'active'
    )
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'teacher_profile_required';
  END IF;

  object_path := nullif(pg_catalog.btrim(coalesce(p_nf_link, '')), '');
  IF p_closing_id IS NULL
    OR object_path IS NULL
    OR pg_catalog.length(object_path) > 512
    OR object_path !~* (
      '^closings/'
      || '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/'
      || '[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}[.]pdf$'
    )
    OR pg_catalog.lower(pg_catalog.split_part(object_path, '/', 2))
       <> pg_catalog.lower(p_closing_id::text)
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = 'nf_link_invalido';
  END IF;

  SELECT closing.*
  INTO closing_row
  FROM public.teacher_closings AS closing
  WHERE closing.id = p_closing_id
    AND closing.teacher_id = v_teacher_id
    AND closing.tenant_id = v_active_tenant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'fechamento_nao_encontrado';
  END IF;

  current_status := upper(coalesce(closing_row.status, ''));
  IF coalesce(closing_row.total_amount, 0) <= 0
    OR current_status NOT IN (
      'PAID_WAITING_NF',
      'PAGO',
      'PAID',
      'REJECTED',
      'REJEITADO',
      'UNDER_REVIEW'
    )
  THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'invoice_submission_not_available';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM storage.objects AS invoice_object
    WHERE invoice_object.bucket_id = 'invoices'
      AND invoice_object.name = object_path
      AND invoice_object.owner_id = v_teacher_id::text
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'invoice_object_not_owned';
  END IF;

  next_status := 'UNDER_REVIEW';

  UPDATE public.teacher_closings AS closing
  SET nf_link = object_path,
      status = next_status,
      rejection_reason = CASE
        WHEN next_status = 'UNDER_REVIEW' THEN NULL
        ELSE closing.rejection_reason
      END,
      updated_at = now()
  WHERE closing.id = closing_row.id
    AND closing.teacher_id = v_teacher_id
    AND closing.tenant_id = v_active_tenant_id
  RETURNING closing.* INTO closing_row;

  RETURN pg_catalog.jsonb_build_object(
    'ok', true,
    'id', closing_row.id,
    'status', closing_row.status,
    'nf_link', closing_row.nf_link
  );
END;
$_$;


--
-- Name: teacher_carteira(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_carteira(p_teacher uuid) RETURNS TABLE(student_id uuid, rnk integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT s.id,
         row_number() OVER (ORDER BY COALESCE(s.start_date, s.created_at::date),
                                     s.created_at, s.id)::int
  FROM profiles s
  WHERE s.role = 'STUDENT'
    AND s.lifecycle_status = 'active'
    AND is_billable_student(s.id)
    AND EXISTS (
      SELECT 1 FROM bookings b
      WHERE b.teacher_id = p_teacher
        AND b.student_id = s.id
        AND COALESCE(b.status, 'SCHEDULED') = 'SCHEDULED'
    );
$$;


--
-- Name: FUNCTION teacher_carteira(p_teacher uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.teacher_carteira(p_teacher uuid) IS 'Alunos da carteira do professor (agenda vigente + ativo + faturável), numerados por antiguidade de matrícula — a ordem que a cláusula 3.4 do contrato usa.';


