--
-- Name: teacher_free_recurring_slots(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_free_recurring_slots(p_tenant text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH dm AS (
    SELECT * FROM (VALUES (0,'Domingo'),(1,'Segunda'),(2,'Terça'),(3,'Quarta'),(4,'Quinta'),(5,'Sexta'),(6,'Sábado')) AS d(dow, name)
  ),
  active_teachers AS (
    SELECT p.id, p.full_name, p.phone
    FROM profiles p
    WHERE p.tenant_id = p_tenant AND p.role = 'TEACHER'
      AND COALESCE(p.lifecycle_status,'active') = 'active'
      AND COALESCE(p.status,'Ativo') NOT IN ('Inativo','INACTIVE','Inactive','Arquivado','Cancelado','Trancado')
  ),
  avail AS (
    SELECT ta.teacher_id, ta.day_of_week AS dow, substring(ta.start_time::text FOR 5) AS tm
    FROM teacher_availability ta
    JOIN active_teachers t ON t.id = ta.teacher_id
    WHERE substring(ta.start_time::text FOR 5) BETWEEN '07:00' AND '21:30'
  ),
  free AS (
    SELECT a.teacher_id, a.dow, a.tm
    FROM avail a
    WHERE NOT EXISTS (
      SELECT 1 FROM bookings b JOIN dm ON dm.name = b.day_of_week
      WHERE b.teacher_id = a.teacher_id AND dm.dow = a.dow
        AND substring(COALESCE(b.time_slot,'') FOR 5) = a.tm
        AND COALESCE(b.status,'') NOT IN ('CANCELLED','CANCELED')
    )
  ),
  per_teacher AS (
    SELECT t.id AS teacher_id, trim(t.full_name) AS name, t.phone,
      COALESCE(jsonb_agg(jsonb_build_object('dow', f.dow, 'time', f.tm) ORDER BY f.dow, f.tm)
               FILTER (WHERE f.dow IS NOT NULL), '[]'::jsonb) AS free_slots,
      count(f.tm) AS free_count
    FROM active_teachers t
    LEFT JOIN free f ON f.teacher_id = t.id
    GROUP BY t.id, t.full_name, t.phone
  )
  SELECT jsonb_build_object(
    'ok', true,
    'teachers', COALESCE(jsonb_agg(jsonb_build_object(
        'teacher_id', teacher_id, 'name', name, 'phone', phone,
        'free_count', free_count, 'free_slots', free_slots
      ) ORDER BY free_count DESC, name) FILTER (WHERE free_count > 0), '[]'::jsonb)
  ) INTO v_result
  FROM per_teacher;

  RETURN v_result;
END;
$$;


