-- Name: teacher_pay_projection(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_pay_projection(p_teacher uuid, p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT private.can_access_teacher_projection(p_teacher, p_month) THEN
    RAISE EXCEPTION 'teacher_finance_access_denied' USING ERRCODE = '42501';
  END IF;

  RETURN public.teacher_pay_projection_unchecked(p_teacher, p_month);
END;
$$;


--
-- Name: FUNCTION teacher_pay_projection(p_teacher uuid, p_month text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.teacher_pay_projection(p_teacher uuid, p_month text) IS 'Tenant-aware facade for the legacy teacher pay projection calculation.';


--
-- Name: teacher_pay_projection_unchecked(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_pay_projection_unchecked(p_teacher uuid, p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_month text; v_start date; v_end date; v_tenant text;
        v_logged_n int; v_logged numeric; v_pot_base numeric; v_pot_turbo numeric;
        v_active int; v_next int; v_next_rate numeric; v_base numeric; v_tiers jsonb;
BEGIN
  v_month := COALESCE(p_month, to_char(current_date,'YYYY-MM'));
  v_start := (v_month||'-01')::date;
  v_end   := (date_trunc('month', v_start) + INTERVAL '1 month - 1 day')::date;

  SELECT tenant_id INTO v_tenant FROM profiles WHERE id = p_teacher;
  SELECT rate INTO v_base FROM teacher_pay_tiers WHERE tenant_id = v_tenant AND min_students = 1;
  v_base := COALESCE(v_base, 0);

  SELECT count(*), COALESCE(sum(v.rate_efetivo),0) INTO v_logged_n, v_logged
  FROM v_payable_class_logs v
  WHERE v.teacher_id = p_teacher AND to_char(v.class_date,'YYYY-MM') = v_month;

  SELECT count(*) INTO v_active FROM teacher_carteira(p_teacher);

  WITH aulas_previstas AS (
    SELECT b.student_id
    FROM bookings b
    CROSS JOIN generate_series(v_start, v_end, '1 day') d
    WHERE b.teacher_id = p_teacher AND b.student_id IS NOT NULL
      AND COALESCE(b.status,'SCHEDULED') = 'SCHEDULED'
      AND dow_name_to_int(b.day_of_week) = EXTRACT(dow FROM d)::int
      AND (b.start_date IS NULL OR d >= b.start_date)
  )
  SELECT COALESCE(count(*),0) * v_base,
         COALESCE(sum(COALESCE(
           (SELECT t.rate FROM teacher_pay_tiers t
             WHERE t.tenant_id = v_tenant AND t.min_students <= c.rnk
             ORDER BY t.min_students DESC LIMIT 1), v_base)), 0)
    INTO v_pot_base, v_pot_turbo
  FROM aulas_previstas a
  LEFT JOIN teacher_carteira(p_teacher) c ON c.student_id = a.student_id;

  IF v_active < 10 THEN v_pot_turbo := v_pot_base; END IF;

  SELECT min_students, rate INTO v_next, v_next_rate FROM teacher_pay_tiers
   WHERE tenant_id = v_tenant AND min_students > v_active ORDER BY min_students ASC LIMIT 1;

  -- Faixas reais da escola, em ordem — a fonte do texto mostrado ao professor.
  SELECT COALESCE(jsonb_agg(jsonb_build_object('min_students', t.min_students, 'rate', t.rate)
                            ORDER BY t.min_students), '[]'::jsonb)
    INTO v_tiers FROM teacher_pay_tiers t WHERE t.tenant_id = v_tenant;

  RETURN jsonb_build_object(
    'month', v_month, 'turbo', teacher_turbo_status(p_teacher),
    'lessons_logged', v_logged_n, 'amount_logged', round(v_logged,2),
    'amount_potential_base', round(v_pot_base,2), 'amount_potential_turbo', round(v_pot_turbo,2),
    'active_students', v_active, 'next_tier_at', v_next, 'next_tier_rate', v_next_rate,
    'students_to_next', CASE WHEN v_next IS NULL THEN NULL ELSE v_next - v_active END,
    'base_rate', v_base, 'tiers', v_tiers
  );
END; $$;


--
-- Name: FUNCTION teacher_pay_projection_unchecked(p_teacher uuid, p_month text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.teacher_pay_projection_unchecked(p_teacher uuid, p_month text) IS 'Projeção do mês do professor + status do turbo + as faixas REAIS de teacher_pay_tiers. Nenhuma tela deve chumbar valor de aula: o que a escola paga está em tiers.';


--
-- Name: teacher_payroll_reconciliation(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_payroll_reconciliation(p_month text DEFAULT NULL::text, p_tenant text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_month text;
  v_tenant text;
  v_ini date;
  v_fim date;
  v_professores jsonb;
  v_totais jsonb;
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR']::text[]
  ) THEN
    RETURN jsonb_build_object('error', 'sem_permissao');
  END IF;

  -- O tenant vem SEMPRE do perfil de quem chamou. Só o SUPER_ADMIN escolhe,
  -- senão um diretor leria a folha de outra escola passando o slug no corpo.
  v_tenant := CASE
    WHEN is_super_admin() AND nullif(btrim(coalesce(p_tenant, '')), '') IS NOT NULL
      THEN btrim(p_tenant)
    ELSE _my_tenant_id()
  END;
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('error', 'sem_tenant');
  END IF;

  v_month := coalesce(nullif(btrim(coalesce(p_month, '')), ''),
                      to_char(current_date, 'YYYY-MM'));
  IF v_month !~ '^[0-9]{4}-(0[1-9]|1[0-2])$' THEN
    RETURN jsonb_build_object('error', 'mes_invalido');
  END IF;
  v_ini := (v_month || '-01')::date;
  v_fim := (date_trunc('month', v_ini) + interval '1 month - 1 day')::date;

  WITH
  -- o que foi DADO: fonte única de "esta aula paga", por professor e aluno
  folha AS (
    SELECT v.teacher_id,
           v.student_id,
           count(*)::int AS aulas,
           round(sum(v.rate_efetivo), 2) AS valor
      FROM v_payable_class_logs AS v
     WHERE v.tenant_id = v_tenant
       AND to_char(v.class_date, 'YYYY-MM') = v_month
     GROUP BY 1, 2
  ),
  -- pagamentos que geraram aviso no grupo (mesmo conjunto de status do caixa)
  pagos AS (
    SELECT sp.id, sp.student_id, payment_split_breakdown(sp.id) AS b
      FROM student_payments AS sp
     WHERE sp.tenant_id = v_tenant
       AND sp.status IN ('RECEIVED', 'RECEIVED_IN_CASH')
       AND to_char(
             coalesce(sp.paid_at, sp.payment_date, sp.due_date), 'YYYY-MM'
           ) = v_month
  ),
  -- o que ENTROU na caixinha, por professor e aluno
  caixinha AS (
    SELECT (prof ->> 'teacher_id')::uuid AS teacher_id,
           p.student_id,
           round(sum((prof ->> 'custo')::numeric), 2) AS valor,
           count(DISTINCT p.id)::int AS avisos
      FROM pagos AS p
      CROSS JOIN LATERAL jsonb_array_elements(p.b -> 'professores') AS prof
     WHERE prof ->> 'custo' IS NOT NULL
       AND prof ->> 'teacher_id' IS NOT NULL
     GROUP BY 1, 2
  ),
  -- quantas cobranças cada aluno teve no mês, e se alguma ficou sem liquidar
  cobrancas AS (
    SELECT sp.student_id,
           count(*) FILTER (
             WHERE sp.status IN ('RECEIVED', 'RECEIVED_IN_CASH')
           )::int AS pagas,
           bool_or(sp.status = 'CONFIRMED') AS tem_confirmed
      FROM student_payments AS sp
     WHERE sp.tenant_id = v_tenant
       AND sp.student_id IS NOT NULL
       AND to_char(
             coalesce(sp.paid_at, sp.payment_date, sp.due_date), 'YYYY-MM'
           ) = v_month
     GROUP BY 1
  ),
  -- previsto pela agenda: é o MESMO cálculo do aviso (dias do mês × grade)
  previsto AS (
    SELECT b.teacher_id,
           count(*)::int AS aulas,
           round(sum(
             teacher_student_rate(b.teacher_id, b.student_id, d::date)
           ), 2) AS valor
      FROM bookings AS b
      CROSS JOIN generate_series(v_ini, v_fim, '1 day') AS d
     WHERE b.tenant_id = v_tenant
       AND coalesce(b.status, 'SCHEDULED') = 'SCHEDULED'
       AND b.student_id IS NOT NULL
       AND dow_name_to_int(b.day_of_week) = extract(dow FROM d)::int
       AND (b.start_date IS NULL OR d >= b.start_date)
     GROUP BY 1
  ),
  -- aula de mês anterior absorvida aqui: está na folha e não na caixinha do mês
  sobras AS (
    SELECT co.teacher_id,
           count(*)::int AS aulas,
           round(sum(co.amount), 2) AS valor
      FROM closing_carryovers AS co
      JOIN class_logs AS cl
        ON cl.id = co.class_log_id
       AND cl.tenant_id = v_tenant
     WHERE co.absorbed_month = v_month
     GROUP BY 1
  ),
  ajustes AS (
    SELECT a.teacher_id, round(sum(a.amount), 2) AS valor
      FROM closing_adjustments AS a
     WHERE a.tenant_id = v_tenant
       AND a.month_year = v_month
     GROUP BY 1
  ),
  fechamento AS (
    SELECT c.teacher_id, c.total_lessons, c.total_amount, c.status
      FROM teacher_closings AS c
     WHERE c.tenant_id = v_tenant
       AND c.month_year = v_month
  ),
  -- Professor da DIREÇÃO: o aviso manda 'custo': null de propósito, porque a
  -- régua dele é pró-labore (80%), não custo descontado do líquido. Ele não tem
  -- caixinha — mostrar "diferença = folha inteira" seria a tela mentindo.
  donos AS (
    SELECT o.teacher_id
      FROM payment_split_owner_teachers AS o
     WHERE o.tenant_id = v_tenant
  ),
  -- uma linha por professor×aluno, já classificada
  detalhe AS (
    SELECT coalesce(f.teacher_id, c.teacher_id) AS teacher_id,
           coalesce(f.student_id, c.student_id) AS student_id,
           coalesce(f.aulas, 0) AS aulas,
           coalesce(f.valor, 0) AS valor_folha,
           coalesce(c.valor, 0) AS valor_caixinha,
           coalesce(c.avisos, 0) AS avisos,
           coalesce(cb.pagas, 0) AS cobrancas_pagas,
           coalesce(cb.tem_confirmed, false) AS tem_confirmed
      FROM folha AS f
      FULL JOIN caixinha AS c
        ON c.teacher_id = f.teacher_id
       AND c.student_id IS NOT DISTINCT FROM f.student_id
      LEFT JOIN cobrancas AS cb
        ON cb.student_id = coalesce(f.student_id, c.student_id)
     WHERE NOT EXISTS (
       SELECT 1 FROM donos AS o
        WHERE o.teacher_id = coalesce(f.teacher_id, c.teacher_id)
     )
  ),
  classificado AS (
    SELECT d.*,
           round(d.valor_folha - d.valor_caixinha, 2) AS diferenca,
           CASE
             WHEN d.student_id IS NULL THEN 'AULA_SEM_ALUNO'
             -- Pagou e mesmo assim não gerou caixinha: o aviso calcula o custo
             -- pela AGENDA, então aluno sem booking ativo sai com custo zero e
             -- o dinheiro entra sem nada ser separado para o professor.
             -- Chamar isso de "não pagou" seria a tela mentindo sobre o aluno.
             WHEN d.valor_caixinha = 0 AND d.cobrancas_pagas > 0
               THEN 'PAGOU_SEM_AGENDA'
             WHEN d.valor_caixinha = 0 AND d.tem_confirmed
               THEN 'PAGAMENTO_NAO_LIQUIDADO'
             WHEN d.valor_caixinha = 0 THEN 'ALUNO_SEM_PAGAMENTO'
             WHEN d.valor_caixinha > d.valor_folha AND d.avisos > 1
               THEN 'PAGAMENTO_REPETIDO'
             WHEN d.valor_caixinha > d.valor_folha THEN 'AULA_NAO_LANCADA'
             WHEN d.valor_folha > d.valor_caixinha THEN 'AGENDA_DESATUALIZADA'
             ELSE 'OK'
           END AS motivo
      FROM detalhe AS d
  ),
  por_professor AS (
    SELECT cl.teacher_id,
           jsonb_agg(
             jsonb_build_object(
               'motivo', cl.motivo,
               'aluno', coalesce(btrim(s.full_name), 'sem aluno vinculado'),
               'aulas', cl.aulas,
               'folha', cl.valor_folha,
               'caixinha', cl.valor_caixinha,
               'diferenca', cl.diferenca,
               'avisos', cl.avisos
             )
             ORDER BY abs(cl.diferenca) DESC, cl.valor_folha DESC
           ) FILTER (WHERE cl.motivo <> 'OK') AS itens,
           round(sum(cl.valor_folha), 2) AS folha_aulas,
           round(sum(cl.valor_caixinha), 2) AS caixinha
      FROM classificado AS cl
      LEFT JOIN profiles AS s ON s.id = cl.student_id
     GROUP BY 1
  )
  SELECT jsonb_agg(linha ORDER BY linha ->> 'teacher_name'), 
         jsonb_build_object(
           'previsto', round(coalesce(sum((linha ->> 'previsto')::numeric), 0), 2),
           'folha',    round(coalesce(sum((linha ->> 'folha')::numeric), 0), 2),
           'caixinha', round(coalesce(sum((linha ->> 'caixinha')::numeric), 0), 2),
           'diferenca',round(coalesce(sum((linha ->> 'diferenca')::numeric), 0), 2),
           'professores', count(*)::int,
           'pro_labore_fora', count(*) FILTER (
             WHERE (linha ->> 'pro_labore')::boolean)::int
         )
    INTO v_professores, v_totais
    FROM (
      SELECT jsonb_build_object(
               'teacher_id', t.id,
               'teacher_name', btrim(t.full_name),
               'previsto', coalesce(pv.valor, 0),
               'previsto_aulas', coalesce(pv.aulas, 0),
               'folha', coalesce(fc.total_amount, pp.folha_aulas, 0),
               'folha_aulas', coalesce(fc.total_lessons, 0),
               'status', coalesce(fc.status, 'SEM FECHAMENTO'),
               'pro_labore', (dn.teacher_id IS NOT NULL),
               'caixinha', CASE WHEN dn.teacher_id IS NULL
                                THEN coalesce(pp.caixinha, 0) END,
               'diferenca', CASE WHEN dn.teacher_id IS NULL THEN round(
                 coalesce(fc.total_amount, pp.folha_aulas, 0)
                 - coalesce(pp.caixinha, 0), 2) END,
               'sobras', jsonb_build_object(
                 'aulas', coalesce(sb.aulas, 0), 'valor', coalesce(sb.valor, 0)),
               'ajustes', coalesce(aj.valor, 0),
               'turbo', jsonb_build_object(
                 'ativo', teacher_turbo_on(t.id, v_fim),
                 'alunos', (SELECT count(*)::int FROM teacher_carteira(t.id)),
                 'detalhe', teacher_turbo_status_at(t.id, v_fim)),
               'itens', coalesce(pp.itens, '[]'::jsonb)
             ) AS linha
        FROM profiles AS t
        LEFT JOIN por_professor AS pp ON pp.teacher_id = t.id
        LEFT JOIN previsto AS pv ON pv.teacher_id = t.id
        LEFT JOIN sobras AS sb ON sb.teacher_id = t.id
        LEFT JOIN ajustes AS aj ON aj.teacher_id = t.id
        LEFT JOIN fechamento AS fc ON fc.teacher_id = t.id
        LEFT JOIN donos AS dn ON dn.teacher_id = t.id
       WHERE t.tenant_id = v_tenant
         AND t.role = 'TEACHER'
         AND (pp.teacher_id IS NOT NULL OR fc.teacher_id IS NOT NULL
              OR pv.teacher_id IS NOT NULL)
    ) AS x;

  RETURN jsonb_build_object(
    'month', v_month,
    'tenant', v_tenant,
    'totais', coalesce(v_totais, '{}'::jsonb),
    'professores', coalesce(v_professores, '[]'::jsonb)
  );
END;
$_$;


--
-- Name: FUNCTION teacher_payroll_reconciliation(p_month text, p_tenant text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.teacher_payroll_reconciliation(p_month text, p_tenant text) IS 'Concilia a caixinha (custo avisado no grupo da gestão, calculado pela agenda) com a folha (aula efetivamente lançada), decompondo a diferença por motivo. Não recalcula pagamento: lê v_payable_class_logs e teacher_closings.';


--
-- Name: teacher_pending_carryover(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_pending_carryover(p_teacher uuid) RETURNS TABLE(class_log_id uuid, origin_month text, class_date date, amount numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
  SELECT v.id, to_char(v.class_date,'YYYY-MM'), v.class_date, v.rate_efetivo
  FROM v_payable_class_logs v
  JOIN teacher_closings tc
    ON tc.teacher_id = v.teacher_id
   AND tc.month_year = to_char(v.class_date,'YYYY-MM')
  WHERE v.teacher_id = p_teacher
    AND tc.status <> 'PENDENTE'                 -- fechamento congelado
    AND v.created_at > tc.updated_at            -- lançada depois de congelar
    -- Corte: o mecanismo vale daqui pra frente. A direção decidiu manter maio e
    -- junho congelados como estão, então o passivo histórico (5 aulas, R$ 45,50
    -- em 01/08/2026) não é puxado retroativamente.
    AND v.created_at >= '2026-08-02'::date
    AND NOT EXISTS (SELECT 1 FROM closing_carryovers cc WHERE cc.class_log_id = v.id);
$_$;


--
-- Name: teacher_pending_carryover_in_tenant(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_pending_carryover_in_tenant(p_tenant text, p_teacher uuid) RETURNS TABLE(class_log_id uuid, origin_month text, class_date date, amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'service_role_required';
  END IF;
  RETURN QUERY
  SELECT pending.class_log_id,
         pending.origin_month,
         pending.class_date,
         pending.amount
    FROM private.teacher_pending_carryover_in_tenant(
      p_tenant,
      p_teacher
    ) AS pending;
END;
$$;


--
-- Name: teacher_student_rate(uuid, uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_student_rate(p_teacher uuid, p_student uuid, p_date date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tenant text; v_flat numeric; v_base numeric; v_rank int; v_rate numeric; v_per_lesson boolean;
BEGIN
  SELECT tenant_id, hourly_rate INTO v_tenant, v_flat FROM profiles WHERE id = p_teacher;
  SELECT coalesce((SELECT commercial_snapshot ->> 'rateUnit' = 'PER_LESSON'
    FROM tenant_contract_records WHERE user_id = p_teacher AND tenant_id = v_tenant
      AND contract_kind = 'TEACHER' ORDER BY accepted_at DESC, created_at DESC LIMIT 1), false)
    INTO v_per_lesson;
  SELECT rate INTO v_base FROM teacher_pay_tiers WHERE tenant_id = v_tenant AND min_students = 1;
  v_base := CASE WHEN v_per_lesson THEN coalesce(v_flat, v_base, 0) ELSE coalesce(v_base, v_flat, 0) END;
  IF NOT teacher_turbo_on(p_teacher, p_date) THEN RETURN v_base; END IF;
  SELECT c.rnk INTO v_rank FROM teacher_carteira(p_teacher) c WHERE c.student_id = p_student;
  IF v_rank IS NULL THEN RETURN v_base; END IF;
  SELECT rate INTO v_rate FROM teacher_pay_tiers
   WHERE tenant_id = v_tenant AND (CASE WHEN v_tenant = 'school-wise-wolf' AND p_date < DATE '2026-09-09' AND min_students = 7 THEN 10 ELSE min_students END) <= v_rank
   ORDER BY min_students DESC LIMIT 1;
  RETURN CASE WHEN v_per_lesson THEN greatest(v_base, coalesce(v_rate, v_base)) ELSE coalesce(v_rate, v_base) END;
END;
$$;


--
-- Name: FUNCTION teacher_student_rate(p_teacher uuid, p_student uuid, p_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.teacher_student_rate(p_teacher uuid, p_student uuid, p_date date) IS 'Tarifa base por aula do tenant (R$ 8,00 na Wise Wolf). Achatada em 01/08/2026 — não usa mais antiguidade de aluno nem turbo. O bônus de treinamento é aplicado em v_payable_class_logs, não aqui.';


--
-- Name: teacher_submit_closing(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_submit_closing(p_month text, p_confirmation text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_teacher uuid := auth.uid();
  v_profile record;
  v_confirm text;
  v_notes text;
  v_row public.teacher_closings;
  v_report jsonb;
  v_lessons int;
  v_amount numeric;
  v_created boolean := false;
begin
  ---------------------------------------------------------------------------
  -- Autenticação e escopo. `teacher_id` é SEMPRE auth.uid(): não existe
  -- parâmetro para confirmar o fechamento de outra pessoa.
  ---------------------------------------------------------------------------
  if v_teacher is null or auth.role() <> 'authenticated' then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  select p.id, p.tenant_id, p.role
    into v_profile
    from public.profiles p
   where p.id = v_teacher;

  if not found
     or v_profile.tenant_id is null
     or v_profile.role not in ('TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN') then
    raise exception using errcode = '42501', message = 'teacher_profile_required';
  end if;

  if p_month is null or p_month !~ '^\d{4}-\d{2}$' then
    raise exception using errcode = '22023', message = 'invalid_month';
  end if;

  v_confirm := upper(pg_catalog.btrim(coalesce(p_confirmation, '')));
  if v_confirm not in ('OK', 'CONTESTADO') then
    raise exception using errcode = '22023', message = 'invalid_confirmation';
  end if;

  -- Contestação sem motivo não serve para nada: o diretor não teria o que
  -- resolver, e a linha ficaria travada sem explicação.
  v_notes := nullif(pg_catalog.btrim(coalesce(p_notes, '')), '');
  if v_confirm = 'CONTESTADO' and v_notes is null then
    raise exception using errcode = '22023', message = 'contestacao_exige_motivo';
  end if;
  if v_confirm = 'OK' then
    v_notes := null;
  else
    v_notes := pg_catalog.left(v_notes, 2000);
  end if;

  ---------------------------------------------------------------------------
  -- Linha existente: SÓ os campos de confirmação. Valor, contagem, status,
  -- class_log_ids e paid_at não são tocados aqui em hipótese nenhuma.
  ---------------------------------------------------------------------------
  select tc.* into v_row
    from public.teacher_closings tc
   where tc.teacher_id = v_teacher
     and tc.month_year = p_month
   for update;

  if found then
    -- Depois que o diretor moveu o fechamento adiante (pagou, aprovou, mandou
    -- para análise de NF), a confirmação do professor já cumpriu o papel.
    -- Reabrir aqui seria voltar o processo no tempo.
    if upper(coalesce(v_row.status, 'PENDENTE'))
       not in ('PENDENTE', 'PENDING', 'PENDING_TEACHER', 'REJEITADO') then
      raise exception using errcode = '42501', message = 'fechamento_ja_em_processamento';
    end if;

    update public.teacher_closings tc
       set teacher_confirmation_status = v_confirm,
           teacher_confirmation_date   = now(),
           teacher_notes               = v_notes,
           updated_at                  = now()
     where tc.id = v_row.id
    returning tc.* into v_row;

  else
    -------------------------------------------------------------------------
    -- Sem linha ainda (professor confirma antes do cron mensal). O valor vem
    -- da RPC canônica — a mesma que a tela lê — e não do que o cliente mandar.
    -------------------------------------------------------------------------
    v_report  := public.get_teacher_closing_report(v_teacher, p_month);
    v_lessons := coalesce((v_report -> 'resumo' ->> 'total_aulas')::int, 0);
    v_amount  := round(coalesce((v_report -> 'resumo' ->> 'valor_total')::numeric, 0), 2);

    insert into public.teacher_closings (
      tenant_id, teacher_id, month_year,
      total_lessons, total_amount, status,
      teacher_confirmation_status, teacher_confirmation_date, teacher_notes,
      created_at, updated_at
    )
    values (
      v_profile.tenant_id, v_teacher, p_month,
      v_lessons, v_amount, 'PENDENTE',
      v_confirm, now(), v_notes,
      now(), now()
    )
    -- Corrida com o cron mensal: se a linha nasceu no meio do caminho, a dele
    -- vale (tem carry-over) e aqui só entra a confirmação.
    on conflict (teacher_id, month_year) do update
       set teacher_confirmation_status = excluded.teacher_confirmation_status,
           teacher_confirmation_date   = excluded.teacher_confirmation_date,
           teacher_notes               = excluded.teacher_notes,
           updated_at                  = now()
    returning * into v_row;

    v_created := true;
  end if;

  return jsonb_build_object(
    'ok', true,
    'criado', v_created,
    'id', v_row.id,
    'month_year', v_row.month_year,
    'status', v_row.status,
    'teacher_confirmation_status', v_row.teacher_confirmation_status,
    'total_lessons', v_row.total_lessons,
    'total_amount', v_row.total_amount
  );
end;
$_$;


--
-- Name: teacher_sync_streak(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_sync_streak(p_teacher uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_tenant text; v_total int; v_streak int; v_best int; v_earned int; v_already int; v_tier int; i int;
BEGIN
  SELECT tenant_id INTO v_tenant FROM profiles WHERE id = p_teacher;

  -- total de aulas qualificadas (professor não faltou)
  SELECT count(*) INTO v_total FROM class_logs cl
   WHERE cl.teacher_id = p_teacher AND cl.presence NOT IN ('TEACHER_ABSENCE','Falta do Professor');

  -- sequência atual: aulas mais recentes consecutivas sem falta do professor
  WITH ordered AS (
    SELECT presence, row_number() OVER (ORDER BY class_date DESC NULLS LAST, created_at DESC) AS rn
    FROM class_logs WHERE teacher_id = p_teacher
  ), broken AS (
    SELECT min(rn) AS first_break FROM ordered WHERE presence IN ('TEACHER_ABSENCE','Falta do Professor')
  )
  SELECT COALESCE((SELECT first_break-1 FROM broken), (SELECT count(*) FROM ordered)) INTO v_streak;

  v_tier := CASE WHEN v_streak >= 200 THEN 200 WHEN v_streak >= 80 THEN 80 ELSE 30 END;
  v_earned := floor(v_total / 30.0);

  INSERT INTO teacher_streaks (teacher_id, tenant_id, current_streak, best_streak, total_qualifying, spins_earned, updated_at)
  VALUES (p_teacher, v_tenant, v_streak, v_streak, v_total, v_earned, now())
  ON CONFLICT (teacher_id) DO UPDATE SET
    current_streak = EXCLUDED.current_streak,
    best_streak = GREATEST(teacher_streaks.best_streak, EXCLUDED.current_streak),
    total_qualifying = EXCLUDED.total_qualifying,
    updated_at = now();

  -- concede os giros ainda não criados
  SELECT count(*) INTO v_already FROM roulette_spins WHERE teacher_id = p_teacher;
  IF v_earned > v_already THEN
    FOR i IN 1..(v_earned - v_already) LOOP
      INSERT INTO roulette_spins (teacher_id, tenant_id, tier) VALUES (p_teacher, v_tenant, v_tier);
    END LOOP;
    UPDATE teacher_streaks SET spins_earned = v_earned WHERE teacher_id = p_teacher;
  END IF;

  RETURN jsonb_build_object('streak', v_streak, 'total', v_total,
    'spins_available', (SELECT count(*) FROM roulette_spins WHERE teacher_id=p_teacher AND status='available'));
END; $$;


--
-- Name: teacher_training_invite(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_training_invite(p_token text, p_decision text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare s public.teacher_training_sessions%rowtype; v_appointment uuid; v_phone text;
begin
 if coalesce(auth.role(),'')<>'service_role' then raise exception using errcode='42501',message='service_role_required'; end if;
 if p_token !~ '^[a-f0-9]{64}$' then return jsonb_build_object('ok',false,'error','Convite inválido.'); end if;
 select t.* into s from public.teacher_training_sessions t join private.teacher_training_invite_tokens k on k.session_id=t.id where k.token_hash=encode(extensions.digest(p_token,'sha256'),'hex') and k.expires_at>now() for update of t;
 if not found then return jsonb_build_object('ok',false,'error','Convite inválido ou expirado. Peça um novo agendamento à gestão.'); end if;
 if p_decision is not null and p_decision not in ('accept','decline') then return jsonb_build_object('ok',false,'error','Resposta inválida.'); end if;
 if s.status='PENDING' and p_decision is not null then
   if p_decision='accept' then
     perform private.validate_training_slot(s.tenant_id,s.trainer_id,s.trainee_id,s.starts_at,s.id);
     insert into public.appointments(tenant_id,teacher_id,professor_id,student_name,student_phone,start_time,status,type)
     values(s.tenant_id,s.trainer_id,s.trainer_id,s.trainee_name,s.trainee_phone,s.starts_at,'scheduled','training') returning id into v_appointment;
     update public.teacher_training_sessions set status='CONFIRMED',appointment_id=v_appointment,responded_at=now() where id=s.id returning * into s;
   else
     update public.teacher_training_sessions set status='DECLINED',responded_at=now() where id=s.id returning * into s;
   end if;
   select regexp_replace(coalesce(nullif(attendance_phone,''),phone,''),'[^0-9]','','g') into v_phone from public.profiles where id=s.trainer_id;
   if length(v_phone) in (10,11) then v_phone:='55'||v_phone; end if;
   if not s.test_fixture and length(v_phone) between 12 and 15 then
     insert into public.notification_queue(tenant_id,student_phone,message_body,scheduled_for,source_type,source_id,notification_kind,idempotency_key)
     values(s.tenant_id,v_phone,s.trainee_name||case when s.status='CONFIRMED' then ' aceitou' else ' recusou' end||' o treinamento de '||to_char(s.starts_at at time zone 'America/Sao_Paulo','DD/MM "às" HH24:MI')||'.'||case when s.status='CONFIRMED' then ' Após ministrar o treinamento, registre a conclusão no lançador de aulas para receber R$ 16,00.' else ' Nenhum valor foi lançado.' end,now(),'teacher_training',s.id,'TEACHER_TRAINING_RESPONSE','teacher-training-response:'||s.id);
   end if;
 end if;
 return jsonb_build_object('ok',true,'status',s.status,'trainer',s.trainer_name,'trainee',s.trainee_name,'starts_at',s.starts_at,'ends_at',s.ends_at,'meeting_link',case when s.status='CONFIRMED' then coalesce(nullif(s.meeting_link,''),(select p.meeting_link from public.profiles p where p.id=s.trainer_id and p.meeting_link ~ '^https://[^[:space:]]+$')) else null end);
end;
$_$;


--
-- Name: teacher_training_scheduler_data(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_training_scheduler_data(p_tenant text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not private.training_manager(p_tenant,auth.uid()) then raise exception using errcode='42501',message='Acesso restrito à gestão.'; end if;
 return jsonb_build_object(
  'teachers',(select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'name',p.full_name,'is_trainer',p.is_trainer) order by p.full_name),'[]'::jsonb) from public.profiles p join public.tenant_memberships m on m.user_id=p.id and m.tenant_id=p_tenant and m.status='ACTIVE' and m.role='TEACHER' where p.tenant_id=p_tenant and p.role='TEACHER' and lower(coalesce(p.lifecycle_status,'active'))='active'),
  'sessions',(select coalesce(jsonb_agg(to_jsonb(x) order by starts_at desc),'[]'::jsonb) from (
   select s.id,s.trainer_name,s.trainee_name,s.starts_at,s.status,s.agreed_rate,
    (select q.delivery_status from public.notification_queue q where q.source_id=s.id and q.notification_kind='TEACHER_TRAINING_INVITE' order by q.created_at desc limit 1) as invitation_status
   from public.teacher_training_sessions s where s.tenant_id=p_tenant and s.starts_at>now()-interval '60 days' and not s.test_fixture order by s.starts_at desc limit 100
  ) x));
end;
$$;


--
-- Name: teacher_turbo_add_event(uuid, text, text, date, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_add_event(p_teacher uuid, p_tenant text, p_event_type text, p_effective_on date, p_source_type text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid, p_actor uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.teacher_turbo_events AS e (
    teacher_id, tenant_id, event_type, effective_on,
    source_type, source_id, actor_id, metadata
  ) VALUES (
    p_teacher, p_tenant, p_event_type, p_effective_on,
    p_source_type, p_source_id, p_actor, COALESCE(p_metadata, '{}'::jsonb)
  )
  ON CONFLICT (teacher_id, event_type, source_type, source_id)
    WHERE source_id IS NOT NULL
  DO UPDATE SET
    tenant_id = EXCLUDED.tenant_id,
    effective_on = EXCLUDED.effective_on,
    actor_id = COALESCE(EXCLUDED.actor_id, e.actor_id),
    metadata = EXCLUDED.metadata;
END;
$$;


--
-- Name: teacher_turbo_business_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_business_date() RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT (pg_catalog.now() AT TIME ZONE 'America/Sao_Paulo')::date;
$$;


--
-- Name: teacher_turbo_ensure_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_ensure_state(p_teacher uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_tenant text;
  v_anchor date;
  v_previous_tenant text;
  v_tenant_changed boolean := false;
BEGIN
  SELECT p.tenant_id,
         LEAST(
           public.teacher_turbo_business_date(),
           COALESCE(p.start_date, p.created_at::date, public.teacher_turbo_business_date())
         )
    INTO v_tenant, v_anchor
  FROM public.profiles p
  WHERE p.id = p_teacher
    AND p.role = 'TEACHER';

  IF v_tenant IS NULL THEN
    RETURN;
  END IF;

  -- profiles representa um unico tenant ativo por professor. Serializar pela
  -- linha de estado permite detectar a transferencia e reiniciar o ciclo uma
  -- unica vez, mesmo se outros gatilhos do mesmo UPDATE tambem fizerem refresh.
  SELECT s.tenant_id
    INTO v_previous_tenant
  FROM public.teacher_turbo_state s
  WHERE s.teacher_id = p_teacher
  FOR UPDATE;

  v_tenant_changed := FOUND AND v_previous_tenant IS DISTINCT FROM v_tenant;

  INSERT INTO public.teacher_turbo_state AS s (
    teacher_id, tenant_id, initial_anchor_on, streak_anchor_on
  ) VALUES (
    p_teacher, v_tenant, v_anchor, v_anchor
  )
  ON CONFLICT (teacher_id) DO UPDATE SET
    tenant_id = EXCLUDED.tenant_id,
    initial_anchor_on = CASE
      WHEN s.tenant_id IS DISTINCT FROM EXCLUDED.tenant_id
        THEN public.teacher_turbo_business_date()
      ELSE s.initial_anchor_on
    END,
    streak_anchor_on = CASE
      WHEN s.tenant_id IS DISTINCT FROM EXCLUDED.tenant_id
        THEN public.teacher_turbo_business_date()
      ELSE s.streak_anchor_on
    END,
    students_active = CASE
      WHEN s.tenant_id IS DISTINCT FROM EXCLUDED.tenant_id THEN 0
      ELSE s.students_active
    END,
    students_eligible_since = CASE
      WHEN s.tenant_id IS DISTINCT FROM EXCLUDED.tenant_id THEN NULL
      ELSE s.students_eligible_since
    END,
    last_confirmed_absence_on = CASE
      WHEN s.tenant_id IS DISTINCT FROM EXCLUDED.tenant_id THEN NULL
      ELSE s.last_confirmed_absence_on
    END,
    updated_at = now();

  IF v_tenant_changed THEN
    PERFORM public.teacher_turbo_add_event(
      p_teacher, v_tenant, 'STREAK_INITIALIZED',
      public.teacher_turbo_business_date(),
      'tenant_transfer', NULL, NULL,
      jsonb_build_object(
        'origin', 'tenant_transfer',
        'previous_tenant_id', v_previous_tenant,
        'tenant_id', v_tenant
      )
    );
  ELSE
    PERFORM public.teacher_turbo_add_event(
      p_teacher, v_tenant, 'STREAK_INITIALIZED', v_anchor,
      'teacher', p_teacher, NULL,
      jsonb_build_object('origin', 'profile_start')
    );
  END IF;
END;
$$;


--
-- Name: teacher_turbo_on(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_on(p_teacher uuid, p_date date DEFAULT public.teacher_turbo_business_date()) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT CASE
    WHEN p_date < DATE '2026-08-20'
      THEN public.teacher_turbo_on_legacy_monthly(p_teacher, p_date)
    ELSE COALESCE((public.teacher_turbo_status_at(p_teacher, p_date)->>'active')::boolean, false)
  END;
$$;


--
-- Name: FUNCTION teacher_turbo_on(p_teacher uuid, p_date date); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.teacher_turbo_on(p_teacher uuid, p_date date) IS 'Antes de 20/08/2026 preserva a apuracao mensal historica; a partir da vigencia usa 10+ alunos, 30 dias corridos sem falta e nenhum TEACHER_NO_SHOW em aberto.';


--
-- Name: teacher_turbo_on_legacy_monthly(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_on_legacy_monthly(p_teacher uuid, p_date date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  WITH janela AS (
    SELECT date_trunc('month', p_date)::date - INTERVAL '1 month' AS ini,
           (date_trunc('month', p_date) + INTERVAL '1 month')::date AS fim
  )
  SELECT
    (SELECT count(*) FROM teacher_carteira(p_teacher)) >= 10
    AND EXISTS (
      SELECT 1 FROM class_logs cl WHERE cl.teacher_id = p_teacher
        AND cl.class_date < date_trunc('month', p_date)::date
    )
    AND EXISTS (
      SELECT 1 FROM class_logs cl, janela j WHERE cl.teacher_id = p_teacher
        AND cl.class_date >= date_trunc('month', p_date)::date AND cl.class_date < j.fim
        AND cl.presence NOT IN ('TEACHER_ABSENCE','Falta do Professor')
    )
    AND NOT EXISTS (
      SELECT 1 FROM class_logs cl, janela j WHERE cl.teacher_id = p_teacher
        AND cl.class_date >= j.ini AND cl.class_date < j.fim
        AND cl.presence IN ('TEACHER_ABSENCE','Falta do Professor')
    )
    AND NOT EXISTS (
      SELECT 1 FROM class_logs cl, janela j WHERE cl.teacher_id = p_teacher
        AND cl.class_date >= j.ini AND cl.class_date < j.fim
        AND COALESCE(cl.payment_hold, false)
    )
    AND NOT EXISTS (
      SELECT 1 FROM attendance_confirmations ac, janela j WHERE ac.teacher_id = p_teacher
        AND ac.class_date >= j.ini AND ac.class_date < j.fim
        AND ac.status IN ('CONFLICT','RESOLVED_UNPAID')
    );
$$;


--
-- Name: teacher_turbo_refresh_eligibility(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_refresh_eligibility(p_teacher uuid, p_effective_on date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_state public.teacher_turbo_state%ROWTYPE;
  v_students integer;
  v_required integer;
  v_on date := COALESCE(p_effective_on, public.teacher_turbo_business_date());
BEGIN
  PERFORM public.teacher_turbo_ensure_state(p_teacher);

  SELECT * INTO v_state
  FROM public.teacher_turbo_state
  WHERE teacher_id = p_teacher
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_required := CASE WHEN v_state.tenant_id = 'school-wise-wolf' AND v_on >= DATE '2026-09-09' THEN 7 ELSE 10 END;

  SELECT public.teacher_turbo_student_count(p_teacher) INTO v_students;

  IF v_students >= v_required AND v_state.students_eligible_since IS NULL THEN
    UPDATE public.teacher_turbo_state
       SET students_active = v_students,
           students_eligible_since = v_on,
           updated_at = now()
     WHERE teacher_id = p_teacher;

    PERFORM public.teacher_turbo_add_event(
      p_teacher, v_state.tenant_id, 'STUDENT_THRESHOLD_REACHED', v_on,
      NULL, NULL, auth.uid(),
      jsonb_build_object('students_active', v_students, 'students_required', v_required)
    );
  ELSIF v_students < v_required AND v_state.students_eligible_since IS NOT NULL THEN
    UPDATE public.teacher_turbo_state
       SET students_active = v_students,
           students_eligible_since = NULL,
           updated_at = now()
     WHERE teacher_id = p_teacher;

    PERFORM public.teacher_turbo_add_event(
      p_teacher, v_state.tenant_id, 'STUDENT_THRESHOLD_LOST', v_on,
      NULL, NULL, auth.uid(),
      jsonb_build_object('students_active', v_students, 'students_required', v_required)
    );
  ELSE
    UPDATE public.teacher_turbo_state
       SET students_active = v_students,
           updated_at = now()
     WHERE teacher_id = p_teacher;
  END IF;
END;
$$;


--
-- Name: teacher_turbo_reset(uuid, date, text, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_reset(p_teacher uuid, p_absence_on date, p_event_type text, p_source_type text, p_source_id uuid, p_actor uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_state public.teacher_turbo_state%ROWTYPE;
BEGIN
  IF p_absence_on IS NULL OR p_event_type NOT IN ('ABSENCE_RECORDED', 'ABSENCE_CONFIRMED') THEN
    RETURN;
  END IF;

  PERFORM public.teacher_turbo_ensure_state(p_teacher);

  SELECT * INTO v_state
  FROM public.teacher_turbo_state
  WHERE teacher_id = p_teacher
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  PERFORM public.teacher_turbo_add_event(
    p_teacher, v_state.tenant_id, p_event_type, p_absence_on,
    p_source_type, p_source_id, p_actor, p_metadata
  );

  -- Evento futuro fica auditado, mas so passa a compor o snapshot quando a data
  -- chegar. Evento antigo nunca anda o contador atual para tras.
  IF p_absence_on <= public.teacher_turbo_business_date() THEN
    UPDATE public.teacher_turbo_state
       SET initial_anchor_on = LEAST(initial_anchor_on, p_absence_on),
           streak_anchor_on = GREATEST(streak_anchor_on, p_absence_on),
           last_confirmed_absence_on = GREATEST(
             COALESCE(last_confirmed_absence_on, p_absence_on),
             p_absence_on
           ),
           updated_at = now()
     WHERE teacher_id = p_teacher;
  END IF;
END;
$$;


--
-- Name: teacher_turbo_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_status(p_teacher uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_jwt_role text;
  v_tenant text;
  v_teacher_tenant text;
BEGIN
  v_jwt_role := COALESCE(
    NULLIF(current_setting('request.jwt.claims', true), '')::jsonb->>'role',
    ''
  );

  IF v_jwt_role = 'service_role' THEN
    v_role := 'SUPER_ADMIN';
  ELSE
    v_role := public._my_role();
    v_tenant := public._my_tenant_id();
  END IF;

  IF NOT COALESCE(v_role IN ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN'), false) THEN
    RETURN jsonb_build_object('active', false, 'status', 'UNKNOWN', 'blocked_by', 'sem_permissao');
  END IF;

  SELECT p.tenant_id INTO v_teacher_tenant
  FROM public.profiles p
  WHERE p.id = p_teacher;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('active', false, 'status', 'UNKNOWN', 'blocked_by', 'professor_invalido');
  END IF;

  IF v_role <> 'SUPER_ADMIN' AND v_teacher_tenant IS DISTINCT FROM v_tenant THEN
    RETURN jsonb_build_object('active', false, 'status', 'UNKNOWN', 'blocked_by', 'sem_permissao');
  END IF;

  RETURN public.teacher_turbo_status_at(p_teacher, public.teacher_turbo_business_date());
END;
$$;


--
-- Name: FUNCTION teacher_turbo_status(p_teacher uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.teacher_turbo_status(p_teacher uuid) IS 'Estado atual auditavel do Turbo: carteira, ofensiva, dias restantes/ativos, ultima falta e suspensoes.';


--
-- Name: teacher_turbo_status_at(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_status_at(p_teacher uuid, p_date date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_state public.teacher_turbo_state%ROWTYPE;
  v_students integer := 0;
  v_required integer;
  v_anchor date;
  v_last_absence date;
  v_threshold_event text;
  v_eligible_since date;
  v_students_eligible boolean := false;
  v_days_clean integer := 0;
  v_days_to_activate integer := 30;
  v_active_since date;
  v_active boolean := false;
  v_active_days integer := 0;
  v_suspensions integer := 0;
  v_suspended_at timestamptz;
  v_absences_this_month integer := 0;
  v_absences_last_month integer := 0;
  v_blocked_by text;
BEGIN
  IF p_date IS NULL THEN
    RETURN jsonb_build_object('active', false, 'blocked_by', 'data_invalida');
  END IF;

  SELECT * INTO v_state
  FROM public.teacher_turbo_state
  WHERE teacher_id = p_teacher;

  IF NOT FOUND THEN
    SELECT p.id, p.tenant_id,
           LEAST(p_date, COALESCE(p.start_date, p.created_at::date, p_date)),
           LEAST(p_date, COALESCE(p.start_date, p.created_at::date, p_date)),
           0, NULL::date, NULL::date, now(), now()
      INTO v_state
    FROM public.profiles p
    WHERE p.id = p_teacher AND p.role = 'TEACHER';

    IF NOT FOUND THEN
      RETURN jsonb_build_object('active', false, 'blocked_by', 'professor_invalido');
    END IF;
  END IF;

  v_required := CASE WHEN v_state.tenant_id = 'school-wise-wolf' AND p_date >= DATE '2026-09-09' THEN 7 ELSE 10 END;

  SELECT public.teacher_turbo_student_count(p_teacher) INTO v_students;

  SELECT max(e.effective_on) INTO v_last_absence
  FROM public.teacher_turbo_events e
  WHERE e.teacher_id = p_teacher
    AND e.tenant_id = v_state.tenant_id
    AND e.event_type IN ('ABSENCE_RECORDED', 'ABSENCE_CONFIRMED')
    AND e.effective_on <= p_date;

  v_anchor := GREATEST(v_state.initial_anchor_on, COALESCE(v_last_absence, v_state.initial_anchor_on));
  v_days_clean := GREATEST(0, p_date - v_anchor);
  v_days_to_activate := GREATEST(0, 30 - v_days_clean);

  -- Para datas historicas, o ultimo evento de limiar e a fonte. Para hoje/futuro,
  -- a carteira atual e soberana e students_eligible_since marca o inicio do ciclo.
  IF p_date >= public.teacher_turbo_business_date() THEN
    v_students_eligible := v_students >= v_required;
    v_eligible_since := CASE WHEN v_students_eligible THEN v_state.students_eligible_since END;
  ELSE
    SELECT e.event_type, e.effective_on
      INTO v_threshold_event, v_eligible_since
    FROM public.teacher_turbo_events e
    WHERE e.teacher_id = p_teacher
      AND e.tenant_id = v_state.tenant_id
      AND e.event_type IN ('STUDENT_THRESHOLD_REACHED', 'STUDENT_THRESHOLD_LOST')
      AND e.effective_on <= p_date
    ORDER BY e.effective_on DESC, e.happened_at DESC, e.id DESC
    LIMIT 1;

    v_students_eligible := COALESCE(
      v_threshold_event = 'STUDENT_THRESHOLD_REACHED',
      false
    );
    IF v_students_eligible IS NOT TRUE THEN
      v_eligible_since := NULL;
    END IF;
  END IF;

  -- Defesa para professor criado entre a migration e o primeiro refresh.
  IF v_students_eligible AND v_eligible_since IS NULL THEN
    v_eligible_since := p_date;
  END IF;

  SELECT count(*)::integer, min(d.suspended_at)
    INTO v_suspensions, v_suspended_at
  FROM public.teacher_turbo_disputes d
  WHERE d.teacher_id = p_teacher
    AND d.tenant_id = v_state.tenant_id
    AND d.status = 'OPEN'
    AND (d.suspended_at AT TIME ZONE 'America/Sao_Paulo')::date <= p_date;

  IF v_students_eligible AND v_days_clean >= 30 THEN
    v_active_since := GREATEST(v_anchor + 30, v_eligible_since);
  END IF;

  IF v_eligible_since IS NOT NULL THEN
    v_days_to_activate := GREATEST(
      v_days_to_activate,
      GREATEST(0, v_eligible_since - p_date)
    );
  END IF;

  v_active := v_active_since IS NOT NULL
              AND v_active_since <= p_date
              AND v_suspensions = 0;
  -- Uma inocentacao recompõe o ciclo como se a suspensao temporaria nunca o
  -- tivesse interrompido; por isso o tempo ativo continua visivel no intervalo.
  IF v_active_since IS NOT NULL AND v_active_since <= p_date THEN
    v_active_days := GREATEST(0, p_date - v_active_since);
  END IF;

  SELECT count(DISTINCT e.effective_on)::integer INTO v_absences_this_month
  FROM public.teacher_turbo_events e
  WHERE e.teacher_id = p_teacher
    AND e.tenant_id = v_state.tenant_id
    AND e.event_type IN ('ABSENCE_RECORDED', 'ABSENCE_CONFIRMED')
    AND e.effective_on >= date_trunc('month', p_date)::date
    AND e.effective_on < (date_trunc('month', p_date) + interval '1 month')::date;

  SELECT count(DISTINCT e.effective_on)::integer INTO v_absences_last_month
  FROM public.teacher_turbo_events e
  WHERE e.teacher_id = p_teacher
    AND e.tenant_id = v_state.tenant_id
    AND e.event_type IN ('ABSENCE_RECORDED', 'ABSENCE_CONFIRMED')
    AND e.effective_on >= (date_trunc('month', p_date) - interval '1 month')::date
    AND e.effective_on < date_trunc('month', p_date)::date;

  v_blocked_by := CASE
    WHEN v_suspensions > 0 THEN 'conflito'
    WHEN v_students_eligible IS NOT TRUE THEN 'carteira'
    WHEN v_days_clean < 30 OR v_active_since > p_date THEN 'ofensiva'
    ELSE NULL
  END;

  RETURN jsonb_build_object(
    'active', v_active,
    'status', CASE
      WHEN v_suspensions > 0 THEN 'SUSPENDED'
      WHEN v_students_eligible IS NOT TRUE THEN 'INELIGIBLE_STUDENTS'
      WHEN v_days_clean < 30 OR v_active_since > p_date THEN 'BUILDING'
      ELSE 'ACTIVE'
    END,
    'scope', 'rolling_30_days',
    'students_active', v_students,
    'students_required', v_required,
    'students_missing', GREATEST(0, v_required - v_students),
    'students_eligible_since', v_eligible_since,
    'clean_since', v_anchor,
    'days_clean', v_days_clean,
    'days_to_activate', v_days_to_activate,
    'active_since', v_active_since,
    'active_days', v_active_days,
    'last_absence', v_last_absence,
    'last_confirmed_absence_on', v_last_absence,
    'suspensions_open', v_suspensions,
    'suspension_since', v_suspended_at,
    -- aliases mantidos para consumidores antigos
    'conflicts_open', v_suspensions,
    'absences_this_month', v_absences_this_month,
    'absences_last_month', v_absences_last_month,
    'blocked_by', v_blocked_by
  );
END;
$$;


--
-- Name: teacher_turbo_student_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_student_count(p_teacher uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT count(*)::integer
  FROM public.teacher_carteira(p_teacher) c
  JOIN public.profiles t
    ON t.id = p_teacher
   AND t.role = 'TEACHER'
  JOIN public.profiles s
    ON s.id = c.student_id
   AND s.tenant_id = t.tenant_id
  WHERE EXISTS (
    SELECT 1
    FROM public.bookings b
    WHERE b.teacher_id = t.id
      AND b.student_id = s.id
      AND b.tenant_id = t.tenant_id
      AND COALESCE(b.status, 'SCHEDULED') = 'SCHEDULED'
  );
$$;


--
-- Name: teacher_turbo_sync_attendance_dispute(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teacher_turbo_sync_attendance_dispute(p_confirmation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  requested public.attendance_confirmations%rowtype;
  c public.attendance_confirmations%rowtype;
  v_canonical_id uuid;
  v_log_presence text;
  v_dispute_status text;
  v_verdict text;
  v_suspended_at timestamptz;
  v_resolution_at timestamptz;
  v_effective_on date;
  v_reported_class_date date;
  v_existing_dispute public.teacher_turbo_disputes%rowtype;
begin
  select ac.*
    into requested
    from public.attendance_confirmations ac
   where ac.id = p_confirmation_id;
  if not found then return; end if;

  v_canonical_id := coalesce(requested.canonical_confirmation_id, requested.id);
  select ac.*
    into c
    from public.attendance_confirmations ac
   where ac.id = v_canonical_id;
  if not found then return; end if;

  if c.teacher_id is null
     or c.tenant_id is null
     or not exists (
       select 1
         from public.profiles p
        where p.id = c.teacher_id
          and p.role = 'TEACHER'
          and p.tenant_id = c.tenant_id
     ) then
    return;
  end if;

  -- Close any legacy per-member OPEN rows. The canonical row below is the only
  -- row allowed to represent the logical session.
  update public.teacher_turbo_disputes d
     set status = 'DISMISSED',
         verdict = 'CANCELLED',
         resolved_at = coalesce(c.resolved_at, now()),
         resolved_by = c.resolved_by,
         resolution_note = 'Consolidada na confirmacao canonica da sessao',
         updated_at = now()
   where d.confirmation_id in (
     select ac.id
       from public.attendance_confirmations ac
      where coalesce(ac.canonical_confirmation_id, ac.id) = v_canonical_id
        and ac.id <> v_canonical_id
   )
     and d.status = 'OPEN';

  if requested.id <> v_canonical_id then
    return;
  end if;

  if c.class_log_id is not null then
    select cl.presence
      into v_log_presence
      from public.class_logs cl
     where cl.id = c.class_log_id
       and cl.tenant_id = c.tenant_id
       and cl.teacher_id = c.teacher_id
       and cl.student_id is not distinct from c.student_id;
    if not found then return; end if;
  end if;

  -- A correction/removal, a non-hard status, or a conflict whose edit window
  -- is still open must leave no preventive suspension behind.
  if c.student_response is distinct from 'TEACHER_NO_SHOW'
     or (
       c.status not in ('CONFLICT', 'RESOLVED_PAID', 'RESOLVED_UNPAID', 'CANCELLED')
       and not (
         c.status = 'CONFIRMED'
         and coalesce(c.teacher_reported, v_log_presence)
             in ('TEACHER_ABSENCE', 'Falta do Professor')
       )
     )
     or (
       c.status = 'CONFLICT'
       and c.response_editable_until is not null
       and c.response_editable_until > now()
     ) then
    v_resolution_at := coalesce(c.resolved_at, now());

    update public.teacher_turbo_disputes d
       set status = 'DISMISSED',
           verdict = 'CANCELLED',
           resolved_at = v_resolution_at,
           resolved_by = c.resolved_by,
           resolution_note = coalesce(
             nullif(c.admin_resolution, ''),
             case
               when c.status = 'CONFLICT'
                 then 'Aguardando encerramento da janela de correcao'
               when c.status = 'CANCELLED'
                 then 'Confirmacao cancelada'
               else 'Relato sem conflito financeiro reconciliado'
             end
           ),
           updated_at = now()
     where d.confirmation_id = v_canonical_id
       and d.teacher_id = c.teacher_id
       and d.tenant_id = c.tenant_id
       and d.status = 'OPEN'
    returning d.* into v_existing_dispute;

    if found then
      perform public.teacher_turbo_add_event(
        c.teacher_id,
        c.tenant_id,
        'DISPUTE_DISMISSED',
        (v_resolution_at at time zone 'America/Sao_Paulo')::date,
        'attendance_confirmation',
        v_canonical_id,
        c.resolved_by,
        jsonb_build_object('verdict', 'CANCELLED', 'reason', 'not_a_mature_hard_conflict')
      );
    end if;
    return;
  end if;

  perform public.teacher_turbo_ensure_state(c.teacher_id);

  v_suspended_at := coalesce(c.response_editable_until, c.responded_at, now());
  v_effective_on := (v_suspended_at at time zone 'America/Sao_Paulo')::date;
  v_reported_class_date := coalesce(c.class_date, v_effective_on);

  if c.status = 'RESOLVED_PAID' then
    v_dispute_status := 'DISMISSED';
    v_verdict := 'TEACHER_PRESENT';
    v_resolution_at := coalesce(c.resolved_at, now());
  elsif c.status = 'CANCELLED' then
    v_dispute_status := 'DISMISSED';
    v_verdict := 'CANCELLED';
    v_resolution_at := coalesce(c.resolved_at, now());
  elsif c.status = 'RESOLVED_UNPAID'
        or c.teacher_reported in ('TEACHER_ABSENCE', 'Falta do Professor')
        or v_log_presence in ('TEACHER_ABSENCE', 'Falta do Professor') then
    v_dispute_status := 'CONFIRMED_ABSENCE';
    v_verdict := 'TEACHER_ABSENT';
    v_resolution_at := coalesce(c.resolved_at, c.responded_at, now());
  else
    -- The only remaining open path is a mature canonical CONFLICT.
    v_dispute_status := 'OPEN';
    v_verdict := null;
    v_resolution_at := null;
  end if;

  insert into public.teacher_turbo_disputes as d (
    confirmation_id, teacher_id, tenant_id, reported_class_date,
    suspended_at, status, verdict, resolved_at, resolved_by,
    resolution_note, updated_at
  ) values (
    v_canonical_id, c.teacher_id, c.tenant_id, v_reported_class_date,
    v_suspended_at, v_dispute_status, v_verdict, v_resolution_at,
    case when v_dispute_status = 'OPEN' then null else c.resolved_by end,
    case when v_dispute_status = 'OPEN' then null else c.admin_resolution end,
    now()
  )
  on conflict (confirmation_id) do update set
    teacher_id = excluded.teacher_id,
    tenant_id = excluded.tenant_id,
    reported_class_date = excluded.reported_class_date,
    suspended_at = least(d.suspended_at, excluded.suspended_at),
    status = excluded.status,
    verdict = excluded.verdict,
    resolved_at = excluded.resolved_at,
    resolved_by = excluded.resolved_by,
    resolution_note = excluded.resolution_note,
    updated_at = now();

  perform public.teacher_turbo_add_event(
    c.teacher_id, c.tenant_id, 'DISPUTE_REPORTED', v_effective_on,
    'attendance_confirmation', v_canonical_id, null,
    jsonb_build_object(
      'class_date', v_reported_class_date,
      'student_response', c.student_response,
      'teacher_reported', c.teacher_reported,
      'session_key', c.session_key
    )
  );

  if v_dispute_status = 'DISMISSED' then
    perform public.teacher_turbo_add_event(
      c.teacher_id, c.tenant_id, 'DISPUTE_DISMISSED',
      (v_resolution_at at time zone 'America/Sao_Paulo')::date,
      'attendance_confirmation', v_canonical_id, c.resolved_by,
      jsonb_build_object('verdict', v_verdict, 'note', c.admin_resolution)
    );
  elsif v_dispute_status = 'CONFIRMED_ABSENCE' then
    perform public.teacher_turbo_reset(
      c.teacher_id, v_reported_class_date, 'ABSENCE_CONFIRMED',
      'attendance_confirmation', v_canonical_id, c.resolved_by,
      jsonb_build_object('verdict', v_verdict, 'note', c.admin_resolution)
    );
  end if;
end;
$$;


