--
-- Name: trg_teacher_turbo_booking(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_teacher_turbo_booking() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
BEGIN
  -- Uma transferencia A->B toca dois snapshots. Ordenar UUID impede que duas
  -- transferencias opostas adquiram os mesmos row locks em ordem inversa.
  FOR r IN
    SELECT DISTINCT x.teacher_id
    FROM (
      VALUES
        (CASE WHEN TG_OP <> 'INSERT' THEN OLD.teacher_id END),
        (CASE WHEN TG_OP <> 'DELETE' THEN NEW.teacher_id END)
    ) AS x(teacher_id)
    WHERE x.teacher_id IS NOT NULL
    ORDER BY x.teacher_id
  LOOP
    PERFORM public.teacher_turbo_refresh_eligibility(r.teacher_id);
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_teacher_turbo_class_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_teacher_turbo_class_log() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.teacher_id IS NOT NULL
     AND NEW.class_date IS NOT NULL
     AND NEW.presence IN ('TEACHER_ABSENCE', 'Falta do Professor')
     AND EXISTS (
       SELECT 1
       FROM public.profiles p
       WHERE p.id = NEW.teacher_id
         AND p.role = 'TEACHER'
         AND p.tenant_id = NEW.tenant_id
     )
     AND (
       TG_OP = 'INSERT'
       OR OLD.presence IS DISTINCT FROM NEW.presence
       OR OLD.teacher_id IS DISTINCT FROM NEW.teacher_id
       OR OLD.class_date IS DISTINCT FROM NEW.class_date
     ) THEN
    PERFORM public.teacher_turbo_reset(
      NEW.teacher_id, NEW.class_date, 'ABSENCE_RECORDED',
      'class_log', NEW.id, auth.uid(),
      jsonb_build_object('presence', NEW.presence)
    );
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_teacher_turbo_non_billable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_teacher_turbo_non_billable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT DISTINCT b.teacher_id
    FROM public.bookings b
    WHERE b.teacher_id IS NOT NULL
      AND b.student_id IN (
        CASE WHEN TG_OP <> 'INSERT' THEN OLD.profile_id ELSE NULL END,
        CASE WHEN TG_OP <> 'DELETE' THEN NEW.profile_id ELSE NULL END
      )
    ORDER BY b.teacher_id
  LOOP
    PERFORM public.teacher_turbo_refresh_eligibility(r.teacher_id);
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_teacher_turbo_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_teacher_turbo_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT DISTINCT affected.teacher_id
    FROM (
      SELECT CASE
        WHEN TG_OP <> 'INSERT' AND OLD.role = 'TEACHER' THEN OLD.id
      END AS teacher_id
      UNION ALL
      SELECT CASE
        WHEN TG_OP <> 'DELETE' AND NEW.role = 'TEACHER' THEN NEW.id
      END
      UNION ALL
      SELECT b.teacher_id
      FROM public.bookings b
      WHERE b.teacher_id IS NOT NULL
        AND b.student_id IN (
          CASE WHEN TG_OP <> 'INSERT' THEN OLD.id ELSE NULL END,
          CASE WHEN TG_OP <> 'DELETE' THEN NEW.id ELSE NULL END
        )
    ) affected
    WHERE affected.teacher_id IS NOT NULL
    ORDER BY affected.teacher_id
  LOOP
    IF TG_OP <> 'DELETE'
       AND NEW.role = 'TEACHER'
       AND r.teacher_id = NEW.id THEN
      PERFORM public.teacher_turbo_ensure_state(r.teacher_id);
    END IF;
    PERFORM public.teacher_turbo_refresh_eligibility(r.teacher_id);
  END LOOP;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trial_followups(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trial_followups() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object('appointment_id',a.id,'student_name',a.student_name,'phone',a.student_phone,'tenant_id',a.tenant_id)), '[]'::jsonb)
  FROM appointments a
  WHERE a.type = 'experimental'
    AND a.start_time::date = current_date - 2
    AND COALESCE(a.status,'scheduled') NOT IN ('cancelled','no_show')
    AND a.student_phone IS NOT NULL AND a.student_phone <> ''
    AND NOT EXISTS (
      SELECT 1 FROM profiles p WHERE p.role='STUDENT' AND p.tenant_id = a.tenant_id
        AND regexp_replace(p.phone,'\D','','g') = regexp_replace(a.student_phone,'\D','','g')
    );
$$;


--
-- Name: trigger_daily_automations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_daily_automations() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE request_id bigint; service_key text;
BEGIN
  SELECT decrypted_secret INTO service_key FROM vault.decrypted_secrets WHERE name='wisewolf_service_role_key' LIMIT 1;
  IF service_key IS NULL OR service_key='' THEN RAISE WARNING 'service key ausente'; RETURN -1; END IF;
  SELECT net.http_post(
    url := 'http://kong:8000/functions/v1/daily-automations',
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||service_key),
    body := '{}'::jsonb, timeout_milliseconds := 120000
  ) INTO request_id;
  RETURN request_id;
END; $$;


