--
-- Name: trigger_funnel_sweeper(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_funnel_sweeper() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault', 'net', 'pg_temp'
    AS $$
DECLARE
  request_id bigint;
  service_key text;
BEGIN
  SELECT decrypted_secret
    INTO service_key
    FROM vault.decrypted_secrets
   WHERE name = 'wisewolf_service_role_key'
   LIMIT 1;

  IF nullif(service_key, '') IS NULL THEN
    RAISE WARNING 'Vault secret wisewolf_service_role_key not set';
    RETURN -1;
  END IF;

  SELECT net.http_post(
    url := 'http://kong:8000/functions/v1/funnel-sweeper',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || service_key
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 55000
  )
  INTO request_id;

  RETURN request_id;
END;
$$;


