--
-- Name: trigger_hr_backfill_drain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_hr_backfill_drain() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE request_id bigint; service_key text; restantes int; nruns int;
BEGIN
  SELECT count(*) INTO restantes FROM job_applications WHERE ai_screened_at IS NULL;
  UPDATE _hr_drain_state SET runs = runs + 1 WHERE id = 1;
  SELECT runs INTO nruns FROM _hr_drain_state WHERE id = 1;
  IF restantes = 0 OR nruns > 60 THEN
    PERFORM cron.unschedule('wisewolf-hr-backfill-drain');
    RETURN 0;
  END IF;
  SELECT decrypted_secret INTO service_key FROM vault.decrypted_secrets WHERE name='wisewolf_service_role_key' LIMIT 1;
  SELECT net.http_post(
    url := 'http://kong:8000/functions/v1/hr-ai-screening',
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||service_key),
    body := '{"mode":"backfill","batch":2}'::jsonb, timeout_milliseconds := 80000
  ) INTO request_id;
  RETURN request_id;
END; $$;


--
-- Name: trigger_hub_fulfillment_worker(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_hub_fulfillment_worker() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_service_key text;
  v_request_id bigint;
begin
  select secret.decrypted_secret
  into v_service_key
  from vault.decrypted_secrets as secret
  where secret.name = 'wisewolf_service_role_key'
  limit 1;

  if v_service_key is null or v_service_key = '' then
    raise warning 'wisewolf_service_role_key is not configured';
    return -1;
  end if;

  select net.http_post(
    url := 'http://kong:8000/functions/v1/process-hub-fulfillment',
    headers := pg_catalog.jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body := '{}'::jsonb,
    timeout_milliseconds := 30000
  ) into v_request_id;

  return v_request_id;
end;
$$;


