--
-- Name: trigger_teacher_closing_recalc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trigger_teacher_closing_recalc() RETURNS bigint[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'vault'
    AS $$
DECLARE service_key text; m text; request_id bigint; ids bigint[] := '{}';
BEGIN
  SELECT decrypted_secret INTO service_key FROM vault.decrypted_secrets WHERE name='wisewolf_service_role_key' LIMIT 1;
  IF service_key IS NULL OR service_key='' THEN RAISE WARNING 'service key ausente'; RETURN NULL; END IF;
  FOREACH m IN ARRAY ARRAY[
    to_char(current_date - interval '1 month','YYYY-MM'),
    to_char(current_date - interval '2 month','YYYY-MM')
  ] LOOP
    SELECT net.http_post(
      url := 'http://kong:8000/functions/v1/monthly-teacher-closing',
      headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||service_key),
      body := jsonb_build_object('month', m), timeout_milliseconds := 120000
    ) INTO request_id;
    ids := ids || request_id;
  END LOOP;
  RETURN ids;
END; $$;


