--
-- Name: undo_payment_not_revenue(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.undo_payment_not_revenue(p_payment_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; v_reason text; v_anterior text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;

  SELECT sp.exclusion_reason INTO v_reason FROM student_payments sp
   WHERE sp.id = p_payment_id AND sp.tenant_id = v_tenant AND sp.status = 'NAO_RECEITA';
  IF v_reason IS NULL THEN RETURN jsonb_build_object('error','nao_esta_excluido'); END IF;

  v_anterior := substring(v_reason from '\[status anterior: ([^\]]+)\]');
  IF v_anterior IS NULL THEN v_anterior := 'RECEIVED'; END IF;

  UPDATE student_payments
     SET status = v_anterior, exclusion_reason = NULL, updated_at = now()
   WHERE id = p_payment_id AND tenant_id = v_tenant;
  UPDATE financial_transactions
     SET category = 'MENSALIDADE'
   WHERE student_payment_id = p_payment_id AND type = 'ENTRADA';

  RETURN jsonb_build_object('ok', true, 'status_restaurado', v_anterior);
END;
$$;


--
-- Name: update_material(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_material(p_id uuid, p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  target_tenant_id text;
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  SELECT material.tenant_id
  INTO target_tenant_id
  FROM public.pedagogical_materials AS material
  WHERE material.id = p_id;
  IF NOT FOUND THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'nao_encontrado'
    );
  END IF;
  IF NOT private.legacy_role_rpc_target_allowed(target_tenant_id) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  RETURN public.update_material_unchecked(p_id, p);
END;
$$;


--
-- Name: update_material_unchecked(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_material_unchecked(p_id uuid, p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; m_tenant text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id=auth.uid();
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;
  SELECT tenant_id INTO m_tenant FROM pedagogical_materials WHERE id=p_id;
  IF m_tenant IS NULL THEN RETURN jsonb_build_object('ok',false,'error','nao_encontrado'); END IF;
  IF v_role='SCHOOL_ADMIN' AND m_tenant<>v_tenant THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;
  UPDATE pedagogical_materials SET
    title = COALESCE(NULLIF(p->>'title',''), title),
    niche = COALESCE(NULLIF(p->>'niche',''), niche),
    level_tag = COALESCE(NULLIF(p->>'level_tag',''), level_tag),
    type = COALESCE(NULLIF(p->>'type',''), type),
    category = COALESCE(NULLIF(p->>'category',''), category)
  WHERE id=p_id;
  RETURN jsonb_build_object('ok', true);
END;
$$;


