--
-- Name: update_student_pedagogical_profile(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_student_pedagogical_profile(p_student_id uuid, p_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid := auth.uid();
  v_actor record;
  v_student record;
  v_is_director boolean;
  v_status_res jsonb;
  v_placement_res jsonb;
  v_requested_module text;
  v_requested_status text;
begin
  if v_actor_id is null or p_student_id is null or p_data is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;

  select profile.role, profile.tenant_id
    into v_actor
    from public.profiles as profile
   where profile.id = v_actor_id;

  if not found or v_actor.role not in ('TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') then
    raise exception using errcode = '42501', message = 'staff_role_required';
  end if;

  select
    profile.id,
    profile.role,
    profile.tenant_id,
    profile.module,
    profile.status,
    profile.lifecycle_status,
    profile.accepted_at,
    profile.documentation_status
    into v_student
    from public.profiles as profile
   where profile.id = p_student_id
   for update;

  if not found or v_student.role <> 'STUDENT' or v_student.tenant_id is null then
    raise exception using errcode = '42501', message = 'student_not_found';
  end if;

  v_is_director := v_actor.role in ('SCHOOL_ADMIN', 'SUPER_ADMIN');

  if not v_is_director then
    if v_actor.tenant_id is null or v_actor.tenant_id <> v_student.tenant_id then
      raise exception using errcode = '42501', message = 'student_not_available';
    end if;
    if not public._teacher_can_access_student(p_student_id, v_student.tenant_id) then
      raise exception using errcode = '42501', message = 'teacher_student_link_required';
    end if;

    -- Blindagem estrita: Professor NÃO PODE alterar CPF, Email, Preço ou Endereço
    if p_data ? 'cpf' or p_data ? 'email' or p_data ? 'monthly_fee' or p_data ? 'due_day' 
       or p_data ? 'address' or p_data ? 'postal_code' or p_data ? 'guardian_cpf' 
       or p_data ? 'guardian_email' or p_data ? 'status_financial' or p_data ? 'professor_id' then
      raise exception using errcode = '42501', message = 'teachers_cannot_modify_sensitive_or_financial_fields';
    end if;
  end if;

  -- 1. Atualizar campos pedagógicos seguros e permitidos
  update public.profiles
     set full_name = case 
           when p_data ? 'full_name' and pg_catalog.length(pg_catalog.btrim(p_data ->> 'full_name')) > 0 
           then pg_catalog.btrim(p_data ->> 'full_name')
           else public.profiles.full_name 
         end,
         phone = case 
           when p_data ? 'phone' then nullif(pg_catalog.btrim(p_data ->> 'phone'), '')
           else public.profiles.phone 
         end,
         attendance_phone = case 
           when p_data ? 'attendance_phone' then nullif(pg_catalog.btrim(p_data ->> 'attendance_phone'), '')
           else public.profiles.attendance_phone 
         end,
         meeting_link = case 
           when p_data ? 'meeting_link' then nullif(pg_catalog.btrim(p_data ->> 'meeting_link'), '')
           else public.profiles.meeting_link 
         end,
         occupation = case 
           when p_data ? 'occupation' then nullif(pg_catalog.btrim(p_data ->> 'occupation'), '')
           else public.profiles.occupation 
         end,
         interests = case 
           when p_data ? 'interests' and jsonb_typeof(p_data -> 'interests') = 'array'
           then (select array_agg(value::text) from jsonb_array_elements_text(p_data -> 'interests'))
           else public.profiles.interests 
         end,
         private_notes = case 
           when p_data ? 'private_notes' then nullif(pg_catalog.btrim(p_data ->> 'private_notes'), '')
           else public.profiles.private_notes 
         end,
         fixed_schedule = case 
           when p_data ? 'fixed_schedule' then nullif(pg_catalog.btrim(p_data ->> 'fixed_schedule'), '')
           else public.profiles.fixed_schedule 
         end,
         is_kids = case 
           when p_data ? 'is_kids' then (p_data ->> 'is_kids')::boolean
           else public.profiles.is_kids 
         end
   where id = p_student_id;

  -- 2. Atualizar campos exclusivos de Diretor (se enviados)
  if v_is_director then
    -- Se contrato não foi aprovado/aceito, permite editar dados cadastrais e financeiros
    if not (coalesce(v_student.accepted_at, null) is not null or v_student.documentation_status = 'APPROVED') then
      update public.profiles
         set cpf = case when p_data ? 'cpf' then nullif(regexp_replace(p_data ->> 'cpf', '[^0-9]', '', 'g'), '') else public.profiles.cpf end,
             postal_code = case when p_data ? 'postal_code' then nullif(p_data ->> 'postal_code', '') else public.profiles.postal_code end,
             address = case when p_data ? 'address' then nullif(p_data ->> 'address', '') else public.profiles.address end,
             address_number = case when p_data ? 'address_number' then nullif(p_data ->> 'address_number', '') else public.profiles.address_number end,
             monthly_fee = case when p_data ? 'monthly_fee' then (p_data ->> 'monthly_fee')::numeric else public.profiles.monthly_fee end,
             due_day = case when p_data ? 'due_day' then (p_data ->> 'due_day')::integer else public.profiles.due_day end
       where id = p_student_id;
    end if;

    if p_data ? 'professor_id' then
      update public.profiles
         set professor_id = nullif(p_data ->> 'professor_id', '')::uuid
       where id = p_student_id;
    end if;
  end if;

  -- 3. Atualizar Status se solicitado
  if p_data ? 'status' and pg_catalog.btrim(coalesce(p_data ->> 'status', '')) <> '' then
    v_requested_status := pg_catalog.btrim(p_data ->> 'status');
    v_status_res := public.set_student_academic_status(
      p_student_id,
      v_requested_status,
      coalesce(p_data ->> 'status_reason', 'Atualizado no perfil do aluno')
    );
  end if;

  -- 4. Atualizar Nível se solicitado
  if p_data ? 'module' and pg_catalog.btrim(coalesce(p_data ->> 'module', '')) <> '' then
    v_requested_module := pg_catalog.upper(pg_catalog.btrim(p_data ->> 'module'));
    if v_requested_module is distinct from v_student.module then
      v_placement_res := public.set_student_pedagogical_placement(
        p_student_id,
        v_requested_module,
        coalesce(p_data ->> 'placement_reason', 'Ajuste de nível autorizado no perfil do aluno')
      );
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'success', true,
    'studentId', p_student_id,
    'statusUpdate', v_status_res,
    'placementUpdate', v_placement_res
  );
end;
$$;


--
-- Name: update_trial_outcome_secure(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_trial_outcome_secure(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_tenant_id text;
  v_actor_role text;
  v_action text;
  v_trial_status text;
  v_request_payload jsonb := coalesce(p_payload, '{}'::jsonb);
  v_request_id uuid;
  v_opportunity_id uuid;
  v_opportunity public.opportunities%rowtype;
  v_appointment public.appointments%rowtype;
  v_override_requested boolean := false;
  v_override_reason text;
  v_override_fingerprint text;
  v_existing_override_fingerprint text;
  v_override_receipt_exists boolean := false;
  v_override_receipt_inserted boolean := false;
  v_response jsonb;
  v_crm_status text;
begin
  if pg_catalog.jsonb_typeof(v_request_payload) is distinct from 'object' then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'invalid_payload'
    );
  end if;
  v_action := pg_catalog.upper(pg_catalog.btrim(coalesce(
    v_request_payload ->> 'action', ''
  )));
  v_trial_status := pg_catalog.upper(pg_catalog.btrim(coalesce(
    v_request_payload ->> 'trialStatus', ''
  )));

  if v_action = 'SET_TRIAL_STATUS' then
    if v_request_payload ? 'overrideBeforeEnd'
       or v_request_payload ? 'overrideReason' then
      if not v_request_payload ?& array[
           'requestId', 'opportunityId', 'action', 'trialStatus',
           'overrideBeforeEnd', 'overrideReason'
         ]
         or (select pg_catalog.count(*)
               from pg_catalog.jsonb_object_keys(v_request_payload)) <> 6
         or pg_catalog.jsonb_typeof(
              v_request_payload -> 'overrideBeforeEnd'
            ) is distinct from 'boolean' then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'error', 'invalid_payload'
        );
      end if;
      v_override_requested := coalesce(
        (v_request_payload ->> 'overrideBeforeEnd')::boolean,
        false
      );
      v_override_reason := nullif(pg_catalog.btrim(coalesce(
        v_request_payload ->> 'overrideReason', ''
      )), '');
      if not v_override_requested
         or pg_catalog.char_length(coalesce(v_override_reason, ''))
              not between 10 and 500 then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'error', 'invalid_override_reason'
        );
      end if;
      v_override_fingerprint := private.secure_trial_payload_fingerprint(
        v_request_payload
      );
      v_request_payload := v_request_payload
        - 'overrideBeforeEnd' - 'overrideReason';
    elsif not v_request_payload ?& array[
            'requestId', 'opportunityId', 'action', 'trialStatus'
          ]
          or (select pg_catalog.count(*)
                from pg_catalog.jsonb_object_keys(v_request_payload)) <> 4 then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_payload'
      );
    end if;

    begin
      v_request_id := (v_request_payload ->> 'requestId')::uuid;
      v_opportunity_id := (v_request_payload ->> 'opportunityId')::uuid;
    exception when invalid_text_representation then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_payload'
      );
    end;
    if v_request_id is null or v_opportunity_id is null then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_payload'
      );
    end if;
    if v_trial_status not in (
      'DONE', 'NO_SHOW_STUDENT', 'NO_SHOW_TEACHER'
    ) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'invalid_trial_status'
      );
    end if;

    select actor.actor_id, actor.tenant_id, actor.actor_role
      into v_actor_id, v_tenant_id, v_actor_role
      from private.secure_trial_actor_context() as actor;
    if v_actor_id is null then
      return pg_catalog.jsonb_build_object('ok', false, 'error', 'forbidden');
    end if;
    if v_actor_role not in ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN') then
      return pg_catalog.jsonb_build_object('ok', false, 'error', 'forbidden');
    end if;

    -- Preserve the JSON contract for missing/cross-tenant UUIDs.  The shared
    -- graph lock raises P0002 for a missing row, so check the scoped identity
    -- first and still catch a concurrent delete before the lock.
    if not exists (
      select 1
        from public.opportunities as opportunity
       where opportunity.id = v_opportunity_id
         and opportunity.tenant_id = v_tenant_id
    ) then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'opportunity_not_found'
      );
    end if;
    begin
      perform private.lock_trial_conversion_graph(v_opportunity_id);
    exception when no_data_found then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'opportunity_not_found'
      );
    end;
    select opportunity.*
      into v_opportunity
      from public.opportunities as opportunity
     where opportunity.id = v_opportunity_id
       and opportunity.tenant_id = v_tenant_id;
    if not found or v_opportunity.trial_appointment_id is null then
      return public.update_trial_outcome_secure_pre_crm_temporal_guard_impl(
        v_request_payload
      );
    end if;

    select appointment.*
      into v_appointment
      from public.appointments as appointment
     where appointment.id = v_opportunity.trial_appointment_id
       and appointment.tenant_id = v_tenant_id
     for update;
    if not found then
      return public.update_trial_outcome_secure_pre_crm_temporal_guard_impl(
        v_request_payload
      );
    end if;
    if v_appointment.start_time is null then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'appointment_time_missing'
      );
    end if;
    if v_override_requested then
      select receipt.payload_fingerprint
        into v_existing_override_fingerprint
        from private.trial_temporal_override_receipts as receipt
       where receipt.tenant_id = v_tenant_id
         and receipt.actor_id = v_actor_id
         and receipt.request_id = v_request_id;
      v_override_receipt_exists := found;
      if v_override_receipt_exists
         and v_existing_override_fingerprint is distinct from
           v_override_fingerprint then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'error', 'idempotency_key_reused'
        );
      end if;
    end if;
    if v_appointment.start_time + interval '30 minutes' >
         pg_catalog.now() then
      if not v_override_requested then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'error', 'appointment_not_ended'
        );
      end if;
      if v_actor_role <> 'SUPER_ADMIN' then
        return pg_catalog.jsonb_build_object(
          'ok', false, 'error', 'forbidden_temporal_override'
        );
      end if;
      if not v_override_receipt_exists then
        insert into private.trial_temporal_override_receipts (
          tenant_id,
          actor_id,
          request_id,
          opportunity_id,
          payload_fingerprint
        ) values (
          v_tenant_id,
          v_actor_id,
          v_request_id,
          v_opportunity_id,
          v_override_fingerprint
        )
        on conflict do nothing;
        v_override_receipt_inserted := found;
        if not found then
          select receipt.payload_fingerprint
            into v_existing_override_fingerprint
            from private.trial_temporal_override_receipts as receipt
           where receipt.tenant_id = v_tenant_id
             and receipt.actor_id = v_actor_id
             and receipt.request_id = v_request_id;
          if v_existing_override_fingerprint is distinct from
               v_override_fingerprint then
            return pg_catalog.jsonb_build_object(
              'ok', false, 'error', 'idempotency_key_reused'
            );
          end if;
          v_override_receipt_exists := true;
        end if;
      end if;
    elsif v_override_requested and not v_override_receipt_exists then
      return pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'override_not_required'
      );
    end if;
  end if;

  v_response :=
    public.update_trial_outcome_secure_pre_crm_temporal_guard_impl(
      v_request_payload
    );
  if coalesce((v_response ->> 'ok')::boolean, false) is not true then
    if v_override_receipt_inserted then
      delete from private.trial_temporal_override_receipts as receipt
       where receipt.tenant_id = v_tenant_id
         and receipt.actor_id = v_actor_id
         and receipt.request_id = v_request_id
         and receipt.payload_fingerprint = v_override_fingerprint;
    end if;
    return v_response;
  end if;

  if v_opportunity_id is null then
    begin
      v_opportunity_id := (v_request_payload ->> 'opportunityId')::uuid;
    exception when invalid_text_representation then
      v_opportunity_id := null;
    end;
  end if;
  v_crm_status := case
    when v_action = 'MARK_LOST' then 'LOST'
    when v_action = 'SAVE_FEEDBACK' then 'TRIAL_DONE'
    when v_action = 'SET_TRIAL_STATUS' and v_trial_status = 'DONE'
      then 'TRIAL_DONE'
    else null
  end;
  if v_crm_status is not null and v_opportunity_id is not null then
    perform pg_catalog.set_config(
      'app.crm_trial_outcome_opportunity',
      v_opportunity_id::text,
      true
    );
    update public.crm_leads as lead
       set status = v_crm_status
     where lead.opportunity_id = v_opportunity_id
       and lead.tenant_id = (
         select opportunity.tenant_id
           from public.opportunities as opportunity
          where opportunity.id = v_opportunity_id
       )
       and lead.status not in ('WON', 'LOST');
    perform pg_catalog.set_config(
      'app.crm_trial_outcome_opportunity',
      '',
      true
    );
  end if;

  if v_override_receipt_inserted
     and coalesce(v_response ->> 'idempotent', 'false') <> 'true' then
    insert into public.audit_logs (
      tenant_id,
      user_id,
      user_role,
      action,
      resource_type,
      resource_id,
      old_values,
      new_values,
      diff
    ) values (
      v_tenant_id,
      v_actor_id,
      v_actor_role,
      'trial_status_override_before_appointment_end',
      'opportunity',
      v_opportunity_id::text,
      pg_catalog.jsonb_build_object(
        'trial_status', v_opportunity.trial_status,
        'appointment_start_time', v_appointment.start_time
      ),
      pg_catalog.jsonb_build_object(
        'trial_status', v_trial_status,
        'override_reason', v_override_reason
      ),
      pg_catalog.jsonb_build_object(
        'trial_status', pg_catalog.jsonb_build_array(
          v_opportunity.trial_status,
          v_trial_status
        ),
        'override_reason', v_override_reason
      )
    );
  end if;

  return v_response;
end;
$$;


--
-- Name: FUNCTION update_trial_outcome_secure(p_payload jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.update_trial_outcome_secure(p_payload jsonb) IS 'Settles trial outcomes only after the appointment window; early SUPER_ADMIN overrides require an audited reason.';


--
-- Name: update_trial_outcome_secure_pre_crm_temporal_guard_impl(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_trial_outcome_secure_pre_crm_temporal_guard_impl(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_tenant_id text;
  v_actor_role text;
  v_action text;
  v_opportunity_id uuid;
  v_opportunity public.opportunities%rowtype;
  v_appointment public.appointments%rowtype;
  v_teacher_id uuid;
begin
  if pg_catalog.jsonb_typeof(coalesce(p_payload, '{}'::jsonb))
       is distinct from 'object' then
    return jsonb_build_object('ok', false, 'error', 'invalid_payload');
  end if;
  v_action := pg_catalog.upper(pg_catalog.btrim(coalesce(
    p_payload ->> 'action', ''
  )));
  if v_action <> 'SAVE_FEEDBACK' then
    return public.update_trial_outcome_secure_pre_feedback_evidence_impl(
      p_payload
    );
  end if;

  begin
    v_opportunity_id := nullif(
      pg_catalog.btrim(coalesce(p_payload ->> 'opportunityId', '')),
      ''
    )::uuid;
  exception when invalid_text_representation then
    return jsonb_build_object('ok', false, 'error', 'invalid_payload');
  end;
  if v_opportunity_id is null then
    return jsonb_build_object('ok', false, 'error', 'invalid_payload');
  end if;

  select actor.actor_id, actor.tenant_id, actor.actor_role
    into v_actor_id, v_tenant_id, v_actor_role
    from private.secure_trial_actor_context() as actor;
  if v_actor_id is null or v_actor_role <> 'TEACHER' then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;

  perform private.lock_trial_conversion_graph(v_opportunity_id);
  select opportunity.* into v_opportunity
    from public.opportunities as opportunity
   where opportunity.id = v_opportunity_id
     and opportunity.tenant_id = v_tenant_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'opportunity_not_found');
  end if;
  v_teacher_id := coalesce(
    v_opportunity.winner_teacher_id, v_opportunity.professor_id
  );
  if v_teacher_id is null or v_teacher_id <> v_actor_id
     or v_opportunity.trial_appointment_id is null then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;

  select appointment.* into v_appointment
    from public.appointments as appointment
   where appointment.id = v_opportunity.trial_appointment_id
     and appointment.tenant_id = v_tenant_id
   for update;
  if not found
     or coalesce(v_appointment.teacher_id, v_appointment.professor_id)
          is distinct from v_actor_id
     or pg_catalog.lower(coalesce(v_appointment.type, '')) <> 'experimental' then
    return jsonb_build_object('ok', false, 'error', 'appointment_tenant_mismatch');
  end if;
  if v_appointment.start_time + interval '30 minutes' > pg_catalog.now() then
    return jsonb_build_object('ok', false, 'error', 'appointment_not_ended');
  end if;
  if not exists (
    select 1
      from public.class_logs as class_log
     where class_log.tenant_id = v_tenant_id
       and class_log.appointment_id = v_appointment.id::text
       and class_log.teacher_id = v_actor_id
       and class_log.presence = 'COMPLETED'
       and class_log.subtype = 'AULA EXPERIMENTAL'
  ) then
    return jsonb_build_object(
      'ok', false, 'error', 'completed_class_log_required'
    );
  end if;

  return public.update_trial_outcome_secure_pre_feedback_evidence_impl(
    p_payload
  );
end;
$$;


--
-- Name: update_trial_outcome_secure_pre_feedback_evidence_impl(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_trial_outcome_secure_pre_feedback_evidence_impl(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_tenant_id text;
  v_actor_role text;
  v_opportunity_id uuid;
  v_result jsonb;
begin
  if pg_catalog.upper(pg_catalog.btrim(coalesce(
    p_payload ->> 'action',
    ''
  ))) <> 'MARK_LOST' then
    return public.update_trial_outcome_secure_pre_trial_lifecycle_impl(
      p_payload
    );
  end if;

  begin
    v_opportunity_id := (p_payload ->> 'opportunityId')::uuid;
  exception when invalid_text_representation or null_value_not_allowed then
    return public.update_trial_outcome_secure_pre_trial_lifecycle_impl(
      p_payload
    );
  end;
  if v_opportunity_id is null then
    return public.update_trial_outcome_secure_pre_trial_lifecycle_impl(
      p_payload
    );
  end if;

  select actor.actor_id, actor.tenant_id, actor.actor_role
  into v_actor_id, v_tenant_id, v_actor_role
  from private.secure_trial_actor_context() as actor;
  if v_actor_id is null
     or v_actor_role not in ('SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN') then
    return public.update_trial_outcome_secure_pre_trial_lifecycle_impl(
      p_payload
    );
  end if;

  perform private.lock_trial_conversion_graph(v_opportunity_id);
  if not exists (
    select 1
    from public.opportunities as opportunity
    where opportunity.id = v_opportunity_id
      and opportunity.tenant_id = v_tenant_id
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'opportunity_not_found'
    );
  end if;

  if exists (
    select 1
    from public.offers as offer
    where offer.opportunity_id = v_opportunity_id
      and offer.kind = 'ENROLLMENT'
      and offer.revoked_at is null
      and offer.consumed_at is null
      and (
        offer.processing_by is not null
        or offer.processing_state <> 'NOT_STARTED'
      )
  ) or exists (
    select 1
    from public.enrollment_links as link
    where link.opportunity_id = v_opportunity_id
      and link.status = 'PROCESSING'
  ) then
    return pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'enrollment_in_progress'
    );
  end if;

  v_result := public.update_trial_outcome_secure_pre_trial_lifecycle_impl(
    p_payload
  );
  if coalesce((v_result ->> 'ok')::boolean, false) is not true then
    return v_result;
  end if;

  -- The wrapped command owns the opportunity lock and must have persisted LOST
  -- before dependent artifacts are invalidated.
  if not exists (
    select 1
    from public.opportunities as opportunity
    where opportunity.id = v_opportunity_id
      and opportunity.tenant_id = v_tenant_id
      and opportunity.conversion_status = 'LOST'
  ) then
    raise exception 'trial_loss_state_not_persisted' using errcode = '40001';
  end if;

  update public.offers as offer
  set revoked_at = coalesce(offer.revoked_at, pg_catalog.now()),
      revoked_by = coalesce(offer.revoked_by, v_actor_id)
  where offer.opportunity_id = v_opportunity_id
    and offer.kind = 'ENROLLMENT'
    and offer.revoked_at is null
    and offer.consumed_at is null
    and offer.processing_by is null
    and offer.processing_state = 'NOT_STARTED';

  update public.enrollment_links as link
  set status = 'EXPIRED'
  where link.opportunity_id = v_opportunity_id
    and link.status = 'PENDING';

  update private.vendor_trial_teacher_requests as request
  set status = 'CANCELED',
      updated_at = pg_catalog.now()
  where request.opportunity_id = v_opportunity_id
    and request.status in ('AWAITING_STUDENT', 'AWAITING_TEACHER');

  return v_result;
end;
$$;


--
-- Name: update_trial_outcome_secure_pre_trial_lifecycle_impl(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_trial_outcome_secure_pre_trial_lifecycle_impl(p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor_id uuid;
  v_tenant_id text;
  v_actor_role text;
  v_request_id uuid;
  v_opportunity_id uuid;
  v_action text;
  v_trial_status text;
  v_lost_reason text;
  v_recommended_level text;
  v_recommended_plan text;
  v_interest_score integer;
  v_notes text;
  v_opportunity public.opportunities%rowtype;
  v_appointment public.appointments%rowtype;
  v_feedback public.trial_feedback%rowtype;
  v_teacher_id uuid;
  v_feedback_id uuid;
  v_class_log_id uuid;
  v_fingerprint text;
  v_existing_fingerprint text;
  v_existing_response jsonb;
  v_response jsonb;
begin
  if jsonb_typeof(p_payload) is distinct from 'object'
     or not p_payload ?& array['requestId', 'opportunityId', 'action'] then
    return jsonb_build_object('ok', false, 'error', 'invalid_payload');
  end if;

  v_action := upper(trim(coalesce(p_payload ->> 'action', '')));
  if (
    v_action = 'SAVE_FEEDBACK'
    and (
      not p_payload ?& array[
        'recommendedLevel', 'recommendedPlan', 'interestScore', 'notes'
      ]
      or (select count(*) from jsonb_object_keys(p_payload)) <> 7
    )
  ) or (
    v_action = 'SET_TRIAL_STATUS'
    and (
      not p_payload ? 'trialStatus'
      or (select count(*) from jsonb_object_keys(p_payload)) <> 4
    )
  ) or (
    v_action = 'MARK_LOST'
    and (
      not p_payload ? 'lostReason'
      or (select count(*) from jsonb_object_keys(p_payload)) <> 4
    )
  ) or v_action not in (
    'SAVE_FEEDBACK', 'SET_TRIAL_STATUS', 'MARK_LOST'
  ) then
    return jsonb_build_object('ok', false, 'error', 'invalid_payload');
  end if;

  begin
    v_request_id := (p_payload ->> 'requestId')::uuid;
    v_opportunity_id := (p_payload ->> 'opportunityId')::uuid;
  exception when invalid_text_representation then
    return jsonb_build_object('ok', false, 'error', 'invalid_payload');
  end;

  select actor.actor_id, actor.tenant_id, actor.actor_role
    into v_actor_id, v_tenant_id, v_actor_role
    from private.secure_trial_actor_context() as actor;

  if v_actor_id is null then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if v_action = 'SAVE_FEEDBACK' and v_actor_role <> 'TEACHER' then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if v_action in ('SET_TRIAL_STATUS', 'MARK_LOST')
     and v_actor_role not in (
       'SCHOOL_ADMIN', 'COORDINATOR', 'SUPER_ADMIN'
     ) then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;
  if not private.tenant_is_operational(v_tenant_id) then
    return jsonb_build_object('ok', false, 'error', 'tenant_not_operational');
  end if;

  if v_action = 'SAVE_FEEDBACK' then
    v_trial_status := 'DONE';
    v_recommended_level := upper(trim(coalesce(
      p_payload ->> 'recommendedLevel', ''
    )));
    v_recommended_plan := trim(coalesce(
      p_payload ->> 'recommendedPlan', ''
    ));
    v_notes := nullif(trim(coalesce(p_payload ->> 'notes', '')), '');
    begin
      v_interest_score := (p_payload ->> 'interestScore')::integer;
    exception when invalid_text_representation then
      return jsonb_build_object('ok', false, 'error', 'invalid_feedback');
    end;
    if v_recommended_level not in ('A1', 'A2', 'B1', 'B2', 'C1', 'C2')
       or v_recommended_plan not in (
         '1x_semana', '2x_semana', '3x_semana', 'intensivo'
       )
       or v_interest_score not between 1 and 5
       or length(coalesce(v_notes, '')) > 4000 then
      return jsonb_build_object('ok', false, 'error', 'invalid_feedback');
    end if;
  elsif v_action = 'SET_TRIAL_STATUS' then
    v_trial_status := upper(trim(coalesce(
      p_payload ->> 'trialStatus', ''
    )));
    if v_trial_status not in (
      'DONE', 'NO_SHOW_STUDENT', 'NO_SHOW_TEACHER'
    ) then
      return jsonb_build_object('ok', false, 'error', 'invalid_trial_status');
    end if;
  else
    v_lost_reason := trim(coalesce(p_payload ->> 'lostReason', ''));
    if v_lost_reason = '' then
      v_lost_reason := 'Não especificado';
    end if;
    if length(v_lost_reason) > 500 then
      return jsonb_build_object('ok', false, 'error', 'invalid_lost_reason');
    end if;
  end if;

  v_fingerprint := private.secure_trial_payload_fingerprint(p_payload);
  select receipt.payload_fingerprint, receipt.response
    into v_existing_fingerprint, v_existing_response
    from private.secure_trial_command_receipts as receipt
   where receipt.tenant_id = v_tenant_id
     and receipt.actor_id = v_actor_id
     and receipt.command = 'TRIAL_OUTCOME'
     and receipt.request_id = v_request_id;
  if found then
    if v_existing_fingerprint <> v_fingerprint then
      return jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    return coalesce(v_existing_response, '{}'::jsonb)
      || jsonb_build_object('idempotent', true);
  end if;

  select opportunity.*
    into v_opportunity
    from public.opportunities as opportunity
   where opportunity.id = v_opportunity_id
     and opportunity.tenant_id = v_tenant_id
   for update;

  if not found then
    return jsonb_build_object('ok', false, 'error', 'opportunity_not_found');
  end if;

  select receipt.payload_fingerprint, receipt.response
    into v_existing_fingerprint, v_existing_response
    from private.secure_trial_command_receipts as receipt
   where receipt.tenant_id = v_tenant_id
     and receipt.actor_id = v_actor_id
     and receipt.command = 'TRIAL_OUTCOME'
     and receipt.request_id = v_request_id;
  if found then
    if v_existing_fingerprint <> v_fingerprint then
      return jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    return coalesce(v_existing_response, '{}'::jsonb)
      || jsonb_build_object('idempotent', true);
  end if;

  if upper(coalesce(v_opportunity.status, '')) <> 'CLAIMED'
     or upper(coalesce(v_opportunity.kind, 'TRIAL')) <> 'TRIAL' then
    return jsonb_build_object(
      'ok', false, 'error', 'opportunity_not_claimed_trial'
    );
  end if;
  if coalesce(v_opportunity.conversion_status, 'OPEN') = 'WON' then
    return jsonb_build_object('ok', false, 'error', 'opportunity_already_won');
  end if;

  v_teacher_id := coalesce(
    v_opportunity.winner_teacher_id,
    v_opportunity.professor_id
  );
  if v_teacher_id is null
     or (
       v_opportunity.winner_teacher_id is not null
       and v_opportunity.winner_teacher_id <> v_teacher_id
     )
     or (
       v_opportunity.professor_id is not null
       and v_opportunity.professor_id <> v_teacher_id
     )
     or not exists (
       select 1
         from public.profiles as profile
         join public.tenant_memberships as membership
           on membership.user_id = profile.id
          and membership.tenant_id = v_tenant_id
          and membership.role = 'TEACHER'
          and membership.status = 'ACTIVE'
        where profile.id = v_teacher_id
          and lower(trim(coalesce(profile.lifecycle_status, ''))) = 'active'
     ) then
    return jsonb_build_object(
      'ok', false, 'error', 'teacher_not_active_for_tenant'
    );
  end if;

  if v_opportunity.created_by_vendor_id is not null
     and not exists (
       select 1
         from public.tenant_memberships as membership
        where membership.user_id = v_opportunity.created_by_vendor_id
          and membership.tenant_id = v_tenant_id
          and membership.role in ('SALESPERSON', 'COMMERCIAL')
     ) then
    return jsonb_build_object('ok', false, 'error', 'vendor_tenant_mismatch');
  end if;
  if v_opportunity.student_id is not null
     and not exists (
       select 1
         from public.tenant_memberships as membership
         join public.profiles as profile
           on profile.id = membership.user_id
        where membership.user_id = v_opportunity.student_id
          and membership.tenant_id = v_tenant_id
          and membership.role = 'STUDENT'
          and membership.status = 'ACTIVE'
          and lower(trim(coalesce(profile.lifecycle_status, 'active'))) = 'active'
     ) then
    return jsonb_build_object('ok', false, 'error', 'student_tenant_mismatch');
  end if;

  if v_opportunity.trial_appointment_id is not null then
    select appointment.*
      into v_appointment
      from public.appointments as appointment
     where appointment.id = v_opportunity.trial_appointment_id
     for update;

    if not found
       or v_appointment.tenant_id <> v_tenant_id
       or coalesce(v_appointment.teacher_id, v_appointment.professor_id)
          is distinct from v_teacher_id
       or (
         v_appointment.teacher_id is not null
         and v_appointment.teacher_id <> v_teacher_id
       )
       or (
         v_appointment.professor_id is not null
         and v_appointment.professor_id <> v_teacher_id
       )
       or lower(coalesce(v_appointment.type, '')) <> 'experimental' then
      return jsonb_build_object(
        'ok', false, 'error', 'appointment_tenant_mismatch'
      );
    end if;
  elsif v_action <> 'MARK_LOST' then
    return jsonb_build_object('ok', false, 'error', 'appointment_required');
  end if;

  if v_action = 'SAVE_FEEDBACK' and v_teacher_id <> v_actor_id then
    return jsonb_build_object('ok', false, 'error', 'forbidden');
  end if;

  if v_action in ('SAVE_FEEDBACK', 'SET_TRIAL_STATUS') then
    if v_trial_status = 'DONE' then
      if lower(coalesce(v_appointment.status, '')) not in (
        'scheduled', 'confirmed', 'completed'
      ) then
        return jsonb_build_object(
          'ok', false, 'error', 'appointment_not_settleable'
        );
      end if;
      if exists (
        select 1
          from public.class_logs as class_log
         where class_log.appointment_id = v_appointment.id::text
           and (
             class_log.tenant_id <> v_tenant_id
             or class_log.teacher_id <> v_teacher_id
             or class_log.presence <> 'COMPLETED'
           )
      ) then
        return jsonb_build_object(
          'ok', false, 'error', 'class_log_tenant_mismatch'
        );
      end if;
    else
      if lower(coalesce(v_appointment.status, '')) not in (
        'scheduled', 'confirmed', 'no_show'
      ) then
        return jsonb_build_object(
          'ok', false, 'error', 'appointment_not_settleable'
        );
      end if;
      if exists (
        select 1
          from public.class_logs as class_log
         where class_log.appointment_id = v_appointment.id::text
      ) then
        return jsonb_build_object(
          'ok', false, 'error', 'trial_already_settled'
        );
      end if;
    end if;
  end if;

  if v_action = 'SAVE_FEEDBACK' then
    select feedback.*
      into v_feedback
      from public.trial_feedback as feedback
     where feedback.opportunity_id = v_opportunity.id
     for update;
    if found and (
      v_feedback.tenant_id <> v_tenant_id
      or v_feedback.teacher_id <> v_actor_id
      or v_feedback.booking_id is distinct from v_appointment.id
    ) then
      return jsonb_build_object(
        'ok', false, 'error', 'feedback_tenant_mismatch'
      );
    end if;
  end if;

  insert into private.secure_trial_command_receipts (
    tenant_id, actor_id, command, request_id, payload_fingerprint
  ) values (
    v_tenant_id, v_actor_id, 'TRIAL_OUTCOME',
    v_request_id, v_fingerprint
  )
  on conflict do nothing;

  if not found then
    select receipt.payload_fingerprint, receipt.response
      into v_existing_fingerprint, v_existing_response
      from private.secure_trial_command_receipts as receipt
     where receipt.tenant_id = v_tenant_id
       and receipt.actor_id = v_actor_id
       and receipt.command = 'TRIAL_OUTCOME'
       and receipt.request_id = v_request_id;
    if v_existing_fingerprint <> v_fingerprint then
      return jsonb_build_object(
        'ok', false, 'error', 'idempotency_key_reused'
      );
    end if;
    return coalesce(v_existing_response, '{}'::jsonb)
      || jsonb_build_object('idempotent', true);
  end if;

  if v_action = 'MARK_LOST' then
    update public.opportunities
       set conversion_status = 'LOST',
           lost_reason = v_lost_reason
     where id = v_opportunity.id
       and tenant_id = v_tenant_id;

    v_response := jsonb_build_object(
      'ok', true,
      'idempotent', false,
      'opportunityId', v_opportunity.id,
      'conversionStatus', 'LOST',
      'lostReason', v_lost_reason
    );
  else
    if v_action = 'SAVE_FEEDBACK' then
      insert into public.trial_feedback as feedback (
        tenant_id, opportunity_id, booking_id, teacher_id,
        recommended_level, recommended_plan, interest_score, notes
      ) values (
        v_tenant_id, v_opportunity.id, v_appointment.id, v_actor_id,
        v_recommended_level, v_recommended_plan, v_interest_score, v_notes
      )
      on conflict (opportunity_id) do update
        set booking_id = excluded.booking_id,
            recommended_level = excluded.recommended_level,
            recommended_plan = excluded.recommended_plan,
            interest_score = excluded.interest_score,
            notes = excluded.notes
      where feedback.tenant_id = excluded.tenant_id
        and feedback.teacher_id = excluded.teacher_id
      returning id into v_feedback_id;

      if v_feedback_id is null then
        raise exception 'secure_trial_feedback_lost_lock'
          using errcode = '40001';
      end if;
    end if;

    if v_trial_status = 'DONE' then
      insert into public.class_logs (
        tenant_id, teacher_id, appointment_id, presence, subtype,
        date, class_date, start_time, created_at
      ) values (
        v_tenant_id, v_teacher_id, v_appointment.id::text,
        'COMPLETED', 'AULA EXPERIMENTAL',
        (v_appointment.start_time at time zone 'America/Sao_Paulo')::date,
        (v_appointment.start_time at time zone 'America/Sao_Paulo')::date,
        (v_appointment.start_time at time zone 'America/Sao_Paulo')::time,
        now()
      )
      on conflict do nothing
      returning id into v_class_log_id;

      if v_class_log_id is null then
        select class_log.id
          into v_class_log_id
          from public.class_logs as class_log
         where class_log.appointment_id = v_appointment.id::text
           and class_log.tenant_id = v_tenant_id
           and class_log.teacher_id = v_teacher_id
           and class_log.presence = 'COMPLETED';
      end if;

      update public.appointments
         set status = 'completed'
       where id = v_appointment.id
         and tenant_id = v_tenant_id;
    else
      update public.appointments
         set status = 'no_show'
       where id = v_appointment.id
         and tenant_id = v_tenant_id;
    end if;

    update public.opportunities
       set trial_status = v_trial_status
     where id = v_opportunity.id
       and tenant_id = v_tenant_id;

    v_response := jsonb_build_object(
      'ok', true,
      'idempotent', false,
      'opportunityId', v_opportunity.id,
      'appointmentId', v_appointment.id,
      'trialStatus', v_trial_status,
      'appointmentStatus', case
        when v_trial_status = 'DONE' then 'completed'
        else 'no_show'
      end,
      'feedbackId', v_feedback_id,
      'classLogId', v_class_log_id
    );
  end if;

  update private.secure_trial_command_receipts
     set response = v_response,
         completed_at = now()
   where tenant_id = v_tenant_id
     and actor_id = v_actor_id
     and command = 'TRIAL_OUTCOME'
     and request_id = v_request_id;

  return v_response;
end;
$$;


--
-- Name: update_unit_activity(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_unit_activity(p_activity_id uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_path_id uuid;
  v_unit_id uuid;
  v_activity public.unit_activities%rowtype;
  v_xp_reward numeric;
  v_estimated_minutes numeric;
begin
  if p_activity_id is null then
    raise exception using
      errcode = '22023',
      message = 'unit_activity_id_required';
  end if;
  if p_payload is null
     or pg_catalog.jsonb_typeof(p_payload) <> 'object'
     or p_payload = '{}'::jsonb
     or exists (
       select 1
         from pg_catalog.jsonb_object_keys(p_payload) as supplied(key)
        where supplied.key not in (
          'title',
          'description',
          'content',
          'xp_reward',
          'estimated_minutes'
        )
     ) then
    raise exception using
      errcode = '22023',
      message = 'unit_activity_payload_invalid';
  end if;

  if p_payload ? 'title'
     and (
       pg_catalog.jsonb_typeof(p_payload -> 'title') <> 'string'
       or nullif(pg_catalog.btrim(p_payload ->> 'title'), '') is null
     ) then
    raise exception using
      errcode = '22023',
      message = 'unit_activity_payload_invalid';
  end if;
  if p_payload ? 'description'
     and pg_catalog.jsonb_typeof(p_payload -> 'description')
       not in ('string', 'null') then
    raise exception using
      errcode = '22023',
      message = 'unit_activity_payload_invalid';
  end if;
  if p_payload ? 'content'
     and pg_catalog.jsonb_typeof(p_payload -> 'content') <> 'object' then
    raise exception using
      errcode = '22023',
      message = 'unit_activity_payload_invalid';
  end if;

  if p_payload ? 'xp_reward' then
    if pg_catalog.jsonb_typeof(p_payload -> 'xp_reward') <> 'number' then
      raise exception using
        errcode = '22023',
        message = 'unit_activity_payload_invalid';
    end if;
    v_xp_reward := (p_payload ->> 'xp_reward')::numeric;
    if v_xp_reward <> pg_catalog.trunc(v_xp_reward)
       or v_xp_reward not between 0::numeric and 10000::numeric then
      raise exception using
        errcode = '22023',
        message = 'unit_activity_payload_invalid';
    end if;
  end if;

  if p_payload ? 'estimated_minutes' then
    if pg_catalog.jsonb_typeof(p_payload -> 'estimated_minutes') <> 'number' then
      raise exception using
        errcode = '22023',
        message = 'unit_activity_payload_invalid';
    end if;
    v_estimated_minutes := (p_payload ->> 'estimated_minutes')::numeric;
    if v_estimated_minutes <> pg_catalog.trunc(v_estimated_minutes)
       or v_estimated_minutes not between 0::numeric and 1440::numeric then
      raise exception using
        errcode = '22023',
        message = 'unit_activity_payload_invalid';
    end if;
  end if;

  select unit.path_id, activity.unit_id
    into v_path_id, v_unit_id
    from public.unit_activities as activity
    join public.learning_units as unit
      on unit.id = activity.unit_id
   where activity.id = p_activity_id;

  perform private.lock_mutable_learning_path(v_path_id);

  update public.unit_activities as activity
     set title = case
           when p_payload ? 'title'
             then pg_catalog.btrim(p_payload ->> 'title')
           else activity.title
         end,
         description = case
           when p_payload ? 'description' then p_payload ->> 'description'
           else activity.description
         end,
         content = case
           when p_payload ? 'content' then p_payload -> 'content'
           else activity.content
         end,
         xp_reward = case
           when p_payload ? 'xp_reward' then v_xp_reward::integer
           else activity.xp_reward
         end,
         estimated_minutes = case
           when p_payload ? 'estimated_minutes'
             then v_estimated_minutes::integer
           else activity.estimated_minutes
         end
   where activity.id = p_activity_id
     and activity.unit_id = v_unit_id
  returning activity.* into v_activity;

  if v_activity.id is null then
    raise exception using
      errcode = '55000',
      message = 'unit_activity_changed_during_mutation';
  end if;

  return pg_catalog.jsonb_build_object(
    'activityId', v_activity.id,
    'unitId', v_unit_id,
    'pathId', v_path_id,
    'activity', pg_catalog.to_jsonb(v_activity)
  );
end;
$$;


--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$;


--
-- Name: upsert_collection(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_collection(p_id uuid, p_title text, p_niche text, p_level text, p_cover text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  target_tenant_id text;
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  IF p_id IS NOT NULL THEN
    SELECT collection.tenant_id
    INTO target_tenant_id
    FROM public.pedagogical_collections AS collection
    WHERE collection.id = p_id;
    IF NOT FOUND THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'nao_encontrado'
      );
    END IF;
    IF NOT private.legacy_role_rpc_target_allowed(target_tenant_id) THEN
      RETURN pg_catalog.jsonb_build_object(
        'ok', false, 'error', 'sem_permissao'
      );
    END IF;
  END IF;
  RETURN public.upsert_collection_unchecked(
    p_id, p_title, p_niche, p_level, p_cover
  );
END;
$$;


--
-- Name: upsert_collection_unchecked(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_collection_unchecked(p_id uuid, p_title text, p_niche text, p_level text, p_cover text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; c_tenant text; v_id uuid;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role NOT IN ('TEACHER','SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
  END IF;
  IF p_title IS NULL OR length(trim(p_title)) < 2 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'titulo_invalido');
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO pedagogical_collections (tenant_id, title, niche, level_tag, cover_url, created_by)
    VALUES (v_tenant, trim(p_title), COALESCE(NULLIF(p_niche,''),'GENERAL'), NULLIF(p_level,''), NULLIF(p_cover,''), auth.uid())
    RETURNING id INTO v_id;
  ELSE
    SELECT tenant_id INTO c_tenant FROM pedagogical_collections WHERE id = p_id;
    IF c_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'nao_encontrado'); END IF;
    IF v_role = 'SCHOOL_ADMIN' AND c_tenant <> v_tenant THEN
      RETURN jsonb_build_object('ok', false, 'error', 'sem_permissao');
    END IF;
    UPDATE pedagogical_collections SET
      title     = COALESCE(NULLIF(trim(p_title),''), title),
      niche     = COALESCE(NULLIF(p_niche,''), niche),
      level_tag = COALESCE(NULLIF(p_level,''), level_tag),
      cover_url = COALESCE(NULLIF(p_cover,''), cover_url)
    WHERE id = p_id;
    v_id := p_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'id', v_id);
END;
$$;


--
-- Name: upsert_niche(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_niche(p_label text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF NOT private.can_execute_legacy_role_rpc(
    ARRAY['TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN']::text[]
  ) THEN
    RETURN pg_catalog.jsonb_build_object(
      'ok', false, 'error', 'sem_permissao'
    );
  END IF;
  RETURN public.upsert_niche_unchecked(p_label);
END;
$$;


--
-- Name: upsert_niche_unchecked(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_niche_unchecked(p_label text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_role text; v_tenant text; v_key text;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id=auth.uid();
  IF v_role NOT IN ('TEACHER','SCHOOL_ADMIN','SUPER_ADMIN') THEN RETURN jsonb_build_object('ok',false,'error','sem_permissao'); END IF;
  IF p_label IS NULL OR length(trim(p_label)) < 2 THEN RETURN jsonb_build_object('ok',false,'error','label_invalido'); END IF;
  -- key: maiúsculas, sem acento, underscore
  v_key := upper(regexp_replace(translate(trim(p_label),
    'áàâãäéèêëíìîïóòôõöúùûüçÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ',
    'aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC'),
    '[^a-zA-Z0-9]+','_','g'));
  v_key := trim(both '_' from v_key);
  IF v_key='' THEN v_key := 'NICHO_'||substr(md5(random()::text),1,4); END IF;
  INSERT INTO tenant_niches (tenant_id, key, label, created_by)
  VALUES (v_tenant, v_key, trim(p_label), auth.uid())
  ON CONFLICT (tenant_id, key) DO UPDATE SET label=EXCLUDED.label;
  RETURN jsonb_build_object('ok', true, 'key', v_key, 'label', trim(p_label));
END;
$$;


--
-- Name: upsert_recurring_expense(uuid, text, numeric, text, integer, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_recurring_expense(p_id uuid, p_label text, p_amount numeric, p_account_code text, p_day_of_month integer DEFAULT 5, p_start_month text DEFAULT NULL::text, p_end_month text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_is_active boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE v_role text; v_tenant text; v_id uuid; v_start text; v_allowed boolean;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN
    RETURN jsonb_build_object('error','sem_permissao');
  END IF;
  IF COALESCE(btrim(p_label),'') = '' THEN RETURN jsonb_build_object('error','label_obrigatorio'); END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN RETURN jsonb_build_object('error','valor_invalido'); END IF;

  -- Conta de fonte autoritativa (repasse, comissão, indicação) não pode virar
  -- despesa recorrente: o valor já entra por competência e o DRE barraria o
  -- lançamento. Recusar aqui evita criar um molde que gera lixo todo mês.
  SELECT ledger_allowed INTO v_allowed FROM dre_accounts WHERE code = p_account_code AND is_active;
  IF v_allowed IS NULL THEN RETURN jsonb_build_object('error','conta_invalida'); END IF;
  IF NOT v_allowed THEN RETURN jsonb_build_object('error','conta_de_fonte_automatica'); END IF;

  v_start := COALESCE(p_start_month, to_char(current_date,'YYYY-MM'));
  IF v_start !~ '^\d{4}-\d{2}$' THEN RETURN jsonb_build_object('error','mes_inicial_invalido'); END IF;
  IF p_end_month IS NOT NULL AND p_end_month !~ '^\d{4}-\d{2}$' THEN
    RETURN jsonb_build_object('error','mes_final_invalido');
  END IF;
  IF p_day_of_month IS NULL OR p_day_of_month NOT BETWEEN 1 AND 28 THEN
    RETURN jsonb_build_object('error','dia_invalido');
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO recurring_expenses (tenant_id, label, amount, account_code, day_of_month,
                                    start_month, end_month, notes, is_active, created_by)
    VALUES (v_tenant, btrim(p_label), p_amount, p_account_code, p_day_of_month,
            v_start, p_end_month, p_notes, COALESCE(p_is_active,true), auth.uid())
    RETURNING id INTO v_id;
  ELSE
    UPDATE recurring_expenses
       SET label = btrim(p_label), amount = p_amount, account_code = p_account_code,
           day_of_month = p_day_of_month, start_month = v_start, end_month = p_end_month,
           notes = p_notes, is_active = COALESCE(p_is_active,true), updated_at = now()
     WHERE id = p_id AND tenant_id = v_tenant
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN RETURN jsonb_build_object('error','nao_encontrada'); END IF;
  END IF;

  RETURN jsonb_build_object('ok', true, 'id', v_id);
END;
$_$;


--
-- Name: upsert_tenant_integration_secret(text, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_tenant_integration_secret(p_tenant_id text, p_provider text, p_secret text, p_environment text, p_actor_id uuid, p_account_label text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  existing_secret_id uuid;
  stored_secret_id uuid;
  secret_name text;
  actor_role text;
  normalized_label text := nullif(left(trim(coalesce(p_account_label, '')), 120), '');
BEGIN
  IF p_provider NOT IN ('asaas', 'evolution', 'openai', 'openrouter')
    OR p_environment IS NULL
    OR (p_provider = 'asaas' AND p_environment NOT IN ('sandbox', 'production'))
    OR (p_provider = 'evolution' AND p_environment <> 'platform')
    OR (p_provider IN ('openai', 'openrouter') AND p_environment <> 'production')
    OR p_secret IS NULL
    OR nullif(btrim(p_secret), '') IS NULL
    OR length(p_secret) NOT BETWEEN 8 AND 4096
    OR NOT EXISTS (SELECT 1 FROM public.tenants WHERE id = p_tenant_id)
  THEN
    RAISE EXCEPTION 'invalid_tenant_secret' USING ERRCODE = '22023';
  END IF;

  -- NULL actor is reserved for the one-time legacy migration below. Interactive
  -- callers always carry an actor and must belong to an operational tenant.
  IF p_actor_id IS NOT NULL
    AND NOT private.tenant_is_operational(p_tenant_id)
  THEN
    RAISE EXCEPTION 'tenant_not_operational' USING ERRCODE = '55000';
  END IF;

  IF p_actor_id IS NULL THEN
    actor_role := 'SYSTEM';
  ELSE
    actor_role := private.active_tenant_role(p_actor_id);
    IF actor_role NOT IN ('SCHOOL_ADMIN', 'SUPER_ADMIN')
      OR private.active_tenant_id(p_actor_id) IS DISTINCT FROM p_tenant_id
    THEN
      RAISE EXCEPTION 'cross_tenant_access_denied' USING ERRCODE = '42501';
    END IF;
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_tenant_id || ':' || p_provider, 0)
  );

  secret_name := 'tenant-integration:' || p_tenant_id || ':' || p_provider;

  SELECT registry.vault_secret_id
  INTO existing_secret_id
  FROM private.tenant_secret_registry AS registry
  WHERE registry.tenant_id = p_tenant_id
    AND registry.provider = p_provider
  FOR UPDATE;

  IF existing_secret_id IS NULL THEN
    SELECT vault.create_secret(
      p_secret,
      secret_name,
      'Tenant-managed integration credential',
      NULL
    )
    INTO stored_secret_id;
  ELSE
    PERFORM vault.update_secret(
      existing_secret_id,
      p_secret,
      secret_name,
      'Tenant-managed integration credential',
      NULL
    );
    stored_secret_id := existing_secret_id;
  END IF;

  INSERT INTO private.tenant_secret_registry (
    tenant_id,
    provider,
    vault_secret_id,
    environment,
    status,
    secret_last_four,
    account_label,
    last_validated_at,
    created_by,
    updated_by,
    updated_at
  )
  VALUES (
    p_tenant_id,
    p_provider,
    stored_secret_id,
    p_environment,
    'healthy',
    right(p_secret, 4),
    normalized_label,
    now(),
    p_actor_id,
    p_actor_id,
    now()
  )
  ON CONFLICT (tenant_id, provider) DO UPDATE
  SET vault_secret_id = EXCLUDED.vault_secret_id,
      environment = EXCLUDED.environment,
      status = 'healthy',
      secret_last_four = EXCLUDED.secret_last_four,
      account_label = EXCLUDED.account_label,
      last_validated_at = now(),
      updated_by = EXCLUDED.updated_by,
      updated_at = now();

  INSERT INTO public.tenant_configuration_audit (
    tenant_id,
    actor_id,
    actor_role,
    action,
    section,
    changes
  )
  VALUES (
    p_tenant_id,
    p_actor_id,
    actor_role,
    CASE WHEN existing_secret_id IS NULL THEN 'credential_configured' ELSE 'credential_rotated' END,
    'integrations',
    jsonb_build_object(
      'provider', p_provider,
      'environment', p_environment,
      'configured', true
    )
  );

  RETURN jsonb_build_object(
    'provider', p_provider,
    'environment', p_environment,
    'status', 'healthy',
    'secretLastFour', right(p_secret, 4),
    'accountLabel', normalized_label,
    'lastValidatedAt', now()
  );
END;
$$;


--
-- Name: validate_offer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_offer(p_offer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_offer RECORD;
BEGIN
    SELECT * INTO v_offer FROM public.offers WHERE id = p_offer_id;

    IF v_offer IS NULL THEN
        RETURN jsonb_build_object('valid', false, 'error', 'OFFER_NOT_FOUND');
    END IF;

    IF v_offer.revoked_at IS NOT NULL THEN
        RETURN jsonb_build_object('valid', false, 'error', 'OFFER_REVOKED');
    END IF;

    IF v_offer.expires_at < now() THEN
        RETURN jsonb_build_object('valid', false, 'error', 'OFFER_EXPIRED');
    END IF;

    -- Track usage
    UPDATE public.offers
    SET usage_count = usage_count + 1, last_used_at = now()
    WHERE id = p_offer_id;

    RETURN jsonb_build_object(
        'valid', true,
        'offer_id', v_offer.id,
        'kind', v_offer.kind,
        'payload', v_offer.payload,
        'tenant_id', v_offer.tenant_id,
        'requires_enrollment', v_offer.requires_enrollment,
        'enrollment_fee', v_offer.enrollment_fee,
        'consumed_at', v_offer.consumed_at
    );
END;
$$;


--
-- Name: verify_custom_domain(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_custom_domain() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_tenant TEXT;
    v_role TEXT;
BEGIN
    SELECT tenant_id, role INTO v_tenant, v_role FROM profiles WHERE id = auth.uid();
    IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN') THEN RAISE EXCEPTION 'Acesso negado'; END IF;

    UPDATE tenants SET custom_domain_verified = TRUE, custom_domain_verified_at = now()
    WHERE id = v_tenant;
    RETURN TRUE;
END;
$$;


--
-- Name: verify_meeting_link(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_meeting_link(p_student_id uuid, p_works boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role   text;
  v_tenant text;
  v_stud   text;
BEGIN
  SELECT p.role, p.tenant_id INTO v_role, v_tenant
  FROM public.profiles p WHERE p.id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN
     ('TEACHER', 'SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') THEN
    RAISE EXCEPTION 'sem_permissao';
  END IF;

  SELECT p.tenant_id INTO v_stud
  FROM public.profiles p WHERE p.id = p_student_id AND p.role = 'STUDENT';
  IF v_stud IS NULL OR v_stud <> v_tenant THEN
    RAISE EXCEPTION 'aluno_invalido';
  END IF;

  IF COALESCE(p_works, false) THEN
    UPDATE public.profiles
    SET meeting_link_verified_at = now(), meeting_link_verified_by = auth.uid()
    WHERE id = p_student_id;
    RETURN jsonb_build_object('ok', true, 'verificado', true);
  END IF;

  -- Não funcionou: limpa o link. Deixá-lo ali só faria alguém clicar de novo.
  -- A trigger zera a verificação junto.
  UPDATE public.profiles SET meeting_link = NULL WHERE id = p_student_id;
  RETURN jsonb_build_object('ok', true, 'verificado', false, 'link_removido', true);
END;
$$;


--
-- Name: verify_prospect_otp(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_prospect_otp(p_prospect_id uuid, p_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_token RECORD;
    v_code_hash TEXT;
BEGIN
    v_code_hash := encode(digest(p_code, 'sha256'), 'hex');

    SELECT * INTO v_token
    FROM public.otp_tokens
    WHERE target_id = p_prospect_id
      AND target_type = 'PROSPECT_VERIFY'
    ORDER BY created_at DESC
    LIMIT 1;

    IF v_token IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'TOKEN_NOT_FOUND');
    END IF;

    IF v_token.verified_at IS NOT NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'ALREADY_VERIFIED');
    END IF;

    IF v_token.expires_at < now() THEN
        RETURN jsonb_build_object('success', false, 'error', 'TOKEN_EXPIRED');
    END IF;

    IF v_token.attempts >= v_token.max_attempts THEN
        RETURN jsonb_build_object('success', false, 'error', 'MAX_ATTEMPTS_REACHED');
    END IF;

    IF v_token.code_hash != v_code_hash THEN
        UPDATE public.otp_tokens SET attempts = attempts + 1 WHERE id = v_token.id;
        RETURN jsonb_build_object('success', false, 'error', 'INVALID_CODE');
    END IF;

    -- Success! Mark verified.
    UPDATE public.otp_tokens SET verified_at = now() WHERE id = v_token.id;
    UPDATE public.prospects SET verified_at = now(), status = 'VERIFIED' WHERE id = p_prospect_id;

    RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: verify_signature_public(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_signature_public(p_signature_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_sig RECORD;
BEGIN
    SELECT id, contract_hash, signed_at, status, evidence_hmac, pdf_hash,
           is_guardian_signature
    INTO v_sig
    FROM public.enrollment_signatures
    WHERE id = p_signature_id;

    IF v_sig IS NULL THEN
        RETURN jsonb_build_object('valid', false, 'error', 'SIGNATURE_NOT_FOUND');
    END IF;

    RETURN jsonb_build_object(
        'valid', true,
        'signature_id', v_sig.id,
        'contract_hash', v_sig.contract_hash,
        'signed_at', v_sig.signed_at,
        'status', v_sig.status,
        'evidence_hmac', v_sig.evidence_hmac,
        'pdf_hash', v_sig.pdf_hash,
        'is_guardian', v_sig.is_guardian_signature
    );
END;
$$;


--
-- Name: verify_tenant_custom_domain_server(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_tenant_custom_domain_server(p_tenant_id text, p_actor_id uuid, p_expected_dns_token text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  actor_role text := private.active_tenant_role(p_actor_id);
  verified_domain text;
  verified_at timestamptz := now();
BEGIN
  IF NOT private.tenant_is_operational(p_tenant_id) THEN
    RAISE EXCEPTION 'tenant_not_operational' USING ERRCODE = '55000';
  END IF;

  IF p_actor_id IS NULL
    OR actor_role NOT IN ('SCHOOL_ADMIN', 'SUPER_ADMIN')
    OR private.active_tenant_id(p_actor_id) IS DISTINCT FROM p_tenant_id
  THEN
    RAISE EXCEPTION 'cross_tenant_access_denied' USING ERRCODE = '42501';
  END IF;

  UPDATE public.tenants
  SET custom_domain_verified = true,
      custom_domain_verified_at = verified_at
  WHERE id = p_tenant_id
    AND custom_domain IS NOT NULL
    AND custom_domain_dns_token = p_expected_dns_token
  RETURNING custom_domain INTO verified_domain;
  IF verified_domain IS NULL THEN
    RAISE EXCEPTION 'domain_verification_state_changed' USING ERRCODE = '40001';
  END IF;

  INSERT INTO public.tenant_configuration_audit (
    tenant_id,
    actor_id,
    actor_role,
    action,
    section,
    changes
  )
  VALUES (
    p_tenant_id,
    p_actor_id,
    actor_role,
    'custom_domain_verified',
    'domains',
    jsonb_build_object('domain', verified_domain, 'verified', true)
  );

  RETURN verified_at;
END;
$$;


--
-- Name: weekly_digest_rows(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.weekly_digest_rows() RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'tenant_id', t.id, 'school', t.name,
    'director_phone', (SELECT phone FROM profiles WHERE tenant_id=t.id AND role='SCHOOL_ADMIN' AND phone IS NOT NULL AND phone<>'' LIMIT 1),
    'active_students', (SELECT count(DISTINCT student_id) FROM bookings WHERE tenant_id=t.id),
    'classes_week', (SELECT count(*) FROM class_logs WHERE tenant_id=t.id AND class_date >= current_date-7),
    'overdue_count', (SELECT count(*) FROM student_payments WHERE tenant_id=t.id AND status='OVERDUE'),
    'overdue_amount', (SELECT COALESCE(sum(value),0) FROM student_payments WHERE tenant_id=t.id AND status='OVERDUE'),
    'received_week', (SELECT COALESCE(sum(value),0) FROM student_payments WHERE tenant_id=t.id AND status IN ('RECEIVED','RECEIVED_IN_CASH') AND COALESCE(paid_at,payment_date,due_date) >= current_date-7)
  )), '[]'::jsonb)
  FROM tenants t WHERE t.id <> 'master';
$$;


--
-- Name: wolfie_access_for_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wolfie_access_for_user(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if coalesce(auth.jwt() ->> 'role', '') <> 'service_role'
     and p_user_id is distinct from auth.uid() then
    raise exception using errcode = '42501', message = 'forbidden';
  end if;
  return private.wolfie_access_snapshot(p_user_id);
end;
$$;


--
-- Name: wolfie_assignment_stats(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wolfie_assignment_stats(p_month text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_role   text;
  v_tenant text;
  v_start  date;
  v_out    jsonb;
BEGIN
  SELECT p.role, p.tenant_id INTO v_role, v_tenant
  FROM public.profiles p WHERE p.id = auth.uid();
  IF v_role IS NULL OR v_role NOT IN
     ('SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') THEN
    RAISE EXCEPTION 'sem_permissao';
  END IF;

  v_start := date_trunc('month',
    COALESCE(to_date(NULLIF(p_month, ''), 'YYYY-MM'), current_date))::date;

  SELECT jsonb_build_object(
    'prescritas', count(*),
    'enviadas',   count(*) FILTER (WHERE sent_at IS NOT NULL),
    'iniciadas',  count(*) FILTER (WHERE started_at IS NOT NULL),
    'concluidas', count(*) FILTER (WHERE status = 'DONE'),
    'alunos',     count(DISTINCT student_id)
  ) INTO v_out
  FROM public.wolfie_assignments
  WHERE tenant_id = v_tenant
    AND created_at >= v_start
    AND created_at < (v_start + interval '1 month');

  RETURN COALESCE(v_out, '{}'::jsonb);
END;
$$;


--
-- Name: wolfie_insights(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wolfie_insights() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_uid uuid := auth.uid(); v_role text; v_tenant text; r jsonb;
BEGIN
  SELECT role, tenant_id INTO v_role, v_tenant FROM profiles WHERE id=v_uid;
  IF v_role NOT IN ('SCHOOL_ADMIN','SUPER_ADMIN','TEACHER') THEN RETURN jsonb_build_object('error','sem_permissao'); END IF;

  WITH scope AS (
    SELECT ws.* FROM wolfie_sessions ws
    WHERE ws.student_id IN (
      SELECT p.id FROM profiles p WHERE p.role='STUDENT' AND (
        v_role='SUPER_ADMIN'
        OR (v_role='SCHOOL_ADMIN' AND p.tenant_id=v_tenant)
        OR (v_role='TEACHER' AND (p.professor_id=v_uid OR p.professor_id2=v_uid
             OR EXISTS (SELECT 1 FROM bookings b WHERE b.student_id=p.id AND b.teacher_id=v_uid)))
      )
    )
  )
  SELECT jsonb_build_object(
    'totals', jsonb_build_object(
      'sessions', (SELECT count(*) FROM scope),
      'students', (SELECT count(DISTINCT student_id) FROM scope),
      'avg_score', (SELECT round(avg(overall_score)::numeric,1) FROM scope WHERE overall_score IS NOT NULL),
      'minutes', (SELECT COALESCE(round(sum(duration_seconds)/60.0),0) FROM scope),
      'sessions_7d', (SELECT count(*) FROM scope WHERE created_at >= now()-interval '7 days')
    ),
    'weak_points', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('error_type', et, 'count', c) ORDER BY c DESC)
      FROM (SELECT COALESCE(NULLIF(wc.error_type,''),'Outros') AS et, count(*) AS c
            FROM wolfie_corrections wc WHERE wc.session_id IN (SELECT id FROM scope)
            GROUP BY 1 ORDER BY c DESC LIMIT 10) z), '[]'::jsonb),
    'by_student', COALESCE((
      SELECT jsonb_agg(jsonb_build_object('student_id', sid, 'name', (SELECT full_name FROM profiles WHERE id=sid),
        'sessions', cnt, 'avg_score', avgs, 'last_at', last_at, 'minutes', mins) ORDER BY cnt DESC)
      FROM (SELECT student_id AS sid, count(*) AS cnt, round(avg(overall_score)::numeric,1) AS avgs,
               max(created_at) AS last_at, COALESCE(round(sum(duration_seconds)/60.0),0) AS mins
            FROM scope GROUP BY student_id ORDER BY cnt DESC LIMIT 20) z), '[]'::jsonb),
    'never_used', (
      SELECT count(*) FROM profiles p WHERE p.role='STUDENT'
        AND (v_role='SUPER_ADMIN' OR (v_role='SCHOOL_ADMIN' AND p.tenant_id=v_tenant)
             OR (v_role='TEACHER' AND (p.professor_id=v_uid OR p.professor_id2=v_uid)))
        AND NOT EXISTS (SELECT 1 FROM wolfie_sessions ws2 WHERE ws2.student_id=p.id)
        AND EXISTS (SELECT 1 FROM bookings b WHERE b.student_id=p.id)
    )
  ) INTO r;
  RETURN r;
END;
$$;


--
-- Name: wolfie_live_balance(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wolfie_live_balance(p_tenant_id text, p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_tenant_id is null
     or p_student_id is null
     or not exists (
       select 1
         from public.profiles as profile
         join public.tenant_memberships as membership
           on membership.user_id = profile.id
          and membership.tenant_id = p_tenant_id
          and membership.status = 'ACTIVE'
          and membership.role = 'STUDENT'
        where profile.id = p_student_id
          and profile.role = 'STUDENT'
     ) then
    raise exception using
      errcode = '42501',
      message = 'student_active_tenant_membership_not_found';
  end if;

  return private.wolfie_live_balance_snapshot(p_tenant_id, p_student_id);
end;
$$;


