  );
$$;


--
-- Name: wolfie_realtime_quota_status(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wolfie_realtime_quota_status(p_tenant_id text, p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_enabled boolean;
  v_quota   bigint;
  v_used    bigint;
  v_start   date := date_trunc('month', current_date)::date;
BEGIN
  SELECT s.enabled, s.monthly_token_quota INTO v_enabled, v_quota
  FROM public.tenant_realtime_settings s
  WHERE s.tenant_id = p_tenant_id;

  -- Sem linha configurada = cota desligada. Nunca bloqueia por omissão.
  IF v_enabled IS NOT TRUE OR COALESCE(v_quota, 0) <= 0 THEN
    RETURN jsonb_build_object('allowed', true, 'enforced', false);
  END IF;

  SELECT COALESCE(sum(
           COALESCE(t.usage_input_audio_tokens, 0)
         + COALESCE(t.usage_output_audio_tokens, 0)
         + COALESCE(t.usage_input_text_tokens, 0)
         + COALESCE(t.usage_output_text_tokens, 0)), 0)
    INTO v_used
  FROM public.wolfie_turns t
  JOIN public.wolfie_sessions ws ON ws.id = t.session_id
  WHERE t.source_kind = 'openai_realtime'
    AND ws.student_id = p_student_id
    AND ws.tenant_id  = p_tenant_id
    AND t.created_at >= v_start
    AND t.created_at <  (v_start + interval '1 month');

  RETURN jsonb_build_object(
    'allowed',  v_used < v_quota,
    'enforced', true,
    'used',     v_used,
    'quota',    v_quota
  );
EXCEPTION WHEN others THEN
  -- Falha de contabilidade nunca pode impedir a aula.
  RETURN jsonb_build_object('allowed', true, 'enforced', false,
                            'reason', 'quota_check_failed');
END;
$$;


--
-- Name: wolfie_realtime_usage_report(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wolfie_realtime_usage_report(p_month text DEFAULT NULL::text) RETURNS TABLE(student_id uuid, student_name text, sessions integer, turns integer, input_audio_tokens bigint, output_audio_tokens bigint, input_text_tokens bigint, output_text_tokens bigint, cached_tokens bigint, total_tokens bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
#variable_conflict use_column
declare
  v_caller uuid := (select auth.uid());
  v_tenant text;
  v_role text;
  v_start date;
begin
  v_tenant := private.active_tenant_id(v_caller);
  v_role := private.active_tenant_role(v_caller);
  if v_tenant is null
     or v_role not in ('SCHOOL_ADMIN', 'SUPER_ADMIN', 'COORDINATOR') then
    raise exception using errcode = '42501', message = 'sem_permissao';
  end if;

  v_start := date_trunc(
    'month',
    coalesce(
      to_date(nullif(p_month, ''), 'YYYY-MM'),
      current_date
    )
  )::date;

  return query
  select
    session.student_id,
    coalesce(profile.full_name, '?')::text,
    pg_catalog.count(distinct session.id)::integer,
    pg_catalog.count(turn_row.id)::integer,
    coalesce(pg_catalog.sum(turn_row.usage_input_audio_tokens), 0)::bigint,
    coalesce(pg_catalog.sum(turn_row.usage_output_audio_tokens), 0)::bigint,
    coalesce(pg_catalog.sum(turn_row.usage_input_text_tokens), 0)::bigint,
    coalesce(pg_catalog.sum(turn_row.usage_output_text_tokens), 0)::bigint,
    coalesce(pg_catalog.sum(turn_row.usage_cached_tokens), 0)::bigint,
    coalesce(pg_catalog.sum(turn_row.tokens_used), 0)::bigint
  from public.wolfie_turns as turn_row
  join public.wolfie_sessions as session
    on session.id = turn_row.session_id
  left join public.profiles as profile on profile.id = session.student_id
  where turn_row.source_kind = 'openai_realtime'
    and turn_row.speaker = 'wolfie'
    and session.tenant_id = v_tenant
    and turn_row.created_at >= v_start
    and turn_row.created_at < v_start + interval '1 month'
  group by session.student_id, profile.full_name
  order by 10 desc;
end;
$$;


--
-- Name: wolfie_tier_for_student(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wolfie_tier_for_student(p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  -- Chamada autenticada só pode perguntar por si mesma; service_role (auth.uid()
  -- nulo) é a edge function e pode perguntar por qualquer aluno.
  IF auth.uid() IS NOT NULL AND p_student_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'sem_permissao';
  END IF;
  RETURN private.wolfie_tier_snapshot(p_student_id);
END;
$$;


