);


--
-- Name: tenant_integration_connections; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.tenant_integration_connections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    provider text NOT NULL,
    mode text NOT NULL,
    status text DEFAULT 'healthy'::text NOT NULL,
    connection_config jsonb DEFAULT '{}'::jsonb NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    last_verified_at timestamp with time zone,
    last_error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tenant_integration_connections_config_check CHECK (private.tenant_integration_config_is_valid(provider, mode, connection_config)),
    CONSTRAINT tenant_integration_connections_last_error_code_check CHECK (((last_error_code IS NULL) OR ((length(last_error_code) >= 2) AND (length(last_error_code) <= 80)))),
    CONSTRAINT tenant_integration_connections_mode_check CHECK ((((provider = 'evolution'::text) AND (mode = ANY (ARRAY['PLATFORM_MANAGED'::text, 'TENANT_BYOK'::text, 'DISABLED'::text]))) OR ((provider = 'asaas'::text) AND ((mode = 'DISABLED'::text) OR ((mode = 'PLATFORM_MANAGED_ROOT'::text) AND (tenant_id = 'school-wise-wolf'::text)))) OR ((provider = ANY (ARRAY['openai'::text, 'openrouter'::text])) AND (mode = ANY (ARRAY['PLATFORM_MANAGED'::text, 'TENANT_BYOK'::text, 'DISABLED'::text]))))),
    CONSTRAINT tenant_integration_connections_mode_status_check CHECK ((((mode = 'DISABLED'::text) AND (status = 'disabled'::text)) OR ((mode <> 'DISABLED'::text) AND (status <> 'disabled'::text)))),
    CONSTRAINT tenant_integration_connections_provider_check CHECK ((provider = ANY (ARRAY['asaas'::text, 'evolution'::text, 'openai'::text, 'openrouter'::text]))),
    CONSTRAINT tenant_integration_connections_status_check CHECK ((status = ANY (ARRAY['configured'::text, 'healthy'::text, 'error'::text, 'disabled'::text]))),
    CONSTRAINT tenant_integration_connections_version_check CHECK ((version > 0))
);


