    CONSTRAINT asaas_outbound_message_attempts_provider_instance_check CHECK (((provider_instance_name IS NULL) OR (((char_length(provider_instance_name) >= 3) AND (char_length(provider_instance_name) <= 120)) AND (provider_instance_name = btrim(provider_instance_name)) AND (provider_instance_name !~ '[[:cntrl:]]'::text)))),
