    CONSTRAINT asaas_outbound_message_attempts_status_check CHECK ((status = ANY (ARRAY['CLAIMED'::text, 'SUBMITTING'::text, 'SENT'::text, 'FAILED'::text, 'UNKNOWN'::text, 'SUPPRESSED'::text]))),
