    lifecycle_released_at timestamp with time zone,
    lifecycle_last_error text,
    CONSTRAINT asaas_creation_external_reference_length CHECK (((length(external_reference) >= 1) AND (length(external_reference) <= 240))),
    CONSTRAINT asaas_creation_fingerprint_format CHECK ((request_fingerprint ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT asaas_creation_lifecycle_binding_kind_check CHECK (((lifecycle_binding_kind IS NULL) OR (lifecycle_binding_kind = ANY (ARRAY['CUSTOMER'::text, 'ENROLLMENT_PAYMENT'::text, 'SUBSCRIPTION'::text, 'BILLING_PERIOD_PAYMENT'::text, 'STUDENT_PAYMENT'::text, 'TOPUP_ORDER'::text])))),
    CONSTRAINT asaas_creation_logical_key_length CHECK (((length(logical_key) >= 1) AND (length(logical_key) <= 240))),
    CONSTRAINT asaas_creation_request_snapshot_object CHECK (((jsonb_typeof(request_snapshot) = 'object'::text) AND (octet_length((request_snapshot)::text) <= 4096))),
    CONSTRAINT asaas_provider_creation_attempts_operation_check CHECK ((operation = ANY (ARRAY['CUSTOMER_CREATE'::text, 'PAYMENT_CREATE'::text, 'SUBSCRIPTION_CREATE'::text]))),
