    CONSTRAINT attendance_confirmations_resolution_verdict_check CHECK (((resolution_verdict IS NULL) OR (resolution_verdict = ANY (ARRAY['TEACHER_PRESENT'::text, 'TEACHER_ABSENT'::text, 'PAY'::text, 'DO_NOT_PAY'::text])))),
    CONSTRAINT attendance_confirmations_student_response_check CHECK (((student_response IS NULL) OR (student_response = ANY (ARRAY['STUDENT_PRESENT'::text, 'TEACHER_NO_SHOW'::text, 'STUDENT_SELF_ABSENT'::text, 'CANCELLED_RESCHEDULED'::text]))))
);


