    CONSTRAINT hub_core_legal_acceptances_terms_snapshot_check CHECK (((octet_length(terms_snapshot) >= 512) AND (octet_length(terms_snapshot) <= 65536))),
    CONSTRAINT hub_core_legal_acceptances_terms_version_check CHECK (((char_length(terms_version) >= 10) AND (char_length(terms_version) <= 80)))
);


