--
-- Name: management_payment_notification_outbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.management_payment_notification_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    payment_id uuid NOT NULL,
    notification_kind text NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    claim_token uuid,
    lease_expires_at timestamp with time zone,
    submit_attempt_count integer DEFAULT 0 NOT NULL,
    configured_destination_snapshot text,
    provider_destination text,
    provider_instance_name text,
    provider_integration_id uuid,
    provider_integration_version bigint,
    provider_endpoint_hash text,
    provider_credential_hash text,
    message_body text,
    source_snapshot jsonb,
    source_snapshot_hash text,
    snapshot_hash text,
    provider_message_id text,
    provider_http_status integer,
    provider_delivery_status text,
    last_error text,
    accepted_at timestamp with time zone,
    delivered_at timestamp with time zone,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT management_payment_notification__provider_delivery_status_check CHECK (((provider_delivery_status IS NULL) OR (provider_delivery_status = ANY (ARRAY['accepted'::text, 'sent'::text, 'delivered'::text, 'read'::text, 'failed'::text, 'uncertain'::text])))),
    CONSTRAINT management_payment_notification_claim_check CHECK (COALESCE((((status = 'PENDING'::text) AND (claim_token IS NULL) AND (lease_expires_at IS NULL) AND (submit_attempt_count = 0)) OR ((status = 'CLAIMED'::text) AND (claim_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (submit_attempt_count = 0)) OR ((status = 'PREPARED'::text) AND (claim_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (submit_attempt_count = 0) AND (configured_destination_snapshot IS NOT NULL) AND (provider_destination IS NOT NULL) AND (provider_instance_name IS NOT NULL) AND (provider_integration_id IS NOT NULL) AND (provider_integration_version > 0) AND (provider_endpoint_hash IS NULL) AND (provider_credential_hash IS NULL) AND (message_body IS NOT NULL) AND (jsonb_typeof(source_snapshot) = 'object'::text) AND (source_snapshot_hash ~ '^[0-9a-f]{64}$'::text) AND (snapshot_hash IS NULL)) OR ((status = ANY (ARRAY['SUBMITTING'::text, 'SENT'::text, 'FAILED'::text, 'UNKNOWN'::text])) AND (claim_token IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (submit_attempt_count = 1) AND (configured_destination_snapshot IS NOT NULL) AND (provider_destination IS NOT NULL) AND (provider_instance_name IS NOT NULL) AND (provider_integration_id IS NOT NULL) AND (provider_integration_version > 0) AND (provider_endpoint_hash ~ '^[0-9a-f]{64}$'::text) AND (provider_credential_hash ~ '^[0-9a-f]{64}$'::text) AND (message_body IS NOT NULL) AND (jsonb_typeof(source_snapshot) = 'object'::text) AND (source_snapshot_hash ~ '^[0-9a-f]{64}$'::text) AND (snapshot_hash ~ '^[0-9a-f]{64}$'::text)) OR ((status = 'SUPPRESSED'::text) AND (submit_attempt_count = 0))), false)),
    CONSTRAINT management_payment_notification_outb_submit_attempt_count_check CHECK (((submit_attempt_count >= 0) AND (submit_attempt_count <= 1))),
    CONSTRAINT management_payment_notification_outbox_notification_kind_check CHECK ((notification_kind = ANY (ARRAY['PAYMENT_SPLIT'::text, 'PAYMENT_RECEIVED'::text]))),
    CONSTRAINT management_payment_notification_outbox_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'CLAIMED'::text, 'PREPARED'::text, 'SUBMITTING'::text, 'SENT'::text, 'FAILED'::text, 'UNKNOWN'::text, 'SUPPRESSED'::text])))
);

ALTER TABLE ONLY public.management_payment_notification_outbox FORCE ROW LEVEL SECURITY;


