    CONSTRAINT pedagogical_evaluation_catalog_book_part_check CHECK ((book_part ~ '^(A1|A2|B1|B2|C1|C2)-[1-4]$'::text)),
    CONSTRAINT pedagogical_evaluation_catalog_identity_check CHECK ((book_part = ((module || '-'::text) || (part)::text))),
    CONSTRAINT pedagogical_evaluation_catalog_module_check CHECK ((module = ANY (ARRAY['A1'::text, 'A2'::text, 'B1'::text, 'B2'::text, 'C1'::text, 'C2'::text]))),
    CONSTRAINT pedagogical_evaluation_catalog_next_check CHECK (((next_book_part IS NULL) OR (next_book_part ~ '^(A1|A2|B1|B2|C1|C2)-[1-4]$'::text))),
    CONSTRAINT pedagogical_evaluation_catalog_part_check CHECK (((part >= 1) AND (part <= 4)))
);


