-- Name: pedagogical_materials; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.pedagogical_materials (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text,
    title text NOT NULL,
    file_url text NOT NULL,
    type text NOT NULL,
    level_tag text,
    category text,
    is_global boolean DEFAULT false,
    scope text DEFAULT 'TENANT'::text,
    uploaded_by uuid,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    niche text DEFAULT 'GENERAL'::text,
    approval_status text DEFAULT 'APPROVED'::text NOT NULL,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    rejection_reason text,
    collection_id uuid,
    part_number integer,
    hub_object_path text,
    hub_sync_status text DEFAULT 'CONSENT_REQUIRED'::text NOT NULL,
    hub_sync_error text,
    hub_synced_at timestamp with time zone,
    storage_object_path text,
    hub_preview_source_path text,
    hub_preview_object_path text,
    hub_catalog_opt_in boolean DEFAULT false NOT NULL,
    hub_commercial_approved boolean DEFAULT false NOT NULL,
    hub_rights_basis text,
    hub_rights_declaration text,
    hub_publication_requested_by uuid,
    hub_publication_requested_at timestamp with time zone,
    hub_rights_verified_by uuid,
    hub_rights_verified_at timestamp with time zone,
    hub_publication_revoked_by uuid,
    hub_publication_revoked_at timestamp with time zone,
    CONSTRAINT pedagogical_materials_hub_commercial_approval_check CHECK (((hub_commercial_approved IS FALSE) OR ((hub_catalog_opt_in IS TRUE) AND (hub_rights_verified_by IS NOT NULL) AND (hub_rights_verified_at IS NOT NULL) AND (hub_rights_verified_by <> hub_publication_requested_by)))),
    CONSTRAINT pedagogical_materials_hub_preview_source_path_check CHECK (((hub_preview_source_path IS NULL) OR ((hub_preview_source_path !~ '(^|/)[.][.]?(/|$)'::text) AND (hub_preview_source_path !~ '^/'::text) AND ((octet_length(hub_preview_source_path) >= 3) AND (octet_length(hub_preview_source_path) <= 1024))))),
    CONSTRAINT pedagogical_materials_hub_publication_consent_check CHECK (((hub_catalog_opt_in IS FALSE) OR ((approval_status = 'APPROVED'::text) AND (upper(COALESCE(type, ''::text)) <> 'LINK'::text) AND (storage_object_path IS NOT NULL) AND (hub_preview_source_path IS NOT NULL) AND (storage_object_path <> hub_preview_source_path) AND (hub_rights_basis = ANY (ARRAY['OWNED'::text, 'LICENSED'::text, 'PUBLIC_DOMAIN'::text])) AND ((char_length(btrim(COALESCE(hub_rights_declaration, ''::text))) >= 20) AND (char_length(btrim(COALESCE(hub_rights_declaration, ''::text))) <= 2000)) AND (hub_publication_requested_by IS NOT NULL) AND (hub_publication_requested_at IS NOT NULL)))),
    CONSTRAINT pedagogical_materials_hub_rights_basis_check CHECK (((hub_rights_basis IS NULL) OR (hub_rights_basis = ANY (ARRAY['OWNED'::text, 'LICENSED'::text, 'PUBLIC_DOMAIN'::text])))),
    CONSTRAINT pedagogical_materials_hub_sync_status_check CHECK ((hub_sync_status = ANY (ARRAY['CONSENT_REQUIRED'::text, 'RIGHTS_REVIEW_REQUIRED'::text, 'PENDING'::text, 'SYNCING'::text, 'SYNCED'::text, 'FAILED'::text, 'NOT_APPLICABLE'::text]))),
    CONSTRAINT pedagogical_materials_scope_check CHECK ((scope = ANY (ARRAY['GLOBAL'::text, 'TENANT'::text, 'PRIVATE'::text]))),
    CONSTRAINT pedagogical_materials_storage_object_path_check CHECK (((storage_object_path IS NULL) OR ((storage_object_path !~ '(^|/)[.][.]?(/|$)'::text) AND (storage_object_path !~ '^/'::text) AND ((octet_length(storage_object_path) >= 3) AND (octet_length(storage_object_path) <= 1024))))),
    CONSTRAINT pedagogical_materials_type_check CHECK ((type = ANY (ARRAY['PDF'::text, 'VIDEO'::text, 'LINK'::text, 'IMAGE'::text])))
);


