    CONSTRAINT planner_ai_runs_json_shapes_check CHECK (((jsonb_typeof(retrieved_sources) = 'array'::text) AND (jsonb_typeof(result) = 'object'::text) AND (jsonb_typeof(usage) = 'object'::text))),
    CONSTRAINT planner_ai_runs_latency_ms_check CHECK (((latency_ms IS NULL) OR (latency_ms >= 0))),
    CONSTRAINT planner_ai_runs_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'SAVED'::text, 'EXPIRED'::text]))),
    CONSTRAINT planner_ai_runs_task_mode_check CHECK ((task_mode = ANY (ARRAY['lesson_plan'::text, 'student_feedback'::text, 'oral_test'::text, 'homework'::text, 'class_script'::text, 'vocabulary'::text, 'presentation_coaching'::text, 'progress_report'::text, 'material_generation'::text])))
);


