    CONSTRAINT profiles_lifecycle_status_chk CHECK ((lifecycle_status = ANY (ARRAY['active'::text, 'suspended'::text, 'offboarded'::text]))),
    CONSTRAINT profiles_notification_preference_check CHECK ((notification_preference = ANY (ARRAY['OFF'::text, 'WHATSAPP'::text, 'PUSH_WEB'::text]))),
    CONSTRAINT profiles_offboarded_student_not_financially_active CHECK ((NOT ((role = 'STUDENT'::text) AND (lower(btrim(COALESCE(lifecycle_status, ''::text))) = 'offboarded'::text) AND (upper(btrim(COALESCE(status_financial, ''::text))) <> ALL (ARRAY['SUSPENDED'::text, 'ARCHIVED'::text]))))),
    CONSTRAINT profiles_offboarding_status_check CHECK ((offboarding_status = ANY (ARRAY['REQUESTED'::text, 'APPROVED'::text, 'REASSIGNING'::text, 'COMPLETED'::text]))),
