    CONSTRAINT recurring_expenses_end_month_check CHECK ((end_month ~ '^\d{4}-\d{2}$'::text)),
    CONSTRAINT recurring_expenses_periodo_valido CHECK (((end_month IS NULL) OR (end_month >= start_month))),
    CONSTRAINT recurring_expenses_start_month_check CHECK ((start_month ~ '^\d{4}-\d{2}$'::text))
);


