--
-- Name: referral_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.referral_stats WITH (security_invoker='true') AS
 SELECT r.id AS referrer_id,
    r.full_name AS referrer_name,
    r.role AS referrer_role,
    r.tenant_id,
    count(p.id) AS total_referrals,
    (count(p.id) * 45) AS total_bonus_brl,
    max(p.created_at) AS last_referral_at
   FROM (public.profiles r
     LEFT JOIN public.profiles p ON (((p.referrer_teacher_id = r.id) OR (p.referrer_student_id = r.id))))
  WHERE (r.role = ANY (ARRAY['TEACHER'::text, 'STUDENT'::text]))
  GROUP BY r.id, r.full_name, r.role, r.tenant_id;


