    CONSTRAINT student_payments_asaas_payment_id_nonempty_chk CHECK (((asaas_payment_id IS NULL) OR (btrim(asaas_payment_id) <> ''::text))),
    CONSTRAINT student_payments_payment_type_check CHECK ((payment_type = ANY (ARRAY['SUBSCRIPTION'::text, 'ENROLLMENT'::text, 'PRO_RATA'::text, 'REFUND'::text, 'OTHER'::text]))),
    CONSTRAINT student_payments_provider_alias_consistency_chk CHECK (((NULLIF(TRIM(BOTH FROM COALESCE(asaas_id, ''::text)), ''::text) IS NULL) OR (NULLIF(TRIM(BOTH FROM COALESCE(asaas_payment_id, ''::text)), ''::text) = NULLIF(TRIM(BOTH FROM COALESCE(asaas_id, ''::text)), ''::text)))),
    CONSTRAINT student_payments_provider_customer_shape CHECK (((provider_customer_id IS NULL) OR ((provider_customer_id = btrim(provider_customer_id)) AND ((length(provider_customer_id) >= 1) AND (length(provider_customer_id) <= 240))))),
    CONSTRAINT student_payments_refunded_amount_valid CHECK (((refunded_amount >= (0)::numeric) AND (((value IS NULL) AND (refunded_amount = (0)::numeric)) OR ((value IS NOT NULL) AND (refunded_amount <= value)))))
);


--
-- Name: COLUMN student_payments.tenant_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.student_payments.tenant_id IS 'Tenant resolved from the canonical student/customer relationship. There is deliberately no default: unresolved Asaas money goes to triage.';


--
-- Name: COLUMN student_payments.exclusion_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.student_payments.exclusion_reason IS 'Preenchido quando o pagamento sai da receita (status NAO_RECEITA): guarda o motivo e o status original.';


--
-- Name: COLUMN student_payments.credited_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.student_payments.credited_at IS 'Actual Asaas balance availability (payment.creditDate). Never populated from estimatedCreditDate or PAYMENT_CONFIRMED.';


--
-- Name: COLUMN student_payments.refunded_amount; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.student_payments.refunded_amount IS 'Cumulative completed provider refund, bounded by the original payment value.';


--
-- Name: COLUMN student_payments.last_provider_event_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.student_payments.last_provider_event_id IS 'ID estavel do ultimo evento aplicado. Em estorno, e a chave idempotente da SAIDA correspondente.';


--
-- Name: COLUMN student_payments.last_provider_event_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.student_payments.last_provider_event_at IS 'Instante declarado pelo provedor para o ultimo evento aplicado; nunca e sintetizado pelo ledger.';


--
-- Name: COLUMN student_payments.provider_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.student_payments.provider_status IS 'Latest observed Asaas lifecycle status. Kept separate so a provider retry never erases the local NAO_RECEITA classification.';


--
-- Name: COLUMN student_payments.estimated_credit_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.student_payments.estimated_credit_at IS 'Provider estimate only; never used as actual cash availability.';


--
-- Name: COLUMN student_payments.provider_customer_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.student_payments.provider_customer_id IS 'Immutable Asaas customer snapshot captured when the provider payment is first bound. Historical events validate this value instead of the mutable current profile customer.';


