-- Name: TABLE student_plan_entitlements; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.student_plan_entitlements IS 'Limites por plano de aluno. Só mede voz ao vivo; escrita é ilimitada.';


