--
-- Name: wolfie_corrections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wolfie_corrections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    session_id uuid NOT NULL,
    turn_id uuid,
    wrong_sentence text NOT NULL,
    correct_sentence text NOT NULL,
    explanation_pt text,
    error_type text,
    natural_sentence text,
    priority text DEFAULT 'medium'::text NOT NULL,
    skill_focus text,
    requires_retry boolean DEFAULT true NOT NULL,
    retry_completed boolean DEFAULT false NOT NULL,
    retry_turn_id uuid,
    retry_score smallint,
    retry_feedback jsonb DEFAULT '{}'::jsonb NOT NULL,
    retry_completed_at timestamp with time zone,
    status text DEFAULT 'active'::text NOT NULL,
    status_reason text,
    disputed_at timestamp with time zone,
    invalidated_at timestamp with time zone,
    superseded_at timestamp with time zone,
    superseded_by_correction_id uuid,
    CONSTRAINT wolfie_corrections_priority_check CHECK ((priority = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text]))),
    CONSTRAINT wolfie_corrections_retry_state_check CHECK (((jsonb_typeof(retry_feedback) = 'object'::text) AND ((retry_score IS NULL) OR ((retry_score >= 0) AND (retry_score <= 100))) AND ((NOT retry_completed) OR ((retry_turn_id IS NOT NULL) AND (retry_completed_at IS NOT NULL))))),
    CONSTRAINT wolfie_corrections_skill_focus_check CHECK (((skill_focus IS NULL) OR (skill_focus = ANY (ARRAY['grammar'::text, 'vocabulary'::text, 'pronunciation'::text, 'fluency'::text, 'formality'::text, 'clarity'::text, 'structure'::text, 'naturalness'::text])))),
    CONSTRAINT wolfie_corrections_status_check CHECK ((status = ANY (ARRAY['active'::text, 'disputed'::text, 'invalid'::text, 'superseded'::text]))),
    CONSTRAINT wolfie_corrections_status_reason_check CHECK (((status_reason IS NULL) OR (char_length(status_reason) <= 1000))),
    CONSTRAINT wolfie_corrections_status_state_check CHECK ((((status = 'active'::text) AND (disputed_at IS NULL) AND (invalidated_at IS NULL) AND (superseded_at IS NULL)) OR ((status = 'disputed'::text) AND (disputed_at IS NOT NULL) AND (NOT requires_retry)) OR ((status = 'invalid'::text) AND (invalidated_at IS NOT NULL) AND (NOT requires_retry)) OR ((status = 'superseded'::text) AND (superseded_at IS NOT NULL) AND (NOT requires_retry))))
);


--
-- Name: COLUMN wolfie_corrections.retry_turn_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wolfie_corrections.retry_turn_id IS 'Student turn that proves the required new attempt was actually made.';


--
-- Name: COLUMN wolfie_corrections.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wolfie_corrections.status IS 'Lifecycle of a model-proposed correction. Only active corrections may lock retry.';


--
-- Name: COLUMN wolfie_corrections.status_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wolfie_corrections.status_reason IS 'Bounded audit reason for dispute, invalidation or supersession.';


--
-- Name: wolfie_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wolfie_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    tenant_id text NOT NULL,
    student_id uuid NOT NULL,
    topic text NOT NULL,
    subtopic text,
    mode text NOT NULL,
    student_level text NOT NULL,
    turn_count integer DEFAULT 0,
    student_word_count integer DEFAULT 0,
    wolfie_word_count integer DEFAULT 0,
    duration_seconds integer DEFAULT 0,
    config_snapshot jsonb DEFAULT '{}'::jsonb,
    overall_score integer,
    summary text,
    avatar_id text,
    scenario_id text,
    scenario_step integer DEFAULT 1,
    summary_json jsonb,
    finished_at timestamp with time zone,
    started_at timestamp with time zone DEFAULT now(),
    experience_mode text DEFAULT 'free_conversation'::text NOT NULL,
    correction_mode text DEFAULT 'selective'::text NOT NULL,
    language_mode text DEFAULT 'bilingual'::text NOT NULL,
    difficulty text DEFAULT 'balanced'::text NOT NULL,
    scenario_context text,
    student_goal text,
    target_skill text,
    current_stage text DEFAULT 'discovery'::text NOT NULL,
    scenario_status text DEFAULT 'active'::text NOT NULL,
    planned_duration_minutes integer,
    time_limit_seconds integer,
    retry_count integer DEFAULT 0 NOT NULL,
    needs_external_verification boolean DEFAULT false NOT NULL,
    report_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    memory_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    sensitive_memory_consent_at timestamp with time zone,
    transcript_retention_until timestamp with time zone,
    last_activity_at timestamp with time zone DEFAULT now() NOT NULL,
    realtime_first_client_turn_id uuid,
    classic_handoff_at timestamp with time zone,
    classic_first_client_turn_id uuid,
    CONSTRAINT wolfie_sessions_correction_mode_check CHECK ((correction_mode = ANY (ARRAY['immediate'::text, 'end'::text, 'selective'::text, 'examiner'::text]))),
    CONSTRAINT wolfie_sessions_difficulty_check CHECK ((difficulty = ANY (ARRAY['supportive'::text, 'balanced'::text, 'challenging'::text, 'adaptive'::text]))),
    CONSTRAINT wolfie_sessions_experience_mode_check CHECK ((experience_mode = ANY (ARRAY['free_conversation'::text, 'guided_lesson'::text, 'roleplay'::text, 'presentation'::text, 'global_meeting'::text, 'interview'::text, 'exam'::text, 'writing'::text, 'pronunciation'::text, 'vocabulary'::text, 'storytelling'::text, 'child_mission'::text, 'teen_challenge'::text, 'examiner'::text, 'fluency'::text, 'emergency'::text]))),
    CONSTRAINT wolfie_sessions_json_shapes_check CHECK (((jsonb_typeof(report_json) = 'object'::text) AND (jsonb_typeof(memory_summary) = 'object'::text))),
    CONSTRAINT wolfie_sessions_language_mode_check CHECK ((language_mode = ANY (ARRAY['pt_support'::text, 'bilingual'::text, 'immersive'::text, 'english_rescue'::text]))),
    CONSTRAINT wolfie_sessions_retry_count_check CHECK ((retry_count >= 0)),
    CONSTRAINT wolfie_sessions_scenario_status_check CHECK ((scenario_status = ANY (ARRAY['active'::text, 'awaiting_retry'::text, 'completed'::text, 'abandoned'::text, 'failed'::text]))),
    CONSTRAINT wolfie_sessions_timing_check CHECK ((((planned_duration_minutes IS NULL) OR ((planned_duration_minutes >= 1) AND (planned_duration_minutes <= 240))) AND ((time_limit_seconds IS NULL) OR ((time_limit_seconds >= 10) AND (time_limit_seconds <= 86400))) AND ((finished_at IS NULL) OR (started_at IS NULL) OR (finished_at >= started_at))))
);


--
-- Name: COLUMN wolfie_sessions.tenant_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wolfie_sessions.tenant_id IS 'Tenant text identifier; references public.tenants(id).';


--
-- Name: COLUMN wolfie_sessions.scenario_context; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wolfie_sessions.scenario_context IS 'Bounded session scenario and objective supplied by the application; treated as untrusted learning data.';


--
-- Name: COLUMN wolfie_sessions.realtime_first_client_turn_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wolfie_sessions.realtime_first_client_turn_id IS 'Idempotency anchor when the first completed Realtime exchange creates the session.';


--
-- Name: COLUMN wolfie_sessions.classic_handoff_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wolfie_sessions.classic_handoff_at IS 'Server-authorized boundary after which a Realtime session continues via classic turns while retaining its existing history and retry state.';


--
-- Name: COLUMN wolfie_sessions.classic_first_client_turn_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wolfie_sessions.classic_first_client_turn_id IS 'Idempotency anchor for the first classic exchange, including recovery after a lost HTTP response.';


--
-- Name: student_recent_corrections; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.student_recent_corrections WITH (security_invoker='true') AS
 SELECT c.id,
    c.created_at,
    c.session_id,
    c.turn_id,
    c.wrong_sentence,
    c.correct_sentence,
    c.explanation_pt,
    c.error_type,
    s.student_id
   FROM (public.wolfie_corrections c
     JOIN public.wolfie_sessions s ON ((c.session_id = s.id)));


