);

ALTER TABLE ONLY public.student_renewal_case_event_notes FORCE ROW LEVEL SECURITY;


--
-- Name: student_renewal_case_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.student_renewal_case_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    renewal_case_id uuid NOT NULL,
    student_id uuid,
    student_id_snapshot uuid NOT NULL,
    actor_id uuid NOT NULL,
    actor_name_snapshot text NOT NULL,
    request_id uuid NOT NULL,
    action text NOT NULL,
    from_status text,
    to_status text NOT NULL,
    channel text,
    contact_at timestamp with time zone,
    next_action_at timestamp with time zone,
    interest_term_months smallint,
    request_envelope jsonb NOT NULL,
    request_fingerprint text NOT NULL,
    result_version integer NOT NULL,
    result_last_contact_at timestamp with time zone,
    result_last_channel text,
    result_next_action_at timestamp with time zone,
    result_interest_term_months smallint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT student_renewal_case_events_action_check CHECK ((action = ANY (ARRAY['CONTACTED'::text, 'SCHEDULE_FOLLOW_UP'::text, 'RECORD_INTEREST'::text, 'AWAIT_FORMALIZATION'::text, 'RECORD_NOT_CONTINUING'::text, 'REOPEN'::text]))),
    CONSTRAINT student_renewal_case_events_actor_name_check CHECK (((char_length(btrim(actor_name_snapshot)) >= 1) AND (char_length(btrim(actor_name_snapshot)) <= 200))),
    CONSTRAINT student_renewal_case_events_channel_check CHECK (((channel IS NULL) OR (channel = ANY (ARRAY['WHATSAPP'::text, 'PHONE'::text, 'EMAIL'::text, 'OTHER'::text])))),
    CONSTRAINT student_renewal_case_events_from_status_check CHECK (((from_status IS NULL) OR (from_status = ANY (ARRAY['PENDING_CONTACT'::text, 'AWAITING_REPLY'::text, 'FOLLOW_UP_SCHEDULED'::text, 'INTEREST_RECORDED'::text, 'FORMALIZATION_PENDING'::text, 'NOT_CONTINUING_RECORDED'::text])))),
    CONSTRAINT student_renewal_case_events_interest_term_check CHECK (((interest_term_months IS NULL) OR (interest_term_months = ANY (ARRAY[6, 12])))),
    CONSTRAINT student_renewal_case_events_request_envelope_check CHECK ((jsonb_typeof(request_envelope) = 'object'::text)),
    CONSTRAINT student_renewal_case_events_request_fingerprint_check CHECK ((request_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT student_renewal_case_events_request_fingerprint_matches CHECK ((request_fingerprint = encode(extensions.digest(convert_to((request_envelope)::text, 'UTF8'::name), 'sha256'::text), 'hex'::text))),
    CONSTRAINT student_renewal_case_events_result_channel_check CHECK (((result_last_channel IS NULL) OR (result_last_channel = ANY (ARRAY['WHATSAPP'::text, 'PHONE'::text, 'EMAIL'::text, 'OTHER'::text])))),
    CONSTRAINT student_renewal_case_events_result_interest_check CHECK (((result_interest_term_months IS NULL) OR (result_interest_term_months = ANY (ARRAY[6, 12])))),
    CONSTRAINT student_renewal_case_events_result_version_check CHECK ((result_version > 0)),
    CONSTRAINT student_renewal_case_events_to_status_check CHECK ((to_status = ANY (ARRAY['PENDING_CONTACT'::text, 'AWAITING_REPLY'::text, 'FOLLOW_UP_SCHEDULED'::text, 'INTEREST_RECORDED'::text, 'FORMALIZATION_PENDING'::text, 'NOT_CONTINUING_RECORDED'::text])))
);

ALTER TABLE ONLY public.student_renewal_case_events FORCE ROW LEVEL SECURITY;


--
-- Name: student_renewal_cases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.student_renewal_cases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    student_id uuid,
    student_id_snapshot uuid NOT NULL,
    service_end_date date NOT NULL,
    source_customer_id text,
    source_subscription_id text,
    source_asaas_end_date date NOT NULL,
    source_subscription_synced_at timestamp with time zone,
    monthly_fee_snapshot numeric(12,2) DEFAULT 0 NOT NULL,
    due_day_snapshot smallint,
    class_frequency_snapshot text,
    status text DEFAULT 'PENDING_CONTACT'::text NOT NULL,
    last_contact_at timestamp with time zone,
    last_channel text,
    next_action_at timestamp with time zone,
    interest_term_months smallint,
    version integer DEFAULT 0 NOT NULL,
    created_by uuid NOT NULL,
    updated_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT student_renewal_cases_due_day_check CHECK (((due_day_snapshot IS NULL) OR ((due_day_snapshot >= 1) AND (due_day_snapshot <= 31)))),
    CONSTRAINT student_renewal_cases_interest_term_check CHECK (((interest_term_months IS NULL) OR (interest_term_months = ANY (ARRAY[6, 12])))),
    CONSTRAINT student_renewal_cases_last_channel_check CHECK (((last_channel IS NULL) OR (last_channel = ANY (ARRAY['WHATSAPP'::text, 'PHONE'::text, 'EMAIL'::text, 'OTHER'::text])))),
    CONSTRAINT student_renewal_cases_monthly_fee_check CHECK ((monthly_fee_snapshot >= (0)::numeric)),
    CONSTRAINT student_renewal_cases_status_check CHECK ((status = ANY (ARRAY['PENDING_CONTACT'::text, 'AWAITING_REPLY'::text, 'FOLLOW_UP_SCHEDULED'::text, 'INTEREST_RECORDED'::text, 'FORMALIZATION_PENDING'::text, 'NOT_CONTINUING_RECORDED'::text]))),
    CONSTRAINT student_renewal_cases_version_check CHECK ((version >= 0))
);

ALTER TABLE ONLY public.student_renewal_cases FORCE ROW LEVEL SECURITY;


