--
-- Name: student_xp_totals; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.student_xp_totals AS
 SELECT student_id,
    tenant_id,
    sum(amount) AS total_xp,
    sum(amount) FILTER (WHERE (created_at >= date_trunc('week'::text, now()))) AS weekly_xp,
    sum(amount) FILTER (WHERE (created_at >= date_trunc('day'::text, now()))) AS daily_xp
   FROM public.xp_events
  GROUP BY student_id, tenant_id
  WITH NO DATA;


