    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT teacher_absences_reason_check CHECK ((reason = ANY (ARRAY['SICK'::text, 'VACATION'::text, 'PERSONAL'::text, 'OTHER'::text]))),
    CONSTRAINT teacher_absences_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'RESOLVED'::text, 'CANCELLED'::text])))
);


--
-- Name: teacher_agenda; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.teacher_agenda WITH (security_invoker='true') AS
 SELECT 'booking'::text AS source_type,
    (b.id)::text AS source_id,
    b.tenant_id,
    b.teacher_id,
    b.student_id,
    NULL::text AS student_name,
    NULL::text AS student_phone,
    b.day_of_week,
    b.time_slot,
    NULL::date AS specific_date,
    b.start_date,
    NULL::text AS trial_status,
    'REGULAR'::text AS slot_kind
   FROM public.bookings b
UNION ALL
 SELECT 'reschedule'::text AS source_type,
    (r.id)::text AS source_id,
    r.tenant_id,
    r.teacher_id,
    r.student_id,
    NULL::text AS student_name,
    NULL::text AS student_phone,
    NULL::text AS day_of_week,
    r."time" AS time_slot,
    (r.date)::date AS specific_date,
    NULL::date AS start_date,
    NULL::text AS trial_status,
    'RESCHEDULE'::text AS slot_kind
   FROM public.reschedules r
  WHERE (r."time" ~ '^[0-9]{2}:[0-9]{2}$'::text)
UNION ALL
 SELECT 'appointment'::text AS source_type,
    (a.id)::text AS source_id,
    a.tenant_id,
    a.teacher_id,
    NULL::uuid AS student_id,
    a.student_name,
    a.student_phone,
    NULL::text AS day_of_week,
    to_char(a.start_time, 'HH24:MI'::text) AS time_slot,
    (a.start_time)::date AS specific_date,
    NULL::date AS start_date,
    o.conversion_status AS trial_status,
    'TRIAL'::text AS slot_kind
   FROM (public.appointments a
     LEFT JOIN public.opportunities o ON ((o.trial_appointment_id = a.id)))
  WHERE ((a.start_time IS NOT NULL) AND (COALESCE(o.conversion_status, 'not_contacted'::text) <> 'lost'::text) AND (COALESCE(a.status, 'SCHEDULED'::text) <> 'NO_SHOW'::text));


