--
-- Name: tentative_enrollments; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tentative_enrollments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    prospect_id uuid NOT NULL,
    opportunity_id uuid,
    teacher_id uuid,
    monthly_fee numeric(10,2),
    plan_duration integer,
    classes_per_week integer,
    due_day integer,
    schedule jsonb,
    start_date date,
    enrollment_fee numeric(10,2) DEFAULT 0,
    charge_enrollment boolean DEFAULT false,
    status text DEFAULT 'DRAFT'::text NOT NULL,
    converted_to_enrollment_id uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tentative_enrollments_due_day_check CHECK (((due_day >= 1) AND (due_day <= 28))),
    CONSTRAINT tentative_enrollments_status_check CHECK ((status = ANY (ARRAY['DRAFT'::text, 'SIGNATURE_PENDING'::text, 'SIGNED'::text, 'PAYMENT_PENDING'::text, 'ENROLLED'::text, 'EXPIRED'::text, 'CANCELLED'::text])))
);


