    CONSTRAINT trial_feedback_interest_score_check CHECK (((interest_score >= 1) AND (interest_score <= 5))),
    CONSTRAINT trial_feedback_recommended_level_check CHECK ((recommended_level = ANY (ARRAY['A1'::text, 'A2'::text, 'B1'::text, 'B2'::text, 'C1'::text, 'C2'::text])))
);


