    after_state jsonb,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT trial_feedback_audit_action_check CHECK ((action = ANY (ARRAY['FEEDBACK_CREATED'::text, 'FEEDBACK_UPDATED'::text, 'STATUS_CHANGE'::text, 'LINK_GENERATED'::text, 'MARKED_LOST'::text, 'MARKED_WON'::text])))
);


--
-- Name: trial_reschedule_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.trial_reschedule_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    opportunity_id uuid NOT NULL,
    appointment_id uuid NOT NULL,
    teacher_id uuid NOT NULL,
    lead_id uuid,
    reply_code text DEFAULT upper(substr(encode(extensions.gen_random_bytes(4), 'hex'::text), 1, 8)) NOT NULL,
    from_start_time timestamp with time zone NOT NULL,
    requested_start_time timestamp with time zone NOT NULL,
    status text DEFAULT 'PENDING'::text NOT NULL,
    response_text text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '01:00:00'::interval) NOT NULL,
    responded_at timestamp with time zone,
    CONSTRAINT trial_reschedule_requests_changed_time_check CHECK ((requested_start_time <> from_start_time)),
    CONSTRAINT trial_reschedule_requests_reply_code_check CHECK ((reply_code ~ '^[A-F0-9]{8}$'::text)),
    CONSTRAINT trial_reschedule_requests_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'ACCEPTED'::text, 'DECLINED'::text, 'SUPERSEDED'::text, 'EXPIRED'::text, 'CONFLICT'::text])))
);


