    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT unit_activities_type_check CHECK ((type = ANY (ARRAY['vocab_cards'::text, 'reading'::text, 'grammar_drill'::text, 'quiz'::text, 'speaking_wolfie'::text])))
);


--
-- Name: upcoming_classes; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.upcoming_classes AS
 WITH _days AS (
         SELECT (generate_series((CURRENT_DATE - '1 day'::interval), (CURRENT_DATE + '14 days'::interval), '1 day'::interval))::date AS class_date
        ), _bookings_expanded AS (
         SELECT b.id AS source_id,
            'booking'::text AS source_type,
            b.tenant_id,
            COALESCE(cc.cover_teacher_id, b.teacher_id) AS teacher_id,
            b.student_id,
            NULL::text AS student_name_override,
            NULL::text AS student_phone_override,
            d.class_date,
            b.time_slot AS time_text,
            ((((((d.class_date)::text || ' '::text) || b.time_slot) || ':00'::text))::timestamp without time zone AT TIME ZONE 'America/Sao_Paulo'::text) AS start_at
           FROM ((public.bookings b
             CROSS JOIN _days d)
             LEFT JOIN public.class_coverages cc ON (((cc.booking_id = b.id) AND (cc.class_date = d.class_date) AND (cc.status = 'confirmed'::text))))
          WHERE ((public.dow_name_to_int(b.day_of_week) = (EXTRACT(dow FROM d.class_date))::integer) AND ((b.start_date IS NULL) OR (d.class_date >= b.start_date)) AND (b.time_slot ~ '^[0-9]{2}:[0-9]{2}$'::text) AND (COALESCE(b.status, 'SCHEDULED'::text) = 'SCHEDULED'::text) AND (b.student_id IS NOT NULL))
        ), _reschedules AS (
         SELECT r.id AS source_id,
            'reschedule'::text AS source_type,
            r.tenant_id,
            r.teacher_id,
            r.student_id,
            NULL::text AS student_name_override,
            NULL::text AS student_phone_override,
            (r.date)::date AS class_date,
            r."time" AS time_text,
            (((((r.date || ' '::text) || r."time") || ':00'::text))::timestamp without time zone AT TIME ZONE 'America/Sao_Paulo'::text) AS start_at
           FROM public.reschedules r
          WHERE (r."time" ~ '^[0-9]{2}:[0-9]{2}$'::text)
        ), _appointments AS (
         SELECT a.id AS source_id,
            'appointment'::text AS source_type,
            a.tenant_id,
            a.teacher_id,
            NULL::uuid AS student_id,
            a.student_name AS student_name_override,
            a.student_phone AS student_phone_override,
            (a.start_time)::date AS class_date,
            to_char(a.start_time, 'HH24:MI'::text) AS time_text,
            a.start_time AS start_at
           FROM public.appointments a
          WHERE ((a.start_time IS NOT NULL) AND (COALESCE(a.status, 'scheduled'::text) <> ALL (ARRAY['cancelled'::text, 'no_show'::text])))
        )
 SELECT _bookings_expanded.source_id,
    _bookings_expanded.source_type,
    _bookings_expanded.tenant_id,
    _bookings_expanded.teacher_id,
    _bookings_expanded.student_id,
    _bookings_expanded.student_name_override,
    _bookings_expanded.student_phone_override,
    _bookings_expanded.class_date,
    _bookings_expanded.time_text,
    _bookings_expanded.start_at
   FROM _bookings_expanded
UNION ALL
 SELECT _reschedules.source_id,
    _reschedules.source_type,
    _reschedules.tenant_id,
    _reschedules.teacher_id,
    _reschedules.student_id,
    _reschedules.student_name_override,
    _reschedules.student_phone_override,
    _reschedules.class_date,
    _reschedules.time_text,
    _reschedules.start_at
   FROM _reschedules
UNION ALL
 SELECT _appointments.source_id,
    _appointments.source_type,
    _appointments.tenant_id,
    _appointments.teacher_id,
    _appointments.student_id,
    _appointments.student_name_override,
    _appointments.student_phone_override,
    _appointments.class_date,
    _appointments.time_text,
    _appointments.start_at
   FROM _appointments;


--
-- Name: VIEW upcoming_classes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.upcoming_classes IS 'Timeline unificada de aulas para automacoes (lembretes, etc). Gera bookings recorrentes nos proximos 14 dias.';


--
-- Name: v_affiliate_dashboard; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_affiliate_dashboard WITH (security_invoker='true') AS
 SELECT ac.tenant_id,
    ac.code,
    ac.owner_type,
    p.full_name AS owner_name,
    ac.total_clicks,
    ac.total_conversions,
    COALESCE(sum(acv.reward_amount_brl) FILTER (WHERE (acv.status = 'REWARD_RELEASED'::text)), (0)::numeric) AS total_rewards_brl,
    count(acv.id) FILTER (WHERE (acv.status = 'BLOCKED_FRAUD'::text)) AS blocked_fraud,
    ac.created_at
   FROM ((public.affiliate_codes ac
     LEFT JOIN public.profiles p ON ((p.id = ac.owner_id)))
     LEFT JOIN public.affiliate_conversions acv ON ((acv.affiliate_code_id = ac.id)))
  GROUP BY ac.id, ac.tenant_id, ac.code, ac.owner_type, p.full_name, ac.total_clicks, ac.total_conversions, ac.created_at;


--
-- Name: v_broadcast_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_broadcast_health WITH (security_invoker='true') AS
 SELECT date_trunc('hour'::text, created_at) AS hour,
    status,
    count(*) AS count,
    avg(attempt_count) AS avg_retries
   FROM public.outbox_messages
  WHERE (created_at > (now() - '7 days'::interval))
  GROUP BY (date_trunc('hour'::text, created_at)), status
  ORDER BY (date_trunc('hour'::text, created_at)) DESC;


--
-- Name: v_legacy_link_usage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_legacy_link_usage WITH (security_invoker='true') AS
 SELECT date(created_at) AS usage_date,
    count(*) AS legacy_count,
    count(*) FILTER (WHERE ((details ->> 'source'::text) = 'claim-opportunity'::text)) AS claim_links,
    count(*) FILTER (WHERE ((details ->> 'source'::text) = 'enrollment'::text)) AS enrollment_links
   FROM public.security_events
  WHERE (event_type = 'LEGACY_LINK_USED'::text)
  GROUP BY (date(created_at))
  ORDER BY (date(created_at)) DESC;


--
-- Name: v_legacy_migration; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_legacy_migration WITH (security_invoker='true') AS
 SELECT route,
    raw_param,
    date_trunc('day'::text, created_at) AS day,
    count(*) AS total,
    count(*) FILTER (WHERE decoded_ok) AS success,
    count(*) FILTER (WHERE (NOT decoded_ok)) AS failures
   FROM public.legacy_offer_usage
  WHERE (created_at > (now() - '30 days'::interval))
  GROUP BY route, raw_param, (date_trunc('day'::text, created_at))
  ORDER BY (date_trunc('day'::text, created_at)) DESC;


--
-- Name: v_offer_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_offer_stats WITH (security_invoker='true') AS
 SELECT kind,
    count(*) AS total,
    count(*) FILTER (WHERE (consumed_at IS NOT NULL)) AS consumed,
    count(*) FILTER (WHERE (revoked_at IS NOT NULL)) AS revoked,
    count(*) FILTER (WHERE ((expires_at < now()) AND (consumed_at IS NULL) AND (revoked_at IS NULL))) AS expired,
    count(*) FILTER (WHERE ((consumed_at IS NULL) AND (revoked_at IS NULL) AND (expires_at >= now()))) AS active,
    round(avg(usage_count), 1) AS avg_views
   FROM public.offers
  GROUP BY kind;


--
-- Name: v_payable_class_logs; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_payable_class_logs AS
 SELECT cl.id,
    cl.tenant_id,
    cl.teacher_id,
    cl.student_id,
    cl.date,
    cl.start_time,
    cl.end_time,
    cl.presence,
    cl.content,
    cl.next_content,
    cl.notes,
    cl.rating,
    cl.created_at,
    cl.booking_id,
    cl.reschedule_id,
    cl.observations,
    cl.subtype,
    cl.student_confirmed,
    cl.class_date,
    cl.topic_id,
    cl.content_covered,
    cl.student_difficulties,
    cl.homework_assigned,
    cl.approval_status,
    cl.requires_review,
    cl.review_notes,
    cl.assessment_level,
    cl.psychological_profile,
    cl.teacher_verdict,
    cl.appointment_id,
    cl.verification_status,
    cl.payment_hold,
    cl.rate_override,
    COALESCE(cl.rate_override,
        CASE
            WHEN ((cl.subtype = 'TREINAMENTO'::text) AND COALESCE(tp.is_trainer, false) AND (NOT (EXISTS ( SELECT 1
               FROM public.opportunities o
              WHERE ((o.kind = 'TRAINING'::text) AND (o.winner_teacher_id = cl.teacher_id) AND ((o.trial_appointment_id)::text = cl.appointment_id)))))) THEN 16.00
            ELSE NULL::numeric
        END, public.teacher_student_rate(cl.teacher_id, cl.student_id, cl.class_date)) AS rate_efetivo,
    ((cl.subtype = ANY (ARRAY['REPOSIÇÃO'::text, 'REPOSIÇÃO_PROF'::text])) AND (r.id IS NULL)) AS reposicao_sem_origem,
    ((cl.subtype = 'TREINAMENTO'::text) AND COALESCE(tp.is_trainer, false) AND (NOT (EXISTS ( SELECT 1
           FROM public.opportunities o2
          WHERE ((o2.kind = 'TRAINING'::text) AND (o2.winner_teacher_id = cl.teacher_id) AND ((o2.trial_appointment_id)::text = cl.appointment_id)))))) AS treinamento_ministrado
   FROM ((((public.class_logs cl
     LEFT JOIN public.reschedules r ON (((r.id)::text = cl.reschedule_id)))
     LEFT JOIN public.profiles tp ON ((tp.id = cl.teacher_id)))
     LEFT JOIN public.appointments ap ON (((ap.id)::text = cl.appointment_id)))
     LEFT JOIN public.opportunities op ON ((op.trial_appointment_id = ap.id)))
  WHERE ((cl.presence <> ALL (ARRAY['TEACHER_ABSENCE'::text, 'Falta do Professor'::text])) AND (COALESCE(cl.payment_hold, false) = false) AND public.is_billable_student(cl.student_id) AND (NOT COALESCE(((cl.subtype = 'Teste Oral'::text) AND (cl.student_id IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM public.class_logs c5
          WHERE ((c5.teacher_id = cl.teacher_id) AND (c5.student_id = cl.student_id) AND (c5.class_date = cl.class_date) AND (c5.id <> cl.id) AND (c5.subtype IS DISTINCT FROM 'Teste Oral'::text) AND (c5.presence <> ALL (ARRAY['TEACHER_ABSENCE'::text, 'Falta do Professor'::text])) AND (COALESCE(c5.payment_hold, false) = false))))), false)) AND (NOT COALESCE((cl.subtype = 'REPOSIÇÃO'::text), false)) AND (NOT COALESCE(((cl.subtype = ANY (ARRAY['REPOSIÇÃO'::text, 'REPOSIÇÃO_PROF'::text])) AND (r.fault_type = 'STUDENT'::text)), false)) AND ((cl.subtype IS DISTINCT FROM 'AULA EXPERIMENTAL'::text) OR (cl.appointment_id IS NULL) OR ((COALESCE(ap.status, ''::text) <> 'no_show'::text) AND (COALESCE(op.trial_status, ''::text) <> 'NO_SHOW_STUDENT'::text) AND ((COALESCE(ap.status, ''::text) = 'completed'::text) OR (COALESCE(op.trial_status, ''::text) = 'DONE'::text)))) AND ((cl.subtype IS DISTINCT FROM 'AULA EXPERIMENTAL'::text) OR (cl.appointment_id IS NULL) OR (cl.id = ( SELECT c2.id
           FROM public.class_logs c2
          WHERE ((c2.subtype = 'AULA EXPERIMENTAL'::text) AND (c2.appointment_id = cl.appointment_id))
          ORDER BY c2.created_at, c2.id
         LIMIT 1))) AND ((cl.subtype IS DISTINCT FROM 'TREINAMENTO'::text) OR (cl.appointment_id IS NULL) OR (cl.id = ( SELECT c4.id
           FROM public.class_logs c4
          WHERE ((c4.subtype = 'TREINAMENTO'::text) AND (c4.appointment_id = cl.appointment_id))
          ORDER BY c4.created_at, c4.id
         LIMIT 1))) AND (NOT ((cl.booking_id IS NULL) AND (cl.student_id IS NOT NULL) AND (cl.subtype IS DISTINCT FROM 'AULA EXPERIMENTAL'::text) AND (cl.subtype IS DISTINCT FROM 'TREINAMENTO'::text) AND (EXISTS ( SELECT 1
           FROM public.class_logs c3
          WHERE ((c3.booking_id IS NOT NULL) AND (c3.teacher_id = cl.teacher_id) AND (c3.student_id = cl.student_id) AND (c3.class_date = cl.class_date) AND (c3.presence <> ALL (ARRAY['TEACHER_ABSENCE'::text, 'Falta do Professor'::text])) AND (COALESCE(c3.payment_hold, false) = false)))))));


--
-- Name: VIEW v_payable_class_logs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_payable_class_logs IS 'Aulas pagáveis ao professor. Reposição de falta do ALUNO (subtype REPOSIÇÃO) não paga — a aula de origem já foi remunerada. Reposição de falta do PROFESSOR (REPOSIÇÃO_PROF) paga.';


--
-- Name: v_school_cashflow_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_school_cashflow_summary WITH (security_invoker='true') AS
 SELECT tenant_id,
    date_trunc('month'::text, occurred_at) AS month,
    COALESCE(sum(amount_cents) FILTER (WHERE (type = 'ENTRADA'::text)), (0)::bigint) AS total_entry_cents,
    COALESCE(sum(amount_cents) FILTER (WHERE (type = 'SAIDA'::text)), (0)::bigint) AS total_exit_cents,
    (COALESCE(sum(amount_cents) FILTER (WHERE (type = 'ENTRADA'::text)), (0)::bigint) - COALESCE(sum(amount_cents) FILTER (WHERE (type = 'SAIDA'::text)), (0)::bigint)) AS balance_cents
   FROM public.financial_transactions
  GROUP BY tenant_id, (date_trunc('month'::text, occurred_at));


--
-- Name: v_security_alerts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_security_alerts WITH (security_invoker='true') AS
 SELECT event_type,
    severity,
    source,
    count(*) AS count,
    max(created_at) AS last_seen
   FROM public.security_events
  WHERE (created_at > (now() - '24:00:00'::interval))
  GROUP BY event_type, severity, source
  ORDER BY
        CASE severity
            WHEN 'CRITICAL'::text THEN 0
            WHEN 'WARN'::text THEN 1
            WHEN 'INFO'::text THEN 2
            ELSE 3
        END, (count(*)) DESC;


--
-- Name: v_student_receivables; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_student_receivables WITH (security_invoker='true') AS
 SELECT sp.tenant_id,
    sp.student_id,
    p.full_name AS student_name,
    count(*) AS total_overdue,
    sum(sp.amount_cents) AS total_overdue_cents
   FROM (public.student_payments sp
     JOIN public.profiles p ON ((sp.student_id = p.id)))
  WHERE (sp.status = 'OVERDUE'::text)
  GROUP BY sp.tenant_id, sp.student_id, p.full_name;


--
-- Name: v_teacher_cost_competencia; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_teacher_cost_competencia AS
 SELECT t.tenant_id,
    to_char((v.class_date)::timestamp with time zone, 'YYYY-MM'::text) AS month_year,
    v.teacher_id,
    (count(*))::integer AS aulas,
    sum(v.rate_efetivo) AS custo_aulas
   FROM (public.v_payable_class_logs v
     JOIN public.profiles t ON ((t.id = v.teacher_id)))
  WHERE (v.class_date IS NOT NULL)
  GROUP BY t.tenant_id, (to_char((v.class_date)::timestamp with time zone, 'YYYY-MM'::text)), v.teacher_id;


--
-- Name: VIEW v_teacher_cost_competencia; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_teacher_cost_competencia IS 'Custo com professor pelo mês da AULA (competência), derivado de v_payable_class_logs. Não inclui closing_adjustments — dre_gerencial soma os ajustes por cima.';


--
-- Name: v_teacher_payables; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_teacher_payables WITH (security_invoker='true') AS
 SELECT tc.id AS closing_id,
    tc.tenant_id,
    tc.teacher_id,
    p.full_name AS teacher_name,
    p.avatar_url,
    tc.period_start,
    tc.period_end,
    tc.total_lessons_count,
    tc.total_amount_cents,
    tc.status,
    tc.updated_at
   FROM (public.teacher_closings tc
     JOIN public.profiles p ON ((tc.teacher_id = p.id)));


--
-- Name: v_trial_funnel; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_trial_funnel WITH (security_invoker='true') AS
 SELECT tenant_id,
    date_trunc('week'::text, created_at) AS week,
    count(*) AS total_opportunities,
    count(*) FILTER (WHERE (trial_status = 'DONE'::text)) AS trials_done,
    count(*) FILTER (WHERE (trial_status = 'NO_SHOW_STUDENT'::text)) AS no_shows,
    count(*) FILTER (WHERE (conversion_status = 'WON'::text)) AS won,
    count(*) FILTER (WHERE (conversion_status = 'LOST'::text)) AS lost,
    count(*) FILTER (WHERE (conversion_status = 'OPEN'::text)) AS open,
    round(((100.0 * (count(*) FILTER (WHERE (conversion_status = 'WON'::text)))::numeric) / (NULLIF(count(*) FILTER (WHERE (trial_status = 'DONE'::text)), 0))::numeric), 1) AS conversion_rate_pct
   FROM public.opportunities
  WHERE (created_at > (now() - '90 days'::interval))
  GROUP BY tenant_id, (date_trunc('week'::text, created_at))
  ORDER BY (date_trunc('week'::text, created_at)) DESC;


