);


--
-- Name: vw_student_contracts; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_student_contracts WITH (security_invoker='false', security_barrier='true') AS
 SELECT id AS user_id,
    full_name AS student_name,
    cpf AS student_cpf,
    email AS student_email,
    phone AS student_phone,
    postal_code AS student_postal_code,
    address AS student_address,
    address_number AS student_address_number,
    COALESCE(NULLIF(monthly_fee, (0)::numeric), ( SELECT sp.value
           FROM public.student_payments sp
          WHERE ((sp.student_id = p.id) AND (sp.status <> 'CANCELLED'::text))
          ORDER BY sp.due_date DESC
         LIMIT 1), (0)::numeric) AS plan_value,
    due_day,
    class_frequency,
    contract_accepted,
    accepted_at,
    signature_ip,
    typed_signature,
    signature_hash,
    student_signature_url,
    signed_document_url,
    wise_wolf_signature_token,
    documentation_status,
    audit_status,
    rejection_reason,
    tenant_id
   FROM public.profiles p
  WHERE ((role = 'STUDENT'::text) AND ((( SELECT public._my_role() AS _my_role) = 'SUPER_ADMIN'::text) OR ((tenant_id = ( SELECT public._my_tenant_id() AS _my_tenant_id)) AND (( SELECT public._my_role() AS _my_role) = ANY (ARRAY['SCHOOL_ADMIN'::text, 'ADMIN'::text])))));


