CREATE TABLE public.whatsapp_conversations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    instance_id uuid NOT NULL,
    instance_name text NOT NULL,
    remote_jid text NOT NULL,
    contact_kind text DEFAULT 'unknown'::text NOT NULL,
    display_name text,
    phone text,
    unread_count integer DEFAULT 0 NOT NULL,
    assigned_to uuid,
    handoff_active boolean DEFAULT false NOT NULL,
    human_handoff_until timestamp with time zone,
    archived boolean DEFAULT false NOT NULL,
    last_message_at timestamp with time zone,
    last_message_preview text,
    last_message_direction text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT whatsapp_conversations_contact_kind_check CHECK ((contact_kind = ANY (ARRAY['student'::text, 'lead'::text, 'candidate'::text, 'teacher'::text, 'group'::text, 'unknown'::text]))),
    CONSTRAINT whatsapp_conversations_display_name_check CHECK (((display_name IS NULL) OR (((char_length(display_name) >= 1) AND (char_length(display_name) <= 160)) AND (display_name !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT whatsapp_conversations_handoff_check CHECK (((handoff_active IS FALSE) OR (human_handoff_until IS NOT NULL))),
    CONSTRAINT whatsapp_conversations_instance_name_check CHECK ((((char_length(instance_name) >= 3) AND (char_length(instance_name) <= 120)) AND (instance_name = btrim(instance_name)) AND (instance_name !~ '[[:cntrl:]]'::text))),
    CONSTRAINT whatsapp_conversations_last_message_direction_check CHECK (((last_message_direction IS NULL) OR (last_message_direction = ANY (ARRAY['in'::text, 'out'::text])))),
    CONSTRAINT whatsapp_conversations_phone_check CHECK (((phone IS NULL) OR (phone ~ '^[0-9]{10,15}$'::text))),
    CONSTRAINT whatsapp_conversations_preview_check CHECK (((last_message_preview IS NULL) OR (char_length(last_message_preview) <= 500))),
    CONSTRAINT whatsapp_conversations_remote_jid_check CHECK ((((char_length(remote_jid) >= 3) AND (char_length(remote_jid) <= 255)) AND (remote_jid = btrim(remote_jid)) AND (remote_jid !~ '[[:cntrl:]]'::text) AND (POSITION(('@'::text) IN (remote_jid)) > 1))),
    CONSTRAINT whatsapp_conversations_unread_count_check CHECK ((unread_count >= 0))
);


