-- Name: whatsapp_messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.whatsapp_messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    instance_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    provider_message_id text,
    client_request_id uuid,
    direction text NOT NULL,
    sender_kind text NOT NULL,
    message_type text NOT NULL,
    body text DEFAULT ''::text NOT NULL,
    status text NOT NULL,
    occurred_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_by_user_id uuid,
    reply_to_provider_message_id text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone DEFAULT now() NOT NULL,
    lease_until timestamp with time zone,
    dispatch_started_at timestamp with time zone,
    error_code text,
    sent_at timestamp with time zone,
    delivered_at timestamp with time zone,
    read_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT whatsapp_messages_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 20))),
    CONSTRAINT whatsapp_messages_body_check CHECK ((char_length(body) <= 16384)),
    CONSTRAINT whatsapp_messages_direction_check CHECK ((direction = ANY (ARRAY['in'::text, 'out'::text]))),
    CONSTRAINT whatsapp_messages_error_code_check CHECK (((error_code IS NULL) OR ((char_length(error_code) >= 1) AND (char_length(error_code) <= 160)))),
    CONSTRAINT whatsapp_messages_lease_check CHECK (((status = 'dispatching'::text) = (lease_until IS NOT NULL))),
    CONSTRAINT whatsapp_messages_message_type_check CHECK ((message_type = ANY (ARRAY['text'::text, 'audio'::text, 'image'::text, 'video'::text, 'document'::text, 'sticker'::text, 'location'::text, 'contact'::text, 'reaction'::text, 'poll'::text, 'system'::text, 'unknown'::text]))),
    CONSTRAINT whatsapp_messages_metadata_check CHECK (((jsonb_typeof(metadata) = 'object'::text) AND (pg_column_size(metadata) <= 32768))),
    CONSTRAINT whatsapp_messages_provider_id_check CHECK (((provider_message_id IS NULL) OR (((char_length(provider_message_id) >= 1) AND (char_length(provider_message_id) <= 320)) AND (provider_message_id = btrim(provider_message_id)) AND (provider_message_id !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT whatsapp_messages_reply_id_check CHECK (((reply_to_provider_message_id IS NULL) OR ((char_length(reply_to_provider_message_id) >= 1) AND (char_length(reply_to_provider_message_id) <= 320)))),
    CONSTRAINT whatsapp_messages_sender_kind_check CHECK ((sender_kind = ANY (ARRAY['contact'::text, 'human'::text, 'ai'::text, 'automation'::text, 'system'::text]))),
    CONSTRAINT whatsapp_messages_status_check CHECK ((status = ANY (ARRAY['received'::text, 'queued'::text, 'dispatching'::text, 'sent'::text, 'delivered'::text, 'read'::text, 'failed'::text, 'uncertain'::text])))
);


