    CONSTRAINT whatsapp_webhook_inbox_event_key_check CHECK ((((char_length(event_key) >= 1) AND (char_length(event_key) <= 500)) AND (event_key = btrim(event_key)) AND (event_key !~ '[[:cntrl:]]'::text))),
    CONSTRAINT whatsapp_webhook_inbox_event_type_check CHECK ((((char_length(event_type) >= 1) AND (char_length(event_type) <= 120)) AND (event_type = btrim(event_type)) AND (event_type !~ '[[:cntrl:]]'::text))),
    CONSTRAINT whatsapp_webhook_inbox_instance_name_check CHECK ((((char_length(instance_name) >= 3) AND (char_length(instance_name) <= 120)) AND (instance_name = btrim(instance_name)) AND (instance_name !~ '[[:cntrl:]]'::text))),
    CONSTRAINT whatsapp_webhook_inbox_payload_check CHECK (((jsonb_typeof(payload) = 'object'::text) AND (pg_column_size(payload) <= 1048576))),
    CONSTRAINT whatsapp_webhook_inbox_processed_check CHECK (((status <> 'processed'::text) OR (processed_at IS NOT NULL))),
    CONSTRAINT whatsapp_webhook_inbox_status_check CHECK ((status = ANY (ARRAY['received'::text, 'processed'::text, 'failed'::text])))
);


