    estimated_level text,
    primary_goal text,
    secondary_goals text[] DEFAULT '{}'::text[] NOT NULL,
    profession text,
    industry text,
    job_role text,
    interests text[] DEFAULT '{}'::text[] NOT NULL,
    travel_destination text,
    exchange_context text,
    target_exam text,
    target_date date,
    preferred_correction_mode text,
    preferred_language_mode text,
    confidence_level text,
    preferred_session_minutes integer,
    pressure_level integer,
    recurring_grammar_errors text[] DEFAULT '{}'::text[] NOT NULL,
    recurring_pronunciation_issues text[] DEFAULT '{}'::text[] NOT NULL,
    recurring_vocabulary_gaps text[] DEFAULT '{}'::text[] NOT NULL,
    structures_mastered text[] DEFAULT '{}'::text[] NOT NULL,
    structures_in_progress text[] DEFAULT '{}'::text[] NOT NULL,
    recent_topics text[] DEFAULT '{}'::text[] NOT NULL,
    professional_scenarios text[] DEFAULT '{}'::text[] NOT NULL,
    completed_simulations text[] DEFAULT '{}'::text[] NOT NULL,
    scores_history jsonb DEFAULT '[]'::jsonb NOT NULL,
    recommended_next_step text,
    previous_session_summary jsonb DEFAULT '{}'::jsonb NOT NULL,
    profile_version integer DEFAULT 1 NOT NULL,
    profiled_at timestamp with time zone,
    CONSTRAINT wolf_intelligence_confidence_check CHECK (((confidence_level IS NULL) OR (confidence_level = ANY (ARRAY['very_low'::text, 'low'::text, 'medium'::text, 'high'::text, 'very_high'::text])))),
    CONSTRAINT wolf_intelligence_correction_mode_check CHECK (((preferred_correction_mode IS NULL) OR (preferred_correction_mode = ANY (ARRAY['immediate'::text, 'end'::text, 'selective'::text, 'examiner'::text])))),
    CONSTRAINT wolf_intelligence_estimated_level_check CHECK (((estimated_level IS NULL) OR (estimated_level = ANY (ARRAY['A1'::text, 'A2'::text, 'B1'::text, 'B2'::text, 'C1'::text, 'C2'::text])))),
    CONSTRAINT wolf_intelligence_json_shapes_check CHECK (((jsonb_typeof(scores_history) = 'array'::text) AND (jsonb_array_length(scores_history) <= 100) AND (jsonb_typeof(previous_session_summary) = 'object'::text))),
    CONSTRAINT wolf_intelligence_language_mode_check CHECK (((preferred_language_mode IS NULL) OR (preferred_language_mode = ANY (ARRAY['pt_support'::text, 'bilingual'::text, 'immersive'::text, 'english_rescue'::text])))),
    CONSTRAINT wolf_intelligence_practice_preferences_check CHECK ((((preferred_session_minutes IS NULL) OR ((preferred_session_minutes >= 1) AND (preferred_session_minutes <= 240))) AND ((pressure_level IS NULL) OR ((pressure_level >= 1) AND (pressure_level <= 5))))),
    CONSTRAINT wolf_intelligence_profile_version_check CHECK (((profile_version >= 1) AND (profile_version <= 1000000))),
    CONSTRAINT wolf_intelligence_total_classes_check CHECK ((total_classes_analyzed >= 0))
);


