    retry_completed boolean DEFAULT false NOT NULL,
    retry_completed_by_attempt_id uuid,
    CONSTRAINT wolfie_activity_attempts_attempt_number_check CHECK ((attempt_number > 0)),
    CONSTRAINT wolfie_activity_attempts_kind_check CHECK (((attempt_kind = ANY (ARRAY['initial'::text, 'retry'::text, 'transfer'::text, 'final'::text])) AND (((attempt_kind = 'retry'::text) AND (parent_attempt_id IS NOT NULL)) OR ((attempt_kind <> 'retry'::text) AND (parent_attempt_id IS NULL))) AND ((NOT retry_completed) OR (retry_completed_by_attempt_id IS NOT NULL)))),
    CONSTRAINT wolfie_activity_attempts_modality_check CHECK ((modality = ANY (ARRAY['text'::text, 'voice'::text, 'mixed'::text]))),
    CONSTRAINT wolfie_activity_attempts_score_check CHECK (((score >= 0) AND (score <= 100)))
);


