    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    student_id uuid NOT NULL,
    subject text NOT NULL,
    cefr_level text NOT NULL,
    sector text,
    phase text DEFAULT 'standard'::text NOT NULL,
    modality text DEFAULT 'text'::text NOT NULL,
    status text DEFAULT 'IN_PROGRESS'::text NOT NULL,
    source_session_id uuid,
    request_key uuid DEFAULT gen_random_uuid() NOT NULL,
    activity_content jsonb DEFAULT '{}'::jsonb NOT NULL,
    learner_state jsonb DEFAULT '{}'::jsonb NOT NULL,
    reused_terms text[] DEFAULT '{}'::text[] NOT NULL,
    introduced_terms text[] DEFAULT '{}'::text[] NOT NULL,
    score smallint,
    xp_earned integer DEFAULT 0 NOT NULL,
    duration_seconds integer DEFAULT 0 NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    test_fixture boolean DEFAULT false NOT NULL,
    started_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    current_stage text DEFAULT 'briefing'::text NOT NULL,
    required_retry_count integer DEFAULT 0 NOT NULL,
    completed_retry_count integer DEFAULT 0 NOT NULL,
    report_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_activity_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT wolfie_activity_sessions_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT wolfie_activity_sessions_cefr_level_check CHECK ((cefr_level = ANY (ARRAY['A1'::text, 'A2'::text, 'B1'::text, 'B2'::text, 'C1'::text, 'C2'::text]))),
    CONSTRAINT wolfie_activity_sessions_completed_at_check CHECK (((completed_at IS NULL) OR (completed_at >= started_at))),
    CONSTRAINT wolfie_activity_sessions_duration_seconds_check CHECK ((duration_seconds >= 0)),
    CONSTRAINT wolfie_activity_sessions_modality_check CHECK ((modality = ANY (ARRAY['text'::text, 'voice'::text, 'mixed'::text]))),
    CONSTRAINT wolfie_activity_sessions_phase_check CHECK ((phase = ANY (ARRAY['standard'::text, 'construction'::text, 'memorization'::text, 'readaptation'::text, 'conversation'::text]))),
    CONSTRAINT wolfie_activity_sessions_retry_counts_check CHECK (((required_retry_count >= 0) AND ((completed_retry_count >= 0) AND (completed_retry_count <= required_retry_count)) AND (jsonb_typeof(report_json) = 'object'::text))),
    CONSTRAINT wolfie_activity_sessions_score_check CHECK (((score >= 0) AND (score <= 100))),
    CONSTRAINT wolfie_activity_sessions_source_phase_check CHECK ((((phase = 'readaptation'::text) AND (source_session_id IS NOT NULL)) OR ((phase <> 'readaptation'::text) AND (source_session_id IS NULL)))),
    CONSTRAINT wolfie_activity_sessions_status_check CHECK ((status = ANY (ARRAY['IN_PROGRESS'::text, 'EVALUATING'::text, 'AWAITING_RETRY'::text, 'COMPLETED'::text, 'ABANDONED'::text, 'FAILED'::text]))),
    CONSTRAINT wolfie_activity_sessions_subject_check CHECK ((subject = ANY (ARRAY['vocabulary'::text, 'grammar'::text, 'listening'::text, 'reading'::text, 'writing'::text, 'conversation'::text, 'global_meetings'::text]))),
    CONSTRAINT wolfie_activity_sessions_xp_earned_check CHECK ((xp_earned >= 0))
);


