--
-- Name: wolfie_facts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wolfie_facts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    student_id uuid NOT NULL,
    fact_type text NOT NULL,
    subject_key text DEFAULT 'student'::text NOT NULL,
    value text NOT NULL,
    normalized_value text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    verification_status text DEFAULT 'observed'::text NOT NULL,
    confidence numeric(4,3) DEFAULT 0.700 NOT NULL,
    occurrence_count integer DEFAULT 1 NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    source_kind text DEFAULT 'learner_statement'::text NOT NULL,
    source_session_id uuid,
    source_turn_id uuid,
    source_transcript text,
    transcription_confidence numeric(4,3),
    evidence jsonb DEFAULT '{}'::jsonb NOT NULL,
    supersedes_fact_id uuid,
    superseded_by_fact_id uuid,
    valid_from timestamp with time zone DEFAULT now() NOT NULL,
    valid_to timestamp with time zone,
    confirmed_at timestamp with time zone,
    disputed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT wolfie_facts_confidence_check CHECK (((confidence >= (0)::numeric) AND (confidence <= (1)::numeric))),
    CONSTRAINT wolfie_facts_confirmation_check CHECK ((((verification_status = 'confirmed'::text) AND (confirmed_at IS NOT NULL)) OR (verification_status <> 'confirmed'::text))),
    CONSTRAINT wolfie_facts_evidence_check CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT wolfie_facts_fact_type_check CHECK ((fact_type = ANY (ARRAY['resides_in'::text, 'is_from'::text, 'born_in'::text, 'preferred_name'::text, 'pronouns'::text, 'timezone'::text, 'language_preference'::text, 'learning_preference'::text, 'personal_preference'::text]))),
    CONSTRAINT wolfie_facts_normalized_value_check CHECK (((char_length(normalized_value) >= 1) AND (char_length(normalized_value) <= 1000))),
    CONSTRAINT wolfie_facts_occurrence_count_check CHECK (((occurrence_count >= 1) AND (occurrence_count <= 1000000))),
    CONSTRAINT wolfie_facts_source_kind_check CHECK ((source_kind = ANY (ARRAY['learner_statement'::text, 'learner_confirmation'::text, 'manual'::text, 'import'::text]))),
    CONSTRAINT wolfie_facts_source_pair_check CHECK (((source_turn_id IS NULL) OR (source_session_id IS NOT NULL))),
    CONSTRAINT wolfie_facts_source_transcript_check CHECK (((source_transcript IS NULL) OR (char_length(source_transcript) <= 4000))),
    CONSTRAINT wolfie_facts_status_check CHECK ((status = ANY (ARRAY['active'::text, 'superseded'::text, 'disputed'::text, 'dismissed'::text]))),
    CONSTRAINT wolfie_facts_status_dates_check CHECK ((((status = 'active'::text) AND (valid_to IS NULL) AND (disputed_at IS NULL)) OR ((status = 'superseded'::text) AND (valid_to IS NOT NULL)) OR ((status = 'disputed'::text) AND (disputed_at IS NOT NULL)) OR (status = 'dismissed'::text))),
    CONSTRAINT wolfie_facts_subject_key_check CHECK (((char_length(subject_key) >= 1) AND (char_length(subject_key) <= 160))),
    CONSTRAINT wolfie_facts_transcription_confidence_check CHECK (((transcription_confidence IS NULL) OR ((transcription_confidence >= (0)::numeric) AND (transcription_confidence <= (1)::numeric)))),
    CONSTRAINT wolfie_facts_validity_check CHECK (((valid_to IS NULL) OR (valid_to >= valid_from))),
    CONSTRAINT wolfie_facts_value_check CHECK (((char_length(value) >= 1) AND (char_length(value) <= 1000))),
    CONSTRAINT wolfie_facts_verification_status_check CHECK ((verification_status = ANY (ARRAY['observed'::text, 'confirmed'::text, 'rejected'::text]))),
    CONSTRAINT wolfie_facts_version_check CHECK (((version >= 1) AND (version <= 1000000)))
);


