    CONSTRAINT wolfie_live_grants_status_check CHECK ((status = ANY (ARRAY['RESERVED'::text, 'ACTIVE'::text, 'CLOSING'::text, 'SETTLED'::text, 'RELEASED'::text, 'EXPIRED'::text])))
);


