    CONSTRAINT wolfie_topup_orders_provider_payment_check CHECK (((provider_payment_id IS NULL) OR ((char_length(provider_payment_id) >= 1) AND (char_length(provider_payment_id) <= 200)))),
    CONSTRAINT wolfie_topup_orders_refunded_amount_check CHECK (((refunded_amount_brl IS NULL) OR (refunded_amount_brl >= (0)::numeric))),
    CONSTRAINT wolfie_topup_orders_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'CREATING'::text, 'AWAITING_PAYMENT'::text, 'PAID'::text, 'SUSPENDED'::text, 'REVERSED'::text, 'FAILED'::text, 'RECONCILIATION_REQUIRED'::text])))
);


--
-- Name: COLUMN wolfie_topup_orders.provider_customer_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wolfie_topup_orders.provider_customer_id IS 'Immutable canonical Asaas customer snapshot required before linking a top-up payment.';


--
-- Name: wolfie_topup_packages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wolfie_topup_packages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id text NOT NULL,
    name text NOT NULL,
    minutes integer NOT NULL,
    price_brl numeric(10,2) NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT wolfie_topup_minutes_check CHECK ((minutes > 0)),
    CONSTRAINT wolfie_topup_price_check CHECK ((price_brl >= (0)::numeric))
);


--
-- Name: wolfie_topup_webhook_inbox; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wolfie_topup_webhook_inbox (
    provider_event_id text NOT NULL,
    event_type text NOT NULL,
    provider_payment_id text NOT NULL,
    external_reference text NOT NULL,
    payment_amount_brl numeric(10,2),
    refunded_amount_brl numeric(10,2),
    billing_type text,
    processing_status text NOT NULL,
    last_error text,
    delivery_count integer DEFAULT 1 NOT NULL,
    first_received_at timestamp with time zone DEFAULT now() NOT NULL,
    last_received_at timestamp with time zone DEFAULT now() NOT NULL,
    processed_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT wolfie_topup_webhook_amount_check CHECK (((payment_amount_brl IS NULL) OR (payment_amount_brl >= (0)::numeric))),
    CONSTRAINT wolfie_topup_webhook_inbox_delivery_count_check CHECK ((delivery_count > 0)),
    CONSTRAINT wolfie_topup_webhook_inbox_event_type_check CHECK (((char_length(event_type) >= 1) AND (char_length(event_type) <= 120))),
    CONSTRAINT wolfie_topup_webhook_inbox_external_reference_check CHECK (((char_length(external_reference) >= 1) AND (char_length(external_reference) <= 300))),
    CONSTRAINT wolfie_topup_webhook_inbox_processing_status_check CHECK ((processing_status = ANY (ARRAY['RECEIVED'::text, 'APPLIED'::text, 'IGNORED'::text, 'LEGACY_REVIEW'::text, 'FAILED'::text]))),
    CONSTRAINT wolfie_topup_webhook_inbox_provider_event_id_check CHECK (((char_length(provider_event_id) >= 1) AND (char_length(provider_event_id) <= 240))),
    CONSTRAINT wolfie_topup_webhook_inbox_provider_payment_id_check CHECK (((char_length(provider_payment_id) >= 1) AND (char_length(provider_payment_id) <= 200))),
    CONSTRAINT wolfie_topup_webhook_refund_check CHECK (((refunded_amount_brl IS NULL) OR (refunded_amount_brl >= (0)::numeric)))
);


--
-- Name: wolfie_turns; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wolfie_turns (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp with time zone DEFAULT timezone('utc'::text, now()) NOT NULL,
    session_id uuid NOT NULL,
    speaker text NOT NULL,
    content text NOT NULL,
    audio_url text,
    turn_index integer NOT NULL,
    tokens_used integer,
    message_type text DEFAULT 'question'::text NOT NULL,
    stage text,
    structured_payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    requires_retry boolean DEFAULT false NOT NULL,
    language_code text,
    speech_metrics jsonb DEFAULT '{}'::jsonb NOT NULL,
    transcription_confidence numeric(4,3),
    source_kind text DEFAULT 'classic'::text NOT NULL,
    client_turn_id uuid,
    usage_input_text_tokens integer,
    usage_input_audio_tokens integer,
    usage_output_text_tokens integer,
    usage_output_audio_tokens integer,
    usage_cached_tokens integer,
    CONSTRAINT wolfie_turns_language_code_check CHECK (((language_code IS NULL) OR (language_code = ANY (ARRAY['pt-BR'::text, 'en-US'::text, 'mixed'::text])))),
    CONSTRAINT wolfie_turns_message_type_check CHECK ((message_type = ANY (ARRAY['question'::text, 'correction'::text, 'explanation'::text, 'simulation'::text, 'feedback'::text, 'instruction'::text]))),
    CONSTRAINT wolfie_turns_payload_shape_check CHECK (((jsonb_typeof(structured_payload) = 'object'::text) AND (jsonb_typeof(speech_metrics) = 'object'::text) AND ((transcription_confidence IS NULL) OR ((transcription_confidence >= (0)::numeric) AND (transcription_confidence <= (1)::numeric))))),
    CONSTRAINT wolfie_turns_source_identity_check CHECK (((source_kind = 'classic'::text) OR ((source_kind = 'openai_realtime'::text) AND (client_turn_id IS NOT NULL)))),
    CONSTRAINT wolfie_turns_source_kind_check CHECK ((source_kind = ANY (ARRAY['classic'::text, 'openai_realtime'::text]))),
    CONSTRAINT wolfie_turns_speaker_check CHECK ((speaker = ANY (ARRAY['student'::text, 'wolfie'::text])))
);


--
-- Name: COLUMN wolfie_turns.structured_payload; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wolfie_turns.structured_payload IS 'Normalized learner-visible feedback, next action and stage metadata for this turn.';


--
-- Name: COLUMN wolfie_turns.source_kind; Type: COMMENT; Schema: public; Owner: -
