--
-- Name: pedagogical_modules Admins can manage modules; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can manage modules" ON public.pedagogical_modules USING ((EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND (profiles.role = ANY (ARRAY['SCHOOL_ADMIN'::text, 'SUPER_ADMIN'::text])) AND (profiles.tenant_id = pedagogical_modules.tenant_id)))));


--
-- Name: notification_queue Admins can manage queue; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can manage queue" ON public.notification_queue USING (((tenant_id = ( SELECT profiles.tenant_id
   FROM public.profiles
  WHERE (profiles.id = ( SELECT auth.uid() AS uid)))) AND (EXISTS ( SELECT 1
   FROM public.profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND (profiles.role = ANY (ARRAY['SUPER_ADMIN'::text, 'SCHOOL_ADMIN'::text])))))));


--
-- Name: profiles Admins can update all profiles in tenant; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Admins can update all profiles in tenant" ON public.profiles FOR UPDATE USING (((public._my_role() = 'SCHOOL_ADMIN'::text) AND (tenant_id = public._my_tenant_id()))) WITH CHECK (((public._my_role() = 'SCHOOL_ADMIN'::text) AND (tenant_id = public._my_tenant_id())));


